-- =========================================================================
-- SOCIAL MEDIA REPORTS
--
-- A client's monthly social media report: the accounts, every post with its
-- figures, and the team's findings, kept as rows and drawn as a PDF in the
-- browser by js/smreport.js. Asked for by the user on 2026-09-25: the client
-- reads the final report in their own portal, and only once the team has
-- finished it, confirmed it and published it.
--
--   draft  -> review     Submit for review          clients.reports Work
--   review -> draft      Return (a note)            the submitter, or Manage
--   review -> confirmed  Confirm                    Manage, never the submitter
--   confirmed -> draft   Return (a note)            Manage
--   confirmed -> published  Publish                 Manage
--   published -> draft   Revise (the next version)  Work
--   published -> confirmed  Unpublish (a reason)    Manage
--
-- Nothing a client reads is ever a row somebody is still editing. Publishing
-- freezes the report into `sm_report_versions.snapshot`, and the client
-- portal reads only that, the newest version not withdrawn. A revision is a
-- new draft with the next version number; the client goes on reading the
-- version they have until the revision is published.
--
-- The rows are edited directly by the console under row level security
-- (`clients.reports` Work), but only while the report is a draft: a trigger
-- refuses any change to the report's content, its accounts or its posts once
-- it has been submitted, and refuses any change to its status, version or
-- stamps except from the functions below. A browser cannot publish a report
-- by writing a column.
--
-- Thumbnails are kept in the row as small JPEG data URLs (the editor scales
-- them to 320px), not on the CDN: the PDF is drawn in the browser, and the
-- CDN does not answer a cross-origin read, so a CDN thumbnail could not be
-- drawn into the file.
--
-- Rollback:
--   drop function if exists public.portal_report(uuid);
--   drop function if exists public.portal_reports(uuid);
--   drop function if exists public.sm_report_delete(uuid, text);
--   drop function if exists public.sm_report_unpublish(uuid, text);
--   drop function if exists public.sm_report_revise(uuid);
--   drop function if exists public.sm_report_publish(uuid);
--   drop function if exists public.sm_report_confirm(uuid);
--   drop function if exists public.sm_report_return(uuid, text);
--   drop function if exists public.sm_report_submit(uuid);
--   drop function if exists public.sm_report_create(uuid, date, date, text);
--   drop function if exists public.sm_report_snapshot(uuid, boolean);
--   drop function if exists public.sm_report_log(uuid, text, text);
--   drop table if exists public.sm_report_versions, public.sm_report_posts,
--     public.sm_report_platforms, public.sm_reports;
--   drop function if exists public.sm_report_guard(), public.sm_report_child_guard();
--   and re-run the activity_section of 2026-09-24-creator-profile.sql.
-- =========================================================================

create table if not exists public.sm_reports (
  id            uuid primary key default gen_random_uuid(),
  client_id     uuid not null references public.clients(id) on delete cascade,
  -- Which report this is. One engine of steps for every kind; the kind
  -- decides what is entered and how the PDF is drawn. Social media is built,
  -- advertising is next.
  kind          text not null default 'social',
  title         text not null default 'Social Media Report',
  period_start  date not null,
  period_end    date not null,
  headline      text,
  intro         text,
  insights      jsonb not null default '{}'::jsonb,
  rank_metric   text not null default 'views',
  status        text not null default 'draft',
  version_no    integer not null default 1,
  return_note   text,
  submitted_by  uuid references public.team_members(id) on delete set null,
  submitted_at  timestamptz,
  confirmed_by  uuid references public.team_members(id) on delete set null,
  confirmed_at  timestamptz,
  created_by    uuid references public.team_members(id) on delete set null,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  constraint sm_reports_status check (status in ('draft', 'review', 'confirmed', 'published')),
  constraint sm_reports_kind check (kind in ('social', 'ads')),
  constraint sm_reports_rank check (rank_metric in ('views', 'reach', 'impressions', 'engagements', 'interactions')),
  constraint sm_reports_period check (period_end >= period_start),
  constraint sm_reports_title check (length(btrim(title)) between 1 and 120)
);
create unique index if not exists sm_reports_client_period_idx
  on public.sm_reports (client_id, kind, period_start, period_end);

create table if not exists public.sm_report_platforms (
  id              uuid primary key default gen_random_uuid(),
  report_id       uuid not null references public.sm_reports(id) on delete cascade,
  platform        text not null,
  account_name    text,
  handle          text,
  group_key       text,
  group_label     text,
  position        integer not null default 0,
  metrics         text[] not null default array['views', 'engagements'],
  followers_start bigint,
  followers_end   bigint,
  growth_override bigint,
  growth_reason   text,
  er_basis        text,
  metric_notes    text,
  summary         text,
  worked          text,
  improve         text,
  actions         text,
  created_at      timestamptz not null default now(),
  constraint sm_platforms_platform check (platform in ('facebook', 'instagram', 'tiktok', 'rednote', 'youtube', 'linkedin', 'x', 'threads', 'other')),
  constraint sm_platforms_basis check (er_basis is null or er_basis in ('views', 'reach', 'impressions', 'followers'))
);
create index if not exists sm_report_platforms_report_idx on public.sm_report_platforms (report_id);

create table if not exists public.sm_report_posts (
  id            uuid primary key default gen_random_uuid(),
  report_id     uuid not null references public.sm_reports(id) on delete cascade,
  platform_id   uuid not null references public.sm_report_platforms(id) on delete cascade,
  posted_on     date,
  title         text,
  caption       text,
  content_type  text,
  url           text,
  thumb_data    text,
  views         bigint,
  reach         bigint,
  impressions   bigint,
  interactions  bigint,
  engagements   bigint,
  likes         bigint,
  comments      bigint,
  shares        bigint,
  saves         bigint,
  notable       text,
  observation   text,
  position      integer not null default 0,
  created_at    timestamptz not null default now(),
  constraint sm_posts_thumb check (thumb_data is null or (thumb_data like 'data:image/%' and length(thumb_data) <= 300000))
);
create index if not exists sm_report_posts_report_idx on public.sm_report_posts (report_id);

create table if not exists public.sm_report_versions (
  id               uuid primary key default gen_random_uuid(),
  report_id        uuid not null references public.sm_reports(id) on delete cascade,
  version_no       integer not null,
  snapshot         jsonb not null,
  published_by     text,
  published_at     timestamptz not null default now(),
  withdrawn_at     timestamptz,
  withdrawn_by     text,
  withdraw_reason  text,
  unique (report_id, version_no)
);

alter table public.sm_reports enable row level security;
alter table public.sm_report_platforms enable row level security;
alter table public.sm_report_posts enable row level security;
alter table public.sm_report_versions enable row level security;

drop policy if exists sm_reports_read on public.sm_reports;
create policy sm_reports_read on public.sm_reports for select to authenticated
  using (public.allowed('clients.reports', 'view'));
drop policy if exists sm_reports_write on public.sm_reports;
create policy sm_reports_write on public.sm_reports for update to authenticated
  using (public.allowed('clients.reports', 'work')) with check (public.allowed('clients.reports', 'work'));
drop policy if exists sm_platforms_all on public.sm_report_platforms;
create policy sm_platforms_all on public.sm_report_platforms for all to authenticated
  using (public.allowed('clients.reports', 'view')) with check (public.allowed('clients.reports', 'work'));
drop policy if exists sm_posts_all on public.sm_report_posts;
create policy sm_posts_all on public.sm_report_posts for all to authenticated
  using (public.allowed('clients.reports', 'view')) with check (public.allowed('clients.reports', 'work'));
drop policy if exists sm_versions_read on public.sm_report_versions;
create policy sm_versions_read on public.sm_report_versions for select to authenticated
  using (public.allowed('clients.reports', 'view'));
-- A report's rows are removed only by the functions; a platform or a post
-- may be deleted directly while its report is a draft, which the guard below
-- decides. The versions are written by the functions alone.

/* The functions below set this for their own transaction. Nothing a browser
   sends can: `set_config` is not reachable through PostgREST, and the
   setting lives only as long as the function's own transaction. */
create or replace function public.sm_report_guard()
returns trigger
language plpgsql set search_path = public as $$
begin
  if coalesce(current_setting('adspace.sm_fn', true), '') = 'on' then
    new.updated_at := now();
    return new;
  end if;
  if new.status is distinct from old.status or new.version_no is distinct from old.version_no
     or new.submitted_by is distinct from old.submitted_by or new.submitted_at is distinct from old.submitted_at
     or new.confirmed_by is distinct from old.confirmed_by or new.confirmed_at is distinct from old.confirmed_at
     or new.return_note is distinct from old.return_note or new.client_id is distinct from old.client_id
     or new.kind is distinct from old.kind
     or new.created_by is distinct from old.created_by or new.created_at is distinct from old.created_at then
    raise exception 'sm-status-by-function' using errcode = 'P0001';
  end if;
  if old.status <> 'draft' then
    raise exception 'sm-not-draft' using errcode = 'P0001';
  end if;
  new.updated_at := now();
  return new;
end $$;
drop trigger if exists sm_reports_guard on public.sm_reports;
create trigger sm_reports_guard before update on public.sm_reports
  for each row execute function public.sm_report_guard();

create or replace function public.sm_report_child_guard()
returns trigger
language plpgsql set search_path = public as $$
declare
  st text;
  rid uuid := case when tg_op = 'DELETE' then old.report_id else new.report_id end;
begin
  if coalesce(current_setting('adspace.sm_fn', true), '') = 'on' then
    return case when tg_op = 'DELETE' then old else new end;
  end if;
  if tg_op = 'UPDATE' and new.report_id is distinct from old.report_id then
    raise exception 'sm-not-draft' using errcode = 'P0001';
  end if;
  select status into st from public.sm_reports where id = rid;
  -- The report itself is going (a client deleted, a cascade): nothing to guard.
  if st is null and tg_op = 'DELETE' then return old; end if;
  if st is distinct from 'draft' then
    raise exception 'sm-not-draft' using errcode = 'P0001';
  end if;
  -- A post is filed only under an account of its own report. Read through
  -- jsonb, because PL/pgSQL resolves `new.platform_id` on the accounts
  -- table too, where there is no such column.
  if tg_table_name = 'sm_report_posts' and tg_op <> 'DELETE' then
    if not exists (select 1 from public.sm_report_platforms p
                    where p.id = (to_jsonb(new) ->> 'platform_id')::uuid and p.report_id = new.report_id) then
      raise exception 'sm-wrong-platform' using errcode = 'P0001';
    end if;
  end if;
  update public.sm_reports set updated_at = now() where id = rid and status = 'draft'
    and updated_at < now() - interval '1 second';
  return case when tg_op = 'DELETE' then old else new end;
end $$;
drop trigger if exists sm_platforms_guard on public.sm_report_platforms;
create trigger sm_platforms_guard before insert or update or delete on public.sm_report_platforms
  for each row execute function public.sm_report_child_guard();
drop trigger if exists sm_posts_guard on public.sm_report_posts;
create trigger sm_posts_guard before insert or update or delete on public.sm_report_posts
  for each row execute function public.sm_report_child_guard();

/* The period in words, as the report and the activity record name it. */
create or replace function public.sm_period_word(p_start date, p_end date)
returns text
language sql immutable set search_path = public as $$
  select case
    when p_start = date_trunc('month', p_start)::date
     and p_end = (date_trunc('month', p_start) + interval '1 month - 1 day')::date
      then trim(to_char(p_start, 'FMMonth YYYY'))
    else to_char(p_start, 'FMDD Mon YYYY') || ' to ' || to_char(p_end, 'FMDD Mon YYYY')
  end
$$;

create or replace function public.sm_report_log(p_id uuid, p_action text, p_extra text default null)
returns void
language plpgsql security definer set search_path = public as $$
declare
  r public.sm_reports;
  who text;
  cname text;
begin
  select * into r from public.sm_reports where id = p_id;
  select c.name into cname from public.clients c where c.id = r.client_id;
  who := coalesce((public.ops_me()).name, auth.jwt() ->> 'email');
  insert into public.activity_log (actor, action, subject, detail)
  values (who, p_action, cname,
          public.sm_period_word(r.period_start, r.period_end) || ' · v' || r.version_no
          || coalesce(' · ' || nullif(btrim(p_extra), ''), ''));
end $$;
revoke all on function public.sm_report_log(uuid, text, text) from public, anon, authenticated;

/* The whole report as js/smreport.js reads it. `p_final` is the published
   form: the status the PDF prints as issued, and the time it was issued. */
create or replace function public.sm_report_snapshot(p_id uuid, p_final boolean default false)
returns jsonb
language plpgsql security definer stable set search_path = public as $$
declare
  r public.sm_reports;
  c public.clients;
begin
  if not public.allowed('clients.reports', 'view') then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_id;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  select * into c from public.clients where id = r.client_id;
  return jsonb_build_object(
    'report', jsonb_build_object(
      'id', r.id, 'kind', r.kind, 'title', r.title, 'client_name', c.name, 'client_logo_url', c.logo_url,
      'period_start', r.period_start, 'period_end', r.period_end,
      'headline', r.headline, 'intro', r.intro, 'insights', r.insights, 'rank_metric', r.rank_metric,
      'status', case when p_final then 'final' else r.status end,
      'version_no', r.version_no, 'generated_at', now(),
      'prepared_by_name', (select name from public.team_members where id = r.submitted_by)),
    'platforms', coalesce((select jsonb_agg(to_jsonb(p) - 'created_at' order by p.position, p.created_at)
                  from public.sm_report_platforms p where p.report_id = r.id), '[]'::jsonb),
    'posts', coalesce((select jsonb_agg((to_jsonb(q) - 'created_at' - 'thumb_data') || jsonb_build_object('thumb_url', q.thumb_data)
                  order by q.posted_on nulls last, q.position, q.created_at)
                  from public.sm_report_posts q where q.report_id = r.id), '[]'::jsonb));
end $$;
grant execute on function public.sm_report_snapshot(uuid, boolean) to authenticated;

/* A new report of a kind for a client and a period. The accounts of the
   client's latest earlier report of the same kind are carried forward, each
   starting with the followers that report ended on, so a month starts with
   its accounts in place and only the figures to type. Only the kinds the
   console can draw are accepted. */
create or replace function public.sm_report_create(p_client uuid, p_start date, p_end date, p_kind text default 'social')
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  rid uuid;
  prev uuid;
begin
  if me.id is null or not public.allowed('clients.reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if p_client is null or not exists (select 1 from public.clients where id = p_client) then
    return jsonb_build_object('error', 'not-found');
  end if;
  if p_start is null or p_end is null or p_end < p_start then return jsonb_build_object('error', 'bad-period'); end if;
  if coalesce(p_kind, '') not in ('social') then return jsonb_build_object('error', 'bad-kind'); end if;
  select id into rid from public.sm_reports
   where client_id = p_client and kind = p_kind and period_start = p_start and period_end = p_end;
  if rid is not null then return jsonb_build_object('error', 'exists', 'id', rid); end if;
  perform set_config('adspace.sm_fn', 'on', true);
  insert into public.sm_reports (client_id, kind, period_start, period_end, created_by)
  values (p_client, p_kind, p_start, p_end, me.id) returning id into rid;
  select id into prev from public.sm_reports
   where client_id = p_client and kind = p_kind and id <> rid and period_start < p_start
   order by period_start desc limit 1;
  if prev is not null then
    insert into public.sm_report_platforms (report_id, platform, account_name, handle, group_key, group_label,
      position, metrics, followers_start, er_basis, metric_notes)
    select rid, p.platform, p.account_name, p.handle, p.group_key, p.group_label, p.position, p.metrics,
           coalesce(p.followers_end, case when p.followers_start is not null and p.growth_override is not null
                                          then p.followers_start + p.growth_override end),
           p.er_basis, p.metric_notes
      from public.sm_report_platforms p where p.report_id = prev;
  end if;
  perform set_config('adspace.sm_fn', 'off', true);
  perform public.sm_report_log(rid, 'report.created');
  return jsonb_build_object('ok', true, 'id', rid, 'carried', prev is not null);
end $$;
grant execute on function public.sm_report_create(uuid, date, date, text) to authenticated;

create or replace function public.sm_report_submit(p_id uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.sm_reports;
begin
  if me.id is null or not public.allowed('clients.reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_id for update;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if r.status <> 'draft' then return jsonb_build_object('error', 'not-draft', 'status', r.status); end if;
  if not exists (select 1 from public.sm_report_platforms where report_id = p_id) then
    return jsonb_build_object('error', 'no-platforms');
  end if;
  if not exists (select 1 from public.sm_report_posts where report_id = p_id) then
    return jsonb_build_object('error', 'no-posts');
  end if;
  perform set_config('adspace.sm_fn', 'on', true);
  update public.sm_reports set status = 'review', submitted_by = me.id, submitted_at = now(),
    return_note = null, confirmed_by = null, confirmed_at = null where id = p_id;
  perform set_config('adspace.sm_fn', 'off', true);
  perform public.sm_report_log(p_id, 'report.submitted');
  return jsonb_build_object('ok', true, 'status', 'review');
end $$;
grant execute on function public.sm_report_submit(uuid) to authenticated;

/* Back to draft with a note saying what to change. The person who
   submitted it may take it back while it waits; otherwise it is the
   reviewer's act, which is Manage. */
create or replace function public.sm_report_return(p_id uuid, p_note text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.sm_reports;
begin
  if me.id is null or not public.allowed('clients.reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_id for update;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if r.status not in ('review', 'confirmed') then return jsonb_build_object('error', 'not-returnable', 'status', r.status); end if;
  if not public.allowed('clients.reports', 'manage')
     and not (r.status = 'review' and r.submitted_by = me.id) then
    return jsonb_build_object('error', 'denied');
  end if;
  if coalesce(btrim(p_note), '') = '' then return jsonb_build_object('error', 'note-required'); end if;
  perform set_config('adspace.sm_fn', 'on', true);
  update public.sm_reports set status = 'draft', return_note = btrim(p_note),
    confirmed_by = null, confirmed_at = null where id = p_id;
  perform set_config('adspace.sm_fn', 'off', true);
  perform public.sm_report_log(p_id, 'report.returned', btrim(p_note));
  return jsonb_build_object('ok', true, 'status', 'draft');
end $$;
grant execute on function public.sm_report_return(uuid, text) to authenticated;

/* The internal confirmation: somebody who may manage reports, and never
   the person who submitted it, reads it and says it is right. */
create or replace function public.sm_report_confirm(p_id uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.sm_reports;
begin
  if me.id is null or not public.allowed('clients.reports', 'manage') then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_id for update;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if r.status <> 'review' then return jsonb_build_object('error', 'not-in-review', 'status', r.status); end if;
  if r.submitted_by = me.id then return jsonb_build_object('error', 'self-confirm'); end if;
  perform set_config('adspace.sm_fn', 'on', true);
  update public.sm_reports set status = 'confirmed', confirmed_by = me.id, confirmed_at = now() where id = p_id;
  perform set_config('adspace.sm_fn', 'off', true);
  perform public.sm_report_log(p_id, 'report.confirmed');
  return jsonb_build_object('ok', true, 'status', 'confirmed');
end $$;
grant execute on function public.sm_report_confirm(uuid) to authenticated;

/* Publish: the confirmed report is frozen as its version and the client
   can read it. The same press twice publishes once. */
create or replace function public.sm_report_publish(p_id uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.sm_reports;
  snap jsonb;
  vid uuid;
begin
  if me.id is null or not public.allowed('clients.reports', 'manage') then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_id for update;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if r.status = 'published' then
    select id into vid from public.sm_report_versions where report_id = p_id and version_no = r.version_no;
    return jsonb_build_object('ok', true, 'status', 'published', 'version_id', vid, 'again', true);
  end if;
  if r.status <> 'confirmed' then return jsonb_build_object('error', 'not-confirmed', 'status', r.status); end if;
  snap := public.sm_report_snapshot(p_id, true);
  perform set_config('adspace.sm_fn', 'on', true);
  insert into public.sm_report_versions (report_id, version_no, snapshot, published_by)
  values (p_id, r.version_no, snap, me.name)
  on conflict (report_id, version_no) do update
    set snapshot = excluded.snapshot, published_by = excluded.published_by, published_at = now(),
        withdrawn_at = null, withdrawn_by = null, withdraw_reason = null
  returning id into vid;
  update public.sm_reports set status = 'published' where id = p_id;
  perform set_config('adspace.sm_fn', 'off', true);
  perform public.sm_report_log(p_id, 'report.published');
  return jsonb_build_object('ok', true, 'status', 'published', 'version_id', vid);
end $$;
grant execute on function public.sm_report_publish(uuid) to authenticated;

/* Revise a published report: a new draft with the next version number.
   The client goes on reading the published version until the revision is
   published in its place. */
create or replace function public.sm_report_revise(p_id uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.sm_reports;
begin
  if me.id is null or not public.allowed('clients.reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_id for update;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if r.status <> 'published' then return jsonb_build_object('error', 'not-published', 'status', r.status); end if;
  perform set_config('adspace.sm_fn', 'on', true);
  update public.sm_reports set status = 'draft', version_no = r.version_no + 1, return_note = null,
    submitted_by = null, submitted_at = null, confirmed_by = null, confirmed_at = null where id = p_id;
  perform set_config('adspace.sm_fn', 'off', true);
  perform public.sm_report_log(p_id, 'report.revised');
  return jsonb_build_object('ok', true, 'status', 'draft', 'version_no', r.version_no + 1);
end $$;
grant execute on function public.sm_report_revise(uuid) to authenticated;

/* Take the published version off the client's portal, with a reason. The
   version is kept, marked withdrawn; a published report goes back to
   confirmed so it can be published again. */
create or replace function public.sm_report_unpublish(p_id uuid, p_reason text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.sm_reports;
  n int;
begin
  if me.id is null or not public.allowed('clients.reports', 'manage') then return jsonb_build_object('error', 'denied'); end if;
  if coalesce(btrim(p_reason), '') = '' then return jsonb_build_object('error', 'reason-required'); end if;
  select * into r from public.sm_reports where id = p_id for update;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  perform set_config('adspace.sm_fn', 'on', true);
  update public.sm_report_versions set withdrawn_at = now(), withdrawn_by = me.name, withdraw_reason = btrim(p_reason)
   where report_id = p_id and withdrawn_at is null;
  get diagnostics n = row_count;
  if n = 0 then
    perform set_config('adspace.sm_fn', 'off', true);
    return jsonb_build_object('error', 'not-published');
  end if;
  if r.status = 'published' then
    update public.sm_reports set status = 'confirmed' where id = p_id;
  end if;
  perform set_config('adspace.sm_fn', 'off', true);
  perform public.sm_report_log(p_id, 'report.unpublished', btrim(p_reason));
  return jsonb_build_object('ok', true);
end $$;
grant execute on function public.sm_report_unpublish(uuid, text) to authenticated;

/* A report that was never published may be deleted, with its period typed
   back. One that a client has read is not: unpublish it instead, so the
   record of what the client was shown stands. */
create or replace function public.sm_report_delete(p_id uuid, p_confirm text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.sm_reports;
  word text;
  cname text;
begin
  if me.id is null or not public.allowed('clients.reports', 'manage') then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_id for update;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if exists (select 1 from public.sm_report_versions where report_id = p_id) then
    return jsonb_build_object('error', 'has-versions');
  end if;
  word := public.sm_period_word(r.period_start, r.period_end);
  if lower(btrim(coalesce(p_confirm, ''))) <> lower(word) then return jsonb_build_object('error', 'confirm-mismatch'); end if;
  select name into cname from public.clients where id = r.client_id;
  perform set_config('adspace.sm_fn', 'on', true);
  delete from public.sm_reports where id = p_id;
  perform set_config('adspace.sm_fn', 'off', true);
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'report.deleted', cname, word || ' · v' || r.version_no);
  return jsonb_build_object('ok', true);
end $$;
grant execute on function public.sm_report_delete(uuid, text) to authenticated;

/* The client portal: the newest version of each report that stands, for a
   client the signed-in address may open, and one version's snapshot. */
create or replace function public.portal_reports(p_client uuid)
returns jsonb
language plpgsql security definer stable set search_path = public as $$
begin
  if auth.jwt() ->> 'email' is null then return jsonb_build_object('error', 'not-signed-in'); end if;
  if p_client is null or p_client not in (select public.portal_clients()) then
    return jsonb_build_object('error', 'no-access');
  end if;
  return jsonb_build_object('reports', coalesce((
    select jsonb_agg(jsonb_build_object('id', v.id, 'kind', r.kind, 'title', r.title, 'period_start', r.period_start,
             'period_end', r.period_end, 'version_no', v.version_no, 'published_at', v.published_at)
           order by r.period_start desc)
      from public.sm_reports r
      join lateral (select * from public.sm_report_versions x
                     where x.report_id = r.id and x.withdrawn_at is null
                     order by x.version_no desc limit 1) v on true
     where r.client_id = p_client), '[]'::jsonb));
end $$;
revoke all on function public.portal_reports(uuid) from public, anon;
grant execute on function public.portal_reports(uuid) to authenticated;

create or replace function public.portal_report(p_version uuid)
returns jsonb
language plpgsql security definer stable set search_path = public as $$
declare
  v public.sm_report_versions;
  cid uuid;
begin
  if auth.jwt() ->> 'email' is null then return jsonb_build_object('error', 'not-signed-in'); end if;
  select * into v from public.sm_report_versions where id = p_version and withdrawn_at is null;
  if v.id is null then return jsonb_build_object('error', 'not-found'); end if;
  select client_id into cid from public.sm_reports where id = v.report_id;
  if cid is null or cid not in (select public.portal_clients()) then return jsonb_build_object('error', 'not-found'); end if;
  if exists (select 1 from public.sm_report_versions x where x.report_id = v.report_id
              and x.withdrawn_at is null and x.version_no > v.version_no) then
    return jsonb_build_object('error', 'not-found');
  end if;
  return jsonb_build_object('snapshot', v.snapshot);
end $$;
revoke all on function public.portal_report(uuid) from public, anon;
grant execute on function public.portal_report(uuid) to authenticated;

revoke all on function public.sm_report_guard() from public, anon, authenticated;
revoke all on function public.sm_report_child_guard() from public, anon, authenticated;
-- END OF SOCIAL MEDIA REPORTS

-- =========================================================================
-- SOCIAL MEDIA ADVERTISING REPORTS
--
-- The second kind the report builder makes: a client's monthly paid social
-- report, from the team's two templates (a first month, and every month
-- after it). Same engine of steps as the social media report (draft,
-- review, confirmed, published), same versions and the same client portal;
-- what differs is what is entered and how the PDF is drawn (js/smreport.js).
--
--   sm_reports.first_month  The client's first month of ads. Set when the
--                           report is made (no earlier advertising report
--                           for the client) and the team's to change. A
--                           first month carries the reading guidance and
--                           no previous period; a later month compares
--                           against the one before.
--   sm_reports.ads_totals   The account's own figures for the period, which
--                           cannot be added up from the ads (reach counts a
--                           person once however many ads they saw), and the
--                           previous period's, carried forward from the last
--                           advertising report when a new one is made:
--                           { reach, impressions, spend,
--                             prev_start, prev_end, prev_reach,
--                             prev_impressions, prev_spend,
--                             prev_groups: { objective: { results, spend } },
--                             groups: { objective: { results, label } } }
--   sm_report_ads           One row an ad and objective: the same creative
--                           run under two goals is two rows, compared side by
--                           side in the PDF.
--
-- Rollback:
--   drop table if exists public.sm_report_ads;
--   alter table public.sm_reports drop column if exists first_month,
--     drop column if exists ads_totals;
--   and re-run sm_report_create, sm_report_submit and sm_report_snapshot from
--   2026-09-25-social-media-reports.sql.
-- =========================================================================

alter table public.sm_reports add column if not exists first_month boolean not null default false;
alter table public.sm_reports add column if not exists ads_totals jsonb not null default '{}'::jsonb;

create table if not exists public.sm_report_ads (
  id            uuid primary key default gen_random_uuid(),
  report_id     uuid not null references public.sm_reports(id) on delete cascade,
  position      integer not null default 0,
  name          text not null,
  objective     text not null default 'awareness',
  result_label  text,
  audience      text,
  starts_on     date,
  ends_on       date,
  spend         numeric(12, 2),
  results       bigint,
  reach         bigint,
  impressions   bigint,
  ctr           numeric(8, 4),
  -- The cost per result as Ads Manager prints it, where it was typed; the PDF
  -- works it out from spend and results otherwise. `thousand` is a figure
  -- per 1,000 people reached, as Ads Manager prices a reach result.
  cpr           numeric(12, 4),
  cpr_basis     text,
  -- The share of results by age band, in per cent: {"18-24": 0, "25-34": 47.6, ...}.
  age           jsonb not null default '{}'::jsonb,
  hook_rate     numeric(8, 4),
  hold_rate     numeric(8, 4),
  -- Average play time, in seconds.
  avg_play      numeric(8, 2),
  -- Plays reaching each quarter of the video, in per cent of plays:
  -- {"p25": 40, "p50": 22, "p75": 12, "p95": 7, "p100": 5}.
  retention     jsonb not null default '{}'::jsonb,
  thumb_data    text,
  remark        text,
  created_at    timestamptz not null default now(),
  constraint sm_ads_basis check (cpr_basis is null or cpr_basis in ('result', 'thousand')),
  constraint sm_ads_objective check (objective in ('awareness', 'traffic', 'engagement', 'leads', 'messaging', 'sales', 'app')),
  constraint sm_ads_name check (btrim(name) <> ''),
  constraint sm_ads_dates check (starts_on is null or ends_on is null or ends_on >= starts_on),
  constraint sm_ads_figures check (coalesce(spend, 0) >= 0 and coalesce(results, 0) >= 0
                                   and coalesce(reach, 0) >= 0 and coalesce(impressions, 0) >= 0),
  constraint sm_ads_thumb check (thumb_data is null or (thumb_data like 'data:image/%' and length(thumb_data) <= 300000))
);
create index if not exists sm_report_ads_report_idx on public.sm_report_ads (report_id, position);

alter table public.sm_report_ads enable row level security;
drop policy if exists sm_ads_all on public.sm_report_ads;
create policy sm_ads_all on public.sm_report_ads for all to authenticated
  using (public.allowed('reports', 'view')) with check (public.allowed('reports', 'work'));
drop trigger if exists sm_ads_guard on public.sm_report_ads;
create trigger sm_ads_guard before insert or update or delete on public.sm_report_ads
  for each row execute function public.sm_report_child_guard();

/* The whole report as js/smreport.js reads it. `p_final` is the published
   form: the status the PDF prints as issued, and the time it was issued.
   The client's market is read through jsonb, because it decides which
   taxes the spend note names and a database without the column still draws
   the report. Reports View reads any report; Clients View reads a finished
   one, which is what the client record's Reports tab shows. */
create or replace function public.sm_report_snapshot(p_id uuid, p_final boolean default false)
returns jsonb
language plpgsql security definer stable set search_path = public as $$
declare
  r public.sm_reports;
  c public.clients;
begin
  if not public.allowed('reports', 'view') and not public.allowed('clients', 'view') then
    return jsonb_build_object('error', 'denied');
  end if;
  select * into r from public.sm_reports where id = p_id;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  -- Somebody who reads Clients but not Reports reads the finished report
  -- only: once it is confirmed, never while it is being prepared.
  if not public.allowed('reports', 'view') and r.status not in ('confirmed', 'published') then
    return jsonb_build_object('error', 'denied');
  end if;
  select * into c from public.clients where id = r.client_id;
  return jsonb_build_object(
    'report', jsonb_build_object(
      'id', r.id, 'kind', r.kind, 'title', r.title, 'client_name', c.name, 'client_logo_url', c.logo_url,
      'market', to_jsonb(c) ->> 'market',
      'period_start', r.period_start, 'period_end', r.period_end,
      'headline', r.headline, 'intro', r.intro, 'insights', r.insights, 'rank_metric', r.rank_metric,
      'first_month', r.first_month, 'ads_totals', r.ads_totals,
      'status', case when p_final then 'final' else r.status end,
      'version_no', r.version_no, 'generated_at', now(),
      'prepared_by_name', (select name from public.team_members where id = r.submitted_by)),
    'platforms', coalesce((select jsonb_agg(to_jsonb(p) - 'created_at' order by p.position, p.created_at)
                  from public.sm_report_platforms p where p.report_id = r.id), '[]'::jsonb),
    'posts', coalesce((select jsonb_agg((to_jsonb(q) - 'created_at' - 'thumb_data') || jsonb_build_object('thumb_url', q.thumb_data)
                  order by q.posted_on nulls last, q.position, q.created_at)
                  from public.sm_report_posts q where q.report_id = r.id), '[]'::jsonb),
    'ads', coalesce((select jsonb_agg((to_jsonb(a) - 'created_at' - 'thumb_data') || jsonb_build_object('thumb_url', a.thumb_data)
                  order by a.position, a.created_at)
                  from public.sm_report_ads a where a.report_id = r.id), '[]'::jsonb));
end $$;
grant execute on function public.sm_report_snapshot(uuid, boolean) to authenticated;

/* A new report of a kind for a client and a period.
   Social: the accounts of the client's latest earlier social report are
   carried forward, each starting with the followers that report ended on.
   Advertising: the first one a client has is their first month; a later one
   carries the previous report's period and totals forward as the figures it
   is compared against, so a month opens with its comparison in place. */
create or replace function public.sm_report_create(p_client uuid, p_start date, p_end date, p_kind text default 'social')
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  rid uuid;
  prev uuid;
  pr public.sm_reports;
  totals jsonb := '{}'::jsonb;
  pgroups jsonb;
begin
  if me.id is null or not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if p_client is null or not exists (select 1 from public.clients where id = p_client) then
    return jsonb_build_object('error', 'not-found');
  end if;
  if p_start is null or p_end is null or p_end < p_start then return jsonb_build_object('error', 'bad-period'); end if;
  if coalesce(p_kind, '') not in ('social', 'ads') then return jsonb_build_object('error', 'bad-kind'); end if;
  select id into rid from public.sm_reports
   where client_id = p_client and kind = p_kind and period_start = p_start and period_end = p_end;
  if rid is not null then return jsonb_build_object('error', 'exists', 'id', rid); end if;
  select id into prev from public.sm_reports
   where client_id = p_client and kind = p_kind and period_start < p_start
   order by period_start desc limit 1;
  perform set_config('adspace.sm_fn', 'on', true);
  if p_kind = 'ads' then
    if prev is not null then
      select * into pr from public.sm_reports where id = prev;
      select coalesce(jsonb_object_agg(g.objective, jsonb_build_object('results',
               coalesce(nullif(pr.ads_totals #>> array['groups', g.objective, 'results'], '')::numeric, g.results),
               'spend', g.spend)), '{}'::jsonb)
        into pgroups
        from (select a.objective, sum(a.results) as results, sum(a.spend) as spend
                from public.sm_report_ads a where a.report_id = prev group by a.objective) g;
      totals := jsonb_strip_nulls(jsonb_build_object(
        'prev_start', pr.period_start, 'prev_end', pr.period_end,
        'prev_reach', nullif(pr.ads_totals ->> 'reach', '')::numeric,
        'prev_impressions', coalesce(nullif(pr.ads_totals ->> 'impressions', '')::numeric,
                                     (select sum(impressions) from public.sm_report_ads where report_id = prev)),
        'prev_spend', coalesce(nullif(pr.ads_totals ->> 'spend', '')::numeric,
                               (select sum(spend) from public.sm_report_ads where report_id = prev)),
        'prev_groups', pgroups));
    end if;
    insert into public.sm_reports (client_id, kind, title, period_start, period_end, created_by, first_month, ads_totals)
    values (p_client, p_kind, 'Social Media Advertising Report', p_start, p_end, me.id, prev is null, totals)
    returning id into rid;
  else
    insert into public.sm_reports (client_id, kind, period_start, period_end, created_by)
    values (p_client, p_kind, p_start, p_end, me.id) returning id into rid;
    if prev is not null then
      insert into public.sm_report_platforms (report_id, platform, account_name, handle, group_key, group_label,
        position, metrics, followers_start, er_basis, metric_notes)
      select rid, p.platform, p.account_name, p.handle, p.group_key, p.group_label, p.position, p.metrics,
             coalesce(p.followers_end, case when p.followers_start is not null and p.growth_override is not null
                                            then p.followers_start + p.growth_override end),
             p.er_basis, p.metric_notes
        from public.sm_report_platforms p where p.report_id = prev;
    end if;
  end if;
  perform set_config('adspace.sm_fn', 'off', true);
  perform public.sm_report_log(rid, 'report.created');
  return jsonb_build_object('ok', true, 'id', rid, 'carried', prev is not null);
end $$;
grant execute on function public.sm_report_create(uuid, date, date, text) to authenticated;

/* Submit for review: a social report needs its accounts and posts, an
   advertising report its ads. */
create or replace function public.sm_report_submit(p_id uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.sm_reports;
begin
  if me.id is null or not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_id for update;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if r.status <> 'draft' then return jsonb_build_object('error', 'not-draft', 'status', r.status); end if;
  if r.kind = 'ads' then
    if not exists (select 1 from public.sm_report_ads where report_id = p_id) then
      return jsonb_build_object('error', 'no-ads');
    end if;
  else
    if not exists (select 1 from public.sm_report_platforms where report_id = p_id) then
      return jsonb_build_object('error', 'no-platforms');
    end if;
    if not exists (select 1 from public.sm_report_posts where report_id = p_id) then
      return jsonb_build_object('error', 'no-posts');
    end if;
  end if;
  perform set_config('adspace.sm_fn', 'on', true);
  update public.sm_reports set status = 'review', submitted_by = me.id, submitted_at = now(),
    return_note = null, confirmed_by = null, confirmed_at = null where id = p_id;
  perform set_config('adspace.sm_fn', 'off', true);
  perform public.sm_report_log(p_id, 'report.submitted');
  return jsonb_build_object('ok', true, 'status', 'review');
end $$;
grant execute on function public.sm_report_submit(uuid) to authenticated;
-- END OF SOCIAL MEDIA ADVERTISING REPORTS

-- =========================================================================
-- THE REPORTS SECTION
--
-- Reports were a part of Clients (`clients.reports`), so a colleague who
-- prepared reports had to be able to read every client record, and the
-- report opened on the client's record. They are a section of their own now:
--
--   reports View    read every report, preview its PDF
--   reports Work    start a report, enter its figures and text, submit it,
--                   revise a published one
--   reports Manage  also confirm, return, publish, unpublish and delete
--
-- A group's level moves across once: its `clients.reports` level where it
-- set one, else its Clients level (which the part fell back to), `none`
-- included, and the old key goes. Guarded on the new key, so a re-run moves
-- nothing. The client record keeps a Reports tab that shows the finished
-- reports only, read by anybody who reads Clients through the two functions
-- at the foot of this section; the tables themselves answer Reports alone.
--
-- Rollback:
--   update public.team_roles set access = (access - 'reports')
--     || jsonb_build_object('clients.reports', access ->> 'reports') where access ? 'reports';
--   drop function if exists public.sm_client_reports(uuid);
--   drop function if exists public.sm_report_file(uuid);
--   and re-run the policies and functions of 2026-09-25-social-media-reports.sql.
-- =========================================================================

update public.team_roles
   set access = (access - 'clients.reports')
       || jsonb_build_object('reports', coalesce(access ->> 'clients.reports', access ->> 'clients', 'none'))
 where not (access ? 'reports');
update public.team_members
   set access = (access - 'clients.reports')
       || jsonb_build_object('reports', coalesce(access ->> 'clients.reports', access ->> 'clients', 'none'))
 where not (access ? 'reports');

drop policy if exists sm_reports_read on public.sm_reports;
create policy sm_reports_read on public.sm_reports for select to authenticated
  using (public.allowed('reports', 'view'));
drop policy if exists sm_reports_write on public.sm_reports;
create policy sm_reports_write on public.sm_reports for update to authenticated
  using (public.allowed('reports', 'work')) with check (public.allowed('reports', 'work'));
drop policy if exists sm_platforms_all on public.sm_report_platforms;
create policy sm_platforms_all on public.sm_report_platforms for all to authenticated
  using (public.allowed('reports', 'view')) with check (public.allowed('reports', 'work'));
drop policy if exists sm_posts_all on public.sm_report_posts;
create policy sm_posts_all on public.sm_report_posts for all to authenticated
  using (public.allowed('reports', 'view')) with check (public.allowed('reports', 'work'));
drop policy if exists sm_versions_read on public.sm_report_versions;
create policy sm_versions_read on public.sm_report_versions for select to authenticated
  using (public.allowed('reports', 'view'));

-- A report is started for a client from the Reports section, so the client
-- list is read there too.
drop policy if exists clients_read on public.clients;
create policy clients_read on public.clients for select to authenticated
  using (public.allowed('clients', 'view') or public.allowed('review', 'view')
      or public.allowed('campaigns', 'view') or public.allowed('reports', 'view'));

/* Back to draft with a note saying what to change. The person who
   submitted it may take it back while it waits; otherwise it is the
   reviewer's act, which is Manage. */
create or replace function public.sm_report_return(p_id uuid, p_note text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.sm_reports;
begin
  if me.id is null or not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_id for update;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if r.status not in ('review', 'confirmed') then return jsonb_build_object('error', 'not-returnable', 'status', r.status); end if;
  if not public.allowed('reports', 'manage')
     and not (r.status = 'review' and r.submitted_by = me.id) then
    return jsonb_build_object('error', 'denied');
  end if;
  if coalesce(btrim(p_note), '') = '' then return jsonb_build_object('error', 'note-required'); end if;
  perform set_config('adspace.sm_fn', 'on', true);
  update public.sm_reports set status = 'draft', return_note = btrim(p_note),
    confirmed_by = null, confirmed_at = null where id = p_id;
  perform set_config('adspace.sm_fn', 'off', true);
  perform public.sm_report_log(p_id, 'report.returned', btrim(p_note));
  return jsonb_build_object('ok', true, 'status', 'draft');
end $$;
grant execute on function public.sm_report_return(uuid, text) to authenticated;

/* The internal confirmation: somebody who may manage reports, and never
   the person who submitted it, reads it and says it is right. */
create or replace function public.sm_report_confirm(p_id uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.sm_reports;
begin
  if me.id is null or not public.allowed('reports', 'manage') then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_id for update;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if r.status <> 'review' then return jsonb_build_object('error', 'not-in-review', 'status', r.status); end if;
  if r.submitted_by = me.id then return jsonb_build_object('error', 'self-confirm'); end if;
  perform set_config('adspace.sm_fn', 'on', true);
  update public.sm_reports set status = 'confirmed', confirmed_by = me.id, confirmed_at = now() where id = p_id;
  perform set_config('adspace.sm_fn', 'off', true);
  perform public.sm_report_log(p_id, 'report.confirmed');
  return jsonb_build_object('ok', true, 'status', 'confirmed');
end $$;
grant execute on function public.sm_report_confirm(uuid) to authenticated;

/* Publish: the confirmed report is frozen as its version and the client
   can read it. The same press twice publishes once. */
create or replace function public.sm_report_publish(p_id uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.sm_reports;
  snap jsonb;
  vid uuid;
begin
  if me.id is null or not public.allowed('reports', 'manage') then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_id for update;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if r.status = 'published' then
    select id into vid from public.sm_report_versions where report_id = p_id and version_no = r.version_no;
    return jsonb_build_object('ok', true, 'status', 'published', 'version_id', vid, 'again', true);
  end if;
  if r.status <> 'confirmed' then return jsonb_build_object('error', 'not-confirmed', 'status', r.status); end if;
  snap := public.sm_report_snapshot(p_id, true);
  perform set_config('adspace.sm_fn', 'on', true);
  insert into public.sm_report_versions (report_id, version_no, snapshot, published_by)
  values (p_id, r.version_no, snap, me.name)
  on conflict (report_id, version_no) do update
    set snapshot = excluded.snapshot, published_by = excluded.published_by, published_at = now(),
        withdrawn_at = null, withdrawn_by = null, withdraw_reason = null
  returning id into vid;
  update public.sm_reports set status = 'published' where id = p_id;
  perform set_config('adspace.sm_fn', 'off', true);
  perform public.sm_report_log(p_id, 'report.published');
  return jsonb_build_object('ok', true, 'status', 'published', 'version_id', vid);
end $$;
grant execute on function public.sm_report_publish(uuid) to authenticated;

/* Revise a published report: a new draft with the next version number.
   The client goes on reading the published version until the revision is
   published in its place. */
create or replace function public.sm_report_revise(p_id uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.sm_reports;
begin
  if me.id is null or not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_id for update;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if r.status <> 'published' then return jsonb_build_object('error', 'not-published', 'status', r.status); end if;
  perform set_config('adspace.sm_fn', 'on', true);
  update public.sm_reports set status = 'draft', version_no = r.version_no + 1, return_note = null,
    submitted_by = null, submitted_at = null, confirmed_by = null, confirmed_at = null where id = p_id;
  perform set_config('adspace.sm_fn', 'off', true);
  perform public.sm_report_log(p_id, 'report.revised');
  return jsonb_build_object('ok', true, 'status', 'draft', 'version_no', r.version_no + 1);
end $$;
grant execute on function public.sm_report_revise(uuid) to authenticated;

/* Take the published version off the client's portal, with a reason. The
   version is kept, marked withdrawn; a published report goes back to
   confirmed so it can be published again. */
create or replace function public.sm_report_unpublish(p_id uuid, p_reason text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.sm_reports;
  n int;
begin
  if me.id is null or not public.allowed('reports', 'manage') then return jsonb_build_object('error', 'denied'); end if;
  if coalesce(btrim(p_reason), '') = '' then return jsonb_build_object('error', 'reason-required'); end if;
  select * into r from public.sm_reports where id = p_id for update;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  perform set_config('adspace.sm_fn', 'on', true);
  update public.sm_report_versions set withdrawn_at = now(), withdrawn_by = me.name, withdraw_reason = btrim(p_reason)
   where report_id = p_id and withdrawn_at is null;
  get diagnostics n = row_count;
  if n = 0 then
    perform set_config('adspace.sm_fn', 'off', true);
    return jsonb_build_object('error', 'not-published');
  end if;
  if r.status = 'published' then
    update public.sm_reports set status = 'confirmed' where id = p_id;
  end if;
  perform set_config('adspace.sm_fn', 'off', true);
  perform public.sm_report_log(p_id, 'report.unpublished', btrim(p_reason));
  return jsonb_build_object('ok', true);
end $$;
grant execute on function public.sm_report_unpublish(uuid, text) to authenticated;

/* A report that was never published may be deleted, with its period typed
   back. One that a client has read is not: unpublish it instead, so the
   record of what the client was shown stands. */
create or replace function public.sm_report_delete(p_id uuid, p_confirm text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.sm_reports;
  word text;
  cname text;
begin
  if me.id is null or not public.allowed('reports', 'manage') then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_id for update;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if exists (select 1 from public.sm_report_versions where report_id = p_id) then
    return jsonb_build_object('error', 'has-versions');
  end if;
  word := public.sm_period_word(r.period_start, r.period_end);
  if lower(btrim(coalesce(p_confirm, ''))) <> lower(word) then return jsonb_build_object('error', 'confirm-mismatch'); end if;
  select name into cname from public.clients where id = r.client_id;
  perform set_config('adspace.sm_fn', 'on', true);
  delete from public.sm_reports where id = p_id;
  perform set_config('adspace.sm_fn', 'off', true);
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'report.deleted', cname, word || ' · v' || r.version_no);
  return jsonb_build_object('ok', true);
end $$;
grant execute on function public.sm_report_delete(uuid, text) to authenticated;

/* The client record's Reports tab: a client's finished reports, for
   anybody who reads Clients or Reports. Finished is confirmed or published,
   or a report being revised whose earlier version the client still reads. */
create or replace function public.sm_client_reports(p_client uuid)
returns jsonb
language plpgsql security definer stable set search_path = public as $$
begin
  if not public.allowed('clients', 'view') and not public.allowed('reports', 'view') then
    return jsonb_build_object('error', 'denied');
  end if;
  return jsonb_build_object('reports', coalesce((
    select jsonb_agg(jsonb_build_object('id', r.id, 'kind', r.kind, 'period_start', r.period_start,
             'period_end', r.period_end, 'status', r.status, 'version_no', r.version_no,
             'confirmed_at', r.confirmed_at, 'live_version', v.version_no, 'published_at', v.published_at)
           order by r.period_start desc, r.kind)
      from public.sm_reports r
      left join lateral (select x.version_no, x.published_at from public.sm_report_versions x
                          where x.report_id = r.id and x.withdrawn_at is null
                          order by x.version_no desc limit 1) v on true
     where r.client_id = p_client
       and (r.status in ('confirmed', 'published') or v.version_no is not null)), '[]'::jsonb));
end $$;
grant execute on function public.sm_client_reports(uuid) to authenticated;

/* The file of a finished report: the version the client reads where one is
   published, else the confirmed report as it stands. */
create or replace function public.sm_report_file(p_id uuid)
returns jsonb
language plpgsql security definer stable set search_path = public as $$
declare
  r public.sm_reports;
  snap jsonb;
begin
  if not public.allowed('clients', 'view') and not public.allowed('reports', 'view') then
    return jsonb_build_object('error', 'denied');
  end if;
  select * into r from public.sm_reports where id = p_id;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  select x.snapshot into snap from public.sm_report_versions x
   where x.report_id = p_id and x.withdrawn_at is null order by x.version_no desc limit 1;
  if snap is not null then return jsonb_build_object('snapshot', snap); end if;
  if r.status <> 'confirmed' then return jsonb_build_object('error', 'not-finished'); end if;
  return jsonb_build_object('snapshot', public.sm_report_snapshot(p_id, false));
end $$;
grant execute on function public.sm_report_file(uuid) to authenticated;
-- END OF THE REPORTS SECTION

-- ===========================================================================
-- BULK ADD FROM THE MONTH — Bulk add takes tasks only into a content month
-- the client already has, with its meeting confirmed; an admin moves a due
-- date without the approval round.
-- 2026-09-25. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/ops.js compares the two.
--
-- WHAT THIS CHANGES, AND WHAT IT LEAVES ALONE.
--
--   1. `ops_generate_month` made the client's month when there was none, so
--      Bulk add could fill a month nobody had planned (the user, 2026-09-25:
--      "if under client -> work is not created for the month, then it
--      shouldnt have tasks within it"). It now refuses, on the preview and on
--      the run alike: `no-month` where the client has no month for that
--      period, `month-closed` where the month is completed or cancelled, and
--      `month-not-confirmed` where its content meeting is neither set nor
--      marked not applicable. The spread over weeks, the codes and the
--      publish dates are unchanged.
--
--   2. `ops_request_due_change` sends an admin's move straight through, as it
--      already did for the person who created the task (the user: "admin
--      should have the full access to overwrite everything"). The move still
--      goes through `ops_change_due_date`, so the original commitment is kept
--      and the event is filed. Everybody else still asks the creator.
--
-- ROLLBACK
--   Re-run 2026-09-24-bulk-add-spreads-the-month.sql and section 4 of
--   2026-09-21-draft-date-is-the-teams-own.sql.
-- ===========================================================================

-- 1. A month of content, only into a month the client has ---------------------
create or replace function public.ops_generate_month(
  p_payload jsonb, p_dry_run boolean default false, p_idem text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m      public.team_members;
  cid    uuid;
  per    text;
  n      integer;
  weeks  integer[];
  bad    text;
  eng    uuid;
  e      public.ops_engagements;
  k      integer;
  w      integer;
  seq    integer;
  seqs   integer;
  made   jsonb := '[]'::jsonb;
  one    jsonb;
  key    text;
  scope  text;
  first_day date;
  last_off integer;
  publish timestamptz;
begin
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if not public.allowed('ops', 'work') then return jsonb_build_object('error', 'denied'); end if;

  cid := (p_payload ->> 'client_id')::uuid;
  per := p_payload ->> 'period';
  n := coalesce((p_payload ->> 'count')::integer, 0);
  scope := coalesce(p_payload ->> 'scope', 'client');
  bad := public.ops_scope_error(scope, cid);
  if bad is not null then return jsonb_build_object('error', bad); end if;
  if per is null or per !~ '^\d{4}-\d{2}$' then return jsonb_build_object('error', 'bad-period'); end if;
  if n < 1 or n > 60 then return jsonb_build_object('error', 'bad-count'); end if;

  if (p_payload -> 'weeks') is not null and jsonb_typeof(p_payload -> 'weeks') = 'array' then
    select array_agg(x::integer) into weeks from jsonb_array_elements_text(p_payload -> 'weeks') x;
    if array_length(weeks, 1) < 1 or array_length(weeks, 1) > 5 then
      return jsonb_build_object('error', 'bad-weeks');
    end if;
    if (select sum(v) from unnest(weeks) v) <> n then return jsonb_build_object('error', 'weeks-do-not-add-up'); end if;
  else
    /* Evenly over four weeks, the extras early: task i (from 0) falls in
       week floor(i * 4 / n) + 1, so eight is two a week, six is 2, 1, 2, 1,
       and two is weeks 1 and 3 rather than both in week 4. */
    weeks := array[]::integer[];
    for w in 1 .. 4 loop
      weeks := weeks || (ceil(w * n / 4.0)::integer - ceil((w - 1) * n / 4.0)::integer);
    end loop;
  end if;

  /* The same press twice is one month, not two. */
  if not p_dry_run and p_idem is not null then
    if exists (select 1 from public.ops_tasks where idem_key = 'month:' || p_idem || ':1') then
      return jsonb_build_object('error', 'already-generated');
    end if;
  end if;

  first_day := (per || '-01')::date;
  last_off := ((first_day + interval '1 month')::date - first_day) - 1;
  /* One lock for the whole run, taken before anything is read: two operators
     generating the same month queue here, so the second sees the first's
     engagement and the first's numbers rather than racing both. */
  perform pg_advisory_xact_lock(hashtext('ops_code:' || cid::text || ':' || per));
  /* The month must already exist on the client's Work pane, still be open,
     and have its content meeting confirmed: a month nobody planned holds no
     tasks. Asked on the preview as well as the run, so the sheet cannot
     show codes for a month the run would refuse. */
  select * into e from public.ops_engagements
   where client_id = cid and period = per;
  if e.id is null then return jsonb_build_object('error', 'no-month'); end if;
  if (p_payload ->> 'engagement_id') is not null and (p_payload ->> 'engagement_id')::uuid <> e.id then
    return jsonb_build_object('error', 'no-month');
  end if;
  if e.status in ('completed', 'cancelled') then return jsonb_build_object('error', 'month-closed'); end if;
  if e.meeting_at is null and not e.meeting_na then
    return jsonb_build_object('error', 'month-not-confirmed');
  end if;
  eng := e.id;
  if not p_dry_run then
    update public.ops_engagements set planned_count = greatest(planned_count, n), updated_at = now()
     where id = eng and planned_count < n;
  end if;

  /* One lock for the whole month, so the preview and the run see the same
     next number and two operators generating for one client queue. */
  seq := public.ops_next_seq(cid, per) - 1;
  seqs := 0;
  for w in 1 .. array_length(weeks, 1) loop
    for k in 1 .. coalesce(weeks[w], 0) loop
      seq := seq + 1;
      seqs := seqs + 1;
      /* A tentative date inside the task's own week, the week's tasks
         spread across its seven days, so the calendar has somewhere to put
         each one; the content meeting fixes the real date. Never past the
         month's last day, which only a fifth week can reach. */
      publish := (first_day + least((w - 1) * 7 + ((k - 1) * 7) / weeks[w], last_off))::timestamptz;
      if p_dry_run then
        made := made || jsonb_build_object('code', public.ops_code_of(per, w, seq), 'week', w, 'seq', seq);
      else
        key := case when p_idem is null then null else 'month:' || p_idem || ':' || seqs::text end;
        one := public.ops_create_task(jsonb_build_object(
          'scope', scope, 'client_id', cid, 'engagement_id', eng,
          'task_type', coalesce(p_payload ->> 'task_type', 'engagement'),
          'deliverable_type', p_payload ->> 'deliverable_type',
          'priority_level', (p_payload ->> 'priority_level')::integer,
          'complexity', p_payload ->> 'complexity',
          'owner_id', (p_payload ->> 'owner_id')::uuid,
          'manager_id', (p_payload ->> 'manager_id')::uuid,
          'code_period', per, 'code_week', w,
          'publish_at', publish), key);
        if one ? 'error' then return one; end if;
        made := made || jsonb_build_object('id', one ->> 'id', 'code', one ->> 'code', 'week', w, 'seq', seq);
      end if;
    end loop;
  end loop;
  return jsonb_build_object('engagement_id', eng, 'period', per, 'count', seqs,
                            'tasks', made, 'dry_run', p_dry_run);
end $$;
grant execute on function public.ops_generate_month(jsonb, boolean, text) to authenticated;

-- 2. Asking to move a date; an admin moves it --------------------------------
create or replace function public.ops_request_due_change(
  p_task uuid, p_kind text, p_value timestamptz, p_reason text,
  p_note text default null, p_version integer default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m     public.team_members;
  t     public.ops_tasks;
  who   uuid;
  was   timestamptz;
  v_id  uuid;
  nm    text;
begin
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if not public.ops_may_see_task(p_task) then return jsonb_build_object('error', 'denied'); end if;
  if not public.allowed('ops', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if coalesce(p_reason, '') = '' then return jsonb_build_object('error', 'reason-required'); end if;
  if p_kind not in ('first_draft', 'final') then return jsonb_build_object('error', 'bad-kind'); end if;
  if p_value is null then return jsonb_build_object('error', 'no-date'); end if;

  select * into t from public.ops_tasks where id = p_task for update;
  if t.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if p_version is not null and p_version <> t.version then
    return jsonb_build_object('error', 'stale', 'task', public.ops_task_json(p_task));
  end if;

  /* Refused before an ask is raised as well as before a move is made: an ask
     nobody could approve without breaking the plan is one to turn away at the
     door, with the word the move itself would have used. */
  if not public.ops_due_order_ok(
       case when p_kind = 'first_draft' then p_value else t.current_first_draft_due_at end,
       case when p_kind = 'final'       then p_value else t.current_final_due_at end) then
    return jsonb_build_object('error', 'draft-not-before-final');
  end if;

  who := public.ops_due_decider(p_task, p_kind);
  /* Nobody to ask — the team's own first draft milestone, or a task whose
     creator is the person asking — so the move is theirs to make and the
     round would be a form with one name on both ends. */
  /* An admin moves any date directly: the round protects the person who set
     the date from somebody else, and an admin is the one who may overwrite
     anybody's. The move still files its event and keeps the original. */
  if who is null or who = m.id or public.allowed('admin') then
    return public.ops_change_due_date(p_task, p_kind, p_value, p_reason, p_note, p_version);
  end if;

  was := case when p_kind = 'final' then t.current_final_due_at
              else t.current_first_draft_due_at end;

  insert into public.ops_due_requests
    (task_id, kind, was_at, wants_at, reason, note, asked_by, decider_id)
  values (p_task, p_kind, was, p_value, p_reason, nullif(btrim(p_note), ''), m.id, who)
  on conflict (task_id, kind) where state = 'asked' do nothing
  returning id into v_id;

  /* The same press twice is the same ask. The open one is handed back so the
     page can say it is already with somebody. */
  if v_id is null then
    select id into v_id from public.ops_due_requests
      where task_id = p_task and kind = p_kind and state = 'asked';
    return jsonb_build_object('ok', true, 'repeat', true, 'request', v_id,
                              'task', public.ops_task_json(p_task));
  end if;

  select name into nm from public.team_members where id = m.id;
  perform public.ops_notify(who, p_task, 'due_requested',
    'Extension requested',
    coalesce(nm, 'Somebody') || ' asked to move ' ||
      case when p_kind = 'final' then 'the due date' else 'the first draft date' end ||
      ' to ' || to_char(timezone('Asia/Kuala_Lumpur', p_value), 'DD Mon YYYY'),
    'due_req:' || v_id::text);

  perform public.ops_log(p_task, 'due_requested',
    jsonb_build_object('kind', p_kind, 'value', was),
    jsonb_build_object('kind', p_kind, 'value', p_value),
    jsonb_build_object('reason', p_reason, 'note', p_note, 'request', v_id));

  return jsonb_build_object('ok', true, 'request', v_id, 'asked', true,
                            'task', public.ops_task_json(p_task));
end $$;
grant execute on function public.ops_request_due_change(uuid, text, timestamptz, text, text, integer) to authenticated;

-- END OF BULK ADD FROM THE MONTH -------------------------------------------

-- ===========================================================================
-- THE OWNER MOVES THE TASK — every task has an owner, and only the owner
-- (or an admin) moves its stage.
-- 2026-09-25. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/ops.js compares the two.
--
-- WHAT THIS CHANGES, AND WHAT IT LEAVES ALONE.
--
--   1. `ops_create_task` makes the person creating a task its owner when the
--      payload names nobody and the template names nobody, so no task is made
--      ownerless (the team, 2026-09-25: "cannot have no owner situation").
--      Open tasks already without an owner take whoever created them.
--
--   2. `ops_transition_task` and `ops_set_blocked` refuse `not-owner` unless
--      the caller is the task's current owner or an admin (the team: "when
--      owner alr changed, other users shouldnt have the authority to mark the
--      status for them"). Unblocking, marking live and a board drag all go
--      through the transition, so they follow. A task with no owner, which
--      now only a hand edit could leave, may be moved by anybody who works it.
--
--   Assigning, handing over, dates, links and comments are unchanged.
--
-- ROLLBACK
--   Re-run the ops_create_task, ops_transition_task and ops_set_blocked
--   definitions in 2026-09-24-my-work-daily-tasks.sql and
--   2026-09-19-operations-system.sql, then
--   drop function if exists public.ops_owner_may_move(uuid);
--   The owners the backfill added stay; end them by hand if wanted.
-- ===========================================================================

-- 1. Who may move a task ------------------------------------------------------
create or replace function public.ops_owner_may_move(p_task uuid)
returns boolean
language sql security definer stable set search_path = public as $$
  select public.allowed('admin')
      or not exists (select 1 from public.ops_task_assignees a
                      where a.task_id = p_task and a.responsibility = 'owner' and a.ended_at is null)
      or exists (select 1 from public.ops_task_assignees a
                  where a.task_id = p_task and a.responsibility = 'owner' and a.ended_at is null
                    and a.team_member_id = (public.ops_me()).id)
$$;
grant execute on function public.ops_owner_may_move(uuid) to authenticated;

-- 2. A new task is owned from the start -------------------------------------
create or replace function public.ops_create_task(p_payload jsonb, p_idem text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m     public.team_members;
  tpl   public.ops_task_templates;
  wf    uuid;
  tid   uuid;
  owner uuid;
  publish timestamptz;
  fd    timestamptz;
  fin   timestamptz;
  item  jsonb;
  i     integer := 0;
  scope text;
  ttype text;
  cid   uuid;
  bad   text;
  descr text;
  period text;
  week  integer;
  seq   integer;
  code  text;
  title text;
  first_stage text;
  wkey  text;
  base  timestamptz;
  eng   public.ops_engagements;
begin
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if not public.allowed('ops', 'work') then return jsonb_build_object('error', 'denied'); end if;

  -- The same press twice is one task.
  if p_idem is not null then
    select id into tid from public.ops_tasks where idem_key = p_idem;
    if tid is not null then return public.ops_task_json(tid); end if;
  end if;

  scope := coalesce(p_payload ->> 'scope', 'client');
  cid := (p_payload ->> 'client_id')::uuid;
  /* A task linked to a month's engagement takes the client from it: the
     person names the month once and the client comes with it. */
  if (p_payload ->> 'engagement_id') is not null then
    select * into eng from public.ops_engagements where id = (p_payload ->> 'engagement_id')::uuid;
    if eng.id is null then return jsonb_build_object('error', 'not-found'); end if;
    if cid is null then cid := eng.client_id; scope := 'client'; end if;
  end if;
  bad := public.ops_scope_error(scope, cid);
  if bad is not null then return jsonb_build_object('error', bad); end if;

  ttype := coalesce(p_payload ->> 'task_type', 'adhoc');
  if ttype not in ('engagement', 'adhoc', 'goodwill', 'special') then
    return jsonb_build_object('error', 'bad-task-type');
  end if;

  /* The description is the team's to edit and may start blank on a task that
     carries a code; a task with no code is named by its description alone, so
     there it is required. `title` is accepted from older callers as the
     description. */
  descr := nullif(btrim(coalesce(p_payload ->> 'content_desc', p_payload ->> 'title', '')), '');

  if (p_payload ->> 'template_id') is not null then
    select * into tpl from public.ops_task_templates
     where id = (p_payload ->> 'template_id')::uuid;
    descr := coalesce(descr, nullif(btrim(coalesce(tpl.default_title, tpl.name, '')), ''));
  end if;
  /* New work goes on the content workflow. A caller may still name another
     (a template's own, or one somebody adds), and a task already on a retired
     workflow is never moved. */
  wf := coalesce((p_payload ->> 'workflow_id')::uuid,
                 (select id from public.ops_workflows where key = p_payload ->> 'workflow_key' and active),
                 tpl.workflow_id,
                 (select id from public.ops_workflows where key = 'content' and active),
                 (select id from public.ops_workflows where active order by created_at limit 1));
  if wf is null then return jsonb_build_object('error', 'workflow-required'); end if;
  select key into first_stage from public.ops_workflow_stages
   where workflow_id = wf order by position limit 1;
  select key into wkey from public.ops_workflows where id = wf;

  publish := (p_payload ->> 'publish_at')::timestamptz;
  fd := coalesce((p_payload ->> 'first_draft_due_at')::timestamptz,
        case when publish is not null and tpl.first_draft_offset_business_days is not null
             then public.ops_add_business_days(publish, -tpl.first_draft_offset_business_days)
             when tpl.first_draft_offset_business_days is not null
             then public.ops_add_business_days(now(), tpl.first_draft_offset_business_days)
        end);
  /* A template's due date is a number of calendar days from the day the
     work is made for (the base date the caller names, else today). */
  base := coalesce((p_payload ->> 'base_date')::timestamptz, now());
  fin := coalesce((p_payload ->> 'final_due_at')::timestamptz,
        case when tpl.due_offset_days is not null
             then date_trunc('day', base) + make_interval(days => tpl.due_offset_days)
             when publish is not null and tpl.final_offset_business_days is not null
             then public.ops_add_business_days(publish, -tpl.final_offset_business_days)
             when tpl.final_offset_business_days is not null
             then public.ops_add_business_days(now(), tpl.final_offset_business_days)
        end);
  if fd is not null and fin is not null and not public.ops_due_order_ok(fd, fin) then
    return jsonb_build_object('error', 'draft-not-before-final');
  end if;

  /* The name. The month is the content month (the scheduled publish date's,
     else the one the caller names, else this one); the week is the planned
     publishing week, chosen by the caller and prefilled by the page from the
     date; the running number is the client's for the month. Generated once,
     under the lock, and never rewritten: a publish date that moves later
     leaves the name as it was, because the name is a label and not a fact
     about the date. */
  if wkey = 'task' then
    /* An everyday task is named by what it is. It carries no content code,
       because the code numbers a client's deliverables for the month and a
       task is not one; the content month is kept where it is known, so the
       task can be grouped with the month it belongs to. */
    if descr is null then return jsonb_build_object('error', 'title-required'); end if;
    title := descr;
    period := coalesce(nullif(p_payload ->> 'code_period', ''), eng.period);
  elsif scope <> 'internal' then
    period := coalesce(nullif(p_payload ->> 'code_period', ''),
                       case when publish is not null then to_char(publish, 'YYYY-MM') end,
                       to_char(now(), 'YYYY-MM'));
    if period !~ '^\d{4}-\d{2}$' then return jsonb_build_object('error', 'bad-period'); end if;
    week := coalesce((p_payload ->> 'code_week')::integer,
                     case when publish is not null
                          then least(5, ((extract(day from publish)::integer - 1) / 7) + 1) end,
                     1);
    if week < 1 or week > 5 then return jsonb_build_object('error', 'bad-week'); end if;
    seq := public.ops_next_seq(cid, period);
    code := public.ops_code_of(period, week, seq);
    title := btrim(code || ' ' || coalesce(descr, ''));
  else
    if descr is null then return jsonb_build_object('error', 'title-required'); end if;
    title := descr;
  end if;

  insert into public.ops_tasks (
    scope, client_id, campaign_id, batch_id, source_type, source_id, template_id,
    workflow_id, stage_key, title, description, remarks, deliverable_type,
    language_codes, priority_level, complexity, estimate_minutes, publish_at,
    original_first_draft_due_at, current_first_draft_due_at,
    original_final_due_at, current_final_due_at, created_by, idem_key,
    legacy_source, legacy_key, data_quality,
    task_type, code, code_period, code_week, code_seq, content_desc,
    engagement_id, manager_id, parent_task_id)
  values (
    scope, cid,
    (p_payload ->> 'campaign_id')::uuid,
    (p_payload ->> 'batch_id')::uuid,
    p_payload ->> 'source_type',
    (p_payload ->> 'source_id')::uuid,
    tpl.id, wf, coalesce(first_stage, 'intake'),
    title, p_payload ->> 'description', p_payload ->> 'remarks',
    coalesce(p_payload ->> 'deliverable_type', tpl.deliverable_type, 'other'),
    coalesce((select array_agg(x) from jsonb_array_elements_text(
               coalesce(p_payload -> 'language_codes', '[]'::jsonb)) x), '{}'),
    coalesce((p_payload ->> 'priority_level')::smallint, 3),
    coalesce(p_payload ->> 'complexity', tpl.default_complexity),
    coalesce((p_payload ->> 'estimate_minutes')::integer, tpl.default_estimate_minutes),
    publish, fd, fd, fin, fin, m.id, p_idem,
    p_payload ->> 'legacy_source', p_payload ->> 'legacy_key',
    coalesce(p_payload ->> 'data_quality', 'complete'),
    ttype, code, period, week, seq, descr,
    coalesce((p_payload ->> 'engagement_id')::uuid, eng.id),
    coalesce((p_payload ->> 'manager_id')::uuid, m.id),
    (p_payload ->> 'parent_task_id')::uuid)
  returning id into tid;

  /* Every task has an owner from the moment it exists: the one named, the
     template's, or else whoever made it. */
  owner := coalesce((p_payload ->> 'owner_id')::uuid, tpl.default_owner_id, m.id);
  if owner is not null then
    insert into public.ops_task_assignees (task_id, team_member_id, responsibility, assigned_by)
    values (tid, owner, 'owner', m.id);
    perform public.ops_log(tid, 'assignment_changed', null,
      jsonb_build_object('owner_id', owner), '{}'::jsonb);
  end if;
  if (p_payload ->> 'reviewer_id') is not null then
    insert into public.ops_task_assignees (task_id, team_member_id, responsibility, assigned_by)
    values (tid, (p_payload ->> 'reviewer_id')::uuid, 'reviewer', m.id);
  end if;

  -- The template's checklist, or the one the caller hands over (a duplicate
  -- carries its source's labels, unticked), in the order stated.
  for item in select * from jsonb_array_elements(
      coalesce(p_payload -> 'checklist', tpl.checklist, '[]'::jsonb)) loop
    i := i + 1;
    insert into public.ops_task_checklist_items (task_id, label, position)
    values (tid, item #>> '{}', i);
  end loop;

  if (p_payload -> 'video') is not null then
    insert into public.ops_video_details (
      task_id, output_duration_seconds, footage_duration_seconds,
      subtitle_required, motion_graphics_required, aspect_ratios,
      script_ready, footage_ready, shoot_required, shoot_at, variant_count)
    values (tid,
      ((p_payload -> 'video') ->> 'output_duration_seconds')::integer,
      ((p_payload -> 'video') ->> 'footage_duration_seconds')::integer,
      coalesce(((p_payload -> 'video') ->> 'subtitle_required')::boolean, false),
      coalesce(((p_payload -> 'video') ->> 'motion_graphics_required')::boolean, false),
      coalesce((select array_agg(x) from jsonb_array_elements_text(
                 coalesce((p_payload -> 'video') -> 'aspect_ratios', '[]'::jsonb)) x), '{}'),
      ((p_payload -> 'video') ->> 'script_ready')::boolean,
      ((p_payload -> 'video') ->> 'footage_ready')::boolean,
      coalesce(((p_payload -> 'video') ->> 'shoot_required')::boolean, false),
      ((p_payload -> 'video') ->> 'shoot_at')::timestamptz,
      coalesce(((p_payload -> 'video') ->> 'variant_count')::integer, 1));
  end if;

  perform public.ops_log(tid, 'task_created', null,
    jsonb_build_object('title', title, 'code', code,
                       'first_draft_due_at', fd, 'final_due_at', fin),
    case when (p_payload ->> 'duplicated_from') is null then '{}'::jsonb
         else jsonb_build_object('duplicated_from', p_payload ->> 'duplicated_from') end);
  return public.ops_task_json(tid);
end $$;
grant execute on function public.ops_create_task(jsonb, text) to authenticated;

-- 3. Only the owner moves the stage ------------------------------------------
create or replace function public.ops_transition_task(
  p_task uuid, p_next text, p_version integer default null, p_note text default null,
  p_assignee uuid default null, p_skip_reason text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m   public.team_members;
  t   public.ops_tasks;
  cur public.ops_workflow_stages;
  nxt public.ops_workflow_stages;
  sk  public.ops_workflow_stages;
  eng public.ops_engagements;
  has_owner boolean;
  has_draft boolean;
  has_final boolean;
  was_owner uuid;
  side text[] := array['blocked', 'waiting', 'kiv', 'cancelled'];
  skipping boolean := false;
  ws  public.ops_work_sessions;
  wmins integer;
  v_round integer;
begin
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if not public.ops_may_see_task(p_task) then return jsonb_build_object('error', 'denied'); end if;
  if not public.allowed('ops', 'work') then return jsonb_build_object('error', 'denied'); end if;

  select * into t from public.ops_tasks where id = p_task for update;
  if t.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if p_version is not null and p_version <> t.version then
    return jsonb_build_object('error', 'stale', 'task', public.ops_task_json(p_task));
  end if;
  if t.stage_key = p_next then return public.ops_task_json(p_task); end if;
  /* The stage is the owner's to move. Once a task is handed to somebody,
     whoever created it or held it before reads it and no longer moves it; an
     admin still may. */
  if not public.ops_owner_may_move(p_task) then return jsonb_build_object('error', 'not-owner'); end if;

  cur := public.ops_stage(t.workflow_id, t.stage_key);
  nxt := public.ops_stage(t.workflow_id, p_next);
  if nxt.id is null then return jsonb_build_object('error', 'no-such-stage'); end if;
  if not (p_next = any (cur.next_stage_keys)) then
    /* A step the deliverable does not need is skipped, forward along the
       line, with a reason on the record: who skipped it and why is written
       against every stage that was passed over. Nothing beside the line can
       be skipped into or out of, and nothing is skipped backwards. */
    /* A revision is where work is sent back from a review, so it is never
       a step somebody skips forward into. */
    if not (cur.stage_group = any (side)) and not (nxt.stage_group = any (side))
       and nxt.stage_group <> 'revision'
       and nxt.position > cur.position then
      if nullif(btrim(coalesce(p_skip_reason, '')), '') is null then
        return jsonb_build_object('error', 'skip-reason-required');
      end if;
      skipping := true;
    else
      return jsonb_build_object('error', 'bad-transition',
        'allowed', to_jsonb(cur.next_stage_keys));
    end if;
  end if;

  /* A performance review goes back to whoever created the task unless the
     move names somebody else. */
  if p_next = 'performance_review' and p_assignee is null and exists (
       select 1 from public.team_members where id = t.created_by and active) then
    p_assignee := t.created_by;
  end if;

  -- What each gate needs before it opens.
  has_owner := exists (select 1 from public.ops_task_assignees
                        where task_id = p_task and responsibility = 'owner' and ended_at is null)
               or p_assignee is not null;
  has_draft := exists (select 1 from public.ops_task_links
                        where task_id = p_task and archived_at is null
                          and kind in ('draft', 'review'));
  has_final := exists (select 1 from public.ops_task_links
                        where task_id = p_task and archived_at is null and kind = 'final');

  if p_next = 'ready' and (not has_owner or t.current_final_due_at is null) then
    return jsonb_build_object('error', 'ready-needs-owner-and-due');
  end if;
  if p_next = 'editing' and exists (
       select 1 from public.ops_video_details v
        where v.task_id = p_task and v.footage_ready is false) then
    return jsonb_build_object('error', 'footage-not-ready');
  end if;
  /* Production waits on the engagement: planning marked complete, and the
     content meeting held or marked not applicable. A task with no engagement
     (ad hoc, internal) has nothing to wait on. */
  if p_next = 'in_production' and t.engagement_id is not null then
    select * into eng from public.ops_engagements where id = t.engagement_id;
    if eng.status = 'planning' then return jsonb_build_object('error', 'planning-incomplete'); end if;
    if not (eng.meeting_na or (eng.meeting_at is not null and eng.meeting_at <= now())) then
      return jsonb_build_object('error', 'meeting-required');
    end if;
  end if;
  /* AQC review comes first: the client sees the work only once it has been
     through AQC review at least once. */
  if p_next = 'client_review'
     and exists (select 1 from public.ops_workflow_stages s
                  where s.workflow_id = t.workflow_id and s.key = 'internal_review')
     and not exists (select 1 from public.ops_task_events e
                      where e.task_id = p_task and e.event_type = 'stage_changed'
                        and e.to_value ->> 'stage_key' = 'internal_review') then
    return jsonb_build_object('error', 'needs-aqc');
  end if;
  /* The draft reaches the client as a link on the task or through the
     team's WhatsApp group with the client. Either way the record says how:
     the link, or a note naming where it went. */
  if p_next = 'client_review' and not has_draft
     and nullif(btrim(coalesce(p_note, '')), '') is null then
    return jsonb_build_object('error', 'needs-draft');
  end if;
  /* A revision says what has to change, and so does taking a post down. */
  if ((nxt.stage_group = 'revision' and p_next <> 'changes_requested') or p_next = 'taken_down')
     and nullif(btrim(coalesce(p_note, '')), '') is null then
    return jsonb_build_object('error', 'note-required');
  end if;
  /* After approval: a schedule needs its date, going live is confirmed with
     its own date through ops_mark_live and needs the post's link or a note,
     and a task is completed only once its performance checklist is done. */
  if p_next = 'scheduled' and t.publish_at is null then
    return jsonb_build_object('error', 'needs-schedule');
  end if;
  if p_next = 'live' and t.live_at is null then
    return jsonb_build_object('error', 'needs-live-date');
  end if;
  if p_next = 'live' and not has_final and coalesce(p_note, '') = '' then
    return jsonb_build_object('error', 'needs-final-or-reason');
  end if;
  if p_next = 'completed' and exists (
       select 1 from public.ops_task_checklist_items c
        where c.task_id = p_task and c.required and c.completed_at is null) then
    return jsonb_build_object('error', 'checklist-incomplete');
  end if;
  if p_next = 'delivered' and not has_final then
    return jsonb_build_object('error', 'needs-final-link');
  end if;
  if p_next = 'done' and t.delivered_at is null
     and coalesce(p_note, '') = '' then
    return jsonb_build_object('error', 'needs-delivery-or-reason');
  end if;
  if p_next = 'published' and not has_final and coalesce(p_note, '') = '' then
    return jsonb_build_object('error', 'needs-final-or-reason');
  end if;

  /* The hand to the next person, recorded on the move: the previous owner
     ends, the new one begins, and the event names both with the stage it
     happened at. Work level, because handing the work on is part of doing
     it; reassigning a task without moving it stays Manage. */
  if p_assignee is not null then
    select team_member_id into was_owner from public.ops_task_assignees
     where task_id = p_task and responsibility = 'owner' and ended_at is null;
    if p_assignee is distinct from was_owner then
      if not exists (select 1 from public.team_members where id = p_assignee and active) then
        return jsonb_build_object('error', 'no-such-person');
      end if;
      update public.ops_task_assignees set ended_at = now()
       where task_id = p_task and responsibility = 'owner' and ended_at is null;
      insert into public.ops_task_assignees (task_id, team_member_id, responsibility, assigned_by)
      values (p_task, p_assignee, 'owner', m.id);
      perform public.ops_log(p_task, 'assignment_changed',
        jsonb_build_object('owner_id', was_owner),
        jsonb_build_object('owner_id', p_assignee),
        jsonb_build_object('handover', true, 'stage_key', p_next, 'from_stage_key', t.stage_key));
    end if;
  end if;

  if skipping then
    for sk in select * from public.ops_workflow_stages
               where workflow_id = t.workflow_id
                 and position > cur.position and position < nxt.position
                 and not (stage_group = any (side))
               order by position loop
      perform public.ops_log(p_task, 'stage_skipped',
        jsonb_build_object('stage_key', sk.key), jsonb_build_object('stage_key', p_next),
        jsonb_build_object('reason', btrim(p_skip_reason)));
    end loop;
  end if;

  /* The round: how many times this task has now entered this review or
     this revision, counted off its own history, so nothing is stored that
     a reverted move could leave wrong. */
  if nxt.is_review or nxt.stage_group = 'revision' then
    select count(*) + 1 into v_round from public.ops_task_events e
     where e.task_id = p_task and e.event_type = 'stage_changed'
       and e.to_value ->> 'stage_key' = p_next;
  end if;

  update public.ops_tasks set
    stage_key = p_next,
    version = version + 1,
    updated_at = now(),
    first_draft_submitted_at = case
      when first_draft_submitted_at is null and nxt.is_review then now()
      else first_draft_submitted_at end,
    delivered_at = case when p_next = 'delivered' then coalesce(delivered_at, now())
                        else delivered_at end,
    completed_at = case when nxt.is_terminal and p_next <> 'cancelled' then coalesce(completed_at, now())
                        when not nxt.is_terminal then null
                        else completed_at end,
    /* Leaving Cancelled for a live stage is a reopening, and the stamp
       leaves with it, as completed_at does; left behind, the task went on
       reading cancelled at the stage it had been reopened to. */
    cancelled_at = case when p_next = 'cancelled' then coalesce(cancelled_at, now())
                        when not nxt.is_terminal then null
                        else cancelled_at end,
    blocked_at = case when p_next = 'blocked' then blocked_at else null end,
    blocked_category = case when p_next = 'blocked' then blocked_category else null end
  where id = p_task;

  /* The performance review brings its own checklist, the same five checks
     for a brand post and a KOC post, added once however often the task
     comes back to the stage. */
  if p_next = 'performance_review' then
    insert into public.ops_task_checklist_items (task_id, label, position, required)
    select p_task, x.label,
           coalesce((select max(c.position) from public.ops_task_checklist_items c
                      where c.task_id = p_task), 0) + x.n,
           true
      from (values (1, 'Reach and views checked'),
                   (2, 'Engagement checked (likes, comments, shares, saves)'),
                   (3, 'Comments checked for brand safety'),
                   (4, 'Leads or sales checked, where tracked'),
                   (5, 'Keep live or take down decided')) as x(n, label)
     where not exists (select 1 from public.ops_task_checklist_items c
                        where c.task_id = p_task and c.label = x.label);
  end if;

  /* A finished task is not being worked on, so every timer running on it
     stops with it, each filed as the stop it is. */
  if nxt.is_terminal then
    for ws in select * from public.ops_work_sessions
               where task_id = p_task and ended_at is null loop
      wmins := greatest(0, (extract(epoch from (now() - ws.started_at)) / 60)::integer);
      update public.ops_work_sessions set ended_at = now(), minutes = wmins where id = ws.id;
      perform public.ops_log(p_task, 'work_stopped', null,
        jsonb_build_object('session_id', ws.id, 'minutes', wmins),
        jsonb_build_object('note', 'Stopped when the task finished'));
    end loop;
  end if;

  perform public.ops_log(p_task, 'stage_changed',
    jsonb_build_object('stage_key', t.stage_key),
    jsonb_build_object('stage_key', p_next),
    (case when p_note is null then '{}'::jsonb else jsonb_build_object('note', p_note) end)
    || (case when skipping then jsonb_build_object('skip_reason', btrim(p_skip_reason)) else '{}'::jsonb end)
    || (case when v_round is not null then jsonb_build_object('round', v_round) else '{}'::jsonb end));
  if p_next = 'delivered' then
    perform public.ops_log(p_task, 'delivered', null, null, '{}'::jsonb);
  end if;
  if nxt.is_terminal and p_next <> 'cancelled' then
    perform public.ops_log(p_task, 'completed', null, null, '{}'::jsonb);
  end if;
  if p_next = 'cancelled' then
    perform public.ops_log(p_task, 'cancelled', null, null,
      jsonb_build_object('reason', p_note));
  end if;
  return public.ops_task_json(p_task);
end $$;
grant execute on function public.ops_transition_task(uuid, text, integer, text, uuid, text) to authenticated;

create or replace function public.ops_set_blocked(
  p_task uuid, p_category text, p_note text default null, p_version integer default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare t public.ops_tasks;
begin
  if (public.ops_me()).id is null then return jsonb_build_object('error', 'not-team'); end if;
  if not public.ops_may_see_task(p_task) then return jsonb_build_object('error', 'denied'); end if;
  if not public.allowed('ops', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if coalesce(p_category, '') = '' then return jsonb_build_object('error', 'category-required'); end if;
  if not public.ops_owner_may_move(p_task) then return jsonb_build_object('error', 'not-owner'); end if;

  select * into t from public.ops_tasks where id = p_task for update;
  if t.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if p_version is not null and p_version <> t.version then
    return jsonb_build_object('error', 'stale', 'task', public.ops_task_json(p_task));
  end if;

  update public.ops_tasks set
    stage_key = 'blocked', blocked_category = p_category, blocked_note = p_note,
    blocked_at = now(), version = version + 1, updated_at = now()
  where id = p_task;
  perform public.ops_log(p_task, 'blocked',
    jsonb_build_object('stage_key', t.stage_key),
    jsonb_build_object('stage_key', 'blocked'),
    jsonb_build_object('category', p_category, 'note', p_note));
  return public.ops_task_json(p_task);
end $$;
grant execute on function public.ops_set_blocked(uuid, text, text, integer) to authenticated;

-- 4. The open tasks with no owner take their creator -------------------------
/* The tasks made before this with no owner take the person who made them,
   where that person is still on the team; nothing else is touched, so a
   second run finds nothing to do. */
insert into public.ops_task_assignees (task_id, team_member_id, responsibility, assigned_by)
select t.id, t.created_by, 'owner', t.created_by
  from public.ops_tasks t
  join public.team_members tm on tm.id = t.created_by and tm.active
 where t.completed_at is null and t.cancelled_at is null
   and not exists (select 1 from public.ops_task_assignees a
                    where a.task_id = t.id and a.responsibility = 'owner' and a.ended_at is null);

-- END OF THE OWNER MOVES THE TASK -------------------------------------------

-- ===========================================================================
-- A FORMAT PER TASK — Bulk add gives each task in the month its own
-- deliverable format, so a month can be mixed.
-- 2026-09-25. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/ops.js compares the two.
--
-- WHAT THIS CHANGES, AND WHAT IT LEAVES ALONE.
--
--   `ops_generate_month` takes an optional `formats` array in its payload,
--   one entry per task in the order the tasks are made (week 1's first, then
--   on), so a month of eight can be three Reels and five graphics (the user,
--   2026-09-25: "if 8 contents, not all 8 are same deliverables"). An array
--   whose length is not the count is refused with `formats-do-not-match`; a
--   blank entry takes the run's `deliverable_type` as before. The preview
--   answers each code with its format. The month rules, the spread over weeks,
--   the codes and the publish dates are unchanged.
--
-- ROLLBACK
--   Re-run section 1 of 2026-09-25-bulk-add-from-the-month.sql.
-- ===========================================================================

create or replace function public.ops_generate_month(
  p_payload jsonb, p_dry_run boolean default false, p_idem text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m      public.team_members;
  cid    uuid;
  per    text;
  n      integer;
  weeks  integer[];
  bad    text;
  eng    uuid;
  e      public.ops_engagements;
  k      integer;
  w      integer;
  seq    integer;
  seqs   integer;
  made   jsonb := '[]'::jsonb;
  one    jsonb;
  key    text;
  scope  text;
  first_day date;
  last_off integer;
  publish timestamptz;
  fmts   text[];
  fmt    text;
begin
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if not public.allowed('ops', 'work') then return jsonb_build_object('error', 'denied'); end if;

  cid := (p_payload ->> 'client_id')::uuid;
  per := p_payload ->> 'period';
  n := coalesce((p_payload ->> 'count')::integer, 0);
  scope := coalesce(p_payload ->> 'scope', 'client');
  bad := public.ops_scope_error(scope, cid);
  if bad is not null then return jsonb_build_object('error', bad); end if;
  if per is null or per !~ '^\d{4}-\d{2}$' then return jsonb_build_object('error', 'bad-period'); end if;
  if n < 1 or n > 60 then return jsonb_build_object('error', 'bad-count'); end if;

  if (p_payload -> 'weeks') is not null and jsonb_typeof(p_payload -> 'weeks') = 'array' then
    select array_agg(x::integer) into weeks from jsonb_array_elements_text(p_payload -> 'weeks') x;
    if array_length(weeks, 1) < 1 or array_length(weeks, 1) > 5 then
      return jsonb_build_object('error', 'bad-weeks');
    end if;
    if (select sum(v) from unnest(weeks) v) <> n then return jsonb_build_object('error', 'weeks-do-not-add-up'); end if;
  else
    /* Evenly over four weeks, the extras early: task i (from 0) falls in
       week floor(i * 4 / n) + 1, so eight is two a week, six is 2, 1, 2, 1,
       and two is weeks 1 and 3 rather than both in week 4. */
    weeks := array[]::integer[];
    for w in 1 .. 4 loop
      weeks := weeks || (ceil(w * n / 4.0)::integer - ceil((w - 1) * n / 4.0)::integer);
    end loop;
  end if;

  /* A format for each task, in the order the tasks are made (week by week,
     then by number), because a month is usually mixed: three Reels and five
     graphics, not eight of one. A task given no format of its own takes the
     one for the run. */
  if (p_payload -> 'formats') is not null and jsonb_typeof(p_payload -> 'formats') = 'array' then
    select array_agg(nullif(btrim(x), '') order by i) into fmts
      from jsonb_array_elements_text(p_payload -> 'formats') with ordinality as a(x, i);
    if coalesce(array_length(fmts, 1), 0) <> n then return jsonb_build_object('error', 'formats-do-not-match'); end if;
  end if;

  /* The same press twice is one month, not two. */
  if not p_dry_run and p_idem is not null then
    if exists (select 1 from public.ops_tasks where idem_key = 'month:' || p_idem || ':1') then
      return jsonb_build_object('error', 'already-generated');
    end if;
  end if;

  first_day := (per || '-01')::date;
  last_off := ((first_day + interval '1 month')::date - first_day) - 1;
  /* One lock for the whole run, taken before anything is read: two operators
     generating the same month queue here, so the second sees the first's
     engagement and the first's numbers rather than racing both. */
  perform pg_advisory_xact_lock(hashtext('ops_code:' || cid::text || ':' || per));
  /* The month must already exist on the client's Work pane, still be open,
     and have its content meeting confirmed: a month nobody planned holds no
     tasks. Asked on the preview as well as the run, so the sheet cannot
     show codes for a month the run would refuse. */
  select * into e from public.ops_engagements
   where client_id = cid and period = per;
  if e.id is null then return jsonb_build_object('error', 'no-month'); end if;
  if (p_payload ->> 'engagement_id') is not null and (p_payload ->> 'engagement_id')::uuid <> e.id then
    return jsonb_build_object('error', 'no-month');
  end if;
  if e.status in ('completed', 'cancelled') then return jsonb_build_object('error', 'month-closed'); end if;
  if e.meeting_at is null and not e.meeting_na then
    return jsonb_build_object('error', 'month-not-confirmed');
  end if;
  eng := e.id;
  if not p_dry_run then
    update public.ops_engagements set planned_count = greatest(planned_count, n), updated_at = now()
     where id = eng and planned_count < n;
  end if;

  /* One lock for the whole month, so the preview and the run see the same
     next number and two operators generating for one client queue. */
  seq := public.ops_next_seq(cid, per) - 1;
  seqs := 0;
  for w in 1 .. array_length(weeks, 1) loop
    for k in 1 .. coalesce(weeks[w], 0) loop
      seq := seq + 1;
      seqs := seqs + 1;
      /* A tentative date inside the task's own week, the week's tasks
         spread across its seven days, so the calendar has somewhere to put
         each one; the content meeting fixes the real date. Never past the
         month's last day, which only a fifth week can reach. */
      fmt := coalesce(fmts[seqs], nullif(p_payload ->> 'deliverable_type', ''));
      publish := (first_day + least((w - 1) * 7 + ((k - 1) * 7) / weeks[w], last_off))::timestamptz;
      if p_dry_run then
        made := made || jsonb_build_object('code', public.ops_code_of(per, w, seq), 'week', w, 'seq', seq, 'format', fmt);
      else
        key := case when p_idem is null then null else 'month:' || p_idem || ':' || seqs::text end;
        one := public.ops_create_task(jsonb_build_object(
          'scope', scope, 'client_id', cid, 'engagement_id', eng,
          'task_type', coalesce(p_payload ->> 'task_type', 'engagement'),
          'deliverable_type', fmt,
          'priority_level', (p_payload ->> 'priority_level')::integer,
          'complexity', p_payload ->> 'complexity',
          'owner_id', (p_payload ->> 'owner_id')::uuid,
          'manager_id', (p_payload ->> 'manager_id')::uuid,
          'code_period', per, 'code_week', w,
          'publish_at', publish), key);
        if one ? 'error' then return one; end if;
        made := made || jsonb_build_object('id', one ->> 'id', 'code', one ->> 'code', 'week', w, 'seq', seq, 'format', fmt);
      end if;
    end loop;
  end loop;
  return jsonb_build_object('engagement_id', eng, 'period', per, 'count', seqs,
                            'tasks', made, 'dry_run', p_dry_run);
end $$;
grant execute on function public.ops_generate_month(jsonb, boolean, text) to authenticated;

-- END OF A FORMAT PER TASK ------------------------------------------------

-- ===========================================================================
-- EVERY TASK IN A CONFIRMED MONTH — a client's deliverable, made one at a
-- time or by a repeat rule, goes only into a month the team has planned; and
-- the client portal reads the month's content meetings.
-- 2026-09-25. Safe to run twice. Rollback at the foot. Run after
-- 2026-09-25-a-format-per-task.sql. Mirrored byte for byte in
-- supabase/schema.sql under the same banner; tests/ops.js compares the two.
--
-- WHAT THIS CHANGES, AND WHAT IT LEAVES ALONE.
--
--   1. `ops_create_task` refuses a client's content deliverable for a month
--      that does not exist (`no-month`), is completed or cancelled
--      (`month-closed`), or has no content meeting set or marked not
--      applicable (`month-not-confirmed`), and joins the task to that month.
--      These are Bulk add's refusals, so New task, From template and
--      Duplicate now answer the same way (the user, 2026-09-25: "Go").
--      An everyday task, an internal task and a lead's task are unchanged.
--
--   2. `ops_generate_recurring` holds a client's repeat rule until the
--      client's month is confirmed, counts it as `held`, and makes nothing
--      for it; a later run makes the tasks. Internal rules are unchanged.
--
--   3. `portal_meetings(client)` lets a signed-in client contact read the
--      client's content meetings (month, date and time, length, channel, and
--      the link while the meeting is ahead). Never a task, a check or a note.
--
-- ROLLBACK
--   Re-run the ops_create_task definition in
--   2026-09-25-the-owner-moves-the-task.sql and the ops_generate_recurring
--   definition in 2026-09-23-operations-phase4.sql, then
--   drop function if exists public.portal_meetings(uuid);
-- ===========================================================================

-- 1. A client's deliverable goes into a confirmed month ----------------------
create or replace function public.ops_create_task(p_payload jsonb, p_idem text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m     public.team_members;
  tpl   public.ops_task_templates;
  wf    uuid;
  tid   uuid;
  owner uuid;
  publish timestamptz;
  fd    timestamptz;
  fin   timestamptz;
  item  jsonb;
  i     integer := 0;
  scope text;
  ttype text;
  cid   uuid;
  bad   text;
  descr text;
  period text;
  cper  text;
  week  integer;
  seq   integer;
  code  text;
  title text;
  first_stage text;
  wkey  text;
  base  timestamptz;
  eng   public.ops_engagements;
begin
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if not public.allowed('ops', 'work') then return jsonb_build_object('error', 'denied'); end if;

  -- The same press twice is one task.
  if p_idem is not null then
    select id into tid from public.ops_tasks where idem_key = p_idem;
    if tid is not null then return public.ops_task_json(tid); end if;
  end if;

  scope := coalesce(p_payload ->> 'scope', 'client');
  cid := (p_payload ->> 'client_id')::uuid;
  /* A task linked to a month's engagement takes the client from it: the
     person names the month once and the client comes with it. */
  if (p_payload ->> 'engagement_id') is not null then
    select * into eng from public.ops_engagements where id = (p_payload ->> 'engagement_id')::uuid;
    if eng.id is null then return jsonb_build_object('error', 'not-found'); end if;
    if cid is null then cid := eng.client_id; scope := 'client'; end if;
  end if;
  bad := public.ops_scope_error(scope, cid);
  if bad is not null then return jsonb_build_object('error', bad); end if;

  ttype := coalesce(p_payload ->> 'task_type', 'adhoc');
  if ttype not in ('engagement', 'adhoc', 'goodwill', 'special') then
    return jsonb_build_object('error', 'bad-task-type');
  end if;

  /* The description is the team's to edit and may start blank on a task that
     carries a code; a task with no code is named by its description alone, so
     there it is required. `title` is accepted from older callers as the
     description. */
  descr := nullif(btrim(coalesce(p_payload ->> 'content_desc', p_payload ->> 'title', '')), '');

  if (p_payload ->> 'template_id') is not null then
    select * into tpl from public.ops_task_templates
     where id = (p_payload ->> 'template_id')::uuid;
    descr := coalesce(descr, nullif(btrim(coalesce(tpl.default_title, tpl.name, '')), ''));
  end if;
  /* New work goes on the content workflow. A caller may still name another
     (a template's own, or one somebody adds), and a task already on a retired
     workflow is never moved. */
  wf := coalesce((p_payload ->> 'workflow_id')::uuid,
                 (select id from public.ops_workflows where key = p_payload ->> 'workflow_key' and active),
                 tpl.workflow_id,
                 (select id from public.ops_workflows where key = 'content' and active),
                 (select id from public.ops_workflows where active order by created_at limit 1));
  if wf is null then return jsonb_build_object('error', 'workflow-required'); end if;
  select key into first_stage from public.ops_workflow_stages
   where workflow_id = wf order by position limit 1;
  select key into wkey from public.ops_workflows where id = wf;

  publish := (p_payload ->> 'publish_at')::timestamptz;
  fd := coalesce((p_payload ->> 'first_draft_due_at')::timestamptz,
        case when publish is not null and tpl.first_draft_offset_business_days is not null
             then public.ops_add_business_days(publish, -tpl.first_draft_offset_business_days)
             when tpl.first_draft_offset_business_days is not null
             then public.ops_add_business_days(now(), tpl.first_draft_offset_business_days)
        end);
  /* A template's due date is a number of calendar days from the day the
     work is made for (the base date the caller names, else today). */
  base := coalesce((p_payload ->> 'base_date')::timestamptz, now());
  fin := coalesce((p_payload ->> 'final_due_at')::timestamptz,
        case when tpl.due_offset_days is not null
             then date_trunc('day', base) + make_interval(days => tpl.due_offset_days)
             when publish is not null and tpl.final_offset_business_days is not null
             then public.ops_add_business_days(publish, -tpl.final_offset_business_days)
             when tpl.final_offset_business_days is not null
             then public.ops_add_business_days(now(), tpl.final_offset_business_days)
        end);
  if fd is not null and fin is not null and not public.ops_due_order_ok(fd, fin) then
    return jsonb_build_object('error', 'draft-not-before-final');
  end if;

  /* The name. The month is the content month (the scheduled publish date's,
     else the one the caller names, else this one); the week is the planned
     publishing week, chosen by the caller and prefilled by the page from the
     date; the running number is the client's for the month. Generated once,
     under the lock, and never rewritten: a publish date that moves later
     leaves the name as it was, because the name is a label and not a fact
     about the date. */
  if wkey = 'task' then
    /* An everyday task is named by what it is. It carries no content code,
       because the code numbers a client's deliverables for the month and a
       task is not one; the content month is kept where it is known, so the
       task can be grouped with the month it belongs to. */
    if descr is null then return jsonb_build_object('error', 'title-required'); end if;
    title := descr;
    period := coalesce(nullif(p_payload ->> 'code_period', ''), eng.period);
  elsif scope <> 'internal' then
    period := coalesce(nullif(p_payload ->> 'code_period', ''),
                       case when publish is not null then to_char(publish, 'YYYY-MM') end,
                       to_char(now(), 'YYYY-MM'));
    if period !~ '^\d{4}-\d{2}$' then return jsonb_build_object('error', 'bad-period'); end if;
    /* A client's deliverable belongs to a month the team has planned: one
       that exists, is still open, and has its content meeting set or marked
       not applicable. The same three refusals Bulk add gives. */
    if scope = 'client' then
      cper := period;
      if eng.id is null or eng.period <> cper then
        select * into eng from public.ops_engagements x where x.client_id = cid and x.period = cper;
      end if;
      if eng.id is null then return jsonb_build_object('error', 'no-month'); end if;
      if eng.status in ('completed', 'cancelled') then return jsonb_build_object('error', 'month-closed'); end if;
      if eng.meeting_at is null and not eng.meeting_na then
        return jsonb_build_object('error', 'month-not-confirmed');
      end if;
    end if;
    week := coalesce((p_payload ->> 'code_week')::integer,
                     case when publish is not null
                          then least(5, ((extract(day from publish)::integer - 1) / 7) + 1) end,
                     1);
    if week < 1 or week > 5 then return jsonb_build_object('error', 'bad-week'); end if;
    seq := public.ops_next_seq(cid, period);
    code := public.ops_code_of(period, week, seq);
    title := btrim(code || ' ' || coalesce(descr, ''));
  else
    if descr is null then return jsonb_build_object('error', 'title-required'); end if;
    title := descr;
  end if;

  insert into public.ops_tasks (
    scope, client_id, campaign_id, batch_id, source_type, source_id, template_id,
    workflow_id, stage_key, title, description, remarks, deliverable_type,
    language_codes, priority_level, complexity, estimate_minutes, publish_at,
    original_first_draft_due_at, current_first_draft_due_at,
    original_final_due_at, current_final_due_at, created_by, idem_key,
    legacy_source, legacy_key, data_quality,
    task_type, code, code_period, code_week, code_seq, content_desc,
    engagement_id, manager_id, parent_task_id)
  values (
    scope, cid,
    (p_payload ->> 'campaign_id')::uuid,
    (p_payload ->> 'batch_id')::uuid,
    p_payload ->> 'source_type',
    (p_payload ->> 'source_id')::uuid,
    tpl.id, wf, coalesce(first_stage, 'intake'),
    title, p_payload ->> 'description', p_payload ->> 'remarks',
    coalesce(p_payload ->> 'deliverable_type', tpl.deliverable_type, 'other'),
    coalesce((select array_agg(x) from jsonb_array_elements_text(
               coalesce(p_payload -> 'language_codes', '[]'::jsonb)) x), '{}'),
    coalesce((p_payload ->> 'priority_level')::smallint, 3),
    coalesce(p_payload ->> 'complexity', tpl.default_complexity),
    coalesce((p_payload ->> 'estimate_minutes')::integer, tpl.default_estimate_minutes),
    publish, fd, fd, fin, fin, m.id, p_idem,
    p_payload ->> 'legacy_source', p_payload ->> 'legacy_key',
    coalesce(p_payload ->> 'data_quality', 'complete'),
    ttype, code, period, week, seq, descr,
    coalesce(eng.id, (p_payload ->> 'engagement_id')::uuid),
    coalesce((p_payload ->> 'manager_id')::uuid, m.id),
    (p_payload ->> 'parent_task_id')::uuid)
  returning id into tid;

  /* Every task has an owner from the moment it exists: the one named, the
     template's, or else whoever made it. */
  owner := coalesce((p_payload ->> 'owner_id')::uuid, tpl.default_owner_id, m.id);
  if owner is not null then
    insert into public.ops_task_assignees (task_id, team_member_id, responsibility, assigned_by)
    values (tid, owner, 'owner', m.id);
    perform public.ops_log(tid, 'assignment_changed', null,
      jsonb_build_object('owner_id', owner), '{}'::jsonb);
  end if;
  if (p_payload ->> 'reviewer_id') is not null then
    insert into public.ops_task_assignees (task_id, team_member_id, responsibility, assigned_by)
    values (tid, (p_payload ->> 'reviewer_id')::uuid, 'reviewer', m.id);
  end if;

  -- The template's checklist, or the one the caller hands over (a duplicate
  -- carries its source's labels, unticked), in the order stated.
  for item in select * from jsonb_array_elements(
      coalesce(p_payload -> 'checklist', tpl.checklist, '[]'::jsonb)) loop
    i := i + 1;
    insert into public.ops_task_checklist_items (task_id, label, position)
    values (tid, item #>> '{}', i);
  end loop;

  if (p_payload -> 'video') is not null then
    insert into public.ops_video_details (
      task_id, output_duration_seconds, footage_duration_seconds,
      subtitle_required, motion_graphics_required, aspect_ratios,
      script_ready, footage_ready, shoot_required, shoot_at, variant_count)
    values (tid,
      ((p_payload -> 'video') ->> 'output_duration_seconds')::integer,
      ((p_payload -> 'video') ->> 'footage_duration_seconds')::integer,
      coalesce(((p_payload -> 'video') ->> 'subtitle_required')::boolean, false),
      coalesce(((p_payload -> 'video') ->> 'motion_graphics_required')::boolean, false),
      coalesce((select array_agg(x) from jsonb_array_elements_text(
                 coalesce((p_payload -> 'video') -> 'aspect_ratios', '[]'::jsonb)) x), '{}'),
      ((p_payload -> 'video') ->> 'script_ready')::boolean,
      ((p_payload -> 'video') ->> 'footage_ready')::boolean,
      coalesce(((p_payload -> 'video') ->> 'shoot_required')::boolean, false),
      ((p_payload -> 'video') ->> 'shoot_at')::timestamptz,
      coalesce(((p_payload -> 'video') ->> 'variant_count')::integer, 1));
  end if;

  perform public.ops_log(tid, 'task_created', null,
    jsonb_build_object('title', title, 'code', code,
                       'first_draft_due_at', fd, 'final_due_at', fin),
    case when (p_payload ->> 'duplicated_from') is null then '{}'::jsonb
         else jsonb_build_object('duplicated_from', p_payload ->> 'duplicated_from') end);
  return public.ops_task_json(tid);
end $$;
grant execute on function public.ops_create_task(jsonb, text) to authenticated;

-- 2. A client's repeats wait for the month --------------------------------
create or replace function public.ops_generate_recurring(
  p_period text, p_rules uuid[] default null, p_idem text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m     public.team_members;
  r     public.ops_recurring_rules;
  src   public.ops_tasks;
  made  integer := 0;
  skip  integer := 0;
  key   text;
  first_day date;
  last_day date;
  anchor date;
  d     date;
  stepd integer;
  one   jsonb;
  wk    integer;
  held  integer := 0;
  ccl   uuid;
  mon   public.ops_engagements;
begin
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if not public.allowed('ops', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if p_period !~ '^\d{4}-\d{2}$' then return jsonb_build_object('error', 'bad-period'); end if;
  first_day := (p_period || '-01')::date;
  last_day := (first_day + interval '1 month' - interval '1 day')::date;

  for r in select * from public.ops_recurring_rules
            where active and (p_rules is null or id = any (p_rules))
              and (source_task_id is null or public.ops_may_see_task(source_task_id)) loop
    if r.source_task_id is not null then
      select * into src from public.ops_tasks where id = r.source_task_id;
    else
      src := null;
    end if;

    /* A client's repeats wait for the client's month: one that exists, is
       open and has its content meeting set or marked not applicable. Until
       then the rule is held and counted, and a later run makes them. */
    ccl := case when src.id is not null then case when src.scope = 'client' then src.client_id end
                else r.client_id end;
    mon := null;
    if ccl is not null then
      select * into mon from public.ops_engagements x where x.client_id = ccl and x.period = p_period;
      if mon.id is null or mon.status in ('completed', 'cancelled')
         or (mon.meeting_at is null and not mon.meeting_na) then
        held := held + 1;
        continue;
      end if;
    end if;

    /* The dates this rule falls on inside the month. */
    if r.frequency = 'monthly' then
      d := first_day + (least(coalesce(r.day_of_month,
              case when src.publish_at is not null then extract(day from src.publish_at)::integer else 1 end),
              extract(day from last_day)::integer) - 1);
      stepd := null;
    else
      stepd := case when r.frequency = 'weekly' then 7 else greatest(1, coalesce(r.interval_days, 7)) end;
      anchor := coalesce(src.publish_at::date, r.created_at::date, first_day);
      if anchor > first_day then d := anchor;
      else d := anchor + ((((first_day - anchor) + stepd - 1) / stepd) * stepd); end if;
    end if;

    while d is not null and d <= last_day loop
      if d >= first_day
         and (r.ends_on is null or d <= r.ends_on)
         and (r.max_count is null or r.generated_count < r.max_count) then
        key := 'recur:' || r.id::text || ':' || to_char(d, 'YYYY-MM-DD');
        if exists (select 1 from public.ops_tasks where idem_key = key) then
          skip := skip + 1;
        else
          wk := coalesce(r.code_week, least(5, ((extract(day from d)::integer - 1) / 7) + 1));
          if src.id is not null then
            one := public.ops_duplicate_task(src.id, jsonb_build_object(
              'keep_desc', true, 'copy_dates', false, 'copy_assignees', true,
              'publish_at', d::timestamptz, 'code_period', p_period, 'code_week', wk,
              'engagement_id', mon.id), key);
          else
            one := public.ops_create_task(jsonb_build_object(
              'scope', case when r.client_id is null then 'internal' else 'client' end,
              'client_id', r.client_id, 'template_id', r.template_id,
              'title', r.name || ' — ' || p_period, 'content_desc', r.name,
              'owner_id', r.owner_id, 'publish_at', d::timestamptz,
              'code_period', p_period, 'code_week', wk, 'engagement_id', mon.id), key);
          end if;
          if one ? 'error' then return one || jsonb_build_object('rule', r.id); end if;
          made := made + 1;
          update public.ops_recurring_rules
             set generated_count = generated_count + 1, last_generated_period = p_period, updated_at = now()
           where id = r.id;
          r.generated_count := r.generated_count + 1;
        end if;
      end if;
      exit when stepd is null;
      d := d + stepd;
    end loop;
  end loop;
  return jsonb_build_object('created', made, 'skipped', skip, 'held', held, 'period', p_period);
end $$;
grant execute on function public.ops_generate_recurring(text, uuid[], text) to authenticated;

-- 3. The client reads the meeting schedule ---------------------------------
create or replace function public.portal_meetings(p_client uuid)
returns jsonb
language plpgsql security definer stable set search_path = public as $$
begin
  if auth.jwt() ->> 'email' is null then return jsonb_build_object('error', 'not-signed-in'); end if;
  if p_client is null or p_client not in (select public.portal_clients()) then
    return jsonb_build_object('error', 'no-access');
  end if;
  /* The content meetings the team has put in the diary, from three months
     back. Nothing about the month's tasks, checks or status beyond this: a
     client reads when we meet, never how the work inside the month is going.
     The link is sent only while the meeting is still ahead. */
  return jsonb_build_object('meetings', coalesce((
    select jsonb_agg(jsonb_build_object(
             'period', e.period, 'at', e.meeting_at, 'minutes', coalesce(e.meeting_minutes, 30),
             'channel', e.meeting_channel,
             'link', case when e.meeting_at + make_interval(mins => coalesce(e.meeting_minutes, 30)) > now()
                          then e.meeting_link end)
           order by e.meeting_at desc)
      from public.ops_engagements e
     where e.client_id = p_client
       and e.meeting_at is not null
       and not coalesce(e.meeting_na, false)
       and e.status <> 'cancelled'
       and e.meeting_at >= date_trunc('month', now()) - interval '3 months'), '[]'::jsonb));
end $$;
revoke all on function public.portal_meetings(uuid) from public, anon;
grant execute on function public.portal_meetings(uuid) to authenticated;
-- END OF EVERY TASK IN A CONFIRMED MONTH ------------------------------------
-- ===========================================================================
-- THE CAMPAIGN CLOCK — when a campaign moved, and when each booking finished.
-- 2026-09-26. Safe to run twice. Rollback at the foot. Mirrored in
-- supabase/schema.sql under the same banner.
--
-- Asked for by the user: an internal timing under Key dates, from created
-- through confirmed and in production to completed, each stage's hours. The
-- page reads it; nothing client-facing sends it.
--
--   1. `campaigns.state_log`: every state the campaign has been in, with when,
--      stamped by a trigger on the move, never by a page. A new campaign
--      starts with its first state at its creation time. Campaigns that
--      existed before this have no log of their past moves: the page omits
--      a stage it cannot date rather than guessing.
--
--   2. `campaign_options.completed_at`: stamped when a booking reaches
--      Completed and cleared if it is reverted, so a campaign is complete at
--      the moment its last booking was.
--
-- ROLLBACK
--   drop trigger if exists campaigns_state_clock on public.campaigns;
--   drop function if exists public.campaigns_state_clock();
--   drop trigger if exists campaign_options_done_clock on public.campaign_options;
--   drop function if exists public.campaign_options_done_clock();
--   alter table public.campaigns drop column if exists state_log;
--   alter table public.campaign_options drop column if exists completed_at;
-- ===========================================================================

alter table public.campaigns add column if not exists state_log jsonb not null default '[]'::jsonb;

create or replace function public.campaigns_state_clock()
returns trigger
language plpgsql
as $$
begin
  if tg_op = 'INSERT' then
    if new.state_log is null or jsonb_array_length(new.state_log) = 0 then
      new.state_log := jsonb_build_array(
        jsonb_build_object('state', new.state, 'at', coalesce(new.created_at, now())));
    end if;
    return new;
  end if;
  if new.state is distinct from old.state then
    new.state_log := coalesce(old.state_log, '[]'::jsonb) ||
      jsonb_build_array(jsonb_build_object('state', new.state, 'at', now()));
  end if;
  return new;
end $$;

drop trigger if exists campaigns_state_clock on public.campaigns;
create trigger campaigns_state_clock before insert or update on public.campaigns
  for each row execute function public.campaigns_state_clock();

alter table public.campaign_options add column if not exists completed_at timestamptz;

create or replace function public.campaign_options_done_clock()
returns trigger
language plpgsql
as $$
begin
  if new.state = 'completed' then
    if tg_op = 'INSERT' or old.state is distinct from 'completed' then
      new.completed_at := now();
    end if;
  else
    new.completed_at := null;
  end if;
  return new;
end $$;

drop trigger if exists campaign_options_done_clock on public.campaign_options;
create trigger campaign_options_done_clock before insert or update on public.campaign_options
  for each row execute function public.campaign_options_done_clock();
-- END OF THE CAMPAIGN CLOCK -------------------------------------------------

-- ===========================================================================
-- DEPARTMENT AND ROLE ON THE TEAM — who a colleague is is kept where the
-- team keeps them, and Performance reads it from there.
-- 2026-09-26. Safe to run twice. Run after 2026-09-24-performance-code-always.sql.
-- Rollback at the foot. Mirrored byte for byte in supabase/schema.sql under
-- the same banner; tests/perf.js compares the two.
--
-- WHAT CHANGED. The user, on 2026-09-26: department and role are changed on
-- the Team page for each member and carried over to Performance. They were
-- kept on perf_people behind both performance locks, so a department was
-- typed into the designation on the Team page ("Creative, Production
-- Executive") and set again on the review sheet. `team_members` gains
-- `department` and `role_family` (the role standard); perf_json and
-- perf_month read them from the team row, and perf_profile_set keeps only
-- the two review settings (runs client ads, reviewed every month). The Team
-- page writes the columns under the policy that already governs that row.
--
-- THE DATA, ONCE. (1) Each colleague's department and role standard move
-- from perf_people to the team row where the team row has none, and are
-- cleared on perf_people, so a later run cannot put back a value somebody
-- has since cleared on the Team page. (2) A designation typed as a
-- department, a comma and a position ("Creative, Production Executive")
-- becomes the department Creative and the position Production Executive,
-- where the row has no department yet or names the same one; any other
-- designation is left as typed. The last statement lists every colleague
-- holding a department or a role afterwards.
--
-- ROLLBACK
--   update public.perf_people pp set department = t.department, role_family = t.role_family
--     from public.team_members t where t.id = pp.team_member_id;
--   then re-run perf_json, perf_month and perf_profile_set from
--   2026-09-24-performance-reviews.sql. The columns on team_members may stay.
--   A split designation is not put back by itself: the list at the foot of
--   the first run names who had one.
-- ===========================================================================

alter table public.team_members add column if not exists department text;
alter table public.team_members add column if not exists role_family text;
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'team_members_department_check') then
    alter table public.team_members add constraint team_members_department_check
      check (department in ('creative', 'marketing'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'team_members_role_family_check') then
    alter table public.team_members add constraint team_members_role_family_check
      check (role_family in ('visual', 'video', 'planner', 'account'));
  end if;
end $$;

/* (1) What the review sheet held moves to the team row, once. */
update public.team_members t
   set department = coalesce(t.department, pp.department),
       role_family = coalesce(t.role_family, pp.role_family)
  from public.perf_people pp
 where pp.team_member_id = t.id
   and (pp.department is not null or pp.role_family is not null);
update public.perf_people set department = null, role_family = null
 where department is not null or role_family is not null;

/* (2) "Creative, Production Executive" is a department and a position. */
update public.team_members t
   set department = lower(s.parts[1]), designation = btrim(s.parts[2])
  from (select id, regexp_match(designation, '^\s*(creative|marketing)\s*,\s*(\S.*)$', 'i') as parts
          from public.team_members) s
 where s.id = t.id and s.parts is not null
   and (t.department is null or t.department = lower(s.parts[1]));

/* Performance reads the team row. */
create or replace function public.perf_json(r public.perf_reviews, p_full boolean)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare m public.team_members; pp public.perf_people; out jsonb;
begin
  select * into m from public.team_members where id = r.team_member_id;
  select * into pp from public.perf_people where team_member_id = r.team_member_id;
  out := jsonb_build_object(
    'id', r.id, 'team_member_id', r.team_member_id, 'period', r.period,
    'month', public.perf_month_word(r.period), 'status', r.status,
    'member', jsonb_build_object('name', m.name, 'staff_code', m.staff_code,
      'designation', m.designation, 'department', m.department,
      'role_family', m.role_family, 'runs_ads', coalesce(pp.runs_ads, false)),
    'scores', jsonb_build_object('output', r.s_output, 'accuracy', r.s_accuracy,
      'delivery', r.s_delivery, 'client', r.s_client, 'comms', r.s_comms,
      'initiative', r.s_initiative),
    'rates', jsonb_build_object('posting', r.r_posting, 'timeline', r.r_timeline,
      'satisfaction', r.r_satisfaction, 'pacing', r.r_pacing, 'sla', r.r_sla),
    'notes', r.notes, 'improvement', r.improvement, 'review_by', r.review_by,
    'reward_step', r.reward_step, 'serial', r.serial,
    'reviewer', (select name from public.team_members where id = r.reviewer_id),
    'released_at', r.released_at, 'dispute_until', r.dispute_until,
    'dispute_open', r.status = 'released' and r.dispute_until > now()
                    and not exists (select 1 from public.perf_disputes d
                                     where d.review_id = r.id and d.version = r.version),
    'acknowledged_at', r.acknowledged_at, 'finalised_at', r.finalised_at,
    'finalised_by', (select name from public.team_members where id = r.finalised_by),
    'version', r.version, 'rev', r.rev,
    'result', public.perf_calc(r),
    'breaches', public.perf_breaches_json(r.team_member_id, r.period, false),
    'disputes', coalesce((select jsonb_agg(jsonb_build_object(
        'id', d.id, 'item', d.item, 'breach_id', d.breach_id, 'reason', d.reason,
        'breach_what', (select b.what from public.perf_breaches b where b.id = d.breach_id),
        'raised_at', d.raised_at, 'decision', d.decision, 'response', d.response,
        'before_value', d.before_value, 'after_value', d.after_value,
        'decided_by', (select name from public.team_members where id = d.decided_by),
        'decided_at', d.decided_at) order by d.raised_at)
        from public.perf_disputes d where d.review_id = r.id and d.version = r.version), '[]'::jsonb));
  if p_full then
    out := out || jsonb_build_object(
      'voided', (select coalesce(jsonb_agg(x), '[]'::jsonb)
                   from jsonb_array_elements(public.perf_breaches_json(r.team_member_id, r.period, true)) x
                  where x ->> 'voided_at' is not null),
      'ops', public.perf_ops_rate(r.team_member_id, r.period),
      'events', coalesce((select jsonb_agg(jsonb_build_object(
          'kind', e.kind, 'detail', e.detail, 'at', e.created_at,
          'by', coalesce((select name from public.team_members where id = e.actor_id), e.actor_email))
          order by e.created_at desc)
          from public.perf_events e where e.review_id = r.id), '[]'::jsonb));
  end if;
  return out;
end $$;

create or replace function public.perf_month(p_token text, p_period date)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare err text; m public.team_members; p date := date_trunc('month', p_period)::date;
begin
  err := public.perf_check(p_token, 'view');
  if err is not null then return jsonb_build_object('error', err); end if;
  m := public.ops_me();
  return jsonb_build_object(
    'period', p, 'month', public.perf_month_word(p),
    'people', coalesce((select jsonb_agg(x order by x ->> 'name') from (
      select jsonb_build_object(
        'team_member_id', t.id, 'name', t.name, 'staff_code', t.staff_code,
        'designation', t.designation,
        'department', t.department, 'role_family', t.role_family,
        'runs_ads', coalesce(pp.runs_ads, false),
        'reviewed', public.perf_reviewed(t.id),
        'breaches', (select count(*) from public.perf_breaches b
                      where b.team_member_id = t.id and b.period = p and b.voided_at is null),
        'review', case when r.id is null then null else jsonb_build_object(
          'id', r.id, 'status', r.status, 'result', public.perf_calc(r),
          'open_disputes', (select count(*) from public.perf_disputes d
                             where d.review_id = r.id and d.version = r.version and d.decision is null),
          'dispute_until', r.dispute_until) end) as x
        from public.team_members t
        left join public.perf_people pp on pp.team_member_id = t.id
        left join public.perf_reviews r on r.team_member_id = t.id and r.period = p
       where t.active and t.id <> m.id) q), '[]'::jsonb));
end $$;

create or replace function public.perf_profile_set(p_token text, p_member uuid, p_payload jsonb)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare err text; m public.team_members; kept jsonb;
begin
  err := public.perf_check(p_token, 'work');
  if err is not null then return jsonb_build_object('error', err); end if;
  m := public.ops_me();
  if p_member = m.id then return jsonb_build_object('error', 'own-review'); end if;
  /* Department and role are the Team page's now. A page from before this
     change may still send them; they are left out rather than refused, so
     its two ticks still save. */
  kept := coalesce(p_payload, '{}'::jsonb) - 'department' - 'role_family';
  insert into public.perf_people (team_member_id, runs_ads, reviewed)
  values (p_member, coalesce((kept ->> 'runs_ads')::boolean, false),
          case when kept ? 'reviewed' then (kept ->> 'reviewed')::boolean end)
  on conflict (team_member_id) do update set
    runs_ads = case when kept ? 'runs_ads' then coalesce((kept ->> 'runs_ads')::boolean, false) else perf_people.runs_ads end,
    reviewed = case when kept ? 'reviewed' then (kept ->> 'reviewed')::boolean else perf_people.reviewed end,
    updated_at = now();
  perform public.perf_log(null, p_member, 'profile', kept);
  return jsonb_build_object('ok', true);
end $$;

select name, department, role_family, designation from public.team_members
 where department is not null or role_family is not null order by name;

-- END OF DEPARTMENT AND ROLE ON THE TEAM -------------------------------------

-- ===========================================================================
-- PERFORMANCE RECORDS, THEIR TRAIL AND THEIR CHECK — a downloaded record is
-- stamped, listed in Documents and answered by the verify page, and the
-- Activity record reads its steps.
-- 2026-09-26. Safe to run twice. Run after
-- 2026-09-26-department-and-role-on-the-team.sql. Rollback at the foot.
-- Mirrored byte for byte in supabase/schema.sql under the same banner;
-- tests/perf.js compares the two.
--
-- WHAT CHANGED, the user's decisions of 2026-09-26:
--  1. A download is filed before the file is drawn and the filing is what the
--     file prints (perf_printed answers the server's time, who, and the
--     record's released, acknowledged and finalised steps). The PDF carries
--     no signature lines; acknowledgement is the portal's.
--  2. A score save names what it changed (perf_save files each scorecard and
--     rate from and to, then the notes or the plan), and a save that changed
--     nothing is not filed.
--  3. The Activity record reads the steps of reviews (perf_activity): when,
--     the step, whose month, who. Never a score, a grade, a breach or a
--     dispute's words. For team.performance at View, without the master
--     code; the caller's own review is left out.
--  4. A record downloaded at least once is listed under HR Letters in
--     Documents (perf_register) for somebody holding both register.hr and
--     team.performance at View, the caller's own left out, with its
--     reference, colleague and month and nothing of its content.
--  5. The verify page answers a downloaded record's reference as an HR
--     Letter, Valid (Replaced while it is reopened as a draft), dated by its
--     release; never the name or the score. Every reference is also found
--     typed with dashes for slashes, the way a file name carries it.
--  6. My performance accepts a fresh passkey (Face ID, Touch ID) as well as a
--     fresh emailed code: perf_code_fresh reads either in the signed token.
--  7. The review list is chosen: a colleague with no setting is off it. The
--     people the old default reviewed are written onto it by name, once.
--
-- ROLLBACK
--   drop function if exists public.perf_activity(integer), public.perf_register();
--   and re-run perf_save and perf_printed from
--   2026-09-24-performance-reviews.sql, perf_code_fresh from
--   2026-09-24-performance-email-code.sql, and verify_serial from
--   supabase/schema.sql's Documents Register section, and perf_reviewed from
--   2026-09-24-performance-reviews.sql. A stamped event keeps its detail and a
--   written review setting stays; nothing is lost by the rollback.
-- ===========================================================================

/* 1. The download, filed first. */
/* A download is filed before the file is drawn, and the filing is what the
   file prints: the server's time, who took it, and the steps the record has
   been through (released, acknowledged, finalised), each by name, address
   and time. A refused filing is a refused file. */
create or replace function public.perf_printed(p_review uuid, p_token text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare m public.team_members; r public.perf_reviews; ev_id uuid; ev_at timestamptz;
begin
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'not-team'); end if;
  select * into r from public.perf_reviews where id = p_review;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if r.team_member_id <> m.id and public.perf_check(p_token, 'view') is not null then
    return jsonb_build_object('error', 'denied');
  end if;
  if r.team_member_id = m.id and r.status = 'draft' then return jsonb_build_object('error', 'not-found'); end if;
  insert into public.perf_events (review_id, team_member_id, actor_id, actor_email, kind, detail)
  values (r.id, r.team_member_id, m.id, m.email, 'printed', jsonb_build_object('version', r.version))
  returning id, created_at into ev_id, ev_at;
  return jsonb_build_object('ok', true, 'id', ev_id, 'at', ev_at, 'by', m.name, 'email', m.email,
    'trail', coalesce((
      select jsonb_agg(jsonb_build_object('kind', t.kind, 'at', t.created_at, 'by', t.who, 'email', t.actor_email)
                       order by t.created_at)
        from (select distinct on (pe.kind) pe.kind, pe.created_at, pe.actor_email,
                     coalesce(tm.name, pe.actor_email) as who
                from public.perf_events pe
                left join public.team_members tm on tm.id = pe.actor_id
               where pe.review_id = r.id
                 and ((pe.kind = 'released' and r.released_at is not null)
                   or (pe.kind = 'acknowledged' and r.acknowledged_at is not null)
                   or (pe.kind = 'finalised' and r.finalised_at is not null))
               order by pe.kind, pe.created_at desc) t), '[]'::jsonb));
end $$;

/* 2. A save names what it changed. */
create or replace function public.perf_save(p_token text, p_member uuid, p_period date,
                                            p_payload jsonb, p_rev integer)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  err text; m public.team_members; r public.perf_reviews; p date := date_trunc('month', p_period)::date;
  sc jsonb := coalesce(p_payload -> 'scores', '{}'::jsonb);
  rt jsonb := coalesce(p_payload -> 'rates', '{}'::jsonb);
  k text; v jsonb; mx numeric; rb date; was public.perf_reviews; changed jsonb;
begin
  err := public.perf_check(p_token, 'work');
  if err is not null then return jsonb_build_object('error', err); end if;
  m := public.ops_me();
  if p_member = m.id then return jsonb_build_object('error', 'own-review'); end if;
  if not exists (select 1 from public.team_members where id = p_member and active) then
    return jsonb_build_object('error', 'not-found');
  end if;
  if jsonb_typeof(sc) <> 'object' or jsonb_typeof(rt) <> 'object'
     or (p_payload ? 'notes' and jsonb_typeof(p_payload -> 'notes') <> 'object') then
    return jsonb_build_object('error', 'bad-payload');
  end if;
  for k, v in select key, value from jsonb_each(sc) loop
    mx := case k when 'output' then 25 when 'accuracy' then 15 when 'delivery' then 15
                 when 'client' then 20 when 'comms' then 15 when 'initiative' then 10 end;
    if mx is null then return jsonb_build_object('error', 'bad-score', 'key', k); end if;
    if jsonb_typeof(v) <> 'null' then
      if jsonb_typeof(v) <> 'number' then return jsonb_build_object('error', 'bad-score', 'key', k, 'max', mx); end if;
      if (v #>> '{}')::numeric not between 0 and mx or round((v #>> '{}')::numeric, 1) <> (v #>> '{}')::numeric then
        return jsonb_build_object('error', 'bad-score', 'key', k, 'max', mx);
      end if;
    end if;
  end loop;
  for k, v in select key, value from jsonb_each(rt) loop
    mx := case k when 'pacing' then 1000 when 'posting' then 100 when 'timeline' then 100
                 when 'satisfaction' then 100 when 'sla' then 100 end;
    if mx is null then return jsonb_build_object('error', 'bad-rate', 'key', k); end if;
    if jsonb_typeof(v) <> 'null' then
      if jsonb_typeof(v) <> 'number' then return jsonb_build_object('error', 'bad-rate', 'key', k); end if;
      if (v #>> '{}')::numeric not between 0 and mx then return jsonb_build_object('error', 'bad-rate', 'key', k); end if;
    end if;
  end loop;
  if coalesce(p_payload ->> 'review_by', '') <> '' then
    begin
      rb := (p_payload ->> 'review_by')::date;
    exception when others then
      return jsonb_build_object('error', 'bad-date');
    end;
  end if;

  select * into r from public.perf_reviews where team_member_id = p_member and period = p for update;
  if r.id is null then
    insert into public.perf_reviews (team_member_id, period) values (p_member, p)
    on conflict (team_member_id, period) do nothing;
    select * into r from public.perf_reviews where team_member_id = p_member and period = p for update;
    perform public.perf_log(r.id, p_member, 'started', '{}'::jsonb);
  elsif p_rev is not null and r.rev <> p_rev then
    return jsonb_build_object('error', 'stale', 'record', public.perf_json(r, true));
  end if;
  /* The scores are the draft's. What the month asks of the person next (the
     improvement, the date it is reviewed by, the step or reward) is written
     at the 1-1 and may be filled in until the record is final. */
  if r.status = 'final' or (r.status <> 'draft'
       and (p_payload - 'improvement' - 'review_by' - 'reward_step') <> '{}'::jsonb) then
    return jsonb_build_object('error', 'not-draft');
  end if;

  was := r;
  update public.perf_reviews set
    s_output     = case when sc ? 'output'     then (sc ->> 'output')::numeric     else s_output end,
    s_accuracy   = case when sc ? 'accuracy'   then (sc ->> 'accuracy')::numeric   else s_accuracy end,
    s_delivery   = case when sc ? 'delivery'   then (sc ->> 'delivery')::numeric   else s_delivery end,
    s_client     = case when sc ? 'client'     then (sc ->> 'client')::numeric     else s_client end,
    s_comms      = case when sc ? 'comms'      then (sc ->> 'comms')::numeric      else s_comms end,
    s_initiative = case when sc ? 'initiative' then (sc ->> 'initiative')::numeric else s_initiative end,
    r_posting      = case when rt ? 'posting'      then (rt ->> 'posting')::numeric      else r_posting end,
    r_timeline     = case when rt ? 'timeline'     then (rt ->> 'timeline')::numeric     else r_timeline end,
    r_satisfaction = case when rt ? 'satisfaction' then (rt ->> 'satisfaction')::numeric else r_satisfaction end,
    r_pacing       = case when rt ? 'pacing'       then (rt ->> 'pacing')::numeric       else r_pacing end,
    r_sla          = case when rt ? 'sla'          then (rt ->> 'sla')::numeric          else r_sla end,
    notes       = case when p_payload ? 'notes' then coalesce(p_payload -> 'notes', '{}'::jsonb) else notes end,
    improvement = case when p_payload ? 'improvement' then nullif(btrim(p_payload ->> 'improvement'), '') else improvement end,
    review_by   = case when p_payload ? 'review_by' then rb else review_by end,
    reward_step = case when p_payload ? 'reward_step' then nullif(btrim(p_payload ->> 'reward_step'), '') else reward_step end,
    updated_at = now(), rev = rev + 1
  where id = r.id
  returning * into r;
  /* What the save changed, named: each scorecard and rate whose value moved,
     from and to, then whether the notes or the plan moved. A save that moved
     nothing is not filed. */
  select coalesce(jsonb_agg(jsonb_build_object('key', c.key, 'from', c.a, 'to', c.b) order by c.n), '[]'::jsonb)
    into changed
    from (values (1, 'output', was.s_output, r.s_output), (2, 'accuracy', was.s_accuracy, r.s_accuracy),
                 (3, 'delivery', was.s_delivery, r.s_delivery), (4, 'client', was.s_client, r.s_client),
                 (5, 'comms', was.s_comms, r.s_comms), (6, 'initiative', was.s_initiative, r.s_initiative),
                 (7, 'posting', was.r_posting, r.r_posting), (8, 'timeline', was.r_timeline, r.r_timeline),
                 (9, 'satisfaction', was.r_satisfaction, r.r_satisfaction), (10, 'pacing', was.r_pacing, r.r_pacing),
                 (11, 'sla', was.r_sla, r.r_sla)) as c(n, key, a, b)
   where c.a is distinct from c.b;
  if coalesce(was.notes, '{}'::jsonb) is distinct from coalesce(r.notes, '{}'::jsonb) then
    changed := changed || jsonb_build_array(jsonb_build_object('key', 'notes'));
  end if;
  if was.improvement is distinct from r.improvement or was.review_by is distinct from r.review_by
     or was.reward_step is distinct from r.reward_step then
    changed := changed || jsonb_build_array(jsonb_build_object('key', 'plan'));
  end if;
  if jsonb_array_length(changed) > 0 then
    perform public.perf_log(r.id, p_member, 'scored', jsonb_build_object('changed', changed));
  end if;
  return public.perf_json(r, true);
end $$;

/* 3. The Activity record's Performance tab. */
create or replace function public.perf_activity(p_limit integer default 200)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare me_row public.team_members;
begin
  me_row := public.ops_me();
  if me_row.id is null or not public.ops_granted('team.performance', 'view') then
    return jsonb_build_object('error', 'denied');
  end if;
  return jsonb_build_object('rows', coalesce((
    select jsonb_agg(jsonb_build_object(
             'at', e.created_at, 'kind', e.kind, 'member', tm.name, 'period', rv.period,
             'actor', e.actor_email, 'actor_name', ac.name) order by e.created_at desc)
      from (select pe.* from public.perf_events pe
             where pe.kind in ('released', 'disputed', 'decided', 'acknowledged',
                               'finalised', 'reopened', 'returned', 'printed')
               and pe.team_member_id is distinct from me_row.id
             order by pe.created_at desc
             limit greatest(1, least(coalesce(p_limit, 200), 500))) e
      left join public.team_members tm on tm.id = e.team_member_id
      left join public.perf_reviews rv on rv.id = e.review_id
      left join public.team_members ac on ac.id = e.actor_id), '[]'::jsonb));
end $$;

revoke all on function public.perf_activity(integer) from public, anon, authenticated;
grant execute on function public.perf_activity(integer) to authenticated;

/* 4. Documents. */
/* The records Documents lists: downloaded at least once, and read by
   somebody holding both HR Letters and Performance at View. */
create or replace function public.perf_register()
returns jsonb
language plpgsql security definer set search_path = public as $$
declare me_row public.team_members;
begin
  me_row := public.ops_me();
  if me_row.id is null or not public.register_may('hr', 'view')
     or not public.ops_granted('team.performance', 'view') then
    return jsonb_build_object('rows', '[]'::jsonb);
  end if;
  return jsonb_build_object('rows', coalesce((
    select jsonb_agg(jsonb_build_object(
             'id', rv.id, 'serial', rv.serial, 'member_id', rv.team_member_id,
             'name', tm.name, 'staff_code', tm.staff_code, 'period', rv.period,
             'month', public.perf_month_word(rv.period), 'status', rv.status,
             'released_at', rv.released_at,
             'downloaded_at', (select min(pe.created_at) from public.perf_events pe
                                where pe.review_id = rv.id and pe.kind = 'printed'))
           order by rv.period desc, tm.name)
      from public.perf_reviews rv
      join public.team_members tm on tm.id = rv.team_member_id
     where rv.serial is not null and rv.team_member_id is distinct from me_row.id
       and exists (select 1 from public.perf_events pe where pe.review_id = rv.id and pe.kind = 'printed')),
    '[]'::jsonb));
end $$;

/* 5. The verify page. */
/* One exact reference in, the kind, the date and whether it stands. A
   reference typed with dashes for slashes (the file name's form) is the same
   reference, but an exact match is always answered first. A performance
   record is answered once it has been downloaded, as an HR Letter. */
create or replace function public.verify_serial(p_serial text)
returns jsonb
language plpgsql security definer stable set search_path = public as $$
declare
  s text := upper(btrim(coalesce(p_serial, '')));
  sd text;
  d public.documents%rowtype;
  l public.client_documents%rowtype;
  rv public.perf_reviews%rowtype;
begin
  if length(s) < 3 or length(s) > 40 then return jsonb_build_object('found', false); end if;
  sd := replace(s, '/', '-');
  select * into d from public.documents
   where upper(serial) = s or replace(upper(serial), '/', '-') = sd
   order by (upper(serial) = s) desc, (voided_at is null) desc, created_at desc limit 1;
  if d.id is not null then
    return jsonb_build_object('found', true, 'serial', d.serial,
      'kind', case when d.family = 'hr' then 'HR Letter' else d.kind end,
      'issued_at', d.issued_at,
      'state', case when d.voided_at is null then 'valid' else 'voided' end);
  end if;
  select * into l from public.client_documents
   where upper(number) = s or replace(upper(number), '/', '-') = sd
   order by (upper(number) = s) desc limit 1;
  if l.id is not null then
    return jsonb_build_object('found', true, 'serial', l.number, 'kind', 'Letter of Offer',
      'issued_at', l.issued_at,
      'state', case when l.voided_at is not null then 'voided'
                    when l.superseded_by is not null then 'replaced'
                    else 'valid' end);
  end if;
  select * into rv from public.perf_reviews pr
   where (upper(pr.serial) = s or replace(upper(pr.serial), '/', '-') = sd)
     and exists (select 1 from public.perf_events pe where pe.review_id = pr.id and pe.kind = 'printed')
   limit 1;
  if rv.id is not null then
    return jsonb_build_object('found', true, 'serial', rv.serial, 'kind', 'HR Letter',
      'issued_at', rv.released_at,
      'state', case when rv.status = 'draft' then 'replaced' else 'valid' end);
  end if;
  return jsonb_build_object('found', false);
end $$;

/* 6. A passkey unlocks My performance too. */
/* The session was verified in the last 15 minutes by an email code or link,
   or by a passkey (Face ID, Touch ID, the device password). Read from the
   signed token, never from anything the page passes in. */
create or replace function public.perf_code_fresh()
returns boolean
language sql stable set search_path = public as $$
  select coalesce((
    select bool_or(a ->> 'method' in ('otp', 'magiclink', 'webauthn', 'passkey')
                   and (a ->> 'timestamp') ~ '^[0-9]+$'
                   and (a ->> 'timestamp')::bigint >= extract(epoch from now())::bigint - 900)
      from jsonb_array_elements(case when jsonb_typeof(auth.jwt() -> 'amr') = 'array'
                                     then auth.jwt() -> 'amr' else '[]'::jsonb end) a), false)
$$;
revoke all on function public.perf_code_fresh() from public, anon, authenticated;

/* 7. The review list is chosen (the user, 2026-09-26: "there could be users
   who don't need performance review"). A colleague with no setting was on
   the list unless an admin; now they are off it until management adds them.
   Everybody the old default put on the list is written onto it by name once,
   while the old default still stands, so nothing changes for them; a second
   run finds the new default and writes nothing. */
do $$
begin
  if exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
              where n.nspname = 'public' and p.proname = 'perf_reviewed'
                and p.prosrc like '%not (m.is_admin or m.role = ''admin'')%') then
    insert into public.perf_people (team_member_id, reviewed)
    select tm.id, true from public.team_members tm
     where tm.active and not (tm.is_admin or tm.role = 'admin')
       and not exists (select 1 from public.perf_people pp where pp.team_member_id = tm.id);
    update public.perf_people pp set reviewed = true
      from public.team_members tm
     where tm.id = pp.team_member_id and pp.reviewed is null
       and tm.active and not (tm.is_admin or tm.role = 'admin');
  end if;
end $$;

/* Is this colleague on the monthly review? Only where management put them. */
create or replace function public.perf_reviewed(p_member uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce((select pp.reviewed from public.perf_people pp where pp.team_member_id = m.id), false)
    from public.team_members m where m.id = p_member
$$;
revoke all on function public.perf_reviewed(uuid) from public, anon, authenticated;

revoke all on function public.perf_activity(integer) from public, anon, authenticated;
revoke all on function public.perf_register() from public, anon, authenticated;
grant execute on function public.perf_activity(integer) to authenticated;
grant execute on function public.perf_register() to authenticated;
grant execute on function public.verify_serial(text) to anon, authenticated;

-- END OF PERFORMANCE RECORDS, THEIR TRAIL AND THEIR CHECK --------------------

-- ===========================================================================
-- MY WORK STAGES IN ORDER — one fixed order for the content workflow, content
-- deliverables start at Ready to start, and going back asks why.
-- 2026-09-26. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/ops.js compares the two.
--
-- WHAT CHANGED, the user's decisions of 2026-09-26 ("your stage listing keeps
-- jumping around"; "Planning and Meeting is for with Clients"):
--  1. A stage can be retired (`ops_workflow_stages.retired`): it keeps the
--     tasks standing on it and takes no new ones. Planning, Content meeting
--     scheduled, Changes requested and Published are retired on the content
--     workflow; the month carries its planning and its meeting.
--  2. The content workflow is numbered in the order the work runs: Ready to
--     start, In progress, AQC review, Revision (Internal), Client review,
--     Revision (Client), Approved, Scheduled, Live, Performance review,
--     Completed, then On hold, Blocked, Cancelled, Taken down, then the
--     retired stages. A new content task therefore starts at Ready to start.
--  3. On hold and Cancelled are reachable from every open stage on the line;
--     a cancelled task comes back to the stage it was cancelled from; nothing
--     offers a retired stage.
--  4. Open tasks standing on Planning or Content meeting scheduled move to
--     Ready to start, each with a stage_changed event saying why.
--  5. `ops_transition_task`: picking an earlier stage on the line is allowed
--     with a reason (`back-reason-required`) and filed with `back: true`; a
--     retired stage is refused (`retired-stage`); a skip never files a
--     revision or a retired stage as skipped.
--
-- ROLLBACK
--   Re-run ops_transition_task from 2026-09-25-the-owner-moves-the-task.sql.
--   The positions, lists and moved tasks stay; the `retired` column may stay
--   (nothing else reads it) or: alter table public.ops_workflow_stages drop
--   column retired;
-- ===========================================================================

-- 1. A stage can be retired ----------------------------------------------------
alter table public.ops_workflow_stages add column if not exists retired boolean not null default false;

-- 2 to 4. The content workflow in the order the work runs -------------------------
do $$
declare
  w uuid;
  line text[] := array['ready', 'in_production', 'internal_review', 'revision_internal',
                       'client_review', 'revision_client', 'approved', 'scheduled', 'live',
                       'performance_review', 'completed', 'on_hold', 'blocked', 'cancelled',
                       'taken_down', 'planning', 'meeting_scheduled', 'changes_requested',
                       'published'];
  open_line text[] := array['ready', 'in_production', 'internal_review', 'revision_internal',
                            'client_review', 'revision_client', 'approved', 'scheduled'];
  k text;
begin
  select id into w from public.ops_workflows where key = 'content';
  if w is null then return; end if;

  update public.ops_workflow_stages set retired = true
   where workflow_id = w and not retired
     and key in ('planning', 'meeting_scheduled', 'changes_requested', 'published');

  /* Numbered twice, because (workflow, position) is unique: out of the way
     first, then into place. A stage somebody added keeps its order after
     the ones named here. */
  if exists (select 1 from public.ops_workflow_stages s
              where s.workflow_id = w
                and ((s.key = any (line) and s.position <> array_position(line, s.key))
                  or (not (s.key = any (line)) and s.position < 100))) then
    update public.ops_workflow_stages set position = position + 1000 where workflow_id = w;
    update public.ops_workflow_stages s
       set position = coalesce(array_position(line, s.key), 100 + (s.position - 1000))
     where s.workflow_id = w;
  end if;

  -- Nothing offers a retired stage.
  update public.ops_workflow_stages s
     set next_stage_keys = array(select x from unnest(s.next_stage_keys) x
                                  where x not in ('planning', 'meeting_scheduled'))
   where s.workflow_id = w and s.next_stage_keys && array['planning', 'meeting_scheduled'];

  -- On hold and Cancelled from every open stage on the line.
  foreach k in array open_line loop
    update public.ops_workflow_stages s set next_stage_keys = s.next_stage_keys || array['on_hold']
     where s.workflow_id = w and s.key = k and not ('on_hold' = any (s.next_stage_keys));
    update public.ops_workflow_stages s set next_stage_keys = s.next_stage_keys || array['cancelled']
     where s.workflow_id = w and s.key = k and not ('cancelled' = any (s.next_stage_keys));
  end loop;
  -- Resume from On hold, and reopen from Cancelled, to any open stage on the line.
  foreach k in array open_line loop
    update public.ops_workflow_stages s set next_stage_keys = s.next_stage_keys || array[k]
     where s.workflow_id = w and s.key in ('on_hold', 'cancelled') and not (k = any (s.next_stage_keys));
  end loop;

  /* The open tasks still on Planning or the content meeting start the work:
     the month holds its planning and its meeting now. */
  insert into public.ops_task_events (task_id, event_type, from_value, to_value, detail)
  select t.id, 'stage_changed', jsonb_build_object('stage_key', t.stage_key),
         jsonb_build_object('stage_key', 'ready'),
         jsonb_build_object('note', 'Planning and the content meeting belong to the month.')
    from public.ops_tasks t
   where t.workflow_id = w and t.stage_key in ('planning', 'meeting_scheduled')
     and t.completed_at is null and t.cancelled_at is null;
  update public.ops_tasks t set stage_key = 'ready', version = t.version + 1, updated_at = now()
   where t.workflow_id = w and t.stage_key in ('planning', 'meeting_scheduled')
     and t.completed_at is null and t.cancelled_at is null;
end $$;

-- 5. Going back asks why; a retired stage takes no task --------------------------
create or replace function public.ops_transition_task(
  p_task uuid, p_next text, p_version integer default null, p_note text default null,
  p_assignee uuid default null, p_skip_reason text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m   public.team_members;
  t   public.ops_tasks;
  cur public.ops_workflow_stages;
  nxt public.ops_workflow_stages;
  sk  public.ops_workflow_stages;
  eng public.ops_engagements;
  has_owner boolean;
  has_draft boolean;
  has_final boolean;
  was_owner uuid;
  side text[] := array['blocked', 'waiting', 'kiv', 'cancelled'];
  skipping boolean := false;
  going_back boolean := false;
  ws  public.ops_work_sessions;
  wmins integer;
  v_round integer;
begin
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if not public.ops_may_see_task(p_task) then return jsonb_build_object('error', 'denied'); end if;
  if not public.allowed('ops', 'work') then return jsonb_build_object('error', 'denied'); end if;

  select * into t from public.ops_tasks where id = p_task for update;
  if t.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if p_version is not null and p_version <> t.version then
    return jsonb_build_object('error', 'stale', 'task', public.ops_task_json(p_task));
  end if;
  if t.stage_key = p_next then return public.ops_task_json(p_task); end if;
  /* The stage is the owner's to move. Once a task is handed to somebody,
     whoever created it or held it before reads it and no longer moves it; an
     admin still may. */
  if not public.ops_owner_may_move(p_task) then return jsonb_build_object('error', 'not-owner'); end if;

  cur := public.ops_stage(t.workflow_id, t.stage_key);
  nxt := public.ops_stage(t.workflow_id, p_next);
  if nxt.id is null then return jsonb_build_object('error', 'no-such-stage'); end if;
  /* A retired stage keeps the tasks already standing on it and takes no new
     ones: Planning and the content meeting are the month's, not a task's. */
  if nxt.retired then return jsonb_build_object('error', 'retired-stage'); end if;
  if not (p_next = any (cur.next_stage_keys)) then
    /* A step the deliverable does not need is skipped, forward along the
       line, with a reason on the record: who skipped it and why is written
       against every stage that was passed over. Nothing beside the line can
       be skipped into or out of, and nothing is skipped backwards. */
    /* A revision is where work is sent back from a review, so it is never
       a step somebody skips forward into. */
    if not (cur.stage_group = any (side)) and not (nxt.stage_group = any (side))
       and nxt.stage_group <> 'revision'
       and nxt.position > cur.position then
      if nullif(btrim(coalesce(p_skip_reason, '')), '') is null then
        return jsonb_build_object('error', 'skip-reason-required');
      end if;
      skipping := true;
    /* Going back is picking an earlier stage on the line, and says why; the
       reason goes on the record with the move. A revision is entered only
       from the review that sends work to it. */
    elsif not (cur.stage_group = any (side)) and not (nxt.stage_group = any (side))
       and nxt.stage_group <> 'revision'
       and nxt.position < cur.position then
      if nullif(btrim(coalesce(p_note, '')), '') is null then
        return jsonb_build_object('error', 'back-reason-required');
      end if;
      going_back := true;
    else
      return jsonb_build_object('error', 'bad-transition',
        'allowed', to_jsonb(cur.next_stage_keys));
    end if;
  end if;

  /* A performance review goes back to whoever created the task unless the
     move names somebody else. */
  if p_next = 'performance_review' and p_assignee is null and exists (
       select 1 from public.team_members where id = t.created_by and active) then
    p_assignee := t.created_by;
  end if;

  -- What each gate needs before it opens.
  has_owner := exists (select 1 from public.ops_task_assignees
                        where task_id = p_task and responsibility = 'owner' and ended_at is null)
               or p_assignee is not null;
  has_draft := exists (select 1 from public.ops_task_links
                        where task_id = p_task and archived_at is null
                          and kind in ('draft', 'review'));
  has_final := exists (select 1 from public.ops_task_links
                        where task_id = p_task and archived_at is null and kind = 'final');

  if p_next = 'ready' and (not has_owner or t.current_final_due_at is null) then
    return jsonb_build_object('error', 'ready-needs-owner-and-due');
  end if;
  if p_next = 'editing' and exists (
       select 1 from public.ops_video_details v
        where v.task_id = p_task and v.footage_ready is false) then
    return jsonb_build_object('error', 'footage-not-ready');
  end if;
  /* Production waits on the engagement: planning marked complete, and the
     content meeting held or marked not applicable. A task with no engagement
     (ad hoc, internal) has nothing to wait on. */
  if p_next = 'in_production' and t.engagement_id is not null then
    select * into eng from public.ops_engagements where id = t.engagement_id;
    if eng.status = 'planning' then return jsonb_build_object('error', 'planning-incomplete'); end if;
    if not (eng.meeting_na or (eng.meeting_at is not null and eng.meeting_at <= now())) then
      return jsonb_build_object('error', 'meeting-required');
    end if;
  end if;
  /* AQC review comes first: the client sees the work only once it has been
     through AQC review at least once. */
  if p_next = 'client_review'
     and exists (select 1 from public.ops_workflow_stages s
                  where s.workflow_id = t.workflow_id and s.key = 'internal_review')
     and not exists (select 1 from public.ops_task_events e
                      where e.task_id = p_task and e.event_type = 'stage_changed'
                        and e.to_value ->> 'stage_key' = 'internal_review') then
    return jsonb_build_object('error', 'needs-aqc');
  end if;
  /* The draft reaches the client as a link on the task or through the
     team's WhatsApp group with the client. Either way the record says how:
     the link, or a note naming where it went. */
  if p_next = 'client_review' and not has_draft
     and nullif(btrim(coalesce(p_note, '')), '') is null then
    return jsonb_build_object('error', 'needs-draft');
  end if;
  /* A revision says what has to change, and so does taking a post down. */
  if ((nxt.stage_group = 'revision' and p_next <> 'changes_requested') or p_next = 'taken_down')
     and nullif(btrim(coalesce(p_note, '')), '') is null then
    return jsonb_build_object('error', 'note-required');
  end if;
  /* After approval: a schedule needs its date, going live is confirmed with
     its own date through ops_mark_live and needs the post's link or a note,
     and a task is completed only once its performance checklist is done. */
  if p_next = 'scheduled' and t.publish_at is null then
    return jsonb_build_object('error', 'needs-schedule');
  end if;
  if p_next = 'live' and t.live_at is null then
    return jsonb_build_object('error', 'needs-live-date');
  end if;
  if p_next = 'live' and not has_final and coalesce(p_note, '') = '' then
    return jsonb_build_object('error', 'needs-final-or-reason');
  end if;
  if p_next = 'completed' and exists (
       select 1 from public.ops_task_checklist_items c
        where c.task_id = p_task and c.required and c.completed_at is null) then
    return jsonb_build_object('error', 'checklist-incomplete');
  end if;
  if p_next = 'delivered' and not has_final then
    return jsonb_build_object('error', 'needs-final-link');
  end if;
  if p_next = 'done' and t.delivered_at is null
     and coalesce(p_note, '') = '' then
    return jsonb_build_object('error', 'needs-delivery-or-reason');
  end if;
  if p_next = 'published' and not has_final and coalesce(p_note, '') = '' then
    return jsonb_build_object('error', 'needs-final-or-reason');
  end if;

  /* The hand to the next person, recorded on the move: the previous owner
     ends, the new one begins, and the event names both with the stage it
     happened at. Work level, because handing the work on is part of doing
     it; reassigning a task without moving it stays Manage. */
  if p_assignee is not null then
    select team_member_id into was_owner from public.ops_task_assignees
     where task_id = p_task and responsibility = 'owner' and ended_at is null;
    if p_assignee is distinct from was_owner then
      if not exists (select 1 from public.team_members where id = p_assignee and active) then
        return jsonb_build_object('error', 'no-such-person');
      end if;
      update public.ops_task_assignees set ended_at = now()
       where task_id = p_task and responsibility = 'owner' and ended_at is null;
      insert into public.ops_task_assignees (task_id, team_member_id, responsibility, assigned_by)
      values (p_task, p_assignee, 'owner', m.id);
      perform public.ops_log(p_task, 'assignment_changed',
        jsonb_build_object('owner_id', was_owner),
        jsonb_build_object('owner_id', p_assignee),
        jsonb_build_object('handover', true, 'stage_key', p_next, 'from_stage_key', t.stage_key));
    end if;
  end if;

  if skipping then
    for sk in select * from public.ops_workflow_stages
               where workflow_id = t.workflow_id
                 and position > cur.position and position < nxt.position
                 and not (stage_group = any (side))
                 and stage_group <> 'revision' and not retired
               order by position loop
      perform public.ops_log(p_task, 'stage_skipped',
        jsonb_build_object('stage_key', sk.key), jsonb_build_object('stage_key', p_next),
        jsonb_build_object('reason', btrim(p_skip_reason)));
    end loop;
  end if;

  /* The round: how many times this task has now entered this review or
     this revision, counted off its own history, so nothing is stored that
     a reverted move could leave wrong. */
  if nxt.is_review or nxt.stage_group = 'revision' then
    select count(*) + 1 into v_round from public.ops_task_events e
     where e.task_id = p_task and e.event_type = 'stage_changed'
       and e.to_value ->> 'stage_key' = p_next;
  end if;

  update public.ops_tasks set
    stage_key = p_next,
    version = version + 1,
    updated_at = now(),
    first_draft_submitted_at = case
      when first_draft_submitted_at is null and nxt.is_review then now()
      else first_draft_submitted_at end,
    delivered_at = case when p_next = 'delivered' then coalesce(delivered_at, now())
                        else delivered_at end,
    completed_at = case when nxt.is_terminal and p_next <> 'cancelled' then coalesce(completed_at, now())
                        when not nxt.is_terminal then null
                        else completed_at end,
    /* Leaving Cancelled for a live stage is a reopening, and the stamp
       leaves with it, as completed_at does; left behind, the task went on
       reading cancelled at the stage it had been reopened to. */
    cancelled_at = case when p_next = 'cancelled' then coalesce(cancelled_at, now())
                        when not nxt.is_terminal then null
                        else cancelled_at end,
    blocked_at = case when p_next = 'blocked' then blocked_at else null end,
    blocked_category = case when p_next = 'blocked' then blocked_category else null end
  where id = p_task;

  /* The performance review brings its own checklist, the same five checks
     for a brand post and a KOC post, added once however often the task
     comes back to the stage. */
  if p_next = 'performance_review' then
    insert into public.ops_task_checklist_items (task_id, label, position, required)
    select p_task, x.label,
           coalesce((select max(c.position) from public.ops_task_checklist_items c
                      where c.task_id = p_task), 0) + x.n,
           true
      from (values (1, 'Reach and views checked'),
                   (2, 'Engagement checked (likes, comments, shares, saves)'),
                   (3, 'Comments checked for brand safety'),
                   (4, 'Leads or sales checked, where tracked'),
                   (5, 'Keep live or take down decided')) as x(n, label)
     where not exists (select 1 from public.ops_task_checklist_items c
                        where c.task_id = p_task and c.label = x.label);
  end if;

  /* A finished task is not being worked on, so every timer running on it
     stops with it, each filed as the stop it is. */
  if nxt.is_terminal then
    for ws in select * from public.ops_work_sessions
               where task_id = p_task and ended_at is null loop
      wmins := greatest(0, (extract(epoch from (now() - ws.started_at)) / 60)::integer);
      update public.ops_work_sessions set ended_at = now(), minutes = wmins where id = ws.id;
      perform public.ops_log(p_task, 'work_stopped', null,
        jsonb_build_object('session_id', ws.id, 'minutes', wmins),
        jsonb_build_object('note', 'Stopped when the task finished'));
    end loop;
  end if;

  perform public.ops_log(p_task, 'stage_changed',
    jsonb_build_object('stage_key', t.stage_key),
    jsonb_build_object('stage_key', p_next),
    (case when p_note is null then '{}'::jsonb else jsonb_build_object('note', p_note) end)
    || (case when skipping then jsonb_build_object('skip_reason', btrim(p_skip_reason)) else '{}'::jsonb end)
    || (case when going_back then jsonb_build_object('back', true) else '{}'::jsonb end)
    || (case when v_round is not null then jsonb_build_object('round', v_round) else '{}'::jsonb end));
  if p_next = 'delivered' then
    perform public.ops_log(p_task, 'delivered', null, null, '{}'::jsonb);
  end if;
  if nxt.is_terminal and p_next <> 'cancelled' then
    perform public.ops_log(p_task, 'completed', null, null, '{}'::jsonb);
  end if;
  if p_next = 'cancelled' then
    perform public.ops_log(p_task, 'cancelled', null, null,
      jsonb_build_object('reason', p_note));
  end if;
  return public.ops_task_json(p_task);
end $$;
grant execute on function public.ops_transition_task(uuid, text, integer, text, uuid, text) to authenticated;

-- END OF MY WORK STAGES IN ORDER --------------------------------------------

-- ===========================================================================
-- DOCUMENT EDITS NAME THEIR CHANGES — an edit to a hand-added Documents row
-- records each field it moved, from and to.
-- 2026-09-26. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/sql.js compares the two.
--
-- WHAT CHANGED, the user's decision of 2026-09-26 (records "too brief"; the
-- example given: "Edited ADHR/AD021/AOR: type Acceptance of Resignation →
-- Offer Letter; date not set → 12 Sept 2026"):
--  1. `register_update` files what moved: the type, the date, the family,
--     the recipient, the client, and whether the note or the file link
--     changed. A save that moved nothing files nothing.
--  2. An HR row keeps its rule: filed under subject `HR`, never the serial,
--     the colleague or the recipient; its detail names the type, the date,
--     the note and the file link only.
--
-- ROLLBACK
--   Re-run register_update from 2026-09-26-an-hr-entry-names-its-colleague.sql.
-- ===========================================================================

create or replace function public.register_day(p_day date)
returns text
language sql immutable set search_path = public as $$
  select case when p_day is null then 'not set'
    else to_char(p_day, 'FMDD') || ' ' ||
         (array['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sept','Oct','Nov','Dec'])[extract(month from p_day)::int]
         || ' ' || to_char(p_day, 'YYYY') end
$$;

create or replace function public.register_update(
  p_doc       uuid,
  p_kind      text,
  p_family    text,
  p_issued_at date,
  p_recipient text,
  p_client    uuid,
  p_note      text,
  p_file_url  text,
  p_member    uuid default null
)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  who   text := lower(auth.jwt() ->> 'email');
  d     public.documents%rowtype;
  v_fam text := coalesce(nullif(btrim(p_family), ''), 'other');
  cl    public.clients%rowtype;
  was_cl public.clients%rowtype;
  tm    public.team_members%rowtype;
  moves text[] := array[]::text[];
  fam_word jsonb := '{"quote_cover":"Quotation Covers","client":"Client Letters","hr":"HR Letters","other":"Other"}'::jsonb;
  v_rec text := coalesce(btrim(p_recipient), '');
  v_note text := nullif(btrim(p_note), '');
  v_file text := nullif(btrim(p_file_url), '');
begin
  select * into d from public.documents where id = p_doc;
  if d.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if d.source <> 'manual' then return jsonb_build_object('error', 'not-manual'); end if;
  if v_fam not in ('quote_cover', 'client', 'hr', 'other') then return jsonb_build_object('error', 'bad-family'); end if;
  if not public.register_may(d.family, 'work') or not public.register_may(v_fam, 'work') then
    return jsonb_build_object('error', 'not-allowed');
  end if;
  if coalesce(btrim(p_kind), '') = '' then return jsonb_build_object('error', 'kind-required'); end if;
  if v_fam = 'hr' then
    if p_member is not null then select * into tm from public.team_members where id = p_member; end if;
  elsif p_client is not null then
    select * into cl from public.clients where id = p_client;
  end if;
  if d.client_id is not null then select * into was_cl from public.clients where id = d.client_id; end if;

  /* What moved, in the order a reader looks: the type, the date, where it is
     filed, who it went to, then whether the note or the file changed. An HR
     row names only its type, date, note and file. */
  if d.kind is distinct from btrim(p_kind) then
    moves := moves || ('type ' || coalesce(d.kind, 'not set') || ' → ' || btrim(p_kind));
  end if;
  if d.issued_at is distinct from p_issued_at then
    moves := moves || ('date ' || public.register_day(d.issued_at) || ' → ' || public.register_day(p_issued_at));
  end if;
  if v_fam <> 'hr' and d.family <> 'hr' then
    if d.family is distinct from v_fam then
      moves := moves || ('filed ' || coalesce(fam_word ->> d.family, d.family) || ' → ' || coalesce(fam_word ->> v_fam, v_fam));
    end if;
    if coalesce(d.recipient ->> 'name', '') is distinct from v_rec then
      moves := moves || ('recipient ' || coalesce(nullif(d.recipient ->> 'name', ''), 'not set') || ' → ' || coalesce(nullif(v_rec, ''), 'not set'));
    end if;
    if d.client_id is distinct from cl.id then
      moves := moves || ('client ' || coalesce(was_cl.name, 'not set') || ' → ' || coalesce(cl.name, 'not set'));
    end if;
  end if;
  if d.note is distinct from v_note then moves := moves || 'note changed'::text; end if;
  if d.file_url is distinct from v_file then moves := moves || 'file link changed'::text; end if;

  update public.documents set
    kind = btrim(p_kind), family = v_fam, issued_at = p_issued_at,
    recipient = jsonb_build_object('name', v_rec),
    client_id = cl.id, member_id = tm.id,
    note = v_note, file_url = v_file
  where id = p_doc;
  if array_length(moves, 1) > 0 then
    insert into public.activity_log (actor, action, subject, detail)
    values (who, 'register.edited',
            case when v_fam = 'hr' or d.family = 'hr' then 'HR' else coalesce(cl.name, nullif(v_rec, ''), d.serial) end,
            case when v_fam = 'hr' or d.family = 'hr' then array_to_string(moves, '; ')
                 else d.serial || ': ' || array_to_string(moves, '; ') end);
  end if;
  return jsonb_build_object('ok', true, 'serial', d.serial);
end $$;
grant execute on function public.register_update(uuid, text, text, date, text, uuid, text, text, uuid) to authenticated;

-- END OF DOCUMENT EDITS NAME THEIR CHANGES -----------------------------------

-- ===========================================================================
-- MONTH STAGES FOLLOW THE WORK — a content month's stage is worked out from
-- its facts; Completed, Cancelled and a reopen are the team's decisions.
-- 2026-09-27. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/ops.js compares the two.
--
-- WHAT CHANGED, the user's decision of 2026-09-27 ("Can the status on content
-- month being set automatically triggered by each stages?"):
--  1. Planning, Ready and In production are no longer set by hand. The page
--     works them out on every load: Planning until the readiness ticks are
--     answered and the meeting is set (or marked not applicable), Ready once
--     they are, In production once the meeting has passed and the month
--     holds a task. `ops_engagement_set_status` refuses them
--     (`derived-state`).
--  2. What a person decides is stored: Completed, refused while any of the
--     month's tasks is open (`tasks-open`, with the count); Cancelled; and
--     Planning, which reopens either.
--  3. A task's move into production reads the same facts (the readiness
--     ticks and the meeting) instead of the stored status, which now stays
--     Planning for an open month; otherwise no content task could start.
--  4. `ops_engagement_counts` counts each month's live, open and done tasks
--     over every task in it: a colleague who reads only their own tasks
--     would otherwise see a month nearly done that is not. Counts only; no
--     task is named. A stored Ready or In production from before is left as
--     it is and read as open.
--
-- ROLLBACK
--   Re-run ops_engagement_set_status from 2026-09-23-operations-phase4.sql
--   and ops_transition_task from 2026-09-26-my-work-stages-in-order.sql;
--   drop function if exists public.ops_engagement_counts(uuid[]);
-- ===========================================================================

create or replace function public.ops_engagement_set_status(
  p_engagement uuid, p_status text, p_version integer default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare m public.team_members; e public.ops_engagements; v_open integer;
begin
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if not public.allowed('ops', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if not public.ops_may_see_engagement(p_engagement) then return jsonb_build_object('error', 'denied'); end if;
  if p_status in ('ready', 'in_production') then
    return jsonb_build_object('error', 'derived-state');
  end if;
  if p_status not in ('planning', 'completed', 'cancelled') then
    return jsonb_build_object('error', 'bad-state');
  end if;
  select * into e from public.ops_engagements where id = p_engagement for update;
  if e.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if p_version is not null and p_version <> e.version then
    return jsonb_build_object('error', 'stale', 'engagement', public.ops_engagement_json(p_engagement));
  end if;
  if p_status = 'completed' then
    select count(*) into v_open from public.ops_tasks t
     where t.engagement_id = p_engagement and t.archived_at is null
       and t.completed_at is null and t.cancelled_at is null;
    if v_open > 0 then
      return jsonb_build_object('error', 'tasks-open', 'open', v_open);
    end if;
  end if;
  if e.status = p_status then return public.ops_engagement_json(p_engagement); end if;
  update public.ops_engagements set status = p_status, updated_at = now(), version = version + 1
   where id = p_engagement;
  perform public.ops_engagement_log(p_engagement, 'status_changed',
    jsonb_build_object('from', e.status, 'to', p_status));
  return public.ops_engagement_json(p_engagement);
end $$;
grant execute on function public.ops_engagement_set_status(uuid, text, integer) to authenticated;

/* A month's tasks, counted over the whole month whoever asks: live (not
   cancelled), open (not finished) and done (completed). Only months the
   caller may see answer. */
create or replace function public.ops_engagement_counts(p_engagements uuid[])
returns jsonb
language sql security definer stable set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'engagement_id', e.id,
           'live', (select count(*) from public.ops_tasks t
                     where t.engagement_id = e.id and t.archived_at is null
                       and t.cancelled_at is null),
           'open', (select count(*) from public.ops_tasks t
                     where t.engagement_id = e.id and t.archived_at is null
                       and t.cancelled_at is null and t.completed_at is null),
           'done', (select count(*) from public.ops_tasks t
                     where t.engagement_id = e.id and t.archived_at is null
                       and t.cancelled_at is null and t.completed_at is not null))), '[]'::jsonb)
    from public.ops_engagements e
   where e.id = any (coalesce(p_engagements, '{}'::uuid[]))
     and public.ops_may_see_engagement(e.id)
$$;
revoke all on function public.ops_engagement_counts(uuid[]) from public, anon;
grant execute on function public.ops_engagement_counts(uuid[]) to authenticated;

create or replace function public.ops_transition_task(
  p_task uuid, p_next text, p_version integer default null, p_note text default null,
  p_assignee uuid default null, p_skip_reason text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m   public.team_members;
  t   public.ops_tasks;
  cur public.ops_workflow_stages;
  nxt public.ops_workflow_stages;
  sk  public.ops_workflow_stages;
  eng public.ops_engagements;
  has_owner boolean;
  has_draft boolean;
  has_final boolean;
  was_owner uuid;
  side text[] := array['blocked', 'waiting', 'kiv', 'cancelled'];
  skipping boolean := false;
  going_back boolean := false;
  ws  public.ops_work_sessions;
  wmins integer;
  v_round integer;
begin
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if not public.ops_may_see_task(p_task) then return jsonb_build_object('error', 'denied'); end if;
  if not public.allowed('ops', 'work') then return jsonb_build_object('error', 'denied'); end if;

  select * into t from public.ops_tasks where id = p_task for update;
  if t.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if p_version is not null and p_version <> t.version then
    return jsonb_build_object('error', 'stale', 'task', public.ops_task_json(p_task));
  end if;
  if t.stage_key = p_next then return public.ops_task_json(p_task); end if;
  /* The stage is the owner's to move. Once a task is handed to somebody,
     whoever created it or held it before reads it and no longer moves it; an
     admin still may. */
  if not public.ops_owner_may_move(p_task) then return jsonb_build_object('error', 'not-owner'); end if;

  cur := public.ops_stage(t.workflow_id, t.stage_key);
  nxt := public.ops_stage(t.workflow_id, p_next);
  if nxt.id is null then return jsonb_build_object('error', 'no-such-stage'); end if;
  /* A retired stage keeps the tasks already standing on it and takes no new
     ones: Planning and the content meeting are the month's, not a task's. */
  if nxt.retired then return jsonb_build_object('error', 'retired-stage'); end if;
  if not (p_next = any (cur.next_stage_keys)) then
    /* A step the deliverable does not need is skipped, forward along the
       line, with a reason on the record: who skipped it and why is written
       against every stage that was passed over. Nothing beside the line can
       be skipped into or out of, and nothing is skipped backwards. */
    /* A revision is where work is sent back from a review, so it is never
       a step somebody skips forward into. */
    if not (cur.stage_group = any (side)) and not (nxt.stage_group = any (side))
       and nxt.stage_group <> 'revision'
       and nxt.position > cur.position then
      if nullif(btrim(coalesce(p_skip_reason, '')), '') is null then
        return jsonb_build_object('error', 'skip-reason-required');
      end if;
      skipping := true;
    /* Going back is picking an earlier stage on the line, and says why; the
       reason goes on the record with the move. A revision is entered only
       from the review that sends work to it. */
    elsif not (cur.stage_group = any (side)) and not (nxt.stage_group = any (side))
       and nxt.stage_group <> 'revision'
       and nxt.position < cur.position then
      if nullif(btrim(coalesce(p_note, '')), '') is null then
        return jsonb_build_object('error', 'back-reason-required');
      end if;
      going_back := true;
    else
      return jsonb_build_object('error', 'bad-transition',
        'allowed', to_jsonb(cur.next_stage_keys));
    end if;
  end if;

  /* A performance review goes back to whoever created the task unless the
     move names somebody else. */
  if p_next = 'performance_review' and p_assignee is null and exists (
       select 1 from public.team_members where id = t.created_by and active) then
    p_assignee := t.created_by;
  end if;

  -- What each gate needs before it opens.
  has_owner := exists (select 1 from public.ops_task_assignees
                        where task_id = p_task and responsibility = 'owner' and ended_at is null)
               or p_assignee is not null;
  has_draft := exists (select 1 from public.ops_task_links
                        where task_id = p_task and archived_at is null
                          and kind in ('draft', 'review'));
  has_final := exists (select 1 from public.ops_task_links
                        where task_id = p_task and archived_at is null and kind = 'final');

  if p_next = 'ready' and (not has_owner or t.current_final_due_at is null) then
    return jsonb_build_object('error', 'ready-needs-owner-and-due');
  end if;
  if p_next = 'editing' and exists (
       select 1 from public.ops_video_details v
        where v.task_id = p_task and v.footage_ready is false) then
    return jsonb_build_object('error', 'footage-not-ready');
  end if;
  /* Production waits on the month's own facts: its readiness ticks
     answered, and its content meeting held or marked not applicable. The
     month's stage is worked out from those facts on the page and is never
     stored, so the stored status is not read here (2026-09-27). A task with
     no month (ad hoc, internal) has nothing to wait on. */
  if p_next = 'in_production' and t.engagement_id is not null then
    select * into eng from public.ops_engagements where id = t.engagement_id;
    if exists (select 1 from public.ops_engagement_checks c
                where c.engagement_id = eng.id
                  and c.state in ('not_started', 'waiting_client', 'in_progress')) then
      return jsonb_build_object('error', 'planning-incomplete');
    end if;
    if not (eng.meeting_na or (eng.meeting_at is not null and eng.meeting_at <= now())) then
      return jsonb_build_object('error', 'meeting-required');
    end if;
  end if;
  /* AQC review comes first: the client sees the work only once it has been
     through AQC review at least once. */
  if p_next = 'client_review'
     and exists (select 1 from public.ops_workflow_stages s
                  where s.workflow_id = t.workflow_id and s.key = 'internal_review')
     and not exists (select 1 from public.ops_task_events e
                      where e.task_id = p_task and e.event_type = 'stage_changed'
                        and e.to_value ->> 'stage_key' = 'internal_review') then
    return jsonb_build_object('error', 'needs-aqc');
  end if;
  /* The draft reaches the client as a link on the task or through the
     team's WhatsApp group with the client. Either way the record says how:
     the link, or a note naming where it went. */
  if p_next = 'client_review' and not has_draft
     and nullif(btrim(coalesce(p_note, '')), '') is null then
    return jsonb_build_object('error', 'needs-draft');
  end if;
  /* A revision says what has to change, and so does taking a post down. */
  if ((nxt.stage_group = 'revision' and p_next <> 'changes_requested') or p_next = 'taken_down')
     and nullif(btrim(coalesce(p_note, '')), '') is null then
    return jsonb_build_object('error', 'note-required');
  end if;
  /* After approval: a schedule needs its date, going live is confirmed with
     its own date through ops_mark_live and needs the post's link or a note,
     and a task is completed only once its performance checklist is done. */
  if p_next = 'scheduled' and t.publish_at is null then
    return jsonb_build_object('error', 'needs-schedule');
  end if;
  if p_next = 'live' and t.live_at is null then
    return jsonb_build_object('error', 'needs-live-date');
  end if;
  if p_next = 'live' and not has_final and coalesce(p_note, '') = '' then
    return jsonb_build_object('error', 'needs-final-or-reason');
  end if;
  if p_next = 'completed' and exists (
       select 1 from public.ops_task_checklist_items c
        where c.task_id = p_task and c.required and c.completed_at is null) then
    return jsonb_build_object('error', 'checklist-incomplete');
  end if;
  if p_next = 'delivered' and not has_final then
    return jsonb_build_object('error', 'needs-final-link');
  end if;
  if p_next = 'done' and t.delivered_at is null
     and coalesce(p_note, '') = '' then
    return jsonb_build_object('error', 'needs-delivery-or-reason');
  end if;
  if p_next = 'published' and not has_final and coalesce(p_note, '') = '' then
    return jsonb_build_object('error', 'needs-final-or-reason');
  end if;

  /* The hand to the next person, recorded on the move: the previous owner
     ends, the new one begins, and the event names both with the stage it
     happened at. Work level, because handing the work on is part of doing
     it; reassigning a task without moving it stays Manage. */
  if p_assignee is not null then
    select team_member_id into was_owner from public.ops_task_assignees
     where task_id = p_task and responsibility = 'owner' and ended_at is null;
    if p_assignee is distinct from was_owner then
      if not exists (select 1 from public.team_members where id = p_assignee and active) then
        return jsonb_build_object('error', 'no-such-person');
      end if;
      update public.ops_task_assignees set ended_at = now()
       where task_id = p_task and responsibility = 'owner' and ended_at is null;
      insert into public.ops_task_assignees (task_id, team_member_id, responsibility, assigned_by)
      values (p_task, p_assignee, 'owner', m.id);
      perform public.ops_log(p_task, 'assignment_changed',
        jsonb_build_object('owner_id', was_owner),
        jsonb_build_object('owner_id', p_assignee),
        jsonb_build_object('handover', true, 'stage_key', p_next, 'from_stage_key', t.stage_key));
    end if;
  end if;

  if skipping then
    for sk in select * from public.ops_workflow_stages
               where workflow_id = t.workflow_id
                 and position > cur.position and position < nxt.position
                 and not (stage_group = any (side))
                 and stage_group <> 'revision' and not retired
               order by position loop
      perform public.ops_log(p_task, 'stage_skipped',
        jsonb_build_object('stage_key', sk.key), jsonb_build_object('stage_key', p_next),
        jsonb_build_object('reason', btrim(p_skip_reason)));
    end loop;
  end if;

  /* The round: how many times this task has now entered this review or
     this revision, counted off its own history, so nothing is stored that
     a reverted move could leave wrong. */
  if nxt.is_review or nxt.stage_group = 'revision' then
    select count(*) + 1 into v_round from public.ops_task_events e
     where e.task_id = p_task and e.event_type = 'stage_changed'
       and e.to_value ->> 'stage_key' = p_next;
  end if;

  update public.ops_tasks set
    stage_key = p_next,
    version = version + 1,
    updated_at = now(),
    first_draft_submitted_at = case
      when first_draft_submitted_at is null and nxt.is_review then now()
      else first_draft_submitted_at end,
    delivered_at = case when p_next = 'delivered' then coalesce(delivered_at, now())
                        else delivered_at end,
    completed_at = case when nxt.is_terminal and p_next <> 'cancelled' then coalesce(completed_at, now())
                        when not nxt.is_terminal then null
                        else completed_at end,
    /* Leaving Cancelled for a live stage is a reopening, and the stamp
       leaves with it, as completed_at does; left behind, the task went on
       reading cancelled at the stage it had been reopened to. */
    cancelled_at = case when p_next = 'cancelled' then coalesce(cancelled_at, now())
                        when not nxt.is_terminal then null
                        else cancelled_at end,
    blocked_at = case when p_next = 'blocked' then blocked_at else null end,
    blocked_category = case when p_next = 'blocked' then blocked_category else null end
  where id = p_task;

  /* The performance review brings its own checklist, the same five checks
     for a brand post and a KOC post, added once however often the task
     comes back to the stage. */
  if p_next = 'performance_review' then
    insert into public.ops_task_checklist_items (task_id, label, position, required)
    select p_task, x.label,
           coalesce((select max(c.position) from public.ops_task_checklist_items c
                      where c.task_id = p_task), 0) + x.n,
           true
      from (values (1, 'Reach and views checked'),
                   (2, 'Engagement checked (likes, comments, shares, saves)'),
                   (3, 'Comments checked for brand safety'),
                   (4, 'Leads or sales checked, where tracked'),
                   (5, 'Keep live or take down decided')) as x(n, label)
     where not exists (select 1 from public.ops_task_checklist_items c
                        where c.task_id = p_task and c.label = x.label);
  end if;

  /* A finished task is not being worked on, so every timer running on it
     stops with it, each filed as the stop it is. */
  if nxt.is_terminal then
    for ws in select * from public.ops_work_sessions
               where task_id = p_task and ended_at is null loop
      wmins := greatest(0, (extract(epoch from (now() - ws.started_at)) / 60)::integer);
      update public.ops_work_sessions set ended_at = now(), minutes = wmins where id = ws.id;
      perform public.ops_log(p_task, 'work_stopped', null,
        jsonb_build_object('session_id', ws.id, 'minutes', wmins),
        jsonb_build_object('note', 'Stopped when the task finished'));
    end loop;
  end if;

  perform public.ops_log(p_task, 'stage_changed',
    jsonb_build_object('stage_key', t.stage_key),
    jsonb_build_object('stage_key', p_next),
    (case when p_note is null then '{}'::jsonb else jsonb_build_object('note', p_note) end)
    || (case when skipping then jsonb_build_object('skip_reason', btrim(p_skip_reason)) else '{}'::jsonb end)
    || (case when going_back then jsonb_build_object('back', true) else '{}'::jsonb end)
    || (case when v_round is not null then jsonb_build_object('round', v_round) else '{}'::jsonb end));
  if p_next = 'delivered' then
    perform public.ops_log(p_task, 'delivered', null, null, '{}'::jsonb);
  end if;
  if nxt.is_terminal and p_next <> 'cancelled' then
    perform public.ops_log(p_task, 'completed', null, null, '{}'::jsonb);
  end if;
  if p_next = 'cancelled' then
    perform public.ops_log(p_task, 'cancelled', null, null,
      jsonb_build_object('reason', p_note));
  end if;
  return public.ops_task_json(p_task);
end $$;
grant execute on function public.ops_transition_task(uuid, text, integer, text, uuid, text) to authenticated;

-- END OF MONTH STAGES FOLLOW THE WORK --------------------------------------
-- ===========================================================================
-- THE CREATOR READS THE CLIENT'S NOTE — a request for changes made on the
-- client's page reaches the creator who has to act on it.
-- 2026-09-27. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/sql.js compares the two.
--
-- The client's Request changes files its note in `option_reviews`
-- (`review_draft`); `get_creator` read the note from `drop_reason`, which only
-- the team's own send-back fills, so the creator's page said "Please revise
-- as noted below" over nothing (reported by the user, 2026-09-27, with three
-- such requests on record). The note now comes from the client's latest
-- request where the round is theirs, and from `drop_reason` where the team
-- sent it back.
--
-- ROLLBACK
--   Re-run get_creator from its canonical section above.
-- ===========================================================================

create or replace function public.get_creator(p_code text)
returns jsonb
language plpgsql security definer stable set search_path = public as $$
declare
  cr creators%rowtype;
begin
  if p_code is null or length(trim(p_code)) < 8 then
    return jsonb_build_object('error', 'not-found');
  end if;
  select * into cr from creators
   where access_code = upper(regexp_replace(p_code, '[^A-Za-z0-9]', '', 'g'));
  if not found then return jsonb_build_object('error', 'not-found'); end if;
  if not cr.active then return jsonb_build_object('error', 'inactive'); end if;

  return jsonb_build_object(
    /* Who they are to us: the name the team keyed, since when, and the
       profile links the client's selection page opens, which they may keep
       up to date themselves. Never `client_rate`: that is the client's
       price, not theirs to read. */
    'creator', jsonb_build_object('name', cr.name, 'code', cr.access_code,
      'since', cr.created_at,
      'profiles', coalesce((
        select jsonb_agg(jsonb_build_object('platform', p.platform, 'handle', p.handle, 'url', p.url)
                         order by p.platform, p.url)
          from creator_profiles p where p.creator_id = cr.id), '[]'::jsonb)),
    'bookings', coalesce((
      select jsonb_agg(b order by b->>'sort')
      from (
        select jsonb_build_object(
          'id', o.id,
          'sort', coalesce(o.visit_date::text, '9999') || c.title,
          'campaign', c.title,
          'campaign_zh', c.title_zh,
          'brand', cl.name,
          'brief', c.brief,
          'brief_zh', c.brief_zh,
          'deliverable', c.deliverable,
          'push_format', c.push_format,
          'platforms', o.platforms,
          /* NO RATE, AND NO CURRENCY. `campaign_options.rate` is what the
             client is quoted for this booking and carries our markup, so it
             is not the creator's to read and is certainly not "their fee";
             what a creator is paid is agreed with them and claimed on AP01,
             which the page links to once the work is approved. `currency`
             existed only to format that one figure and names the client's
             market, which is a fact about the client. */
          'state', o.state,
          'visit_date', o.visit_date,
          'visit_time', o.visit_time,
          'visit_location', o.visit_location,
          'visit_pic', o.visit_pic,
          'visit_pic_phone', o.visit_pic_phone,
          'tracking_no', o.tracking_no,
          'submission_due', o.submission_due,
          'planned_publish', o.planned_publish,
          'revision_round', o.revision_round,
          /* The open request's note: the client's own, from their decision
             on their page, else the team's send-back (2026-09-27: the
             client's note reached nobody). */
          'change_note', case when o.state = 'changes' then
            case when coalesce(o.changes_by, 'client') = 'team' then o.drop_reason
                 else (select r.note from public.option_reviews r
                        where r.option_id = o.id and r.decision = 'changes'
                        order by r.created_at desc limit 1) end end,
          'caption', o.draft_caption,
          'submitted_at', o.submitted_at,
          'rating', o.creator_rating,
          'can_deliver', public.creator_can_deliver(o.state),
          'files', coalesce((
            select jsonb_agg(jsonb_build_object(
              'id', d.id, 'url', d.url, 'name', d.name, 'kind', d.kind,
              'bytes', d.bytes, 'round', d.round)
              order by d.uploaded_at)
            from campaign_deliverables d
             where d.option_id = o.id and d.removed_at is null), '[]'::jsonb)
        ) as b
        from campaign_options o
        join campaigns c on c.id = o.campaign_id
        join clients cl on cl.id = c.client_id
        where o.creator_id = cr.id
          and c.state <> 'draft'
          and o.state in ('confirmed', 'pending_visit', 'pending_delivery',
                          'pending_draft', 'submitted', 'reviewing', 'changes',
                          'scheduled', 'posted', 'completed', 'withdrawn', 'replaced')
      ) rows), '[]'::jsonb));
end $$;

grant execute on function public.get_creator(text) to anon, authenticated;

-- END OF THE CREATOR READS THE CLIENT'S NOTE ---------------------------------
-- ===========================================================================
-- THE REVIEW LOOP REACHES EVERYONE — a request for changes is read where it
-- is acted on, and one made by mistake can be taken back.
-- 2026-09-27. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/sql.js compares the two.
--
-- WHAT CHANGED (the user, 2026-09-27: "when client submitted changes, why is
-- the change comments from client portal are not shown inside"; "the problem
-- happens same in the admin portal too"; "revert for changes"):
--  1. Every decision on a draft is one row in `option_reviews`, whoever made
--     it: the client's (`review_draft`, `source` client) and the team's own
--     send-back (`campaign_send_back`, `source` team). The team's note lived
--     only in `drop_reason` and the console read neither; the client's
--     reached the creator only with the hotfix of the same day
--     (THE CREATOR READS THE CLIENT'S NOTE).
--  2. `get_creator` sends the open request's note from the record, from
--     either side and never one taken back (`drop_reason` still answers for
--     a team round sent back before this).
--  3. `get_campaign` counts the client's own rounds only, and never shows a
--     request that was taken back; a team round stays withheld as before.
--  4. `campaign_revert_changes` takes a request back. The client's goes back
--     to Client review on the round that was checked and released to them,
--     refused once the creator has handed in new files (they would reach the
--     client unchecked); the team's goes back to Submitted. The request stays
--     on the record as taken back (`undone_at`, `undone_by`). A direct move
--     into Client review from Changes requested was refused by the release
--     gate, because the client's request moves the round the check counts.
--
-- ROLLBACK
--   drop function if exists public.campaign_send_back(uuid, text);
--   drop function if exists public.campaign_revert_changes(uuid);
--   Re-run get_creator and get_campaign from their canonical sections above.
--   alter table public.option_reviews drop constraint if exists option_reviews_source_check;
--   alter table public.option_reviews drop column if exists source,
--     drop column if exists undone_at, drop column if exists undone_by;
-- ===========================================================================

alter table public.option_reviews add column if not exists source text not null default 'client';
alter table public.option_reviews add column if not exists undone_at timestamptz;
alter table public.option_reviews add column if not exists undone_by uuid references public.team_members(id);
do $$ begin
  alter table public.option_reviews add constraint option_reviews_source_check
    check (source in ('client', 'team'));
exception when duplicate_object then null;
end $$;

create or replace function public.get_campaign(p_token text, p_passcode text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  c campaigns%rowtype;
  cl clients%rowtype;
  billable boolean;
begin
  select * into c from campaigns where access_token = p_token;
  if not found then return jsonb_build_object('error', 'not-found'); end if;
  select * into cl from clients where id = c.client_id;

  -- An invoice belongs to an accepted booking. Until the client has chosen and
  -- the team has confirmed at least one creator, the number and the PDF stay
  -- off the client's page, and reverting the last confirmation takes them off
  -- it again. The gate is here rather than on the page so nothing the client
  -- can open carries what it should not show.
  select exists (
    select 1 from campaign_options o
     where o.campaign_id = c.id
       and o.state in ('confirmed', 'pending_visit', 'pending_draft', 'submitted',
                       'reviewing', 'changes', 'scheduled', 'posted', 'completed')
  ) into billable;

  if c.passcode is not null and c.passcode <> '' then
    if p_passcode is null or p_passcode <> c.passcode then
      return jsonb_build_object('error', 'passcode', 'client', cl.name);
    end if;
  end if;

  return jsonb_build_object(
    'campaign', jsonb_build_object(
      'title', c.title, 'title_zh', c.title_zh,
      'purpose', c.purpose, 'purpose_zh', c.purpose_zh, 'slots', c.slots,
      'backups_open', coalesce(c.backups_open, false),
      'deadline', c.deadline, 'state', c.state, 'deliverable', c.deliverable,
      'push_format', c.push_format, 'brief', c.brief, 'brief_zh', c.brief_zh,
      'invoice_no', case when billable then c.invoice_no end,
      'invoice_url', case when billable then c.invoice_url end),
    -- Currency and tax travel with the campaign, because the client's page
    -- prints both and must not assume Malaysia.
    'client', jsonb_build_object('name', cl.name, 'logo_url', cl.logo_url,
      'market', coalesce(cl.market, 'MY'), 'sst_applies', coalesce(cl.sst_applies, true)),
    /* A draft reaches the client when the team releases it, and not a moment
       before. `submitted` is the team's own step, so it is reported as
       `pending_draft`: the client is not asked to approve something they
       cannot open, and does not learn that a round exists. A `changes` the
       team raised is the same round going back to the creator, so it is
       withheld the same way; a `changes` the client raised is their own and
       is reported as it is. The mapping is here and not on the page, because
       what a client may not see is withheld by this function. */
    'options', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', o.id, 'name', cr.name,
        'rate', o.rate, 'platforms', o.platforms, 'state', s.shown,
        'is_replacement', o.is_replacement, 'added_at', o.added_at,
        -- Production. Present once a creator is locked; null before that, so
        -- the page can tell "not started" from "nothing to say".
        'visit_date', o.visit_date, 'visit_time', o.visit_time,
        'visit_location', o.visit_location, 'visit_pic', o.visit_pic,
        'visit_pic_phone', o.visit_pic_phone, 'tracking_no', o.tracking_no,
        'draft_url', case when s.released then o.draft_url end,
        /* The client's own rounds: a round the team sent back, or a request
           taken back, is not one the client made (2026-09-27). */
        'revision_round', (select count(*) from public.option_reviews r
                            where r.option_id = o.id and r.source = 'client'
                              and r.decision = 'changes' and r.undone_at is null)::int + 1,
        'planned_publish', o.planned_publish,
        /* What the creator uploaded, once it has been released: the newest
           round handed in, which at `changes` is the one the client turned
           down and wants to refer back to. Never the round sitting with the
           team. */
        'files', case when s.released then coalesce((
            select jsonb_agg(jsonb_build_object(
              'id', d.id, 'url', d.url, 'name', d.name, 'kind', d.kind,
              'bytes', d.bytes) order by d.uploaded_at)
            from campaign_deliverables d
            where d.option_id = o.id and d.removed_at is null
              and d.round = (select max(d2.round) from campaign_deliverables d2
                             where d2.option_id = o.id and d2.removed_at is null)
          ), '[]'::jsonb) else '[]'::jsonb end,
        -- The caption is part of what is being approved, so it travels with
        -- the files and is withheld with them.
        'caption', case when s.released then o.draft_caption end,
        'profiles', coalesce((
          select jsonb_agg(jsonb_build_object('platform', p.platform, 'url', p.url))
          from creator_profiles p where p.creator_id = cr.id), '[]'::jsonb),
        -- One row per platform posted on, so two placements stay two numbers.
        'posts', coalesce((
          select jsonb_agg(jsonb_build_object(
            'platform', pp.platform, 'post_url', pp.post_url,
            'published_at', pp.published_at, 'window_days', pp.window_days,
            'impressions', pp.impressions, 'engagements', pp.engagements,
            'views', pp.views, 'measured_at', pp.measured_at) order by pp.platform)
          from option_posts pp where pp.option_id = o.id), '[]'::jsonb),
        /* What the client last decided, so the card can say who approved it
           and when rather than jumping to the next step with nothing to show
           for the decision. Withheld with the draft it is about. */
        'review', case when s.released then (
            select jsonb_build_object('decision', r.decision, 'reviewer', r.reviewer,
                                      'note', r.note, 'at', r.created_at)
            from option_reviews r where r.option_id = o.id
              and r.source = 'client' and r.undone_at is null
            order by r.created_at desc limit 1) end)
        order by o.position, o.added_at)
      from campaign_options o
      join creators cr on cr.id = o.creator_id
      cross join lateral (
        select sh.shown,
               sh.shown in ('reviewing', 'changes', 'scheduled', 'posted', 'completed')
                 as released
        from (select case
                       when o.state = 'submitted' then 'pending_draft'
                       when o.state = 'changes'
                            and coalesce(o.changes_by, 'client') = 'team' then 'pending_draft'
                       else o.state
                     end as shown) sh
      ) s
      where o.campaign_id = c.id and o.state <> 'replaced'), '[]'::jsonb)
  );
end $$;

create or replace function public.get_creator(p_code text)
returns jsonb
language plpgsql security definer stable set search_path = public as $$
declare
  cr creators%rowtype;
begin
  if p_code is null or length(trim(p_code)) < 8 then
    return jsonb_build_object('error', 'not-found');
  end if;
  select * into cr from creators
   where access_code = upper(regexp_replace(p_code, '[^A-Za-z0-9]', '', 'g'));
  if not found then return jsonb_build_object('error', 'not-found'); end if;
  if not cr.active then return jsonb_build_object('error', 'inactive'); end if;

  return jsonb_build_object(
    /* Who they are to us: the name the team keyed, since when, and the
       profile links the client's selection page opens, which they may keep
       up to date themselves. Never `client_rate`: that is the client's
       price, not theirs to read. */
    'creator', jsonb_build_object('name', cr.name, 'code', cr.access_code,
      'since', cr.created_at,
      'profiles', coalesce((
        select jsonb_agg(jsonb_build_object('platform', p.platform, 'handle', p.handle, 'url', p.url)
                         order by p.platform, p.url)
          from creator_profiles p where p.creator_id = cr.id), '[]'::jsonb)),
    'bookings', coalesce((
      select jsonb_agg(b order by b->>'sort')
      from (
        select jsonb_build_object(
          'id', o.id,
          'sort', coalesce(o.visit_date::text, '9999') || c.title,
          'campaign', c.title,
          'campaign_zh', c.title_zh,
          'brand', cl.name,
          'brief', c.brief,
          'brief_zh', c.brief_zh,
          'deliverable', c.deliverable,
          'push_format', c.push_format,
          'platforms', o.platforms,
          /* NO RATE, AND NO CURRENCY. `campaign_options.rate` is what the
             client is quoted for this booking and carries our markup, so it
             is not the creator's to read and is certainly not "their fee";
             what a creator is paid is agreed with them and claimed on AP01,
             which the page links to once the work is approved. `currency`
             existed only to format that one figure and names the client's
             market, which is a fact about the client. */
          'state', o.state,
          'visit_date', o.visit_date,
          'visit_time', o.visit_time,
          'visit_location', o.visit_location,
          'visit_pic', o.visit_pic,
          'visit_pic_phone', o.visit_pic_phone,
          'tracking_no', o.tracking_no,
          'submission_due', o.submission_due,
          'planned_publish', o.planned_publish,
          'revision_round', o.revision_round,
          /* The open request's note, whoever made it: the client's through
             their page, the team's through the send-back (2026-09-27). A
             team round sent back before the record held it is in
             `drop_reason`. */
          'change_note', case when o.state = 'changes' then coalesce(
            (select r.note from public.option_reviews r
              where r.option_id = o.id and r.decision = 'changes' and r.undone_at is null
                and r.source = case when coalesce(o.changes_by, 'client') = 'team' then 'team' else 'client' end
              order by r.created_at desc limit 1),
            case when o.changes_by = 'team' then o.drop_reason end) end,
          'caption', o.draft_caption,
          'submitted_at', o.submitted_at,
          'rating', o.creator_rating,
          'can_deliver', public.creator_can_deliver(o.state),
          'files', coalesce((
            select jsonb_agg(jsonb_build_object(
              'id', d.id, 'url', d.url, 'name', d.name, 'kind', d.kind,
              'bytes', d.bytes, 'round', d.round)
              order by d.uploaded_at)
            from campaign_deliverables d
             where d.option_id = o.id and d.removed_at is null), '[]'::jsonb)
        ) as b
        from campaign_options o
        join campaigns c on c.id = o.campaign_id
        join clients cl on cl.id = c.client_id
        where o.creator_id = cr.id
          and c.state <> 'draft'
          and o.state in ('confirmed', 'pending_visit', 'pending_delivery',
                          'pending_draft', 'submitted', 'reviewing', 'changes',
                          'scheduled', 'posted', 'completed', 'withdrawn', 'replaced')
      ) rows), '[]'::jsonb));
end $$;

revoke all on function public.get_campaign(text, text) from public;
grant execute on function public.get_campaign(text, text) to anon, authenticated;
grant execute on function public.get_creator(text) to anon, authenticated;

/* The team's own send-back: the draft goes back to the creator with what to
   change, on the record beside the client's decisions, and the check starts
   again on the next round. The client's page never learns of it. */
create or replace function public.campaign_send_back(p_option uuid, p_note text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me     public.team_members;
  o      public.campaign_options;
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
  v_n    integer;
begin
  if not public.allowed('campaigns.campaigns', 'work') then
    return jsonb_build_object('error', 'denied');
  end if;
  select * into me from public.ops_me();
  if me.id is null then return jsonb_build_object('error', 'denied'); end if;
  if v_note is null then return jsonb_build_object('error', 'note-required'); end if;
  select * into o from public.campaign_options where id = p_option for update;
  if o.id is null then return jsonb_build_object('error', 'no-booking'); end if;
  if o.state <> 'submitted' then return jsonb_build_object('error', 'not-submitted'); end if;
  v_n := greatest(coalesce(o.revision_round, 0), 1);
  insert into public.option_reviews (option_id, round, decision, note, reviewer, source)
  values (p_option, v_n, 'changes', v_note, me.name, 'team');
  update public.campaign_options
     set state = 'changes', changes_by = 'team', revision_round = v_n + 1,
         qc_second_wanted = false
   where id = p_option;
  return jsonb_build_object('ok', true, 'round', v_n + 1);
end $$;
revoke all on function public.campaign_send_back(uuid, text) from public, anon;
grant execute on function public.campaign_send_back(uuid, text) to authenticated;

/* Taking a request for changes back. The client's goes back to Client review
   on the round that was checked and released to them, which is the round the
   release gate counts; it is refused once the creator has handed in files
   for the next round, because Client review would show them unchecked. The
   team's goes back to Submitted. Either way the request stays on the record,
   marked taken back. */
create or replace function public.campaign_revert_changes(p_option uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me      public.team_members;
  o       public.campaign_options;
  v_rv    uuid;
  v_team  boolean;
  v_round integer;
begin
  if not public.allowed('campaigns.campaigns', 'work') then
    return jsonb_build_object('error', 'denied');
  end if;
  select * into me from public.ops_me();
  if me.id is null then return jsonb_build_object('error', 'denied'); end if;
  select * into o from public.campaign_options where id = p_option for update;
  if o.id is null then return jsonb_build_object('error', 'no-booking'); end if;
  if o.state <> 'changes' then return jsonb_build_object('error', 'not-changes'); end if;
  v_team := coalesce(o.changes_by, 'client') = 'team';
  select r.id into v_rv from public.option_reviews r
   where r.option_id = p_option and r.decision = 'changes' and r.undone_at is null
     and r.source = case when v_team then 'team' else 'client' end
   order by r.created_at desc limit 1;
  if v_team then
    update public.campaign_options set state = 'submitted', changes_by = null
     where id = p_option;
  else
    select max(q.round) into v_round from public.option_qc q where q.option_id = p_option;
    if v_round is null then return jsonb_build_object('error', 'qc-required'); end if;
    if exists (select 1 from public.campaign_deliverables d
                where d.option_id = p_option and d.removed_at is null
                  and d.round > greatest(v_round, 1)) then
      return jsonb_build_object('error', 'new-files');
    end if;
    /* The round first, then the state: the gate reads the row as it stands,
       so it has to find the checked round there before the move. */
    update public.campaign_options set revision_round = v_round where id = p_option;
    update public.campaign_options set state = 'reviewing', changes_by = null
     where id = p_option;
  end if;
  if v_rv is not null then
    update public.option_reviews set undone_at = now(), undone_by = me.id where id = v_rv;
  end if;
  return jsonb_build_object('ok', true, 'state', case when v_team then 'submitted' else 'reviewing' end);
end $$;
revoke all on function public.campaign_revert_changes(uuid) from public, anon;
grant execute on function public.campaign_revert_changes(uuid) to authenticated;

-- END OF THE REVIEW LOOP REACHES EVERYONE ----------------------------------
-- ===========================================================================

-- ===========================================================================
-- THE TEAM DECIDES APPROVAL AND SELECTION — a draft the client agreed to by
-- word of mouth is approved from the console, and the client's selection
-- closes when the slots are full until the team reopens it.
-- 2026-09-27. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/sql.js compares the two.
--
-- WHAT CHANGED (the user, 2026-09-27: "add one Confirm internally button for
-- the creator draft (even after revisions) so sometimes if clients never
-- response but once we got their verbal comms or confirmation, we could
-- proceeded to approve internally. Client-facing side will show Proceed by
-- {internal user} {timestamp}"; and on selection: "Only when slots opens up
-- (not 100% filled, either replaced / withdrawn / added more slots cases)
-- and clicking of reopen selection only then the not selected ones show up"):
--  1. `campaign_proceed` approves a draft at Client review on the client's
--     behalf: one row in `option_reviews` (`source` team, decision approved,
--     the colleague's name), and the booking moves to Scheduled. Campaigns
--     Work, as every other step on the card.
--  2. `campaign_revert_approval` takes an approval back, the client's or the
--     team's: the booking goes back to Client review and the approval stays
--     on the record, taken back (`undone_at`, `undone_by`).
--  3. `campaigns.selection_closed_at` is stamped by trigger the moment the
--     bookings fill the slots (a booking moving, or the slots lowered), and
--     only the team clears it (Reopen selection). While it is set the client
--     chooses nothing: `save_selection` and `confirm_selection` refuse
--     (`closed`), except for backups where the team opened them and every
--     slot is taken. A campaign already full is closed once, by this file.
--  4. `get_campaign` sends the team's approval as the last decision
--     (`by_team`), so the client's page reads "Proceeded by {name}", and
--     whether selection is closed. A team send-back is still withheld, and a
--     team row never carries its note.
--
-- ROLLBACK
--   drop trigger if exists campaign_options_selection_close on public.campaign_options;
--   drop trigger if exists campaigns_selection_slots on public.campaigns;
--   drop function if exists public.campaign_selection_close();
--   drop function if exists public.campaigns_selection_slots();
--   drop function if exists public.campaign_booked(uuid);
--   drop function if exists public.campaign_proceed(uuid);
--   drop function if exists public.campaign_revert_approval(uuid);
--   Re-run get_campaign from THE REVIEW LOOP REACHES EVERYONE, and
--   save_selection and confirm_selection from their canonical sections.
--   alter table public.campaigns drop column if exists selection_closed_at;
-- ===========================================================================

alter table public.campaigns add column if not exists selection_closed_at timestamptz;

/* The bookings holding a slot: every step from Confirmed on. */
create or replace function public.campaign_booked(p_campaign uuid)
returns integer
language sql stable security definer set search_path = public as $$
  select count(*)::int from public.campaign_options o
   where o.campaign_id = p_campaign
     and o.state in ('confirmed', 'pending_visit', 'pending_draft', 'submitted',
                     'reviewing', 'changes', 'scheduled', 'posted', 'completed')
$$;
revoke all on function public.campaign_booked(uuid) from public, anon;
grant execute on function public.campaign_booked(uuid) to authenticated;

/* The last slot filled closes the selection. A slot freed later does not open
   it again: that is the team's call (Reopen selection). */
create or replace function public.campaign_selection_close()
returns trigger
language plpgsql security definer set search_path = public as $$
begin
  update public.campaigns c set selection_closed_at = now()
   where c.id = new.campaign_id and c.selection_closed_at is null
     and coalesce(c.slots, 0) > 0 and public.campaign_booked(c.id) >= c.slots;
  return null;
end $$;
drop trigger if exists campaign_options_selection_close on public.campaign_options;
create trigger campaign_options_selection_close
  after insert or update of state on public.campaign_options
  for each row execute function public.campaign_selection_close();

create or replace function public.campaigns_selection_slots()
returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.selection_closed_at is null and coalesce(new.slots, 0) > 0
     and public.campaign_booked(new.id) >= new.slots then
    new.selection_closed_at := now();
  end if;
  return new;
end $$;
drop trigger if exists campaigns_selection_slots on public.campaigns;
create trigger campaigns_selection_slots
  before update of slots on public.campaigns
  for each row execute function public.campaigns_selection_slots();

update public.campaigns set selection_closed_at = now()
 where selection_closed_at is null and coalesce(slots, 0) > 0
   and public.campaign_booked(id) >= slots;

create or replace function public.get_campaign(p_token text, p_passcode text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  c campaigns%rowtype;
  cl clients%rowtype;
  billable boolean;
begin
  select * into c from campaigns where access_token = p_token;
  if not found then return jsonb_build_object('error', 'not-found'); end if;
  select * into cl from clients where id = c.client_id;

  -- An invoice belongs to an accepted booking. Until the client has chosen and
  -- the team has confirmed at least one creator, the number and the PDF stay
  -- off the client's page, and reverting the last confirmation takes them off
  -- it again. The gate is here rather than on the page so nothing the client
  -- can open carries what it should not show.
  select exists (
    select 1 from campaign_options o
     where o.campaign_id = c.id
       and o.state in ('confirmed', 'pending_visit', 'pending_draft', 'submitted',
                       'reviewing', 'changes', 'scheduled', 'posted', 'completed')
  ) into billable;

  if c.passcode is not null and c.passcode <> '' then
    if p_passcode is null or p_passcode <> c.passcode then
      return jsonb_build_object('error', 'passcode', 'client', cl.name);
    end if;
  end if;

  return jsonb_build_object(
    'campaign', jsonb_build_object(
      'title', c.title, 'title_zh', c.title_zh,
      'purpose', c.purpose, 'purpose_zh', c.purpose_zh, 'slots', c.slots,
      'backups_open', coalesce(c.backups_open, false),
      'selection_closed', c.selection_closed_at is not null,
      'deadline', c.deadline, 'state', c.state, 'deliverable', c.deliverable,
      'push_format', c.push_format, 'brief', c.brief, 'brief_zh', c.brief_zh,
      'invoice_no', case when billable then c.invoice_no end,
      'invoice_url', case when billable then c.invoice_url end),
    -- Currency and tax travel with the campaign, because the client's page
    -- prints both and must not assume Malaysia.
    'client', jsonb_build_object('name', cl.name, 'logo_url', cl.logo_url,
      'market', coalesce(cl.market, 'MY'), 'sst_applies', coalesce(cl.sst_applies, true)),
    /* A draft reaches the client when the team releases it, and not a moment
       before. `submitted` is the team's own step, so it is reported as
       `pending_draft`: the client is not asked to approve something they
       cannot open, and does not learn that a round exists. A `changes` the
       team raised is the same round going back to the creator, so it is
       withheld the same way; a `changes` the client raised is their own and
       is reported as it is. The mapping is here and not on the page, because
       what a client may not see is withheld by this function. */
    'options', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', o.id, 'name', cr.name,
        'rate', o.rate, 'platforms', o.platforms, 'state', s.shown,
        'is_replacement', o.is_replacement, 'added_at', o.added_at,
        -- Production. Present once a creator is locked; null before that, so
        -- the page can tell "not started" from "nothing to say".
        'visit_date', o.visit_date, 'visit_time', o.visit_time,
        'visit_location', o.visit_location, 'visit_pic', o.visit_pic,
        'visit_pic_phone', o.visit_pic_phone, 'tracking_no', o.tracking_no,
        'draft_url', case when s.released then o.draft_url end,
        /* The client's own rounds: a round the team sent back, or a request
           taken back, is not one the client made (2026-09-27). */
        'revision_round', (select count(*) from public.option_reviews r
                            where r.option_id = o.id and r.source = 'client'
                              and r.decision = 'changes' and r.undone_at is null)::int + 1,
        'planned_publish', o.planned_publish,
        /* What the creator uploaded, once it has been released: the newest
           round handed in, which at `changes` is the one the client turned
           down and wants to refer back to. Never the round sitting with the
           team. */
        'files', case when s.released then coalesce((
            select jsonb_agg(jsonb_build_object(
              'id', d.id, 'url', d.url, 'name', d.name, 'kind', d.kind,
              'bytes', d.bytes) order by d.uploaded_at)
            from campaign_deliverables d
            where d.option_id = o.id and d.removed_at is null
              and d.round = (select max(d2.round) from campaign_deliverables d2
                             where d2.option_id = o.id and d2.removed_at is null)
          ), '[]'::jsonb) else '[]'::jsonb end,
        -- The caption is part of what is being approved, so it travels with
        -- the files and is withheld with them.
        'caption', case when s.released then o.draft_caption end,
        'profiles', coalesce((
          select jsonb_agg(jsonb_build_object('platform', p.platform, 'url', p.url))
          from creator_profiles p where p.creator_id = cr.id), '[]'::jsonb),
        -- One row per platform posted on, so two placements stay two numbers.
        'posts', coalesce((
          select jsonb_agg(jsonb_build_object(
            'platform', pp.platform, 'post_url', pp.post_url,
            'published_at', pp.published_at, 'window_days', pp.window_days,
            'impressions', pp.impressions, 'engagements', pp.engagements,
            'views', pp.views, 'measured_at', pp.measured_at) order by pp.platform)
          from option_posts pp where pp.option_id = o.id), '[]'::jsonb),
        /* What was last decided, so the card can say who approved it and
           when rather than jumping to the next step with nothing to show for
           the decision. The client's own decisions, and an approval the team
           gave on the client's behalf (`by_team`, read "Proceeded by"); a
           team send-back stays withheld. Withheld with the draft it is about. */
        'review', case when s.released then (
            select jsonb_build_object('decision', r.decision, 'reviewer', r.reviewer,
                                      'note', case when r.source = 'client' then r.note end,
                                      'at', r.created_at, 'by_team', r.source = 'team')
            from option_reviews r where r.option_id = o.id
              and (r.source = 'client' or r.decision = 'approved') and r.undone_at is null
            order by r.created_at desc limit 1) end)
        order by o.position, o.added_at)
      from campaign_options o
      join creators cr on cr.id = o.creator_id
      cross join lateral (
        select sh.shown,
               sh.shown in ('reviewing', 'changes', 'scheduled', 'posted', 'completed')
                 as released
        from (select case
                       when o.state = 'submitted' then 'pending_draft'
                       when o.state = 'changes'
                            and coalesce(o.changes_by, 'client') = 'team' then 'pending_draft'
                       else o.state
                     end as shown) sh
      ) s
      where o.campaign_id = c.id and o.state <> 'replaced'), '[]'::jsonb)
  );
end $$;

revoke all on function public.get_campaign(text, text) from public;
grant execute on function public.get_campaign(text, text) to anon, authenticated;

create or replace function public.save_selection(
  p_token text, p_selected uuid[], p_backup uuid[], p_passcode text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  c campaigns%rowtype;
  n integer;
begin
  select * into c from campaigns where access_token = p_token;
  if not found then return jsonb_build_object('error', 'not-found'); end if;
  if c.passcode is not null and c.passcode <> ''
     and (p_passcode is null or p_passcode <> c.passcode) then
    return jsonb_build_object('error', 'passcode');
  end if;

  n := coalesce(array_length(p_selected, 1), 0);
  /* Closed once the slots were full, until the team reopens it; backups
     alone may still be named where the team opened them. */
  if c.selection_closed_at is not null and not (coalesce(c.backups_open, false) and n = 0) then
    return jsonb_build_object('error', 'closed');
  end if;
  if n > c.slots then
    return jsonb_build_object('error', 'over-slots', 'slots', c.slots);
  end if;

  -- Anything already confirmed or further along is the team's to change.
  update campaign_options set state = 'option'
   where campaign_id = c.id and state in ('shortlisted', 'backup');

  if n > 0 then
    update campaign_options set state = 'shortlisted'
     where campaign_id = c.id and id = any(p_selected) and state = 'option';
  end if;
  -- Only where the team opened them: the page hides the control, and this is
  -- what makes that a fact rather than a courtesy.
  if coalesce(c.backups_open, false) and coalesce(array_length(p_backup, 1), 0) > 0 then
    update campaign_options set state = 'backup'
     where campaign_id = c.id and id = any(p_backup) and state = 'option';
  end if;

  return jsonb_build_object('ok', true, 'selected', n);
end $$;


create or replace function public.confirm_selection(
  p_token text, p_person text, p_passcode text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  c campaigns%rowtype;
begin
  select * into c from campaigns where access_token = p_token;
  if not found then return jsonb_build_object('error', 'not-found'); end if;
  if c.passcode is not null and c.passcode <> ''
     and (p_passcode is null or p_passcode <> c.passcode) then
    return jsonb_build_object('error', 'passcode');
  end if;
  if coalesce(trim(p_person), '') = '' then
    return jsonb_build_object('error', 'name-required');
  end if;
  if c.selection_closed_at is not null and not coalesce(c.backups_open, false) then
    return jsonb_build_object('error', 'closed');
  end if;

  insert into campaign_confirmations (campaign_id, kind, person, source)
  values (c.id, 'client', trim(p_person), 'portal');

  /* Logged here and not in `save_selection`: that one fires on every tick as
     an autosave, and a record full of half-made selections is a record nobody
     can read. This is the commitment, and it is the one that carries a name. */
  insert into public.activity_log (actor, action, subject, detail)
  values (trim(p_person), 'campaign.confirmed', c.title,
          (select count(*)::text || ' creator' || case when count(*) = 1 then '' else 's' end
             from campaign_options
            where campaign_id = c.id and state = 'shortlisted') || ' confirmed');

  return jsonb_build_object('ok', true);
end $$;

revoke all on function public.save_selection(text, uuid[], uuid[], text) from public;
revoke all on function public.confirm_selection(text, text, text) from public;
grant execute on function public.save_selection(text, uuid[], uuid[], text) to anon, authenticated;
grant execute on function public.confirm_selection(text, text, text) to anon, authenticated;

create or replace function public.campaign_proceed(p_option uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me  public.team_members;
  o   public.campaign_options;
  v_n integer;
begin
  if not public.allowed('campaigns.campaigns', 'work') then
    return jsonb_build_object('error', 'denied');
  end if;
  select * into me from public.ops_me();
  if me.id is null then return jsonb_build_object('error', 'denied'); end if;
  select * into o from public.campaign_options where id = p_option for update;
  if o.id is null then return jsonb_build_object('error', 'no-booking'); end if;
  if o.state <> 'reviewing' then return jsonb_build_object('error', 'not-reviewing'); end if;
  v_n := greatest(coalesce(o.revision_round, 0), 1);
  insert into public.option_reviews (option_id, round, decision, note, reviewer, source)
  values (p_option, v_n, 'approved', null, me.name, 'team');
  update public.campaign_options set state = 'scheduled', changes_by = null
   where id = p_option;
  return jsonb_build_object('ok', true, 'reviewer', me.name);
end $$;
revoke all on function public.campaign_proceed(uuid) from public, anon;
grant execute on function public.campaign_proceed(uuid) to authenticated;

create or replace function public.campaign_revert_approval(p_option uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me   public.team_members;
  o    public.campaign_options;
  v_rv uuid;
begin
  if not public.allowed('campaigns.campaigns', 'work') then
    return jsonb_build_object('error', 'denied');
  end if;
  select * into me from public.ops_me();
  if me.id is null then return jsonb_build_object('error', 'denied'); end if;
  select * into o from public.campaign_options where id = p_option for update;
  if o.id is null then return jsonb_build_object('error', 'no-booking'); end if;
  if o.state <> 'scheduled' then return jsonb_build_object('error', 'not-scheduled'); end if;
  select r.id into v_rv from public.option_reviews r
   where r.option_id = p_option and r.decision = 'approved' and r.undone_at is null
   order by r.created_at desc limit 1;
  update public.campaign_options set state = 'reviewing' where id = p_option;
  if v_rv is not null then
    update public.option_reviews set undone_at = now(), undone_by = me.id where id = v_rv;
  end if;
  return jsonb_build_object('ok', true, 'state', 'reviewing');
end $$;
revoke all on function public.campaign_revert_approval(uuid) from public, anon;
grant execute on function public.campaign_revert_approval(uuid) to authenticated;

-- END OF THE TEAM DECIDES APPROVAL AND SELECTION ---------------------------
-- ===========================================================================
-- TASKS LINK RECORDS — a task names the Creator Campaign or content set it
-- is for, and that record lists the tasks that name it.
-- 2026-09-27. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/ops.js compares the two.
--
-- WHAT CHANGED (the user, 2026-09-27: "for files and links is it possible to
-- add one more inside, link to which creator campaigns or content reviews
-- etc. it works like a backlinks kind"):
--  1. A link on a task may name a record instead of an address: `ref_type`
--     (campaign, set) and `ref_id`, kind `record`. The label is the record's
--     title when it was linked and the address is its console route; the
--     page reads the title again when it draws the link.
--  2. `ops_link_record` links one, at My Work's Work level, only a record of
--     the task's own client and only once while the link stands. Removing
--     it is `ops_set_link_archived`, with its Undo, as for any link.
--  3. Both sides are filed: the task's own log (Link added, removed,
--     restored), and the Activity record under the campaign
--     (`campaign.task_linked`, `campaign.task_unlinked`) or the set
--     (`set.task_linked`, `set.task_unlinked`).
--  4. `ops_record_tasks` is the backlink list: the tasks linking a record
--     that the caller may see, with the stage, owner and final date. It
--     answers only a person who may read the record's own section.
--  5. `ops_update_link` refuses a record link (`record-link`): a record is
--     unlinked and linked again, never retyped as an address.
--
-- ROLLBACK
--   drop function if exists public.ops_link_record(uuid, text, uuid, integer);
--   drop function if exists public.ops_record_tasks(text, uuid);
--   Re-run ops_set_link_archived (operations phase 2) and ops_update_link
--   (operations phase 4) from their canonical sections above, and
--   activity_section from 2026-09-27-two-tags-filed.sql.
--   drop index if exists public.ops_links_ref_idx;
--   alter table public.ops_task_links drop constraint if exists ops_task_links_ref_check;
--   alter table public.ops_task_links drop column if exists ref_type,
--     drop column if exists ref_id;
-- ===========================================================================

alter table public.ops_task_links add column if not exists ref_type text;
alter table public.ops_task_links add column if not exists ref_id uuid;
do $$ begin
  alter table public.ops_task_links add constraint ops_task_links_ref_check
    check ((ref_type is null and ref_id is null)
        or (ref_type in ('campaign', 'set') and ref_id is not null and kind = 'record'));
exception when duplicate_object then null;
end $$;
create index if not exists ops_links_ref_idx
  on public.ops_task_links(ref_type, ref_id) where archived_at is null;

/* What a record is called and where it lives, read the same way by the
   link, the unlink and the record's own Activity. `null` where the record is
   gone. */
create or replace function public.ops_ref_of(p_type text, p_ref uuid)
returns jsonb
language sql stable security definer set search_path = public as $$
  select case p_type
    when 'campaign' then (
      select jsonb_build_object(
               'client_id', c.client_id,
               'title', coalesce(nullif(btrim(c.title), ''), 'Untitled campaign'),
               'subject', coalesce(c.title, ''),
               'url', '/admin/?s=campaigns&campaign=' || c.id::text)
        from public.campaigns c where c.id = p_ref)
    when 'set' then (
      select jsonb_build_object(
               'client_id', b.client_id,
               'title', coalesce(nullif(btrim(b.title), ''), 'Content set'),
               'subject', coalesce(cl.name, '') || ' — ' || coalesce(b.title, ''),
               'url', '/admin/?s=review&client=' || coalesce(nullif(cl.slug, ''), cl.id::text)
                      || '&set=' || b.id::text)
        from public.batches b left join public.clients cl on cl.id = b.client_id
       where b.id = p_ref)
  end
$$;
revoke all on function public.ops_ref_of(text, uuid) from public, anon, authenticated;

/* Both sides of one link filed at once: the task's own log in the words
   every link uses, and the record's Activity naming the task. */
create or replace function public.ops_ref_file(
  p_link public.ops_task_links, p_act text)
returns void
language plpgsql security definer set search_path = public as $$
declare
  v_ref jsonb := public.ops_ref_of(p_link.ref_type, p_link.ref_id);
  v_t   public.ops_tasks;
  v_me  public.team_members := public.ops_me();
begin
  select * into v_t from public.ops_tasks where id = p_link.task_id;
  perform public.ops_log(p_link.task_id,
    case p_act when 'linked' then 'file_added' when 'unlinked' then 'file_removed' else 'file_restored' end,
    null,
    jsonb_build_object('link_id', p_link.id, 'kind', 'record', 'ref_type', p_link.ref_type,
                       'label', coalesce(v_ref->>'title', p_link.label)),
    '{}'::jsonb);
  if v_ref is null then return; end if;
  insert into public.activity_log (actor, action, subject, detail)
  values (coalesce(v_me.email, v_me.name),
          p_link.ref_type || case when p_act = 'unlinked' then '.task_unlinked' else '.task_linked' end,
          v_ref->>'subject',
          public.ops_serial(v_t.task_no) || ' · ' || public.ops_title(v_t));
end $$;
revoke all on function public.ops_ref_file(public.ops_task_links, text) from public, anon, authenticated;

create or replace function public.ops_link_record(
  p_task uuid, p_type text, p_ref uuid, p_version integer default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me  public.team_members;
  v_t   public.ops_tasks;
  v_ref jsonb;
  v_l   public.ops_task_links;
begin
  v_me := public.ops_me();
  if v_me.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if not public.ops_may_see_task(p_task) then return jsonb_build_object('error', 'denied'); end if;
  if not public.allowed('ops', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if p_type is null or p_type not in ('campaign', 'set') then
    return jsonb_build_object('error', 'bad-kind');
  end if;
  select * into v_t from public.ops_tasks where id = p_task for update;
  if v_t.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if p_version is not null and p_version <> v_t.version then
    return jsonb_build_object('error', 'stale', 'task', public.ops_task_json(p_task));
  end if;
  v_ref := public.ops_ref_of(p_type, p_ref);
  if v_ref is null then return jsonb_build_object('error', 'record-not-found'); end if;
  if v_t.client_id is null or (v_ref->>'client_id') is null
     or (v_ref->>'client_id')::uuid <> v_t.client_id then
    return jsonb_build_object('error', 'other-client');
  end if;
  select * into v_l from public.ops_task_links k
   where k.task_id = p_task and k.ref_type = p_type and k.ref_id = p_ref and k.archived_at is null
   limit 1;
  if v_l.id is not null then
    return jsonb_build_object('link_id', v_l.id, 'already', true, 'task', public.ops_task_json(p_task));
  end if;

  insert into public.ops_task_links (task_id, kind, label, url, created_by, ref_type, ref_id)
  values (p_task, 'record', v_ref->>'title', v_ref->>'url', v_me.id, p_type, p_ref)
  returning * into v_l;
  update public.ops_tasks set version = version + 1, updated_at = now() where id = p_task;
  perform public.ops_ref_file(v_l, 'linked');
  return jsonb_build_object('link_id', v_l.id, 'task', public.ops_task_json(p_task));
end $$;
revoke all on function public.ops_link_record(uuid, text, uuid, integer) from public, anon;
grant execute on function public.ops_link_record(uuid, text, uuid, integer) to authenticated;

/* ops_set_link_archived as phase 2 left it, filing a record link on both
   sides. */
create or replace function public.ops_set_link_archived(p_link uuid, p_on boolean)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare l public.ops_task_links;
begin
  if (public.ops_me()).id is null then return jsonb_build_object('error', 'not-team'); end if;
  select * into l from public.ops_task_links where id = p_link for update;
  if l.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if not public.ops_may_see_task(l.task_id) then return jsonb_build_object('error', 'denied'); end if;
  if not public.allowed('ops', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if (l.archived_at is not null) = p_on then
    return jsonb_build_object('link_id', l.id, 'archived', p_on,
                              'task', public.ops_task_json(l.task_id));
  end if;

  update public.ops_task_links
     set archived_at = case when p_on then now() else null end
   where id = p_link;
  update public.ops_tasks set version = version + 1, updated_at = now() where id = l.task_id;
  if l.ref_type is not null then
    perform public.ops_ref_file(l, case when p_on then 'unlinked' else 'relinked' end);
  else
    perform public.ops_log(l.task_id,
      case when p_on then 'file_removed' else 'file_restored' end, null,
      jsonb_build_object('link_id', l.id, 'kind', l.kind, 'label', l.label), '{}'::jsonb);
  end if;
  return jsonb_build_object('link_id', l.id, 'archived', p_on,
                            'task', public.ops_task_json(l.task_id));
end $$;
grant execute on function public.ops_set_link_archived(uuid, boolean) to authenticated;

/* ops_update_link as phase 4 left it, refusing a record link. */
create or replace function public.ops_update_link(
  p_link uuid, p_label text, p_url text, p_kind text, p_version integer default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m   public.team_members;
  l   public.ops_task_links;
  t   public.ops_tasks;
  lbl text;
  u   text;
begin
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'not-team'); end if;
  select * into l from public.ops_task_links where id = p_link for update;
  if l.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if not public.ops_may_see_task(l.task_id) then return jsonb_build_object('error', 'denied'); end if;
  if not public.allowed('ops', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if l.ref_type is not null then return jsonb_build_object('error', 'record-link'); end if;
  if p_kind not in ('brief', 'asset', 'draft', 'review', 'final', 'other') then
    return jsonb_build_object('error', 'bad-kind');
  end if;
  u := nullif(btrim(coalesce(p_url, '')), '');
  if u is null then return jsonb_build_object('error', 'url-required'); end if;
  select * into t from public.ops_tasks where id = l.task_id for update;
  if p_version is not null and p_version <> t.version then
    return jsonb_build_object('error', 'stale', 'task', public.ops_task_json(l.task_id));
  end if;
  lbl := coalesce(nullif(btrim(coalesce(p_label, '')), ''), initcap(p_kind) || ' link');
  if lbl = l.label and u = l.url and p_kind = l.kind then
    return jsonb_build_object('link_id', l.id, 'task', public.ops_task_json(l.task_id));
  end if;
  update public.ops_task_links set label = lbl, url = u, kind = p_kind where id = p_link;
  update public.ops_tasks set version = version + 1, updated_at = now() where id = l.task_id;
  perform public.ops_log(l.task_id, 'file_changed',
    jsonb_build_object('link_id', l.id, 'label', l.label, 'url', l.url, 'kind', l.kind),
    jsonb_build_object('link_id', l.id, 'label', lbl, 'url', u, 'kind', p_kind), '{}'::jsonb);
  return jsonb_build_object('link_id', l.id, 'task', public.ops_task_json(l.task_id));
end $$;
grant execute on function public.ops_update_link(uuid, text, text, text, integer) to authenticated;

/* The backlinks: every task linking a record, open work first, that the
   caller may see. A person who may not read the record's own section is
   told nothing of it, and a task they may not see is left out. */
create or replace function public.ops_record_tasks(p_type text, p_ref uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if (public.ops_me()).id is null then return '[]'::jsonb; end if;
  if p_type = 'campaign' and not public.allowed('campaigns', 'view') then return '[]'::jsonb; end if;
  if p_type = 'set' and not public.allowed('review', 'view') then return '[]'::jsonb; end if;
  if p_type is null or p_type not in ('campaign', 'set') then return '[]'::jsonb; end if;
  return coalesce((
    select jsonb_agg(x.j order by x.done, x.due nulls last, x.no)
      from (
        select distinct on (t.id)
               t.id, t.task_no as no,
               (t.completed_at is not null or t.cancelled_at is not null) as done,
               t.current_final_due_at as due,
               jsonb_build_object(
                 'id', t.id,
                 'serial', public.ops_serial(t.task_no),
                 'title', public.ops_title(t),
                 'stage_key', t.stage_key,
                 'stage', coalesce(s.label, initcap(replace(t.stage_key, '_', ' '))),
                 'stage_group', s.stage_group,
                 'owner', (select m.name from public.ops_task_assignees a
                             join public.team_members m on m.id = a.team_member_id
                            where a.task_id = t.id and a.responsibility = 'owner' and a.ended_at is null
                            limit 1),
                 'final_due_at', t.current_final_due_at,
                 'completed_at', t.completed_at,
                 'cancelled_at', t.cancelled_at,
                 'link_id', k.id) as j
          from public.ops_task_links k
          join public.ops_tasks t on t.id = k.task_id
          left join public.ops_workflow_stages s
                 on s.workflow_id = t.workflow_id and s.key = t.stage_key
         where k.ref_type = p_type and k.ref_id = p_ref and k.archived_at is null
           and public.ops_may_see_task(t.id)
         order by t.id, k.created_at
      ) x), '[]'::jsonb);
end $$;
revoke all on function public.ops_record_tasks(text, uuid) from public, anon;
grant execute on function public.ops_record_tasks(text, uuid) to authenticated;

-- END OF TASKS LINK RECORDS ----------------------------------------------------

-- ===========================================================================
-- THE CREATOR REPORTS THE RESULTS — the post link and the platform's numbers
-- come from the creator's own page, over a period only the team sets.
-- 2026-09-27. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/sql.js compares the two.
--
-- WHAT CHANGED (the user, 2026-09-27: "once approved by client, they can fill
-- in ... the posting link, and data within the period given (this should be
-- in sync with admin portal, one special thing is that the period date to
-- date should be set by the admin only ... So we dont need to go back
-- whatsapp communicate and then come back fill in again"; numbers only, no
-- screenshots; the post link moves the booking to Posted):
--  1. `option_posts` gains the measurement period (`measure_from`,
--     `measure_to`) and who last entered the figures (`entered_by`,
--     `entered_at`). Only the team writes the period: the creator's function
--     never touches it.
--  2. `creator_post_save` takes one placement's link, its publish date and
--     its numbers from the creator's page, once the draft is approved
--     (Scheduled, Posted). The link must be the platform's own. The numbers
--     wait for the period, and are whole and not negative. The first link at
--     Scheduled moves the booking to Posted.
--  3. `get_creator` sends each placement's link, period and numbers.
--  4. A creator's entry is filed as `campaign.results`.
--
-- ROLLBACK
--   drop function if exists public.creator_post_save(text, uuid, text, text, date, bigint, bigint, bigint);
--   drop function if exists public.post_link_ok(text, text);
--   Re-run get_creator from THE REVIEW LOOP REACHES EVERYONE and
--   activity_section from TASKS LINK RECORDS.
--   alter table public.option_posts drop column if exists measure_from,
--     drop column if exists measure_to, drop column if exists entered_by,
--     drop column if exists entered_at;
-- ===========================================================================

alter table public.option_posts add column if not exists measure_from date;
alter table public.option_posts add column if not exists measure_to date;
alter table public.option_posts add column if not exists entered_by text;
alter table public.option_posts add column if not exists entered_at timestamptz;

/* A placement's printed name ("rednote", "Instagram") or an older key, as
   one key. */
create or replace function public.post_platform_key(p text)
returns text
language sql immutable set search_path = public as $$
  select case lower(btrim(coalesce(p, '')))
           when 'rednote' then 'xhs' when 'xiaohongshu' then 'xhs' when 'xhs' then 'xhs'
           when 'instagram' then 'instagram' when 'tiktok' then 'tiktok'
           when 'facebook' then 'facebook'
           else lower(btrim(coalesce(p, ''))) end
$$;

/* The link is the platform's own post, on its own host, and nothing else:
   the client's page opens it as "View post on {platform}". */
create or replace function public.post_link_ok(p_platform text, p_url text)
returns boolean
language plpgsql immutable set search_path = public as $$
declare
  v    text := btrim(coalesce(p_url, ''));
  host text;
begin
  if v = '' or length(v) > 500 or v ~ '\s' or v !~* '^https://' then return false; end if;
  host := lower(substring(v from '^https://([^/?#]+)'));
  if host is null or host ~ '[@:]' then return false; end if;
  host := regexp_replace(host, '^(www|m|vm|vt)\.', '');
  return case public.post_platform_key(p_platform)
    when 'xhs' then host in ('xiaohongshu.com', 'xhslink.com')
    when 'instagram' then host = 'instagram.com'
    when 'tiktok' then host = 'tiktok.com'
    when 'facebook' then host in ('facebook.com', 'fb.watch', 'fb.com')
    else true end;
end $$;

create or replace function public.creator_post_save(
  p_code text, p_option uuid, p_platform text, p_url text, p_published date,
  p_impressions bigint, p_engagements bigint, p_views bigint)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  cr     creators%rowtype;
  o      campaign_options%rowtype;
  p      option_posts%rowtype;
  v_plat text;
  v_url  text := nullif(btrim(coalesce(p_url, '')), '');
  v_nums boolean := p_impressions is not null or p_engagements is not null or p_views is not null;
  v_live boolean := false;
begin
  select * into cr from creators where access_code = upper(p_code) and active;
  if not found then return jsonb_build_object('error', 'not-found'); end if;
  select * into o from campaign_options where id = p_option and creator_id = cr.id for update;
  if not found then return jsonb_build_object('error', 'not-found'); end if;
  if o.state not in ('scheduled', 'posted') then return jsonb_build_object('error', 'closed'); end if;

  -- One of the placements this booking is for, by its printed name.
  select btrim(x) into v_plat
    from unnest(string_to_array(coalesce(o.platforms, ''), ',')) x
   where public.post_platform_key(x) = public.post_platform_key(p_platform)
   limit 1;
  if v_plat is null then return jsonb_build_object('error', 'platform'); end if;
  if v_url is not null and not public.post_link_ok(v_plat, v_url) then
    return jsonb_build_object('error', 'link');
  end if;
  if coalesce(p_impressions, 0) < 0 or coalesce(p_engagements, 0) < 0 or coalesce(p_views, 0) < 0 then
    return jsonb_build_object('error', 'number');
  end if;
  if p_published is not null and (p_published > current_date + 1 or p_published < date '2023-08-14') then
    return jsonb_build_object('error', 'date');
  end if;

  select * into p from option_posts
   where option_id = p_option and public.post_platform_key(platform) = public.post_platform_key(v_plat)
   limit 1;
  if p.id is null then
    insert into option_posts (option_id, platform, window_days)
    values (p_option, v_plat, 7) returning * into p;
  end if;
  -- The numbers are counted over the period the team set, and wait for it.
  if v_nums and (p.measure_from is null or p.measure_to is null) then
    return jsonb_build_object('error', 'period');
  end if;

  update option_posts
     set post_url = coalesce(v_url, post_url),
         published_at = coalesce(p_published, published_at, case when v_url is not null then current_date end),
         impressions = case when v_nums then p_impressions else impressions end,
         engagements = case when v_nums then p_engagements else engagements end,
         views = case when v_nums then p_views else views end,
         measured_at = case when v_nums then current_date else measured_at end,
         entered_by = 'creator', entered_at = now()
   where id = p.id;

  -- The post is out: the booking says so, on the creator's word.
  if o.state = 'scheduled' and v_url is not null then
    update campaign_options set state = 'posted' where id = p_option;
    v_live := true;
  end if;

  insert into public.activity_log (actor, action, subject, detail)
  select cr.name, 'campaign.results', c.title,
         cr.name || ' · ' || v_plat ||
         case when v_url is not null and v_url is distinct from p.post_url then ' · link' else '' end ||
         case when v_nums then ' · ' || coalesce(p_views::text, '—') || ' views, ' ||
              coalesce(p_engagements::text, '—') || ' engagements, ' ||
              coalesce(p_impressions::text, '—') || ' impressions' else '' end ||
         case when v_live then ' · Posted' else '' end
    from campaigns c where c.id = o.campaign_id;

  return jsonb_build_object('ok', true, 'posted', v_live);
end $$;
revoke all on function public.creator_post_save(text, uuid, text, text, date, bigint, bigint, bigint) from public;
grant execute on function public.creator_post_save(text, uuid, text, text, date, bigint, bigint, bigint) to anon, authenticated;
grant execute on function public.post_link_ok(text, text) to anon, authenticated;
grant execute on function public.post_platform_key(text) to anon, authenticated;

create or replace function public.get_creator(p_code text)
returns jsonb
language plpgsql security definer stable set search_path = public as $$
declare
  cr creators%rowtype;
begin
  if p_code is null or length(trim(p_code)) < 8 then
    return jsonb_build_object('error', 'not-found');
  end if;
  select * into cr from creators
   where access_code = upper(regexp_replace(p_code, '[^A-Za-z0-9]', '', 'g'));
  if not found then return jsonb_build_object('error', 'not-found'); end if;
  if not cr.active then return jsonb_build_object('error', 'inactive'); end if;

  return jsonb_build_object(
    /* Who they are to us: the name the team keyed, since when, and the
       profile links the client's selection page opens, which they may keep
       up to date themselves. Never `client_rate`: that is the client's
       price, not theirs to read. */
    'creator', jsonb_build_object('name', cr.name, 'code', cr.access_code,
      'since', cr.created_at,
      'profiles', coalesce((
        select jsonb_agg(jsonb_build_object('platform', p.platform, 'handle', p.handle, 'url', p.url)
                         order by p.platform, p.url)
          from creator_profiles p where p.creator_id = cr.id), '[]'::jsonb)),
    'bookings', coalesce((
      select jsonb_agg(b order by b->>'sort')
      from (
        select jsonb_build_object(
          'id', o.id,
          'sort', coalesce(o.visit_date::text, '9999') || c.title,
          'campaign', c.title,
          'campaign_zh', c.title_zh,
          'brand', cl.name,
          'brief', c.brief,
          'brief_zh', c.brief_zh,
          'deliverable', c.deliverable,
          'push_format', c.push_format,
          'platforms', o.platforms,
          /* NO RATE, AND NO CURRENCY. `campaign_options.rate` is what the
             client is quoted for this booking and carries our markup, so it
             is not the creator's to read and is certainly not "their fee";
             what a creator is paid is agreed with them and claimed on AP01,
             which the page links to once the work is approved. `currency`
             existed only to format that one figure and names the client's
             market, which is a fact about the client. */
          'state', o.state,
          'visit_date', o.visit_date,
          'visit_time', o.visit_time,
          'visit_location', o.visit_location,
          'visit_pic', o.visit_pic,
          'visit_pic_phone', o.visit_pic_phone,
          'tracking_no', o.tracking_no,
          'submission_due', o.submission_due,
          'planned_publish', o.planned_publish,
          'revision_round', o.revision_round,
          /* The open request's note, whoever made it: the client's through
             their page, the team's through the send-back (2026-09-27). A
             team round sent back before the record held it is in
             `drop_reason`. */
          'change_note', case when o.state = 'changes' then coalesce(
            (select r.note from public.option_reviews r
              where r.option_id = o.id and r.decision = 'changes' and r.undone_at is null
                and r.source = case when coalesce(o.changes_by, 'client') = 'team' then 'team' else 'client' end
              order by r.created_at desc limit 1),
            case when o.changes_by = 'team' then o.drop_reason end) end,
          /* Each placement's post and its numbers, and the period the team
             set to count them over: the creator fills in the link and the
             figures here (2026-09-27). */
          'posts', coalesce((
            select jsonb_agg(jsonb_build_object(
              'platform', pp.platform, 'post_url', pp.post_url,
              'published_at', pp.published_at,
              'measure_from', pp.measure_from, 'measure_to', pp.measure_to,
              'impressions', pp.impressions, 'engagements', pp.engagements,
              'views', pp.views, 'measured_at', pp.measured_at,
              'entered_by', pp.entered_by) order by pp.platform)
            from public.option_posts pp where pp.option_id = o.id), '[]'::jsonb),
          'caption', o.draft_caption,
          'submitted_at', o.submitted_at,
          'rating', o.creator_rating,
          'can_deliver', public.creator_can_deliver(o.state),
          'files', coalesce((
            select jsonb_agg(jsonb_build_object(
              'id', d.id, 'url', d.url, 'name', d.name, 'kind', d.kind,
              'bytes', d.bytes, 'round', d.round)
              order by d.uploaded_at)
            from campaign_deliverables d
             where d.option_id = o.id and d.removed_at is null), '[]'::jsonb)
        ) as b
        from campaign_options o
        join campaigns c on c.id = o.campaign_id
        join clients cl on cl.id = c.client_id
        where o.creator_id = cr.id
          and c.state <> 'draft'
          and o.state in ('confirmed', 'pending_visit', 'pending_delivery',
                          'pending_draft', 'submitted', 'reviewing', 'changes',
                          'scheduled', 'posted', 'completed', 'withdrawn', 'replaced')
      ) rows), '[]'::jsonb));
end $$;
grant execute on function public.get_creator(text) to anon, authenticated;

-- END OF THE CREATOR REPORTS THE RESULTS ------------------------------------

-- ===========================================================================
-- INTERNAL HELPERS STAY INTERNAL — the database's own helper functions can no
-- longer be called from outside it.
-- 2026-09-27. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/sql.js compares the two.
--
-- WHAT CHANGED (the security review the user approved on 2026-09-27):
--   The open finding said the CRM and campaign tables let any signed-in
--   account read and write every row. Checked live on 2026-09-27, that is no
--   longer true: every public table has row level security on, no policy
--   reads `true`, and every policy asks `allowed()`, which answers false for
--   anybody who is not an active colleague. What was still open is a level
--   below the tables. Supabase grants EXECUTE on every new function to
--   `anon` and `authenticated`, and a security definer function runs as its
--   owner, so a helper written to be called only from inside other functions
--   could be called straight through the API with the public key:
--     - writes: `ops_notify` (a notification in any colleague's bell),
--       `ops_log` and `ops_engagement_log` (history rows), `campaign_qc_reset`,
--       `ops_record_review_decision`, `ops_next_seq`, `ops_code_of`;
--     - reads: `ops_task_json` and `ops_engagement_json` (a task or a month
--       whole, to anyone holding its id), `letter_sole_services`,
--       `ops_due_decider`, `ops_stage`, `serial_taken` (whether a reference
--       exists), `option_qc_count`, `option_qc_ok`, `campaign_booked`,
--       `ops_owner_may_move`, `ops_due_order_ok`, `ops_scope_error`.
--   None of them is called by a page, a policy, a view, a constraint, a
--   default or an invoker function (checked live), so they are revoked from
--   everybody but their owner. The functions that call them are security
--   definer and run as the owner, so every flow is unchanged.
--
--   A function added later is granted the same way by default: every new
--   helper that is not an API function revokes itself in the file that
--   creates it.
--
-- ROLLBACK
--   Grant each back with
--   grant execute on function <the signature below> to anon, authenticated;
-- ===========================================================================

/* Each by its exact signature, and only where it exists, so the file runs
   on any copy of the schema. */
do $$
declare
  f text;
begin
  foreach f in array array[
    'public.campaign_booked(uuid)',
    'public.campaign_qc_reset(uuid)',
    'public.letter_sole_services(uuid)',
    'public.ops_code_of(text, integer, integer)',
    'public.ops_due_decider(uuid, text)',
    'public.ops_due_order_ok(timestamp with time zone, timestamp with time zone)',
    'public.ops_engagement_json(uuid)',
    'public.ops_engagement_log(uuid, text, jsonb)',
    'public.ops_log(uuid, text, jsonb, jsonb, jsonb)',
    'public.ops_next_seq(uuid, text)',
    'public.ops_notify(uuid, uuid, text, text, text, text)',
    'public.ops_owner_may_move(uuid)',
    'public.ops_record_review_decision(uuid, uuid, boolean, text)',
    'public.ops_scope_error(text, uuid)',
    'public.ops_stage(uuid, text)',
    'public.ops_task_json(uuid)',
    'public.option_qc_count(uuid)',
    'public.option_qc_ok(uuid)',
    'public.serial_taken(text)'
  ] loop
    if to_regprocedure(f) is not null then
      execute format('revoke all on function %s from public, anon, authenticated', f);
    end if;
  end loop;
end $$;

-- END OF INTERNAL HELPERS STAY INTERNAL ------------------------------------

-- ===========================================================================
-- PUSH NOTIFICATIONS — the team, a client on the creator selection page and
-- a creator on their own page are told on their phone when something moves.
-- 2026-09-27. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/sql.js compares the two.
--
-- WHAT CHANGED (the user, 2026-09-27: "Mobile notifications for all,
-- client-facing esp on the creator selection; creator portal once it
-- receives updates (like requested changes / ready to post etc.); admin
-- internal team mostly on those that is now active notifications alr"):
--  1. A device turns notifications on from the page it is on, and follows
--     what that page belongs to, proved as the page proves it: the signed-in
--     colleague (the console), a campaign (the client's selection page, by
--     its token) or a creator (their page, by their code). A device follows
--     one colleague and one creator at most, and any number of campaigns.
--     Only a real push service's address is accepted, so the sender never
--     posts anywhere else.
--  2. What to send is queued in `push_outbox` by triggers, only where a
--     device follows it: a colleague's bell notification (`ops_notifications`)
--     as it is written; a draft released to the client and a post going live;
--     a creator booked, sent back for changes, and cleared to post. Only a
--     forward move is told. The client's words carry the creator and the
--     campaign; the creator's carry the campaign.
--  3. The queue is sent by the `push-send` edge function, which `pg_net`
--     wakes after the write commits. Where `pg_net` is not installed the
--     queue waits and nothing else is affected: a notification never fails
--     the write that caused it.
--  4. The sender's keys (VAPID) are made by `push-send` on its first run and
--     kept in `app_secrets`; only the public half ever leaves the database
--     (`push_public_key`). Nothing is typed or pasted by anybody.
--  5. The tables have row level security and no policy; every read and
--     write goes through these functions. The queue and the keys answer to
--     the service role alone.
--
-- ROLLBACK
--   drop trigger if exists ops_notifications_push on public.ops_notifications;
--   drop trigger if exists campaign_options_push on public.campaign_options;
--   drop function if exists public.ops_notifications_push(), public.campaign_options_push(),
--     public.push_queue(text, uuid, jsonb, text, text), public.push_kick(),
--     public.push_endpoint_ok(text), public.push_target(text, text),
--     public.push_subscribe(text, text, text, text, text, text),
--     public.push_unsubscribe(text, text, text), public.push_status(text, text, text),
--     public.push_public_key(), public.push_keys(), public.push_set_keys(text, text),
--     public.push_claim(integer), public.push_done(uuid, integer, integer, uuid[]);
--   drop table if exists public.push_outbox, public.push_subscriptions;
--   delete from public.app_secrets where key in ('push_vapid_public', 'push_vapid_private');
-- ===========================================================================

do $$ begin
  create extension if not exists pg_net;
exception when others then
  raise notice 'pg_net is not available here; the queue is sent when push-send is next called';
end $$;

create table if not exists public.push_subscriptions (
  id             uuid primary key default gen_random_uuid(),
  endpoint       text not null,
  p256dh         text not null,
  auth           text not null,
  audience       text not null check (audience in ('team', 'client', 'creator')),
  team_member_id uuid references public.team_members(id) on delete cascade,
  campaign_id    uuid references public.campaigns(id) on delete cascade,
  creator_id     uuid references public.creators(id) on delete cascade,
  target         uuid generated always as (coalesce(team_member_id, campaign_id, creator_id)) stored,
  lang           text not null default 'en' check (lang in ('en', 'zh')),
  created_at     timestamptz not null default now(),
  seen_at        timestamptz not null default now(),
  check ((audience = 'team') = (team_member_id is not null)),
  check ((audience = 'client') = (campaign_id is not null)),
  check ((audience = 'creator') = (creator_id is not null)),
  unique (endpoint, target)
);
create index if not exists push_subscriptions_target_idx on public.push_subscriptions(target);
alter table public.push_subscriptions enable row level security;
revoke all on public.push_subscriptions from public, anon, authenticated;

create table if not exists public.push_outbox (
  id             uuid primary key default gen_random_uuid(),
  created_at     timestamptz not null default now(),
  audience       text not null check (audience in ('team', 'client', 'creator')),
  target         uuid not null,
  message        jsonb not null,
  url            text not null,
  tag            text,
  claimed_at     timestamptz,
  sent_at        timestamptz,
  sent           integer not null default 0,
  failed         integer not null default 0
);
create index if not exists push_outbox_open_idx on public.push_outbox(created_at) where sent_at is null;
alter table public.push_outbox enable row level security;
revoke all on public.push_outbox from public, anon, authenticated;

/* The half of the sender's key a browser needs to subscribe; null until
   push-send has made the pair, and the pages hide their control until then. */
create or replace function public.push_public_key()
returns text
language sql stable security definer set search_path = public as $$
  select s.value from public.app_secrets s where s.key = 'push_vapid_public'
$$;
revoke all on function public.push_public_key() from public;
grant execute on function public.push_public_key() to anon, authenticated;

/* A push service's own address, and nothing else: Chrome and Android
   (Google), Safari and iPhone (Apple), Firefox (Mozilla), Edge (Microsoft).
   The sender posts to whatever is stored here, so an address anybody could
   type is refused. */
create or replace function public.push_endpoint_ok(p_endpoint text)
returns boolean
language sql immutable set search_path = public as $$
  select coalesce(length(p_endpoint) <= 1000 and p_endpoint ~ ('^https://(fcm\.googleapis\.com|android\.googleapis\.com'
    || '|([a-z0-9-]+\.)*push\.apple\.com|updates\.push\.services\.mozilla\.com'
    || '|([a-z0-9-]+\.)*notify\.windows\.com)/'), false)
$$;
revoke all on function public.push_endpoint_ok(text) from public, anon, authenticated;

/* What a page follows, proved as the page proves it: the signed-in
   colleague, the campaign's token, the creator's code. */
create or replace function public.push_target(p_audience text, p_ref text)
returns uuid
language plpgsql stable security definer set search_path = public as $$
declare
  v_code text := upper(regexp_replace(coalesce(p_ref, ''), '[^A-Za-z0-9]', '', 'g'));
  v_id   uuid;
begin
  if p_audience = 'team' then
    return (public.ops_me()).id;
  elsif p_audience = 'client' and coalesce(p_ref, '') <> '' then
    select c.id into v_id from public.campaigns c where c.access_token = p_ref;
  elsif p_audience = 'creator' and length(v_code) >= 8 then
    select k.id into v_id from public.creators k where k.access_code = v_code and k.active;
  end if;
  return v_id;
end $$;
revoke all on function public.push_target(text, text) from public, anon, authenticated;

/* A device turns notifications on for what its page follows. A console
   follows one colleague and a creator's page one creator, so turning on
   there moves the device; a client's device adds each campaign it is turned
   on for. Twenty devices at most follow one thing: the oldest leaves. */
create or replace function public.push_subscribe(
  p_audience text, p_ref text, p_endpoint text, p_p256dh text, p_auth text, p_lang text default 'en')
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_target uuid;
  v_lang   text := case when p_lang = 'zh' then 'zh' else 'en' end;
begin
  if not public.push_endpoint_ok(p_endpoint)
     or coalesce(length(p_p256dh), 0) not between 80 and 100
     or coalesce(length(p_auth), 0) not between 16 and 32 then
    return jsonb_build_object('error', 'bad-subscription');
  end if;
  if p_audience not in ('team', 'client', 'creator') then
    return jsonb_build_object('error', 'bad-audience');
  end if;
  v_target := public.push_target(p_audience, p_ref);
  if v_target is null then
    return jsonb_build_object('error', case when p_audience = 'team' then 'not-team' else 'not-found' end);
  end if;

  if p_audience in ('team', 'creator') then
    delete from public.push_subscriptions s
     where s.endpoint = p_endpoint and s.audience = p_audience and s.target <> v_target;
  end if;
  insert into public.push_subscriptions
    (endpoint, p256dh, auth, audience, team_member_id, campaign_id, creator_id, lang)
  values (p_endpoint, p_p256dh, p_auth, p_audience,
          case when p_audience = 'team' then v_target end,
          case when p_audience = 'client' then v_target end,
          case when p_audience = 'creator' then v_target end, v_lang)
  on conflict (endpoint, target) do update
     set lang = excluded.lang, seen_at = now();
  update public.push_subscriptions s set p256dh = p_p256dh, auth = p_auth
   where s.endpoint = p_endpoint and (s.p256dh <> p_p256dh or s.auth <> p_auth);
  delete from public.push_subscriptions s
   where s.target = v_target
     and s.id not in (select x.id from public.push_subscriptions x where x.target = v_target
                       order by x.seen_at desc limit 20);
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.push_subscribe(text, text, text, text, text, text) from public;
grant execute on function public.push_subscribe(text, text, text, text, text, text) to anon, authenticated;

/* Turning off is the device's own act: whoever holds the endpoint. With a
   page's audience and reference it stops that one; without, everything the
   device follows. `left` says whether the device still follows anything. */
create or replace function public.push_unsubscribe(p_endpoint text, p_audience text default null, p_ref text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_target uuid;
begin
  if p_audience is null then
    delete from public.push_subscriptions s where s.endpoint = p_endpoint;
  else
    v_target := public.push_target(p_audience, p_ref);
    delete from public.push_subscriptions s where s.endpoint = p_endpoint and s.target = v_target;
  end if;
  return jsonb_build_object('ok', true,
    'left', (select count(*) from public.push_subscriptions s where s.endpoint = p_endpoint));
end $$;
revoke all on function public.push_unsubscribe(text, text, text) from public;
grant execute on function public.push_unsubscribe(text, text, text) to anon, authenticated;

/* Whether this device follows what this page belongs to. It says nothing
   about any other device, or anything else this one follows. */
create or replace function public.push_status(p_endpoint text, p_audience text, p_ref text)
returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object('on', exists (
    select 1 from public.push_subscriptions s
     where s.endpoint = p_endpoint and s.target = public.push_target(p_audience, p_ref)))
$$;
revoke all on function public.push_status(text, text, text) from public;
grant execute on function public.push_status(text, text, text) to anon, authenticated;

/* Wakes push-send once the write has committed. Silent where pg_net is not
   installed or refuses: the queue is kept, and the next wake sends it. */
create or replace function public.push_kick()
returns void
language plpgsql security definer set search_path = public as $$
begin
  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
                  where n.nspname = 'net' and p.proname = 'http_post') then
    return;
  end if;
  execute 'select net.http_post(url := $1, body := $2)'
    using 'https://hwwuigvdfubuymchsvyx.supabase.co/functions/v1/push-send', '{}'::jsonb;
exception when others then
  return;
end $$;
revoke all on function public.push_kick() from public, anon, authenticated;

/* One message into the queue, only where a device follows it. */
create or replace function public.push_queue(
  p_audience text, p_target uuid, p_message jsonb, p_url text, p_tag text)
returns void
language plpgsql security definer set search_path = public as $$
begin
  if p_target is null or not exists (select 1 from public.push_subscriptions s
                  where s.audience = p_audience and s.target = p_target) then
    return;
  end if;
  insert into public.push_outbox (audience, target, message, url, tag)
  values (p_audience, p_target, p_message, p_url, p_tag);
  perform public.push_kick();
end $$;
revoke all on function public.push_queue(text, uuid, jsonb, text, text) from public, anon, authenticated;

/* A colleague's bell, on their phone: the same words, and the task opens. */
create or replace function public.ops_notifications_push()
returns trigger
language plpgsql security definer set search_path = public as $$
declare
  v_title text := coalesce(nullif(btrim(new.title), ''), 'My Work');
  v_body  text := coalesce(new.body, '');
begin
  perform public.push_queue('team', new.team_member_id,
    jsonb_build_object('en', jsonb_build_object('title', v_title, 'body', v_body),
                       'zh', jsonb_build_object('title', v_title, 'body', v_body)),
    case when new.task_id is null then '/admin/' else '/admin/?s=work&open=' || new.task_id::text end,
    case when new.task_id is null then null else 'task-' || new.task_id::text end);
  return new;
exception when others then
  return new;
end $$;
drop trigger if exists ops_notifications_push on public.ops_notifications;
create trigger ops_notifications_push after insert on public.ops_notifications
  for each row execute function public.ops_notifications_push();

/* A booking's step, told to whoever follows it: the client when a draft
   is released to them and when the post goes live; the creator when they are
   booked, asked for changes, and cleared to post. Only a forward move is
   told: a Revert back into a step tells nobody. */
create or replace function public.campaign_options_push()
returns trigger
language plpgsql security definer set search_path = public as $$
declare
  v_title    text;
  v_title_zh text;
  v_token    text;
  v_creator  text;
  v_msg      jsonb;
begin
  if new.state is not distinct from old.state then return new; end if;
  select coalesce(nullif(btrim(c.title), ''), 'Your campaign'),
         coalesce(nullif(btrim(c.title_zh), ''), nullif(btrim(c.title), ''), '您的活动'),
         c.access_token
    into v_title, v_title_zh, v_token from public.campaigns c where c.id = new.campaign_id;
  select coalesce(nullif(btrim(k.name), ''), 'A creator') into v_creator
    from public.creators k where k.id = new.creator_id;
  v_creator := coalesce(v_creator, 'A creator');

  if v_token is not null and ((new.state = 'reviewing' and old.state = 'submitted')
                           or (new.state = 'posted' and old.state = 'scheduled')) then
    v_msg := case new.state
      when 'reviewing' then jsonb_build_object(
        'en', jsonb_build_object('title', 'Draft ready for review', 'body', v_creator || ' · ' || v_title),
        'zh', jsonb_build_object('title', '初稿待审阅', 'body', v_creator || ' · ' || v_title_zh))
      else jsonb_build_object(
        'en', jsonb_build_object('title', 'Post is live', 'body', v_creator || ' · ' || v_title),
        'zh', jsonb_build_object('title', '帖子已发布', 'body', v_creator || ' · ' || v_title_zh))
    end;
    perform public.push_queue('client', new.campaign_id, v_msg,
      '/creators/?k=' || v_token, 'option-' || new.id::text);
  end if;

  if (new.state = 'confirmed' and old.state in ('option', 'shortlisted', 'backup'))
     or new.state = 'changes'
     or (new.state = 'scheduled' and old.state in ('submitted', 'reviewing', 'changes')) then
    v_msg := case new.state
      when 'confirmed' then jsonb_build_object(
        'en', jsonb_build_object('title', 'Booking confirmed', 'body', v_title),
        'zh', jsonb_build_object('title', '合作已确认', 'body', v_title_zh))
      when 'changes' then jsonb_build_object(
        'en', jsonb_build_object('title', 'Changes requested', 'body', v_title),
        'zh', jsonb_build_object('title', '需要修改', 'body', v_title_zh))
      else jsonb_build_object(
        'en', jsonb_build_object('title', 'Approved: ready to post', 'body', v_title),
        'zh', jsonb_build_object('title', '已通过，可以发布', 'body', v_title_zh))
    end;
    perform public.push_queue('creator', new.creator_id, v_msg,
      '/creator/#b=' || new.id::text, 'option-' || new.id::text);
  end if;
  return new;
exception when others then
  return new;
end $$;
drop trigger if exists campaign_options_push on public.campaign_options;
create trigger campaign_options_push after update of state on public.campaign_options
  for each row execute function public.campaign_options_push();

/* The sender's keys, for push-send alone. */
create or replace function public.push_keys()
returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'public',  (select s.value from public.app_secrets s where s.key = 'push_vapid_public'),
    'private', (select s.value from public.app_secrets s where s.key = 'push_vapid_private'))
$$;
revoke all on function public.push_keys() from public, anon, authenticated;
grant execute on function public.push_keys() to service_role;

/* Kept once: a second run, or two at once, keeps the first pair. */
create or replace function public.push_set_keys(p_public text, p_private text)
returns jsonb
language plpgsql security definer set search_path = public as $$
begin
  if coalesce(p_public, '') = '' or coalesce(p_private, '') = '' then
    return public.push_keys();
  end if;
  if not exists (select 1 from public.app_secrets s where s.key = 'push_vapid_private') then
    insert into public.app_secrets (key, value) values ('push_vapid_private', p_private)
      on conflict (key) do nothing;
    insert into public.app_secrets (key, value) values ('push_vapid_public', p_public)
      on conflict (key) do nothing;
  end if;
  return public.push_keys();
end $$;
revoke all on function public.push_set_keys(text, text) from public, anon, authenticated;
grant execute on function public.push_set_keys(text, text) to service_role;

/* The next messages to send, each with the devices that follow it. A claim
   holds a message for five minutes, so two runs never send it twice; a
   message older than two days is not sent. */
create or replace function public.push_claim(p_limit integer default 50)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_out jsonb;
begin
  with c as (
    select o.id from public.push_outbox o
     where o.sent_at is null
       and (o.claimed_at is null or o.claimed_at < now() - interval '5 minutes')
       and o.created_at > now() - interval '2 days'
     order by o.created_at
     limit greatest(1, least(coalesce(p_limit, 50), 200))
     for update skip locked
  ), took as (
    update public.push_outbox o set claimed_at = now() from c where o.id = c.id returning o.*
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', t.id, 'message', t.message, 'url', t.url, 'tag', t.tag,
           'subs', coalesce((select jsonb_agg(jsonb_build_object(
                     'id', s.id, 'endpoint', s.endpoint, 'p256dh', s.p256dh, 'auth', s.auth, 'lang', s.lang))
                     from public.push_subscriptions s
                    where s.audience = t.audience and s.target = t.target), '[]'::jsonb))
           order by t.created_at), '[]'::jsonb)
    into v_out from took t;
  return v_out;
end $$;
revoke all on function public.push_claim(integer) from public, anon, authenticated;
grant execute on function public.push_claim(integer) to service_role;

/* What a send did: the message is done, a device the push service no longer
   knows is taken off with everything it followed, and a month of the queue
   is kept. */
create or replace function public.push_done(p_outbox uuid, p_sent integer, p_failed integer, p_dead uuid[])
returns void
language plpgsql security definer set search_path = public as $$
begin
  update public.push_outbox
     set sent_at = now(), sent = coalesce(p_sent, 0), failed = coalesce(p_failed, 0)
   where id = p_outbox;
  if p_dead is not null and array_length(p_dead, 1) > 0 then
    delete from public.push_subscriptions s
     where s.endpoint in (select d.endpoint from public.push_subscriptions d where d.id = any (p_dead));
  end if;
  delete from public.push_outbox where created_at < now() - interval '30 days';
end $$;
revoke all on function public.push_done(uuid, integer, integer, uuid[]) from public, anon, authenticated;
grant execute on function public.push_done(uuid, integer, integer, uuid[]) to service_role;

-- END OF PUSH NOTIFICATIONS ---------------------------------------------------

-- ===========================================================================
-- S3 SWEEP — a file leaves the bucket only when nothing points at it.
-- 2026-09-28. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/s3sql.js compares the
-- two.
--
-- WHAT CHANGED (the S3 build the user approved on 2026-09-27):
--   The portal writes to S3 and never removed anything, so an object whose
--   row was deleted stayed in the bucket, billed and invisible. The
--   `s3-sweep` edge function now lists `content/`, asks this database which
--   keys are still referenced, and deletes the rest. The portal itself still
--   never deletes from S3; only the sweep does.
--
--   `s3_keys_in_use(p_keys)` answers which of the keys it is given are still
--   referenced. A key is in use while ANY row anywhere in `public` holds it:
--     - a handed-in draft (`campaign_deliverables.url`) while it stands, and
--       for 30 days after it is soft removed, because Undo puts the row back
--       and the client's page would then point at a file that is gone;
--     - every other text, varchar, json, jsonb or text[] column of every
--       table in `public`, read whole: `posts.media` (url and poster inside
--       the jsonb), `drive_assets.url` and `poster_url`, `campaigns
--       .invoice_url`, `clients.logo_url`, `documents.file_url`, a pasted
--       draft link, a history row. A column added later is covered the day
--       it is added, without this file changing.
--   Matching is by the key appearing anywhere in the value, so a CDN link, a
--   bucket link and a bare key all count, and a near miss keeps a file
--   rather than losing one.
--
--   `s3_sweeps` is one row per run: listed, too young to judge (under 7
--   days), kept, deleted and would-delete, each with its bytes. Row level
--   security on, no policy: only the service role reads or writes it.
--   Read it in the SQL editor:
--     select * from public.s3_sweeps order by ran_at desc limit 10;
--
--   The daily schedule is written only where pg_cron and pg_net are both
--   installed and the two Vault secrets it reads exist (see
--   docs/S3-STORAGE.md). Otherwise the file still applies and says so.
--
-- ROLLBACK
--   select cron.unschedule('s3-sweep-daily');   -- where it was scheduled
--   drop function if exists public.s3_keys_in_use(text[]);
--   drop table if exists public.s3_sweeps;
-- ===========================================================================

create table if not exists public.s3_sweeps (
  id                 uuid primary key default gen_random_uuid(),
  ran_at             timestamptz not null default now(),
  mode               text not null check (mode in ('dry', 'delete', 'held', 'failed')),
  prefix             text not null,
  listed             integer not null default 0,
  listed_bytes       bigint  not null default 0,
  young              integer not null default 0,
  young_bytes        bigint  not null default 0,
  kept               integer not null default 0,
  kept_bytes         bigint  not null default 0,
  would_delete       integer not null default 0,
  would_delete_bytes bigint  not null default 0,
  deleted            integer not null default 0,
  deleted_bytes      bigint  not null default 0,
  failed             integer not null default 0,
  note               text,
  sample             text[] not null default '{}'
);
create index if not exists s3_sweeps_ran_idx on public.s3_sweeps (ran_at desc);

alter table public.s3_sweeps enable row level security;
revoke all on public.s3_sweeps from public, anon, authenticated;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    grant select, insert on public.s3_sweeps to service_role;
  end if;
end $$;

create or replace function public.s3_keys_in_use(p_keys text[])
returns text[]
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_ask  text[];
  v_used text[];
  v_hit  text[];
  col    record;
begin
  /* An empty key would match every value, so it is never asked. */
  select coalesce(array_agg(distinct k), '{}') into v_ask
    from unnest(coalesce(p_keys, '{}')) k
   where k is not null and btrim(k) <> '';
  if cardinality(v_ask) = 0 then return '{}'; end if;

  /* A handed-in draft: standing, or soft removed within the Undo's 30 days. */
  select coalesce(array_agg(k), '{}') into v_used
    from unnest(v_ask) k
   where exists (select 1 from public.campaign_deliverables d
                  where strpos(d.url, k) > 0
                    and (d.removed_at is null or d.removed_at > now() - interval '30 days'));

  /* Every other text-like column of every table, whole. Only the keys not
     yet known to be in use are carried to the next column. */
  for col in
    select c.relname as tbl, a.attname as att
      from pg_class c
      join pg_namespace n on n.oid = c.relnamespace
      join pg_attribute a on a.attrelid = c.oid
     where n.nspname = 'public' and c.relkind in ('r', 'p')
       and a.attnum > 0 and not a.attisdropped
       and a.atttypid in ('text'::regtype, 'character varying'::regtype, 'json'::regtype,
                          'jsonb'::regtype, 'text[]'::regtype, 'character varying[]'::regtype)
       and not (c.relname = 'campaign_deliverables' and a.attname = 'url')
       and c.relname <> 's3_sweeps'
     order by c.relname, a.attnum
  loop
    exit when cardinality(v_ask) = cardinality(v_used);
    execute format(
      'select coalesce(array_agg(distinct k), ''{}'') from unnest($1) k
        where exists (select 1 from public.%I x where strpos(x.%I::text, k) > 0)',
      col.tbl, col.att)
      into v_hit
      using array(select k from unnest(v_ask) k where not (k = any(v_used)));
    v_used := v_used || v_hit;
  end loop;

  return v_used;
end $$;
revoke all on function public.s3_keys_in_use(text[]) from public, anon, authenticated;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    grant execute on function public.s3_keys_in_use(text[]) to service_role;
  end if;
end $$;

/* Daily at 03:17 in Malaysia (19:17 UTC). The call carries the sweep's own
   token from Vault; the key and the project address never enter this file. */
do $$
declare
  n integer := 0;
begin
  if not exists (select 1 from pg_extension where extname = 'pg_cron')
     or not exists (select 1 from pg_extension where extname = 'pg_net') then
    raise notice 's3-sweep: pg_cron and pg_net are not both installed, so no schedule was written. See docs/S3-STORAGE.md.';
    return;
  end if;
  if to_regclass('vault.decrypted_secrets') is not null then
    execute $q$select count(*) from vault.decrypted_secrets
               where name in ('project_url', 's3_sweep_token')$q$ into n;
  end if;
  if n < 2 then
    raise notice 's3-sweep: the Vault secrets project_url and s3_sweep_token are not both set, so no schedule was written. See docs/S3-STORAGE.md.';
    return;
  end if;
  perform cron.unschedule(j.jobid) from cron.job j where j.jobname = 's3-sweep-daily';
  perform cron.schedule('s3-sweep-daily', '17 19 * * *', $cmd$
    select net.http_post(
      url     := (select decrypted_secret from vault.decrypted_secrets where name = 'project_url')
                 || '/functions/v1/s3-sweep',
      headers := jsonb_build_object(
                   'Content-Type', 'application/json',
                   'Authorization', 'Bearer ' || (select decrypted_secret from vault.decrypted_secrets
                                                  where name = 's3_sweep_token')),
      body    := '{}'::jsonb,
      timeout_milliseconds := 60000);
  $cmd$);
end $$;

-- END OF S3 SWEEP ------------------------------------------------------------

-- ===========================================================================
-- PERFORMANCE REWARDS — the quarter and its two prizes, flexible hours, the
-- bonus pool and the company trip, and growth commission, each worked out
-- from finalised months.
-- 2026-09-28. Safe to run twice. Run after
-- 2026-09-26-performance-records-trail-and-check.sql. Rollback at the foot of
-- this header. Mirrored byte for byte in supabase/schema.sql under the same
-- banner; tests/perf.js compares the two.
--
-- THE RULES, confirmed by the user on 2026-09-27. Grades read the monthly
-- bands (A 90 and over, B 80, C 70, D 60, E under 60).
--  1. A quarter is a calendar quarter; the first is Q3 2026. A member's
--     quarterly average is the mean of their FINALISED monthly final scores
--     in it, graded on the same bands.
--  2. Individual prize, RM 400 a quarter: the highest average among the
--     eligible takes it, a tie splits it. Eligible: an average of 70 or more,
--     no E month, no Level 4 breach in the quarter, active, on the review
--     list. Nobody eligible is no payout, said so.
--  3. Department prize, RM 600 a quarter: management enters each
--     department's five criteria and a tick for an unresolved critical
--     issue. The higher total wins if it is 80 or more with no critical
--     issue, else nobody. Tied departments are joint winners and a winner
--     that does not qualify drops out, so a tie with both qualifying splits
--     the pool and a tie with one qualifying pays that one the whole pool.
--     A winning share is split equally among the department's active
--     members on the review list.
--  4. Flexible hours: a month unlocks the next month once every active
--     member on the review list has a final review of it and 50% or more of
--     them scored 70 or more. A member may use it where their own month is
--     70 or more with no Level 3 or 4 breach.
--  5. Bonus pool and company trip, over two quarters (a period, named by its
--     first quarter): revenue and profit are entered by an admin and read by
--     nobody else. The pool opens at RM 500,000 revenue and is at most 10%
--     of profit, set by the admin, never more. The trip opens at
--     RM 1,000,000 with a budget the admin sets. A member qualifies with 3 or
--     more months at B or better in the six, no E month, no Level 4 breach,
--     active. Units from the grade of their six-month average: A 3.0, B 1.5,
--     C 0.5, D and E none. Each share is units over all units times the
--     amount.
--  6. Growth commission: management enters each deal (the member, the client
--     if any, a description, the month invoiced, the net profit, the rate).
--     Payable only where that month is final at 70 or more with no Level 3 or
--     4 breach; otherwise it is recorded as not payable, with the reason, or
--     pending while the month is not final. The amount is net profit times
--     the rate, to the cent.
--  Money is divided in cents: each share is rounded down to the cent and
--  what the rounding leaves is stated as the remainder, never lost.
--
-- WHO READS WHAT. Every table below has row level security on and no policy.
-- Management functions ask `team.performance` and a live master-code unlock
-- (perf_check), the same two locks as a month. Revenue and profit are read
-- and written only by an admin (perf_is_admin); the rest of management sees
-- the amounts and never the figures behind them. The caller's own row is sent
-- with its name alone. A member reads their own confirmed quarters and
-- periods, their flexible hours once a month is decided and their
-- commissions once the month is final, through perf_rewards_mine(), behind
-- the same fresh code as My performance.
--
-- CONFIRM AND REOPEN. A quarter's or a period's outcome is worked out on every
-- read. Confirm keeps a snapshot (perf_rewards), which is what the member
-- reads; Reopen removes it, files the snapshot in the history and never
-- asks. Every entry, confirmation and reopening is filed in perf_events;
-- no notification carries a score or an amount.
--
-- ROLLBACK
--   drop function if exists public.perf_rewards_mine(), public.perf_commission_restore(text, uuid),
--     public.perf_commission_remove(text, uuid), public.perf_commission_add(text, jsonb),
--     public.perf_commissions(text), public.perf_period_reopen(text, date),
--     public.perf_period_confirm(text, date), public.perf_company_set(text, date, jsonb),
--     public.perf_period(text, date), public.perf_flex(text, date),
--     public.perf_quarter_reopen(text, date), public.perf_quarter_confirm(text, date),
--     public.perf_dept_save(text, date, text, jsonb), public.perf_quarter(text, date),
--     public.perf_reward_events(text[], text), public.perf_hide_own(jsonb, uuid),
--     public.perf_commission_json(public.perf_commissions), public.perf_period_calc(date),
--     public.perf_flex_calc(date), public.perf_quarter_calc(date), public.perf_is_admin(),
--     public.perf_period_word(date), public.perf_quarter_word(date), public.perf_today() cascade;
--   drop table if exists public.perf_commissions, public.perf_company, public.perf_rewards,
--     public.perf_dept_scores cascade;
-- ===========================================================================

-- 1. The record -----------------------------------------------------------------------
/* What management enters for a department's quarter: the five criteria in
   the framework's order, each out of its own maximum, and the tick. */
create table if not exists public.perf_dept_scores (
  quarter     date not null check (quarter >= date '2026-07-01'
                                   and extract(day from quarter) = 1 and extract(month from quarter) in (1, 4, 7, 10)),
  department  text not null check (department in ('creative', 'marketing')),
  c1          numeric(4,1) not null check (c1 between 0 and 25),
  c2          numeric(4,1) not null check (c2 between 0 and 25),
  c3          numeric(4,1) not null check (c3 between 0 and 20),
  c4          numeric(4,1) not null check (c4 between 0 and 15),
  c5          numeric(4,1) not null check (c5 between 0 and 15),
  critical    boolean not null default false,
  entered_by  uuid references public.team_members(id) on delete set null,
  updated_at  timestamptz not null default now(),
  primary key (quarter, department)
);

/* A confirmed quarter or period: the outcome as it was worked out at the
   press. The row's absence is the way back. */
create table if not exists public.perf_rewards (
  kind          text not null check (kind in ('quarter', 'period')),
  period        date not null,
  snapshot      jsonb not null,
  confirmed_by  uuid references public.team_members(id) on delete set null,
  confirmed_at  timestamptz not null default now(),
  primary key (kind, period)
);

/* The company's figures for a period of two quarters, named by the first.
   Read and written by an admin alone. */
create table if not exists public.perf_company (
  period       date primary key check (period >= date '2026-07-01'
                                       and extract(day from period) = 1 and extract(month from period) in (1, 4, 7, 10)),
  revenue      numeric(14,2) not null check (revenue >= 0),
  profit       numeric(14,2) not null,
  pool         numeric(14,2) not null default 0 check (pool >= 0),
  trip_budget  numeric(14,2) not null default 0 check (trip_budget >= 0),
  entered_by   uuid references public.team_members(id) on delete set null,
  updated_at   timestamptz not null default now()
);

create table if not exists public.perf_commissions (
  id              uuid primary key default gen_random_uuid(),
  team_member_id  uuid not null references public.team_members(id) on delete cascade,
  client_id       uuid references public.clients(id) on delete set null,
  description     text not null,
  month           date not null check (extract(day from month) = 1),
  net_profit      numeric(14,2) not null check (net_profit >= 0),
  pct             numeric(5,2) not null check (pct > 0 and pct <= 100),
  created_by      uuid references public.team_members(id) on delete set null,
  created_at      timestamptz not null default now(),
  removed_at      timestamptz,
  removed_by      uuid references public.team_members(id) on delete set null
);
create index if not exists perf_commissions_member_idx on public.perf_commissions(team_member_id, month);

-- 2. Nobody reads a table directly -------------------------------------------------
alter table public.perf_dept_scores enable row level security;
alter table public.perf_rewards enable row level security;
alter table public.perf_company enable row level security;
alter table public.perf_commissions enable row level security;
revoke all on public.perf_dept_scores, public.perf_rewards, public.perf_company, public.perf_commissions
  from anon, authenticated;
do $$
declare p record;
begin
  for p in select policyname, tablename from pg_policies
            where schemaname = 'public'
              and tablename in ('perf_dept_scores', 'perf_rewards', 'perf_company', 'perf_commissions') loop
    execute format('drop policy if exists %I on public.%I', p.policyname, p.tablename);
  end loop;
end $$;

-- 3. The rules, stated once ----------------------------------------------------------
/* Today, in one place, so every "has it ended" asks the same clock. */
create or replace function public.perf_today()
returns date language sql stable as $$
  select current_date
$$;
create or replace function public.perf_quarter_word(p_quarter date)
returns text language sql immutable as $$
  select 'Q' || extract(quarter from p_quarter)::int || ' ' || extract(year from p_quarter)::int
$$;
/* Two quarters, named without a dash: "Q3 and Q4 2026", "Q4 2026 and Q1 2027". */
create or replace function public.perf_period_word(p_from date)
returns text language sql immutable as $$
  select case when extract(year from p_from) = extract(year from (p_from + interval '3 months'))
              then 'Q' || extract(quarter from p_from)::int || ' and Q'
                   || extract(quarter from (p_from + interval '3 months'))::int || ' ' || extract(year from p_from)::int
              else public.perf_quarter_word(p_from) || ' and '
                   || public.perf_quarter_word((p_from + interval '3 months')::date) end
$$;
create or replace function public.perf_is_admin()
returns boolean
language plpgsql stable security definer set search_path = public as $$
declare v_me public.team_members;
begin
  v_me := public.ops_me();
  return v_me.id is not null and (coalesce(v_me.is_admin, false) or v_me.role = 'admin');
end $$;

/* The quarter, worked out: every person with a final month in it or on the
   review list, their average and why they are or are not eligible, the
   individual prize, and the department prize. Never stored except by
   Confirm. */
create or replace function public.perf_quarter_calc(p_quarter date)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_q date := date_trunc('quarter', p_quarter)::date;
  v_qe date := (date_trunc('quarter', p_quarter) + interval '3 months')::date;
  v_people jsonb; v_wins integer; v_each numeric; v_ind jsonb;
  v_depts jsonb; v_dwins integer; v_both boolean; v_why text; v_dp jsonb;
begin
  with m as (
    select t.id as mid, t.name as mname, t.staff_code as mcode, t.department as mdept, t.active as mactive,
           public.perf_reviewed(t.id) as monlist, f.nmonths, f.mean, f.emonth,
           exists (select 1 from public.perf_breaches b
                    where b.team_member_id = t.id and b.voided_at is null and b.severity = 4
                      and b.period >= v_q and b.period < v_qe) as ml4
      from public.team_members t
      cross join lateral (
        select count(*)::int as nmonths, round(avg((x.res ->> 'final')::numeric), 2) as mean,
               coalesce(bool_or(x.res ->> 'grade' = 'E'), false) as emonth
          from (select coalesce(r.result, public.perf_calc(r)) as res
                  from public.perf_reviews r
                 where r.team_member_id = t.id and r.status = 'final'
                   and r.period >= v_q and r.period < v_qe) x) f
     where f.nmonths > 0 or (t.active and public.perf_reviewed(t.id))
  ), e as (
    select m.*, array_remove(array[
             case when m.nmonths = 0 then 'no-final-month' end,
             case when m.nmonths > 0 and m.mean < 70 then 'below-c' end,
             case when m.emonth then 'e-month' end,
             case when m.ml4 then 'critical-breach' end,
             case when not m.mactive then 'inactive' end,
             case when not m.monlist then 'not-reviewed' end], null) as why
      from m
  ), w as (
    select e.*, cardinality(e.why) = 0 as ok,
           coalesce(cardinality(e.why) = 0
                    and e.mean = max(e.mean) filter (where cardinality(e.why) = 0) over (), false) as won
      from e
  ), p as (
    select w.*, count(*) filter (where w.won) over () as nwon from w
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'team_member_id', p.mid, 'name', p.mname, 'staff_code', p.mcode, 'department', p.mdept,
           'active', p.mactive, 'reviewed', p.monlist, 'months', p.nmonths, 'average', p.mean,
           'grade', case when p.nmonths > 0 then public.perf_grade_of(p.mean) end,
           'e_month', p.emonth, 'l4', p.ml4, 'eligible', p.ok, 'reasons', to_jsonb(p.why),
           'prize', case when p.won then floor(40000.0 / p.nwon) / 100 else 0 end)
         order by p.ok desc, p.mean desc nulls last, p.mname), '[]'::jsonb),
         coalesce(max(p.nwon), 0)
    into v_people, v_wins
    from p;
  v_each := case when v_wins > 0 then floor(40000.0 / v_wins) / 100 end;
  v_ind := jsonb_build_object('pool', 400, 'winners', v_wins, 'each', v_each,
    'paid', coalesce(v_each * v_wins, 0), 'remainder', 400 - coalesce(v_each * v_wins, 0),
    'reason', case when v_wins = 0 then 'nobody-eligible' end);

  with d as (
    select k.dep, s.c1, s.c2, s.c3, s.c4, s.c5, coalesce(s.critical, false) as crit,
           s.c1 + s.c2 + s.c3 + s.c4 + s.c5 as total, s.quarter is not null as entered, k.ord
      from (values ('creative', 1), ('marketing', 2)) k(dep, ord)
      left join public.perf_dept_scores s on s.quarter = v_q and s.department = k.dep
  ), x as (
    select d.*, bool_and(d.entered) over () as bothin,
           coalesce(d.total = max(d.total) over (), false) as istop
      from d
  ), y as (
    select x.*, (x.bothin and x.istop and x.total >= 80 and not x.crit) as won,
           coalesce((select array_agg(t.id order by t.name) from public.team_members t
                      where t.active and t.department = x.dep and public.perf_reviewed(t.id)), '{}'::uuid[]) as mems
      from x
  ), z as (
    select y.*, count(*) filter (where y.won) over () as nwon,
           case when y.won then floor(60000.0 / count(*) filter (where y.won) over ()) end as sharec
      from y
  )
  select jsonb_agg(jsonb_build_object(
           'department', z.dep, 'entered', z.entered,
           'criteria', case when z.entered then jsonb_build_array(z.c1, z.c2, z.c3, z.c4, z.c5) end,
           'total', z.total, 'grade', case when z.entered then public.perf_grade_of(z.total) end,
           'critical', z.crit, 'top', z.bothin and z.istop,
           'qualifies', z.entered and z.total >= 80 and not z.crit, 'won', z.won,
           'share', coalesce(z.sharec / 100, 0), 'members', to_jsonb(z.mems),
           'each', case when z.won and cardinality(z.mems) > 0 then floor(z.sharec / cardinality(z.mems)) / 100 end,
           'remainder', case when z.won then case when cardinality(z.mems) > 0
                               then (z.sharec - floor(z.sharec / cardinality(z.mems)) * cardinality(z.mems)) / 100
                               else z.sharec / 100 end end)
         order by z.ord),
         coalesce(max(z.nwon), 0), bool_and(z.bothin),
         case when bool_and(z.bothin) and max(z.nwon) = 0 then
           case when bool_or(z.istop and z.total >= 80 and z.crit) then 'critical-issue' else 'below-b' end end
    into v_depts, v_dwins, v_both, v_why
    from z;
  v_dp := jsonb_build_object('pool', 600, 'winners', v_dwins,
    'paid', case when v_dwins > 0 then floor(60000.0 / v_dwins) * v_dwins / 100 else 0 end,
    'remainder', case when v_dwins > 0 then 600 - floor(60000.0 / v_dwins) * v_dwins / 100 else 600 end,
    'reason', case when not v_both then 'scores-needed' else v_why end);

  return jsonb_build_object('quarter', v_q, 'word', public.perf_quarter_word(v_q),
    'ended', public.perf_today() >= v_qe, 'people', v_people, 'individual', v_ind,
    'departments', v_depts, 'department_prize', v_dp);
end $$;

/* One month's flexible hours: the month decides the next once every active
   member on the review list is final, and unlocks it at half or more at 70
   or over. Each person's own filter beside it. */
create or replace function public.perf_flex_calc(p_period date)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_p date := date_trunc('month', p_period)::date;
  v_total integer; v_finals integer; v_at integer; v_rows jsonb;
begin
  with m as (
    select t.id as mid, t.name as mname, t.staff_code as mcode,
           case when r.id is not null then coalesce(r.result, public.perf_calc(r)) end as res
      from public.team_members t
      left join public.perf_reviews r on r.team_member_id = t.id and r.period = v_p and r.status = 'final'
     where t.active and public.perf_reviewed(t.id)
  )
  select count(*)::int, count(m.res)::int,
         (count(*) filter (where (m.res ->> 'final')::numeric >= 70))::int,
         coalesce(jsonb_agg(jsonb_build_object('team_member_id', m.mid, 'name', m.mname, 'staff_code', m.mcode,
           'final', m.res -> 'final', 'grade', m.res ->> 'grade',
           'breach', coalesce((m.res ->> 'l3')::boolean or (m.res ->> 'l4')::boolean, false),
           'eligible', coalesce((m.res ->> 'final')::numeric >= 70
                                and not (m.res ->> 'l3')::boolean and not (m.res ->> 'l4')::boolean, false))
           order by m.mname), '[]'::jsonb)
    into v_total, v_finals, v_at, v_rows
    from m;
  return jsonb_build_object('period', v_p, 'month', public.perf_month_word(v_p),
    'next', (v_p + interval '1 month')::date,
    'next_month', public.perf_month_word((v_p + interval '1 month')::date),
    'members', v_total, 'finals', v_finals, 'at_70', v_at,
    'decided', v_total > 0 and v_finals = v_total,
    'unlocked', v_total > 0 and v_finals = v_total and v_at * 2 >= v_total,
    'people', v_rows);
end $$;

/* A period of two quarters: who qualifies, their units, and their share of
   the bonus pool and of the trip. Revenue and profit never leave this
   function; only whether each gate opened and the amounts set. */
create or replace function public.perf_period_calc(p_from date)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_f date := date_trunc('quarter', p_from)::date;
  v_t date := (date_trunc('quarter', p_from) + interval '6 months')::date;
  v_c public.perf_company; v_pool numeric; v_trip numeric; v_popen boolean; v_topen boolean;
  v_rows jsonb; v_units numeric; v_bpaid numeric; v_tpaid numeric;
begin
  select * into v_c from public.perf_company where period = v_f;
  v_popen := coalesce(v_c.revenue, 0) >= 500000;
  v_topen := coalesce(v_c.revenue, 0) >= 1000000;
  v_pool := case when v_popen then coalesce(v_c.pool, 0) else 0 end;
  v_trip := case when v_topen then coalesce(v_c.trip_budget, 0) else 0 end;
  with m as (
    select t.id as mid, t.name as mname, t.staff_code as mcode, t.active as mactive,
           f.nmonths, f.nb, f.mean, f.emonth,
           exists (select 1 from public.perf_breaches b
                    where b.team_member_id = t.id and b.voided_at is null and b.severity = 4
                      and b.period >= v_f and b.period < v_t) as ml4
      from public.team_members t
      cross join lateral (
        select count(*)::int as nmonths,
               (count(*) filter (where x.res ->> 'grade' in ('A', 'B')))::int as nb,
               round(avg((x.res ->> 'final')::numeric), 2) as mean,
               coalesce(bool_or(x.res ->> 'grade' = 'E'), false) as emonth
          from (select coalesce(r.result, public.perf_calc(r)) as res
                  from public.perf_reviews r
                 where r.team_member_id = t.id and r.status = 'final'
                   and r.period >= v_f and r.period < v_t) x) f
     where f.nmonths > 0 or (t.active and public.perf_reviewed(t.id))
  ), e as (
    select m.*, array_remove(array[
             case when m.nmonths = 0 then 'no-final-month' end,
             case when m.nmonths > 0 and m.nb < 3 then 'few-b-months' end,
             case when m.emonth then 'e-month' end,
             case when m.ml4 then 'critical-breach' end,
             case when not m.mactive then 'inactive' end], null) as why
      from m
  ), u as (
    select e.*, cardinality(e.why) = 0 as ok,
           case when cardinality(e.why) = 0 then
             case public.perf_grade_of(e.mean) when 'A' then 3.0 when 'B' then 1.5 when 'C' then 0.5 else 0 end
           else 0 end as units
      from e
  ), s as (
    select u.*, sum(u.units) over () as allunits from u
  ), o as (
    select s.*,
           case when s.allunits > 0 then floor(v_pool * 100 * s.units / s.allunits) / 100 else 0 end as bonus,
           case when s.allunits > 0 then floor(v_trip * 100 * s.units / s.allunits) / 100 else 0 end as tripshare
      from s
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'team_member_id', o.mid, 'name', o.mname, 'staff_code', o.mcode, 'active', o.mactive,
           'months', o.nmonths, 'months_b', o.nb, 'average', o.mean,
           'grade', case when o.nmonths > 0 then public.perf_grade_of(o.mean) end,
           'e_month', o.emonth, 'l4', o.ml4, 'eligible', o.ok, 'reasons', to_jsonb(o.why),
           'units', o.units, 'bonus', o.bonus, 'trip', o.tripshare)
         order by o.ok desc, o.units desc, o.mean desc nulls last, o.mname), '[]'::jsonb),
         coalesce(sum(o.units), 0), coalesce(sum(o.bonus), 0), coalesce(sum(o.tripshare), 0)
    into v_rows, v_units, v_bpaid, v_tpaid
    from o;
  return jsonb_build_object('period', v_f, 'word', public.perf_period_word(v_f),
    'last_month', (v_t - interval '1 month')::date, 'ended', public.perf_today() >= v_t,
    'figures', v_c.period is not null, 'total_units', v_units, 'people', v_rows,
    'bonus', jsonb_build_object('open', v_popen, 'pool', v_pool, 'paid', v_bpaid, 'remainder', v_pool - v_bpaid,
      'reason', case when v_c.period is null then 'figures-needed' when not v_popen then 'below-gate'
                     when v_pool = 0 then 'no-pool' when v_units = 0 then 'nobody-eligible' end),
    'trip', jsonb_build_object('open', v_topen, 'budget', v_trip, 'paid', v_tpaid, 'remainder', v_trip - v_tpaid,
      'reason', case when v_c.period is null then 'figures-needed' when not v_topen then 'below-gate'
                     when v_trip = 0 then 'no-budget' when v_units = 0 then 'nobody-eligible' end));
end $$;

/* One commission, read against the month it was invoiced in. */
create or replace function public.perf_commission_json(c public.perf_commissions)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_r public.perf_reviews; v_res jsonb; v_state text; v_why text;
begin
  select * into v_r from public.perf_reviews where team_member_id = c.team_member_id and period = c.month;
  v_res := case when v_r.id is not null and v_r.status = 'final' then coalesce(v_r.result, public.perf_calc(v_r)) end;
  if v_res is null then
    v_state := 'pending'; v_why := 'month-not-final';
  elsif (v_res ->> 'final')::numeric < 70 then
    v_state := 'not-payable'; v_why := 'below-c';
  elsif coalesce((v_res ->> 'l3')::boolean, false) or coalesce((v_res ->> 'l4')::boolean, false) then
    v_state := 'not-payable'; v_why := 'breach';
  else
    v_state := 'payable';
  end if;
  return jsonb_build_object('id', c.id, 'team_member_id', c.team_member_id,
    'name', (select t.name from public.team_members t where t.id = c.team_member_id),
    'staff_code', (select t.staff_code from public.team_members t where t.id = c.team_member_id),
    'client_id', c.client_id,
    'client', (select cl.name from public.clients cl where cl.id = c.client_id),
    'client_code', (select cl.client_code from public.clients cl where cl.id = c.client_id),
    'description', c.description, 'month', c.month, 'month_word', public.perf_month_word(c.month),
    'net_profit', c.net_profit, 'pct', c.pct, 'amount', round(c.net_profit * c.pct / 100, 2),
    'state', v_state, 'reason', v_why, 'created_at', c.created_at,
    'created_by', (select t.name from public.team_members t where t.id = c.created_by),
    'removed_at', c.removed_at);
end $$;

/* The caller's own row goes to management with its name alone: their own
   outcome is theirs to read in My performance. */
create or replace function public.perf_hide_own(p_rows jsonb, p_me uuid)
returns jsonb
language sql immutable as $$
  select coalesce(jsonb_agg(case when x ->> 'team_member_id' = p_me::text
                                 then jsonb_build_object('team_member_id', x -> 'team_member_id',
                                        'name', x -> 'name', 'staff_code', x -> 'staff_code', 'own', true)
                                 else x end order by n), '[]'::jsonb)
    from jsonb_array_elements(coalesce(p_rows, '[]'::jsonb)) with ordinality as a(x, n)
$$;

/* The history of a quarter, a period or the commissions: what was entered,
   confirmed and reopened, by whom and when. */
create or replace function public.perf_reward_events(p_kinds text[], p_key text)
returns jsonb
language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object('kind', e.kind, 'detail', e.detail - 'was', 'at', e.created_at,
           'by', coalesce(t.name, e.actor_email)) order by e.created_at desc), '[]'::jsonb)
    from (select * from public.perf_events pe
           where pe.kind = any(p_kinds) and (p_key is null or pe.detail ->> 'key' = p_key)
           order by pe.created_at desc limit 30) e
    left join public.team_members t on t.id = e.actor_id
$$;

-- 4. Management: the quarter -----------------------------------------------------------
create or replace function public.perf_quarter(p_token text, p_quarter date)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_err text; v_me public.team_members; v_q date; v_rw public.perf_rewards; v_out jsonb;
begin
  v_err := public.perf_check(p_token, 'view');
  if v_err is not null then return jsonb_build_object('error', v_err); end if;
  v_me := public.ops_me();
  v_q := date_trunc('quarter', coalesce(p_quarter, public.perf_today()))::date;
  if v_q < date '2026-07-01' then return jsonb_build_object('error', 'before-first'); end if;
  select * into v_rw from public.perf_rewards where kind = 'quarter' and period = v_q;
  v_out := coalesce(v_rw.snapshot, public.perf_quarter_calc(v_q));
  return v_out || jsonb_build_object(
    'people', public.perf_hide_own(v_out -> 'people', v_me.id),
    'confirmed', v_rw.period is not null, 'confirmed_at', v_rw.confirmed_at,
    'confirmed_by', (select t.name from public.team_members t where t.id = v_rw.confirmed_by),
    'ended', public.perf_today() >= (v_q + interval '3 months')::date,
    'events', public.perf_reward_events(array['dept_scored', 'quarter_confirmed', 'quarter_reopened'], v_q::text));
end $$;

create or replace function public.perf_dept_save(p_token text, p_quarter date, p_department text, p_payload jsonb)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_err text; v_me public.team_members; v_q date; v_c jsonb; v_i integer; v_v jsonb; v_n numeric[] := '{}';
  v_max constant numeric[] := array[25, 25, 20, 15, 15]; v_was public.perf_dept_scores; v_crit boolean;
  v_changed jsonb := '[]'::jsonb; v_old numeric[];
begin
  v_err := public.perf_check(p_token, 'work');
  if v_err is not null then return jsonb_build_object('error', v_err); end if;
  v_me := public.ops_me();
  v_q := date_trunc('quarter', p_quarter)::date;
  if v_q is null or v_q < date '2026-07-01' then return jsonb_build_object('error', 'before-first'); end if;
  if p_department is null or p_department not in ('creative', 'marketing') then
    return jsonb_build_object('error', 'bad-department');
  end if;
  if exists (select 1 from public.perf_rewards where kind = 'quarter' and period = v_q) then
    return jsonb_build_object('error', 'confirmed');
  end if;
  v_c := p_payload -> 'criteria';
  if v_c is null or jsonb_typeof(v_c) <> 'array' then return jsonb_build_object('error', 'bad-payload'); end if;
  if jsonb_array_length(v_c) <> 5 then return jsonb_build_object('error', 'bad-payload'); end if;
  for v_i in 1..5 loop
    v_v := v_c -> (v_i - 1);
    if jsonb_typeof(v_v) <> 'number' then
      return jsonb_build_object('error', 'bad-score', 'index', v_i, 'max', v_max[v_i]);
    end if;
    if (v_v #>> '{}')::numeric not between 0 and v_max[v_i]
       or round((v_v #>> '{}')::numeric, 1) <> (v_v #>> '{}')::numeric then
      return jsonb_build_object('error', 'bad-score', 'index', v_i, 'max', v_max[v_i]);
    end if;
    v_n := v_n || (v_v #>> '{}')::numeric;
  end loop;
  v_crit := coalesce((p_payload ->> 'critical')::boolean, false);
  select * into v_was from public.perf_dept_scores where quarter = v_q and department = p_department for update;
  insert into public.perf_dept_scores (quarter, department, c1, c2, c3, c4, c5, critical, entered_by, updated_at)
  values (v_q, p_department, v_n[1], v_n[2], v_n[3], v_n[4], v_n[5], v_crit, v_me.id, now())
  on conflict (quarter, department) do update set
    c1 = excluded.c1, c2 = excluded.c2, c3 = excluded.c3, c4 = excluded.c4, c5 = excluded.c5,
    critical = excluded.critical, entered_by = excluded.entered_by, updated_at = now();
  v_old := array[v_was.c1, v_was.c2, v_was.c3, v_was.c4, v_was.c5];
  for v_i in 1..5 loop
    if v_old[v_i] is distinct from v_n[v_i] then
      v_changed := v_changed || jsonb_build_array(jsonb_build_object('key', 'c' || v_i, 'from', v_old[v_i], 'to', v_n[v_i]));
    end if;
  end loop;
  if v_was.critical is distinct from v_crit then
    v_changed := v_changed || jsonb_build_array(jsonb_build_object('key', 'critical', 'from', v_was.critical, 'to', v_crit));
  end if;
  if jsonb_array_length(v_changed) > 0 then
    perform public.perf_log(null, null, 'dept_scored',
      jsonb_build_object('key', v_q::text, 'department', p_department, 'changed', v_changed));
  end if;
  return public.perf_quarter(p_token, v_q);
end $$;

create or replace function public.perf_quarter_confirm(p_token text, p_quarter date)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_err text; v_me public.team_members; v_q date; v_snap jsonb; v_x jsonb;
begin
  v_err := public.perf_check(p_token, 'work');
  if v_err is not null then return jsonb_build_object('error', v_err); end if;
  v_me := public.ops_me();
  v_q := date_trunc('quarter', p_quarter)::date;
  if v_q is null or v_q < date '2026-07-01' then return jsonb_build_object('error', 'before-first'); end if;
  if exists (select 1 from public.perf_rewards where kind = 'quarter' and period = v_q) then
    return public.perf_quarter(p_token, v_q);
  end if;
  if public.perf_today() < (v_q + interval '3 months')::date then
    return jsonb_build_object('error', 'quarter-open');
  end if;
  if (select count(*) from public.perf_dept_scores where quarter = v_q) < 2 then
    return jsonb_build_object('error', 'dept-scores-needed');
  end if;
  v_snap := public.perf_quarter_calc(v_q);
  insert into public.perf_rewards (kind, period, snapshot, confirmed_by) values ('quarter', v_q, v_snap, v_me.id)
  on conflict (kind, period) do nothing;
  perform public.perf_log(null, null, 'quarter_confirmed', jsonb_build_object('key', v_q::text,
    'winners', v_snap -> 'individual' -> 'winners', 'departments', v_snap -> 'department_prize' -> 'winners'));
  for v_x in select * from jsonb_array_elements(v_snap -> 'people') loop
    if (v_x ->> 'active')::boolean then
      perform public.perf_notify((v_x ->> 'team_member_id')::uuid, 'perf.quarter',
        'Your ' || public.perf_quarter_word(v_q) || ' quarterly outcome is ready.',
        'perf.quarter.' || v_q || '.' || (v_x ->> 'team_member_id') || '.' || extract(epoch from now())::bigint);
    end if;
  end loop;
  return public.perf_quarter(p_token, v_q);
end $$;

create or replace function public.perf_quarter_reopen(p_token text, p_quarter date)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_err text; v_q date; v_rw public.perf_rewards;
begin
  v_err := public.perf_check(p_token, 'manage');
  if v_err is not null then return jsonb_build_object('error', v_err); end if;
  v_q := date_trunc('quarter', p_quarter)::date;
  select * into v_rw from public.perf_rewards where kind = 'quarter' and period = v_q for update;
  if v_rw.period is null then return jsonb_build_object('error', 'not-confirmed'); end if;
  perform public.perf_log(null, null, 'quarter_reopened', jsonb_build_object('key', v_q::text, 'was', v_rw.snapshot,
    'confirmed_at', v_rw.confirmed_at));
  delete from public.perf_rewards where kind = 'quarter' and period = v_q;
  return public.perf_quarter(p_token, v_q);
end $$;

-- 5. Management: flexible hours, the period, commission ---------------------------------
create or replace function public.perf_flex(p_token text, p_period date)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_err text; v_me public.team_members; v_out jsonb;
begin
  v_err := public.perf_check(p_token, 'view');
  if v_err is not null then return jsonb_build_object('error', v_err); end if;
  v_me := public.ops_me();
  v_out := public.perf_flex_calc(p_period);
  return v_out || jsonb_build_object('people', public.perf_hide_own(v_out -> 'people', v_me.id));
end $$;

create or replace function public.perf_period(p_token text, p_from date)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_err text; v_me public.team_members; v_f date; v_rw public.perf_rewards; v_c public.perf_company; v_out jsonb;
begin
  v_err := public.perf_check(p_token, 'view');
  if v_err is not null then return jsonb_build_object('error', v_err); end if;
  v_me := public.ops_me();
  v_f := date_trunc('quarter', coalesce(p_from, public.perf_today()))::date;
  if v_f < date '2026-07-01' then return jsonb_build_object('error', 'before-first'); end if;
  select * into v_rw from public.perf_rewards where kind = 'period' and period = v_f;
  v_out := coalesce(v_rw.snapshot, public.perf_period_calc(v_f));
  v_out := v_out || jsonb_build_object(
    'people', public.perf_hide_own(v_out -> 'people', v_me.id),
    'admin', public.perf_is_admin(),
    'confirmed', v_rw.period is not null, 'confirmed_at', v_rw.confirmed_at,
    'confirmed_by', (select t.name from public.team_members t where t.id = v_rw.confirmed_by),
    'ended', public.perf_today() >= (v_f + interval '6 months')::date,
    'events', public.perf_reward_events(array['company_set', 'period_confirmed', 'period_reopened'], v_f::text));
  /* Revenue and profit, and the ceiling they set, for an admin alone. */
  if public.perf_is_admin() then
    select * into v_c from public.perf_company where period = v_f;
    if v_c.period is not null then
      v_out := v_out || jsonb_build_object('company', jsonb_build_object('revenue', v_c.revenue, 'profit', v_c.profit,
        'pool', v_c.pool, 'trip_budget', v_c.trip_budget, 'max_pool', greatest(0, floor(v_c.profit * 10) / 100)));
    end if;
  end if;
  return v_out;
end $$;

create or replace function public.perf_company_set(p_token text, p_from date, p_payload jsonb)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_err text; v_me public.team_members; v_f date; v_rev numeric; v_pro numeric; v_pool numeric; v_trip numeric;
  v_was public.perf_company; v_max numeric; v_changed jsonb := '[]'::jsonb;
begin
  v_err := public.perf_check(p_token, 'work');
  if v_err is not null then return jsonb_build_object('error', v_err); end if;
  if not public.perf_is_admin() then return jsonb_build_object('error', 'admin-only'); end if;
  v_me := public.ops_me();
  v_f := date_trunc('quarter', p_from)::date;
  if v_f is null or v_f < date '2026-07-01' then return jsonb_build_object('error', 'before-first'); end if;
  if exists (select 1 from public.perf_rewards where kind = 'period' and period = v_f) then
    return jsonb_build_object('error', 'confirmed');
  end if;
  if coalesce(jsonb_typeof(p_payload -> 'revenue'), '') <> 'number'
     or coalesce(jsonb_typeof(p_payload -> 'profit'), '') <> 'number'
     or coalesce(jsonb_typeof(p_payload -> 'pool'), 'number') not in ('number', 'null')
     or coalesce(jsonb_typeof(p_payload -> 'trip_budget'), 'number') not in ('number', 'null') then
    return jsonb_build_object('error', 'bad-amount');
  end if;
  v_rev := (p_payload ->> 'revenue')::numeric;
  v_pro := (p_payload ->> 'profit')::numeric;
  v_pool := coalesce((p_payload ->> 'pool')::numeric, 0);
  v_trip := coalesce((p_payload ->> 'trip_budget')::numeric, 0);
  if v_rev < 0 or v_pool < 0 or v_trip < 0
     or round(v_rev, 2) <> v_rev or round(v_pro, 2) <> v_pro or round(v_pool, 2) <> v_pool or round(v_trip, 2) <> v_trip
     or greatest(abs(v_rev), abs(v_pro), v_pool, v_trip) >= 1e12 then
    return jsonb_build_object('error', 'bad-amount');
  end if;
  v_max := greatest(0, floor(v_pro * 10) / 100);
  if v_pool > 0 and v_rev < 500000 then return jsonb_build_object('error', 'pool-closed'); end if;
  if v_pool > v_max then return jsonb_build_object('error', 'pool-over', 'max', v_max); end if;
  if v_trip > 0 and v_rev < 1000000 then return jsonb_build_object('error', 'trip-closed'); end if;
  select * into v_was from public.perf_company where period = v_f for update;
  insert into public.perf_company (period, revenue, profit, pool, trip_budget, entered_by, updated_at)
  values (v_f, v_rev, v_pro, v_pool, v_trip, v_me.id, now())
  on conflict (period) do update set revenue = excluded.revenue, profit = excluded.profit, pool = excluded.pool,
    trip_budget = excluded.trip_budget, entered_by = excluded.entered_by, updated_at = now();
  /* Revenue and profit are filed by name only, so the history an admin
     shares with the rest of management never carries them. */
  if v_was.revenue is distinct from v_rev then v_changed := v_changed || '[{"key":"revenue"}]'::jsonb; end if;
  if v_was.profit is distinct from v_pro then v_changed := v_changed || '[{"key":"profit"}]'::jsonb; end if;
  if v_was.pool is distinct from v_pool then
    v_changed := v_changed || jsonb_build_array(jsonb_build_object('key', 'pool', 'from', v_was.pool, 'to', v_pool));
  end if;
  if v_was.trip_budget is distinct from v_trip then
    v_changed := v_changed || jsonb_build_array(jsonb_build_object('key', 'trip_budget', 'from', v_was.trip_budget, 'to', v_trip));
  end if;
  if jsonb_array_length(v_changed) > 0 then
    perform public.perf_log(null, null, 'company_set', jsonb_build_object('key', v_f::text, 'changed', v_changed));
  end if;
  return public.perf_period(p_token, v_f);
end $$;

create or replace function public.perf_period_confirm(p_token text, p_from date)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_err text; v_me public.team_members; v_f date; v_snap jsonb; v_x jsonb;
begin
  v_err := public.perf_check(p_token, 'work');
  if v_err is not null then return jsonb_build_object('error', v_err); end if;
  v_me := public.ops_me();
  v_f := date_trunc('quarter', p_from)::date;
  if v_f is null or v_f < date '2026-07-01' then return jsonb_build_object('error', 'before-first'); end if;
  if exists (select 1 from public.perf_rewards where kind = 'period' and period = v_f) then
    return public.perf_period(p_token, v_f);
  end if;
  if public.perf_today() < (v_f + interval '6 months')::date then
    return jsonb_build_object('error', 'period-open');
  end if;
  if not exists (select 1 from public.perf_company where period = v_f) then
    return jsonb_build_object('error', 'figures-needed');
  end if;
  v_snap := public.perf_period_calc(v_f);
  insert into public.perf_rewards (kind, period, snapshot, confirmed_by) values ('period', v_f, v_snap, v_me.id)
  on conflict (kind, period) do nothing;
  perform public.perf_log(null, null, 'period_confirmed', jsonb_build_object('key', v_f::text));
  for v_x in select * from jsonb_array_elements(v_snap -> 'people') loop
    if (v_x ->> 'active')::boolean then
      perform public.perf_notify((v_x ->> 'team_member_id')::uuid, 'perf.period',
        'Your ' || public.perf_period_word(v_f) || ' bonus and trip outcome is ready.',
        'perf.period.' || v_f || '.' || (v_x ->> 'team_member_id') || '.' || extract(epoch from now())::bigint);
    end if;
  end loop;
  return public.perf_period(p_token, v_f);
end $$;

create or replace function public.perf_period_reopen(p_token text, p_from date)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_err text; v_f date; v_rw public.perf_rewards;
begin
  v_err := public.perf_check(p_token, 'manage');
  if v_err is not null then return jsonb_build_object('error', v_err); end if;
  v_f := date_trunc('quarter', p_from)::date;
  select * into v_rw from public.perf_rewards where kind = 'period' and period = v_f for update;
  if v_rw.period is null then return jsonb_build_object('error', 'not-confirmed'); end if;
  perform public.perf_log(null, null, 'period_reopened', jsonb_build_object('key', v_f::text, 'was', v_rw.snapshot,
    'confirmed_at', v_rw.confirmed_at));
  delete from public.perf_rewards where kind = 'period' and period = v_f;
  return public.perf_period(p_token, v_f);
end $$;

/* Every standing commission but the caller's own, the clients a deal may
   name and the colleagues it may be entered for. */
create or replace function public.perf_commissions(p_token text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_err text; v_me public.team_members;
begin
  v_err := public.perf_check(p_token, 'view');
  if v_err is not null then return jsonb_build_object('error', v_err); end if;
  v_me := public.ops_me();
  return jsonb_build_object(
    'rows', coalesce((select jsonb_agg(public.perf_commission_json(c) order by c.month desc, c.created_at desc)
                        from public.perf_commissions c
                       where c.removed_at is null and c.team_member_id <> v_me.id), '[]'::jsonb),
    'clients', coalesce((select jsonb_agg(jsonb_build_object('id', cl.id, 'name', cl.name, 'client_code', cl.client_code)
                                          order by cl.name)
                           from public.clients cl
                          where cl.stage in ('active', 'paused', 'past')), '[]'::jsonb),
    'members', coalesce((select jsonb_agg(jsonb_build_object('id', t.id, 'name', t.name, 'staff_code', t.staff_code)
                                          order by t.name)
                           from public.team_members t where t.active and t.id <> v_me.id), '[]'::jsonb),
    'events', public.perf_reward_events(array['commission_added', 'commission_removed', 'commission_restored'], null));
end $$;

create or replace function public.perf_commission_add(p_token text, p_payload jsonb)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_err text; v_me public.team_members; v_mem uuid; v_cl uuid; v_mon date; v_np numeric; v_pct numeric;
  v_row public.perf_commissions;
begin
  v_err := public.perf_check(p_token, 'work');
  if v_err is not null then return jsonb_build_object('error', v_err); end if;
  v_me := public.ops_me();
  begin v_mem := (p_payload ->> 'team_member_id')::uuid; exception when others then v_mem := null; end;
  if v_mem is null or not exists (select 1 from public.team_members where id = v_mem and active) then
    return jsonb_build_object('error', 'bad-member');
  end if;
  if v_mem = v_me.id then return jsonb_build_object('error', 'own-review'); end if;
  if coalesce(p_payload ->> 'client_id', '') <> '' then
    begin v_cl := (p_payload ->> 'client_id')::uuid; exception when others then v_cl := null; end;
    if v_cl is null or not exists (select 1 from public.clients where id = v_cl) then
      return jsonb_build_object('error', 'bad-client');
    end if;
  end if;
  if coalesce(btrim(p_payload ->> 'description'), '') = '' then return jsonb_build_object('error', 'description-needed'); end if;
  begin v_mon := (p_payload ->> 'month')::date; exception when others then v_mon := null; end;
  if v_mon is null or extract(day from v_mon) <> 1 or v_mon < date '2026-06-01'
     or v_mon > date_trunc('month', public.perf_today())::date then
    return jsonb_build_object('error', 'bad-month');
  end if;
  if coalesce(jsonb_typeof(p_payload -> 'net_profit'), '') <> 'number' then return jsonb_build_object('error', 'bad-amount'); end if;
  v_np := (p_payload ->> 'net_profit')::numeric;
  if v_np < 0 or round(v_np, 2) <> v_np or v_np >= 1e12 then return jsonb_build_object('error', 'bad-amount'); end if;
  if coalesce(jsonb_typeof(p_payload -> 'pct'), '') <> 'number' then return jsonb_build_object('error', 'bad-pct'); end if;
  v_pct := (p_payload ->> 'pct')::numeric;
  if v_pct <= 0 or v_pct > 100 or round(v_pct, 2) <> v_pct then return jsonb_build_object('error', 'bad-pct'); end if;
  insert into public.perf_commissions (team_member_id, client_id, description, month, net_profit, pct, created_by)
  values (v_mem, v_cl, btrim(p_payload ->> 'description'), v_mon, v_np, v_pct, v_me.id)
  returning * into v_row;
  perform public.perf_log(null, v_mem, 'commission_added', jsonb_build_object('commission', v_row.id,
    'month', v_mon, 'net_profit', v_np, 'pct', v_pct));
  return public.perf_commission_json(v_row);
end $$;

create or replace function public.perf_commission_remove(p_token text, p_id uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_err text; v_me public.team_members; v_row public.perf_commissions;
begin
  v_err := public.perf_check(p_token, 'work');
  if v_err is not null then return jsonb_build_object('error', v_err); end if;
  v_me := public.ops_me();
  select * into v_row from public.perf_commissions where id = p_id for update;
  if v_row.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if v_row.team_member_id = v_me.id then return jsonb_build_object('error', 'own-review'); end if;
  if v_row.removed_at is null then
    update public.perf_commissions set removed_at = now(), removed_by = v_me.id where id = p_id returning * into v_row;
    perform public.perf_log(null, v_row.team_member_id, 'commission_removed', jsonb_build_object('commission', p_id));
  end if;
  return public.perf_commission_json(v_row);
end $$;

create or replace function public.perf_commission_restore(p_token text, p_id uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_err text; v_me public.team_members; v_row public.perf_commissions;
begin
  v_err := public.perf_check(p_token, 'work');
  if v_err is not null then return jsonb_build_object('error', v_err); end if;
  v_me := public.ops_me();
  select * into v_row from public.perf_commissions where id = p_id for update;
  if v_row.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if v_row.team_member_id = v_me.id then return jsonb_build_object('error', 'own-review'); end if;
  if v_row.removed_at is not null then
    update public.perf_commissions set removed_at = null, removed_by = null where id = p_id returning * into v_row;
    perform public.perf_log(null, v_row.team_member_id, 'commission_restored', jsonb_build_object('commission', p_id));
  end if;
  return public.perf_commission_json(v_row);
end $$;

-- 6. The member: their own outcome ------------------------------------------------------
/* The signed-in person's own confirmed quarters and periods, flexible hours
   for each month once it is decided, and commissions once the month is
   final. Never another person's score, share or figure. */
create or replace function public.perf_rewards_mine()
returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_me public.team_members; v_id text;
begin
  v_me := public.ops_me();
  if v_me.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if public.perf_guarded(v_me.id) and not public.perf_code_fresh() then
    return jsonb_build_object('error', 'code-needed');
  end if;
  v_id := v_me.id::text;
  return jsonb_build_object(
    'quarters', coalesce((
      select jsonb_agg(jsonb_build_object('quarter', rw.period, 'word', rw.snapshot ->> 'word',
               'confirmed_at', rw.confirmed_at, 'me', me_row,
               'individual', jsonb_build_object('winners', rw.snapshot -> 'individual' -> 'winners',
                                                'reason', rw.snapshot -> 'individual' -> 'reason'),
               'department', (select jsonb_build_object('department', d ->> 'department', 'total', d -> 'total',
                                       'grade', d -> 'grade', 'won', d -> 'won', 'each', d -> 'each')
                                from jsonb_array_elements(rw.snapshot -> 'departments') d
                               where d -> 'members' ? v_id limit 1))
             order by rw.period desc)
        from public.perf_rewards rw
        cross join lateral (select p as me_row from jsonb_array_elements(rw.snapshot -> 'people') p
                             where p ->> 'team_member_id' = v_id limit 1) mine
       where rw.kind = 'quarter'), '[]'::jsonb),
    'periods', coalesce((
      select jsonb_agg(jsonb_build_object('period', rw.period, 'word', rw.snapshot ->> 'word',
               'confirmed_at', rw.confirmed_at, 'me', me_row,
               'bonus_open', rw.snapshot -> 'bonus' -> 'open', 'trip_open', rw.snapshot -> 'trip' -> 'open')
             order by rw.period desc)
        from public.perf_rewards rw
        cross join lateral (select p as me_row from jsonb_array_elements(rw.snapshot -> 'people') p
                             where p ->> 'team_member_id' = v_id limit 1) mine
       where rw.kind = 'period'), '[]'::jsonb),
    'flex', coalesce((
      select jsonb_agg(jsonb_build_object('period', f.fx ->> 'period', 'month', f.fx ->> 'month',
               'next_month', f.fx ->> 'next_month', 'unlocked', f.fx -> 'unlocked',
               'eligible', (select p -> 'eligible' from jsonb_array_elements(f.fx -> 'people') p
                             where p ->> 'team_member_id' = v_id limit 1))
             order by f.pd desc)
        from (select r.period as pd, public.perf_flex_calc(r.period) as fx
                from public.perf_reviews r
               where r.team_member_id = v_me.id and r.status = 'final') f
       where (f.fx ->> 'decided')::boolean
         and exists (select 1 from jsonb_array_elements(f.fx -> 'people') p where p ->> 'team_member_id' = v_id)), '[]'::jsonb),
    'commissions', coalesce((
      select jsonb_agg(x.j - 'created_by' - 'removed_at' - 'name' - 'staff_code' order by x.mo desc, x.ca desc)
        from (select public.perf_commission_json(c) as j, c.month as mo, c.created_at as ca
                from public.perf_commissions c
               where c.team_member_id = v_me.id and c.removed_at is null) x
       where x.j ->> 'state' <> 'pending'), '[]'::jsonb));
end $$;

