-- ===========================================================================
-- A PERFORMANCE RECORD CAN BE DELETED — by an admin, with the master code
-- unlocked, the member's name and month typed back and a reason.
-- 2026-09-28. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/perf.js compares the
-- two.
--
-- WHAT CHANGED (the user, 2026-09-27: "the team performance is missing the
-- delete records for admins"; then chose "any state, with safeguards"):
--  1. `perf_delete` removes one member's month, whatever its state, for an
--     admin alone (`perf_is_admin`, on top of `team.performance` at Manage
--     and a live unlock), never on the admin's own review. The name and the
--     month are typed back (`{name} {Month YYYY}`, case and spaces ignored)
--     and a reason is required. The review, its disputes and its scores go.
--  2. What happened to it is kept. The review's history rows stay (their
--     link to the review is let go rather than deleted with it; the
--     append-only guard now lets that one database write through), and one row
--     more says who deleted which month, when and why, with no score in it.
--     The Activity record's Performance tab reads it as Record deleted.
--  3. A printed record is a document somebody may still hold, so it never
--     becomes "not found": `perf_deleted` keeps its reference, and
--     `/verify/` answers it as an HR Letter, Void. A new review of the same
--     month, once printed, is answered first, as Valid.
--
-- ROLLBACK
--   drop function if exists public.perf_delete(text, uuid, text, text);
--   Re-run perf_events_frozen from THE PERFORMANCE SYSTEM.
--   drop table if exists public.perf_deleted;
--   Re-run verify_serial and perf_activity from PERFORMANCE RECORDS, THEIR
--   TRAIL AND THEIR CHECK.
--   alter table public.perf_events drop constraint if exists perf_events_review_id_fkey,
--     add constraint perf_events_review_id_fkey foreign key (review_id)
--     references public.perf_reviews(id) on delete cascade;
-- ===========================================================================

/* The history outlives the review: deleting a review lets go of its rows'
   link instead of deleting them. The history stays append-only to every
   write a function makes; only the database's own work below another write
   passes (depth > 1), and there an update keeps its new value. Returning the
   old row, as before, quietly cancelled the database's set-null and left the
   row pointing at a review that no longer exists. */
create or replace function public.perf_events_frozen()
returns trigger language plpgsql as $$
begin
  if pg_trigger_depth() > 1 then
    if tg_op = 'DELETE' then return old; end if;
    return new;
  end if;
  raise exception 'perf-events-append-only';
end $$;
revoke all on function public.perf_events_frozen() from public, anon, authenticated;

do $$
begin
  if exists (select 1 from pg_constraint
              where conname = 'perf_events_review_id_fkey' and confdeltype = 'c') then
    alter table public.perf_events drop constraint perf_events_review_id_fkey;
    alter table public.perf_events add constraint perf_events_review_id_fkey
      foreign key (review_id) references public.perf_reviews(id) on delete set null;
  end if;
end $$;

/* One row per deleted month: enough to answer a printed reference honestly
   and to say who removed it. No score, no grade, no note. */
create table if not exists public.perf_deleted (
  id             uuid primary key default gen_random_uuid(),
  team_member_id uuid references public.team_members(id) on delete cascade,
  period         date not null,
  serial         text,
  status         text not null,
  printed        boolean not null default false,
  released_at    timestamptz,
  deleted_at     timestamptz not null default now(),
  deleted_by     uuid references public.team_members(id) on delete set null,
  reason         text not null
);
create index if not exists perf_deleted_serial_idx on public.perf_deleted(upper(serial)) where serial is not null;
alter table public.perf_deleted enable row level security;
revoke all on public.perf_deleted from public, anon, authenticated;

create or replace function public.perf_delete(p_token text, p_review uuid, p_confirm text, p_reason text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_err     text;
  v_me      public.team_members;
  v_rev     public.perf_reviews;
  v_name    text;
  v_month   text;
  v_printed boolean;
begin
  v_err := public.perf_check(p_token, 'manage');
  if v_err is not null then return jsonb_build_object('error', v_err); end if;
  if not public.perf_is_admin() then return jsonb_build_object('error', 'admin-only'); end if;
  v_me := public.ops_me();
  select * into v_rev from public.perf_reviews pr where pr.id = p_review for update;
  if v_rev.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if v_rev.team_member_id = v_me.id then return jsonb_build_object('error', 'own-review'); end if;
  if coalesce(btrim(p_reason), '') = '' then return jsonb_build_object('error', 'reason-needed'); end if;
  select tm.name into v_name from public.team_members tm where tm.id = v_rev.team_member_id;
  v_month := public.perf_month_word(v_rev.period);
  if lower(regexp_replace(btrim(coalesce(p_confirm, '')), '\s+', ' ', 'g'))
     <> lower(regexp_replace(btrim(coalesce(v_name, '') || ' ' || v_month), '\s+', ' ', 'g')) then
    return jsonb_build_object('error', 'confirm-mismatch');
  end if;
  v_printed := exists (select 1 from public.perf_events pe where pe.review_id = v_rev.id and pe.kind = 'printed');

  insert into public.perf_deleted (team_member_id, period, serial, status, printed, released_at, deleted_by, reason)
  values (v_rev.team_member_id, v_rev.period, v_rev.serial, v_rev.status, v_printed, v_rev.released_at,
          v_me.id, btrim(p_reason));
  perform public.perf_log(null, v_rev.team_member_id, 'deleted',
    jsonb_build_object('period', v_rev.period, 'month', v_month, 'serial', v_rev.serial,
                       'status', v_rev.status, 'printed', v_printed, 'reason', btrim(p_reason)));
  delete from public.perf_reviews pr where pr.id = v_rev.id;
  return jsonb_build_object('ok', true, 'month', v_month, 'status', v_rev.status, 'printed', v_printed);
end $$;
revoke all on function public.perf_delete(text, uuid, text, text) from public, anon;
grant execute on function public.perf_delete(text, uuid, text, text) to authenticated;

/* The Activity record's Performance tab: the steps it lists, and now a
   deleted month, whose period comes from the row itself. */
create or replace function public.perf_activity(p_limit integer default 200)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare me_row public.team_members;
begin
  me_row := public.ops_me();
  if me_row.id is null or not public.ops_granted('team.performance', 'view') then
    return jsonb_build_object('error', 'denied');
  end if;
  return jsonb_build_object('rows', coalesce((
    select jsonb_agg(jsonb_build_object(
             'at', e.created_at, 'kind', e.kind, 'member', tm.name,
             'period', coalesce(rv.period, case when e.kind = 'deleted' then (e.detail ->> 'period')::date end),
             'actor', e.actor_email, 'actor_name', ac.name) order by e.created_at desc)
      from (select pe.* from public.perf_events pe
             where pe.kind in ('released', 'disputed', 'decided', 'acknowledged',
                               'finalised', 'reopened', 'returned', 'printed', 'deleted')
               and pe.team_member_id is distinct from me_row.id
             order by pe.created_at desc
             limit greatest(1, least(coalesce(p_limit, 200), 500))) e
      left join public.team_members tm on tm.id = e.team_member_id
      left join public.perf_reviews rv on rv.id = e.review_id
      left join public.team_members ac on ac.id = e.actor_id), '[]'::jsonb));
end $$;
revoke all on function public.perf_activity(integer) from public, anon, authenticated;
grant execute on function public.perf_activity(integer) to authenticated;

/* The verify page, with a deleted printed record answered as Void. A
   standing record under the same reference is answered first. */
create or replace function public.verify_serial(p_serial text)
returns jsonb
language plpgsql security definer stable set search_path = public as $$
declare
  s text := upper(btrim(coalesce(p_serial, '')));
  sd text;
  d public.documents%rowtype;
  l public.client_documents%rowtype;
  rv public.perf_reviews%rowtype;
  dl public.perf_deleted%rowtype;
begin
  if length(s) < 3 or length(s) > 40 then return jsonb_build_object('found', false); end if;
  sd := replace(s, '/', '-');
  select * into d from public.documents
   where upper(serial) = s or replace(upper(serial), '/', '-') = sd
   order by (upper(serial) = s) desc, (voided_at is null) desc, created_at desc limit 1;
  if d.id is not null then
    return jsonb_build_object('found', true, 'serial', d.serial,
      'kind', case when d.family = 'hr' then 'HR Letter' else d.kind end,
      'issued_at', d.issued_at,
      'state', case when d.voided_at is null then 'valid' else 'voided' end);
  end if;
  select * into l from public.client_documents
   where upper(number) = s or replace(upper(number), '/', '-') = sd
   order by (upper(number) = s) desc limit 1;
  if l.id is not null then
    return jsonb_build_object('found', true, 'serial', l.number, 'kind', 'Letter of Offer',
      'issued_at', l.issued_at,
      'state', case when l.voided_at is not null then 'voided'
                    when l.superseded_by is not null then 'replaced'
                    else 'valid' end);
  end if;
  select * into rv from public.perf_reviews pr
   where (upper(pr.serial) = s or replace(upper(pr.serial), '/', '-') = sd)
     and exists (select 1 from public.perf_events pe where pe.review_id = pr.id and pe.kind = 'printed')
   limit 1;
  if rv.id is not null then
    return jsonb_build_object('found', true, 'serial', rv.serial, 'kind', 'HR Letter',
      'issued_at', rv.released_at,
      'state', case when rv.status = 'draft' then 'replaced' else 'valid' end);
  end if;
  select * into dl from public.perf_deleted pd
   where pd.printed and (upper(pd.serial) = s or replace(upper(pd.serial), '/', '-') = sd)
   order by pd.deleted_at desc limit 1;
  if dl.id is not null then
    return jsonb_build_object('found', true, 'serial', dl.serial, 'kind', 'HR Letter',
      'issued_at', dl.released_at, 'state', 'voided');
  end if;
  return jsonb_build_object('found', false);
end $$;
revoke all on function public.verify_serial(text) from public;
grant execute on function public.verify_serial(text) to anon, authenticated;

-- END OF A PERFORMANCE RECORD CAN BE DELETED ---------------------------------

-- ===========================================================================
-- RELEASE WITH OR WITHOUT TELLING — a month is released with a tick for
-- whether the member is notified.
-- 2026-09-28. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/perf.js compares the
-- two.
--
-- WHAT CHANGED (the user, 2026-09-27: "when releasing the performance review
-- could you give an optional notification tick, to notify or not to notify,
-- to the team member. So we wont need to specifically notify them when i
-- issue for June July and August 2026 and also for future months if
-- applicable"):
--   `perf_release` takes `p_notify` (true unless the page says otherwise).
--   Unticked, the release writes no notification: nothing in the bell, and
--   so nothing on the member's phone. The release itself, its reference, its
--   dispute window and its history row are unchanged; the history row says
--   whether the member was told. The member still reads the released month
--   on My performance whenever they open it.
--   The three-argument version is dropped first: PostgREST cannot choose
--   between two versions a call fits.
--
-- ROLLBACK
--   drop function if exists public.perf_release(text, uuid, integer, boolean);
--   Re-run perf_release from THE PERFORMANCE SYSTEM.
-- ===========================================================================

drop function if exists public.perf_release(text, uuid, integer);

create or replace function public.perf_release(p_token text, p_review uuid, p_rev integer, p_notify boolean default true)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare err text; m public.team_members; r public.perf_reviews; tm public.team_members;
begin
  err := public.perf_check(p_token, 'work');
  if err is not null then return jsonb_build_object('error', err); end if;
  m := public.ops_me();
  select * into r from public.perf_reviews where id = p_review for update;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if r.team_member_id = m.id then return jsonb_build_object('error', 'own-review'); end if;
  if p_rev is not null and r.rev <> p_rev then
    return jsonb_build_object('error', 'stale', 'record', public.perf_json(r, true));
  end if;
  if r.status <> 'draft' then return jsonb_build_object('error', 'not-draft'); end if;
  if not (public.perf_calc(r) ->> 'complete')::boolean then
    return jsonb_build_object('error', 'incomplete');
  end if;
  select * into tm from public.team_members where id = r.team_member_id;
  if r.serial is null and coalesce(btrim(tm.staff_code), '') = '' then
    return jsonb_build_object('error', 'no-staff-code');
  end if;
  update public.perf_reviews set status = 'released', released_at = now(),
         dispute_until = now() + interval '3 days', reviewer_id = m.id,
         serial = coalesce(serial, 'ADHR/' || upper(btrim(tm.staff_code)) || '/PR' || to_char(period, 'YYMM')),
         rev = rev + 1, updated_at = now()
   where id = r.id returning * into r;
  perform public.perf_log(r.id, r.team_member_id, 'released',
    jsonb_build_object('version', r.version, 'notified', coalesce(p_notify, true)));
  if coalesce(p_notify, true) then
    perform public.perf_notify(r.team_member_id, 'perf.released',
      'Your ' || public.perf_month_word(r.period) || ' performance review is ready.',
      'perf.released.' || r.id || '.' || r.version);
  end if;
  return public.perf_json(r, true);
end $$;
revoke all on function public.perf_release(text, uuid, integer, boolean) from public, anon;
grant execute on function public.perf_release(text, uuid, integer, boolean) to authenticated;

-- END OF RELEASE WITH OR WITHOUT TELLING -------------------------------------

-- ===========================================================================
-- CLIENT BILLING COLUMNS — a client's billing details are read only by the
-- people Clients: Billing admits.
-- 2026-09-28. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/sql.js compares the
-- two.
--
-- WHAT CHANGED
--   `clients_read` lets anybody with Clients, Content Review, Creator
--   Campaigns or Reports at View read the whole row, so the registered name,
--   the registration numbers, the tax numbers, the billing contact, the
--   finance email and the billing address reached people the Billing part
--   refuses, through the API if not on the page. A policy cannot hide a
--   column, so the columns themselves are withheld:
--   - the table's SELECT is taken from anon and authenticated, and given back
--     column by column for every column except the billing ones (worked out
--     from the table as it stands, so a column added later is granted by
--     running this section again);
--   - `client_billing(p_ids)` answers the billing columns to Clients: Billing
--     at View, and only the registered name and billing address to
--     Documents at Work (a letter is addressed to them). Every row also
--     names the required fields left blank (`billing_missing`), which
--     Clients at View reads without the values, so the Active gate still
--     says what is missing. Anybody else gets no rows.
--   Writes are unchanged: `clients_billing_guard` still asks Clients: Billing
--   at Work for a change to these columns.
--
-- ROLLBACK
--   grant select on table public.clients to authenticated;
--   drop function if exists public.client_billing(uuid[]);
-- ===========================================================================

revoke select on table public.clients from anon, authenticated;

do $$
declare cols text;
begin
  select string_agg(quote_ident(c.column_name), ', ' order by c.ordinal_position) into cols
    from information_schema.columns c
   where c.table_schema = 'public' and c.table_name = 'clients'
     and c.column_name not in ('legal_name', 'company_no', 'company_no_old', 'tin', 'sst_no',
                               'bill_contact', 'bill_contact_email', 'bill_contact_phone',
                               'bill_contact_id', 'finance_email', 'billing_address',
                               'script_key');
  execute format('grant select (%s) on table public.clients to authenticated', cols);
end $$;

-- Dropped first, so a later change to what it returns re-creates it.
drop function if exists public.client_billing(uuid[]);
create or replace function public.client_billing(p_ids uuid[] default null)
returns table (id uuid, legal_name text, company_no text, company_no_old text, tin text,
               sst_no text, bill_contact_id uuid, bill_contact text, bill_contact_email text,
               bill_contact_phone text, finance_email text, billing_address text,
               billing_missing text[])
language sql stable security definer set search_path = public as $$
  select c.id,
         case when p.bill or p.docs then c.legal_name end,
         case when p.bill then c.company_no end,
         case when p.bill then c.company_no_old end,
         case when p.bill then c.tin end,
         case when p.bill then c.sst_no end,
         case when p.bill then c.bill_contact_id end,
         case when p.bill then c.bill_contact end,
         case when p.bill then c.bill_contact_email end,
         case when p.bill then c.bill_contact_phone end,
         case when p.bill then c.finance_email end,
         case when p.bill or p.docs then c.billing_address end,
         array_remove(array[
           case when coalesce(btrim(c.legal_name), '') = '' then 'legal_name' end,
           case when coalesce(btrim(c.company_no), '') = '' then 'company_no' end,
           case when coalesce(btrim(c.billing_address), '') = '' then 'billing_address' end], null)
    from public.clients c,
         (select public.allowed('clients.billing', 'view') as bill,
                 public.register_may('client', 'work') as docs,
                 public.allowed('clients', 'view') as cv) p
   where (p.bill or p.docs or p.cv)
     and (p_ids is null or c.id = any(p_ids))
$$;
revoke all on function public.client_billing(uuid[]) from public, anon;
grant execute on function public.client_billing(uuid[]) to authenticated;

-- END OF CLIENT BILLING COLUMNS ----------------------------------------------

-- ===========================================================================
-- THE OVERVIEW — the start page for a group that manages a section reads
-- what each section has waiting.
-- 2026-09-28. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/sql.js compares the
-- two.
--
-- WHAT CHANGED
--   1. `batches.published_at`: when a content set was last published,
--      stamped by a trigger on the move to published and cleared on
--      Unpublish, so "waiting on the client for N days" is a fact and not a
--      guess. Sets already published take the time their last post was
--      added (the nearest thing to a publish date they hold).
--   2. `ops_report` answers `open_by_person` (each Task Owner's open tasks
--      and how many are late) where `ops.all` is granted, so the Report and
--      the Overview count the open work one way. Nothing else in it moves.
--   3. `perf_overview(p_period)`: for a month, each person on the review
--      list and the step their review has reached. Names and steps only,
--      never a score, a grade or a word of a dispute; `team.performance` at
--      View, as the Activity record's Performance tab.
--   Nothing here is money: the Overview shows no revenue, value or fee.
--
-- ROLLBACK
--   drop trigger if exists batches_published_at on public.batches;
--   drop function if exists public.batches_published_at();
--   alter table public.batches drop column if exists published_at;
--   drop function if exists public.perf_overview(date);
--   Re-run ops_report from THE OPERATIONS REPORT.
-- ===========================================================================

alter table public.batches add column if not exists published_at timestamptz;

create or replace function public.batches_published_at()
returns trigger language plpgsql set search_path = public as $$
begin
  if new.published and (tg_op = 'INSERT' or not coalesce(old.published, false)) then
    new.published_at := now();
  elsif not new.published then
    new.published_at := null;
  end if;
  return new;
end $$;
revoke all on function public.batches_published_at() from public, anon, authenticated;
drop trigger if exists batches_published_at on public.batches;
create trigger batches_published_at before insert or update of published on public.batches
  for each row execute function public.batches_published_at();

update public.batches b
   set published_at = coalesce((select max(p.created_at) from public.posts p where p.batch_id = b.id), b.created_at)
 where b.published and b.published_at is null;

create or replace function public.ops_report(
  p_from timestamptz default (now() - interval '90 days'),
  p_to   timestamptz default now())
returns jsonb
language plpgsql security definer stable set search_path = public as $$
declare
  out jsonb;
begin
  if not public.ops_granted('ops.reports', 'view') then
    return jsonb_build_object('error', 'denied');
  end if;

  with
  /* Where client review begins in each workflow. The final due date is the
     day the work is owed AT that stage, so everything below that position is
     "has not reached the client yet". Read from `stage_group` and never from
     a stage key: the two seeded workflows name that stage differently. */
  floors as (
    select workflow_id, min(position) as at
      from public.ops_workflow_stages
     where stage_group = 'client_review'
     group by workflow_id
  ),
  live as (
    select t.*, s.label as stage_label, s.position as stage_position,
           s.stage_group, f.at as review_at
      from public.ops_tasks t
      join public.ops_workflow_stages s
        on s.workflow_id = t.workflow_id and s.key = t.stage_key
      left join floors f on f.workflow_id = t.workflow_id
     where t.completed_at is null and t.cancelled_at is null
       and t.archived_at is null
  ),

  /* 1. WHAT IS RUNNING, by the words on the screen. Grouped by the stage's
        own label rather than by its group, because "what is on shooting" is
        the question and Shooting is a label, not a group. */
  running as (
    select jsonb_agg(x order by x ->> 'position', x ->> 'label') as j from (
      select jsonb_build_object(
               'stage_key', stage_key, 'label', stage_label,
               'position', stage_position, 'stage_group', stage_group,
               'count', count(*)) as x
        from live
       group by stage_key, stage_label, stage_position, stage_group
    ) q
  ),

  /* 2. WHAT IS LATE. Past the commitment and still short of client review.
        The same rule the queue row draws, stated once more here because a
        report a page computes for itself is a second definition. */
  late as (
    select jsonb_agg(x order by x ->> 'due_at') as j from (
      select jsonb_build_object(
               'task_id', l.id, 'task_no', l.task_no, 'title', l.title,
               'client', c.name, 'stage', l.stage_label,
               'due_at', l.current_final_due_at,
               'days_over', (current_date - l.current_final_due_at::date),
               'owner', (select tm.name
                           from public.ops_task_assignees a
                           join public.team_members tm on tm.id = a.team_member_id
                          where a.task_id = l.id and a.responsibility = 'owner'
                            and a.ended_at is null
                          limit 1)) as x
        from live l
        left join public.clients c on c.id = l.client_id
       where l.current_final_due_at is not null
         and l.current_final_due_at::date < current_date
         and (l.review_at is null or l.stage_position < l.review_at)
    ) q
  ),

  /* 3. HOW LONG EACH STAGE TAKES. A task enters a stage at the event that
        names it and leaves at the next event, or at its own ending, or now.
        Only spans that were ENTERED inside the period are counted, so the
        window means what it says and a task that sat in Editing since March
        does not land in every report for ever. */
  spans as (
    select e.task_id,
           e.to_value ->> 'stage_key' as stage_key,
           e.created_at as from_at,
           coalesce(
             lead(e.created_at) over (partition by e.task_id order by e.created_at),
             t.completed_at, t.cancelled_at, now()) as to_at
      from public.ops_task_events e
      join public.ops_tasks t on t.id = e.task_id
     where e.event_type in ('task_created', 'stage_changed')
       and e.to_value ->> 'stage_key' is not null
  ),
  /* One row per span and no grouping: an earlier draft grouped by the span's
     own timestamps, which silently collapsed two tasks that entered the same
     stage in the same instant into one measurement. The label is looked up
     once per stage below instead of aggregated here. */
  span_mins as (
    select s.stage_key,
           extract(epoch from (s.to_at - s.from_at)) / 60 as mins
      from spans s
     where s.from_at >= p_from and s.from_at < p_to
       and s.to_at > s.from_at
  ),
  stage_time as (
    select jsonb_agg(x order by x ->> 'label') as j from (
      select jsonb_build_object(
               'stage_key', stage_key,
               'label', coalesce((select w.label from public.ops_workflow_stages w
                                   where w.key = sm.stage_key limit 1), stage_key),
               'n', count(*),
               'median_minutes', round(percentile_cont(0.5) within group (order by mins))::int,
               'p90_minutes', round(percentile_cont(0.9) within group (order by mins))::int) as x
        from span_mins sm
       group by stage_key
    ) q
  ),

  /* 4. WAS IT THERE ON TIME. Of the tasks that reached client review inside
        the period, how many got there on or before the date they were owed.
        Replanning is counted beside it and never folded into it: an extension
        that moves the date would otherwise erase the miss it was granted for,
        and a rate that cannot be missed is not a measurement. */
  reached as (
    select distinct on (e.task_id)
           e.task_id, e.created_at as at, t.current_final_due_at as due,
           (t.original_final_due_at is distinct from t.current_final_due_at) as replanned
      from public.ops_task_events e
      join public.ops_tasks t on t.id = e.task_id
      join public.ops_workflow_stages w
        on w.workflow_id = t.workflow_id and w.key = e.to_value ->> 'stage_key'
     where e.event_type = 'stage_changed'
       and w.stage_group = 'client_review'
       and e.created_at >= p_from and e.created_at < p_to
     order by e.task_id, e.created_at
  ),
  on_time as (
    select jsonb_build_object(
             'reached', count(*),
             'met', count(*) filter (where due is null or at::date <= due::date),
             'missed', count(*) filter (where due is not null and at::date > due::date),
             'replanned', count(*) filter (where replanned)) as j
      from reached
  ),

  /* 5. BY PERSON. The foundation of a KPI and not a KPI: what somebody
        finished in the window, how much of it was on time, and how long their
        work took end to end. No ranking and no score — a number a person can
        check is worth more than a league table nobody trusts. */
  done as (
    select t.id, t.created_at, coalesce(t.completed_at, t.delivered_at) as ended,
           t.current_final_due_at as due,
           (select a.team_member_id
              from public.ops_task_assignees a
             where a.task_id = t.id and a.responsibility = 'owner'
             order by a.ended_at nulls first, a.assigned_at desc
             limit 1) as owner_id
      from public.ops_tasks t
     where t.completed_at is not null
       and t.completed_at >= p_from and t.completed_at < p_to
  ),
  by_person as (
    select jsonb_agg(x order by x ->> 'name') as j from (
      select jsonb_build_object(
               'team_member_id', d.owner_id,
               'name', coalesce(tm.name, 'Nobody'),
               'completed', count(*),
               'on_time', count(*) filter (where d.due is null or d.ended::date <= d.due::date),
               'median_cycle_minutes',
                 round(percentile_cont(0.5) within group (
                   order by extract(epoch from (d.ended - d.created_at)) / 60))::int) as x
        from done d
        left join public.team_members tm on tm.id = d.owner_id
       group by d.owner_id, tm.name
    ) q
  ),

  /* 6. WHO IS CARRYING THE OPEN WORK (2026-09-28). One row a Task Owner:
        the open tasks they hold, and how many of those are late by the rule
        in 2 above. The team's whole queue is `ops.all`, so it is answered
        only where that part is granted. */
  open_by_person as (
    select jsonb_agg(x order by (x ->> 'open')::int desc, x ->> 'name') as j from (
      select jsonb_build_object(
               'team_member_id', o.owner_id,
               'name', coalesce(tm.name, 'No task owner'),
               'open', count(*),
               'late', count(*) filter (where o.is_late)) as x
        from (select l.id,
                     (select a.team_member_id
                        from public.ops_task_assignees a
                       where a.task_id = l.id and a.responsibility = 'owner' and a.ended_at is null
                       limit 1) as owner_id,
                     (l.current_final_due_at is not null
                      and l.current_final_due_at::date < current_date
                      and (l.review_at is null or l.stage_position < l.review_at)) as is_late
                from live l) o
        left join public.team_members tm on tm.id = o.owner_id
       where public.ops_granted('ops.all', 'view')
       group by o.owner_id, tm.name
    ) q
  )

  select jsonb_build_object(
           'from', p_from, 'to', p_to,
           'running',    coalesce((select j from running), '[]'::jsonb),
           'late',       coalesce((select j from late), '[]'::jsonb),
           'stage_time', coalesce((select j from stage_time), '[]'::jsonb),
           'on_time',    coalesce((select j from on_time), '{}'::jsonb),
           'by_person',  coalesce((select j from by_person), '[]'::jsonb),
           'open_by_person', case when public.ops_granted('ops.all', 'view')
                                  then coalesce((select j from open_by_person), '[]'::jsonb) end)
    into out;

  return out;
end $$;
grant execute on function public.ops_report(timestamptz, timestamptz) to authenticated;

create or replace function public.perf_overview(p_period date)
returns jsonb
language plpgsql security definer stable set search_path = public as $$
declare me_row public.team_members; m date;
begin
  me_row := public.ops_me();
  if me_row.id is null or not public.ops_granted('team.performance', 'view') then
    return jsonb_build_object('error', 'denied');
  end if;
  m := date_trunc('month', coalesce(p_period, current_date))::date;
  return jsonb_build_object('period', m, 'rows', coalesce((
    select jsonb_agg(jsonb_build_object('team_member_id', t.id, 'name', t.name,
             'status', coalesce(r.status, 'none')) order by t.name)
      from public.team_members t
      left join public.perf_reviews r on r.team_member_id = t.id and r.period = m
     where t.id is distinct from me_row.id
       and ((t.active and public.perf_reviewed(t.id)) or r.id is not null)), '[]'::jsonb));
end $$;
revoke all on function public.perf_overview(date) from public, anon, authenticated;
grant execute on function public.perf_overview(date) to authenticated;

-- END OF THE OVERVIEW -------------------------------------------------------

-- ===========================================================================
-- TEMPLATE FAMILIES — a deliverable's format fills the task from its family.
-- 2026-09-28. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/ops.js compares the
-- two.
--
-- WHAT CHANGED (the user, 2026-09-28: "When creating Reels up to 30s / 60s
-- it should then come out using the Reels template already right. Else I'd
-- be doing double triple works"; then "Each must be unique unless u make it
-- like product variants, the variants is the hours ... checklist its the
-- same for Reels ... same goes to Graphics (Static, GIF, Carousel)"):
--   1. `ops_template_variants`: a format (the rate card's key: reels_30,
--      static, …) belongs to one template, its family, with the hours that
--      variant takes. A format is unique across every family.
--   2. `ops_create_task`: with no template named, the family owning the
--      chosen format fills the task: its checklist, complexity, draft and
--      final offsets and owner, and the variant's hours. The task stays on
--      the workflow the caller asked for (a content deliverable is never
--      moved to the everyday workflow by its family), and a family's "due N
--      days after" is not used: a deliverable's dates come from its month.
--      New task, Bulk add and repeats all create through this function.
--   3. `ops_save_template` takes `variants` ([{format, estimate_minutes}])
--      and replaces the family's set; a format another family holds is
--      refused (`format-taken`, naming the family).
--   4. First run only (while no variant exists), the team's templates become
--      families as agreed: Reel → Reels (30s 3h, 60s 4h, 120s 5h), Static
--      post → Graphics (Static 1h, GIF 2h, Carousel 2h; the export line
--      names the FB and IG sizes), Report (1h). Short video and Carousel,
--      now variants of those families, are set inactive; nothing is deleted.
--
-- ROLLBACK
--   Re-run ops_create_task from EVERY TASK IN A CONFIRMED MONTH and
--   ops_save_template from its section, then
--   drop table if exists public.ops_template_variants;
-- ===========================================================================

create table if not exists public.ops_template_variants (
  id               uuid primary key default gen_random_uuid(),
  template_id      uuid not null references public.ops_task_templates(id) on delete cascade,
  format           text not null unique,
  estimate_minutes integer check (estimate_minutes is null or estimate_minutes between 1 and 6000),
  created_at       timestamptz not null default now()
);
alter table public.ops_template_variants enable row level security;
drop policy if exists ops_template_variants_read on public.ops_template_variants;
create policy ops_template_variants_read on public.ops_template_variants
  for select to authenticated using (public.allowed('ops', 'view'));

create or replace function public.ops_create_task(p_payload jsonb, p_idem text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m     public.team_members;
  tpl   public.ops_task_templates;
  fam   public.ops_template_variants;
  byfmt boolean := false;
  wf    uuid;
  tid   uuid;
  owner uuid;
  publish timestamptz;
  fd    timestamptz;
  fin   timestamptz;
  item  jsonb;
  i     integer := 0;
  scope text;
  ttype text;
  cid   uuid;
  bad   text;
  descr text;
  period text;
  cper  text;
  week  integer;
  seq   integer;
  code  text;
  title text;
  first_stage text;
  wkey  text;
  base  timestamptz;
  eng   public.ops_engagements;
begin
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if not public.allowed('ops', 'work') then return jsonb_build_object('error', 'denied'); end if;

  -- The same press twice is one task.
  if p_idem is not null then
    select id into tid from public.ops_tasks where idem_key = p_idem;
    if tid is not null then return public.ops_task_json(tid); end if;
  end if;

  scope := coalesce(p_payload ->> 'scope', 'client');
  cid := (p_payload ->> 'client_id')::uuid;
  /* A task linked to a month's engagement takes the client from it: the
     person names the month once and the client comes with it. */
  if (p_payload ->> 'engagement_id') is not null then
    select * into eng from public.ops_engagements where id = (p_payload ->> 'engagement_id')::uuid;
    if eng.id is null then return jsonb_build_object('error', 'not-found'); end if;
    if cid is null then cid := eng.client_id; scope := 'client'; end if;
  end if;
  bad := public.ops_scope_error(scope, cid);
  if bad is not null then return jsonb_build_object('error', bad); end if;

  ttype := coalesce(p_payload ->> 'task_type', 'adhoc');
  if ttype not in ('engagement', 'adhoc', 'goodwill', 'special') then
    return jsonb_build_object('error', 'bad-task-type');
  end if;

  /* The description is the team's to edit and may start blank on a task that
     carries a code; a task with no code is named by its description alone, so
     there it is required. `title` is accepted from older callers as the
     description. */
  descr := nullif(btrim(coalesce(p_payload ->> 'content_desc', p_payload ->> 'title', '')), '');

  if (p_payload ->> 'template_id') is not null then
    select * into tpl from public.ops_task_templates
     where id = (p_payload ->> 'template_id')::uuid;
    descr := coalesce(descr, nullif(btrim(coalesce(tpl.default_title, tpl.name, '')), ''));
  end if;
  /* No template named: the family that owns the chosen format fills the task
     (its checklist, complexity, draft and final offsets, owner) and the
     format's own variant its hours (TEMPLATE FAMILIES, 2026-09-28). */
  if tpl.id is null and nullif(p_payload ->> 'deliverable_type', '') is not null then
    select v.* into fam from public.ops_template_variants v
      join public.ops_task_templates t on t.id = v.template_id and t.active
     where v.format = p_payload ->> 'deliverable_type';
    if fam.id is not null then
      select * into tpl from public.ops_task_templates where id = fam.template_id;
      byfmt := true;
    end if;
  end if;
  /* New work goes on the content workflow. A caller may still name another
     (a template's own, or one somebody adds), and a task already on a retired
     workflow is never moved. */
  wf := coalesce((p_payload ->> 'workflow_id')::uuid,
                 (select id from public.ops_workflows where key = p_payload ->> 'workflow_key' and active),
                 case when byfmt then null else tpl.workflow_id end,
                 (select id from public.ops_workflows where key = 'content' and active),
                 (select id from public.ops_workflows where active order by created_at limit 1));
  if wf is null then return jsonb_build_object('error', 'workflow-required'); end if;
  select key into first_stage from public.ops_workflow_stages
   where workflow_id = wf order by position limit 1;
  select key into wkey from public.ops_workflows where id = wf;

  publish := (p_payload ->> 'publish_at')::timestamptz;
  fd := coalesce((p_payload ->> 'first_draft_due_at')::timestamptz,
        case when publish is not null and tpl.first_draft_offset_business_days is not null
             then public.ops_add_business_days(publish, -tpl.first_draft_offset_business_days)
             when tpl.first_draft_offset_business_days is not null
             then public.ops_add_business_days(now(), tpl.first_draft_offset_business_days)
        end);
  /* A template's due date is a number of calendar days from the day the
     work is made for (the base date the caller names, else today). */
  base := coalesce((p_payload ->> 'base_date')::timestamptz, now());
  fin := coalesce((p_payload ->> 'final_due_at')::timestamptz,
        case when tpl.due_offset_days is not null and not byfmt
             then date_trunc('day', base) + make_interval(days => tpl.due_offset_days)
             when publish is not null and tpl.final_offset_business_days is not null
             then public.ops_add_business_days(publish, -tpl.final_offset_business_days)
             when tpl.final_offset_business_days is not null
             then public.ops_add_business_days(now(), tpl.final_offset_business_days)
        end);
  if fd is not null and fin is not null and not public.ops_due_order_ok(fd, fin) then
    return jsonb_build_object('error', 'draft-not-before-final');
  end if;

  /* The name. The month is the content month (the scheduled publish date's,
     else the one the caller names, else this one); the week is the planned
     publishing week, chosen by the caller and prefilled by the page from the
     date; the running number is the client's for the month. Generated once,
     under the lock, and never rewritten: a publish date that moves later
     leaves the name as it was, because the name is a label and not a fact
     about the date. */
  if wkey = 'task' then
    /* An everyday task is named by what it is. It carries no content code,
       because the code numbers a client's deliverables for the month and a
       task is not one; the content month is kept where it is known, so the
       task can be grouped with the month it belongs to. */
    if descr is null then return jsonb_build_object('error', 'title-required'); end if;
    title := descr;
    period := coalesce(nullif(p_payload ->> 'code_period', ''), eng.period);
  elsif scope <> 'internal' then
    period := coalesce(nullif(p_payload ->> 'code_period', ''),
                       case when publish is not null then to_char(publish, 'YYYY-MM') end,
                       to_char(now(), 'YYYY-MM'));
    if period !~ '^\d{4}-\d{2}$' then return jsonb_build_object('error', 'bad-period'); end if;
    /* A client's deliverable belongs to a month the team has planned: one
       that exists, is still open, and has its content meeting set or marked
       not applicable. The same three refusals Bulk add gives. */
    if scope = 'client' then
      cper := period;
      if eng.id is null or eng.period <> cper then
        select * into eng from public.ops_engagements x where x.client_id = cid and x.period = cper;
      end if;
      if eng.id is null then return jsonb_build_object('error', 'no-month'); end if;
      if eng.status in ('completed', 'cancelled') then return jsonb_build_object('error', 'month-closed'); end if;
      if eng.meeting_at is null and not eng.meeting_na then
        return jsonb_build_object('error', 'month-not-confirmed');
      end if;
    end if;
    week := coalesce((p_payload ->> 'code_week')::integer,
                     case when publish is not null
                          then least(5, ((extract(day from publish)::integer - 1) / 7) + 1) end,
                     1);
    if week < 1 or week > 5 then return jsonb_build_object('error', 'bad-week'); end if;
    seq := public.ops_next_seq(cid, period);
    code := public.ops_code_of(period, week, seq);
    title := btrim(code || ' ' || coalesce(descr, ''));
  else
    if descr is null then return jsonb_build_object('error', 'title-required'); end if;
    title := descr;
  end if;

  insert into public.ops_tasks (
    scope, client_id, campaign_id, batch_id, source_type, source_id, template_id,
    workflow_id, stage_key, title, description, remarks, deliverable_type,
    language_codes, priority_level, complexity, estimate_minutes, publish_at,
    original_first_draft_due_at, current_first_draft_due_at,
    original_final_due_at, current_final_due_at, created_by, idem_key,
    legacy_source, legacy_key, data_quality,
    task_type, code, code_period, code_week, code_seq, content_desc,
    engagement_id, manager_id, parent_task_id)
  values (
    scope, cid,
    (p_payload ->> 'campaign_id')::uuid,
    (p_payload ->> 'batch_id')::uuid,
    p_payload ->> 'source_type',
    (p_payload ->> 'source_id')::uuid,
    tpl.id, wf, coalesce(first_stage, 'intake'),
    title, p_payload ->> 'description', p_payload ->> 'remarks',
    coalesce(p_payload ->> 'deliverable_type', tpl.deliverable_type, 'other'),
    coalesce((select array_agg(x) from jsonb_array_elements_text(
               coalesce(p_payload -> 'language_codes', '[]'::jsonb)) x), '{}'),
    coalesce((p_payload ->> 'priority_level')::smallint, 3),
    coalesce(p_payload ->> 'complexity', tpl.default_complexity),
    coalesce((p_payload ->> 'estimate_minutes')::integer, fam.estimate_minutes, tpl.default_estimate_minutes),
    publish, fd, fd, fin, fin, m.id, p_idem,
    p_payload ->> 'legacy_source', p_payload ->> 'legacy_key',
    coalesce(p_payload ->> 'data_quality', 'complete'),
    ttype, code, period, week, seq, descr,
    coalesce(eng.id, (p_payload ->> 'engagement_id')::uuid),
    coalesce((p_payload ->> 'manager_id')::uuid, m.id),
    (p_payload ->> 'parent_task_id')::uuid)
  returning id into tid;

  /* Every task has an owner from the moment it exists: the one named, the
     template's, or else whoever made it. */
  owner := coalesce((p_payload ->> 'owner_id')::uuid, tpl.default_owner_id, m.id);
  if owner is not null then
    insert into public.ops_task_assignees (task_id, team_member_id, responsibility, assigned_by)
    values (tid, owner, 'owner', m.id);
    perform public.ops_log(tid, 'assignment_changed', null,
      jsonb_build_object('owner_id', owner), '{}'::jsonb);
  end if;
  if (p_payload ->> 'reviewer_id') is not null then
    insert into public.ops_task_assignees (task_id, team_member_id, responsibility, assigned_by)
    values (tid, (p_payload ->> 'reviewer_id')::uuid, 'reviewer', m.id);
  end if;

  -- The template's checklist, or the one the caller hands over (a duplicate
  -- carries its source's labels, unticked), in the order stated.
  for item in select * from jsonb_array_elements(
      coalesce(p_payload -> 'checklist', tpl.checklist, '[]'::jsonb)) loop
    i := i + 1;
    insert into public.ops_task_checklist_items (task_id, label, position)
    values (tid, item #>> '{}', i);
  end loop;

  if (p_payload -> 'video') is not null then
    insert into public.ops_video_details (
      task_id, output_duration_seconds, footage_duration_seconds,
      subtitle_required, motion_graphics_required, aspect_ratios,
      script_ready, footage_ready, shoot_required, shoot_at, variant_count)
    values (tid,
      ((p_payload -> 'video') ->> 'output_duration_seconds')::integer,
      ((p_payload -> 'video') ->> 'footage_duration_seconds')::integer,
      coalesce(((p_payload -> 'video') ->> 'subtitle_required')::boolean, false),
      coalesce(((p_payload -> 'video') ->> 'motion_graphics_required')::boolean, false),
      coalesce((select array_agg(x) from jsonb_array_elements_text(
                 coalesce((p_payload -> 'video') -> 'aspect_ratios', '[]'::jsonb)) x), '{}'),
      ((p_payload -> 'video') ->> 'script_ready')::boolean,
      ((p_payload -> 'video') ->> 'footage_ready')::boolean,
      coalesce(((p_payload -> 'video') ->> 'shoot_required')::boolean, false),
      ((p_payload -> 'video') ->> 'shoot_at')::timestamptz,
      coalesce(((p_payload -> 'video') ->> 'variant_count')::integer, 1));
  end if;

  perform public.ops_log(tid, 'task_created', null,
    jsonb_build_object('title', title, 'code', code,
                       'first_draft_due_at', fd, 'final_due_at', fin),
    case when (p_payload ->> 'duplicated_from') is null then '{}'::jsonb
         else jsonb_build_object('duplicated_from', p_payload ->> 'duplicated_from') end);
  return public.ops_task_json(tid);
end $$;
grant execute on function public.ops_create_task(jsonb, text) to authenticated;

create or replace function public.ops_save_template(p_id uuid, p_payload jsonb)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m    public.team_members;
  nm   text;
  wf   uuid;
  tid  uuid;
  other text;
  fmt  text;
begin
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if not public.ops_granted('ops.workflows', 'work') then return jsonb_build_object('error', 'denied'); end if;
  nm := nullif(btrim(coalesce(p_payload ->> 'name', '')), '');
  if nm is null then return jsonb_build_object('error', 'name-required'); end if;
  if exists (select 1 from public.ops_task_templates
              where lower(name) = lower(nm) and id is distinct from p_id) then
    return jsonb_build_object('error', 'name-taken');
  end if;
  /* The formats this family serves, when the page sends them: each format
     belongs to one family, so a format another holds is refused by name. */
  if jsonb_typeof(p_payload -> 'variants') = 'array' then
    for fmt in select v ->> 'format' from jsonb_array_elements(p_payload -> 'variants') v loop
      if fmt is null or fmt !~ '^[a-z0-9_]{1,40}$' then return jsonb_build_object('error', 'bad-format'); end if;
    end loop;
    if (select count(*) from jsonb_array_elements(p_payload -> 'variants'))
       <> (select count(distinct v ->> 'format') from jsonb_array_elements(p_payload -> 'variants') v) then
      return jsonb_build_object('error', 'bad-format');
    end if;
    select t.name into other from public.ops_template_variants x
      join public.ops_task_templates t on t.id = x.template_id
     where x.template_id is distinct from p_id
       and x.format in (select v ->> 'format' from jsonb_array_elements(p_payload -> 'variants') v)
     limit 1;
    if other is not null then return jsonb_build_object('error', 'format-taken', 'family', other); end if;
  end if;
  wf := coalesce((select id from public.ops_workflows where key = coalesce(p_payload ->> 'workflow_key', 'task')),
                 (select id from public.ops_workflows where key = 'task'));
  if wf is null then return jsonb_build_object('error', 'workflow-required'); end if;
  if p_id is null then
    insert into public.ops_task_templates (name, deliverable_type, workflow_id, default_title,
      default_owner_id, due_offset_days, default_estimate_minutes, checklist, active)
    values (nm, coalesce(nullif(p_payload ->> 'deliverable_type', ''), 'other'), wf,
      nullif(btrim(coalesce(p_payload ->> 'default_title', '')), ''),
      (p_payload ->> 'default_owner_id')::uuid,
      (p_payload ->> 'due_offset_days')::integer,
      (p_payload ->> 'default_estimate_minutes')::integer,
      coalesce(p_payload -> 'checklist', '[]'::jsonb),
      coalesce((p_payload ->> 'active')::boolean, true))
    returning id into tid;
  else
    update public.ops_task_templates set
      name = nm,
      deliverable_type = coalesce(nullif(p_payload ->> 'deliverable_type', ''), deliverable_type),
      workflow_id = wf,
      default_title = nullif(btrim(coalesce(p_payload ->> 'default_title', '')), ''),
      default_owner_id = (p_payload ->> 'default_owner_id')::uuid,
      due_offset_days = (p_payload ->> 'due_offset_days')::integer,
      default_estimate_minutes = (p_payload ->> 'default_estimate_minutes')::integer,
      checklist = coalesce(p_payload -> 'checklist', '[]'::jsonb),
      active = coalesce((p_payload ->> 'active')::boolean, active),
      updated_at = now()
    where id = p_id
    returning id into tid;
    if tid is null then return jsonb_build_object('error', 'not-found'); end if;
  end if;
  if jsonb_typeof(p_payload -> 'variants') = 'array' then
    delete from public.ops_template_variants v where v.template_id = tid;
    insert into public.ops_template_variants (template_id, format, estimate_minutes)
    select tid, v ->> 'format', nullif(v ->> 'estimate_minutes', '')::integer
      from jsonb_array_elements(p_payload -> 'variants') v;
  end if;
  return (select to_jsonb(x) || jsonb_build_object('variants', coalesce((
            select jsonb_agg(jsonb_build_object('format', v.format, 'estimate_minutes', v.estimate_minutes) order by v.format)
              from public.ops_template_variants v where v.template_id = x.id), '[]'::jsonb))
            from public.ops_task_templates x where x.id = tid);
end $$;
grant execute on function public.ops_save_template(uuid, jsonb) to authenticated;

-- The team's templates as families, once.
do $$
declare reels uuid; graphics uuid; rep uuid;
begin
  if exists (select 1 from public.ops_template_variants) then return; end if;
  select id into reels from public.ops_task_templates where lower(name) in ('reels', 'reel')
   order by (lower(name) = 'reels') desc limit 1;
  select id into graphics from public.ops_task_templates where lower(name) in ('graphics', 'static post')
   order by (lower(name) = 'graphics') desc limit 1;
  select id into rep from public.ops_task_templates where lower(name) = 'report' limit 1;
  if reels is not null then
    update public.ops_task_templates set name = 'Reels', updated_at = now()
     where id = reels and name = 'Reel'
       and not exists (select 1 from public.ops_task_templates where lower(name) = 'reels');
    insert into public.ops_template_variants (template_id, format, estimate_minutes)
    values (reels, 'reels_30', 180), (reels, 'reels_60', 240), (reels, 'reels_120', 300)
    on conflict (format) do nothing;
    update public.ops_task_templates set active = false, updated_at = now()
     where name = 'Short video' and active;
  end if;
  if graphics is not null then
    update public.ops_task_templates
       set name = 'Graphics',
           checklist = '["Proof-read", "Exported in 1080 * 1080 & 1350 * 1080 (FB+IG sizes)", "Working files saved to [Internal] folder"]'::jsonb,
           updated_at = now()
     where id = graphics and name = 'Static post'
       and not exists (select 1 from public.ops_task_templates where lower(name) = 'graphics');
    insert into public.ops_template_variants (template_id, format, estimate_minutes)
    values (graphics, 'static', 60), (graphics, 'gif', 120), (graphics, 'carousel', 120)
    on conflict (format) do nothing;
    update public.ops_task_templates set active = false, updated_at = now()
     where name = 'Carousel' and active;
  end if;
  if rep is not null then
    insert into public.ops_template_variants (template_id, format, estimate_minutes)
    values (rep, 'report', 60) on conflict (format) do nothing;
  end if;
end $$;

-- END OF TEMPLATE FAMILIES --------------------------------------------------

-- ===========================================================================
-- PIECES AND REPEATS — one sheet makes a month's pieces and their repeat, and
-- repeats are made without anybody pressing Run.
-- 2026-09-28. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/ops.js compares the
-- two.
--
-- WHAT CHANGED (the user, 2026-09-28: "why bulk add still necessary? Why not
-- just at the create / new task or content deliverable Optional repeat", then
-- "1 and 2 proceed"):
--   1. `ops_create_pieces(p_payload, p_idem)`: the New sheet's one act. Its
--      pieces (each a description, a format and a week; a sheet's only piece
--      may carry its own dates) are made through `ops_create_task` in one
--      transaction, all or none. Where there is more than one piece, or a
--      repeat, a piece with no publish date takes a tentative one inside its
--      week, as Bulk add did. An optional `repeat` sets the same rule on every
--      piece (`ops_set_recurring`) and makes at once what already falls due.
--      The same press twice is the same act.
--   2. `ops_generate_recurring` makes nothing on or before the day of the task
--      a rule copies: that task is the first occurrence. Before this, a rule
--      run for its own month copied its task onto its task's own day.
--   3. `ops_set_recurring` keeps a task's week only on a monthly rule; a weekly
--      or every-N-days copy takes the week of its own date.
--   4. Repeats run themselves. When a client's month is confirmed (its meeting
--      set or marked not applicable), that client's repeats for the month are
--      made at once, as the person confirming (`ops_engagements_confirmed`).
--      Every morning at 00:10 Malaysia time `ops_recurring_daily()` makes what
--      falls due this month, and next month in the last seven days
--      (`ops_recurring_periods()`), each rule as the colleague who set it (else
--      its task's owner) with that colleague's own access. Run repeating tasks
--      and Bulk add leave the page; `ops_generate_month` stays for the record.
--   5. A copy somebody deletes stays deleted. Every date a repeat has made is
--      kept (`ops_recurring_made`, by rule and by the task it copies), and no
--      date is made twice, even after the repeat is turned off and on again.
--      The copies already made are recorded here from their keys.
--   6. A task deleted stops its repeat (`ops_tasks_stop_repeat`), since a rule
--      is seen and turned off only from its task. A rule whose task was
--      already gone stops here. Found on the live database before this ran:
--      one such rule, whose deleted September copy the morning run would have
--      made again.
--
-- ROLLBACK
--   select cron.unschedule('ops-repeats-daily');
--   drop trigger if exists ops_tasks_stop_repeat on public.ops_tasks;
--   drop function if exists public.ops_tasks_stop_repeat();
--   drop table if exists public.ops_recurring_made;
--   (a rule stopped because its task was gone stays stopped; set it active by
--   hand to bring it back)
--   drop trigger if exists ops_engagements_confirmed on public.ops_engagements;
--   drop function if exists public.ops_engagements_confirmed();
--   drop function if exists public.ops_recurring_daily();
--   drop function if exists public.ops_create_pieces(jsonb, text);
--   drop function if exists public.ops_recurring_periods();
--   Re-run ops_set_recurring from THE OPERATIONS SYSTEM, PHASE 4 and
--   ops_generate_recurring from EVERY TASK IN A CONFIRMED MONTH.
-- ===========================================================================

create or replace function public.ops_set_recurring(p_task uuid, p_payload jsonb)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m public.team_members;
  t public.ops_tasks;
  r public.ops_recurring_rules;
  freq text;
begin
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if not public.ops_may_see_task(p_task) then return jsonb_build_object('error', 'denied'); end if;
  if not public.allowed('ops', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into t from public.ops_tasks where id = p_task;
  if t.id is null then return jsonb_build_object('error', 'not-found'); end if;

  select * into r from public.ops_recurring_rules where source_task_id = p_task and active;
  if coalesce((p_payload ->> 'active')::boolean, true) = false then
    if r.id is not null then
      update public.ops_recurring_rules set active = false, updated_at = now() where id = r.id;
      perform public.ops_log(p_task, 'recurrence_off', null, null, '{}'::jsonb);
    end if;
    return jsonb_build_object('ok', true, 'active', false);
  end if;

  freq := coalesce(p_payload ->> 'frequency', 'monthly');
  if freq not in ('weekly', 'monthly', 'custom') then return jsonb_build_object('error', 'bad-frequency'); end if;
  if freq = 'custom' and coalesce((p_payload ->> 'interval_days')::integer, 0) < 1 then
    return jsonb_build_object('error', 'interval-required');
  end if;

  if r.id is null then
    insert into public.ops_recurring_rules
      (name, client_id, template_id, owner_id, frequency, day_of_month, source_task_id,
       interval_days, ends_on, max_count, code_week, created_by)
    values (public.ops_title(t), t.client_id, t.template_id,
            (select team_member_id from public.ops_task_assignees
              where task_id = p_task and responsibility = 'owner' and ended_at is null),
            freq, (p_payload ->> 'day_of_month')::integer, p_task,
            (p_payload ->> 'interval_days')::integer, (p_payload ->> 'ends_on')::date,
            (p_payload ->> 'max_count')::integer,
            coalesce((p_payload ->> 'code_week')::integer, case when freq = 'monthly' then t.code_week end),
            m.id)
    returning * into r;
    perform public.ops_log(p_task, 'recurrence_set', null, to_jsonb(r) - 'id', '{}'::jsonb);
  else
    update public.ops_recurring_rules set
      frequency = freq, day_of_month = (p_payload ->> 'day_of_month')::integer,
      interval_days = (p_payload ->> 'interval_days')::integer,
      ends_on = (p_payload ->> 'ends_on')::date, max_count = (p_payload ->> 'max_count')::integer,
      code_week = coalesce((p_payload ->> 'code_week')::integer, case when freq = 'monthly' then r.code_week end),
      updated_at = now()
    where id = r.id returning * into r;
    perform public.ops_log(p_task, 'recurrence_set', null, to_jsonb(r) - 'id', '{}'::jsonb);
  end if;
  return to_jsonb(r);
end $$;
grant execute on function public.ops_set_recurring(uuid, jsonb) to authenticated;

/* Every date a repeat has made, by its rule and by the task it copies, so a
   copy deleted is not made again the next morning and a repeat turned off
   and on again makes no date twice. Written and read only by the generator;
   no page reads it. */
create table if not exists public.ops_recurring_made (
  rule_id        uuid not null references public.ops_recurring_rules(id) on delete cascade,
  source_task_id uuid,
  on_date        date not null,
  made_at        timestamptz not null default now(),
  primary key (rule_id, on_date)
);
create index if not exists ops_recurring_made_source
  on public.ops_recurring_made (source_task_id, on_date) where source_task_id is not null;
alter table public.ops_recurring_made enable row level security;
revoke all on public.ops_recurring_made from anon, authenticated;

/* The copies made before the record began, read from their keys. */
insert into public.ops_recurring_made (rule_id, source_task_id, on_date)
select r.id, r.source_task_id, split_part(t.idem_key, ':', 3)::date
  from public.ops_tasks t
  join public.ops_recurring_rules r on r.id::text = split_part(t.idem_key, ':', 2)
 where t.idem_key ~ '^recur:[0-9a-f-]{36}:\d{4}-\d{2}-\d{2}$'
on conflict do nothing;

/* A task deleted takes its repeat with it: a rule is seen and turned off
   only from its task, so one left behind would make copies nobody could
   stop. */
create or replace function public.ops_tasks_stop_repeat()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  update public.ops_recurring_rules set active = false, updated_at = now()
   where source_task_id = old.id and active;
  return old;
end $$;
revoke all on function public.ops_tasks_stop_repeat() from public, anon, authenticated;
drop trigger if exists ops_tasks_stop_repeat on public.ops_tasks;
create trigger ops_tasks_stop_repeat before delete on public.ops_tasks
  for each row execute function public.ops_tasks_stop_repeat();

/* A rule whose task was deleted before the trigger stops now. */
update public.ops_recurring_rules set active = false, updated_at = now()
 where active and source_task_id is null;

create or replace function public.ops_generate_recurring(
  p_period text, p_rules uuid[] default null, p_idem text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m     public.team_members;
  r     public.ops_recurring_rules;
  src   public.ops_tasks;
  made  integer := 0;
  skip  integer := 0;
  key   text;
  first_day date;
  last_day date;
  anchor date;
  d     date;
  stepd integer;
  one   jsonb;
  wk    integer;
  held  integer := 0;
  ccl   uuid;
  mon   public.ops_engagements;
begin
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if not public.allowed('ops', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if p_period !~ '^\d{4}-\d{2}$' then return jsonb_build_object('error', 'bad-period'); end if;
  first_day := (p_period || '-01')::date;
  last_day := (first_day + interval '1 month' - interval '1 day')::date;

  for r in select * from public.ops_recurring_rules
            where active and (p_rules is null or id = any (p_rules))
              and (source_task_id is null or public.ops_may_see_task(source_task_id)) loop
    if r.source_task_id is not null then
      select * into src from public.ops_tasks where id = r.source_task_id;
    else
      src := null;
    end if;

    /* A client's repeats wait for the client's month: one that exists, is
       open and has its content meeting set or marked not applicable. Until
       then the rule is held and counted, and a later run makes them. */
    ccl := case when src.id is not null then case when src.scope = 'client' then src.client_id end
                else r.client_id end;
    mon := null;
    if ccl is not null then
      select * into mon from public.ops_engagements x where x.client_id = ccl and x.period = p_period;
      if mon.id is null or mon.status in ('completed', 'cancelled')
         or (mon.meeting_at is null and not mon.meeting_na) then
        held := held + 1;
        continue;
      end if;
    end if;

    /* The dates this rule falls on inside the month. */
    if r.frequency = 'monthly' then
      d := first_day + (least(coalesce(r.day_of_month,
              case when src.publish_at is not null then extract(day from src.publish_at)::integer else 1 end),
              extract(day from last_day)::integer) - 1);
      stepd := null;
    else
      stepd := case when r.frequency = 'weekly' then 7 else greatest(1, coalesce(r.interval_days, 7)) end;
      anchor := coalesce(src.publish_at::date, r.created_at::date, first_day);
      if anchor > first_day then d := anchor;
      else d := anchor + ((((first_day - anchor) + stepd - 1) / stepd) * stepd); end if;
    end if;

    while d is not null and d <= last_day loop
      if d >= first_day
         /* The task a rule copies is its first occurrence: nothing on or
            before its day is made again. */
         and (src.id is null or d > coalesce(src.publish_at, r.created_at)::date)
         and (r.ends_on is null or d <= r.ends_on)
         and (r.max_count is null or r.generated_count < r.max_count) then
        key := 'recur:' || r.id::text || ':' || to_char(d, 'YYYY-MM-DD');
        /* Made once is made: a copy since deleted stays deleted, and a rule
           set again on the same task makes none of its dates twice. */
        if exists (select 1 from public.ops_tasks where idem_key = key)
           or exists (select 1 from public.ops_recurring_made x
                       where x.on_date = d
                         and (x.rule_id = r.id
                              or (r.source_task_id is not null and x.source_task_id = r.source_task_id))) then
          skip := skip + 1;
        else
          wk := coalesce(r.code_week, least(5, ((extract(day from d)::integer - 1) / 7) + 1));
          if src.id is not null then
            one := public.ops_duplicate_task(src.id, jsonb_build_object(
              'keep_desc', true, 'copy_dates', false, 'copy_assignees', true,
              'publish_at', d::timestamptz, 'code_period', p_period, 'code_week', wk,
              'engagement_id', mon.id), key);
          else
            one := public.ops_create_task(jsonb_build_object(
              'scope', case when r.client_id is null then 'internal' else 'client' end,
              'client_id', r.client_id, 'template_id', r.template_id,
              'title', r.name || ' — ' || p_period, 'content_desc', r.name,
              'owner_id', r.owner_id, 'publish_at', d::timestamptz,
              'code_period', p_period, 'code_week', wk, 'engagement_id', mon.id), key);
          end if;
          if one ? 'error' then return one || jsonb_build_object('rule', r.id); end if;
          made := made + 1;
          insert into public.ops_recurring_made (rule_id, source_task_id, on_date)
          values (r.id, r.source_task_id, d) on conflict do nothing;
          update public.ops_recurring_rules
             set generated_count = generated_count + 1, last_generated_period = p_period, updated_at = now()
           where id = r.id;
          r.generated_count := r.generated_count + 1;
        end if;
      end if;
      exit when stepd is null;
      d := d + stepd;
    end loop;
  end loop;
  return jsonb_build_object('created', made, 'skipped', skip, 'held', held, 'period', p_period);
end $$;
grant execute on function public.ops_generate_recurring(text, uuid[], text) to authenticated;

/* The months a repeat is made for today: this one in Malaysia, and the next
   one once this one is in its last seven days. */
create or replace function public.ops_recurring_periods()
returns text[]
language sql stable set search_path = public as $$
  select case
    when (now() at time zone 'Asia/Kuala_Lumpur')::date
         > (date_trunc('month', now() at time zone 'Asia/Kuala_Lumpur') + interval '1 month' - interval '8 days')::date
    then array[to_char(now() at time zone 'Asia/Kuala_Lumpur', 'YYYY-MM'),
               to_char(date_trunc('month', now() at time zone 'Asia/Kuala_Lumpur') + interval '1 month', 'YYYY-MM')]
    else array[to_char(now() at time zone 'Asia/Kuala_Lumpur', 'YYYY-MM')]
  end
$$;
revoke all on function public.ops_recurring_periods() from public, anon, authenticated;

/* The New sheet's one act: the pieces, each through ops_create_task, and the
   repeat on every one of them, all or none. */
create or replace function public.ops_create_pieces(p_payload jsonb, p_idem text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m      public.team_members;
  n      integer;
  pc     jsonb;
  i      integer := 0;
  w      integer;
  k      integer;
  inweek integer;
  per    text;
  first_day date;
  last_off integer;
  spread boolean;
  base   jsonb;
  one    jsonb;
  made   jsonb := '[]'::jsonb;
  rep    jsonb;
  rule   jsonb;
  ids    uuid[] := '{}';
  gen    jsonb := '[]'::jsonb;
  pp     text;
  said   text;
begin
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if not public.allowed('ops', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if jsonb_typeof(p_payload -> 'pieces') is distinct from 'array' then
    return jsonb_build_object('error', 'bad-count');
  end if;
  n := jsonb_array_length(p_payload -> 'pieces');
  if n < 1 or n > 60 then return jsonb_build_object('error', 'bad-count'); end if;
  rep := case when jsonb_typeof(p_payload -> 'repeat') = 'object' then p_payload -> 'repeat' end;
  if rep is not null then
    if coalesce(rep ->> 'frequency', '') not in ('weekly', 'monthly', 'custom') then
      return jsonb_build_object('error', 'bad-frequency');
    end if;
    if rep ->> 'frequency' = 'custom' and coalesce((rep ->> 'interval_days')::integer, 0) < 1 then
      return jsonb_build_object('error', 'interval-required');
    end if;
  end if;

  /* What every piece shares: whose it is, what kind, who does it. A piece
     names its own description, format and week; only a sheet's one piece
     carries its own dates and brief. */
  base := jsonb_strip_nulls(jsonb_build_object(
    'scope', p_payload ->> 'scope', 'client_id', p_payload ->> 'client_id',
    'engagement_id', p_payload ->> 'engagement_id',
    'code_period', p_payload ->> 'code_period',
    'task_type', p_payload ->> 'task_type',
    'owner_id', p_payload ->> 'owner_id',
    'priority_level', p_payload -> 'priority_level',
    'complexity', p_payload ->> 'complexity',
    'description', case when n = 1 then p_payload ->> 'description' end));
  per := p_payload ->> 'code_period';
  if per ~ '^\d{4}-\d{2}$' and coalesce(p_payload ->> 'scope', 'client') <> 'internal' then
    first_day := (per || '-01')::date;
    last_off := ((first_day + interval '1 month')::date - first_day) - 1;
  end if;
  spread := first_day is not null and (n > 1 or rep is not null);

  begin
    for pc in select x from jsonb_array_elements(p_payload -> 'pieces') x loop
      i := i + 1;
      w := least(5, greatest(1, coalesce((pc ->> 'code_week')::integer, 1)));
      one := base || jsonb_strip_nulls(jsonb_build_object(
        'content_desc', nullif(btrim(coalesce(pc ->> 'content_desc', '')), ''),
        'deliverable_type', nullif(pc ->> 'deliverable_type', ''),
        'code_week', case when first_day is not null then w end));
      if n = 1 then
        one := one || jsonb_strip_nulls(jsonb_build_object(
          'publish_at', nullif(pc ->> 'publish_at', ''),
          'first_draft_due_at', nullif(pc ->> 'first_draft_due_at', ''),
          'final_due_at', nullif(pc ->> 'final_due_at', '')));
      end if;
      /* A tentative day inside the piece's week, the week's pieces spread
         across its seven days, so the calendar has somewhere to put each one
         and a repeat a day to count from; the content meeting fixes the real
         date. Never past the month's last day, which only week 5 reaches. */
      if spread and not (one ? 'publish_at') then
        select count(*) filter (where least(5, greatest(1, coalesce((y ->> 'code_week')::integer, 1))) = w),
               count(*) filter (where least(5, greatest(1, coalesce((y ->> 'code_week')::integer, 1))) = w and o < i)
          into inweek, k
          from jsonb_array_elements(p_payload -> 'pieces') with ordinality as a(y, o);
        one := one || jsonb_build_object('publish_at',
          (first_day + least((w - 1) * 7 + (k * 7) / greatest(inweek, 1), last_off))::timestamptz);
      end if;
      one := public.ops_create_task(one, case when p_idem is null then null else p_idem || ':' || i end);
      if one ? 'error' then raise exception using message = one::text; end if;
      made := made || jsonb_build_object('id', one ->> 'id', 'code', one ->> 'code', 'title', one ->> 'title');
      ids := ids || (one ->> 'id')::uuid;
      if rep is not null then
        rule := public.ops_set_recurring((one ->> 'id')::uuid, jsonb_strip_nulls(jsonb_build_object(
          'frequency', rep ->> 'frequency',
          'interval_days', case when rep ->> 'frequency' = 'custom' then rep -> 'interval_days' end,
          'ends_on', nullif(rep ->> 'ends_on', ''),
          'max_count', rep -> 'max_count')));
        if rule ? 'error' then raise exception using message = rule::text; end if;
      end if;
    end loop;
  exception when raise_exception then
    /* A refusal part way leaves nothing behind: the block's writes are
       undone and the refusal is answered as it was given. */
    said := sqlerrm;
    begin
      return said::jsonb;
    exception when others then
      return jsonb_build_object('error', said);
    end;
  end;

  /* What the new rules already owe is made now rather than tomorrow morning. */
  if rep is not null then
    foreach pp in array public.ops_recurring_periods() loop
      gen := gen || public.ops_generate_recurring(pp,
        array(select r.id from public.ops_recurring_rules r where r.active and r.source_task_id = any (ids)));
    end loop;
  end if;
  return jsonb_build_object('count', n, 'tasks', made, 'repeats', gen);
end $$;
grant execute on function public.ops_create_pieces(jsonb, text) to authenticated;

/* A client's month confirmed makes that client's repeats for it at once, as
   the person confirming and with their access. A refusal or a fault here
   never fails the confirmation; the morning run makes what it missed. */
create or replace function public.ops_engagements_confirmed()
returns trigger language plpgsql security definer set search_path = public as $$
declare rules uuid[];
begin
  if new.status in ('completed', 'cancelled') then return null; end if;
  if old.meeting_at is not null or coalesce(old.meeting_na, false) then return null; end if;
  if new.meeting_at is null and not coalesce(new.meeting_na, false) then return null; end if;
  select array_agg(r.id) into rules
    from public.ops_recurring_rules r
    left join public.ops_tasks s on s.id = r.source_task_id
   where r.active
     and case when s.id is not null then case when s.scope = 'client' then s.client_id end
              else r.client_id end = new.client_id;
  if rules is null then return null; end if;
  begin
    perform public.ops_generate_recurring(new.period, rules);
  exception when others then
    null;
  end;
  return null;
end $$;
revoke all on function public.ops_engagements_confirmed() from public, anon, authenticated;
drop trigger if exists ops_engagements_confirmed on public.ops_engagements;
create trigger ops_engagements_confirmed after update of meeting_at, meeting_na on public.ops_engagements
  for each row execute function public.ops_engagements_confirmed();

/* The morning run. Each rule is made as the colleague who set it, else its
   task's owner, with that colleague's own access; a rule neither of them can
   make waits. Nobody calls this but the schedule below. */
create or replace function public.ops_recurring_daily()
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  a   record;
  pp  text;
  out jsonb := '[]'::jsonb;
  was text := current_setting('request.jwt.claims', true);
begin
  for a in
    select actor.email, array_agg(r.id order by r.id) as rules
      from public.ops_recurring_rules r
      left join public.ops_tasks s on s.id = r.source_task_id
      cross join lateral (
        select tm.email from public.team_members tm
         where tm.active and tm.email is not null
           and tm.id in (r.created_by,
                         (select x.team_member_id from public.ops_task_assignees x
                           where x.task_id = s.id and x.responsibility = 'owner' and x.ended_at is null
                           limit 1))
         order by (tm.id = r.created_by) desc nulls last
         limit 1) actor
     where r.active
     group by actor.email
  loop
    perform set_config('request.jwt.claims',
      jsonb_build_object('email', a.email, 'role', 'authenticated')::text, true);
    foreach pp in array public.ops_recurring_periods() loop
      out := out || jsonb_build_object('period', pp, 'rules', to_jsonb(a.rules),
                                       'result', public.ops_generate_recurring(pp, a.rules));
    end loop;
  end loop;
  perform set_config('request.jwt.claims', coalesce(was, ''), true);
  return out;
end $$;
revoke all on function public.ops_recurring_daily() from public, anon, authenticated;

/* Every morning at 00:10 in Malaysia (16:10 UTC). */
do $$
begin
  if not exists (select 1 from pg_extension where extname = 'pg_cron') then
    raise notice 'ops-repeats-daily: pg_cron is not installed, so no schedule was written.';
    return;
  end if;
  perform cron.unschedule(j.jobid) from cron.job j where j.jobname = 'ops-repeats-daily';
  perform cron.schedule('ops-repeats-daily', '10 16 * * *', 'select public.ops_recurring_daily()');
end $$;

-- END OF PIECES AND REPEATS ---------------------------------------------------

-- ===========================================================================
-- POST REVISIONS — a post the client has decided on is revised in place, as
-- its next round, and the rounds before it are kept for the team.
-- 2026-09-30. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/sql.js compares the
-- two.
--
-- WHAT CHANGED
--   1. `posts.round`: which round of the post is the one on show. A change
--      to its file, caption, Chinese caption or title after the client has
--      decided on the round moves it to the next one (trigger
--      `posts_revision`), and the round it replaces is kept whole in
--      `post_versions`. Before any decision an edit is a correction and
--      makes no round.
--   2. `reviews.round`: the round a decision was about, stamped by trigger
--      (`reviews_round`), never by a page. A decision on an earlier round
--      no longer answers for the post.
--   3. `reviews.suggested_caption` / `suggested_caption_zh`: a client may
--      edit the copy inside Request changes. The edit is kept as a
--      suggestion on the request; the post's copy changes only when the
--      team accepts it (which, being a change after a decision, is the
--      next round).
--   4. `get_review_feed` sends each post's round, the decision on that
--      round only, and, for a revised post, what the client asked of the
--      round before (`asked`). Never an earlier round's file or copy: the
--      client sees the revised version alone.
--   5. `submit_review` takes the suggested copy (`p_caption`,
--      `p_caption_zh`). A request needs a note or an edit to the copy.
--   6. `post_versions` is read at Content Review (sets) View and written
--      only by the trigger.
--
-- ROLLBACK
--   drop trigger if exists posts_revision on public.posts;
--   drop function if exists public.posts_revision();
--   drop trigger if exists reviews_round on public.reviews;
--   drop function if exists public.reviews_round();
--   drop table if exists public.post_versions;
--   alter table public.reviews drop column if exists suggested_caption_zh;
--   alter table public.reviews drop column if exists suggested_caption;
--   alter table public.reviews drop column if exists round;
--   alter table public.posts drop column if exists round;
--   drop function if exists public.submit_review(text, uuid, text, text, text, text, text, text);
--   Re-run get_review_feed and submit_review from the Client-facing API
--   section of supabase/schema.sql as it stood before 2026-09-30.
-- ===========================================================================

alter table public.posts add column if not exists round int not null default 1;

alter table public.reviews add column if not exists round int;
alter table public.reviews add column if not exists suggested_caption text;
alter table public.reviews add column if not exists suggested_caption_zh text;
update public.reviews set round = 1 where round is null;
alter table public.reviews alter column round set default 1;
alter table public.reviews alter column round set not null;
create index if not exists reviews_post_round_idx on public.reviews(post_id, round, created_at desc);

create table if not exists public.post_versions (
  id           uuid primary key default gen_random_uuid(),
  post_id      uuid not null references public.posts(id) on delete cascade,
  round        int not null,
  platform     text,
  format       text,
  title        text,
  caption      text,
  caption_zh   text,
  media        jsonb not null default '[]'::jsonb,
  replaced_at  timestamptz not null default now(),
  replaced_by  text,
  unique (post_id, round)
);
alter table public.post_versions enable row level security;
drop policy if exists post_versions_read on public.post_versions;
create policy post_versions_read on public.post_versions for select to authenticated
  using (public.allowed('review.sets', 'view'));

/* The round a decision is about is the post's round when it was made. */
create or replace function public.reviews_round() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  select p.round into new.round from public.posts p where p.id = new.post_id;
  new.round := coalesce(new.round, 1);
  return new;
end $$;
revoke all on function public.reviews_round() from public, anon, authenticated;
drop trigger if exists reviews_round on public.reviews;
create trigger reviews_round before insert on public.reviews
  for each row execute function public.reviews_round();

/* A change to what the client decided on is the next round; the round it
   replaces is kept whole. A decision taken back by Request re-approval
   (`review_reset_at`) no longer counts, so an edit after it is a
   correction of the round the client is being asked about again. */
create or replace function public.posts_revision() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if (new.media, new.caption, new.caption_zh, new.title)
     is not distinct from (old.media, old.caption, old.caption_zh, old.title) then
    return new;
  end if;
  if not exists (select 1 from public.reviews r
                  where r.post_id = old.id and r.round = old.round
                    and (old.review_reset_at is null or r.created_at > old.review_reset_at)) then
    return new;
  end if;
  insert into public.post_versions (post_id, round, platform, format, title, caption, caption_zh, media, replaced_by)
  values (old.id, old.round, old.platform, old.format, old.title, old.caption, old.caption_zh, old.media,
          nullif(auth.jwt() ->> 'email', ''))
  on conflict (post_id, round) do nothing;
  new.round := old.round + 1;
  return new;
end $$;
revoke all on function public.posts_revision() from public, anon, authenticated;
drop trigger if exists posts_revision on public.posts;
create trigger posts_revision before update on public.posts
  for each row execute function public.posts_revision();

create or replace function public.get_review_feed(p_token text, p_passcode text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_client public.clients%rowtype;
begin
  select * into v_client
  from public.clients
  where access_token = p_token and active;

  if not found then
    return jsonb_build_object('error', 'not_found');
  end if;

  if v_client.passcode is not null
     and (p_passcode is null or p_passcode <> v_client.passcode) then
    return jsonb_build_object('error', 'passcode_required', 'client', v_client.name);
  end if;

  return jsonb_build_object(
    'client', jsonb_build_object(
      'name', v_client.name,
      'logo_url', v_client.logo_url,
      'handles', jsonb_build_object(
        'instagram', v_client.handle_ig,
        'facebook',  v_client.handle_fb,
        'tiktok',    v_client.handle_tiktok,
        'xhs',       v_client.handle_xhs)),
    'batches', coalesce((
      select jsonb_agg(batch order by batch->>'created_at' desc)
      from (
        select jsonb_build_object(
          'id',         b.id,
          'title',      b.title,
          'note',       b.note,
          'created_at', b.created_at,
          'posts', coalesce((
            select jsonb_agg(post order by (post->>'position')::int)
            from (
              select jsonb_build_object(
                'id',         p.id,
                'platform',   p.platform,
                'format',     p.format,
                'handle',     p.handle,
                'caption',    p.caption,
                'caption_zh', p.caption_zh,
                'title',      p.title,
                'media',      p.media,
                'position',   p.position,
                'round',      p.round,
                'reset_note', case
                  when p.review_reset_at is not null then p.review_reset_note end,
                /* The decision on the round on show, never one about a round
                   the client no longer sees. */
                'review',     (
                  select jsonb_build_object(
                    'decision',   r.decision,
                    'note',       r.note,
                    'reviewer',   r.reviewer,
                    'created_at', r.created_at,
                    'suggested',  (r.suggested_caption is not null or r.suggested_caption_zh is not null))
                  from public.reviews r
                  where r.post_id = p.id and r.round = p.round
                    and (p.review_reset_at is null or r.created_at > p.review_reset_at)
                  order by r.created_at desc
                  limit 1),
                /* What the client asked of the round before, so a revision
                   says what it answers. Words only: the earlier file and copy
                   stay with the team. */
                'asked',      case when p.round > 1 then (
                  select jsonb_build_object(
                    'note',       r.note,
                    'reviewer',   r.reviewer,
                    'created_at', r.created_at,
                    'suggested',  (r.suggested_caption is not null or r.suggested_caption_zh is not null))
                  from public.reviews r
                  where r.post_id = p.id and r.round = p.round - 1 and r.decision = 'changes'
                  order by r.created_at desc
                  limit 1) end
              ) as post
              from public.posts p
              where p.batch_id = b.id
            ) posts
          ), '[]'::jsonb)
        ) as batch
        from public.batches b
        where b.client_id = v_client.id and b.published
      ) batches
    ), '[]'::jsonb)
  );
end $$;

/* The signature grows, so the old one goes first: PostgREST cannot choose
   between two functions a call fits. */
drop function if exists public.submit_review(text, uuid, text, text, text, text);
create or replace function public.submit_review(
  p_token      text,
  p_post_id    uuid,
  p_decision   text,
  p_note       text default null,
  p_reviewer   text default null,
  p_passcode   text default null,
  p_caption    text default null,
  p_caption_zh text default null
) returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_client_id uuid;
  v_post      public.posts%rowtype;
  v_cap       text;
  v_cap_zh    text;
begin
  if p_decision not in ('approved', 'changes') then
    return jsonb_build_object('error', 'bad_decision');
  end if;

  select c.id into v_client_id
  from public.clients c
  where c.access_token = p_token
    and c.active
    and (c.passcode is null or c.passcode = p_passcode);

  if v_client_id is null then
    return jsonb_build_object('error', 'not_found');
  end if;

  -- the post must belong to a published batch of this client
  select p.* into v_post
  from public.posts p
  join public.batches b on b.id = p.batch_id
  where p.id = p_post_id and b.client_id = v_client_id and b.published;

  if v_post.id is null then
    return jsonb_build_object('error', 'not_found');
  end if;

  /* A suggested copy is kept only where it differs from the copy on show,
     and only on a request for changes. */
  if p_decision = 'changes' then
    v_cap    := case when p_caption is not null
                      and p_caption is distinct from coalesce(v_post.caption, '') then p_caption end;
    v_cap_zh := case when p_caption_zh is not null
                      and p_caption_zh is distinct from coalesce(v_post.caption_zh, '') then p_caption_zh end;
  end if;

  if p_decision = 'changes' and coalesce(btrim(p_note), '') = ''
     and v_cap is null and v_cap_zh is null then
    return jsonb_build_object('error', 'note_required');
  end if;

  insert into public.reviews (post_id, decision, note, reviewer, suggested_caption, suggested_caption_zh)
  values (p_post_id, p_decision, nullif(btrim(p_note), ''), nullif(btrim(p_reviewer), ''), v_cap, v_cap_zh);

  /* The activity record is the portal's account of what was decided and by
     whom, and it held only what the team did. A client approving a post is
     the decision the whole section exists to collect, and it left nothing
     anybody could produce later: the verdict sat in `reviews` alone, which
     no screen reads as a history. The reviewer's own typed name is the
     actor, because a person decided it. */
  insert into public.activity_log (actor, action, subject, detail)
  select coalesce(nullif(btrim(coalesce(p_reviewer, '')), ''), 'Client'),
         case when p_decision = 'approved' then 'review.approved' else 'review.changes' end,
         c.name,
         b.title || ' · ' || coalesce(nullif(p.platform, ''), 'post') ||
         case when p.round > 1 then ' · revision ' || p.round else '' end ||
         coalesce(' · ' || nullif(btrim(coalesce(p_note, '')), ''), '') ||
         case when v_cap is not null or v_cap_zh is not null then ' · caption edited' else '' end
    from public.posts p
    join public.batches b on b.id = p.batch_id
    join public.clients c on c.id = b.client_id
   where p.id = p_post_id;

  return jsonb_build_object('ok', true);
end $$;

revoke all on function public.get_review_feed(text, text) from public;
revoke all on function public.submit_review(text, uuid, text, text, text, text, text, text) from public;
grant execute on function public.get_review_feed(text, text) to anon, authenticated;
grant execute on function public.submit_review(text, uuid, text, text, text, text, text, text) to anon, authenticated;

-- END OF POST REVISIONS -----------------------------------------------------

-- ===========================================================================
-- REVIEW CONFIRMED INTERNALLY — the team approves a post for the client, under
-- the colleague's own name, and can take it back.
-- 2026-10-01. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/sql.js compares the
-- two.
--
-- WHAT CHANGED
--   1. `reviews.source`: who decided, 'client' (the review link) or 'team'
--      (Confirm internally in the console). Every row before this is the
--      client's.
--   2. `reviews.undone_at` / `undone_by`: a team approval taken back
--      (Revert confirmation) is kept, marked undone, and no longer answers
--      for the post. A client's decision is never undone here; the team asks
--      again with Request re-approval.
--   3. `review_confirm(p_post)`: Content Review (sets) at Work approves the
--      round on show as the signed-in colleague. Refused where the round is
--      already approved or the set is not published.
--   4. `review_revert_confirm(p_post)`: takes back the team's approval of the
--      round on show, and only that. The post falls back to the decision
--      before it (Pending, or the client's request).
--   5. `get_review_feed` sends `by_team` on the decision, so the client's page
--      reads Confirmed internally by {name}; an undone decision is never sent.
--      It also sends the client's own suggested caption on the decision
--      standing, so Edit request reopens the request as they sent it.
--   6. `posts_revision` counts only a decision that stands.
--   7. `review.unconfirmed` is the tag Revert confirmation files, under
--      Content Review (`activity_section`, restated whole below; the console's
--      ACTION_LABEL names it). The feed never sends a colleague's name: a
--      team decision goes out with no reviewer.
--
-- ROLLBACK
--   drop function if exists public.review_revert_confirm(uuid);
--   drop function if exists public.review_confirm(uuid);
--   alter table public.reviews drop constraint if exists reviews_source_check;
--   alter table public.reviews drop column if exists undone_by;
--   alter table public.reviews drop column if exists undone_at;
--   alter table public.reviews drop column if exists source;
--   Re-run get_review_feed and posts_revision from POST REVISIONS, and
--   activity_section from TASKS LINK RECORDS.
-- ===========================================================================

alter table public.reviews add column if not exists source text not null default 'client';
alter table public.reviews add column if not exists undone_at timestamptz;
alter table public.reviews add column if not exists undone_by uuid references public.team_members(id) on delete set null;
alter table public.reviews drop constraint if exists reviews_source_check;
alter table public.reviews add constraint reviews_source_check check (source in ('client', 'team'));

/* A change to what the client decided on is the next round; a decision
   taken back (undone, or asked again with Request re-approval) no longer
   counts, so an edit after it is a correction. */
create or replace function public.posts_revision() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if (new.media, new.caption, new.caption_zh, new.title)
     is not distinct from (old.media, old.caption, old.caption_zh, old.title) then
    return new;
  end if;
  if not exists (select 1 from public.reviews r
                  where r.post_id = old.id and r.round = old.round and r.undone_at is null
                    and (old.review_reset_at is null or r.created_at > old.review_reset_at)) then
    return new;
  end if;
  insert into public.post_versions (post_id, round, platform, format, title, caption, caption_zh, media, replaced_by)
  values (old.id, old.round, old.platform, old.format, old.title, old.caption, old.caption_zh, old.media,
          nullif(auth.jwt() ->> 'email', ''))
  on conflict (post_id, round) do nothing;
  new.round := old.round + 1;
  return new;
end $$;
revoke all on function public.posts_revision() from public, anon, authenticated;

create or replace function public.get_review_feed(p_token text, p_passcode text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_client public.clients%rowtype;
begin
  select * into v_client
  from public.clients
  where access_token = p_token and active;

  if not found then
    return jsonb_build_object('error', 'not_found');
  end if;

  if v_client.passcode is not null
     and (p_passcode is null or p_passcode <> v_client.passcode) then
    return jsonb_build_object('error', 'passcode_required', 'client', v_client.name);
  end if;

  return jsonb_build_object(
    'client', jsonb_build_object(
      'name', v_client.name,
      'logo_url', v_client.logo_url,
      'handles', jsonb_build_object(
        'instagram', v_client.handle_ig,
        'facebook',  v_client.handle_fb,
        'tiktok',    v_client.handle_tiktok,
        'xhs',       v_client.handle_xhs)),
    'batches', coalesce((
      select jsonb_agg(batch order by batch->>'created_at' desc)
      from (
        select jsonb_build_object(
          'id',         b.id,
          'title',      b.title,
          'note',       b.note,
          'created_at', b.created_at,
          'posts', coalesce((
            select jsonb_agg(post order by (post->>'position')::int)
            from (
              select jsonb_build_object(
                'id',         p.id,
                'platform',   p.platform,
                'format',     p.format,
                'handle',     p.handle,
                'caption',    p.caption,
                'caption_zh', p.caption_zh,
                'title',      p.title,
                'media',      p.media,
                'position',   p.position,
                'round',      p.round,
                'reset_note', case
                  when p.review_reset_at is not null then p.review_reset_note end,
                /* The decision standing on the round on show: never one about
                   a round the client no longer sees, never one taken back. */
                'review',     (
                  select jsonb_build_object(
                    'decision',   r.decision,
                    'note',       r.note,
                    'reviewer',   case when r.source = 'team' then null else r.reviewer end,
                    'created_at', r.created_at,
                    'by_team',    (r.source = 'team'),
                    'suggested',  (r.suggested_caption is not null or r.suggested_caption_zh is not null),
                    /* The client's own edit, so Edit request reopens it. */
                    'suggested_caption',    r.suggested_caption,
                    'suggested_caption_zh', r.suggested_caption_zh)
                  from public.reviews r
                  where r.post_id = p.id and r.round = p.round and r.undone_at is null
                    and (p.review_reset_at is null or r.created_at > p.review_reset_at)
                  order by r.created_at desc
                  limit 1),
                /* What the client asked of the round before, so a revision
                   says what it answers. Words only: the earlier file and copy
                   stay with the team. */
                'asked',      case when p.round > 1 then (
                  select jsonb_build_object(
                    'note',       r.note,
                    'reviewer',   r.reviewer,
                    'created_at', r.created_at,
                    'suggested',  (r.suggested_caption is not null or r.suggested_caption_zh is not null))
                  from public.reviews r
                  where r.post_id = p.id and r.round = p.round - 1 and r.decision = 'changes'
                    and r.undone_at is null
                  order by r.created_at desc
                  limit 1) end
              ) as post
              from public.posts p
              where p.batch_id = b.id
            ) posts
          ), '[]'::jsonb)
        ) as batch
        from public.batches b
        where b.client_id = v_client.id and b.published
      ) batches
    ), '[]'::jsonb)
  );
end $$;
revoke all on function public.get_review_feed(text, text) from public;
grant execute on function public.get_review_feed(text, text) to anon, authenticated;

/* The client said yes by word of mouth: the team approves the round on show
   under its own name. The client's page reads Confirmed internally by
   {name}; the activity record files it as an approval by the colleague. */
create or replace function public.review_confirm(p_post uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me       public.team_members;
  v_post   public.posts%rowtype;
  v_pub    boolean;
  v_title  text;
  v_client text;
  v_now    text;
begin
  if not public.allowed('review.sets', 'work') then
    return jsonb_build_object('error', 'denied');
  end if;
  select * into me from public.ops_me();
  if me.id is null then return jsonb_build_object('error', 'denied'); end if;
  select * into v_post from public.posts where id = p_post for update;
  if v_post.id is null then return jsonb_build_object('error', 'no-post'); end if;
  select b.published, b.title, c.name into v_pub, v_title, v_client
    from public.batches b join public.clients c on c.id = b.client_id
   where b.id = v_post.batch_id;
  if not coalesce(v_pub, false) then return jsonb_build_object('error', 'not-published'); end if;
  select r.decision into v_now from public.reviews r
   where r.post_id = v_post.id and r.round = v_post.round and r.undone_at is null
     and (v_post.review_reset_at is null or r.created_at > v_post.review_reset_at)
   order by r.created_at desc limit 1;
  if v_now = 'approved' then return jsonb_build_object('error', 'already-approved'); end if;

  insert into public.reviews (post_id, decision, reviewer, source)
  values (v_post.id, 'approved', me.name, 'team');

  insert into public.activity_log (actor, action, subject, detail)
  values (coalesce(nullif(auth.jwt() ->> 'email', ''), me.name), 'review.approved', v_client,
          v_title || ' · ' || coalesce(nullif(v_post.platform, ''), 'post') ||
          case when v_post.round > 1 then ' · revision ' || v_post.round else '' end ||
          ' · confirmed internally');
  return jsonb_build_object('ok', true, 'reviewer', me.name);
end $$;
revoke all on function public.review_confirm(uuid) from public, anon;
grant execute on function public.review_confirm(uuid) to authenticated;

/* Takes back the team's own approval of the round on show, and nothing else:
   a client's decision stays theirs. The row is kept, marked undone. */
create or replace function public.review_revert_confirm(p_post uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me       public.team_members;
  v_post   public.posts%rowtype;
  v_rv     public.reviews%rowtype;
  v_title  text;
  v_client text;
begin
  if not public.allowed('review.sets', 'work') then
    return jsonb_build_object('error', 'denied');
  end if;
  select * into me from public.ops_me();
  if me.id is null then return jsonb_build_object('error', 'denied'); end if;
  select * into v_post from public.posts where id = p_post for update;
  if v_post.id is null then return jsonb_build_object('error', 'no-post'); end if;
  select r.* into v_rv from public.reviews r
   where r.post_id = v_post.id and r.round = v_post.round and r.undone_at is null
     and (v_post.review_reset_at is null or r.created_at > v_post.review_reset_at)
   order by r.created_at desc limit 1;
  if v_rv.id is null or v_rv.decision <> 'approved' or v_rv.source <> 'team' then
    return jsonb_build_object('error', 'not-confirmed');
  end if;
  update public.reviews set undone_at = now(), undone_by = me.id where id = v_rv.id;

  select b.title, c.name into v_title, v_client
    from public.batches b join public.clients c on c.id = b.client_id
   where b.id = v_post.batch_id;
  insert into public.activity_log (actor, action, subject, detail)
  values (coalesce(nullif(auth.jwt() ->> 'email', ''), me.name), 'review.unconfirmed', v_client,
          coalesce(v_title, '') || ' · ' || coalesce(nullif(v_post.platform, ''), 'post') ||
          ' · internal confirmation reverted');
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.review_revert_confirm(uuid) from public, anon;
grant execute on function public.review_revert_confirm(uuid) to authenticated;

/* The record files Revert confirmation under Content Review. */
create or replace function public.activity_section(p_action text)
returns text
language sql immutable parallel safe as $$
  select case
    when action in ('campaign.bulk', 'campaign.closed', 'campaign.confirmed',
                    'campaign.created', 'campaign.dates', 'campaign.deleted', 'campaign.edited',
                    'campaign.file_added', 'campaign.qc',
                    'campaign.invoice', 'campaign.invoice_file',
                    'campaign.invoice_removed', 'campaign.keyed', 'campaign.locked',
                    'campaign.opened', 'campaign.rate', 'campaign.rated',
                    'campaign.reinstated', 'campaign.replaced', 'campaign.results', 'campaign.review',
                    'campaign.stage', 'campaign.submitted', 'campaign.task_linked',
                    'campaign.task_unlinked', 'campaign.unbooked',
                    'campaign.unkeyed', 'campaign.withdrawn', 'creator.added',
                    'creator.code', 'creator.links', 'creator.links_restored',
                    'creator.links_self', 'creator.off', 'creator.on', 'creator.removed',
                    'creator.updated') then 'campaigns'
    when action in ('client.action_done', 'client.action_reopened', 'client.added',
                    'client.billing', 'client.brand', 'client.deleted', 'client.edited',
                    'client.review_on', 'client.service', 'client.service_changed',
                    'client.service_removed', 'client.stage', 'client.touch',
                    'client.touch_edited', 'client.touch_removed',
                    'client.touch_restored', 'contact.added', 'contact.deleted',
                    'contact.edited', 'contact.portal_invite', 'contact.portal_off',
                    'contact.portal_on', 'contact.primary', 'contact.removed',
                    'contact.restored', 'report.confirmed', 'report.created',
                    'report.deleted', 'report.published', 'report.returned',
                    'report.revised', 'report.submitted', 'report.unpublished',
                    'request.changed', 'request.raised',
                    'request.reinstated', 'request.replied', 'request.withdrawn',
                    'service.override') then 'clients'
    when action in ('qr.created', 'qr.restored', 'qr.revoked', 'shortlink.created',
                    'shortlink.deleted', 'shortlink.imported', 'shortlink.updated') then 'links'
    when action in ('ops.deleted', 'ops.month_deleted', 'ops.numbering') then 'ops'
    when action in ('document.deleted', 'document.issued', 'document.reissued',
                    'document.restored', 'document.signed', 'document.superseded',
                    'document.unsigned', 'document.verified', 'document.voided',
                    'register.added', 'register.edited') then 'register'
    when action in ('client.drive', 'client.handles', 'client.profile',
                    'client.removed', 'drive.imported', 'link.reset', 'post.added',
                    'post.deleted', 'post.edited', 'reapproval.requested',
                    'review.approved', 'review.changes', 'review.removed',
                    'review.unconfirmed',
                    'set.created', 'set.deleted', 'set.published', 'set.renamed',
                    'set.task_linked', 'set.task_unlinked',
                    'set.withdrawn') then 'review'
    when action in ('service.added', 'service.changed', 'service.deleted',
                    'service.off', 'service.on') then 'services'
    when action in ('team.added', 'team.changed', 'team.edited', 'team.group_added',
                    'team.group_changed', 'team.group_removed', 'team.invited') then 'team'
    else 'other'
  end
  from (select p_action as action) t
$$;
grant execute on function public.activity_section(text) to authenticated;

-- END OF REVIEW CONFIRMED INTERNALLY ----------------------------------------

-- ===========================================================================
-- SHORT LINKS FOR CLIENTS — a client's review link and a campaign's
-- selection link carry an eight-character key, and the long key each had
-- before still opens, by handing the page its new key.
-- 2026-10-01. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/sql.js compares the
-- two.
--
-- WHAT CHANGED
--   1. `clients.moved_token` / `campaigns.moved_token`: the long key a link
--      carried before its short one. It opens nothing by itself; it is
--      answered only by `link_moved`, with the key that replaced it.
--   2. `new_link_key()`: eight characters from the creator code's alphabet
--      in lower case (no 0, 1, i, l, o), from pgcrypto's random bytes, never
--      one already in use as a key or a moved key. The console makes the
--      same shape (`ADspaceAPI.accessToken`).
--   3. Once: every client and campaign whose key is longer than eight
--      characters keeps it as `moved_token` and takes a new short key. A
--      second run finds nothing left to move.
--   4. `link_moved(p_kind, p_token)`: `review` or `selection`, an exact moved
--      key in, the current key out, else null. Granted to anon, as the pages
--      that ask are signed out. It answers one key with one key: no listing,
--      no prefix.
--   5. A key changed afterwards (Reset access link) clears the moved key by
--      trigger, so a reset retires every earlier link, the long one
--      included.
--
-- ROLLBACK
--   Put each long key back first, while it is still known:
--     update public.clients set access_token = moved_token where moved_token is not null;
--     update public.campaigns set access_token = moved_token where moved_token is not null;
--   then:
--   drop trigger if exists clients_link_moved on public.clients;
--   drop trigger if exists campaigns_link_moved on public.campaigns;
--   drop function if exists public.link_key_changed();
--   drop function if exists public.link_moved(text, text);
--   drop function if exists public.new_link_key();
--   alter table public.clients drop column if exists moved_token;
--   alter table public.campaigns drop column if exists moved_token;
-- ===========================================================================

alter table public.clients   add column if not exists moved_token text;
alter table public.campaigns add column if not exists moved_token text;
create unique index if not exists clients_moved_token_idx
  on public.clients(moved_token) where moved_token is not null;
create unique index if not exists campaigns_moved_token_idx
  on public.campaigns(moved_token) where moved_token is not null;

create or replace function public.new_link_key()
returns text language plpgsql volatile set search_path = public, extensions as $$
declare
  alphabet constant text := '23456789abcdefghjkmnpqrstuvwxyz';
  v_out   text;
  v_bytes bytea;
  v_i     integer;
  v_b     integer;
begin
  loop
    v_out := '';
    while length(v_out) < 8 loop
      v_bytes := gen_random_bytes(16);
      for v_i in 0..15 loop
        v_b := get_byte(v_bytes, v_i);
        /* 248 is 31 × 8: below it every character is equally likely. */
        if v_b < 248 and length(v_out) < 8 then
          v_out := v_out || substr(alphabet, 1 + (v_b % 31), 1);
        end if;
      end loop;
    end loop;
    exit when not exists (select 1 from public.clients c
                           where c.access_token = v_out or c.moved_token = v_out)
          and not exists (select 1 from public.campaigns k
                           where k.access_token = v_out or k.moved_token = v_out);
  end loop;
  return v_out;
end $$;
revoke all on function public.new_link_key() from public, anon, authenticated;

/* A key changed by anything but this move retires the moved key with it. */
create or replace function public.link_key_changed() returns trigger
language plpgsql set search_path = public as $$
begin
  if new.access_token is distinct from old.access_token
     and new.moved_token is not distinct from old.moved_token then
    new.moved_token := null;
  end if;
  return new;
end $$;
revoke all on function public.link_key_changed() from public, anon, authenticated;
drop trigger if exists clients_link_moved on public.clients;
create trigger clients_link_moved before update on public.clients
  for each row execute function public.link_key_changed();
drop trigger if exists campaigns_link_moved on public.campaigns;
create trigger campaigns_link_moved before update on public.campaigns
  for each row execute function public.link_key_changed();

/* The move, once: a long key becomes the moved key. */
do $$
declare r record;
begin
  for r in select id from public.clients
            where length(access_token) > 8 and moved_token is null loop
    update public.clients
       set moved_token = access_token, access_token = public.new_link_key()
     where id = r.id;
  end loop;
  for r in select id from public.campaigns
            where length(access_token) > 8 and moved_token is null loop
    update public.campaigns
       set moved_token = access_token, access_token = public.new_link_key()
     where id = r.id;
  end loop;
end $$;

create or replace function public.link_moved(p_kind text, p_token text)
returns text language sql stable security definer set search_path = public as $$
  select case p_kind
    when 'review' then
      (select c.access_token from public.clients c
        where p_token is not null and c.moved_token = p_token and c.active limit 1)
    when 'selection' then
      (select k.access_token from public.campaigns k
        where p_token is not null and k.moved_token = p_token limit 1)
  end
$$;
revoke all on function public.link_moved(text, text) from public;
grant execute on function public.link_moved(text, text) to anon, authenticated;

-- END OF SHORT LINKS FOR CLIENTS --------------------------------------------

-- ===========================================================================
-- THE QUARTER RANKED — a quarter lists its people best to worst with each
-- one's whole reward, is confirmed only once every month in it is final, and
-- the bonus pool runs over fixed halves of the year.
-- 2026-10-01. Safe to run twice. Run after
-- 2026-09-28-performance-rewards.sql. Rollback at the foot of this header.
-- Mirrored byte for byte in supabase/schema.sql under the same banner;
-- tests/perf.js compares the two.
--
-- WHAT CHANGED
--   1. perf_quarter_calc: every person carries `rank` (1 is the highest
--      average; equal averages share a rank; nobody without a final month is
--      ranked) and `open` (their months in the quarter not yet final). The
--      list runs best to worst by average. The quarter carries `open_months`
--      (reviews in it not yet final) and `missing_months` (months already
--      ended that an active member on the review list has no review for).
--      The department prize goes to the winning department whole, and its
--      team leader decides the split (the user, 2026-10-01): a department
--      carries its `share` and no longer a figure for each member.
--   2. perf_quarter_confirm refuses `months-open` while any review in the
--      quarter is not final, naming how many: a month still in dispute or
--      waiting to be finalised would otherwise be left out of an average
--      that is then kept. A missing month does not refuse; the page asks
--      first.
--   3. The period of the bonus pool and the trip is a half of the year: Q1
--      and Q2, or Q3 and Q4 (perf_half), so two periods never share a
--      quarter and no month is paid twice. Any date given is read as the
--      half it falls in. `perf_company.period` is held to 1 January or
--      1 July.
--   4. perf_rewards_mine sends a member their own quarter without `rank`
--      (the ranking is management's), and their department's `share` where
--      it won.
--
-- ROLLBACK
--   Run the PERFORMANCE REWARDS section of supabase/schema.sql again (it
--   restores the five period functions, perf_quarter_calc,
--   perf_quarter_confirm and perf_rewards_mine), then:
--   alter table public.perf_company drop constraint if exists perf_company_period_half;
--   drop function if exists public.perf_half(date);
-- ===========================================================================

/* The half of the year a date falls in: 1 January or 1 July. */
create or replace function public.perf_half(p_date date)
returns date language sql immutable as $$
  select (date_trunc('year', p_date)
          + case when extract(month from p_date) >= 7 then interval '6 months' else interval '0 months' end)::date
$$;
revoke all on function public.perf_half(date) from public, anon, authenticated;

alter table public.perf_company drop constraint if exists perf_company_period_check;
alter table public.perf_company drop constraint if exists perf_company_period_half;
alter table public.perf_company add constraint perf_company_period_half
  check (period >= date '2026-07-01' and extract(day from period) = 1 and extract(month from period) in (1, 7));

create or replace function public.perf_quarter_calc(p_quarter date)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_q date := date_trunc('quarter', p_quarter)::date;
  v_qe date := (date_trunc('quarter', p_quarter) + interval '3 months')::date;
  v_people jsonb; v_wins integer; v_each numeric; v_ind jsonb;
  v_depts jsonb; v_dwins integer; v_both boolean; v_why text; v_dp jsonb;
  v_open integer; v_missing integer;
begin
  with m as (
    select t.id as mid, t.name as mname, t.staff_code as mcode, t.department as mdept, t.active as mactive,
           public.perf_reviewed(t.id) as monlist, f.nmonths, f.mean, f.emonth,
           (select count(*)::int from public.perf_reviews o
             where o.team_member_id = t.id and o.status <> 'final'
               and o.period >= v_q and o.period < v_qe) as nopen,
           exists (select 1 from public.perf_breaches b
                    where b.team_member_id = t.id and b.voided_at is null and b.severity = 4
                      and b.period >= v_q and b.period < v_qe) as ml4
      from public.team_members t
      cross join lateral (
        select count(*)::int as nmonths, round(avg((x.res ->> 'final')::numeric), 2) as mean,
               coalesce(bool_or(x.res ->> 'grade' = 'E'), false) as emonth
          from (select coalesce(r.result, public.perf_calc(r)) as res
                  from public.perf_reviews r
                 where r.team_member_id = t.id and r.status = 'final'
                   and r.period >= v_q and r.period < v_qe) x) f
     where f.nmonths > 0 or (t.active and public.perf_reviewed(t.id))
  ), e as (
    select m.*, array_remove(array[
             case when m.nmonths = 0 then 'no-final-month' end,
             case when m.nmonths > 0 and m.mean < 70 then 'below-c' end,
             case when m.emonth then 'e-month' end,
             case when m.ml4 then 'critical-breach' end,
             case when not m.mactive then 'inactive' end,
             case when not m.monlist then 'not-reviewed' end], null) as why
      from m
  ), w as (
    select e.*, cardinality(e.why) = 0 as ok,
           coalesce(cardinality(e.why) = 0
                    and e.mean = max(e.mean) filter (where cardinality(e.why) = 0) over (), false) as won
      from e
  ), p as (
    select w.*, count(*) filter (where w.won) over () as nwon,
           case when w.nmonths > 0 then rank() over (order by w.mean desc nulls last) end as mrank
      from w
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'team_member_id', p.mid, 'name', p.mname, 'staff_code', p.mcode, 'department', p.mdept,
           'active', p.mactive, 'reviewed', p.monlist, 'months', p.nmonths, 'open', p.nopen,
           'rank', p.mrank, 'average', p.mean,
           'grade', case when p.nmonths > 0 then public.perf_grade_of(p.mean) end,
           'e_month', p.emonth, 'l4', p.ml4, 'eligible', p.ok, 'reasons', to_jsonb(p.why),
           'prize', case when p.won then floor(40000.0 / p.nwon) / 100 else 0 end)
         order by p.mean desc nulls last, p.mname), '[]'::jsonb),
         coalesce(max(p.nwon), 0)
    into v_people, v_wins
    from p;
  v_each := case when v_wins > 0 then floor(40000.0 / v_wins) / 100 end;
  v_ind := jsonb_build_object('pool', 400, 'winners', v_wins, 'each', v_each,
    'paid', coalesce(v_each * v_wins, 0), 'remainder', 400 - coalesce(v_each * v_wins, 0),
    'reason', case when v_wins = 0 then 'nobody-eligible' end);

  with d as (
    select k.dep, s.c1, s.c2, s.c3, s.c4, s.c5, coalesce(s.critical, false) as crit,
           s.c1 + s.c2 + s.c3 + s.c4 + s.c5 as total, s.quarter is not null as entered, k.ord
      from (values ('creative', 1), ('marketing', 2)) k(dep, ord)
      left join public.perf_dept_scores s on s.quarter = v_q and s.department = k.dep
  ), x as (
    select d.*, bool_and(d.entered) over () as bothin,
           coalesce(d.total = max(d.total) over (), false) as istop
      from d
  ), y as (
    select x.*, (x.bothin and x.istop and x.total >= 80 and not x.crit) as won,
           coalesce((select array_agg(t.id order by t.name) from public.team_members t
                      where t.active and t.department = x.dep and public.perf_reviewed(t.id)), '{}'::uuid[]) as mems
      from x
  ), z as (
    select y.*, count(*) filter (where y.won) over () as nwon,
           case when y.won then floor(60000.0 / count(*) filter (where y.won) over ()) end as sharec
      from y
  )
  select jsonb_agg(jsonb_build_object(
           'department', z.dep, 'entered', z.entered,
           'criteria', case when z.entered then jsonb_build_array(z.c1, z.c2, z.c3, z.c4, z.c5) end,
           'total', z.total, 'grade', case when z.entered then public.perf_grade_of(z.total) end,
           'critical', z.crit, 'top', z.bothin and z.istop,
           'qualifies', z.entered and z.total >= 80 and not z.crit, 'won', z.won,
           'share', coalesce(z.sharec / 100, 0), 'members', to_jsonb(z.mems))
         order by z.ord),
         coalesce(max(z.nwon), 0), bool_and(z.bothin),
         case when bool_and(z.bothin) and max(z.nwon) = 0 then
           case when bool_or(z.istop and z.total >= 80 and z.crit) then 'critical-issue' else 'below-b' end end
    into v_depts, v_dwins, v_both, v_why
    from z;
  v_dp := jsonb_build_object('pool', 600, 'winners', v_dwins,
    'paid', case when v_dwins > 0 then floor(60000.0 / v_dwins) * v_dwins / 100 else 0 end,
    'remainder', case when v_dwins > 0 then 600 - floor(60000.0 / v_dwins) * v_dwins / 100 else 600 end,
    'reason', case when not v_both then 'scores-needed' else v_why end);

  select count(*)::int into v_open
    from public.perf_reviews r
   where r.status <> 'final' and r.period >= v_q and r.period < v_qe;
  select count(*)::int into v_missing
    from public.team_members t
    cross join generate_series(v_q, (v_qe - interval '1 month')::date, interval '1 month') g(mo)
   where t.active and public.perf_reviewed(t.id)
     and (g.mo + interval '1 month')::date <= public.perf_today()
     and not exists (select 1 from public.perf_reviews r where r.team_member_id = t.id and r.period = g.mo::date);

  return jsonb_build_object('quarter', v_q, 'word', public.perf_quarter_word(v_q),
    'ended', public.perf_today() >= v_qe, 'people', v_people, 'individual', v_ind,
    'departments', v_depts, 'department_prize', v_dp,
    'open_months', v_open, 'missing_months', v_missing);
end $$;

create or replace function public.perf_quarter_confirm(p_token text, p_quarter date)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_err text; v_me public.team_members; v_q date; v_snap jsonb; v_x jsonb; v_open integer;
begin
  v_err := public.perf_check(p_token, 'work');
  if v_err is not null then return jsonb_build_object('error', v_err); end if;
  v_me := public.ops_me();
  v_q := date_trunc('quarter', p_quarter)::date;
  if v_q is null or v_q < date '2026-07-01' then return jsonb_build_object('error', 'before-first'); end if;
  if exists (select 1 from public.perf_rewards where kind = 'quarter' and period = v_q) then
    return public.perf_quarter(p_token, v_q);
  end if;
  if public.perf_today() < (v_q + interval '3 months')::date then
    return jsonb_build_object('error', 'quarter-open');
  end if;
  select count(*)::int into v_open
    from public.perf_reviews r
   where r.status <> 'final' and r.period >= v_q and r.period < (v_q + interval '3 months')::date;
  if v_open > 0 then
    return jsonb_build_object('error', 'months-open', 'count', v_open);
  end if;
  if (select count(*) from public.perf_dept_scores where quarter = v_q) < 2 then
    return jsonb_build_object('error', 'dept-scores-needed');
  end if;
  v_snap := public.perf_quarter_calc(v_q);
  insert into public.perf_rewards (kind, period, snapshot, confirmed_by) values ('quarter', v_q, v_snap, v_me.id)
  on conflict (kind, period) do nothing;
  perform public.perf_log(null, null, 'quarter_confirmed', jsonb_build_object('key', v_q::text,
    'winners', v_snap -> 'individual' -> 'winners', 'departments', v_snap -> 'department_prize' -> 'winners'));
  for v_x in select * from jsonb_array_elements(v_snap -> 'people') loop
    if (v_x ->> 'active')::boolean then
      perform public.perf_notify((v_x ->> 'team_member_id')::uuid, 'perf.quarter',
        'Your ' || public.perf_quarter_word(v_q) || ' quarterly outcome is ready.',
        'perf.quarter.' || v_q || '.' || (v_x ->> 'team_member_id') || '.' || extract(epoch from now())::bigint);
    end if;
  end loop;
  return public.perf_quarter(p_token, v_q);
end $$;

/* A period of two quarters, now a half of the year. */
create or replace function public.perf_period_calc(p_from date)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_f date := public.perf_half(p_from);
  v_t date := (public.perf_half(p_from) + interval '6 months')::date;
  v_c public.perf_company; v_pool numeric; v_trip numeric; v_popen boolean; v_topen boolean;
  v_rows jsonb; v_units numeric; v_bpaid numeric; v_tpaid numeric;
begin
  select * into v_c from public.perf_company where period = v_f;
  v_popen := coalesce(v_c.revenue, 0) >= 500000;
  v_topen := coalesce(v_c.revenue, 0) >= 1000000;
  v_pool := case when v_popen then coalesce(v_c.pool, 0) else 0 end;
  v_trip := case when v_topen then coalesce(v_c.trip_budget, 0) else 0 end;
  with m as (
    select t.id as mid, t.name as mname, t.staff_code as mcode, t.active as mactive,
           f.nmonths, f.nb, f.mean, f.emonth,
           exists (select 1 from public.perf_breaches b
                    where b.team_member_id = t.id and b.voided_at is null and b.severity = 4
                      and b.period >= v_f and b.period < v_t) as ml4
      from public.team_members t
      cross join lateral (
        select count(*)::int as nmonths,
               (count(*) filter (where x.res ->> 'grade' in ('A', 'B')))::int as nb,
               round(avg((x.res ->> 'final')::numeric), 2) as mean,
               coalesce(bool_or(x.res ->> 'grade' = 'E'), false) as emonth
          from (select coalesce(r.result, public.perf_calc(r)) as res
                  from public.perf_reviews r
                 where r.team_member_id = t.id and r.status = 'final'
                   and r.period >= v_f and r.period < v_t) x) f
     where f.nmonths > 0 or (t.active and public.perf_reviewed(t.id))
  ), e as (
    select m.*, array_remove(array[
             case when m.nmonths = 0 then 'no-final-month' end,
             case when m.nmonths > 0 and m.nb < 3 then 'few-b-months' end,
             case when m.emonth then 'e-month' end,
             case when m.ml4 then 'critical-breach' end,
             case when not m.mactive then 'inactive' end], null) as why
      from m
  ), u as (
    select e.*, cardinality(e.why) = 0 as ok,
           case when cardinality(e.why) = 0 then
             case public.perf_grade_of(e.mean) when 'A' then 3.0 when 'B' then 1.5 when 'C' then 0.5 else 0 end
           else 0 end as units
      from e
  ), s as (
    select u.*, sum(u.units) over () as allunits from u
  ), o as (
    select s.*,
           case when s.allunits > 0 then floor(v_pool * 100 * s.units / s.allunits) / 100 else 0 end as bonus,
           case when s.allunits > 0 then floor(v_trip * 100 * s.units / s.allunits) / 100 else 0 end as tripshare
      from s
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'team_member_id', o.mid, 'name', o.mname, 'staff_code', o.mcode, 'active', o.mactive,
           'months', o.nmonths, 'months_b', o.nb, 'average', o.mean,
           'grade', case when o.nmonths > 0 then public.perf_grade_of(o.mean) end,
           'e_month', o.emonth, 'l4', o.ml4, 'eligible', o.ok, 'reasons', to_jsonb(o.why),
           'units', o.units, 'bonus', o.bonus, 'trip', o.tripshare)
         order by o.ok desc, o.units desc, o.mean desc nulls last, o.mname), '[]'::jsonb),
         coalesce(sum(o.units), 0), coalesce(sum(o.bonus), 0), coalesce(sum(o.tripshare), 0)
    into v_rows, v_units, v_bpaid, v_tpaid
    from o;
  return jsonb_build_object('period', v_f, 'word', public.perf_period_word(v_f),
    'last_month', (v_t - interval '1 month')::date, 'ended', public.perf_today() >= v_t,
    'figures', v_c.period is not null, 'total_units', v_units, 'people', v_rows,
    'bonus', jsonb_build_object('open', v_popen, 'pool', v_pool, 'paid', v_bpaid, 'remainder', v_pool - v_bpaid,
      'reason', case when v_c.period is null then 'figures-needed' when not v_popen then 'below-gate'
                     when v_pool = 0 then 'no-pool' when v_units = 0 then 'nobody-eligible' end),
    'trip', jsonb_build_object('open', v_topen, 'budget', v_trip, 'paid', v_tpaid, 'remainder', v_trip - v_tpaid,
      'reason', case when v_c.period is null then 'figures-needed' when not v_topen then 'below-gate'
                     when v_trip = 0 then 'no-budget' when v_units = 0 then 'nobody-eligible' end));
end $$;

create or replace function public.perf_period(p_token text, p_from date)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_err text; v_me public.team_members; v_f date; v_rw public.perf_rewards; v_c public.perf_company; v_out jsonb;
begin
  v_err := public.perf_check(p_token, 'view');
  if v_err is not null then return jsonb_build_object('error', v_err); end if;
  v_me := public.ops_me();
  v_f := public.perf_half(coalesce(p_from, public.perf_today()));
  if v_f < date '2026-07-01' then return jsonb_build_object('error', 'before-first'); end if;
  select * into v_rw from public.perf_rewards where kind = 'period' and period = v_f;
  v_out := coalesce(v_rw.snapshot, public.perf_period_calc(v_f));
  v_out := v_out || jsonb_build_object(
    'people', public.perf_hide_own(v_out -> 'people', v_me.id),
    'admin', public.perf_is_admin(),
    'confirmed', v_rw.period is not null, 'confirmed_at', v_rw.confirmed_at,
    'confirmed_by', (select t.name from public.team_members t where t.id = v_rw.confirmed_by),
    'ended', public.perf_today() >= (v_f + interval '6 months')::date,
    'events', public.perf_reward_events(array['company_set', 'period_confirmed', 'period_reopened'], v_f::text));
  /* Revenue and profit, and the ceiling they set, for an admin alone. */
  if public.perf_is_admin() then
    select * into v_c from public.perf_company where period = v_f;
    if v_c.period is not null then
      v_out := v_out || jsonb_build_object('company', jsonb_build_object('revenue', v_c.revenue, 'profit', v_c.profit,
        'pool', v_c.pool, 'trip_budget', v_c.trip_budget, 'max_pool', greatest(0, floor(v_c.profit * 10) / 100)));
    end if;
  end if;
  return v_out;
end $$;

create or replace function public.perf_company_set(p_token text, p_from date, p_payload jsonb)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_err text; v_me public.team_members; v_f date; v_rev numeric; v_pro numeric; v_pool numeric; v_trip numeric;
  v_was public.perf_company; v_max numeric; v_changed jsonb := '[]'::jsonb;
begin
  v_err := public.perf_check(p_token, 'work');
  if v_err is not null then return jsonb_build_object('error', v_err); end if;
  if not public.perf_is_admin() then return jsonb_build_object('error', 'admin-only'); end if;
  v_me := public.ops_me();
  v_f := public.perf_half(p_from);
  if v_f is null or v_f < date '2026-07-01' then return jsonb_build_object('error', 'before-first'); end if;
  if exists (select 1 from public.perf_rewards where kind = 'period' and period = v_f) then
    return jsonb_build_object('error', 'confirmed');
  end if;
  if coalesce(jsonb_typeof(p_payload -> 'revenue'), '') <> 'number'
     or coalesce(jsonb_typeof(p_payload -> 'profit'), '') <> 'number'
     or coalesce(jsonb_typeof(p_payload -> 'pool'), 'number') not in ('number', 'null')
     or coalesce(jsonb_typeof(p_payload -> 'trip_budget'), 'number') not in ('number', 'null') then
    return jsonb_build_object('error', 'bad-amount');
  end if;
  v_rev := (p_payload ->> 'revenue')::numeric;
  v_pro := (p_payload ->> 'profit')::numeric;
  v_pool := coalesce((p_payload ->> 'pool')::numeric, 0);
  v_trip := coalesce((p_payload ->> 'trip_budget')::numeric, 0);
  if v_rev < 0 or v_pool < 0 or v_trip < 0
     or round(v_rev, 2) <> v_rev or round(v_pro, 2) <> v_pro or round(v_pool, 2) <> v_pool or round(v_trip, 2) <> v_trip
     or greatest(abs(v_rev), abs(v_pro), v_pool, v_trip) >= 1e12 then
    return jsonb_build_object('error', 'bad-amount');
  end if;
  v_max := greatest(0, floor(v_pro * 10) / 100);
  if v_pool > 0 and v_rev < 500000 then return jsonb_build_object('error', 'pool-closed'); end if;
  if v_pool > v_max then return jsonb_build_object('error', 'pool-over', 'max', v_max); end if;
  if v_trip > 0 and v_rev < 1000000 then return jsonb_build_object('error', 'trip-closed'); end if;
  select * into v_was from public.perf_company where period = v_f for update;
  insert into public.perf_company (period, revenue, profit, pool, trip_budget, entered_by, updated_at)
  values (v_f, v_rev, v_pro, v_pool, v_trip, v_me.id, now())
  on conflict (period) do update set revenue = excluded.revenue, profit = excluded.profit, pool = excluded.pool,
    trip_budget = excluded.trip_budget, entered_by = excluded.entered_by, updated_at = now();
  /* Revenue and profit are filed by name only, so the history an admin
     shares with the rest of management never carries them. */
  if v_was.revenue is distinct from v_rev then v_changed := v_changed || '[{"key":"revenue"}]'::jsonb; end if;
  if v_was.profit is distinct from v_pro then v_changed := v_changed || '[{"key":"profit"}]'::jsonb; end if;
  if v_was.pool is distinct from v_pool then
    v_changed := v_changed || jsonb_build_array(jsonb_build_object('key', 'pool', 'from', v_was.pool, 'to', v_pool));
  end if;
  if v_was.trip_budget is distinct from v_trip then
    v_changed := v_changed || jsonb_build_array(jsonb_build_object('key', 'trip_budget', 'from', v_was.trip_budget, 'to', v_trip));
  end if;
  if jsonb_array_length(v_changed) > 0 then
    perform public.perf_log(null, null, 'company_set', jsonb_build_object('key', v_f::text, 'changed', v_changed));
  end if;
  return public.perf_period(p_token, v_f);
end $$;

create or replace function public.perf_period_confirm(p_token text, p_from date)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_err text; v_me public.team_members; v_f date; v_snap jsonb; v_x jsonb;
begin
  v_err := public.perf_check(p_token, 'work');
  if v_err is not null then return jsonb_build_object('error', v_err); end if;
  v_me := public.ops_me();
  v_f := public.perf_half(p_from);
  if v_f is null or v_f < date '2026-07-01' then return jsonb_build_object('error', 'before-first'); end if;
  if exists (select 1 from public.perf_rewards where kind = 'period' and period = v_f) then
    return public.perf_period(p_token, v_f);
  end if;
  if public.perf_today() < (v_f + interval '6 months')::date then
    return jsonb_build_object('error', 'period-open');
  end if;
  if not exists (select 1 from public.perf_company where period = v_f) then
    return jsonb_build_object('error', 'figures-needed');
  end if;
  v_snap := public.perf_period_calc(v_f);
  insert into public.perf_rewards (kind, period, snapshot, confirmed_by) values ('period', v_f, v_snap, v_me.id)
  on conflict (kind, period) do nothing;
  perform public.perf_log(null, null, 'period_confirmed', jsonb_build_object('key', v_f::text));
  for v_x in select * from jsonb_array_elements(v_snap -> 'people') loop
    if (v_x ->> 'active')::boolean then
      perform public.perf_notify((v_x ->> 'team_member_id')::uuid, 'perf.period',
        'Your ' || public.perf_period_word(v_f) || ' bonus and trip outcome is ready.',
        'perf.period.' || v_f || '.' || (v_x ->> 'team_member_id') || '.' || extract(epoch from now())::bigint);
    end if;
  end loop;
  return public.perf_period(p_token, v_f);
end $$;

create or replace function public.perf_period_reopen(p_token text, p_from date)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_err text; v_f date; v_rw public.perf_rewards;
begin
  v_err := public.perf_check(p_token, 'manage');
  if v_err is not null then return jsonb_build_object('error', v_err); end if;
  v_f := public.perf_half(p_from);
  select * into v_rw from public.perf_rewards where kind = 'period' and period = v_f for update;
  if v_rw.period is null then return jsonb_build_object('error', 'not-confirmed'); end if;
  perform public.perf_log(null, null, 'period_reopened', jsonb_build_object('key', v_f::text, 'was', v_rw.snapshot,
    'confirmed_at', v_rw.confirmed_at));
  delete from public.perf_rewards where kind = 'period' and period = v_f;
  return public.perf_period(p_token, v_f);
end $$;

/* The member's own outcome, as before, with the ranking left out. */
create or replace function public.perf_rewards_mine()
returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_me public.team_members; v_id text;
begin
  v_me := public.ops_me();
  if v_me.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if public.perf_guarded(v_me.id) and not public.perf_code_fresh() then
    return jsonb_build_object('error', 'code-needed');
  end if;
  v_id := v_me.id::text;
  return jsonb_build_object(
    'quarters', coalesce((
      select jsonb_agg(jsonb_build_object('quarter', rw.period, 'word', rw.snapshot ->> 'word',
               'confirmed_at', rw.confirmed_at, 'me', me_row - 'rank',
               'individual', jsonb_build_object('winners', rw.snapshot -> 'individual' -> 'winners',
                                                'reason', rw.snapshot -> 'individual' -> 'reason'),
               'department', (select jsonb_build_object('department', d ->> 'department', 'total', d -> 'total',
                                       'grade', d -> 'grade', 'won', d -> 'won', 'share', d -> 'share')
                                from jsonb_array_elements(rw.snapshot -> 'departments') d
                               where d -> 'members' ? v_id limit 1))
             order by rw.period desc)
        from public.perf_rewards rw
        cross join lateral (select p as me_row from jsonb_array_elements(rw.snapshot -> 'people') p
                             where p ->> 'team_member_id' = v_id limit 1) mine
       where rw.kind = 'quarter'), '[]'::jsonb),
    'periods', coalesce((
      select jsonb_agg(jsonb_build_object('period', rw.period, 'word', rw.snapshot ->> 'word',
               'confirmed_at', rw.confirmed_at, 'me', me_row,
               'bonus_open', rw.snapshot -> 'bonus' -> 'open', 'trip_open', rw.snapshot -> 'trip' -> 'open')
             order by rw.period desc)
        from public.perf_rewards rw
        cross join lateral (select p as me_row from jsonb_array_elements(rw.snapshot -> 'people') p
                             where p ->> 'team_member_id' = v_id limit 1) mine
       where rw.kind = 'period'), '[]'::jsonb),
    'flex', coalesce((
      select jsonb_agg(jsonb_build_object('period', f.fx ->> 'period', 'month', f.fx ->> 'month',
               'next_month', f.fx ->> 'next_month', 'unlocked', f.fx -> 'unlocked',
               'eligible', (select p -> 'eligible' from jsonb_array_elements(f.fx -> 'people') p
                             where p ->> 'team_member_id' = v_id limit 1))
             order by f.pd desc)
        from (select r.period as pd, public.perf_flex_calc(r.period) as fx
                from public.perf_reviews r
               where r.team_member_id = v_me.id and r.status = 'final') f
       where (f.fx ->> 'decided')::boolean
         and exists (select 1 from jsonb_array_elements(f.fx -> 'people') p where p ->> 'team_member_id' = v_id)), '[]'::jsonb),
    'commissions', coalesce((
      select jsonb_agg(x.j - 'created_by' - 'removed_at' - 'name' - 'staff_code' order by x.mo desc, x.ca desc)
        from (select public.perf_commission_json(c) as j, c.month as mo, c.created_at as ca
                from public.perf_commissions c
               where c.team_member_id = v_me.id and c.removed_at is null) x
       where x.j ->> 'state' <> 'pending'), '[]'::jsonb));
end $$;

/* Who may call what: create or replace keeps each function's grants, and
   these state them again. */
revoke all on function public.perf_quarter_calc(date) from public, anon, authenticated;
revoke all on function public.perf_period_calc(date) from public, anon, authenticated;
revoke all on function public.perf_quarter_confirm(text, date) from public, anon, authenticated;
revoke all on function public.perf_period(text, date) from public, anon, authenticated;
revoke all on function public.perf_company_set(text, date, jsonb) from public, anon, authenticated;
revoke all on function public.perf_period_confirm(text, date) from public, anon, authenticated;
revoke all on function public.perf_period_reopen(text, date) from public, anon, authenticated;
revoke all on function public.perf_rewards_mine() from public, anon, authenticated;
