-- END OF THE QUARTER RANKED --------------------------------------------------

-- ===========================================================================
-- DATE OF EVALUATION — each month's review records the day its numbers were
-- reported to the team member, and the member has 7 days from release to
-- dispute.
-- 2026-10-01. Safe to run twice. Run after
-- 2026-09-28-performance-release-notify.sql. Rollback at the foot of this
-- header. Mirrored byte for byte in supabase/schema.sql under the same
-- banner; tests/perf.js compares the two.
--
-- WHAT CHANGED (the user, 2026-10-01)
--   1. `perf_reviews.evaluated_on` (date): the day the report and its
--      numbers were reported to the team member. Release fills it with the
--      day of release (Malaysia) where it is empty; management may correct
--      it until the record is final.
--   2. perf_save takes `evaluated_on` in its payload: on or after the first
--      day of the month reviewed and never after today in Malaysia
--      (`bad-eval-date`); an empty value clears it. A change is filed from
--      and to.
--   3. perf_release gives the member 7 days to dispute (was 3). A month
--      released before keeps the window it was given.
--   4. perf_json sends `evaluated_on`, so the review, the member's own page
--      and the printed record read it beside the last day to dispute.
--
-- ROLLBACK
--   Run the PERFORMANCE RECORDS, THEIR TRAIL AND THEIR CHECK section of
--   supabase/schema.sql again for perf_save, the DEPARTMENT AND ROLE ON THE
--   TEAM section for perf_json and the RELEASE WITH OR WITHOUT TELLING
--   section for perf_release, then:
--   alter table public.perf_reviews drop column if exists evaluated_on;
-- ===========================================================================

alter table public.perf_reviews add column if not exists evaluated_on date;

create or replace function public.perf_json(r public.perf_reviews, p_full boolean)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare m public.team_members; pp public.perf_people; out jsonb;
begin
  select * into m from public.team_members where id = r.team_member_id;
  select * into pp from public.perf_people where team_member_id = r.team_member_id;
  out := jsonb_build_object(
    'id', r.id, 'team_member_id', r.team_member_id, 'period', r.period,
    'month', public.perf_month_word(r.period), 'status', r.status,
    'member', jsonb_build_object('name', m.name, 'staff_code', m.staff_code,
      'designation', m.designation, 'department', m.department,
      'role_family', m.role_family, 'runs_ads', coalesce(pp.runs_ads, false)),
    'scores', jsonb_build_object('output', r.s_output, 'accuracy', r.s_accuracy,
      'delivery', r.s_delivery, 'client', r.s_client, 'comms', r.s_comms,
      'initiative', r.s_initiative),
    'rates', jsonb_build_object('posting', r.r_posting, 'timeline', r.r_timeline,
      'satisfaction', r.r_satisfaction, 'pacing', r.r_pacing, 'sla', r.r_sla),
    'notes', r.notes, 'improvement', r.improvement, 'review_by', r.review_by,
    'evaluated_on', r.evaluated_on,
    'reward_step', r.reward_step, 'serial', r.serial,
    'reviewer', (select name from public.team_members where id = r.reviewer_id),
    'released_at', r.released_at, 'dispute_until', r.dispute_until,
    'dispute_open', r.status = 'released' and r.dispute_until > now()
                    and not exists (select 1 from public.perf_disputes d
                                     where d.review_id = r.id and d.version = r.version),
    'acknowledged_at', r.acknowledged_at, 'finalised_at', r.finalised_at,
    'finalised_by', (select name from public.team_members where id = r.finalised_by),
    'version', r.version, 'rev', r.rev,
    'result', public.perf_calc(r),
    'breaches', public.perf_breaches_json(r.team_member_id, r.period, false),
    'disputes', coalesce((select jsonb_agg(jsonb_build_object(
        'id', d.id, 'item', d.item, 'breach_id', d.breach_id, 'reason', d.reason,
        'breach_what', (select b.what from public.perf_breaches b where b.id = d.breach_id),
        'raised_at', d.raised_at, 'decision', d.decision, 'response', d.response,
        'before_value', d.before_value, 'after_value', d.after_value,
        'decided_by', (select name from public.team_members where id = d.decided_by),
        'decided_at', d.decided_at) order by d.raised_at)
        from public.perf_disputes d where d.review_id = r.id and d.version = r.version), '[]'::jsonb));
  if p_full then
    out := out || jsonb_build_object(
      'voided', (select coalesce(jsonb_agg(x), '[]'::jsonb)
                   from jsonb_array_elements(public.perf_breaches_json(r.team_member_id, r.period, true)) x
                  where x ->> 'voided_at' is not null),
      'ops', public.perf_ops_rate(r.team_member_id, r.period),
      'events', coalesce((select jsonb_agg(jsonb_build_object(
          'kind', e.kind, 'detail', e.detail, 'at', e.created_at,
          'by', coalesce((select name from public.team_members where id = e.actor_id), e.actor_email))
          order by e.created_at desc)
          from public.perf_events e where e.review_id = r.id), '[]'::jsonb));
  end if;
  return out;
end $$;

create or replace function public.perf_save(p_token text, p_member uuid, p_period date,
                                            p_payload jsonb, p_rev integer)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  err text; m public.team_members; r public.perf_reviews; p date := date_trunc('month', p_period)::date;
  sc jsonb := coalesce(p_payload -> 'scores', '{}'::jsonb);
  rt jsonb := coalesce(p_payload -> 'rates', '{}'::jsonb);
  k text; v jsonb; mx numeric; rb date; ev date; was public.perf_reviews; changed jsonb;
begin
  err := public.perf_check(p_token, 'work');
  if err is not null then return jsonb_build_object('error', err); end if;
  m := public.ops_me();
  if p_member = m.id then return jsonb_build_object('error', 'own-review'); end if;
  if not exists (select 1 from public.team_members where id = p_member and active) then
    return jsonb_build_object('error', 'not-found');
  end if;
  if jsonb_typeof(sc) <> 'object' or jsonb_typeof(rt) <> 'object'
     or (p_payload ? 'notes' and jsonb_typeof(p_payload -> 'notes') <> 'object') then
    return jsonb_build_object('error', 'bad-payload');
  end if;
  for k, v in select key, value from jsonb_each(sc) loop
    mx := case k when 'output' then 25 when 'accuracy' then 15 when 'delivery' then 15
                 when 'client' then 20 when 'comms' then 15 when 'initiative' then 10 end;
    if mx is null then return jsonb_build_object('error', 'bad-score', 'key', k); end if;
    if jsonb_typeof(v) <> 'null' then
      if jsonb_typeof(v) <> 'number' then return jsonb_build_object('error', 'bad-score', 'key', k, 'max', mx); end if;
      if (v #>> '{}')::numeric not between 0 and mx or round((v #>> '{}')::numeric, 1) <> (v #>> '{}')::numeric then
        return jsonb_build_object('error', 'bad-score', 'key', k, 'max', mx);
      end if;
    end if;
  end loop;
  for k, v in select key, value from jsonb_each(rt) loop
    mx := case k when 'pacing' then 1000 when 'posting' then 100 when 'timeline' then 100
                 when 'satisfaction' then 100 when 'sla' then 100 end;
    if mx is null then return jsonb_build_object('error', 'bad-rate', 'key', k); end if;
    if jsonb_typeof(v) <> 'null' then
      if jsonb_typeof(v) <> 'number' then return jsonb_build_object('error', 'bad-rate', 'key', k); end if;
      if (v #>> '{}')::numeric not between 0 and mx then return jsonb_build_object('error', 'bad-rate', 'key', k); end if;
    end if;
  end loop;
  if coalesce(p_payload ->> 'review_by', '') <> '' then
    begin
      rb := (p_payload ->> 'review_by')::date;
    exception when others then
      return jsonb_build_object('error', 'bad-date');
    end;
  end if;

  /* The day the month was evaluated: on or after its first day, never
     after today in Malaysia. */
  if coalesce(p_payload ->> 'evaluated_on', '') <> '' then
    begin
      ev := (p_payload ->> 'evaluated_on')::date;
    exception when others then
      return jsonb_build_object('error', 'bad-eval-date');
    end;
    if ev < p or ev > (now() at time zone 'Asia/Kuala_Lumpur')::date then
      return jsonb_build_object('error', 'bad-eval-date');
    end if;
  end if;

  select * into r from public.perf_reviews where team_member_id = p_member and period = p for update;
  if r.id is null then
    insert into public.perf_reviews (team_member_id, period) values (p_member, p)
    on conflict (team_member_id, period) do nothing;
    select * into r from public.perf_reviews where team_member_id = p_member and period = p for update;
    perform public.perf_log(r.id, p_member, 'started', '{}'::jsonb);
  elsif p_rev is not null and r.rev <> p_rev then
    return jsonb_build_object('error', 'stale', 'record', public.perf_json(r, true));
  end if;
  /* The scores are the draft's. What the month asks of the person next (the
     improvement, the date it is reviewed by, the step or reward) is written
     at the 1-1 and may be filled in until the record is final. */
  if r.status = 'final' or (r.status <> 'draft'
       and (p_payload - 'improvement' - 'review_by' - 'reward_step' - 'evaluated_on') <> '{}'::jsonb) then
    return jsonb_build_object('error', 'not-draft');
  end if;

  was := r;
  update public.perf_reviews set
    s_output     = case when sc ? 'output'     then (sc ->> 'output')::numeric     else s_output end,
    s_accuracy   = case when sc ? 'accuracy'   then (sc ->> 'accuracy')::numeric   else s_accuracy end,
    s_delivery   = case when sc ? 'delivery'   then (sc ->> 'delivery')::numeric   else s_delivery end,
    s_client     = case when sc ? 'client'     then (sc ->> 'client')::numeric     else s_client end,
    s_comms      = case when sc ? 'comms'      then (sc ->> 'comms')::numeric      else s_comms end,
    s_initiative = case when sc ? 'initiative' then (sc ->> 'initiative')::numeric else s_initiative end,
    r_posting      = case when rt ? 'posting'      then (rt ->> 'posting')::numeric      else r_posting end,
    r_timeline     = case when rt ? 'timeline'     then (rt ->> 'timeline')::numeric     else r_timeline end,
    r_satisfaction = case when rt ? 'satisfaction' then (rt ->> 'satisfaction')::numeric else r_satisfaction end,
    r_pacing       = case when rt ? 'pacing'       then (rt ->> 'pacing')::numeric       else r_pacing end,
    r_sla          = case when rt ? 'sla'          then (rt ->> 'sla')::numeric          else r_sla end,
    notes       = case when p_payload ? 'notes' then coalesce(p_payload -> 'notes', '{}'::jsonb) else notes end,
    improvement = case when p_payload ? 'improvement' then nullif(btrim(p_payload ->> 'improvement'), '') else improvement end,
    review_by   = case when p_payload ? 'review_by' then rb else review_by end,
    reward_step = case when p_payload ? 'reward_step' then nullif(btrim(p_payload ->> 'reward_step'), '') else reward_step end,
    evaluated_on = case when p_payload ? 'evaluated_on' then ev else evaluated_on end,
    updated_at = now(), rev = rev + 1
  where id = r.id
  returning * into r;
  /* What the save changed, named: each scorecard and rate whose value moved,
     from and to, then whether the notes or the plan moved. A save that moved
     nothing is not filed. */
  select coalesce(jsonb_agg(jsonb_build_object('key', c.key, 'from', c.a, 'to', c.b) order by c.n), '[]'::jsonb)
    into changed
    from (values (1, 'output', was.s_output, r.s_output), (2, 'accuracy', was.s_accuracy, r.s_accuracy),
                 (3, 'delivery', was.s_delivery, r.s_delivery), (4, 'client', was.s_client, r.s_client),
                 (5, 'comms', was.s_comms, r.s_comms), (6, 'initiative', was.s_initiative, r.s_initiative),
                 (7, 'posting', was.r_posting, r.r_posting), (8, 'timeline', was.r_timeline, r.r_timeline),
                 (9, 'satisfaction', was.r_satisfaction, r.r_satisfaction), (10, 'pacing', was.r_pacing, r.r_pacing),
                 (11, 'sla', was.r_sla, r.r_sla)) as c(n, key, a, b)
   where c.a is distinct from c.b;
  if coalesce(was.notes, '{}'::jsonb) is distinct from coalesce(r.notes, '{}'::jsonb) then
    changed := changed || jsonb_build_array(jsonb_build_object('key', 'notes'));
  end if;
  if was.improvement is distinct from r.improvement or was.review_by is distinct from r.review_by
     or was.reward_step is distinct from r.reward_step then
    changed := changed || jsonb_build_array(jsonb_build_object('key', 'plan'));
  end if;
  if was.evaluated_on is distinct from r.evaluated_on then
    changed := changed || jsonb_build_array(jsonb_build_object('key', 'evaluated_on', 'from', was.evaluated_on, 'to', r.evaluated_on));
  end if;
  if jsonb_array_length(changed) > 0 then
    perform public.perf_log(r.id, p_member, 'scored', jsonb_build_object('changed', changed));
  end if;
  return public.perf_json(r, true);
end $$;

create or replace function public.perf_release(p_token text, p_review uuid, p_rev integer, p_notify boolean default true)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare err text; m public.team_members; r public.perf_reviews; tm public.team_members;
begin
  err := public.perf_check(p_token, 'work');
  if err is not null then return jsonb_build_object('error', err); end if;
  m := public.ops_me();
  select * into r from public.perf_reviews where id = p_review for update;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if r.team_member_id = m.id then return jsonb_build_object('error', 'own-review'); end if;
  if p_rev is not null and r.rev <> p_rev then
    return jsonb_build_object('error', 'stale', 'record', public.perf_json(r, true));
  end if;
  if r.status <> 'draft' then return jsonb_build_object('error', 'not-draft'); end if;
  if not (public.perf_calc(r) ->> 'complete')::boolean then
    return jsonb_build_object('error', 'incomplete');
  end if;
  select * into tm from public.team_members where id = r.team_member_id;
  if r.serial is null and coalesce(btrim(tm.staff_code), '') = '' then
    return jsonb_build_object('error', 'no-staff-code');
  end if;
  update public.perf_reviews set status = 'released', released_at = now(),
         dispute_until = now() + interval '7 days', reviewer_id = m.id,
         evaluated_on = coalesce(evaluated_on, (now() at time zone 'Asia/Kuala_Lumpur')::date),
         serial = coalesce(serial, 'ADHR/' || upper(btrim(tm.staff_code)) || '/PR' || to_char(period, 'YYMM')),
         rev = rev + 1, updated_at = now()
   where id = r.id returning * into r;
  perform public.perf_log(r.id, r.team_member_id, 'released',
    jsonb_build_object('version', r.version, 'notified', coalesce(p_notify, true)));
  if coalesce(p_notify, true) then
    perform public.perf_notify(r.team_member_id, 'perf.released',
      'Your ' || public.perf_month_word(r.period) || ' performance review is ready.',
      'perf.released.' || r.id || '.' || r.version);
  end if;
  return public.perf_json(r, true);
end $$;

revoke all on function public.perf_json(public.perf_reviews, boolean) from public, anon, authenticated;
revoke all on function public.perf_save(text, uuid, date, jsonb, integer) from public, anon, authenticated;
revoke all on function public.perf_release(text, uuid, integer, boolean) from public, anon, authenticated;
grant execute on function public.perf_save(text, uuid, date, jsonb, integer) to authenticated;
grant execute on function public.perf_release(text, uuid, integer, boolean) to authenticated;

-- END OF DATE OF EVALUATION --------------------------------------------------
-- ===========================================================================
-- DRAFT WITH AI LIMITS — every press of Draft with AI is counted. A report
-- has one draft; drafting it again is an admin's (up to 5 a report in 24
-- hours). A colleague has 20 a day and the team 60, so a slip or a stuck
-- button cannot run up the AI bill. A draft that failed is not counted.
-- 2026-10-01. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/smsql.js compares the
-- two.
--
-- WHAT CHANGED
--   1. `ai_drafts`: one row a press (the report, the colleague, when, and
--      pending, drafted or failed). Row level security on, no policy, every
--      grant revoked: only the two functions below read or write it.
--   2. `ai_draft_claim(p_report)`: Reports at Work. Counts under one lock
--      and answers `ai-limit` with the scope and when the next draft is
--      free: `redraft` where a colleague who is not an admin asks for a
--      report's second draft (no time: an admin redrafts it), `report` where
--      an admin passes 5 for the report in 24 hours, `person` past 20 and
--      `team` past 60 in 24 hours. Otherwise it records a pending press and
--      answers its id and how many the colleague has left today.
--   3. `ai_draft_done(p_id, p_ok)`: the `report-draft` function marks its
--      own press drafted or failed; only the colleague who pressed, only
--      while pending.
--
-- ROLLBACK
--   drop function if exists public.ai_draft_done(uuid, boolean);
--   drop function if exists public.ai_draft_claim(uuid);
--   drop table if exists public.ai_drafts;
-- ===========================================================================

create table if not exists public.ai_drafts (
  id             uuid primary key default gen_random_uuid(),
  report_id      uuid references public.sm_reports(id) on delete set null,
  team_member_id uuid references public.team_members(id) on delete set null,
  outcome        text not null default 'pending',
  created_at     timestamptz not null default now(),
  constraint ai_drafts_outcome check (outcome in ('pending', 'drafted', 'failed'))
);
create index if not exists ai_drafts_member_idx on public.ai_drafts (team_member_id, created_at);
create index if not exists ai_drafts_report_idx on public.ai_drafts (report_id, created_at);
create index if not exists ai_drafts_at_idx on public.ai_drafts (created_at);
alter table public.ai_drafts enable row level security;
revoke all on public.ai_drafts from public, anon, authenticated;

create or replace function public.ai_draft_claim(p_report uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m public.team_members;
  since timestamptz := now() - interval '24 hours';
  n_report integer;
  n_member integer;
  n_team integer;
  first_at timestamptz;
  new_id uuid;
begin
  if not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'denied'); end if;
  -- One count at a time, so two presses together cannot both take the last draft.
  perform pg_advisory_xact_lock(hashtext('ai_draft_claim'));
  -- One draft a report; a second and later is an admin's.
  if not coalesce(m.is_admin, false) and exists (
    select 1 from public.ai_drafts d where d.report_id = p_report and d.outcome <> 'failed') then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'redraft', 'limit', 1);
  end if;
  select count(*), min(d.created_at) into n_report, first_at from public.ai_drafts d
   where d.report_id = p_report and d.created_at > since and d.outcome <> 'failed';
  if n_report >= 5 then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'report', 'limit', 5, 'next', first_at + interval '24 hours');
  end if;
  select count(*), min(d.created_at) into n_member, first_at from public.ai_drafts d
   where d.team_member_id = m.id and d.created_at > since and d.outcome <> 'failed';
  if n_member >= 20 then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'person', 'limit', 20, 'next', first_at + interval '24 hours');
  end if;
  select count(*), min(d.created_at) into n_team, first_at from public.ai_drafts d
   where d.created_at > since and d.outcome <> 'failed';
  if n_team >= 60 then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'team', 'limit', 60, 'next', first_at + interval '24 hours');
  end if;
  insert into public.ai_drafts (report_id, team_member_id) values (p_report, m.id) returning id into new_id;
  return jsonb_build_object('id', new_id, 'left', 20 - n_member - 1);
end $$;

create or replace function public.ai_draft_done(p_id uuid, p_ok boolean)
returns void
language sql security definer set search_path = public as $$
  update public.ai_drafts d
     set outcome = case when p_ok then 'drafted' else 'failed' end
   where d.id = p_id and d.outcome = 'pending'
     and d.team_member_id = (public.ops_me()).id
$$;

revoke all on function public.ai_draft_claim(uuid) from public, anon, authenticated;
revoke all on function public.ai_draft_done(uuid, boolean) from public, anon, authenticated;
grant execute on function public.ai_draft_claim(uuid) to authenticated;
grant execute on function public.ai_draft_done(uuid, boolean) to authenticated;

-- END OF DRAFT WITH AI LIMITS ------------------------------------------------
-- ===========================================================================
-- AD IDS ON THE REPORT — each ad row keeps the Ads Manager Ad IDs it was
-- built from, and the ad account's ID, for the team to find the ad again.
-- 2026-10-01. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/smsql.js compares the
-- two.
--
-- WHAT CHANGED
--   1. `sm_report_ads.ad_ids`: the Ad IDs a row gathers (copies of one
--      creative are one row, so it can hold several). Filled from an export's
--      Ad ID column; a later paste matches its rows by them first.
--   2. `sm_report_ads.ad_account`: the ad account's ID, from an Account ID
--      column, so the console can open the ads in Ads Manager.
--   Both are the team's references: the console shows them, the PDF never
--   prints them.
--
-- ROLLBACK
--   alter table public.sm_report_ads drop column if exists ad_account;
--   alter table public.sm_report_ads drop column if exists ad_ids;
-- ===========================================================================

alter table public.sm_report_ads add column if not exists ad_ids text[];
alter table public.sm_report_ads add column if not exists ad_account text;

-- END OF AD IDS ON THE REPORT ------------------------------------------------
-- ===========================================================================
-- REPORT LANGUAGE — a report is written and printed in English or Chinese.
-- 2026-10-01. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/smsql.js compares the
-- two.
--
-- WHAT CHANGED
--   1. `sm_reports.lang` ('en' or 'zh', English by default): the language the
--      client reads. The console sets it beside Draft with AI; the draft is
--      written in it and the PDF's own headings, labels and dates follow it.
--   2. `sm_report_snapshot` sends it, so a published version freezes the
--      language it was issued in. The function is otherwise unchanged.
--
-- ROLLBACK
--   Run the REPORTS section's sm_report_snapshot again, then
--   alter table public.sm_reports drop column if exists lang;
-- ===========================================================================

alter table public.sm_reports add column if not exists lang text not null default 'en';
alter table public.sm_reports drop constraint if exists sm_reports_lang;
alter table public.sm_reports add constraint sm_reports_lang check (lang in ('en', 'zh'));

create or replace function public.sm_report_snapshot(p_id uuid, p_final boolean default false)
returns jsonb
language plpgsql security definer stable set search_path = public as $$
declare
  r public.sm_reports;
  c public.clients;
begin
  if not public.allowed('reports', 'view') and not public.allowed('clients', 'view') then
    return jsonb_build_object('error', 'denied');
  end if;
  select * into r from public.sm_reports where id = p_id;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  -- Somebody who reads Clients but not Reports reads the finished report
  -- only: once it is confirmed, never while it is being prepared.
  if not public.allowed('reports', 'view') and r.status not in ('confirmed', 'published') then
    return jsonb_build_object('error', 'denied');
  end if;
  select * into c from public.clients where id = r.client_id;
  return jsonb_build_object(
    'report', jsonb_build_object(
      'id', r.id, 'kind', r.kind, 'title', r.title, 'client_name', c.name, 'client_logo_url', c.logo_url,
      'market', to_jsonb(c) ->> 'market', 'lang', r.lang,
      'period_start', r.period_start, 'period_end', r.period_end,
      'headline', r.headline, 'intro', r.intro, 'insights', r.insights, 'rank_metric', r.rank_metric,
      'first_month', r.first_month, 'ads_totals', r.ads_totals,
      'status', case when p_final then 'final' else r.status end,
      'version_no', r.version_no, 'generated_at', now(),
      'prepared_by_name', (select name from public.team_members where id = r.submitted_by)),
    'platforms', coalesce((select jsonb_agg(to_jsonb(p) - 'created_at' order by p.position, p.created_at)
                  from public.sm_report_platforms p where p.report_id = r.id), '[]'::jsonb),
    'posts', coalesce((select jsonb_agg((to_jsonb(q) - 'created_at' - 'thumb_data') || jsonb_build_object('thumb_url', q.thumb_data)
                  order by q.posted_on nulls last, q.position, q.created_at)
                  from public.sm_report_posts q where q.report_id = r.id), '[]'::jsonb),
    'ads', coalesce((select jsonb_agg((to_jsonb(a) - 'created_at' - 'thumb_data') || jsonb_build_object('thumb_url', a.thumb_data)
                  order by a.position, a.created_at)
                  from public.sm_report_ads a where a.report_id = r.id), '[]'::jsonb));
end $$;
grant execute on function public.sm_report_snapshot(uuid, boolean) to authenticated;

-- END OF REPORT LANGUAGE -----------------------------------------------------
-- ===========================================================================
-- FIRST MONTH OF ADS UNTICKED — a new advertising report compares with the
-- month before.
-- 2026-10-01. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/smsql.js compares the
-- two.
--
-- WHAT CHANGED
--   `sm_report_create` makes an advertising report with `first_month` false
--   (the user, 2026-10-01: most clients are not new; the team ticks it for a
--   client's true first month). Where the client has an earlier advertising
--   report its period and totals carry forward as before; where it has none,
--   the period before is prefilled (the previous calendar month for a month,
--   else the same length just before) for the team to type its figures. The
--   function is otherwise unchanged.
--
-- ROLLBACK
--   Run the SOCIAL MEDIA ADVERTISING REPORTS section's sm_report_create again.
-- ===========================================================================

create or replace function public.sm_report_create(p_client uuid, p_start date, p_end date, p_kind text default 'social')
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  rid uuid;
  prev uuid;
  pr public.sm_reports;
  totals jsonb := '{}'::jsonb;
  pgroups jsonb;
begin
  if me.id is null or not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if p_client is null or not exists (select 1 from public.clients where id = p_client) then
    return jsonb_build_object('error', 'not-found');
  end if;
  if p_start is null or p_end is null or p_end < p_start then return jsonb_build_object('error', 'bad-period'); end if;
  if coalesce(p_kind, '') not in ('social', 'ads') then return jsonb_build_object('error', 'bad-kind'); end if;
  select id into rid from public.sm_reports
   where client_id = p_client and kind = p_kind and period_start = p_start and period_end = p_end;
  if rid is not null then return jsonb_build_object('error', 'exists', 'id', rid); end if;
  select id into prev from public.sm_reports
   where client_id = p_client and kind = p_kind and period_start < p_start
   order by period_start desc limit 1;
  perform set_config('adspace.sm_fn', 'on', true);
  if p_kind = 'ads' then
    if prev is not null then
      select * into pr from public.sm_reports where id = prev;
      select coalesce(jsonb_object_agg(g.objective, jsonb_build_object('results',
               coalesce(nullif(pr.ads_totals #>> array['groups', g.objective, 'results'], '')::numeric, g.results),
               'spend', g.spend)), '{}'::jsonb)
        into pgroups
        from (select a.objective, sum(a.results) as results, sum(a.spend) as spend
                from public.sm_report_ads a where a.report_id = prev group by a.objective) g;
      totals := jsonb_strip_nulls(jsonb_build_object(
        'prev_start', pr.period_start, 'prev_end', pr.period_end,
        'prev_reach', nullif(pr.ads_totals ->> 'reach', '')::numeric,
        'prev_impressions', coalesce(nullif(pr.ads_totals ->> 'impressions', '')::numeric,
                                     (select sum(impressions) from public.sm_report_ads where report_id = prev)),
        'prev_spend', coalesce(nullif(pr.ads_totals ->> 'spend', '')::numeric,
                               (select sum(spend) from public.sm_report_ads where report_id = prev)),
        'prev_groups', pgroups));
    else
      -- No earlier report here: most clients advertised before the portal, so
      -- the period before is prefilled for the team to type its figures.
      if date_trunc('month', p_start)::date = p_start and (p_start + interval '1 month' - interval '1 day')::date = p_end then
        totals := jsonb_build_object('prev_start', (p_start - interval '1 month')::date, 'prev_end', p_start - 1);
      else
        totals := jsonb_build_object('prev_start', p_start - (p_end - p_start + 1), 'prev_end', p_start - 1);
      end if;
    end if;
    insert into public.sm_reports (client_id, kind, title, period_start, period_end, created_by, first_month, ads_totals)
    values (p_client, p_kind, 'Social Media Advertising Report', p_start, p_end, me.id, false, totals)
    returning id into rid;
  else
    insert into public.sm_reports (client_id, kind, period_start, period_end, created_by)
    values (p_client, p_kind, p_start, p_end, me.id) returning id into rid;
    if prev is not null then
      insert into public.sm_report_platforms (report_id, platform, account_name, handle, group_key, group_label,
        position, metrics, followers_start, er_basis, metric_notes)
      select rid, p.platform, p.account_name, p.handle, p.group_key, p.group_label, p.position, p.metrics,
             coalesce(p.followers_end, case when p.followers_start is not null and p.growth_override is not null
                                            then p.followers_start + p.growth_override end),
             p.er_basis, p.metric_notes
        from public.sm_report_platforms p where p.report_id = prev;
    end if;
  end if;
  perform set_config('adspace.sm_fn', 'off', true);
  perform public.sm_report_log(rid, 'report.created');
  return jsonb_build_object('ok', true, 'id', rid, 'carried', prev is not null);
end $$;
grant execute on function public.sm_report_create(uuid, date, date, text) to authenticated;

-- END OF FIRST MONTH OF ADS UNTICKED -----------------------------------------

-- ===========================================================================
-- TEAM ACCESS EXPIRY — a colleague's access ends on a date unless extended.
-- 2026-10-01. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/levels.js compares the
-- two.
--
-- WHAT CHANGED
--   1. `team_members.access_until`: the last day, in Malaysia, a colleague's
--      access runs; empty for no end. `expired_at` says when it ended.
--   2. Every morning at 00:05 in Malaysia, `team_expire_access()` stands
--      down each active colleague whose day has passed (`active` false, as
--      Set inactive does, so every policy, function and picker that asks
--      for an active colleague refuses them), and files it under Access
--      changed. The last admin with access is never stood down: the console
--      cannot be run without one.
--   3. `team_access_guard`: nobody sets their own date (`own-expiry`), and a
--      date moved to today or later on an expired colleague brings them back
--      at once; Set active on one whose date has passed is refused
--      (`expired-date`) until the date is moved.
--   4. `team_set_expiry(p_until)`: Team at Manage sets one date (or none)
--      for every active colleague but the caller, refusing a past date.
--   5. `my_access_expired()`: whether the signed-in address was stood down
--      by its date, so the console says Access expired, not Access denied.
--
-- ROLLBACK
--   select cron.unschedule('team-access-expiry');
--   drop trigger if exists team_access_guard on public.team_members;
--   drop function if exists public.team_access_guard(), public.team_expire_access(),
--     public.team_set_expiry(date), public.my_access_expired();
--   The two columns may stay; nothing else reads them.
-- ===========================================================================

alter table public.team_members add column if not exists access_until date;
alter table public.team_members add column if not exists expired_at timestamptz;

create or replace function public.team_access_guard()
returns trigger language plpgsql as $$
declare
  who text := lower(coalesce(auth.jwt() ->> 'email', ''));
  today date := (now() at time zone 'Asia/Kuala_Lumpur')::date;
begin
  if new.access_until is distinct from old.access_until and who <> '' and lower(old.email) = who then
    raise exception 'own-expiry' using hint = 'Another admin sets your access date.';
  end if;
  if new.active and not old.active then
    if new.access_until is not null and new.access_until < today then
      raise exception 'expired-date' using hint = 'Move the access date first.';
    end if;
    new.expired_at := null;
  elsif old.expired_at is not null and new.access_until is distinct from old.access_until
        and (new.access_until is null or new.access_until >= today) then
    new.active := true;
    new.expired_at := null;
  end if;
  return new;
end $$;
drop trigger if exists team_access_guard on public.team_members;
create trigger team_access_guard before update on public.team_members
  for each row execute function public.team_access_guard();

create or replace function public.team_expire_access()
returns int language plpgsql security definer set search_path = public as $$
declare
  today date := (now() at time zone 'Asia/Kuala_Lumpur')::date;
  m public.team_members;
  n int := 0;
begin
  for m in select * from public.team_members t
            where t.active and t.access_until is not null and t.access_until < today
            order by t.access_until, t.name loop
    if (m.is_admin or m.role = 'admin') and not exists (
         select 1 from public.team_members o
          where o.id <> m.id and o.active and (o.is_admin or o.role = 'admin')
            and (o.access_until is null or o.access_until >= today)) then
      continue;
    end if;
    update public.team_members set active = false, expired_at = now() where id = m.id;
    insert into public.activity_log (actor, action, subject, detail)
    values ('system', 'team.changed', m.name,
            'Access expired after ' || replace(to_char(m.access_until, 'FMDD Mon YYYY'), ' Sep ', ' Sept '));
    n := n + 1;
  end loop;
  return n;
end $$;
revoke all on function public.team_expire_access() from public, anon, authenticated;

create or replace function public.team_set_expiry(p_until date)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  who text := lower(coalesce(auth.jwt() ->> 'email', ''));
  n int;
begin
  if not public.allowed('team', 'manage') then return jsonb_build_object('error', 'denied'); end if;
  if p_until is not null and p_until < (now() at time zone 'Asia/Kuala_Lumpur')::date then
    return jsonb_build_object('error', 'past-date');
  end if;
  update public.team_members t set access_until = p_until
   where t.active and lower(t.email) <> who and t.access_until is distinct from p_until;
  get diagnostics n = row_count;
  if n > 0 then
    insert into public.activity_log (actor, action, subject, detail)
    values (who, 'team.changed', 'Team',
            'Access until ' || coalesce(replace(to_char(p_until, 'FMDD Mon YYYY'), ' Sep ', ' Sept '), 'not set')
            || ' for ' || n || case when n = 1 then ' colleague' else ' colleagues' end);
  end if;
  return jsonb_build_object('ok', true, 'count', n);
end $$;
grant execute on function public.team_set_expiry(date) to authenticated;

create or replace function public.my_access_expired()
returns boolean language sql security definer stable set search_path = public as $$
  select exists (select 1 from public.team_members t
                  where lower(t.email) = lower(auth.jwt() ->> 'email')
                    and not t.active and t.expired_at is not null)
$$;
grant execute on function public.my_access_expired() to authenticated;

/* Every morning at 00:05 in Malaysia (16:05 UTC). */
do $$
begin
  if not exists (select 1 from pg_extension where extname = 'pg_cron') then
    raise notice 'team-access-expiry: pg_cron is not installed, so no schedule was written.';
    return;
  end if;
  perform cron.unschedule(j.jobid) from cron.job j where j.jobname = 'team-access-expiry';
  perform cron.schedule('team-access-expiry', '5 16 * * *', 'select public.team_expire_access()');
end $$;

-- END OF TEAM ACCESS EXPIRY ---------------------------------------------------

-- ===========================================================================
-- ACTIVITY REPORTS TAB — a report's steps are filed under Reports, its own
-- tab in the Activity record.
-- 2026-10-01. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner, and the function in THE
-- ACTIVITY RECORD, SECTION BY SECTION; tests/sql.js compares them.
--
-- WHAT CHANGED
--   `activity_section()` files the eight steps of a report (started,
--   submitted, returned, confirmed, published, revised, unpublished,
--   deleted) under `reports` instead of `clients`, so the read policy asks
--   `activity.reports`, a part of the Activity record that answers with the
--   record's own level unless set. It also names the three tags the page
--   now files: every save (`report.saved`: the step or sheet and what it
--   held) and every Draft with AI, drafted or failed (`report.ai_drafted`,
--   `report.ai_failed`).
--
-- ROLLBACK
--   Re-run activity_section from 2026-10-01-review-confirm-internally.sql.
-- ===========================================================================

create or replace function public.activity_section(p_action text)
returns text
language sql immutable parallel safe as $$
  select case
    when action in ('campaign.bulk', 'campaign.closed', 'campaign.confirmed',
                    'campaign.created', 'campaign.dates', 'campaign.deleted', 'campaign.edited',
                    'campaign.file_added', 'campaign.qc',
                    'campaign.invoice', 'campaign.invoice_file',
                    'campaign.invoice_removed', 'campaign.keyed', 'campaign.locked',
                    'campaign.opened', 'campaign.rate', 'campaign.rated',
                    'campaign.reinstated', 'campaign.replaced', 'campaign.results', 'campaign.review',
                    'campaign.stage', 'campaign.submitted', 'campaign.task_linked',
                    'campaign.task_unlinked', 'campaign.unbooked',
                    'campaign.unkeyed', 'campaign.withdrawn', 'creator.added',
                    'creator.code', 'creator.links', 'creator.links_restored',
                    'creator.links_self', 'creator.off', 'creator.on', 'creator.removed',
                    'creator.updated') then 'campaigns'
    when action in ('client.action_done', 'client.action_reopened', 'client.added',
                    'client.billing', 'client.brand', 'client.deleted', 'client.edited',
                    'client.review_on', 'client.service', 'client.service_changed',
                    'client.service_removed', 'client.stage', 'client.touch',
                    'client.touch_edited', 'client.touch_removed',
                    'client.touch_restored', 'contact.added', 'contact.deleted',
                    'contact.edited', 'contact.portal_invite', 'contact.portal_off',
                    'contact.portal_on', 'contact.primary', 'contact.removed',
                    'contact.restored',
                    'request.changed', 'request.raised',
                    'request.reinstated', 'request.replied', 'request.withdrawn',
                    'service.override') then 'clients'
    when action in ('report.ai_drafted', 'report.ai_failed', 'report.confirmed',
                    'report.created', 'report.deleted', 'report.published',
                    'report.returned', 'report.revised', 'report.saved',
                    'report.submitted', 'report.unpublished') then 'reports'
    when action in ('qr.created', 'qr.restored', 'qr.revoked', 'shortlink.created',
                    'shortlink.deleted', 'shortlink.imported', 'shortlink.updated') then 'links'
    when action in ('ops.deleted', 'ops.month_deleted', 'ops.numbering') then 'ops'
    when action in ('document.deleted', 'document.issued', 'document.reissued',
                    'document.restored', 'document.signed', 'document.superseded',
                    'document.unsigned', 'document.verified', 'document.voided',
                    'register.added', 'register.edited') then 'register'
    when action in ('client.drive', 'client.handles', 'client.profile',
                    'client.removed', 'drive.imported', 'link.reset', 'post.added',
                    'post.deleted', 'post.edited', 'reapproval.requested',
                    'review.approved', 'review.changes', 'review.removed',
                    'review.unconfirmed',
                    'set.created', 'set.deleted', 'set.published', 'set.renamed',
                    'set.task_linked', 'set.task_unlinked',
                    'set.withdrawn') then 'review'
    when action in ('service.added', 'service.changed', 'service.deleted',
                    'service.off', 'service.on') then 'services'
    when action in ('team.added', 'team.changed', 'team.edited', 'team.group_added',
                    'team.group_changed', 'team.group_removed', 'team.invited') then 'team'
    else 'other'
  end
  from (select p_action as action) t
$$;
grant execute on function public.activity_section(text) to authenticated;

-- END OF ACTIVITY REPORTS TAB ---------------------------------------------------

-- ===========================================================================
-- DRAFT WITH AI LEFT — how many drafts a colleague has left on a report,
-- shown beside Draft with AI.
-- 2026-10-01. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/smsql.js compares the
-- two.
--
-- WHAT CHANGED
--   `ai_draft_left(p_report)`: Reports at Work. Reads `ai_drafts` as
--   `ai_draft_claim` counts it, writing nothing: what is left on the
--   report (one draft, else none for a colleague who is not an admin; five
--   in 24 hours for an admin), for the colleague (twenty in 24 hours) and
--   for the team (sixty in 24 hours), the least of the three as `left`, the
--   scope that sets it and its limit, and, where nothing is left, when the
--   next draft is free. A failed press is not counted.
--
-- ROLLBACK
--   drop function if exists public.ai_draft_left(uuid);
-- ===========================================================================

create or replace function public.ai_draft_left(p_report uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  m public.team_members;
  since timestamptz := now() - interval '24 hours';
  is_adm boolean;
  n_report integer; n_member integer; n_team integer;
  at_report timestamptz; at_member timestamptz; at_team timestamptz;
  l_report integer; l_member integer; l_team integer; l_min integer;
  v_scope text;
begin
  if not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'denied'); end if;
  is_adm := coalesce(m.is_admin, false);
  select count(*), min(d.created_at) into n_report, at_report from public.ai_drafts d
   where d.report_id = p_report and d.created_at > since and d.outcome <> 'failed';
  if is_adm then
    l_report := greatest(0, 5 - n_report);
  elsif exists (select 1 from public.ai_drafts d where d.report_id = p_report and d.outcome <> 'failed') then
    l_report := 0;
  else
    l_report := 1;
  end if;
  select count(*), min(d.created_at) into n_member, at_member from public.ai_drafts d
   where d.team_member_id = m.id and d.created_at > since and d.outcome <> 'failed';
  l_member := greatest(0, 20 - n_member);
  select count(*), min(d.created_at) into n_team, at_team from public.ai_drafts d
   where d.created_at > since and d.outcome <> 'failed';
  l_team := greatest(0, 60 - n_team);
  l_min := least(l_report, l_member, l_team);
  v_scope := case when l_min = l_report then case when is_adm then 'report' else 'redraft' end
                  when l_min = l_member then 'person' else 'team' end;
  return jsonb_build_object(
    'left', l_min, 'scope', v_scope,
    'limit', case v_scope when 'redraft' then 1 when 'report' then 5 when 'person' then 20 else 60 end,
    'report', l_report, 'person', l_member, 'team', l_team, 'admin', is_adm,
    'next', case when l_min > 0 or v_scope = 'redraft' then null
                 when v_scope = 'report' then at_report + interval '24 hours'
                 when v_scope = 'person' then at_member + interval '24 hours'
                 else at_team + interval '24 hours' end);
end $$;

revoke all on function public.ai_draft_left(uuid) from public, anon, authenticated;
grant execute on function public.ai_draft_left(uuid) to authenticated;

-- END OF DRAFT WITH AI LEFT --------------------------------------------------

-- ===========================================================================
-- HANDBOOK — the company's internal files (the Employee Handbook, SOPs,
-- policies, templates and forms) in one console section, kept private and
-- opened through a link that lasts 60 seconds.
-- 2026-10-01. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner, and activity_section() in
-- THE ACTIVITY RECORD, SECTION BY SECTION; tests/sql.js compares
-- them.
--
-- WHAT CHANGED
--   1. `handbook_docs` (a title, a category, a summary, an outside link or
--      none, the current version, archived or not) and `handbook_versions`
--      (each file kept: its private path, name, size, type, what changed,
--      who and when). Every colleague on the team reads both (`is_team()`);
--      nothing writes them but the four functions below.
--   2. `handbook_save`, `handbook_add_version`, `handbook_archive`,
--      `handbook_delete`: admins only (`allowed('admin')`), each filed
--      under Handbook in the Activity record. A file is never overwritten:
--      a new version is a new row and a new object, and every earlier one
--      stays readable. Delete takes the title typed back and answers the
--      paths of the files it removed, which the page then takes out of
--      storage.
--   3. Storage, where the project has it: the private bucket `handbook`
--      (50 MB a file, never public). Every colleague reads an object, which
--      the page does only through a signed link of 60 seconds; only an
--      admin adds or removes one. Nothing in the bucket is served by the
--      CDN.
--   4. `activity_section()` files `handbook.*` under Handbook, a part of
--      the Activity record that answers with the record's level unless set.
--
-- ROLLBACK
--   drop function if exists public.handbook_delete(uuid, text),
--     public.handbook_archive(uuid, boolean),
--     public.handbook_add_version(uuid, text, text, bigint, text, text),
--     public.handbook_save(uuid, text, text, text, text);
--   drop table if exists public.handbook_versions, public.handbook_docs;
--   Storage: drop the three policies `handbook_files_*` on storage.objects
--   and empty and delete the bucket in the dashboard. Re-run activity_section
--   from 2026-10-01-activity-reports-tab.sql.
-- ===========================================================================

create table if not exists public.handbook_docs (
  id              uuid primary key default gen_random_uuid(),
  title           text not null,
  category        text not null default 'handbook',
  summary         text,
  link_url        text,
  current_version integer not null default 0,
  archived_at     timestamptz,
  created_at      timestamptz not null default now(),
  created_by      text,
  updated_at      timestamptz not null default now(),
  constraint handbook_docs_category check (category in ('handbook', 'sop', 'policy', 'template', 'other')),
  constraint handbook_docs_link check (link_url is null or link_url ~ '^https://')
);
create table if not exists public.handbook_versions (
  id          uuid primary key default gen_random_uuid(),
  doc_id      uuid not null references public.handbook_docs(id) on delete cascade,
  version_no  integer not null,
  file_path   text not null,
  file_name   text not null,
  file_size   bigint,
  mime        text,
  note        text,
  created_at  timestamptz not null default now(),
  created_by  text,
  unique (doc_id, version_no)
);
create index if not exists handbook_versions_doc_idx on public.handbook_versions (doc_id, version_no desc);

alter table public.handbook_docs enable row level security;
alter table public.handbook_versions enable row level security;
revoke all on public.handbook_docs from anon;
revoke all on public.handbook_versions from anon;
drop policy if exists handbook_docs_read on public.handbook_docs;
create policy handbook_docs_read on public.handbook_docs for select to authenticated using (public.is_team());
drop policy if exists handbook_versions_read on public.handbook_versions;
create policy handbook_versions_read on public.handbook_versions for select to authenticated using (public.is_team());

create or replace function public.handbook_save(p_id uuid, p_title text, p_category text, p_summary text, p_link text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  who text := lower(coalesce(auth.jwt() ->> 'email', ''));
  v_title text := btrim(coalesce(p_title, ''));
  v_link text := nullif(btrim(coalesce(p_link, '')), '');
  v_changed text;
  d public.handbook_docs;
begin
  if not public.allowed('admin') then return jsonb_build_object('error', 'denied'); end if;
  if v_title = '' then return jsonb_build_object('error', 'no-title'); end if;
  if coalesce(p_category, '') not in ('handbook', 'sop', 'policy', 'template', 'other') then
    return jsonb_build_object('error', 'bad-category');
  end if;
  if v_link is not null and v_link !~ '^https://' then return jsonb_build_object('error', 'bad-link'); end if;
  select * into d from public.handbook_docs h where h.id = p_id;
  if d.id is null then
    insert into public.handbook_docs (id, title, category, summary, link_url, created_by)
    values (coalesce(p_id, gen_random_uuid()), v_title, p_category, nullif(btrim(coalesce(p_summary, '')), ''), v_link, who)
    returning * into d;
    insert into public.activity_log (actor, action, subject, detail)
    values (who, 'handbook.added', d.title, case d.category when 'handbook' then 'Employee Handbook'
      when 'sop' then 'SOPs' when 'policy' then 'Policies' when 'template' then 'Templates and forms' else 'Other' end);
  else
    v_changed := concat_ws(', ',
      case when d.title is distinct from v_title then 'title' end,
      case when d.category is distinct from p_category then 'category' end,
      case when d.summary is distinct from nullif(btrim(coalesce(p_summary, '')), '') then 'summary' end,
      case when d.link_url is distinct from v_link then 'link' end);
    if v_changed = '' then return jsonb_build_object('ok', true, 'id', d.id, 'changed', false); end if;
    update public.handbook_docs h
       set title = v_title, category = p_category,
           summary = nullif(btrim(coalesce(p_summary, '')), ''), link_url = v_link, updated_at = now()
     where h.id = p_id returning * into d;
    insert into public.activity_log (actor, action, subject, detail)
    values (who, 'handbook.edited', d.title, upper(left(v_changed, 1)) || substr(v_changed, 2));
  end if;
  return jsonb_build_object('ok', true, 'id', d.id);
end $$;

create or replace function public.handbook_add_version(p_doc uuid, p_path text, p_name text, p_size bigint, p_mime text, p_note text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  who text := lower(coalesce(auth.jwt() ->> 'email', ''));
  d public.handbook_docs;
  n integer;
begin
  if not public.allowed('admin') then return jsonb_build_object('error', 'denied'); end if;
  select * into d from public.handbook_docs h where h.id = p_doc for update;
  if d.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if coalesce(p_path, '') = '' or position(p_doc::text || '/' in p_path) <> 1 then
    return jsonb_build_object('error', 'bad-path');
  end if;
  if btrim(coalesce(p_name, '')) = '' then return jsonb_build_object('error', 'no-file'); end if;
  select coalesce(max(v.version_no), 0) + 1 into n from public.handbook_versions v where v.doc_id = p_doc;
  insert into public.handbook_versions (doc_id, version_no, file_path, file_name, file_size, mime, note, created_by)
  values (p_doc, n, p_path, btrim(p_name), p_size, p_mime, nullif(btrim(coalesce(p_note, '')), ''), who);
  update public.handbook_docs h set current_version = n, updated_at = now() where h.id = p_doc;
  insert into public.activity_log (actor, action, subject, detail)
  values (who, 'handbook.version', d.title,
          concat_ws(' · ', 'Version ' || n, btrim(p_name), nullif(btrim(coalesce(p_note, '')), '')));
  return jsonb_build_object('ok', true, 'version', n);
end $$;

create or replace function public.handbook_archive(p_id uuid, p_on boolean)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  who text := lower(coalesce(auth.jwt() ->> 'email', ''));
  d public.handbook_docs;
begin
  if not public.allowed('admin') then return jsonb_build_object('error', 'denied'); end if;
  update public.handbook_docs h
     set archived_at = case when p_on then coalesce(h.archived_at, now()) end
   where h.id = p_id returning * into d;
  if d.id is null then return jsonb_build_object('error', 'not-found'); end if;
  insert into public.activity_log (actor, action, subject, detail)
  values (who, case when p_on then 'handbook.archived' else 'handbook.restored' end, d.title, null);
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.handbook_delete(p_id uuid, p_title text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  who text := lower(coalesce(auth.jwt() ->> 'email', ''));
  d public.handbook_docs;
  v_paths jsonb;
begin
  if not public.allowed('admin') then return jsonb_build_object('error', 'denied'); end if;
  select * into d from public.handbook_docs h where h.id = p_id;
  if d.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if lower(btrim(coalesce(p_title, ''))) <> lower(btrim(d.title)) then
    return jsonb_build_object('error', 'mismatch');
  end if;
  select coalesce(jsonb_agg(v.file_path order by v.version_no), '[]'::jsonb) into v_paths
    from public.handbook_versions v where v.doc_id = p_id;
  delete from public.handbook_docs h where h.id = p_id;
  insert into public.activity_log (actor, action, subject, detail)
  values (who, 'handbook.deleted', d.title,
          jsonb_array_length(v_paths) || case when jsonb_array_length(v_paths) = 1 then ' version' else ' versions' end);
  return jsonb_build_object('ok', true, 'paths', v_paths);
end $$;

revoke all on function public.handbook_save(uuid, text, text, text, text) from public, anon;
revoke all on function public.handbook_add_version(uuid, text, text, bigint, text, text) from public, anon;
revoke all on function public.handbook_archive(uuid, boolean) from public, anon;
revoke all on function public.handbook_delete(uuid, text) from public, anon;
grant execute on function public.handbook_save(uuid, text, text, text, text) to authenticated;
grant execute on function public.handbook_add_version(uuid, text, text, bigint, text, text) to authenticated;
grant execute on function public.handbook_archive(uuid, boolean) to authenticated;
grant execute on function public.handbook_delete(uuid, text) to authenticated;

/* The private bucket and who may touch it, where the project has storage. */
do $$
begin
  if not exists (select 1 from pg_namespace where nspname = 'storage') then
    raise notice 'handbook: no storage schema here, so no bucket or policy was written.';
    return;
  end if;
  insert into storage.buckets (id, name, public, file_size_limit)
  values ('handbook', 'handbook', false, 52428800)
  on conflict (id) do update set public = false, file_size_limit = 52428800;
  execute 'drop policy if exists handbook_files_read on storage.objects';
  execute $p$create policy handbook_files_read on storage.objects for select to authenticated
    using (bucket_id = 'handbook' and public.is_team())$p$;
  execute 'drop policy if exists handbook_files_add on storage.objects';
  execute $p$create policy handbook_files_add on storage.objects for insert to authenticated
    with check (bucket_id = 'handbook' and public.allowed('admin'))$p$;
  execute 'drop policy if exists handbook_files_remove on storage.objects';
  execute $p$create policy handbook_files_remove on storage.objects for delete to authenticated
    using (bucket_id = 'handbook' and public.allowed('admin'))$p$;
end $$;

create or replace function public.activity_section(p_action text)
returns text
language sql immutable parallel safe as $$
  select case
    when action in ('campaign.bulk', 'campaign.closed', 'campaign.confirmed',
                    'campaign.created', 'campaign.dates', 'campaign.deleted', 'campaign.edited',
                    'campaign.file_added', 'campaign.qc',
                    'campaign.invoice', 'campaign.invoice_file',
                    'campaign.invoice_removed', 'campaign.keyed', 'campaign.locked',
                    'campaign.opened', 'campaign.rate', 'campaign.rated',
                    'campaign.reinstated', 'campaign.replaced', 'campaign.results', 'campaign.review',
                    'campaign.stage', 'campaign.submitted', 'campaign.task_linked',
                    'campaign.task_unlinked', 'campaign.unbooked',
                    'campaign.unkeyed', 'campaign.withdrawn', 'creator.added',
                    'creator.code', 'creator.links', 'creator.links_restored',
                    'creator.links_self', 'creator.off', 'creator.on', 'creator.removed',
                    'creator.updated') then 'campaigns'
    when action in ('client.action_done', 'client.action_reopened', 'client.added',
                    'client.billing', 'client.brand', 'client.deleted', 'client.edited',
                    'client.review_on', 'client.service', 'client.service_changed',
                    'client.service_removed', 'client.stage', 'client.touch',
                    'client.touch_edited', 'client.touch_removed',
                    'client.touch_restored', 'contact.added', 'contact.deleted',
                    'contact.edited', 'contact.portal_invite', 'contact.portal_off',
                    'contact.portal_on', 'contact.primary', 'contact.removed',
                    'contact.restored',
                    'request.changed', 'request.raised',
                    'request.reinstated', 'request.replied', 'request.withdrawn',
                    'service.override') then 'clients'
    when action in ('report.ai_drafted', 'report.ai_failed', 'report.confirmed',
                    'report.created', 'report.deleted', 'report.published',
                    'report.returned', 'report.revised', 'report.saved',
                    'report.submitted', 'report.unpublished') then 'reports'
    when action in ('qr.created', 'qr.restored', 'qr.revoked', 'shortlink.created',
                    'shortlink.deleted', 'shortlink.imported', 'shortlink.updated') then 'links'
    when action in ('ops.deleted', 'ops.month_deleted', 'ops.numbering') then 'ops'
    when action in ('document.deleted', 'document.issued', 'document.reissued',
                    'document.restored', 'document.signed', 'document.superseded',
                    'document.unsigned', 'document.verified', 'document.voided',
                    'register.added', 'register.edited') then 'register'
    when action in ('client.drive', 'client.handles', 'client.profile',
                    'client.removed', 'drive.imported', 'link.reset', 'post.added',
                    'post.deleted', 'post.edited', 'reapproval.requested',
                    'review.approved', 'review.changes', 'review.removed',
                    'review.unconfirmed',
                    'set.created', 'set.deleted', 'set.published', 'set.renamed',
                    'set.task_linked', 'set.task_unlinked',
                    'set.withdrawn') then 'review'
    when action in ('handbook.added', 'handbook.archived', 'handbook.deleted',
                    'handbook.edited', 'handbook.restored', 'handbook.version') then 'handbook'
    when action in ('service.added', 'service.changed', 'service.deleted',
                    'service.off', 'service.on') then 'services'
    when action in ('team.added', 'team.changed', 'team.edited', 'team.group_added',
                    'team.group_changed', 'team.group_removed', 'team.invited') then 'team'
    else 'other'
  end
  from (select p_action as action) t
$$;
grant execute on function public.activity_section(text) to authenticated;

-- END OF HANDBOOK -----------------------------------------------------------

-- ===========================================================================
-- REPORT ADMIN CONFIRM — an admin may confirm a report they submitted.
-- 2026-10-02. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/smsql.js compares the
-- two.
--
-- WHAT CHANGED
--   `sm_report_confirm(p_id)`: a manager still never confirms their own
--   report (`self-confirm`), but an admin (`team_members.is_admin`, or the
--   older `role = 'admin'`) may: the team's hierarchy ends with them, and a
--   report waiting on nobody else is otherwise stuck (the user, 2026-10-02).
--   The page asks first and the activity record files it under their name.
--
-- ROLLBACK
--   Re-run sm_report_confirm from 2026-09-25-report-builder.sql.
-- ===========================================================================

create or replace function public.sm_report_confirm(p_id uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.sm_reports;
begin
  if me.id is null or not public.allowed('reports', 'manage') then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_id for update;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if r.status <> 'review' then return jsonb_build_object('error', 'not-in-review', 'status', r.status); end if;
  if r.submitted_by = me.id and not (coalesce(me.is_admin, false) or me.role = 'admin') then
    return jsonb_build_object('error', 'self-confirm');
  end if;
  perform set_config('adspace.sm_fn', 'on', true);
  update public.sm_reports set status = 'confirmed', confirmed_by = me.id, confirmed_at = now() where id = p_id;
  perform set_config('adspace.sm_fn', 'off', true);
  perform public.sm_report_log(p_id, 'report.confirmed');
  return jsonb_build_object('ok', true, 'status', 'confirmed');
end $$;
grant execute on function public.sm_report_confirm(uuid) to authenticated;

-- END OF REPORT ADMIN CONFIRM -------------------------------------------------

-- ===========================================================================
-- TEAM NAMECARDS — every active colleague has a digital namecard.
-- 2026-10-03. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/levels.js compares the
-- two.
--
-- WHAT CHANGED
--   1. `team_members.mobile` (as typed; the card formats it), `card_email`
--      (the address the card shows; empty shows the sign-in email) and
--      `card_key`: eight characters from the link keys' alphabet, made by
--      trigger on every new row and never changed, so a printed QR keeps
--      working. The card's address is /card/?k={card_key}.
--   2. `namecard_get(p_key)`, granted to anon: an active colleague's name,
--      position, mobile and email for that key, and nothing else (never the
--      Employee ID, group, access or sign-in details where a card email is
--      set). A colleague stood down, or a key nobody holds, answers
--      `not-found`, so the card goes the day their access does.
--   3. `namecard_mine()`: the signed-in colleague's own card, key included.
--      `namecard_save_mine(p_mobile, p_email)`: they correct their own mobile
--      and card email (filed under Team); the Team sheet edits everybody's.
--
-- ROLLBACK
--   drop trigger if exists team_card_key on public.team_members;
--   drop function if exists public.team_card_key(), public.namecard_get(text),
--     public.namecard_mine(), public.namecard_save_mine(text, text);
--   The three columns may stay; nothing else reads them.
-- ===========================================================================

alter table public.team_members add column if not exists mobile text;
alter table public.team_members add column if not exists card_email text;
alter table public.team_members add column if not exists card_key text;
create unique index if not exists team_members_card_key_idx
  on public.team_members(card_key) where card_key is not null;

/* new_link_key() is closed to the browser, so a default calling it would
   refuse the Team sheet's insert; a definer trigger makes the key instead. */
create or replace function public.team_card_key()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  k text;
begin
  if new.card_key is null then
    loop
      k := public.new_link_key();
      exit when not exists (select 1 from public.team_members t where t.card_key = k);
    end loop;
    new.card_key := k;
  end if;
  if tg_op = 'UPDATE' and old.card_key is not null then
    new.card_key := old.card_key;
  end if;
  return new;
end $$;
revoke all on function public.team_card_key() from public, anon, authenticated;
drop trigger if exists team_card_key on public.team_members;
create trigger team_card_key before insert or update on public.team_members
  for each row execute function public.team_card_key();

update public.team_members set card_key = null where card_key is null;

create or replace function public.namecard_get(p_key text)
returns jsonb language sql security definer stable set search_path = public as $$
  select coalesce((
    select jsonb_build_object(
             'name', t.name,
             'designation', t.designation,
             'mobile', nullif(btrim(coalesce(t.mobile, '')), ''),
             'email', coalesce(nullif(btrim(coalesce(t.card_email, '')), ''), t.email))
      from public.team_members t
     where t.card_key = lower(btrim(coalesce(p_key, ''))) and t.active
     limit 1), jsonb_build_object('error', 'not-found'))
$$;
grant execute on function public.namecard_get(text) to anon, authenticated;

create or replace function public.namecard_mine()
returns jsonb language sql security definer stable set search_path = public as $$
  select coalesce((
    select jsonb_build_object(
             'key', t.card_key, 'name', t.name, 'designation', t.designation,
             'mobile', t.mobile, 'card_email', t.card_email, 'email', t.email)
      from public.team_members t
     where lower(t.email) = lower(auth.jwt() ->> 'email') and t.active
     limit 1), jsonb_build_object('error', 'not-team'))
$$;
grant execute on function public.namecard_mine() to authenticated;

create or replace function public.namecard_save_mine(p_mobile text, p_email text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  me_row public.team_members;
  v_mobile text := nullif(btrim(coalesce(p_mobile, '')), '');
  v_email text := lower(nullif(btrim(coalesce(p_email, '')), ''));
  moved text[] := '{}';
begin
  select * into me_row from public.team_members t
   where lower(t.email) = lower(auth.jwt() ->> 'email') and t.active limit 1;
  if me_row.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if v_mobile is not null and length(regexp_replace(v_mobile, '\D', '', 'g')) not between 8 and 15 then
    return jsonb_build_object('error', 'bad-mobile');
  end if;
  if v_email is not null and v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then
    return jsonb_build_object('error', 'bad-email');
  end if;
  if v_mobile is distinct from me_row.mobile then
    moved := moved || ('Mobile: ' || coalesce(me_row.mobile, 'not set') || ' → ' || coalesce(v_mobile, 'not set'));
  end if;
  if v_email is distinct from me_row.card_email then
    moved := moved || ('Email on card: ' || coalesce(me_row.card_email, 'not set') || ' → ' || coalesce(v_email, 'not set'));
  end if;
  if array_length(moved, 1) is null then return jsonb_build_object('ok', true); end if;
  update public.team_members set mobile = v_mobile, card_email = v_email where id = me_row.id;
  insert into public.activity_log (actor, action, subject, detail)
  values (lower(me_row.email), 'team.edited', me_row.name, array_to_string(moved, ' · '));
  return jsonb_build_object('ok', true);
end $$;
grant execute on function public.namecard_save_mine(text, text) to authenticated;

-- END OF TEAM NAMECARDS -------------------------------------------------------

-- ===========================================================================
-- TEAM ACCESS TIME — access may end at a time of day, not only at its end.
-- 2026-10-03. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/levels.js compares the
-- two.
--
-- WHAT CHANGED
--   1. `team_members.access_until_time`: the time in Malaysia on
--      `access_until` that access ends; empty is the end of that day, as
--      before (the user, 2026-10-03: "03/10/2026 6pm or other manual
--      timings"). `team_access_ends(day, time)` is the moment.
--   2. `team_expire_access()` stands down each colleague whose moment has
--      passed, and runs every five minutes instead of once a morning, so a
--      time is kept to within five minutes. The last admin with access is
--      still never stood down.
--   3. `team_access_guard`: a date or time moved past now on an expired
--      colleague brings them back; Set active before that is refused
--      (`expired-date`); nobody sets their own date or time (`own-expiry`).
--   4. `team_set_expiry_at(p_until, p_time)`: Set access expiry for every
--      active colleague but the caller, with an optional time, refusing a
--      moment already past (`past-date`). `team_set_expiry(p_until)` stays
--      and sets the day's end.
--
-- ROLLBACK
--   Re-run the TEAM ACCESS EXPIRY section (2026-10-01-team-access-expiry.sql):
--   it puts back the three functions and the morning schedule. Then
--   drop function if exists public.team_set_expiry_at(date, time),
--     public.team_access_ends(date, time);
--   The column may stay; nothing else reads it.
-- ===========================================================================

alter table public.team_members add column if not exists access_until_time time;

create or replace function public.team_access_ends(p_day date, p_time time)
returns timestamptz language sql stable as $$
  select case when p_day is null then null
              else ((p_day + coalesce(p_time, time '24:00')) at time zone 'Asia/Kuala_Lumpur') end
$$;
/* The guard is an invoker trigger, so a colleague's own update calls it. */
revoke all on function public.team_access_ends(date, time) from public, anon;
grant execute on function public.team_access_ends(date, time) to authenticated;

create or replace function public.team_access_word(p_day date, p_time time)
returns text language sql stable as $$
  select replace(to_char(p_day, 'FMDD Mon YYYY'), ' Sep ', ' Sept ')
         || coalesce(', ' || case when extract(minute from p_time) = 0
                                  then to_char(p_time, 'FMHH12am')
                                  else to_char(p_time, 'FMHH12.MIam') end, '')
$$;
revoke all on function public.team_access_word(date, time) from public, anon, authenticated;

create or replace function public.team_access_guard()
returns trigger language plpgsql as $$
declare
  who text := lower(coalesce(auth.jwt() ->> 'email', ''));
  ends timestamptz := public.team_access_ends(new.access_until, new.access_until_time);
  moved boolean := new.access_until is distinct from old.access_until
                   or new.access_until_time is distinct from old.access_until_time;
begin
  if moved and who <> '' and lower(old.email) = who then
    raise exception 'own-expiry' using hint = 'Another admin sets your access date.';
  end if;
  if new.active and not old.active then
    if ends is not null and ends <= now() then
      raise exception 'expired-date' using hint = 'Move the access date first.';
    end if;
    new.expired_at := null;
  elsif old.expired_at is not null and moved and (ends is null or ends > now()) then
    new.active := true;
    new.expired_at := null;
  end if;
  return new;
end $$;
create or replace trigger team_access_guard before update on public.team_members
  for each row execute function public.team_access_guard();

create or replace function public.team_expire_access()
returns int language plpgsql security definer set search_path = public as $$
declare
  m public.team_members;
  n int := 0;
begin
  for m in select * from public.team_members t
            where t.active and t.access_until is not null
              and public.team_access_ends(t.access_until, t.access_until_time) <= now()
            order by t.access_until, t.access_until_time nulls last, t.name loop
    if (m.is_admin or m.role = 'admin') and not exists (
         select 1 from public.team_members o
          where o.id <> m.id and o.active and (o.is_admin or o.role = 'admin')
            and (o.access_until is null
                 or public.team_access_ends(o.access_until, o.access_until_time) > now())) then
      continue;
    end if;
    update public.team_members set active = false, expired_at = now() where id = m.id;
    insert into public.activity_log (actor, action, subject, detail)
    values ('system', 'team.changed', m.name,
            case when m.access_until_time is null
                 then 'Access expired after ' || public.team_access_word(m.access_until, null)
                 else 'Access expired at ' || public.team_access_word(m.access_until, m.access_until_time) end);
    n := n + 1;
  end loop;
  return n;
end $$;
revoke all on function public.team_expire_access() from public, anon, authenticated;

create or replace function public.team_set_expiry_at(p_until date, p_time time)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  who text := lower(coalesce(auth.jwt() ->> 'email', ''));
  v_time time := case when p_until is null then null else p_time end;
  n int;
begin
  if not public.allowed('team', 'manage') then return jsonb_build_object('error', 'denied'); end if;
  if p_until is not null and public.team_access_ends(p_until, v_time) <= now() then
    return jsonb_build_object('error', 'past-date');
  end if;
  update public.team_members t set access_until = p_until, access_until_time = v_time
   where t.active and lower(t.email) <> who
     and (t.access_until is distinct from p_until or t.access_until_time is distinct from v_time);
  get diagnostics n = row_count;
  if n > 0 then
    insert into public.activity_log (actor, action, subject, detail)
    values (who, 'team.changed', 'Team',
            'Access until ' || coalesce(public.team_access_word(p_until, v_time), 'not set')
            || ' for ' || n || case when n = 1 then ' colleague' else ' colleagues' end);
  end if;
  return jsonb_build_object('ok', true, 'count', n);
end $$;
grant execute on function public.team_set_expiry_at(date, time) to authenticated;

create or replace function public.team_set_expiry(p_until date)
returns jsonb language sql security definer set search_path = public as $$
  select public.team_set_expiry_at(p_until, null)
$$;
grant execute on function public.team_set_expiry(date) to authenticated;

/* Every five minutes, so a time of day is kept to within five minutes. */
do $$
begin
  if not exists (select 1 from pg_extension where extname = 'pg_cron') then
    raise notice 'team-access-expiry: pg_cron is not installed, so no schedule was written.';
    return;
  end if;
  perform cron.unschedule(j.jobid) from cron.job j where j.jobname = 'team-access-expiry';
  perform cron.schedule('team-access-expiry', '*/5 * * * *', 'select public.team_expire_access()');
end $$;

-- END OF TEAM ACCESS TIME -----------------------------------------------------

-- ===========================================================================
-- NAMECARDS FROM THE SIGN-IN — a card shows the email its colleague signs
-- in with.
-- 2026-10-03. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/levels.js compares the
-- two.
--
-- WHAT CHANGED
--   The user, 2026-10-03: "why not just use the login email". Every active
--   colleague keeps a card, interns signing in with a personal address
--   included (the user: "cannot restrict @adspacestudios.com").
--   1. `namecard_get` and `namecard_mine` give the sign-in address as the
--      card's email; `card_email` is no longer read (the column stays,
--      unread).
--   2. `namecard_save_mine` keeps the mobile alone (its email argument is
--      ignored, so the page's call is unchanged).
--   3. `team_members.card_on` (on by default): Team turns a card off and on
--      again from the colleague's row; while off its address answers
--      `not-found`, and the same address works again once it is back on.
--
-- ROLLBACK
--   Re-run the three functions from 2026-10-03-team-namecards.sql. The
--   column may stay; nothing else reads it.
-- ===========================================================================

alter table public.team_members add column if not exists card_on boolean not null default true;

create or replace function public.namecard_get(p_key text)
returns jsonb language sql security definer stable set search_path = public as $$
  select coalesce((
    select jsonb_build_object(
             'name', t.name,
             'designation', t.designation,
             'mobile', nullif(btrim(coalesce(t.mobile, '')), ''),
             'email', lower(t.email))
      from public.team_members t
     where t.card_key = lower(btrim(coalesce(p_key, ''))) and t.active and t.card_on
     limit 1), jsonb_build_object('error', 'not-found'))
$$;
grant execute on function public.namecard_get(text) to anon, authenticated;

create or replace function public.namecard_mine()
returns jsonb language sql security definer stable set search_path = public as $$
  select coalesce((
    select jsonb_build_object('key', t.card_key, 'name', t.name, 'designation', t.designation,
                              'mobile', t.mobile, 'email', lower(t.email), 'on', t.card_on)
      from public.team_members t
     where lower(t.email) = lower(auth.jwt() ->> 'email') and t.active
     limit 1), jsonb_build_object('error', 'not-team'))
$$;
grant execute on function public.namecard_mine() to authenticated;

create or replace function public.namecard_save_mine(p_mobile text, p_email text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  me_row public.team_members;
  v_mobile text := nullif(btrim(coalesce(p_mobile, '')), '');
begin
  select * into me_row from public.team_members t
   where lower(t.email) = lower(auth.jwt() ->> 'email') and t.active limit 1;
  if me_row.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if v_mobile is not null and length(regexp_replace(v_mobile, '\D', '', 'g')) not between 8 and 15 then
    return jsonb_build_object('error', 'bad-mobile');
  end if;
  if v_mobile is not distinct from me_row.mobile then return jsonb_build_object('ok', true); end if;
  update public.team_members set mobile = v_mobile where id = me_row.id;
  insert into public.activity_log (actor, action, subject, detail)
  values (lower(me_row.email), 'team.edited', me_row.name,
          'Mobile: ' || coalesce(me_row.mobile, 'not set') || ' → ' || coalesce(v_mobile, 'not set'));
  return jsonb_build_object('ok', true);
end $$;
grant execute on function public.namecard_save_mine(text, text) to authenticated;

-- END OF NAMECARDS FROM THE SIGN-IN -------------------------------------------

-- ===========================================================================
-- NAMECARD SHORT LINKS — every colleague's card has a short link on the
-- links host.
-- 2026-10-03. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/levels.js compares the
-- two.
--
-- WHAT CHANGED
--   The user, 2026-10-03: a short link for every namecard, made from the
--   name with no space and edited per person, in Team and by the colleague
--   in My namecard.
--   1. `team_members.card_slug`: made from the name as the colleague is
--      added (Xue Yi reads `xueyi`), numbered where taken (`-2`), and never
--      following a rename. Team edits it; an empty value is made again from
--      the name. One slug is never both a card's and a short link's, whichever
--      came first (`slug-taken`).
--   2. `link_resolve` answers a card's slug with the card's own address
--      (`/card/?k=`) while the colleague is active and the card is on, and
--      as missing otherwise, so the Worker needs no change. A short link
--      still wins where both could answer.
--   3. `namecard_mine` adds `slug`, for My namecard to show and copy, and
--      `namecard_save_card(p_mobile, p_slug)` saves the colleague's own
--      mobile and short link (filed `team.edited`, from and to);
--      `namecard_save_mine` stays for a page from before.
--   The QR on the card keeps the card's own address, which never changes,
--   so a printed code survives an edited slug.
--
-- ROLLBACK
--   Re-run link_resolve from the SHORT LINKS section of schema.sql and
--   namecard_mine from NAMECARDS FROM THE SIGN-IN; then remove the triggers
--   links_card_clash and team_card_slug and their functions, and
--   card_slug_base(text), card_slug_free(text, uuid) and
--   namecard_save_card(text, text). The column may stay.
-- ===========================================================================

alter table public.team_members add column if not exists card_slug text;
create unique index if not exists team_members_card_slug_idx
  on public.team_members(card_slug) where card_slug is not null;
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'team_card_slug_shape') then
    alter table public.team_members add constraint team_card_slug_shape
      check (card_slug ~ '^[a-z0-9][a-z0-9._-]{0,79}$');
  end if;
end $$;

/* A name as a slug: lower case letters and digits, no space (the user,
   2026-10-03: Xue Yi reads xueyi). */
create or replace function public.card_slug_base(p_name text)
returns text language sql immutable as $$
  select coalesce(nullif(left(regexp_replace(lower(coalesce(p_name, '')), '[^a-z0-9]+', '', 'g'), 70), ''),
         'card')
$$;
revoke all on function public.card_slug_base(text) from public, anon, authenticated;

/* The base, else the base numbered, free of every short link and every
   other colleague's card. */
create or replace function public.card_slug_free(p_base text, p_self uuid)
returns text language plpgsql security definer stable set search_path = public as $$
declare
  cand text := p_base;
  k int := 1;
begin
  loop
    exit when not exists (select 1 from public.links l where l.slug = cand)
          and not exists (select 1 from public.team_members t
                           where t.card_slug = cand and t.id is distinct from p_self);
    k := k + 1;
    cand := p_base || '-' || k;
  end loop;
  return cand;
end $$;
revoke all on function public.card_slug_free(text, uuid) from public, anon, authenticated;

create or replace function public.team_card_slug()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'UPDATE' and new.card_slug is not distinct from old.card_slug then
    return new;
  end if;
  if new.card_slug is null or btrim(new.card_slug) = '' then
    new.card_slug := public.card_slug_free(public.card_slug_base(new.name), new.id);
    return new;
  end if;
  new.card_slug := lower(btrim(new.card_slug));
  if new.card_slug !~ '^[a-z0-9][a-z0-9._-]{0,79}$' then
    raise exception 'slug-shape' using hint = 'Lowercase letters, digits, dots, dashes or underscores.';
  end if;
  if exists (select 1 from public.links l where l.slug = new.card_slug)
     or exists (select 1 from public.team_members t where t.card_slug = new.card_slug and t.id <> new.id) then
    raise exception 'slug-taken' using errcode = '23505';
  end if;
  return new;
end $$;
revoke all on function public.team_card_slug() from public, anon, authenticated;
create or replace trigger team_card_slug before insert or update on public.team_members
  for each row execute function public.team_card_slug();

create or replace function public.links_card_clash()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if exists (select 1 from public.team_members t where t.card_slug = new.slug) then
    raise exception 'slug-taken' using errcode = '23505';
  end if;
  return new;
end $$;
revoke all on function public.links_card_clash() from public, anon, authenticated;
create or replace trigger links_card_clash before insert or update of slug on public.links
  for each row execute function public.links_card_clash();

/* Everybody already on the list, one at a time so two of one name number
   apart. */
do $$
declare
  r record;
begin
  for r in select t.id from public.team_members t where t.card_slug is null order by t.name, t.id loop
    update public.team_members set card_slug = '' where id = r.id;
  end loop;
end $$;

create or replace function public.link_resolve(p_slug text, p_qr text default null)
returns table (url text, state text)
language plpgsql security definer stable set search_path = public as $$
declare
  v_slug   text := lower(btrim(coalesce(p_slug, '')));
  v_code   text := lower(btrim(coalesce(p_qr, '')));
  v_target text;
  v_live   boolean;
begin
  if v_slug = '' then
    return query select null::text, 'missing'::text;
    return;
  end if;

  select l.target_url, l.active into v_target, v_live
    from public.links l
   where l.slug = v_slug;

  if v_target is null then
    -- A colleague's namecard, while they are active and the card is on.
    select 'https://digital.adspace.me/card/?k=' || t.card_key into v_target
      from public.team_members t
     where t.card_slug = v_slug and t.active and t.card_on and t.card_key is not null;
    if v_target is null then
      return query select null::text, 'missing'::text;
      return;
    end if;
    return query select v_target, 'ok'::text;
    return;
  end if;
  if not v_live then
    return query select null::text, 'paused'::text;
    return;
  end if;

  -- A scan carries its code; a typed link does not, and is never turned away
  -- by one. A code that belongs to another slug is as revoked as a dead one.
  if v_code <> '' and not exists (
       select 1 from public.link_qrs q
        where q.code = v_code and q.slug = v_slug and q.active) then
    return query select null::text, 'revoked'::text;
    return;
  end if;

  return query select v_target, 'ok'::text;
end $$;
revoke all on function public.link_resolve(text, text) from public;
grant execute on function public.link_resolve(text, text) to anon, authenticated;

create or replace function public.namecard_mine()
returns jsonb language sql security definer stable set search_path = public as $$
  select coalesce((
    select jsonb_build_object('key', t.card_key, 'slug', t.card_slug, 'name', t.name,
                              'designation', t.designation, 'mobile', t.mobile,
                              'email', lower(t.email), 'on', t.card_on)
      from public.team_members t
     where lower(t.email) = lower(auth.jwt() ->> 'email') and t.active
     limit 1), jsonb_build_object('error', 'not-team'))
$$;
grant execute on function public.namecard_mine() to authenticated;

/* The colleague's own mobile and short link, from My namecard. An empty
   short link is made again from the name; the trigger refuses a taken or
   badly shaped one, answered here by name. */
create or replace function public.namecard_save_card(p_mobile text, p_slug text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  me_row public.team_members;
  v_mobile text := nullif(btrim(coalesce(p_mobile, '')), '');
  v_slug text := lower(btrim(coalesce(p_slug, '')));
  now_slug text;
  said text := '';
begin
  select * into me_row from public.team_members t
   where lower(t.email) = lower(auth.jwt() ->> 'email') and t.active limit 1;
  if me_row.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if v_mobile is not null and length(regexp_replace(v_mobile, '\D', '', 'g')) not between 8 and 15 then
    return jsonb_build_object('error', 'bad-mobile');
  end if;
  if v_slug <> '' and v_slug !~ '^[a-z0-9][a-z0-9._-]{0,79}$' then
    return jsonb_build_object('error', 'slug-shape');
  end if;
  if v_mobile is not distinct from me_row.mobile and v_slug = coalesce(me_row.card_slug, '') then
    return jsonb_build_object('ok', true, 'slug', me_row.card_slug);
  end if;
  begin
    update public.team_members set mobile = v_mobile, card_slug = nullif(v_slug, '')
     where id = me_row.id
     returning card_slug into now_slug;
  exception when others then
    if sqlerrm in ('slug-taken', 'slug-shape') then return jsonb_build_object('error', sqlerrm); end if;
    raise;
  end;
  if v_mobile is distinct from me_row.mobile then
    said := 'Mobile: ' || coalesce(me_row.mobile, 'not set') || ' → ' || coalesce(v_mobile, 'not set');
  end if;
  if now_slug is distinct from me_row.card_slug then
    said := said || case when said = '' then '' else '; ' end
         || 'Short link: ' || coalesce(me_row.card_slug, 'not set') || ' → ' || coalesce(now_slug, 'not set');
  end if;
  if said <> '' then
    insert into public.activity_log (actor, action, subject, detail)
    values (lower(me_row.email), 'team.edited', me_row.name, said);
  end if;
  return jsonb_build_object('ok', true, 'slug', now_slug);
end $$;
grant execute on function public.namecard_save_card(text, text) to authenticated;

-- END OF NAMECARD SHORT LINKS --------------------------------------------------

-- ===========================================================================
-- NAMECARD MOBILE SWITCH — each colleague shows or hides their mobile on
-- their card.
-- 2026-10-03. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/levels.js compares the
-- two.
--
-- WHAT CHANGED
--   The user, 2026-10-03: one card, one link and one QR; whether the mobile
--   is on it is the colleague's own choice ("mobile numbers is more of
--   personal preference"), turned on and off at will.
--   1. `team_members.card_mobile` (shown by default, as every card was).
--   2. `namecard_get` sends the mobile only while it is shown: hidden, the
--      number never leaves the database, so the card, its WhatsApp button
--      and Save contact all go without it.
--   3. `namecard_mine` adds `show_mobile`; `namecard_save(p_mobile, p_slug,
--      p_show)` saves the colleague's mobile, short link and the switch in
--      one write, filed `team.edited` from and to. `namecard_save_card`
--      stays for a page from before.
--
-- ROLLBACK
--   Re-run namecard_get from NAMECARDS FROM THE SIGN-IN and namecard_mine
--   from NAMECARD SHORT LINKS; then remove namecard_save(text, text,
--   boolean). The column may stay.
-- ===========================================================================

alter table public.team_members add column if not exists card_mobile boolean not null default true;

create or replace function public.namecard_get(p_key text)
returns jsonb language sql security definer stable set search_path = public as $$
  select coalesce((
    select jsonb_build_object(
             'name', t.name,
             'designation', t.designation,
             'mobile', case when t.card_mobile then nullif(btrim(coalesce(t.mobile, '')), '') end,
             'email', lower(t.email))
      from public.team_members t
     where t.card_key = lower(btrim(coalesce(p_key, ''))) and t.active and t.card_on
     limit 1), jsonb_build_object('error', 'not-found'))
$$;
grant execute on function public.namecard_get(text) to anon, authenticated;

create or replace function public.namecard_mine()
returns jsonb language sql security definer stable set search_path = public as $$
  select coalesce((
    select jsonb_build_object('key', t.card_key, 'slug', t.card_slug, 'name', t.name,
                              'designation', t.designation, 'mobile', t.mobile,
                              'email', lower(t.email), 'on', t.card_on,
                              'show_mobile', t.card_mobile)
      from public.team_members t
     where lower(t.email) = lower(auth.jwt() ->> 'email') and t.active
     limit 1), jsonb_build_object('error', 'not-team'))
$$;
grant execute on function public.namecard_mine() to authenticated;

/* The colleague's own mobile, short link and whether the mobile is shown,
   from My namecard, in one write. An empty short link is made again from the
   name; the trigger refuses a taken or badly shaped one, answered here by
   name. A null p_show leaves the switch where it is. */
create or replace function public.namecard_save(p_mobile text, p_slug text, p_show boolean default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  me_row public.team_members;
  v_mobile text := nullif(btrim(coalesce(p_mobile, '')), '');
  v_slug text := lower(btrim(coalesce(p_slug, '')));
  v_show boolean;
  now_slug text;
  said text := '';
begin
  select * into me_row from public.team_members t
   where lower(t.email) = lower(auth.jwt() ->> 'email') and t.active limit 1;
  if me_row.id is null then return jsonb_build_object('error', 'not-team'); end if;
  v_show := coalesce(p_show, me_row.card_mobile);
  if v_mobile is not null and length(regexp_replace(v_mobile, '\D', '', 'g')) not between 8 and 15 then
    return jsonb_build_object('error', 'bad-mobile');
  end if;
  if v_slug <> '' and v_slug !~ '^[a-z0-9][a-z0-9._-]{0,79}$' then
    return jsonb_build_object('error', 'slug-shape');
  end if;
  if v_mobile is not distinct from me_row.mobile and v_slug = coalesce(me_row.card_slug, '')
     and v_show = me_row.card_mobile then
    return jsonb_build_object('ok', true, 'slug', me_row.card_slug, 'show_mobile', me_row.card_mobile);
  end if;
  begin
    update public.team_members set mobile = v_mobile, card_slug = nullif(v_slug, ''), card_mobile = v_show
     where id = me_row.id
     returning card_slug into now_slug;
  exception when others then
    if sqlerrm in ('slug-taken', 'slug-shape') then return jsonb_build_object('error', sqlerrm); end if;
    raise;
  end;
  if v_mobile is distinct from me_row.mobile then
    said := 'Mobile: ' || coalesce(me_row.mobile, 'not set') || ' → ' || coalesce(v_mobile, 'not set');
  end if;
  if v_show <> me_row.card_mobile then
    said := said || case when said = '' then '' else '; ' end || 'Mobile on card: '
         || case when me_row.card_mobile then 'Show' else 'Hide' end || ' → '
         || case when v_show then 'Show' else 'Hide' end;
  end if;
  if now_slug is distinct from me_row.card_slug then
    said := said || case when said = '' then '' else '; ' end
         || 'Short link: ' || coalesce(me_row.card_slug, 'not set') || ' → ' || coalesce(now_slug, 'not set');
  end if;
  if said <> '' then
    insert into public.activity_log (actor, action, subject, detail)
    values (lower(me_row.email), 'team.edited', me_row.name, said);
  end if;
  return jsonb_build_object('ok', true, 'slug', now_slug, 'show_mobile', v_show);
end $$;
grant execute on function public.namecard_save(text, text, boolean) to authenticated;

-- END OF NAMECARD MOBILE SWITCH ------------------------------------------------

-- ===========================================================================
-- CLIENT SCOPE — leads, past clients and a group's own clients, held by the
-- database in every section that hangs off a client.
-- 2026-10-03. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/levels.js compares the
-- two.
--
-- WHAT CHANGED (the user, 2026-10-03: leads and past clients are the
-- managers' and sales' portion; "give option to view or manage or x leads,
-- same goes to past clients"; Own clients only "covers all", an unassigned
-- lead is seen and taken)
--   1. Two parts under Clients, `clients.leads` (Lead, Contacted, Proposal
--      sent) and `clients.past` (Past), each No Access, View or Manage, and
--      Same as section where unset. They narrow and never widen: a lead is
--      read at the lesser of the group's Clients level and its Leads level.
--      The Members group (slug `account`) starts at No Access on both, as the
--      user chose; every other group stays as it was.
--   2. `team_roles.client_scope`, copied to `team_members` with the rest of a
--      group: `all` (as before) or `own`, the clients where the colleague is
--      Person in charge, and any lead nobody is in charge of, to see and take.
--   3. The rule is one function, `client_row_seen(stage, owner, level)`, and
--      the database holds it everywhere a client's work is kept:
--      - a restrictive read policy, `client_scope`, on the client and every
--        table under it (contacts, services, letters, calls, requests,
--        documents, Drive imports, campaigns and their bookings, content
--        sets and posts, reports): a row on a client somebody may not see
--        never arrives;
--      - a guard trigger, `client_scope_guard`, on the same tables, which
--        also catches the security definer functions that write them: a
--        write needs Manage on the client's band (`client-scope`, in the
--        team's words);
--      - My Work through its two helpers: `ops_may_see_task` keeps a
--        colleague's own tasks and gives the whole queue (`ops.all`) only
--        the clients they may see, `ops_may_see_engagement` the same for
--        months, `ops_scope_error` refuses a task on a client out of reach,
--        and `ops_report` counts and names only those tasks;
--      - the functions that read past the policies: `client_billing`,
--        `sm_client_reports`, `sm_report_file`, `sm_report_snapshot`.
--   4. Person in charge changes from one colleague to another only at
--      Clients Full Access, or at Team Full Access for a stand-down or a
--      rename (`owner-change`); taking a lead nobody is in charge of needs
--      Leads at Manage.
--   Not covered: the Activity record keeps one log for every client (its
--   tabs are their own parts), and a client's own pages read through their
--   token functions as before.
--
-- ROLLBACK
--   For each table in the list below:
--     drop policy if exists client_scope on public.<table>;
--     drop trigger if exists client_scope_guard on public.<table>;
--   Then re-run ops_may_see_task, ops_may_see_engagement, ops_scope_error,
--   ops_report, client_billing, sm_client_reports, sm_report_file,
--   sm_report_snapshot and team_role_defaults from their own sections, and
--   remove the functions client_row_seen(text, text, text),
--   client_seen(uuid, text), client_of(text, uuid),
--   client_scope_free(text), client_scope_ok(text, uuid, text),
--   client_scope_guard() and ops_task_in_scope(uuid). The columns may stay;
--   take `clients.leads` and `clients.past` out of a group's access in Team.
-- ===========================================================================

alter table public.team_roles add column if not exists client_scope text not null default 'all';
alter table public.team_members add column if not exists client_scope text not null default 'all';
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'team_roles_client_scope') then
    alter table public.team_roles add constraint team_roles_client_scope check (client_scope in ('all', 'own'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'team_members_client_scope') then
    alter table public.team_members add constraint team_members_client_scope check (client_scope in ('all', 'own'));
  end if;
end $$;

-- A member carries their group's switches, its scope among them.
create or replace function public.team_role_defaults()
returns trigger language plpgsql as $$
declare r public.team_roles;
begin
  select * into r from public.team_roles where slug = new.role;
  if r.slug is null then
    select * into r from public.team_roles where slug = 'account';
    new.role := 'account';
  end if;
  new.is_admin      := r.is_admin;
  new.can_clients   := r.can_clients;   new.can_review   := r.can_review;
  new.can_campaigns := r.can_campaigns; new.can_links    := r.can_links;
  new.can_activity  := r.can_activity;  new.can_billing  := r.can_billing;
  new.can_remove    := r.can_remove;    new.can_doc_void := r.can_doc_void;
  new.access        := coalesce(r.access, '{}'::jsonb);
  new.client_scope  := coalesce(r.client_scope, 'all');
  new.updated_at    := now();
  return new;
end $$;

/* The one rule. A client in the lead stages answers to `clients.leads`, a
   past client to `clients.past`, each falling back to the Clients level
   where unset; an active or paused client answers to the section asking.
   Own clients only keeps the clients the colleague is Person in charge of,
   and a lead nobody is in charge of. Somebody who is not on the team is
   left to the other policies, so a client's own pages are untouched. */
create or replace function public.client_row_seen(p_stage text, p_owner text, p_level text)
returns boolean language plpgsql security definer stable set search_path = public as $$
declare
  t public.team_members;
  band text;
begin
  select * into t from public.team_members
   where lower(email) = lower(auth.jwt() ->> 'email') and active limit 1;
  if t.id is null or t.is_admin or t.role = 'admin' then return true; end if;
  band := case when p_stage in ('lead', 'contacted', 'proposal') then 'clients.leads'
               when p_stage = 'past' then 'clients.past' end;
  if band is not null and public.level_rank(coalesce(t.access ->> band, t.access ->> 'clients'))
                          < public.level_rank(p_level) then
    return false;
  end if;
  if coalesce(t.client_scope, 'all') = 'own' then
    if nullif(btrim(coalesce(p_owner, '')), '') is null then
      return coalesce(band = 'clients.leads', false);
    end if;
    return lower(btrim(p_owner)) = lower(btrim(coalesce(t.name, '')));
  end if;
  return true;
end $$;
revoke all on function public.client_row_seen(text, text, text) from public, anon, authenticated;

-- A client by its id; no client (internal work) and a client gone are
-- left to the other policies.
create or replace function public.client_seen(p_client uuid, p_level text default 'view')
returns boolean language plpgsql security definer stable set search_path = public as $$
declare
  st text;
  ow text;
begin
  if p_client is null then return true; end if;
  select c.stage, c.owner into st, ow from public.clients c where c.id = p_client;
  if not found then return true; end if;
  return public.client_row_seen(st, ow, p_level);
end $$;
revoke all on function public.client_seen(uuid, text) from public, anon, authenticated;

-- The client a row hangs off, read past the policies.
create or replace function public.client_of(p_kind text, p_id uuid)
returns uuid language sql security definer stable set search_path = public as $$
  select case p_kind
    when 'client' then p_id
    when 'campaign' then (select c.client_id from public.campaigns c where c.id = p_id)
    when 'option' then (select c.client_id from public.campaign_options o
                          join public.campaigns c on c.id = o.campaign_id where o.id = p_id)
    when 'batch' then (select b.client_id from public.batches b where b.id = p_id)
    when 'post' then (select b.client_id from public.posts p
                        join public.batches b on b.id = p.batch_id where p.id = p_id)
    when 'report' then (select r.client_id from public.sm_reports r where r.id = p_id)
  end
$$;
revoke all on function public.client_of(text, uuid) from public, anon, authenticated;

/* True where the rule cannot hide anything from the caller at this level:
   not on the team, an admin, or every client at the level with both bands
   reaching it. A policy asks it once a statement (`(select …)`), so the
   ordinary group pays nothing a row. */
create or replace function public.client_scope_free(p_level text default 'view')
returns boolean language plpgsql security definer stable set search_path = public as $$
declare t public.team_members;
begin
  select * into t from public.team_members
   where lower(email) = lower(auth.jwt() ->> 'email') and active limit 1;
  if t.id is null or t.is_admin or t.role = 'admin' then return true; end if;
  if coalesce(t.client_scope, 'all') = 'own' then return false; end if;
  return public.level_rank(coalesce(t.access ->> 'clients.leads', t.access ->> 'clients')) >= public.level_rank(p_level)
     and public.level_rank(coalesce(t.access ->> 'clients.past', t.access ->> 'clients')) >= public.level_rank(p_level);
end $$;
revoke all on function public.client_scope_free(text) from public, anon;
grant execute on function public.client_scope_free(text) to authenticated;

-- The rule for one row, by what it hangs off. Answers a boolean only.
create or replace function public.client_scope_ok(p_kind text, p_id uuid, p_level text default 'view')
returns boolean language sql security definer stable set search_path = public as $$
  select public.client_seen(public.client_of(p_kind, p_id), p_level)
$$;
revoke all on function public.client_scope_ok(text, uuid, text) from public, anon;
grant execute on function public.client_scope_ok(text, uuid, text) to authenticated;

/* Every write, whoever makes it (a page or a security definer function):
   the row before and the row after must both be the caller's at Manage.
   A write made by another trigger (a cascade, a stamp) was already asked.
   A removal is not guarded here: a browser's reaches only rows its read
   policy shows (PostgREST names the row it removes), and the functions that
   remove ask their own permission first. */
create or replace function public.client_scope_guard()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  kind text := tg_argv[0];
  col  text := tg_argv[1];
  o jsonb;
  n jsonb := to_jsonb(new);
begin
  if pg_trigger_depth() > 1 or public.client_scope_free('work') then return new; end if;
  if tg_op = 'UPDATE' then
    o := to_jsonb(old);
    if (kind = 'self' and not public.client_row_seen(o ->> 'stage', o ->> 'owner', 'work'))
       or (kind <> 'self' and not public.client_scope_ok(kind, (o ->> col)::uuid, 'work')) then
      raise exception 'This client is outside your access.' using errcode = '42501', hint = 'client-scope';
    end if;
  end if;
  if (kind = 'self' and not public.client_row_seen(n ->> 'stage', n ->> 'owner', 'work'))
     or (kind <> 'self' and not public.client_scope_ok(kind, (n ->> col)::uuid, 'work')) then
    raise exception 'This client is outside your access.' using errcode = '42501', hint = 'client-scope';
  end if;
  return new;
end $$;
revoke all on function public.client_scope_guard() from public, anon, authenticated;

/* Person in charge moves from one colleague to another at Clients Full
   Access, or at Team Full Access, which stands a colleague down and renames
   them and carries both onto their clients; a lead nobody holds is taken at
   Leads Manage, which the guard above has already asked. */
create or replace function public.clients_owner_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if pg_trigger_depth() > 1 then return new; end if;
  if nullif(btrim(coalesce(old.owner, '')), '') is not null
     and coalesce(btrim(new.owner), '') is distinct from btrim(old.owner)
     and (select t.id from public.team_members t
           where lower(t.email) = lower(auth.jwt() ->> 'email') and t.active limit 1) is not null
     and not public.allowed('clients', 'manage') and not public.allowed('team', 'manage') then
    raise exception 'Person in charge is changed at Clients Full Access.' using errcode = '42501', hint = 'owner-change';
  end if;
  return new;
end $$;
revoke all on function public.clients_owner_guard() from public, anon, authenticated;
create or replace trigger clients_owner_guard before update of owner on public.clients
  for each row execute function public.clients_owner_guard();

/* The tables a client's work is kept in, and what each hangs off. A read is
   one restrictive policy (it narrows what the other policies allow and
   never widens it); a write is the guard. Altered in place when it exists,
   so a second run changes nothing. */
do $$
declare
  spec text[][] := array[
    ['clients', 'self', 'id'],
    ['client_contacts', 'client', 'client_id'],
    ['client_services', 'client', 'client_id'],
    ['client_documents', 'client', 'client_id'],
    ['client_document_deletions', 'client', 'client_id'],
    ['client_requests', 'client', 'client_id'],
    ['client_touches', 'client', 'client_id'],
    ['documents', 'client', 'client_id'],
    ['drive_assets', 'client', 'client_id'],
    ['campaigns', 'client', 'client_id'],
    ['campaign_confirmations', 'campaign', 'campaign_id'],
    ['campaign_options', 'campaign', 'campaign_id'],
    ['campaign_deliverables', 'option', 'option_id'],
    ['option_posts', 'option', 'option_id'],
    ['option_qc', 'option', 'option_id'],
    ['option_reviews', 'option', 'option_id'],
    ['batches', 'client', 'client_id'],
    ['posts', 'batch', 'batch_id'],
    ['post_versions', 'post', 'post_id'],
    ['reviews', 'post', 'post_id'],
    ['sm_reports', 'client', 'client_id'],
    ['sm_report_ads', 'report', 'report_id'],
    ['sm_report_platforms', 'report', 'report_id'],
    ['sm_report_posts', 'report', 'report_id'],
    ['sm_report_versions', 'report', 'report_id'],
    ['ops_engagements', 'client', 'client_id']];
  i int;
  tbl text;
  kind text;
  col text;
  rule text;
begin
  for i in 1 .. array_length(spec, 1) loop
    tbl := spec[i][1]; kind := spec[i][2]; col := spec[i][3];
    if to_regclass('public.' || tbl) is null then continue; end if;
    rule := format('(select public.client_scope_free(%L)) or public.client_scope_ok(%L, %I, %L)',
                   'view', case when kind = 'self' then 'client' else kind end, col, 'view');
    /* My Work's months are read through `ops_may_see_engagement`; only the
       guard is theirs here. */
    if tbl <> 'ops_engagements' then
      if exists (select 1 from pg_policies where schemaname = 'public' and tablename = tbl
                  and policyname = 'client_scope') then
        execute format('alter policy client_scope on public.%I using (%s)', tbl, rule);
      else
        execute format('create policy client_scope on public.%I as restrictive for select to authenticated using (%s)',
                       tbl, rule);
      end if;
    end if;
    execute format('create or replace trigger client_scope_guard before insert or update on public.%I '
                   || 'for each row execute function public.client_scope_guard(%L, %L)', tbl, kind, col);
  end loop;
end $$;

-- The Members group starts at No Access on leads and past clients (the
-- user, 2026-10-03), once: a group that already says anything about either
-- is left as it is.
do $$
declare g public.team_roles;
begin
  select * into g from public.team_roles where slug = 'account';
  if g.slug is not null and not (coalesce(g.access, '{}'::jsonb) ? 'clients.leads')
     and not (coalesce(g.access, '{}'::jsonb) ? 'clients.past') then
    update public.team_roles
       set access = coalesce(access, '{}'::jsonb) || '{"clients.leads": "none", "clients.past": "none"}'::jsonb
     where slug = 'account';
    insert into public.activity_log (actor, action, subject, detail)
    values ('system', 'team.group_changed', g.name,
            'Clients · Leads: Same as section → No Access; Clients · Past clients: Same as section → No Access');
  end if;
end $$;

/* A task is in scope where it is the colleague's own work, or it hangs off a
   client they may see (no client: internal work). */
create or replace function public.ops_task_in_scope(p_task uuid)
returns boolean language sql security definer stable set search_path = public as $$
  select public.client_scope_free('view')
      or exists (select 1 from public.ops_tasks t
                  where t.id = p_task
                    and (t.created_by = (select id from public.ops_me())
                         or exists (select 1 from public.ops_task_assignees a
                                     where a.task_id = t.id and a.ended_at is null
                                       and a.team_member_id = (select id from public.ops_me()))))
      or public.client_seen((select t.client_id from public.ops_tasks t where t.id = p_task), 'view')
$$;
revoke all on function public.ops_task_in_scope(uuid) from public, anon, authenticated;

/* May the signed-in colleague read this task? Their own work always: owner,
   contributor, reviewer or the person who asked for it. The whole team's
   work with `ops.all`, on the clients they may see. */
create or replace function public.ops_may_see_task(p_task uuid)
returns boolean
language sql security definer stable set search_path = public as $$
  select case
    when not public.allowed('ops', 'view') then false
    when public.ops_granted('ops.all', 'view') and public.client_scope_free('view') then true
    when exists (
      select 1 from public.ops_tasks t
       where t.id = p_task
         and (t.created_by = (select id from public.ops_me())
              or exists (select 1 from public.ops_task_assignees a
                          where a.task_id = t.id and a.ended_at is null
                            and a.team_member_id = (select id from public.ops_me())))) then true
    when public.ops_granted('ops.all', 'view')
      then public.client_seen((select t.client_id from public.ops_tasks t where t.id = p_task), 'view')
    else false
  end
$$;
grant execute on function public.ops_may_see_task(uuid) to authenticated;

/* An engagement is read by whoever manages it or created it, by anybody who
   may see a task inside it, and by the team queue on the clients it may
   see. */
create or replace function public.ops_may_see_engagement(p_engagement uuid)
returns boolean
language sql security definer stable set search_path = public as $$
  select case
    when not public.allowed('ops', 'view') then false
    when public.ops_granted('ops.all', 'view') and public.client_scope_free('view') then true
    else exists (
      select 1 from public.ops_engagements e
       where e.id = p_engagement
         and (e.manager_id = (select id from public.ops_me())
              or e.created_by = (select id from public.ops_me())
              or (public.ops_granted('ops.all', 'view') and public.client_seen(e.client_id, 'view'))
              or exists (select 1 from public.ops_tasks t
                          where t.engagement_id = e.id and public.ops_may_see_task(t.id))))
  end
$$;
grant execute on function public.ops_may_see_engagement(uuid) to authenticated;

-- A task is made only on a client the colleague may work.
create or replace function public.ops_scope_error(p_scope text, p_client uuid)
returns text
language plpgsql stable as $$
declare st text;
begin
  if p_scope = 'internal' then return null; end if;
  if p_scope not in ('client', 'lead') then return 'bad-scope'; end if;
  if p_client is null then return 'client-required'; end if;
  select stage into st from public.clients where id = p_client;
  if st is null then return 'client-required'; end if;
  if p_scope = 'client' and st not in ('active', 'paused', 'past') then return 'client-not-active'; end if;
  if p_scope = 'lead' and st not in ('lead', 'contacted', 'proposal') then return 'not-a-lead'; end if;
  if not public.client_seen(p_client, 'work') then return 'client-scope'; end if;
  return null;
end $$;

create or replace function public.ops_report(
  p_from timestamptz default (now() - interval '90 days'),
  p_to   timestamptz default now())
returns jsonb
language plpgsql security definer stable set search_path = public as $$
declare
  out jsonb;
begin
  if not public.ops_granted('ops.reports', 'view') then
    return jsonb_build_object('error', 'denied');
  end if;

  with
  /* Where client review begins in each workflow. The final due date is the
     day the work is owed AT that stage, so everything below that position is
     "has not reached the client yet". Read from `stage_group` and never from
     a stage key: the two seeded workflows name that stage differently. */
  floors as (
    select workflow_id, min(position) as at
      from public.ops_workflow_stages
     where stage_group = 'client_review'
     group by workflow_id
  ),
  live as (
    select t.*, s.label as stage_label, s.position as stage_position,
           s.stage_group, f.at as review_at
      from public.ops_tasks t
      join public.ops_workflow_stages s
        on s.workflow_id = t.workflow_id and s.key = t.stage_key
      left join floors f on f.workflow_id = t.workflow_id
     where t.completed_at is null and t.cancelled_at is null
       and t.archived_at is null
       and public.ops_task_in_scope(t.id)
  ),

  /* 1. WHAT IS RUNNING, by the words on the screen. Grouped by the stage's
        own label rather than by its group, because "what is on shooting" is
        the question and Shooting is a label, not a group. */
  running as (
    select jsonb_agg(x order by x ->> 'position', x ->> 'label') as j from (
      select jsonb_build_object(
               'stage_key', stage_key, 'label', stage_label,
               'position', stage_position, 'stage_group', stage_group,
               'count', count(*)) as x
        from live
       group by stage_key, stage_label, stage_position, stage_group
    ) q
  ),

  /* 2. WHAT IS LATE. Past the commitment and still short of client review.
        The same rule the queue row draws, stated once more here because a
        report a page computes for itself is a second definition. */
  late as (
    select jsonb_agg(x order by x ->> 'due_at') as j from (
      select jsonb_build_object(
               'task_id', l.id, 'task_no', l.task_no, 'title', l.title,
               'client', c.name, 'stage', l.stage_label,
               'due_at', l.current_final_due_at,
               'days_over', (current_date - l.current_final_due_at::date),
               'owner', (select tm.name
                           from public.ops_task_assignees a
                           join public.team_members tm on tm.id = a.team_member_id
                          where a.task_id = l.id and a.responsibility = 'owner'
                            and a.ended_at is null
                          limit 1)) as x
        from live l
        left join public.clients c on c.id = l.client_id
       where l.current_final_due_at is not null
         and l.current_final_due_at::date < current_date
         and (l.review_at is null or l.stage_position < l.review_at)
    ) q
  ),

  /* 3. HOW LONG EACH STAGE TAKES. A task enters a stage at the event that
        names it and leaves at the next event, or at its own ending, or now.
        Only spans that were ENTERED inside the period are counted, so the
        window means what it says and a task that sat in Editing since March
        does not land in every report for ever. */
  spans as (
    select e.task_id,
           e.to_value ->> 'stage_key' as stage_key,
           e.created_at as from_at,
           coalesce(
             lead(e.created_at) over (partition by e.task_id order by e.created_at),
             t.completed_at, t.cancelled_at, now()) as to_at
      from public.ops_task_events e
      join public.ops_tasks t on t.id = e.task_id
     where e.event_type in ('task_created', 'stage_changed')
       and e.to_value ->> 'stage_key' is not null
  ),
  /* One row per span and no grouping: an earlier draft grouped by the span's
     own timestamps, which silently collapsed two tasks that entered the same
     stage in the same instant into one measurement. The label is looked up
     once per stage below instead of aggregated here. */
  span_mins as (
    select s.stage_key,
           extract(epoch from (s.to_at - s.from_at)) / 60 as mins
      from spans s
     where s.from_at >= p_from and s.from_at < p_to
       and s.to_at > s.from_at
  ),
  stage_time as (
    select jsonb_agg(x order by x ->> 'label') as j from (
      select jsonb_build_object(
               'stage_key', stage_key,
               'label', coalesce((select w.label from public.ops_workflow_stages w
                                   where w.key = sm.stage_key limit 1), stage_key),
               'n', count(*),
               'median_minutes', round(percentile_cont(0.5) within group (order by mins))::int,
               'p90_minutes', round(percentile_cont(0.9) within group (order by mins))::int) as x
        from span_mins sm
       group by stage_key
    ) q
  ),

  /* 4. WAS IT THERE ON TIME. Of the tasks that reached client review inside
        the period, how many got there on or before the date they were owed.
        Replanning is counted beside it and never folded into it: an extension
        that moves the date would otherwise erase the miss it was granted for,
        and a rate that cannot be missed is not a measurement. */
  reached as (
    select distinct on (e.task_id)
           e.task_id, e.created_at as at, t.current_final_due_at as due,
           (t.original_final_due_at is distinct from t.current_final_due_at) as replanned
      from public.ops_task_events e
      join public.ops_tasks t on t.id = e.task_id
      join public.ops_workflow_stages w
        on w.workflow_id = t.workflow_id and w.key = e.to_value ->> 'stage_key'
     where e.event_type = 'stage_changed'
       and w.stage_group = 'client_review'
       and e.created_at >= p_from and e.created_at < p_to
     order by e.task_id, e.created_at
  ),
  on_time as (
    select jsonb_build_object(
             'reached', count(*),
             'met', count(*) filter (where due is null or at::date <= due::date),
             'missed', count(*) filter (where due is not null and at::date > due::date),
             'replanned', count(*) filter (where replanned)) as j
      from reached
  ),

  /* 5. BY PERSON. The foundation of a KPI and not a KPI: what somebody
        finished in the window, how much of it was on time, and how long their
        work took end to end. No ranking and no score — a number a person can
        check is worth more than a league table nobody trusts. */
  done as (
    select t.id, t.created_at, coalesce(t.completed_at, t.delivered_at) as ended,
           t.current_final_due_at as due,
           (select a.team_member_id
              from public.ops_task_assignees a
             where a.task_id = t.id and a.responsibility = 'owner'
             order by a.ended_at nulls first, a.assigned_at desc
             limit 1) as owner_id
      from public.ops_tasks t
     where t.completed_at is not null
       and t.completed_at >= p_from and t.completed_at < p_to
  ),
  by_person as (
    select jsonb_agg(x order by x ->> 'name') as j from (
      select jsonb_build_object(
               'team_member_id', d.owner_id,
               'name', coalesce(tm.name, 'Nobody'),
               'completed', count(*),
               'on_time', count(*) filter (where d.due is null or d.ended::date <= d.due::date),
               'median_cycle_minutes',
                 round(percentile_cont(0.5) within group (
                   order by extract(epoch from (d.ended - d.created_at)) / 60))::int) as x
        from done d
        left join public.team_members tm on tm.id = d.owner_id
       group by d.owner_id, tm.name
    ) q
  ),

  /* 6. WHO IS CARRYING THE OPEN WORK (2026-09-28). One row a Task Owner:
        the open tasks they hold, and how many of those are late by the rule
        in 2 above. The team's whole queue is `ops.all`, so it is answered
        only where that part is granted. */
  open_by_person as (
    select jsonb_agg(x order by (x ->> 'open')::int desc, x ->> 'name') as j from (
      select jsonb_build_object(
               'team_member_id', o.owner_id,
               'name', coalesce(tm.name, 'No task owner'),
               'open', count(*),
               'late', count(*) filter (where o.is_late)) as x
        from (select l.id,
                     (select a.team_member_id
                        from public.ops_task_assignees a
                       where a.task_id = l.id and a.responsibility = 'owner' and a.ended_at is null
                       limit 1) as owner_id,
                     (l.current_final_due_at is not null
                      and l.current_final_due_at::date < current_date
                      and (l.review_at is null or l.stage_position < l.review_at)) as is_late
                from live l) o
        left join public.team_members tm on tm.id = o.owner_id
       where public.ops_granted('ops.all', 'view')
       group by o.owner_id, tm.name
    ) q
  )

  select jsonb_build_object(
           'from', p_from, 'to', p_to,
           'running',    coalesce((select j from running), '[]'::jsonb),
           'late',       coalesce((select j from late), '[]'::jsonb),
           'stage_time', coalesce((select j from stage_time), '[]'::jsonb),
           'on_time',    coalesce((select j from on_time), '{}'::jsonb),
           'by_person',  coalesce((select j from by_person), '[]'::jsonb),
           'open_by_person', case when public.ops_granted('ops.all', 'view')
                                  then coalesce((select j from open_by_person), '[]'::jsonb) end)
    into out;

  return out;
end $$;
grant execute on function public.ops_report(timestamptz, timestamptz) to authenticated;

create or replace function public.client_billing(p_ids uuid[] default null)
returns table (id uuid, legal_name text, company_no text, company_no_old text, tin text,
               sst_no text, bill_contact_id uuid, bill_contact text, bill_contact_email text,
               bill_contact_phone text, finance_email text, billing_address text,
               billing_missing text[])
language sql stable security definer set search_path = public as $$
  select c.id,
         case when p.bill or p.docs then c.legal_name end,
         case when p.bill then c.company_no end,
         case when p.bill then c.company_no_old end,
         case when p.bill then c.tin end,
         case when p.bill then c.sst_no end,
         case when p.bill then c.bill_contact_id end,
         case when p.bill then c.bill_contact end,
         case when p.bill then c.bill_contact_email end,
         case when p.bill then c.bill_contact_phone end,
         case when p.bill then c.finance_email end,
         case when p.bill or p.docs then c.billing_address end,
         array_remove(array[
           case when coalesce(btrim(c.legal_name), '') = '' then 'legal_name' end,
           case when coalesce(btrim(c.company_no), '') = '' then 'company_no' end,
           case when coalesce(btrim(c.billing_address), '') = '' then 'billing_address' end], null)
    from public.clients c,
         (select public.allowed('clients.billing', 'view') as bill,
                 public.register_may('client', 'work') as docs,
                 public.allowed('clients', 'view') as cv) p
   where (p.bill or p.docs or p.cv)
     and (p_ids is null or c.id = any(p_ids))
     and public.client_seen(c.id, 'view')
$$;
revoke all on function public.client_billing(uuid[]) from public, anon;
grant execute on function public.client_billing(uuid[]) to authenticated;

create or replace function public.sm_client_reports(p_client uuid)
returns jsonb
language plpgsql security definer stable set search_path = public as $$
begin
  if not public.allowed('clients', 'view') and not public.allowed('reports', 'view') then
    return jsonb_build_object('error', 'denied');
  end if;
  if not public.client_seen(p_client, 'view') then
    return jsonb_build_object('error', 'denied');
  end if;
  return jsonb_build_object('reports', coalesce((
    select jsonb_agg(jsonb_build_object('id', r.id, 'kind', r.kind, 'period_start', r.period_start,
             'period_end', r.period_end, 'status', r.status, 'version_no', r.version_no,
             'confirmed_at', r.confirmed_at, 'live_version', v.version_no, 'published_at', v.published_at)
           order by r.period_start desc, r.kind)
      from public.sm_reports r
      left join lateral (select x.version_no, x.published_at from public.sm_report_versions x
                          where x.report_id = r.id and x.withdrawn_at is null
                          order by x.version_no desc limit 1) v on true
     where r.client_id = p_client
       and (r.status in ('confirmed', 'published') or v.version_no is not null)), '[]'::jsonb));
end $$;
grant execute on function public.sm_client_reports(uuid) to authenticated;

create or replace function public.sm_report_file(p_id uuid)
returns jsonb
language plpgsql security definer stable set search_path = public as $$
declare
  r public.sm_reports;
  snap jsonb;
begin
  if not public.allowed('clients', 'view') and not public.allowed('reports', 'view') then
    return jsonb_build_object('error', 'denied');
  end if;
  select * into r from public.sm_reports where id = p_id;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if not public.client_seen(r.client_id, 'view') then return jsonb_build_object('error', 'denied'); end if;
  select x.snapshot into snap from public.sm_report_versions x
   where x.report_id = p_id and x.withdrawn_at is null order by x.version_no desc limit 1;
  if snap is not null then return jsonb_build_object('snapshot', snap); end if;
  if r.status <> 'confirmed' then return jsonb_build_object('error', 'not-finished'); end if;
  return jsonb_build_object('snapshot', public.sm_report_snapshot(p_id, false));
end $$;
grant execute on function public.sm_report_file(uuid) to authenticated;

create or replace function public.sm_report_snapshot(p_id uuid, p_final boolean default false)
returns jsonb
language plpgsql security definer stable set search_path = public as $$
declare
  r public.sm_reports;
  c public.clients;
begin
  if not public.allowed('reports', 'view') and not public.allowed('clients', 'view') then
    return jsonb_build_object('error', 'denied');
  end if;
  select * into r from public.sm_reports where id = p_id;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if not public.client_seen(r.client_id, 'view') then return jsonb_build_object('error', 'denied'); end if;
  -- Somebody who reads Clients but not Reports reads the finished report
  -- only: once it is confirmed, never while it is being prepared.
  if not public.allowed('reports', 'view') and r.status not in ('confirmed', 'published') then
    return jsonb_build_object('error', 'denied');
  end if;
  select * into c from public.clients where id = r.client_id;
  return jsonb_build_object(
    'report', jsonb_build_object(
      'id', r.id, 'kind', r.kind, 'title', r.title, 'client_name', c.name, 'client_logo_url', c.logo_url,
      'market', to_jsonb(c) ->> 'market', 'lang', r.lang,
      'period_start', r.period_start, 'period_end', r.period_end,
      'headline', r.headline, 'intro', r.intro, 'insights', r.insights, 'rank_metric', r.rank_metric,
      'first_month', r.first_month, 'ads_totals', r.ads_totals,
      'status', case when p_final then 'final' else r.status end,
      'version_no', r.version_no, 'generated_at', now(),
      'prepared_by_name', (select name from public.team_members where id = r.submitted_by)),
    'platforms', coalesce((select jsonb_agg(to_jsonb(p) - 'created_at' order by p.position, p.created_at)
                  from public.sm_report_platforms p where p.report_id = r.id), '[]'::jsonb),
    'posts', coalesce((select jsonb_agg((to_jsonb(q) - 'created_at' - 'thumb_data') || jsonb_build_object('thumb_url', q.thumb_data)
                  order by q.posted_on nulls last, q.position, q.created_at)
                  from public.sm_report_posts q where q.report_id = r.id), '[]'::jsonb),
    'ads', coalesce((select jsonb_agg((to_jsonb(a) - 'created_at' - 'thumb_data') || jsonb_build_object('thumb_url', a.thumb_data)
                  order by a.position, a.created_at)
                  from public.sm_report_ads a where a.report_id = r.id), '[]'::jsonb));
end $$;
grant execute on function public.sm_report_snapshot(uuid, boolean) to authenticated;

-- END OF CLIENT SCOPE --------------------------------------------------------

-- ===========================================================================
-- HIDDEN FROM CONTENT REVIEW — a client removed from Content Review keeps
-- every set, and their review link opens nothing while they are hidden.
-- 2026-10-03. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/sql.js compares the
-- two.
--
-- WHAT CHANGED
--   The audit of 2026-10-03: Remove from Content Review deleted every set,
--   post and approval of the client before hiding them, with no way back. It
--   now hides the client alone (`clients.review_hidden`), with Undo; Enable
--   Content Review on the client's record brings them back with the same
--   link and everything in it. The link asked only that the client be
--   active, so a hidden client's link went on opening every published set.
--   Both functions it reaches now ask that the client is not hidden, and
--   answer `not_found` (Link not recognised) while they are:
--   1. `get_review_feed` (the page, and `media-pass`, which proves a link
--      through it);
--   2. `submit_review`.
--   Each body is otherwise the one before it: get_review_feed from REVIEW
--   CONFIRMED INTERNALLY, submit_review from POST REVISIONS.
--
-- ROLLBACK
--   Re-run get_review_feed from REVIEW CONFIRMED INTERNALLY and
--   submit_review from POST REVISIONS.
-- ===========================================================================

create or replace function public.get_review_feed(p_token text, p_passcode text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_client public.clients%rowtype;
begin
  select * into v_client
  from public.clients
  where access_token = p_token and active and not review_hidden;

  if not found then
    return jsonb_build_object('error', 'not_found');
  end if;

  if v_client.passcode is not null
     and (p_passcode is null or p_passcode <> v_client.passcode) then
    return jsonb_build_object('error', 'passcode_required', 'client', v_client.name);
  end if;

  return jsonb_build_object(
    'client', jsonb_build_object(
      'name', v_client.name,
      'logo_url', v_client.logo_url,
      'handles', jsonb_build_object(
        'instagram', v_client.handle_ig,
        'facebook',  v_client.handle_fb,
        'tiktok',    v_client.handle_tiktok,
        'xhs',       v_client.handle_xhs)),
    'batches', coalesce((
      select jsonb_agg(batch order by batch->>'created_at' desc)
      from (
        select jsonb_build_object(
          'id',         b.id,
          'title',      b.title,
          'note',       b.note,
          'created_at', b.created_at,
          'posts', coalesce((
            select jsonb_agg(post order by (post->>'position')::int)
            from (
              select jsonb_build_object(
                'id',         p.id,
                'platform',   p.platform,
                'format',     p.format,
                'handle',     p.handle,
                'caption',    p.caption,
                'caption_zh', p.caption_zh,
                'title',      p.title,
                'media',      p.media,
                'position',   p.position,
                'round',      p.round,
                'reset_note', case
                  when p.review_reset_at is not null then p.review_reset_note end,
                /* The decision standing on the round on show: never one about
                   a round the client no longer sees, never one taken back. */
                'review',     (
                  select jsonb_build_object(
                    'decision',   r.decision,
                    'note',       r.note,
                    'reviewer',   case when r.source = 'team' then null else r.reviewer end,
                    'created_at', r.created_at,
                    'by_team',    (r.source = 'team'),
                    'suggested',  (r.suggested_caption is not null or r.suggested_caption_zh is not null),
                    /* The client's own edit, so Edit request reopens it. */
                    'suggested_caption',    r.suggested_caption,
                    'suggested_caption_zh', r.suggested_caption_zh)
                  from public.reviews r
                  where r.post_id = p.id and r.round = p.round and r.undone_at is null
                    and (p.review_reset_at is null or r.created_at > p.review_reset_at)
                  order by r.created_at desc
                  limit 1),
                /* What the client asked of the round before, so a revision
                   says what it answers. Words only: the earlier file and copy
                   stay with the team. */
                'asked',      case when p.round > 1 then (
                  select jsonb_build_object(
                    'note',       r.note,
                    'reviewer',   r.reviewer,
                    'created_at', r.created_at,
                    'suggested',  (r.suggested_caption is not null or r.suggested_caption_zh is not null))
                  from public.reviews r
                  where r.post_id = p.id and r.round = p.round - 1 and r.decision = 'changes'
                    and r.undone_at is null
                  order by r.created_at desc
                  limit 1) end
              ) as post
              from public.posts p
              where p.batch_id = b.id
            ) posts
          ), '[]'::jsonb)
        ) as batch
        from public.batches b
        where b.client_id = v_client.id and b.published
      ) batches
    ), '[]'::jsonb)
  );
end $$;
revoke all on function public.get_review_feed(text, text) from public;
grant execute on function public.get_review_feed(text, text) to anon, authenticated;

create or replace function public.submit_review(
  p_token      text,
  p_post_id    uuid,
  p_decision   text,
  p_note       text default null,
  p_reviewer   text default null,
  p_passcode   text default null,
  p_caption    text default null,
  p_caption_zh text default null
) returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_client_id uuid;
  v_post      public.posts%rowtype;
  v_cap       text;
  v_cap_zh    text;
begin
  if p_decision not in ('approved', 'changes') then
    return jsonb_build_object('error', 'bad_decision');
  end if;

  select c.id into v_client_id
  from public.clients c
  where c.access_token = p_token
    and c.active
    and not c.review_hidden
    and (c.passcode is null or c.passcode = p_passcode);

  if v_client_id is null then
    return jsonb_build_object('error', 'not_found');
  end if;

  -- the post must belong to a published batch of this client
  select p.* into v_post
  from public.posts p
  join public.batches b on b.id = p.batch_id
  where p.id = p_post_id and b.client_id = v_client_id and b.published;

  if v_post.id is null then
    return jsonb_build_object('error', 'not_found');
  end if;

  /* A suggested copy is kept only where it differs from the copy on show,
     and only on a request for changes. */
  if p_decision = 'changes' then
    v_cap    := case when p_caption is not null
                      and p_caption is distinct from coalesce(v_post.caption, '') then p_caption end;
    v_cap_zh := case when p_caption_zh is not null
                      and p_caption_zh is distinct from coalesce(v_post.caption_zh, '') then p_caption_zh end;
  end if;

  if p_decision = 'changes' and coalesce(btrim(p_note), '') = ''
     and v_cap is null and v_cap_zh is null then
    return jsonb_build_object('error', 'note_required');
  end if;

  insert into public.reviews (post_id, decision, note, reviewer, suggested_caption, suggested_caption_zh)
  values (p_post_id, p_decision, nullif(btrim(p_note), ''), nullif(btrim(p_reviewer), ''), v_cap, v_cap_zh);

  /* The activity record is the portal's account of what was decided and by
     whom, and it held only what the team did. A client approving a post is
     the decision the whole section exists to collect, and it left nothing
     anybody could produce later: the verdict sat in `reviews` alone, which
     no screen reads as a history. The reviewer's own typed name is the
     actor, because a person decided it. */
  insert into public.activity_log (actor, action, subject, detail)
  select coalesce(nullif(btrim(coalesce(p_reviewer, '')), ''), 'Client'),
         case when p_decision = 'approved' then 'review.approved' else 'review.changes' end,
         c.name,
         b.title || ' · ' || coalesce(nullif(p.platform, ''), 'post') ||
         case when p.round > 1 then ' · revision ' || p.round else '' end ||
         coalesce(' · ' || nullif(btrim(coalesce(p_note, '')), ''), '') ||
         case when v_cap is not null or v_cap_zh is not null then ' · caption edited' else '' end
    from public.posts p
    join public.batches b on b.id = p.batch_id
    join public.clients c on c.id = b.client_id
   where p.id = p_post_id;

  return jsonb_build_object('ok', true);
end $$;

revoke all on function public.submit_review(text, uuid, text, text, text, text, text, text) from public;
grant execute on function public.submit_review(text, uuid, text, text, text, text, text, text) to anon, authenticated;

-- END OF HIDDEN FROM CONTENT REVIEW ------------------------------------------

-- ===========================================================================
-- TASK CLIENT NAMES — a task names its client wherever the colleague may see
-- the task.
-- 2026-10-03. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/sql.js compares the
-- two.
--
-- WHAT CHANGED
--   The audit of 2026-10-03: a colleague's own task on a client outside
--   their reach (Own clients only, or a band at No Access) read No client in
--   My Work, because the client's row never arrives to the join. The page
--   asks `ops_task_clients(p_tasks)` for those tasks alone: each task the
--   caller may see (`ops_may_see_task`) with its client's name, and nothing
--   else about the client. At most 500 tasks a call.
--
-- ROLLBACK
--   Remove the function ops_task_clients(uuid[]).
-- ===========================================================================

create or replace function public.ops_task_clients(p_tasks uuid[])
returns table (task_id uuid, client_name text)
language sql security definer stable set search_path = public as $$
  select t.id, c.name
    from public.ops_tasks t
    join public.clients c on c.id = t.client_id
   where t.id = any (p_tasks[1:500])
     and public.ops_may_see_task(t.id)
$$;
revoke all on function public.ops_task_clients(uuid[]) from public, anon;
grant execute on function public.ops_task_clients(uuid[]) to authenticated;

-- END OF TASK CLIENT NAMES ---------------------------------------------------
-- ===========================================================================
-- CLIENT SCOPE ON REMOVAL — a record under a client is removed only by a
-- colleague who holds that client at Manage.
-- 2026-10-03. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/sql.js compares the
-- two.
--
-- WHAT CHANGED
--   The audit of 2026-10-03: `client_scope_guard` asks every insert and
--   update, and left removals to the functions that make them. Five of
--   them (`delete_client`, `letter_delete`, `document_delete`,
--   `sm_report_delete`, `ops_delete_engagement`) are security definer and
--   asked only the section's level, so a colleague on Own clients only, or
--   with Leads or Past clients below Manage, could remove a record they
--   cannot open. A guard before each removal on the five tables those
--   functions remove from now asks the same rule at Manage
--   (`client_row_seen`, `client_scope_ok`). A removal made by a cascade
--   (`pg_trigger_depth() > 1`) was already asked at the record it came
--   from; a caller who is not on the team, an admin, or one every client
--   reaches at Manage pays nothing (`client_scope_free`). A browser's own
--   removal already reaches only rows its read policy shows, and now meets
--   the same rule.
--
--   Holds the word delete (trigger events), so it is run in the SQL Editor.
--
-- ROLLBACK
--   For each table below: drop trigger if exists client_scope_removal on
--   public.<table>; then drop function public.client_scope_removal().
-- ===========================================================================

create or replace function public.client_scope_removal()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  kind text := tg_argv[0];
  col  text := tg_argv[1];
  o jsonb := to_jsonb(old);
begin
  if pg_trigger_depth() > 1 or public.client_scope_free('manage') then return old; end if;
  if (kind = 'self' and not public.client_row_seen(o ->> 'stage', o ->> 'owner', 'manage'))
     or (kind <> 'self' and not public.client_scope_ok(kind, (o ->> col)::uuid, 'manage')) then
    raise exception 'This client is outside your access.' using errcode = '42501', hint = 'client-scope';
  end if;
  return old;
end $$;
revoke all on function public.client_scope_removal() from public, anon, authenticated;

do $$
declare
  spec text[][] := array[
    ['clients', 'self', 'id'],
    ['client_documents', 'client', 'client_id'],
    ['documents', 'client', 'client_id'],
    ['sm_reports', 'client', 'client_id'],
    ['ops_engagements', 'client', 'client_id']];
  i int;
begin
  for i in 1 .. array_length(spec, 1) loop
    if to_regclass('public.' || spec[i][1]) is null then continue; end if;
    execute format('create or replace trigger client_scope_removal before delete on public.%I '
                   || 'for each row execute function public.client_scope_removal(%L, %L)',
                   spec[i][1], spec[i][2], spec[i][3]);
  end loop;
end $$;

-- END OF CLIENT SCOPE ON REMOVAL ---------------------------------------------

-- ===========================================================================
-- REEL COVER PAIRS — a cover names the reel it was made for, and the client's
-- page shows the two as one card.
-- 2026-10-03. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/sql.js compares the
-- two.
--
-- WHAT CHANGED
--   The user, 2026-10-03: a set of thirty reels with their covers read as
--   sixty items. `posts.cover_for` names the reel a cover image belongs to
--   (the team pairs them as the files are added, or from the cover's ⋯);
--   `get_review_feed` sends it, and the client's page draws the reel and its
--   cover as one card with a tab each. Each is still its own post with its
--   own decision, round and history; a pairing is not a revision (the
--   revision trigger reads the file, copy and title only). The column holds
--   no foreign key, so removing a reel never waits on its cover: a cover
--   whose reel is gone stands alone on both pages.
--
-- ROLLBACK
--   Re-run the HIDDEN FROM CONTENT REVIEW section of schema.sql (its
--   get_review_feed), then remove the column posts.cover_for.
-- ===========================================================================

alter table public.posts add column if not exists cover_for uuid;

create or replace function public.get_review_feed(p_token text, p_passcode text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_client public.clients%rowtype;
begin
  select * into v_client
  from public.clients
  where access_token = p_token and active and not review_hidden;

  if not found then
    return jsonb_build_object('error', 'not_found');
  end if;

  if v_client.passcode is not null
     and (p_passcode is null or p_passcode <> v_client.passcode) then
    return jsonb_build_object('error', 'passcode_required', 'client', v_client.name);
  end if;

  return jsonb_build_object(
    'client', jsonb_build_object(
      'name', v_client.name,
      'logo_url', v_client.logo_url,
      'handles', jsonb_build_object(
        'instagram', v_client.handle_ig,
        'facebook',  v_client.handle_fb,
        'tiktok',    v_client.handle_tiktok,
        'xhs',       v_client.handle_xhs)),
    'batches', coalesce((
      select jsonb_agg(batch order by batch->>'created_at' desc)
      from (
        select jsonb_build_object(
          'id',         b.id,
          'title',      b.title,
          'note',       b.note,
          'created_at', b.created_at,
          'posts', coalesce((
            select jsonb_agg(post order by (post->>'position')::int)
            from (
              select jsonb_build_object(
                'id',         p.id,
                'platform',   p.platform,
                'format',     p.format,
                'handle',     p.handle,
                'caption',    p.caption,
                'caption_zh', p.caption_zh,
                'title',      p.title,
                'media',      p.media,
                'cover_for',  p.cover_for,
                'position',   p.position,
                'round',      p.round,
                'reset_note', case
                  when p.review_reset_at is not null then p.review_reset_note end,
                /* The decision standing on the round on show: never one about
                   a round the client no longer sees, never one taken back. */
                'review',     (
                  select jsonb_build_object(
                    'decision',   r.decision,
                    'note',       r.note,
                    'reviewer',   case when r.source = 'team' then null else r.reviewer end,
                    'created_at', r.created_at,
                    'by_team',    (r.source = 'team'),
                    'suggested',  (r.suggested_caption is not null or r.suggested_caption_zh is not null),
                    /* The client's own edit, so Edit request reopens it. */
                    'suggested_caption',    r.suggested_caption,
                    'suggested_caption_zh', r.suggested_caption_zh)
                  from public.reviews r
                  where r.post_id = p.id and r.round = p.round and r.undone_at is null
                    and (p.review_reset_at is null or r.created_at > p.review_reset_at)
                  order by r.created_at desc
                  limit 1),
                /* What the client asked of the round before, so a revision
                   says what it answers. Words only: the earlier file and copy
                   stay with the team. */
                'asked',      case when p.round > 1 then (
                  select jsonb_build_object(
                    'note',       r.note,
                    'reviewer',   r.reviewer,
                    'created_at', r.created_at,
                    'suggested',  (r.suggested_caption is not null or r.suggested_caption_zh is not null))
                  from public.reviews r
                  where r.post_id = p.id and r.round = p.round - 1 and r.decision = 'changes'
                    and r.undone_at is null
                  order by r.created_at desc
                  limit 1) end
              ) as post
              from public.posts p
              where p.batch_id = b.id
            ) posts
          ), '[]'::jsonb)
        ) as batch
        from public.batches b
        where b.client_id = v_client.id and b.published
      ) batches
    ), '[]'::jsonb)
  );
end $$;
revoke all on function public.get_review_feed(text, text) from public;
grant execute on function public.get_review_feed(text, text) to anon, authenticated;

-- END OF REEL COVER PAIRS ---------------------------------------------------
-- ===========================================================================
-- UPGRADE MODE — an admin covers the portal's pages while it is upgraded.
-- 2026-10-03. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/sql.js compares the
-- two.
--
-- WHAT CHANGED
--   The user, 2026-10-03: an admin-only switch that shows every portal page,
--   internal and client facing, one cover reading Upgrading in progress,
--   now or from a set date and time, until it is switched off or an end set
--   with it passes. One row in `app_flags` holds it (RLS on, no policy, no
--   grant): `maintenance_state()` answers anybody whether it is on now
--   (`on`), switched on at all (`set`), its note and its window; and
--   `maintenance_set()` changes it for an admin alone, filed as Access
--   changed under Team (`team.changed`, subject Portal, "Upgrade mode: off →
--   on"). The page draws the cover (`js/maintenance.js`) and an admin keeps
--   working under a banner; the front door and short links stay up. Pages
--   only: the database keeps answering while it is on.
--
-- ROLLBACK
--   Remove the functions maintenance_set(boolean, text, timestamptz,
--   timestamptz) and maintenance_state(), then the table app_flags.
-- ===========================================================================

create table if not exists public.app_flags (
  key        text primary key,
  on_now     boolean not null default false,
  note       text,
  starts_at  timestamptz,
  ends_at    timestamptz,
  set_by     text,
  set_at     timestamptz
);
alter table public.app_flags add column if not exists starts_at timestamptz;
alter table public.app_flags add column if not exists ends_at timestamptz;
alter table public.app_flags enable row level security;
revoke all on table public.app_flags from public, anon, authenticated;

create or replace function public.maintenance_state()
returns jsonb language sql security definer stable set search_path = public as $$
  select coalesce((select jsonb_build_object(
                     'on', f.on_now and (f.starts_at is null or f.starts_at <= now())
                                    and (f.ends_at is null or f.ends_at > now()),
                     'set', f.on_now and (f.ends_at is null or f.ends_at > now()),
                     'note', f.note,
                     'since', coalesce(f.starts_at, f.set_at),
                     'starts_at', f.starts_at,
                     'ends_at', f.ends_at)
                     from public.app_flags f where f.key = 'maintenance'),
                  jsonb_build_object('on', false, 'set', false))
$$;
revoke all on function public.maintenance_state() from public;
grant execute on function public.maintenance_state() to anon, authenticated;

create or replace function public.maintenance_set(p_on boolean, p_note text default null,
                                                  p_starts timestamptz default null,
                                                  p_ends timestamptz default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_was boolean;
  v_who text;
  v_on boolean := coalesce(p_on, false);
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
  v_when text := '';
begin
  if not public.allowed('admin') then
    return jsonb_build_object('error', 'denied');
  end if;
  if v_on and p_ends is not null and p_ends <= greatest(coalesce(p_starts, now()), now()) then
    return jsonb_build_object('error', 'bad-window');
  end if;
  select coalesce(t.name, t.email) into v_who from public.team_members t
   where lower(t.email) = lower(auth.jwt() ->> 'email') and t.active limit 1;
  select f.on_now and (f.ends_at is null or f.ends_at > now()) into v_was
    from public.app_flags f where f.key = 'maintenance';
  insert into public.app_flags (key, on_now, note, starts_at, ends_at, set_by, set_at)
  values ('maintenance', v_on, case when v_on then left(v_note, 300) end,
          case when v_on and p_starts > now() then p_starts end,
          case when v_on then p_ends end, v_who, now())
  on conflict (key) do update
    set on_now = excluded.on_now, note = excluded.note, starts_at = excluded.starts_at,
        ends_at = excluded.ends_at, set_by = excluded.set_by, set_at = excluded.set_at;
  if v_on and p_starts > now() then
    v_when := ' · from ' || regexp_replace(to_char(p_starts at time zone 'Asia/Kuala_Lumpur', 'FMDD Mon YYYY HH24:MI'), '\mSep\M', 'Sept');
  end if;
  if v_on and p_ends is not null then
    v_when := v_when || ' · until ' || regexp_replace(to_char(p_ends at time zone 'Asia/Kuala_Lumpur', 'FMDD Mon YYYY HH24:MI'), '\mSep\M', 'Sept');
  end if;
  insert into public.activity_log (actor, action, subject, detail)
  values (coalesce(v_who, 'admin'), 'team.changed', 'Portal',
          'Upgrade mode: ' || case when coalesce(v_was, false) then 'on' else 'off' end || ' → ' ||
          case when v_on then 'on' else 'off' end || v_when ||
          case when v_on then coalesce(' · ' || left(v_note, 300), '') else '' end);
  return public.maintenance_state();
end $$;
revoke all on function public.maintenance_set(boolean, text, timestamptz, timestamptz) from public, anon;
grant execute on function public.maintenance_set(boolean, text, timestamptz, timestamptz) to authenticated;

-- END OF UPGRADE MODE --------------------------------------------------------
-- ===========================================================================
-- DRAFT WITH AI BY SUBJECT — a report's one draft is counted by what the
-- report is about, so deleting it and starting it again does not free a
-- second draft.
-- 2026-10-04. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/smsql.js compares the
-- two.
--
-- WHAT CHANGED
--   1. `ai_drafts` keeps the report's subject on every press: its client,
--      its kind and its period. A deleted report's link is set to null, so
--      the count by report alone came back to nothing and a new report for
--      the same client and month took a fresh draft. The subject stays.
--      Earlier presses are filled in from their reports; a press whose
--      report is already gone has none.
--   2. `ai_draft_claim(p_report)` and `ai_draft_left(p_report)` count, for
--      the report's one draft and an admin's five a day, every press on the
--      report or on any report of the same client and kind whose period
--      shares a day with it, deleted or not. The colleague's twenty and the
--      team's sixty a day are unchanged, as is a failed press not counting.
--
-- ROLLBACK
--   Run the DRAFT WITH AI LIMITS section's ai_draft_claim and the DRAFT WITH
--   AI LEFT section's ai_draft_left again, then
--   drop function if exists public.ai_draft_same(uuid);
--   alter table public.ai_drafts drop column if exists period_end,
--     drop column if exists period_start, drop column if exists kind,
--     drop column if exists client_id;
-- ===========================================================================

alter table public.ai_drafts add column if not exists client_id uuid;
alter table public.ai_drafts add column if not exists kind text;
alter table public.ai_drafts add column if not exists period_start date;
alter table public.ai_drafts add column if not exists period_end date;
create index if not exists ai_drafts_subject_idx on public.ai_drafts (client_id, kind, period_start, period_end);

update public.ai_drafts d
   set client_id = r.client_id, kind = r.kind, period_start = r.period_start, period_end = r.period_end
  from public.sm_reports r
 where r.id = d.report_id and d.client_id is null;

-- The presses on a report's subject: the report itself, or any report of the
-- same client and kind whose period shares a day with it.
create or replace function public.ai_draft_same(p_report uuid)
returns setof public.ai_drafts
language sql stable security definer set search_path = public as $$
  select d.* from public.ai_drafts d
   where d.outcome <> 'failed'
     and (d.report_id = p_report
          or exists (select 1 from public.sm_reports r
                      where r.id = p_report and d.client_id = r.client_id and d.kind = r.kind
                        and d.period_start <= r.period_end and d.period_end >= r.period_start))
$$;
revoke all on function public.ai_draft_same(uuid) from public, anon, authenticated;

create or replace function public.ai_draft_claim(p_report uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m public.team_members;
  r public.sm_reports;
  since timestamptz := now() - interval '24 hours';
  n_report integer;
  n_member integer;
  n_team integer;
  first_at timestamptz;
  new_id uuid;
begin
  if not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'denied'); end if;
  -- One count at a time, so two presses together cannot both take the last draft.
  perform pg_advisory_xact_lock(hashtext('ai_draft_claim'));
  select * into r from public.sm_reports where id = p_report;
  -- One draft a subject; a second and later is an admin's.
  if not coalesce(m.is_admin, false) and exists (select 1 from public.ai_draft_same(p_report)) then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'redraft', 'limit', 1);
  end if;
  select count(*), min(s.created_at) into n_report, first_at from public.ai_draft_same(p_report) s
   where s.created_at > since;
  if n_report >= 5 then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'report', 'limit', 5, 'next', first_at + interval '24 hours');
  end if;
  select count(*), min(d.created_at) into n_member, first_at from public.ai_drafts d
   where d.team_member_id = m.id and d.created_at > since and d.outcome <> 'failed';
  if n_member >= 20 then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'person', 'limit', 20, 'next', first_at + interval '24 hours');
  end if;
  select count(*), min(d.created_at) into n_team, first_at from public.ai_drafts d
   where d.created_at > since and d.outcome <> 'failed';
  if n_team >= 60 then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'team', 'limit', 60, 'next', first_at + interval '24 hours');
  end if;
  insert into public.ai_drafts (report_id, team_member_id, client_id, kind, period_start, period_end)
  values (p_report, m.id, r.client_id, r.kind, r.period_start, r.period_end) returning id into new_id;
  return jsonb_build_object('id', new_id, 'left', 20 - n_member - 1);
end $$;

create or replace function public.ai_draft_left(p_report uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  m public.team_members;
  since timestamptz := now() - interval '24 hours';
  is_adm boolean;
  n_report integer; n_member integer; n_team integer;
  at_report timestamptz; at_member timestamptz; at_team timestamptz;
  l_report integer; l_member integer; l_team integer; l_min integer;
  v_scope text;
begin
  if not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'denied'); end if;
  is_adm := coalesce(m.is_admin, false);
  select count(*), min(s.created_at) into n_report, at_report from public.ai_draft_same(p_report) s
   where s.created_at > since;
  if is_adm then
    l_report := greatest(0, 5 - n_report);
  elsif exists (select 1 from public.ai_draft_same(p_report)) then
    l_report := 0;
  else
    l_report := 1;
  end if;
  select count(*), min(d.created_at) into n_member, at_member from public.ai_drafts d
   where d.team_member_id = m.id and d.created_at > since and d.outcome <> 'failed';
  l_member := greatest(0, 20 - n_member);
  select count(*), min(d.created_at) into n_team, at_team from public.ai_drafts d
   where d.created_at > since and d.outcome <> 'failed';
  l_team := greatest(0, 60 - n_team);
  l_min := least(l_report, l_member, l_team);
  v_scope := case when l_min = l_report then case when is_adm then 'report' else 'redraft' end
                  when l_min = l_member then 'person' else 'team' end;
  return jsonb_build_object(
    'left', l_min, 'scope', v_scope,
    'limit', case v_scope when 'redraft' then 1 when 'report' then 5 when 'person' then 20 else 60 end,
    'report', l_report, 'person', l_member, 'team', l_team, 'admin', is_adm,
    'next', case when l_min > 0 or v_scope = 'redraft' then null
                 when v_scope = 'report' then at_report + interval '24 hours'
                 when v_scope = 'person' then at_member + interval '24 hours'
                 else at_team + interval '24 hours' end);
end $$;

revoke all on function public.ai_draft_claim(uuid) from public, anon, authenticated;
revoke all on function public.ai_draft_left(uuid) from public, anon, authenticated;
grant execute on function public.ai_draft_claim(uuid) to authenticated;
grant execute on function public.ai_draft_left(uuid) to authenticated;

-- END OF DRAFT WITH AI BY SUBJECT --------------------------------------------
-- ===========================================================================
-- REPORT REVIEWER — a report is submitted to a named reviewer, who is told,
-- and only that reviewer or an admin confirms it.
-- 2026-10-04. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/smsql.js compares the
-- two.
--
-- WHAT CHANGED
--   1. `sm_reports.reviewer_id`: who checks the report. Set only by the
--      functions (the guard refuses it from a page). Kept through a send
--      back and a revision, so the next submit offers the same reviewer.
--   2. `ops_notifications.report_id`: a notification may open a report. The
--      push it queues opens `?s=reports&report=`.
--   3. `sm_report_may_review(p_member)`: an active colleague at Reports Full
--      Access, or an admin. `sm_report_reviewers(p_id)` (Reports at Work)
--      lists them for the report, the submitter never among them, with the
--      reviewer last named for the client marked `last`.
--   4. `sm_report_submit(p_id, p_reviewer, p_reason)`: the reviewer is required
--      (`no-reviewer`), never the submitter (`self-review`), and must be
--      able to review (`bad-reviewer`). The reviewer is told; the record
--      names them.
--   5. `sm_report_assign(p_id, p_reviewer)`: while in review, the
--      submitter, the reviewer or an admin hands the review to another
--      colleague who may review and is not the submitter; they are told;
--      filed `report.reassigned` with from and to.
--   6. `sm_report_confirm(p_id)`: with a reviewer named, only that reviewer
--      or an admin confirms (`not-reviewer`); an admin confirming for
--      somebody else is filed "in place of" them. A report submitted before
--      reviewers keeps the earlier rule (Full Access, never the submitter
--      unless an admin). The submitter is told.
--   7. `sm_report_return(p_id, p_note)`: in review with a reviewer named,
--      the reviewer, an admin or the submitter (taking it back) sends it
--      back; the submitter is told with the note when somebody else does.
--   8. `activity_section` files `report.reassigned` under Reports.
--   Notifications never fail the step that caused them.
--
-- ROLLBACK
--   Run the REPORTS section's sm_report_submit and sm_report_return, the
--   REPORT ADMIN CONFIRM section's sm_report_confirm, the guard and the
--   push trigger from their sections, and the HANDBOOK section's
--   activity_section again, then
--   drop function if exists public.sm_report_submit(uuid, uuid, text);
--   drop function if exists public.sm_report_assign(uuid, uuid);
--   drop function if exists public.sm_report_reviewers(uuid);
--   drop function if exists public.sm_report_notify(uuid, uuid, text, text, text);
--   drop function if exists public.sm_report_may_review(uuid);
--   alter table public.ops_notifications drop column if exists report_id;
--   alter table public.sm_reports drop column if exists reviewer_id;
-- ===========================================================================

alter table public.sm_reports add column if not exists reviewer_id uuid
  references public.team_members(id) on delete set null;
alter table public.ops_notifications add column if not exists report_id uuid
  references public.sm_reports(id) on delete cascade;

-- The reviewer is a stamp like the submitter: only the functions move it.
create or replace function public.sm_report_guard()
returns trigger
language plpgsql set search_path = public as $$
begin
  if coalesce(current_setting('adspace.sm_fn', true), '') = 'on' then
    new.updated_at := now();
    return new;
  end if;
  if new.status is distinct from old.status or new.version_no is distinct from old.version_no
     or new.submitted_by is distinct from old.submitted_by or new.submitted_at is distinct from old.submitted_at
     or new.confirmed_by is distinct from old.confirmed_by or new.confirmed_at is distinct from old.confirmed_at
     or new.return_note is distinct from old.return_note or new.client_id is distinct from old.client_id
     or new.kind is distinct from old.kind or new.reviewer_id is distinct from old.reviewer_id
     or new.created_by is distinct from old.created_by or new.created_at is distinct from old.created_at then
    raise exception 'sm-status-by-function' using errcode = 'P0001';
  end if;
  if old.status <> 'draft' then
    raise exception 'sm-not-draft' using errcode = 'P0001';
  end if;
  new.updated_at := now();
  return new;
end $$;
revoke all on function public.sm_report_guard() from public, anon, authenticated;

create or replace function public.ops_notifications_push()
returns trigger
language plpgsql security definer set search_path = public as $$
declare
  v_title text := coalesce(nullif(btrim(new.title), ''), 'My Work');
  v_body  text := coalesce(new.body, '');
begin
  perform public.push_queue('team', new.team_member_id,
    jsonb_build_object('en', jsonb_build_object('title', v_title, 'body', v_body),
                       'zh', jsonb_build_object('title', v_title, 'body', v_body)),
    case when new.task_id is not null then '/admin/?s=work&open=' || new.task_id::text
         when new.report_id is not null then '/admin/?s=reports&report=' || new.report_id::text
         else '/admin/' end,
    case when new.task_id is not null then 'task-' || new.task_id::text
         when new.report_id is not null then 'report-' || new.report_id::text
         else null end);
  return new;
exception when others then
  return new;
end $$;
drop trigger if exists ops_notifications_push on public.ops_notifications;
create trigger ops_notifications_push after insert on public.ops_notifications
  for each row execute function public.ops_notifications_push();

-- Who may check a report: an active colleague at Reports Full Access, or an admin.
create or replace function public.sm_report_may_review(p_member uuid)
returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.team_members m
     where m.id = p_member and m.active
       and (coalesce(m.is_admin, false) or m.role = 'admin'
            or public.level_rank(coalesce(m.access ->> 'reports', 'none')) >= public.level_rank('manage')))
$$;
revoke all on function public.sm_report_may_review(uuid) from public, anon, authenticated;

-- A report's notification to one colleague, never to the one acting, and
-- never failing the step that sends it.
create or replace function public.sm_report_notify(p_member uuid, p_report uuid, p_kind text, p_title text, p_body text)
returns void
language plpgsql security definer set search_path = public as $$
begin
  if p_member is null or p_member = (public.ops_me()).id then return; end if;
  insert into public.ops_notifications (team_member_id, task_id, report_id, kind, title, body, dedupe_key)
  values (p_member, null, p_report, p_kind, p_title, p_body,
          p_kind || ':' || p_report::text || ':' || p_member::text || ':' || to_char(now(), 'YYYYMMDDHH24MI'))
  on conflict (dedupe_key) do nothing;
exception when others then
  return;
end $$;
revoke all on function public.sm_report_notify(uuid, uuid, text, text, text) from public, anon, authenticated;

create or replace function public.sm_report_reviewers(p_id uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.sm_reports;
  author uuid;
  last_id uuid;
begin
  if me.id is null or not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_id;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  author := case when r.status = 'review' then r.submitted_by else me.id end;
  select x.reviewer_id into last_id from public.sm_reports x
   where x.client_id = r.client_id and x.reviewer_id is not null and x.reviewer_id is distinct from author
     and public.sm_report_may_review(x.reviewer_id)
   order by coalesce(x.submitted_at, x.updated_at) desc nulls last limit 1;
  return jsonb_build_object('reviewers', coalesce((
    select jsonb_agg(jsonb_build_object('id', m.id, 'name', m.name, 'code', m.staff_code,
             'last', m.id = coalesce(r.reviewer_id, last_id))
             order by m.staff_code nulls last, m.name)
      from public.team_members m
     where m.id is distinct from author and public.sm_report_may_review(m.id)), '[]'::jsonb));
end $$;
revoke all on function public.sm_report_reviewers(uuid) from public, anon, authenticated;
grant execute on function public.sm_report_reviewers(uuid) to authenticated;

-- PostgREST cannot choose between overloads, so the one-argument submit goes.
drop function if exists public.sm_report_submit(uuid);
/* `p_reason` is the reason a late submit, or one past the month's gate,
   gives; it is read from MONTH REPORTS (2026-10-04) on. */
create or replace function public.sm_report_submit(p_id uuid, p_reviewer uuid default null, p_reason text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.sm_reports;
  cname text;
begin
  if me.id is null or not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_id for update;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if r.status <> 'draft' then return jsonb_build_object('error', 'not-draft', 'status', r.status); end if;
  if r.kind = 'ads' then
    if not exists (select 1 from public.sm_report_ads where report_id = p_id) then
      return jsonb_build_object('error', 'no-ads');
    end if;
  else
    if not exists (select 1 from public.sm_report_platforms where report_id = p_id) then
      return jsonb_build_object('error', 'no-platforms');
    end if;
    if not exists (select 1 from public.sm_report_posts where report_id = p_id) then
      return jsonb_build_object('error', 'no-posts');
    end if;
  end if;
  if p_reviewer is null then return jsonb_build_object('error', 'no-reviewer'); end if;
  if p_reviewer = me.id then return jsonb_build_object('error', 'self-review'); end if;
  if not public.sm_report_may_review(p_reviewer) then return jsonb_build_object('error', 'bad-reviewer'); end if;
  perform set_config('adspace.sm_fn', 'on', true);
  update public.sm_reports set status = 'review', submitted_by = me.id, submitted_at = now(),
    reviewer_id = p_reviewer, return_note = null, confirmed_by = null, confirmed_at = null where id = p_id;
  perform set_config('adspace.sm_fn', 'off', true);
  perform public.sm_report_log(p_id, 'report.submitted',
    'Reviewer: ' || (select name from public.team_members where id = p_reviewer));
  select c.name into cname from public.clients c where c.id = r.client_id;
  perform public.sm_report_notify(p_reviewer, p_id, 'report.review', 'Report to review',
    cname || ' · ' || public.sm_period_word(r.period_start, r.period_end));
  return jsonb_build_object('ok', true, 'status', 'review');
end $$;
revoke all on function public.sm_report_submit(uuid, uuid, text) from public, anon, authenticated;
grant execute on function public.sm_report_submit(uuid, uuid, text) to authenticated;

create or replace function public.sm_report_assign(p_id uuid, p_reviewer uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.sm_reports;
  was text;
  cname text;
begin
  if me.id is null or not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_id for update;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if r.status <> 'review' then return jsonb_build_object('error', 'not-in-review', 'status', r.status); end if;
  if not (me.id = r.submitted_by or me.id is not distinct from r.reviewer_id
          or coalesce(me.is_admin, false) or me.role = 'admin') then
    return jsonb_build_object('error', 'denied');
  end if;
  if p_reviewer is null then return jsonb_build_object('error', 'no-reviewer'); end if;
  if p_reviewer = r.submitted_by then return jsonb_build_object('error', 'self-review'); end if;
  if p_reviewer is not distinct from r.reviewer_id then return jsonb_build_object('error', 'same-reviewer'); end if;
  if not public.sm_report_may_review(p_reviewer) then return jsonb_build_object('error', 'bad-reviewer'); end if;
  select name into was from public.team_members where id = r.reviewer_id;
  perform set_config('adspace.sm_fn', 'on', true);
  update public.sm_reports set reviewer_id = p_reviewer where id = p_id;
  perform set_config('adspace.sm_fn', 'off', true);
  perform public.sm_report_log(p_id, 'report.reassigned',
    'Reviewer: ' || coalesce(was, 'not set') || ' → ' || (select name from public.team_members where id = p_reviewer));
  select c.name into cname from public.clients c where c.id = r.client_id;
  perform public.sm_report_notify(p_reviewer, p_id, 'report.review', 'Report to review',
    cname || ' · ' || public.sm_period_word(r.period_start, r.period_end));
  return jsonb_build_object('ok', true, 'status', 'review');
end $$;
revoke all on function public.sm_report_assign(uuid, uuid) from public, anon, authenticated;
grant execute on function public.sm_report_assign(uuid, uuid) to authenticated;

create or replace function public.sm_report_confirm(p_id uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.sm_reports;
  v_admin boolean;
  cname text;
begin
  if me.id is null or not public.allowed('reports', 'manage') then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_id for update;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if r.status <> 'review' then return jsonb_build_object('error', 'not-in-review', 'status', r.status); end if;
  v_admin := coalesce(me.is_admin, false) or me.role = 'admin';
  if r.reviewer_id is not null and r.reviewer_id <> me.id and not v_admin then
    return jsonb_build_object('error', 'not-reviewer');
  end if;
  if r.submitted_by = me.id and not v_admin then
    return jsonb_build_object('error', 'self-confirm');
  end if;
  perform set_config('adspace.sm_fn', 'on', true);
  update public.sm_reports set status = 'confirmed', confirmed_by = me.id, confirmed_at = now() where id = p_id;
  perform set_config('adspace.sm_fn', 'off', true);
  perform public.sm_report_log(p_id, 'report.confirmed',
    case when r.reviewer_id is not null and r.reviewer_id <> me.id
         then 'in place of ' || (select name from public.team_members where id = r.reviewer_id) end);
  select c.name into cname from public.clients c where c.id = r.client_id;
  perform public.sm_report_notify(r.submitted_by, p_id, 'report.confirmed', 'Report confirmed',
    cname || ' · ' || public.sm_period_word(r.period_start, r.period_end));
  return jsonb_build_object('ok', true, 'status', 'confirmed');
end $$;
revoke all on function public.sm_report_confirm(uuid) from public, anon, authenticated;
grant execute on function public.sm_report_confirm(uuid) to authenticated;

create or replace function public.sm_report_return(p_id uuid, p_note text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.sm_reports;
  cname text;
begin
  if me.id is null or not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_id for update;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if r.status not in ('review', 'confirmed') then return jsonb_build_object('error', 'not-returnable', 'status', r.status); end if;
  if r.status = 'review' and r.reviewer_id is not null then
    -- The reviewer sends it back, an admin may, and the submitter takes it back.
    if not (me.id = r.reviewer_id or me.id = r.submitted_by
            or ((coalesce(me.is_admin, false) or me.role = 'admin') and public.allowed('reports', 'manage'))) then
      return jsonb_build_object('error', 'not-reviewer');
    end if;
  elsif not public.allowed('reports', 'manage')
     and not (r.status = 'review' and r.submitted_by = me.id) then
    return jsonb_build_object('error', 'denied');
  end if;
  if coalesce(btrim(p_note), '') = '' then return jsonb_build_object('error', 'note-required'); end if;
  perform set_config('adspace.sm_fn', 'on', true);
  update public.sm_reports set status = 'draft', return_note = btrim(p_note),
    confirmed_by = null, confirmed_at = null where id = p_id;
  perform set_config('adspace.sm_fn', 'off', true);
  perform public.sm_report_log(p_id, 'report.returned', btrim(p_note));
  select c.name into cname from public.clients c where c.id = r.client_id;
  perform public.sm_report_notify(r.submitted_by, p_id, 'report.returned', 'Report sent back',
    cname || ' · ' || public.sm_period_word(r.period_start, r.period_end) || ' · ' || btrim(p_note));
  return jsonb_build_object('ok', true, 'status', 'draft');
end $$;
revoke all on function public.sm_report_return(uuid, text) from public, anon, authenticated;
grant execute on function public.sm_report_return(uuid, text) to authenticated;

create or replace function public.activity_section(p_action text)
returns text
language sql immutable parallel safe as $$
  select case
    when action in ('campaign.bulk', 'campaign.closed', 'campaign.confirmed',
                    'campaign.created', 'campaign.dates', 'campaign.deleted', 'campaign.edited',
                    'campaign.file_added', 'campaign.qc',
                    'campaign.invoice', 'campaign.invoice_file',
                    'campaign.invoice_removed', 'campaign.keyed', 'campaign.locked',
                    'campaign.opened', 'campaign.rate', 'campaign.rated',
                    'campaign.reinstated', 'campaign.replaced', 'campaign.results', 'campaign.review',
                    'campaign.stage', 'campaign.submitted', 'campaign.task_linked',
                    'campaign.task_unlinked', 'campaign.unbooked',
                    'campaign.unkeyed', 'campaign.withdrawn', 'creator.added',
                    'creator.code', 'creator.links', 'creator.links_restored',
                    'creator.links_self', 'creator.off', 'creator.on', 'creator.removed',
                    'creator.updated') then 'campaigns'
    when action in ('client.action_done', 'client.action_reopened', 'client.added',
                    'client.billing', 'client.brand', 'client.deleted', 'client.edited',
                    'client.review_on', 'client.service', 'client.service_changed',
                    'client.service_removed', 'client.stage', 'client.touch',
                    'client.touch_edited', 'client.touch_removed',
                    'client.touch_restored', 'contact.added', 'contact.deleted',
                    'contact.edited', 'contact.portal_invite', 'contact.portal_off',
                    'contact.portal_on', 'contact.primary', 'contact.removed',
                    'contact.restored',
                    'request.changed', 'request.raised',
                    'request.reinstated', 'request.replied', 'request.withdrawn',
                    'service.override') then 'clients'
    when action in ('report.ai_drafted', 'report.ai_failed', 'report.confirmed',
                    'report.created', 'report.deleted', 'report.published',
                    'report.reassigned', 'report.returned', 'report.revised', 'report.saved',
                    'report.submitted', 'report.unpublished') then 'reports'
    when action in ('qr.created', 'qr.restored', 'qr.revoked', 'shortlink.created',
                    'shortlink.deleted', 'shortlink.imported', 'shortlink.updated') then 'links'
    when action in ('ops.deleted', 'ops.month_deleted', 'ops.numbering') then 'ops'
    when action in ('document.deleted', 'document.issued', 'document.reissued',
                    'document.restored', 'document.signed', 'document.superseded',
                    'document.unsigned', 'document.verified', 'document.voided',
                    'register.added', 'register.edited') then 'register'
    when action in ('client.drive', 'client.handles', 'client.profile',
                    'client.removed', 'drive.imported', 'link.reset', 'post.added',
                    'post.deleted', 'post.edited', 'reapproval.requested',
                    'review.approved', 'review.changes', 'review.removed',
                    'review.unconfirmed',
                    'set.created', 'set.deleted', 'set.published', 'set.renamed',
                    'set.task_linked', 'set.task_unlinked',
                    'set.withdrawn') then 'review'
    when action in ('handbook.added', 'handbook.archived', 'handbook.deleted',
                    'handbook.edited', 'handbook.restored', 'handbook.version') then 'handbook'
    when action in ('service.added', 'service.changed', 'service.deleted',
                    'service.off', 'service.on') then 'services'
    when action in ('team.added', 'team.changed', 'team.edited', 'team.group_added',
                    'team.group_changed', 'team.group_removed', 'team.invited') then 'team'
    else 'other'
  end
  from (select p_action as action) t
$$;
grant execute on function public.activity_section(text) to authenticated;

-- END OF REPORT REVIEWER -----------------------------------------------------

-- ===========================================================================
-- DRAFT WITH AI ALLOWANCES — an admin sees every colleague's use of Draft
-- with AI and sets how many drafts a day each may take, the team's included.
-- 2026-10-04. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/smsql.js compares the
-- two.
--
-- WHAT CHANGED
--   1. `ai_draft_limits` holds the day's allowances: `team` (60 unless set),
--      `person` (each colleague's, 20 unless set) and one row a colleague
--      set apart from it (the colleague's id). A null daily reads the default;
--      0 stops Draft with AI. RLS on, no policy, no grants.
--   2. `ai_draft_claim` and `ai_draft_left` read them: a colleague at 0 is
--      refused `stopped`, a team at 0 `team` with no time the next is free.
--      A report's one draft and an admin's five a report a day are unchanged.
--   3. `ai_draft_usage()` (admin): each colleague who may draft or drafted in
--      the last 30 days, with the last 24 hours, 30 days, failed presses,
--      the last press and the allowance; the team's figures and defaults.
--   4. `ai_draft_set_limit(p_scope, p_daily)` (admin): `team`, `person` or a
--      colleague's id; null puts the default back. Filed `team.changed`
--      under subject Draft with AI, from and to; a set that changes nothing
--      files nothing.
--
-- ROLLBACK
--   Run the DRAFT WITH AI BY SUBJECT section's ai_draft_claim and
--   ai_draft_left again, then remove the functions ai_draft_usage(),
--   ai_draft_set_limit(text, integer) and ai_draft_limit(text, integer), and
--   the table ai_draft_limits.
-- ===========================================================================

create table if not exists public.ai_draft_limits (
  scope   text primary key,
  daily   integer check (daily is null or daily between 0 and 500),
  set_by  text,
  set_at  timestamptz not null default now()
);
alter table public.ai_draft_limits enable row level security;
revoke all on table public.ai_draft_limits from public, anon, authenticated;

-- A scope's allowance a day, else the default given.
create or replace function public.ai_draft_limit(p_scope text, p_default integer)
returns integer
language sql stable security definer set search_path = public as $$
  select coalesce((select l.daily from public.ai_draft_limits l where l.scope = p_scope), p_default)
$$;
revoke all on function public.ai_draft_limit(text, integer) from public, anon, authenticated;

create or replace function public.ai_draft_claim(p_report uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m public.team_members;
  r public.sm_reports;
  since timestamptz := now() - interval '24 hours';
  n_report integer;
  n_member integer;
  n_team integer;
  lim_member integer;
  lim_team integer;
  first_at timestamptz;
  new_id uuid;
begin
  if not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'denied'); end if;
  -- One count at a time, so two presses together cannot both take the last draft.
  perform pg_advisory_xact_lock(hashtext('ai_draft_claim'));
  select * into r from public.sm_reports where id = p_report;
  lim_member := public.ai_draft_limit(m.id::text, public.ai_draft_limit('person', 20));
  lim_team := public.ai_draft_limit('team', 60);
  if lim_member = 0 then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'stopped', 'limit', 0);
  end if;
  if lim_team = 0 then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'team', 'limit', 0);
  end if;
  -- One draft a subject; a second and later is an admin's.
  if not coalesce(m.is_admin, false) and exists (select 1 from public.ai_draft_same(p_report)) then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'redraft', 'limit', 1);
  end if;
  select count(*), min(s.created_at) into n_report, first_at from public.ai_draft_same(p_report) s
   where s.created_at > since;
  if n_report >= 5 then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'report', 'limit', 5, 'next', first_at + interval '24 hours');
  end if;
  select count(*), min(d.created_at) into n_member, first_at from public.ai_drafts d
   where d.team_member_id = m.id and d.created_at > since and d.outcome <> 'failed';
  if n_member >= lim_member then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'person', 'limit', lim_member, 'next', first_at + interval '24 hours');
  end if;
  select count(*), min(d.created_at) into n_team, first_at from public.ai_drafts d
   where d.created_at > since and d.outcome <> 'failed';
  if n_team >= lim_team then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'team', 'limit', lim_team, 'next', first_at + interval '24 hours');
  end if;
  insert into public.ai_drafts (report_id, team_member_id, client_id, kind, period_start, period_end)
  values (p_report, m.id, r.client_id, r.kind, r.period_start, r.period_end) returning id into new_id;
  return jsonb_build_object('id', new_id, 'left', lim_member - n_member - 1);
end $$;

create or replace function public.ai_draft_left(p_report uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  m public.team_members;
  since timestamptz := now() - interval '24 hours';
  is_adm boolean;
  n_report integer; n_member integer; n_team integer;
  at_report timestamptz; at_member timestamptz; at_team timestamptz;
  l_report integer; l_member integer; l_team integer; l_min integer;
  lim_member integer; lim_team integer;
  v_scope text;
begin
  if not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'denied'); end if;
  is_adm := coalesce(m.is_admin, false);
  lim_member := public.ai_draft_limit(m.id::text, public.ai_draft_limit('person', 20));
  lim_team := public.ai_draft_limit('team', 60);
  select count(*), min(s.created_at) into n_report, at_report from public.ai_draft_same(p_report) s
   where s.created_at > since;
  if is_adm then
    l_report := greatest(0, 5 - n_report);
  elsif exists (select 1 from public.ai_draft_same(p_report)) then
    l_report := 0;
  else
    l_report := 1;
  end if;
  select count(*), min(d.created_at) into n_member, at_member from public.ai_drafts d
   where d.team_member_id = m.id and d.created_at > since and d.outcome <> 'failed';
  l_member := greatest(0, lim_member - n_member);
  select count(*), min(d.created_at) into n_team, at_team from public.ai_drafts d
   where d.created_at > since and d.outcome <> 'failed';
  l_team := greatest(0, lim_team - n_team);
  l_min := least(l_report, l_member, l_team);
  v_scope := case when lim_member = 0 then 'stopped'
                  when lim_team = 0 then 'team'
                  when l_min = l_report then case when is_adm then 'report' else 'redraft' end
                  when l_min = l_member then 'person' else 'team' end;
  return jsonb_build_object(
    'left', l_min, 'scope', v_scope,
    'limit', case v_scope when 'stopped' then 0 when 'redraft' then 1 when 'report' then 5
                          when 'person' then lim_member else lim_team end,
    'report', l_report, 'person', l_member, 'team', l_team, 'admin', is_adm,
    'next', case when l_min > 0 or v_scope in ('redraft', 'stopped') or lim_team = 0 then null
                 when v_scope = 'report' then at_report + interval '24 hours'
                 when v_scope = 'person' then at_member + interval '24 hours'
                 else at_team + interval '24 hours' end);
end $$;

revoke all on function public.ai_draft_claim(uuid) from public, anon, authenticated;
revoke all on function public.ai_draft_left(uuid) from public, anon, authenticated;
grant execute on function public.ai_draft_claim(uuid) to authenticated;
grant execute on function public.ai_draft_left(uuid) to authenticated;

-- Every colleague's use and allowance, for an admin.
create or replace function public.ai_draft_usage()
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_day timestamptz := now() - interval '24 hours';
  v_month timestamptz := now() - interval '30 days';
begin
  if not public.allowed('admin') then return jsonb_build_object('error', 'denied'); end if;
  return jsonb_build_object(
    'person', public.ai_draft_limit('person', 20),
    'team', public.ai_draft_limit('team', 60),
    'team_day', (select count(*) from public.ai_drafts d where d.created_at > v_day and d.outcome <> 'failed'),
    'team_month', (select count(*) from public.ai_drafts d where d.created_at > v_month and d.outcome <> 'failed'),
    'people', coalesce((select jsonb_agg(s.x order by s.x ->> 'name') from (
      select jsonb_build_object(
        'id', t.id, 'name', t.name, 'code', t.staff_code, 'group', g.name,
        'admin', coalesce(t.is_admin, false),
        'day', (select count(*) from public.ai_drafts d where d.team_member_id = t.id and d.created_at > v_day and d.outcome <> 'failed'),
        'month', (select count(*) from public.ai_drafts d where d.team_member_id = t.id and d.created_at > v_month and d.outcome <> 'failed'),
        'failed', (select count(*) from public.ai_drafts d where d.team_member_id = t.id and d.created_at > v_month and d.outcome = 'failed'),
        'last', (select max(d.created_at) from public.ai_drafts d where d.team_member_id = t.id and d.outcome <> 'failed'),
        'limit', (select l.daily from public.ai_draft_limits l where l.scope = t.id::text)) as x
        from public.team_members t
        left join public.team_roles g on g.slug = t.role
       where t.active
         and (coalesce(t.is_admin, false) or t.role = 'admin'
              or public.level_rank(coalesce(t.access ->> 'reports', 'none')) >= public.level_rank('work')
              or exists (select 1 from public.ai_drafts d where d.team_member_id = t.id and d.created_at > v_month))
    ) s), '[]'::jsonb));
end $$;
revoke all on function public.ai_draft_usage() from public, anon, authenticated;
grant execute on function public.ai_draft_usage() to authenticated;

-- An allowance a day: the team's, each colleague's, or one colleague's.
-- Null puts the default back.
create or replace function public.ai_draft_set_limit(p_scope text, p_daily integer)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_who text;
  v_name text;
  v_was integer;
  v_def integer;
  v_scope text := btrim(coalesce(p_scope, ''));
begin
  if not public.allowed('admin') then return jsonb_build_object('error', 'denied'); end if;
  if p_daily is not null and (p_daily < 0 or p_daily > 500) then
    return jsonb_build_object('error', 'bad-limit');
  end if;
  if v_scope = 'team' then
    v_name := 'Team'; v_def := 60;
  elsif v_scope = 'person' then
    v_name := 'Each colleague'; v_def := 20;
  else
    select t.name into v_name from public.team_members t where t.id::text = v_scope;
    if v_name is null then return jsonb_build_object('error', 'not-found'); end if;
    v_def := public.ai_draft_limit('person', 20);
  end if;
  select l.daily into v_was from public.ai_draft_limits l where l.scope = v_scope;
  if v_was is not distinct from p_daily then return jsonb_build_object('ok', true, 'same', true); end if;
  select coalesce(t.name, t.email) into v_who from public.team_members t
   where lower(t.email) = lower(auth.jwt() ->> 'email') and t.active limit 1;
  insert into public.ai_draft_limits (scope, daily, set_by, set_at)
  values (v_scope, p_daily, v_who, now())
  on conflict (scope) do update set daily = excluded.daily, set_by = excluded.set_by, set_at = excluded.set_at;
  insert into public.activity_log (actor, action, subject, detail)
  values (coalesce(v_who, 'admin'), 'team.changed', 'Draft with AI',
          v_name || ': ' ||
          case when v_was is null then 'default, ' || v_def || ' a day' when v_was = 0 then 'stopped' else v_was || ' a day' end ||
          ' → ' ||
          case when p_daily is null then 'default, ' || v_def || ' a day' when p_daily = 0 then 'stopped' else p_daily || ' a day' end);
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.ai_draft_set_limit(text, integer) from public, anon, authenticated;
grant execute on function public.ai_draft_set_limit(text, integer) to authenticated;

-- END OF DRAFT WITH AI ALLOWANCES --------------------------------------------

-- ===========================================================================
-- MONTH REPORTS — a client's month says which reports it owes (Accounts,
-- Advertising, both or none) and on which day it starts; each report ticked
-- is a task in the month, due seven days after the month ends.
-- 2026-10-04. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/ops.js compares the
-- two.
--
-- WHAT CHANGED
--   1. `ops_engagements.reports` (`social` the Accounts report, `ads` the
--      Advertising report; empty for a client owed neither) and
--      `ops_engagements.start_day` (1 to 28; a month starting on the 16th
--      runs to the 15th of the next). A new month takes both from the
--      client's month before unless it names them, so a change of start day
--      carries forward from the month it is made on, never backwards.
--   2. `ops_month_span(period, day)`: the first and last day of a month.
--   3. `ops_engagement_sync_reports(month, moved)`: each report ticked has
--      one live task on the everyday workflow, named Accounts report or
--      Advertising report, its format Report, its owner the month's manager,
--      its first draft due at 23:59 MYT five days after the month's last day
--      and its final seven days after (`source_type` `report_social` /
--      `report_ads`). A report unticked cancels its task while it is still To
--      do and keeps one already started. Only a start day moved (`moved`)
--      moves an open task's dates, filed as date changes; any other save
--      leaves a date somebody moved alone.
--   4. `ops_engagement_upsert` takes `reports` and `start_day` and syncs.
--
-- ROLLBACK
--   Run the READINESS IS THE FIRST MONTH'S section's ops_engagement_upsert
--   again, remove the functions ops_engagement_sync_reports(uuid, boolean) and
--   ops_month_span(text, integer), then
--   alter table public.ops_engagements drop column if exists reports,
--     drop column if exists start_day;
-- ===========================================================================

alter table public.ops_engagements add column if not exists reports text[] not null default '{}';
alter table public.ops_engagements add column if not exists start_day smallint not null default 1;
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'ops_engagements_reports_check') then
    alter table public.ops_engagements add constraint ops_engagements_reports_check
      check (reports <@ array['social', 'ads']::text[]);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'ops_engagements_start_day_check') then
    alter table public.ops_engagements add constraint ops_engagements_start_day_check
      check (start_day between 1 and 28);
  end if;
end $$;

-- The first and last day of a month that starts on `p_day`.
create or replace function public.ops_month_span(p_period text, p_day integer)
returns table (starts date, ends date)
language sql immutable set search_path = public as $$
  select d, (d + interval '1 month')::date - 1
    from (select make_date(split_part(p_period, '-', 1)::integer, split_part(p_period, '-', 2)::integer,
                           greatest(1, least(28, coalesce(p_day, 1)))) as d) x
$$;
revoke all on function public.ops_month_span(text, integer) from public, anon, authenticated;

-- One live task a report the month asks for; a report no longer asked for
-- cancels its task while it is still To do; a start day moved moves the
-- dates of one still open.
create or replace function public.ops_engagement_sync_reports(p_engagement uuid, p_moved boolean default false)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  e public.ops_engagements;
  k text;
  v_ends date;
  v_due timestamptz;
  v_draft timestamptz;
  t public.ops_tasks;
  v_first text;
  res jsonb;
  made integer := 0;
  gone integer := 0;
begin
  select * into e from public.ops_engagements where id = p_engagement;
  if e.id is null or e.status in ('completed', 'cancelled') then
    return jsonb_build_object('made', 0, 'cancelled', 0);
  end if;
  select s.ends into v_ends from public.ops_month_span(e.period, e.start_day) s;
  v_due := ((v_ends + 7)::timestamp + time '23:59') at time zone 'Asia/Kuala_Lumpur';
  v_draft := ((v_ends + 5)::timestamp + time '23:59') at time zone 'Asia/Kuala_Lumpur';
  foreach k in array array['social', 'ads'] loop
    if k = any (e.reports) then
      if not exists (select 1 from public.ops_tasks x
                      where x.engagement_id = e.id and x.source_type = 'report_' || k
                        and x.cancelled_at is null and x.archived_at is null) then
        res := public.ops_create_task(jsonb_build_object(
          'engagement_id', e.id, 'scope', 'client', 'client_id', e.client_id,
          'workflow_key', 'task', 'task_type', 'engagement', 'deliverable_type', 'report',
          'content_desc', case k when 'social' then 'Accounts report' else 'Advertising report' end,
          'code_period', e.period, 'first_draft_due_at', v_draft, 'final_due_at', v_due,
          'source_type', 'report_' || k,
          'owner_id', e.manager_id, 'manager_id', e.manager_id));
        if res ? 'error' then
          raise exception 'report-task: %', res ->> 'error' using errcode = 'P0001';
        end if;
        made := made + 1;
      elsif p_moved then
        for t in select * from public.ops_tasks x
                  where x.engagement_id = e.id and x.source_type = 'report_' || k
                    and x.cancelled_at is null and x.archived_at is null and x.completed_at is null loop
          update public.ops_tasks set current_final_due_at = v_due,
                 current_first_draft_due_at = case when first_draft_submitted_at is null then v_draft
                                                   else current_first_draft_due_at end,
                 updated_at = now(), version = version + 1
           where id = t.id;
          if t.current_final_due_at is distinct from v_due then
            perform public.ops_log(t.id, 'due_changed',
              jsonb_build_object('kind', 'final', 'value', t.current_final_due_at),
              jsonb_build_object('kind', 'final', 'value', v_due),
              jsonb_build_object('reason', 'scope_change', 'note', 'The month''s start day moved.'));
          end if;
          if t.first_draft_submitted_at is null and t.current_first_draft_due_at is distinct from v_draft then
            perform public.ops_log(t.id, 'due_changed',
              jsonb_build_object('kind', 'first_draft', 'value', t.current_first_draft_due_at),
              jsonb_build_object('kind', 'first_draft', 'value', v_draft),
              jsonb_build_object('reason', 'scope_change', 'note', 'The month''s start day moved.'));
          end if;
        end loop;
      end if;
    else
      for t in select * from public.ops_tasks x
                where x.engagement_id = e.id and x.source_type = 'report_' || k
                  and x.cancelled_at is null and x.archived_at is null and x.completed_at is null loop
        select s.key into v_first from public.ops_workflow_stages s
         where s.workflow_id = t.workflow_id order by s.position limit 1;
        if t.stage_key = v_first then
          update public.ops_tasks set stage_key = 'cancelled', cancelled_at = now(), updated_at = now(),
                 version = version + 1
           where id = t.id;
          perform public.ops_log(t.id, 'stage_changed', jsonb_build_object('stage_key', t.stage_key),
            jsonb_build_object('stage_key', 'cancelled'),
            jsonb_build_object('note', 'The month no longer asks for this report.'));
          gone := gone + 1;
        end if;
      end loop;
    end if;
  end loop;
  return jsonb_build_object('made', made, 'cancelled', gone);
end $$;
revoke all on function public.ops_engagement_sync_reports(uuid, boolean) from public, anon, authenticated;

/* One a client a month. A second call for the same month edits the one row
   rather than making a second. The two checks are onboarding, so they are
   seeded on the client's first month and on no later one. The reports a
   month owes and its start day come from the month before unless named. */
create or replace function public.ops_engagement_upsert(p_payload jsonb)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m public.team_members;
  cid uuid;
  per text;
  eid uuid;
  k text;
  fresh boolean := false;
  prev public.ops_engagements;
  v_day integer;
  v_reports text[];
  v_was_day integer;
begin
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if not public.allowed('ops', 'work') then return jsonb_build_object('error', 'denied'); end if;
  cid := (p_payload ->> 'client_id')::uuid;
  per := p_payload ->> 'period';
  if cid is null or not exists (select 1 from public.clients where id = cid) then
    return jsonb_build_object('error', 'client-required');
  end if;
  if per is null or per !~ '^\d{4}-\d{2}$' then return jsonb_build_object('error', 'bad-period'); end if;
  if p_payload ? 'start_day' and (nullif(p_payload ->> 'start_day', '') is null
     or (p_payload ->> 'start_day') !~ '^\d{1,2}$' or (p_payload ->> 'start_day')::integer not between 1 and 28) then
    return jsonb_build_object('error', 'bad-start-day');
  end if;
  if p_payload ? 'reports' then
    if jsonb_typeof(p_payload -> 'reports') <> 'array' then return jsonb_build_object('error', 'bad-reports'); end if;
    select coalesce(array_agg(distinct x), '{}') into v_reports from jsonb_array_elements_text(p_payload -> 'reports') x;
    if not (v_reports <@ array['social', 'ads']::text[]) then return jsonb_build_object('error', 'bad-reports'); end if;
  end if;

  select e.id into eid from public.ops_engagements e where e.client_id = cid and e.period = per;
  if eid is null then
    select * into prev from public.ops_engagements o
     where o.client_id = cid and o.period < per order by o.period desc limit 1;
    v_day := coalesce((p_payload ->> 'start_day')::integer, prev.start_day, 1);
    v_reports := coalesce(v_reports, prev.reports, '{}');
    insert into public.ops_engagements (client_id, period, manager_id, planned_count, drive_url, created_by,
                                        reports, start_day)
    values (cid, per, coalesce((p_payload ->> 'manager_id')::uuid, m.id),
            coalesce((p_payload ->> 'planned_count')::integer, 0),
            nullif(p_payload ->> 'drive_url', ''), m.id, v_reports, v_day)
    on conflict (client_id, period) do nothing
    returning id into eid;
    /* Somebody else made it between the read and the write: theirs stands. */
    if eid is null then
      select e.id into eid from public.ops_engagements e where e.client_id = cid and e.period = per;
    else
      fresh := true;
    end if;
  end if;
  if fresh then
    if not exists (select 1 from public.ops_engagements o where o.client_id = cid and o.id <> eid) then
    foreach k in array array['onboarding', 'pre_ads'] loop
      insert into public.ops_engagement_checks (engagement_id, key) values (eid, k)
      on conflict do nothing;
    end loop;
    end if;
    perform public.ops_engagement_log(eid, 'created', p_payload - 'client_id');
  else
    if not public.ops_may_see_engagement(eid) then return jsonb_build_object('error', 'denied'); end if;
    /* Asked for with nothing to change, the month is answered as it stands:
       a task made for a month joins it without editing it. */
    if (p_payload - 'client_id' - 'period') = '{}'::jsonb then
      return public.ops_engagement_json(eid) || jsonb_build_object('created', false);
    end if;
    select o.start_day into v_was_day from public.ops_engagements o where o.id = eid;
    update public.ops_engagements set
      manager_id = coalesce((p_payload ->> 'manager_id')::uuid, manager_id),
      planned_count = coalesce((p_payload ->> 'planned_count')::integer, planned_count),
      drive_url = case when p_payload ? 'drive_url' then nullif(p_payload ->> 'drive_url', '') else drive_url end,
      reports = coalesce(v_reports, reports),
      start_day = coalesce((p_payload ->> 'start_day')::integer, start_day),
      updated_at = now(), version = version + 1
    where id = eid;
    perform public.ops_engagement_log(eid, 'edited', p_payload - 'client_id' - 'period');
  end if;
  perform public.ops_engagement_sync_reports(eid,
    v_was_day is not null and v_was_day is distinct from (select o.start_day from public.ops_engagements o where o.id = eid));
  return public.ops_engagement_json(eid) || jsonb_build_object('created', fresh);
end $$;
grant execute on function public.ops_engagement_upsert(jsonb) to authenticated;

-- END OF MONTH REPORTS -------------------------------------------------------

-- ===========================================================================
-- REPORT MONTH GATE — a report is submitted for review only once its month
-- is in order, and on time or with the reason it is late.
-- 2026-10-04. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/smsql.js compares the
-- two. Runs after MONTH REPORTS.
--
-- WHAT CHANGED
--   1. `sm_report_gate(p_id)` (Reports View): for a report whose period starts
--      on or after 1 Oct 2026, the client's month whose span holds the
--      report's last day, and what it lacks: `no-month` (no such month),
--      `not-ticked` (the month does not ask for this report), `no-task` (its
--      report task is not there), `content` (fewer content tasks than
--      planned; report tasks and cancelled tasks are not counted). It answers
--      the due time (the report task's, else 23:59 MYT seven days after the
--      month's last day, else after the report's), `late`, and
--      `may_override` (an admin or Reports Full Access). An earlier report is
--      not gated. A report the caller may not see answers `denied`.
--   2. `sm_report_submit(p_id, p_reviewer, p_reason)`: after the report's own
--      contents, a report that fails the gate is refused `month-gate` with
--      what it lacks, unless an admin or Reports Full Access gives a reason;
--      a late report is refused `late-reason` until a reason is given. The
--      reason is kept on the report (`late_reason`, `gate_note`) and filed
--      with the submission.
--   3. `sm_report_guard` keeps both columns to the functions.
--
-- ROLLBACK
--   Run the REPORT REVIEWER section's sm_report_guard and sm_report_submit
--   again, remove the function sm_report_gate(uuid), then
--   alter table public.sm_reports drop column if exists late_reason,
--     drop column if exists gate_note;
-- ===========================================================================

alter table public.sm_reports add column if not exists late_reason text;
alter table public.sm_reports add column if not exists gate_note text;

create or replace function public.sm_report_guard()
returns trigger
language plpgsql set search_path = public as $$
begin
  if coalesce(current_setting('adspace.sm_fn', true), '') = 'on' then
    new.updated_at := now();
    return new;
  end if;
  if new.status is distinct from old.status or new.version_no is distinct from old.version_no
     or new.submitted_by is distinct from old.submitted_by or new.submitted_at is distinct from old.submitted_at
     or new.confirmed_by is distinct from old.confirmed_by or new.confirmed_at is distinct from old.confirmed_at
     or new.return_note is distinct from old.return_note or new.client_id is distinct from old.client_id
     or new.kind is distinct from old.kind or new.reviewer_id is distinct from old.reviewer_id
     or new.late_reason is distinct from old.late_reason or new.gate_note is distinct from old.gate_note
     or new.created_by is distinct from old.created_by or new.created_at is distinct from old.created_at then
    raise exception 'sm-status-by-function' using errcode = 'P0001';
  end if;
  if old.status <> 'draft' then
    raise exception 'sm-not-draft' using errcode = 'P0001';
  end if;
  new.updated_at := now();
  return new;
end $$;
revoke all on function public.sm_report_guard() from public, anon, authenticated;

-- What a report's month lacks, and when the report is due.
create or replace function public.sm_report_gate(p_id uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.sm_reports;
  c public.clients;
  e public.ops_engagements;
  task public.ops_tasks;
  v_starts date;
  v_ends date;
  v_due timestamptz;
  v_made integer := 0;
  v_missing text[] := '{}';
begin
  if me.id is null or not public.allowed('reports', 'view') then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_id;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  select * into c from public.clients where id = r.client_id;
  if not public.client_row_seen(c.stage, c.owner, 'view') then return jsonb_build_object('error', 'denied'); end if;
  if r.period_start < date '2026-10-01' then
    return jsonb_build_object('applies', false, 'ok', true, 'missing', '[]'::jsonb);
  end if;
  select x.* into e from public.ops_engagements x
   cross join lateral public.ops_month_span(x.period, x.start_day) s
   where x.client_id = r.client_id and x.status <> 'cancelled'
     and r.period_end between s.starts and s.ends
   order by x.period desc limit 1;
  if e.id is null then
    v_missing := v_missing || 'no-month'::text;
    v_due := ((r.period_end + 7)::timestamp + time '23:59') at time zone 'Asia/Kuala_Lumpur';
  else
    select s.starts, s.ends into v_starts, v_ends from public.ops_month_span(e.period, e.start_day) s;
    v_due := ((v_ends + 7)::timestamp + time '23:59') at time zone 'Asia/Kuala_Lumpur';
    if not (r.kind = any (e.reports)) then
      v_missing := v_missing || 'not-ticked'::text;
    else
      select * into task from public.ops_tasks x
       where x.engagement_id = e.id and x.source_type = 'report_' || r.kind
         and x.cancelled_at is null and x.archived_at is null
       order by x.created_at desc limit 1;
      if task.id is null then
        v_missing := v_missing || 'no-task'::text;
      else
        v_due := coalesce(task.current_final_due_at, v_due);
      end if;
    end if;
    select count(*) into v_made from public.ops_tasks x
     where x.engagement_id = e.id and x.cancelled_at is null and x.archived_at is null
       and coalesce(x.source_type, '') not in ('report_social', 'report_ads');
    if v_made < e.planned_count then v_missing := v_missing || 'content'::text; end if;
  end if;
  return jsonb_build_object(
    'applies', true, 'ok', cardinality(v_missing) = 0, 'missing', to_jsonb(v_missing),
    'month', case when e.id is null then null else jsonb_build_object(
               'id', e.id, 'period', e.period, 'start_day', e.start_day, 'starts', v_starts, 'ends', v_ends,
               'reports', to_jsonb(e.reports)) end,
    'planned', coalesce(e.planned_count, 0), 'made', v_made,
    'task', case when task.id is null then null else jsonb_build_object(
              'id', task.id, 'task_no', task.task_no, 'stage_key', task.stage_key) end,
    'due', v_due, 'late', now() > v_due,
    'may_override', coalesce(me.is_admin, false) or me.role = 'admin' or public.allowed('reports', 'manage'));
end $$;
revoke all on function public.sm_report_gate(uuid) from public, anon, authenticated;
grant execute on function public.sm_report_gate(uuid) to authenticated;

/* `p_reason` is the reason a late submit, or one past the month's gate,
   gives; it is read from MONTH REPORTS (2026-10-04) on. */
create or replace function public.sm_report_submit(p_id uuid, p_reviewer uuid default null, p_reason text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.sm_reports;
  cname text;
  g jsonb;
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
  v_gate text;
  v_late text;
  v_extra text := '';
begin
  if me.id is null or not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_id for update;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if r.status <> 'draft' then return jsonb_build_object('error', 'not-draft', 'status', r.status); end if;
  if r.kind = 'ads' then
    if not exists (select 1 from public.sm_report_ads where report_id = p_id) then
      return jsonb_build_object('error', 'no-ads');
    end if;
  else
    if not exists (select 1 from public.sm_report_platforms where report_id = p_id) then
      return jsonb_build_object('error', 'no-platforms');
    end if;
    if not exists (select 1 from public.sm_report_posts where report_id = p_id) then
      return jsonb_build_object('error', 'no-posts');
    end if;
  end if;
  g := public.sm_report_gate(p_id);
  if coalesce((g ->> 'applies')::boolean, false) then
    if not (g ->> 'ok')::boolean then
      if not (g ->> 'may_override')::boolean or v_reason is null then
        return jsonb_build_object('error', 'month-gate', 'missing', g -> 'missing', 'planned', g -> 'planned',
                                  'made', g -> 'made', 'may_override', g -> 'may_override');
      end if;
      v_gate := left(v_reason, 500);
    end if;
    if (g ->> 'late')::boolean then
      if v_reason is null then
        return jsonb_build_object('error', 'late-reason', 'due', g -> 'due');
      end if;
      v_late := left(v_reason, 500);
    end if;
  end if;
  if p_reviewer is null then return jsonb_build_object('error', 'no-reviewer'); end if;
  if p_reviewer = me.id then return jsonb_build_object('error', 'self-review'); end if;
  if not public.sm_report_may_review(p_reviewer) then return jsonb_build_object('error', 'bad-reviewer'); end if;
  perform set_config('adspace.sm_fn', 'on', true);
  update public.sm_reports set status = 'review', submitted_by = me.id, submitted_at = now(),
    reviewer_id = p_reviewer, return_note = null, confirmed_by = null, confirmed_at = null,
    late_reason = v_late, gate_note = v_gate where id = p_id;
  perform set_config('adspace.sm_fn', 'off', true);
  if v_gate is not null then v_extra := v_extra || ' · Past the month''s gate: ' || v_gate; end if;
  if v_late is not null and v_gate is distinct from v_late then v_extra := v_extra || ' · Late: ' || v_late;
  elsif v_late is not null then v_extra := v_extra || ' · Late'; end if;
  perform public.sm_report_log(p_id, 'report.submitted',
    'Reviewer: ' || (select name from public.team_members where id = p_reviewer) || v_extra);
  select c.name into cname from public.clients c where c.id = r.client_id;
  perform public.sm_report_notify(p_reviewer, p_id, 'report.review', 'Report to review',
    cname || ' · ' || public.sm_period_word(r.period_start, r.period_end));
  return jsonb_build_object('ok', true, 'status', 'review');
end $$;
revoke all on function public.sm_report_submit(uuid, uuid, text) from public, anon, authenticated;
grant execute on function public.sm_report_submit(uuid, uuid, text) to authenticated;

-- END OF REPORT MONTH GATE ---------------------------------------------------

-- ===========================================================================
-- MONTH COUNTS LEAVE REPORTS OUT — the count of what a month holds against
-- its plan leaves out the report tasks the month makes for itself.
-- 2026-10-04. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/ops.js compares the
-- two. Runs after MONTH REPORTS.
--
-- WHAT CHANGED
--   `ops_engagement_counts` adds `content`: the month's live tasks less its
--   report tasks (`report_social`, `report_ads`), as the report's month gate
--   counts them. The New sheet reads it as "n added" against the pieces
--   planned. `live`, `open` and `done` still count every task, so a month
--   stays in production until its report is done.
--
-- ROLLBACK
--   Run the MONTH STAGES FOLLOW THE WORK section's ops_engagement_counts
--   again.
-- ===========================================================================

/* A month's tasks, counted over the whole month whoever asks: live (not
   cancelled), open (not finished), done (completed), and content (live, less
   the report tasks the month makes for itself). Only months the caller may
   see answer. */
create or replace function public.ops_engagement_counts(p_engagements uuid[])
returns jsonb
language sql security definer stable set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'engagement_id', e.id,
           'live', (select count(*) from public.ops_tasks t
                     where t.engagement_id = e.id and t.archived_at is null
                       and t.cancelled_at is null),
           'open', (select count(*) from public.ops_tasks t
                     where t.engagement_id = e.id and t.archived_at is null
                       and t.cancelled_at is null and t.completed_at is null),
           'done', (select count(*) from public.ops_tasks t
                     where t.engagement_id = e.id and t.archived_at is null
                       and t.cancelled_at is null and t.completed_at is not null),
           'content', (select count(*) from public.ops_tasks t
                        where t.engagement_id = e.id and t.archived_at is null
                          and t.cancelled_at is null
                          and coalesce(t.source_type, '') not in ('report_social', 'report_ads')))), '[]'::jsonb)
    from public.ops_engagements e
   where e.id = any (coalesce(p_engagements, '{}'::uuid[]))
     and public.ops_may_see_engagement(e.id)
$$;
revoke all on function public.ops_engagement_counts(uuid[]) from public, anon;
grant execute on function public.ops_engagement_counts(uuid[]) to authenticated;

-- END OF MONTH COUNTS LEAVE REPORTS OUT ----------------------------------------

-- ===========================================================================
-- A DELETED MONTH TAKES ITS REPORT TASKS — the report tasks a month made for
-- itself and nobody has started are cancelled when the month is deleted.
-- 2026-10-04. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/ops.js compares the
-- two. Runs after MONTH REPORTS.
--
-- WHAT CHANGED
--   1. `ops_engagement_cancel_reports(month, kinds, note)`: each of the
--      month's open report tasks of those kinds still at its workflow's first
--      stage is cancelled, filed with the note; one already started is kept.
--      One copy, used by the two below.
--   2. `ops_engagement_sync_reports` cancels a report unticked through it.
--   3. `ops_delete_engagement` cancels both kinds through it before the month
--      goes ("The month was deleted."), so a month keyed for the wrong client
--      or period leaves no report owed behind. Every other task leaves the
--      month as before, and the record counts the reports cancelled.
--
-- ROLLBACK
--   Run the MONTH REPORTS section's ops_engagement_sync_reports and THE
--   MONTH IN TWO TICKS section's ops_delete_engagement again, then remove
--   the function ops_engagement_cancel_reports(uuid, text[], text).
-- ===========================================================================

-- A month's report tasks nobody has started, cancelled with a note.
create or replace function public.ops_engagement_cancel_reports(p_engagement uuid, p_kinds text[], p_note text)
returns integer
language plpgsql security definer set search_path = public as $$
declare
  t public.ops_tasks;
  v_first text;
  gone integer := 0;
begin
  for t in select * from public.ops_tasks x
            where x.engagement_id = p_engagement
              and x.source_type in (select 'report_' || k from unnest(coalesce(p_kinds, '{}'::text[])) k)
              and x.cancelled_at is null and x.archived_at is null and x.completed_at is null loop
    select s.key into v_first from public.ops_workflow_stages s
     where s.workflow_id = t.workflow_id order by s.position limit 1;
    if t.stage_key = v_first then
      update public.ops_tasks set stage_key = 'cancelled', cancelled_at = now(), updated_at = now(),
             version = version + 1
       where id = t.id;
      perform public.ops_log(t.id, 'stage_changed', jsonb_build_object('stage_key', t.stage_key),
        jsonb_build_object('stage_key', 'cancelled'), jsonb_build_object('note', p_note));
      gone := gone + 1;
    end if;
  end loop;
  return gone;
end $$;
revoke all on function public.ops_engagement_cancel_reports(uuid, text[], text) from public, anon, authenticated;

-- One live task a report the month asks for; a report no longer asked for
-- cancels its task while it is still To do; a start day moved moves the
-- dates of one still open.
create or replace function public.ops_engagement_sync_reports(p_engagement uuid, p_moved boolean default false)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  e public.ops_engagements;
  k text;
  v_ends date;
  v_due timestamptz;
  v_draft timestamptz;
  t public.ops_tasks;
  res jsonb;
  made integer := 0;
  gone integer := 0;
begin
  select * into e from public.ops_engagements where id = p_engagement;
  if e.id is null or e.status in ('completed', 'cancelled') then
    return jsonb_build_object('made', 0, 'cancelled', 0);
  end if;
  select s.ends into v_ends from public.ops_month_span(e.period, e.start_day) s;
  v_due := ((v_ends + 7)::timestamp + time '23:59') at time zone 'Asia/Kuala_Lumpur';
  v_draft := ((v_ends + 5)::timestamp + time '23:59') at time zone 'Asia/Kuala_Lumpur';
  foreach k in array array['social', 'ads'] loop
    if k = any (e.reports) then
      if not exists (select 1 from public.ops_tasks x
                      where x.engagement_id = e.id and x.source_type = 'report_' || k
                        and x.cancelled_at is null and x.archived_at is null) then
        res := public.ops_create_task(jsonb_build_object(
          'engagement_id', e.id, 'scope', 'client', 'client_id', e.client_id,
          'workflow_key', 'task', 'task_type', 'engagement', 'deliverable_type', 'report',
          'content_desc', case k when 'social' then 'Accounts report' else 'Advertising report' end,
          'code_period', e.period, 'first_draft_due_at', v_draft, 'final_due_at', v_due,
          'source_type', 'report_' || k,
          'owner_id', e.manager_id, 'manager_id', e.manager_id));
        if res ? 'error' then
          raise exception 'report-task: %', res ->> 'error' using errcode = 'P0001';
        end if;
        made := made + 1;
      elsif p_moved then
        for t in select * from public.ops_tasks x
                  where x.engagement_id = e.id and x.source_type = 'report_' || k
                    and x.cancelled_at is null and x.archived_at is null and x.completed_at is null loop
          update public.ops_tasks set current_final_due_at = v_due,
                 current_first_draft_due_at = case when first_draft_submitted_at is null then v_draft
                                                   else current_first_draft_due_at end,
                 updated_at = now(), version = version + 1
           where id = t.id;
          if t.current_final_due_at is distinct from v_due then
            perform public.ops_log(t.id, 'due_changed',
              jsonb_build_object('kind', 'final', 'value', t.current_final_due_at),
              jsonb_build_object('kind', 'final', 'value', v_due),
              jsonb_build_object('reason', 'scope_change', 'note', 'The month''s start day moved.'));
          end if;
          if t.first_draft_submitted_at is null and t.current_first_draft_due_at is distinct from v_draft then
            perform public.ops_log(t.id, 'due_changed',
              jsonb_build_object('kind', 'first_draft', 'value', t.current_first_draft_due_at),
              jsonb_build_object('kind', 'first_draft', 'value', v_draft),
              jsonb_build_object('reason', 'scope_change', 'note', 'The month''s start day moved.'));
          end if;
        end loop;
      end if;
    else
      gone := gone + public.ops_engagement_cancel_reports(e.id, array[k], 'The month no longer asks for this report.');
    end if;
  end loop;
  return jsonb_build_object('made', made, 'cancelled', gone);
end $$;
revoke all on function public.ops_engagement_sync_reports(uuid, boolean) from public, anon, authenticated;

/* A month keyed in for the wrong client or the wrong period has to be able
   to go. ops Manage, a reason, and a row in the activity record, because the
   month's own history goes with it. Its tasks are not deleted: they stay, with
   their codes, and simply leave the month; the report tasks it made and
   nobody has started are cancelled first. */
create or replace function public.ops_delete_engagement(p_engagement uuid, p_reason text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m  public.team_members;
  e  public.ops_engagements;
  cl text;
  n  integer;
  v_gone integer;
begin
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if not public.allowed('ops', 'manage') then return jsonb_build_object('error', 'denied'); end if;
  if not public.ops_may_see_engagement(p_engagement) then return jsonb_build_object('error', 'denied'); end if;
  if nullif(btrim(coalesce(p_reason, '')), '') is null then
    return jsonb_build_object('error', 'reason-required');
  end if;
  select * into e from public.ops_engagements where id = p_engagement for update;
  if e.id is null then return jsonb_build_object('error', 'not-found'); end if;
  select c.name into cl from public.clients c where c.id = e.client_id;
  v_gone := public.ops_engagement_cancel_reports(e.id, array['social', 'ads'], 'The month was deleted.');
  select count(*) into n from public.ops_tasks t where t.engagement_id = e.id;

  insert into public.activity_log (actor, action, subject, detail)
  values (coalesce(m.name, m.email), 'ops.month_deleted', coalesce(cl, 'Client'),
          to_char(to_date(e.period || '-01', 'YYYY-MM-DD'), 'Mon YYYY') ||
          case when n = 1 then ' · 1 task left the month'
               when n > 1 then ' · ' || n || ' tasks left the month' else '' end ||
          case when v_gone = 1 then ' · 1 report task cancelled'
               when v_gone > 1 then ' · ' || v_gone || ' report tasks cancelled' else '' end ||
          ' · ' || btrim(p_reason));

  delete from public.ops_engagements where id = e.id;
  return jsonb_build_object('deleted', true, 'period', e.period, 'tasks', n, 'cancelled', v_gone);
end $$;
grant execute on function public.ops_delete_engagement(uuid, text) to authenticated;

-- END OF A DELETED MONTH TAKES ITS REPORT TASKS -------------------------------

-- ===========================================================================
-- DRAFT WITH AI RESETS AT MIDNIGHT — a colleague's drafts are counted from
-- 12:00 am Malaysia time and start again each midnight; the team's and a
-- group's totals are the sum of their colleagues' limits.
-- 2026-10-04. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/smsql.js compares the
-- two. Runs after DRAFT WITH AI ALLOWANCES.
--
-- WHAT CHANGED (the user, 2026-10-04: reset at midnight, like a usage page;
-- set only each person's limit and let the totals add up)
--   1. `ai_draft_claim` and `ai_draft_left` count a colleague's drafts and a
--      report's from today's 12:00 am MYT, not the last 24 hours; the next
--      draft is free at the next midnight. The team's own cap is gone: the
--      team can draft only what its colleagues' limits add up to.
--   2. `ai_draft_usage()` answers the reset (`resets_at`) and, for every
--      colleague who may draft or drafted in 30 days, today's count, the
--      limit that applies (`cap`, their own else the standard) and their
--      group; the page adds up the team and each group.
--   3. The limits a report has are settings too (the user, 2026-10-04:
--      nothing hard coded): `report`, the drafts a report may have from a
--      colleague (1 unless set), and `report_admin`, an admin's drafts a
--      report a day (5 unless set).
--   4. `ai_draft_set_limit` takes `person` (the standard), a colleague's id,
--      `report` or `report_admin`; `team` is refused (`bad-scope`).
--
-- ROLLBACK
--   Run the DRAFT WITH AI ALLOWANCES section's ai_draft_claim,
--   ai_draft_left, ai_draft_usage and ai_draft_set_limit again.
-- ===========================================================================

-- Today's 12:00 am in Malaysia, the start of every count.
create or replace function public.ai_draft_day()
returns timestamptz
language sql stable set search_path = public as $$
  select (date_trunc('day', now() at time zone 'Asia/Kuala_Lumpur')) at time zone 'Asia/Kuala_Lumpur'
$$;
revoke all on function public.ai_draft_day() from public, anon, authenticated;

create or replace function public.ai_draft_claim(p_report uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m public.team_members;
  r public.sm_reports;
  since timestamptz := public.ai_draft_day();
  n_report integer;
  n_member integer;
  lim_member integer;
  lim_report integer := public.ai_draft_limit('report', 1);
  lim_admin integer := public.ai_draft_limit('report_admin', 5);
  new_id uuid;
begin
  if not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'denied'); end if;
  -- One count at a time, so two presses together cannot both take the last draft.
  perform pg_advisory_xact_lock(hashtext('ai_draft_claim'));
  select * into r from public.sm_reports where id = p_report;
  lim_member := public.ai_draft_limit(m.id::text, public.ai_draft_limit('person', 20));
  if lim_member = 0 then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'stopped', 'limit', 0);
  end if;
  -- A report's drafts from a colleague; past them, the rest are an admin's.
  if not coalesce(m.is_admin, false) and (select count(*) from public.ai_draft_same(p_report)) >= lim_report then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'redraft', 'limit', lim_report);
  end if;
  select count(*) into n_report from public.ai_draft_same(p_report) s where s.created_at >= since;
  if coalesce(m.is_admin, false) and n_report >= lim_admin then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'report', 'limit', lim_admin, 'next', since + interval '1 day');
  end if;
  select count(*) into n_member from public.ai_drafts d
   where d.team_member_id = m.id and d.created_at >= since and d.outcome <> 'failed';
  if n_member >= lim_member then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'person', 'limit', lim_member, 'next', since + interval '1 day');
  end if;
  insert into public.ai_drafts (report_id, team_member_id, client_id, kind, period_start, period_end)
  values (p_report, m.id, r.client_id, r.kind, r.period_start, r.period_end) returning id into new_id;
  return jsonb_build_object('id', new_id, 'left', lim_member - n_member - 1);
end $$;

create or replace function public.ai_draft_left(p_report uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  m public.team_members;
  since timestamptz := public.ai_draft_day();
  is_adm boolean;
  n_report integer; n_member integer;
  l_report integer; l_member integer; l_min integer;
  lim_member integer;
  lim_report integer := public.ai_draft_limit('report', 1);
  lim_admin integer := public.ai_draft_limit('report_admin', 5);
  v_scope text;
begin
  if not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'denied'); end if;
  is_adm := coalesce(m.is_admin, false);
  lim_member := public.ai_draft_limit(m.id::text, public.ai_draft_limit('person', 20));
  select count(*) into n_report from public.ai_draft_same(p_report) s where s.created_at >= since;
  if is_adm then
    l_report := greatest(0, lim_admin - n_report);
  else
    l_report := greatest(0, lim_report - (select count(*) from public.ai_draft_same(p_report))::integer);
  end if;
  select count(*) into n_member from public.ai_drafts d
   where d.team_member_id = m.id and d.created_at >= since and d.outcome <> 'failed';
  l_member := greatest(0, lim_member - n_member);
  l_min := least(l_report, l_member);
  v_scope := case when lim_member = 0 then 'stopped'
                  when l_min = l_report then case when is_adm then 'report' else 'redraft' end
                  else 'person' end;
  return jsonb_build_object(
    'left', l_min, 'scope', v_scope,
    'limit', case v_scope when 'stopped' then 0 when 'redraft' then lim_report when 'report' then lim_admin else lim_member end,
    'report', l_report, 'person', l_member, 'admin', is_adm,
    'next', case when l_min > 0 or v_scope in ('redraft', 'stopped') then null else since + interval '1 day' end);
end $$;

revoke all on function public.ai_draft_claim(uuid) from public, anon, authenticated;
revoke all on function public.ai_draft_left(uuid) from public, anon, authenticated;
grant execute on function public.ai_draft_claim(uuid) to authenticated;
grant execute on function public.ai_draft_left(uuid) to authenticated;

-- Every colleague's use today against their limit, for an admin.
create or replace function public.ai_draft_usage()
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_day timestamptz := public.ai_draft_day();
  v_month timestamptz := now() - interval '30 days';
  v_std integer := public.ai_draft_limit('person', 20);
begin
  if not public.allowed('admin') then return jsonb_build_object('error', 'denied'); end if;
  return jsonb_build_object(
    'person', v_std,
    'report', public.ai_draft_limit('report', 1),
    'report_admin', public.ai_draft_limit('report_admin', 5),
    'resets_at', v_day + interval '1 day',
    'people', coalesce((select jsonb_agg(s.x order by s.x ->> 'name') from (
      select jsonb_build_object(
        'id', t.id, 'name', t.name, 'code', t.staff_code, 'group', g.name, 'group_slug', t.role,
        'admin', coalesce(t.is_admin, false),
        'day', (select count(*) from public.ai_drafts d where d.team_member_id = t.id and d.created_at >= v_day and d.outcome <> 'failed'),
        'month', (select count(*) from public.ai_drafts d where d.team_member_id = t.id and d.created_at > v_month and d.outcome <> 'failed'),
        'limit', (select l.daily from public.ai_draft_limits l where l.scope = t.id::text),
        'cap', coalesce((select l.daily from public.ai_draft_limits l where l.scope = t.id::text), v_std)) as x
        from public.team_members t
        left join public.team_roles g on g.slug = t.role
       where t.active
         and (coalesce(t.is_admin, false) or t.role = 'admin'
              or public.level_rank(coalesce(t.access ->> 'reports', 'none')) >= public.level_rank('work')
              or exists (select 1 from public.ai_drafts d where d.team_member_id = t.id and d.created_at > v_month))
    ) s), '[]'::jsonb));
end $$;
revoke all on function public.ai_draft_usage() from public, anon, authenticated;
grant execute on function public.ai_draft_usage() to authenticated;

-- A colleague's limit a day, or the standard for everyone. Null puts the
-- standard back.
create or replace function public.ai_draft_set_limit(p_scope text, p_daily integer)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_who text;
  v_name text;
  v_was integer;
  v_def integer;
  v_unit text := ' a day';
  v_scope text := btrim(coalesce(p_scope, ''));
begin
  if not public.allowed('admin') then return jsonb_build_object('error', 'denied'); end if;
  if p_daily is not null and (p_daily < 0 or p_daily > 500) then
    return jsonb_build_object('error', 'bad-limit');
  end if;
  if v_scope = 'person' then
    v_name := 'Each colleague'; v_def := 20;
  elsif v_scope = 'report' then
    v_name := 'Drafts per report'; v_def := 1; v_unit := '';
  elsif v_scope = 'report_admin' then
    v_name := 'Admin drafts per report'; v_def := 5;
  elsif v_scope = 'team' then
    return jsonb_build_object('error', 'bad-scope');
  else
    select t.name into v_name from public.team_members t where t.id::text = v_scope;
    if v_name is null then return jsonb_build_object('error', 'not-found'); end if;
    v_def := public.ai_draft_limit('person', 20);
  end if;
  select l.daily into v_was from public.ai_draft_limits l where l.scope = v_scope;
  if v_was is not distinct from p_daily then return jsonb_build_object('ok', true, 'same', true); end if;
  select coalesce(t.name, t.email) into v_who from public.team_members t
   where lower(t.email) = lower(auth.jwt() ->> 'email') and t.active limit 1;
  insert into public.ai_draft_limits (scope, daily, set_by, set_at)
  values (v_scope, p_daily, v_who, now())
  on conflict (scope) do update set daily = excluded.daily, set_by = excluded.set_by, set_at = excluded.set_at;
  insert into public.activity_log (actor, action, subject, detail)
  values (coalesce(v_who, 'admin'), 'team.changed', 'AI',
          v_name || ': ' ||
          case when v_was is null then 'standard, ' || v_def || v_unit when v_was = 0 then 'stopped' else v_was || v_unit end ||
          ' → ' ||
          case when p_daily is null then 'standard, ' || v_def || v_unit when p_daily = 0 then 'stopped' else p_daily || v_unit end);
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.ai_draft_set_limit(text, integer) from public, anon, authenticated;
grant execute on function public.ai_draft_set_limit(text, integer) to authenticated;

-- END OF DRAFT WITH AI RESETS AT MIDNIGHT -------------------------------------

-- ===========================================================================
-- AI CHECKS A REPORT AGAINST ITS FIGURES — on Check and submit, the
-- commentary as it stands (drafted or written by hand) is read against the
-- report's own figures, and what does not hold is listed for the team.
-- 2026-10-04. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/smsql.js compares the
-- two. Runs after DRAFT WITH AI RESETS AT MIDNIGHT.
--
-- WHAT CHANGED (the user, 2026-10-04: a check on the last step, reading the
-- draft as it stands, original or edited)
--   1. `ai_drafts.purpose` tells a draft from a check; `result` keeps a
--      check's findings and `basis` the commentary it read. A check that
--      came back is `drafted` (done), as a draft is.
--   2. `ai_check_claim(p_report)`: Reports Work, a report in draft or in
--      review the caller may see; it counts toward the colleague's day
--      (their own limit, else the standard) and never toward a report's
--      drafts.
--   3. `ai_check_done(p_id, p_ok, p_result, p_basis)`: the caller's own
--      pending check, written once.
--   4. `ai_check_last(p_report)`: Reports View on a report the caller may
--      see; the last check that came back, who ran it and when.
--   5. `ai_draft_same` counts drafts only.
--
-- ROLLBACK
--   Run the DRAFT WITH AI COUNTED BY SUBJECT section's ai_draft_same again;
--   then, in the SQL Editor, drop the three ai_check_ functions. The three
--   columns may stay.
-- ===========================================================================

alter table public.ai_drafts add column if not exists purpose text not null default 'draft'
  constraint ai_drafts_purpose check (purpose in ('draft', 'check'));
alter table public.ai_drafts add column if not exists result jsonb;
alter table public.ai_drafts add column if not exists basis jsonb;
create index if not exists ai_drafts_check_idx on public.ai_drafts (report_id, purpose, created_at);

create or replace function public.ai_draft_same(p_report uuid)
returns setof public.ai_drafts
language sql stable security definer set search_path = public as $$
  select d.* from public.ai_drafts d
   where d.outcome <> 'failed' and d.purpose = 'draft'
     and (d.report_id = p_report
          or exists (select 1 from public.sm_reports r
                      where r.id = p_report and d.client_id = r.client_id and d.kind = r.kind
                        and d.period_start <= r.period_end and d.period_end >= r.period_start))
$$;
revoke all on function public.ai_draft_same(uuid) from public, anon, authenticated;

create or replace function public.ai_check_claim(p_report uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m public.team_members;
  r public.sm_reports;
  since timestamptz := public.ai_draft_day();
  n_member integer;
  lim_member integer;
  new_id uuid;
begin
  if not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_report;
  if r.id is null or not public.client_seen(r.client_id, 'view') then
    return jsonb_build_object('error', 'not-found');
  end if;
  if r.status not in ('draft', 'review') then return jsonb_build_object('error', 'not-open'); end if;
  -- One count at a time, with the drafts, so the last use is taken once.
  perform pg_advisory_xact_lock(hashtext('ai_draft_claim'));
  lim_member := public.ai_draft_limit(m.id::text, public.ai_draft_limit('person', 20));
  if lim_member = 0 then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'stopped', 'limit', 0);
  end if;
  select count(*) into n_member from public.ai_drafts d
   where d.team_member_id = m.id and d.created_at >= since and d.outcome <> 'failed';
  if n_member >= lim_member then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'person', 'limit', lim_member, 'next', since + interval '1 day');
  end if;
  insert into public.ai_drafts (report_id, team_member_id, client_id, kind, period_start, period_end, purpose)
  values (p_report, m.id, r.client_id, r.kind, r.period_start, r.period_end, 'check') returning id into new_id;
  return jsonb_build_object('id', new_id, 'left', lim_member - n_member - 1);
end $$;

create or replace function public.ai_check_done(p_id uuid, p_ok boolean, p_result jsonb, p_basis jsonb)
returns void
language sql security definer set search_path = public as $$
  update public.ai_drafts d
     set outcome = case when p_ok then 'drafted' else 'failed' end,
         result = case when p_ok then p_result end,
         basis = case when p_ok then p_basis end
   where d.id = p_id and d.purpose = 'check' and d.outcome = 'pending'
     and d.team_member_id = (public.ops_me()).id
$$;

create or replace function public.ai_check_last(p_report uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  r public.sm_reports;
  c public.ai_drafts;
begin
  if not public.allowed('reports', 'view') then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_report;
  if r.id is null or not public.client_seen(r.client_id, 'view') then
    return jsonb_build_object('error', 'not-found');
  end if;
  select d.* into c from public.ai_drafts d
   where d.report_id = p_report and d.purpose = 'check' and d.outcome = 'drafted'
   order by d.created_at desc limit 1;
  if c.id is null then return jsonb_build_object('none', true); end if;
  return jsonb_build_object('at', c.created_at, 'result', c.result, 'basis', c.basis,
    'by', (select t.name from public.team_members t where t.id = c.team_member_id));
end $$;

revoke all on function public.ai_check_claim(uuid) from public, anon, authenticated;
revoke all on function public.ai_check_done(uuid, boolean, jsonb, jsonb) from public, anon, authenticated;
revoke all on function public.ai_check_last(uuid) from public, anon, authenticated;
grant execute on function public.ai_check_claim(uuid) to authenticated;
grant execute on function public.ai_check_done(uuid, boolean, jsonb, jsonb) to authenticated;
grant execute on function public.ai_check_last(uuid) to authenticated;

-- END OF AI CHECKS A REPORT AGAINST ITS FIGURES -----------------------------

-- ===========================================================================
-- INITIATIVES AND THE MONTHLY REFLECTION — a colleague logs what they started
-- (an idea for a client, a better way of working, a tool, an SOP) and writes
-- three lines on their month; management reads both beside the review.
-- 2026-10-04. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/perf.js compares the
-- two. Runs after the PERFORMANCE sections.
--
-- WHAT CHANGED (the user, 2026-10-04: initiative is already scored, Initiative
-- and improvement, 10 points; growth data is shared only by the member)
--   1. `perf_initiatives`: one row an initiative, the colleague's own. Proposed
--      → Adopted / Not now → Done; Withdrawn by its author (Restore brings it
--      back). Credited in the month it was logged and the month it was done.
--   2. `perf_reflections`: Proud of, Found hard, Want to learn, one row a
--      colleague a month; management reads it only once the colleague shares
--      it, and never scores it.
--   3. The colleague's functions ask the fresh proof My performance asks
--      (`perf_guarded`, `perf_code_fresh`); management's ask the granted part
--      and a live unlock (`perf_check`). Nobody decides on their own.
--   4. `perf_review_context(p_token, p_member, p_period)`: what the review
--      sheet shows beside Initiative and improvement.
--
-- ROLLBACK
--   In the SQL Editor, drop the twelve functions below, then the two tables.
--   No other table or function reads them.
-- ===========================================================================

create table if not exists public.perf_initiatives (
  id             uuid primary key default gen_random_uuid(),
  team_member_id uuid not null references public.team_members(id) on delete cascade,
  title          text not null check (char_length(btrim(title)) between 3 and 140),
  improves       text not null check (improves in ('client', 'process', 'tool', 'sop', 'other')),
  detail         text check (detail is null or char_length(detail) <= 2000),
  link           text check (link is null or link ~ '^https://[^[:space:]]+$'),
  status         text not null default 'proposed'
                 check (status in ('proposed', 'adopted', 'not_now', 'done', 'withdrawn')),
  period         date not null check (extract(day from period) = 1),
  done_period    date check (done_period is null or extract(day from done_period) = 1),
  decided_by     uuid references public.team_members(id) on delete set null,
  decided_at     timestamptz,
  note           text check (note is null or char_length(note) <= 1000),
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);
create index if not exists perf_initiatives_member_idx on public.perf_initiatives (team_member_id, period);

create table if not exists public.perf_reflections (
  team_member_id uuid not null references public.team_members(id) on delete cascade,
  period         date not null check (extract(day from period) = 1),
  proud          text check (proud is null or char_length(proud) <= 1000),
  hard           text check (hard is null or char_length(hard) <= 1000),
  learn          text check (learn is null or char_length(learn) <= 1000),
  shared_at      timestamptz,
  updated_at     timestamptz not null default now(),
  primary key (team_member_id, period)
);

alter table public.perf_initiatives enable row level security;
alter table public.perf_reflections enable row level security;
revoke all on public.perf_initiatives, public.perf_reflections from anon, authenticated;

/* One reading of an initiative, for its author and for management alike. */
create or replace function public.perf_initiative_json(i public.perf_initiatives)
returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'id', i.id, 'team_member_id', i.team_member_id,
    'name', (select t.name from public.team_members t where t.id = i.team_member_id),
    'title', i.title, 'improves', i.improves, 'detail', i.detail, 'link', i.link,
    'status', i.status, 'period', i.period, 'month', public.perf_month_word(i.period),
    'done_period', i.done_period,
    'done_month', case when i.done_period is null then null else public.perf_month_word(i.done_period) end,
    'decided_by', (select t.name from public.team_members t where t.id = i.decided_by),
    'decided_at', i.decided_at, 'note', i.note, 'created_at', i.created_at)
$$;
revoke all on function public.perf_initiative_json(public.perf_initiatives) from public, anon, authenticated;

/* The colleague's own: the fresh proof My performance asks, every time. */
create or replace function public.perf_mine_gate()
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare m public.team_members;
begin
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if public.perf_guarded(m.id) and not public.perf_code_fresh() then
    return jsonb_build_object('error', 'code-needed');
  end if;
  return null;
end $$;
revoke all on function public.perf_mine_gate() from public, anon, authenticated;

create or replace function public.perf_initiatives_mine()
returns jsonb
language plpgsql security definer set search_path = public as $$
declare m public.team_members; g jsonb;
begin
  g := public.perf_mine_gate();
  if g is not null then return g; end if;
  m := public.ops_me();
  return jsonb_build_object('initiatives', coalesce((
    select jsonb_agg(public.perf_initiative_json(i) order by i.created_at desc)
      from public.perf_initiatives i where i.team_member_id = m.id), '[]'::jsonb));
end $$;

create or replace function public.perf_initiative_save(p_id uuid, p_title text, p_improves text, p_detail text, p_link text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare m public.team_members; g jsonb; i public.perf_initiatives;
        t text := btrim(coalesce(p_title, '')); d text := nullif(btrim(coalesce(p_detail, '')), '');
        l text := nullif(btrim(coalesce(p_link, '')), '');
begin
  g := public.perf_mine_gate();
  if g is not null then return g; end if;
  m := public.ops_me();
  if char_length(t) < 3 then return jsonb_build_object('error', 'title'); end if;
  if char_length(t) > 140 then return jsonb_build_object('error', 'title-long'); end if;
  if p_improves is null or p_improves not in ('client', 'process', 'tool', 'sop', 'other') then
    return jsonb_build_object('error', 'improves');
  end if;
  if l is not null and l !~ '^https://[^[:space:]]+$' then return jsonb_build_object('error', 'link'); end if;
  if p_id is null then
    insert into public.perf_initiatives (team_member_id, title, improves, detail, link, period)
    values (m.id, t, p_improves, d, l, date_trunc('month', public.perf_today())::date)
    returning * into i;
    perform public.perf_log(null, m.id, 'initiative.logged', jsonb_build_object('title', t));
  else
    select * into i from public.perf_initiatives where id = p_id for update;
    if i.id is null or i.team_member_id <> m.id then return jsonb_build_object('error', 'not-found'); end if;
    if i.status <> 'proposed' then return jsonb_build_object('error', 'decided'); end if;
    update public.perf_initiatives
       set title = t, improves = p_improves, detail = d, link = l, updated_at = now()
     where id = i.id returning * into i;
    perform public.perf_log(null, m.id, 'initiative.edited', jsonb_build_object('title', t));
  end if;
  return jsonb_build_object('initiative', public.perf_initiative_json(i));
end $$;

/* Withdraw is the author's way out of a proposal; Restore its way back. */
create or replace function public.perf_initiative_withdraw(p_id uuid, p_back boolean default false)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare m public.team_members; g jsonb; i public.perf_initiatives;
begin
  g := public.perf_mine_gate();
  if g is not null then return g; end if;
  m := public.ops_me();
  select * into i from public.perf_initiatives where id = p_id for update;
  if i.id is null or i.team_member_id <> m.id then return jsonb_build_object('error', 'not-found'); end if;
  if i.status <> (case when p_back then 'withdrawn' else 'proposed' end) then
    return jsonb_build_object('error', 'decided');
  end if;
  update public.perf_initiatives
     set status = case when p_back then 'proposed' else 'withdrawn' end, updated_at = now()
   where id = i.id returning * into i;
  perform public.perf_log(null, m.id, case when p_back then 'initiative.restored' else 'initiative.withdrawn' end,
                          jsonb_build_object('title', i.title));
  return jsonb_build_object('initiative', public.perf_initiative_json(i));
end $$;

/* A reflection is written for this month or the last, until that month's
   review is final. */
create or replace function public.perf_reflection_open(p_member uuid, p_period date)
returns text
language sql stable security definer set search_path = public as $$
  select case
    when p_period is null or p_period not in (date_trunc('month', public.perf_today())::date,
                                              (date_trunc('month', public.perf_today()) - interval '1 month')::date)
      then 'bad-month'
    when exists (select 1 from public.perf_reviews r
                  where r.team_member_id = p_member and r.period = p_period and r.status = 'final')
      then 'final'
  end
$$;
revoke all on function public.perf_reflection_open(uuid, date) from public, anon, authenticated;

create or replace function public.perf_reflection_mine(p_period date)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare m public.team_members; g jsonb; f public.perf_reflections; p date := date_trunc('month', p_period)::date;
begin
  g := public.perf_mine_gate();
  if g is not null then return g; end if;
  m := public.ops_me();
  select * into f from public.perf_reflections where team_member_id = m.id and period = p;
  return jsonb_build_object('period', p, 'month', public.perf_month_word(p),
    'proud', f.proud, 'hard', f.hard, 'learn', f.learn, 'shared_at', f.shared_at,
    'open', public.perf_reflection_open(m.id, p) is null);
end $$;

create or replace function public.perf_reflection_save(p_period date, p_proud text, p_hard text, p_learn text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare m public.team_members; g jsonb; err text; p date := date_trunc('month', p_period)::date;
begin
  g := public.perf_mine_gate();
  if g is not null then return g; end if;
  m := public.ops_me();
  err := public.perf_reflection_open(m.id, p);
  if err is not null then return jsonb_build_object('error', err); end if;
  if char_length(coalesce(p_proud, '')) > 1000 or char_length(coalesce(p_hard, '')) > 1000
     or char_length(coalesce(p_learn, '')) > 1000 then
    return jsonb_build_object('error', 'too-long');
  end if;
  insert into public.perf_reflections (team_member_id, period, proud, hard, learn)
  values (m.id, p, nullif(btrim(coalesce(p_proud, '')), ''), nullif(btrim(coalesce(p_hard, '')), ''),
          nullif(btrim(coalesce(p_learn, '')), ''))
  on conflict (team_member_id, period) do update
     set proud = excluded.proud, hard = excluded.hard, learn = excluded.learn, updated_at = now();
  return public.perf_reflection_mine(p);
end $$;

/* Shared only by the colleague, and taken back by them until the month is
   final. */
create or replace function public.perf_reflection_share(p_period date, p_on boolean)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare m public.team_members; g jsonb; err text; n integer; p date := date_trunc('month', p_period)::date;
begin
  g := public.perf_mine_gate();
  if g is not null then return g; end if;
  m := public.ops_me();
  err := public.perf_reflection_open(m.id, p);
  if err is not null then return jsonb_build_object('error', err); end if;
  update public.perf_reflections
     set shared_at = case when p_on then now() end, updated_at = now()
   where team_member_id = m.id and period = p
     and (not p_on or coalesce(proud, hard, learn) is not null);
  get diagnostics n = row_count;
  if n = 0 then return jsonb_build_object('error', 'empty'); end if;
  perform public.perf_log(null, m.id, case when p_on then 'reflection.shared' else 'reflection.unshared' end,
                          jsonb_build_object('period', p));
  return public.perf_reflection_mine(p);
end $$;

/* Management: every colleague's initiatives but the caller's own. */
create or replace function public.perf_initiatives(p_token text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare err text; m public.team_members;
begin
  err := public.perf_check(p_token, 'view');
  if err is not null then return jsonb_build_object('error', err); end if;
  m := public.ops_me();
  return jsonb_build_object('initiatives', coalesce((
    select jsonb_agg(public.perf_initiative_json(i) order by i.created_at desc)
      from public.perf_initiatives i
     where i.team_member_id <> m.id and i.status <> 'withdrawn'), '[]'::jsonb));
end $$;

/* Adopted or Not now from a proposal, Done from adopted; Proposed is the way
   back from any of them and asks nothing. */
create or replace function public.perf_initiative_decide(p_token text, p_id uuid, p_status text, p_note text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare err text; m public.team_members; i public.perf_initiatives; was text;
begin
  err := public.perf_check(p_token, 'work');
  if err is not null then return jsonb_build_object('error', err); end if;
  m := public.ops_me();
  select * into i from public.perf_initiatives where id = p_id for update;
  if i.id is null or i.status = 'withdrawn' then return jsonb_build_object('error', 'not-found'); end if;
  if i.team_member_id = m.id then return jsonb_build_object('error', 'own'); end if;
  if p_status is null or p_status not in ('adopted', 'not_now', 'done', 'proposed') then
    return jsonb_build_object('error', 'bad-status');
  end if;
  if not ((i.status = 'proposed' and p_status in ('adopted', 'not_now'))
       or (i.status = 'adopted' and p_status = 'done')
       or (i.status <> 'proposed' and p_status = 'proposed')) then
    return jsonb_build_object('error', 'bad-move');
  end if;
  was := i.status;
  update public.perf_initiatives
     set status = p_status,
         done_period = case when p_status = 'done' then date_trunc('month', public.perf_today())::date
                            when p_status = 'proposed' then null else done_period end,
         decided_by = case when p_status = 'proposed' then null else m.id end,
         decided_at = case when p_status = 'proposed' then null else now() end,
         note = case when p_status = 'proposed' then null
                     else coalesce(nullif(btrim(coalesce(p_note, '')), ''), note) end,
         updated_at = now()
   where id = i.id returning * into i;
  perform public.perf_log(null, i.team_member_id, 'initiative.' || p_status,
                          jsonb_build_object('title', i.title, 'from', was));
  if p_status in ('adopted', 'done', 'not_now') then
    perform public.perf_notify(i.team_member_id, 'perf.initiative',
      case p_status when 'adopted' then 'Your initiative was adopted: '
                    when 'done' then 'Your initiative is done: '
                    else 'Your initiative is on hold for now: ' end || i.title,
      'initiative:' || i.id || ':' || p_status || ':' || extract(epoch from now())::bigint);
  end if;
  return jsonb_build_object('initiative', public.perf_initiative_json(i));
end $$;

/* Beside Initiative and improvement in the review sheet: the colleague's
   initiatives logged or done in the month, and their reflection once shared. */
create or replace function public.perf_review_context(p_token text, p_member uuid, p_period date)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare err text; m public.team_members; f public.perf_reflections; p date := date_trunc('month', p_period)::date;
begin
  err := public.perf_check(p_token, 'view');
  if err is not null then return jsonb_build_object('error', err); end if;
  m := public.ops_me();
  if p_member is null or p_member = m.id then return jsonb_build_object('error', 'own'); end if;
  select * into f from public.perf_reflections
   where team_member_id = p_member and period = p and shared_at is not null;
  return jsonb_build_object(
    'initiatives', coalesce((
      select jsonb_agg(public.perf_initiative_json(i) order by i.created_at)
        from public.perf_initiatives i
       where i.team_member_id = p_member and i.status <> 'withdrawn'
         and (i.period = p or i.done_period = p)), '[]'::jsonb),
    'reflection', case when f.team_member_id is null then null else jsonb_build_object(
      'proud', f.proud, 'hard', f.hard, 'learn', f.learn, 'shared_at', f.shared_at) end);
end $$;

revoke all on function public.perf_initiatives_mine() from public, anon, authenticated;
revoke all on function public.perf_initiative_save(uuid, text, text, text, text) from public, anon, authenticated;
revoke all on function public.perf_initiative_withdraw(uuid, boolean) from public, anon, authenticated;
revoke all on function public.perf_reflection_mine(date) from public, anon, authenticated;
revoke all on function public.perf_reflection_save(date, text, text, text) from public, anon, authenticated;
revoke all on function public.perf_reflection_share(date, boolean) from public, anon, authenticated;
revoke all on function public.perf_initiatives(text) from public, anon, authenticated;
revoke all on function public.perf_initiative_decide(text, uuid, text, text) from public, anon, authenticated;
revoke all on function public.perf_review_context(text, uuid, date) from public, anon, authenticated;
grant execute on function public.perf_initiatives_mine() to authenticated;
grant execute on function public.perf_initiative_save(uuid, text, text, text, text) to authenticated;
grant execute on function public.perf_initiative_withdraw(uuid, boolean) to authenticated;
grant execute on function public.perf_reflection_mine(date) to authenticated;
grant execute on function public.perf_reflection_save(date, text, text, text) to authenticated;
grant execute on function public.perf_reflection_share(date, boolean) to authenticated;
grant execute on function public.perf_initiatives(text) to authenticated;
grant execute on function public.perf_initiative_decide(text, uuid, text, text) to authenticated;
grant execute on function public.perf_review_context(text, uuid, date) to authenticated;

-- END OF INITIATIVES AND THE MONTHLY REFLECTION -----------------------------

-- ===========================================================================
-- OPEN TO TAKE — a Task Owner offers a task to the team, and any colleague
-- who works in My Work takes it and becomes its owner. Pulling work is the
-- initiative; the task keeps an owner throughout.
-- 2026-10-04. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/ops.js compares the
-- two. Runs after CLIENT SCOPE.
--
-- WHAT CHANGED (the user, 2026-10-04: pick up work, approved)
--   1. `ops_tasks.open_at`, `open_by`: when and by whom a task was offered.
--      A task that changes hands any way is no longer open (trigger on the
--      new owner's row).
--   2. `ops_set_open(p_task, p_on)`: the Task Owner or an admin, My Work at
--      Work, an open task. Filed `offered` / `offer_withdrawn`.
--   3. `ops_take_task(p_task, p_version)`: My Work at Work, an offered open
--      task the caller may see, not already theirs. The caller becomes the
--      owner (filed `assignment_changed`, `taken`), and the owner before is
--      told.
--   4. `ops_may_see_task`: an offered open task is seen by anyone at My Work
--      Work whose client scope holds its client, so it can be taken.
--
-- ROLLBACK
--   Run the CLIENT SCOPE section's ops_may_see_task again; in the SQL Editor
--   drop the two functions, the trigger and its function. The two columns
--   may stay.
-- ===========================================================================

alter table public.ops_tasks add column if not exists open_at timestamptz;
alter table public.ops_tasks add column if not exists open_by uuid references public.team_members(id) on delete set null;

create or replace function public.ops_may_see_task(p_task uuid)
returns boolean
language sql security definer stable set search_path = public as $$
  select case
    when not public.allowed('ops', 'view') then false
    when public.ops_granted('ops.all', 'view') and public.client_scope_free('view') then true
    when exists (
      select 1 from public.ops_tasks t
       where t.id = p_task
         and (t.created_by = (select id from public.ops_me())
              or exists (select 1 from public.ops_task_assignees a
                          where a.task_id = t.id and a.ended_at is null
                            and a.team_member_id = (select id from public.ops_me())))) then true
    when public.allowed('ops', 'work') and exists (
      select 1 from public.ops_tasks t
       where t.id = p_task and t.open_at is not null
         and t.completed_at is null and t.cancelled_at is null)
      then public.client_seen((select t.client_id from public.ops_tasks t where t.id = p_task), 'view')
    when public.ops_granted('ops.all', 'view')
      then public.client_seen((select t.client_id from public.ops_tasks t where t.id = p_task), 'view')
    else false
  end
$$;

/* A task that changes hands, any way, is no longer on offer. */
create or replace function public.ops_assignees_close_offer()
returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.responsibility = 'owner' and new.ended_at is null then
    update public.ops_tasks set open_at = null, open_by = null
     where id = new.task_id and open_at is not null;
  end if;
  return new;
end $$;
revoke all on function public.ops_assignees_close_offer() from public, anon, authenticated;
create or replace trigger ops_assignees_close_offer
  after insert on public.ops_task_assignees
  for each row execute function public.ops_assignees_close_offer();

create or replace function public.ops_set_open(p_task uuid, p_on boolean)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare m public.team_members; t public.ops_tasks;
begin
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if not public.allowed('ops', 'work') or not public.ops_may_see_task(p_task) then
    return jsonb_build_object('error', 'denied');
  end if;
  select * into t from public.ops_tasks where id = p_task for update;
  if t.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if not public.ops_owner_may_move(p_task) then return jsonb_build_object('error', 'not-owner'); end if;
  if t.completed_at is not null or t.cancelled_at is not null then
    return jsonb_build_object('error', 'finished');
  end if;
  if (t.open_at is not null) = coalesce(p_on, false) then return public.ops_task_json(p_task); end if;
  update public.ops_tasks
     set open_at = case when p_on then now() end, open_by = case when p_on then m.id end,
         version = version + 1, updated_at = now()
   where id = p_task;
  perform public.ops_log(p_task, case when p_on then 'offered' else 'offer_withdrawn' end,
                         null, null, '{}'::jsonb);
  return public.ops_task_json(p_task);
end $$;

create or replace function public.ops_take_task(p_task uuid, p_version integer default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare m public.team_members; t public.ops_tasks; was uuid;
begin
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if not public.allowed('ops', 'work') or not public.ops_may_see_task(p_task) then
    return jsonb_build_object('error', 'denied');
  end if;
  select * into t from public.ops_tasks where id = p_task for update;
  if t.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if t.open_at is null then return jsonb_build_object('error', 'not-open'); end if;
  if t.completed_at is not null or t.cancelled_at is not null then
    return jsonb_build_object('error', 'finished');
  end if;
  if p_version is not null and p_version <> t.version then
    return jsonb_build_object('error', 'stale', 'task', public.ops_task_json(p_task));
  end if;
  select team_member_id into was from public.ops_task_assignees
   where task_id = p_task and responsibility = 'owner' and ended_at is null;
  if was = m.id then return jsonb_build_object('error', 'already-yours'); end if;
  update public.ops_task_assignees set ended_at = now()
   where task_id = p_task and responsibility = 'owner' and ended_at is null;
  insert into public.ops_task_assignees (task_id, team_member_id, responsibility, assigned_by)
  values (p_task, m.id, 'owner', m.id);
  update public.ops_tasks set version = version + 1, updated_at = now() where id = p_task;
  perform public.ops_log(p_task, 'assignment_changed',
    jsonb_build_object('owner_id', was), jsonb_build_object('owner_id', m.id),
    jsonb_build_object('taken', true, 'stage_key', t.stage_key));
  if was is not null then
    perform public.ops_notify(was, p_task, 'taken',
      public.ops_serial(t.task_no) || ' · ' || public.ops_title(t),
      'Taken by ' || coalesce(nullif(m.name, ''), m.email) || '.',
      'taken:' || p_task::text || ':' || m.id::text || ':' || to_char(now(), 'YYYYMMDDHH24MI'));
  end if;
  return public.ops_task_json(p_task);
end $$;

revoke all on function public.ops_set_open(uuid, boolean) from public, anon, authenticated;
revoke all on function public.ops_take_task(uuid, integer) from public, anon, authenticated;
grant execute on function public.ops_set_open(uuid, boolean) to authenticated;
grant execute on function public.ops_take_task(uuid, integer) to authenticated;

-- END OF OPEN TO TAKE -------------------------------------------------------

-- ===========================================================================
-- A CLIENT PAUSED OR PAST SAYS WHY — moving a client to Paused or Past takes
-- a reason, kept on that stage move, and each colleague with work still open
-- for the client is told once to finish its delivery.
-- 2026-10-04. Safe to run twice. Rollback below. Mirrored byte for byte in
-- supabase/schema.sql under the same banner; tests/sql.js compares the two.
--
-- WHAT CHANGED (the user, 2026-10-04: a reason required on Paused and Past;
-- a client paused or ended at its invoice period still has revisions and
-- reviews to deliver, and they need arranging urgently)
--   1. `clients.stage_reason` (budget, results, in_house, closed, no_reply,
--      other) and `clients.stage_note` arrive with the stage itself; the
--      clock writes them into that move's `stage_log` entry. A move into
--      Paused or Past without a reason is refused (`stage-reason`); a move
--      to any other stage clears both, since they belong to the pause or
--      the ending.
--   2. `clients_stage_notice` (after update): on a real move into Paused or
--      Past, each colleague who owns an open task of the client is told
--      once, `{client} moved to Paused · 3 open tasks to deliver`, opening My
--      Work (`kind` client_left). The urgent mark itself is worked out by
--      the page from the client's stage, never written to a task.
--   3. `client_open_tasks(p_client)`: the count of the client's open tasks,
--      for the question that asks the reason (Clients View).
--   4. `ops_notifications_push` opens My Work for a client_left notice.
--   5. `ops_task_client_facts(p_tasks)`: a task's client name and stage for
--      the tasks the colleague may see, where the client itself is out of
--      their reach (their own task on another's client), so its urgent
--      delivery shows too. `ops_task_clients` stays for the page before it.
--
-- ROLLBACK
--   Run the CLIENTS STAGE CLOCK section's clients_stage_clock and the PUSH
--   section's ops_notifications_push again; then, in the SQL Editor, drop
--   the trigger clients_stage_notice, its function, client_open_tasks and
--   ops_task_client_facts.
--   The two columns may stay.
-- ===========================================================================

alter table public.clients add column if not exists stage_reason text;
alter table public.clients add column if not exists stage_note text;
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'clients_stage_reason') then
    alter table public.clients add constraint clients_stage_reason
      check (stage_reason is null or stage_reason in ('budget', 'results', 'in_house', 'closed', 'no_reply', 'other'));
  end if;
end $$;
grant select (stage_reason, stage_note) on table public.clients to authenticated;

create or replace function public.clients_stage_clock()
returns trigger
language plpgsql
as $$
begin
  if tg_op = 'INSERT' then
    new.stage_since := coalesce(new.stage_since, coalesce(new.created_at, now()));
    if new.stage_log is null or jsonb_array_length(new.stage_log) = 0 then
      new.stage_log := jsonb_build_array(
        jsonb_build_object('stage', new.stage, 'at', new.stage_since));
    end if;
    return new;
  end if;
  -- Only a real move restarts the clock. A move into Paused or Past says
  -- why; a move anywhere else leaves the reason behind with the pause.
  if new.stage is distinct from old.stage then
    if new.stage in ('paused', 'past') then
      if nullif(btrim(coalesce(new.stage_reason, '')), '') is null then
        raise exception 'stage-reason' using errcode = 'P0001';
      end if;
    else
      new.stage_reason := null;
      new.stage_note := null;
    end if;
    new.stage_since := now();
    new.stage_log := coalesce(old.stage_log, '[]'::jsonb) ||
      jsonb_build_array(jsonb_strip_nulls(jsonb_build_object('stage', new.stage, 'at', now(),
        'reason', new.stage_reason, 'note', nullif(btrim(coalesce(new.stage_note, '')), ''))));
  end if;
  return new;
end $$;

-- A client's open tasks: not finished, cancelled or archived.
create or replace function public.client_open_tasks(p_client uuid)
returns integer
language sql stable security definer set search_path = public as $$
  select case when public.allowed('clients', 'view') and public.client_seen(p_client, 'view') then
    (select count(*)::integer from public.ops_tasks t
      where t.client_id = p_client and t.completed_at is null
        and t.cancelled_at is null and t.archived_at is null)
  else 0 end
$$;
revoke all on function public.client_open_tasks(uuid) from public, anon, authenticated;
grant execute on function public.client_open_tasks(uuid) to authenticated;

create or replace function public.clients_stage_notice()
returns trigger
language plpgsql security definer set search_path = public as $$
declare
  r record;
  v_word text := case new.stage when 'paused' then 'Paused' else 'Past' end;
begin
  if new.stage is not distinct from old.stage or new.stage not in ('paused', 'past') then
    return new;
  end if;
  for r in select a.team_member_id as owner, count(*) as n
             from public.ops_tasks t
             join public.ops_task_assignees a
               on a.task_id = t.id and a.responsibility = 'owner' and a.ended_at is null
            where t.client_id = new.id and t.completed_at is null
              and t.cancelled_at is null and t.archived_at is null
            group by a.team_member_id loop
    perform public.ops_notify(r.owner, null, 'client_left',
      coalesce(nullif(btrim(new.name), ''), 'A client') || ' moved to ' || v_word,
      r.n || case when r.n = 1 then ' open task' else ' open tasks' end || ' to deliver',
      'client_left:' || new.id || ':' || new.stage || ':' || r.owner || ':' || to_char(now(), 'YYYYMMDDHH24MI'));
  end loop;
  return new;
exception when others then
  return new;
end $$;
revoke all on function public.clients_stage_notice() from public, anon, authenticated;
create or replace trigger clients_stage_notice after update on public.clients
  for each row execute function public.clients_stage_notice();

create or replace function public.ops_notifications_push()
returns trigger
language plpgsql security definer set search_path = public as $$
declare
  v_title text := coalesce(nullif(btrim(new.title), ''), 'My Work');
  v_body  text := coalesce(new.body, '');
begin
  perform public.push_queue('team', new.team_member_id,
    jsonb_build_object('en', jsonb_build_object('title', v_title, 'body', v_body),
                       'zh', jsonb_build_object('title', v_title, 'body', v_body)),
    case when new.task_id is not null then '/admin/?s=work&open=' || new.task_id::text
         when new.report_id is not null then '/admin/?s=reports&report=' || new.report_id::text
         when new.kind = 'client_left' then '/admin/?s=work'
         else '/admin/' end,
    case when new.task_id is not null then 'task-' || new.task_id::text
         when new.report_id is not null then 'report-' || new.report_id::text
         else null end);
  return new;
exception when others then
  return new;
end $$;

/* A task's client, named and staged, for the colleague's own tasks on a
   client outside their reach: the name alone was not enough once a paused
   or past client's open work reads as urgent delivery. */
create or replace function public.ops_task_client_facts(p_tasks uuid[])
returns table (task_id uuid, client_name text, client_stage text)
language sql security definer stable set search_path = public as $$
  select t.id, c.name, c.stage
    from public.ops_tasks t
    join public.clients c on c.id = t.client_id
   where t.id = any (p_tasks[1:500])
     and public.ops_may_see_task(t.id)
$$;
revoke all on function public.ops_task_client_facts(uuid[]) from public, anon;
grant execute on function public.ops_task_client_facts(uuid[]) to authenticated;

-- END OF A CLIENT PAUSED OR PAST SAYS WHY ------------------------------------

-- ===========================================================================
-- AI LIMITS BY REPORT AND VERSION — one draft a report, one figures check a
-- version, ten AI uses a day a colleague, an admin five drafts and five
-- checks a report a day within twenty.
-- 2026-10-05. Safe to run twice. Rollback below. Mirrored byte for byte in
-- supabase/schema.sql under the same banner; tests/sql.js compares the two.
--
-- WHAT CHANGED (the user, 2026-10-05: the figures check allowed up to twenty
-- a day on one report; a report is drafted once, its revisions inside that
-- one draft, and checked once a version)
--   1. `ai_drafts.version_no`: the report's version a check was run on.
--   2. `ai_day_cap(m)`: a colleague's AI uses a day, drafts and checks
--      together: their own limit, else `admin` (20) for an admin, else
--      `person` (10). Every count and the usage page read it.
--   3. `ai_check_claim`: a colleague's check is refused once the report's
--      current version has one (`recheck`, setting `check`, 1); an admin's
--      past it up to `check_admin` (5) a report a day (`report_check`).
--   4. `ai_check_left(p_report)`: what is left for the Check button, read
--      without writing, as `ai_draft_left` is for drafts.
--   5. `ai_draft_usage` and `ai_draft_set_limit` carry `admin`, `check` and
--      `check_admin` beside `person`, `report` and `report_admin`; the
--      standard a colleague is 10.
--   Drafts are unchanged: one a report from colleagues (`report`, by
--   subject, so a revision of the same period shares it), an admin's five
--   a report a day (`report_admin`).
--
-- ROLLBACK
--   Run the DRAFT WITH AI RESETS AT MIDNIGHT section's ai_draft_claim,
--   ai_draft_left, ai_draft_usage and ai_draft_set_limit, and the AI CHECKS
--   A REPORT AGAINST ITS FIGURES section's ai_check_claim, again; then, in
--   the SQL Editor, drop ai_check_left and ai_day_cap. The column may stay.
-- ===========================================================================

alter table public.ai_drafts add column if not exists version_no integer;

-- A colleague's AI uses a day: their own, else an admin's or the standard.
create or replace function public.ai_day_cap(m public.team_members)
returns integer
language sql stable security definer set search_path = public as $$
  select public.ai_draft_limit(m.id::text,
    case when coalesce(m.is_admin, false) or m.role = 'admin'
         then public.ai_draft_limit('admin', 20)
         else public.ai_draft_limit('person', 10) end)
$$;
revoke all on function public.ai_day_cap(public.team_members) from public, anon, authenticated;

create or replace function public.ai_draft_claim(p_report uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m public.team_members;
  r public.sm_reports;
  since timestamptz := public.ai_draft_day();
  n_report integer;
  n_member integer;
  lim_member integer;
  lim_report integer := public.ai_draft_limit('report', 1);
  lim_admin integer := public.ai_draft_limit('report_admin', 5);
  new_id uuid;
begin
  if not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'denied'); end if;
  -- One count at a time, so two presses together cannot both take the last draft.
  perform pg_advisory_xact_lock(hashtext('ai_draft_claim'));
  select * into r from public.sm_reports where id = p_report;
  lim_member := public.ai_day_cap(m);
  if lim_member = 0 then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'stopped', 'limit', 0);
  end if;
  -- A report's drafts from a colleague; past them, the rest are an admin's.
  if not coalesce(m.is_admin, false) and (select count(*) from public.ai_draft_same(p_report)) >= lim_report then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'redraft', 'limit', lim_report);
  end if;
  select count(*) into n_report from public.ai_draft_same(p_report) s where s.created_at >= since;
  if coalesce(m.is_admin, false) and n_report >= lim_admin then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'report', 'limit', lim_admin, 'next', since + interval '1 day');
  end if;
  select count(*) into n_member from public.ai_drafts d
   where d.team_member_id = m.id and d.created_at >= since and d.outcome <> 'failed';
  if n_member >= lim_member then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'person', 'limit', lim_member, 'next', since + interval '1 day');
  end if;
  insert into public.ai_drafts (report_id, team_member_id, client_id, kind, period_start, period_end, version_no)
  values (p_report, m.id, r.client_id, r.kind, r.period_start, r.period_end, r.version_no) returning id into new_id;
  return jsonb_build_object('id', new_id, 'left', lim_member - n_member - 1);
end $$;

create or replace function public.ai_draft_left(p_report uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  m public.team_members;
  since timestamptz := public.ai_draft_day();
  is_adm boolean;
  n_report integer; n_member integer;
  l_report integer; l_member integer; l_min integer;
  lim_member integer;
  lim_report integer := public.ai_draft_limit('report', 1);
  lim_admin integer := public.ai_draft_limit('report_admin', 5);
  v_scope text;
begin
  if not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'denied'); end if;
  is_adm := coalesce(m.is_admin, false);
  lim_member := public.ai_day_cap(m);
  select count(*) into n_report from public.ai_draft_same(p_report) s where s.created_at >= since;
  if is_adm then
    l_report := greatest(0, lim_admin - n_report);
  else
    l_report := greatest(0, lim_report - (select count(*) from public.ai_draft_same(p_report))::integer);
  end if;
  select count(*) into n_member from public.ai_drafts d
   where d.team_member_id = m.id and d.created_at >= since and d.outcome <> 'failed';
  l_member := greatest(0, lim_member - n_member);
  l_min := least(l_report, l_member);
  v_scope := case when lim_member = 0 then 'stopped'
                  when l_min = l_report then case when is_adm then 'report' else 'redraft' end
                  else 'person' end;
  return jsonb_build_object(
    'left', l_min, 'scope', v_scope,
    'limit', case v_scope when 'stopped' then 0 when 'redraft' then lim_report when 'report' then lim_admin else lim_member end,
    'report', l_report, 'person', l_member, 'admin', is_adm,
    'next', case when l_min > 0 or v_scope in ('redraft', 'stopped') then null else since + interval '1 day' end);
end $$;

-- A figures check: one a version of the report from colleagues; an admin's
-- past it, up to `check_admin` a report a day; all within the day's uses.
create or replace function public.ai_check_claim(p_report uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m public.team_members;
  r public.sm_reports;
  since timestamptz := public.ai_draft_day();
  n_member integer;
  lim_member integer;
  lim_check integer := public.ai_draft_limit('check', 1);
  lim_admin integer := public.ai_draft_limit('check_admin', 5);
  new_id uuid;
begin
  if not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_report;
  if r.id is null or not public.client_seen(r.client_id, 'view') then
    return jsonb_build_object('error', 'not-found');
  end if;
  if r.status not in ('draft', 'review') then return jsonb_build_object('error', 'not-open'); end if;
  -- One count at a time, with the drafts, so the last use is taken once.
  perform pg_advisory_xact_lock(hashtext('ai_draft_claim'));
  lim_member := public.ai_day_cap(m);
  if lim_member = 0 then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'stopped', 'limit', 0);
  end if;
  if not coalesce(m.is_admin, false) then
    if (select count(*) from public.ai_drafts d
         where d.report_id = p_report and d.purpose = 'check' and d.outcome <> 'failed'
           and d.version_no is not distinct from r.version_no) >= lim_check then
      return jsonb_build_object('error', 'ai-limit', 'scope', 'recheck', 'limit', lim_check, 'version', r.version_no);
    end if;
  elsif (select count(*) from public.ai_drafts d
          where d.report_id = p_report and d.purpose = 'check' and d.outcome <> 'failed'
            and d.created_at >= since) >= lim_admin then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'report_check', 'limit', lim_admin, 'next', since + interval '1 day');
  end if;
  select count(*) into n_member from public.ai_drafts d
   where d.team_member_id = m.id and d.created_at >= since and d.outcome <> 'failed';
  if n_member >= lim_member then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'person', 'limit', lim_member, 'next', since + interval '1 day');
  end if;
  insert into public.ai_drafts (report_id, team_member_id, client_id, kind, period_start, period_end, purpose, version_no)
  values (p_report, m.id, r.client_id, r.kind, r.period_start, r.period_end, 'check', r.version_no) returning id into new_id;
  return jsonb_build_object('id', new_id, 'left', lim_member - n_member - 1);
end $$;

-- What the Check button has left, read without writing.
create or replace function public.ai_check_left(p_report uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  m public.team_members;
  r public.sm_reports;
  since timestamptz := public.ai_draft_day();
  is_adm boolean;
  n_member integer;
  l_report integer; l_member integer; l_min integer;
  lim_member integer;
  lim_check integer := public.ai_draft_limit('check', 1);
  lim_admin integer := public.ai_draft_limit('check_admin', 5);
  v_scope text;
begin
  if not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_report;
  if r.id is null or not public.client_seen(r.client_id, 'view') then
    return jsonb_build_object('error', 'not-found');
  end if;
  is_adm := coalesce(m.is_admin, false);
  lim_member := public.ai_day_cap(m);
  if is_adm then
    l_report := greatest(0, lim_admin - (select count(*) from public.ai_drafts d
      where d.report_id = p_report and d.purpose = 'check' and d.outcome <> 'failed' and d.created_at >= since)::integer);
  else
    l_report := greatest(0, lim_check - (select count(*) from public.ai_drafts d
      where d.report_id = p_report and d.purpose = 'check' and d.outcome <> 'failed'
        and d.version_no is not distinct from r.version_no)::integer);
  end if;
  select count(*) into n_member from public.ai_drafts d
   where d.team_member_id = m.id and d.created_at >= since and d.outcome <> 'failed';
  l_member := greatest(0, lim_member - n_member);
  l_min := least(l_report, l_member);
  v_scope := case when lim_member = 0 then 'stopped'
                  when l_min = l_report then case when is_adm then 'report_check' else 'recheck' end
                  else 'person' end;
  return jsonb_build_object(
    'left', l_min, 'scope', v_scope, 'version', r.version_no,
    'limit', case v_scope when 'stopped' then 0 when 'recheck' then lim_check when 'report_check' then lim_admin else lim_member end,
    'report', l_report, 'person', l_member, 'admin', is_adm,
    'next', case when l_min > 0 or v_scope in ('recheck', 'stopped') then null else since + interval '1 day' end);
end $$;

revoke all on function public.ai_draft_claim(uuid) from public, anon, authenticated;
revoke all on function public.ai_draft_left(uuid) from public, anon, authenticated;
revoke all on function public.ai_check_claim(uuid) from public, anon, authenticated;
revoke all on function public.ai_check_left(uuid) from public, anon, authenticated;
grant execute on function public.ai_draft_claim(uuid) to authenticated;
grant execute on function public.ai_draft_left(uuid) to authenticated;
grant execute on function public.ai_check_claim(uuid) to authenticated;
grant execute on function public.ai_check_left(uuid) to authenticated;

-- Every colleague's use today against their limit, for an admin.
create or replace function public.ai_draft_usage()
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_day timestamptz := public.ai_draft_day();
  v_month timestamptz := now() - interval '30 days';
begin
  if not public.allowed('admin') then return jsonb_build_object('error', 'denied'); end if;
  return jsonb_build_object(
    'person', public.ai_draft_limit('person', 10),
    'admin', public.ai_draft_limit('admin', 20),
    'report', public.ai_draft_limit('report', 1),
    'report_admin', public.ai_draft_limit('report_admin', 5),
    'check', public.ai_draft_limit('check', 1),
    'check_admin', public.ai_draft_limit('check_admin', 5),
    'resets_at', v_day + interval '1 day',
    'people', coalesce((select jsonb_agg(s.x order by s.x ->> 'name') from (
      select jsonb_build_object(
        'id', t.id, 'name', t.name, 'code', t.staff_code, 'group', g.name, 'group_slug', t.role,
        'admin', coalesce(t.is_admin, false) or t.role = 'admin',
        'day', (select count(*) from public.ai_drafts d where d.team_member_id = t.id and d.created_at >= v_day and d.outcome <> 'failed'),
        'month', (select count(*) from public.ai_drafts d where d.team_member_id = t.id and d.created_at > v_month and d.outcome <> 'failed'),
        'limit', (select l.daily from public.ai_draft_limits l where l.scope = t.id::text),
        'cap', public.ai_day_cap(t)) as x
        from public.team_members t
        left join public.team_roles g on g.slug = t.role
       where t.active
         and (coalesce(t.is_admin, false) or t.role = 'admin'
              or public.level_rank(coalesce(t.access ->> 'reports', 'none')) >= public.level_rank('work')
              or exists (select 1 from public.ai_drafts d where d.team_member_id = t.id and d.created_at > v_month))
    ) s), '[]'::jsonb));
end $$;
revoke all on function public.ai_draft_usage() from public, anon, authenticated;
grant execute on function public.ai_draft_usage() to authenticated;

-- A colleague's limit a day, or a standard for everyone. Null puts the
-- standard back.
create or replace function public.ai_draft_set_limit(p_scope text, p_daily integer)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_who text;
  v_name text;
  v_was integer;
  v_def integer;
  v_unit text := ' a day';
  v_scope text := btrim(coalesce(p_scope, ''));
  t public.team_members;
begin
  if not public.allowed('admin') then return jsonb_build_object('error', 'denied'); end if;
  if p_daily is not null and (p_daily < 0 or p_daily > 500) then
    return jsonb_build_object('error', 'bad-limit');
  end if;
  if v_scope = 'person' then
    v_name := 'Each colleague'; v_def := 10;
  elsif v_scope = 'admin' then
    v_name := 'Each admin'; v_def := 20;
  elsif v_scope = 'report' then
    v_name := 'Drafts per report'; v_def := 1; v_unit := '';
  elsif v_scope = 'report_admin' then
    v_name := 'Admin drafts per report'; v_def := 5;
  elsif v_scope = 'check' then
    v_name := 'Figures checks per version'; v_def := 1; v_unit := '';
  elsif v_scope = 'check_admin' then
    v_name := 'Admin figures checks per report'; v_def := 5;
  elsif v_scope = 'team' then
    return jsonb_build_object('error', 'bad-scope');
  else
    select * into t from public.team_members x where x.id::text = v_scope;
    if t.id is null then return jsonb_build_object('error', 'not-found'); end if;
    v_name := t.name;
    v_def := case when coalesce(t.is_admin, false) or t.role = 'admin'
                  then public.ai_draft_limit('admin', 20) else public.ai_draft_limit('person', 10) end;
  end if;
  select l.daily into v_was from public.ai_draft_limits l where l.scope = v_scope;
  if v_was is not distinct from p_daily then return jsonb_build_object('ok', true, 'same', true); end if;
  select coalesce(x.name, x.email) into v_who from public.team_members x
   where lower(x.email) = lower(auth.jwt() ->> 'email') and x.active limit 1;
  insert into public.ai_draft_limits (scope, daily, set_by, set_at)
  values (v_scope, p_daily, v_who, now())
  on conflict (scope) do update set daily = excluded.daily, set_by = excluded.set_by, set_at = excluded.set_at;
  insert into public.activity_log (actor, action, subject, detail)
  values (coalesce(v_who, 'admin'), 'team.changed', 'AI',
          v_name || ': ' ||
          case when v_was is null then 'standard, ' || v_def || v_unit when v_was = 0 then 'stopped' else v_was || v_unit end ||
          ' → ' ||
          case when p_daily is null then 'standard, ' || v_def || v_unit when p_daily = 0 then 'stopped' else p_daily || v_unit end);
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.ai_draft_set_limit(text, integer) from public, anon, authenticated;
grant execute on function public.ai_draft_set_limit(text, integer) to authenticated;

-- END OF AI LIMITS BY REPORT AND VERSION ------------------------------------

-- ===========================================================================
-- AI LIMITS A COLLEAGUE A REPORT A DAY — each colleague has one draft and one
-- figures check on a report a day, reset at midnight; an admin five of each.
-- 2026-10-05. Safe to run twice. Rollback below. Mirrored byte for byte in
-- supabase/schema.sql under the same banner; tests/smsql.js compares the two.
--
-- WHAT CHANGED (the user, 2026-10-05: "just give per pax per report per use
-- per day ... if they do the report last minute ... they need to be
-- responsible for the late until next day. same goes to the figure check.
-- resets daily")
--   1. A draft is counted by who asks, on that report, today: `report` (1) a
--      colleague's, `report_admin` (5) an admin's. Past it the refusal is
--      `report` with the reset time. A revision of the same period is the
--      same report (`ai_draft_same`).
--   2. A figures check is counted the same way: `check` (1) a colleague's,
--      `check_admin` (5) an admin's, refused `report_check` with the reset
--      time. A revision no longer brings another check the same day.
--   3. `ai_draft_left` and `ai_check_left` read the same counts.
--   4. `ai_draft_set_limit` names the two everyday limits by what they now
--      count. The day's uses (`person` 10, `admin` 20) are unchanged.
--
-- ROLLBACK
--   Run the AI LIMITS BY REPORT AND VERSION section of schema.sql again.
-- ===========================================================================

create or replace function public.ai_draft_claim(p_report uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m public.team_members;
  r public.sm_reports;
  since timestamptz := public.ai_draft_day();
  n_report integer;
  n_member integer;
  lim_member integer;
  lim_report integer;
  new_id uuid;
begin
  if not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'denied'); end if;
  -- One count at a time, so two presses together cannot both take the last draft.
  perform pg_advisory_xact_lock(hashtext('ai_draft_claim'));
  select * into r from public.sm_reports where id = p_report;
  lim_member := public.ai_day_cap(m);
  if lim_member = 0 then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'stopped', 'limit', 0);
  end if;
  lim_report := case when coalesce(m.is_admin, false) then public.ai_draft_limit('report_admin', 5)
                     else public.ai_draft_limit('report', 1) end;
  select count(*) into n_report from public.ai_draft_same(p_report) s
   where s.team_member_id = m.id and s.created_at >= since;
  if n_report >= lim_report then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'report', 'limit', lim_report, 'next', since + interval '1 day');
  end if;
  select count(*) into n_member from public.ai_drafts d
   where d.team_member_id = m.id and d.created_at >= since and d.outcome <> 'failed';
  if n_member >= lim_member then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'person', 'limit', lim_member, 'next', since + interval '1 day');
  end if;
  insert into public.ai_drafts (report_id, team_member_id, client_id, kind, period_start, period_end, version_no)
  values (p_report, m.id, r.client_id, r.kind, r.period_start, r.period_end, r.version_no) returning id into new_id;
  return jsonb_build_object('id', new_id, 'left', lim_member - n_member - 1);
end $$;

create or replace function public.ai_draft_left(p_report uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  m public.team_members;
  since timestamptz := public.ai_draft_day();
  is_adm boolean;
  n_member integer;
  l_report integer; l_member integer; l_min integer;
  lim_member integer;
  lim_report integer;
  v_scope text;
begin
  if not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'denied'); end if;
  is_adm := coalesce(m.is_admin, false);
  lim_member := public.ai_day_cap(m);
  lim_report := case when is_adm then public.ai_draft_limit('report_admin', 5) else public.ai_draft_limit('report', 1) end;
  l_report := greatest(0, lim_report - (select count(*) from public.ai_draft_same(p_report) s
    where s.team_member_id = m.id and s.created_at >= since)::integer);
  select count(*) into n_member from public.ai_drafts d
   where d.team_member_id = m.id and d.created_at >= since and d.outcome <> 'failed';
  l_member := greatest(0, lim_member - n_member);
  l_min := least(l_report, l_member);
  v_scope := case when lim_member = 0 then 'stopped' when l_min = l_report then 'report' else 'person' end;
  return jsonb_build_object(
    'left', l_min, 'scope', v_scope,
    'limit', case v_scope when 'stopped' then 0 when 'report' then lim_report else lim_member end,
    'report', l_report, 'person', l_member, 'admin', is_adm,
    'next', case when l_min > 0 or v_scope = 'stopped' then null else since + interval '1 day' end);
end $$;

create or replace function public.ai_check_claim(p_report uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m public.team_members;
  r public.sm_reports;
  since timestamptz := public.ai_draft_day();
  n_member integer;
  lim_member integer;
  lim_check integer;
  new_id uuid;
begin
  if not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_report;
  if r.id is null or not public.client_seen(r.client_id, 'view') then
    return jsonb_build_object('error', 'not-found');
  end if;
  if r.status not in ('draft', 'review') then return jsonb_build_object('error', 'not-open'); end if;
  -- One count at a time, with the drafts, so the last use is taken once.
  perform pg_advisory_xact_lock(hashtext('ai_draft_claim'));
  lim_member := public.ai_day_cap(m);
  if lim_member = 0 then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'stopped', 'limit', 0);
  end if;
  lim_check := case when coalesce(m.is_admin, false) then public.ai_draft_limit('check_admin', 5)
                    else public.ai_draft_limit('check', 1) end;
  if (select count(*) from public.ai_drafts d
       where d.report_id = p_report and d.purpose = 'check' and d.outcome <> 'failed'
         and d.team_member_id = m.id and d.created_at >= since) >= lim_check then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'report_check', 'limit', lim_check, 'next', since + interval '1 day');
  end if;
  select count(*) into n_member from public.ai_drafts d
   where d.team_member_id = m.id and d.created_at >= since and d.outcome <> 'failed';
  if n_member >= lim_member then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'person', 'limit', lim_member, 'next', since + interval '1 day');
  end if;
  insert into public.ai_drafts (report_id, team_member_id, client_id, kind, period_start, period_end, purpose, version_no)
  values (p_report, m.id, r.client_id, r.kind, r.period_start, r.period_end, 'check', r.version_no) returning id into new_id;
  return jsonb_build_object('id', new_id, 'left', lim_member - n_member - 1);
end $$;

create or replace function public.ai_check_left(p_report uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  m public.team_members;
  r public.sm_reports;
  since timestamptz := public.ai_draft_day();
  is_adm boolean;
  n_member integer;
  l_report integer; l_member integer; l_min integer;
  lim_member integer;
  lim_check integer;
  v_scope text;
begin
  if not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_report;
  if r.id is null or not public.client_seen(r.client_id, 'view') then
    return jsonb_build_object('error', 'not-found');
  end if;
  is_adm := coalesce(m.is_admin, false);
  lim_member := public.ai_day_cap(m);
  lim_check := case when is_adm then public.ai_draft_limit('check_admin', 5) else public.ai_draft_limit('check', 1) end;
  l_report := greatest(0, lim_check - (select count(*) from public.ai_drafts d
    where d.report_id = p_report and d.purpose = 'check' and d.outcome <> 'failed'
      and d.team_member_id = m.id and d.created_at >= since)::integer);
  select count(*) into n_member from public.ai_drafts d
   where d.team_member_id = m.id and d.created_at >= since and d.outcome <> 'failed';
  l_member := greatest(0, lim_member - n_member);
  l_min := least(l_report, l_member);
  v_scope := case when lim_member = 0 then 'stopped' when l_min = l_report then 'report_check' else 'person' end;
  return jsonb_build_object(
    'left', l_min, 'scope', v_scope, 'version', r.version_no,
    'limit', case v_scope when 'stopped' then 0 when 'report_check' then lim_check else lim_member end,
    'report', l_report, 'person', l_member, 'admin', is_adm,
    'next', case when l_min > 0 or v_scope = 'stopped' then null else since + interval '1 day' end);
end $$;

revoke all on function public.ai_draft_claim(uuid) from public, anon, authenticated;
revoke all on function public.ai_draft_left(uuid) from public, anon, authenticated;
revoke all on function public.ai_check_claim(uuid) from public, anon, authenticated;
revoke all on function public.ai_check_left(uuid) from public, anon, authenticated;
grant execute on function public.ai_draft_claim(uuid) to authenticated;
grant execute on function public.ai_draft_left(uuid) to authenticated;
grant execute on function public.ai_check_claim(uuid) to authenticated;
grant execute on function public.ai_check_left(uuid) to authenticated;

-- A colleague's limit a day, or a standard for everyone. Null puts the
-- standard back.
create or replace function public.ai_draft_set_limit(p_scope text, p_daily integer)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_who text;
  v_name text;
  v_was integer;
