-- END OF AI LIMITS A COLLEAGUE A REPORT A DAY --------------------------------

-- ===========================================================================
-- PERFORMANCE REWARD SETTINGS — every amount, threshold and rate the rewards
-- are worked out with is a setting an admin changes from a quarter on;
-- nothing in the rules is a figure typed into the code.
-- 2026-10-05. Safe to run twice. Rollback below. Mirrored byte for byte in
-- supabase/schema.sql under the same banner; tests/perf.js compares the two.
--
-- WHAT CHANGED (the user, 2026-10-05: "please do not make the figures hard
-- coded. what if i need changes the next quarter")
--   1. `perf_settings` (key, from_period, value): a value holds from its
--      quarter until a later row for the same key. RLS on, no policy, no
--      grant. The first run seeds each key's value as the rules stood, from
--      Q3 2026, only where the key has no row.
--   2. `perf_setting(key, at)`: the value in force at a date (else the
--      earliest), for the functions alone.
--   3. `perf_quarter_calc`, `perf_flex_calc`, `perf_period_calc`,
--      `perf_period`, `perf_company_set` and `perf_commission_json` read
--      their figures from it, as at the quarter, month, half or deal month,
--      and say which (`rules`), so a confirmed snapshot keeps the figures it
--      was worked out with.
--   4. `perf_rewards_mine` sends each confirmed quarter's and half's rules.
--   5. The individual prize has no minimum average (the user, 2026-10-05):
--      the highest average among the eligible takes it whole (a tie
--      shares it). The department prize stays the winning department's,
--      its leader deciding the split.
--   6. `perf_settings_read(p_token)` (management, a live unlock): every
--      key's rows and the changes filed; `perf_settings_set(p_token,
--      p_from, p_values)` (an admin, a live unlock): from a quarter on, never
--      into a quarter or half already confirmed (`confirmed`), each value in
--      its bounds (`bad-value`); a save that changes nothing files nothing,
--      else `settings_set` with each key from and to.
--
-- ROLLBACK
--   Run the PERFORMANCE REWARDS and PERFORMANCE QUARTER RANKED sections'
--   functions named in 3 again; then, in the SQL Editor, drop
--   perf_settings_set, perf_settings_read, perf_setting and the table.
-- ===========================================================================

create table if not exists public.perf_settings (
  key         text not null,
  from_period date not null check (from_period >= date '2026-07-01'
                                    and extract(day from from_period) = 1 and extract(month from from_period) in (1, 4, 7, 10)),
  value       numeric(14,2) not null,
  set_by      uuid references public.team_members(id) on delete set null,
  set_at      timestamptz not null default now(),
  primary key (key, from_period)
);
alter table public.perf_settings enable row level security;
revoke all on table public.perf_settings from public, anon, authenticated;

-- The rules as they stood, from Q3 2026, into a key that has no row.
insert into public.perf_settings (key, from_period, value)
select k.key, date '2026-07-01', k.value
  from (values ('prize_individual', 400),
               ('prize_department', 600), ('prize_department_min_total', 80),
               ('flex_team_share', 50), ('flex_member_min', 70),
               ('bonus_pool_revenue', 500000), ('bonus_pool_profit_pct', 10), ('trip_revenue', 1000000),
               ('bonus_months_b', 3), ('units_a', 3), ('units_b', 1.5), ('units_c', 0.5),
               ('commission_min', 70)) k(key, value)
 where not exists (select 1 from public.perf_settings s where s.key = k.key);

-- The value in force at a date: the latest row from or before it, else the
-- earliest row (a date before the first quarter).
create or replace function public.perf_setting(p_key text, p_at date)
returns numeric
language sql stable security definer set search_path = public as $$
  select coalesce(
    (select s.value from public.perf_settings s where s.key = p_key and s.from_period <= p_at
      order by s.from_period desc limit 1),
    (select s.value from public.perf_settings s where s.key = p_key order by s.from_period limit 1))
$$;
revoke all on function public.perf_setting(text, date) from public, anon, authenticated;

create or replace function public.perf_quarter_calc(p_quarter date)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_q date := date_trunc('quarter', p_quarter)::date;
  v_qe date := (date_trunc('quarter', p_quarter) + interval '3 months')::date;
  v_people jsonb; v_wins integer; v_each numeric; v_ind jsonb;
  v_depts jsonb; v_dwins integer; v_both boolean; v_why text; v_dp jsonb;
  v_open integer; v_missing integer;
  v_ip numeric := public.perf_setting('prize_individual', date_trunc('quarter', p_quarter)::date);
  v_dpool numeric := public.perf_setting('prize_department', date_trunc('quarter', p_quarter)::date);
  v_dmin numeric := public.perf_setting('prize_department_min_total', date_trunc('quarter', p_quarter)::date);
begin
  with m as (
    select t.id as mid, t.name as mname, t.staff_code as mcode, t.department as mdept, t.active as mactive,
           public.perf_reviewed(t.id) as monlist, f.nmonths, f.mean, f.emonth,
           (select count(*)::int from public.perf_reviews o
             where o.team_member_id = t.id and o.status <> 'final'
               and o.period >= v_q and o.period < v_qe) as nopen,
           exists (select 1 from public.perf_breaches b
                    where b.team_member_id = t.id and b.voided_at is null and b.severity = 4
                      and b.period >= v_q and b.period < v_qe) as ml4
      from public.team_members t
      cross join lateral (
        select count(*)::int as nmonths, round(avg((x.res ->> 'final')::numeric), 2) as mean,
               coalesce(bool_or(x.res ->> 'grade' = 'E'), false) as emonth
          from (select coalesce(r.result, public.perf_calc(r)) as res
                  from public.perf_reviews r
                 where r.team_member_id = t.id and r.status = 'final'
                   and r.period >= v_q and r.period < v_qe) x) f
     where f.nmonths > 0 or (t.active and public.perf_reviewed(t.id))
  ), e as (
    select m.*, array_remove(array[
             case when m.nmonths = 0 then 'no-final-month' end,
             case when m.emonth then 'e-month' end,
             case when m.ml4 then 'critical-breach' end,
             case when not m.mactive then 'inactive' end,
             case when not m.monlist then 'not-reviewed' end], null) as why
      from m
  ), w as (
    select e.*, cardinality(e.why) = 0 as ok,
           coalesce(cardinality(e.why) = 0
                    and e.mean = max(e.mean) filter (where cardinality(e.why) = 0) over (), false) as won
      from e
  ), p as (
    select w.*, count(*) filter (where w.won) over () as nwon,
           case when w.nmonths > 0 then rank() over (order by w.mean desc nulls last) end as mrank
      from w
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'team_member_id', p.mid, 'name', p.mname, 'staff_code', p.mcode, 'department', p.mdept,
           'active', p.mactive, 'reviewed', p.monlist, 'months', p.nmonths, 'open', p.nopen,
           'rank', p.mrank, 'average', p.mean,
           'grade', case when p.nmonths > 0 then public.perf_grade_of(p.mean) end,
           'e_month', p.emonth, 'l4', p.ml4, 'eligible', p.ok, 'reasons', to_jsonb(p.why),
           'prize', case when p.won then floor(v_ip * 100 / p.nwon) / 100 else 0 end)
         order by p.mean desc nulls last, p.mname), '[]'::jsonb),
         coalesce(max(p.nwon), 0)
    into v_people, v_wins
    from p;
  v_each := case when v_wins > 0 then floor(v_ip * 100 / v_wins) / 100 end;
  v_ind := jsonb_build_object('pool', v_ip, 'winners', v_wins, 'each', v_each,
    'paid', coalesce(v_each * v_wins, 0), 'remainder', v_ip - coalesce(v_each * v_wins, 0),
    'reason', case when v_wins = 0 then 'nobody-eligible' end);

  with d as (
    select k.dep, s.c1, s.c2, s.c3, s.c4, s.c5, coalesce(s.critical, false) as crit,
           s.c1 + s.c2 + s.c3 + s.c4 + s.c5 as total, s.quarter is not null as entered, k.ord
      from (values ('creative', 1), ('marketing', 2)) k(dep, ord)
      left join public.perf_dept_scores s on s.quarter = v_q and s.department = k.dep
  ), x as (
    select d.*, bool_and(d.entered) over () as bothin,
           coalesce(d.total = max(d.total) over (), false) as istop
      from d
  ), y as (
    select x.*, (x.bothin and x.istop and x.total >= v_dmin and not x.crit) as won,
           coalesce((select array_agg(t.id order by t.name) from public.team_members t
                      where t.active and t.department = x.dep and public.perf_reviewed(t.id)), '{}'::uuid[]) as mems
      from x
  ), z as (
    select y.*, count(*) filter (where y.won) over () as nwon,
           case when y.won then floor((v_dpool * 100) / count(*) filter (where y.won) over ()) end as sharec
      from y
  )
  select jsonb_agg(jsonb_build_object(
           'department', z.dep, 'entered', z.entered,
           'criteria', case when z.entered then jsonb_build_array(z.c1, z.c2, z.c3, z.c4, z.c5) end,
           'total', z.total, 'grade', case when z.entered then public.perf_grade_of(z.total) end,
           'critical', z.crit, 'top', z.bothin and z.istop,
           'qualifies', z.entered and z.total >= v_dmin and not z.crit, 'won', z.won,
           'share', coalesce(z.sharec / 100, 0), 'members', to_jsonb(z.mems))
         order by z.ord),
         coalesce(max(z.nwon), 0), bool_and(z.bothin),
         case when bool_and(z.bothin) and max(z.nwon) = 0 then
           case when bool_or(z.istop and z.total >= v_dmin and z.crit) then 'critical-issue' else 'below-b' end end
    into v_depts, v_dwins, v_both, v_why
    from z;
  v_dp := jsonb_build_object('pool', v_dpool, 'winners', v_dwins,
    'paid', case when v_dwins > 0 then floor((v_dpool * 100) / v_dwins) * v_dwins / 100 else 0 end,
    'remainder', case when v_dwins > 0 then v_dpool - floor((v_dpool * 100) / v_dwins) * v_dwins / 100 else v_dpool end,
    'reason', case when not v_both then 'scores-needed' else v_why end);

  select count(*)::int into v_open
    from public.perf_reviews r
   where r.status <> 'final' and r.period >= v_q and r.period < v_qe;
  select count(*)::int into v_missing
    from public.team_members t
    cross join generate_series(v_q, (v_qe - interval '1 month')::date, interval '1 month') g(mo)
   where t.active and public.perf_reviewed(t.id)
     and (g.mo + interval '1 month')::date <= public.perf_today()
     and not exists (select 1 from public.perf_reviews r where r.team_member_id = t.id and r.period = g.mo::date);

  return jsonb_build_object('quarter', v_q, 'word', public.perf_quarter_word(v_q),
    'ended', public.perf_today() >= v_qe, 'people', v_people, 'individual', v_ind,
    'departments', v_depts, 'department_prize', v_dp,
    'open_months', v_open, 'missing_months', v_missing,
    'rules', jsonb_build_object('individual', v_ip, 'department', v_dpool, 'min_total', v_dmin));
end $$;

create or replace function public.perf_flex_calc(p_period date)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_p date := date_trunc('month', p_period)::date;
  v_total integer; v_finals integer; v_at integer; v_rows jsonb;
  v_share numeric := public.perf_setting('flex_team_share', date_trunc('month', p_period)::date);
  v_fmin numeric := public.perf_setting('flex_member_min', date_trunc('month', p_period)::date);
begin
  with m as (
    select t.id as mid, t.name as mname, t.staff_code as mcode,
           case when r.id is not null then coalesce(r.result, public.perf_calc(r)) end as res
      from public.team_members t
      left join public.perf_reviews r on r.team_member_id = t.id and r.period = v_p and r.status = 'final'
     where t.active and public.perf_reviewed(t.id)
  )
  select count(*)::int, count(m.res)::int,
         (count(*) filter (where (m.res ->> 'final')::numeric >= v_fmin))::int,
         coalesce(jsonb_agg(jsonb_build_object('team_member_id', m.mid, 'name', m.mname, 'staff_code', m.mcode,
           'final', m.res -> 'final', 'grade', m.res ->> 'grade',
           'breach', coalesce((m.res ->> 'l3')::boolean or (m.res ->> 'l4')::boolean, false),
           'eligible', coalesce((m.res ->> 'final')::numeric >= v_fmin
                                and not (m.res ->> 'l3')::boolean and not (m.res ->> 'l4')::boolean, false))
           order by m.mname), '[]'::jsonb)
    into v_total, v_finals, v_at, v_rows
    from m;
  return jsonb_build_object('period', v_p, 'month', public.perf_month_word(v_p),
    'next', (v_p + interval '1 month')::date,
    'next_month', public.perf_month_word((v_p + interval '1 month')::date),
    'members', v_total, 'finals', v_finals, 'at_70', v_at,
    'decided', v_total > 0 and v_finals = v_total,
    'unlocked', v_total > 0 and v_finals = v_total and v_at * 100 >= v_total * v_share,
    'people', v_rows, 'rules', jsonb_build_object('share', v_share, 'min', v_fmin));
end $$;

create or replace function public.perf_period_calc(p_from date)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_f date := public.perf_half(p_from);
  v_t date := (public.perf_half(p_from) + interval '6 months')::date;
  v_c public.perf_company; v_pool numeric; v_trip numeric; v_popen boolean; v_topen boolean;
  v_rows jsonb; v_units numeric; v_bpaid numeric; v_tpaid numeric;
  v_prev numeric := public.perf_setting('bonus_pool_revenue', public.perf_half(p_from));
  v_trev numeric := public.perf_setting('trip_revenue', public.perf_half(p_from));
  v_nb numeric := public.perf_setting('bonus_months_b', public.perf_half(p_from));
  v_ua numeric := public.perf_setting('units_a', public.perf_half(p_from));
  v_ub numeric := public.perf_setting('units_b', public.perf_half(p_from));
  v_uc numeric := public.perf_setting('units_c', public.perf_half(p_from));
begin
  select * into v_c from public.perf_company where period = v_f;
  v_popen := coalesce(v_c.revenue, 0) >= v_prev;
  v_topen := coalesce(v_c.revenue, 0) >= v_trev;
  v_pool := case when v_popen then coalesce(v_c.pool, 0) else 0 end;
  v_trip := case when v_topen then coalesce(v_c.trip_budget, 0) else 0 end;
  with m as (
    select t.id as mid, t.name as mname, t.staff_code as mcode, t.active as mactive,
           f.nmonths, f.nb, f.mean, f.emonth,
           exists (select 1 from public.perf_breaches b
                    where b.team_member_id = t.id and b.voided_at is null and b.severity = 4
                      and b.period >= v_f and b.period < v_t) as ml4
      from public.team_members t
      cross join lateral (
        select count(*)::int as nmonths,
               (count(*) filter (where x.res ->> 'grade' in ('A', 'B')))::int as nb,
               round(avg((x.res ->> 'final')::numeric), 2) as mean,
               coalesce(bool_or(x.res ->> 'grade' = 'E'), false) as emonth
          from (select coalesce(r.result, public.perf_calc(r)) as res
                  from public.perf_reviews r
                 where r.team_member_id = t.id and r.status = 'final'
                   and r.period >= v_f and r.period < v_t) x) f
     where f.nmonths > 0 or (t.active and public.perf_reviewed(t.id))
  ), e as (
    select m.*, array_remove(array[
             case when m.nmonths = 0 then 'no-final-month' end,
             case when m.nmonths > 0 and m.nb < v_nb then 'few-b-months' end,
             case when m.emonth then 'e-month' end,
             case when m.ml4 then 'critical-breach' end,
             case when not m.mactive then 'inactive' end], null) as why
      from m
  ), u as (
    select e.*, cardinality(e.why) = 0 as ok,
           case when cardinality(e.why) = 0 then
             case public.perf_grade_of(e.mean) when 'A' then v_ua when 'B' then v_ub when 'C' then v_uc else 0 end
           else 0 end as units
      from e
  ), s as (
    select u.*, sum(u.units) over () as allunits from u
  ), o as (
    select s.*,
           case when s.allunits > 0 then floor(v_pool * 100 * s.units / s.allunits) / 100 else 0 end as bonus,
           case when s.allunits > 0 then floor(v_trip * 100 * s.units / s.allunits) / 100 else 0 end as tripshare
      from s
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'team_member_id', o.mid, 'name', o.mname, 'staff_code', o.mcode, 'active', o.mactive,
           'months', o.nmonths, 'months_b', o.nb, 'average', o.mean,
           'grade', case when o.nmonths > 0 then public.perf_grade_of(o.mean) end,
           'e_month', o.emonth, 'l4', o.ml4, 'eligible', o.ok, 'reasons', to_jsonb(o.why),
           'units', o.units, 'bonus', o.bonus, 'trip', o.tripshare)
         order by o.ok desc, o.units desc, o.mean desc nulls last, o.mname), '[]'::jsonb),
         coalesce(sum(o.units), 0), coalesce(sum(o.bonus), 0), coalesce(sum(o.tripshare), 0)
    into v_rows, v_units, v_bpaid, v_tpaid
    from o;
  return jsonb_build_object('period', v_f, 'word', public.perf_period_word(v_f),
    'last_month', (v_t - interval '1 month')::date, 'ended', public.perf_today() >= v_t,
    'figures', v_c.period is not null, 'total_units', v_units, 'people', v_rows,
    'rules', jsonb_build_object('pool_revenue', v_prev, 'trip_revenue', v_trev, 'months_b', v_nb,
      'units_a', v_ua, 'units_b', v_ub, 'units_c', v_uc,
      'pool_pct', public.perf_setting('bonus_pool_profit_pct', public.perf_half(p_from))),
    'bonus', jsonb_build_object('open', v_popen, 'pool', v_pool, 'paid', v_bpaid, 'remainder', v_pool - v_bpaid,
      'reason', case when v_c.period is null then 'figures-needed' when not v_popen then 'below-gate'
                     when v_pool = 0 then 'no-pool' when v_units = 0 then 'nobody-eligible' end),
    'trip', jsonb_build_object('open', v_topen, 'budget', v_trip, 'paid', v_tpaid, 'remainder', v_trip - v_tpaid,
      'reason', case when v_c.period is null then 'figures-needed' when not v_topen then 'below-gate'
                     when v_trip = 0 then 'no-budget' when v_units = 0 then 'nobody-eligible' end));
end $$;

create or replace function public.perf_period(p_token text, p_from date)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_err text; v_me public.team_members; v_f date; v_rw public.perf_rewards; v_c public.perf_company; v_out jsonb;
begin
  v_err := public.perf_check(p_token, 'view');
  if v_err is not null then return jsonb_build_object('error', v_err); end if;
  v_me := public.ops_me();
  v_f := public.perf_half(coalesce(p_from, public.perf_today()));
  if v_f < date '2026-07-01' then return jsonb_build_object('error', 'before-first'); end if;
  select * into v_rw from public.perf_rewards where kind = 'period' and period = v_f;
  v_out := coalesce(v_rw.snapshot, public.perf_period_calc(v_f));
  v_out := v_out || jsonb_build_object(
    'people', public.perf_hide_own(v_out -> 'people', v_me.id),
    'admin', public.perf_is_admin(),
    'confirmed', v_rw.period is not null, 'confirmed_at', v_rw.confirmed_at,
    'confirmed_by', (select t.name from public.team_members t where t.id = v_rw.confirmed_by),
    'ended', public.perf_today() >= (v_f + interval '6 months')::date,
    'events', public.perf_reward_events(array['company_set', 'period_confirmed', 'period_reopened'], v_f::text));
  /* Revenue and profit, and the ceiling they set, for an admin alone. */
  if public.perf_is_admin() then
    select * into v_c from public.perf_company where period = v_f;
    if v_c.period is not null then
      v_out := v_out || jsonb_build_object('company', jsonb_build_object('revenue', v_c.revenue, 'profit', v_c.profit,
        'pool', v_c.pool, 'trip_budget', v_c.trip_budget, 'max_pool', greatest(0, floor(v_c.profit * public.perf_setting('bonus_pool_profit_pct', v_f)) / 100)));
    end if;
  end if;
  return v_out;
end $$;

create or replace function public.perf_company_set(p_token text, p_from date, p_payload jsonb)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_err text; v_me public.team_members; v_f date; v_rev numeric; v_pro numeric; v_pool numeric; v_trip numeric;
  v_was public.perf_company; v_max numeric; v_changed jsonb := '[]'::jsonb;
  v_prev numeric; v_trev numeric; v_pct numeric;
begin
  v_err := public.perf_check(p_token, 'work');
  if v_err is not null then return jsonb_build_object('error', v_err); end if;
  if not public.perf_is_admin() then return jsonb_build_object('error', 'admin-only'); end if;
  v_me := public.ops_me();
  v_f := public.perf_half(p_from);
  if v_f is null or v_f < date '2026-07-01' then return jsonb_build_object('error', 'before-first'); end if;
  if exists (select 1 from public.perf_rewards where kind = 'period' and period = v_f) then
    return jsonb_build_object('error', 'confirmed');
  end if;
  if coalesce(jsonb_typeof(p_payload -> 'revenue'), '') <> 'number'
     or coalesce(jsonb_typeof(p_payload -> 'profit'), '') <> 'number'
     or coalesce(jsonb_typeof(p_payload -> 'pool'), 'number') not in ('number', 'null')
     or coalesce(jsonb_typeof(p_payload -> 'trip_budget'), 'number') not in ('number', 'null') then
    return jsonb_build_object('error', 'bad-amount');
  end if;
  v_rev := (p_payload ->> 'revenue')::numeric;
  v_pro := (p_payload ->> 'profit')::numeric;
  v_pool := coalesce((p_payload ->> 'pool')::numeric, 0);
  v_trip := coalesce((p_payload ->> 'trip_budget')::numeric, 0);
  if v_rev < 0 or v_pool < 0 or v_trip < 0
     or round(v_rev, 2) <> v_rev or round(v_pro, 2) <> v_pro or round(v_pool, 2) <> v_pool or round(v_trip, 2) <> v_trip
     or greatest(abs(v_rev), abs(v_pro), v_pool, v_trip) >= 1e12 then
    return jsonb_build_object('error', 'bad-amount');
  end if;
  v_prev := public.perf_setting('bonus_pool_revenue', v_f);
  v_trev := public.perf_setting('trip_revenue', v_f);
  v_pct := public.perf_setting('bonus_pool_profit_pct', v_f);
  v_max := greatest(0, floor(v_pro * v_pct) / 100);
  if v_pool > 0 and v_rev < v_prev then return jsonb_build_object('error', 'pool-closed', 'at', v_prev); end if;
  if v_pool > v_max then return jsonb_build_object('error', 'pool-over', 'max', v_max, 'pct', v_pct); end if;
  if v_trip > 0 and v_rev < v_trev then return jsonb_build_object('error', 'trip-closed', 'at', v_trev); end if;
  select * into v_was from public.perf_company where period = v_f for update;
  insert into public.perf_company (period, revenue, profit, pool, trip_budget, entered_by, updated_at)
  values (v_f, v_rev, v_pro, v_pool, v_trip, v_me.id, now())
  on conflict (period) do update set revenue = excluded.revenue, profit = excluded.profit, pool = excluded.pool,
    trip_budget = excluded.trip_budget, entered_by = excluded.entered_by, updated_at = now();
  /* Revenue and profit are filed by name only, so the history an admin
     shares with the rest of management never carries them. */
  if v_was.revenue is distinct from v_rev then v_changed := v_changed || '[{"key":"revenue"}]'::jsonb; end if;
  if v_was.profit is distinct from v_pro then v_changed := v_changed || '[{"key":"profit"}]'::jsonb; end if;
  if v_was.pool is distinct from v_pool then
    v_changed := v_changed || jsonb_build_array(jsonb_build_object('key', 'pool', 'from', v_was.pool, 'to', v_pool));
  end if;
  if v_was.trip_budget is distinct from v_trip then
    v_changed := v_changed || jsonb_build_array(jsonb_build_object('key', 'trip_budget', 'from', v_was.trip_budget, 'to', v_trip));
  end if;
  if jsonb_array_length(v_changed) > 0 then
    perform public.perf_log(null, null, 'company_set', jsonb_build_object('key', v_f::text, 'changed', v_changed));
  end if;
  return public.perf_period(p_token, v_f);
end $$;

create or replace function public.perf_commission_json(c public.perf_commissions)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_r public.perf_reviews; v_res jsonb; v_state text; v_why text;
begin
  select * into v_r from public.perf_reviews where team_member_id = c.team_member_id and period = c.month;
  v_res := case when v_r.id is not null and v_r.status = 'final' then coalesce(v_r.result, public.perf_calc(v_r)) end;
  if v_res is null then
    v_state := 'pending'; v_why := 'month-not-final';
  elsif (v_res ->> 'final')::numeric < public.perf_setting('commission_min', c.month) then
    v_state := 'not-payable'; v_why := 'below-c';
  elsif coalesce((v_res ->> 'l3')::boolean, false) or coalesce((v_res ->> 'l4')::boolean, false) then
    v_state := 'not-payable'; v_why := 'breach';
  else
    v_state := 'payable';
  end if;
  return jsonb_build_object('id', c.id, 'team_member_id', c.team_member_id,
    'name', (select t.name from public.team_members t where t.id = c.team_member_id),
    'staff_code', (select t.staff_code from public.team_members t where t.id = c.team_member_id),
    'client_id', c.client_id,
    'client', (select cl.name from public.clients cl where cl.id = c.client_id),
    'client_code', (select cl.client_code from public.clients cl where cl.id = c.client_id),
    'description', c.description, 'month', c.month, 'month_word', public.perf_month_word(c.month),
    'net_profit', c.net_profit, 'pct', c.pct, 'amount', round(c.net_profit * c.pct / 100, 2),
    'state', v_state, 'reason', v_why, 'created_at', c.created_at,
    'created_by', (select t.name from public.team_members t where t.id = c.created_by),
    'removed_at', c.removed_at, 'min', public.perf_setting('commission_min', c.month));
end $$;

/* The member reads the rules their own quarter and half were worked out with. */
create or replace function public.perf_rewards_mine()
returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_me public.team_members; v_id text;
begin
  v_me := public.ops_me();
  if v_me.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if public.perf_guarded(v_me.id) and not public.perf_code_fresh() then
    return jsonb_build_object('error', 'code-needed');
  end if;
  v_id := v_me.id::text;
  return jsonb_build_object(
    'quarters', coalesce((
      select jsonb_agg(jsonb_build_object('quarter', rw.period, 'word', rw.snapshot ->> 'word',
               'confirmed_at', rw.confirmed_at, 'me', me_row - 'rank', 'rules', rw.snapshot -> 'rules',
               'individual', jsonb_build_object('winners', rw.snapshot -> 'individual' -> 'winners',
                                                'reason', rw.snapshot -> 'individual' -> 'reason'),
               'department', (select jsonb_build_object('department', d ->> 'department', 'total', d -> 'total',
                                       'grade', d -> 'grade', 'won', d -> 'won', 'share', d -> 'share')
                                from jsonb_array_elements(rw.snapshot -> 'departments') d
                               where d -> 'members' ? v_id limit 1))
             order by rw.period desc)
        from public.perf_rewards rw
        cross join lateral (select p as me_row from jsonb_array_elements(rw.snapshot -> 'people') p
                             where p ->> 'team_member_id' = v_id limit 1) mine
       where rw.kind = 'quarter'), '[]'::jsonb),
    'periods', coalesce((
      select jsonb_agg(jsonb_build_object('period', rw.period, 'word', rw.snapshot ->> 'word',
               'confirmed_at', rw.confirmed_at, 'me', me_row, 'rules', rw.snapshot -> 'rules',
               'bonus_open', rw.snapshot -> 'bonus' -> 'open', 'trip_open', rw.snapshot -> 'trip' -> 'open')
             order by rw.period desc)
        from public.perf_rewards rw
        cross join lateral (select p as me_row from jsonb_array_elements(rw.snapshot -> 'people') p
                             where p ->> 'team_member_id' = v_id limit 1) mine
       where rw.kind = 'period'), '[]'::jsonb),
    'flex', coalesce((
      select jsonb_agg(jsonb_build_object('period', f.fx ->> 'period', 'month', f.fx ->> 'month',
               'next_month', f.fx ->> 'next_month', 'unlocked', f.fx -> 'unlocked',
               'eligible', (select p -> 'eligible' from jsonb_array_elements(f.fx -> 'people') p
                             where p ->> 'team_member_id' = v_id limit 1))
             order by f.pd desc)
        from (select r.period as pd, public.perf_flex_calc(r.period) as fx
                from public.perf_reviews r
               where r.team_member_id = v_me.id and r.status = 'final') f
       where (f.fx ->> 'decided')::boolean
         and exists (select 1 from jsonb_array_elements(f.fx -> 'people') p where p ->> 'team_member_id' = v_id)), '[]'::jsonb),
    'commissions', coalesce((
      select jsonb_agg(x.j - 'created_by' - 'removed_at' - 'name' - 'staff_code' order by x.mo desc, x.ca desc)
        from (select public.perf_commission_json(c) as j, c.month as mo, c.created_at as ca
                from public.perf_commissions c
               where c.team_member_id = v_me.id and c.removed_at is null) x
       where x.j ->> 'state' <> 'pending'), '[]'::jsonb));
end $$;

-- Every key's values by quarter, and the changes filed, for management.
create or replace function public.perf_settings_read(p_token text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_err text;
begin
  v_err := public.perf_check(p_token, 'view');
  if v_err is not null then return jsonb_build_object('error', v_err); end if;
  return jsonb_build_object(
    'admin', public.perf_is_admin(),
    'settings', coalesce((select jsonb_agg(jsonb_build_object('key', s.key, 'from', s.from_period,
        'word', public.perf_quarter_word(s.from_period), 'value', s.value,
        'by', (select t.name from public.team_members t where t.id = s.set_by), 'at', s.set_at)
        order by s.key, s.from_period) from public.perf_settings s), '[]'::jsonb),
    'confirmed', jsonb_build_object(
      'quarter', (select max(r.period) from public.perf_rewards r where r.kind = 'quarter'),
      'period', (select max(r.period) from public.perf_rewards r where r.kind = 'period')),
    'events', public.perf_reward_events(array['settings_set'], null));
end $$;

-- From a quarter on, an admin's. A quarter or a half already confirmed keeps
-- its figures: a change never reaches into one.
create or replace function public.perf_settings_set(p_token text, p_from date, p_values jsonb)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_err text; v_me public.team_members; v_from date; v_k text; v_v numeric; v_was numeric;
  v_changed jsonb := '[]'::jsonb;
  v_keys constant text[] := array['prize_individual', 'prize_department', 'prize_department_min_total',
    'flex_team_share', 'flex_member_min', 'bonus_pool_revenue',
    'bonus_pool_profit_pct', 'trip_revenue', 'bonus_months_b', 'units_a', 'units_b', 'units_c', 'commission_min'];
begin
  v_err := public.perf_check(p_token, 'work');
  if v_err is not null then return jsonb_build_object('error', v_err); end if;
  if not public.perf_is_admin() then return jsonb_build_object('error', 'admin-only'); end if;
  v_me := public.ops_me();
  v_from := date_trunc('quarter', p_from)::date;
  if v_from is null or v_from < date '2026-07-01' then return jsonb_build_object('error', 'before-first'); end if;
  if jsonb_typeof(p_values) is distinct from 'object' then return jsonb_build_object('error', 'bad-value'); end if;
  if exists (select 1 from public.perf_rewards r
              where (r.kind = 'quarter' and r.period >= v_from)
                 or (r.kind = 'period' and (r.period + interval '6 months')::date > v_from)) then
    return jsonb_build_object('error', 'confirmed');
  end if;
  for v_k in select jsonb_object_keys(p_values) loop
    if not (v_k = any(v_keys)) or jsonb_typeof(p_values -> v_k) <> 'number' then
      return jsonb_build_object('error', 'bad-value', 'key', v_k);
    end if;
    v_v := (p_values ->> v_k)::numeric;
    if v_v < 0 or round(v_v, 2) <> v_v
       or (v_k in ('prize_individual', 'prize_department', 'bonus_pool_revenue', 'trip_revenue') and v_v >= 1e9)
       or (v_k in ('prize_department_min_total', 'flex_team_share', 'flex_member_min',
                   'bonus_pool_profit_pct', 'commission_min') and v_v > 100)
       or (v_k = 'bonus_months_b' and (v_v > 6 or v_v <> trunc(v_v)))
       or (v_k in ('units_a', 'units_b', 'units_c') and v_v > 10) then
      return jsonb_build_object('error', 'bad-value', 'key', v_k);
    end if;
  end loop;
  for v_k in select jsonb_object_keys(p_values) loop
    v_v := (p_values ->> v_k)::numeric;
    v_was := public.perf_setting(v_k, v_from);
    if v_was is distinct from v_v then
      insert into public.perf_settings (key, from_period, value, set_by, set_at)
      values (v_k, v_from, v_v, v_me.id, now())
      on conflict (key, from_period) do update set value = excluded.value, set_by = excluded.set_by, set_at = now();
      v_changed := v_changed || jsonb_build_array(jsonb_build_object('key', v_k, 'from', v_was, 'to', v_v));
    end if;
  end loop;
  if jsonb_array_length(v_changed) > 0 then
    perform public.perf_log(null, null, 'settings_set', jsonb_build_object('from_period', v_from,
      'word', public.perf_quarter_word(v_from), 'changed', v_changed));
  end if;
  return public.perf_settings_read(p_token);
end $$;

revoke all on function public.perf_settings_read(text) from public, anon, authenticated;
revoke all on function public.perf_settings_set(text, date, jsonb) from public, anon, authenticated;
grant execute on function public.perf_settings_read(text) to authenticated;
grant execute on function public.perf_settings_set(text, date, jsonb) to authenticated;

-- END OF PERFORMANCE REWARD SETTINGS ------------------------------------------

-- ===========================================================================
-- PERFORMANCE QUARTER LIVE — the quarter is ranked as its months are
-- released, not only once all three are final.
-- 2026-10-05. Safe to run twice. Rollback below. Mirrored byte for byte in
-- supabase/schema.sql under the same banner; tests/perf.js compares the two.
--
-- WHAT CHANGED (the user, 2026-10-05: "since i have alr added Q3 (july and
-- august 2026) data ... could alr started just that it is not final until
-- the full three months per quarter has alr updated ... management would be
-- able to view it the realtime sequence")
--   1. `perf_quarter_calc` averages, ranks and names the leader from every
--      month released to its member (any state but draft), not from final
--      months alone. Each row says how many of its months are final
--      (`finals`); a person with no released month reads `no-month`.
--   2. The quarter says `provisional` while it runs, a month is not final,
--      or an ended month was never entered. Confirm is unchanged: it still
--      waits for every month to be final, so a confirmed quarter is never
--      provisional.
--
-- ROLLBACK
--   Run the PERFORMANCE REWARD SETTINGS section's perf_quarter_calc again.
-- ===========================================================================

create or replace function public.perf_quarter_calc(p_quarter date)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_q date := date_trunc('quarter', p_quarter)::date;
  v_qe date := (date_trunc('quarter', p_quarter) + interval '3 months')::date;
  v_people jsonb; v_wins integer; v_each numeric; v_ind jsonb;
  v_depts jsonb; v_dwins integer; v_both boolean; v_why text; v_dp jsonb;
  v_open integer; v_missing integer; v_ended boolean := public.perf_today() >= (date_trunc('quarter', p_quarter) + interval '3 months')::date;
  v_ip numeric := public.perf_setting('prize_individual', date_trunc('quarter', p_quarter)::date);
  v_dpool numeric := public.perf_setting('prize_department', date_trunc('quarter', p_quarter)::date);
  v_dmin numeric := public.perf_setting('prize_department_min_total', date_trunc('quarter', p_quarter)::date);
begin
  with m as (
    select t.id as mid, t.name as mname, t.staff_code as mcode, t.department as mdept, t.active as mactive,
           public.perf_reviewed(t.id) as monlist, f.nmonths, f.nfinal, f.mean, f.emonth,
           (select count(*)::int from public.perf_reviews o
             where o.team_member_id = t.id and o.status <> 'final'
               and o.period >= v_q and o.period < v_qe) as nopen,
           exists (select 1 from public.perf_breaches b
                    where b.team_member_id = t.id and b.voided_at is null and b.severity = 4
                      and b.period >= v_q and b.period < v_qe) as ml4
      from public.team_members t
      cross join lateral (
        select count(*)::int as nmonths, (count(*) filter (where x.st = 'final'))::int as nfinal,
               round(avg((x.res ->> 'final')::numeric), 2) as mean,
               coalesce(bool_or(x.res ->> 'grade' = 'E'), false) as emonth
          from (select coalesce(r.result, public.perf_calc(r)) as res, r.status as st
                  from public.perf_reviews r
                 where r.team_member_id = t.id and r.status <> 'draft'
                   and r.period >= v_q and r.period < v_qe) x) f
     where f.nmonths > 0 or (t.active and public.perf_reviewed(t.id))
  ), e as (
    select m.*, array_remove(array[
             case when m.nmonths = 0 then 'no-month' end,
             case when m.emonth then 'e-month' end,
             case when m.ml4 then 'critical-breach' end,
             case when not m.mactive then 'inactive' end,
             case when not m.monlist then 'not-reviewed' end], null) as why
      from m
  ), w as (
    select e.*, cardinality(e.why) = 0 as ok,
           coalesce(cardinality(e.why) = 0
                    and e.mean = max(e.mean) filter (where cardinality(e.why) = 0) over (), false) as won
      from e
  ), p as (
    select w.*, count(*) filter (where w.won) over () as nwon,
           case when w.nmonths > 0 then rank() over (order by w.mean desc nulls last) end as mrank
      from w
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'team_member_id', p.mid, 'name', p.mname, 'staff_code', p.mcode, 'department', p.mdept,
           'active', p.mactive, 'reviewed', p.monlist, 'months', p.nmonths, 'finals', p.nfinal, 'open', p.nopen,
           'rank', p.mrank, 'average', p.mean,
           'grade', case when p.nmonths > 0 then public.perf_grade_of(p.mean) end,
           'e_month', p.emonth, 'l4', p.ml4, 'eligible', p.ok, 'reasons', to_jsonb(p.why),
           'prize', case when p.won then floor(v_ip * 100 / p.nwon) / 100 else 0 end)
         order by p.mean desc nulls last, p.mname), '[]'::jsonb),
         coalesce(max(p.nwon), 0)
    into v_people, v_wins
    from p;
  v_each := case when v_wins > 0 then floor(v_ip * 100 / v_wins) / 100 end;
  v_ind := jsonb_build_object('pool', v_ip, 'winners', v_wins, 'each', v_each,
    'paid', coalesce(v_each * v_wins, 0), 'remainder', v_ip - coalesce(v_each * v_wins, 0),
    'reason', case when v_wins = 0 then 'nobody-eligible' end);

  with d as (
    select k.dep, s.c1, s.c2, s.c3, s.c4, s.c5, coalesce(s.critical, false) as crit,
           s.c1 + s.c2 + s.c3 + s.c4 + s.c5 as total, s.quarter is not null as entered, k.ord
      from (values ('creative', 1), ('marketing', 2)) k(dep, ord)
      left join public.perf_dept_scores s on s.quarter = v_q and s.department = k.dep
  ), x as (
    select d.*, bool_and(d.entered) over () as bothin,
           coalesce(d.total = max(d.total) over (), false) as istop
      from d
  ), y as (
    select x.*, (x.bothin and x.istop and x.total >= v_dmin and not x.crit) as won,
           coalesce((select array_agg(t.id order by t.name) from public.team_members t
                      where t.active and t.department = x.dep and public.perf_reviewed(t.id)), '{}'::uuid[]) as mems
      from x
  ), z as (
    select y.*, count(*) filter (where y.won) over () as nwon,
           case when y.won then floor((v_dpool * 100) / count(*) filter (where y.won) over ()) end as sharec
      from y
  )
  select jsonb_agg(jsonb_build_object(
           'department', z.dep, 'entered', z.entered,
           'criteria', case when z.entered then jsonb_build_array(z.c1, z.c2, z.c3, z.c4, z.c5) end,
           'total', z.total, 'grade', case when z.entered then public.perf_grade_of(z.total) end,
           'critical', z.crit, 'top', z.bothin and z.istop,
           'qualifies', z.entered and z.total >= v_dmin and not z.crit, 'won', z.won,
           'share', coalesce(z.sharec / 100, 0), 'members', to_jsonb(z.mems))
         order by z.ord),
         coalesce(max(z.nwon), 0), bool_and(z.bothin),
         case when bool_and(z.bothin) and max(z.nwon) = 0 then
           case when bool_or(z.istop and z.total >= v_dmin and z.crit) then 'critical-issue' else 'below-b' end end
    into v_depts, v_dwins, v_both, v_why
    from z;
  v_dp := jsonb_build_object('pool', v_dpool, 'winners', v_dwins,
    'paid', case when v_dwins > 0 then floor((v_dpool * 100) / v_dwins) * v_dwins / 100 else 0 end,
    'remainder', case when v_dwins > 0 then v_dpool - floor((v_dpool * 100) / v_dwins) * v_dwins / 100 else v_dpool end,
    'reason', case when not v_both then 'scores-needed' else v_why end);

  select count(*)::int into v_open
    from public.perf_reviews r
   where r.status <> 'final' and r.period >= v_q and r.period < v_qe;
  select count(*)::int into v_missing
    from public.team_members t
    cross join generate_series(v_q, (v_qe - interval '1 month')::date, interval '1 month') g(mo)
   where t.active and public.perf_reviewed(t.id)
     and (g.mo + interval '1 month')::date <= public.perf_today()
     and not exists (select 1 from public.perf_reviews r where r.team_member_id = t.id and r.period = g.mo::date);

  return jsonb_build_object('quarter', v_q, 'word', public.perf_quarter_word(v_q),
    'ended', v_ended, 'provisional', not v_ended or v_open > 0 or v_missing > 0,
    'people', v_people, 'individual', v_ind,
    'departments', v_depts, 'department_prize', v_dp,
    'open_months', v_open, 'missing_months', v_missing,
    'rules', jsonb_build_object('individual', v_ip, 'department', v_dpool, 'min_total', v_dmin));
end $$;

revoke all on function public.perf_quarter_calc(date) from public, anon, authenticated;

-- END OF PERFORMANCE QUARTER LIVE ---------------------------------------------

-- ===========================================================================
-- PERFORMANCE RULE SETTINGS — the grade bands, the breach deductions and
-- their cap, and the dispute window are settings an admin changes from a
-- quarter on, beside the reward figures.
-- 2026-10-05. Safe to run twice. Rollback below. Mirrored byte for byte in
-- supabase/schema.sql under the same banner; tests/perf.js compares the two.
--
-- WHAT CHANGED (the user, 2026-10-05: the grade bands, breach deductions
-- and the dispute window made editable, as the reward figures are)
--   1. `perf_settings` gains, from Q3 2026 where the key has no row:
--      grade_a 90, grade_b 80, grade_c 70, grade_d 60 (the least score for
--      each grade); ded_l1 3, ded_l2 7, ded_l3 15, ded_l4 30, ded_repeat 5,
--      ded_late 5 (points taken); ded_cap 35; dispute_days 7.
--   2. `perf_grade_at(score, at)` and `perf_deduction_at(severity,
--      repeated, late, at)` read them as at a month; `perf_grade_of` and
--      `perf_deduction` read them as at today.
--   3. `perf_calc` grades and caps a month by its own quarter's settings
--      and says the cap and the points by level it used (`cap`, `points`);
--      a final month keeps its result.
--   4. The quarter and the half grade averages by their own settings; the
--      quarter says its grade bands (`rules.grades`).
--   5. `perf_release` opens the dispute window the month's setting names.
--   6. `perf_settings_set` takes the new keys, in bounds, and keeps the
--      bands in order (`bad-order`).
--
-- ROLLBACK
--   Run the PERFORMANCE section's perf_grade_of, perf_deduction and
--   perf_calc, the DATE OF EVALUATION section's perf_release and the
--   PERFORMANCE REWARD SETTINGS section and the PERFORMANCE QUARTER LIVE
--   section again; then, in the SQL Editor, drop perf_grade_at and
--   perf_deduction_at.
-- ===========================================================================

insert into public.perf_settings (key, from_period, value)
select k.key, date '2026-07-01', k.value
  from (values ('grade_a', 90), ('grade_b', 80), ('grade_c', 70), ('grade_d', 60),
               ('ded_l1', 3), ('ded_l2', 7), ('ded_l3', 15), ('ded_l4', 30),
               ('ded_repeat', 5), ('ded_late', 5), ('ded_cap', 35), ('dispute_days', 7)) k(key, value)
 where not exists (select 1 from public.perf_settings s where s.key = k.key);

create or replace function public.perf_grade_at(p_score numeric, p_at date)
returns text
language sql stable security definer set search_path = public as $$
  select case when p_score >= public.perf_setting('grade_a', p_at) then 'A'
              when p_score >= public.perf_setting('grade_b', p_at) then 'B'
              when p_score >= public.perf_setting('grade_c', p_at) then 'C'
              when p_score >= public.perf_setting('grade_d', p_at) then 'D' else 'E' end
$$;
create or replace function public.perf_grade_of(p_score numeric)
returns text
language sql stable security definer set search_path = public as $$
  select public.perf_grade_at(p_score, public.perf_today())
$$;
create or replace function public.perf_deduction_at(p_severity integer, p_repeated boolean, p_late boolean, p_at date)
returns integer
language sql stable security definer set search_path = public as $$
  select (- coalesce(case p_severity when 1 then public.perf_setting('ded_l1', p_at) when 2 then public.perf_setting('ded_l2', p_at)
                                    when 3 then public.perf_setting('ded_l3', p_at) when 4 then public.perf_setting('ded_l4', p_at) end, 0)
          - case when p_repeated then public.perf_setting('ded_repeat', p_at) else 0 end
          - case when p_late then public.perf_setting('ded_late', p_at) else 0 end)::integer
$$;
create or replace function public.perf_deduction(p_severity integer, p_repeated boolean, p_late boolean)
returns integer
language sql stable security definer set search_path = public as $$
  select public.perf_deduction_at(p_severity, p_repeated, p_late, public.perf_today())
$$;
revoke all on function public.perf_grade_at(numeric, date) from public, anon, authenticated;
revoke all on function public.perf_grade_of(numeric) from public, anon, authenticated;
revoke all on function public.perf_deduction_at(integer, boolean, boolean, date) from public, anon, authenticated;
revoke all on function public.perf_deduction(integer, boolean, boolean) from public, anon, authenticated;

create or replace function public.perf_calc(r public.perf_reviews)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  base numeric; raw_ded integer; ded integer; fin numeric; l3 boolean; l4 boolean;
  g text; cap integer; rk integer; prev public.perf_reviews; prev_g text; ok boolean;
  complete boolean; path text; ads boolean; bd text; bc text; bm text;
  rank_of constant text := 'ABCDE';
  v_cap numeric;
begin
  if r.status = 'final' and r.result is not null then return r.result; end if;
  complete := r.s_output is not null and r.s_accuracy is not null and r.s_delivery is not null
          and r.s_client is not null and r.s_comms is not null and r.s_initiative is not null;
  base := coalesce(r.s_output, 0) + coalesce(r.s_accuracy, 0) + coalesce(r.s_delivery, 0)
        + coalesce(r.s_client, 0) + coalesce(r.s_comms, 0) + coalesce(r.s_initiative, 0);
  select coalesce(sum(public.perf_deduction_at(severity, repeated, late, r.period)), 0),
         coalesce(bool_or(severity = 3), false), coalesce(bool_or(severity = 4), false)
    into raw_ded, l3, l4
    from public.perf_breaches
   where team_member_id = r.team_member_id and period = r.period and voided_at is null;
  v_cap := public.perf_setting('ded_cap', r.period);
  ded := greatest(raw_ded, -v_cap::integer);
  fin := greatest(0, least(100, base + ded));
  g := public.perf_grade_at(fin, r.period);
  cap := case when l4 then 4 when l3 then 2 else 0 end;
  rk := greatest(position(g in rank_of), cap);
  g := substr(rank_of, rk, 1);

  select * into prev from public.perf_reviews
   where team_member_id = r.team_member_id and period = (r.period - interval '1 month')::date
     and status <> 'draft';
  if prev.id is not null then
    prev_g := (public.perf_calc(prev)) ->> 'grade';
  end if;
  ok := (g in ('A', 'B') or (g = 'C' and prev_g is distinct from 'C')) and not l3 and not l4;
  path := case when g = 'E' or l3 or l4 then 'accountability' when g = 'D' then 'development' end;

  ads := coalesce((select runs_ads from public.perf_people where team_member_id = r.team_member_id), false);
  bd := (select b from unnest(array[public.perf_band(r.r_posting, 95), public.perf_band(r.r_timeline, 90)]) b
          where b is not null order by position(b in 'green amber red') desc limit 1);
  bc := (select b from unnest(array[public.perf_band(r.r_satisfaction, 90),
                                    case when ads then public.perf_pacing_band(r.r_pacing) end]) b
          where b is not null order by position(b in 'green amber red') desc limit 1);
  bm := public.perf_band(r.r_sla, 90);

  return jsonb_build_object(
    'complete', complete, 'base', base, 'deduction', ded, 'deduction_raw', raw_ded,
    'final', fin, 'cap', v_cap,
    'points', jsonb_build_object('1', public.perf_setting('ded_l1', r.period), '2', public.perf_setting('ded_l2', r.period),
                                 '3', public.perf_setting('ded_l3', r.period), '4', public.perf_setting('ded_l4', r.period),
                                 'repeat', public.perf_setting('ded_repeat', r.period), 'late', public.perf_setting('ded_late', r.period)),
    'raw_grade', public.perf_grade_at(fin, r.period), 'grade', g,
    'grade_word', public.perf_grade_word(g),
    'capped', case when rk > position(public.perf_grade_at(fin, r.period) in rank_of) then (case when l4 then 'D' else 'B' end) end,
    'l3', l3, 'l4', l4, 'review', l4,
    'eligible', ok, 'previous_grade', prev_g,
    'path', path,
    'suggested', jsonb_build_object(
      'delivery', case bd when 'green' then 15 when 'amber' then 12 when 'red' then 7.5 end,
      'delivery_band', bd,
      'client', case bc when 'green' then 20 when 'amber' then 16 when 'red' then 10 end,
      'client_band', bc,
      'comms', case bm when 'green' then 15 when 'amber' then 12 when 'red' then 7.5 end,
      'comms_band', bm));
end $$;

create or replace function public.perf_quarter_calc(p_quarter date)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_q date := date_trunc('quarter', p_quarter)::date;
  v_qe date := (date_trunc('quarter', p_quarter) + interval '3 months')::date;
  v_people jsonb; v_wins integer; v_each numeric; v_ind jsonb;
  v_depts jsonb; v_dwins integer; v_both boolean; v_why text; v_dp jsonb;
  v_open integer; v_missing integer; v_ended boolean := public.perf_today() >= (date_trunc('quarter', p_quarter) + interval '3 months')::date;
  v_ip numeric := public.perf_setting('prize_individual', date_trunc('quarter', p_quarter)::date);
  v_dpool numeric := public.perf_setting('prize_department', date_trunc('quarter', p_quarter)::date);
  v_dmin numeric := public.perf_setting('prize_department_min_total', date_trunc('quarter', p_quarter)::date);
begin
  with m as (
    select t.id as mid, t.name as mname, t.staff_code as mcode, t.department as mdept, t.active as mactive,
           public.perf_reviewed(t.id) as monlist, f.nmonths, f.nfinal, f.mean, f.emonth,
           (select count(*)::int from public.perf_reviews o
             where o.team_member_id = t.id and o.status <> 'final'
               and o.period >= v_q and o.period < v_qe) as nopen,
           exists (select 1 from public.perf_breaches b
                    where b.team_member_id = t.id and b.voided_at is null and b.severity = 4
                      and b.period >= v_q and b.period < v_qe) as ml4
      from public.team_members t
      cross join lateral (
        select count(*)::int as nmonths, (count(*) filter (where x.st = 'final'))::int as nfinal,
               round(avg((x.res ->> 'final')::numeric), 2) as mean,
               coalesce(bool_or(x.res ->> 'grade' = 'E'), false) as emonth
          from (select coalesce(r.result, public.perf_calc(r)) as res, r.status as st
                  from public.perf_reviews r
                 where r.team_member_id = t.id and r.status <> 'draft'
                   and r.period >= v_q and r.period < v_qe) x) f
     where f.nmonths > 0 or (t.active and public.perf_reviewed(t.id))
  ), e as (
    select m.*, array_remove(array[
             case when m.nmonths = 0 then 'no-month' end,
             case when m.emonth then 'e-month' end,
             case when m.ml4 then 'critical-breach' end,
             case when not m.mactive then 'inactive' end,
             case when not m.monlist then 'not-reviewed' end], null) as why
      from m
  ), w as (
    select e.*, cardinality(e.why) = 0 as ok,
           coalesce(cardinality(e.why) = 0
                    and e.mean = max(e.mean) filter (where cardinality(e.why) = 0) over (), false) as won
      from e
  ), p as (
    select w.*, count(*) filter (where w.won) over () as nwon,
           case when w.nmonths > 0 then rank() over (order by w.mean desc nulls last) end as mrank
      from w
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'team_member_id', p.mid, 'name', p.mname, 'staff_code', p.mcode, 'department', p.mdept,
           'active', p.mactive, 'reviewed', p.monlist, 'months', p.nmonths, 'finals', p.nfinal, 'open', p.nopen,
           'rank', p.mrank, 'average', p.mean,
           'grade', case when p.nmonths > 0 then public.perf_grade_at(p.mean, v_q) end,
           'e_month', p.emonth, 'l4', p.ml4, 'eligible', p.ok, 'reasons', to_jsonb(p.why),
           'prize', case when p.won then floor(v_ip * 100 / p.nwon) / 100 else 0 end)
         order by p.mean desc nulls last, p.mname), '[]'::jsonb),
         coalesce(max(p.nwon), 0)
    into v_people, v_wins
    from p;
  v_each := case when v_wins > 0 then floor(v_ip * 100 / v_wins) / 100 end;
  v_ind := jsonb_build_object('pool', v_ip, 'winners', v_wins, 'each', v_each,
    'paid', coalesce(v_each * v_wins, 0), 'remainder', v_ip - coalesce(v_each * v_wins, 0),
    'reason', case when v_wins = 0 then 'nobody-eligible' end);

  with d as (
    select k.dep, s.c1, s.c2, s.c3, s.c4, s.c5, coalesce(s.critical, false) as crit,
           s.c1 + s.c2 + s.c3 + s.c4 + s.c5 as total, s.quarter is not null as entered, k.ord
      from (values ('creative', 1), ('marketing', 2)) k(dep, ord)
      left join public.perf_dept_scores s on s.quarter = v_q and s.department = k.dep
  ), x as (
    select d.*, bool_and(d.entered) over () as bothin,
           coalesce(d.total = max(d.total) over (), false) as istop
      from d
  ), y as (
    select x.*, (x.bothin and x.istop and x.total >= v_dmin and not x.crit) as won,
           coalesce((select array_agg(t.id order by t.name) from public.team_members t
                      where t.active and t.department = x.dep and public.perf_reviewed(t.id)), '{}'::uuid[]) as mems
      from x
  ), z as (
    select y.*, count(*) filter (where y.won) over () as nwon,
           case when y.won then floor((v_dpool * 100) / count(*) filter (where y.won) over ()) end as sharec
      from y
  )
  select jsonb_agg(jsonb_build_object(
           'department', z.dep, 'entered', z.entered,
           'criteria', case when z.entered then jsonb_build_array(z.c1, z.c2, z.c3, z.c4, z.c5) end,
           'total', z.total, 'grade', case when z.entered then public.perf_grade_at(z.total, v_q) end,
           'critical', z.crit, 'top', z.bothin and z.istop,
           'qualifies', z.entered and z.total >= v_dmin and not z.crit, 'won', z.won,
           'share', coalesce(z.sharec / 100, 0), 'members', to_jsonb(z.mems))
         order by z.ord),
         coalesce(max(z.nwon), 0), bool_and(z.bothin),
         case when bool_and(z.bothin) and max(z.nwon) = 0 then
           case when bool_or(z.istop and z.total >= v_dmin and z.crit) then 'critical-issue' else 'below-b' end end
    into v_depts, v_dwins, v_both, v_why
    from z;
  v_dp := jsonb_build_object('pool', v_dpool, 'winners', v_dwins,
    'paid', case when v_dwins > 0 then floor((v_dpool * 100) / v_dwins) * v_dwins / 100 else 0 end,
    'remainder', case when v_dwins > 0 then v_dpool - floor((v_dpool * 100) / v_dwins) * v_dwins / 100 else v_dpool end,
    'reason', case when not v_both then 'scores-needed' else v_why end);

  select count(*)::int into v_open
    from public.perf_reviews r
   where r.status <> 'final' and r.period >= v_q and r.period < v_qe;
  select count(*)::int into v_missing
    from public.team_members t
    cross join generate_series(v_q, (v_qe - interval '1 month')::date, interval '1 month') g(mo)
   where t.active and public.perf_reviewed(t.id)
     and (g.mo + interval '1 month')::date <= public.perf_today()
     and not exists (select 1 from public.perf_reviews r where r.team_member_id = t.id and r.period = g.mo::date);

  return jsonb_build_object('quarter', v_q, 'word', public.perf_quarter_word(v_q),
    'ended', v_ended, 'provisional', not v_ended or v_open > 0 or v_missing > 0,
    'people', v_people, 'individual', v_ind,
    'departments', v_depts, 'department_prize', v_dp,
    'open_months', v_open, 'missing_months', v_missing,
    'rules', jsonb_build_object('individual', v_ip, 'department', v_dpool, 'min_total', v_dmin,
      'grades', jsonb_build_object('A', public.perf_setting('grade_a', v_q), 'B', public.perf_setting('grade_b', v_q),
                                   'C', public.perf_setting('grade_c', v_q), 'D', public.perf_setting('grade_d', v_q))));
end $$;

create or replace function public.perf_period_calc(p_from date)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_f date := public.perf_half(p_from);
  v_t date := (public.perf_half(p_from) + interval '6 months')::date;
  v_c public.perf_company; v_pool numeric; v_trip numeric; v_popen boolean; v_topen boolean;
  v_rows jsonb; v_units numeric; v_bpaid numeric; v_tpaid numeric;
  v_prev numeric := public.perf_setting('bonus_pool_revenue', public.perf_half(p_from));
  v_trev numeric := public.perf_setting('trip_revenue', public.perf_half(p_from));
  v_nb numeric := public.perf_setting('bonus_months_b', public.perf_half(p_from));
  v_ua numeric := public.perf_setting('units_a', public.perf_half(p_from));
  v_ub numeric := public.perf_setting('units_b', public.perf_half(p_from));
  v_uc numeric := public.perf_setting('units_c', public.perf_half(p_from));
begin
  select * into v_c from public.perf_company where period = v_f;
  v_popen := coalesce(v_c.revenue, 0) >= v_prev;
  v_topen := coalesce(v_c.revenue, 0) >= v_trev;
  v_pool := case when v_popen then coalesce(v_c.pool, 0) else 0 end;
  v_trip := case when v_topen then coalesce(v_c.trip_budget, 0) else 0 end;
  with m as (
    select t.id as mid, t.name as mname, t.staff_code as mcode, t.active as mactive,
           f.nmonths, f.nb, f.mean, f.emonth,
           exists (select 1 from public.perf_breaches b
                    where b.team_member_id = t.id and b.voided_at is null and b.severity = 4
                      and b.period >= v_f and b.period < v_t) as ml4
      from public.team_members t
      cross join lateral (
        select count(*)::int as nmonths,
               (count(*) filter (where x.res ->> 'grade' in ('A', 'B')))::int as nb,
               round(avg((x.res ->> 'final')::numeric), 2) as mean,
               coalesce(bool_or(x.res ->> 'grade' = 'E'), false) as emonth
          from (select coalesce(r.result, public.perf_calc(r)) as res
                  from public.perf_reviews r
                 where r.team_member_id = t.id and r.status = 'final'
                   and r.period >= v_f and r.period < v_t) x) f
     where f.nmonths > 0 or (t.active and public.perf_reviewed(t.id))
  ), e as (
    select m.*, array_remove(array[
             case when m.nmonths = 0 then 'no-final-month' end,
             case when m.nmonths > 0 and m.nb < v_nb then 'few-b-months' end,
             case when m.emonth then 'e-month' end,
             case when m.ml4 then 'critical-breach' end,
             case when not m.mactive then 'inactive' end], null) as why
      from m
  ), u as (
    select e.*, cardinality(e.why) = 0 as ok,
           case when cardinality(e.why) = 0 then
             case public.perf_grade_at(e.mean, v_f) when 'A' then v_ua when 'B' then v_ub when 'C' then v_uc else 0 end
           else 0 end as units
      from e
  ), s as (
    select u.*, sum(u.units) over () as allunits from u
  ), o as (
    select s.*,
           case when s.allunits > 0 then floor(v_pool * 100 * s.units / s.allunits) / 100 else 0 end as bonus,
           case when s.allunits > 0 then floor(v_trip * 100 * s.units / s.allunits) / 100 else 0 end as tripshare
      from s
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'team_member_id', o.mid, 'name', o.mname, 'staff_code', o.mcode, 'active', o.mactive,
           'months', o.nmonths, 'months_b', o.nb, 'average', o.mean,
           'grade', case when o.nmonths > 0 then public.perf_grade_at(o.mean, v_f) end,
           'e_month', o.emonth, 'l4', o.ml4, 'eligible', o.ok, 'reasons', to_jsonb(o.why),
           'units', o.units, 'bonus', o.bonus, 'trip', o.tripshare)
         order by o.ok desc, o.units desc, o.mean desc nulls last, o.mname), '[]'::jsonb),
         coalesce(sum(o.units), 0), coalesce(sum(o.bonus), 0), coalesce(sum(o.tripshare), 0)
    into v_rows, v_units, v_bpaid, v_tpaid
    from o;
  return jsonb_build_object('period', v_f, 'word', public.perf_period_word(v_f),
    'last_month', (v_t - interval '1 month')::date, 'ended', public.perf_today() >= v_t,
    'figures', v_c.period is not null, 'total_units', v_units, 'people', v_rows,
    'rules', jsonb_build_object('pool_revenue', v_prev, 'trip_revenue', v_trev, 'months_b', v_nb,
      'units_a', v_ua, 'units_b', v_ub, 'units_c', v_uc,
      'pool_pct', public.perf_setting('bonus_pool_profit_pct', public.perf_half(p_from))),
    'bonus', jsonb_build_object('open', v_popen, 'pool', v_pool, 'paid', v_bpaid, 'remainder', v_pool - v_bpaid,
      'reason', case when v_c.period is null then 'figures-needed' when not v_popen then 'below-gate'
                     when v_pool = 0 then 'no-pool' when v_units = 0 then 'nobody-eligible' end),
    'trip', jsonb_build_object('open', v_topen, 'budget', v_trip, 'paid', v_tpaid, 'remainder', v_trip - v_tpaid,
      'reason', case when v_c.period is null then 'figures-needed' when not v_topen then 'below-gate'
                     when v_trip = 0 then 'no-budget' when v_units = 0 then 'nobody-eligible' end));
end $$;

create or replace function public.perf_release(p_token text, p_review uuid, p_rev integer, p_notify boolean default true)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare err text; m public.team_members; r public.perf_reviews; tm public.team_members;
begin
  err := public.perf_check(p_token, 'work');
  if err is not null then return jsonb_build_object('error', err); end if;
  m := public.ops_me();
  select * into r from public.perf_reviews where id = p_review for update;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if r.team_member_id = m.id then return jsonb_build_object('error', 'own-review'); end if;
  if p_rev is not null and r.rev <> p_rev then
    return jsonb_build_object('error', 'stale', 'record', public.perf_json(r, true));
  end if;
  if r.status <> 'draft' then return jsonb_build_object('error', 'not-draft'); end if;
  if not (public.perf_calc(r) ->> 'complete')::boolean then
    return jsonb_build_object('error', 'incomplete');
  end if;
  select * into tm from public.team_members where id = r.team_member_id;
  if r.serial is null and coalesce(btrim(tm.staff_code), '') = '' then
    return jsonb_build_object('error', 'no-staff-code');
  end if;
  update public.perf_reviews set status = 'released', released_at = now(),
         dispute_until = now() + make_interval(days => public.perf_setting('dispute_days', r.period)::integer), reviewer_id = m.id,
         evaluated_on = coalesce(evaluated_on, (now() at time zone 'Asia/Kuala_Lumpur')::date),
         serial = coalesce(serial, 'ADHR/' || upper(btrim(tm.staff_code)) || '/PR' || to_char(period, 'YYMM')),
         rev = rev + 1, updated_at = now()
   where id = r.id returning * into r;
  perform public.perf_log(r.id, r.team_member_id, 'released',
    jsonb_build_object('version', r.version, 'notified', coalesce(p_notify, true)));
  if coalesce(p_notify, true) then
    perform public.perf_notify(r.team_member_id, 'perf.released',
      'Your ' || public.perf_month_word(r.period) || ' performance review is ready.',
      'perf.released.' || r.id || '.' || r.version);
  end if;
  return public.perf_json(r, true);
end $$;

create or replace function public.perf_settings_set(p_token text, p_from date, p_values jsonb)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_err text; v_me public.team_members; v_from date; v_k text; v_v numeric; v_was numeric;
  v_changed jsonb := '[]'::jsonb;
  v_keys constant text[] := array['prize_individual', 'prize_department', 'prize_department_min_total',
    'flex_team_share', 'flex_member_min', 'bonus_pool_revenue',
    'bonus_pool_profit_pct', 'trip_revenue', 'bonus_months_b', 'units_a', 'units_b', 'units_c', 'commission_min',
    'grade_a', 'grade_b', 'grade_c', 'grade_d', 'ded_l1', 'ded_l2', 'ded_l3', 'ded_l4', 'ded_repeat', 'ded_late',
    'ded_cap', 'dispute_days'];
  v_a numeric; v_b numeric; v_c numeric; v_d numeric;
begin
  v_err := public.perf_check(p_token, 'work');
  if v_err is not null then return jsonb_build_object('error', v_err); end if;
  if not public.perf_is_admin() then return jsonb_build_object('error', 'admin-only'); end if;
  v_me := public.ops_me();
  v_from := date_trunc('quarter', p_from)::date;
  if v_from is null or v_from < date '2026-07-01' then return jsonb_build_object('error', 'before-first'); end if;
  if jsonb_typeof(p_values) is distinct from 'object' then return jsonb_build_object('error', 'bad-value'); end if;
  if exists (select 1 from public.perf_rewards r
              where (r.kind = 'quarter' and r.period >= v_from)
                 or (r.kind = 'period' and (r.period + interval '6 months')::date > v_from)) then
    return jsonb_build_object('error', 'confirmed');
  end if;
  for v_k in select jsonb_object_keys(p_values) loop
    if not (v_k = any(v_keys)) or jsonb_typeof(p_values -> v_k) <> 'number' then
      return jsonb_build_object('error', 'bad-value', 'key', v_k);
    end if;
    v_v := (p_values ->> v_k)::numeric;
    if v_v < 0 or round(v_v, 2) <> v_v
       or (v_k in ('prize_individual', 'prize_department', 'bonus_pool_revenue', 'trip_revenue') and v_v >= 1e9)
       or (v_k in ('prize_department_min_total', 'flex_team_share', 'flex_member_min',
                   'bonus_pool_profit_pct', 'commission_min', 'grade_a', 'grade_b', 'grade_c', 'grade_d',
                   'ded_l1', 'ded_l2', 'ded_l3', 'ded_l4', 'ded_repeat', 'ded_late', 'ded_cap') and v_v > 100)
       or (v_k = 'dispute_days' and (v_v < 1 or v_v > 30 or v_v <> trunc(v_v)))
       or (v_k = 'bonus_months_b' and (v_v > 6 or v_v <> trunc(v_v)))
       or (v_k in ('units_a', 'units_b', 'units_c') and v_v > 10) then
      return jsonb_build_object('error', 'bad-value', 'key', v_k);
    end if;
  end loop;
  -- The grade bands stay in order from the quarter on: A above B above C above D.
  v_a := coalesce((p_values ->> 'grade_a')::numeric, public.perf_setting('grade_a', v_from));
  v_b := coalesce((p_values ->> 'grade_b')::numeric, public.perf_setting('grade_b', v_from));
  v_c := coalesce((p_values ->> 'grade_c')::numeric, public.perf_setting('grade_c', v_from));
  v_d := coalesce((p_values ->> 'grade_d')::numeric, public.perf_setting('grade_d', v_from));
  if not (v_a > v_b and v_b > v_c and v_c > v_d and v_d > 0) then
    return jsonb_build_object('error', 'bad-order');
  end if;
  for v_k in select jsonb_object_keys(p_values) loop
    v_v := (p_values ->> v_k)::numeric;
    v_was := public.perf_setting(v_k, v_from);
    if v_was is distinct from v_v then
      insert into public.perf_settings (key, from_period, value, set_by, set_at)
      values (v_k, v_from, v_v, v_me.id, now())
      on conflict (key, from_period) do update set value = excluded.value, set_by = excluded.set_by, set_at = now();
      v_changed := v_changed || jsonb_build_array(jsonb_build_object('key', v_k, 'from', v_was, 'to', v_v));
    end if;
  end loop;
  if jsonb_array_length(v_changed) > 0 then
    perform public.perf_log(null, null, 'settings_set', jsonb_build_object('from_period', v_from,
      'word', public.perf_quarter_word(v_from), 'changed', v_changed));
  end if;
  return public.perf_settings_read(p_token);
end $$;

revoke all on function public.perf_release(text, uuid, integer, boolean) from public, anon, authenticated;
grant execute on function public.perf_release(text, uuid, integer, boolean) to authenticated;
revoke all on function public.perf_settings_set(text, date, jsonb) from public, anon, authenticated;
grant execute on function public.perf_settings_set(text, date, jsonb) to authenticated;

-- END OF PERFORMANCE RULE SETTINGS -------------------------------------------

-- ===========================================================================
-- APP SETTINGS — the business figures outside Performance that the team may
-- change: how long a lead and a proposal wait before they read overdue, SST,
-- the term adjustments, and when a month's report is due.
-- 2026-10-05. Safe to run twice. Rollback below. Mirrored byte for byte in
-- supabase/schema.sql under the same banner; tests/sql.js compares the two.
--
-- WHAT CHANGED (the user, 2026-10-05: "what if i need changes the next
-- quarter"; the list chosen the same day)
--   1. `app_settings` (key, from_date, value): a value holds from its day
--      until a later row for the same key. RLS on, no policy, no grant. The
--      first run seeds each key's value as it stood, from 14 Aug 2023 (the
--      company's registration), only where the key has no row:
--      lead_followup_hours 48, proposal_followup_days 21, sst_pct 8,
--      term_1_3 25, term_4_5 15, term_6_11 0, term_12_23 -5, term_24 -10,
--      report_due_days 7.
--   2. `app_setting(key, at)`: the value in force on a day (else the
--      earliest), for the functions alone.
--   3. `app_settings_read()` (anyone: the figures are on every quote):
--      every key's rows, and who set each for the team.
--   4. `app_settings_set(p_from, p_values)` (an admin): from today (MYT) or
--      a later day, never an earlier one (`past`), so an issued letter keeps
--      the SST and terms of its own day; each value in its bounds
--      (`bad-value` with the key); a value already in force is not a
--      change; each change filed `team.changed` under Settings, from and to.
--   5. A month's report task is due once: `report_due_days` after the
--      month's last day at 23:59 MYT (`sm_report_gate` reads the same day),
--      with no separate first draft date
--      (the user, 2026-10-05: "one date, 7 days"). An open report task keeps
--      its first draft date until it is done.
--
-- ROLLBACK
--   Run ops_engagement_sync_reports from A DELETED MONTH TAKES ITS REPORT
--   TASKS and sm_report_gate from REPORT MONTH GATE again; then,
--   in the SQL Editor, drop app_settings_set, app_settings_read,
--   app_setting and the table.
-- ===========================================================================

create table if not exists public.app_settings (
  key        text not null,
  from_date  date not null,
  value      numeric not null,
  set_by     uuid references public.team_members(id) on delete set null,
  set_at     timestamptz not null default now(),
  primary key (key, from_date)
);
alter table public.app_settings enable row level security;
revoke all on table public.app_settings from public, anon, authenticated;

insert into public.app_settings (key, from_date, value)
select k.key, date '2023-08-14', k.value
  from (values ('lead_followup_hours', 48), ('proposal_followup_days', 21), ('sst_pct', 8),
               ('term_1_3', 25), ('term_4_5', 15), ('term_6_11', 0), ('term_12_23', -5), ('term_24', -10),
               ('report_due_days', 7)) k(key, value)
 where not exists (select 1 from public.app_settings s where s.key = k.key);

create or replace function public.app_setting(p_key text, p_at date)
returns numeric
language sql stable security definer set search_path = public as $$
  select coalesce(
    (select s.value from public.app_settings s where s.key = p_key and s.from_date <= coalesce(p_at, current_date)
      order by s.from_date desc limit 1),
    (select s.value from public.app_settings s where s.key = p_key order by s.from_date limit 1))
$$;
revoke all on function public.app_setting(text, date) from public, anon, authenticated;

create or replace function public.app_settings_read()
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_team boolean := public.is_team();
begin
  return jsonb_build_object(
    'today', (now() at time zone 'Asia/Kuala_Lumpur')::date,
    'admin', v_team and public.allowed('admin'),
    'settings', coalesce((select jsonb_agg(jsonb_build_object('key', s.key, 'from', s.from_date, 'value', s.value,
                   'by', case when v_team then (select t.name from public.team_members t where t.id = s.set_by) end,
                   'at', case when v_team then s.set_at end)
                 order by s.key, s.from_date) from public.app_settings s), '[]'::jsonb));
end $$;

create or replace function public.app_settings_set(p_from date, p_values jsonb)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me public.team_members; v_k text; v_v numeric; v_was numeric; v_name text; v_unit text;
  v_today date := (now() at time zone 'Asia/Kuala_Lumpur')::date;
  v_keys constant text[] := array['lead_followup_hours', 'proposal_followup_days', 'sst_pct',
    'term_1_3', 'term_4_5', 'term_6_11', 'term_12_23', 'term_24', 'report_due_days'];
  v_moved text[] := '{}';
begin
  if not public.allowed('admin') then return jsonb_build_object('error', 'denied'); end if;
  v_me := public.ops_me();
  if p_from is null or p_from < v_today then return jsonb_build_object('error', 'past', 'today', v_today); end if;
  if jsonb_typeof(p_values) is distinct from 'object' then return jsonb_build_object('error', 'bad-value'); end if;
  for v_k in select jsonb_object_keys(p_values) loop
    if not (v_k = any(v_keys)) or jsonb_typeof(p_values -> v_k) <> 'number' then
      return jsonb_build_object('error', 'bad-value', 'key', v_k);
    end if;
    v_v := (p_values ->> v_k)::numeric;
    if round(v_v, 2) <> v_v
       or (v_k = 'lead_followup_hours' and (v_v < 1 or v_v > 720 or v_v <> trunc(v_v)))
       or (v_k = 'proposal_followup_days' and (v_v < 1 or v_v > 365 or v_v <> trunc(v_v)))
       or (v_k = 'report_due_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'sst_pct' and (v_v < 0 or v_v > 100))
       or (v_k like 'term_%' and (v_v < -100 or v_v > 100)) then
      return jsonb_build_object('error', 'bad-value', 'key', v_k);
    end if;
  end loop;
  for v_k in select jsonb_object_keys(p_values) loop
    v_v := (p_values ->> v_k)::numeric;
    v_was := public.app_setting(v_k, p_from);
    if v_was is distinct from v_v then
      insert into public.app_settings (key, from_date, value, set_by, set_at)
      values (v_k, p_from, v_v, v_me.id, now())
      on conflict (key, from_date) do update set value = excluded.value, set_by = excluded.set_by, set_at = now();
      v_name := case v_k when 'lead_followup_hours' then 'A lead waits' when 'proposal_followup_days' then 'A proposal waits'
        when 'sst_pct' then 'SST' when 'term_1_3' then '1 to 3 months' when 'term_4_5' then '4 and 5 months'
        when 'term_6_11' then '6 to 11 months' when 'term_12_23' then '12 to 23 months' when 'term_24' then '24 months and more'
        else 'Report due' end;
      v_unit := case when v_k = 'lead_followup_hours' then ' hours' when v_k in ('proposal_followup_days', 'report_due_days') then ' days'
        else '%' end;
      insert into public.activity_log (actor, action, subject, detail)
      values (coalesce(v_me.name, 'admin'), 'team.changed', 'Settings',
              v_name || ': ' || trim(to_char(v_was, 'FM999999990.99'), '.') || v_unit || ' → ' ||
              trim(to_char(v_v, 'FM999999990.99'), '.') || v_unit || ' · from ' || public.register_day(p_from));
      v_moved := v_moved || v_k;
    end if;
  end loop;
  return public.app_settings_read() || jsonb_build_object('changed', to_jsonb(v_moved));
end $$;
revoke all on function public.app_settings_set(date, jsonb) from public, anon;
grant execute on function public.app_settings_read() to anon, authenticated;
grant execute on function public.app_settings_set(date, jsonb) to authenticated;

create or replace function public.ops_engagement_sync_reports(p_engagement uuid, p_moved boolean default false)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  e public.ops_engagements;
  k text;
  v_ends date;
  v_due timestamptz;
  v_draft timestamptz;
  t public.ops_tasks;
  v_first text;
  res jsonb;
  made integer := 0;
  gone integer := 0;
begin
  select * into e from public.ops_engagements where id = p_engagement;
  if e.id is null or e.status in ('completed', 'cancelled') then
    return jsonb_build_object('made', 0, 'cancelled', 0);
  end if;
  select s.ends into v_ends from public.ops_month_span(e.period, e.start_day) s;
  v_due := ((v_ends + public.app_setting('report_due_days', v_ends)::integer)::timestamp + time '23:59') at time zone 'Asia/Kuala_Lumpur';
  v_draft := v_due - interval '1 day';
  foreach k in array array['social', 'ads'] loop
    if k = any (e.reports) then
      if not exists (select 1 from public.ops_tasks x
                      where x.engagement_id = e.id and x.source_type = 'report_' || k
                        and x.cancelled_at is null and x.archived_at is null) then
        res := public.ops_create_task(jsonb_build_object(
          'engagement_id', e.id, 'scope', 'client', 'client_id', e.client_id,
          'workflow_key', 'task', 'task_type', 'engagement', 'deliverable_type', 'report',
          'content_desc', case k when 'social' then 'Accounts report' else 'Advertising report' end,
          'code_period', e.period, 'first_draft_due_at', v_draft, 'final_due_at', v_due,
          'source_type', 'report_' || k,
          'owner_id', e.manager_id, 'manager_id', e.manager_id));
        if res ? 'error' then
          raise exception 'report-task: %', res ->> 'error' using errcode = 'P0001';
        end if;
        /* One date: the task is made with a draft date the day before (so
           neither the order check nor the Report template sets one), then
           it is taken off. */
        update public.ops_tasks set original_first_draft_due_at = null, current_first_draft_due_at = null
         where engagement_id = e.id and source_type = 'report_' || k
           and cancelled_at is null and archived_at is null and first_draft_submitted_at is null;
        made := made + 1;
      elsif p_moved then
        for t in select * from public.ops_tasks x
                  where x.engagement_id = e.id and x.source_type = 'report_' || k
                    and x.cancelled_at is null and x.archived_at is null and x.completed_at is null loop
          update public.ops_tasks set current_final_due_at = v_due,
                 updated_at = now(), version = version + 1
           where id = t.id;
          if t.current_final_due_at is distinct from v_due then
            perform public.ops_log(t.id, 'due_changed',
              jsonb_build_object('kind', 'final', 'value', t.current_final_due_at),
              jsonb_build_object('kind', 'final', 'value', v_due),
              jsonb_build_object('reason', 'scope_change', 'note', 'The month''s start day moved.'));
          end if;
        end loop;
      end if;
    else
      for t in select * from public.ops_tasks x
                where x.engagement_id = e.id and x.source_type = 'report_' || k
                  and x.cancelled_at is null and x.archived_at is null and x.completed_at is null loop
        select s.key into v_first from public.ops_workflow_stages s
         where s.workflow_id = t.workflow_id order by s.position limit 1;
        if t.stage_key = v_first then
          update public.ops_tasks set stage_key = 'cancelled', cancelled_at = now(), updated_at = now(),
                 version = version + 1
           where id = t.id;
          perform public.ops_log(t.id, 'stage_changed', jsonb_build_object('stage_key', t.stage_key),
            jsonb_build_object('stage_key', 'cancelled'),
            jsonb_build_object('note', 'The month no longer asks for this report.'));
          gone := gone + 1;
        end if;
      end loop;
    end if;
  end loop;
  return jsonb_build_object('made', made, 'cancelled', gone);
end $$;
revoke all on function public.ops_engagement_sync_reports(uuid, boolean) from public, anon, authenticated;

create or replace function public.sm_report_gate(p_id uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.sm_reports;
  c public.clients;
  e public.ops_engagements;
  task public.ops_tasks;
  v_starts date;
  v_ends date;
  v_due timestamptz;
  v_made integer := 0;
  v_missing text[] := '{}';
begin
  if me.id is null or not public.allowed('reports', 'view') then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_id;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  select * into c from public.clients where id = r.client_id;
  if not public.client_row_seen(c.stage, c.owner, 'view') then return jsonb_build_object('error', 'denied'); end if;
  if r.period_start < date '2026-10-01' then
    return jsonb_build_object('applies', false, 'ok', true, 'missing', '[]'::jsonb);
  end if;
  select x.* into e from public.ops_engagements x
   cross join lateral public.ops_month_span(x.period, x.start_day) s
   where x.client_id = r.client_id and x.status <> 'cancelled'
     and r.period_end between s.starts and s.ends
   order by x.period desc limit 1;
  if e.id is null then
    v_missing := v_missing || 'no-month'::text;
    v_due := ((r.period_end + public.app_setting('report_due_days', r.period_end)::integer)::timestamp + time '23:59') at time zone 'Asia/Kuala_Lumpur';
  else
    select s.starts, s.ends into v_starts, v_ends from public.ops_month_span(e.period, e.start_day) s;
    v_due := ((v_ends + public.app_setting('report_due_days', v_ends)::integer)::timestamp + time '23:59') at time zone 'Asia/Kuala_Lumpur';
    if not (r.kind = any (e.reports)) then
      v_missing := v_missing || 'not-ticked'::text;
    else
      select * into task from public.ops_tasks x
       where x.engagement_id = e.id and x.source_type = 'report_' || r.kind
         and x.cancelled_at is null and x.archived_at is null
       order by x.created_at desc limit 1;
      if task.id is null then
        v_missing := v_missing || 'no-task'::text;
      else
        v_due := coalesce(task.current_final_due_at, v_due);
      end if;
    end if;
    select count(*) into v_made from public.ops_tasks x
     where x.engagement_id = e.id and x.cancelled_at is null and x.archived_at is null
       and coalesce(x.source_type, '') not in ('report_social', 'report_ads');
    if v_made < e.planned_count then v_missing := v_missing || 'content'::text; end if;
  end if;
  return jsonb_build_object(
    'applies', true, 'ok', cardinality(v_missing) = 0, 'missing', to_jsonb(v_missing),
    'month', case when e.id is null then null else jsonb_build_object(
               'id', e.id, 'period', e.period, 'start_day', e.start_day, 'starts', v_starts, 'ends', v_ends,
               'reports', to_jsonb(e.reports)) end,
    'planned', coalesce(e.planned_count, 0), 'made', v_made,
    'task', case when task.id is null then null else jsonb_build_object(
              'id', task.id, 'task_no', task.task_no, 'stage_key', task.stage_key) end,
    'due', v_due, 'late', now() > v_due,
    'may_override', coalesce(me.is_admin, false) or me.role = 'admin' or public.allowed('reports', 'manage'));
end $$;

-- END OF APP SETTINGS ----------------------------------------------------------
-- ===========================================================================
-- ADS ON TWO PLATFORMS — one advertising report holds Meta's ads and
-- TikTok's, each ad naming its platform.
-- 2026-10-05. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/smsql.js compares the
-- two.
--
-- WHAT CHANGED (the user, 2026-10-05: "one report for both platforms")
--   1. `sm_report_ads.platform`: 'meta' (every row before today) or
--      'tiktok', checked.
--   2. `sm_reports.ads_totals` keeps Meta's figures where they always were;
--      TikTok's sit under its `tiktok` key (reach, impressions, spend and the
--      previous period's), since reach is never added across platforms.
--   3. `sm_report_create` carries the earlier report's figures forward per
--      platform: Meta's from Meta's ads and figures, TikTok's under
--      `tiktok` only where the earlier report had TikTok. Otherwise
--      unchanged.
--
-- ROLLBACK
--   Run the FIRST MONTH OF ADS UNTICKED section's sm_report_create again, then
--   alter table public.sm_report_ads drop constraint if exists sm_report_ads_platform_chk;
--   alter table public.sm_report_ads drop column if exists platform;
-- ===========================================================================

alter table public.sm_report_ads add column if not exists platform text not null default 'meta';
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'sm_report_ads_platform_chk') then
    alter table public.sm_report_ads add constraint sm_report_ads_platform_chk check (platform in ('meta', 'tiktok'));
  end if;
end $$;

create or replace function public.sm_report_create(p_client uuid, p_start date, p_end date, p_kind text default 'social')
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  rid uuid;
  prev uuid;
  pr public.sm_reports;
  totals jsonb := '{}'::jsonb;
  pgroups jsonb;
  ptk jsonb;
begin
  if me.id is null or not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if p_client is null or not exists (select 1 from public.clients where id = p_client) then
    return jsonb_build_object('error', 'not-found');
  end if;
  if p_start is null or p_end is null or p_end < p_start then return jsonb_build_object('error', 'bad-period'); end if;
  if coalesce(p_kind, '') not in ('social', 'ads') then return jsonb_build_object('error', 'bad-kind'); end if;
  select id into rid from public.sm_reports
   where client_id = p_client and kind = p_kind and period_start = p_start and period_end = p_end;
  if rid is not null then return jsonb_build_object('error', 'exists', 'id', rid); end if;
  select id into prev from public.sm_reports
   where client_id = p_client and kind = p_kind and period_start < p_start
   order by period_start desc limit 1;
  perform set_config('adspace.sm_fn', 'on', true);
  if p_kind = 'ads' then
    if prev is not null then
      select * into pr from public.sm_reports where id = prev;
      select coalesce(jsonb_object_agg(g.objective, jsonb_build_object('results',
               coalesce(nullif(pr.ads_totals #>> array['groups', g.objective, 'results'], '')::numeric, g.results),
               'spend', g.spend)), '{}'::jsonb)
        into pgroups
        from (select a.objective, sum(a.results) as results, sum(a.spend) as spend
                from public.sm_report_ads a where a.report_id = prev and a.platform = 'meta' group by a.objective) g;
      -- TikTok's figures carry forward under their own key, only where the
      -- earlier report had TikTok ads or TikTok figures of its own.
      if exists (select 1 from public.sm_report_ads where report_id = prev and platform = 'tiktok')
         or coalesce(pr.ads_totals #>> '{tiktok,reach}', pr.ads_totals #>> '{tiktok,impressions}',
                     pr.ads_totals #>> '{tiktok,spend}') is not null then
        ptk := jsonb_strip_nulls(jsonb_build_object(
          'prev_reach', nullif(pr.ads_totals #>> '{tiktok,reach}', '')::numeric,
          'prev_impressions', coalesce(nullif(pr.ads_totals #>> '{tiktok,impressions}', '')::numeric,
                                       (select sum(impressions) from public.sm_report_ads where report_id = prev and platform = 'tiktok')),
          'prev_spend', coalesce(nullif(pr.ads_totals #>> '{tiktok,spend}', '')::numeric,
                                 (select sum(spend) from public.sm_report_ads where report_id = prev and platform = 'tiktok'))));
      end if;
      totals := jsonb_strip_nulls(jsonb_build_object(
        'prev_start', pr.period_start, 'prev_end', pr.period_end,
        'prev_reach', nullif(pr.ads_totals ->> 'reach', '')::numeric,
        'prev_impressions', coalesce(nullif(pr.ads_totals ->> 'impressions', '')::numeric,
                                     (select sum(impressions) from public.sm_report_ads where report_id = prev and platform = 'meta')),
        'prev_spend', coalesce(nullif(pr.ads_totals ->> 'spend', '')::numeric,
                               (select sum(spend) from public.sm_report_ads where report_id = prev and platform = 'meta')),
        'prev_groups', pgroups,
        'tiktok', ptk));
    else
      -- No earlier report here: most clients advertised before the portal, so
      -- the period before is prefilled for the team to type its figures.
      if date_trunc('month', p_start)::date = p_start and (p_start + interval '1 month' - interval '1 day')::date = p_end then
        totals := jsonb_build_object('prev_start', (p_start - interval '1 month')::date, 'prev_end', p_start - 1);
      else
        totals := jsonb_build_object('prev_start', p_start - (p_end - p_start + 1), 'prev_end', p_start - 1);
      end if;
    end if;
    insert into public.sm_reports (client_id, kind, title, period_start, period_end, created_by, first_month, ads_totals)
    values (p_client, p_kind, 'Social Media Advertising Report', p_start, p_end, me.id, false, totals)
    returning id into rid;
  else
    insert into public.sm_reports (client_id, kind, period_start, period_end, created_by)
    values (p_client, p_kind, p_start, p_end, me.id) returning id into rid;
    if prev is not null then
      insert into public.sm_report_platforms (report_id, platform, account_name, handle, group_key, group_label,
        position, metrics, followers_start, er_basis, metric_notes)
      select rid, p.platform, p.account_name, p.handle, p.group_key, p.group_label, p.position, p.metrics,
             coalesce(p.followers_end, case when p.followers_start is not null and p.growth_override is not null
                                            then p.followers_start + p.growth_override end),
             p.er_basis, p.metric_notes
        from public.sm_report_platforms p where p.report_id = prev;
    end if;
  end if;
  perform set_config('adspace.sm_fn', 'off', true);
  perform public.sm_report_log(rid, 'report.created');
  return jsonb_build_object('ok', true, 'id', rid, 'carried', prev is not null);
end $$;
grant execute on function public.sm_report_create(uuid, date, date, text) to authenticated;

-- END OF ADS ON TWO PLATFORMS ------------------------------------------------

-- ===========================================================================
-- PIECE DATES AS TYPED — every piece takes the due date typed on its row,
-- and nothing is worked out for it.
-- 2026-10-05. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/ops.js compares the
-- two. Runs after TEMPLATE FAMILIES and PIECES AND REPEATS.
--
-- WHAT CHANGED
--   `ops_create_pieces` sends each piece's own `final_due_at` (several
--   pieces once got none) and asks `ops_create_task` to take the dates as
--   given (`dates_as_given`): no due or draft date is worked out from a
--   template's offsets, and plain pieces take no tentative publish day. Four
--   Week 1 reels added on 5 Oct came out due 29 Sept to 2 Oct; a row left
--   blank now reads Not set. A repeat still takes a tentative day to count
--   from. Every other caller of `ops_create_task` is unchanged.
--
-- ROLLBACK
--   Run the TEMPLATE FAMILIES section's ops_create_task and the PIECES AND
--   REPEATS section's ops_create_pieces again.
-- ===========================================================================

create or replace function public.ops_create_task(p_payload jsonb, p_idem text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m     public.team_members;
  tpl   public.ops_task_templates;
  fam   public.ops_template_variants;
  byfmt boolean := false;
  wf    uuid;
  tid   uuid;
  owner uuid;
  publish timestamptz;
  fd    timestamptz;
  fin   timestamptz;
  item  jsonb;
  i     integer := 0;
  scope text;
  ttype text;
  cid   uuid;
  bad   text;
  descr text;
  period text;
  cper  text;
  week  integer;
  seq   integer;
  code  text;
  title text;
  first_stage text;
  wkey  text;
  base  timestamptz;
  eng   public.ops_engagements;
begin
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if not public.allowed('ops', 'work') then return jsonb_build_object('error', 'denied'); end if;

  -- The same press twice is one task.
  if p_idem is not null then
    select id into tid from public.ops_tasks where idem_key = p_idem;
    if tid is not null then return public.ops_task_json(tid); end if;
  end if;

  scope := coalesce(p_payload ->> 'scope', 'client');
  cid := (p_payload ->> 'client_id')::uuid;
  /* A task linked to a month's engagement takes the client from it: the
     person names the month once and the client comes with it. */
  if (p_payload ->> 'engagement_id') is not null then
    select * into eng from public.ops_engagements where id = (p_payload ->> 'engagement_id')::uuid;
    if eng.id is null then return jsonb_build_object('error', 'not-found'); end if;
    if cid is null then cid := eng.client_id; scope := 'client'; end if;
  end if;
  bad := public.ops_scope_error(scope, cid);
  if bad is not null then return jsonb_build_object('error', bad); end if;

  ttype := coalesce(p_payload ->> 'task_type', 'adhoc');
  if ttype not in ('engagement', 'adhoc', 'goodwill', 'special') then
    return jsonb_build_object('error', 'bad-task-type');
  end if;

  /* The description is the team's to edit and may start blank on a task that
     carries a code; a task with no code is named by its description alone, so
     there it is required. `title` is accepted from older callers as the
     description. */
  descr := nullif(btrim(coalesce(p_payload ->> 'content_desc', p_payload ->> 'title', '')), '');

  if (p_payload ->> 'template_id') is not null then
    select * into tpl from public.ops_task_templates
     where id = (p_payload ->> 'template_id')::uuid;
    descr := coalesce(descr, nullif(btrim(coalesce(tpl.default_title, tpl.name, '')), ''));
  end if;
  /* No template named: the family that owns the chosen format fills the task
     (its checklist, complexity, draft and final offsets, owner) and the
     format's own variant its hours (TEMPLATE FAMILIES, 2026-09-28). */
  if tpl.id is null and nullif(p_payload ->> 'deliverable_type', '') is not null then
    select v.* into fam from public.ops_template_variants v
      join public.ops_task_templates t on t.id = v.template_id and t.active
     where v.format = p_payload ->> 'deliverable_type';
    if fam.id is not null then
      select * into tpl from public.ops_task_templates where id = fam.template_id;
      byfmt := true;
    end if;
  end if;
  /* New work goes on the content workflow. A caller may still name another
     (a template's own, or one somebody adds), and a task already on a retired
     workflow is never moved. */
  wf := coalesce((p_payload ->> 'workflow_id')::uuid,
                 (select id from public.ops_workflows where key = p_payload ->> 'workflow_key' and active),
                 case when byfmt then null else tpl.workflow_id end,
                 (select id from public.ops_workflows where key = 'content' and active),
                 (select id from public.ops_workflows where active order by created_at limit 1));
  if wf is null then return jsonb_build_object('error', 'workflow-required'); end if;
  select key into first_stage from public.ops_workflow_stages
   where workflow_id = wf order by position limit 1;
  select key into wkey from public.ops_workflows where id = wf;

  publish := (p_payload ->> 'publish_at')::timestamptz;
  fd := coalesce((p_payload ->> 'first_draft_due_at')::timestamptz,
        case when publish is not null and tpl.first_draft_offset_business_days is not null
             then public.ops_add_business_days(publish, -tpl.first_draft_offset_business_days)
             when tpl.first_draft_offset_business_days is not null
             then public.ops_add_business_days(now(), tpl.first_draft_offset_business_days)
        end);
  /* A template's due date is a number of calendar days from the day the
     work is made for (the base date the caller names, else today). */
  base := coalesce((p_payload ->> 'base_date')::timestamptz, now());
  fin := coalesce((p_payload ->> 'final_due_at')::timestamptz,
        case when tpl.due_offset_days is not null and not byfmt
             then date_trunc('day', base) + make_interval(days => tpl.due_offset_days)
             when publish is not null and tpl.final_offset_business_days is not null
             then public.ops_add_business_days(publish, -tpl.final_offset_business_days)
             when tpl.final_offset_business_days is not null
             then public.ops_add_business_days(now(), tpl.final_offset_business_days)
        end);
  /* Dates a person typed stand as typed, and a date left blank stays blank:
     nothing is worked out from a template's offsets (the user, 2026-10-05). */
  if coalesce((p_payload ->> 'dates_as_given')::boolean, false) then
    fd := (p_payload ->> 'first_draft_due_at')::timestamptz;
    fin := (p_payload ->> 'final_due_at')::timestamptz;
  end if;
  if fd is not null and fin is not null and not public.ops_due_order_ok(fd, fin) then
    return jsonb_build_object('error', 'draft-not-before-final');
  end if;

  /* The name. The month is the content month (the scheduled publish date's,
     else the one the caller names, else this one); the week is the planned
     publishing week, chosen by the caller and prefilled by the page from the
     date; the running number is the client's for the month. Generated once,
     under the lock, and never rewritten: a publish date that moves later
     leaves the name as it was, because the name is a label and not a fact
     about the date. */
  if wkey = 'task' then
    /* An everyday task is named by what it is. It carries no content code,
       because the code numbers a client's deliverables for the month and a
       task is not one; the content month is kept where it is known, so the
       task can be grouped with the month it belongs to. */
    if descr is null then return jsonb_build_object('error', 'title-required'); end if;
    title := descr;
    period := coalesce(nullif(p_payload ->> 'code_period', ''), eng.period);
  elsif scope <> 'internal' then
    period := coalesce(nullif(p_payload ->> 'code_period', ''),
                       case when publish is not null then to_char(publish, 'YYYY-MM') end,
                       to_char(now(), 'YYYY-MM'));
    if period !~ '^\d{4}-\d{2}$' then return jsonb_build_object('error', 'bad-period'); end if;
    /* A client's deliverable belongs to a month the team has planned: one
       that exists, is still open, and has its content meeting set or marked
       not applicable. The same three refusals Bulk add gives. */
    if scope = 'client' then
      cper := period;
      if eng.id is null or eng.period <> cper then
        select * into eng from public.ops_engagements x where x.client_id = cid and x.period = cper;
      end if;
      if eng.id is null then return jsonb_build_object('error', 'no-month'); end if;
      if eng.status in ('completed', 'cancelled') then return jsonb_build_object('error', 'month-closed'); end if;
      if eng.meeting_at is null and not eng.meeting_na then
        return jsonb_build_object('error', 'month-not-confirmed');
      end if;
    end if;
    week := coalesce((p_payload ->> 'code_week')::integer,
                     case when publish is not null
                          then least(5, ((extract(day from publish)::integer - 1) / 7) + 1) end,
                     1);
    if week < 1 or week > 5 then return jsonb_build_object('error', 'bad-week'); end if;
    seq := public.ops_next_seq(cid, period);
    code := public.ops_code_of(period, week, seq);
    title := btrim(code || ' ' || coalesce(descr, ''));
  else
    if descr is null then return jsonb_build_object('error', 'title-required'); end if;
    title := descr;
  end if;

  insert into public.ops_tasks (
    scope, client_id, campaign_id, batch_id, source_type, source_id, template_id,
    workflow_id, stage_key, title, description, remarks, deliverable_type,
    language_codes, priority_level, complexity, estimate_minutes, publish_at,
    original_first_draft_due_at, current_first_draft_due_at,
    original_final_due_at, current_final_due_at, created_by, idem_key,
    legacy_source, legacy_key, data_quality,
    task_type, code, code_period, code_week, code_seq, content_desc,
    engagement_id, manager_id, parent_task_id)
  values (
    scope, cid,
    (p_payload ->> 'campaign_id')::uuid,
    (p_payload ->> 'batch_id')::uuid,
    p_payload ->> 'source_type',
    (p_payload ->> 'source_id')::uuid,
    tpl.id, wf, coalesce(first_stage, 'intake'),
    title, p_payload ->> 'description', p_payload ->> 'remarks',
    coalesce(p_payload ->> 'deliverable_type', tpl.deliverable_type, 'other'),
    coalesce((select array_agg(x) from jsonb_array_elements_text(
               coalesce(p_payload -> 'language_codes', '[]'::jsonb)) x), '{}'),
    coalesce((p_payload ->> 'priority_level')::smallint, 3),
    coalesce(p_payload ->> 'complexity', tpl.default_complexity),
    coalesce((p_payload ->> 'estimate_minutes')::integer, fam.estimate_minutes, tpl.default_estimate_minutes),
    publish, fd, fd, fin, fin, m.id, p_idem,
    p_payload ->> 'legacy_source', p_payload ->> 'legacy_key',
    coalesce(p_payload ->> 'data_quality', 'complete'),
    ttype, code, period, week, seq, descr,
    coalesce(eng.id, (p_payload ->> 'engagement_id')::uuid),
    coalesce((p_payload ->> 'manager_id')::uuid, m.id),
    (p_payload ->> 'parent_task_id')::uuid)
  returning id into tid;

  /* Every task has an owner from the moment it exists: the one named, the
     template's, or else whoever made it. */
  owner := coalesce((p_payload ->> 'owner_id')::uuid, tpl.default_owner_id, m.id);
  if owner is not null then
    insert into public.ops_task_assignees (task_id, team_member_id, responsibility, assigned_by)
    values (tid, owner, 'owner', m.id);
    perform public.ops_log(tid, 'assignment_changed', null,
      jsonb_build_object('owner_id', owner), '{}'::jsonb);
  end if;
  if (p_payload ->> 'reviewer_id') is not null then
    insert into public.ops_task_assignees (task_id, team_member_id, responsibility, assigned_by)
    values (tid, (p_payload ->> 'reviewer_id')::uuid, 'reviewer', m.id);
  end if;

  -- The template's checklist, or the one the caller hands over (a duplicate
  -- carries its source's labels, unticked), in the order stated.
  for item in select * from jsonb_array_elements(
      coalesce(p_payload -> 'checklist', tpl.checklist, '[]'::jsonb)) loop
    i := i + 1;
    insert into public.ops_task_checklist_items (task_id, label, position)
    values (tid, item #>> '{}', i);
  end loop;

  if (p_payload -> 'video') is not null then
    insert into public.ops_video_details (
      task_id, output_duration_seconds, footage_duration_seconds,
      subtitle_required, motion_graphics_required, aspect_ratios,
      script_ready, footage_ready, shoot_required, shoot_at, variant_count)
    values (tid,
      ((p_payload -> 'video') ->> 'output_duration_seconds')::integer,
      ((p_payload -> 'video') ->> 'footage_duration_seconds')::integer,
      coalesce(((p_payload -> 'video') ->> 'subtitle_required')::boolean, false),
      coalesce(((p_payload -> 'video') ->> 'motion_graphics_required')::boolean, false),
      coalesce((select array_agg(x) from jsonb_array_elements_text(
                 coalesce((p_payload -> 'video') -> 'aspect_ratios', '[]'::jsonb)) x), '{}'),
      ((p_payload -> 'video') ->> 'script_ready')::boolean,
      ((p_payload -> 'video') ->> 'footage_ready')::boolean,
      coalesce(((p_payload -> 'video') ->> 'shoot_required')::boolean, false),
      ((p_payload -> 'video') ->> 'shoot_at')::timestamptz,
      coalesce(((p_payload -> 'video') ->> 'variant_count')::integer, 1));
  end if;

  perform public.ops_log(tid, 'task_created', null,
    jsonb_build_object('title', title, 'code', code,
                       'first_draft_due_at', fd, 'final_due_at', fin),
    case when (p_payload ->> 'duplicated_from') is null then '{}'::jsonb
         else jsonb_build_object('duplicated_from', p_payload ->> 'duplicated_from') end);
  return public.ops_task_json(tid);
end $$;
grant execute on function public.ops_create_task(jsonb, text) to authenticated;

/* The New sheet's one act: the pieces, each through ops_create_task, and the
   repeat on every one of them, all or none. */
create or replace function public.ops_create_pieces(p_payload jsonb, p_idem text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m      public.team_members;
  n      integer;
  pc     jsonb;
  i      integer := 0;
  w      integer;
  k      integer;
  inweek integer;
  per    text;
  first_day date;
  last_off integer;
  spread boolean;
  base   jsonb;
  one    jsonb;
  made   jsonb := '[]'::jsonb;
  rep    jsonb;
  rule   jsonb;
  ids    uuid[] := '{}';
  gen    jsonb := '[]'::jsonb;
  pp     text;
  said   text;
begin
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if not public.allowed('ops', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if jsonb_typeof(p_payload -> 'pieces') is distinct from 'array' then
    return jsonb_build_object('error', 'bad-count');
  end if;
  n := jsonb_array_length(p_payload -> 'pieces');
  if n < 1 or n > 60 then return jsonb_build_object('error', 'bad-count'); end if;
  rep := case when jsonb_typeof(p_payload -> 'repeat') = 'object' then p_payload -> 'repeat' end;
  if rep is not null then
    if coalesce(rep ->> 'frequency', '') not in ('weekly', 'monthly', 'custom') then
      return jsonb_build_object('error', 'bad-frequency');
    end if;
    if rep ->> 'frequency' = 'custom' and coalesce((rep ->> 'interval_days')::integer, 0) < 1 then
      return jsonb_build_object('error', 'interval-required');
    end if;
  end if;

  /* What every piece shares: whose it is, what kind, who does it. A piece
     names its own description, format and week; only a sheet's one piece
     carries its own dates and brief. */
  base := jsonb_strip_nulls(jsonb_build_object(
    'scope', p_payload ->> 'scope', 'client_id', p_payload ->> 'client_id',
    'engagement_id', p_payload ->> 'engagement_id',
    'code_period', p_payload ->> 'code_period',
    'task_type', p_payload ->> 'task_type',
    'owner_id', p_payload ->> 'owner_id',
    'priority_level', p_payload -> 'priority_level',
    'complexity', p_payload ->> 'complexity',
    'description', case when n = 1 then p_payload ->> 'description' end));
  per := p_payload ->> 'code_period';
  if per ~ '^\d{4}-\d{2}$' and coalesce(p_payload ->> 'scope', 'client') <> 'internal' then
    first_day := (per || '-01')::date;
    last_off := ((first_day + interval '1 month')::date - first_day) - 1;
  end if;
  /* Only a repeat needs a day to count from; plain pieces take the dates
     typed on their rows and nothing else. */
  spread := first_day is not null and rep is not null;
  base := base || jsonb_build_object('dates_as_given', true);

  begin
    for pc in select x from jsonb_array_elements(p_payload -> 'pieces') x loop
      i := i + 1;
      w := least(5, greatest(1, coalesce((pc ->> 'code_week')::integer, 1)));
      one := base || jsonb_strip_nulls(jsonb_build_object(
        'content_desc', nullif(btrim(coalesce(pc ->> 'content_desc', '')), ''),
        'deliverable_type', nullif(pc ->> 'deliverable_type', ''),
        'code_week', case when first_day is not null then w end));
      /* Every piece carries the due date typed on its row; a sheet's one
         piece carries its draft and publish dates too. */
      one := one || jsonb_strip_nulls(jsonb_build_object(
        'final_due_at', nullif(pc ->> 'final_due_at', '')));
      if n = 1 then
        one := one || jsonb_strip_nulls(jsonb_build_object(
          'publish_at', nullif(pc ->> 'publish_at', ''),
          'first_draft_due_at', nullif(pc ->> 'first_draft_due_at', '')));
      end if;
      /* A tentative day inside the piece's week, the week's pieces spread
         across its seven days, so the calendar has somewhere to put each one
         and a repeat a day to count from; the content meeting fixes the real
         date. Never past the month's last day, which only week 5 reaches. */
      if spread and not (one ? 'publish_at') then
        select count(*) filter (where least(5, greatest(1, coalesce((y ->> 'code_week')::integer, 1))) = w),
               count(*) filter (where least(5, greatest(1, coalesce((y ->> 'code_week')::integer, 1))) = w and o < i)
          into inweek, k
          from jsonb_array_elements(p_payload -> 'pieces') with ordinality as a(y, o);
        one := one || jsonb_build_object('publish_at',
          (first_day + least((w - 1) * 7 + (k * 7) / greatest(inweek, 1), last_off))::timestamptz);
      end if;
      one := public.ops_create_task(one, case when p_idem is null then null else p_idem || ':' || i end);
      if one ? 'error' then raise exception using message = one::text; end if;
      made := made || jsonb_build_object('id', one ->> 'id', 'code', one ->> 'code', 'title', one ->> 'title');
      ids := ids || (one ->> 'id')::uuid;
      if rep is not null then
        rule := public.ops_set_recurring((one ->> 'id')::uuid, jsonb_strip_nulls(jsonb_build_object(
          'frequency', rep ->> 'frequency',
          'interval_days', case when rep ->> 'frequency' = 'custom' then rep -> 'interval_days' end,
          'ends_on', nullif(rep ->> 'ends_on', ''),
          'max_count', rep -> 'max_count')));
        if rule ? 'error' then raise exception using message = rule::text; end if;
      end if;
    end loop;
  exception when raise_exception then
    /* A refusal part way leaves nothing behind: the block's writes are
       undone and the refusal is answered as it was given. */
    said := sqlerrm;
    begin
      return said::jsonb;
    exception when others then
      return jsonb_build_object('error', said);
    end;
  end;

  /* What the new rules already owe is made now rather than tomorrow morning. */
  if rep is not null then
    foreach pp in array public.ops_recurring_periods() loop
      gen := gen || public.ops_generate_recurring(pp,
        array(select r.id from public.ops_recurring_rules r where r.active and r.source_task_id = any (ids)));
    end loop;
  end if;
  return jsonb_build_object('count', n, 'tasks', made, 'repeats', gen);
end $$;
grant execute on function public.ops_create_pieces(jsonb, text) to authenticated;

-- END OF PIECE DATES AS TYPED ------------------------------------------------

-- ===========================================================================
-- PERFORMANCE IN PLAIN WORDS — the two notices a query sends say query,
-- never dispute.
-- 2026-10-05. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/perf.js compares the
-- two. Runs after PERFORMANCE REVIEWS and MY PERFORMANCE BEHIND AN EMAIL
-- CODE, which defined the two functions last.
--
-- WHAT CHANGED
--   The page reads Query, Issue, Shared and Agreed where it read Dispute,
--   Breach, Released and Upheld (the user, 2026-10-05: "why use evidence.
--   Sounds like some criminals"). The stored keys (`disputed`, `breach`,
--   `upheld`, the kinds `perf.disputed` and `perf.answered`) never move;
--   only the words of the two notices and an agreed query's void reason.
--   Each function is otherwise its last definition, unchanged.
--
-- ROLLBACK
--   Run perf_decide from PERFORMANCE REVIEWS and perf_dispute from MY
--   PERFORMANCE BEHIND AN EMAIL CODE again.
-- ===========================================================================

create or replace function public.perf_decide(p_token text, p_dispute uuid, p_decision text,
                                              p_response text, p_value numeric)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  err text; m public.team_members; d public.perf_disputes; r public.perf_reviews;
  b public.perf_breaches; mx numeric; was numeric; col text;
begin
  err := public.perf_check(p_token, 'work');
  if err is not null then return jsonb_build_object('error', err); end if;
  m := public.ops_me();
  if p_decision not in ('upheld', 'partly', 'not_upheld') then return jsonb_build_object('error', 'bad-decision'); end if;
  if coalesce(btrim(p_response), '') = '' then return jsonb_build_object('error', 'reason-needed'); end if;
  select * into d from public.perf_disputes where id = p_dispute for update;
  if d.id is null then return jsonb_build_object('error', 'not-found'); end if;
  select * into r from public.perf_reviews where id = d.review_id for update;
  if r.team_member_id = m.id then return jsonb_build_object('error', 'own-review'); end if;
  if r.status <> 'disputed' or d.decision is not null or d.version <> r.version then
    return jsonb_build_object('error', 'already-decided');
  end if;

  if d.item = 'breach' then
    select * into b from public.perf_breaches where id = d.breach_id for update;
    was := b.severity;
    if p_decision = 'upheld' then
      update public.perf_breaches set voided_at = now(), voided_by = m.id, void_reason = 'Query agreed'
       where id = b.id;
    elsif p_decision = 'partly' then
      if p_value is null or p_value not in (1, 2, 3) or p_value >= b.severity then
        return jsonb_build_object('error', 'bad-severity');
      end if;
      update public.perf_breaches set severity = p_value::integer where id = b.id;
    end if;
  else
    mx := case d.item when 'output' then 25 when 'accuracy' then 15 when 'delivery' then 15
                      when 'client' then 20 when 'comms' then 15 when 'initiative' then 10 end;
    col := 's_' || d.item;
    execute format('select %I from public.perf_reviews where id = $1', col) into was using r.id;
    if p_decision in ('upheld', 'partly') then
      if p_value is null or p_value < 0 or p_value > mx or round(p_value, 1) <> p_value then
        return jsonb_build_object('error', 'bad-score', 'max', mx);
      end if;
      execute format('update public.perf_reviews set %I = $1 where id = $2', col) using p_value, r.id;
    end if;
  end if;

  update public.perf_disputes set decision = p_decision, response = btrim(p_response),
         before_value = was,
         after_value = case when p_decision = 'not_upheld' then was
                            when d.item = 'breach' and p_decision = 'upheld' then 0
                            else p_value end,
         decided_by = m.id, decided_at = now()
   where id = d.id;
  if not exists (select 1 from public.perf_disputes x
                  where x.review_id = r.id and x.version = r.version and x.decision is null) then
    update public.perf_reviews set status = 'resolved' where id = r.id;
    perform public.perf_notify(r.team_member_id, 'perf.answered',
      'Your query on ' || public.perf_month_word(r.period) || ' has been answered.',
      'perf.answered.' || r.id || '.' || r.version);
  end if;
  update public.perf_reviews set rev = rev + 1, updated_at = now() where id = r.id returning * into r;
  perform public.perf_log(r.id, r.team_member_id, 'decided',
    jsonb_build_object('item', d.item, 'decision', p_decision, 'was', was,
                       'after', case when p_decision = 'not_upheld' then was else p_value end));
  return public.perf_json(r, true);
end $$;

create or replace function public.perf_dispute(p_review uuid, p_items jsonb)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare m public.team_members; r public.perf_reviews; it jsonb; n integer := 0; itm text; bid uuid;
begin
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if public.perf_guarded(m.id) and not public.perf_code_fresh() then
    return jsonb_build_object('error', 'code-needed');
  end if;
  select * into r from public.perf_reviews where id = p_review for update;
  if r.id is null or r.team_member_id <> m.id or r.status = 'draft' then
    return jsonb_build_object('error', 'not-found');
  end if;
  if r.status <> 'released' or exists (select 1 from public.perf_disputes d
                                        where d.review_id = r.id and d.version = r.version) then
    return jsonb_build_object('error', 'dispute-closed');
  end if;
  if r.dispute_until <= now() then return jsonb_build_object('error', 'window-closed'); end if;
  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    return jsonb_build_object('error', 'nothing-disputed');
  end if;
  for it in select * from jsonb_array_elements(p_items) loop
    itm := it ->> 'item';
    if itm is null or itm not in ('output', 'accuracy', 'delivery', 'client', 'comms', 'initiative', 'breach') then
      return jsonb_build_object('error', 'bad-item');
    end if;
    if coalesce(btrim(it ->> 'reason'), '') = '' then return jsonb_build_object('error', 'reason-needed', 'item', itm); end if;
    bid := null;
    if itm = 'breach' then
      begin bid := (it ->> 'breach_id')::uuid; exception when others then bid := null; end;
      if bid is null or not exists (select 1 from public.perf_breaches b
                                     where b.id = bid and b.team_member_id = m.id
                                       and b.period = r.period and b.voided_at is null) then
        return jsonb_build_object('error', 'bad-item');
      end if;
    end if;
    insert into public.perf_disputes (review_id, version, item, breach_id, reason)
    values (r.id, r.version, itm, bid, btrim(it ->> 'reason'));
    n := n + 1;
  end loop;
  update public.perf_reviews set status = 'disputed', rev = rev + 1, updated_at = now()
   where id = r.id returning * into r;
  perform public.perf_log(r.id, r.team_member_id, 'disputed', jsonb_build_object('items', n));
  perform public.perf_notify(r.reviewer_id, 'perf.disputed',
    m.name || ' raised a query on ' || public.perf_month_word(r.period) || '.',
    'perf.disputed.' || r.id || '.' || r.version);
  return public.perf_json(r, false);
end $$;

-- END OF PERFORMANCE IN PLAIN WORDS ----------------------------------------

-- ===========================================================================
-- THE ASSIGNEE REASSIGNS — the person a task is assigned to may give it to
-- someone else, and so may any group above them.
-- 2026-10-05. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/ops.js compares the
-- two. Runs after the sections that last defined ops_assign_task and
-- ops_hand_over_task (MY WORK AS A DAILY TASK TRACKER for the second).
--
-- WHAT CHANGED
--   Both asked My Work at Manage. The user decided who reassigns: the
--   assignee (My Work at Work, their own task only) and any group above
--   them (Manage, an admin). Helpers and the reviewer stay a manager's.
--   ops_assign_task now also asks ops_may_see_task, as every other task
--   write does, so nobody reassigns a task outside their client scope.
--
-- ROLLBACK
--   Run the two functions from the sections that defined them before.
-- ===========================================================================

create or replace function public.ops_assign_task(
  p_task uuid, p_owner uuid, p_contributors uuid[] default null,
  p_reviewer uuid default null, p_version integer default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m   public.team_members;
  t   public.ops_tasks;
  was uuid;
  c   uuid;
begin
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'not-team'); end if;
  /* The person it is assigned to reassigns it, and so does any group
     above them (My Work at Manage, an admin); helpers and the reviewer
     stay a manager's (the user, 2026-10-05). */
  if not public.ops_may_see_task(p_task) then return jsonb_build_object('error', 'denied'); end if;
  if not public.allowed('ops', 'manage') then
    if not public.allowed('ops', 'work') or p_contributors is not null or p_reviewer is not null
       or not exists (select 1 from public.ops_task_assignees a
                       where a.task_id = p_task and a.responsibility = 'owner'
                         and a.ended_at is null and a.team_member_id = m.id) then
      return jsonb_build_object('error', 'denied');
    end if;
  end if;

  select * into t from public.ops_tasks where id = p_task for update;
  if t.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if p_version is not null and p_version <> t.version then
    return jsonb_build_object('error', 'stale', 'task', public.ops_task_json(p_task));
  end if;

  select team_member_id into was from public.ops_task_assignees
   where task_id = p_task and responsibility = 'owner' and ended_at is null;

  if p_owner is not null and p_owner is distinct from was then
    /* The former owner stops seeing it as live work and keeps their place in
       its history: the row is ended and kept. */
    update public.ops_task_assignees set ended_at = now()
     where task_id = p_task and responsibility = 'owner' and ended_at is null;
    insert into public.ops_task_assignees (task_id, team_member_id, responsibility, assigned_by)
    values (p_task, p_owner, 'owner', m.id);
    perform public.ops_log(p_task, 'assignment_changed',
      jsonb_build_object('owner_id', was), jsonb_build_object('owner_id', p_owner), '{}'::jsonb);
  end if;

  if p_contributors is not null then
    update public.ops_task_assignees set ended_at = now()
     where task_id = p_task and responsibility = 'contributor' and ended_at is null
       and not (team_member_id = any (p_contributors));
    foreach c in array p_contributors loop
      insert into public.ops_task_assignees (task_id, team_member_id, responsibility, assigned_by)
      values (p_task, c, 'contributor', m.id)
      on conflict do nothing;
    end loop;
    perform public.ops_log(p_task, 'contributor_changed', null,
      jsonb_build_object('contributors', to_jsonb(p_contributors)), '{}'::jsonb);
  end if;

  if p_reviewer is not null then
    update public.ops_task_assignees set ended_at = now()
     where task_id = p_task and responsibility = 'reviewer' and ended_at is null
       and team_member_id <> p_reviewer;
    insert into public.ops_task_assignees (task_id, team_member_id, responsibility, assigned_by)
    values (p_task, p_reviewer, 'reviewer', m.id)
    on conflict do nothing;
    perform public.ops_log(p_task, 'reviewer_changed', null,
      jsonb_build_object('reviewer_id', p_reviewer), '{}'::jsonb);
  end if;

  update public.ops_tasks set version = version + 1, updated_at = now() where id = p_task;
  return public.ops_task_json(p_task);
end $$;
grant execute on function public.ops_assign_task(uuid, uuid, uuid[], uuid, integer) to authenticated;

create or replace function public.ops_hand_over_task(
  p_task uuid, p_owner uuid, p_note text default null, p_version integer default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m   public.team_members;
  t   public.ops_tasks;
  was uuid;
begin
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if not public.ops_may_see_task(p_task) then return jsonb_build_object('error', 'denied'); end if;
  /* The person it is assigned to hands it over, and so does any group
     above them (the user, 2026-10-05). */
  if not public.allowed('ops', 'manage') then
    if not public.allowed('ops', 'work')
       or not exists (select 1 from public.ops_task_assignees a
                       where a.task_id = p_task and a.responsibility = 'owner'
                         and a.ended_at is null and a.team_member_id = m.id) then
      return jsonb_build_object('error', 'denied');
    end if;
  end if;
  if p_owner is null then return jsonb_build_object('error', 'no-such-person'); end if;

  select * into t from public.ops_tasks where id = p_task for update;
  if t.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if p_version is not null and p_version <> t.version then
    return jsonb_build_object('error', 'stale', 'task', public.ops_task_json(p_task));
  end if;
  if not exists (select 1 from public.team_members where id = p_owner and active) then
    return jsonb_build_object('error', 'no-such-person');
  end if;

  select team_member_id into was from public.ops_task_assignees
   where task_id = p_task and responsibility = 'owner' and ended_at is null;
  if p_owner is not distinct from was then return public.ops_task_json(p_task); end if;

  update public.ops_task_assignees set ended_at = now()
   where task_id = p_task and responsibility = 'owner' and ended_at is null;
  insert into public.ops_task_assignees (task_id, team_member_id, responsibility, assigned_by)
  values (p_task, p_owner, 'owner', m.id);
  update public.ops_tasks set version = version + 1, updated_at = now() where id = p_task;
  perform public.ops_log(p_task, 'assignment_changed',
    jsonb_build_object('owner_id', was),
    jsonb_build_object('owner_id', p_owner),
    jsonb_build_object('handover', true, 'stage_key', t.stage_key)
      || case when nullif(btrim(coalesce(p_note, '')), '') is null then '{}'::jsonb
              else jsonb_build_object('note', btrim(p_note)) end);
  return public.ops_task_json(p_task);
end $$;
grant execute on function public.ops_hand_over_task(uuid, uuid, text, integer) to authenticated;

-- END OF THE ASSIGNEE REASSIGNS ---------------------------------------------

-- ===========================================================================
-- A MONTH'S EDITS REACH ITS REPORTS — cancelling a month cancels its report
-- tasks nobody started, reopening it asks for them again, and a new manager
-- takes the ones nobody started.
-- 2026-10-05. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/ops.js compares the
-- two. Runs after MONTH STAGES FOLLOW THE WORK (ops_engagement_set_status)
-- and APP SETTINGS (ops_engagement_sync_reports).
--
-- WHAT CHANGED
--   Audit round 7, continued. A cancelled month kept its report tasks live
--   in My Work, though deleting the month cancelled them; a reopened month
--   never asked for them again; and a month whose manager changed left its
--   report tasks with the manager before. Each is the rule deleting and
--   unticking already keep: only a task still at its first stage moves.
--
-- ROLLBACK
--   Run the two functions from the sections named above again.
-- ===========================================================================

create or replace function public.ops_engagement_set_status(
  p_engagement uuid, p_status text, p_version integer default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare m public.team_members; e public.ops_engagements; v_open integer;
begin
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if not public.allowed('ops', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if not public.ops_may_see_engagement(p_engagement) then return jsonb_build_object('error', 'denied'); end if;
  if p_status in ('ready', 'in_production') then
    return jsonb_build_object('error', 'derived-state');
  end if;
  if p_status not in ('planning', 'completed', 'cancelled') then
    return jsonb_build_object('error', 'bad-state');
  end if;
  select * into e from public.ops_engagements where id = p_engagement for update;
  if e.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if p_version is not null and p_version <> e.version then
    return jsonb_build_object('error', 'stale', 'engagement', public.ops_engagement_json(p_engagement));
  end if;
  if p_status = 'completed' then
    select count(*) into v_open from public.ops_tasks t
     where t.engagement_id = p_engagement and t.archived_at is null
       and t.completed_at is null and t.cancelled_at is null;
    if v_open > 0 then
      return jsonb_build_object('error', 'tasks-open', 'open', v_open);
    end if;
  end if;
  if e.status = p_status then return public.ops_engagement_json(p_engagement); end if;
  update public.ops_engagements set status = p_status, updated_at = now(), version = version + 1
   where id = p_engagement;
  perform public.ops_engagement_log(p_engagement, 'status_changed',
    jsonb_build_object('from', e.status, 'to', p_status));
  /* A month cancelled cancels the report tasks nobody started (as deleting
     it does), keeping a started one; reopened, it asks for its reports
     again. */
  if p_status = 'cancelled' then
    perform public.ops_engagement_cancel_reports(p_engagement, array['social', 'ads'], 'The month was cancelled.');
  elsif e.status = 'cancelled' and p_status = 'planning' then
    perform public.ops_engagement_sync_reports(p_engagement);
  end if;
  return public.ops_engagement_json(p_engagement);
end $$;
grant execute on function public.ops_engagement_set_status(uuid, text, integer) to authenticated;

create or replace function public.ops_engagement_sync_reports(p_engagement uuid, p_moved boolean default false)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  e public.ops_engagements;
  k text;
  v_ends date;
  v_due timestamptz;
  v_draft timestamptz;
  t public.ops_tasks;
  v_first text;
  res jsonb;
  made integer := 0;
  gone integer := 0;
begin
  select * into e from public.ops_engagements where id = p_engagement;
  if e.id is null or e.status in ('completed', 'cancelled') then
    return jsonb_build_object('made', 0, 'cancelled', 0);
  end if;
  select s.ends into v_ends from public.ops_month_span(e.period, e.start_day) s;
  v_due := ((v_ends + public.app_setting('report_due_days', v_ends)::integer)::timestamp + time '23:59') at time zone 'Asia/Kuala_Lumpur';
  v_draft := v_due - interval '1 day';
  foreach k in array array['social', 'ads'] loop
    /* A report task nobody has started follows the month's manager. */
    if k = any (e.reports) and e.manager_id is not null then
      for t in select * from public.ops_tasks x
                where x.engagement_id = e.id and x.source_type = 'report_' || k
                  and x.cancelled_at is null and x.archived_at is null and x.completed_at is null
                  and x.stage_key = (select s.key from public.ops_workflow_stages s
                                      where s.workflow_id = x.workflow_id order by s.position limit 1)
                  and exists (select 1 from public.ops_task_assignees a
                               where a.task_id = x.id and a.responsibility = 'owner' and a.ended_at is null
                                 and a.team_member_id <> e.manager_id) loop
        update public.ops_task_assignees set ended_at = now()
         where task_id = t.id and responsibility = 'owner' and ended_at is null;
        insert into public.ops_task_assignees (task_id, team_member_id, responsibility, assigned_by)
        values (t.id, e.manager_id, 'owner', e.manager_id);
        update public.ops_tasks set version = version + 1, updated_at = now() where id = t.id;
        perform public.ops_log(t.id, 'assignment_changed', null,
          jsonb_build_object('owner_id', e.manager_id),
          jsonb_build_object('note', 'The month''s manager changed.'));
      end loop;
    end if;
    if k = any (e.reports) then
      if not exists (select 1 from public.ops_tasks x
                      where x.engagement_id = e.id and x.source_type = 'report_' || k
                        and x.cancelled_at is null and x.archived_at is null) then
        res := public.ops_create_task(jsonb_build_object(
          'engagement_id', e.id, 'scope', 'client', 'client_id', e.client_id,
          'workflow_key', 'task', 'task_type', 'engagement', 'deliverable_type', 'report',
          'content_desc', case k when 'social' then 'Accounts report' else 'Advertising report' end,
          'code_period', e.period, 'first_draft_due_at', v_draft, 'final_due_at', v_due,
          'source_type', 'report_' || k,
          'owner_id', e.manager_id, 'manager_id', e.manager_id));
        if res ? 'error' then
          raise exception 'report-task: %', res ->> 'error' using errcode = 'P0001';
        end if;
        /* One date: the task is made with a draft date the day before (so
           neither the order check nor the Report template sets one), then
           it is taken off. */
        update public.ops_tasks set original_first_draft_due_at = null, current_first_draft_due_at = null
         where engagement_id = e.id and source_type = 'report_' || k
           and cancelled_at is null and archived_at is null and first_draft_submitted_at is null;
        made := made + 1;
      elsif p_moved then
        for t in select * from public.ops_tasks x
                  where x.engagement_id = e.id and x.source_type = 'report_' || k
                    and x.cancelled_at is null and x.archived_at is null and x.completed_at is null loop
          update public.ops_tasks set current_final_due_at = v_due,
                 updated_at = now(), version = version + 1
           where id = t.id;
          if t.current_final_due_at is distinct from v_due then
            perform public.ops_log(t.id, 'due_changed',
              jsonb_build_object('kind', 'final', 'value', t.current_final_due_at),
              jsonb_build_object('kind', 'final', 'value', v_due),
              jsonb_build_object('reason', 'scope_change', 'note', 'The month''s start day moved.'));
          end if;
        end loop;
      end if;
    else
      for t in select * from public.ops_tasks x
                where x.engagement_id = e.id and x.source_type = 'report_' || k
                  and x.cancelled_at is null and x.archived_at is null and x.completed_at is null loop
        select s.key into v_first from public.ops_workflow_stages s
         where s.workflow_id = t.workflow_id order by s.position limit 1;
        if t.stage_key = v_first then
          update public.ops_tasks set stage_key = 'cancelled', cancelled_at = now(), updated_at = now(),
                 version = version + 1
           where id = t.id;
          perform public.ops_log(t.id, 'stage_changed', jsonb_build_object('stage_key', t.stage_key),
            jsonb_build_object('stage_key', 'cancelled'),
            jsonb_build_object('note', 'The month no longer asks for this report.'));
          gone := gone + 1;
        end if;
      end loop;
    end if;
  end loop;
  return jsonb_build_object('made', made, 'cancelled', gone);
end $$;
revoke all on function public.ops_engagement_sync_reports(uuid, boolean) from public, anon, authenticated;

-- END OF A MONTH'S EDITS REACH ITS REPORTS ---------------------------------

-- ===========================================================================
-- MEETINGS OUTSIDE A MONTH — a meeting in a client's Calls and visits takes a
-- time, a length and a link (a Google Meet made for it), and the client's
-- portal lists it beside the month's content meeting.
-- 2026-10-05. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/ops.js (§41) compares
-- the two. Runs after EVERY TASK IN A CONFIRMED MONTH (portal_meetings).
--
-- WHAT CHANGED
--   The user: "sometimes we also create adhoc meeting (not new month) but
--   to record inside as extras". `client_touches` gains meet_at,
--   meet_minutes (15 to 240), meet_link (Meet, Zoom or Teams only) and
--   meet_event_id. `client_touch_meet_prepare` and `client_touch_set_meet`
--   are what meet-create asks for an entry, as it asks the month's pair;
--   both run as the caller, so the table's own policies (Clients: Calls
--   at Work, the client scope) decide. portal_meetings adds these meetings.
--
-- ROLLBACK
--   Run portal_meetings from EVERY TASK IN A CONFIRMED MONTH again; the
--   columns and the two functions may stay (nothing else reads them).
-- ===========================================================================

alter table public.client_touches add column if not exists meet_at       timestamptz;
alter table public.client_touches add column if not exists meet_minutes  integer;
alter table public.client_touches add column if not exists meet_link     text;
alter table public.client_touches add column if not exists meet_event_id text;
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'client_touches_meet_minutes') then
    alter table public.client_touches add constraint client_touches_meet_minutes
      check (meet_minutes is null or meet_minutes between 15 and 240);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'client_touches_meet_link') then
    alter table public.client_touches add constraint client_touches_meet_link
      check (meet_link is null or meet_link ~* '^https://([a-z0-9-]+\.)*(meet\.google\.com|zoom\.us|teams\.microsoft\.com|teams\.live\.com)/');
  end if;
end $$;

/* What meet-create needs to book an entry's meeting, read as the caller:
   an entry the caller cannot read answers not-found. */
create or replace function public.client_touch_meet_prepare(p_touch uuid)
returns jsonb
language plpgsql security invoker stable set search_path = public as $$
declare t public.client_touches; cl text;
begin
  if not public.allowed('clients.calls', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into t from public.client_touches where id = p_touch and archived_at is null;
  if t.id is null then return jsonb_build_object('error', 'not-found'); end if;
  /* An entry that stopped being a meeting is still read while its event
     stands, so the event can be taken off the calendar. */
  if t.kind <> 'meeting' and t.meet_event_id is null then return jsonb_build_object('error', 'not-a-meeting'); end if;
  select c.name into cl from public.clients c where c.id = t.client_id;
  return jsonb_build_object('id', t.id, 'client_name', coalesce(cl, 'Client'),
    'meeting_at', t.meet_at, 'meeting_minutes', coalesce(t.meet_minutes, 30),
    'meeting_link', t.meet_link, 'meeting_event_id', t.meet_event_id);
end $$;
grant execute on function public.client_touch_meet_prepare(uuid) to authenticated;

/* The link and the calendar's event, recorded on the entry as the caller.
   A null pair is the event removed and takes a Meet link with it; a Zoom
   or Teams link somebody typed stays. */
create or replace function public.client_touch_set_meet(p_touch uuid, p_link text, p_event text)
returns jsonb
language plpgsql security invoker set search_path = public as $$
declare t public.client_touches;
begin
  if not public.allowed('clients.calls', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if p_link is not null and p_link !~* '^https://meet\.google\.com/' then
    return jsonb_build_object('error', 'bad-meeting-link');
  end if;
  update public.client_touches set meet_link = case
           when p_link is not null then p_link
           when p_event is null and meet_link ~* '^https://meet\.google\.com/' then null
           else meet_link end,
         meet_event_id = p_event, updated_at = now()
   where id = p_touch and archived_at is null
  returning * into t;
  if t.id is null then return jsonb_build_object('error', 'not-found'); end if;
  return to_jsonb(t);
end $$;
grant execute on function public.client_touch_set_meet(uuid, text, text) to authenticated;

create or replace function public.portal_meetings(p_client uuid)
returns jsonb
language plpgsql security definer stable set search_path = public as $$
begin
  if auth.jwt() ->> 'email' is null then return jsonb_build_object('error', 'not-signed-in'); end if;
  if p_client is null or p_client not in (select public.portal_clients()) then
    return jsonb_build_object('error', 'no-access');
  end if;
  /* The content meetings the team has put in the diary, from three months
     back. Nothing about the month's tasks, checks or status beyond this: a
     client reads when we meet, never how the work inside the month is going.
     The link is sent only while the meeting is still ahead. */
  /* Beside them, the meetings the team booked outside a month (Calls and
     visits, kind meeting, with a time; 2026-10-05): the time, the length
     and the link, never what was written about it. */
  return jsonb_build_object('meetings', coalesce((
    select jsonb_agg(x.j order by x.at desc) from (
      select e.meeting_at as at, jsonb_build_object(
               'kind', 'content', 'period', e.period, 'at', e.meeting_at, 'minutes', coalesce(e.meeting_minutes, 30),
               'channel', e.meeting_channel,
               'link', case when e.meeting_at + make_interval(mins => coalesce(e.meeting_minutes, 30)) > now()
                            then e.meeting_link end) as j
        from public.ops_engagements e
       where e.client_id = p_client
         and e.meeting_at is not null
         and not coalesce(e.meeting_na, false)
         and e.status <> 'cancelled'
         and e.meeting_at >= date_trunc('month', now()) - interval '3 months'
      union all
      select t.meet_at, jsonb_build_object(
               'kind', 'meeting', 'period', null, 'at', t.meet_at, 'minutes', coalesce(t.meet_minutes, 30),
               'channel', case when t.meet_link ~* 'meet\.google\.com' then 'google_meet'
                               when t.meet_link ~* 'zoom\.us' then 'zoom'
                               when t.meet_link ~* 'teams\.' then 'teams' end,
               'link', case when t.meet_at + make_interval(mins => coalesce(t.meet_minutes, 30)) > now()
                            then t.meet_link end)
        from public.client_touches t
       where t.client_id = p_client
         and t.kind = 'meeting' and t.meet_at is not null and t.archived_at is null
         and t.meet_at >= date_trunc('month', now()) - interval '3 months') x), '[]'::jsonb));
end $$;
revoke all on function public.portal_meetings(uuid) from public, anon;
grant execute on function public.portal_meetings(uuid) to authenticated;

-- END OF MEETINGS OUTSIDE A MONTH -------------------------------------------

-- ===========================================================================
-- THREE DATES A POST — every post line carries its draft due, its due date
-- and its post date, and a client's request for changes moves the due date
-- to the next day by itself.
-- 2026-10-06. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/ops.js (§42) compares
-- the two. Runs after APP SETTINGS and PIECE DATES AS TYPED.
--
-- WHAT CHANGED (the user, 2026-10-06)
--   1. `ops_create_pieces` takes each piece's draft due (ready for AQC
--      review), due date (to the client) and post date, on every piece:
--      several pieces once got the due date alone. Nothing is worked out.
--   2. `revision_due_days` (1) is a setting an admin changes in My Work's
--      Due dates, from a day on (`app_settings_set` restated with the key).
--   3. `ops_tasks_revision_due` (after update of stage_key): a task moved
--      into Revision (Client) takes as its due date the day that many days
--      after today (MYT), where that is later than the date it holds, filed
--      as a due change for a client request. The draft due is left alone.
--
-- ROLLBACK
--   Run ops_create_pieces from PIECE DATES AS TYPED and app_settings_set
--   from APP SETTINGS again; in the SQL Editor, remove the trigger
--   ops_tasks_revision_due. The setting's row may stay.
-- ===========================================================================

insert into public.app_settings (key, from_date, value)
select 'revision_due_days', date '2023-08-14', 1
 where not exists (select 1 from public.app_settings s where s.key = 'revision_due_days');

/* The New sheet's one act: the pieces, each through ops_create_task, and the
   repeat on every one of them, all or none. */
create or replace function public.ops_create_pieces(p_payload jsonb, p_idem text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m      public.team_members;
  n      integer;
  pc     jsonb;
  i      integer := 0;
  w      integer;
  k      integer;
  inweek integer;
  per    text;
  first_day date;
  last_off integer;
  spread boolean;
  base   jsonb;
  one    jsonb;
  made   jsonb := '[]'::jsonb;
  rep    jsonb;
  rule   jsonb;
  ids    uuid[] := '{}';
  gen    jsonb := '[]'::jsonb;
  pp     text;
  said   text;
begin
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if not public.allowed('ops', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if jsonb_typeof(p_payload -> 'pieces') is distinct from 'array' then
    return jsonb_build_object('error', 'bad-count');
  end if;
  n := jsonb_array_length(p_payload -> 'pieces');
  if n < 1 or n > 60 then return jsonb_build_object('error', 'bad-count'); end if;
  rep := case when jsonb_typeof(p_payload -> 'repeat') = 'object' then p_payload -> 'repeat' end;
  if rep is not null then
    if coalesce(rep ->> 'frequency', '') not in ('weekly', 'monthly', 'custom') then
      return jsonb_build_object('error', 'bad-frequency');
    end if;
    if rep ->> 'frequency' = 'custom' and coalesce((rep ->> 'interval_days')::integer, 0) < 1 then
      return jsonb_build_object('error', 'interval-required');
    end if;
  end if;

  /* What every piece shares: whose it is, what kind, who does it. A piece
     names its own description, format, week and dates; only a sheet's one
     piece carries a brief. */
  base := jsonb_strip_nulls(jsonb_build_object(
    'scope', p_payload ->> 'scope', 'client_id', p_payload ->> 'client_id',
    'engagement_id', p_payload ->> 'engagement_id',
    'code_period', p_payload ->> 'code_period',
    'task_type', p_payload ->> 'task_type',
    'owner_id', p_payload ->> 'owner_id',
    'priority_level', p_payload -> 'priority_level',
    'complexity', p_payload ->> 'complexity',
    'description', case when n = 1 then p_payload ->> 'description' end));
  per := p_payload ->> 'code_period';
  if per ~ '^\d{4}-\d{2}$' and coalesce(p_payload ->> 'scope', 'client') <> 'internal' then
    first_day := (per || '-01')::date;
    last_off := ((first_day + interval '1 month')::date - first_day) - 1;
  end if;
  /* Only a repeat needs a day to count from; plain pieces take the dates
     typed on their rows and nothing else. */
  spread := first_day is not null and rep is not null;
  base := base || jsonb_build_object('dates_as_given', true);

  begin
    for pc in select x from jsonb_array_elements(p_payload -> 'pieces') x loop
      i := i + 1;
      w := least(5, greatest(1, coalesce((pc ->> 'code_week')::integer, 1)));
      one := base || jsonb_strip_nulls(jsonb_build_object(
        'content_desc', nullif(btrim(coalesce(pc ->> 'content_desc', '')), ''),
        'deliverable_type', nullif(pc ->> 'deliverable_type', ''),
        'code_week', case when first_day is not null then w end));
      /* Every piece carries the three dates typed on its row: the draft
         due (ready for AQC review), the due date (to the client) and the
         post date (2026-10-06). */
      one := one || jsonb_strip_nulls(jsonb_build_object(
        'first_draft_due_at', nullif(pc ->> 'first_draft_due_at', ''),
        'final_due_at', nullif(pc ->> 'final_due_at', ''),
        'publish_at', nullif(pc ->> 'publish_at', '')));
      /* A tentative day inside the piece's week, the week's pieces spread
         across its seven days, so the calendar has somewhere to put each one
         and a repeat a day to count from; the content meeting fixes the real
         date. Never past the month's last day, which only week 5 reaches. */
      if spread and not (one ? 'publish_at') then
        select count(*) filter (where least(5, greatest(1, coalesce((y ->> 'code_week')::integer, 1))) = w),
               count(*) filter (where least(5, greatest(1, coalesce((y ->> 'code_week')::integer, 1))) = w and o < i)
          into inweek, k
          from jsonb_array_elements(p_payload -> 'pieces') with ordinality as a(y, o);
        one := one || jsonb_build_object('publish_at',
          (first_day + least((w - 1) * 7 + (k * 7) / greatest(inweek, 1), last_off))::timestamptz);
      end if;
      one := public.ops_create_task(one, case when p_idem is null then null else p_idem || ':' || i end);
      if one ? 'error' then raise exception using message = one::text; end if;
      made := made || jsonb_build_object('id', one ->> 'id', 'code', one ->> 'code', 'title', one ->> 'title');
      ids := ids || (one ->> 'id')::uuid;
      if rep is not null then
        rule := public.ops_set_recurring((one ->> 'id')::uuid, jsonb_strip_nulls(jsonb_build_object(
          'frequency', rep ->> 'frequency',
          'interval_days', case when rep ->> 'frequency' = 'custom' then rep -> 'interval_days' end,
          'ends_on', nullif(rep ->> 'ends_on', ''),
          'max_count', rep -> 'max_count')));
        if rule ? 'error' then raise exception using message = rule::text; end if;
      end if;
    end loop;
  exception when raise_exception then
    /* A refusal part way leaves nothing behind: the block's writes are
       undone and the refusal is answered as it was given. */
    said := sqlerrm;
    begin
      return said::jsonb;
    exception when others then
      return jsonb_build_object('error', said);
    end;
  end;

  /* What the new rules already owe is made now rather than tomorrow morning. */
  if rep is not null then
    foreach pp in array public.ops_recurring_periods() loop
      gen := gen || public.ops_generate_recurring(pp,
        array(select r.id from public.ops_recurring_rules r where r.active and r.source_task_id = any (ids)));
    end loop;
  end if;
  return jsonb_build_object('count', n, 'tasks', made, 'repeats', gen);
end $$;
grant execute on function public.ops_create_pieces(jsonb, text) to authenticated;

create or replace function public.app_settings_set(p_from date, p_values jsonb)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me public.team_members; v_k text; v_v numeric; v_was numeric; v_name text; v_unit text;
  v_today date := (now() at time zone 'Asia/Kuala_Lumpur')::date;
  v_keys constant text[] := array['lead_followup_hours', 'proposal_followup_days', 'sst_pct',
    'term_1_3', 'term_4_5', 'term_6_11', 'term_12_23', 'term_24', 'report_due_days', 'revision_due_days'];
  v_moved text[] := '{}';
begin
  if not public.allowed('admin') then return jsonb_build_object('error', 'denied'); end if;
  v_me := public.ops_me();
  if p_from is null or p_from < v_today then return jsonb_build_object('error', 'past', 'today', v_today); end if;
  if jsonb_typeof(p_values) is distinct from 'object' then return jsonb_build_object('error', 'bad-value'); end if;
  for v_k in select jsonb_object_keys(p_values) loop
    if not (v_k = any(v_keys)) or jsonb_typeof(p_values -> v_k) <> 'number' then
      return jsonb_build_object('error', 'bad-value', 'key', v_k);
    end if;
    v_v := (p_values ->> v_k)::numeric;
    if round(v_v, 2) <> v_v
       or (v_k = 'lead_followup_hours' and (v_v < 1 or v_v > 720 or v_v <> trunc(v_v)))
       or (v_k = 'proposal_followup_days' and (v_v < 1 or v_v > 365 or v_v <> trunc(v_v)))
       or (v_k = 'report_due_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'revision_due_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'sst_pct' and (v_v < 0 or v_v > 100))
       or (v_k like 'term_%' and (v_v < -100 or v_v > 100)) then
      return jsonb_build_object('error', 'bad-value', 'key', v_k);
    end if;
  end loop;
  for v_k in select jsonb_object_keys(p_values) loop
    v_v := (p_values ->> v_k)::numeric;
    v_was := public.app_setting(v_k, p_from);
    if v_was is distinct from v_v then
      insert into public.app_settings (key, from_date, value, set_by, set_at)
      values (v_k, p_from, v_v, v_me.id, now())
      on conflict (key, from_date) do update set value = excluded.value, set_by = excluded.set_by, set_at = now();
      v_name := case v_k when 'lead_followup_hours' then 'A lead waits' when 'proposal_followup_days' then 'A proposal waits'
        when 'sst_pct' then 'SST' when 'term_1_3' then '1 to 3 months' when 'term_4_5' then '4 and 5 months'
        when 'term_6_11' then '6 to 11 months' when 'term_12_23' then '12 to 23 months' when 'term_24' then '24 months and more'
        when 'revision_due_days' then 'Revision due' else 'Report due' end;
      v_unit := case when v_k = 'lead_followup_hours' then ' hours' when v_k in ('proposal_followup_days', 'report_due_days', 'revision_due_days') then ' days'
        else '%' end;
      insert into public.activity_log (actor, action, subject, detail)
      values (coalesce(v_me.name, 'admin'), 'team.changed', 'Settings',
              v_name || ': ' || trim(to_char(v_was, 'FM999999990.99'), '.') || v_unit || ' → ' ||
              trim(to_char(v_v, 'FM999999990.99'), '.') || v_unit || ' · from ' || public.register_day(p_from));
      v_moved := v_moved || v_k;
    end if;
  end loop;
  return public.app_settings_read() || jsonb_build_object('changed', to_jsonb(v_moved));
end $$;
revoke all on function public.app_settings_set(date, jsonb) from public, anon;
grant execute on function public.app_settings_read() to anon, authenticated;
grant execute on function public.app_settings_set(date, jsonb) to authenticated;

/* A client's request for changes sends the work back with a new due date:
   the day `revision_due_days` after today in Malaysia, stored as a typed
   date is (that day at 00:00 UTC), and only where it is later than the due
   date the task holds. */
create or replace function public.ops_tasks_revision_due()
returns trigger
language plpgsql security definer set search_path = public as $$
declare v_day date; v_due timestamptz;
begin
  if new.stage_key <> 'revision_client' or old.stage_key is not distinct from new.stage_key then return null; end if;
  v_day := (now() at time zone 'Asia/Kuala_Lumpur')::date;
  v_due := ((v_day + coalesce(public.app_setting('revision_due_days', v_day), 1)::integer)::timestamp) at time zone 'UTC';
  if new.current_final_due_at is not null and new.current_final_due_at >= v_due then return null; end if;
  update public.ops_tasks set current_final_due_at = v_due, updated_at = now() where id = new.id;
  perform public.ops_log(new.id, 'due_changed',
    jsonb_build_object('kind', 'final', 'value', new.current_final_due_at),
    jsonb_build_object('kind', 'final', 'value', v_due),
    jsonb_build_object('reason', 'client_request', 'note', 'The client asked for changes.', 'auto', true));
  return null;
end $$;
revoke all on function public.ops_tasks_revision_due() from public, anon, authenticated;
create or replace trigger ops_tasks_revision_due after update of stage_key on public.ops_tasks
  for each row when (new.stage_key = 'revision_client' and old.stage_key is distinct from new.stage_key)
  execute function public.ops_tasks_revision_due();

-- END OF THREE DATES A POST --------------------------------------------------

-- ===========================================================================
-- REPORT MOVED TO ANOTHER CLIENT — an admin moves a draft report started
-- under a temporary client to the client it belongs to.
-- 2026-10-06. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/smsql.js compares the
-- two. Runs after the REPORTS sections (sm_report_log, the guard's
-- adspace.sm_fn switch) and AI DRAFT SUBJECT (ai_drafts.client_id).
--
-- WHAT CHANGED (the user, 2026-10-06)
--   The team starts a report under a temporary client while a client's
--   record is pending. `sm_report_move(p_id, p_client)` (an admin's alone)
--   moves a draft to an Active client; its accounts, posts, ads and text
--   go with it, since they hang off the report. A report past draft keeps
--   its client (`not-draft`); the target must be Active (`not-active`) and
--   hold no report of the same kind whose period shares a day (`exists`).
--   The report's AI uses follow it (`ai_drafts.client_id`). The move is
--   filed under both clients as a save, from and to.
--
-- ROLLBACK
--   In the SQL Editor, remove the function sm_report_move(uuid, uuid).
-- ===========================================================================

create or replace function public.sm_report_move(p_id uuid, p_client uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.sm_reports;
  c public.clients;
  was text;
begin
  if me.id is null or not public.allowed('admin') then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_id for update;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if r.status <> 'draft' then return jsonb_build_object('error', 'not-draft', 'status', r.status); end if;
  select * into c from public.clients where id = p_client;
  if c.id is null or c.stage <> 'active' then return jsonb_build_object('error', 'not-active'); end if;
  if c.id = r.client_id then return jsonb_build_object('ok', true, 'client_id', c.id); end if;
  if exists (select 1 from public.sm_reports x
              where x.client_id = c.id and x.kind = r.kind and x.id <> r.id
                and x.period_start <= r.period_end and x.period_end >= r.period_start) then
    return jsonb_build_object('error', 'exists');
  end if;
  select k.name into was from public.clients k where k.id = r.client_id;
  perform public.sm_report_log(p_id, 'report.saved', 'Client: ' || coalesce(was, 'not set') || ' → ' || c.name);
  perform set_config('adspace.sm_fn', 'on', true);
  update public.sm_reports set client_id = c.id where id = p_id;
  perform set_config('adspace.sm_fn', 'off', true);
  update public.ai_drafts set client_id = c.id where report_id = p_id;
  perform public.sm_report_log(p_id, 'report.saved', 'Client: ' || coalesce(was, 'not set') || ' → ' || c.name);
  return jsonb_build_object('ok', true, 'client_id', c.id);
end $$;
revoke all on function public.sm_report_move(uuid, uuid) from public, anon, authenticated;
grant execute on function public.sm_report_move(uuid, uuid) to authenticated;

-- END OF REPORT MOVED TO ANOTHER CLIENT -------------------------------------

-- ===========================================================================
-- REPORT PARTNERS — a partner's clients' reports carry the partner's logo at
-- the top of every page, in place of ADspace's wordmark.
-- 2026-10-06. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/smsql.js compares the
-- two. Runs after CLIENT SCOPE (sm_report_snapshot, client_seen).
--
-- WHAT CHANGED (the user, 2026-10-06)
--   ADspace subcontracts white-label work: one partner hands over several of
--   its own clients, and their reports go out as a courtesy under the
--   partner's logo (landscape, never the client's round mark). Everything
--   else stays ADspace's: the clients know who does the work.
--   1. `report_partners` (name, a landscape logo kept as a PNG data address,
--      active) and `report_partner_clients` (one row a client, the partner
--      or none; no foreign key to the client, so removing a client never
--      waits on it, and a row left behind names nobody). RLS on, read at Reports View (the client's own row within
--      the client scope), written only through the functions below.
--   2. `report_partner_save(p_id, p_name, p_logo, p_clients)` adds or edits a
--      partner and sets its clients (a client moves from another partner;
--      one taken off reads ADspace again); `report_partner_set_active` stands
--      a partner down or back. Both an admin's or Reports Full Access, filed
--      `report.saved` under Partners.
--   3. `sm_report_snapshot` sends the client's active partner (name, logo),
--      so a published version keeps the brand it went out with.
--
-- ROLLBACK
--   Run sm_report_snapshot from CLIENT SCOPE again; the two tables and two
--   functions may stay unused.
-- ===========================================================================

create table if not exists public.report_partners (
  id         uuid primary key default gen_random_uuid(),
  name       text not null,
  logo_data  text,
  active     boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint report_partners_name check (char_length(btrim(name)) between 2 and 80),
  constraint report_partners_logo check (logo_data is null or (logo_data ~ '^data:image/png;base64,' and char_length(logo_data) <= 1500000))
);
create table if not exists public.report_partner_clients (
  client_id  uuid primary key,
  partner_id uuid references public.report_partners(id),
  updated_at timestamptz not null default now()
);
alter table public.report_partners enable row level security;
alter table public.report_partner_clients enable row level security;
grant select on public.report_partners, public.report_partner_clients to authenticated;
revoke insert, update on public.report_partners, public.report_partner_clients from anon, authenticated;
revoke select on public.report_partners, public.report_partner_clients from anon;
do $$ begin
  if not exists (select 1 from pg_policies where tablename = 'report_partners' and policyname = 'report_partners_read') then
    create policy report_partners_read on public.report_partners for select to authenticated
      using (public.allowed('reports', 'view'));
  end if;
  if not exists (select 1 from pg_policies where tablename = 'report_partner_clients' and policyname = 'report_partner_clients_read') then
    create policy report_partner_clients_read on public.report_partner_clients for select to authenticated
      using (public.allowed('reports', 'view'));
  end if;
  -- The scope rule asks the two helpers every other table's does: a login
  -- may not run client_seen itself, so a policy naming it fails every read.
  if not exists (select 1 from pg_policies where tablename = 'report_partner_clients' and policyname = 'client_scope') then
    create policy client_scope on public.report_partner_clients as restrictive for select to authenticated
      using ((select public.client_scope_free('view')) or public.client_scope_ok('client', client_id, 'view'));
  else
    alter policy client_scope on public.report_partner_clients
      using ((select public.client_scope_free('view')) or public.client_scope_ok('client', client_id, 'view'));
  end if;
end $$;

create or replace function public.report_partner_save(p_id uuid, p_name text, p_logo text, p_clients uuid[])
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  v_id uuid := p_id;
  v_name text := btrim(coalesce(p_name, ''));
  v_was public.report_partners;
  v_list text;
  c uuid;
begin
  if me.id is null or not (public.allowed('admin') or public.allowed('reports', 'manage')) then
    return jsonb_build_object('error', 'denied');
  end if;
  if char_length(v_name) < 2 or char_length(v_name) > 80 then return jsonb_build_object('error', 'bad-name'); end if;
  if p_logo is not null and (p_logo !~ '^data:image/png;base64,' or char_length(p_logo) > 1500000) then
    return jsonb_build_object('error', 'bad-logo');
  end if;
  foreach c in array coalesce(p_clients, '{}') loop
    if not exists (select 1 from public.clients k where k.id = c) or not public.client_seen(c, 'view') then
      return jsonb_build_object('error', 'bad-client');
    end if;
  end loop;
  if v_id is null then
    insert into public.report_partners (name, logo_data) values (v_name, p_logo) returning id into v_id;
  else
    select * into v_was from public.report_partners where id = v_id for update;
    if v_was.id is null then return jsonb_build_object('error', 'not-found'); end if;
    update public.report_partners set name = v_name, logo_data = p_logo, updated_at = now() where id = v_id;
  end if;
  update public.report_partner_clients set partner_id = null, updated_at = now()
   where partner_id = v_id and not (client_id = any (coalesce(p_clients, '{}')));
  foreach c in array coalesce(p_clients, '{}') loop
    insert into public.report_partner_clients (client_id, partner_id) values (c, v_id)
    on conflict (client_id) do update set partner_id = excluded.partner_id, updated_at = now();
  end loop;
  select string_agg(k.name, ', ' order by k.name) into v_list
    from public.report_partner_clients pc join public.clients k on k.id = pc.client_id where pc.partner_id = v_id;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'report.saved', 'Partners',
          case when v_was.id is null then 'Partner added: ' else 'Partner edited: ' end || v_name
          || case when v_was.id is not null and v_was.name is distinct from v_name then ' (was ' || v_was.name || ')' else '' end
          || case when v_was.id is not null and v_was.logo_data is distinct from p_logo then ' · logo changed' else '' end
          || ' · clients: ' || coalesce(v_list, 'none'));
  return jsonb_build_object('ok', true, 'id', v_id);
end $$;
revoke all on function public.report_partner_save(uuid, text, text, uuid[]) from public, anon;
grant execute on function public.report_partner_save(uuid, text, text, uuid[]) to authenticated;

create or replace function public.report_partner_set_active(p_id uuid, p_on boolean)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  v public.report_partners;
begin
  if me.id is null or not (public.allowed('admin') or public.allowed('reports', 'manage')) then
    return jsonb_build_object('error', 'denied');
  end if;
  select * into v from public.report_partners where id = p_id for update;
  if v.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if v.active is distinct from coalesce(p_on, false) then
    update public.report_partners set active = coalesce(p_on, false), updated_at = now() where id = p_id;
    insert into public.activity_log (actor, action, subject, detail)
    values (me.name, 'report.saved', 'Partners',
            case when coalesce(p_on, false) then 'Partner set active: ' else 'Partner set inactive: ' end || v.name);
  end if;
  return jsonb_build_object('ok', true, 'active', coalesce(p_on, false));
end $$;
revoke all on function public.report_partner_set_active(uuid, boolean) from public, anon;
grant execute on function public.report_partner_set_active(uuid, boolean) to authenticated;

create or replace function public.sm_report_snapshot(p_id uuid, p_final boolean default false)
returns jsonb
language plpgsql security definer stable set search_path = public as $$
declare
  r public.sm_reports;
  c public.clients;
begin
  if not public.allowed('reports', 'view') and not public.allowed('clients', 'view') then
    return jsonb_build_object('error', 'denied');
  end if;
  select * into r from public.sm_reports where id = p_id;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if not public.client_seen(r.client_id, 'view') then return jsonb_build_object('error', 'denied'); end if;
  -- Somebody who reads Clients but not Reports reads the finished report
  -- only: once it is confirmed, never while it is being prepared.
  if not public.allowed('reports', 'view') and r.status not in ('confirmed', 'published') then
    return jsonb_build_object('error', 'denied');
  end if;
  select * into c from public.clients where id = r.client_id;
  return jsonb_build_object(
    'report', jsonb_build_object(
      'id', r.id, 'kind', r.kind, 'title', r.title, 'client_name', c.name, 'client_logo_url', c.logo_url,
      'market', to_jsonb(c) ->> 'market', 'lang', r.lang,
      'period_start', r.period_start, 'period_end', r.period_end,
      'headline', r.headline, 'intro', r.intro, 'insights', r.insights, 'rank_metric', r.rank_metric,
      'first_month', r.first_month, 'ads_totals', r.ads_totals,
      'status', case when p_final then 'final' else r.status end,
      'version_no', r.version_no, 'generated_at', now(),
      'prepared_by_name', (select name from public.team_members where id = r.submitted_by),
      -- The partner whose logo the report carries (2026-10-06), else none.
      'partner', (select jsonb_build_object('name', p.name, 'logo', p.logo_data)
                    from public.report_partner_clients pc join public.report_partners p on p.id = pc.partner_id
                   where pc.client_id = r.client_id and p.active)),
    'platforms', coalesce((select jsonb_agg(to_jsonb(p) - 'created_at' order by p.position, p.created_at)
                  from public.sm_report_platforms p where p.report_id = r.id), '[]'::jsonb),
    'posts', coalesce((select jsonb_agg((to_jsonb(q) - 'created_at' - 'thumb_data') || jsonb_build_object('thumb_url', q.thumb_data)
                  order by q.posted_on nulls last, q.position, q.created_at)
                  from public.sm_report_posts q where q.report_id = r.id), '[]'::jsonb),
    'ads', coalesce((select jsonb_agg((to_jsonb(a) - 'created_at' - 'thumb_data') || jsonb_build_object('thumb_url', a.thumb_data)
                  order by a.position, a.created_at)
                  from public.sm_report_ads a where a.report_id = r.id), '[]'::jsonb));
end $$;
grant execute on function public.sm_report_snapshot(uuid, boolean) to authenticated;

-- END OF REPORT PARTNERS ------------------------------------------------------

-- ===========================================================================
-- REPORT WHITE LABEL — a report set as white-label carries a partner's logo
-- and the brand it covers, while it stays under the client who pays for it.
-- 2026-10-06. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/smsql.js compares the
-- two. Runs after REPORT PARTNERS (report_partners, sm_report_snapshot).
--
-- WHAT CHANGED (the user, 2026-10-06)
--   The partner is the client: The Peakle Creative is billed and has its
--   portal, and ADspace services Peakle's own clients (SKS City Mall JBCC)
--   under Peakle's name. So the report is made under Peakle and set, report
--   by report, to the partner's logo and the brand it covers.
--   1. `sm_reports.partner_id` (the partner whose logo the PDF carries) and
--      `sm_reports.brand_name` (the brand the report covers), both empty
--      for an ordinary report.
--   2. `sm_report_white_label(p_id, p_partner, p_brand)`: an admin's or
--      Reports Full Access, on any report not published (`published`),
--      an active partner (`bad-partner`), a brand of 120 characters at
--      most (`bad-brand`); filed `report.saved` from and to.
--   3. `sm_report_snapshot` sends the report's partner (name, logo) and,
--      where a brand is set, the brand as the client's name and no client
--      logo; a published version keeps what it went out with. The clients a
--      partner held (`report_partner_clients`) are no longer read.
--
-- ROLLBACK
--   Run sm_report_snapshot from REPORT PARTNERS again; the two columns and
--   the function may stay unused.
-- ===========================================================================

alter table public.sm_reports add column if not exists partner_id uuid references public.report_partners(id);
alter table public.sm_reports add column if not exists brand_name text;
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'sm_reports_brand_name') then
    alter table public.sm_reports add constraint sm_reports_brand_name
      check (brand_name is null or char_length(btrim(brand_name)) between 1 and 120);
  end if;
end $$;

create or replace function public.sm_report_white_label(p_id uuid, p_partner uuid, p_brand text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.sm_reports;
  v_brand text := nullif(btrim(coalesce(p_brand, '')), '');
  v_p public.report_partners;
  v_was text;
  v_bits text[] := '{}';
begin
  if me.id is null or not (public.allowed('admin') or public.allowed('reports', 'manage')) then
    return jsonb_build_object('error', 'denied');
  end if;
  select * into r from public.sm_reports where id = p_id for update;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if not public.client_seen(r.client_id, 'view') then return jsonb_build_object('error', 'denied'); end if;
  if r.status = 'published' then return jsonb_build_object('error', 'published'); end if;
  if v_brand is not null and char_length(v_brand) > 120 then return jsonb_build_object('error', 'bad-brand'); end if;
  if p_partner is not null then
    select * into v_p from public.report_partners where id = p_partner;
    if v_p.id is null or not v_p.active then return jsonb_build_object('error', 'bad-partner'); end if;
  end if;
  if r.partner_id is not distinct from p_partner and r.brand_name is not distinct from v_brand then
    return jsonb_build_object('ok', true);
  end if;
  if r.partner_id is distinct from p_partner then
    select p.name into v_was from public.report_partners p where p.id = r.partner_id;
    v_bits := v_bits || ('Partner logo: ' || coalesce(v_was, 'ADspace') || ' → ' || coalesce(v_p.name, 'ADspace'));
  end if;
  if r.brand_name is distinct from v_brand then
    v_bits := v_bits || ('Brand on the report: ' || coalesce(r.brand_name, 'not set') || ' → ' || coalesce(v_brand, 'not set'));
  end if;
  perform set_config('adspace.sm_fn', 'on', true);
  update public.sm_reports set partner_id = p_partner, brand_name = v_brand where id = p_id;
  perform set_config('adspace.sm_fn', 'off', true);
  perform public.sm_report_log(p_id, 'report.saved', array_to_string(v_bits, ' · '));
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.sm_report_white_label(uuid, uuid, text) from public, anon;
grant execute on function public.sm_report_white_label(uuid, uuid, text) to authenticated;

create or replace function public.sm_report_snapshot(p_id uuid, p_final boolean default false)
returns jsonb
language plpgsql security definer stable set search_path = public as $$
declare
  r public.sm_reports;
  c public.clients;
begin
  if not public.allowed('reports', 'view') and not public.allowed('clients', 'view') then
    return jsonb_build_object('error', 'denied');
  end if;
  select * into r from public.sm_reports where id = p_id;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if not public.client_seen(r.client_id, 'view') then return jsonb_build_object('error', 'denied'); end if;
  -- Somebody who reads Clients but not Reports reads the finished report
  -- only: once it is confirmed, never while it is being prepared.
  if not public.allowed('reports', 'view') and r.status not in ('confirmed', 'published') then
    return jsonb_build_object('error', 'denied');
  end if;
  select * into c from public.clients where id = r.client_id;
  return jsonb_build_object(
    'report', jsonb_build_object(
      -- A white-label report names the brand it covers, with no client logo.
      'id', r.id, 'kind', r.kind, 'title', r.title, 'client_name', coalesce(r.brand_name, c.name),
      'client_logo_url', case when r.brand_name is null then c.logo_url end,
      'market', to_jsonb(c) ->> 'market', 'lang', r.lang,
      'period_start', r.period_start, 'period_end', r.period_end,
      'headline', r.headline, 'intro', r.intro, 'insights', r.insights, 'rank_metric', r.rank_metric,
      'first_month', r.first_month, 'ads_totals', r.ads_totals,
      'status', case when p_final then 'final' else r.status end,
      'version_no', r.version_no, 'generated_at', now(),
      'prepared_by_name', (select name from public.team_members where id = r.submitted_by),
      -- The partner whose logo the report carries (2026-10-06), else none.
      'partner', (select jsonb_build_object('name', p.name, 'logo', p.logo_data)
                    from public.report_partners p where p.id = r.partner_id and p.active)),
    'platforms', coalesce((select jsonb_agg(to_jsonb(p) - 'created_at' order by p.position, p.created_at)
                  from public.sm_report_platforms p where p.report_id = r.id), '[]'::jsonb),
    'posts', coalesce((select jsonb_agg((to_jsonb(q) - 'created_at' - 'thumb_data') || jsonb_build_object('thumb_url', q.thumb_data)
                  order by q.posted_on nulls last, q.position, q.created_at)
                  from public.sm_report_posts q where q.report_id = r.id), '[]'::jsonb),
    'ads', coalesce((select jsonb_agg((to_jsonb(a) - 'created_at' - 'thumb_data') || jsonb_build_object('thumb_url', a.thumb_data)
                  order by a.position, a.created_at)
                  from public.sm_report_ads a where a.report_id = r.id), '[]'::jsonb));
end $$;
grant execute on function public.sm_report_snapshot(uuid, boolean) to authenticated;

-- END OF REPORT WHITE LABEL ---------------------------------------------------

-- ===========================================================================
-- REPORT PLATFORM NAMES — an account on a platform the list does not hold
-- carries the platform's own name, printed wherever the platform is named.
-- 2026-10-06. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/smsql.js compares the
-- two. Runs after ADS ON TWO PLATFORMS (sm_report_create).
--
-- WHAT CHANGED (the user, 2026-10-06)
--   Two accounts set to Other both read "Other" in the report. The list
--   now offers Douyin, Pinterest and 大众点评 by name, and Other asks for
--   the platform's name: all of them are kept as platform `other` with
--   `sm_report_platforms.platform_name` (40 characters at most), so the
--   platform check is left as it stands.
--   1. `sm_report_platforms.platform_name`.
--   2. `sm_report_create` carries it forward with the account.
--
-- ROLLBACK
--   Run sm_report_create from ADS ON TWO PLATFORMS again; the column may stay.
-- ===========================================================================

alter table public.sm_report_platforms add column if not exists platform_name text;
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'sm_platforms_platform_name') then
    alter table public.sm_report_platforms add constraint sm_platforms_platform_name
      check (platform_name is null or char_length(btrim(platform_name)) between 1 and 40);
  end if;
end $$;

create or replace function public.sm_report_create(p_client uuid, p_start date, p_end date, p_kind text default 'social')
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  rid uuid;
  prev uuid;
  pr public.sm_reports;
  totals jsonb := '{}'::jsonb;
  pgroups jsonb;
  ptk jsonb;
begin
  if me.id is null or not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if p_client is null or not exists (select 1 from public.clients where id = p_client) then
    return jsonb_build_object('error', 'not-found');
  end if;
  if p_start is null or p_end is null or p_end < p_start then return jsonb_build_object('error', 'bad-period'); end if;
  if coalesce(p_kind, '') not in ('social', 'ads') then return jsonb_build_object('error', 'bad-kind'); end if;
  select id into rid from public.sm_reports
   where client_id = p_client and kind = p_kind and period_start = p_start and period_end = p_end;
  if rid is not null then return jsonb_build_object('error', 'exists', 'id', rid); end if;
  select id into prev from public.sm_reports
   where client_id = p_client and kind = p_kind and period_start < p_start
   order by period_start desc limit 1;
  perform set_config('adspace.sm_fn', 'on', true);
  if p_kind = 'ads' then
    if prev is not null then
      select * into pr from public.sm_reports where id = prev;
      select coalesce(jsonb_object_agg(g.objective, jsonb_build_object('results',
               coalesce(nullif(pr.ads_totals #>> array['groups', g.objective, 'results'], '')::numeric, g.results),
               'spend', g.spend)), '{}'::jsonb)
        into pgroups
        from (select a.objective, sum(a.results) as results, sum(a.spend) as spend
                from public.sm_report_ads a where a.report_id = prev and a.platform = 'meta' group by a.objective) g;
      -- TikTok's figures carry forward under their own key, only where the
      -- earlier report had TikTok ads or TikTok figures of its own.
      if exists (select 1 from public.sm_report_ads where report_id = prev and platform = 'tiktok')
         or coalesce(pr.ads_totals #>> '{tiktok,reach}', pr.ads_totals #>> '{tiktok,impressions}',
                     pr.ads_totals #>> '{tiktok,spend}') is not null then
        ptk := jsonb_strip_nulls(jsonb_build_object(
          'prev_reach', nullif(pr.ads_totals #>> '{tiktok,reach}', '')::numeric,
          'prev_impressions', coalesce(nullif(pr.ads_totals #>> '{tiktok,impressions}', '')::numeric,
                                       (select sum(impressions) from public.sm_report_ads where report_id = prev and platform = 'tiktok')),
          'prev_spend', coalesce(nullif(pr.ads_totals #>> '{tiktok,spend}', '')::numeric,
                                 (select sum(spend) from public.sm_report_ads where report_id = prev and platform = 'tiktok'))));
      end if;
      totals := jsonb_strip_nulls(jsonb_build_object(
        'prev_start', pr.period_start, 'prev_end', pr.period_end,
        'prev_reach', nullif(pr.ads_totals ->> 'reach', '')::numeric,
        'prev_impressions', coalesce(nullif(pr.ads_totals ->> 'impressions', '')::numeric,
                                     (select sum(impressions) from public.sm_report_ads where report_id = prev and platform = 'meta')),
        'prev_spend', coalesce(nullif(pr.ads_totals ->> 'spend', '')::numeric,
                               (select sum(spend) from public.sm_report_ads where report_id = prev and platform = 'meta')),
        'prev_groups', pgroups,
        'tiktok', ptk));
    else
      -- No earlier report here: most clients advertised before the portal, so
      -- the period before is prefilled for the team to type its figures.
      if date_trunc('month', p_start)::date = p_start and (p_start + interval '1 month' - interval '1 day')::date = p_end then
        totals := jsonb_build_object('prev_start', (p_start - interval '1 month')::date, 'prev_end', p_start - 1);
      else
        totals := jsonb_build_object('prev_start', p_start - (p_end - p_start + 1), 'prev_end', p_start - 1);
      end if;
    end if;
    insert into public.sm_reports (client_id, kind, title, period_start, period_end, created_by, first_month, ads_totals)
    values (p_client, p_kind, 'Social Media Advertising Report', p_start, p_end, me.id, false, totals)
    returning id into rid;
  else
    insert into public.sm_reports (client_id, kind, period_start, period_end, created_by)
    values (p_client, p_kind, p_start, p_end, me.id) returning id into rid;
    if prev is not null then
      insert into public.sm_report_platforms (report_id, platform, platform_name, account_name, handle, group_key, group_label,
        position, metrics, followers_start, er_basis, metric_notes)
      select rid, p.platform, p.platform_name, p.account_name, p.handle, p.group_key, p.group_label, p.position, p.metrics,
             coalesce(p.followers_end, case when p.followers_start is not null and p.growth_override is not null
                                            then p.followers_start + p.growth_override end),
             p.er_basis, p.metric_notes
        from public.sm_report_platforms p where p.report_id = prev;
    end if;
  end if;
  perform set_config('adspace.sm_fn', 'off', true);
  perform public.sm_report_log(rid, 'report.created');
  return jsonb_build_object('ok', true, 'id', rid, 'carried', prev is not null);
end $$;
grant execute on function public.sm_report_create(uuid, date, date, text) to authenticated;

-- END OF REPORT PLATFORM NAMES -----------------------------------------------

-- ===========================================================================
-- HR LETTERS SHARED — an HR letter issued to a colleague is theirs to read in
-- My performance (Letters), behind the same fresh proof, and they are told.
-- 2026-10-06. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/perf.js compares the
-- two. Runs after the documents register and PUSH (ops_notifications_push).
--
-- WHAT CHANGED (the user, 2026-10-06)
--   A letter management issues to a team member is shared with them by
--   default, a tick in the issue sheet turning it off for a sensitive one.
--   1. `documents.shared_at` / `shared_by`: when, and by whom, an HR letter
--      was shared with the colleague it names (`member_id`).
--   2. `document_share(p_id, p_on)`: HR letters at Work; an HR letter that
--      names a colleague (`not-hr`, `no-member`). Shared, the colleague is
--      told once (`ops_notifications` kind `hr.letter`, its kind and never
--      its words; a bell and a push opening Letters); stopped, it leaves
--      their list. Filed under HR with the kind alone.
--   3. `my_letters()`: the caller's own shared HR letters, behind the
--      fresh proof (`perf_mine_gate`), newest first, a letter a reissue
--      replaced left out and a voided one marked so; enough of each row to
--      draw its PDF in the browser, never another colleague's.
--   4. `ops_notifications_push` opens Letters for an `hr.letter`.
--
-- ROLLBACK
--   Run ops_notifications_push from A CLIENT PAUSED OR PAST SAYS WHY again;
--   the columns and the two functions may stay unused.
-- ===========================================================================

alter table public.documents add column if not exists shared_at timestamptz;
alter table public.documents add column if not exists shared_by text;

create or replace function public.document_share(p_id uuid, p_on boolean)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  d public.documents;
  v_kind text;
begin
  if me.id is null or not public.register_may('hr', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into d from public.documents where id = p_id for update;
  if d.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if d.family <> 'hr' then return jsonb_build_object('error', 'not-hr'); end if;
  if d.member_id is null then return jsonb_build_object('error', 'no-member'); end if;
  if coalesce(p_on, false) = (d.shared_at is not null) then
    return jsonb_build_object('ok', true, 'shared', d.shared_at is not null);
  end if;
  v_kind := coalesce(nullif(btrim(d.kind), ''), 'HR letter');
  if coalesce(p_on, false) then
    update public.documents set shared_at = now(), shared_by = me.name where id = p_id;
    insert into public.ops_notifications (team_member_id, kind, title, body, dedupe_key)
    values (d.member_id, 'hr.letter', 'A letter was issued to you', v_kind, 'hr.letter:' || d.id::text)
    on conflict (dedupe_key) do nothing;
  else
    update public.documents set shared_at = null, shared_by = null where id = p_id;
  end if;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'register.edited', 'HR',
          case when coalesce(p_on, false) then 'Shared with the colleague: ' else 'No longer shared: ' end || v_kind);
  return jsonb_build_object('ok', true, 'shared', coalesce(p_on, false));
end $$;
revoke all on function public.document_share(uuid, boolean) from public, anon;
grant execute on function public.document_share(uuid, boolean) to authenticated;

create or replace function public.my_letters()
returns jsonb
language plpgsql security definer stable set search_path = public as $$
declare
  me public.team_members;
  g jsonb;
begin
  g := public.perf_mine_gate();
  if g is not null then return g; end if;
  me := public.ops_me();
  return jsonb_build_object('letters', coalesce((
    select jsonb_agg(jsonb_build_object(
             'id', d.id, 'serial', d.serial, 'kind', d.kind, 'family', d.family, 'title', d.title,
             'salutation', d.salutation, 'closing', d.closing, 'recipient', d.recipient, 'body', d.body,
             'languages', d.languages, 'signatory', d.signatory, 'signed', d.signed, 'issued_at', d.issued_at,
             'source', d.source, 'file_url', d.file_url, 'shared_at', d.shared_at,
             'void', d.voided_at is not null)
           order by coalesce(d.issued_at, d.created_at::date) desc, d.created_at desc)
      from public.documents d
     where d.member_id = me.id and d.family = 'hr' and d.shared_at is not null
       and not exists (select 1 from public.documents n where n.replaces = d.id and n.voided_at is null)), '[]'::jsonb));
end $$;
revoke all on function public.my_letters() from public, anon;
grant execute on function public.my_letters() to authenticated;

create or replace function public.ops_notifications_push()
returns trigger
language plpgsql security definer set search_path = public as $$
declare
  v_title text := coalesce(nullif(btrim(new.title), ''), 'My Work');
  v_body  text := coalesce(new.body, '');
begin
  perform public.push_queue('team', new.team_member_id,
    jsonb_build_object('en', jsonb_build_object('title', v_title, 'body', v_body),
                       'zh', jsonb_build_object('title', v_title, 'body', v_body)),
    case when new.task_id is not null then '/admin/?s=work&open=' || new.task_id::text
         when new.report_id is not null then '/admin/?s=reports&report=' || new.report_id::text
         when new.kind = 'client_left' then '/admin/?s=work'
         when new.kind = 'hr.letter' then '/admin/?s=mine&view=letters'
         else '/admin/' end,
    case when new.task_id is not null then 'task-' || new.task_id::text
         when new.report_id is not null then 'report-' || new.report_id::text
         when new.kind = 'hr.letter' then 'hr-letter'
         else null end);
  return new;
exception when others then
  return new;
end $$;

-- END OF HR LETTERS SHARED ----------------------------------------------------

-- ===========================================================================
-- WHITE LABEL ON THE CLIENT — a client ticked White label on its Brand pane
-- carries a wide logo for reports, and a report is set to one of those
-- clients and the brand it covers.
-- 2026-10-07. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/smsql.js compares the
-- two. Runs after REPORT WHITE LABEL and CLIENT BILLING COLUMNS.
--
-- WHAT CHANGED (the user, 2026-10-06)
--   The partner is a client, so the separate list of partners goes. A
--   client's Brand pane holds a White label tick and, while it is ticked,
--   the wide logo its reports carry; a report's White label offers only the
--   Active clients ticked so.
--   1. `clients.white_label` (off by default) and `clients.report_logo` (a
--      PNG data URL, 1200 by 400 at most); ticked needs the logo
--      (`clients_white_label_logo`). Both readable to the team, as every
--      other non-billing column. Changing either is Reports: White label
--      at Work (`clients_white_label_guard`, as Billing's).
--   2. `sm_reports.label_client`: the white-label client whose logo the
--      report carries.
--   3. `sm_report_label(p_id, p_client, p_brand)`: Reports: White label at
--      Work, on any report not published (`published`), a client
--      ticked White label, holding its logo and Active (`bad-client`), a
--      brand of 120 characters at most (`bad-brand`); filed `report.saved`
--      from and to.
--   4. Reports: White label (`reports.whitelabel`) is a granted part, as
--      the operations parts are (`ops_granted`): an admin holds it, any
--      other group only once it is set (the user, 2026-10-07: controllable
--      in the groups, on for Admin and Managers for now). Managers is given
--      it once, where the key is not yet set.
--   5. `sm_report_snapshot` sends that client as the partner (name, logo)
--      while it is still ticked, and, where a brand is set, the brand as the
--      client's name and no client logo. `report_partners` is no longer read.
--
-- ROLLBACK
--   Run sm_report_snapshot from REPORT WHITE LABEL again; the columns, the
--   guard (it only asks the part) and the function may stay unused.
-- ===========================================================================

alter table public.clients add column if not exists white_label boolean not null default false;
alter table public.clients add column if not exists report_logo text;
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'clients_white_label_logo') then
    alter table public.clients add constraint clients_white_label_logo
      check (not white_label or report_logo is not null);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'clients_report_logo_png') then
    alter table public.clients add constraint clients_report_logo_png
      check (report_logo is null or (report_logo like 'data:image/png;base64,%' and char_length(report_logo) <= 1500000));
  end if;
end $$;
grant select (white_label, report_logo) on table public.clients to authenticated;

create or replace function public.clients_white_label_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if pg_trigger_depth() > 1 or (auth.jwt() ->> 'email') is null then return new; end if;
  if (new.white_label, new.report_logo) is distinct from (old.white_label, old.report_logo)
     and not public.ops_granted('reports.whitelabel', 'work') then
    raise exception 'White label needs Reports: White label at Work.' using errcode = '42501', hint = 'white-label';
  end if;
  return new;
end $$;
revoke all on function public.clients_white_label_guard() from public, anon, authenticated;
create or replace trigger clients_white_label_guard before update on public.clients
  for each row execute function public.clients_white_label_guard();

-- No foreign key, as `posts.cover_for`: a client gone leaves the report on
-- ADspace's wordmark (the snapshot finds no ticked client).
alter table public.sm_reports add column if not exists label_client uuid;

update public.team_roles set access = access || '{"reports.whitelabel": "work"}'::jsonb
 where slug = 'managers' and not (access ? 'reports.whitelabel');

create or replace function public.sm_report_label(p_id uuid, p_client uuid, p_brand text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.sm_reports;
  v_brand text := nullif(btrim(coalesce(p_brand, '')), '');
  v_c public.clients;
  v_was text;
  v_bits text[] := '{}';
begin
  if me.id is null or not public.ops_granted('reports.whitelabel', 'work') then
    return jsonb_build_object('error', 'denied');
  end if;
  select * into r from public.sm_reports where id = p_id for update;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if not public.client_seen(r.client_id, 'view') then return jsonb_build_object('error', 'denied'); end if;
  if r.status = 'published' then return jsonb_build_object('error', 'published'); end if;
  if v_brand is not null and char_length(v_brand) > 120 then return jsonb_build_object('error', 'bad-brand'); end if;
  if p_client is not null then
    select * into v_c from public.clients where id = p_client;
    if v_c.id is null or not v_c.white_label or v_c.report_logo is null or v_c.stage <> 'active' then
      return jsonb_build_object('error', 'bad-client');
    end if;
  end if;
  if r.label_client is not distinct from p_client and r.brand_name is not distinct from v_brand then
    return jsonb_build_object('ok', true);
  end if;
  if r.label_client is distinct from p_client then
    select c.name into v_was from public.clients c where c.id = r.label_client;
    v_bits := v_bits || ('White label: ' || coalesce(v_was, 'ADspace') || ' → ' || coalesce(v_c.name, 'ADspace'));
  end if;
  if r.brand_name is distinct from v_brand then
    v_bits := v_bits || ('Brand on the report: ' || coalesce(r.brand_name, 'not set') || ' → ' || coalesce(v_brand, 'not set'));
  end if;
  perform set_config('adspace.sm_fn', 'on', true);
  update public.sm_reports set label_client = p_client, partner_id = null, brand_name = v_brand where id = p_id;
  perform set_config('adspace.sm_fn', 'off', true);
  perform public.sm_report_log(p_id, 'report.saved', array_to_string(v_bits, ' · '));
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.sm_report_label(uuid, uuid, text) from public, anon;
grant execute on function public.sm_report_label(uuid, uuid, text) to authenticated;

create or replace function public.sm_report_snapshot(p_id uuid, p_final boolean default false)
returns jsonb
language plpgsql security definer stable set search_path = public as $$
declare
  r public.sm_reports;
  c public.clients;
begin
  if not public.allowed('reports', 'view') and not public.allowed('clients', 'view') then
    return jsonb_build_object('error', 'denied');
  end if;
  select * into r from public.sm_reports where id = p_id;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if not public.client_seen(r.client_id, 'view') then return jsonb_build_object('error', 'denied'); end if;
  -- Somebody who reads Clients but not Reports reads the finished report
  -- only: once it is confirmed, never while it is being prepared.
  if not public.allowed('reports', 'view') and r.status not in ('confirmed', 'published') then
    return jsonb_build_object('error', 'denied');
  end if;
  select * into c from public.clients where id = r.client_id;
  return jsonb_build_object(
    'report', jsonb_build_object(
      -- A white-label report names the brand it covers, with no client logo.
      'id', r.id, 'kind', r.kind, 'title', r.title, 'client_name', coalesce(r.brand_name, c.name),
      'client_logo_url', case when r.brand_name is null then c.logo_url end,
      'market', to_jsonb(c) ->> 'market', 'lang', r.lang,
      'period_start', r.period_start, 'period_end', r.period_end,
      'headline', r.headline, 'intro', r.intro, 'insights', r.insights, 'rank_metric', r.rank_metric,
      'first_month', r.first_month, 'ads_totals', r.ads_totals,
      'status', case when p_final then 'final' else r.status end,
      'version_no', r.version_no, 'generated_at', now(),
      'prepared_by_name', (select name from public.team_members where id = r.submitted_by),
      -- The white-label client whose logo the report carries (2026-10-07),
      -- while it is still ticked; else none.
      'partner', (select jsonb_build_object('name', l.name, 'logo', l.report_logo)
                    from public.clients l where l.id = r.label_client and l.white_label)),
    'platforms', coalesce((select jsonb_agg(to_jsonb(p) - 'created_at' order by p.position, p.created_at)
                  from public.sm_report_platforms p where p.report_id = r.id), '[]'::jsonb),
    'posts', coalesce((select jsonb_agg((to_jsonb(q) - 'created_at' - 'thumb_data') || jsonb_build_object('thumb_url', q.thumb_data)
                  order by q.posted_on nulls last, q.position, q.created_at)
                  from public.sm_report_posts q where q.report_id = r.id), '[]'::jsonb),
    'ads', coalesce((select jsonb_agg((to_jsonb(a) - 'created_at' - 'thumb_data') || jsonb_build_object('thumb_url', a.thumb_data)
                  order by a.position, a.created_at)
                  from public.sm_report_ads a where a.report_id = r.id), '[]'::jsonb));
end $$;
grant execute on function public.sm_report_snapshot(uuid, boolean) to authenticated;

-- END OF WHITE LABEL ON THE CLIENT --------------------------------------------

-- ===========================================================================
-- WHITE LABEL BRANDS — a white-label client keeps a list of the brands it is
-- serviced for, and a report belongs to its client and its brand, so each
-- brand has its own report a month, its own AI quota and its own history.
-- 2026-10-07. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/smsql.js compares the
-- two. Runs after WHITE LABEL ON THE CLIENT.
--
-- WHAT CHANGED (the user, 2026-10-07)
--   The partner is the client (Peakle), and Peakle's own clients (A, B, C)
--   are its brands. A report for Client A must not take Peakle's own month,
--   nor share its AI quota with Client B.
--   1. `client_brands` (RLS on, no policy, no grant): a client's saved
--      brands, a name each (unique within the client, any case), stood down
--      with `active`, never removed. Read through `client_brands_list`
--      (Reports or Clients at View, the client in scope); written through
--      `client_brand_save` (Reports: White label at Work), filed
--      `client.brand`. A rename carries onto the client's reports not yet
--      published.
--   2. `sm_reports.brand_id`: the brand a report covers. One report a client,
--      kind, period and brand (`sm_reports_client_brand_period_idx`; the
--      client's own report is the one with no brand).
--   3. `sm_report_create_for(p_client, p_start, p_end, p_kind, p_brand)`
--      starts a report for a brand (Reports: White label at Work; the client
--      ticked White label with its logo; the brand the client's, active,
--      `bad-brand`), carrying accounts forward from that brand's own last
--      report; `sm_report_create` is the same with no brand.
--   4. `sm_report_brand(p_id, p_brand)` sets or clears the brand of a report
--      not published (`exists` where the brand already has one for the
--      period), the report's own client's logo going with it; filed from and
--      to. `sm_report_label` is no longer called.
--   5. `ai_drafts.brand_id`, filled from the report on every insert, and
--      `ai_draft_same` counting by brand, so a brand's drafts are its own.
--   6. `sm_report_move` refuses a white-label report (`white-label`) and
--      checks the destination's own reports only.
--   7. A report set before this (a typed brand name) is given a saved brand
--      of that name.
--   8. Mark as sent (the user, 2026-10-07): `sm_reports.sent_on` /
--      `sent_by`, set on a published report only through
--      `sm_report_sent(p_id, p_on)` (Reports at Work; `not-published`; a day
--      not after today in Malaysia nor before the period starts,
--      `bad-date`; null marks it not sent), filed from and to.
--
-- BY HAND, ONCE, IN THE SQL EDITOR (the connector holds the statement):
--   drop index if exists public.sm_reports_client_period_idx;
--   Until then a second report for a period (a brand's beside the client's
--   own) is refused (`index-pending`).
--
-- ROLLBACK
--   Run sm_report_create, sm_report_move and ai_draft_same from their earlier
--   sections again; the table, the columns and the new functions may stay.
-- ===========================================================================

create table if not exists public.client_brands (
  id          uuid primary key default gen_random_uuid(),
  client_id   uuid not null,
  name        text not null,
  active      boolean not null default true,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  constraint client_brands_name check (char_length(btrim(name)) between 1 and 120)
);
create unique index if not exists client_brands_name_idx on public.client_brands (client_id, lower(btrim(name)));
alter table public.client_brands enable row level security;
revoke all on public.client_brands from public, anon, authenticated;

alter table public.sm_reports add column if not exists brand_id uuid;
create unique index if not exists sm_reports_client_brand_period_idx
  on public.sm_reports (client_id, kind, period_start, period_end, coalesce(brand_id, '00000000-0000-0000-0000-000000000000'::uuid));

-- A report given a typed brand before the list existed takes a saved brand.
insert into public.client_brands (client_id, name)
select distinct r.client_id, btrim(r.brand_name) from public.sm_reports r
 where r.brand_name is not null and r.brand_id is null
on conflict do nothing;
update public.sm_reports r set brand_id = b.id
  from public.client_brands b
 where r.brand_id is null and r.brand_name is not null
   and b.client_id = r.client_id and lower(btrim(b.name)) = lower(btrim(r.brand_name));

alter table public.ai_drafts add column if not exists brand_id uuid;
create or replace function public.ai_drafts_brand()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.report_id is not null and new.brand_id is null then
    select r.brand_id into new.brand_id from public.sm_reports r where r.id = new.report_id;
  end if;
  return new;
end $$;
revoke all on function public.ai_drafts_brand() from public, anon, authenticated;
create or replace trigger ai_drafts_brand before insert on public.ai_drafts
  for each row execute function public.ai_drafts_brand();
update public.ai_drafts d set brand_id = r.brand_id
  from public.sm_reports r where d.report_id = r.id and d.brand_id is null and r.brand_id is not null;

create or replace function public.ai_draft_same(p_report uuid)
returns setof public.ai_drafts
language sql stable security definer set search_path = public as $$
  select d.* from public.ai_drafts d
   where d.outcome <> 'failed' and d.purpose = 'draft'
     and (d.report_id = p_report
          or exists (select 1 from public.sm_reports r
                      where r.id = p_report and d.client_id = r.client_id and d.kind = r.kind
                        and d.brand_id is not distinct from r.brand_id
                        and d.period_start <= r.period_end and d.period_end >= r.period_start))
$$;
revoke all on function public.ai_draft_same(uuid) from public, anon, authenticated;

create or replace function public.client_brands_list(p_client uuid)
returns jsonb
language plpgsql security definer stable set search_path = public as $$
begin
  if not (public.allowed('reports', 'view') or public.allowed('clients', 'view')) then
    return jsonb_build_object('error', 'denied');
  end if;
  if not public.client_seen(p_client, 'view') then return jsonb_build_object('error', 'denied'); end if;
  return jsonb_build_object('brands', coalesce((
    select jsonb_agg(jsonb_build_object('id', b.id, 'name', b.name, 'active', b.active) order by b.active desc, lower(b.name))
      from public.client_brands b where b.client_id = p_client), '[]'::jsonb));
end $$;
revoke all on function public.client_brands_list(uuid) from public, anon;
grant execute on function public.client_brands_list(uuid) to authenticated;

create or replace function public.client_brand_save(p_id uuid, p_client uuid, p_name text, p_active boolean default true)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  v_name text := nullif(btrim(coalesce(p_name, '')), '');
  b public.client_brands;
  v_client text;
  v_id uuid;
begin
  if me.id is null or not public.ops_granted('reports.whitelabel', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if not public.client_seen(p_client, 'view') then return jsonb_build_object('error', 'denied'); end if;
  select c.name into v_client from public.clients c where c.id = p_client;
  if v_client is null then return jsonb_build_object('error', 'not-found'); end if;
  if v_name is null or char_length(v_name) > 120 then return jsonb_build_object('error', 'bad-name'); end if;
  if exists (select 1 from public.client_brands x where x.client_id = p_client and lower(btrim(x.name)) = lower(v_name)
              and x.id is distinct from p_id) then
    return jsonb_build_object('error', 'taken');
  end if;
  if p_id is null then
    insert into public.client_brands (client_id, name, active) values (p_client, v_name, coalesce(p_active, true))
    returning id into v_id;
    insert into public.activity_log (actor, action, subject, detail)
    values (me.name, 'client.brand', v_client, 'White label brand added: ' || v_name);
    return jsonb_build_object('ok', true, 'id', v_id);
  end if;
  select * into b from public.client_brands where id = p_id and client_id = p_client for update;
  if b.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if b.name = v_name and b.active = coalesce(p_active, b.active) then return jsonb_build_object('ok', true, 'id', b.id); end if;
  update public.client_brands set name = v_name, active = coalesce(p_active, b.active), updated_at = now() where id = p_id;
  if b.name <> v_name then
    perform set_config('adspace.sm_fn', 'on', true);
    update public.sm_reports set brand_name = v_name where brand_id = p_id and status <> 'published';
    perform set_config('adspace.sm_fn', 'off', true);
  end if;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'client.brand', v_client, concat_ws(' · ',
    case when b.name <> v_name then 'White label brand: ' || b.name || ' → ' || v_name end,
    case when b.active <> coalesce(p_active, b.active)
         then 'White label brand ' || v_name || (case when p_active then ': inactive → active' else ': active → inactive' end) end));
  return jsonb_build_object('ok', true, 'id', b.id);
end $$;
revoke all on function public.client_brand_save(uuid, uuid, text, boolean) from public, anon;
grant execute on function public.client_brand_save(uuid, uuid, text, boolean) to authenticated;

create or replace function public.sm_report_create_for(p_client uuid, p_start date, p_end date, p_kind text, p_brand uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  rid uuid;
  prev uuid;
  pr public.sm_reports;
  totals jsonb := '{}'::jsonb;
  pgroups jsonb;
  ptk jsonb;
  c public.clients;
  b public.client_brands;
begin
  if me.id is null or not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into c from public.clients where id = p_client;
  if c.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if p_start is null or p_end is null or p_end < p_start then return jsonb_build_object('error', 'bad-period'); end if;
  if coalesce(p_kind, '') not in ('social', 'ads') then return jsonb_build_object('error', 'bad-kind'); end if;
  if p_brand is not null then
    if not public.ops_granted('reports.whitelabel', 'work') then return jsonb_build_object('error', 'denied'); end if;
    select * into b from public.client_brands where id = p_brand;
    if b.id is null or b.client_id <> p_client or not b.active or not c.white_label or c.report_logo is null then
      return jsonb_build_object('error', 'bad-brand');
    end if;
  end if;
  select id into rid from public.sm_reports
   where client_id = p_client and kind = p_kind and period_start = p_start and period_end = p_end
     and brand_id is not distinct from p_brand;
  if rid is not null then return jsonb_build_object('error', 'exists', 'id', rid); end if;
  select id into prev from public.sm_reports
   where client_id = p_client and kind = p_kind and period_start < p_start and brand_id is not distinct from p_brand
   order by period_start desc limit 1;
  perform set_config('adspace.sm_fn', 'on', true);
  begin
    if p_kind = 'ads' then
      if prev is not null then
        select * into pr from public.sm_reports where id = prev;
        select coalesce(jsonb_object_agg(g.objective, jsonb_build_object('results',
                 coalesce(nullif(pr.ads_totals #>> array['groups', g.objective, 'results'], '')::numeric, g.results),
                 'spend', g.spend)), '{}'::jsonb)
          into pgroups
          from (select a.objective, sum(a.results) as results, sum(a.spend) as spend
                  from public.sm_report_ads a where a.report_id = prev and a.platform = 'meta' group by a.objective) g;
        if exists (select 1 from public.sm_report_ads where report_id = prev and platform = 'tiktok')
           or coalesce(pr.ads_totals #>> '{tiktok,reach}', pr.ads_totals #>> '{tiktok,impressions}',
                       pr.ads_totals #>> '{tiktok,spend}') is not null then
          ptk := jsonb_strip_nulls(jsonb_build_object(
            'prev_reach', nullif(pr.ads_totals #>> '{tiktok,reach}', '')::numeric,
            'prev_impressions', coalesce(nullif(pr.ads_totals #>> '{tiktok,impressions}', '')::numeric,
                                         (select sum(impressions) from public.sm_report_ads where report_id = prev and platform = 'tiktok')),
            'prev_spend', coalesce(nullif(pr.ads_totals #>> '{tiktok,spend}', '')::numeric,
                                   (select sum(spend) from public.sm_report_ads where report_id = prev and platform = 'tiktok'))));
        end if;
        totals := jsonb_strip_nulls(jsonb_build_object(
          'prev_start', pr.period_start, 'prev_end', pr.period_end,
          'prev_reach', nullif(pr.ads_totals ->> 'reach', '')::numeric,
          'prev_impressions', coalesce(nullif(pr.ads_totals ->> 'impressions', '')::numeric,
                                       (select sum(impressions) from public.sm_report_ads where report_id = prev and platform = 'meta')),
          'prev_spend', coalesce(nullif(pr.ads_totals ->> 'spend', '')::numeric,
                                 (select sum(spend) from public.sm_report_ads where report_id = prev and platform = 'meta')),
          'prev_groups', pgroups,
          'tiktok', ptk));
      else
        if date_trunc('month', p_start)::date = p_start and (p_start + interval '1 month' - interval '1 day')::date = p_end then
          totals := jsonb_build_object('prev_start', (p_start - interval '1 month')::date, 'prev_end', p_start - 1);
        else
          totals := jsonb_build_object('prev_start', p_start - (p_end - p_start + 1), 'prev_end', p_start - 1);
        end if;
      end if;
      insert into public.sm_reports (client_id, kind, title, period_start, period_end, created_by, first_month, ads_totals,
                                     brand_id, brand_name, label_client)
      values (p_client, p_kind, 'Social Media Advertising Report', p_start, p_end, me.id, false, totals,
              b.id, b.name, case when b.id is not null then p_client end)
      returning id into rid;
    else
      insert into public.sm_reports (client_id, kind, period_start, period_end, created_by, brand_id, brand_name, label_client)
      values (p_client, p_kind, p_start, p_end, me.id, b.id, b.name, case when b.id is not null then p_client end)
      returning id into rid;
      if prev is not null then
        insert into public.sm_report_platforms (report_id, platform, platform_name, account_name, handle, group_key, group_label,
          position, metrics, followers_start, er_basis, metric_notes)
        select rid, p.platform, p.platform_name, p.account_name, p.handle, p.group_key, p.group_label, p.position, p.metrics,
               coalesce(p.followers_end, case when p.followers_start is not null and p.growth_override is not null
                                              then p.followers_start + p.growth_override end),
               p.er_basis, p.metric_notes
          from public.sm_report_platforms p where p.report_id = prev;
      end if;
    end if;
  exception when unique_violation then
    perform set_config('adspace.sm_fn', 'off', true);
    return jsonb_build_object('error', 'index-pending');
  end;
  perform set_config('adspace.sm_fn', 'off', true);
  perform public.sm_report_log(rid, 'report.created', case when b.id is not null then 'White label: ' || b.name end);
  return jsonb_build_object('ok', true, 'id', rid, 'carried', prev is not null);
end $$;
revoke all on function public.sm_report_create_for(uuid, date, date, text, uuid) from public, anon;
grant execute on function public.sm_report_create_for(uuid, date, date, text, uuid) to authenticated;

create or replace function public.sm_report_create(p_client uuid, p_start date, p_end date, p_kind text default 'social')
returns jsonb
language sql security definer set search_path = public as $$
  select public.sm_report_create_for(p_client, p_start, p_end, p_kind, null)
$$;
grant execute on function public.sm_report_create(uuid, date, date, text) to authenticated;

create or replace function public.sm_report_brand(p_id uuid, p_brand uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.sm_reports;
  c public.clients;
  b public.client_brands;
begin
  if me.id is null or not public.ops_granted('reports.whitelabel', 'work') then
    return jsonb_build_object('error', 'denied');
  end if;
  select * into r from public.sm_reports where id = p_id for update;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if not public.client_seen(r.client_id, 'view') then return jsonb_build_object('error', 'denied'); end if;
  if r.status = 'published' then return jsonb_build_object('error', 'published'); end if;
  select * into c from public.clients where id = r.client_id;
  if p_brand is not null then
    select * into b from public.client_brands where id = p_brand;
    if b.id is null or b.client_id <> r.client_id or not b.active or not c.white_label or c.report_logo is null then
      return jsonb_build_object('error', 'bad-brand');
    end if;
  end if;
  if r.brand_id is not distinct from p_brand then return jsonb_build_object('ok', true); end if;
  if exists (select 1 from public.sm_reports x
              where x.client_id = r.client_id and x.kind = r.kind and x.id <> r.id
                and x.period_start = r.period_start and x.period_end = r.period_end
                and x.brand_id is not distinct from p_brand) then
    return jsonb_build_object('error', 'exists');
  end if;
  perform set_config('adspace.sm_fn', 'on', true);
  begin
    update public.sm_reports
       set brand_id = b.id, brand_name = b.name, partner_id = null,
           label_client = case when b.id is not null then r.client_id end
     where id = p_id;
  exception when unique_violation then
    perform set_config('adspace.sm_fn', 'off', true);
    return jsonb_build_object('error', 'index-pending');
  end;
  perform set_config('adspace.sm_fn', 'off', true);
  perform public.sm_report_log(p_id, 'report.saved',
    'White label: ' || coalesce(r.brand_name, 'not set') || ' → ' || coalesce(b.name, 'not set'));
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.sm_report_brand(uuid, uuid) from public, anon;
grant execute on function public.sm_report_brand(uuid, uuid) to authenticated;

create or replace function public.sm_report_move(p_id uuid, p_client uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.sm_reports;
  c public.clients;
  was text;
begin
  if me.id is null or not public.allowed('admin') then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_id for update;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if r.status <> 'draft' then return jsonb_build_object('error', 'not-draft', 'status', r.status); end if;
  if r.brand_id is not null then return jsonb_build_object('error', 'white-label'); end if;
  select * into c from public.clients where id = p_client;
  if c.id is null or c.stage <> 'active' then return jsonb_build_object('error', 'not-active'); end if;
  if c.id = r.client_id then return jsonb_build_object('ok', true, 'client_id', c.id); end if;
  if exists (select 1 from public.sm_reports x
              where x.client_id = c.id and x.kind = r.kind and x.id <> r.id and x.brand_id is null
                and x.period_start <= r.period_end and x.period_end >= r.period_start) then
    return jsonb_build_object('error', 'exists');
  end if;
  select k.name into was from public.clients k where k.id = r.client_id;
  perform public.sm_report_log(p_id, 'report.saved', 'Client: ' || coalesce(was, 'not set') || ' → ' || c.name);
  perform set_config('adspace.sm_fn', 'on', true);
  update public.sm_reports set client_id = c.id where id = p_id;
  perform set_config('adspace.sm_fn', 'off', true);
  update public.ai_drafts set client_id = c.id where report_id = p_id;
  perform public.sm_report_log(p_id, 'report.saved', 'Client: ' || coalesce(was, 'not set') || ' → ' || c.name);
  return jsonb_build_object('ok', true, 'client_id', c.id);
end $$;
revoke all on function public.sm_report_move(uuid, uuid) from public, anon, authenticated;
grant execute on function public.sm_report_move(uuid, uuid) to authenticated;

alter table public.sm_reports add column if not exists sent_on date;
alter table public.sm_reports add column if not exists sent_by text;

create or replace function public.sm_report_sent(p_id uuid, p_on date)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.sm_reports;
  v_today date := (now() at time zone 'Asia/Kuala_Lumpur')::date;
begin
  if me.id is null or not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_id for update;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if not public.client_seen(r.client_id, 'view') then return jsonb_build_object('error', 'denied'); end if;
  if r.status <> 'published' then return jsonb_build_object('error', 'not-published'); end if;
  if p_on is not null and (p_on > v_today or p_on < r.period_start) then return jsonb_build_object('error', 'bad-date'); end if;
  if r.sent_on is not distinct from p_on then return jsonb_build_object('ok', true); end if;
  perform set_config('adspace.sm_fn', 'on', true);
  update public.sm_reports set sent_on = p_on, sent_by = case when p_on is null then null else me.name end where id = p_id;
  perform set_config('adspace.sm_fn', 'off', true);
  perform public.sm_report_log(p_id, 'report.saved', 'Sent to client: ' ||
    coalesce(public.register_day(r.sent_on), 'not set') || ' → ' || coalesce(public.register_day(p_on), 'not set'));
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.sm_report_sent(uuid, date) from public, anon;
grant execute on function public.sm_report_sent(uuid, date) to authenticated;

-- END OF WHITE LABEL BRANDS ---------------------------------------------------

-- ===========================================================================
-- WHITE LABEL BRAND LOGO — each brand says whose mark heads its reports: the
-- white-label client's wide logo, or ADspace's own wordmark.
-- 2026-10-07. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/smsql.js compares the
-- two. Runs after WHITE LABEL BRANDS.
--
-- WHAT CHANGED (the user, 2026-10-07)
--   Some of a partner's brands go out under the partner's logo, some under
--   ADspace's own mark; the brand is still named as the client either way.
--   1. `client_brands.logo`: 'partner' (the client's wide logo, the default)
--      or 'adspace'.
--   2. `client_brand_logo(p_id, p_logo)`: Reports: White label at Work;
--      `bad-logo`; filed `client.brand` from and to.
--   3. `client_brands_list` sends each brand's logo.
--   4. `sm_report_snapshot` sends the partner only where the report's brand
--      takes the partner's logo; a published version keeps what it went out
--      with.
--
-- ROLLBACK
--   Run sm_report_snapshot from WHITE LABEL ON THE CLIENT and
--   client_brands_list from WHITE LABEL BRANDS again; the column and the
--   function may stay unused.
-- ===========================================================================

alter table public.client_brands add column if not exists logo text not null default 'partner';
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'client_brands_logo') then
    alter table public.client_brands add constraint client_brands_logo check (logo in ('partner', 'adspace'));
  end if;
end $$;

create or replace function public.client_brands_list(p_client uuid)
returns jsonb
language plpgsql security definer stable set search_path = public as $$
begin
  if not (public.allowed('reports', 'view') or public.allowed('clients', 'view')) then
    return jsonb_build_object('error', 'denied');
  end if;
  if not public.client_seen(p_client, 'view') then return jsonb_build_object('error', 'denied'); end if;
  return jsonb_build_object('brands', coalesce((
    select jsonb_agg(jsonb_build_object('id', b.id, 'name', b.name, 'active', b.active, 'logo', b.logo)
                     order by b.active desc, lower(b.name))
      from public.client_brands b where b.client_id = p_client), '[]'::jsonb));
end $$;
revoke all on function public.client_brands_list(uuid) from public, anon;
grant execute on function public.client_brands_list(uuid) to authenticated;

create or replace function public.client_brand_logo(p_id uuid, p_logo text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  b public.client_brands;
  v_client text;
begin
  if me.id is null or not public.ops_granted('reports.whitelabel', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if coalesce(p_logo, '') not in ('partner', 'adspace') then return jsonb_build_object('error', 'bad-logo'); end if;
  select * into b from public.client_brands where id = p_id for update;
  if b.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if not public.client_seen(b.client_id, 'view') then return jsonb_build_object('error', 'denied'); end if;
  if b.logo = p_logo then return jsonb_build_object('ok', true); end if;
  select c.name into v_client from public.clients c where c.id = b.client_id;
  update public.client_brands set logo = p_logo, updated_at = now() where id = p_id;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'client.brand', v_client, 'White label brand ' || b.name || ' logo: ' ||
    case b.logo when 'adspace' then 'ADspace' else v_client end || ' → ' ||
    case p_logo when 'adspace' then 'ADspace' else v_client end);
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.client_brand_logo(uuid, text) from public, anon;
grant execute on function public.client_brand_logo(uuid, text) to authenticated;

create or replace function public.sm_report_snapshot(p_id uuid, p_final boolean default false)
returns jsonb
language plpgsql security definer stable set search_path = public as $$
declare
  r public.sm_reports;
  c public.clients;
begin
  if not public.allowed('reports', 'view') and not public.allowed('clients', 'view') then
    return jsonb_build_object('error', 'denied');
  end if;
  select * into r from public.sm_reports where id = p_id;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if not public.client_seen(r.client_id, 'view') then return jsonb_build_object('error', 'denied'); end if;
  -- Somebody who reads Clients but not Reports reads the finished report
  -- only: once it is confirmed, never while it is being prepared.
  if not public.allowed('reports', 'view') and r.status not in ('confirmed', 'published') then
    return jsonb_build_object('error', 'denied');
  end if;
  select * into c from public.clients where id = r.client_id;
  return jsonb_build_object(
    'report', jsonb_build_object(
      -- A white-label report names the brand it covers, with no client logo.
      'id', r.id, 'kind', r.kind, 'title', r.title, 'client_name', coalesce(r.brand_name, c.name),
      'client_logo_url', case when r.brand_name is null then c.logo_url end,
      'market', to_jsonb(c) ->> 'market', 'lang', r.lang,
      'period_start', r.period_start, 'period_end', r.period_end,
      'headline', r.headline, 'intro', r.intro, 'insights', r.insights, 'rank_metric', r.rank_metric,
      'first_month', r.first_month, 'ads_totals', r.ads_totals,
      'status', case when p_final then 'final' else r.status end,
      'version_no', r.version_no, 'generated_at', now(),
      'prepared_by_name', (select name from public.team_members where id = r.submitted_by),
      -- The white-label client's wide logo while it is still ticked and the
      -- report's brand takes it (2026-10-07); else ADspace's own mark.
      'partner', (select jsonb_build_object('name', l.name, 'logo', l.report_logo)
                    from public.clients l where l.id = r.label_client and l.white_label
                     and coalesce((select b.logo from public.client_brands b where b.id = r.brand_id), 'partner') = 'partner')),
    'platforms', coalesce((select jsonb_agg(to_jsonb(p) - 'created_at' order by p.position, p.created_at)
                  from public.sm_report_platforms p where p.report_id = r.id), '[]'::jsonb),
    'posts', coalesce((select jsonb_agg((to_jsonb(q) - 'created_at' - 'thumb_data') || jsonb_build_object('thumb_url', q.thumb_data)
                  order by q.posted_on nulls last, q.position, q.created_at)
                  from public.sm_report_posts q where q.report_id = r.id), '[]'::jsonb),
    'ads', coalesce((select jsonb_agg((to_jsonb(a) - 'created_at' - 'thumb_data') || jsonb_build_object('thumb_url', a.thumb_data)
                  order by a.position, a.created_at)
                  from public.sm_report_ads a where a.report_id = r.id), '[]'::jsonb));
end $$;
grant execute on function public.sm_report_snapshot(uuid, boolean) to authenticated;

-- END OF WHITE LABEL BRAND LOGO -----------------------------------------------

-- ===========================================================================
-- ADMIN PARTS — every act an admin alone could take is a granted part: an
-- admin holds it, any other group only once it is set in its Team panel.
-- 2026-10-07. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/sql.js compares the
-- two. Runs after WHITE LABEL BRAND LOGO.
--
-- WHAT CHANGED (the user, 2026-10-07: "keep to auto admin only but then
-- allow changes to add permissions for other user groups too. make it
-- controllable")
--   Each check below asked `allowed('admin')` (or `perf_is_admin()`, an
--   admin alone); each now asks `ops_granted(key, 'work')`, which answers
--   true for an admin and for a group whose access holds the key at Work.
--   No group is given any of them here.
--     ops.numbering      ops_next_task_no, ops_set_next_task_no
--     ops.override       ops_owner_may_move (move a task one does not own),
--                        ops_request_due_change (move a final date directly)
--     team.perfadmin     perf_is_admin(): revenue and profit, Performance
--                        settings, a month's record removed
--     team.settings      app_settings_set (Follow-up limits, Tax and terms,
--                        Due dates); app_settings_read's `admin` answers it
--     team.upgrade       maintenance_set
--     team.handbook      handbook_save, handbook_add_version,
--                        handbook_archive, handbook_delete, and the bucket's
--                        add and remove policies
--     team.invite        the invite-member edge function (asked there)
--     reports.transfer   sm_report_move
--     reports.ai         ai_draft_usage, ai_draft_set_limit
--   The AI limits an admin is given (`admin`, `report_admin`, `check_admin`)
--   stay an admin's: they are a role's allowance, not a permission.
--
-- ROLLBACK
--   Run each function's previous section again (MAINTENANCE MODE, APP
--   SETTINGS, HANDBOOK, …); the parts then grant nothing beyond an admin.
-- ===========================================================================

create or replace function public.perf_is_admin()
returns boolean
language plpgsql stable security definer set search_path = public as $$
begin
  return public.ops_granted('team.perfadmin', 'work');
end $$;
revoke all on function public.perf_is_admin() from public, anon, authenticated;

create or replace function public.ops_next_task_no()
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  lv   bigint;
  ic   boolean;
  nxt  bigint;
  top  bigint;
begin
  if not public.ops_granted('ops.numbering', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select last_value, is_called into lv, ic from public.ops_task_no_seq;
  nxt := case when ic then lv + 1 else lv end;
  select max(task_no) into top from public.ops_tasks;
  return jsonb_build_object('next', nxt, 'serial', public.ops_serial(nxt),
    'highest', top, 'highest_serial', case when top is null then null else public.ops_serial(top) end);
end $$;
grant execute on function public.ops_next_task_no() to authenticated;

create or replace function public.ops_set_next_task_no(p_next bigint)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m    public.team_members;
  top  bigint;
begin
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if not public.ops_granted('ops.numbering', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if p_next is null or p_next < 1 or p_next > 9999999 then
    return jsonb_build_object('error', 'bad-number');
  end if;
  select max(task_no) into top from public.ops_tasks;
  if top is not null and p_next <= top then
    return jsonb_build_object('error', 'number-taken', 'highest', public.ops_serial(top));
  end if;
  perform setval('public.ops_task_no_seq', p_next, false);
  insert into public.activity_log (actor, action, subject, detail)
  values (coalesce(m.name, m.email), 'ops.numbering', 'My Work',
          'Next task number set to ' || public.ops_serial(p_next));
  return public.ops_next_task_no();
end $$;
grant execute on function public.ops_set_next_task_no(bigint) to authenticated;

create or replace function public.ops_owner_may_move(p_task uuid)
returns boolean
language sql security definer stable set search_path = public as $$
  select public.ops_granted('ops.override', 'work')
      or not exists (select 1 from public.ops_task_assignees a
                      where a.task_id = p_task and a.responsibility = 'owner' and a.ended_at is null)
      or exists (select 1 from public.ops_task_assignees a
                  where a.task_id = p_task and a.responsibility = 'owner' and a.ended_at is null
                    and a.team_member_id = (public.ops_me()).id)
$$;
grant execute on function public.ops_owner_may_move(uuid) to authenticated;

create or replace function public.ops_request_due_change(
  p_task uuid, p_kind text, p_value timestamptz, p_reason text,
  p_note text default null, p_version integer default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m     public.team_members;
  t     public.ops_tasks;
  who   uuid;
  was   timestamptz;
  v_id  uuid;
  nm    text;
begin
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if not public.ops_may_see_task(p_task) then return jsonb_build_object('error', 'denied'); end if;
  if not public.allowed('ops', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if coalesce(p_reason, '') = '' then return jsonb_build_object('error', 'reason-required'); end if;
  if p_kind not in ('first_draft', 'final') then return jsonb_build_object('error', 'bad-kind'); end if;
  if p_value is null then return jsonb_build_object('error', 'no-date'); end if;

  select * into t from public.ops_tasks where id = p_task for update;
  if t.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if p_version is not null and p_version <> t.version then
    return jsonb_build_object('error', 'stale', 'task', public.ops_task_json(p_task));
  end if;

  /* Refused before an ask is raised as well as before a move is made: an ask
     nobody could approve without breaking the plan is one to turn away at the
     door, with the word the move itself would have used. */
  if not public.ops_due_order_ok(
       case when p_kind = 'first_draft' then p_value else t.current_first_draft_due_at end,
       case when p_kind = 'final'       then p_value else t.current_final_due_at end) then
    return jsonb_build_object('error', 'draft-not-before-final');
  end if;

  who := public.ops_due_decider(p_task, p_kind);
  /* Nobody to ask — the team's own first draft milestone, or a task whose
     creator is the person asking — so the move is theirs to make and the
     round would be a form with one name on both ends. */
  /* An admin moves any date directly: the round protects the person who set
     the date from somebody else, and an admin is the one who may overwrite
     anybody's. The move still files its event and keeps the original. */
  if who is null or who = m.id or public.ops_granted('ops.override', 'work') then
    return public.ops_change_due_date(p_task, p_kind, p_value, p_reason, p_note, p_version);
  end if;

  was := case when p_kind = 'final' then t.current_final_due_at
              else t.current_first_draft_due_at end;

  insert into public.ops_due_requests
    (task_id, kind, was_at, wants_at, reason, note, asked_by, decider_id)
  values (p_task, p_kind, was, p_value, p_reason, nullif(btrim(p_note), ''), m.id, who)
  on conflict (task_id, kind) where state = 'asked' do nothing
  returning id into v_id;

  /* The same press twice is the same ask. The open one is handed back so the
     page can say it is already with somebody. */
  if v_id is null then
    select id into v_id from public.ops_due_requests
      where task_id = p_task and kind = p_kind and state = 'asked';
    return jsonb_build_object('ok', true, 'repeat', true, 'request', v_id,
                              'task', public.ops_task_json(p_task));
  end if;

  select name into nm from public.team_members where id = m.id;
  perform public.ops_notify(who, p_task, 'due_requested',
    'Extension requested',
    coalesce(nm, 'Somebody') || ' asked to move ' ||
      case when p_kind = 'final' then 'the due date' else 'the first draft date' end ||
      ' to ' || to_char(timezone('Asia/Kuala_Lumpur', p_value), 'DD Mon YYYY'),
    'due_req:' || v_id::text);

  perform public.ops_log(p_task, 'due_requested',
    jsonb_build_object('kind', p_kind, 'value', was),
    jsonb_build_object('kind', p_kind, 'value', p_value),
    jsonb_build_object('reason', p_reason, 'note', p_note, 'request', v_id));

  return jsonb_build_object('ok', true, 'request', v_id, 'asked', true,
                            'task', public.ops_task_json(p_task));
end $$;
grant execute on function public.ops_request_due_change(uuid, text, timestamptz, text, text, integer) to authenticated;

create or replace function public.app_settings_set(p_from date, p_values jsonb)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me public.team_members; v_k text; v_v numeric; v_was numeric; v_name text; v_unit text;
  v_today date := (now() at time zone 'Asia/Kuala_Lumpur')::date;
  v_keys constant text[] := array['lead_followup_hours', 'proposal_followup_days', 'sst_pct',
    'term_1_3', 'term_4_5', 'term_6_11', 'term_12_23', 'term_24', 'report_due_days', 'revision_due_days'];
  v_moved text[] := '{}';
begin
  if not public.ops_granted('team.settings', 'work') then return jsonb_build_object('error', 'denied'); end if;
  v_me := public.ops_me();
  if p_from is null or p_from < v_today then return jsonb_build_object('error', 'past', 'today', v_today); end if;
  if jsonb_typeof(p_values) is distinct from 'object' then return jsonb_build_object('error', 'bad-value'); end if;
  for v_k in select jsonb_object_keys(p_values) loop
    if not (v_k = any(v_keys)) or jsonb_typeof(p_values -> v_k) <> 'number' then
      return jsonb_build_object('error', 'bad-value', 'key', v_k);
    end if;
    v_v := (p_values ->> v_k)::numeric;
    if round(v_v, 2) <> v_v
       or (v_k = 'lead_followup_hours' and (v_v < 1 or v_v > 720 or v_v <> trunc(v_v)))
       or (v_k = 'proposal_followup_days' and (v_v < 1 or v_v > 365 or v_v <> trunc(v_v)))
       or (v_k = 'report_due_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'revision_due_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'sst_pct' and (v_v < 0 or v_v > 100))
       or (v_k like 'term_%' and (v_v < -100 or v_v > 100)) then
      return jsonb_build_object('error', 'bad-value', 'key', v_k);
    end if;
  end loop;
  for v_k in select jsonb_object_keys(p_values) loop
    v_v := (p_values ->> v_k)::numeric;
    v_was := public.app_setting(v_k, p_from);
    if v_was is distinct from v_v then
      insert into public.app_settings (key, from_date, value, set_by, set_at)
      values (v_k, p_from, v_v, v_me.id, now())
      on conflict (key, from_date) do update set value = excluded.value, set_by = excluded.set_by, set_at = now();
      v_name := case v_k when 'lead_followup_hours' then 'A lead waits' when 'proposal_followup_days' then 'A proposal waits'
        when 'sst_pct' then 'SST' when 'term_1_3' then '1 to 3 months' when 'term_4_5' then '4 and 5 months'
        when 'term_6_11' then '6 to 11 months' when 'term_12_23' then '12 to 23 months' when 'term_24' then '24 months and more'
        when 'revision_due_days' then 'Revision due' else 'Report due' end;
      v_unit := case when v_k = 'lead_followup_hours' then ' hours' when v_k in ('proposal_followup_days', 'report_due_days', 'revision_due_days') then ' days'
        else '%' end;
      insert into public.activity_log (actor, action, subject, detail)
      values (coalesce(v_me.name, 'admin'), 'team.changed', 'Settings',
              v_name || ': ' || trim(to_char(v_was, 'FM999999990.99'), '.') || v_unit || ' → ' ||
              trim(to_char(v_v, 'FM999999990.99'), '.') || v_unit || ' · from ' || public.register_day(p_from));
      v_moved := v_moved || v_k;
    end if;
  end loop;
  return public.app_settings_read() || jsonb_build_object('changed', to_jsonb(v_moved));
end $$;
revoke all on function public.app_settings_set(date, jsonb) from public, anon;

create or replace function public.app_settings_read()
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_team boolean := public.is_team();
begin
  return jsonb_build_object(
    'today', (now() at time zone 'Asia/Kuala_Lumpur')::date,
    'admin', v_team and public.ops_granted('team.settings', 'work'),
    'settings', coalesce((select jsonb_agg(jsonb_build_object('key', s.key, 'from', s.from_date, 'value', s.value,
                   'by', case when v_team then (select t.name from public.team_members t where t.id = s.set_by) end,
                   'at', case when v_team then s.set_at end)
                 order by s.key, s.from_date) from public.app_settings s), '[]'::jsonb));
end $$;

create or replace function public.maintenance_set(p_on boolean, p_note text default null,
                                                  p_starts timestamptz default null,
                                                  p_ends timestamptz default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_was boolean;
  v_who text;
  v_on boolean := coalesce(p_on, false);
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
  v_when text := '';
begin
  if not public.ops_granted('team.upgrade', 'work') then
    return jsonb_build_object('error', 'denied');
  end if;
  if v_on and p_ends is not null and p_ends <= greatest(coalesce(p_starts, now()), now()) then
    return jsonb_build_object('error', 'bad-window');
  end if;
  select coalesce(t.name, t.email) into v_who from public.team_members t
   where lower(t.email) = lower(auth.jwt() ->> 'email') and t.active limit 1;
  select f.on_now and (f.ends_at is null or f.ends_at > now()) into v_was
    from public.app_flags f where f.key = 'maintenance';
  insert into public.app_flags (key, on_now, note, starts_at, ends_at, set_by, set_at)
  values ('maintenance', v_on, case when v_on then left(v_note, 300) end,
          case when v_on and p_starts > now() then p_starts end,
          case when v_on then p_ends end, v_who, now())
  on conflict (key) do update
    set on_now = excluded.on_now, note = excluded.note, starts_at = excluded.starts_at,
        ends_at = excluded.ends_at, set_by = excluded.set_by, set_at = excluded.set_at;
  if v_on and p_starts > now() then
    v_when := ' · from ' || regexp_replace(to_char(p_starts at time zone 'Asia/Kuala_Lumpur', 'FMDD Mon YYYY HH24:MI'), '\mSep\M', 'Sept');
  end if;
  if v_on and p_ends is not null then
    v_when := v_when || ' · until ' || regexp_replace(to_char(p_ends at time zone 'Asia/Kuala_Lumpur', 'FMDD Mon YYYY HH24:MI'), '\mSep\M', 'Sept');
  end if;
  insert into public.activity_log (actor, action, subject, detail)
  values (coalesce(v_who, 'admin'), 'team.changed', 'Portal',
          'Upgrade mode: ' || case when coalesce(v_was, false) then 'on' else 'off' end || ' → ' ||
          case when v_on then 'on' else 'off' end || v_when ||
          case when v_on then coalesce(' · ' || left(v_note, 300), '') else '' end);
  return public.maintenance_state();
end $$;
revoke all on function public.maintenance_set(boolean, text, timestamptz, timestamptz) from public, anon;
grant execute on function public.maintenance_set(boolean, text, timestamptz, timestamptz) to authenticated;

create or replace function public.handbook_save(p_id uuid, p_title text, p_category text, p_summary text, p_link text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  who text := lower(coalesce(auth.jwt() ->> 'email', ''));
  v_title text := btrim(coalesce(p_title, ''));
  v_link text := nullif(btrim(coalesce(p_link, '')), '');
  v_changed text;
  d public.handbook_docs;
begin
  if not public.ops_granted('team.handbook', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if v_title = '' then return jsonb_build_object('error', 'no-title'); end if;
  if coalesce(p_category, '') not in ('handbook', 'sop', 'policy', 'template', 'other') then
    return jsonb_build_object('error', 'bad-category');
  end if;
  if v_link is not null and v_link !~ '^https://' then return jsonb_build_object('error', 'bad-link'); end if;
  select * into d from public.handbook_docs h where h.id = p_id;
  if d.id is null then
    insert into public.handbook_docs (id, title, category, summary, link_url, created_by)
    values (coalesce(p_id, gen_random_uuid()), v_title, p_category, nullif(btrim(coalesce(p_summary, '')), ''), v_link, who)
    returning * into d;
    insert into public.activity_log (actor, action, subject, detail)
    values (who, 'handbook.added', d.title, case d.category when 'handbook' then 'Employee Handbook'
      when 'sop' then 'SOPs' when 'policy' then 'Policies' when 'template' then 'Templates and forms' else 'Other' end);
  else
    v_changed := concat_ws(', ',
      case when d.title is distinct from v_title then 'title' end,
      case when d.category is distinct from p_category then 'category' end,
      case when d.summary is distinct from nullif(btrim(coalesce(p_summary, '')), '') then 'summary' end,
      case when d.link_url is distinct from v_link then 'link' end);
    if v_changed = '' then return jsonb_build_object('ok', true, 'id', d.id, 'changed', false); end if;
    update public.handbook_docs h
       set title = v_title, category = p_category,
           summary = nullif(btrim(coalesce(p_summary, '')), ''), link_url = v_link, updated_at = now()
     where h.id = p_id returning * into d;
    insert into public.activity_log (actor, action, subject, detail)
    values (who, 'handbook.edited', d.title, upper(left(v_changed, 1)) || substr(v_changed, 2));
  end if;
  return jsonb_build_object('ok', true, 'id', d.id);
end $$;


create or replace function public.handbook_add_version(p_doc uuid, p_path text, p_name text, p_size bigint, p_mime text, p_note text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  who text := lower(coalesce(auth.jwt() ->> 'email', ''));
  d public.handbook_docs;
  n integer;
begin
  if not public.ops_granted('team.handbook', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into d from public.handbook_docs h where h.id = p_doc for update;
  if d.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if coalesce(p_path, '') = '' or position(p_doc::text || '/' in p_path) <> 1 then
    return jsonb_build_object('error', 'bad-path');
  end if;
  if btrim(coalesce(p_name, '')) = '' then return jsonb_build_object('error', 'no-file'); end if;
  select coalesce(max(v.version_no), 0) + 1 into n from public.handbook_versions v where v.doc_id = p_doc;
  insert into public.handbook_versions (doc_id, version_no, file_path, file_name, file_size, mime, note, created_by)
  values (p_doc, n, p_path, btrim(p_name), p_size, p_mime, nullif(btrim(coalesce(p_note, '')), ''), who);
  update public.handbook_docs h set current_version = n, updated_at = now() where h.id = p_doc;
  insert into public.activity_log (actor, action, subject, detail)
  values (who, 'handbook.version', d.title,
          concat_ws(' · ', 'Version ' || n, btrim(p_name), nullif(btrim(coalesce(p_note, '')), '')));
  return jsonb_build_object('ok', true, 'version', n);
end $$;


create or replace function public.handbook_archive(p_id uuid, p_on boolean)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  who text := lower(coalesce(auth.jwt() ->> 'email', ''));
  d public.handbook_docs;
begin
  if not public.ops_granted('team.handbook', 'work') then return jsonb_build_object('error', 'denied'); end if;
  update public.handbook_docs h
     set archived_at = case when p_on then coalesce(h.archived_at, now()) end
   where h.id = p_id returning * into d;
  if d.id is null then return jsonb_build_object('error', 'not-found'); end if;
  insert into public.activity_log (actor, action, subject, detail)
  values (who, case when p_on then 'handbook.archived' else 'handbook.restored' end, d.title, null);
  return jsonb_build_object('ok', true);
end $$;


create or replace function public.handbook_delete(p_id uuid, p_title text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  who text := lower(coalesce(auth.jwt() ->> 'email', ''));
  d public.handbook_docs;
  v_paths jsonb;
begin
  if not public.ops_granted('team.handbook', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into d from public.handbook_docs h where h.id = p_id;
  if d.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if lower(btrim(coalesce(p_title, ''))) <> lower(btrim(d.title)) then
    return jsonb_build_object('error', 'mismatch');
  end if;
  select coalesce(jsonb_agg(v.file_path order by v.version_no), '[]'::jsonb) into v_paths
    from public.handbook_versions v where v.doc_id = p_id;
  delete from public.handbook_docs h where h.id = p_id;
  insert into public.activity_log (actor, action, subject, detail)
  values (who, 'handbook.deleted', d.title,
          jsonb_array_length(v_paths) || case when jsonb_array_length(v_paths) = 1 then ' version' else ' versions' end);
  return jsonb_build_object('ok', true, 'paths', v_paths);
end $$;


create or replace function public.sm_report_move(p_id uuid, p_client uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.sm_reports;
  c public.clients;
  was text;
begin
  if me.id is null or not public.ops_granted('reports.transfer', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_id for update;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if r.status <> 'draft' then return jsonb_build_object('error', 'not-draft', 'status', r.status); end if;
  if r.brand_id is not null then return jsonb_build_object('error', 'white-label'); end if;
  select * into c from public.clients where id = p_client;
  if c.id is null or c.stage <> 'active' then return jsonb_build_object('error', 'not-active'); end if;
  if c.id = r.client_id then return jsonb_build_object('ok', true, 'client_id', c.id); end if;
  if exists (select 1 from public.sm_reports x
              where x.client_id = c.id and x.kind = r.kind and x.id <> r.id and x.brand_id is null
                and x.period_start <= r.period_end and x.period_end >= r.period_start) then
    return jsonb_build_object('error', 'exists');
  end if;
  select k.name into was from public.clients k where k.id = r.client_id;
  perform public.sm_report_log(p_id, 'report.saved', 'Client: ' || coalesce(was, 'not set') || ' → ' || c.name);
  perform set_config('adspace.sm_fn', 'on', true);
  update public.sm_reports set client_id = c.id where id = p_id;
  perform set_config('adspace.sm_fn', 'off', true);
  update public.ai_drafts set client_id = c.id where report_id = p_id;
  perform public.sm_report_log(p_id, 'report.saved', 'Client: ' || coalesce(was, 'not set') || ' → ' || c.name);
  return jsonb_build_object('ok', true, 'client_id', c.id);
end $$;
revoke all on function public.sm_report_move(uuid, uuid) from public, anon, authenticated;
grant execute on function public.sm_report_move(uuid, uuid) to authenticated;

create or replace function public.ai_draft_usage()
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_day timestamptz := public.ai_draft_day();
  v_month timestamptz := now() - interval '30 days';
begin
  if not public.ops_granted('reports.ai', 'work') then return jsonb_build_object('error', 'denied'); end if;
  return jsonb_build_object(
    'person', public.ai_draft_limit('person', 10),
    'admin', public.ai_draft_limit('admin', 20),
    'report', public.ai_draft_limit('report', 1),
    'report_admin', public.ai_draft_limit('report_admin', 5),
    'check', public.ai_draft_limit('check', 1),
    'check_admin', public.ai_draft_limit('check_admin', 5),
    'resets_at', v_day + interval '1 day',
    'people', coalesce((select jsonb_agg(s.x order by s.x ->> 'name') from (
      select jsonb_build_object(
        'id', t.id, 'name', t.name, 'code', t.staff_code, 'group', g.name, 'group_slug', t.role,
        'admin', coalesce(t.is_admin, false) or t.role = 'admin',
        'day', (select count(*) from public.ai_drafts d where d.team_member_id = t.id and d.created_at >= v_day and d.outcome <> 'failed'),
        'month', (select count(*) from public.ai_drafts d where d.team_member_id = t.id and d.created_at > v_month and d.outcome <> 'failed'),
        'limit', (select l.daily from public.ai_draft_limits l where l.scope = t.id::text),
        'cap', public.ai_day_cap(t)) as x
        from public.team_members t
        left join public.team_roles g on g.slug = t.role
       where t.active
         and (coalesce(t.is_admin, false) or t.role = 'admin'
              or public.level_rank(coalesce(t.access ->> 'reports', 'none')) >= public.level_rank('work')
              or exists (select 1 from public.ai_drafts d where d.team_member_id = t.id and d.created_at > v_month))
    ) s), '[]'::jsonb));
end $$;
revoke all on function public.ai_draft_usage() from public, anon, authenticated;
grant execute on function public.ai_draft_usage() to authenticated;

create or replace function public.ai_draft_set_limit(p_scope text, p_daily integer)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_who text;
  v_name text;
  v_was integer;
  v_def integer;
  v_unit text := ' a day';
  v_scope text := btrim(coalesce(p_scope, ''));
  t public.team_members;
begin
  if not public.ops_granted('reports.ai', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if p_daily is not null and (p_daily < 0 or p_daily > 500) then
    return jsonb_build_object('error', 'bad-limit');
  end if;
  if v_scope = 'person' then
    v_name := 'Each colleague'; v_def := 10;
  elsif v_scope = 'admin' then
    v_name := 'Each admin'; v_def := 20;
  elsif v_scope = 'report' then
    v_name := 'Drafts per report, each colleague'; v_def := 1;
  elsif v_scope = 'report_admin' then
    v_name := 'Drafts per report, each admin'; v_def := 5;
  elsif v_scope = 'check' then
    v_name := 'Figures checks per report, each colleague'; v_def := 1;
  elsif v_scope = 'check_admin' then
    v_name := 'Figures checks per report, each admin'; v_def := 5;
  elsif v_scope = 'team' then
    return jsonb_build_object('error', 'bad-scope');
  else
    select * into t from public.team_members x where x.id::text = v_scope;
    if t.id is null then return jsonb_build_object('error', 'not-found'); end if;
    v_name := t.name;
    v_def := case when coalesce(t.is_admin, false) or t.role = 'admin'
                  then public.ai_draft_limit('admin', 20) else public.ai_draft_limit('person', 10) end;
  end if;
  select l.daily into v_was from public.ai_draft_limits l where l.scope = v_scope;
  if v_was is not distinct from p_daily then return jsonb_build_object('ok', true, 'same', true); end if;
  select coalesce(x.name, x.email) into v_who from public.team_members x
   where lower(x.email) = lower(auth.jwt() ->> 'email') and x.active limit 1;
  insert into public.ai_draft_limits (scope, daily, set_by, set_at)
  values (v_scope, p_daily, v_who, now())
  on conflict (scope) do update set daily = excluded.daily, set_by = excluded.set_by, set_at = excluded.set_at;
  insert into public.activity_log (actor, action, subject, detail)
  values (coalesce(v_who, 'admin'), 'team.changed', 'AI',
          v_name || ': ' ||
          case when v_was is null then 'standard, ' || v_def || v_unit when v_was = 0 then 'stopped' else v_was || v_unit end ||
          ' → ' ||
          case when p_daily is null then 'standard, ' || v_def || v_unit when p_daily = 0 then 'stopped' else p_daily || v_unit end);
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.ai_draft_set_limit(text, integer) from public, anon, authenticated;
grant execute on function public.ai_draft_set_limit(text, integer) to authenticated;

do $$
begin
  if not exists (select 1 from pg_namespace where nspname = 'storage') then return; end if;
  if exists (select 1 from pg_policies where schemaname = 'storage' and tablename = 'objects'
              and policyname = 'handbook_files_add') then
    execute $p$alter policy handbook_files_add on storage.objects
      with check (bucket_id = 'handbook' and public.ops_granted('team.handbook', 'work'))$p$;
  end if;
  if exists (select 1 from pg_policies where schemaname = 'storage' and tablename = 'objects'
              and policyname = 'handbook_files_remove') then
    execute $p$alter policy handbook_files_remove on storage.objects
      using (bucket_id = 'handbook' and public.ops_granted('team.handbook', 'work'))$p$;
  end if;
end $$;

-- END OF ADMIN PARTS ----------------------------------------------------------

-- ===========================================================================
-- ANNOUNCEMENTS — one line at the top of the portal, for the team (the
-- console) or for clients (every client page), each its own, one at a time.
-- 2026-10-07. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/smsql.js compares the
-- two. Runs after ADMIN PARTS.
--
-- WHAT CHANGED (the user, 2026-10-06: "announcement in the portal ... team
-- and clients. able to choose separately. one at a time.")
--   1. `announcements` (RLS on, no policy, no grant): the audience (`team`
--      or `clients`), the tone (`info` or `important`), the words in English
--      and, optionally, 中文 (300 characters each), an optional https link,
--      an optional start and end, and `ended_at` once stopped or replaced.
--   2. `announcement_now(p_audience)`: the one live for that audience (its
--      start passed or none, its end ahead or none, not ended), newest first.
--      Clients' is read by anyone (every client page, signed in or by link);
--      the team's by the team alone.
--   3. Team: Announcements (`team.announce`, a granted part: an admin's by
--      itself, any other group's once set) writes:
--      `announcement_save(p_id, p_audience, p_tone, p_body_en, p_body_zh,
--      p_link, p_starts, p_ends)` (bad-audience, bad-tone, bad-text,
--      bad-link, bad-window), which ends every other announcement of that
--      audience (one at a time); `announcement_end(p_id, p_on)`, Stop (false)
--      and Restore (true, while its end is ahead; it ends the others again);
--      `announcements_list()`, the latest 20 of each audience. Every write is
--      filed `team.changed` under subject Announcements.
--
-- ROLLBACK
--   Nothing reads the table but these functions; leaving them unused hides
--   every bar.
-- ===========================================================================

create table if not exists public.announcements (
  id         uuid primary key default gen_random_uuid(),
  audience   text not null,
  tone       text not null default 'info',
  body_en    text not null,
  body_zh    text,
  link       text,
  starts_at  timestamptz,
  ends_at    timestamptz,
  ended_at   timestamptz,
  created_by text,
  created_at timestamptz not null default now(),
  updated_by text,
  updated_at timestamptz not null default now()
);
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'announcements_audience') then
    alter table public.announcements add constraint announcements_audience check (audience in ('team', 'clients'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'announcements_tone') then
    alter table public.announcements add constraint announcements_tone check (tone in ('info', 'important'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'announcements_text') then
    alter table public.announcements add constraint announcements_text
      check (char_length(btrim(body_en)) between 1 and 300 and (body_zh is null or char_length(body_zh) <= 300));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'announcements_link') then
    alter table public.announcements add constraint announcements_link check (link is null or link ~ '^https://[^\s]+$');
  end if;
end $$;
create index if not exists announcements_live_idx on public.announcements (audience, updated_at desc) where ended_at is null;
alter table public.announcements enable row level security;
revoke all on table public.announcements from public, anon, authenticated;

create or replace function public.announcement_json(a public.announcements)
returns jsonb
language sql stable set search_path = public as $$
  select jsonb_build_object('id', a.id, 'audience', a.audience, 'tone', a.tone, 'body_en', a.body_en,
    'body_zh', a.body_zh, 'link', a.link, 'starts_at', a.starts_at, 'ends_at', a.ends_at,
    'ended_at', a.ended_at, 'created_by', a.created_by, 'created_at', a.created_at,
    'updated_by', a.updated_by, 'updated_at', a.updated_at)
$$;
revoke all on function public.announcement_json(public.announcements) from public, anon, authenticated;

create or replace function public.announcement_now(p_audience text)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare a public.announcements;
begin
  if p_audience not in ('team', 'clients') then return null; end if;
  if p_audience = 'team' and not public.is_team() then return null; end if;
  select * into a from public.announcements x
   where x.audience = p_audience and x.ended_at is null
     and (x.starts_at is null or x.starts_at <= now())
     and (x.ends_at is null or x.ends_at > now())
   order by x.updated_at desc limit 1;
  if a.id is null then return null; end if;
  return public.announcement_json(a) - 'created_by' - 'updated_by' - 'created_at' - 'ended_at';
end $$;
grant execute on function public.announcement_now(text) to anon, authenticated;

create or replace function public.announcements_list()
returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.ops_granted('team.announce', 'work') then return jsonb_build_object('error', 'denied'); end if;
  return jsonb_build_object('now', now(), 'items', coalesce((
    select jsonb_agg(public.announcement_json(x) order by x.updated_at desc)
      from public.announcements x
     where (select count(*) from public.announcements z
             where z.audience = x.audience and z.updated_at > x.updated_at) < 20), '[]'::jsonb));
end $$;
revoke all on function public.announcements_list() from public, anon;
grant execute on function public.announcements_list() to authenticated;

/* "Team announcement: … · Important · from … · until …", Malaysia time. */
create or replace function public.announcement_said(a public.announcements)
returns text
language sql stable set search_path = public as $$
  select case a.audience when 'team' then 'Team' else 'Clients' end || ' announcement: ' || a.body_en
      || case when a.tone = 'important' then ' · Important' else '' end
      || case when a.starts_at is not null
              then ' · from ' || to_char(a.starts_at at time zone 'Asia/Kuala_Lumpur', 'FMDD Mon YYYY HH24:MI') else '' end
      || case when a.ends_at is not null
              then ' · until ' || to_char(a.ends_at at time zone 'Asia/Kuala_Lumpur', 'FMDD Mon YYYY HH24:MI') else '' end
$$;
revoke all on function public.announcement_said(public.announcements) from public, anon, authenticated;

create or replace function public.announcement_save(p_id uuid, p_audience text, p_tone text, p_body_en text,
                                                    p_body_zh text, p_link text, p_starts timestamptz,
                                                    p_ends timestamptz)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  v_en text := btrim(coalesce(p_body_en, ''));
  v_zh text := nullif(btrim(coalesce(p_body_zh, '')), '');
  v_link text := nullif(btrim(coalesce(p_link, '')), '');
  v_tone text := coalesce(nullif(p_tone, ''), 'info');
  a public.announcements;
  v_was text;
  v_gone int;
begin
  if me.id is null or not public.ops_granted('team.announce', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if p_audience is null or p_audience not in ('team', 'clients') then return jsonb_build_object('error', 'bad-audience'); end if;
  if v_tone not in ('info', 'important') then return jsonb_build_object('error', 'bad-tone'); end if;
  if char_length(v_en) < 1 or char_length(v_en) > 300 or char_length(coalesce(v_zh, '')) > 300 then
    return jsonb_build_object('error', 'bad-text');
  end if;
  if v_link is not null and v_link !~ '^https://[^\s]+$' then return jsonb_build_object('error', 'bad-link'); end if;
  if p_ends is not null and p_ends <= greatest(coalesce(p_starts, now()), now()) then
    return jsonb_build_object('error', 'bad-window');
  end if;
  if p_id is not null then
    select * into a from public.announcements x where x.id = p_id for update;
    if a.id is null then return jsonb_build_object('error', 'not-found'); end if;
    if a.audience <> p_audience then return jsonb_build_object('error', 'bad-audience'); end if;
    v_was := public.announcement_said(a);
    update public.announcements x
       set tone = v_tone, body_en = v_en, body_zh = v_zh, link = v_link, starts_at = p_starts,
           ends_at = p_ends, ended_at = null, updated_by = me.name, updated_at = now()
     where x.id = p_id returning * into a;
  else
    insert into public.announcements (audience, tone, body_en, body_zh, link, starts_at, ends_at, created_by, updated_by)
    values (p_audience, v_tone, v_en, v_zh, v_link, p_starts, p_ends, me.name, me.name)
    returning * into a;
  end if;
  /* One at a time: every other announcement for the audience ends here. */
  update public.announcements x set ended_at = now()
   where x.audience = a.audience and x.id <> a.id and x.ended_at is null;
  get diagnostics v_gone = row_count;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'team.changed', 'Announcements',
    case when v_was is null then public.announcement_said(a)
         else v_was || ' → ' || public.announcement_said(a) end
    || case when v_gone > 0 then ' · the one before stopped' else '' end);
  return jsonb_build_object('ok', true, 'item', public.announcement_json(a));
end $$;
revoke all on function public.announcement_save(uuid, text, text, text, text, text, timestamptz, timestamptz) from public, anon;
grant execute on function public.announcement_save(uuid, text, text, text, text, text, timestamptz, timestamptz) to authenticated;

create or replace function public.announcement_end(p_id uuid, p_on boolean)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  a public.announcements;
begin
  if me.id is null or not public.ops_granted('team.announce', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into a from public.announcements x where x.id = p_id for update;
  if a.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if coalesce(p_on, false) then
    if a.ended_at is null then return jsonb_build_object('ok', true); end if;
    if a.ends_at is not null and a.ends_at <= now() then return jsonb_build_object('error', 'over'); end if;
    update public.announcements x set ended_at = now()
     where x.audience = a.audience and x.id <> a.id and x.ended_at is null;
    update public.announcements x set ended_at = null, updated_by = me.name, updated_at = now()
     where x.id = a.id returning * into a;
    insert into public.activity_log (actor, action, subject, detail)
    values (me.name, 'team.changed', 'Announcements', 'Restored · ' || public.announcement_said(a));
  else
    if a.ended_at is not null then return jsonb_build_object('ok', true); end if;
    update public.announcements x set ended_at = now() where x.id = a.id returning * into a;
    insert into public.activity_log (actor, action, subject, detail)
    values (me.name, 'team.changed', 'Announcements', 'Stopped · ' || public.announcement_said(a));
  end if;
  return jsonb_build_object('ok', true, 'item', public.announcement_json(a));
end $$;
revoke all on function public.announcement_end(uuid, boolean) from public, anon;
grant execute on function public.announcement_end(uuid, boolean) to authenticated;

-- END OF ANNOUNCEMENTS --------------------------------------------------------

-- ===========================================================================
-- REPORT FILES KEPT — each published version of a report keeps the PDF it
-- went out as, so a later change to how reports are drawn never changes a
-- report a client was sent, and every earlier version can be fetched again.
-- 2026-10-07. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/smsql.js compares the
-- two. Runs after SOCIAL MEDIA REPORTS and CLIENT SCOPE.
--
-- WHAT CHANGED (the user, 2026-10-06: "if our client received version at
-- (2026/10/06) but in the future maybe 2026/12/12 there is a new version, i
-- no longer can fetch back the 2026/10/06 version")
--   1. `sm_report_versions.file_key`, `file_at`, `file_by`: the PDF drawn
--      from the version once it is published, stored in the bucket under
--      `private/{client}/`, which is never served without a five-minute
--      signature. A file stands for the publish it was drawn after
--      (`file_at` not before `published_at`): a version taken off the portal
--      and published again keeps the next file drawn instead.
--   2. `sm_report_keep_file(p_version, p_key)`: Reports at Work, on a client
--      the colleague sees; the key must sit under the report's own client; a
--      version whose file stands answers `kept` with its own key and keeps
--      it.
--   3. `sm_report_file_key(p_version)`: what sign-download asks, as the
--      caller. A colleague at Reports View, or Clients View, on a client they
--      see: any version. A client's portal contact: only the version the
--      portal shows. Anybody else is answered `not-found`.
--   4. `portal_report` and `sm_report_file` say whether the version's file
--      stands (`kept`); `sm_report_file` also names the version.
--
-- ROLLBACK
--   Revoke execute on sm_report_keep_file(uuid, text) and
--   sm_report_file_key(uuid) from authenticated, then run portal_report from
--   SOCIAL MEDIA REPORTS and sm_report_file from CLIENT SCOPE again; the
--   columns may stay unused.
-- ===========================================================================

alter table public.sm_report_versions add column if not exists file_key text;
alter table public.sm_report_versions add column if not exists file_at timestamptz;
alter table public.sm_report_versions add column if not exists file_by text;

create or replace function public.sm_report_keep_file(p_version uuid, p_key text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  v public.sm_report_versions;
  v_client uuid;
begin
  if me.id is null or not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into v from public.sm_report_versions where id = p_version for update;
  if v.id is null then return jsonb_build_object('error', 'not-found'); end if;
  select r.client_id into v_client from public.sm_reports r where r.id = v.report_id;
  if v_client is null or not public.client_seen(v_client, 'view') then return jsonb_build_object('error', 'not-found'); end if;
  if v.file_key is not null and v.file_at >= v.published_at then
    return jsonb_build_object('ok', true, 'kept', true, 'key', v.file_key);
  end if;
  if coalesce(p_key, '') !~ ('^private/' || v_client::text || '/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.pdf$') then
    return jsonb_build_object('error', 'bad-key');
  end if;
  update public.sm_report_versions set file_key = p_key, file_at = now(), file_by = me.name where id = v.id;
  return jsonb_build_object('ok', true, 'key', p_key);
end $$;
revoke all on function public.sm_report_keep_file(uuid, text) from public, anon;
grant execute on function public.sm_report_keep_file(uuid, text) to authenticated;

create or replace function public.sm_report_file_key(p_version uuid)
returns jsonb
language plpgsql security definer stable set search_path = public as $$
declare
  v public.sm_report_versions;
  v_client uuid;
begin
  if auth.jwt() ->> 'email' is null then return jsonb_build_object('error', 'not-signed-in'); end if;
  select * into v from public.sm_report_versions where id = p_version;
  if v.id is null then return jsonb_build_object('error', 'not-found'); end if;
  select r.client_id into v_client from public.sm_reports r where r.id = v.report_id;
  if v_client is null then return jsonb_build_object('error', 'not-found'); end if;
  if public.is_team() then
    if not (public.allowed('reports', 'view') or public.allowed('clients', 'view'))
       or not public.client_seen(v_client, 'view') then
      return jsonb_build_object('error', 'not-found');
    end if;
  elsif v_client not in (select public.portal_clients())
     or v.withdrawn_at is not null
     or exists (select 1 from public.sm_report_versions x where x.report_id = v.report_id
                 and x.withdrawn_at is null and x.version_no > v.version_no) then
    return jsonb_build_object('error', 'not-found');
  end if;
  if v.file_key is null or v.file_at < v.published_at then return jsonb_build_object('error', 'not-kept'); end if;
  return jsonb_build_object('key', v.file_key);
end $$;
revoke all on function public.sm_report_file_key(uuid) from public, anon;
grant execute on function public.sm_report_file_key(uuid) to authenticated;

create or replace function public.portal_report(p_version uuid)
returns jsonb
language plpgsql security definer stable set search_path = public as $$
declare
  v public.sm_report_versions;
  cid uuid;
begin
  if auth.jwt() ->> 'email' is null then return jsonb_build_object('error', 'not-signed-in'); end if;
  select * into v from public.sm_report_versions where id = p_version and withdrawn_at is null;
  if v.id is null then return jsonb_build_object('error', 'not-found'); end if;
  select client_id into cid from public.sm_reports where id = v.report_id;
  if cid is null or cid not in (select public.portal_clients()) then return jsonb_build_object('error', 'not-found'); end if;
  if exists (select 1 from public.sm_report_versions x where x.report_id = v.report_id
              and x.withdrawn_at is null and x.version_no > v.version_no) then
    return jsonb_build_object('error', 'not-found');
  end if;
  return jsonb_build_object('snapshot', v.snapshot,
    'kept', v.file_key is not null and v.file_at >= v.published_at);
end $$;
revoke all on function public.portal_report(uuid) from public, anon;
grant execute on function public.portal_report(uuid) to authenticated;

create or replace function public.sm_report_file(p_id uuid)
returns jsonb
language plpgsql security definer stable set search_path = public as $$
declare
  r public.sm_reports;
  v public.sm_report_versions;
begin
  if not public.allowed('clients', 'view') and not public.allowed('reports', 'view') then
    return jsonb_build_object('error', 'denied');
  end if;
  select * into r from public.sm_reports where id = p_id;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if not public.client_seen(r.client_id, 'view') then return jsonb_build_object('error', 'denied'); end if;
  select * into v from public.sm_report_versions x
   where x.report_id = p_id and x.withdrawn_at is null order by x.version_no desc limit 1;
  if v.id is not null then
    return jsonb_build_object('snapshot', v.snapshot, 'version_id', v.id,
      'kept', v.file_key is not null and v.file_at >= v.published_at);
  end if;
  if r.status <> 'confirmed' then return jsonb_build_object('error', 'not-finished'); end if;
  return jsonb_build_object('snapshot', public.sm_report_snapshot(p_id, false));
end $$;
grant execute on function public.sm_report_file(uuid) to authenticated;

-- END OF REPORT FILES KEPT ----------------------------------------------------

-- ===========================================================================
-- DOCUMENT TYPES — the team adds and edits its own kinds of letter, each
-- asking on Issue for the fields its wording names.
-- 2026-10-07. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/sql.js compares the
-- two.
--
-- WHAT CHANGED
--   1. `doc_types.fields`: how each field the wording names in braces is
--      asked for on Issue ({intern name} as text, {from} as a date, {scope}
--      as a paragraph), a map from the field's name to `text`, `date` or
--      `long`. A field the map does not name is asked as text. The fields
--      themselves are whatever the wording names; {first name}, {role} and
--      {client} fill themselves and are never asked.
--   2. `doc_type_save(...)` adds or edits a type: its group (fixed once
--      made: Quotation, Client letter, HR letter), its name (unique), an HR
--      letter's reference code (ADHR/{Employee ID}/{code}{YYMM}), the
--      wording, whether it is signed, and its fields. `doc_type_set_active`
--      offers it on Issue or stops offering it. Both are Documents: Document
--      types (`register.types`), a granted part: an admin's by itself, any
--      other group's once set. Each is filed `team.changed` under subject
--      Document types, naming what changed from and to. A type is never
--      removed: an issued document names its type.
--
-- ROLLBACK (in the SQL Editor)
--   drop function if exists public.doc_type_set_active(text, boolean);
--   drop function if exists public.doc_type_save(text, text, text, text, text, text, text, text, text, text, boolean, jsonb);
--   alter table public.doc_types drop column if exists fields;
-- ===========================================================================

alter table public.doc_types add column if not exists fields jsonb not null default '{}'::jsonb;

create or replace function public.doc_type_save(
  p_id         text,
  p_family     text,
  p_name       text,
  p_code       text,
  p_title      text,
  p_salutation text,
  p_closing    text,
  p_body_en    text,
  p_body_zh    text,
  p_body_ms    text,
  p_signed     boolean,
  p_fields     jsonb
)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me        public.team_members;
  v_old     public.doc_types%rowtype;
  v_name    text := btrim(coalesce(p_name, ''));
  v_code    text := upper(btrim(coalesce(p_code, '')));
  v_title   text := btrim(coalesce(p_title, ''));
  v_sal     text := btrim(coalesce(p_salutation, ''));
  v_close   text := btrim(coalesce(p_closing, ''));
  v_en      text := btrim(coalesce(p_body_en, ''));
  v_zh      text := btrim(coalesce(p_body_zh, ''));
  v_ms      text := btrim(coalesce(p_body_ms, ''));
  v_signed  boolean := coalesce(p_signed, true);
  v_fields  jsonb := coalesce(p_fields, '{}'::jsonb);
  v_family  text;
  v_id      text;
  v_n       int;
  v_key     text;
  v_kind    text;
  v_moves   text[] := '{}';
  v_said    text;
  v_was     text;
begin
  if not public.ops_granted('register.types', 'work') then return jsonb_build_object('error', 'denied'); end if;
  me := public.ops_me();
  if char_length(v_name) < 2 or char_length(v_name) > 80 then return jsonb_build_object('error', 'bad-name'); end if;
  if char_length(v_title) > 200 or char_length(v_sal) > 120 or char_length(v_close) > 120
     or char_length(v_en) > 20000 or char_length(v_zh) > 20000 or char_length(v_ms) > 20000 then
    return jsonb_build_object('error', 'too-long');
  end if;
  if jsonb_typeof(v_fields) <> 'object' or (select count(*) from jsonb_object_keys(v_fields)) > 30 then
    return jsonb_build_object('error', 'bad-fields');
  end if;
  for v_key, v_kind in select e.key, e.value from jsonb_each_text(v_fields) as e loop
    if v_key !~ '^[^{}\n]{1,40}$' or v_kind is null or v_kind not in ('text', 'date', 'long') then
      return jsonb_build_object('error', 'bad-fields');
    end if;
  end loop;

  if coalesce(btrim(p_id), '') <> '' then
    select * into v_old from public.doc_types d where d.id = btrim(p_id);
    if v_old.id is null then return jsonb_build_object('error', 'not-found'); end if;
    if p_family is not null and p_family <> v_old.family then return jsonb_build_object('error', 'family-fixed'); end if;
    v_family := v_old.family;
  else
    if p_family is null or p_family not in ('quote_cover', 'client', 'hr') then return jsonb_build_object('error', 'bad-family'); end if;
    v_family := p_family;
  end if;

  if exists (select 1 from public.doc_types d
              where lower(btrim(d.name)) = lower(v_name) and d.id is distinct from v_old.id) then
    return jsonb_build_object('error', 'taken');
  end if;
  -- An HR letter's reference is ADHR/{Employee ID}/{code}{YYMM}, so its code
  -- is required and is its own among the HR letters offered.
  if v_family = 'hr' then
    if v_code !~ '^[A-Z0-9]{1,4}$' then return jsonb_build_object('error', 'bad-code'); end if;
    if exists (select 1 from public.doc_types d
                where d.family = 'hr' and d.active and upper(coalesce(d.code, '')) = v_code
                  and d.id is distinct from v_old.id) then
      return jsonb_build_object('error', 'code-taken');
    end if;
  else
    v_code := v_old.code;
  end if;

  if v_old.id is null then
    v_id := left(coalesce(nullif(btrim(regexp_replace(lower(v_name), '[^a-z0-9]+', '_', 'g'), '_'), ''), 'type'), 40);
    if exists (select 1 from public.doc_types d where d.id = v_id) then
      v_n := 2;
      while exists (select 1 from public.doc_types d where d.id = v_id || '_' || v_n) loop v_n := v_n + 1; end loop;
      v_id := v_id || '_' || v_n;
    end if;
    insert into public.doc_types (id, family, code, name, title, salutation, closing, body_en, body_zh, body_ms,
                                  signed, position, active, fields)
    values (v_id, v_family, v_code, v_name, v_title, v_sal, v_close, v_en, v_zh, v_ms, v_signed,
            coalesce((select max(d.position) from public.doc_types d), 0) + 10, true, v_fields);
    insert into public.activity_log (actor, action, subject, detail)
    values (coalesce(me.name, lower(auth.jwt() ->> 'email')), 'team.changed', 'Document types',
            'Added: ' || v_name || ' · ' || case v_family when 'hr' then 'HR letter · Code ' || v_code
                                                          when 'client' then 'Client letter' else 'Quotation' end);
    return jsonb_build_object('ok', true, 'id', v_id);
  end if;

  -- What changed, from and to; the wording is long, so it is named only.
  if v_old.name <> v_name then v_moves := v_moves || ('Name: ' || v_old.name || ' → ' || v_name); end if;
  if v_family = 'hr' and coalesce(v_old.code, '') <> v_code then
    v_moves := v_moves || ('Code: ' || coalesce(nullif(v_old.code, ''), 'not set') || ' → ' || v_code);
  end if;
  if coalesce(v_old.title, '') <> v_title then
    v_moves := v_moves || ('Title: ' || coalesce(nullif(v_old.title, ''), 'not set') || ' → ' || coalesce(nullif(v_title, ''), 'not set'));
  end if;
  if coalesce(v_old.salutation, '') <> v_sal then
    v_moves := v_moves || ('Salutation: ' || coalesce(nullif(v_old.salutation, ''), 'not set') || ' → ' || coalesce(nullif(v_sal, ''), 'not set'));
  end if;
  if coalesce(v_old.closing, '') <> v_close then
    v_moves := v_moves || ('Closing: ' || coalesce(nullif(v_old.closing, ''), 'not set') || ' → ' || coalesce(nullif(v_close, ''), 'not set'));
  end if;
  if v_old.signed <> v_signed then
    v_moves := v_moves || ('To be signed: ' || case when v_old.signed then 'Yes → No' else 'No → Yes' end);
  end if;
  if coalesce(v_old.body_en, '') <> v_en then v_moves := v_moves || 'Wording changed'::text; end if;
  if coalesce(v_old.body_zh, '') <> v_zh then v_moves := v_moves || 'Chinese wording changed'::text; end if;
  if coalesce(v_old.body_ms, '') <> v_ms then v_moves := v_moves || 'Malay wording changed'::text; end if;
  if coalesce(v_old.fields, '{}'::jsonb) <> v_fields then
    select coalesce(string_agg(e.key || ' (' || case e.value when 'long' then 'paragraph' else e.value end || ')', ', ' order by e.key), 'none')
      into v_was from jsonb_each_text(coalesce(v_old.fields, '{}'::jsonb)) as e;
    select coalesce(string_agg(e.key || ' (' || case e.value when 'long' then 'paragraph' else e.value end || ')', ', ' order by e.key), 'none')
      into v_said from jsonb_each_text(v_fields) as e;
    v_moves := v_moves || ('Fields: ' || v_was || ' → ' || v_said);
  end if;
  if array_length(v_moves, 1) is null then
    return jsonb_build_object('ok', true, 'id', v_old.id, 'unchanged', true);
  end if;

  update public.doc_types d
     set name = v_name, code = v_code, title = v_title, salutation = v_sal, closing = v_close,
         body_en = v_en, body_zh = v_zh, body_ms = v_ms, signed = v_signed, fields = v_fields
   where d.id = v_old.id;
  insert into public.activity_log (actor, action, subject, detail)
  values (coalesce(me.name, lower(auth.jwt() ->> 'email')), 'team.changed', 'Document types',
          v_name || ' · ' || array_to_string(v_moves, ' · '));
  return jsonb_build_object('ok', true, 'id', v_old.id);
end $$;
grant execute on function public.doc_type_save(text, text, text, text, text, text, text, text, text, text, boolean, jsonb) to authenticated;

-- Offered on Issue, or no longer. The way back never asks.
create or replace function public.doc_type_set_active(p_id text, p_on boolean)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me    public.team_members;
  v_t   public.doc_types%rowtype;
  v_on  boolean := coalesce(p_on, false);
begin
  if not public.ops_granted('register.types', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into v_t from public.doc_types d where d.id = p_id;
  if v_t.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if v_t.active = v_on then return jsonb_build_object('ok', true, 'unchanged', true); end if;
  if v_on and v_t.family = 'hr' and exists (select 1 from public.doc_types d
       where d.family = 'hr' and d.active and d.id <> v_t.id and upper(coalesce(d.code, '')) = upper(coalesce(v_t.code, ''))) then
    return jsonb_build_object('error', 'code-taken');
  end if;
  me := public.ops_me();
  update public.doc_types d set active = v_on where d.id = v_t.id;
  insert into public.activity_log (actor, action, subject, detail)
  values (coalesce(me.name, lower(auth.jwt() ->> 'email')), 'team.changed', 'Document types',
          v_t.name || ' · ' || case when v_on then 'Inactive → Active' else 'Active → Inactive' end);
  return jsonb_build_object('ok', true);
end $$;
grant execute on function public.doc_type_set_active(text, boolean) to authenticated;

-- END OF DOCUMENT TYPES -------------------------------------------------------

-- ===========================================================================
-- REPORTS OWED — the reports a content month asks for, and where each one
-- stands, for the Overview's Reports card.
-- 2026-10-07. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/smsql.js compares the
-- two.
--
-- WHAT CHANGED (the user, 2026-10-07: "some clients are not monthly
-- engagement ... show only those have content month")
--   1. `sm_reports_owed(p_period)`: for a content month ('YYYY-MM'; last
--      month in Malaysia when none is given), every report a client's month
--      asks for (its Reports ticks) and every report made for that month
--      that no tick asked for, each with its stage: none (not started),
--      draft, review, confirmed or published; the brand of a white-label
--      report; the report task and who it is assigned to; the due time (the
--      task's, else `report_due_days` after the month's last day, 23:59
--      MYT); and late once that time has passed short of published. A
--      report belongs to the month whose span holds its last day, else to
--      the calendar month of its last day. Reports at Full Access, and only
--      the clients the caller may see (`client_row_seen`).
--
-- ROLLBACK (in the SQL Editor)
--   drop function if exists public.sm_reports_owed(text);
-- ===========================================================================

create or replace function public.sm_reports_owed(p_period text default null)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_period   text := coalesce(nullif(btrim(p_period), ''),
                       to_char(date_trunc('month', now() at time zone 'Asia/Kuala_Lumpur') - interval '1 month', 'YYYY-MM'));
  v_items    jsonb := '[]'::jsonb;
  v_seen     uuid[] := '{}';
  v_task     uuid;
  v_tdue     timestamptz;
  v_assignee text;
  v_due      timestamptz;
  v_found    boolean;
  e          record;
  k          text;
  r          record;
begin
  if not public.allowed('reports', 'manage') then return jsonb_build_object('error', 'denied'); end if;
  if v_period !~ '^[0-9]{4}-(0[1-9]|1[0-2])$' then return jsonb_build_object('error', 'bad-period'); end if;

  -- Every report a month of the period asks for, found or not started.
  for e in
    select x.id, x.client_id, x.reports, s.starts, s.ends, c.name as client_name, c.slug as client_slug
      from public.ops_engagements x
      join public.clients c on c.id = x.client_id
     cross join lateral public.ops_month_span(x.period, x.start_day) s
     where x.period = v_period and x.status <> 'cancelled' and cardinality(x.reports) > 0
       and public.client_row_seen(c.stage, c.owner, 'view')
     order by c.name
  loop
    foreach k in array e.reports loop
      v_task := null; v_tdue := null; v_assignee := null;
      select x.id, x.current_final_due_at, m.name into v_task, v_tdue, v_assignee
        from public.ops_tasks x
        left join public.ops_task_assignees a
          on a.task_id = x.id and a.responsibility = 'owner' and a.ended_at is null
        left join public.team_members m on m.id = a.team_member_id
       where x.engagement_id = e.id and x.source_type = 'report_' || k
         and x.cancelled_at is null and x.archived_at is null
       order by x.created_at desc limit 1;
      v_due := coalesce(v_tdue,
        ((e.ends + public.app_setting('report_due_days', e.ends)::integer)::timestamp + time '23:59') at time zone 'Asia/Kuala_Lumpur');
      v_found := false;
      for r in
        select y.id, y.status, y.sent_on, b.name as brand_name
          from public.sm_reports y
          left join public.client_brands b on b.id = y.brand_id
         where y.client_id = e.client_id and y.kind = k and y.period_end between e.starts and e.ends
         order by b.name nulls first, y.period_start
      loop
        v_found := true;
        v_seen := v_seen || r.id;
        v_items := v_items || jsonb_build_object(
          'client_id', e.client_id, 'client', e.client_name, 'slug', e.client_slug, 'kind', k,
          'brand', r.brand_name, 'report_id', r.id, 'status', r.status, 'sent_on', r.sent_on,
          'asked', true, 'task_id', v_task, 'assignee', v_assignee, 'due', v_due,
          'late', r.status <> 'published' and now() > v_due);
      end loop;
      if not v_found then
        v_items := v_items || jsonb_build_object(
          'client_id', e.client_id, 'client', e.client_name, 'slug', e.client_slug, 'kind', k,
          'brand', null, 'report_id', null, 'status', 'none', 'sent_on', null,
          'asked', true, 'task_id', v_task, 'assignee', v_assignee, 'due', v_due, 'late', now() > v_due);
      end if;
    end loop;
  end loop;

  -- Every report made for the period that no month's tick asked for: it
  -- belongs to the month whose span holds its last day, else to the
  -- calendar month of that day.
  for r in
    select y.id, y.client_id, y.kind, y.status, y.sent_on, y.period_end,
           c.name as client_name, c.slug as client_slug, b.name as brand_name
      from public.sm_reports y
      join public.clients c on c.id = y.client_id
      left join public.client_brands b on b.id = y.brand_id
     where not (y.id = any (v_seen))
       and coalesce((select x.period from public.ops_engagements x
                      cross join lateral public.ops_month_span(x.period, x.start_day) s
                      where x.client_id = y.client_id and x.status <> 'cancelled'
                        and y.period_end between s.starts and s.ends
                      order by x.period desc limit 1),
                    to_char(y.period_end, 'YYYY-MM')) = v_period
       and public.client_row_seen(c.stage, c.owner, 'view')
     order by c.name, y.kind, b.name nulls first
  loop
    v_due := ((r.period_end + public.app_setting('report_due_days', r.period_end)::integer)::timestamp + time '23:59') at time zone 'Asia/Kuala_Lumpur';
    v_items := v_items || jsonb_build_object(
      'client_id', r.client_id, 'client', r.client_name, 'slug', r.client_slug, 'kind', r.kind,
      'brand', r.brand_name, 'report_id', r.id, 'status', r.status, 'sent_on', r.sent_on,
      'asked', false, 'task_id', null, 'assignee', null, 'due', v_due,
      'late', r.status <> 'published' and now() > v_due);
  end loop;

  return jsonb_build_object('period', v_period, 'items', v_items);
end $$;
revoke all on function public.sm_reports_owed(text) from public, anon, authenticated;
grant execute on function public.sm_reports_owed(text) to authenticated;

-- END OF REPORTS OWED ---------------------------------------------------------

-- ===========================================================================
-- PERFORMANCE SELF-RATING — a colleague rates themselves on the scorecard
-- before the month is shared, a month whose query window has closed settles
-- by itself, and the first open of a shared review is recorded.
-- 2026-10-07. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/perf.js compares the
-- two.
--
-- WHAT CHANGED (the user, 2026-10-07: "we need them to rate themselves too
-- based on the same metrics"; "after dispute period, no disputes = auto
-- acknowledged same goes to previous months. So i would be able to confirm
-- and issue the quarter rewards"; answered: the scorecard only, before
-- management scores, Acknowledged and Final, record the first open)
--   1. `perf_self_ratings` (colleague, month, the six scorecard scores in
--      the scorecard's own maxima, when saved): RLS on, no policy, no
--      grant. A month opens to rate on the 1st after it (from June 2026)
--      for a colleague on the review list, or one whose review of it has
--      begun, from the month they joined, and stays open until its review
--      is shared (`perf_self_open`: `bad-month`, `shared`, `not-reviewed`).
--      `perf_self_mine()` answers the months open and what was given;
--      `perf_self_save(p_period, p_scores)` writes all six at once
--      (`incomplete`, `bad-score` with the item and its maximum); both
--      behind the fresh proof (`perf_mine_gate`). Each save is filed
--      `self.saved`, which the review's history reads.
--   2. `perf_json` sends the colleague's rating as `self` (scores, total,
--      when saved) beside management's scores; it never enters the grade.
--      It sends `opened_at` (the open of the version on show) and
--      `final_auto` (settled by itself).
--   3. `perf_reviews.opened_at`: `perf_seen(p_review)` stamps the first time
--      the colleague opens their shared review (again after a release
--      that followed it), filed `opened`. It moves nothing else.
--   4. `perf_close_windows()`: a shared month whose query window has closed
--      with no query waiting on an answer (shared, every query answered, or
--      acknowledged) becomes Final by itself: acknowledged as at the window's
--      close, or the last answer where that came after it, and finalised
--      now, each filed with `auto`, its result kept as Final keeps it.
--      Every hour (pg_cron `perf-close-windows`) and once at the foot of
--      this file, so earlier months settle at once. No browser calls it.
--   5. `perf_printed`'s trail adds Opened and marks the automatic steps;
--      `perf_activity` lists `opened` and `self.saved`, each with `auto`.
--
-- ROLLBACK (in the SQL Editor)
--   select cron.unschedule('perf-close-windows');
--   Run perf_json from DATE OF EVALUATION, perf_printed from PERFORMANCE
--   RECORDS, THEIR TRAIL AND THEIR CHECK and perf_activity from A
--   PERFORMANCE RECORD CAN BE DELETED again; then drop perf_close_windows,
--   perf_seen, perf_self_save, perf_self_mine, perf_self_open and the
--   table, and run
--   alter table public.perf_reviews drop column if exists opened_at;
-- ===========================================================================

alter table public.perf_reviews add column if not exists opened_at timestamptz;

create table if not exists public.perf_self_ratings (
  team_member_id uuid not null references public.team_members(id) on delete cascade,
  period         date not null check (extract(day from period) = 1),
  s_output       numeric(4,1) not null check (s_output between 0 and 25),
  s_accuracy     numeric(4,1) not null check (s_accuracy between 0 and 15),
  s_delivery     numeric(4,1) not null check (s_delivery between 0 and 15),
  s_client       numeric(4,1) not null check (s_client between 0 and 20),
  s_comms        numeric(4,1) not null check (s_comms between 0 and 15),
  s_initiative   numeric(4,1) not null check (s_initiative between 0 and 10),
  saved_at       timestamptz not null default now(),
  primary key (team_member_id, period)
);
alter table public.perf_self_ratings enable row level security;
revoke all on public.perf_self_ratings from public, anon, authenticated;

/* One reading of a colleague's own rating, for them and for management. */
create or replace function public.perf_self_json(p_member uuid, p_period date)
returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'scores', jsonb_build_object('output', s.s_output, 'accuracy', s.s_accuracy,
      'delivery', s.s_delivery, 'client', s.s_client, 'comms', s.s_comms,
      'initiative', s.s_initiative),
    'total', s.s_output + s.s_accuracy + s.s_delivery + s.s_client + s.s_comms + s.s_initiative,
    'saved_at', s.saved_at)
    from public.perf_self_ratings s
   where s.team_member_id = p_member and s.period = p_period
$$;
revoke all on function public.perf_self_json(uuid, date) from public, anon, authenticated;

/* Null when the month is open to rate; else why not. */
create or replace function public.perf_self_open(p_member uuid, p_period date)
returns text
language sql stable security definer set search_path = public as $$
  select case
    when p_period is null or extract(day from p_period) <> 1 or p_period < date '2026-06-01'
      or p_period >= date_trunc('month', public.perf_today())::date
      then 'bad-month'
    when exists (select 1 from public.perf_reviews r
                  where r.team_member_id = p_member and r.period = p_period and r.status <> 'draft')
      then 'shared'
    when not exists (select 1 from public.perf_reviews r
                      where r.team_member_id = p_member and r.period = p_period)
     and (not coalesce(public.perf_reviewed(p_member), false)
          or p_period < (select date_trunc('month', t.created_at)::date
                           from public.team_members t where t.id = p_member))
      then 'not-reviewed'
  end
$$;
revoke all on function public.perf_self_open(uuid, date) from public, anon, authenticated;

create or replace function public.perf_self_mine()
returns jsonb
language plpgsql security definer set search_path = public as $$
declare m public.team_members; g jsonb;
begin
  g := public.perf_mine_gate();
  if g is not null then return g; end if;
  m := public.ops_me();
  return jsonb_build_object('months', coalesce((
    select jsonb_agg(jsonb_build_object('period', p.period, 'month', public.perf_month_word(p.period),
                                        'rating', public.perf_self_json(m.id, p.period))
                     order by p.period desc)
      from (select generate_series(date '2026-06-01',
                                   (date_trunc('month', public.perf_today()) - interval '1 month')::date,
                                   interval '1 month')::date as period) p
     where public.perf_self_open(m.id, p.period) is null), '[]'::jsonb));
end $$;

create or replace function public.perf_self_save(p_period date, p_scores jsonb)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m public.team_members; g jsonb; err text; p date := date_trunc('month', p_period)::date;
  k text; mx numeric; v numeric; was boolean; rid uuid;
begin
  g := public.perf_mine_gate();
  if g is not null then return g; end if;
  m := public.ops_me();
  err := public.perf_self_open(m.id, p);
  if err is not null then return jsonb_build_object('error', err); end if;
  if jsonb_typeof(p_scores) is distinct from 'object' then return jsonb_build_object('error', 'incomplete'); end if;
  foreach k in array array['output', 'accuracy', 'delivery', 'client', 'comms', 'initiative'] loop
    if jsonb_typeof(p_scores -> k) is distinct from 'number' then
      return jsonb_build_object('error', 'incomplete', 'item', k);
    end if;
    mx := case k when 'output' then 25 when 'accuracy' then 15 when 'delivery' then 15
                 when 'client' then 20 when 'comms' then 15 when 'initiative' then 10 end;
    v := (p_scores ->> k)::numeric;
    if v < 0 or v > mx or round(v, 1) <> v then
      return jsonb_build_object('error', 'bad-score', 'item', k, 'max', mx);
    end if;
  end loop;
  was := exists (select 1 from public.perf_self_ratings s where s.team_member_id = m.id and s.period = p);
  insert into public.perf_self_ratings (team_member_id, period, s_output, s_accuracy, s_delivery,
                                        s_client, s_comms, s_initiative, saved_at)
  values (m.id, p, (p_scores ->> 'output')::numeric, (p_scores ->> 'accuracy')::numeric,
          (p_scores ->> 'delivery')::numeric, (p_scores ->> 'client')::numeric,
          (p_scores ->> 'comms')::numeric, (p_scores ->> 'initiative')::numeric, now())
  on conflict (team_member_id, period) do update
     set s_output = excluded.s_output, s_accuracy = excluded.s_accuracy, s_delivery = excluded.s_delivery,
         s_client = excluded.s_client, s_comms = excluded.s_comms, s_initiative = excluded.s_initiative,
         saved_at = now();
  select r.id into rid from public.perf_reviews r where r.team_member_id = m.id and r.period = p;
  perform public.perf_log(rid, m.id, 'self.saved', jsonb_build_object('period', p, 'again', was));
  return public.perf_self_mine();
end $$;

/* The first open of what was shared, by the colleague it is about. */
create or replace function public.perf_seen(p_review uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare m public.team_members; g jsonb; r public.perf_reviews;
begin
  g := public.perf_mine_gate();
  if g is not null then return g; end if;
  m := public.ops_me();
  update public.perf_reviews set opened_at = now()
   where id = p_review and team_member_id = m.id and status <> 'draft'
     and (opened_at is null or opened_at < released_at)
  returning * into r;
  if r.id is not null then
    perform public.perf_log(r.id, r.team_member_id, 'opened', jsonb_build_object('version', r.version));
  else
    select * into r from public.perf_reviews
     where id = p_review and team_member_id = m.id and status <> 'draft';
    if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  end if;
  return public.perf_json(r, false);
end $$;

create or replace function public.perf_json(r public.perf_reviews, p_full boolean)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare m public.team_members; pp public.perf_people; out jsonb;
begin
  select * into m from public.team_members where id = r.team_member_id;
  select * into pp from public.perf_people where team_member_id = r.team_member_id;
  out := jsonb_build_object(
    'id', r.id, 'team_member_id', r.team_member_id, 'period', r.period,
    'month', public.perf_month_word(r.period), 'status', r.status,
    'member', jsonb_build_object('name', m.name, 'staff_code', m.staff_code,
      'designation', m.designation, 'department', m.department,
      'role_family', m.role_family, 'runs_ads', coalesce(pp.runs_ads, false)),
    'scores', jsonb_build_object('output', r.s_output, 'accuracy', r.s_accuracy,
      'delivery', r.s_delivery, 'client', r.s_client, 'comms', r.s_comms,
      'initiative', r.s_initiative),
    'self', public.perf_self_json(r.team_member_id, r.period),
    'rates', jsonb_build_object('posting', r.r_posting, 'timeline', r.r_timeline,
      'satisfaction', r.r_satisfaction, 'pacing', r.r_pacing, 'sla', r.r_sla),
    'notes', r.notes, 'improvement', r.improvement, 'review_by', r.review_by,
    'evaluated_on', r.evaluated_on,
    'reward_step', r.reward_step, 'serial', r.serial,
    'reviewer', (select name from public.team_members where id = r.reviewer_id),
    'released_at', r.released_at, 'dispute_until', r.dispute_until,
    'dispute_open', r.status = 'released' and r.dispute_until > now()
                    and not exists (select 1 from public.perf_disputes d
                                     where d.review_id = r.id and d.version = r.version),
    'opened_at', case when r.opened_at >= r.released_at then r.opened_at end,
    'acknowledged_at', r.acknowledged_at, 'finalised_at', r.finalised_at,
    'finalised_by', (select name from public.team_members where id = r.finalised_by),
    'final_auto', r.status = 'final' and r.finalised_by is null,
    'version', r.version, 'rev', r.rev,
    'result', public.perf_calc(r),
    'breaches', public.perf_breaches_json(r.team_member_id, r.period, false),
    'disputes', coalesce((select jsonb_agg(jsonb_build_object(
        'id', d.id, 'item', d.item, 'breach_id', d.breach_id, 'reason', d.reason,
        'breach_what', (select b.what from public.perf_breaches b where b.id = d.breach_id),
        'raised_at', d.raised_at, 'decision', d.decision, 'response', d.response,
        'before_value', d.before_value, 'after_value', d.after_value,
        'decided_by', (select name from public.team_members where id = d.decided_by),
        'decided_at', d.decided_at) order by d.raised_at)
        from public.perf_disputes d where d.review_id = r.id and d.version = r.version), '[]'::jsonb));
  if p_full then
    out := out || jsonb_build_object(
      'voided', (select coalesce(jsonb_agg(x), '[]'::jsonb)
                   from jsonb_array_elements(public.perf_breaches_json(r.team_member_id, r.period, true)) x
                  where x ->> 'voided_at' is not null),
      'ops', public.perf_ops_rate(r.team_member_id, r.period),
      'events', coalesce((select jsonb_agg(jsonb_build_object(
          'kind', e.kind, 'detail', e.detail, 'at', e.created_at,
          'by', coalesce((select name from public.team_members where id = e.actor_id), e.actor_email))
          order by e.created_at desc)
          from public.perf_events e
         where e.review_id = r.id
            or (e.review_id is null and e.kind = 'self.saved' and e.team_member_id = r.team_member_id
                and e.detail ->> 'period' = r.period::text)), '[]'::jsonb));
  end if;
  return out;
end $$;

/* A month whose window has closed with nothing waiting on an answer is
   settled: acknowledged as at the close (or the last answer, where that
   came after it) and finalised now, each filed as automatic. */
create or replace function public.perf_close_windows()
returns integer
language plpgsql security definer set search_path = public as $$
declare r public.perf_reviews; res jsonb; n integer := 0; v_ack timestamptz;
begin
  for r in
    select x.* from public.perf_reviews x
     where x.status in ('released', 'resolved', 'acknowledged')
       and x.dispute_until is not null and x.dispute_until <= now()
       and not exists (select 1 from public.perf_disputes d
                        where d.review_id = x.id and d.version = x.version and d.decision is null)
     order by x.period, x.id
     for update skip locked
  loop
    v_ack := coalesce(r.acknowledged_at, greatest(r.dispute_until,
               coalesce((select max(d.decided_at) from public.perf_disputes d
                          where d.review_id = r.id and d.version = r.version), r.dispute_until)));
    res := public.perf_calc(r);
    update public.perf_reviews
       set status = 'final', result = res, acknowledged_at = v_ack,
           finalised_at = now(), finalised_by = null, rev = rev + 1, updated_at = now()
     where id = r.id;
    if r.acknowledged_at is null then
      insert into public.perf_events (review_id, team_member_id, actor_id, actor_email, kind, detail, created_at)
      values (r.id, r.team_member_id, null, null, 'acknowledged', jsonb_build_object('auto', true), v_ack);
    end if;
    insert into public.perf_events (review_id, team_member_id, actor_id, actor_email, kind, detail)
    values (r.id, r.team_member_id, null, null, 'finalised',
            jsonb_build_object('auto', true, 'grade', res ->> 'grade', 'final', res -> 'final'));
    n := n + 1;
  end loop;
  return n;
end $$;

create or replace function public.perf_printed(p_review uuid, p_token text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare m public.team_members; r public.perf_reviews; ev_id uuid; ev_at timestamptz;
begin
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'not-team'); end if;
  select * into r from public.perf_reviews where id = p_review;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if r.team_member_id <> m.id and public.perf_check(p_token, 'view') is not null then
    return jsonb_build_object('error', 'denied');
  end if;
  if r.team_member_id = m.id and r.status = 'draft' then return jsonb_build_object('error', 'not-found'); end if;
  insert into public.perf_events (review_id, team_member_id, actor_id, actor_email, kind, detail)
  values (r.id, r.team_member_id, m.id, m.email, 'printed', jsonb_build_object('version', r.version))
  returning id, created_at into ev_id, ev_at;
  return jsonb_build_object('ok', true, 'id', ev_id, 'at', ev_at, 'by', m.name, 'email', m.email,
    'trail', coalesce((
      select jsonb_agg(jsonb_build_object('kind', t.kind, 'at', t.created_at, 'by', t.who,
                                          'email', t.actor_email, 'auto', t.auto)
                       order by t.created_at)
        from (select distinct on (pe.kind) pe.kind, pe.created_at, pe.actor_email,
                     coalesce(tm.name, pe.actor_email) as who,
                     coalesce((pe.detail ->> 'auto')::boolean, false) as auto
                from public.perf_events pe
                left join public.team_members tm on tm.id = pe.actor_id
               where pe.review_id = r.id
                 and ((pe.kind = 'released' and r.released_at is not null)
                   or (pe.kind = 'opened' and r.opened_at >= r.released_at)
                   or (pe.kind = 'acknowledged' and r.acknowledged_at is not null)
                   or (pe.kind = 'finalised' and r.finalised_at is not null))
               order by pe.kind, pe.created_at desc) t), '[]'::jsonb));
end $$;

/* The Activity record's Performance tab, now with the first open and a
   colleague's own rating, and whether a step settled by itself. */
create or replace function public.perf_activity(p_limit integer default 200)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare me_row public.team_members;
begin
  me_row := public.ops_me();
  if me_row.id is null or not public.ops_granted('team.performance', 'view') then
    return jsonb_build_object('error', 'denied');
  end if;
  return jsonb_build_object('rows', coalesce((
    select jsonb_agg(jsonb_build_object(
             'at', e.created_at, 'kind', e.kind, 'member', tm.name,
             'period', coalesce(rv.period, case when e.kind in ('deleted', 'self.saved')
                                                then (e.detail ->> 'period')::date end),
             'actor', e.actor_email, 'actor_name', ac.name,
             'auto', coalesce((e.detail ->> 'auto')::boolean, false)) order by e.created_at desc)
      from (select pe.* from public.perf_events pe
             where pe.kind in ('released', 'opened', 'self.saved', 'disputed', 'decided', 'acknowledged',
                               'finalised', 'reopened', 'returned', 'printed', 'deleted')
               and pe.team_member_id is distinct from me_row.id
             order by pe.created_at desc
             limit greatest(1, least(coalesce(p_limit, 200), 500))) e
      left join public.team_members tm on tm.id = e.team_member_id
      left join public.perf_reviews rv on rv.id = e.review_id
      left join public.team_members ac on ac.id = e.actor_id), '[]'::jsonb));
end $$;

