-- ===========================================================================
-- ACTIVITY FILES A RESTORE AND A DELETE — a service line restored and a call
-- or visit deleted are each filed as themselves, under Clients.
-- 2026-10-08. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/trail.js reads the
-- map against the console's ACTION_LABEL.
--
-- WHAT CHANGED
--   The delete audit (the user, 2026-10-07) gave a removed service line its
--   way back after the Undo (Restore, `client.service_restored`, which had
--   been filed as Service changed) and a removed call or visit its delete at
--   Manage (`client.touch_deleted`). activity_section() names both, so the
--   record files them under Clients rather than Other. Nothing else moves.
--
-- ROLLBACK
--   Run the function as the section that last defined it (the activity map
--   above this banner) defines it.
-- ===========================================================================

create or replace function public.activity_section(p_action text)
returns text
language sql immutable parallel safe as $$
  select case
    when action in ('campaign.bulk', 'campaign.closed', 'campaign.confirmed',
                    'campaign.created', 'campaign.dates', 'campaign.deleted', 'campaign.edited',
                    'campaign.file_added', 'campaign.qc',
                    'campaign.invoice', 'campaign.invoice_file',
                    'campaign.invoice_removed', 'campaign.keyed', 'campaign.locked',
                    'campaign.opened', 'campaign.rate', 'campaign.rated',
                    'campaign.reinstated', 'campaign.replaced', 'campaign.results', 'campaign.review',
                    'campaign.stage', 'campaign.submitted', 'campaign.task_linked',
                    'campaign.task_unlinked', 'campaign.unbooked',
                    'campaign.unkeyed', 'campaign.withdrawn', 'creator.added',
                    'creator.code', 'creator.links', 'creator.links_restored',
                    'creator.links_self', 'creator.off', 'creator.on', 'creator.removed',
                    'creator.updated') then 'campaigns'
    when action in ('client.action_done', 'client.action_reopened', 'client.added',
                    'client.billing', 'client.brand', 'client.deleted', 'client.edited',
                    'client.review_on', 'client.service', 'client.service_changed',
                    'client.service_removed', 'client.service_restored', 'client.stage', 'client.touch',
                    'client.touch_deleted', 'client.touch_edited', 'client.touch_removed',
                    'client.touch_restored', 'contact.added', 'contact.deleted',
                    'contact.edited', 'contact.portal_invite', 'contact.portal_off',
                    'contact.portal_on', 'contact.primary', 'contact.removed',
                    'contact.restored',
                    'request.changed', 'request.raised',
                    'request.reinstated', 'request.replied', 'request.withdrawn',
                    'service.override') then 'clients'
    when action in ('report.ai_drafted', 'report.ai_failed', 'report.confirmed',
                    'report.created', 'report.deleted', 'report.published',
                    'report.reassigned', 'report.returned', 'report.revised', 'report.saved',
                    'report.submitted', 'report.unpublished') then 'reports'
    when action in ('qr.created', 'qr.restored', 'qr.revoked', 'shortlink.created',
                    'shortlink.deleted', 'shortlink.imported', 'shortlink.updated') then 'links'
    when action in ('ops.deleted', 'ops.month_deleted', 'ops.numbering') then 'ops'
    when action in ('document.deleted', 'document.issued', 'document.reissued',
                    'document.restored', 'document.signed', 'document.superseded',
                    'document.unsigned', 'document.verified', 'document.voided',
                    'register.added', 'register.edited') then 'register'
    when action in ('client.drive', 'client.handles', 'client.profile',
                    'client.removed', 'drive.imported', 'link.reset', 'post.added',
                    'post.deleted', 'post.edited', 'reapproval.requested',
                    'review.approved', 'review.changes', 'review.removed',
                    'review.unconfirmed',
                    'set.created', 'set.deleted', 'set.published', 'set.renamed',
                    'set.task_linked', 'set.task_unlinked',
                    'set.withdrawn') then 'review'
    when action in ('handbook.added', 'handbook.archived', 'handbook.deleted',
                    'handbook.edited', 'handbook.restored', 'handbook.version') then 'handbook'
    when action in ('service.added', 'service.changed', 'service.deleted',
                    'service.off', 'service.on') then 'services'
    when action in ('team.added', 'team.changed', 'team.edited', 'team.group_added',
                    'team.group_changed', 'team.group_removed', 'team.invited') then 'team'
    else 'other'
  end
  from (select p_action as action) t
$$;
grant execute on function public.activity_section(text) to authenticated;

-- END OF ACTIVITY FILES A RESTORE AND A DELETE -----------------------------

-- ===========================================================================
-- TASK CODE EDITABLE — a task's code is corrected in place.
-- 2026-10-08. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/ops.js compares the
-- two.
--
-- WHAT CHANGED
--   The user, 2026-10-08: "the 2610WN make it editable". The code was made
--   once and never rewritten; the #WT serial stays the task's identity, so
--   the code may now be corrected. `ops_set_code(p_task, p_code, p_version)`:
--   the owner or an admin (`ops_owner_may_move`, `not-owner`), My Work at
--   Work, a task that already carries a code (`no-code`); the code keeps its
--   shape YYMMW{week}{NN}, the month 01 to 12 and the week 1 to 5
--   (`bad-code`), and is the client's own for that month (`code-taken`,
--   naming the task that holds it). It writes code, code_period, code_week,
--   code_seq and the title, and files `code_changed` from and to.
--
-- ROLLBACK
--   Remove the function ops_set_code(uuid, text, integer).
-- ===========================================================================

create or replace function public.ops_set_code(
  p_task uuid, p_code text, p_version integer default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m public.team_members;
  t public.ops_tasks;
  v_code text;
  v_parts text[];
  v_period text;
  v_week integer;
  v_seq integer;
  v_other bigint;
begin
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if not public.ops_may_see_task(p_task) then return jsonb_build_object('error', 'denied'); end if;
  if not public.allowed('ops', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if not public.ops_owner_may_move(p_task) then return jsonb_build_object('error', 'not-owner'); end if;
  select * into t from public.ops_tasks where id = p_task for update;
  if t.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if p_version is not null and p_version <> t.version then
    return jsonb_build_object('error', 'stale', 'task', public.ops_task_json(p_task));
  end if;
  if coalesce(t.code, '') = '' or t.code_seq is null then
    return jsonb_build_object('error', 'no-code');
  end if;
  v_code := upper(regexp_replace(coalesce(p_code, ''), '\s', '', 'g'));
  v_parts := regexp_match(v_code, '^([0-9]{2})([0-9]{2})W([1-5])([0-9]{2,3})$');
  if v_parts is null or v_parts[2]::integer not between 1 and 12 or v_parts[4]::integer < 1 then
    return jsonb_build_object('error', 'bad-code');
  end if;
  v_period := '20' || v_parts[1] || '-' || v_parts[2];
  v_week := v_parts[3]::integer;
  v_seq := v_parts[4]::integer;
  v_code := v_parts[1] || v_parts[2] || 'W' || v_week::text || lpad(v_seq::text, 2, '0');
  if v_code = t.code then return public.ops_task_json(p_task); end if;
  select o.task_no into v_other from public.ops_tasks o
   where o.id <> p_task
     and coalesce(o.client_id, '00000000-0000-0000-0000-000000000000'::uuid)
       = coalesce(t.client_id, '00000000-0000-0000-0000-000000000000'::uuid)
     and o.code_period = v_period and o.code_seq = v_seq
   limit 1;
  if found then
    return jsonb_build_object('error', 'code-taken', 'task_no', v_other);
  end if;
  update public.ops_tasks
     set code = v_code, code_period = v_period, code_week = v_week, code_seq = v_seq,
         title = btrim(v_code || ' ' || coalesce(content_desc, '')),
         version = version + 1, updated_at = now()
   where id = p_task;
  perform public.ops_log(p_task, 'code_changed',
    jsonb_build_object('code', t.code), jsonb_build_object('code', v_code), '{}'::jsonb);
  return public.ops_task_json(p_task);
end $$;
revoke all on function public.ops_set_code(uuid, text, integer) from public, anon;
grant execute on function public.ops_set_code(uuid, text, integer) to authenticated;

-- END OF TASK CODE EDITABLE -------------------------------------------------

-- ===========================================================================
-- TASK DETAILS EDITABLE — a task's format, type, complexity and estimate are
-- changed where the record shows them.
-- 2026-10-08. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/ops.js compares the
-- two.
--
-- WHAT CHANGED
--   The user, 2026-10-08: "allow changes straight from these too … a lot of
--   it are hardcoded". `ops_update_task(p_task, p_payload, p_version)` takes,
--   beside the brief and the priority, `deliverable_type` (a format key, or
--   null; `bad-format`), `task_type` (`bad-type`), `complexity`
--   (`bad-complexity`) and `estimate_minutes` (0 to 10,000, or null;
--   `bad-estimate`), each only where sent, and files `details_changed` from
--   and to for what moved.
--
-- ROLLBACK
--   Run the earlier ops_update_task again (supabase/schema.sql, the section
--   "What was added can be put right": the brief and the priority only).
-- ===========================================================================

create or replace function public.ops_update_task(
  p_task uuid, p_payload jsonb, p_version integer default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m     public.team_members;
  t     public.ops_tasks;
  d     text;
  pr    integer;
  fm    text;
  ty    text;
  cx    text;
  es    integer;
  was   jsonb := '{}'::jsonb;
  now_  jsonb := '{}'::jsonb;
begin
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if not public.ops_may_see_task(p_task) then return jsonb_build_object('error', 'denied'); end if;
  if not public.allowed('ops', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into t from public.ops_tasks where id = p_task for update;
  if t.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if p_version is not null and p_version <> t.version then
    return jsonb_build_object('error', 'stale', 'task', public.ops_task_json(p_task));
  end if;
  d := t.description; pr := t.priority_level; fm := t.deliverable_type;
  ty := t.task_type; cx := t.complexity; es := t.estimate_minutes;
  if p_payload ? 'description' then
    d := nullif(btrim(coalesce(p_payload ->> 'description', '')), '');
    if length(coalesce(d, '')) > 4000 then return jsonb_build_object('error', 'too-long'); end if;
  end if;
  if p_payload ? 'priority_level' then
    pr := (p_payload ->> 'priority_level')::integer;
    if pr is null or pr < 1 or pr > 4 then return jsonb_build_object('error', 'bad-priority'); end if;
  end if;
  if p_payload ? 'deliverable_type' then
    fm := nullif(btrim(coalesce(p_payload ->> 'deliverable_type', '')), '');
    if fm is not null and fm !~ '^[a-z0-9_]{1,40}$' then return jsonb_build_object('error', 'bad-format'); end if;
  end if;
  if p_payload ? 'task_type' then
    ty := p_payload ->> 'task_type';
    if ty is null or ty not in ('engagement', 'adhoc', 'goodwill', 'special') then
      return jsonb_build_object('error', 'bad-type');
    end if;
  end if;
  if p_payload ? 'complexity' then
    cx := p_payload ->> 'complexity';
    if cx is null or cx not in ('simple', 'standard', 'complex') then
      return jsonb_build_object('error', 'bad-complexity');
    end if;
  end if;
  if p_payload ? 'estimate_minutes' then
    if jsonb_typeof(p_payload -> 'estimate_minutes') = 'null' then es := null;
    else
      es := (p_payload ->> 'estimate_minutes')::integer;
      if es < 0 or es > 10000 then return jsonb_build_object('error', 'bad-estimate'); end if;
    end if;
  end if;
  if d is distinct from t.description then
    was := was || jsonb_build_object('description', t.description); now_ := now_ || jsonb_build_object('description', d);
  end if;
  if pr is distinct from t.priority_level then
    was := was || jsonb_build_object('priority_level', t.priority_level); now_ := now_ || jsonb_build_object('priority_level', pr);
  end if;
  if fm is distinct from t.deliverable_type then
    was := was || jsonb_build_object('deliverable_type', t.deliverable_type); now_ := now_ || jsonb_build_object('deliverable_type', fm);
  end if;
  if ty is distinct from t.task_type then
    was := was || jsonb_build_object('task_type', t.task_type); now_ := now_ || jsonb_build_object('task_type', ty);
  end if;
  if cx is distinct from t.complexity then
    was := was || jsonb_build_object('complexity', t.complexity); now_ := now_ || jsonb_build_object('complexity', cx);
  end if;
  if es is distinct from t.estimate_minutes then
    was := was || jsonb_build_object('estimate_minutes', t.estimate_minutes); now_ := now_ || jsonb_build_object('estimate_minutes', es);
  end if;
  if now_ = '{}'::jsonb then return public.ops_task_json(p_task); end if;
  update public.ops_tasks set description = d, priority_level = pr, deliverable_type = fm,
         task_type = ty, complexity = cx, estimate_minutes = es,
         version = version + 1, updated_at = now()
   where id = p_task;
  perform public.ops_log(p_task, 'details_changed', was, now_, '{}'::jsonb);
  return public.ops_task_json(p_task);
end $$;
grant execute on function public.ops_update_task(uuid, jsonb, integer) to authenticated;

-- END OF TASK DETAILS EDITABLE ----------------------------------------------

-- ===========================================================================
-- TASK NUMBERS FOLLOW THE PLAN — a client's month numbers its planned pieces
-- 01 to N, extras after them, and a number freed by a delete is used again.
-- 2026-10-08. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/ops.js compares the
-- two.
--
-- WHAT CHANGED
--   The user, 2026-10-08: "Make only deliverables based on pieces planned.
--   Extras or addons block the engagement selection … if delete then frees
--   up and can reuse serial … if its W1 then needs to be Week 1". The code's
--   NN was the client's highest for the month plus one, so a deleted piece
--   left a gap and the count stopped tallying with the plan. Now, under the
--   same advisory lock as `ops_next_seq`, trigger `ops_tasks_code_slot`
--   numbers a task as it is made:
--     - a Retainer piece (task_type `engagement`, not a report task) takes
--       the lowest number free from 01 to the month's `planned_count`; none
--       free is refused `plan-full` (with `planned`), so extras are Ad hoc,
--       Goodwill or Special;
--     - any other task takes the lowest free after `planned_count`;
--     - a month with nothing planned numbers from 01, lowest free first.
--   A task whose type moves between Retainer and the others is numbered
--   again the same way. A number typed by hand (`ops_set_code`) stays in its
--   range: a Retainer piece at or under the plan (`plan-range`), any other
--   task over it (`extra-range`). The code is always rebuilt from its month,
--   week and number (`ops_code_of`), so W1 is Week 1, and the title's code
--   follows it. Refusals are raised as the JSON the page reads.
--
-- ROLLBACK
--   drop trigger ops_tasks_code_slot on public.ops_tasks;
--   drop function public.ops_tasks_code_slot();
--   drop function public.ops_code_free(uuid, text, integer, integer, uuid);
--   drop function public.ops_code_retainer(text, text);
-- ===========================================================================

create or replace function public.ops_code_retainer(p_type text, p_source text)
returns boolean
language sql immutable set search_path = public as $$
  select coalesce(p_type, '') = 'engagement'
     and coalesce(p_source, '') not in ('report_social', 'report_ads')
$$;

create or replace function public.ops_code_free(
  p_client uuid, p_period text, p_from integer, p_to integer, p_except uuid)
returns integer
language sql stable set search_path = public as $$
  select min(n)::integer
    from generate_series(p_from, coalesce(p_to, p_from + (
           select count(*)::integer from public.ops_tasks o
            where coalesce(o.client_id, '00000000-0000-0000-0000-000000000000'::uuid)
                = coalesce(p_client, '00000000-0000-0000-0000-000000000000'::uuid)
              and o.code_period = p_period) + 1)) n
   where not exists (
     select 1 from public.ops_tasks o
      where coalesce(o.client_id, '00000000-0000-0000-0000-000000000000'::uuid)
          = coalesce(p_client, '00000000-0000-0000-0000-000000000000'::uuid)
        and o.code_period = p_period and o.code_seq = n
        and o.id is distinct from p_except)
$$;

create or replace function public.ops_tasks_code_slot()
returns trigger
language plpgsql set search_path = public as $$
declare
  v_planned integer;
  v_ret boolean;
  v_n integer;
  v_was text;
begin
  if new.code_seq is null or new.code_period is null or coalesce(new.code, '') = '' then
    return new;
  end if;
  v_was := case when tg_op = 'INSERT' then new.code else old.code end;
  select coalesce(e.planned_count, 0) into v_planned from public.ops_engagements e
   where e.client_id = new.client_id and e.period = new.code_period;
  v_planned := coalesce(v_planned, 0);
  v_ret := public.ops_code_retainer(new.task_type, new.source_type);
  if tg_op = 'INSERT'
     or (new.code_seq = old.code_seq and new.code_period = old.code_period
         and v_ret <> public.ops_code_retainer(old.task_type, old.source_type)) then
    perform pg_advisory_xact_lock(hashtext('ops_code:' || coalesce(new.client_id::text, 'internal') || ':' || new.code_period));
    if v_planned > 0 and v_ret then
      v_n := public.ops_code_free(new.client_id, new.code_period, 1, v_planned, new.id);
      if v_n is null then
        raise exception using message = jsonb_build_object('error', 'plan-full', 'planned', v_planned)::text;
      end if;
    else
      v_n := public.ops_code_free(new.client_id, new.code_period,
               case when v_planned > 0 then v_planned + 1 else 1 end, null, new.id);
    end if;
    new.code_seq := v_n;
  elsif (new.code_seq is distinct from old.code_seq or new.code_period is distinct from old.code_period)
        and v_planned > 0 then
    if v_ret and new.code_seq > v_planned then
      raise exception using message = jsonb_build_object('error', 'plan-range', 'planned', v_planned)::text;
    end if;
    if not v_ret and new.code_seq <= v_planned then
      raise exception using message = jsonb_build_object('error', 'extra-range', 'planned', v_planned)::text;
    end if;
  end if;
  new.code := public.ops_code_of(new.code_period, coalesce(new.code_week, 1), new.code_seq);
  if v_was is not null and new.code is distinct from v_was and left(coalesce(new.title, ''), length(v_was)) = v_was then
    new.title := new.code || substr(new.title, length(v_was) + 1);
  end if;
  return new;
end $$;
revoke all on function public.ops_tasks_code_slot() from public, anon, authenticated;
revoke all on function public.ops_code_free(uuid, text, integer, integer, uuid) from public, anon, authenticated;
revoke all on function public.ops_code_retainer(text, text) from public, anon, authenticated;

create or replace trigger ops_tasks_code_slot
  before insert or update of task_type, code_seq, code_week, code_period on public.ops_tasks
  for each row execute function public.ops_tasks_code_slot();

-- END OF TASK NUMBERS FOLLOW THE PLAN ---------------------------------------

-- ===========================================================================
-- REPORT TASKS FOLLOW THEIR REPORT — the month's Accounts report and
-- Advertising report tasks move with the report they stand for.
-- 2026-10-08. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/ops.js compares the
-- two.
--
-- WHAT CHANGED
--   The user, 2026-10-08: "could the tasks for advertising report and
--   accounts report be linked to the stage of the actual report too (report
--   created, it shifts to in progress assigned to the person who created;
--   report in review stage it goes to waiting until it is out to publish
--   stage whereby its marked as sent to client manually for review then move
--   to reviewing stage.) Done to be marked manually by the assigned users".
--   Trigger `sm_reports_task_follow` (after insert, or an update of status
--   or sent_on, on `sm_reports`) finds the report's task as
--   `sm_report_gate` does (the client's month whose span holds the report's
--   last day, its live `report_{kind}` task) and moves it on the everyday
--   workflow, by `sm_report_task_target`:
--     - a draft: In progress (`doing`); a report just made also makes its
--       maker the task's owner;
--     - in review or confirmed, and published but not yet sent: Waiting;
--     - published and marked as sent: Review.
--   Done stays the owner's own press: a finished or cancelled task is never
--   moved, and nothing moves a task to Done. A white-label brand's report
--   (`brand_id`) leaves the month's task alone. Each move is filed on the
--   task (`stage_changed`, `report_id`, note "Report …"). A refusal or fault
--   never fails the report's own write.
--
-- ROLLBACK
--   drop trigger sm_reports_task_follow on public.sm_reports;
--   drop function public.sm_reports_task_follow();
--   drop function public.sm_report_task_target(text, date);
-- ===========================================================================

create or replace function public.sm_report_task_target(p_status text, p_sent date)
returns text
language sql immutable set search_path = public as $$
  select case
    when p_status = 'draft' then 'doing'
    when p_status in ('review', 'confirmed') then 'waiting'
    when p_status = 'published' and p_sent is null then 'waiting'
    when p_status = 'published' then 'review'
  end
$$;

create or replace function public.sm_reports_task_follow()
returns trigger
language plpgsql security definer set search_path = public as $$
declare
  e public.ops_engagements;
  t public.ops_tasks;
  v_to text;
  v_was uuid;
  v_note text;
begin
  if new.brand_id is not null then return null; end if;
  if tg_op = 'UPDATE' and new.status is not distinct from old.status
     and new.sent_on is not distinct from old.sent_on then
    return null;
  end if;
  v_to := public.sm_report_task_target(new.status, new.sent_on);
  if v_to is null then return null; end if;
  select x.* into e from public.ops_engagements x
   cross join lateral public.ops_month_span(x.period, x.start_day) s
   where x.client_id = new.client_id and x.status <> 'cancelled'
     and new.period_end between s.starts and s.ends
   order by x.period desc limit 1;
  if e.id is null then return null; end if;
  select * into t from public.ops_tasks x
   where x.engagement_id = e.id and x.source_type = 'report_' || new.kind
     and x.cancelled_at is null and x.archived_at is null
   order by x.created_at desc limit 1
   for update;
  if t.id is null or t.completed_at is not null then return null; end if;

  if tg_op = 'INSERT' and new.created_by is not null then
    select team_member_id into v_was from public.ops_task_assignees
     where task_id = t.id and responsibility = 'owner' and ended_at is null;
    if v_was is distinct from new.created_by then
      update public.ops_task_assignees set ended_at = now()
       where task_id = t.id and responsibility = 'owner' and ended_at is null;
      insert into public.ops_task_assignees (task_id, team_member_id, responsibility, assigned_by)
      values (t.id, new.created_by, 'owner', new.created_by);
      perform public.ops_log(t.id, 'assignment_changed',
        jsonb_build_object('owner_id', v_was), jsonb_build_object('owner_id', new.created_by),
        jsonb_build_object('report', true, 'report_id', new.id, 'stage_key', t.stage_key));
    end if;
  end if;

  if t.stage_key is distinct from v_to then
    v_note := case
      when tg_op = 'INSERT' then 'Report started'
      when new.status = 'draft' then 'Report back in draft'
      when new.status = 'review' then 'Report submitted for review'
      when new.status = 'confirmed' then 'Report confirmed'
      when new.sent_on is null then 'Report published'
      else 'Report sent to the client' end;
    update public.ops_tasks set stage_key = v_to, version = version + 1, updated_at = now(),
           completed_at = null, blocked_at = null, blocked_category = null
     where id = t.id;
    perform public.ops_log(t.id, 'stage_changed',
      jsonb_build_object('stage_key', t.stage_key), jsonb_build_object('stage_key', v_to),
      jsonb_build_object('note', v_note, 'report_id', new.id));
  elsif tg_op = 'INSERT' then
    update public.ops_tasks set version = version + 1, updated_at = now() where id = t.id;
  end if;
  return null;
exception when others then
  return null;
end $$;
revoke all on function public.sm_reports_task_follow() from public, anon, authenticated;
revoke all on function public.sm_report_task_target(text, date) from public, anon, authenticated;

create or replace trigger sm_reports_task_follow
  after insert or update of status, sent_on on public.sm_reports
  for each row execute function public.sm_reports_task_follow();

-- END OF REPORT TASKS FOLLOW THEIR REPORT ------------------------------------

-- ===========================================================================
-- A NOON REMINDER TO ADD TASKS — on a weekday at 12:00 MYT, a colleague with
-- no open task, or who has never added one, is reminded to add their work.
-- 2026-10-08. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/ops.js compares the
-- two.
--
-- WHAT CHANGED
--   The user, 2026-10-08: "if the account has either totally no tasks under
--   or not created any tasks, sent a reminder daily during weekday at noon to
--   remind to add tasks (admins excluded)".
--   1. `ops_tasks_remind(p_today)` (no caller but pg_cron; revoked from every
--      login): on Monday to Friday (MYT) each active colleague who is not an
--      admin is told once that day (kind `tasks.empty`, `dedupe_key`
--      `tasks.remind.{member}.{day}`), when no open task is assigned to
--      them, or when they have never added a task. Answers how many were
--      told.
--   2. pg_cron `tasks-reminder` runs it at 04:00 UTC (12:00 MYT), Monday to
--      Friday.
--   3. `ops_notifications_push` opens My Work for `tasks.empty` and tags it
--      `tasks-empty`, so a second day's reminder replaces the first.
--
-- ROLLBACK
--   select cron.unschedule('tasks-reminder');
--   drop function public.ops_tasks_remind(date);
--   (ops_notifications_push: re-run the MY HR REMINDERS section.)
-- ===========================================================================

create or replace function public.ops_tasks_remind(p_today date default null)
returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_today date := coalesce(p_today, (now() at time zone 'Asia/Kuala_Lumpur')::date);
  m record;
  v_open boolean;
  v_made boolean;
  n integer := 0;
begin
  if extract(isodow from v_today) > 5 then return 0; end if;
  for m in select t.id from public.team_members t
            where t.active and not coalesce(t.is_admin, false) and coalesce(t.role, '') <> 'admin'
            order by t.id loop
    v_open := exists (select 1 from public.ops_task_assignees a
                        join public.ops_tasks k on k.id = a.task_id
                       where a.team_member_id = m.id and a.responsibility = 'owner' and a.ended_at is null
                         and k.completed_at is null and k.cancelled_at is null and k.archived_at is null);
    v_made := exists (select 1 from public.ops_tasks k where k.created_by = m.id);
    if v_open and v_made then continue; end if;
    insert into public.ops_notifications (team_member_id, task_id, kind, title, body, dedupe_key)
    values (m.id, null, 'tasks.empty',
            case when not v_open then 'No open tasks are assigned to you. Add the work you are on in My Work.'
                 else 'Add the tasks you are working on in My Work.' end,
            null, 'tasks.remind.' || m.id || '.' || v_today)
    on conflict (dedupe_key) do nothing;
    n := n + 1;
  end loop;
  return n;
end $$;
revoke all on function public.ops_tasks_remind(date) from public, anon, authenticated;

create or replace function public.ops_notifications_push()
returns trigger
language plpgsql security definer set search_path = public as $$
declare
  v_title text := coalesce(nullif(btrim(new.title), ''), 'My Work');
  v_body  text := coalesce(new.body, '');
begin
  perform public.push_queue('team', new.team_member_id,
    jsonb_build_object('en', jsonb_build_object('title', v_title, 'body', v_body),
                       'zh', jsonb_build_object('title', v_title, 'body', v_body)),
    case when new.task_id is not null then '/admin/?s=work&open=' || new.task_id::text
         when new.report_id is not null then '/admin/?s=reports&report=' || new.report_id::text
         when new.kind in ('client_left', 'tasks.empty') then '/admin/?s=work'
         when new.kind = 'hr.letter' then '/admin/?s=mine&view=letters'
         when new.kind = 'perf.disputed' then '/admin/?s=team&tab=performance'
         when new.kind = 'perf.reflect' then '/admin/?s=mine&view=reflection'
         when new.kind = 'perf.initiative' then '/admin/?s=mine&view=initiatives'
         when new.kind like 'health.%' then '/admin/?s=mine&view=health'
         when new.kind like 'perf.%' then '/admin/?s=mine'
         else '/admin/' end,
    case when new.task_id is not null then 'task-' || new.task_id::text
         when new.report_id is not null then 'report-' || new.report_id::text
         when new.kind = 'hr.letter' then 'hr-letter'
         when new.kind in ('perf.remind', 'perf.reflect', 'health.remind') then 'my-hr'
         when new.kind = 'tasks.empty' then 'tasks-empty'
         else null end);
  return new;
exception when others then
  return new;
end $$;

do $$
begin
  if not exists (select 1 from pg_extension where extname = 'pg_cron') then
    raise notice 'pg_cron is not enabled: no task reminders go out until it is.';
    return;
  end if;
  perform cron.unschedule(j.jobid) from cron.job j where j.jobname = 'tasks-reminder';
  perform cron.schedule('tasks-reminder', '0 4 * * 1-5', 'select public.ops_tasks_remind()');
end $$;

-- END OF A NOON REMINDER TO ADD TASKS ----------------------------------------

-- ===========================================================================
-- SYSTEM ACCOUNT — a login kept for IT and development: a full admin that
-- is never offered for work, and that no other admin can stand down, expire
-- or move.
-- 2026-10-08. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/team.js compares the
-- two.
--
-- WHAT CHANGED
--   The user, 2026-10-08: "disable users from selecting one admin on assigned
--   to or all others, as this account is used for system IT development only
--   … its own account wouldn't be restricted".
--   1. `team_members.system` (false by default). It is set only from the SQL
--      editor or the connector (no sign-in on the call); a browser that tries
--      is refused `system-account`. Which account is set is data, never this
--      file.
--   2. Trigger `team_members_system_guard` (before update): on a system
--      account, only the account itself changes whether it is active, its
--      access date and time, its group, its admin mark or its email; anyone
--      else is refused `system-account`. A cascade from its group
--      (`pg_trigger_depth() > 1`) and a call with no sign-in (the access
--      sweep, the SQL editor) pass.
--   3. `team_set_expiry_at` (Set access expiry for everyone) leaves system
--      accounts out.
--   4. `sm_report_may_review` never names a system account, so it is never
--      offered as a report's reviewer.
--   The console's pickers leave it out (`ADspaceAdmin.isSystem`); Team shows
--   it with a System tag and no ⋯ for anyone else.
--
-- ROLLBACK
--   drop trigger team_members_system_guard on public.team_members;
--   drop function public.team_members_system_guard();
--   alter table public.team_members drop column system;
--   (team_set_expiry_at and sm_report_may_review: re-run their sections.)
-- ===========================================================================

alter table public.team_members add column if not exists system boolean not null default false;

create or replace function public.team_members_system_guard()
returns trigger
language plpgsql set search_path = public as $$
declare
  who text := lower(coalesce(auth.jwt() ->> 'email', ''));
begin
  if who = '' or pg_trigger_depth() > 1 then return new; end if;
  if new.system is distinct from old.system then
    raise exception 'system-account' using hint = 'A system account is set from the database.';
  end if;
  if old.system and lower(old.email) <> who and (
       new.active is distinct from old.active
    or new.access_until is distinct from old.access_until
    or new.access_until_time is distinct from old.access_until_time
    or new.role is distinct from old.role
    or new.is_admin is distinct from old.is_admin
    or lower(new.email) is distinct from lower(old.email)) then
    raise exception 'system-account' using hint = 'This is a system account.';
  end if;
  return new;
end $$;
revoke all on function public.team_members_system_guard() from public, anon, authenticated;

create or replace trigger team_members_system_guard before update on public.team_members
  for each row execute function public.team_members_system_guard();

create or replace function public.team_set_expiry_at(p_until date, p_time time)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  who text := lower(coalesce(auth.jwt() ->> 'email', ''));
  v_time time := case when p_until is null then null else p_time end;
  n int;
begin
  if not public.allowed('team', 'manage') then return jsonb_build_object('error', 'denied'); end if;
  if p_until is not null and public.team_access_ends(p_until, v_time) <= now() then
    return jsonb_build_object('error', 'past-date');
  end if;
  update public.team_members t set access_until = p_until, access_until_time = v_time
   where t.active and lower(t.email) <> who and not t.system
     and (t.access_until is distinct from p_until or t.access_until_time is distinct from v_time);
  get diagnostics n = row_count;
  if n > 0 then
    insert into public.activity_log (actor, action, subject, detail)
    values (who, 'team.changed', 'Team',
            'Access until ' || coalesce(public.team_access_word(p_until, v_time), 'not set')
            || ' for ' || n || case when n = 1 then ' colleague' else ' colleagues' end);
  end if;
  return jsonb_build_object('ok', true, 'count', n);
end $$;
grant execute on function public.team_set_expiry_at(date, time) to authenticated;

create or replace function public.sm_report_may_review(p_member uuid)
returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.team_members m
     where m.id = p_member and m.active and not m.system
       and (coalesce(m.is_admin, false) or m.role = 'admin'
            or public.level_rank(coalesce(m.access ->> 'reports', 'none')) >= public.level_rank('manage')))
$$;
revoke all on function public.sm_report_may_review(uuid) from public, anon, authenticated;

-- END OF SYSTEM ACCOUNT -------------------------------------------------------

-- ===========================================================================
-- META LINKS — which of Meta's ad accounts, Page and Instagram account a
-- client's reports are read from (Import from Meta).
-- 2026-10-08. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/smsql.js compares the
-- two. Runs after WHITE LABEL BRANDS.
--
-- WHAT CHANGED (the user, 2026-10-08: "1 2 ok", "4 meta marketing api ok")
--   ADspace works in its own Meta business portfolio, and clients share
--   their ad accounts, Pages and Instagram accounts with it as a partner. A
--   client, and each of a white-label client's brands, links one or more ad
--   accounts, one Facebook Page and one Instagram account, picked from what
--   the system user can see (the `meta-import` edge function's `assets`),
--   never typed. Each pick keeps Meta's id and the name Meta gives it.
--   1. `meta_links` (RLS on, no policy, no grant): one row a client and brand
--      (the client's own has no brand); `ad_accounts` a list, `page` and
--      `instagram` one each, `{ id, name }`. Removed with its client or
--      brand; never removed by hand (an empty pick is kept as empty).
--   2. `meta_links_list(p_client)`: every row of the client (Reports or
--      Clients at View, the client in scope).
--   3. `meta_links_save(p_client, p_brand, p_ad_accounts, p_page,
--      p_instagram)`: Clients at Work with the client in scope at Work; the
--      brand the client's (`bad-brand`); ids digits only, at most 20 ad
--      accounts (`bad-asset`). Filed `client.brand` from and to; a save that
--      changed nothing files nothing.
--
-- ROLLBACK
--   drop function if exists public.meta_links_save(uuid, uuid, jsonb, jsonb, jsonb);
--   drop function if exists public.meta_links_list(uuid);
--   drop table if exists public.meta_links;
-- ===========================================================================

create table if not exists public.meta_links (
  id          uuid primary key default gen_random_uuid(),
  client_id   uuid not null references public.clients(id) on delete cascade,
  brand_id    uuid references public.client_brands(id) on delete cascade,
  ad_accounts jsonb not null default '[]'::jsonb,
  page        jsonb,
  instagram   jsonb,
  updated_at  timestamptz not null default now(),
  updated_by  text
);
create unique index if not exists meta_links_client_brand_idx
  on public.meta_links (client_id, coalesce(brand_id, '00000000-0000-0000-0000-000000000000'::uuid));
alter table public.meta_links enable row level security;
revoke all on public.meta_links from public, anon, authenticated;

create or replace function public.meta_links_list(p_client uuid)
returns jsonb
language plpgsql security definer stable set search_path = public as $$
begin
  if not (public.allowed('reports', 'view') or public.allowed('clients', 'view')) then
    return jsonb_build_object('error', 'denied');
  end if;
  if not public.client_seen(p_client, 'view') then return jsonb_build_object('error', 'denied'); end if;
  return jsonb_build_object('links', coalesce((
    select jsonb_agg(jsonb_build_object('brand_id', l.brand_id, 'ad_accounts', l.ad_accounts,
             'page', l.page, 'instagram', l.instagram) order by l.brand_id nulls first)
      from public.meta_links l where l.client_id = p_client), '[]'::jsonb));
end $$;
revoke all on function public.meta_links_list(uuid) from public, anon;
grant execute on function public.meta_links_list(uuid) to authenticated;

-- One asset as kept: Meta's id (digits) and its name, else null.
create or replace function public.meta_asset_of(p jsonb)
returns jsonb
language sql immutable set search_path = public as $$
  select case
    when p is null or jsonb_typeof(p) <> 'object' or coalesce(p ->> 'id', '') = '' then null
    when (p ->> 'id') !~ '^[0-9]{3,30}$' then jsonb_build_object('bad', true)
    else jsonb_build_object('id', p ->> 'id',
           'name', left(coalesce(nullif(btrim(p ->> 'name'), ''), p ->> 'id'), 200))
  end
$$;
revoke all on function public.meta_asset_of(jsonb) from public, anon, authenticated;

-- How a pick reads in the record: the names, else "not set".
create or replace function public.meta_names(p jsonb)
returns text
language sql immutable set search_path = public as $$
  select coalesce(nullif(case jsonb_typeof(p)
    when 'array' then (select string_agg(e ->> 'name', ', ' order by o) from jsonb_array_elements(p) with ordinality as x(e, o))
    when 'object' then p ->> 'name' end, ''), 'not set')
$$;
revoke all on function public.meta_names(jsonb) from public, anon, authenticated;

create or replace function public.meta_links_save(p_client uuid, p_brand uuid, p_ad_accounts jsonb, p_page jsonb, p_instagram jsonb)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  v_client text;
  v_brand text;
  v_accs jsonb := '[]'::jsonb;
  v_page jsonb := public.meta_asset_of(p_page);
  v_ig jsonb := public.meta_asset_of(p_instagram);
  e jsonb;
  a jsonb;
  v_old public.meta_links;
  v_detail text;
begin
  if me.id is null or not public.allowed('clients', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if not public.client_seen(p_client, 'work') then return jsonb_build_object('error', 'denied'); end if;
  select c.name into v_client from public.clients c where c.id = p_client;
  if v_client is null then return jsonb_build_object('error', 'not-found'); end if;
  if p_brand is not null then
    select b.name into v_brand from public.client_brands b where b.id = p_brand and b.client_id = p_client;
    if v_brand is null then return jsonb_build_object('error', 'bad-brand'); end if;
  end if;
  if p_ad_accounts is not null and jsonb_typeof(p_ad_accounts) <> 'array' then return jsonb_build_object('error', 'bad-asset'); end if;
  for e in select x from jsonb_array_elements(coalesce(p_ad_accounts, '[]'::jsonb)) as t(x) loop
    a := public.meta_asset_of(e);
    if a is null or a ? 'bad' then return jsonb_build_object('error', 'bad-asset'); end if;
    if not exists (select 1 from jsonb_array_elements(v_accs) as y(z) where y.z ->> 'id' = a ->> 'id') then
      v_accs := v_accs || jsonb_build_array(a);
    end if;
  end loop;
  if jsonb_array_length(v_accs) > 20 or coalesce(v_page ? 'bad', false) or coalesce(v_ig ? 'bad', false) then
    return jsonb_build_object('error', 'bad-asset');
  end if;
  select * into v_old from public.meta_links l
   where l.client_id = p_client and l.brand_id is not distinct from p_brand for update;
  if v_old.id is not null and v_old.ad_accounts = v_accs and v_old.page is not distinct from v_page and v_old.instagram is not distinct from v_ig then
    return jsonb_build_object('ok', true);
  end if;
  if v_old.id is null and jsonb_array_length(v_accs) = 0 and v_page is null and v_ig is null then
    return jsonb_build_object('ok', true);
  end if;
  v_detail := concat_ws(' · ',
    case when coalesce(v_old.ad_accounts, '[]'::jsonb) <> v_accs
         then 'Meta ad accounts: ' || public.meta_names(v_old.ad_accounts) || ' → ' || public.meta_names(v_accs) end,
    case when v_old.page is distinct from v_page
         then 'Facebook Page: ' || public.meta_names(v_old.page) || ' → ' || public.meta_names(v_page) end,
    case when v_old.instagram is distinct from v_ig
         then 'Instagram: ' || public.meta_names(v_old.instagram) || ' → ' || public.meta_names(v_ig) end);
  if v_old.id is null then
    insert into public.meta_links (client_id, brand_id, ad_accounts, page, instagram, updated_by)
    values (p_client, p_brand, v_accs, v_page, v_ig, me.name);
  else
    update public.meta_links set ad_accounts = v_accs, page = v_page, instagram = v_ig,
           updated_at = now(), updated_by = me.name
     where id = v_old.id;
  end if;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'client.brand', v_client, case when v_brand is not null then v_brand || ': ' else '' end || v_detail);
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.meta_links_save(uuid, uuid, jsonb, jsonb, jsonb) from public, anon;
grant execute on function public.meta_links_save(uuid, uuid, jsonb, jsonb, jsonb) to authenticated;

-- END OF META LINKS ---------------------------------------------------------

-- ===========================================================================
-- CAPTION WRITER AND AI COST — Write caption in Content Review, counted apart
-- from the reports' AI uses, and every AI call's tokens kept with an
-- estimated cost a month.
-- 2026-10-08. Safe to run twice. Rollback below. Mirrored byte for byte in
-- supabase/schema.sql under the same banner; tests/smsql.js compares the two.
--
-- WHAT CHANGED (the user, 2026-10-08: "1 2 ok", "Also check costing")
--   1. `ai_drafts.purpose` takes `caption`; a caption's row names its set
--      (`batch_id`) and client. Every row keeps what the call cost:
--      `input_tokens`, `output_tokens` and `model`.
--   2. `ai_caption_claim(p_batch)`: Content Review: Sets at Work, a set on a
--      client the colleague sees. Counted by the colleague a day, from
--      midnight MYT: `caption` (20) a colleague's, `caption_admin` (40) an
--      admin's, both settings in `ai_draft_limits`; 0 stops it.
--      `ai_caption_left()` reads what is left without writing.
--   3. Captions never take from the reports' limits: `ai_draft_claim`,
--      `ai_draft_left`, `ai_check_claim` and `ai_check_left` count the day's
--      uses without them.
--   4. `ai_draft_tokens(p_id, p_in, p_out, p_model)`: the edge function
--      records the call's tokens on its own row, once, drafted or failed.
--   5. `ai_price_in` (4) and `ai_price_out` (20), US$ a million tokens, are
--      Business settings from a day on (`app_settings_set`).
--   6. `ai_draft_usage()` adds the caption limits, each colleague's captions
--      today, and this month's tokens and estimated cost by purpose, each
--      row priced at the prices of its own day.
--   7. `ai_draft_set_limit` names `caption` and `caption_admin`.
--
-- ROLLBACK
--   Run the AI LIMITS A COLLEAGUE A REPORT A DAY section and the latest
--   app_settings_set, ai_draft_usage and ai_draft_set_limit (ADMIN PARTS)
--   again; then, in the SQL Editor, drop ai_caption_claim(uuid),
--   ai_caption_left() and ai_draft_tokens(uuid, integer, integer, text),
--   delete the caption rows from ai_drafts and put the purpose check back to
--   ('draft', 'check'). The columns and the price settings may stay.
-- ===========================================================================

alter table public.ai_drafts add column if not exists batch_id uuid;
alter table public.ai_drafts add column if not exists input_tokens integer;
alter table public.ai_drafts add column if not exists output_tokens integer;
alter table public.ai_drafts add column if not exists model text;
alter table public.ai_drafts drop constraint if exists ai_drafts_purpose;
alter table public.ai_drafts add constraint ai_drafts_purpose check (purpose in ('draft', 'check', 'caption'));
create index if not exists ai_drafts_purpose_idx on public.ai_drafts (team_member_id, purpose, created_at);

insert into public.app_settings (key, from_date, value)
select k.key, date '2026-10-08', k.value
  from (values ('ai_price_in', 4), ('ai_price_out', 20)) k(key, value)
 where not exists (select 1 from public.app_settings s where s.key = k.key);

create or replace function public.app_settings_set(p_from date, p_values jsonb)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me public.team_members; v_k text; v_v numeric; v_was numeric; v_name text; v_unit text;
  v_today date := (now() at time zone 'Asia/Kuala_Lumpur')::date;
  v_keys constant text[] := array['lead_followup_hours', 'proposal_followup_days', 'sst_pct',
    'term_1_3', 'term_4_5', 'term_6_11', 'term_12_23', 'term_24', 'report_due_days', 'revision_due_days',
    'ai_price_in', 'ai_price_out'];
  v_moved text[] := '{}';
begin
  if not public.ops_granted('team.settings', 'work') then return jsonb_build_object('error', 'denied'); end if;
  v_me := public.ops_me();
  if p_from is null or p_from < v_today then return jsonb_build_object('error', 'past', 'today', v_today); end if;
  if jsonb_typeof(p_values) is distinct from 'object' then return jsonb_build_object('error', 'bad-value'); end if;
  for v_k in select jsonb_object_keys(p_values) loop
    if not (v_k = any(v_keys)) or jsonb_typeof(p_values -> v_k) <> 'number' then
      return jsonb_build_object('error', 'bad-value', 'key', v_k);
    end if;
    v_v := (p_values ->> v_k)::numeric;
    if round(v_v, 2) <> v_v
       or (v_k = 'lead_followup_hours' and (v_v < 1 or v_v > 720 or v_v <> trunc(v_v)))
       or (v_k = 'proposal_followup_days' and (v_v < 1 or v_v > 365 or v_v <> trunc(v_v)))
       or (v_k = 'report_due_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'revision_due_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'sst_pct' and (v_v < 0 or v_v > 100))
       or (v_k like 'term_%' and (v_v < -100 or v_v > 100))
       or (v_k like 'ai_price_%' and (v_v < 0 or v_v > 1000)) then
      return jsonb_build_object('error', 'bad-value', 'key', v_k);
    end if;
  end loop;
  for v_k in select jsonb_object_keys(p_values) loop
    v_v := (p_values ->> v_k)::numeric;
    v_was := public.app_setting(v_k, p_from);
    if v_was is distinct from v_v then
      insert into public.app_settings (key, from_date, value, set_by, set_at)
      values (v_k, p_from, v_v, v_me.id, now())
      on conflict (key, from_date) do update set value = excluded.value, set_by = excluded.set_by, set_at = now();
      v_name := case v_k when 'lead_followup_hours' then 'A lead waits' when 'proposal_followup_days' then 'A proposal waits'
        when 'sst_pct' then 'SST' when 'term_1_3' then '1 to 3 months' when 'term_4_5' then '4 and 5 months'
        when 'term_6_11' then '6 to 11 months' when 'term_12_23' then '12 to 23 months' when 'term_24' then '24 months and more'
        when 'revision_due_days' then 'Revision due' when 'ai_price_in' then 'AI input, a million tokens'
        when 'ai_price_out' then 'AI output, a million tokens' else 'Report due' end;
      v_unit := case when v_k = 'lead_followup_hours' then ' hours' when v_k in ('proposal_followup_days', 'report_due_days', 'revision_due_days') then ' days'
        else '%' end;
      insert into public.activity_log (actor, action, subject, detail)
      values (coalesce(v_me.name, 'admin'), 'team.changed', 'Settings',
              v_name || ': ' || case when v_k like 'ai_price_%' then 'US$' else '' end ||
              trim(to_char(v_was, 'FM999999990.99'), '.') || case when v_k like 'ai_price_%' then '' else v_unit end || ' → ' ||
              case when v_k like 'ai_price_%' then 'US$' else '' end ||
              trim(to_char(v_v, 'FM999999990.99'), '.') || case when v_k like 'ai_price_%' then '' else v_unit end ||
              ' · from ' || public.register_day(p_from));
      v_moved := v_moved || v_k;
    end if;
  end loop;
  return public.app_settings_read() || jsonb_build_object('changed', to_jsonb(v_moved));
end $$;
revoke all on function public.app_settings_set(date, jsonb) from public, anon;

-- A caption: the colleague's own count a day, apart from the reports'.
create or replace function public.ai_caption_claim(p_batch uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m public.team_members;
  b public.batches;
  since timestamptz := public.ai_draft_day();
  n_cap integer;
  lim integer;
  new_id uuid;
begin
  if not public.allowed('review.sets', 'work') then return jsonb_build_object('error', 'denied'); end if;
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'denied'); end if;
  select * into b from public.batches x where x.id = p_batch;
  if b.id is null or not public.client_seen(b.client_id, 'view') then
    return jsonb_build_object('error', 'not-found');
  end if;
  -- One count at a time, with the drafts, so the last caption is taken once.
  perform pg_advisory_xact_lock(hashtext('ai_draft_claim'));
  lim := case when coalesce(m.is_admin, false) or m.role = 'admin'
              then public.ai_draft_limit('caption_admin', 40) else public.ai_draft_limit('caption', 20) end;
  if lim = 0 then return jsonb_build_object('error', 'ai-limit', 'scope', 'stopped', 'limit', 0); end if;
  select count(*) into n_cap from public.ai_drafts d
   where d.team_member_id = m.id and d.purpose = 'caption' and d.created_at >= since and d.outcome <> 'failed';
  if n_cap >= lim then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'caption', 'limit', lim, 'next', since + interval '1 day');
  end if;
  insert into public.ai_drafts (team_member_id, client_id, batch_id, purpose)
  values (m.id, b.client_id, b.id, 'caption') returning id into new_id;
  return jsonb_build_object('id', new_id, 'left', lim - n_cap - 1, 'limit', lim);
end $$;

-- What Write caption has left today, read without writing.
create or replace function public.ai_caption_left()
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  m public.team_members;
  since timestamptz := public.ai_draft_day();
  lim integer;
  l_left integer;
begin
  if not public.allowed('review.sets', 'work') then return jsonb_build_object('error', 'denied'); end if;
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'denied'); end if;
  lim := case when coalesce(m.is_admin, false) or m.role = 'admin'
              then public.ai_draft_limit('caption_admin', 40) else public.ai_draft_limit('caption', 20) end;
  l_left := greatest(0, lim - (select count(*) from public.ai_drafts d
    where d.team_member_id = m.id and d.purpose = 'caption' and d.created_at >= since and d.outcome <> 'failed')::integer);
  return jsonb_build_object('left', l_left, 'limit', lim, 'scope', case when lim = 0 then 'stopped' else 'caption' end,
    'next', case when l_left > 0 or lim = 0 then null else since + interval '1 day' end);
end $$;

-- What a call cost, on the caller's own row, once.
create or replace function public.ai_draft_tokens(p_id uuid, p_in integer, p_out integer, p_model text)
returns void
language sql security definer set search_path = public as $$
  update public.ai_drafts d
     set input_tokens = greatest(0, coalesce(p_in, 0)),
         output_tokens = greatest(0, coalesce(p_out, 0)),
         model = left(nullif(btrim(coalesce(p_model, '')), ''), 80)
   where d.id = p_id and d.input_tokens is null
     and d.team_member_id = (public.ops_me()).id
$$;

revoke all on function public.ai_caption_claim(uuid) from public, anon, authenticated;
revoke all on function public.ai_caption_left() from public, anon, authenticated;
revoke all on function public.ai_draft_tokens(uuid, integer, integer, text) from public, anon, authenticated;
grant execute on function public.ai_caption_claim(uuid) to authenticated;
grant execute on function public.ai_caption_left() to authenticated;
grant execute on function public.ai_draft_tokens(uuid, integer, integer, text) to authenticated;

create or replace function public.ai_draft_claim(p_report uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m public.team_members;
  r public.sm_reports;
  since timestamptz := public.ai_draft_day();
  n_report integer;
  n_member integer;
  lim_member integer;
  lim_report integer;
  new_id uuid;
begin
  if not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'denied'); end if;
  -- One count at a time, so two presses together cannot both take the last draft.
  perform pg_advisory_xact_lock(hashtext('ai_draft_claim'));
  select * into r from public.sm_reports where id = p_report;
  lim_member := public.ai_day_cap(m);
  if lim_member = 0 then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'stopped', 'limit', 0);
  end if;
  lim_report := case when coalesce(m.is_admin, false) then public.ai_draft_limit('report_admin', 5)
                     else public.ai_draft_limit('report', 1) end;
  select count(*) into n_report from public.ai_draft_same(p_report) s
   where s.team_member_id = m.id and s.created_at >= since;
  if n_report >= lim_report then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'report', 'limit', lim_report, 'next', since + interval '1 day');
  end if;
  select count(*) into n_member from public.ai_drafts d
   where d.team_member_id = m.id and d.created_at >= since and d.outcome <> 'failed' and d.purpose <> 'caption';
  if n_member >= lim_member then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'person', 'limit', lim_member, 'next', since + interval '1 day');
  end if;
  insert into public.ai_drafts (report_id, team_member_id, client_id, kind, period_start, period_end, version_no)
  values (p_report, m.id, r.client_id, r.kind, r.period_start, r.period_end, r.version_no) returning id into new_id;
  return jsonb_build_object('id', new_id, 'left', lim_member - n_member - 1);
end $$;

create or replace function public.ai_draft_left(p_report uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  m public.team_members;
  since timestamptz := public.ai_draft_day();
  is_adm boolean;
  n_member integer;
  l_report integer; l_member integer; l_min integer;
  lim_member integer;
  lim_report integer;
  v_scope text;
begin
  if not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'denied'); end if;
  is_adm := coalesce(m.is_admin, false);
  lim_member := public.ai_day_cap(m);
  lim_report := case when is_adm then public.ai_draft_limit('report_admin', 5) else public.ai_draft_limit('report', 1) end;
  l_report := greatest(0, lim_report - (select count(*) from public.ai_draft_same(p_report) s
    where s.team_member_id = m.id and s.created_at >= since)::integer);
  select count(*) into n_member from public.ai_drafts d
   where d.team_member_id = m.id and d.created_at >= since and d.outcome <> 'failed' and d.purpose <> 'caption';
  l_member := greatest(0, lim_member - n_member);
  l_min := least(l_report, l_member);
  v_scope := case when lim_member = 0 then 'stopped' when l_min = l_report then 'report' else 'person' end;
  return jsonb_build_object(
    'left', l_min, 'scope', v_scope,
    'limit', case v_scope when 'stopped' then 0 when 'report' then lim_report else lim_member end,
    'report', l_report, 'person', l_member, 'admin', is_adm,
    'next', case when l_min > 0 or v_scope = 'stopped' then null else since + interval '1 day' end);
end $$;

create or replace function public.ai_check_claim(p_report uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m public.team_members;
  r public.sm_reports;
  since timestamptz := public.ai_draft_day();
  n_member integer;
  lim_member integer;
  lim_check integer;
  new_id uuid;
begin
  if not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_report;
  if r.id is null or not public.client_seen(r.client_id, 'view') then
    return jsonb_build_object('error', 'not-found');
  end if;
  if r.status not in ('draft', 'review') then return jsonb_build_object('error', 'not-open'); end if;
  -- One count at a time, with the drafts, so the last use is taken once.
  perform pg_advisory_xact_lock(hashtext('ai_draft_claim'));
  lim_member := public.ai_day_cap(m);
  if lim_member = 0 then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'stopped', 'limit', 0);
  end if;
  lim_check := case when coalesce(m.is_admin, false) then public.ai_draft_limit('check_admin', 5)
                    else public.ai_draft_limit('check', 1) end;
  if (select count(*) from public.ai_drafts d
       where d.report_id = p_report and d.purpose = 'check' and d.outcome <> 'failed'
         and d.team_member_id = m.id and d.created_at >= since) >= lim_check then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'report_check', 'limit', lim_check, 'next', since + interval '1 day');
  end if;
  select count(*) into n_member from public.ai_drafts d
   where d.team_member_id = m.id and d.created_at >= since and d.outcome <> 'failed' and d.purpose <> 'caption';
  if n_member >= lim_member then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'person', 'limit', lim_member, 'next', since + interval '1 day');
  end if;
  insert into public.ai_drafts (report_id, team_member_id, client_id, kind, period_start, period_end, purpose, version_no)
  values (p_report, m.id, r.client_id, r.kind, r.period_start, r.period_end, 'check', r.version_no) returning id into new_id;
  return jsonb_build_object('id', new_id, 'left', lim_member - n_member - 1);
end $$;

create or replace function public.ai_check_left(p_report uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  m public.team_members;
  r public.sm_reports;
  since timestamptz := public.ai_draft_day();
  is_adm boolean;
  n_member integer;
  l_report integer; l_member integer; l_min integer;
  lim_member integer;
  lim_check integer;
  v_scope text;
begin
  if not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_report;
  if r.id is null or not public.client_seen(r.client_id, 'view') then
    return jsonb_build_object('error', 'not-found');
  end if;
  is_adm := coalesce(m.is_admin, false);
  lim_member := public.ai_day_cap(m);
  lim_check := case when is_adm then public.ai_draft_limit('check_admin', 5) else public.ai_draft_limit('check', 1) end;
  l_report := greatest(0, lim_check - (select count(*) from public.ai_drafts d
    where d.report_id = p_report and d.purpose = 'check' and d.outcome <> 'failed'
      and d.team_member_id = m.id and d.created_at >= since)::integer);
  select count(*) into n_member from public.ai_drafts d
   where d.team_member_id = m.id and d.created_at >= since and d.outcome <> 'failed' and d.purpose <> 'caption';
  l_member := greatest(0, lim_member - n_member);
  l_min := least(l_report, l_member);
  v_scope := case when lim_member = 0 then 'stopped' when l_min = l_report then 'report_check' else 'person' end;
  return jsonb_build_object(
    'left', l_min, 'scope', v_scope, 'version', r.version_no,
    'limit', case v_scope when 'stopped' then 0 when 'report_check' then lim_check else lim_member end,
    'report', l_report, 'person', l_member, 'admin', is_adm,
    'next', case when l_min > 0 or v_scope = 'stopped' then null else since + interval '1 day' end);
end $$;

revoke all on function public.ai_draft_claim(uuid) from public, anon, authenticated;
revoke all on function public.ai_draft_left(uuid) from public, anon, authenticated;
revoke all on function public.ai_check_claim(uuid) from public, anon, authenticated;
revoke all on function public.ai_check_left(uuid) from public, anon, authenticated;
grant execute on function public.ai_draft_claim(uuid) to authenticated;
grant execute on function public.ai_draft_left(uuid) to authenticated;
grant execute on function public.ai_check_claim(uuid) to authenticated;
