create or replace function public.ai_draft_usage()
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_day timestamptz := public.ai_draft_day();
  v_month timestamptz := now() - interval '30 days';
  -- This calendar month in Malaysia, for what the calls cost.
  v_cal timestamptz := date_trunc('month', now() at time zone 'Asia/Kuala_Lumpur') at time zone 'Asia/Kuala_Lumpur';
  v_today date := (now() at time zone 'Asia/Kuala_Lumpur')::date;
begin
  if not public.ops_granted('reports.ai', 'work') then return jsonb_build_object('error', 'denied'); end if;
  return jsonb_build_object(
    'person', public.ai_draft_limit('person', 10),
    'admin', public.ai_draft_limit('admin', 20),
    'report', public.ai_draft_limit('report', 1),
    'report_admin', public.ai_draft_limit('report_admin', 5),
    'check', public.ai_draft_limit('check', 1),
    'check_admin', public.ai_draft_limit('check_admin', 5),
    'caption', public.ai_draft_limit('caption', 20),
    'caption_admin', public.ai_draft_limit('caption_admin', 40),
    'cost', (select jsonb_build_object(
        'since', v_cal,
        'price_in', public.app_setting('ai_price_in', v_today),
        'price_out', public.app_setting('ai_price_out', v_today),
        'uses', count(*),
        'untracked', count(*) filter (where c.input_tokens is null),
        'input', coalesce(sum(c.input_tokens), 0),
        'output', coalesce(sum(c.output_tokens), 0),
        'usd', round(coalesce(sum(c.usd), 0), 2),
        'by', coalesce((select jsonb_object_agg(p.purpose, p.x) from (
            select c2.purpose, jsonb_build_object('uses', count(*), 'input', coalesce(sum(c2.input_tokens), 0),
                     'output', coalesce(sum(c2.output_tokens), 0), 'usd', round(coalesce(sum(c2.usd), 0), 2)) as x
              from (select d.purpose, d.input_tokens, d.output_tokens,
                           (coalesce(d.input_tokens, 0) * public.app_setting('ai_price_in', (d.created_at at time zone 'Asia/Kuala_Lumpur')::date)
                          + coalesce(d.output_tokens, 0) * public.app_setting('ai_price_out', (d.created_at at time zone 'Asia/Kuala_Lumpur')::date)) / 1000000.0 as usd
                      from public.ai_drafts d where d.created_at >= v_cal and (d.outcome <> 'failed' or d.input_tokens is not null)) c2
             group by c2.purpose) p), '{}'::jsonb))
      from (select d.input_tokens, d.output_tokens,
                   (coalesce(d.input_tokens, 0) * public.app_setting('ai_price_in', (d.created_at at time zone 'Asia/Kuala_Lumpur')::date)
                  + coalesce(d.output_tokens, 0) * public.app_setting('ai_price_out', (d.created_at at time zone 'Asia/Kuala_Lumpur')::date)) / 1000000.0 as usd
              from public.ai_drafts d where d.created_at >= v_cal and (d.outcome <> 'failed' or d.input_tokens is not null)) c),
    'resets_at', v_day + interval '1 day',
    'people', coalesce((select jsonb_agg(s.x order by s.x ->> 'name') from (
      select jsonb_build_object(
        'id', t.id, 'name', t.name, 'code', t.staff_code, 'group', g.name, 'group_slug', t.role,
        'admin', coalesce(t.is_admin, false) or t.role = 'admin',
        'day', (select count(*) from public.ai_drafts d where d.team_member_id = t.id and d.created_at >= v_day and d.outcome <> 'failed' and d.purpose <> 'caption'),
        'captions', (select count(*) from public.ai_drafts d where d.team_member_id = t.id and d.created_at >= v_day and d.outcome <> 'failed' and d.purpose = 'caption'),
        'caption_cap', case when coalesce(t.is_admin, false) or t.role = 'admin'
                            then public.ai_draft_limit('caption_admin', 40) else public.ai_draft_limit('caption', 20) end,
        'month', (select count(*) from public.ai_drafts d where d.team_member_id = t.id and d.created_at > v_month and d.outcome <> 'failed'),
        'limit', (select l.daily from public.ai_draft_limits l where l.scope = t.id::text),
        'cap', public.ai_day_cap(t)) as x
        from public.team_members t
        left join public.team_roles g on g.slug = t.role
       where t.active
         and (coalesce(t.is_admin, false) or t.role = 'admin'
              or public.level_rank(coalesce(t.access ->> 'reports', 'none')) >= public.level_rank('work')
              or public.level_rank(coalesce(t.access ->> 'review', 'none')) >= public.level_rank('work')
              or exists (select 1 from public.ai_drafts d where d.team_member_id = t.id and d.created_at > v_month))
    ) s), '[]'::jsonb));
end $$;
revoke all on function public.ai_draft_usage() from public, anon, authenticated;
grant execute on function public.ai_draft_usage() to authenticated;

create or replace function public.ai_draft_set_limit(p_scope text, p_daily integer)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_who text;
  v_name text;
  v_was integer;
  v_def integer;
  v_unit text := ' a day';
  v_scope text := btrim(coalesce(p_scope, ''));
  t public.team_members;
begin
  if not public.ops_granted('reports.ai', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if p_daily is not null and (p_daily < 0 or p_daily > 500) then
    return jsonb_build_object('error', 'bad-limit');
  end if;
  if v_scope = 'person' then
    v_name := 'Each colleague'; v_def := 10;
  elsif v_scope = 'admin' then
    v_name := 'Each admin'; v_def := 20;
  elsif v_scope = 'report' then
    v_name := 'Drafts per report, each colleague'; v_def := 1;
  elsif v_scope = 'report_admin' then
    v_name := 'Drafts per report, each admin'; v_def := 5;
  elsif v_scope = 'check' then
    v_name := 'Figures checks per report, each colleague'; v_def := 1;
  elsif v_scope = 'check_admin' then
    v_name := 'Figures checks per report, each admin'; v_def := 5;
  elsif v_scope = 'caption' then
    v_name := 'Captions, each colleague'; v_def := 20;
  elsif v_scope = 'caption_admin' then
    v_name := 'Captions, each admin'; v_def := 40;
  elsif v_scope = 'team' then
    return jsonb_build_object('error', 'bad-scope');
  else
    select * into t from public.team_members x where x.id::text = v_scope;
    if t.id is null then return jsonb_build_object('error', 'not-found'); end if;
    v_name := t.name;
    v_def := case when coalesce(t.is_admin, false) or t.role = 'admin'
                  then public.ai_draft_limit('admin', 20) else public.ai_draft_limit('person', 10) end;
  end if;
  select l.daily into v_was from public.ai_draft_limits l where l.scope = v_scope;
  if v_was is not distinct from p_daily then return jsonb_build_object('ok', true, 'same', true); end if;
  select coalesce(x.name, x.email) into v_who from public.team_members x
   where lower(x.email) = lower(auth.jwt() ->> 'email') and x.active limit 1;
  insert into public.ai_draft_limits (scope, daily, set_by, set_at)
  values (v_scope, p_daily, v_who, now())
  on conflict (scope) do update set daily = excluded.daily, set_by = excluded.set_by, set_at = excluded.set_at;
  insert into public.activity_log (actor, action, subject, detail)
  values (coalesce(v_who, 'admin'), 'team.changed', 'AI',
          v_name || ': ' ||
          case when v_was is null then 'standard, ' || v_def || v_unit when v_was = 0 then 'stopped' else v_was || v_unit end ||
          ' → ' ||
          case when p_daily is null then 'standard, ' || v_def || v_unit when p_daily = 0 then 'stopped' else p_daily || v_unit end);
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.ai_draft_set_limit(text, integer) from public, anon, authenticated;
grant execute on function public.ai_draft_set_limit(text, integer) to authenticated;

-- END OF CAPTION WRITER AND AI COST -----------------------------------------

-- ===========================================================================
-- A REPORT BEGINS IN ITS MONTH — a month's report is started from the month
-- in My Work that asks for it, and a draft taken away puts its task back.
-- 2026-10-09. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/ops.js compares the
-- two.
--
-- WHAT CHANGED
--   The user, 2026-10-09: "if no content month completed, then the option
--   to create that specific month would be greyed out". The loop is month
--   (its Reports ticks) → report task → report → the task follows it.
--   1. `sm_report_months(p_client, p_kind)`: the client's months in My Work
--      (not cancelled), newest first, each with its span, whether it asks
--      for the kind, and the report already made for it (no white-label
--      brand); and whether the reader may start one outside them
--      (`may_override`: an admin or Reports Full Access). Reports View, in
--      the colleague's client scope. New report offers these months, the
--      period being the month's own span (a month starting on the 16th
--      runs to the 15th), and greys a month that does not ask.
--   2. Trigger `sm_reports_month_gate` (before insert on `sm_reports`): a
--      report from October 2026 on, with no white-label brand, is refused
--      `month-gate` unless a month in My Work whose span holds its last day
--      asks for its kind, or the colleague is an admin or holds Reports
--      Full Access (the same people Submit lets past the month's gate). The
--      SQL editor (no colleague) passes.
--   3. `sm_reports_task_reset` (after a report row goes): a draft report
--      taken away puts its month's task back to To do, filed "Report
--      deleted", unless the task is finished. Its trigger statement names
--      the event, so it is applied on its own (CLAUDE.md §3).
--
-- ROLLBACK
--   Drop the triggers sm_reports_task_reset and sm_reports_month_gate on
--   public.sm_reports, then the functions sm_reports_task_reset(),
--   sm_reports_month_gate() and sm_report_months(uuid, text).
-- ===========================================================================

create or replace function public.sm_report_months(p_client uuid, p_kind text default 'social')
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  c public.clients;
begin
  if me.id is null or not public.allowed('reports', 'view') then return jsonb_build_object('error', 'denied'); end if;
  if coalesce(p_kind, '') not in ('social', 'ads') then return jsonb_build_object('error', 'bad-kind'); end if;
  select * into c from public.clients where id = p_client;
  if c.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if not public.client_row_seen(c.stage, c.owner, 'view') then return jsonb_build_object('error', 'denied'); end if;
  return jsonb_build_object(
    'may_override', coalesce(me.is_admin, false) or me.role = 'admin' or public.allowed('reports', 'manage'),
    'months', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', e.id, 'period', e.period, 'start_day', e.start_day,
               'starts', s.starts, 'ends', s.ends, 'status', e.status,
               'asks', p_kind = any (coalesce(e.reports, '{}'::text[])),
               'report', (select r.id from public.sm_reports r
                           where r.client_id = e.client_id and r.kind = p_kind and r.brand_id is null
                             and r.period_end between s.starts and s.ends
                           order by r.period_start desc limit 1))
             order by e.period desc)
        from public.ops_engagements e
       cross join lateral public.ops_month_span(e.period, e.start_day) s
       where e.client_id = p_client and e.status <> 'cancelled'), '[]'::jsonb));
end $$;

create or replace function public.sm_reports_month_gate()
returns trigger
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
begin
  if new.brand_id is not null or new.period_start < date '2026-10-01' or me.id is null then return new; end if;
  if coalesce(me.is_admin, false) or me.role = 'admin' or public.allowed('reports', 'manage') then return new; end if;
  if exists (select 1 from public.ops_engagements e
              cross join lateral public.ops_month_span(e.period, e.start_day) s
              where e.client_id = new.client_id and e.status <> 'cancelled'
                and new.period_end between s.starts and s.ends
                and new.kind = any (coalesce(e.reports, '{}'::text[]))) then
    return new;
  end if;
  raise exception 'month-gate' using errcode = 'P0001';
end $$;
revoke all on function public.sm_reports_month_gate() from public, anon, authenticated;

create or replace trigger sm_reports_month_gate
  before insert on public.sm_reports
  for each row execute function public.sm_reports_month_gate();

create or replace function public.sm_reports_task_reset()
returns trigger
language plpgsql security definer set search_path = public as $$
declare
  t public.ops_tasks;
begin
  if old.brand_id is not null or old.status <> 'draft' then return null; end if;
  select x.* into t from public.ops_tasks x
    join public.ops_engagements e on e.id = x.engagement_id
   cross join lateral public.ops_month_span(e.period, e.start_day) s
   where e.client_id = old.client_id and e.status <> 'cancelled'
     and old.period_end between s.starts and s.ends
     and x.source_type = 'report_' || old.kind
     and x.cancelled_at is null and x.archived_at is null
   order by e.period desc, x.created_at desc limit 1
   for update of x;
  if t.id is null or t.completed_at is not null or t.stage_key = 'todo' then return null; end if;
  update public.ops_tasks set stage_key = 'todo', version = version + 1, updated_at = now(),
         blocked_at = null, blocked_category = null
   where id = t.id;
  perform public.ops_log(t.id, 'stage_changed',
    jsonb_build_object('stage_key', t.stage_key), jsonb_build_object('stage_key', 'todo'),
    jsonb_build_object('note', 'Report deleted', 'report_id', old.id));
  return null;
exception when others then
  return null;
end $$;
revoke all on function public.sm_reports_task_reset() from public, anon, authenticated;

create or replace trigger sm_reports_task_reset
  after delete on public.sm_reports
  for each row execute function public.sm_reports_task_reset();

-- END OF A REPORT BEGINS IN ITS MONTH ----------------------------------------

-- ===========================================================================
-- TEAM NOTICES — a notice to every colleague, or to the colleagues chosen,
-- in the notification bell and as a push.
-- 2026-10-09. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/smsql.js compares the
-- two.
--
-- WHAT CHANGED
--   The user, 2026-10-09: "add the send notice, whereby i can send custom
--   in-app notifications to all members, or to specific team member(s)".
--   1. `team_notices` (RLS on, no policy, no grant): the notice, whom it went
--      to, who sent it, and when it was withdrawn.
--   2. `ops_notifications.notice_id`, `from_name` and `hidden_at`: each
--      colleague's copy names its notice and who sent it, and a notice
--      withdrawn is hidden from every bell.
--   3. Team: Notices (`team.notice`, a granted part: an admin's by itself,
--      any other group's once set):
--      `team_notice_send(p_title, p_body, p_to)` sends to all active
--      colleagues (`p_to` null) or to those named, never a system account and
--      never the sender (`bad-title`, `bad-body`, `no-one`);
--      `team_notices_list()` answers the latest 50, each with whom it went to
--      and how many have read it;
--      `team_notice_withdraw(p_id, p_restore)` hides it from every bell (a
--      push already delivered stays on the device), and with `p_restore`
--      puts it back.
--      Each is filed `team.changed` under subject Notices.
--
-- ROLLBACK
--   Nothing reads the table but these functions; leaving them unused sends
--   nothing. The three columns may stay: the bell reads `hidden_at` only to
--   leave a withdrawn notice out, and `from_name` only to say who sent it.
-- ===========================================================================

create table if not exists public.team_notices (
  id            uuid primary key default gen_random_uuid(),
  title         text not null,
  body          text,
  to_all        boolean not null default false,
  recipients    uuid[] not null default '{}',
  sent_by       uuid,
  sent_by_name  text,
  created_at    timestamptz not null default now(),
  withdrawn_at  timestamptz,
  withdrawn_by  text
);
alter table public.team_notices enable row level security;
revoke all on public.team_notices from public, anon, authenticated;

alter table public.ops_notifications add column if not exists notice_id uuid;
alter table public.ops_notifications add column if not exists from_name text;
alter table public.ops_notifications add column if not exists hidden_at timestamptz;
create index if not exists ops_notif_notice_idx on public.ops_notifications(notice_id) where notice_id is not null;

create or replace function public.team_notice_send(p_title text, p_body text, p_to uuid[])
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  v_title text := btrim(coalesce(p_title, ''));
  v_body  text := nullif(btrim(coalesce(p_body, '')), '');
  v_to    uuid[];
  v_id    uuid;
  n       int;
begin
  if me.id is null or not public.ops_granted('team.notice', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if v_title = '' or length(v_title) > 120 then return jsonb_build_object('error', 'bad-title'); end if;
  if v_body is not null and length(v_body) > 1000 then return jsonb_build_object('error', 'bad-body'); end if;
  select coalesce(array_agg(m.id order by m.name), '{}') into v_to
    from public.team_members m
   where m.active and not coalesce(m.system, false) and m.id <> me.id
     and (p_to is null or m.id = any(p_to));
  n := coalesce(array_length(v_to, 1), 0);
  if n = 0 then return jsonb_build_object('error', 'no-one'); end if;
  insert into public.team_notices (title, body, to_all, recipients, sent_by, sent_by_name)
  values (v_title, v_body, p_to is null, v_to, me.id, me.name)
  returning id into v_id;
  insert into public.ops_notifications (team_member_id, kind, title, body, notice_id, from_name)
  select x, 'notice', v_title, v_body, v_id, me.name from unnest(v_to) as x;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'team.changed', 'Notices',
    'Sent to ' || case when p_to is null then 'all colleagues (' || n || ')'
                       when n = 1 then '1 colleague' else n || ' colleagues' end || ': ' || v_title);
  return jsonb_build_object('ok', true, 'id', v_id, 'count', n);
end $$;
revoke all on function public.team_notice_send(text, text, uuid[]) from public, anon;
grant execute on function public.team_notice_send(text, text, uuid[]) to authenticated;

create or replace function public.team_notices_list()
returns jsonb
language plpgsql security definer stable set search_path = public as $$
declare
  me public.team_members := public.ops_me();
begin
  if me.id is null or not public.ops_granted('team.notice', 'work') then return jsonb_build_object('error', 'denied'); end if;
  return jsonb_build_object('items', coalesce((
    select jsonb_agg(row_to_json(x) order by x.created_at desc)
      from (select tn.id, tn.title, tn.body, tn.to_all, tn.sent_by_name, tn.created_at, tn.withdrawn_at,
                   coalesce(array_length(tn.recipients, 1), 0) as sent,
                   (select count(*) from public.ops_notifications o
                     where o.notice_id = tn.id and o.read_at is not null) as read,
                   (select coalesce(jsonb_agg(m.name order by m.name), '[]'::jsonb) from public.team_members m
                     where m.id = any(tn.recipients)) as names
              from public.team_notices tn
             order by tn.created_at desc
             limit 50) x), '[]'::jsonb));
end $$;
revoke all on function public.team_notices_list() from public, anon;
grant execute on function public.team_notices_list() to authenticated;

create or replace function public.team_notice_withdraw(p_id uuid, p_restore boolean default false)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  v public.team_notices;
begin
  if me.id is null or not public.ops_granted('team.notice', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into v from public.team_notices tn where tn.id = p_id for update;
  if v.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if coalesce(p_restore, false) then
    if v.withdrawn_at is null then return jsonb_build_object('ok', true); end if;
    update public.team_notices tn set withdrawn_at = null, withdrawn_by = null where tn.id = p_id;
    update public.ops_notifications o set hidden_at = null where o.notice_id = p_id;
    insert into public.activity_log (actor, action, subject, detail)
    values (me.name, 'team.changed', 'Notices', 'Restored: ' || v.title);
    return jsonb_build_object('ok', true);
  end if;
  if v.withdrawn_at is not null then return jsonb_build_object('ok', true); end if;
  update public.team_notices tn set withdrawn_at = now(), withdrawn_by = me.name where tn.id = p_id;
  update public.ops_notifications o set hidden_at = now() where o.notice_id = p_id and o.hidden_at is null;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'team.changed', 'Notices', 'Withdrawn: ' || v.title);
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.team_notice_withdraw(uuid, boolean) from public, anon;
grant execute on function public.team_notice_withdraw(uuid, boolean) to authenticated;

-- END OF TEAM NOTICES -------------------------------------------------------

-- ===========================================================================
-- REPORT AUDIT — a report's figures are read against Meta's before it is
-- submitted and again before it is published, and nothing passes while one
-- differs.
-- 2026-10-09. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/smsql.js compares the
-- two.
--
-- WHAT CHANGED
--   The user, 2026-10-09: "there shouldnt be any mismatches". Check and
--   submit's figures check becomes the Report audit, in two parts: the
--   Commentary (the AI's reading of the words, as before) and Against Meta
--   (the page reads Meta through `meta-import` and compares every figure the
--   report takes from Meta, exactly, at the precision the report holds it;
--   no AI use). This file holds the readings and the gate.
--   1. `sm_report_audits` (RLS on, no policy, no grant): each reading: the
--      version, when, who, the outcome (`match`, `mismatch`, `unavailable`,
--      `override`), the print of the figures read, the rows that differed,
--      and a note (what Meta answered, or an admin's reason).
--   2. `sm_report_meta_print(p_id)`: one print of the figures the report
--      takes from Meta: an Advertising Report's Meta ads (their figures, age
--      split, retention and Ad IDs) and Step 1's reach, impressions and
--      amount spent; an Accounts Report's Facebook and Instagram posts (link
--      and figures). Any change to one of them changes the print.
--   3. `sm_report_audit_needed(p_id)`: whether the report's client (or its
--      white-label brand) links what the report is read from: an ad account
--      for an Advertising Report; a Page or an Instagram account the report
--      holds an account for, for an Accounts Report. Not linked, nothing is
--      required.
--   4. `sm_report_audit_save(p_id, p_outcome, p_rows, p_note)`: a reading
--      filed by the page (Reports at Work, the client in the colleague's
--      scope): an Advertising Report in draft, review or confirmed (Meta is
--      read again before Publish); an Accounts Report in draft (a post's
--      figures are lifetime totals that grow by the hour, so the reading at
--      submission is the one that stands). `override` is an admin's alone,
--      after a reading Meta did not answer, with a reason. A reading the same
--      as the last refreshes its time; a new outcome is filed
--      `report.audited` (Report audit).
--   5. `sm_report_audit_last(p_id)`: the last reading of the version, whether
--      the figures still print as they did, whether the gate holds, and when
--      the figures took their present print (Reports at View).
--   6. `sm_report_audit_blocks(p_id, p_after)`: `meta-audit` where a linked
--      report's last reading since p_after is not a match (or an admin's
--      override) of the figures as they stand. sm_report_submit asks it;
--      sm_report_publish asks it since confirmation for an Advertising
--      Report, and for an Accounts Report holds the reading it was submitted
--      on (a report submitted before this file holds none and is not held).
--   7. activity_section() files `report.audited` under Reports.
--
-- ROLLBACK
--   Run sm_report_submit as REPORT MONTH GATE defines it, sm_report_publish
--   as REPORTS defines it and activity_section as ACTIVITY FILES A RESTORE
--   AND A DELETE defines it; then remove the functions
--   sm_report_audit_last(uuid), sm_report_audit_save(uuid, text, jsonb,
--   text), sm_report_audit_blocks(uuid, timestamptz),
--   sm_report_audit_needed(uuid) and sm_report_meta_print(uuid), and the
--   table sm_report_audits.
-- ===========================================================================

create table if not exists public.sm_report_audits (
  id          uuid primary key default gen_random_uuid(),
  report_id   uuid not null references public.sm_reports(id) on delete cascade,
  version_no  integer not null,
  read_at     timestamptz not null default now(),
  by_id       uuid references public.team_members(id) on delete set null,
  by_name     text,
  outcome     text not null,
  print       text,
  diffs       jsonb not null default '[]'::jsonb,
  note        text,
  constraint sm_report_audits_outcome check (outcome in ('match', 'mismatch', 'unavailable', 'override'))
);
create index if not exists sm_report_audits_report_idx
  on public.sm_report_audits (report_id, version_no, read_at desc);
alter table public.sm_report_audits enable row level security;
revoke all on public.sm_report_audits from public, anon, authenticated;

/* The figures the report takes from Meta, as one print. A JSON array a row,
   so a value that moves from one field to the next never prints the same. */
create or replace function public.sm_report_meta_print(p_id uuid)
returns text
language sql stable security definer set search_path = public as $$
  select md5(case when r.kind = 'ads' then
      coalesce((select string_agg(jsonb_build_array(a.id, a.result_label, a.results, a.reach, a.impressions, a.spend,
                  a.ctr, a.cpr, a.hook_rate, a.hold_rate, a.avg_play, a.retention, a.age, a.ad_ids)::text, ';' order by a.id)
                  from public.sm_report_ads a
                 where a.report_id = r.id and coalesce(a.platform, 'meta') = 'meta'), '')
      || '#' || jsonb_build_object('reach', r.ads_totals -> 'reach', 'impressions', r.ads_totals -> 'impressions',
                                   'spend', r.ads_totals -> 'spend')::text
    else
      coalesce((select string_agg(jsonb_build_array(p.id, p.url, p.views, p.reach, p.impressions, p.interactions,
                  p.engagements, p.likes, p.comments, p.shares, p.saves)::text, ';' order by p.id)
                  from public.sm_report_posts p
                  join public.sm_report_platforms f on f.id = p.platform_id
                 where p.report_id = r.id and f.platform in ('facebook', 'instagram')), '')
    end)
  from public.sm_reports r where r.id = p_id
$$;
revoke all on function public.sm_report_meta_print(uuid) from public, anon, authenticated;

/* Whether the report's client (or brand) links what it is read from. */
create or replace function public.sm_report_audit_needed(p_id uuid)
returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce((
    select case when r.kind = 'ads' then jsonb_array_length(coalesce(l.ad_accounts, '[]'::jsonb)) > 0
                else (jsonb_typeof(l.page) = 'object' and exists (
                        select 1 from public.sm_report_platforms f where f.report_id = r.id and f.platform = 'facebook'))
                  or (jsonb_typeof(l.instagram) = 'object' and exists (
                        select 1 from public.sm_report_platforms f where f.report_id = r.id and f.platform = 'instagram'))
           end
      from public.sm_reports r
      join public.meta_links l on l.client_id = r.client_id and l.brand_id is not distinct from r.brand_id
     where r.id = p_id), false)
$$;
revoke all on function public.sm_report_audit_needed(uuid) from public, anon, authenticated;

/* `meta-audit` where a linked report has no passing reading of its figures
   as they stand, since p_after. */
create or replace function public.sm_report_audit_blocks(p_id uuid, p_after timestamptz default null)
returns text
language plpgsql stable security definer set search_path = public as $$
declare
  r public.sm_reports;
  a public.sm_report_audits;
begin
  select * into r from public.sm_reports where id = p_id;
  if r.id is null or not public.sm_report_audit_needed(p_id) then return null; end if;
  select * into a from public.sm_report_audits x
   where x.report_id = p_id and x.version_no = r.version_no
   order by x.read_at desc, x.id desc limit 1;
  if a.id is null or a.read_at < coalesce(p_after, '-infinity'::timestamptz) then return 'meta-audit'; end if;
  if a.outcome not in ('match', 'override') then return 'meta-audit'; end if;
  if a.print is distinct from public.sm_report_meta_print(p_id) then return 'meta-audit'; end if;
  return null;
end $$;
revoke all on function public.sm_report_audit_blocks(uuid, timestamptz) from public, anon, authenticated;

/* A reading filed. The comparison is the page's (it runs the report's own
   importer over Meta's answer); the print is taken here, so a figure changed
   after the reading is a reading no longer. */
create or replace function public.sm_report_audit_save(p_id uuid, p_outcome text, p_rows jsonb default '[]'::jsonb,
                                                       p_note text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.sm_reports;
  c public.clients;
  prev public.sm_report_audits;
  v_rows jsonb := coalesce(p_rows, '[]'::jsonb);
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
  v_print text;
  v_id uuid;
  v_at timestamptz;
  v_word text;
begin
  if me.id is null or not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if coalesce(p_outcome, '') not in ('match', 'mismatch', 'unavailable', 'override') then
    return jsonb_build_object('error', 'bad-outcome');
  end if;
  if jsonb_typeof(v_rows) is distinct from 'array' or jsonb_array_length(v_rows) > 500 or length(v_rows::text) > 200000 then
    return jsonb_build_object('error', 'bad-rows');
  end if;
  if p_outcome = 'match' then v_rows := '[]'::jsonb; end if;
  if p_outcome = 'mismatch' and jsonb_array_length(v_rows) = 0 then return jsonb_build_object('error', 'bad-rows'); end if;
  select * into r from public.sm_reports where id = p_id for update;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  select * into c from public.clients where id = r.client_id;
  if not public.client_row_seen(c.stage, c.owner, 'view') then return jsonb_build_object('error', 'denied'); end if;
  if not (r.status = 'draft' or (r.kind = 'ads' and r.status in ('review', 'confirmed'))) then
    return jsonb_build_object('error', 'not-open', 'status', r.status);
  end if;
  if not public.sm_report_audit_needed(p_id) then return jsonb_build_object('error', 'not-linked'); end if;
  select * into prev from public.sm_report_audits x
   where x.report_id = p_id and x.version_no = r.version_no
   order by x.read_at desc, x.id desc limit 1;
  if p_outcome = 'override' then
    if not (coalesce(me.is_admin, false) or me.role = 'admin') then return jsonb_build_object('error', 'denied'); end if;
    if prev.id is null or prev.outcome <> 'unavailable' then return jsonb_build_object('error', 'not-unavailable'); end if;
    if v_note is null then return jsonb_build_object('error', 'reason-required'); end if;
    v_rows := '[]'::jsonb;
  end if;
  if p_outcome = 'match' then v_note := null; end if;
  v_note := left(v_note, 500);
  v_print := public.sm_report_meta_print(p_id);
  if prev.id is not null and p_outcome <> 'override' and prev.outcome = p_outcome
     and prev.print is not distinct from v_print and prev.diffs = v_rows and prev.note is not distinct from v_note then
    update public.sm_report_audits set read_at = now(), by_id = me.id, by_name = me.name where id = prev.id
    returning id, read_at into v_id, v_at;
    return jsonb_build_object('ok', true, 'id', v_id, 'at', v_at, 'outcome', p_outcome, 'again', true);
  end if;
  insert into public.sm_report_audits (report_id, version_no, by_id, by_name, outcome, print, diffs, note)
  values (p_id, r.version_no, me.id, me.name, p_outcome, v_print, v_rows, v_note)
  returning id, read_at into v_id, v_at;
  if prev.id is null or prev.outcome <> p_outcome or p_outcome = 'override' then
    v_word := case p_outcome
      when 'match' then 'Against Meta: matches'
      when 'mismatch' then 'Against Meta: ' || jsonb_array_length(v_rows) || ' to fix'
      when 'unavailable' then 'Against Meta: not checked, Meta unavailable'
      else 'Against Meta: not checked, Meta unavailable · Reason: ' || v_note end;
    perform public.sm_report_log(p_id, 'report.audited', 'Report audit · ' || v_word);
  end if;
  return jsonb_build_object('ok', true, 'id', v_id, 'at', v_at, 'outcome', p_outcome);
end $$;
revoke all on function public.sm_report_audit_save(uuid, text, jsonb, text) from public, anon, authenticated;
grant execute on function public.sm_report_audit_save(uuid, text, jsonb, text) to authenticated;

/* The last reading of the version, as the audit card reads it. */
create or replace function public.sm_report_audit_last(p_id uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.sm_reports;
  c public.clients;
  a public.sm_report_audits;
  v_print text;
begin
  if me.id is null or not public.allowed('reports', 'view') then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_id;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  select * into c from public.clients where id = r.client_id;
  if not public.client_row_seen(c.stage, c.owner, 'view') then return jsonb_build_object('error', 'denied'); end if;
  v_print := public.sm_report_meta_print(p_id);
  select * into a from public.sm_report_audits x
   where x.report_id = p_id and x.version_no = r.version_no
   order by x.read_at desc, x.id desc limit 1;
  return jsonb_build_object(
    'needed', public.sm_report_audit_needed(p_id),
    'may_override', coalesce(me.is_admin, false) or me.role = 'admin',
    'blocks', public.sm_report_audit_blocks(p_id, null),
    'held', exists (select 1 from public.sm_report_audits x where x.report_id = p_id and x.version_no = r.version_no),
    'print_since', (select min(x.read_at) from public.sm_report_audits x
                     where x.report_id = p_id and x.version_no = r.version_no and x.print = v_print),
    'print_moved', exists (select 1 from public.sm_report_audits x
                            where x.report_id = p_id and x.version_no = r.version_no and x.print is distinct from v_print),
    'last', case when a.id is null then null else jsonb_build_object(
      'at', a.read_at, 'by', a.by_name, 'outcome', a.outcome, 'rows', a.diffs, 'note', a.note,
      'current', a.print is not distinct from v_print) end);
end $$;
revoke all on function public.sm_report_audit_last(uuid) from public, anon, authenticated;
grant execute on function public.sm_report_audit_last(uuid) to authenticated;

/* `p_reason` is the reason a late submit, or one past the month's gate,
   gives; it is read from MONTH REPORTS (2026-10-04) on. The Report audit
   (2026-10-09) holds a linked report until Meta's figures match. */
create or replace function public.sm_report_submit(p_id uuid, p_reviewer uuid default null, p_reason text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.sm_reports;
  cname text;
  g jsonb;
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
  v_gate text;
  v_late text;
  v_extra text := '';
  v_audit text;
begin
  if me.id is null or not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_id for update;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if r.status <> 'draft' then return jsonb_build_object('error', 'not-draft', 'status', r.status); end if;
  if r.kind = 'ads' then
    if not exists (select 1 from public.sm_report_ads where report_id = p_id) then
      return jsonb_build_object('error', 'no-ads');
    end if;
  else
    if not exists (select 1 from public.sm_report_platforms where report_id = p_id) then
      return jsonb_build_object('error', 'no-platforms');
    end if;
    if not exists (select 1 from public.sm_report_posts where report_id = p_id) then
      return jsonb_build_object('error', 'no-posts');
    end if;
  end if;
  v_audit := public.sm_report_audit_blocks(p_id, null);
  if v_audit is not null then return jsonb_build_object('error', v_audit); end if;
  g := public.sm_report_gate(p_id);
  if coalesce((g ->> 'applies')::boolean, false) then
    if not (g ->> 'ok')::boolean then
      if not (g ->> 'may_override')::boolean or v_reason is null then
        return jsonb_build_object('error', 'month-gate', 'missing', g -> 'missing', 'planned', g -> 'planned',
                                  'made', g -> 'made', 'may_override', g -> 'may_override');
      end if;
      v_gate := left(v_reason, 500);
    end if;
    if (g ->> 'late')::boolean then
      if v_reason is null then
        return jsonb_build_object('error', 'late-reason', 'due', g -> 'due');
      end if;
      v_late := left(v_reason, 500);
    end if;
  end if;
  if p_reviewer is null then return jsonb_build_object('error', 'no-reviewer'); end if;
  if p_reviewer = me.id then return jsonb_build_object('error', 'self-review'); end if;
  if not public.sm_report_may_review(p_reviewer) then return jsonb_build_object('error', 'bad-reviewer'); end if;
  perform set_config('adspace.sm_fn', 'on', true);
  update public.sm_reports set status = 'review', submitted_by = me.id, submitted_at = now(),
    reviewer_id = p_reviewer, return_note = null, confirmed_by = null, confirmed_at = null,
    late_reason = v_late, gate_note = v_gate where id = p_id;
  perform set_config('adspace.sm_fn', 'off', true);
  if v_gate is not null then v_extra := v_extra || ' · Past the month''s gate: ' || v_gate; end if;
  if v_late is not null and v_gate is distinct from v_late then v_extra := v_extra || ' · Late: ' || v_late;
  elsif v_late is not null then v_extra := v_extra || ' · Late'; end if;
  perform public.sm_report_log(p_id, 'report.submitted',
    'Reviewer: ' || (select name from public.team_members where id = p_reviewer) || v_extra);
  select c.name into cname from public.clients c where c.id = r.client_id;
  perform public.sm_report_notify(p_reviewer, p_id, 'report.review', 'Report to review',
    cname || ' · ' || public.sm_period_word(r.period_start, r.period_end));
  return jsonb_build_object('ok', true, 'status', 'review');
end $$;
revoke all on function public.sm_report_submit(uuid, uuid, text) from public, anon, authenticated;
grant execute on function public.sm_report_submit(uuid, uuid, text) to authenticated;

/* Publish: the confirmed report is frozen as its version and the client
   can read it. The same press twice publishes once. An Advertising Report
   is read against Meta again since it was confirmed; an Accounts Report
   holds the reading it was submitted on (2026-10-09). */
create or replace function public.sm_report_publish(p_id uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.sm_reports;
  snap jsonb;
  vid uuid;
  v_audit text;
begin
  if me.id is null or not public.allowed('reports', 'manage') then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_id for update;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if r.status = 'published' then
    select id into vid from public.sm_report_versions where report_id = p_id and version_no = r.version_no;
    return jsonb_build_object('ok', true, 'status', 'published', 'version_id', vid, 'again', true);
  end if;
  if r.status <> 'confirmed' then return jsonb_build_object('error', 'not-confirmed', 'status', r.status); end if;
  if r.kind = 'ads' then
    v_audit := public.sm_report_audit_blocks(p_id, r.confirmed_at);
  elsif exists (select 1 from public.sm_report_audits x where x.report_id = p_id and x.version_no = r.version_no) then
    v_audit := public.sm_report_audit_blocks(p_id, null);
  end if;
  if v_audit is not null then return jsonb_build_object('error', v_audit); end if;
  snap := public.sm_report_snapshot(p_id, true);
  perform set_config('adspace.sm_fn', 'on', true);
  insert into public.sm_report_versions (report_id, version_no, snapshot, published_by)
  values (p_id, r.version_no, snap, me.name)
  on conflict (report_id, version_no) do update
    set snapshot = excluded.snapshot, published_by = excluded.published_by, published_at = now(),
        withdrawn_at = null, withdrawn_by = null, withdraw_reason = null
  returning id into vid;
  update public.sm_reports set status = 'published' where id = p_id;
  perform set_config('adspace.sm_fn', 'off', true);
  perform public.sm_report_log(p_id, 'report.published');
  return jsonb_build_object('ok', true, 'status', 'published', 'version_id', vid);
end $$;
revoke all on function public.sm_report_publish(uuid) from public, anon, authenticated;
grant execute on function public.sm_report_publish(uuid) to authenticated;

create or replace function public.activity_section(p_action text)
returns text
language sql immutable parallel safe as $$
  select case
    when action in ('campaign.bulk', 'campaign.closed', 'campaign.confirmed',
                    'campaign.created', 'campaign.dates', 'campaign.deleted', 'campaign.edited',
                    'campaign.file_added', 'campaign.qc',
                    'campaign.invoice', 'campaign.invoice_file',
                    'campaign.invoice_removed', 'campaign.keyed', 'campaign.locked',
                    'campaign.opened', 'campaign.rate', 'campaign.rated',
                    'campaign.reinstated', 'campaign.replaced', 'campaign.results', 'campaign.review',
                    'campaign.stage', 'campaign.submitted', 'campaign.task_linked',
                    'campaign.task_unlinked', 'campaign.unbooked',
                    'campaign.unkeyed', 'campaign.withdrawn', 'creator.added',
                    'creator.code', 'creator.links', 'creator.links_restored',
                    'creator.links_self', 'creator.off', 'creator.on', 'creator.removed',
                    'creator.updated') then 'campaigns'
    when action in ('client.action_done', 'client.action_reopened', 'client.added',
                    'client.billing', 'client.brand', 'client.deleted', 'client.edited',
                    'client.review_on', 'client.service', 'client.service_changed',
                    'client.service_removed', 'client.service_restored', 'client.stage', 'client.touch',
                    'client.touch_deleted', 'client.touch_edited', 'client.touch_removed',
                    'client.touch_restored', 'contact.added', 'contact.deleted',
                    'contact.edited', 'contact.portal_invite', 'contact.portal_off',
                    'contact.portal_on', 'contact.primary', 'contact.removed',
                    'contact.restored',
                    'request.changed', 'request.raised',
                    'request.reinstated', 'request.replied', 'request.withdrawn',
                    'service.override') then 'clients'
    when action in ('report.ai_drafted', 'report.ai_failed', 'report.audited', 'report.confirmed',
                    'report.created', 'report.deleted', 'report.published',
                    'report.reassigned', 'report.returned', 'report.revised', 'report.saved',
                    'report.submitted', 'report.unpublished') then 'reports'
    when action in ('qr.created', 'qr.restored', 'qr.revoked', 'shortlink.created',
                    'shortlink.deleted', 'shortlink.imported', 'shortlink.updated') then 'links'
    when action in ('ops.deleted', 'ops.month_deleted', 'ops.numbering') then 'ops'
    when action in ('document.deleted', 'document.issued', 'document.reissued',
                    'document.restored', 'document.signed', 'document.superseded',
                    'document.unsigned', 'document.verified', 'document.voided',
                    'register.added', 'register.edited') then 'register'
    when action in ('client.drive', 'client.handles', 'client.profile',
                    'client.removed', 'drive.imported', 'link.reset', 'post.added',
                    'post.deleted', 'post.edited', 'reapproval.requested',
                    'review.approved', 'review.changes', 'review.removed',
                    'review.unconfirmed',
                    'set.created', 'set.deleted', 'set.published', 'set.renamed',
                    'set.task_linked', 'set.task_unlinked',
                    'set.withdrawn') then 'review'
    when action in ('handbook.added', 'handbook.archived', 'handbook.deleted',
                    'handbook.edited', 'handbook.restored', 'handbook.version') then 'handbook'
    when action in ('service.added', 'service.changed', 'service.deleted',
                    'service.off', 'service.on') then 'services'
    when action in ('team.added', 'team.changed', 'team.edited', 'team.group_added',
                    'team.group_changed', 'team.group_removed', 'team.invited') then 'team'
    else 'other'
  end
  from (select p_action as action) t
$$;
grant execute on function public.activity_section(text) to authenticated;

-- END OF REPORT AUDIT --------------------------------------------------------

-- ===========================================================================
-- REPORTS ON REQUEST — a report the client asked for, on any period, held
-- by no month's checks and moving no month's report task.
-- 2026-10-09. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/smsql.js compares the
-- two.
--
-- WHAT CHANGED
--   The user, 2026-10-09: "Sometimes we need to create report on demand.
--   Like situation like now client requests a report." A report made on
--   request is not the month's report: it covers any period (a week, two
--   weeks, a whole month the month's ticks do not ask for), so nothing tied
--   to the month holds it or follows it.
--   1. `sm_reports.on_request` (false by default), set once at creation.
--   2. `sm_report_create_for(…, p_on_request)` takes it (New report's
--      Requested by the client, or any custom period) and files `On request`
--      on `report.created`. The four-argument `sm_report_create` stays the
--      month's. A changed signature drops the old one first (PostgREST
--      cannot choose between overloads).
--   3. `sm_reports_month_gate` lets it be made for any period.
--   4. `sm_report_gate` does not apply to it: Submit asks no month, content
--      count or late reason.
--   5. `sm_reports_task_follow` and `sm_reports_task_reset` leave the month's
--      report task alone for it.
--   6. `sm_report_months` and `sm_reports_owed` never count it as the
--      month's report.
--   7. A month's report carries on from the month's report before it, never
--      from one asked for; an Advertising Report asked for compares with the
--      same length just before it, typed by the team.
--
-- ROLLBACK
--   Run sm_report_create_for, sm_report_create, sm_reports_month_gate,
--   sm_report_gate, sm_reports_task_follow, sm_reports_task_reset,
--   sm_report_months and sm_reports_owed as their earlier sections define
--   them (dropping sm_report_create_for(uuid, date, date, text, uuid,
--   boolean) first), then drop the column sm_reports.on_request.
-- ===========================================================================

alter table public.sm_reports add column if not exists on_request boolean not null default false;

drop function if exists public.sm_report_create_for(uuid, date, date, text, uuid);
create or replace function public.sm_report_create_for(p_client uuid, p_start date, p_end date, p_kind text, p_brand uuid,
                                                       p_on_request boolean default false)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  rid uuid;
  prev uuid;
  pr public.sm_reports;
  totals jsonb := '{}'::jsonb;
  pgroups jsonb;
  ptk jsonb;
  c public.clients;
  b public.client_brands;
begin
  if me.id is null or not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into c from public.clients where id = p_client;
  if c.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if p_start is null or p_end is null or p_end < p_start then return jsonb_build_object('error', 'bad-period'); end if;
  if coalesce(p_kind, '') not in ('social', 'ads') then return jsonb_build_object('error', 'bad-kind'); end if;
  if p_brand is not null then
    if not public.ops_granted('reports.whitelabel', 'work') then return jsonb_build_object('error', 'denied'); end if;
    select * into b from public.client_brands where id = p_brand;
    if b.id is null or b.client_id <> p_client or not b.active or not c.white_label or c.report_logo is null then
      return jsonb_build_object('error', 'bad-brand');
    end if;
  end if;
  select id into rid from public.sm_reports
   where client_id = p_client and kind = p_kind and period_start = p_start and period_end = p_end
     and brand_id is not distinct from p_brand;
  if rid is not null then return jsonb_build_object('error', 'exists', 'id', rid); end if;
  /* The month's report carries on from the month's before it, never from
     one asked for; one asked for carries its accounts from the latest. */
  select id into prev from public.sm_reports
   where client_id = p_client and kind = p_kind and period_start < p_start and brand_id is not distinct from p_brand
     and (coalesce(p_on_request, false) or not on_request)
   order by period_start desc limit 1;
  perform set_config('adspace.sm_fn', 'on', true);
  begin
    if p_kind = 'ads' then
      /* An Advertising Report asked for compares with the same length just
         before it, typed by the team. */
      if prev is not null and not coalesce(p_on_request, false) then
        select * into pr from public.sm_reports where id = prev;
        select coalesce(jsonb_object_agg(g.objective, jsonb_build_object('results',
                 coalesce(nullif(pr.ads_totals #>> array['groups', g.objective, 'results'], '')::numeric, g.results),
                 'spend', g.spend)), '{}'::jsonb)
          into pgroups
          from (select a.objective, sum(a.results) as results, sum(a.spend) as spend
                  from public.sm_report_ads a where a.report_id = prev and a.platform = 'meta' group by a.objective) g;
        if exists (select 1 from public.sm_report_ads where report_id = prev and platform = 'tiktok')
           or coalesce(pr.ads_totals #>> '{tiktok,reach}', pr.ads_totals #>> '{tiktok,impressions}',
                       pr.ads_totals #>> '{tiktok,spend}') is not null then
          ptk := jsonb_strip_nulls(jsonb_build_object(
            'prev_reach', nullif(pr.ads_totals #>> '{tiktok,reach}', '')::numeric,
            'prev_impressions', coalesce(nullif(pr.ads_totals #>> '{tiktok,impressions}', '')::numeric,
                                         (select sum(impressions) from public.sm_report_ads where report_id = prev and platform = 'tiktok')),
            'prev_spend', coalesce(nullif(pr.ads_totals #>> '{tiktok,spend}', '')::numeric,
                                   (select sum(spend) from public.sm_report_ads where report_id = prev and platform = 'tiktok'))));
        end if;
        totals := jsonb_strip_nulls(jsonb_build_object(
          'prev_start', pr.period_start, 'prev_end', pr.period_end,
          'prev_reach', nullif(pr.ads_totals ->> 'reach', '')::numeric,
          'prev_impressions', coalesce(nullif(pr.ads_totals ->> 'impressions', '')::numeric,
                                       (select sum(impressions) from public.sm_report_ads where report_id = prev and platform = 'meta')),
          'prev_spend', coalesce(nullif(pr.ads_totals ->> 'spend', '')::numeric,
                                 (select sum(spend) from public.sm_report_ads where report_id = prev and platform = 'meta')),
          'prev_groups', pgroups,
          'tiktok', ptk));
      else
        if date_trunc('month', p_start)::date = p_start and (p_start + interval '1 month' - interval '1 day')::date = p_end then
          totals := jsonb_build_object('prev_start', (p_start - interval '1 month')::date, 'prev_end', p_start - 1);
        else
          totals := jsonb_build_object('prev_start', p_start - (p_end - p_start + 1), 'prev_end', p_start - 1);
        end if;
      end if;
      insert into public.sm_reports (client_id, kind, title, period_start, period_end, created_by, first_month, ads_totals,
                                     brand_id, brand_name, label_client, on_request)
      values (p_client, p_kind, 'Social Media Advertising Report', p_start, p_end, me.id, false, totals,
              b.id, b.name, case when b.id is not null then p_client end, coalesce(p_on_request, false))
      returning id into rid;
    else
      insert into public.sm_reports (client_id, kind, period_start, period_end, created_by, brand_id, brand_name, label_client,
                                     on_request)
      values (p_client, p_kind, p_start, p_end, me.id, b.id, b.name, case when b.id is not null then p_client end,
              coalesce(p_on_request, false))
      returning id into rid;
      if prev is not null then
        insert into public.sm_report_platforms (report_id, platform, platform_name, account_name, handle, group_key, group_label,
          position, metrics, followers_start, er_basis, metric_notes)
        select rid, p.platform, p.platform_name, p.account_name, p.handle, p.group_key, p.group_label, p.position, p.metrics,
               coalesce(p.followers_end, case when p.followers_start is not null and p.growth_override is not null
                                              then p.followers_start + p.growth_override end),
               p.er_basis, p.metric_notes
          from public.sm_report_platforms p where p.report_id = prev;
      end if;
    end if;
  exception when unique_violation then
    perform set_config('adspace.sm_fn', 'off', true);
    return jsonb_build_object('error', 'index-pending');
  end;
  perform set_config('adspace.sm_fn', 'off', true);
  perform public.sm_report_log(rid, 'report.created', nullif(concat_ws(' · ',
    case when b.id is not null then 'White label: ' || b.name end,
    case when p_on_request then 'On request' end), ''));
  return jsonb_build_object('ok', true, 'id', rid, 'carried', prev is not null);
end $$;
revoke all on function public.sm_report_create_for(uuid, date, date, text, uuid, boolean) from public, anon;
grant execute on function public.sm_report_create_for(uuid, date, date, text, uuid, boolean) to authenticated;

create or replace function public.sm_report_create(p_client uuid, p_start date, p_end date, p_kind text default 'social')
returns jsonb
language sql security definer set search_path = public as $$
  select public.sm_report_create_for(p_client, p_start, p_end, p_kind, null, false)
$$;
grant execute on function public.sm_report_create(uuid, date, date, text) to authenticated;

create or replace function public.sm_reports_month_gate()
returns trigger
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
begin
  if new.brand_id is not null or new.on_request or new.period_start < date '2026-10-01' or me.id is null then return new; end if;
  if coalesce(me.is_admin, false) or me.role = 'admin' or public.allowed('reports', 'manage') then return new; end if;
  if exists (select 1 from public.ops_engagements e
              cross join lateral public.ops_month_span(e.period, e.start_day) s
              where e.client_id = new.client_id and e.status <> 'cancelled'
                and new.period_end between s.starts and s.ends
                and new.kind = any (coalesce(e.reports, '{}'::text[]))) then
    return new;
  end if;
  raise exception 'month-gate' using errcode = 'P0001';
end $$;
revoke all on function public.sm_reports_month_gate() from public, anon, authenticated;

create or replace function public.sm_report_gate(p_id uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.sm_reports;
  c public.clients;
  e public.ops_engagements;
  task public.ops_tasks;
  v_starts date;
  v_ends date;
  v_due timestamptz;
  v_made integer := 0;
  v_missing text[] := '{}';
begin
  if me.id is null or not public.allowed('reports', 'view') then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_id;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  select * into c from public.clients where id = r.client_id;
  if not public.client_row_seen(c.stage, c.owner, 'view') then return jsonb_build_object('error', 'denied'); end if;
  if r.period_start < date '2026-10-01' or r.on_request then
    return jsonb_build_object('applies', false, 'ok', true, 'missing', '[]'::jsonb, 'on_request', r.on_request);
  end if;
  select x.* into e from public.ops_engagements x
   cross join lateral public.ops_month_span(x.period, x.start_day) s
   where x.client_id = r.client_id and x.status <> 'cancelled'
     and r.period_end between s.starts and s.ends
   order by x.period desc limit 1;
  if e.id is null then
    v_missing := v_missing || 'no-month'::text;
    v_due := ((r.period_end + public.app_setting('report_due_days', r.period_end)::integer)::timestamp + time '23:59') at time zone 'Asia/Kuala_Lumpur';
  else
    select s.starts, s.ends into v_starts, v_ends from public.ops_month_span(e.period, e.start_day) s;
    v_due := ((v_ends + public.app_setting('report_due_days', v_ends)::integer)::timestamp + time '23:59') at time zone 'Asia/Kuala_Lumpur';
    if not (r.kind = any (e.reports)) then
      v_missing := v_missing || 'not-ticked'::text;
    else
      select * into task from public.ops_tasks x
       where x.engagement_id = e.id and x.source_type = 'report_' || r.kind
         and x.cancelled_at is null and x.archived_at is null
       order by x.created_at desc limit 1;
      if task.id is null then
        v_missing := v_missing || 'no-task'::text;
      else
        v_due := coalesce(task.current_final_due_at, v_due);
      end if;
    end if;
    select count(*) into v_made from public.ops_tasks x
     where x.engagement_id = e.id and x.cancelled_at is null and x.archived_at is null
       and coalesce(x.source_type, '') not in ('report_social', 'report_ads');
    if v_made < e.planned_count then v_missing := v_missing || 'content'::text; end if;
  end if;
  return jsonb_build_object(
    'applies', true, 'ok', cardinality(v_missing) = 0, 'missing', to_jsonb(v_missing),
    'month', case when e.id is null then null else jsonb_build_object(
               'id', e.id, 'period', e.period, 'start_day', e.start_day, 'starts', v_starts, 'ends', v_ends,
               'reports', to_jsonb(e.reports)) end,
    'planned', coalesce(e.planned_count, 0), 'made', v_made,
    'task', case when task.id is null then null else jsonb_build_object(
              'id', task.id, 'task_no', task.task_no, 'stage_key', task.stage_key) end,
    'due', v_due, 'late', now() > v_due,
    'may_override', coalesce(me.is_admin, false) or me.role = 'admin' or public.allowed('reports', 'manage'));
end $$;

create or replace function public.sm_reports_task_follow()
returns trigger
language plpgsql security definer set search_path = public as $$
declare
  e public.ops_engagements;
  t public.ops_tasks;
  v_to text;
  v_was uuid;
  v_note text;
begin
  if new.brand_id is not null or new.on_request then return null; end if;
  if tg_op = 'UPDATE' and new.status is not distinct from old.status
     and new.sent_on is not distinct from old.sent_on then
    return null;
  end if;
  v_to := public.sm_report_task_target(new.status, new.sent_on);
  if v_to is null then return null; end if;
  select x.* into e from public.ops_engagements x
   cross join lateral public.ops_month_span(x.period, x.start_day) s
   where x.client_id = new.client_id and x.status <> 'cancelled'
     and new.period_end between s.starts and s.ends
   order by x.period desc limit 1;
  if e.id is null then return null; end if;
  select * into t from public.ops_tasks x
   where x.engagement_id = e.id and x.source_type = 'report_' || new.kind
     and x.cancelled_at is null and x.archived_at is null
   order by x.created_at desc limit 1
   for update;
  if t.id is null or t.completed_at is not null then return null; end if;

  if tg_op = 'INSERT' and new.created_by is not null then
    select team_member_id into v_was from public.ops_task_assignees
     where task_id = t.id and responsibility = 'owner' and ended_at is null;
    if v_was is distinct from new.created_by then
      update public.ops_task_assignees set ended_at = now()
       where task_id = t.id and responsibility = 'owner' and ended_at is null;
      insert into public.ops_task_assignees (task_id, team_member_id, responsibility, assigned_by)
      values (t.id, new.created_by, 'owner', new.created_by);
      perform public.ops_log(t.id, 'assignment_changed',
        jsonb_build_object('owner_id', v_was), jsonb_build_object('owner_id', new.created_by),
        jsonb_build_object('report', true, 'report_id', new.id, 'stage_key', t.stage_key));
    end if;
  end if;

  if t.stage_key is distinct from v_to then
    v_note := case
      when tg_op = 'INSERT' then 'Report started'
      when new.status = 'draft' then 'Report back in draft'
      when new.status = 'review' then 'Report submitted for review'
      when new.status = 'confirmed' then 'Report confirmed'
      when new.sent_on is null then 'Report published'
      else 'Report sent to the client' end;
    update public.ops_tasks set stage_key = v_to, version = version + 1, updated_at = now(),
           completed_at = null, blocked_at = null, blocked_category = null
     where id = t.id;
    perform public.ops_log(t.id, 'stage_changed',
      jsonb_build_object('stage_key', t.stage_key), jsonb_build_object('stage_key', v_to),
      jsonb_build_object('note', v_note, 'report_id', new.id));
  elsif tg_op = 'INSERT' then
    update public.ops_tasks set version = version + 1, updated_at = now() where id = t.id;
  end if;
  return null;
exception when others then
  return null;
end $$;
revoke all on function public.sm_reports_task_follow() from public, anon, authenticated;

create or replace function public.sm_reports_task_reset()
returns trigger
language plpgsql security definer set search_path = public as $$
declare
  t public.ops_tasks;
begin
  if old.brand_id is not null or old.on_request or old.status <> 'draft' then return null; end if;
  select x.* into t from public.ops_tasks x
    join public.ops_engagements e on e.id = x.engagement_id
   cross join lateral public.ops_month_span(e.period, e.start_day) s
   where e.client_id = old.client_id and e.status <> 'cancelled'
     and old.period_end between s.starts and s.ends
     and x.source_type = 'report_' || old.kind
     and x.cancelled_at is null and x.archived_at is null
   order by e.period desc, x.created_at desc limit 1
   for update of x;
  if t.id is null or t.completed_at is not null or t.stage_key = 'todo' then return null; end if;
  update public.ops_tasks set stage_key = 'todo', version = version + 1, updated_at = now(),
         blocked_at = null, blocked_category = null
   where id = t.id;
  perform public.ops_log(t.id, 'stage_changed',
    jsonb_build_object('stage_key', t.stage_key), jsonb_build_object('stage_key', 'todo'),
    jsonb_build_object('note', 'Report deleted', 'report_id', old.id));
  return null;
exception when others then
  return null;
end $$;
revoke all on function public.sm_reports_task_reset() from public, anon, authenticated;

create or replace function public.sm_report_months(p_client uuid, p_kind text default 'social')
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  c public.clients;
begin
  if me.id is null or not public.allowed('reports', 'view') then return jsonb_build_object('error', 'denied'); end if;
  if coalesce(p_kind, '') not in ('social', 'ads') then return jsonb_build_object('error', 'bad-kind'); end if;
  select * into c from public.clients where id = p_client;
  if c.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if not public.client_row_seen(c.stage, c.owner, 'view') then return jsonb_build_object('error', 'denied'); end if;
  return jsonb_build_object(
    'may_override', coalesce(me.is_admin, false) or me.role = 'admin' or public.allowed('reports', 'manage'),
    'months', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', e.id, 'period', e.period, 'start_day', e.start_day,
               'starts', s.starts, 'ends', s.ends, 'status', e.status,
               'asks', p_kind = any (coalesce(e.reports, '{}'::text[])),
               'report', (select r.id from public.sm_reports r
                           where r.client_id = e.client_id and r.kind = p_kind and r.brand_id is null
                             and not r.on_request and r.period_end between s.starts and s.ends
                           order by r.period_start desc limit 1))
             order by e.period desc)
        from public.ops_engagements e
       cross join lateral public.ops_month_span(e.period, e.start_day) s
       where e.client_id = p_client and e.status <> 'cancelled'), '[]'::jsonb));
end $$;

create or replace function public.sm_reports_owed(p_period text default null)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_period   text := coalesce(nullif(btrim(p_period), ''),
                       to_char(date_trunc('month', now() at time zone 'Asia/Kuala_Lumpur') - interval '1 month', 'YYYY-MM'));
  v_items    jsonb := '[]'::jsonb;
  v_seen     uuid[] := '{}';
  v_task     uuid;
  v_tdue     timestamptz;
  v_assignee text;
  v_due      timestamptz;
  v_found    boolean;
  e          record;
  k          text;
  r          record;
begin
  if not public.allowed('reports', 'manage') then return jsonb_build_object('error', 'denied'); end if;
  if v_period !~ '^[0-9]{4}-(0[1-9]|1[0-2])$' then return jsonb_build_object('error', 'bad-period'); end if;

  -- Every report a month of the period asks for, found or not started.
  for e in
    select x.id, x.client_id, x.reports, s.starts, s.ends, c.name as client_name, c.slug as client_slug
      from public.ops_engagements x
      join public.clients c on c.id = x.client_id
     cross join lateral public.ops_month_span(x.period, x.start_day) s
     where x.period = v_period and x.status <> 'cancelled' and cardinality(x.reports) > 0
       and public.client_row_seen(c.stage, c.owner, 'view')
     order by c.name
  loop
    foreach k in array e.reports loop
      v_task := null; v_tdue := null; v_assignee := null;
      select x.id, x.current_final_due_at, m.name into v_task, v_tdue, v_assignee
        from public.ops_tasks x
        left join public.ops_task_assignees a
          on a.task_id = x.id and a.responsibility = 'owner' and a.ended_at is null
        left join public.team_members m on m.id = a.team_member_id
       where x.engagement_id = e.id and x.source_type = 'report_' || k
         and x.cancelled_at is null and x.archived_at is null
       order by x.created_at desc limit 1;
      v_due := coalesce(v_tdue,
        ((e.ends + public.app_setting('report_due_days', e.ends)::integer)::timestamp + time '23:59') at time zone 'Asia/Kuala_Lumpur');
      v_found := false;
      for r in
        select y.id, y.status, y.sent_on, b.name as brand_name
          from public.sm_reports y
          left join public.client_brands b on b.id = y.brand_id
         where y.client_id = e.client_id and y.kind = k and not y.on_request
           and y.period_end between e.starts and e.ends
         order by b.name nulls first, y.period_start
      loop
        v_found := true;
        v_seen := v_seen || r.id;
        v_items := v_items || jsonb_build_object(
          'client_id', e.client_id, 'client', e.client_name, 'slug', e.client_slug, 'kind', k,
          'brand', r.brand_name, 'report_id', r.id, 'status', r.status, 'sent_on', r.sent_on,
          'asked', true, 'task_id', v_task, 'assignee', v_assignee, 'due', v_due,
          'late', r.status <> 'published' and now() > v_due);
      end loop;
      if not v_found then
        v_items := v_items || jsonb_build_object(
          'client_id', e.client_id, 'client', e.client_name, 'slug', e.client_slug, 'kind', k,
          'brand', null, 'report_id', null, 'status', 'none', 'sent_on', null,
          'asked', true, 'task_id', v_task, 'assignee', v_assignee, 'due', v_due, 'late', now() > v_due);
      end if;
    end loop;
  end loop;

  -- Every report made for the period that no month's tick asked for: it
  -- belongs to the month whose span holds its last day, else to the
  -- calendar month of that day.
  for r in
    select y.id, y.client_id, y.kind, y.status, y.sent_on, y.period_end,
           c.name as client_name, c.slug as client_slug, b.name as brand_name
      from public.sm_reports y
      join public.clients c on c.id = y.client_id
      left join public.client_brands b on b.id = y.brand_id
     where not (y.id = any (v_seen)) and not y.on_request
       and coalesce((select x.period from public.ops_engagements x
                      cross join lateral public.ops_month_span(x.period, x.start_day) s
                      where x.client_id = y.client_id and x.status <> 'cancelled'
                        and y.period_end between s.starts and s.ends
                      order by x.period desc limit 1),
                    to_char(y.period_end, 'YYYY-MM')) = v_period
       and public.client_row_seen(c.stage, c.owner, 'view')
     order by c.name, y.kind, b.name nulls first
  loop
    v_due := ((r.period_end + public.app_setting('report_due_days', r.period_end)::integer)::timestamp + time '23:59') at time zone 'Asia/Kuala_Lumpur';
    v_items := v_items || jsonb_build_object(
      'client_id', r.client_id, 'client', r.client_name, 'slug', r.client_slug, 'kind', r.kind,
      'brand', r.brand_name, 'report_id', r.id, 'status', r.status, 'sent_on', r.sent_on,
      'asked', false, 'task_id', null, 'assignee', null, 'due', v_due,
      'late', r.status <> 'published' and now() > v_due);
  end loop;

  return jsonb_build_object('period', v_period, 'items', v_items);
end $$;
revoke all on function public.sm_reports_owed(text) from public, anon, authenticated;
grant execute on function public.sm_reports_owed(text) to authenticated;

-- END OF REPORTS ON REQUEST --------------------------------------------------

-- ===========================================================================
-- ONE CHECK A MINUTE — an open page's minute check is one request: upgrade
-- mode, the announcements and the bell answered together.
-- 2026-10-09. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/smsql.js compares the
-- two.
--
-- WHAT CHANGED
--   Supabase's usage page (the user, 2026-10-09: "why is it using so much")
--   showed log ingestion near its allowance: every request the portal makes
--   is a logged line of about 2.8 KB. An open console asked four times a
--   minute (upgrade mode, the announcements, the bell's unread and its
--   earlier notices) and a client page twice, about a seventh of all logged
--   requests. `page_pulse(p_audience, p_bell)` answers them in one:
--   `maintenance` as `maintenance_state()` answers it, `announcements` as
--   `announcement_now(p_audience)` does (where an audience is named), and,
--   with `p_bell` for a signed-in colleague, `bell`: their own unread
--   notices (thirty, newest first) and the read ones of the last seven days
--   (ten), never one withdrawn. Each part keeps its own function's rules;
--   nobody reads more than they read before. A page whose database holds no
--   `page_pulse` asks each part alone, as before. It joins `open_to_anon`
--   (FUNCTION HYGIENE): run 2026-10-07-function-hygiene.sql again BEFORE
--   this file, so the tidy at its foot keeps it open.
--
-- ROLLBACK
--   Pages fall back to the three reads by themselves:
--     drop function if exists public.page_pulse(text, boolean);
-- ===========================================================================

create or replace function public.page_pulse(p_audience text default null, p_bell boolean default false)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  me public.team_members;
  v  jsonb := jsonb_build_object('maintenance', public.maintenance_state());
begin
  if p_audience in ('team', 'clients') then
    v := v || jsonb_build_object('announcements', coalesce(public.announcement_now(p_audience), '[]'::jsonb));
  end if;
  if coalesce(p_bell, false) then
    me := public.ops_me();
    if me.id is not null then
      v := v || jsonb_build_object('bell', jsonb_build_object(
        'unread', coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at desc)
                              from (select * from public.ops_notifications o
                                     where o.team_member_id = me.id and o.read_at is null and o.hidden_at is null
                                     order by o.created_at desc limit 30) x), '[]'::jsonb),
        'earlier', coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at desc)
                               from (select * from public.ops_notifications o
                                      where o.team_member_id = me.id and o.read_at is not null and o.hidden_at is null
                                        and o.created_at >= now() - interval '7 days'
                                      order by o.created_at desc limit 10) x), '[]'::jsonb)));
    end if;
  end if;
  return v;
end $$;
revoke all on function public.page_pulse(text, boolean) from public;
grant execute on function public.page_pulse(text, boolean) to anon, authenticated;

-- END OF ONE CHECK A MINUTE --------------------------------------------------

-- ===========================================================================
-- ON-SITE MEETINGS — a content meeting held at the client's may be recorded
-- after the day, and whoever led it is reminded to submit the outstation
-- record.
-- 2026-10-09. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/ops.js compares the
-- two.
--
-- WHAT CHANGED
--   The user, 2026-10-09: "on-site please allow add past date. and add one
--   more reminder for on-site to submit the outstation record
--   (go.adspace.me/outstation)".
--   1. `ops_engagement_set_meeting` accepts a first date in the past for an
--      on-site meeting (channel `onsite`): it was held, and is written down
--      afterwards. An online meeting is still put in the diary from today.
--   2. `ops_notifications.link`: an https address a notice opens (the bell
--      and a push alike), in place of a console page.
--   3. `ops_outstation_remind()` (pg_cron `outstation-reminder`, every
--      fifteen minutes): each on-site meeting that has ended tells whoever
--      led it (else the month's manager), once, to submit the outstation
--      record (kind `outstation`, the form's address as its link).
--      `ops_engagements.outstation_told_at` keeps that it was told; a
--      meeting moved to another time is told again for the new one. The
--      on-site meetings that ended before this file are counted as told.
--
-- ROLLBACK
--   select cron.unschedule('outstation-reminder');
--   drop function if exists public.ops_outstation_remind();
--   Re-run 2026-09-24-content-meeting-google-meet.sql for
--   ops_engagement_set_meeting and 2026-10-08-tasks-reminder.sql for
--   ops_notifications_push, then:
--   alter table public.ops_engagements drop column if exists outstation_told_at;
--   alter table public.ops_notifications drop column if exists link;
-- ===========================================================================

alter table public.ops_engagements add column if not exists outstation_told_at timestamptz;
alter table public.ops_notifications add column if not exists link text;
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'ops_notifications_link_https') then
    alter table public.ops_notifications add constraint ops_notifications_link_https
      check (link is null or link ~* '^https://');
  end if;
end $$;

/* The on-site meetings that ended before reminders began were never owed
   one. */
update public.ops_engagements e set outstation_told_at = e.updated_at
 where e.meeting_channel = 'onsite' and e.outstation_told_at is null
   and e.meeting_at is not null and e.meeting_at < timestamptz '2026-10-09 16:00:00+00'
   and e.updated_at < timestamptz '2026-10-09 16:00:00+00';

/* The content meeting. Put in the diary, an online meeting's first date is
   today or later; an on-site one may be written down after it was held.
   Once held the record stays as it was, because a past meeting is a fact
   and not a mistake. Not applicable is its own answer, and clears the link.
   A link is Google Meet's, Zoom's or Teams', never anything else, because
   it is sent to a client as it stands. A meeting moved to another time owes
   its outstation reminder again. */
create or replace function public.ops_engagement_set_meeting(
  p_engagement uuid, p_at timestamptz, p_channel text default null,
  p_owner uuid default null, p_note text default null, p_na boolean default false,
  p_minutes integer default null, p_link text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare m public.team_members; e public.ops_engagements; lk text;
begin
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if not public.allowed('ops', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if not public.ops_may_see_engagement(p_engagement) then return jsonb_build_object('error', 'denied'); end if;
  select * into e from public.ops_engagements where id = p_engagement for update;
  if e.id is null then return jsonb_build_object('error', 'not-found'); end if;

  if coalesce(p_na, false) then
    update public.ops_engagements set meeting_na = true, meeting_note = coalesce(p_note, meeting_note),
           meeting_link = null, updated_at = now(), version = version + 1 where id = p_engagement;
    perform public.ops_engagement_log(p_engagement, 'meeting_na', jsonb_build_object('note', p_note));
    return public.ops_engagement_json(p_engagement);
  end if;
  if p_at is null then return jsonb_build_object('error', 'no-date'); end if;
  if p_channel is not null and p_channel not in ('onsite', 'google_meet', 'zoom', 'other') then
    return jsonb_build_object('error', 'bad-channel');
  end if;
  if e.meeting_at is null and p_at::date < current_date
     and coalesce(p_channel, e.meeting_channel, '') <> 'onsite' then
    return jsonb_build_object('error', 'meeting-in-past');
  end if;
  if p_minutes is not null and (p_minutes < 15 or p_minutes > 240) then
    return jsonb_build_object('error', 'bad-minutes');
  end if;
  lk := nullif(btrim(coalesce(p_link, '')), '');
  if lk is not null and lk !~* '^https://([a-z0-9-]+\.)*(meet\.google\.com|zoom\.us|teams\.microsoft\.com|teams\.live\.com)/' then
    return jsonb_build_object('error', 'bad-meeting-link');
  end if;
  update public.ops_engagements set
    meeting_at = p_at, meeting_channel = coalesce(p_channel, meeting_channel),
    meeting_owner_id = coalesce(p_owner, meeting_owner_id, m.id),
    meeting_note = case when p_note is null then meeting_note else nullif(btrim(p_note), '') end,
    meeting_minutes = coalesce(p_minutes, meeting_minutes),
    meeting_link = case when p_link is null then meeting_link else lk end,
    outstation_told_at = case when e.meeting_at is distinct from p_at then null else outstation_told_at end,
    meeting_na = false, updated_at = now(), version = version + 1
  where id = p_engagement;
  perform public.ops_engagement_log(p_engagement, 'meeting_set',
    jsonb_build_object('at', p_at, 'channel', p_channel, 'owner_id', p_owner, 'was', e.meeting_at,
                       'minutes', p_minutes));
  return public.ops_engagement_json(p_engagement);
end $$;
grant execute on function public.ops_engagement_set_meeting(uuid, timestamptz, text, uuid, text, boolean, integer, text) to authenticated;

/* Each on-site meeting that has ended tells whoever led it, once, to submit
   the outstation record; a meeting nobody leads tells the month's manager.
   Run by pg_cron alone. */
create or replace function public.ops_outstation_remind()
returns integer
language plpgsql security definer set search_path = public as $$
declare r record; n integer := 0;
begin
  for r in
    select e.id, e.meeting_at, coalesce(e.meeting_owner_id, e.manager_id) as who, c.name as client_name
      from public.ops_engagements e
      left join public.clients c on c.id = e.client_id
     where e.meeting_channel = 'onsite' and not e.meeting_na and e.meeting_at is not null
       and e.outstation_told_at is null
       and e.meeting_at + make_interval(mins => coalesce(e.meeting_minutes, 30)) <= now()
       and coalesce(e.status, '') <> 'cancelled'
     for update of e skip locked
  loop
    if r.who is not null and exists (select 1 from public.team_members t where t.id = r.who and t.active) then
      insert into public.ops_notifications (team_member_id, kind, title, body, link, dedupe_key)
      values (r.who, 'outstation', 'Submit the outstation record',
              coalesce(r.client_name, 'Client') || ' · on-site meeting on ' ||
                public.register_day((r.meeting_at at time zone 'Asia/Kuala_Lumpur')::date),
              'https://go.adspace.me/outstation',
              'outstation.' || r.id::text || '.' || extract(epoch from r.meeting_at)::bigint::text)
      on conflict (dedupe_key) do nothing;
      n := n + 1;
    end if;
    update public.ops_engagements set outstation_told_at = now() where id = r.id;
  end loop;
  return n;
end $$;
revoke all on function public.ops_outstation_remind() from public, anon, authenticated;

/* A notice with a link opens it, on a phone as in the bell. */
create or replace function public.ops_notifications_push()
returns trigger
language plpgsql security definer set search_path = public as $$
declare
  v_title text := coalesce(nullif(btrim(new.title), ''), 'My Work');
  v_body  text := coalesce(new.body, '');
begin
  perform public.push_queue('team', new.team_member_id,
    jsonb_build_object('en', jsonb_build_object('title', v_title, 'body', v_body),
                       'zh', jsonb_build_object('title', v_title, 'body', v_body)),
    case when new.link is not null then new.link
         when new.task_id is not null then '/admin/?s=work&open=' || new.task_id::text
         when new.report_id is not null then '/admin/?s=reports&report=' || new.report_id::text
         when new.kind in ('client_left', 'tasks.empty') then '/admin/?s=work'
         when new.kind = 'hr.letter' then '/admin/?s=mine&view=letters'
         when new.kind = 'perf.disputed' then '/admin/?s=team&tab=performance'
         when new.kind = 'perf.reflect' then '/admin/?s=mine&view=reflection'
         when new.kind = 'perf.initiative' then '/admin/?s=mine&view=initiatives'
         when new.kind like 'health.%' then '/admin/?s=mine&view=health'
         when new.kind like 'perf.%' then '/admin/?s=mine'
         else '/admin/' end,
    case when new.task_id is not null then 'task-' || new.task_id::text
         when new.report_id is not null then 'report-' || new.report_id::text
         when new.kind = 'hr.letter' then 'hr-letter'
         when new.kind in ('perf.remind', 'perf.reflect', 'health.remind') then 'my-hr'
         when new.kind = 'tasks.empty' then 'tasks-empty'
         when new.kind = 'outstation' then 'outstation'
         else null end);
  return new;
exception when others then
  return new;
end $$;

do $$
begin
  if not exists (select 1 from pg_extension where extname = 'pg_cron') then
    raise notice 'pg_cron is not enabled: no outstation reminders go out until it is.';
    return;
  end if;
  perform cron.unschedule(j.jobid) from cron.job j where j.jobname = 'outstation-reminder';
  perform cron.schedule('outstation-reminder', '*/15 * * * *', 'select public.ops_outstation_remind()');
end $$;

-- END OF ON-SITE MEETINGS -----------------------------------------------------

-- ===========================================================================
-- VIDEO SCRIPTS — a shoot's scripts, one a video, read and approved by the
-- client online and ticked by the crew on the day.
-- 2026-10-09. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/vssql.js compares the
-- two.
--
-- WHAT CHANGED
--   The user (2026-10-09): "a script table covers one video, hence there is
--   a # … three different types of script, detailed scenes / products +
--   scenes / story + VO. VC# is the video clip number on camera … one
--   digital similar as content review able to view online, another is export
--   pdf for on-site use."
--   1. `video_scripts`: one video's script. Its kind (`scenes` Detailed
--      scenes, `products` Products and scenes, `story` Story and voice-over),
--      its number in its shoot (`series_id`, `video_no`: V1, V2…), the
--      header (title, reference link, platform, language, shooting date and
--      time, venue, estimated duration, cast), the context a products or
--      story script opens on, the voice-over a story script is read from
--      (`vo`, with its own clip number and tick), and the notes. A draft
--      until shared; `round` counts what the client decided on (kind, title,
--      reference, context, script, scenes): a change to one of those after
--      the client decided on the round is the next round, and a change
--      before any decision is a correction.
--   2. `video_script_scenes`: the scenes in order, each what is seen
--      (`visual`) and, on a detailed script, what is said (`line`), with the
--      crew's clip number (`vc`) and tick (`shot_at`, `shot_by`). A scene
--      moved or reworded keeps its clip number and its tick.
--   3. `video_script_reviews`: the client's decision on a round (Approved,
--      Changes requested with a note) under the name they typed, never
--      removed.
--   4. Video Scripts is a section of its own on the ladder (`scripts`), every
--      group starting at its Content Review level, once. The tables read at
--      View under the client scope rule; every write is a function:
--      `video_script_create(p_client, p_kind, p_from, p_idem)` (`p_from` a
--      video of the shoot: the next number, its header copied, the script
--      empty; the same press twice the same video),
--      `video_script_save(p_id, p_head, p_scenes, p_version)` (one save for
--      the whole script, filed from and to, `stale` with the row as it
--      stands), `video_script_share(p_ids, p_on)`,
--      `video_script_shot(p_script, p_scene, p_on, p_vc)` (on the day; never
--      a round), `video_script_delete(p_id, p_typed)` (Full Access, the title
--      typed back, else V and the number) and `script_link(p_client,
--      p_reset)` (the client's own key, `clients.script_key`, made on first
--      asking; a reset retires the old one). Each is filed under the client
--      (`script.*`, the Video Scripts tab).
--   5. The client's page (`/script/?k=`) reads only through
--      `get_scripts(p_token)` (the shared videos, their scenes, the decision
--      on the round on show and the request it answers; never a colleague's
--      name, a clip number, a tick or the version) and decides through
--      `script_decide(p_token, p_script, p_decision, p_name, p_note)`, which
--      tells the colleague who made the video
--      (`ops_notifications.script_id`, kind `script`, opening the script).
--      Both join `open_to_anon` (FUNCTION HYGIENE): run
--      2026-10-07-function-hygiene.sql again BEFORE this file, so the tidy
--      at its foot keeps them open.
--
-- ROLLBACK
--   Pages first (the section reads "This needs a database update."), then:
--     drop function if exists public.script_decide(text, uuid, text, text, text);
--     drop function if exists public.get_scripts(text);
--     drop function if exists public.video_script_delete(uuid, text);
--     drop function if exists public.video_script_shot(uuid, uuid, boolean, text);
--     drop function if exists public.video_script_share(uuid[], boolean);
--     drop function if exists public.script_link(uuid, boolean);
--     drop function if exists public.video_script_save(uuid, jsonb, jsonb, integer);
--     drop function if exists public.video_script_create(uuid, text, uuid, text);
--     drop function if exists public.video_script_label(public.video_scripts);
--     drop table if exists public.video_script_reviews, public.video_script_scenes, public.video_scripts;
--     alter table public.clients drop column if exists script_key;
--     alter table public.ops_notifications drop column if exists script_id;
--   and re-run ops_notifications_push and activity_section from the band
--   before this one.
-- ===========================================================================

create table if not exists public.video_scripts (
  id               uuid primary key default gen_random_uuid(),
  client_id        uuid not null references public.clients(id) on delete cascade,
  series_id        uuid not null default gen_random_uuid(),
  video_no         integer not null default 1 check (video_no between 1 and 99),
  kind             text not null default 'scenes' check (kind in ('scenes', 'products', 'story')),
  title            text not null default '',
  reference_url    text check (reference_url is null or reference_url ~ '^https://'),
  platform         text,
  language         text,
  shoot_on         date,
  shoot_time       time,
  venue            text,
  duration_minutes integer check (duration_minutes is null or duration_minutes between 5 and 1440),
  cast_names       text,
  context          text,
  vo               text,
  vo_vc            text,
  vo_shot_at       timestamptz,
  vo_shot_by       text,
  remarks          text,
  status           text not null default 'draft' check (status in ('draft', 'shared')),
  shared_at        timestamptz,
  round            integer not null default 1,
  version          integer not null default 1,
  idem_key         text unique,
  created_by       uuid,
  created_by_name  text,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  updated_by_name  text,
  unique (series_id, video_no)
);
create index if not exists video_scripts_client_idx on public.video_scripts(client_id, created_at desc);

create table if not exists public.video_script_scenes (
  id        uuid primary key default gen_random_uuid(),
  script_id uuid not null references public.video_scripts(id) on delete cascade,
  position  integer not null,
  visual    text,
  line      text,
  vc        text,
  shot_at   timestamptz,
  shot_by   text
);
create index if not exists video_script_scenes_script_idx on public.video_script_scenes(script_id, position);

create table if not exists public.video_script_reviews (
  id         uuid primary key default gen_random_uuid(),
  script_id  uuid not null references public.video_scripts(id) on delete cascade,
  round      integer not null,
  decision   text not null check (decision in ('approved', 'changes')),
  note       text,
  reviewer   text not null,
  created_at timestamptz not null default now()
);
create index if not exists video_script_reviews_script_idx on public.video_script_reviews(script_id, round, created_at desc);

alter table public.clients add column if not exists script_key text;
create unique index if not exists clients_script_key_idx on public.clients(script_key) where script_key is not null;
alter table public.ops_notifications add column if not exists script_id uuid;

alter table public.video_scripts enable row level security;
alter table public.video_script_scenes enable row level security;
alter table public.video_script_reviews enable row level security;

drop policy if exists video_scripts_read on public.video_scripts;
create policy video_scripts_read on public.video_scripts for select to authenticated
  using (public.allowed('scripts', 'view'));
drop policy if exists client_scope on public.video_scripts;
create policy client_scope on public.video_scripts as restrictive for select to authenticated
  using ((select public.client_scope_free('view')) or public.client_scope_ok('client', client_id, 'view'));
create or replace trigger client_scope_guard before insert or update on public.video_scripts
  for each row execute function public.client_scope_guard('client', 'client_id');

drop policy if exists video_script_scenes_read on public.video_script_scenes;
create policy video_script_scenes_read on public.video_script_scenes for select to authenticated
  using (public.allowed('scripts', 'view')
         and exists (select 1 from public.video_scripts s where s.id = video_script_scenes.script_id));
drop policy if exists video_script_reviews_read on public.video_script_reviews;
create policy video_script_reviews_read on public.video_script_reviews for select to authenticated
  using (public.allowed('scripts', 'view')
         and exists (select 1 from public.video_scripts s where s.id = video_script_reviews.script_id));

-- Every group starts at its Content Review level, once.
update public.team_roles
   set access = access || jsonb_build_object('scripts', coalesce(access ->> 'review', 'none'))
 where not (access ? 'scripts');
update public.team_members
   set access = access || jsonb_build_object('scripts', coalesce(access ->> 'review', 'none'))
 where not (access ? 'scripts');

-- V1 · Title, as every screen and the activity record name a video.
create or replace function public.video_script_label(p public.video_scripts)
returns text language sql immutable set search_path = public as $$
  select 'V' || p.video_no || coalesce(' · ' || nullif(btrim(p.title), ''), '')
$$;
revoke all on function public.video_script_label(public.video_scripts) from public, anon, authenticated;

create or replace function public.video_script_create(p_client uuid, p_kind text, p_from uuid default null,
                                                      p_idem text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me     public.team_members := public.ops_me();
  f      public.video_scripts;
  v_cl   public.clients;
  v_kind text;
  v_ser  uuid;
  v_no   integer;
  v_id   uuid;
  v_new  public.video_scripts;
begin
  if me.id is null or not public.allowed('scripts', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if nullif(btrim(coalesce(p_idem, '')), '') is not null then
    select s.id into v_id from public.video_scripts s where s.idem_key = p_idem;
    if v_id is not null then return jsonb_build_object('ok', true, 'id', v_id, 'again', true); end if;
  end if;
  if p_from is not null then
    select * into f from public.video_scripts s where s.id = p_from;
    if f.id is null or (p_client is not null and p_client <> f.client_id) then
      return jsonb_build_object('error', 'not-found');
    end if;
    v_ser := f.series_id;
  else
    v_ser := gen_random_uuid();
  end if;
  select * into v_cl from public.clients c where c.id = coalesce(f.client_id, p_client);
  if v_cl.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if not public.client_seen(v_cl.id, 'work') then return jsonb_build_object('error', 'client-scope'); end if;
  v_kind := coalesce(nullif(btrim(coalesce(p_kind, '')), ''), f.kind, 'scenes');
  if v_kind not in ('scenes', 'products', 'story') then return jsonb_build_object('error', 'bad-kind'); end if;
  perform pg_advisory_xact_lock(hashtext('video_script:' || v_ser::text));
  select coalesce(max(s.video_no), 0) + 1 into v_no from public.video_scripts s where s.series_id = v_ser;
  if v_no > 99 then return jsonb_build_object('error', 'too-many'); end if;
  insert into public.video_scripts (client_id, series_id, video_no, kind, platform, language, shoot_on,
                                    shoot_time, venue, duration_minutes, cast_names, idem_key,
                                    created_by, created_by_name, updated_by_name)
  values (v_cl.id, v_ser, v_no, v_kind, f.platform, f.language, f.shoot_on, f.shoot_time, f.venue,
          f.duration_minutes, f.cast_names, nullif(btrim(coalesce(p_idem, '')), ''), me.id, me.name, me.name)
  returning * into v_new;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'script.created', v_cl.name,
          public.video_script_label(v_new) || ' · '
          || case v_kind when 'scenes' then 'Detailed scenes' when 'products' then 'Products and scenes'
                         else 'Story and voice-over' end
          || case when f.id is not null then ' · header from V' || f.video_no else '' end);
  return jsonb_build_object('ok', true, 'id', v_new.id, 'series_id', v_ser, 'video_no', v_no);
end $$;
revoke all on function public.video_script_create(uuid, text, uuid, text) from public, anon;
grant execute on function public.video_script_create(uuid, text, uuid, text) to authenticated;

/* One save for the whole script: the header facts named in `p_head` (a key
   left out keeps its value) and, where `p_scenes` is given, the scene rows
   in order ({id, visual, line}; a row named by its id keeps its clip number
   and its tick). A change to what the client decides on, once they have
   decided on this round, starts the next round. Files what changed, from
   and to for a short value, by name for the long ones. */
create or replace function public.video_script_save(p_id uuid, p_head jsonb, p_scenes jsonb, p_version integer default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me        public.team_members := public.ops_me();
  v         public.video_scripts;
  n         public.video_scripts;
  v_client  text;
  h         jsonb := coalesce(p_head, '{}'::jsonb);
  v_moves   text[] := '{}';
  v_creat   boolean := false;
  v_old_sc  jsonb;
  v_new_sc  jsonb;
  v_row     jsonb;
  v_pos     integer := 0;
  v_keep    uuid[] := '{}';
  v_sid     uuid;
  v_kindw   text;
begin
  if me.id is null or not public.allowed('scripts', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into v from public.video_scripts s where s.id = p_id for update;
  if v.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if not public.client_seen(v.client_id, 'work') then return jsonb_build_object('error', 'client-scope'); end if;
  if p_version is not null and p_version <> v.version then
    return jsonb_build_object('error', 'stale', 'row', to_jsonb(v));
  end if;
  n := v;
  if h ? 'kind' then n.kind := h ->> 'kind'; end if;
  if h ? 'title' then n.title := btrim(coalesce(h ->> 'title', '')); end if;
  if h ? 'reference_url' then n.reference_url := nullif(btrim(coalesce(h ->> 'reference_url', '')), ''); end if;
  if h ? 'platform' then n.platform := nullif(btrim(coalesce(h ->> 'platform', '')), ''); end if;
  if h ? 'language' then n.language := nullif(btrim(coalesce(h ->> 'language', '')), ''); end if;
  if h ? 'shoot_on' then n.shoot_on := nullif(h ->> 'shoot_on', '')::date; end if;
  if h ? 'shoot_time' then n.shoot_time := nullif(h ->> 'shoot_time', '')::time; end if;
  if h ? 'venue' then n.venue := nullif(btrim(coalesce(h ->> 'venue', '')), ''); end if;
  if h ? 'duration_minutes' then n.duration_minutes := nullif(h ->> 'duration_minutes', '')::integer; end if;
  if h ? 'cast_names' then n.cast_names := nullif(btrim(coalesce(h ->> 'cast_names', '')), ''); end if;
  if h ? 'context' then n.context := nullif(btrim(coalesce(h ->> 'context', '')), ''); end if;
  if h ? 'vo' then n.vo := nullif(btrim(coalesce(h ->> 'vo', '')), ''); end if;
  if h ? 'remarks' then n.remarks := nullif(btrim(coalesce(h ->> 'remarks', '')), ''); end if;

  if n.kind not in ('scenes', 'products', 'story') then return jsonb_build_object('error', 'bad-kind'); end if;
  if length(n.title) > 200 then return jsonb_build_object('error', 'bad-title'); end if;
  if n.reference_url is not null and (n.reference_url !~ '^https://' or length(n.reference_url) > 1000) then
    return jsonb_build_object('error', 'bad-link');
  end if;
  if n.duration_minutes is not null and n.duration_minutes not between 5 and 1440 then
    return jsonb_build_object('error', 'bad-duration');
  end if;
  if n.shoot_on is not null and n.shoot_on not between date '2023-08-14' and date '2099-12-31' then
    return jsonb_build_object('error', 'bad-date');
  end if;
  if greatest(length(coalesce(n.platform, '')), length(coalesce(n.language, '')), length(coalesce(n.venue, ''))) > 200
     or greatest(length(coalesce(n.cast_names, '')), length(coalesce(n.context, '')),
                 length(coalesce(n.vo, '')), length(coalesce(n.remarks, ''))) > 4000 then
    return jsonb_build_object('error', 'too-long');
  end if;
  if p_scenes is not null then
    if jsonb_typeof(p_scenes) <> 'array' then return jsonb_build_object('error', 'bad-scenes'); end if;
    if jsonb_array_length(p_scenes) > 60 then return jsonb_build_object('error', 'too-many'); end if;
    if exists (select 1 from jsonb_array_elements(p_scenes) e
                where length(coalesce(e.value ->> 'visual', '')) > 2000
                   or length(coalesce(e.value ->> 'line', '')) > 2000) then
      return jsonb_build_object('error', 'too-long');
    end if;
  end if;

  v_kindw := case n.kind when 'products' then 'Products and context' when 'story' then 'Hook and story' else 'Context' end;
  if n.kind is distinct from v.kind then
    v_creat := true;
    v_moves := v_moves || ('Kind: ' || case v.kind when 'scenes' then 'Detailed scenes' when 'products' then 'Products and scenes' else 'Story and voice-over' end
                           || ' → ' || case n.kind when 'scenes' then 'Detailed scenes' when 'products' then 'Products and scenes' else 'Story and voice-over' end);
  end if;
  if n.title is distinct from v.title then
    v_creat := true;
    v_moves := v_moves || ('Title: ' || coalesce(nullif(v.title, ''), 'not set') || ' → ' || coalesce(nullif(n.title, ''), 'not set'));
  end if;
  if n.reference_url is distinct from v.reference_url then
    v_creat := true;
    v_moves := v_moves || ('Reference: ' || coalesce(v.reference_url, 'not set') || ' → ' || coalesce(n.reference_url, 'not set'));
  end if;
  if n.platform is distinct from v.platform then
    v_moves := v_moves || ('Platform: ' || coalesce(v.platform, 'not set') || ' → ' || coalesce(n.platform, 'not set'));
  end if;
  if n.language is distinct from v.language then
    v_moves := v_moves || ('Language: ' || coalesce(v.language, 'not set') || ' → ' || coalesce(n.language, 'not set'));
  end if;
  if n.shoot_on is distinct from v.shoot_on then
    v_moves := v_moves || ('Shooting date: '
      || coalesce(replace(to_char(v.shoot_on, 'FMDD Mon YYYY'), 'Sep ', 'Sept '), 'not set') || ' → '
      || coalesce(replace(to_char(n.shoot_on, 'FMDD Mon YYYY'), 'Sep ', 'Sept '), 'not set'));
  end if;
  if n.shoot_time is distinct from v.shoot_time then
    v_moves := v_moves || ('Shooting time: ' || coalesce(to_char(v.shoot_time, 'FMHH12:MI am'), 'not set')
                           || ' → ' || coalesce(to_char(n.shoot_time, 'FMHH12:MI am'), 'not set'));
  end if;
  if n.venue is distinct from v.venue then
    v_moves := v_moves || ('Venue: ' || coalesce(v.venue, 'not set') || ' → ' || coalesce(n.venue, 'not set'));
  end if;
  if n.duration_minutes is distinct from v.duration_minutes then
    v_moves := v_moves || ('Duration: ' || coalesce(v.duration_minutes || ' min', 'not set') || ' → '
                           || coalesce(n.duration_minutes || ' min', 'not set'));
  end if;
  if n.cast_names is distinct from v.cast_names then v_moves := v_moves || 'Cast'::text; end if;
  if n.context is distinct from v.context then v_creat := true; v_moves := v_moves || v_kindw; end if;
  if n.vo is distinct from v.vo then v_creat := true; v_moves := v_moves || 'Script (read here)'::text; end if;
  if n.remarks is distinct from v.remarks then v_moves := v_moves || 'Notes'::text; end if;

  if p_scenes is not null then
    select coalesce(jsonb_agg(jsonb_build_object('visual', coalesce(sc.visual, ''), 'line', coalesce(sc.line, ''))
                              order by sc.position), '[]'::jsonb)
      into v_old_sc from public.video_script_scenes sc where sc.script_id = p_id;
    select coalesce(jsonb_agg(jsonb_build_object('visual', btrim(coalesce(e.value ->> 'visual', '')),
                                                 'line', btrim(coalesce(e.value ->> 'line', '')))
                              order by e.ord), '[]'::jsonb)
      into v_new_sc from jsonb_array_elements(p_scenes) with ordinality as e(value, ord);
    if v_new_sc is distinct from v_old_sc then
      v_creat := true;
      v_moves := v_moves || ('Scenes' || case when jsonb_array_length(v_old_sc) <> jsonb_array_length(v_new_sc)
                                              then ': ' || jsonb_array_length(v_old_sc) || ' → ' || jsonb_array_length(v_new_sc)
                                              else '' end);
      for v_row in select e.value from jsonb_array_elements(p_scenes) e loop
        v_pos := v_pos + 1;
        v_sid := null;
        if coalesce(v_row ->> 'id', '') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
          select sc.id into v_sid from public.video_script_scenes sc
           where sc.id = (v_row ->> 'id')::uuid and sc.script_id = p_id;
        end if;
        if v_sid is null then
          insert into public.video_script_scenes (script_id, position, visual, line)
          values (p_id, v_pos, nullif(btrim(coalesce(v_row ->> 'visual', '')), ''),
                  nullif(btrim(coalesce(v_row ->> 'line', '')), ''))
          returning id into v_sid;
        else
          update public.video_script_scenes sc
             set position = v_pos,
                 visual = nullif(btrim(coalesce(v_row ->> 'visual', '')), ''),
                 line = nullif(btrim(coalesce(v_row ->> 'line', '')), '')
           where sc.id = v_sid;
        end if;
        v_keep := v_keep || v_sid;
      end loop;
      delete from public.video_script_scenes sc where sc.script_id = p_id and not (sc.id = any (v_keep));
    end if;
  end if;

  if coalesce(array_length(v_moves, 1), 0) = 0 then
    return jsonb_build_object('ok', true, 'version', v.version, 'round', v.round, 'changed', false);
  end if;
  if v_creat and exists (select 1 from public.video_script_reviews r where r.script_id = p_id and r.round = v.round) then
    n.round := v.round + 1;
  end if;
  update public.video_scripts s
     set kind = n.kind, title = n.title, reference_url = n.reference_url, platform = n.platform,
         language = n.language, shoot_on = n.shoot_on, shoot_time = n.shoot_time, venue = n.venue,
         duration_minutes = n.duration_minutes, cast_names = n.cast_names, context = n.context,
         vo = n.vo, remarks = n.remarks, round = n.round, version = v.version + 1,
         updated_at = now(), updated_by_name = me.name
   where s.id = p_id;
  select c.name into v_client from public.clients c where c.id = v.client_id;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'script.saved', v_client,
          public.video_script_label(n) || ' · ' || array_to_string(v_moves, '; ')
          || case when n.round > v.round then ' · round ' || n.round else '' end);
  return jsonb_build_object('ok', true, 'version', v.version + 1, 'round', n.round, 'changed', true);
end $$;
revoke all on function public.video_script_save(uuid, jsonb, jsonb, integer) from public, anon;
grant execute on function public.video_script_save(uuid, jsonb, jsonb, integer) to authenticated;

-- The client's own link key, made on first asking; a reset retires the old.
create or replace function public.script_link(p_client uuid, p_reset boolean default false)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me    public.team_members := public.ops_me();
  v_cl  public.clients;
  v_key text;
begin
  if me.id is null or not public.allowed('scripts', 'view') then return jsonb_build_object('error', 'denied'); end if;
  select * into v_cl from public.clients c where c.id = p_client for update;
  if v_cl.id is null or not public.client_seen(v_cl.id, 'view') then return jsonb_build_object('error', 'not-found'); end if;
  if v_cl.script_key is not null and not coalesce(p_reset, false) then
    return jsonb_build_object('ok', true, 'key', v_cl.script_key);
  end if;
  if not public.allowed('scripts', 'work') or not public.client_seen(v_cl.id, 'work') then
    return jsonb_build_object('error', 'denied');
  end if;
  loop
    v_key := public.new_link_key();
    exit when not exists (select 1 from public.clients c where c.script_key = v_key);
  end loop;
  update public.clients c set script_key = v_key where c.id = p_client;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'script.link', v_cl.name,
          case when v_cl.script_key is null then 'Video Scripts link created' else 'Video Scripts link reset' end);
  return jsonb_build_object('ok', true, 'key', v_key);
end $$;
revoke all on function public.script_link(uuid, boolean) from public, anon;
grant execute on function public.script_link(uuid, boolean) to authenticated;

create or replace function public.video_script_share(p_ids uuid[], p_on boolean)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me    public.team_members := public.ops_me();
  s     public.video_scripts;
  v_cl  text;
  n     integer := 0;
  v_key text;
begin
  if me.id is null or not public.allowed('scripts', 'work') then return jsonb_build_object('error', 'denied'); end if;
  for s in select * from public.video_scripts x where x.id = any (coalesce(p_ids, '{}')) order by x.video_no for update loop
    if not public.client_seen(s.client_id, 'work') then return jsonb_build_object('error', 'client-scope'); end if;
    if (s.status = 'shared') = coalesce(p_on, false) then continue; end if;
    update public.video_scripts x
       set status = case when p_on then 'shared' else 'draft' end,
           shared_at = case when p_on then now() else null end
     where x.id = s.id;
    select c.name, c.script_key into v_cl, v_key from public.clients c where c.id = s.client_id;
    if p_on and v_key is null then
      loop
        v_key := public.new_link_key();
        exit when not exists (select 1 from public.clients c where c.script_key = v_key);
      end loop;
      update public.clients c set script_key = v_key where c.id = s.client_id;
    end if;
    insert into public.activity_log (actor, action, subject, detail)
    values (me.name, case when p_on then 'script.shared' else 'script.unshared' end, v_cl,
            public.video_script_label(s));
    n := n + 1;
  end loop;
  return jsonb_build_object('ok', true, 'count', n);
end $$;
revoke all on function public.video_script_share(uuid[], boolean) from public, anon;
grant execute on function public.video_script_share(uuid[], boolean) to authenticated;

/* On the day: a scene ticked shot, and its clip number (VC#) as the camera
   names it. With no scene, the voice-over line. Neither starts a round. */
create or replace function public.video_script_shot(p_script uuid, p_scene uuid, p_on boolean, p_vc text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me     public.team_members := public.ops_me();
  s      public.video_scripts;
  sc     public.video_script_scenes;
  v_cl   text;
  v_was  boolean;
begin
  if me.id is null or not public.allowed('scripts', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into s from public.video_scripts x where x.id = p_script for update;
  if s.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if not public.client_seen(s.client_id, 'work') then return jsonb_build_object('error', 'client-scope'); end if;
  if p_vc is not null and length(p_vc) > 40 then return jsonb_build_object('error', 'too-long'); end if;
  select c.name into v_cl from public.clients c where c.id = s.client_id;
  if p_scene is null then
    v_was := s.vo_shot_at is not null;
    update public.video_scripts x
       set vo_shot_at = case when p_on is null then x.vo_shot_at when p_on then coalesce(x.vo_shot_at, now()) end,
           vo_shot_by = case when p_on is null then x.vo_shot_by when p_on then coalesce(x.vo_shot_by, me.name) end,
           vo_vc = case when p_vc is null then x.vo_vc else nullif(btrim(p_vc), '') end
     where x.id = p_script;
    if p_on is not null and p_on <> v_was then
      insert into public.activity_log (actor, action, subject, detail)
      values (me.name, 'script.shot', v_cl, public.video_script_label(s) || ' · Script (read here) '
              || case when p_on then 'shot' else 'not shot' end);
    end if;
    return jsonb_build_object('ok', true);
  end if;
  select * into sc from public.video_script_scenes y where y.id = p_scene and y.script_id = p_script for update;
  if sc.id is null then return jsonb_build_object('error', 'not-found'); end if;
  v_was := sc.shot_at is not null;
  update public.video_script_scenes y
     set shot_at = case when p_on is null then y.shot_at when p_on then coalesce(y.shot_at, now()) end,
         shot_by = case when p_on is null then y.shot_by when p_on then coalesce(y.shot_by, me.name) end,
         vc = case when p_vc is null then y.vc else nullif(btrim(p_vc), '') end
   where y.id = p_scene;
  if p_on is not null and p_on <> v_was then
    insert into public.activity_log (actor, action, subject, detail)
    values (me.name, 'script.shot', v_cl, public.video_script_label(s) || ' · Scene ' || sc.position || ' '
            || case when p_on then 'shot' else 'not shot' end);
  end if;
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.video_script_shot(uuid, uuid, boolean, text) from public, anon;
grant execute on function public.video_script_shot(uuid, uuid, boolean, text) to authenticated;

create or replace function public.video_script_delete(p_id uuid, p_typed text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me   public.team_members := public.ops_me();
  s    public.video_scripts;
  v_cl text;
begin
  if me.id is null or not public.allowed('scripts', 'manage') then return jsonb_build_object('error', 'denied'); end if;
  select * into s from public.video_scripts x where x.id = p_id for update;
  if s.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if not public.client_seen(s.client_id, 'manage') then return jsonb_build_object('error', 'client-scope'); end if;
  if lower(btrim(coalesce(p_typed, ''))) <> lower(coalesce(nullif(btrim(s.title), ''), 'V' || s.video_no)) then
    return jsonb_build_object('error', 'name');
  end if;
  select c.name into v_cl from public.clients c where c.id = s.client_id;
  delete from public.video_scripts x where x.id = p_id;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'script.deleted', v_cl, public.video_script_label(s));
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.video_script_delete(uuid, text) from public, anon;
grant execute on function public.video_script_delete(uuid, text) to authenticated;

/* The client's page: the shared scripts, newest shoot first, each with the
   decision on its round and the request the round answers. Never a
   colleague's name, a clip number or a tick. */
create or replace function public.get_scripts(p_token text)
returns jsonb
language plpgsql security definer stable set search_path = public as $$
declare
  v_cl public.clients;
begin
  select * into v_cl from public.clients c
   where c.script_key = p_token and p_token is not null and c.active;
  if v_cl.id is null then return jsonb_build_object('error', 'not_found'); end if;
  return jsonb_build_object(
    'client', jsonb_build_object('name', v_cl.name, 'logo_url', v_cl.logo_url),
    'scripts', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', s.id, 'series_id', s.series_id, 'video_no', s.video_no, 'kind', s.kind,
               'title', s.title, 'reference_url', s.reference_url, 'platform', s.platform,
               'language', s.language, 'shoot_on', s.shoot_on, 'shoot_time', s.shoot_time,
               'venue', s.venue, 'duration_minutes', s.duration_minutes, 'cast_names', s.cast_names,
               'context', s.context, 'vo', s.vo, 'remarks', s.remarks, 'round', s.round,
               'shared_at', s.shared_at, 'updated_at', s.updated_at,
               'scenes', coalesce((select jsonb_agg(jsonb_build_object('position', sc.position,
                                                     'visual', sc.visual, 'line', sc.line)
                                                     order by sc.position)
                                     from public.video_script_scenes sc where sc.script_id = s.id), '[]'::jsonb),
               'decision', (select jsonb_build_object('decision', r.decision, 'note', r.note,
                                                      'reviewer', r.reviewer, 'at', r.created_at)
                              from public.video_script_reviews r
                             where r.script_id = s.id and r.round = s.round
                             order by r.created_at desc limit 1),
               'asked', (select jsonb_build_object('note', r.note, 'reviewer', r.reviewer, 'at', r.created_at)
                           from public.video_script_reviews r
                          where r.script_id = s.id and r.round = s.round - 1 and r.decision = 'changes'
                          order by r.created_at desc limit 1))
             order by coalesce(s.shoot_on, s.created_at::date) desc, s.series_id, s.video_no)
        from public.video_scripts s
       where s.client_id = v_cl.id and s.status = 'shared'), '[]'::jsonb));
end $$;
revoke all on function public.get_scripts(text) from public;
grant execute on function public.get_scripts(text) to anon;
grant execute on function public.get_scripts(text) to authenticated;

create or replace function public.script_decide(p_token text, p_script uuid, p_decision text,
                                                p_name text, p_note text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_cl   public.clients;
  s      public.video_scripts;
  v_name text := btrim(coalesce(p_name, ''));
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
  v_who  uuid;
begin
  if p_decision not in ('approved', 'changes') then return jsonb_build_object('error', 'bad-decision'); end if;
  select * into v_cl from public.clients c
   where c.script_key = p_token and p_token is not null and c.active;
  if v_cl.id is null then return jsonb_build_object('error', 'not_found'); end if;
  select * into s from public.video_scripts x
   where x.id = p_script and x.client_id = v_cl.id and x.status = 'shared';
  if s.id is null then return jsonb_build_object('error', 'not_found'); end if;
  if v_name = '' or length(v_name) > 80 then return jsonb_build_object('error', 'name-required'); end if;
  if p_decision = 'changes' and v_note is null then return jsonb_build_object('error', 'note-required'); end if;
  if v_note is not null and length(v_note) > 2000 then return jsonb_build_object('error', 'too-long'); end if;
  insert into public.video_script_reviews (script_id, round, decision, note, reviewer)
  values (s.id, s.round, p_decision, v_note, v_name);
  insert into public.activity_log (actor, action, subject, detail)
  values (v_name, case when p_decision = 'approved' then 'script.approved' else 'script.changes' end, v_cl.name,
          public.video_script_label(s) || case when s.round > 1 then ' · round ' || s.round else '' end
          || coalesce(' · ' || v_note, ''));
  select m.id into v_who from public.team_members m where m.id = s.created_by and m.active;
  if v_who is not null then
    insert into public.ops_notifications (team_member_id, kind, title, body, script_id)
    values (v_who, 'script',
            v_cl.name || case when p_decision = 'approved' then ' approved ' else ' requested changes on ' end
            || public.video_script_label(s),
            left(v_note, 200), s.id);
  end if;
  return jsonb_build_object('ok', true, 'decision', p_decision, 'round', s.round);
end $$;
revoke all on function public.script_decide(text, uuid, text, text, text) from public;
grant execute on function public.script_decide(text, uuid, text, text, text) to anon;
grant execute on function public.script_decide(text, uuid, text, text, text) to authenticated;

-- A script's notice opens the script.
create or replace function public.ops_notifications_push()
returns trigger
language plpgsql security definer set search_path = public as $$
declare
  v_title text := coalesce(nullif(btrim(new.title), ''), 'My Work');
  v_body  text := coalesce(new.body, '');
begin
  perform public.push_queue('team', new.team_member_id,
    jsonb_build_object('en', jsonb_build_object('title', v_title, 'body', v_body),
                       'zh', jsonb_build_object('title', v_title, 'body', v_body)),
    case when new.link is not null then new.link
         when new.task_id is not null then '/admin/?s=work&open=' || new.task_id::text
         when new.report_id is not null then '/admin/?s=reports&report=' || new.report_id::text
         when new.script_id is not null then '/admin/?s=scripts&script=' || new.script_id::text
         when new.kind in ('client_left', 'tasks.empty') then '/admin/?s=work'
         when new.kind = 'hr.letter' then '/admin/?s=mine&view=letters'
         when new.kind = 'perf.disputed' then '/admin/?s=team&tab=performance'
         when new.kind = 'perf.reflect' then '/admin/?s=mine&view=reflection'
         when new.kind = 'perf.initiative' then '/admin/?s=mine&view=initiatives'
         when new.kind like 'health.%' then '/admin/?s=mine&view=health'
         when new.kind like 'perf.%' then '/admin/?s=mine'
         else '/admin/' end,
    case when new.task_id is not null then 'task-' || new.task_id::text
         when new.report_id is not null then 'report-' || new.report_id::text
         when new.script_id is not null then 'script-' || new.script_id::text
         when new.kind = 'hr.letter' then 'hr-letter'
         when new.kind in ('perf.remind', 'perf.reflect', 'health.remind') then 'my-hr'
         when new.kind = 'tasks.empty' then 'tasks-empty'
         when new.kind = 'outstation' then 'outstation'
         else null end);
  return new;
exception when others then
  return new;
end $$;

create or replace function public.activity_section(p_action text)
returns text
language sql immutable parallel safe as $$
  select case
    when action in ('campaign.bulk', 'campaign.closed', 'campaign.confirmed',
                    'campaign.created', 'campaign.dates', 'campaign.deleted', 'campaign.edited',
                    'campaign.file_added', 'campaign.qc',
                    'campaign.invoice', 'campaign.invoice_file',
                    'campaign.invoice_removed', 'campaign.keyed', 'campaign.locked',
                    'campaign.opened', 'campaign.rate', 'campaign.rated',
                    'campaign.reinstated', 'campaign.replaced', 'campaign.results', 'campaign.review',
                    'campaign.stage', 'campaign.submitted', 'campaign.task_linked',
                    'campaign.task_unlinked', 'campaign.unbooked',
                    'campaign.unkeyed', 'campaign.withdrawn', 'creator.added',
                    'creator.code', 'creator.links', 'creator.links_restored',
                    'creator.links_self', 'creator.off', 'creator.on', 'creator.removed',
                    'creator.updated') then 'campaigns'
    when action in ('client.action_done', 'client.action_reopened', 'client.added',
                    'client.billing', 'client.brand', 'client.deleted', 'client.edited',
                    'client.review_on', 'client.service', 'client.service_changed',
                    'client.service_removed', 'client.service_restored', 'client.stage', 'client.touch',
                    'client.touch_deleted', 'client.touch_edited', 'client.touch_removed',
                    'client.touch_restored', 'contact.added', 'contact.deleted',
                    'contact.edited', 'contact.portal_invite', 'contact.portal_off',
                    'contact.portal_on', 'contact.primary', 'contact.removed',
                    'contact.restored',
                    'request.changed', 'request.raised',
                    'request.reinstated', 'request.replied', 'request.withdrawn',
                    'service.override') then 'clients'
    when action in ('report.ai_drafted', 'report.ai_failed', 'report.audited', 'report.confirmed',
                    'report.created', 'report.deleted', 'report.published',
                    'report.reassigned', 'report.returned', 'report.revised', 'report.saved',
                    'report.submitted', 'report.unpublished') then 'reports'
    when action in ('qr.created', 'qr.restored', 'qr.revoked', 'shortlink.created',
                    'shortlink.deleted', 'shortlink.imported', 'shortlink.updated') then 'links'
    when action in ('ops.deleted', 'ops.month_deleted', 'ops.numbering') then 'ops'
    when action in ('document.deleted', 'document.issued', 'document.reissued',
                    'document.restored', 'document.signed', 'document.superseded',
                    'document.unsigned', 'document.verified', 'document.voided',
                    'register.added', 'register.edited') then 'register'
    when action in ('client.drive', 'client.handles', 'client.profile',
                    'client.removed', 'drive.imported', 'link.reset', 'post.added',
                    'post.deleted', 'post.edited', 'reapproval.requested',
                    'review.approved', 'review.changes', 'review.removed',
                    'review.unconfirmed',
                    'set.created', 'set.deleted', 'set.published', 'set.renamed',
                    'set.task_linked', 'set.task_unlinked',
                    'set.withdrawn') then 'review'
    when action in ('script.approved', 'script.changes', 'script.created', 'script.deleted',
                    'script.link', 'script.saved', 'script.shared', 'script.shot',
                    'script.unshared') then 'scripts'
    when action in ('handbook.added', 'handbook.archived', 'handbook.deleted',
                    'handbook.edited', 'handbook.restored', 'handbook.version') then 'handbook'
    when action in ('service.added', 'service.changed', 'service.deleted',
                    'service.off', 'service.on') then 'services'
    when action in ('team.added', 'team.changed', 'team.edited', 'team.group_added',
                    'team.group_changed', 'team.group_removed', 'team.invited') then 'team'
    else 'other'
  end
  from (select p_action as action) t
$$;
grant execute on function public.activity_section(text) to authenticated;

-- END OF VIDEO SCRIPTS -------------------------------------------------------

-- ===========================================================================
-- SCRIPT WRITER — Write script in Video Scripts: a video's script drafted by
-- AI from the colleague's notes, counted apart from the reports' and the
-- captions' AI uses.
-- 2026-10-09. Safe to run twice. Rollback below. Mirrored byte for byte in
-- supabase/schema.sql under the same banner; tests/smsql.js compares the two.
--
-- WHAT CHANGED (the user, 2026-10-09: "go ahead and write script")
--   1. `ai_drafts.purpose` takes `script`; a script's row names its video
--      (`script_id`) and client.
--   2. `ai_script_claim(p_script)`: Video Scripts at Work, a video on a client
--      the colleague works on. Counted by the colleague a day, from midnight
--      MYT: `script` (10) a colleague's, `script_admin` (20) an admin's, both
--      settings in `ai_draft_limits`; 0 stops it. `ai_script_left()` reads
--      what is left without writing.
--   3. The reports' limits count report drafts and commentary checks alone
--      (`purpose in ('draft', 'check')`), so neither a caption nor a script
--      takes from them.
--   4. `ai_draft_usage()` adds the script limits and each colleague's scripts
--      today, and lists a colleague at Video Scripts Work;
--      `ai_draft_set_limit` names `script` and `script_admin`.
--
-- ROLLBACK
--   Run the CAPTION WRITER AND AI COST section again; then, in the SQL
--   Editor, drop ai_script_claim(uuid) and ai_script_left(), delete the
--   script rows from ai_drafts and put the purpose check back to
--   ('draft', 'check', 'caption'). The column may stay.
-- ===========================================================================

alter table public.ai_drafts add column if not exists script_id uuid;
alter table public.ai_drafts drop constraint if exists ai_drafts_purpose;
alter table public.ai_drafts add constraint ai_drafts_purpose check (purpose in ('draft', 'check', 'caption', 'script'));

-- A script: the colleague's own count a day, apart from the reports' and the
-- captions'.
create or replace function public.ai_script_claim(p_script uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m public.team_members;
  v public.video_scripts;
  since timestamptz := public.ai_draft_day();
  n_used integer;
  lim integer;
  new_id uuid;
begin
  if not public.allowed('scripts', 'work') then return jsonb_build_object('error', 'denied'); end if;
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'denied'); end if;
  select * into v from public.video_scripts x where x.id = p_script;
  if v.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if not public.client_seen(v.client_id, 'work') then return jsonb_build_object('error', 'client-scope'); end if;
  -- One count at a time, with the drafts, so the last script is taken once.
  perform pg_advisory_xact_lock(hashtext('ai_draft_claim'));
  lim := case when coalesce(m.is_admin, false) or m.role = 'admin'
              then public.ai_draft_limit('script_admin', 20) else public.ai_draft_limit('script', 10) end;
  if lim = 0 then return jsonb_build_object('error', 'ai-limit', 'scope', 'stopped', 'limit', 0); end if;
  select count(*) into n_used from public.ai_drafts d
   where d.team_member_id = m.id and d.purpose = 'script' and d.created_at >= since and d.outcome <> 'failed';
  if n_used >= lim then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'script', 'limit', lim, 'next', since + interval '1 day');
  end if;
  insert into public.ai_drafts (team_member_id, client_id, script_id, purpose)
  values (m.id, v.client_id, v.id, 'script') returning id into new_id;
  return jsonb_build_object('id', new_id, 'left', lim - n_used - 1, 'limit', lim);
end $$;

-- What Write script has left today, read without writing.
create or replace function public.ai_script_left()
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  m public.team_members;
  since timestamptz := public.ai_draft_day();
  lim integer;
  l_left integer;
begin
  if not public.allowed('scripts', 'work') then return jsonb_build_object('error', 'denied'); end if;
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'denied'); end if;
  lim := case when coalesce(m.is_admin, false) or m.role = 'admin'
              then public.ai_draft_limit('script_admin', 20) else public.ai_draft_limit('script', 10) end;
  l_left := greatest(0, lim - (select count(*) from public.ai_drafts d
    where d.team_member_id = m.id and d.purpose = 'script' and d.created_at >= since and d.outcome <> 'failed')::integer);
  return jsonb_build_object('left', l_left, 'limit', lim, 'scope', case when lim = 0 then 'stopped' else 'script' end,
    'next', case when l_left > 0 or lim = 0 then null else since + interval '1 day' end);
end $$;

revoke all on function public.ai_script_claim(uuid) from public, anon, authenticated;
revoke all on function public.ai_script_left() from public, anon, authenticated;
grant execute on function public.ai_script_claim(uuid) to authenticated;
grant execute on function public.ai_script_left() to authenticated;

create or replace function public.ai_draft_claim(p_report uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m public.team_members;
  r public.sm_reports;
  since timestamptz := public.ai_draft_day();
  n_report integer;
  n_member integer;
  lim_member integer;
  lim_report integer;
  new_id uuid;
begin
  if not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'denied'); end if;
  -- One count at a time, so two presses together cannot both take the last draft.
  perform pg_advisory_xact_lock(hashtext('ai_draft_claim'));
  select * into r from public.sm_reports where id = p_report;
  lim_member := public.ai_day_cap(m);
  if lim_member = 0 then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'stopped', 'limit', 0);
  end if;
  lim_report := case when coalesce(m.is_admin, false) then public.ai_draft_limit('report_admin', 5)
                     else public.ai_draft_limit('report', 1) end;
  select count(*) into n_report from public.ai_draft_same(p_report) s
   where s.team_member_id = m.id and s.created_at >= since;
  if n_report >= lim_report then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'report', 'limit', lim_report, 'next', since + interval '1 day');
  end if;
  select count(*) into n_member from public.ai_drafts d
   where d.team_member_id = m.id and d.created_at >= since and d.outcome <> 'failed' and d.purpose in ('draft', 'check');
  if n_member >= lim_member then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'person', 'limit', lim_member, 'next', since + interval '1 day');
  end if;
  insert into public.ai_drafts (report_id, team_member_id, client_id, kind, period_start, period_end, version_no)
  values (p_report, m.id, r.client_id, r.kind, r.period_start, r.period_end, r.version_no) returning id into new_id;
  return jsonb_build_object('id', new_id, 'left', lim_member - n_member - 1);
end $$;

create or replace function public.ai_draft_left(p_report uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  m public.team_members;
  since timestamptz := public.ai_draft_day();
  is_adm boolean;
  n_member integer;
  l_report integer; l_member integer; l_min integer;
  lim_member integer;
  lim_report integer;
  v_scope text;
begin
  if not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'denied'); end if;
  is_adm := coalesce(m.is_admin, false);
  lim_member := public.ai_day_cap(m);
  lim_report := case when is_adm then public.ai_draft_limit('report_admin', 5) else public.ai_draft_limit('report', 1) end;
  l_report := greatest(0, lim_report - (select count(*) from public.ai_draft_same(p_report) s
    where s.team_member_id = m.id and s.created_at >= since)::integer);
  select count(*) into n_member from public.ai_drafts d
   where d.team_member_id = m.id and d.created_at >= since and d.outcome <> 'failed' and d.purpose in ('draft', 'check');
  l_member := greatest(0, lim_member - n_member);
  l_min := least(l_report, l_member);
  v_scope := case when lim_member = 0 then 'stopped' when l_min = l_report then 'report' else 'person' end;
  return jsonb_build_object(
    'left', l_min, 'scope', v_scope,
    'limit', case v_scope when 'stopped' then 0 when 'report' then lim_report else lim_member end,
    'report', l_report, 'person', l_member, 'admin', is_adm,
    'next', case when l_min > 0 or v_scope = 'stopped' then null else since + interval '1 day' end);
end $$;

create or replace function public.ai_check_claim(p_report uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m public.team_members;
  r public.sm_reports;
  since timestamptz := public.ai_draft_day();
  n_member integer;
  lim_member integer;
  lim_check integer;
  new_id uuid;
begin
  if not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_report;
  if r.id is null or not public.client_seen(r.client_id, 'view') then
    return jsonb_build_object('error', 'not-found');
  end if;
  if r.status not in ('draft', 'review') then return jsonb_build_object('error', 'not-open'); end if;
  -- One count at a time, with the drafts, so the last use is taken once.
  perform pg_advisory_xact_lock(hashtext('ai_draft_claim'));
  lim_member := public.ai_day_cap(m);
  if lim_member = 0 then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'stopped', 'limit', 0);
  end if;
  lim_check := case when coalesce(m.is_admin, false) then public.ai_draft_limit('check_admin', 5)
                    else public.ai_draft_limit('check', 1) end;
  if (select count(*) from public.ai_drafts d
       where d.report_id = p_report and d.purpose = 'check' and d.outcome <> 'failed'
         and d.team_member_id = m.id and d.created_at >= since) >= lim_check then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'report_check', 'limit', lim_check, 'next', since + interval '1 day');
  end if;
  select count(*) into n_member from public.ai_drafts d
   where d.team_member_id = m.id and d.created_at >= since and d.outcome <> 'failed' and d.purpose in ('draft', 'check');
  if n_member >= lim_member then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'person', 'limit', lim_member, 'next', since + interval '1 day');
  end if;
  insert into public.ai_drafts (report_id, team_member_id, client_id, kind, period_start, period_end, purpose, version_no)
  values (p_report, m.id, r.client_id, r.kind, r.period_start, r.period_end, 'check', r.version_no) returning id into new_id;
  return jsonb_build_object('id', new_id, 'left', lim_member - n_member - 1);
end $$;

create or replace function public.ai_check_left(p_report uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  m public.team_members;
  r public.sm_reports;
  since timestamptz := public.ai_draft_day();
  is_adm boolean;
  n_member integer;
  l_report integer; l_member integer; l_min integer;
  lim_member integer;
  lim_check integer;
  v_scope text;
begin
  if not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_report;
  if r.id is null or not public.client_seen(r.client_id, 'view') then
    return jsonb_build_object('error', 'not-found');
  end if;
  is_adm := coalesce(m.is_admin, false);
  lim_member := public.ai_day_cap(m);
  lim_check := case when is_adm then public.ai_draft_limit('check_admin', 5) else public.ai_draft_limit('check', 1) end;
  l_report := greatest(0, lim_check - (select count(*) from public.ai_drafts d
    where d.report_id = p_report and d.purpose = 'check' and d.outcome <> 'failed'
      and d.team_member_id = m.id and d.created_at >= since)::integer);
  select count(*) into n_member from public.ai_drafts d
   where d.team_member_id = m.id and d.created_at >= since and d.outcome <> 'failed' and d.purpose in ('draft', 'check');
  l_member := greatest(0, lim_member - n_member);
  l_min := least(l_report, l_member);
  v_scope := case when lim_member = 0 then 'stopped' when l_min = l_report then 'report_check' else 'person' end;
  return jsonb_build_object(
    'left', l_min, 'scope', v_scope, 'version', r.version_no,
    'limit', case v_scope when 'stopped' then 0 when 'report_check' then lim_check else lim_member end,
    'report', l_report, 'person', l_member, 'admin', is_adm,
    'next', case when l_min > 0 or v_scope = 'stopped' then null else since + interval '1 day' end);
end $$;

revoke all on function public.ai_draft_claim(uuid) from public, anon, authenticated;
revoke all on function public.ai_draft_left(uuid) from public, anon, authenticated;
revoke all on function public.ai_check_claim(uuid) from public, anon, authenticated;
revoke all on function public.ai_check_left(uuid) from public, anon, authenticated;
grant execute on function public.ai_draft_claim(uuid) to authenticated;
grant execute on function public.ai_draft_left(uuid) to authenticated;
grant execute on function public.ai_check_claim(uuid) to authenticated;
grant execute on function public.ai_check_left(uuid) to authenticated;

create or replace function public.ai_draft_usage()
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_day timestamptz := public.ai_draft_day();
  v_month timestamptz := now() - interval '30 days';
  -- This calendar month in Malaysia, for what the calls cost.
  v_cal timestamptz := date_trunc('month', now() at time zone 'Asia/Kuala_Lumpur') at time zone 'Asia/Kuala_Lumpur';
  v_today date := (now() at time zone 'Asia/Kuala_Lumpur')::date;
begin
  if not public.ops_granted('reports.ai', 'work') then return jsonb_build_object('error', 'denied'); end if;
  return jsonb_build_object(
    'person', public.ai_draft_limit('person', 10),
    'admin', public.ai_draft_limit('admin', 20),
    'report', public.ai_draft_limit('report', 1),
    'report_admin', public.ai_draft_limit('report_admin', 5),
    'check', public.ai_draft_limit('check', 1),
    'check_admin', public.ai_draft_limit('check_admin', 5),
    'caption', public.ai_draft_limit('caption', 20),
    'caption_admin', public.ai_draft_limit('caption_admin', 40),
    'script', public.ai_draft_limit('script', 10),
    'script_admin', public.ai_draft_limit('script_admin', 20),
    'cost', (select jsonb_build_object(
        'since', v_cal,
        'price_in', public.app_setting('ai_price_in', v_today),
        'price_out', public.app_setting('ai_price_out', v_today),
        'uses', count(*),
        'untracked', count(*) filter (where c.input_tokens is null),
        'input', coalesce(sum(c.input_tokens), 0),
        'output', coalesce(sum(c.output_tokens), 0),
        'usd', round(coalesce(sum(c.usd), 0), 2),
        'by', coalesce((select jsonb_object_agg(p.purpose, p.x) from (
            select c2.purpose, jsonb_build_object('uses', count(*), 'input', coalesce(sum(c2.input_tokens), 0),
                     'output', coalesce(sum(c2.output_tokens), 0), 'usd', round(coalesce(sum(c2.usd), 0), 2)) as x
              from (select d.purpose, d.input_tokens, d.output_tokens,
                           (coalesce(d.input_tokens, 0) * public.app_setting('ai_price_in', (d.created_at at time zone 'Asia/Kuala_Lumpur')::date)
                          + coalesce(d.output_tokens, 0) * public.app_setting('ai_price_out', (d.created_at at time zone 'Asia/Kuala_Lumpur')::date)) / 1000000.0 as usd
                      from public.ai_drafts d where d.created_at >= v_cal and (d.outcome <> 'failed' or d.input_tokens is not null)) c2
             group by c2.purpose) p), '{}'::jsonb))
      from (select d.input_tokens, d.output_tokens,
                   (coalesce(d.input_tokens, 0) * public.app_setting('ai_price_in', (d.created_at at time zone 'Asia/Kuala_Lumpur')::date)
                  + coalesce(d.output_tokens, 0) * public.app_setting('ai_price_out', (d.created_at at time zone 'Asia/Kuala_Lumpur')::date)) / 1000000.0 as usd
              from public.ai_drafts d where d.created_at >= v_cal and (d.outcome <> 'failed' or d.input_tokens is not null)) c),
    'resets_at', v_day + interval '1 day',
    'people', coalesce((select jsonb_agg(s.x order by s.x ->> 'name') from (
      select jsonb_build_object(
        'id', t.id, 'name', t.name, 'code', t.staff_code, 'group', g.name, 'group_slug', t.role,
        'admin', coalesce(t.is_admin, false) or t.role = 'admin',
        'day', (select count(*) from public.ai_drafts d where d.team_member_id = t.id and d.created_at >= v_day and d.outcome <> 'failed' and d.purpose in ('draft', 'check')),
        'captions', (select count(*) from public.ai_drafts d where d.team_member_id = t.id and d.created_at >= v_day and d.outcome <> 'failed' and d.purpose = 'caption'),
        'caption_cap', case when coalesce(t.is_admin, false) or t.role = 'admin'
                            then public.ai_draft_limit('caption_admin', 40) else public.ai_draft_limit('caption', 20) end,
        'scripts', (select count(*) from public.ai_drafts d where d.team_member_id = t.id and d.created_at >= v_day and d.outcome <> 'failed' and d.purpose = 'script'),
        'script_cap', case when coalesce(t.is_admin, false) or t.role = 'admin'
                           then public.ai_draft_limit('script_admin', 20) else public.ai_draft_limit('script', 10) end,
        'month', (select count(*) from public.ai_drafts d where d.team_member_id = t.id and d.created_at > v_month and d.outcome <> 'failed'),
        'limit', (select l.daily from public.ai_draft_limits l where l.scope = t.id::text),
        'cap', public.ai_day_cap(t)) as x
        from public.team_members t
        left join public.team_roles g on g.slug = t.role
       where t.active
         and (coalesce(t.is_admin, false) or t.role = 'admin'
              or public.level_rank(coalesce(t.access ->> 'reports', 'none')) >= public.level_rank('work')
              or public.level_rank(coalesce(t.access ->> 'review', 'none')) >= public.level_rank('work')
              or public.level_rank(coalesce(t.access ->> 'scripts', 'none')) >= public.level_rank('work')
              or exists (select 1 from public.ai_drafts d where d.team_member_id = t.id and d.created_at > v_month))
    ) s), '[]'::jsonb));
end $$;
revoke all on function public.ai_draft_usage() from public, anon, authenticated;
grant execute on function public.ai_draft_usage() to authenticated;

create or replace function public.ai_draft_set_limit(p_scope text, p_daily integer)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_who text;
  v_name text;
  v_was integer;
  v_def integer;
  v_unit text := ' a day';
  v_scope text := btrim(coalesce(p_scope, ''));
  t public.team_members;
begin
  if not public.ops_granted('reports.ai', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if p_daily is not null and (p_daily < 0 or p_daily > 500) then
    return jsonb_build_object('error', 'bad-limit');
  end if;
  if v_scope = 'person' then
    v_name := 'Each colleague'; v_def := 10;
  elsif v_scope = 'admin' then
    v_name := 'Each admin'; v_def := 20;
  elsif v_scope = 'report' then
    v_name := 'Drafts per report, each colleague'; v_def := 1;
  elsif v_scope = 'report_admin' then
    v_name := 'Drafts per report, each admin'; v_def := 5;
  elsif v_scope = 'check' then
    v_name := 'Figures checks per report, each colleague'; v_def := 1;
  elsif v_scope = 'check_admin' then
    v_name := 'Figures checks per report, each admin'; v_def := 5;
  elsif v_scope = 'caption' then
    v_name := 'Captions, each colleague'; v_def := 20;
  elsif v_scope = 'caption_admin' then
    v_name := 'Captions, each admin'; v_def := 40;
  elsif v_scope = 'script' then
    v_name := 'Scripts, each colleague'; v_def := 10;
  elsif v_scope = 'script_admin' then
    v_name := 'Scripts, each admin'; v_def := 20;
  elsif v_scope = 'team' then
    return jsonb_build_object('error', 'bad-scope');
  else
    select * into t from public.team_members x where x.id::text = v_scope;
    if t.id is null then return jsonb_build_object('error', 'not-found'); end if;
    v_name := t.name;
    v_def := case when coalesce(t.is_admin, false) or t.role = 'admin'
                  then public.ai_draft_limit('admin', 20) else public.ai_draft_limit('person', 10) end;
  end if;
  select l.daily into v_was from public.ai_draft_limits l where l.scope = v_scope;
  if v_was is not distinct from p_daily then return jsonb_build_object('ok', true, 'same', true); end if;
  select coalesce(x.name, x.email) into v_who from public.team_members x
   where lower(x.email) = lower(auth.jwt() ->> 'email') and x.active limit 1;
  insert into public.ai_draft_limits (scope, daily, set_by, set_at)
  values (v_scope, p_daily, v_who, now())
  on conflict (scope) do update set daily = excluded.daily, set_by = excluded.set_by, set_at = excluded.set_at;
  insert into public.activity_log (actor, action, subject, detail)
  values (coalesce(v_who, 'admin'), 'team.changed', 'AI',
          v_name || ': ' ||
          case when v_was is null then 'standard, ' || v_def || v_unit when v_was = 0 then 'stopped' else v_was || v_unit end ||
          ' → ' ||
          case when p_daily is null then 'standard, ' || v_def || v_unit when p_daily = 0 then 'stopped' else p_daily || v_unit end);
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.ai_draft_set_limit(text, integer) from public, anon, authenticated;
grant execute on function public.ai_draft_set_limit(text, integer) to authenticated;

-- END OF SCRIPT WRITER --------------------------------------------------------

-- ===========================================================================
-- SCRIPTS BY MONTH — a video script belongs to a client's content month and
-- is numbered in it (YYMMVSNN), the client link is for reading the script
-- and recording the clip numbers on site, and the client no longer decides
-- on it.
-- 2026-10-09. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/vssql.js compares the
-- two.
--
-- WHAT CHANGED
--   The user (2026-10-09): "we are working on content month, monthly basis
--   … the default for video script can be YYMMVSNN (VS is video script
--   meaning) NN is the number of script … one script is for one full video
--   … no need show the approve or changes at client side, the public link …
--   is for us and or client to view how the video script is like digitally;
--   and on the spot digital use for entering VC#." The user's answers: VC#
--   in the console and on the link; a month picked, linked where My Work
--   holds it; the link shows shared scripts only; NN counted per client a
--   month.
--   1. `video_scripts.period` (YYYY-MM), `seq` (1 to 99) and `code`
--      (`2610VS01`, kept from the two), unique a client a month;
--      `engagement_id` names the client's My Work month for the period
--      where one exists (set on create and on a move, never required).
--      Every script before this file takes the month of its shooting date,
--      else of the day it was made, numbered in the order it was made.
--      `series_id` and `video_no` stay unread.
--   2. `video_script_new(p_client, p_period, p_kind, p_from, p_idem)` makes
--      a script in a month at the lowest free number; with `p_from` (Add next
--      script) the client and month are its, the header copied, the script
--      empty. `video_script_create` (the pages before this file) makes it in
--      its first video's month, else this month (MYT).
--   3. `video_script_save` takes `period` in the head: the script moves to
--      that month at its lowest free number, filed with both codes.
--      Deleting asks for the title typed back, else the code.
--   4. `script_shot_link(p_token, p_script, p_scene, p_on, p_vc)` (anon,
--      joins `open_to_anon`): the client link records a shared script's clip
--      numbers and Shot ticks on site, filed under the client by `Client
--      link`, as the console's `video_script_shot` does.
--   5. `get_scripts` sends each shared script's code, its scenes with their
--      ids, clip numbers and Shot ticks (never who ticked), the voice-over's,
--      and no decision. `script_decide` answers `closed` and writes nothing.
--
-- ROLLBACK
--   Pages first, then re-run VIDEO SCRIPTS (2026-10-09-video-scripts.sql) for
--   video_script_label, video_script_create, video_script_save,
--   video_script_delete, get_scripts and script_decide, and in the SQL
--   Editor drop script_shot_link and video_script_new. The columns may stay.
-- ===========================================================================

alter table public.video_scripts add column if not exists period text;
alter table public.video_scripts add column if not exists seq integer;
alter table public.video_scripts add column if not exists engagement_id uuid references public.ops_engagements(id) on delete set null;

update public.video_scripts s
   set period = to_char(coalesce(s.shoot_on, (s.created_at at time zone 'Asia/Kuala_Lumpur')::date), 'YYYY-MM')
 where s.period is null;
with n as (
  select s.id, row_number() over (partition by s.client_id, s.period order by s.created_at, s.video_no)
         + coalesce((select max(t.seq) from public.video_scripts t
                      where t.client_id = s.client_id and t.period = s.period and t.seq is not null), 0) as k
    from public.video_scripts s where s.seq is null)
update public.video_scripts s set seq = n.k from n where s.id = n.id;
update public.video_scripts s set engagement_id = e.id
  from public.ops_engagements e
 where s.engagement_id is null and e.client_id = s.client_id and e.period = s.period;

alter table public.video_scripts alter column period set not null;
alter table public.video_scripts alter column seq set not null;
alter table public.video_scripts add column if not exists code text
  generated always as (substr(period, 3, 2) || substr(period, 6, 2) || 'VS' || lpad(seq::text, 2, '0')) stored;
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'video_scripts_period_shape') then
    alter table public.video_scripts add constraint video_scripts_period_shape
      check (period ~ '^\d{4}-(0[1-9]|1[0-2])$' and seq between 1 and 99);
  end if;
end $$;
create unique index if not exists video_scripts_month_seq_idx on public.video_scripts(client_id, period, seq);

-- 2610VS01 · Title, as every screen and the activity record name a script.
create or replace function public.video_script_label(p public.video_scripts)
returns text language sql immutable set search_path = public as $$
  select substr(p.period, 3, 2) || substr(p.period, 6, 2) || 'VS' || lpad(p.seq::text, 2, '0')
         || coalesce(' · ' || nullif(btrim(p.title), ''), '')
$$;
revoke all on function public.video_script_label(public.video_scripts) from public, anon, authenticated;

create or replace function public.video_script_new(p_client uuid, p_period text, p_kind text default null,
                                                   p_from uuid default null, p_idem text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me     public.team_members := public.ops_me();
  f      public.video_scripts;
  v_cl   public.clients;
  v_kind text;
  v_per  text;
  v_seq  integer;
  v_eng  uuid;
  v_id   uuid;
  v_new  public.video_scripts;
begin
  if me.id is null or not public.allowed('scripts', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if nullif(btrim(coalesce(p_idem, '')), '') is not null then
    select s.id into v_id from public.video_scripts s where s.idem_key = p_idem;
    if v_id is not null then return jsonb_build_object('ok', true, 'id', v_id, 'again', true); end if;
  end if;
  if p_from is not null then
    select * into f from public.video_scripts s where s.id = p_from;
    if f.id is null or (p_client is not null and p_client <> f.client_id) then
      return jsonb_build_object('error', 'not-found');
    end if;
  end if;
  select * into v_cl from public.clients c where c.id = coalesce(f.client_id, p_client);
  if v_cl.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if not public.client_seen(v_cl.id, 'work') then return jsonb_build_object('error', 'client-scope'); end if;
  v_per := coalesce(nullif(btrim(coalesce(p_period, '')), ''), f.period);
  if v_per is null or v_per !~ '^\d{4}-(0[1-9]|1[0-2])$' or v_per not between '2023-08' and '2099-12' then
    return jsonb_build_object('error', 'bad-period');
  end if;
  v_kind := coalesce(nullif(btrim(coalesce(p_kind, '')), ''), f.kind, 'scenes');
  if v_kind not in ('scenes', 'products', 'story') then return jsonb_build_object('error', 'bad-kind'); end if;
  perform pg_advisory_xact_lock(hashtext('video_script:' || v_cl.id::text || ':' || v_per));
  select min(g) into v_seq from generate_series(1, 99) g
   where not exists (select 1 from public.video_scripts s where s.client_id = v_cl.id and s.period = v_per and s.seq = g);
  if v_seq is null then return jsonb_build_object('error', 'too-many'); end if;
  select e.id into v_eng from public.ops_engagements e where e.client_id = v_cl.id and e.period = v_per limit 1;
  insert into public.video_scripts (client_id, period, seq, engagement_id, kind, platform, language, shoot_on,
                                    shoot_time, venue, duration_minutes, cast_names, idem_key,
                                    created_by, created_by_name, updated_by_name)
  values (v_cl.id, v_per, v_seq, v_eng, v_kind, f.platform, f.language, f.shoot_on, f.shoot_time, f.venue,
          f.duration_minutes, f.cast_names, nullif(btrim(coalesce(p_idem, '')), ''), me.id, me.name, me.name)
  returning * into v_new;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'script.created', v_cl.name,
          public.video_script_label(v_new) || ' · '
          || case v_kind when 'scenes' then 'Detailed scenes' when 'products' then 'Products and scenes'
                         else 'Story and voice-over' end
          || case when f.id is not null then ' · header from ' || f.code else '' end);
  return jsonb_build_object('ok', true, 'id', v_new.id, 'code', v_new.code, 'period', v_per, 'seq', v_seq);
end $$;
revoke all on function public.video_script_new(uuid, text, text, uuid, text) from public, anon;
grant execute on function public.video_script_new(uuid, text, text, uuid, text) to authenticated;

-- The pages before this file: the first video's month, else this month.
create or replace function public.video_script_create(p_client uuid, p_kind text, p_from uuid default null,
                                                      p_idem text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
begin
  return public.video_script_new(p_client,
    coalesce((select s.period from public.video_scripts s where s.id = p_from),
             to_char((now() at time zone 'Asia/Kuala_Lumpur')::date, 'YYYY-MM')),
    p_kind, p_from, p_idem);
end $$;
revoke all on function public.video_script_create(uuid, text, uuid, text) from public, anon;
grant execute on function public.video_script_create(uuid, text, uuid, text) to authenticated;

/* One save for the whole script: the header facts named in `p_head` (a key
   left out keeps its value; `period` moves it to that month at its lowest
   free number) and, where `p_scenes` is given, the scene rows in order ({id,
   visual, line}; a row named by its id keeps its clip number and its tick).
   Files what changed, from and to for a short value, by name for the long
   ones. */
create or replace function public.video_script_save(p_id uuid, p_head jsonb, p_scenes jsonb, p_version integer default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me        public.team_members := public.ops_me();
  v         public.video_scripts;
  n         public.video_scripts;
  v_client  text;
  h         jsonb := coalesce(p_head, '{}'::jsonb);
  v_moves   text[] := '{}';
  v_creat   boolean := false;
  v_old_sc  jsonb;
  v_new_sc  jsonb;
  v_row     jsonb;
  v_pos     integer := 0;
  v_keep    uuid[] := '{}';
  v_sid     uuid;
  v_kindw   text;
begin
  if me.id is null or not public.allowed('scripts', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into v from public.video_scripts s where s.id = p_id for update;
  if v.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if not public.client_seen(v.client_id, 'work') then return jsonb_build_object('error', 'client-scope'); end if;
  if p_version is not null and p_version <> v.version then
    return jsonb_build_object('error', 'stale', 'row', to_jsonb(v));
  end if;
  n := v;
  if h ? 'kind' then n.kind := h ->> 'kind'; end if;
  if h ? 'title' then n.title := btrim(coalesce(h ->> 'title', '')); end if;
  if h ? 'reference_url' then n.reference_url := nullif(btrim(coalesce(h ->> 'reference_url', '')), ''); end if;
  if h ? 'platform' then n.platform := nullif(btrim(coalesce(h ->> 'platform', '')), ''); end if;
  if h ? 'language' then n.language := nullif(btrim(coalesce(h ->> 'language', '')), ''); end if;
  if h ? 'shoot_on' then n.shoot_on := nullif(h ->> 'shoot_on', '')::date; end if;
  if h ? 'shoot_time' then n.shoot_time := nullif(h ->> 'shoot_time', '')::time; end if;
  if h ? 'venue' then n.venue := nullif(btrim(coalesce(h ->> 'venue', '')), ''); end if;
  if h ? 'duration_minutes' then n.duration_minutes := nullif(h ->> 'duration_minutes', '')::integer; end if;
  if h ? 'cast_names' then n.cast_names := nullif(btrim(coalesce(h ->> 'cast_names', '')), ''); end if;
  if h ? 'context' then n.context := nullif(btrim(coalesce(h ->> 'context', '')), ''); end if;
  if h ? 'vo' then n.vo := nullif(btrim(coalesce(h ->> 'vo', '')), ''); end if;
  if h ? 'remarks' then n.remarks := nullif(btrim(coalesce(h ->> 'remarks', '')), ''); end if;
  if h ? 'period' and nullif(btrim(coalesce(h ->> 'period', '')), '') is not null then
    n.period := btrim(h ->> 'period');
  end if;

  if n.kind not in ('scenes', 'products', 'story') then return jsonb_build_object('error', 'bad-kind'); end if;
  if n.period !~ '^\d{4}-(0[1-9]|1[0-2])$' or n.period not between '2023-08' and '2099-12' then
    return jsonb_build_object('error', 'bad-period');
  end if;
  if length(n.title) > 200 then return jsonb_build_object('error', 'bad-title'); end if;
  if n.reference_url is not null and (n.reference_url !~ '^https://' or length(n.reference_url) > 1000) then
    return jsonb_build_object('error', 'bad-link');
  end if;
  if n.duration_minutes is not null and n.duration_minutes not between 5 and 1440 then
    return jsonb_build_object('error', 'bad-duration');
  end if;
  if n.shoot_on is not null and n.shoot_on not between date '2023-08-14' and date '2099-12-31' then
    return jsonb_build_object('error', 'bad-date');
  end if;
  if greatest(length(coalesce(n.platform, '')), length(coalesce(n.language, '')), length(coalesce(n.venue, ''))) > 200
     or greatest(length(coalesce(n.cast_names, '')), length(coalesce(n.context, '')),
                 length(coalesce(n.vo, '')), length(coalesce(n.remarks, ''))) > 4000 then
    return jsonb_build_object('error', 'too-long');
  end if;
  if p_scenes is not null then
    if jsonb_typeof(p_scenes) <> 'array' then return jsonb_build_object('error', 'bad-scenes'); end if;
    if jsonb_array_length(p_scenes) > 60 then return jsonb_build_object('error', 'too-many'); end if;
    if exists (select 1 from jsonb_array_elements(p_scenes) e
                where length(coalesce(e.value ->> 'visual', '')) > 2000
                   or length(coalesce(e.value ->> 'line', '')) > 2000) then
      return jsonb_build_object('error', 'too-long');
    end if;
  end if;

  if n.period is distinct from v.period then
    perform pg_advisory_xact_lock(hashtext('video_script:' || v.client_id::text || ':' || n.period));
    select min(g) into n.seq from generate_series(1, 99) g
     where not exists (select 1 from public.video_scripts s where s.client_id = v.client_id and s.period = n.period and s.seq = g);
    if n.seq is null then return jsonb_build_object('error', 'too-many'); end if;
    select e.id into n.engagement_id from public.ops_engagements e where e.client_id = v.client_id and e.period = n.period limit 1;
    v_moves := v_moves || ('Month: ' || replace(to_char(to_date(v.period, 'YYYY-MM'), 'Mon YYYY'), 'Sep ', 'Sept ')
                           || ' → ' || replace(to_char(to_date(n.period, 'YYYY-MM'), 'Mon YYYY'), 'Sep ', 'Sept ')
                           || ' · ' || v.code || ' → ' || substr(n.period, 3, 2) || substr(n.period, 6, 2) || 'VS' || lpad(n.seq::text, 2, '0'));
  end if;
  v_kindw := case n.kind when 'products' then 'Products and context' when 'story' then 'Hook and story' else 'Context' end;
  if n.kind is distinct from v.kind then
    v_creat := true;
    v_moves := v_moves || ('Kind: ' || case v.kind when 'scenes' then 'Detailed scenes' when 'products' then 'Products and scenes' else 'Story and voice-over' end
                           || ' → ' || case n.kind when 'scenes' then 'Detailed scenes' when 'products' then 'Products and scenes' else 'Story and voice-over' end);
  end if;
  if n.title is distinct from v.title then
    v_creat := true;
    v_moves := v_moves || ('Title: ' || coalesce(nullif(v.title, ''), 'not set') || ' → ' || coalesce(nullif(n.title, ''), 'not set'));
  end if;
  if n.reference_url is distinct from v.reference_url then
    v_creat := true;
    v_moves := v_moves || ('Reference: ' || coalesce(v.reference_url, 'not set') || ' → ' || coalesce(n.reference_url, 'not set'));
  end if;
  if n.platform is distinct from v.platform then
    v_moves := v_moves || ('Platform: ' || coalesce(v.platform, 'not set') || ' → ' || coalesce(n.platform, 'not set'));
  end if;
  if n.language is distinct from v.language then
    v_moves := v_moves || ('Language: ' || coalesce(v.language, 'not set') || ' → ' || coalesce(n.language, 'not set'));
  end if;
  if n.shoot_on is distinct from v.shoot_on then
    v_moves := v_moves || ('Shooting date: '
      || coalesce(replace(to_char(v.shoot_on, 'FMDD Mon YYYY'), 'Sep ', 'Sept '), 'not set') || ' → '
      || coalesce(replace(to_char(n.shoot_on, 'FMDD Mon YYYY'), 'Sep ', 'Sept '), 'not set'));
  end if;
  if n.shoot_time is distinct from v.shoot_time then
    v_moves := v_moves || ('Shooting time: ' || coalesce(to_char(v.shoot_time, 'FMHH12:MI am'), 'not set')
                           || ' → ' || coalesce(to_char(n.shoot_time, 'FMHH12:MI am'), 'not set'));
  end if;
  if n.venue is distinct from v.venue then
    v_moves := v_moves || ('Venue: ' || coalesce(v.venue, 'not set') || ' → ' || coalesce(n.venue, 'not set'));
  end if;
  if n.duration_minutes is distinct from v.duration_minutes then
    v_moves := v_moves || ('Duration: ' || coalesce(v.duration_minutes || ' min', 'not set') || ' → '
                           || coalesce(n.duration_minutes || ' min', 'not set'));
  end if;
  if n.cast_names is distinct from v.cast_names then v_moves := v_moves || 'Cast'::text; end if;
  if n.context is distinct from v.context then v_creat := true; v_moves := v_moves || v_kindw; end if;
  if n.vo is distinct from v.vo then v_creat := true; v_moves := v_moves || 'Script (read here)'::text; end if;
  if n.remarks is distinct from v.remarks then v_moves := v_moves || 'Notes'::text; end if;

  if p_scenes is not null then
    select coalesce(jsonb_agg(jsonb_build_object('visual', coalesce(sc.visual, ''), 'line', coalesce(sc.line, ''))
                              order by sc.position), '[]'::jsonb)
      into v_old_sc from public.video_script_scenes sc where sc.script_id = p_id;
    select coalesce(jsonb_agg(jsonb_build_object('visual', btrim(coalesce(e.value ->> 'visual', '')),
                                                 'line', btrim(coalesce(e.value ->> 'line', '')))
                              order by e.ord), '[]'::jsonb)
      into v_new_sc from jsonb_array_elements(p_scenes) with ordinality as e(value, ord);
    if v_new_sc is distinct from v_old_sc then
      v_creat := true;
      v_moves := v_moves || ('Scenes' || case when jsonb_array_length(v_old_sc) <> jsonb_array_length(v_new_sc)
                                              then ': ' || jsonb_array_length(v_old_sc) || ' → ' || jsonb_array_length(v_new_sc)
                                              else '' end);
      for v_row in select e.value from jsonb_array_elements(p_scenes) e loop
        v_pos := v_pos + 1;
        v_sid := null;
        if coalesce(v_row ->> 'id', '') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
          select sc.id into v_sid from public.video_script_scenes sc
           where sc.id = (v_row ->> 'id')::uuid and sc.script_id = p_id;
        end if;
        if v_sid is null then
          insert into public.video_script_scenes (script_id, position, visual, line)
          values (p_id, v_pos, nullif(btrim(coalesce(v_row ->> 'visual', '')), ''),
                  nullif(btrim(coalesce(v_row ->> 'line', '')), ''))
          returning id into v_sid;
        else
          update public.video_script_scenes sc
             set position = v_pos,
                 visual = nullif(btrim(coalesce(v_row ->> 'visual', '')), ''),
                 line = nullif(btrim(coalesce(v_row ->> 'line', '')), '')
           where sc.id = v_sid;
        end if;
        v_keep := v_keep || v_sid;
      end loop;
      delete from public.video_script_scenes sc where sc.script_id = p_id and not (sc.id = any (v_keep));
    end if;
  end if;

  if coalesce(array_length(v_moves, 1), 0) = 0 then
    return jsonb_build_object('ok', true, 'version', v.version, 'round', v.round, 'changed', false);
  end if;
  update public.video_scripts s
     set kind = n.kind, title = n.title, reference_url = n.reference_url, platform = n.platform,
         language = n.language, shoot_on = n.shoot_on, shoot_time = n.shoot_time, venue = n.venue,
         duration_minutes = n.duration_minutes, cast_names = n.cast_names, context = n.context,
         vo = n.vo, remarks = n.remarks, period = n.period, seq = n.seq, engagement_id = n.engagement_id,
         version = v.version + 1, updated_at = now(), updated_by_name = me.name
   where s.id = p_id;
  select c.name into v_client from public.clients c where c.id = v.client_id;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'script.saved', v_client,
          public.video_script_label(n) || ' · ' || array_to_string(v_moves, '; '));
  return jsonb_build_object('ok', true, 'version', v.version + 1, 'round', v.round, 'changed', true,
    'code', substr(n.period, 3, 2) || substr(n.period, 6, 2) || 'VS' || lpad(n.seq::text, 2, '0'));
end $$;
revoke all on function public.video_script_save(uuid, jsonb, jsonb, integer) from public, anon;
grant execute on function public.video_script_save(uuid, jsonb, jsonb, integer) to authenticated;

create or replace function public.video_script_delete(p_id uuid, p_typed text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me   public.team_members := public.ops_me();
  s    public.video_scripts;
  v_cl text;
begin
  if me.id is null or not public.allowed('scripts', 'manage') then return jsonb_build_object('error', 'denied'); end if;
  select * into s from public.video_scripts x where x.id = p_id for update;
  if s.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if not public.client_seen(s.client_id, 'manage') then return jsonb_build_object('error', 'client-scope'); end if;
  if lower(btrim(coalesce(p_typed, ''))) <> lower(coalesce(nullif(btrim(s.title), ''), s.code)) then
    return jsonb_build_object('error', 'name');
  end if;
  select c.name into v_cl from public.clients c where c.id = s.client_id;
  delete from public.video_scripts x where x.id = p_id;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'script.deleted', v_cl, public.video_script_label(s));
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.video_script_delete(uuid, text) from public, anon;
grant execute on function public.video_script_delete(uuid, text) to authenticated;

/* On site, from the client link: a shared script's scene ticked shot and
   its clip number (VC#); with no scene, the voice-over's. Filed under the
   client by `Client link`. */
create or replace function public.script_shot_link(p_token text, p_script uuid, p_scene uuid, p_on boolean,
                                                   p_vc text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_cl   public.clients;
  s      public.video_scripts;
  sc     public.video_script_scenes;
  v_was  boolean;
begin
  select * into v_cl from public.clients c
   where c.script_key = p_token and p_token is not null and c.active;
  if v_cl.id is null then return jsonb_build_object('error', 'not_found'); end if;
  select * into s from public.video_scripts x
   where x.id = p_script and x.client_id = v_cl.id and x.status = 'shared' for update;
  if s.id is null then return jsonb_build_object('error', 'not_found'); end if;
  if p_vc is not null and length(p_vc) > 40 then return jsonb_build_object('error', 'too-long'); end if;
  if p_scene is null then
    v_was := s.vo_shot_at is not null;
    update public.video_scripts x
       set vo_shot_at = case when p_on is null then x.vo_shot_at when p_on then coalesce(x.vo_shot_at, now()) end,
           vo_shot_by = case when p_on is null then x.vo_shot_by when p_on then coalesce(x.vo_shot_by, 'Client link') end,
           vo_vc = case when p_vc is null then x.vo_vc else nullif(btrim(p_vc), '') end
     where x.id = p_script;
    if p_on is not null and p_on <> v_was then
      insert into public.activity_log (actor, action, subject, detail)
      values ('Client link', 'script.shot', v_cl.name, public.video_script_label(s) || ' · Script (read here) '
              || case when p_on then 'shot' else 'not shot' end);
    end if;
    return jsonb_build_object('ok', true);
  end if;
  select * into sc from public.video_script_scenes y where y.id = p_scene and y.script_id = p_script for update;
  if sc.id is null then return jsonb_build_object('error', 'not_found'); end if;
  v_was := sc.shot_at is not null;
  update public.video_script_scenes y
     set shot_at = case when p_on is null then y.shot_at when p_on then coalesce(y.shot_at, now()) end,
         shot_by = case when p_on is null then y.shot_by when p_on then coalesce(y.shot_by, 'Client link') end,
         vc = case when p_vc is null then y.vc else nullif(btrim(p_vc), '') end
   where y.id = p_scene;
  if p_on is not null and p_on <> v_was then
    insert into public.activity_log (actor, action, subject, detail)
    values ('Client link', 'script.shot', v_cl.name, public.video_script_label(s) || ' · Scene ' || sc.position || ' '
            || case when p_on then 'shot' else 'not shot' end);
  end if;
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.script_shot_link(text, uuid, uuid, boolean, text) from public;
grant execute on function public.script_shot_link(text, uuid, uuid, boolean, text) to anon;
grant execute on function public.script_shot_link(text, uuid, uuid, boolean, text) to authenticated;

/* The client link: the shared scripts, newest month first, each with its
   code, its scenes, their clip numbers and Shot ticks. Never a colleague's
   name, who ticked, a version or a decision. */
create or replace function public.get_scripts(p_token text)
returns jsonb
language plpgsql security definer stable set search_path = public as $$
declare
  v_cl public.clients;
begin
  select * into v_cl from public.clients c
   where c.script_key = p_token and p_token is not null and c.active;
  if v_cl.id is null then return jsonb_build_object('error', 'not_found'); end if;
  return jsonb_build_object(
    'client', jsonb_build_object('name', v_cl.name, 'logo_url', v_cl.logo_url),
    'scripts', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', s.id, 'code', s.code, 'period', s.period, 'kind', s.kind,
               'title', s.title, 'reference_url', s.reference_url, 'platform', s.platform,
               'language', s.language, 'shoot_on', s.shoot_on, 'shoot_time', s.shoot_time,
               'venue', s.venue, 'duration_minutes', s.duration_minutes, 'cast_names', s.cast_names,
               'context', s.context, 'vo', s.vo, 'vo_vc', s.vo_vc, 'vo_shot', s.vo_shot_at is not null,
               'remarks', s.remarks, 'shared_at', s.shared_at, 'updated_at', s.updated_at,
               'scenes', coalesce((select jsonb_agg(jsonb_build_object('id', sc.id, 'position', sc.position,
                                                     'visual', sc.visual, 'line', sc.line, 'vc', sc.vc,
                                                     'shot', sc.shot_at is not null)
                                                     order by sc.position)
                                     from public.video_script_scenes sc where sc.script_id = s.id), '[]'::jsonb))
             order by s.period desc, s.seq)
        from public.video_scripts s
       where s.client_id = v_cl.id and s.status = 'shared'), '[]'::jsonb));
end $$;
revoke all on function public.get_scripts(text) from public;
grant execute on function public.get_scripts(text) to anon;
grant execute on function public.get_scripts(text) to authenticated;

-- The client no longer decides on a script (the user, 2026-10-09).
create or replace function public.script_decide(p_token text, p_script uuid, p_decision text,
                                                p_name text, p_note text default null)
returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object('error', 'closed')
$$;
revoke all on function public.script_decide(text, uuid, text, text, text) from public;
grant execute on function public.script_decide(text, uuid, text, text, text) to anon;
grant execute on function public.script_decide(text, uuid, text, text, text) to authenticated;

-- END OF SCRIPTS BY MONTH -----------------------------------------------------

-- ===========================================================================
-- WHATSAPP — messages sent from the portal through the WhatsApp Business
-- Platform (Cloud API), each with a template Meta approved: a published
-- report to the client's main contact, a feedback request sent by hand, the
-- team's reminders and a creator's booking steps.
-- 2026-10-09. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/smsql.js compares the
-- two.
--
-- WHAT CHANGED (the user, 2026-10-09: "Report to client, Team reminders,
-- Creator updates, Manually send with button a feedback approved template on
-- whatsapp")
--   1. `wa_templates`: one approved template a purpose (`report`, `feedback`,
--      `reminder`, `creator`): its name and language as Meta holds them, how
--      many body variables it takes, and whether it is on. Read by the team
--      (`wa_templates_read`), set by Business settings
--      (`wa_template_save`, filed `team.changed` under WhatsApp). A purpose
--      with no template on sends nothing.
--   2. `wa_outbox`: every message, queued or sent by hand: the purpose, the
--      number, the template and its values, what it is about, its state
--      (`queued`, `sent`, `failed`) with Meta's message id or its refusal.
--      RLS on, no policy, no grant; the sender alone claims and closes the
--      queue (`wa_claim`, `wa_done`, the service role's), and the team reads
--      the last fifty (`wa_recent`, Business settings).
--   3. A number is the WhatsApp number in its international form
--      (`wa_number`): digits only, a Malaysian number's leading 0 taking 60,
--      a Singapore number of eight digits taking 65; a WhatsApp username
--      (`@name`) cannot be messaged and is left out.
--   4. Queued by trigger, sent by `wa-send` once the write commits
--      (`wa_kick`, pg_net): each reminder in a colleague's bell (the notice
--      kinds `tasks.empty`, `outstation`, `perf.remind`, `perf.reflect`,
--      `health.remind`) to the colleague's mobile; a creator booked, asked
--      for changes or cleared to post, to the creator's WhatsApp number
--      (`creators.whatsapp`, new). A trigger never fails the write that
--      caused it.
--   5. By hand, through `wa-send` as the colleague: `wa_report_prepare`
--      (Reports Work, a published report, the client's main contact with a
--      WhatsApp number) and `wa_feedback_prepare` (Clients Work, the main
--      contact) answer the number, the name and the template; `wa_record`
--      files what was sent (`wa.sent` under the client) or refused.
--
-- ROLLBACK
--   In the SQL Editor: drop the triggers ops_notifications_wa and
--   campaign_options_wa, then the functions of this file, then the tables
--   wa_outbox and wa_templates. The column creators.whatsapp may stay.
-- ===========================================================================

alter table public.creators add column if not exists whatsapp text;

create table if not exists public.wa_templates (
  purpose   text primary key check (purpose in ('report', 'feedback', 'reminder', 'creator')),
  name      text not null default '',
  lang      text not null default 'en',
  params    integer not null default 0 check (params between 0 and 5),
  active    boolean not null default false,
  set_by    text,
  set_at    timestamptz
);
insert into public.wa_templates (purpose) values ('report'), ('feedback'), ('reminder'), ('creator')
on conflict (purpose) do nothing;
alter table public.wa_templates enable row level security;
revoke all on public.wa_templates from public, anon, authenticated;

create table if not exists public.wa_outbox (
  id          uuid primary key default gen_random_uuid(),
  purpose     text not null,
  to_number   text not null,
  to_name     text,
  template    text not null,
  lang        text not null default 'en',
  params      jsonb not null default '[]'::jsonb,
  ref_kind    text,
  ref_id      uuid,
  client_id   uuid,
  state       text not null default 'queued' check (state in ('queued', 'sending', 'sent', 'failed')),
  wa_id       text,
  error       text,
  tries       integer not null default 0,
  created_by  text,
  created_at  timestamptz not null default now(),
  claimed_at  timestamptz,
  sent_at     timestamptz
);
create index if not exists wa_outbox_state_idx on public.wa_outbox (state, created_at);
alter table public.wa_outbox enable row level security;
revoke all on public.wa_outbox from public, anon, authenticated;

/* A WhatsApp number in its international form, or null. */
create or replace function public.wa_number(p_raw text, p_market text default 'MY')
returns text
language sql immutable set search_path = public as $$
  select case
    when p_raw is null or btrim(p_raw) like '@%' then null
    else (select case
            when length(d) < 8 or length(d) > 15 then null
            when upper(coalesce(p_market, 'MY')) = 'SG' and length(d) = 8 then '65' || d
            when d like '0%' then '60' || substr(d, 2)
            else d end
          from (select regexp_replace(p_raw, '[^0-9]', '', 'g') as d) x)
  end
$$;
revoke all on function public.wa_number(text, text) from public, anon, authenticated;

create or replace function public.wa_templates_read()
returns jsonb
language sql stable security definer set search_path = public as $$
  select case when public.ops_me() is null or (public.ops_me()).id is null then jsonb_build_object('error', 'denied')
    else jsonb_build_object('templates', coalesce((select jsonb_agg(jsonb_build_object(
      'purpose', t.purpose, 'name', t.name, 'lang', t.lang, 'params', t.params, 'active', t.active,
      'set_by', t.set_by, 'set_at', t.set_at) order by array_position(array['report', 'feedback', 'reminder', 'creator'], t.purpose))
      from public.wa_templates t), '[]'::jsonb)) end
$$;
revoke all on function public.wa_templates_read() from public, anon;
grant execute on function public.wa_templates_read() to authenticated;

create or replace function public.wa_template_save(p_purpose text, p_name text, p_lang text, p_params integer, p_active boolean)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me     public.team_members := public.ops_me();
  t      public.wa_templates;
  v_name text := btrim(coalesce(p_name, ''));
  v_lang text := btrim(coalesce(p_lang, ''));
  v_word text;
begin
  if me.id is null or not public.ops_granted('team.settings', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into t from public.wa_templates x where x.purpose = p_purpose;
  if t.purpose is null then return jsonb_build_object('error', 'not-found'); end if;
  if (v_name !~ '^[a-z0-9_]+$' or length(v_name) > 512) and not (v_name = '' and not coalesce(p_active, false)) then
    return jsonb_build_object('error', 'bad-name');
  end if;
  if v_lang !~ '^[a-z]{2,3}(_[A-Z]{2})?$' then return jsonb_build_object('error', 'bad-lang'); end if;
  if p_params is null or p_params not between 0 and 5 then return jsonb_build_object('error', 'bad-params'); end if;
  if t.name = v_name and t.lang = v_lang and t.params = p_params and t.active = coalesce(p_active, false) then
    return jsonb_build_object('ok', true, 'same', true);
  end if;
  update public.wa_templates x
     set name = v_name, lang = v_lang, params = p_params, active = coalesce(p_active, false), set_by = me.name, set_at = now()
   where x.purpose = p_purpose;
  v_word := case p_purpose when 'report' then 'Report to client' when 'feedback' then 'Feedback request'
                           when 'reminder' then 'Team reminders' else 'Creator updates' end;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'team.changed', 'WhatsApp',
          v_word || ': ' || coalesce(nullif(t.name, ''), 'not set') || ' (' || t.lang || ', ' || case when t.active then 'on' else 'off' end
          || ') → ' || coalesce(nullif(v_name, ''), 'not set') || ' (' || v_lang || ', ' || case when coalesce(p_active, false) then 'on' else 'off' end || ')');
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.wa_template_save(text, text, text, integer, boolean) from public, anon;
grant execute on function public.wa_template_save(text, text, text, integer, boolean) to authenticated;

/* The last fifty messages, newest first, for Business settings. */
create or replace function public.wa_recent()
returns jsonb
language sql stable security definer set search_path = public as $$
  select case when not public.ops_granted('team.settings', 'work') then jsonb_build_object('error', 'denied')
    else jsonb_build_object('items', coalesce((select jsonb_agg(x order by x.created_at desc) from (
      select o.id, o.purpose, o.to_name, '••••' || right(o.to_number, 4) as to_number, o.state, o.error,
             o.created_at, o.sent_at, o.created_by
        from public.wa_outbox o order by o.created_at desc limit 50) x), '[]'::jsonb)) end
$$;
revoke all on function public.wa_recent() from public, anon;
grant execute on function public.wa_recent() to authenticated;

/* Wakes wa-send once the write has committed. Silent where pg_net is not
   installed or refuses: the queue is kept, and the next wake sends it. */
create or replace function public.wa_kick()
returns void
language plpgsql security definer set search_path = public as $$
begin
  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
                  where n.nspname = 'net' and p.proname = 'http_post') then
    return;
  end if;
  execute 'select net.http_post(url := $1, body := $2)'
    using 'https://hwwuigvdfubuymchsvyx.supabase.co/functions/v1/wa-send', '{"action":"drain"}'::jsonb;
exception when others then
  return;
end $$;
revoke all on function public.wa_kick() from public, anon, authenticated;

/* One message into the queue, where its purpose has a template on and the
   number reads. */
create or replace function public.wa_queue(p_purpose text, p_number text, p_name text, p_params jsonb,
                                           p_ref_kind text, p_ref_id uuid, p_client uuid default null)
returns void
language plpgsql security definer set search_path = public as $$
declare t public.wa_templates;
begin
  select * into t from public.wa_templates x where x.purpose = p_purpose and x.active and x.name <> '';
  if t.purpose is null or p_number is null then return; end if;
  insert into public.wa_outbox (purpose, to_number, to_name, template, lang, params, ref_kind, ref_id, client_id, created_by)
  values (p_purpose, p_number, p_name, t.name, t.lang,
          coalesce((select jsonb_agg(e.value) from (select value from jsonb_array_elements(coalesce(p_params, '[]'::jsonb)) with ordinality e(value, n)
                     where n <= t.params order by n) e), '[]'::jsonb),
          p_ref_kind, p_ref_id, p_client, 'system');
  perform public.wa_kick();
end $$;
revoke all on function public.wa_queue(text, text, text, jsonb, text, uuid, uuid) from public, anon, authenticated;

/* A reminder in a colleague's bell, to their WhatsApp too. */
create or replace function public.ops_notifications_wa()
returns trigger
language plpgsql security definer set search_path = public as $$
declare m public.team_members;
begin
  if new.kind not in ('tasks.empty', 'outstation', 'perf.remind', 'perf.reflect', 'health.remind') then return new; end if;
  select * into m from public.team_members x where x.id = new.team_member_id and x.active;
  if m.id is null then return new; end if;
  perform public.wa_queue('reminder', public.wa_number(m.mobile, 'MY'), m.name,
    jsonb_build_array(split_part(btrim(m.name), ' ', 1), coalesce(new.title, ''), coalesce(new.body, '')),
    'notice', new.id);
  return new;
exception when others then
  return new;
end $$;
revoke all on function public.ops_notifications_wa() from public, anon, authenticated;
create or replace trigger ops_notifications_wa after insert on public.ops_notifications
  for each row execute function public.ops_notifications_wa();

/* A creator booked, asked for changes, or cleared to post: told on WhatsApp
   as on their phone's notifications. Only a forward move. */
create or replace function public.campaign_options_wa()
returns trigger
language plpgsql security definer set search_path = public as $$
declare
  k       public.creators;
  v_title text;
  v_cl    uuid;
  v_what  text;
begin
  if new.state is not distinct from old.state then return new; end if;
  v_what := case
    when new.state = 'confirmed' and old.state in ('option', 'shortlisted', 'backup') then 'Booking confirmed'
    when new.state = 'changes' then 'Changes requested'
    when new.state = 'scheduled' and old.state in ('submitted', 'reviewing', 'changes') then 'Approved: ready to post'
    else null end;
  if v_what is null then return new; end if;
  select * into k from public.creators x where x.id = new.creator_id;
  if k.id is null then return new; end if;
  select coalesce(nullif(btrim(c.title), ''), 'Your campaign'), c.client_id into v_title, v_cl
    from public.campaigns c where c.id = new.campaign_id;
  perform public.wa_queue('creator', public.wa_number(k.whatsapp, 'MY'), k.name,
    jsonb_build_array(split_part(btrim(k.name), ' ', 1), v_title, v_what), 'option', new.id, v_cl);
  return new;
exception when others then
  return new;
end $$;
revoke all on function public.campaign_options_wa() from public, anon, authenticated;
create or replace trigger campaign_options_wa after update of state on public.campaign_options
  for each row execute function public.campaign_options_wa();

/* The sender's side, the service role's alone: claim what is queued (and
   what was claimed over five minutes ago without an answer), then close it. */
create or replace function public.wa_claim(p_limit integer default 20)
returns setof public.wa_outbox
language sql security definer set search_path = public as $$
  update public.wa_outbox o set state = 'sending', claimed_at = now(), tries = o.tries + 1
   where o.id in (select x.id from public.wa_outbox x
                   where (x.state = 'queued' or (x.state = 'sending' and x.claimed_at < now() - interval '5 minutes'))
                     and x.tries < 3
                   order by x.created_at limit greatest(1, least(coalesce(p_limit, 20), 50))
                   for update skip locked)
  returning o.*
$$;
create or replace function public.wa_done(p_id uuid, p_ok boolean, p_wa_id text, p_error text)
returns void
language sql security definer set search_path = public as $$
  update public.wa_outbox o
     set state = case when p_ok then 'sent' when o.tries >= 3 then 'failed' else 'queued' end,
         wa_id = left(p_wa_id, 200), error = left(p_error, 500), sent_at = case when p_ok then now() end
   where o.id = p_id
$$;
revoke all on function public.wa_claim(integer) from public, anon, authenticated;
revoke all on function public.wa_done(uuid, boolean, text, text) from public, anon, authenticated;

/* By hand: what a published report's message needs, asked as the colleague. */
create or replace function public.wa_report_prepare(p_id uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  r   public.sm_reports;
  c   public.clients;
  k   public.client_contacts;
  t   public.wa_templates;
  v_n text;
begin
  if not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports x where x.id = p_id;
  if r.id is null or not public.client_seen(r.client_id, 'view') then return jsonb_build_object('error', 'not-found'); end if;
  if r.status <> 'published' then return jsonb_build_object('error', 'not-published'); end if;
  select * into t from public.wa_templates x where x.purpose = 'report' and x.active and x.name <> '';
  if t.purpose is null then return jsonb_build_object('error', 'wa-off'); end if;
  select * into c from public.clients x where x.id = r.client_id;
  select * into k from public.client_contacts x where x.client_id = r.client_id and x.archived_at is null
   order by x.is_primary desc nulls last, x.created_at limit 1;
  v_n := public.wa_number(coalesce(case when k.whatsapp !~ '^@' then k.whatsapp end, k.phone), c.market);
  if v_n is null then return jsonb_build_object('error', 'no-number'); end if;
  return jsonb_build_object('ok', true, 'number', v_n, 'name', k.name, 'first', split_part(btrim(coalesce(k.name, '')), ' ', 1),
    'client', coalesce(nullif(r.brand_name, ''), c.name), 'client_id', c.id,
    'template', t.name, 'lang', t.lang, 'params', t.params);
end $$;
revoke all on function public.wa_report_prepare(uuid) from public, anon;
grant execute on function public.wa_report_prepare(uuid) to authenticated;

