-- ===========================================================================
-- WHATSAPP ACTIVITY MAP — a message sent on WhatsApp and a template changed
-- file under WhatsApp in the activity record.
-- 2026-10-10. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/smsql.js compares the
-- two. Run after 2026-10-10-whatsapp-section.sql. A file of its own because
-- the map names tags such as `client.deleted`, which the Supabase connector
-- holds for a confirmation it cannot show: hand it to the SQL Editor as its
-- own run.
--
-- WHAT CHANGED (the user, 2026-10-10: WhatsApp a section of its own)
--   `wa.sent` (a message sent by hand, from the composer or a record) moves
--   from Clients to WhatsApp, and `wa.template` (a purpose's template chosen
--   or switched, `wa_template_set`) joins it. `campaign.whatsapp` (a
--   booking queued again, before the composer) stays with Creator
--   Campaigns. js/admin.js ACTION_LABEL names both.
--
-- ROLLBACK
--   Restate the map from 2026-10-09-whatsapp-numbers-resend.sql.
-- ===========================================================================

create or replace function public.activity_section(p_action text)
returns text
language sql immutable parallel safe as $$
  select case
    when action in ('campaign.bulk', 'campaign.closed', 'campaign.confirmed',
                    'campaign.created', 'campaign.dates', 'campaign.deleted', 'campaign.edited',
                    'campaign.file_added', 'campaign.qc',
                    'campaign.invoice', 'campaign.invoice_file',
                    'campaign.invoice_removed', 'campaign.keyed', 'campaign.locked',
                    'campaign.opened', 'campaign.rate', 'campaign.rated',
                    'campaign.reinstated', 'campaign.replaced', 'campaign.results', 'campaign.review',
                    'campaign.stage', 'campaign.submitted', 'campaign.task_linked',
                    'campaign.task_unlinked', 'campaign.unbooked',
                    'campaign.unkeyed', 'campaign.whatsapp', 'campaign.withdrawn', 'creator.added',
                    'creator.code', 'creator.links', 'creator.links_restored',
                    'creator.links_self', 'creator.off', 'creator.on', 'creator.removed',
                    'creator.updated') then 'campaigns'
    when action in ('client.action_done', 'client.action_reopened', 'client.added',
                    'client.billing', 'client.brand', 'client.deleted', 'client.edited',
                    'client.review_on', 'client.service', 'client.service_changed',
                    'client.service_removed', 'client.service_restored', 'client.stage', 'client.touch',
                    'client.touch_deleted', 'client.touch_edited', 'client.touch_removed',
                    'client.touch_restored', 'contact.added', 'contact.deleted',
                    'contact.edited', 'contact.portal_invite', 'contact.portal_off',
                    'contact.portal_on', 'contact.primary', 'contact.removed',
                    'contact.restored',
                    'request.changed', 'request.raised',
                    'request.reinstated', 'request.replied', 'request.withdrawn',
                    'service.override') then 'clients'
    when action in ('wa.sent', 'wa.template') then 'whatsapp'
    when action in ('report.ai_drafted', 'report.ai_failed', 'report.audited', 'report.confirmed',
                    'report.created', 'report.deleted', 'report.published',
                    'report.reassigned', 'report.returned', 'report.revised', 'report.saved',
                    'report.submitted', 'report.unpublished') then 'reports'
    when action in ('qr.created', 'qr.restored', 'qr.revoked', 'shortlink.created',
                    'shortlink.deleted', 'shortlink.imported', 'shortlink.updated') then 'links'
    when action in ('ops.deleted', 'ops.month_deleted', 'ops.numbering') then 'ops'
    when action in ('document.deleted', 'document.issued', 'document.reissued',
                    'document.restored', 'document.signed', 'document.superseded',
                    'document.unsigned', 'document.verified', 'document.voided',
                    'register.added', 'register.edited') then 'register'
    when action in ('client.drive', 'client.handles', 'client.profile',
                    'client.removed', 'drive.imported', 'link.reset', 'post.added',
                    'post.deleted', 'post.edited', 'reapproval.requested',
                    'review.approved', 'review.changes', 'review.removed',
                    'review.unconfirmed',
                    'set.created', 'set.deleted', 'set.published', 'set.renamed',
                    'set.task_linked', 'set.task_unlinked',
                    'set.withdrawn') then 'review'
    when action in ('script.approved', 'script.changes', 'script.created', 'script.deleted',
                    'script.link', 'script.saved', 'script.shared', 'script.shot',
                    'script.unshared') then 'scripts'
    when action in ('handbook.added', 'handbook.archived', 'handbook.deleted',
                    'handbook.edited', 'handbook.restored', 'handbook.version') then 'handbook'
    when action in ('service.added', 'service.changed', 'service.deleted',
                    'service.off', 'service.on') then 'services'
    when action in ('team.added', 'team.changed', 'team.edited', 'team.group_added',
                    'team.group_changed', 'team.group_removed', 'team.invited') then 'team'
    else 'other'
  end
  from (select p_action as action) t
$$;
grant execute on function public.activity_section(text) to authenticated;

-- END OF WHATSAPP ACTIVITY MAP ------------------------------------------------

-- ===========================================================================
-- WHATSAPP APPROVAL PURPOSE — a fifth purpose a template is set for, the
-- approval reminder.
-- 2026-10-10. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/smsql.js compares the
-- two. Run in the SQL Editor (it replaces a check, which the Supabase
-- connector stops on), before 2026-10-10-whatsapp-approval-reminder.sql.
--
-- WHAT CHANGED (the user, 2026-10-10: "yes" to the approval chaser)
--   1. `wa_templates.purpose` takes `approval` beside report, feedback,
--      reminder and creator, and its row is seeded switched off.
--
-- ROLLBACK
--   Pages first (Templates lists four purposes again), then delete the
--   `approval` row and put the check back without it.
-- ===========================================================================

alter table public.wa_templates drop constraint if exists wa_templates_purpose_check;
alter table public.wa_templates add constraint wa_templates_purpose_check
  check (purpose in ('report', 'feedback', 'reminder', 'creator', 'approval'));
insert into public.wa_templates (purpose) values ('approval') on conflict (purpose) do nothing;

-- END OF WHATSAPP APPROVAL PURPOSE --------------------------------------------

-- ===========================================================================
-- WHATSAPP APPROVAL REMINDER — a client reminded on WhatsApp, by hand, when a
-- content set or a creator's draft has waited on their approval.
-- 2026-10-10. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/smsql.js compares the
-- two. Run after 2026-10-10-whatsapp-approval-purpose.sql.
--
-- WHAT CHANGED (the user, 2026-10-10: "yes" to the approval chaser: manual,
-- its own template purpose, the wait a Business setting)
--   1. `approval_reminder_days` (3), a Business setting from a day on: how
--      long a published set or a draft at Reviewing waits on the client
--      before My Work's Waiting for you offers Remind. `app_settings_set`
--      takes it (1 to 60 whole days), filed as Approval reminder.
--   2. `wa_may_send('approval', 'contact')`: WhatsApp and its Approval
--      reminder part at Work, and Content Review: Content sets or Creator
--      Campaigns: Campaigns at View.
--   3. `wa_compose_prepare` and `wa_sent` take `approval` to a client
--      contact, `p_ref` a published content set of the contact's client
--      (Content sets View) or a booking at Reviewing on a campaign of that
--      client (Campaigns View); else `not-found` or `not-waiting`. It is
--      filed against the set (`set`) or the booking (`option`), and in the
--      activity record as "Approval reminder sent on WhatsApp to …".
--   4. `wa_template_set` names the purpose Approval reminder.
--
-- ROLLBACK
--   Pages first, then restate app_settings_set from META CHECKS SWITCH and
--   wa_may_send, wa_compose_prepare, wa_sent and wa_template_set from
--   WHATSAPP SECTION. The setting's row may stay.
-- ===========================================================================

insert into public.app_settings (key, from_date, value)
select 'approval_reminder_days', date '2023-08-14', 3
 where not exists (select 1 from public.app_settings s where s.key = 'approval_reminder_days');

create or replace function public.app_settings_set(p_from date, p_values jsonb)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me public.team_members; v_k text; v_v numeric; v_was numeric; v_name text; v_unit text;
  v_today date := (now() at time zone 'Asia/Kuala_Lumpur')::date;
  v_keys constant text[] := array['lead_followup_hours', 'proposal_followup_days', 'sst_pct',
    'term_1_3', 'term_4_5', 'term_6_11', 'term_12_23', 'term_24', 'report_due_days', 'revision_due_days',
    'ai_price_in', 'ai_price_out', 'meta_checks', 'approval_reminder_days'];
  v_moved text[] := '{}';
begin
  if not public.ops_granted('team.settings', 'work') then return jsonb_build_object('error', 'denied'); end if;
  v_me := public.ops_me();
  if p_from is null or p_from < v_today then return jsonb_build_object('error', 'past', 'today', v_today); end if;
  if jsonb_typeof(p_values) is distinct from 'object' then return jsonb_build_object('error', 'bad-value'); end if;
  for v_k in select jsonb_object_keys(p_values) loop
    if not (v_k = any(v_keys)) or jsonb_typeof(p_values -> v_k) <> 'number' then
      return jsonb_build_object('error', 'bad-value', 'key', v_k);
    end if;
    v_v := (p_values ->> v_k)::numeric;
    if round(v_v, 2) <> v_v
       or (v_k = 'lead_followup_hours' and (v_v < 1 or v_v > 720 or v_v <> trunc(v_v)))
       or (v_k = 'proposal_followup_days' and (v_v < 1 or v_v > 365 or v_v <> trunc(v_v)))
       or (v_k = 'report_due_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'revision_due_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'approval_reminder_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'sst_pct' and (v_v < 0 or v_v > 100))
       or (v_k like 'term_%' and (v_v < -100 or v_v > 100))
       or (v_k like 'ai_price_%' and (v_v < 0 or v_v > 1000))
       or (v_k = 'meta_checks' and v_v not in (0, 1)) then
      return jsonb_build_object('error', 'bad-value', 'key', v_k);
    end if;
  end loop;
  for v_k in select jsonb_object_keys(p_values) loop
    v_v := (p_values ->> v_k)::numeric;
    v_was := public.app_setting(v_k, p_from);
    if v_was is distinct from v_v then
      insert into public.app_settings (key, from_date, value, set_by, set_at)
      values (v_k, p_from, v_v, v_me.id, now())
      on conflict (key, from_date) do update set value = excluded.value, set_by = excluded.set_by, set_at = now();
      v_name := case v_k when 'lead_followup_hours' then 'A lead waits' when 'proposal_followup_days' then 'A proposal waits'
        when 'sst_pct' then 'SST' when 'term_1_3' then '1 to 3 months' when 'term_4_5' then '4 and 5 months'
        when 'term_6_11' then '6 to 11 months' when 'term_12_23' then '12 to 23 months' when 'term_24' then '24 months and more'
        when 'revision_due_days' then 'Revision due' when 'ai_price_in' then 'AI input, a million tokens'
        when 'ai_price_out' then 'AI output, a million tokens' when 'meta_checks' then 'Meta checks'
        when 'approval_reminder_days' then 'Approval reminder' else 'Report due' end;
      v_unit := case when v_k = 'lead_followup_hours' then ' hours' when v_k in ('proposal_followup_days', 'report_due_days', 'revision_due_days', 'approval_reminder_days') then ' days'
        else '%' end;
      insert into public.activity_log (actor, action, subject, detail)
      values (coalesce(v_me.name, 'admin'), 'team.changed', 'Settings',
              v_name || ': ' || case when v_k = 'meta_checks' then
                case when v_was = 1 then 'On' else 'Off' end || ' → ' || case when v_v = 1 then 'On' else 'Off' end ||
                ' · from ' || public.register_day(p_from) else '' end ||
              case when v_k = 'meta_checks' then '' else case when v_k like 'ai_price_%' then 'US$' else '' end ||
              trim(to_char(v_was, 'FM999999990.99'), '.') || case when v_k like 'ai_price_%' then '' else v_unit end || ' → ' ||
              case when v_k like 'ai_price_%' then 'US$' else '' end ||
              trim(to_char(v_v, 'FM999999990.99'), '.') || case when v_k like 'ai_price_%' then '' else v_unit end ||
              ' · from ' || public.register_day(p_from) end);
      v_moved := v_moved || v_k;
    end if;
  end loop;
  return public.app_settings_read() || jsonb_build_object('changed', to_jsonb(v_moved));
end $$;
revoke all on function public.app_settings_set(date, jsonb) from public, anon;

create or replace function public.wa_may_send(p_purpose text, p_to_kind text)
returns boolean
language sql stable security definer set search_path = public as $$
  select public.allowed('whatsapp', 'work') and case p_purpose
    when 'report'   then public.allowed('whatsapp.report', 'work') and public.allowed('reports', 'view')
    when 'feedback' then public.allowed('whatsapp.feedback', 'work') and public.allowed('clients', 'view')
    when 'creator'  then public.allowed('whatsapp.booking', 'work') and public.allowed('campaigns', 'view')
    when 'approval' then p_to_kind = 'contact' and public.allowed('whatsapp.approval', 'work')
                         and (public.allowed('review.sets', 'view') or public.allowed('campaigns.campaigns', 'view'))
    when 'message'  then case p_to_kind when 'contact' then public.allowed('clients.contacts', 'view')
                                        when 'creator' then public.allowed('campaigns.creators', 'view')
                                        else false end
    else false end
$$;
revoke all on function public.wa_may_send(text, text) from public, anon, authenticated;

create or replace function public.wa_compose_prepare(p_to_kind text, p_to uuid, p_purpose text, p_ref uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  me   public.team_members := public.ops_me();
  k    public.client_contacts;
  cr   public.creators;
  c    public.clients;
  r    public.sm_reports;
  o    public.campaign_options;
  cp   public.campaigns;
  b    public.batches;
  v_n  text;
begin
  if me.id is null then return jsonb_build_object('error', 'denied'); end if;
  if p_purpose not in ('message', 'report', 'feedback', 'creator', 'approval') or p_to_kind not in ('contact', 'creator')
     or (p_purpose in ('report', 'feedback', 'approval') and p_to_kind <> 'contact')
     or (p_purpose = 'creator' and p_to_kind <> 'creator') then
    return jsonb_build_object('error', 'bad-request');
  end if;
  if not public.wa_may_send(p_purpose, p_to_kind) then return jsonb_build_object('error', 'denied'); end if;
  if p_to_kind = 'contact' then
    select * into k from public.client_contacts x where x.id = p_to and x.archived_at is null;
    if k.id is null then return jsonb_build_object('error', 'not-found'); end if;
    select * into c from public.clients x where x.id = k.client_id;
    if c.id is null or not public.client_seen(c.id, 'view') then return jsonb_build_object('error', 'not-found'); end if;
    if p_purpose = 'report' then
      select * into r from public.sm_reports x where x.id = p_ref;
      if r.id is null or r.client_id <> c.id then return jsonb_build_object('error', 'not-found'); end if;
      if r.status <> 'published' then return jsonb_build_object('error', 'not-published'); end if;
    end if;
    /* An approval reminder names what waits on the client: a published
       content set of theirs, or a creator's draft at Reviewing on a
       campaign of theirs, each read at its own section. */
    if p_purpose = 'approval' then
      select * into b from public.batches x where x.id = p_ref;
      if b.id is not null then
        if b.client_id <> c.id or not public.allowed('review.sets', 'view') then return jsonb_build_object('error', 'not-found'); end if;
        if not coalesce(b.published, false) then return jsonb_build_object('error', 'not-waiting'); end if;
      else
        select * into o from public.campaign_options x where x.id = p_ref;
        if o.id is not null then select * into cp from public.campaigns x where x.id = o.campaign_id; end if;
        if o.id is null or cp.id is null or cp.client_id is distinct from c.id or not public.allowed('campaigns.campaigns', 'view') then
          return jsonb_build_object('error', 'not-found');
        end if;
        if o.state <> 'reviewing' then return jsonb_build_object('error', 'not-waiting'); end if;
      end if;
    end if;
    v_n := public.wa_number(coalesce(case when k.whatsapp !~ '^@' then k.whatsapp end, k.phone), c.market);
    if v_n is null then
      return jsonb_build_object('error', case when k.whatsapp ~ '^@' then 'username' else 'no-number' end);
    end if;
    return jsonb_build_object('ok', true, 'number', v_n, 'name', k.name, 'greeting', public.contact_greeting(k.salutation, k.name),
      'client_id', c.id, 'client', case when r.id is not null then coalesce(nullif(r.brand_name, ''), c.name) else c.name end,
      'subject', c.name, 'ref_kind', case when b.id is not null then 'set' when o.id is not null then 'option' end);
  end if;
  select * into cr from public.creators x where x.id = p_to;
  if cr.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if p_purpose = 'creator' then
    select * into o from public.campaign_options x where x.id = p_ref;
    if o.id is null or o.creator_id <> cr.id then return jsonb_build_object('error', 'not-found'); end if;
    select * into cp from public.campaigns x where x.id = o.campaign_id;
    if cp.id is null or (cp.client_id is not null and not public.client_seen(cp.client_id, 'view')) then
      return jsonb_build_object('error', 'not-found');
    end if;
    if o.state in ('option', 'shortlisted', 'backup', 'withdrawn', 'replaced') then
      return jsonb_build_object('error', 'not-booked');
    end if;
  elsif not cr.active then
    return jsonb_build_object('error', 'not-found');
  end if;
  v_n := public.wa_number(cr.whatsapp, 'MY');
  if v_n is null then return jsonb_build_object('error', 'no-creator-number'); end if;
  return jsonb_build_object('ok', true, 'number', v_n, 'name', cr.name, 'greeting', split_part(btrim(cr.name), ' ', 1),
    'client_id', cp.client_id,
    'campaign', case when cp.id is not null then coalesce(nullif(btrim(cp.title), ''), 'Your campaign') end,
    'code', cr.access_code, 'subject', coalesce(nullif(btrim(cp.title), ''), cr.name));
end $$;
revoke all on function public.wa_compose_prepare(text, uuid, text, uuid) from public, anon;
grant execute on function public.wa_compose_prepare(text, uuid, text, uuid) to authenticated;

create or replace function public.wa_sent(p_to_kind text, p_to uuid, p_purpose text, p_ref uuid, p_template text,
                                          p_lang text, p_category text, p_params jsonb, p_ok boolean,
                                          p_wa_id text, p_error text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me   public.team_members := public.ops_me();
  p    jsonb := public.wa_compose_prepare(p_to_kind, p_to, p_purpose, p_ref);
  v_word text;
begin
  if me.id is null then return jsonb_build_object('error', 'denied'); end if;
  if p ? 'error' then return p; end if;
  insert into public.wa_outbox (purpose, to_number, to_name, template, lang, params, ref_kind, ref_id, client_id, state,
                                wa_id, error, created_by, sent_at, tries, to_kind, to_id, category)
  values (p_purpose, p ->> 'number', p ->> 'name', coalesce(nullif(btrim(p_template), ''), ''), coalesce(nullif(btrim(p_lang), ''), 'en'),
          case when jsonb_typeof(p_params) = 'array' then p_params else '[]'::jsonb end,
          case p_purpose when 'report' then 'report' when 'creator' then 'option' when 'feedback' then 'client'
                         when 'approval' then p ->> 'ref_kind' end,
          case when p_purpose in ('report', 'creator', 'approval') then p_ref when p_purpose = 'feedback' then (p ->> 'client_id')::uuid end,
          (p ->> 'client_id')::uuid,
          case when p_ok then 'sent' else 'failed' end, left(p_wa_id, 200), left(p_error, 500), me.name,
          case when p_ok then now() end, 1, p_to_kind, p_to,
          nullif(lower(btrim(coalesce(p_category, ''))), ''));
  if p_ok then
    v_word := case p_purpose when 'report' then 'Report' when 'feedback' then 'Feedback request'
                             when 'creator' then 'Booking' when 'approval' then 'Approval reminder' else 'Message' end;
    insert into public.activity_log (actor, action, subject, detail)
    values (me.name, 'wa.sent', p ->> 'subject',
            case when p_purpose = 'creator' then (p ->> 'name') || ' · Booking sent on WhatsApp'
                 else v_word || ' sent on WhatsApp to ' || coalesce(nullif(btrim(p ->> 'name'), ''), 'the contact') end);
  end if;
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.wa_sent(text, uuid, text, uuid, text, text, text, jsonb, boolean, text, text) from public, anon;
grant execute on function public.wa_sent(text, uuid, text, uuid, text, text, text, jsonb, boolean, text, text) to authenticated;

create or replace function public.wa_template_set(p_purpose text, p_name text, p_lang text, p_params integer,
                                                  p_category text, p_active boolean)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me     public.team_members := public.ops_me();
  t      public.wa_templates;
  v_name text := btrim(coalesce(p_name, ''));
  v_lang text := btrim(coalesce(p_lang, ''));
  v_cat  text := lower(btrim(coalesce(p_category, '')));
  v_word text;
begin
  if me.id is null or not public.allowed('whatsapp', 'manage') then return jsonb_build_object('error', 'denied'); end if;
  select * into t from public.wa_templates x where x.purpose = p_purpose;
  if t.purpose is null then return jsonb_build_object('error', 'not-found'); end if;
  if (v_name !~ '^[a-z0-9_]+$' or length(v_name) > 512) and not (v_name = '' and not coalesce(p_active, false)) then
    return jsonb_build_object('error', 'bad-name');
  end if;
  if v_lang !~ '^[a-z]{2,3}(_[A-Z]{2})?$' then return jsonb_build_object('error', 'bad-lang'); end if;
  if p_params is null or p_params not between 0 and 5 then return jsonb_build_object('error', 'bad-params'); end if;
  if v_cat not in ('', 'utility', 'marketing', 'authentication') then return jsonb_build_object('error', 'bad-category'); end if;
  if t.name = v_name and t.lang = v_lang and t.params = p_params and t.category = v_cat and t.active = coalesce(p_active, false) then
    return jsonb_build_object('ok', true, 'same', true);
  end if;
  update public.wa_templates x
     set name = v_name, lang = v_lang, params = p_params, category = v_cat, active = coalesce(p_active, false),
         set_by = me.name, set_at = now()
   where x.purpose = p_purpose;
  v_word := case p_purpose when 'report' then 'Report to client' when 'feedback' then 'Feedback request'
                           when 'reminder' then 'Team reminders' when 'approval' then 'Approval reminder' else 'Creator updates' end;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'wa.template', 'WhatsApp',
          v_word || ': ' || coalesce(nullif(t.name, ''), 'not set') || ' (' || t.lang || ', ' || case when t.active then 'on' else 'off' end
          || ') → ' || coalesce(nullif(v_name, ''), 'not set') || ' (' || v_lang || ', ' || case when coalesce(p_active, false) then 'on' else 'off' end || ')');
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.wa_template_set(text, text, text, integer, text, boolean) from public, anon;
grant execute on function public.wa_template_set(text, text, text, integer, text, boolean) to authenticated;

-- END OF WHATSAPP APPROVAL REMINDER -------------------------------------------

-- ===========================================================================
-- BRAND ANALYSIS — an AI analysis of a client's brand on its Brand pane:
-- positioning, target audiences, SWOT, content and ad targeting, read from
-- the client's own record, reports, post results, Meta where linked, and
-- detailed web research on the brand and its competitors.
-- 2026-10-10. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/smsql.js compares the
-- two. Runs after SCRIPT WRITER, META CHECKS SWITCH, CLIENT BRIEF and the
-- WhatsApp approval reminder's settings.
--
-- WHAT CHANGED (the user, 2026-10-10: "provide a suggestions or inputs on the
-- deep analysis of this clients … brand part, target audiences, SWOTs,
-- advantages disadvantages, ads targetting etc."; "clients name just give
-- the clients brand name, perform detailed web research"; "anyone could run
-- it")
--   1. `brand_analyses` (RLS on, no policy, no grant): a client's analyses,
--      one row a run, numbered by client; read and written only through the
--      functions below. Not in CLIENT SCOPE's guarded list: a colleague at
--      Clients View runs one, so each function asks `client_seen` at View
--      itself.
--   2. `ai_analysis_claim(p_client)` / `ai_analysis_left()`: Clients View on
--      a client the colleague sees. Counted by the colleague a day, from
--      midnight MYT: `analysis` (3) a colleague's, `analysis_admin` (10) an
--      admin's, settings in `ai_draft_limits`; 0 stops it.
--   3. `brand_analysis_save(...)`: the `brand-analysis` function keeps what
--      it wrote as the caller, against the caller's own pending press; filed
--      `client.brand`.
--   4. `brand_analyses_list(p_client)`: every version, newest first (20 at
--      most), with who ran and who confirmed it. `brand_analysis_confirm(
--      p_id, p_on)`: the declaration that it was read and confirmed, and its
--      way back; filed `client.brand`.
--   5. `brand_analysis_brief(p_client)`: the latest confirmed analysis's
--      positioning, audiences and pillars in compact form, for Write with AI
--      on captions, scripts and reports (a colleague on the team who sees
--      the client).
--   6. `ai_drafts.web_searches` and `ai_draft_searches(p_id, p_n)`: the web
--      searches a press made, priced at `ai_price_search` (10, US$ a
--      thousand searches), a Business setting from a day like the token
--      prices; `app_settings_set` takes it.
--   7. `ai_draft_usage()` adds the analysis limits, each colleague's
--      analyses today, the searches and their cost; `ai_draft_set_limit`
--      names `analysis` and `analysis_admin`.
--
-- ROLLBACK
--   Run SCRIPT WRITER's ai_draft_usage and ai_draft_set_limit and WHATSAPP
--   APPROVAL REMINDER's app_settings_set again; then, in the SQL Editor, drop
--   the functions above and the table, delete the analysis rows from ai_drafts
--   and put the purpose check back to ('draft', 'check', 'caption',
--   'script'). The column and the setting's row may stay.
-- ===========================================================================

create table if not exists public.brand_analyses (
  id uuid primary key default gen_random_uuid(),
  client_id uuid not null references public.clients(id) on delete cascade,
  version integer not null,
  analysis jsonb not null,
  sources jsonb not null default '[]'::jsonb,
  basis jsonb not null default '{}'::jsonb,
  hypothesis boolean not null default false,
  model text,
  press_id uuid,
  created_by uuid references public.team_members(id) on delete set null,
  created_at timestamptz not null default now(),
  confirmed_by uuid references public.team_members(id) on delete set null,
  confirmed_at timestamptz,
  unique (client_id, version),
  constraint brand_analyses_shape check (jsonb_typeof(analysis) = 'object' and char_length(analysis::text) <= 60000
    and jsonb_typeof(sources) = 'array' and char_length(sources::text) <= 12000)
);
alter table public.brand_analyses enable row level security;
revoke all on table public.brand_analyses from public, anon, authenticated;

alter table public.ai_drafts add column if not exists web_searches integer;
alter table public.ai_drafts drop constraint if exists ai_drafts_purpose;
alter table public.ai_drafts add constraint ai_drafts_purpose check (purpose in ('draft', 'check', 'caption', 'script', 'analysis'));

insert into public.app_settings (key, from_date, value)
select 'ai_price_search', date '2026-10-10', 10
 where not exists (select 1 from public.app_settings s where s.key = 'ai_price_search');

-- An analysis: the colleague's own count a day, apart from every other AI use.
create or replace function public.ai_analysis_claim(p_client uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m public.team_members;
  since timestamptz := public.ai_draft_day();
  n_used integer;
  lim integer;
  new_id uuid;
begin
  if not public.allowed('clients', 'view') then return jsonb_build_object('error', 'denied'); end if;
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'denied'); end if;
  if not exists (select 1 from public.clients c where c.id = p_client) then return jsonb_build_object('error', 'not-found'); end if;
  if not public.client_seen(p_client, 'view') then return jsonb_build_object('error', 'client-scope'); end if;
  -- One count at a time, with the drafts, so the last analysis is taken once.
  perform pg_advisory_xact_lock(hashtext('ai_draft_claim'));
  lim := case when coalesce(m.is_admin, false) or m.role = 'admin'
              then public.ai_draft_limit('analysis_admin', 10) else public.ai_draft_limit('analysis', 3) end;
  if lim = 0 then return jsonb_build_object('error', 'ai-limit', 'scope', 'stopped', 'limit', 0); end if;
  select count(*) into n_used from public.ai_drafts d
   where d.team_member_id = m.id and d.purpose = 'analysis' and d.created_at >= since and d.outcome <> 'failed';
  if n_used >= lim then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'analysis', 'limit', lim, 'next', since + interval '1 day');
  end if;
  insert into public.ai_drafts (team_member_id, client_id, purpose)
  values (m.id, p_client, 'analysis') returning id into new_id;
  return jsonb_build_object('id', new_id, 'left', lim - n_used - 1, 'limit', lim);
end $$;

-- What Run analysis has left today, read without writing.
create or replace function public.ai_analysis_left()
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  m public.team_members;
  since timestamptz := public.ai_draft_day();
  lim integer;
  l_left integer;
begin
  if not public.allowed('clients', 'view') then return jsonb_build_object('error', 'denied'); end if;
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'denied'); end if;
  lim := case when coalesce(m.is_admin, false) or m.role = 'admin'
              then public.ai_draft_limit('analysis_admin', 10) else public.ai_draft_limit('analysis', 3) end;
  l_left := greatest(0, lim - (select count(*) from public.ai_drafts d
    where d.team_member_id = m.id and d.purpose = 'analysis' and d.created_at >= since and d.outcome <> 'failed')::integer);
  return jsonb_build_object('left', l_left, 'limit', lim, 'scope', case when lim = 0 then 'stopped' else 'analysis' end,
    'next', case when l_left > 0 or lim = 0 then null else since + interval '1 day' end);
end $$;

-- The web searches a press made, on the caller's own row, once.
create or replace function public.ai_draft_searches(p_id uuid, p_n integer)
returns void
language sql security definer set search_path = public as $$
  update public.ai_drafts d
     set web_searches = greatest(0, least(coalesce(p_n, 0), 100))
   where d.id = p_id and d.web_searches is null
     and d.team_member_id = (public.ops_me()).id
$$;

-- One version a row, with who ran and who confirmed it.
create or replace function public.brand_analysis_row(a public.brand_analyses)
returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object('id', a.id, 'client_id', a.client_id, 'version', a.version, 'analysis', a.analysis,
    'sources', a.sources, 'basis', a.basis, 'hypothesis', a.hypothesis, 'created_at', a.created_at,
    'by', (select t.name from public.team_members t where t.id = a.created_by),
    'confirmed_at', a.confirmed_at,
    'confirmed_by', (select t.name from public.team_members t where t.id = a.confirmed_by))
$$;
revoke all on function public.brand_analysis_row(public.brand_analyses) from public, anon, authenticated;

-- What the brand-analysis function wrote, kept against the caller's own
-- pending press for this client.
create or replace function public.brand_analysis_save(p_press uuid, p_analysis jsonb, p_sources jsonb,
                                                      p_basis jsonb, p_hypothesis boolean, p_model text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m public.team_members;
  d public.ai_drafts;
  c public.clients;
  a public.brand_analyses;
  v_no integer;
begin
  if not public.allowed('clients', 'view') then return jsonb_build_object('error', 'denied'); end if;
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'denied'); end if;
  select * into d from public.ai_drafts x where x.id = p_press for update;
  if d.id is null or d.team_member_id <> m.id or d.purpose <> 'analysis' or d.outcome <> 'pending'
     or exists (select 1 from public.brand_analyses x where x.press_id = d.id) then
    return jsonb_build_object('error', 'not-found');
  end if;
  select * into c from public.clients x where x.id = d.client_id;
  if c.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if not public.client_seen(c.id, 'view') then return jsonb_build_object('error', 'client-scope'); end if;
  if jsonb_typeof(p_analysis) is distinct from 'object' or char_length(p_analysis::text) > 60000 then
    return jsonb_build_object('error', 'bad-analysis');
  end if;
  perform pg_advisory_xact_lock(hashtext('brand_analysis:' || c.id::text));
  select coalesce(max(x.version), 0) + 1 into v_no from public.brand_analyses x where x.client_id = c.id;
  insert into public.brand_analyses (client_id, version, analysis, sources, basis, hypothesis, model, press_id, created_by)
  values (c.id, v_no, p_analysis,
          case when jsonb_typeof(p_sources) = 'array' and char_length(p_sources::text) <= 12000 then p_sources else '[]'::jsonb end,
          case when jsonb_typeof(p_basis) = 'object' then p_basis else '{}'::jsonb end,
          coalesce(p_hypothesis, false), left(nullif(btrim(coalesce(p_model, '')), ''), 80), d.id, m.id)
  returning * into a;
  insert into public.activity_log (actor, action, subject, detail)
  values (coalesce(m.name, m.email), 'client.brand', c.name,
          'Brand analysis: version ' || v_no || ' run with AI' ||
          case when coalesce(p_hypothesis, false) then ', a starting hypothesis to test' else '' end);
  return public.brand_analysis_row(a);
end $$;

create or replace function public.brand_analyses_list(p_client uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.allowed('clients', 'view') then return jsonb_build_object('error', 'denied'); end if;
  if not public.client_seen(p_client, 'view') then return jsonb_build_object('error', 'client-scope'); end if;
  return jsonb_build_object('versions', coalesce((select jsonb_agg(public.brand_analysis_row(x) order by x.version desc)
    from (select * from public.brand_analyses a where a.client_id = p_client order by a.version desc limit 20) x), '[]'::jsonb));
end $$;

-- The declaration that a colleague read the analysis and confirms it; with
-- p_on false, its way back.
create or replace function public.brand_analysis_confirm(p_id uuid, p_on boolean default true)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m public.team_members;
  a public.brand_analyses;
  c public.clients;
begin
  if not public.allowed('clients', 'view') then return jsonb_build_object('error', 'denied'); end if;
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'denied'); end if;
  select * into a from public.brand_analyses x where x.id = p_id for update;
  if a.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if not public.client_seen(a.client_id, 'view') then return jsonb_build_object('error', 'client-scope'); end if;
  select * into c from public.clients x where x.id = a.client_id;
  if coalesce(p_on, true) = (a.confirmed_at is not null) then return public.brand_analysis_row(a); end if;
  update public.brand_analyses x
     set confirmed_at = case when coalesce(p_on, true) then now() end,
         confirmed_by = case when coalesce(p_on, true) then m.id end
   where x.id = p_id returning * into a;
  insert into public.activity_log (actor, action, subject, detail)
  values (coalesce(m.name, m.email), 'client.brand', c.name,
          'Brand analysis: version ' || a.version ||
          case when coalesce(p_on, true) then ' written with AI, read and confirmed' else ' confirmation withdrawn' end);
  return public.brand_analysis_row(a);
end $$;

-- For Write with AI: the latest confirmed analysis, in compact form.
create or replace function public.brand_analysis_brief(p_client uuid)
returns jsonb
language sql stable security definer set search_path = public as $$
  select case when public.is_team() and public.client_seen(p_client, 'view') then (
    select jsonb_strip_nulls(jsonb_build_object(
      'positioning', a.analysis -> 'positioning',
      'audiences', (select jsonb_agg(jsonb_build_object('name', s ->> 'name', 'pains', s ->> 'pains', 'motivations', s ->> 'motivations'))
                      from jsonb_array_elements(case when jsonb_typeof(a.analysis -> 'audiences') = 'array' then a.analysis -> 'audiences' else '[]'::jsonb end) s),
      'pillars', a.analysis #> '{content,pillars}',
      'hypothesis', case when a.hypothesis then true end))
      from public.brand_analyses a
     where a.client_id = p_client and a.confirmed_at is not null
     order by a.version desc limit 1) end
$$;

revoke all on function public.ai_analysis_claim(uuid) from public, anon, authenticated;
revoke all on function public.ai_analysis_left() from public, anon, authenticated;
revoke all on function public.ai_draft_searches(uuid, integer) from public, anon, authenticated;
