create or replace function public.ai_draft_usage()
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_day timestamptz := public.ai_draft_day();
  v_month timestamptz := now() - interval '30 days';
  -- This calendar month in Malaysia, for what the calls cost.
  v_cal timestamptz := date_trunc('month', now() at time zone 'Asia/Kuala_Lumpur') at time zone 'Asia/Kuala_Lumpur';
  v_today date := (now() at time zone 'Asia/Kuala_Lumpur')::date;
begin
  if not public.ops_granted('reports.ai', 'work') then return jsonb_build_object('error', 'denied'); end if;
  return jsonb_build_object(
    'person', public.ai_draft_limit('person', 10),
    'admin', public.ai_draft_limit('admin', 20),
    'report', public.ai_draft_limit('report', 1),
    'report_admin', public.ai_draft_limit('report_admin', 5),
    'check', public.ai_draft_limit('check', 1),
    'check_admin', public.ai_draft_limit('check_admin', 5),
    'caption', public.ai_draft_limit('caption', 20),
    'caption_admin', public.ai_draft_limit('caption_admin', 40),
    'script', public.ai_draft_limit('script', 10),
    'script_admin', public.ai_draft_limit('script_admin', 20),
    'analysis', public.ai_draft_limit('analysis', 3),
    'analysis_admin', public.ai_draft_limit('analysis_admin', 10),
    'cost', (select jsonb_build_object(
        'since', v_cal,
        'price_in', public.app_setting('ai_price_in', v_today),
        'price_out', public.app_setting('ai_price_out', v_today),
        'price_search', coalesce(public.app_setting('ai_price_search', v_today), 10),
        'uses', count(*),
        'untracked', count(*) filter (where c.input_tokens is null),
        'input', coalesce(sum(c.input_tokens), 0),
        'output', coalesce(sum(c.output_tokens), 0),
        'searches', coalesce(sum(c.web_searches), 0),
        'usd', round(coalesce(sum(c.usd), 0), 2),
        'by', coalesce((select jsonb_object_agg(p.purpose, p.x) from (
            select c2.purpose, jsonb_build_object('uses', count(*), 'input', coalesce(sum(c2.input_tokens), 0),
                     'output', coalesce(sum(c2.output_tokens), 0), 'searches', coalesce(sum(c2.web_searches), 0),
                     'usd', round(coalesce(sum(c2.usd), 0), 2)) as x
              from (select d.purpose, d.input_tokens, d.output_tokens, d.web_searches,
                           (coalesce(d.input_tokens, 0) * public.app_setting('ai_price_in', (d.created_at at time zone 'Asia/Kuala_Lumpur')::date)
                          + coalesce(d.output_tokens, 0) * public.app_setting('ai_price_out', (d.created_at at time zone 'Asia/Kuala_Lumpur')::date)) / 1000000.0
                          + coalesce(d.web_searches, 0) * coalesce(public.app_setting('ai_price_search', (d.created_at at time zone 'Asia/Kuala_Lumpur')::date), 10) / 1000.0 as usd
                      from public.ai_drafts d where d.created_at >= v_cal and (d.outcome <> 'failed' or d.input_tokens is not null)) c2
             group by c2.purpose) p), '{}'::jsonb))
      from (select d.input_tokens, d.output_tokens, d.web_searches,
                   (coalesce(d.input_tokens, 0) * public.app_setting('ai_price_in', (d.created_at at time zone 'Asia/Kuala_Lumpur')::date)
                  + coalesce(d.output_tokens, 0) * public.app_setting('ai_price_out', (d.created_at at time zone 'Asia/Kuala_Lumpur')::date)) / 1000000.0
                  + coalesce(d.web_searches, 0) * coalesce(public.app_setting('ai_price_search', (d.created_at at time zone 'Asia/Kuala_Lumpur')::date), 10) / 1000.0 as usd
              from public.ai_drafts d where d.created_at >= v_cal and (d.outcome <> 'failed' or d.input_tokens is not null)) c),
    'resets_at', v_day + interval '1 day',
    'people', coalesce((select jsonb_agg(s.x order by s.x ->> 'name') from (
      select jsonb_build_object(
        'id', t.id, 'name', t.name, 'code', t.staff_code, 'group', g.name, 'group_slug', t.role,
        'admin', coalesce(t.is_admin, false) or t.role = 'admin',
        'day', (select count(*) from public.ai_drafts d where d.team_member_id = t.id and d.created_at >= v_day and d.outcome <> 'failed' and d.purpose in ('draft', 'check')),
        'captions', (select count(*) from public.ai_drafts d where d.team_member_id = t.id and d.created_at >= v_day and d.outcome <> 'failed' and d.purpose = 'caption'),
        'caption_cap', case when coalesce(t.is_admin, false) or t.role = 'admin'
                            then public.ai_draft_limit('caption_admin', 40) else public.ai_draft_limit('caption', 20) end,
        'scripts', (select count(*) from public.ai_drafts d where d.team_member_id = t.id and d.created_at >= v_day and d.outcome <> 'failed' and d.purpose = 'script'),
        'script_cap', case when coalesce(t.is_admin, false) or t.role = 'admin'
                           then public.ai_draft_limit('script_admin', 20) else public.ai_draft_limit('script', 10) end,
        'analyses', (select count(*) from public.ai_drafts d where d.team_member_id = t.id and d.created_at >= v_day and d.outcome <> 'failed' and d.purpose = 'analysis'),
        'analysis_cap', case when coalesce(t.is_admin, false) or t.role = 'admin'
                             then public.ai_draft_limit('analysis_admin', 10) else public.ai_draft_limit('analysis', 3) end,
        'month', (select count(*) from public.ai_drafts d where d.team_member_id = t.id and d.created_at > v_month and d.outcome <> 'failed'),
        'limit', (select l.daily from public.ai_draft_limits l where l.scope = t.id::text),
        'cap', public.ai_day_cap(t)) as x
        from public.team_members t
        left join public.team_roles g on g.slug = t.role
       where t.active
         and (coalesce(t.is_admin, false) or t.role = 'admin'
              or public.level_rank(coalesce(t.access ->> 'reports', 'none')) >= public.level_rank('work')
              or public.level_rank(coalesce(t.access ->> 'review', 'none')) >= public.level_rank('work')
              or public.level_rank(coalesce(t.access ->> 'scripts', 'none')) >= public.level_rank('work')
              or exists (select 1 from public.ai_drafts d where d.team_member_id = t.id and d.created_at > v_month))
    ) s), '[]'::jsonb));
end $$;
revoke all on function public.ai_draft_usage() from public, anon, authenticated;
grant execute on function public.ai_draft_usage() to authenticated;

create or replace function public.ai_draft_set_limit(p_scope text, p_daily integer)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_who text;
  v_name text;
  v_was integer;
  v_def integer;
  v_unit text := ' a day';
  v_scope text := btrim(coalesce(p_scope, ''));
  t public.team_members;
begin
  if not public.ops_granted('reports.ai', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if p_daily is not null and (p_daily < 0 or p_daily > 500) then
    return jsonb_build_object('error', 'bad-limit');
  end if;
  if v_scope = 'person' then
    v_name := 'Each colleague'; v_def := 10;
  elsif v_scope = 'admin' then
    v_name := 'Each admin'; v_def := 20;
  elsif v_scope = 'report' then
    v_name := 'Drafts per report, each colleague'; v_def := 1;
  elsif v_scope = 'report_admin' then
    v_name := 'Drafts per report, each admin'; v_def := 5;
  elsif v_scope = 'check' then
    v_name := 'Figures checks per report, each colleague'; v_def := 1;
  elsif v_scope = 'check_admin' then
    v_name := 'Figures checks per report, each admin'; v_def := 5;
  elsif v_scope = 'caption' then
    v_name := 'Captions, each colleague'; v_def := 20;
  elsif v_scope = 'caption_admin' then
    v_name := 'Captions, each admin'; v_def := 40;
  elsif v_scope = 'script' then
    v_name := 'Scripts, each colleague'; v_def := 10;
  elsif v_scope = 'script_admin' then
    v_name := 'Scripts, each admin'; v_def := 20;
  elsif v_scope = 'analysis' then
    v_name := 'Brand analyses, each colleague'; v_def := 3;
  elsif v_scope = 'analysis_admin' then
    v_name := 'Brand analyses, each admin'; v_def := 10;
  elsif v_scope = 'team' then
    return jsonb_build_object('error', 'bad-scope');
  else
    select * into t from public.team_members x where x.id::text = v_scope;
    if t.id is null then return jsonb_build_object('error', 'not-found'); end if;
    v_name := t.name;
    v_def := case when coalesce(t.is_admin, false) or t.role = 'admin'
                  then public.ai_draft_limit('admin', 20) else public.ai_draft_limit('person', 10) end;
  end if;
  select l.daily into v_was from public.ai_draft_limits l where l.scope = v_scope;
  if v_was is not distinct from p_daily then return jsonb_build_object('ok', true, 'same', true); end if;
  select coalesce(x.name, x.email) into v_who from public.team_members x
   where lower(x.email) = lower(auth.jwt() ->> 'email') and x.active limit 1;
  insert into public.ai_draft_limits (scope, daily, set_by, set_at)
  values (v_scope, p_daily, v_who, now())
  on conflict (scope) do update set daily = excluded.daily, set_by = excluded.set_by, set_at = excluded.set_at;
  insert into public.activity_log (actor, action, subject, detail)
  values (coalesce(v_who, 'admin'), 'team.changed', 'AI',
          v_name || ': ' ||
          case when v_was is null then 'standard, ' || v_def || v_unit when v_was = 0 then 'stopped' else v_was || v_unit end ||
          ' → ' ||
          case when p_daily is null then 'standard, ' || v_def || v_unit when p_daily = 0 then 'stopped' else p_daily || v_unit end);
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.ai_draft_set_limit(text, integer) from public, anon, authenticated;
grant execute on function public.ai_draft_set_limit(text, integer) to authenticated;

create or replace function public.app_settings_set(p_from date, p_values jsonb)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me public.team_members; v_k text; v_v numeric; v_was numeric; v_name text; v_unit text;
  v_today date := (now() at time zone 'Asia/Kuala_Lumpur')::date;
  v_keys constant text[] := array['lead_followup_hours', 'proposal_followup_days', 'sst_pct',
    'term_1_3', 'term_4_5', 'term_6_11', 'term_12_23', 'term_24', 'report_due_days', 'revision_due_days',
    'ai_price_in', 'ai_price_out', 'meta_checks', 'approval_reminder_days', 'ai_price_search'];
  v_moved text[] := '{}';
begin
  if not public.ops_granted('team.settings', 'work') then return jsonb_build_object('error', 'denied'); end if;
  v_me := public.ops_me();
  if p_from is null or p_from < v_today then return jsonb_build_object('error', 'past', 'today', v_today); end if;
  if jsonb_typeof(p_values) is distinct from 'object' then return jsonb_build_object('error', 'bad-value'); end if;
  for v_k in select jsonb_object_keys(p_values) loop
    if not (v_k = any(v_keys)) or jsonb_typeof(p_values -> v_k) <> 'number' then
      return jsonb_build_object('error', 'bad-value', 'key', v_k);
    end if;
    v_v := (p_values ->> v_k)::numeric;
    if round(v_v, 2) <> v_v
       or (v_k = 'lead_followup_hours' and (v_v < 1 or v_v > 720 or v_v <> trunc(v_v)))
       or (v_k = 'proposal_followup_days' and (v_v < 1 or v_v > 365 or v_v <> trunc(v_v)))
       or (v_k = 'report_due_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'revision_due_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'approval_reminder_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'sst_pct' and (v_v < 0 or v_v > 100))
       or (v_k like 'term_%' and (v_v < -100 or v_v > 100))
       or (v_k like 'ai_price_%' and (v_v < 0 or v_v > 1000))
       or (v_k = 'meta_checks' and v_v not in (0, 1)) then
      return jsonb_build_object('error', 'bad-value', 'key', v_k);
    end if;
  end loop;
  for v_k in select jsonb_object_keys(p_values) loop
    v_v := (p_values ->> v_k)::numeric;
    v_was := public.app_setting(v_k, p_from);
    if v_was is distinct from v_v then
      insert into public.app_settings (key, from_date, value, set_by, set_at)
      values (v_k, p_from, v_v, v_me.id, now())
      on conflict (key, from_date) do update set value = excluded.value, set_by = excluded.set_by, set_at = now();
      v_name := case v_k when 'lead_followup_hours' then 'A lead waits' when 'proposal_followup_days' then 'A proposal waits'
        when 'sst_pct' then 'SST' when 'term_1_3' then '1 to 3 months' when 'term_4_5' then '4 and 5 months'
        when 'term_6_11' then '6 to 11 months' when 'term_12_23' then '12 to 23 months' when 'term_24' then '24 months and more'
        when 'revision_due_days' then 'Revision due' when 'ai_price_in' then 'AI input, a million tokens'
        when 'ai_price_out' then 'AI output, a million tokens' when 'ai_price_search' then 'AI web searches, a thousand' when 'meta_checks' then 'Meta checks'
        when 'approval_reminder_days' then 'Approval reminder' else 'Report due' end;
      v_unit := case when v_k = 'lead_followup_hours' then ' hours' when v_k in ('proposal_followup_days', 'report_due_days', 'revision_due_days', 'approval_reminder_days') then ' days'
        else '%' end;
      insert into public.activity_log (actor, action, subject, detail)
      values (coalesce(v_me.name, 'admin'), 'team.changed', 'Settings',
              v_name || ': ' || case when v_k = 'meta_checks' then
                case when v_was = 1 then 'On' else 'Off' end || ' → ' || case when v_v = 1 then 'On' else 'Off' end ||
                ' · from ' || public.register_day(p_from) else '' end ||
              case when v_k = 'meta_checks' then '' else case when v_k like 'ai_price_%' then 'US$' else '' end ||
              trim(to_char(v_was, 'FM999999990.99'), '.') || case when v_k like 'ai_price_%' then '' else v_unit end || ' → ' ||
              case when v_k like 'ai_price_%' then 'US$' else '' end ||
              trim(to_char(v_v, 'FM999999990.99'), '.') || case when v_k like 'ai_price_%' then '' else v_unit end ||
              ' · from ' || public.register_day(p_from) end);
      v_moved := v_moved || v_k;
    end if;
  end loop;
  return public.app_settings_read() || jsonb_build_object('changed', to_jsonb(v_moved));
end $$;
revoke all on function public.app_settings_set(date, jsonb) from public, anon;

-- END OF BRAND ANALYSIS -------------------------------------------------------

-- ===========================================================================
-- REACH ALLOWANCE — the Report audit reads an ad's or an account's Reach as
-- matching Meta's within a small allowance, because Meta itself revises
-- Reach (an estimate of the people reached) while a period runs; every other
-- figure stays exact.
-- 2026-10-10. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/smsql.js compares the
-- two. Runs after BRAND ANALYSIS, whose settings it keeps.
--
-- WHAT CHANGED (the user, 2026-10-10, from a report imported from Meta and
-- audited 27 seconds later, two ads' Reach moved by 12 and 9 people while
-- spend, impressions and results held: "Small allowance")
--   1. `reach_allowance_pct` is a Business setting (0 to 5, two decimals,
--      from a day), seeded 0.5 from the start. `app_settings_set` takes it,
--      filed "Reach allowance: 0.5% → 1% · from …".
--   2. The page compares (js/reports.js `metaCompare`): a Reach within the
--      allowance of Meta's is a match and holds nothing; the card says how
--      many were within it. Nothing else in the database changes: a match is
--      filed as before.
--
-- ROLLBACK
--   Run app_settings_set from BRAND ANALYSIS again; the
--   setting's row may stay (the page then compares Reach exactly where it
--   reads none).
-- ===========================================================================

insert into public.app_settings (key, from_date, value)
select 'reach_allowance_pct', date '2023-08-14', 0.5
 where not exists (select 1 from public.app_settings s where s.key = 'reach_allowance_pct');

create or replace function public.app_settings_set(p_from date, p_values jsonb)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me public.team_members; v_k text; v_v numeric; v_was numeric; v_name text; v_unit text;
  v_today date := (now() at time zone 'Asia/Kuala_Lumpur')::date;
  v_keys constant text[] := array['lead_followup_hours', 'proposal_followup_days', 'sst_pct',
    'term_1_3', 'term_4_5', 'term_6_11', 'term_12_23', 'term_24', 'report_due_days', 'revision_due_days',
    'ai_price_in', 'ai_price_out', 'meta_checks', 'approval_reminder_days', 'ai_price_search',
    'reach_allowance_pct'];
  v_moved text[] := '{}';
begin
  if not public.ops_granted('team.settings', 'work') then return jsonb_build_object('error', 'denied'); end if;
  v_me := public.ops_me();
  if p_from is null or p_from < v_today then return jsonb_build_object('error', 'past', 'today', v_today); end if;
  if jsonb_typeof(p_values) is distinct from 'object' then return jsonb_build_object('error', 'bad-value'); end if;
  for v_k in select jsonb_object_keys(p_values) loop
    if not (v_k = any(v_keys)) or jsonb_typeof(p_values -> v_k) <> 'number' then
      return jsonb_build_object('error', 'bad-value', 'key', v_k);
    end if;
    v_v := (p_values ->> v_k)::numeric;
    if round(v_v, 2) <> v_v
       or (v_k = 'lead_followup_hours' and (v_v < 1 or v_v > 720 or v_v <> trunc(v_v)))
       or (v_k = 'proposal_followup_days' and (v_v < 1 or v_v > 365 or v_v <> trunc(v_v)))
       or (v_k = 'report_due_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'revision_due_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'approval_reminder_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'sst_pct' and (v_v < 0 or v_v > 100))
       or (v_k like 'term_%' and (v_v < -100 or v_v > 100))
       or (v_k like 'ai_price_%' and (v_v < 0 or v_v > 1000))
       or (v_k = 'meta_checks' and v_v not in (0, 1))
       or (v_k = 'reach_allowance_pct' and (v_v < 0 or v_v > 5)) then
      return jsonb_build_object('error', 'bad-value', 'key', v_k);
    end if;
  end loop;
  for v_k in select jsonb_object_keys(p_values) loop
    v_v := (p_values ->> v_k)::numeric;
    v_was := public.app_setting(v_k, p_from);
    if v_was is distinct from v_v then
      insert into public.app_settings (key, from_date, value, set_by, set_at)
      values (v_k, p_from, v_v, v_me.id, now())
      on conflict (key, from_date) do update set value = excluded.value, set_by = excluded.set_by, set_at = now();
      v_name := case v_k when 'lead_followup_hours' then 'A lead waits' when 'proposal_followup_days' then 'A proposal waits'
        when 'sst_pct' then 'SST' when 'term_1_3' then '1 to 3 months' when 'term_4_5' then '4 and 5 months'
        when 'term_6_11' then '6 to 11 months' when 'term_12_23' then '12 to 23 months' when 'term_24' then '24 months and more'
        when 'revision_due_days' then 'Revision due' when 'ai_price_in' then 'AI input, a million tokens'
        when 'ai_price_out' then 'AI output, a million tokens' when 'ai_price_search' then 'AI web searches, a thousand' when 'meta_checks' then 'Meta checks'
        when 'approval_reminder_days' then 'Approval reminder' when 'reach_allowance_pct' then 'Reach allowance'
        else 'Report due' end;
      v_unit := case when v_k = 'lead_followup_hours' then ' hours' when v_k in ('proposal_followup_days', 'report_due_days', 'revision_due_days', 'approval_reminder_days') then ' days'
        else '%' end;
      insert into public.activity_log (actor, action, subject, detail)
      values (coalesce(v_me.name, 'admin'), 'team.changed', 'Settings',
              v_name || ': ' || case when v_k = 'meta_checks' then
                case when v_was = 1 then 'On' else 'Off' end || ' → ' || case when v_v = 1 then 'On' else 'Off' end ||
                ' · from ' || public.register_day(p_from) else '' end ||
              case when v_k = 'meta_checks' then '' else case when v_k like 'ai_price_%' then 'US$' else '' end ||
              trim(to_char(v_was, 'FM999999990.99'), '.') || case when v_k like 'ai_price_%' then '' else v_unit end || ' → ' ||
              case when v_k like 'ai_price_%' then 'US$' else '' end ||
              trim(to_char(v_v, 'FM999999990.99'), '.') || case when v_k like 'ai_price_%' then '' else v_unit end ||
              ' · from ' || public.register_day(p_from) end);
      v_moved := v_moved || v_k;
    end if;
  end loop;
  return public.app_settings_read() || jsonb_build_object('changed', to_jsonb(v_moved));
end $$;
revoke all on function public.app_settings_set(date, jsonb) from public, anon;

-- END OF REACH ALLOWANCE ------------------------------------------------------

-- ===========================================================================
-- SETS BY MONTH — a content set names its content month (2026-10-10, the
-- user: a client's sets grow without end; they are listed by month, as
-- Video Scripts and Reports are).
-- 2026-10-10. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/smsql.js compares the
-- two.
--
-- WHAT CHANGED
--   `batches.period` (YYYY-MM, the content month; empty is Ad hoc). It is
--   added once and, that first time only, each set takes the month it was
--   made in (Malaysia time), so a second run never undoes a set the team
--   has since made Ad hoc. A new set takes this month on the page; the set's
--   menu changes it (`set.month`, from and to).
--
-- ROLLBACK
--   Remove the constraint batches_period_shape and the column period.
-- ===========================================================================

do $$
begin
  if not exists (select 1 from information_schema.columns
                 where table_schema = 'public' and table_name = 'batches' and column_name = 'period') then
    alter table public.batches add column period text;
    update public.batches set period = to_char(created_at at time zone 'Asia/Kuala_Lumpur', 'YYYY-MM');
  end if;
end $$;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'batches_period_shape') then
    alter table public.batches add constraint batches_period_shape
      check (period is null or period ~ '^[0-9]{4}-(0[1-9]|1[0-2])$');
  end if;
end $$;

-- END OF SETS BY MONTH ---------------------------------------------------------

-- ===========================================================================
-- SETS BY MONTH ACTIVITY MAP — a content set's month changed files under
-- Content Review.
-- 2026-10-10. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/smsql.js compares the
-- two. Runs after WHATSAPP ACTIVITY MAP and restates it whole, with
-- `set.month` added beside the set's other tags, so running this file alone
-- also files WhatsApp's tags. The map names tags such as `set.deleted`, which
-- the Supabase connector holds for a confirmation it cannot show: hand it to
-- the SQL Editor as its own run.
--
-- ROLLBACK
--   Restate the map from 2026-10-10-whatsapp-activity-map.sql.
-- ===========================================================================

create or replace function public.activity_section(p_action text)
returns text
language sql immutable parallel safe as $$
  select case
    when action in ('campaign.bulk', 'campaign.closed', 'campaign.confirmed',
                    'campaign.created', 'campaign.dates', 'campaign.deleted', 'campaign.edited',
                    'campaign.file_added', 'campaign.qc',
                    'campaign.invoice', 'campaign.invoice_file',
                    'campaign.invoice_removed', 'campaign.keyed', 'campaign.locked',
                    'campaign.opened', 'campaign.rate', 'campaign.rated',
                    'campaign.reinstated', 'campaign.replaced', 'campaign.results', 'campaign.review',
                    'campaign.stage', 'campaign.submitted', 'campaign.task_linked',
                    'campaign.task_unlinked', 'campaign.unbooked',
                    'campaign.unkeyed', 'campaign.whatsapp', 'campaign.withdrawn', 'creator.added',
                    'creator.code', 'creator.links', 'creator.links_restored',
                    'creator.links_self', 'creator.off', 'creator.on', 'creator.removed',
                    'creator.updated') then 'campaigns'
    when action in ('client.action_done', 'client.action_reopened', 'client.added',
                    'client.billing', 'client.brand', 'client.deleted', 'client.edited',
                    'client.review_on', 'client.service', 'client.service_changed',
                    'client.service_removed', 'client.service_restored', 'client.stage', 'client.touch',
                    'client.touch_deleted', 'client.touch_edited', 'client.touch_removed',
                    'client.touch_restored', 'contact.added', 'contact.deleted',
                    'contact.edited', 'contact.portal_invite', 'contact.portal_off',
                    'contact.portal_on', 'contact.primary', 'contact.removed',
                    'contact.restored',
                    'request.changed', 'request.raised',
                    'request.reinstated', 'request.replied', 'request.withdrawn',
                    'service.override') then 'clients'
    when action in ('wa.sent', 'wa.template') then 'whatsapp'
    when action in ('report.ai_drafted', 'report.ai_failed', 'report.audited', 'report.confirmed',
                    'report.created', 'report.deleted', 'report.published',
                    'report.reassigned', 'report.returned', 'report.revised', 'report.saved',
                    'report.submitted', 'report.unpublished') then 'reports'
    when action in ('qr.created', 'qr.restored', 'qr.revoked', 'shortlink.created',
                    'shortlink.deleted', 'shortlink.imported', 'shortlink.updated') then 'links'
    when action in ('ops.deleted', 'ops.month_deleted', 'ops.numbering') then 'ops'
    when action in ('document.deleted', 'document.issued', 'document.reissued',
                    'document.restored', 'document.signed', 'document.superseded',
                    'document.unsigned', 'document.verified', 'document.voided',
                    'register.added', 'register.edited') then 'register'
    when action in ('client.drive', 'client.handles', 'client.profile',
                    'client.removed', 'drive.imported', 'link.reset', 'post.added',
                    'post.deleted', 'post.edited', 'reapproval.requested',
                    'review.approved', 'review.changes', 'review.removed',
                    'review.unconfirmed',
                    'set.created', 'set.deleted', 'set.month', 'set.published', 'set.renamed',
                    'set.task_linked', 'set.task_unlinked',
                    'set.withdrawn') then 'review'
    when action in ('script.approved', 'script.changes', 'script.created', 'script.deleted',
                    'script.link', 'script.saved', 'script.shared', 'script.shot',
                    'script.unshared') then 'scripts'
    when action in ('handbook.added', 'handbook.archived', 'handbook.deleted',
                    'handbook.edited', 'handbook.restored', 'handbook.version') then 'handbook'
    when action in ('service.added', 'service.changed', 'service.deleted',
                    'service.off', 'service.on') then 'services'
    when action in ('team.added', 'team.changed', 'team.edited', 'team.group_added',
                    'team.group_changed', 'team.group_removed', 'team.invited') then 'team'
    else 'other'
  end
  from (select p_action as action) t
$$;
grant execute on function public.activity_section(text) to authenticated;

-- END OF SETS BY MONTH ACTIVITY MAP --------------------------------------------

-- ===========================================================================
-- RAIL ORDER — a colleague arranges the console's sections once, and the web
-- rail and the phone tab bar both follow (2026-10-10, the user: "Add in the
-- phone tab bar rearrange"; "mobile tab and web … both sync edits").
-- 2026-10-10. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/smsql.js compares the
-- two.
--
-- WHAT CHANGED
--   1. `rail_orders` keeps one row a colleague: the section keys in the order
--      they chose, an empty list meaning the standard order. RLS on, no
--      policy, no grant: it is read and written only through the two
--      functions below, each the caller's own row.
--   2. `rail_order_mine()` answers the caller's list (empty where none is
--      kept).
--   3. `rail_order_set(p_sections)` keeps it: every key one of the rail's
--      sections (the Overview stays first and is not ordered), none twice
--      (`bad-order`); an empty list goes back to the standard order. A
--      personal choice, so nothing is filed in the Activity record.
--   The page orders each of the rail's two groups (Work, Internal) by the
--   list, a section it does not name after in the standard order, and the
--   phone tab bar takes the first sections of the rail as it then reads.
--
-- ROLLBACK
--   Pages first (the rail returns to the standard order), then remove the
--   two functions and the table.
-- ===========================================================================

create table if not exists public.rail_orders (
  member_id  uuid primary key references public.team_members(id),
  sections   text[] not null default '{}',
  updated_at timestamptz not null default now()
);
alter table public.rail_orders enable row level security;
revoke all on public.rail_orders from public, anon, authenticated;

create or replace function public.rail_order_mine()
returns jsonb
language plpgsql security definer stable set search_path = public as $$
declare
  me public.team_members;
begin
  me := public.ops_me();
  if me.id is null then return jsonb_build_object('error', 'denied'); end if;
  return jsonb_build_object('sections', coalesce((select to_jsonb(o.sections) from public.rail_orders o where o.member_id = me.id), '[]'::jsonb));
end $$;
grant execute on function public.rail_order_mine() to authenticated;

create or replace function public.rail_order_set(p_sections text[])
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members;
  v_list text[] := coalesce(p_sections, '{}');
  v_known constant text[] := array['work', 'clients', 'review', 'scripts', 'campaigns', 'reports', 'whatsapp',
    'register', 'links', 'services', 'team', 'handbook'];
begin
  me := public.ops_me();
  if me.id is null then return jsonb_build_object('error', 'denied'); end if;
  if exists (select 1 from unnest(v_list) k where k is null or not (k = any(v_known)))
     or (select count(distinct k) from unnest(v_list) k) <> cardinality(v_list) then
    return jsonb_build_object('error', 'bad-order');
  end if;
  insert into public.rail_orders (member_id, sections, updated_at) values (me.id, v_list, now())
  on conflict (member_id) do update set sections = excluded.sections, updated_at = now();
  return jsonb_build_object('sections', to_jsonb(v_list));
end $$;
grant execute on function public.rail_order_set(text[]) to authenticated;

-- END OF RAIL ORDER ------------------------------------------------------------

-- ===========================================================================
-- SERVICE CONFIRM GUARD — a service line becomes Confirmed only through a
-- verified signed letter or the admin's reasoned override (audit S1,
-- 2026-10-10). 2026-10-10. Safe to run twice. Rollback at the foot. Mirrored
-- byte for byte in supabase/schema.sql under the same banner;
-- tests/smsql.js compares the two.
--
-- WHAT CHANGED
--   The service sheet offered Confirmed and wrote it straight to the table,
--   while the line's own control refused it. `client_services_confirm_guard`
--   refuses a row inserted as Confirmed, or moved into Confirmed, by a page
--   (the `authenticated` and `anon` roles): `verify_letter` and
--   `override_service_state` run as their owner and pass. A line already
--   Confirmed is untouched, and its other fields stay editable as before.
--
-- ROLLBACK
--   Pages first is not needed (the page no longer offers Confirmed); remove
--   the trigger and its function.
-- ===========================================================================

create or replace function public.client_services_confirm_guard()
returns trigger
language plpgsql
set search_path = public as $$
begin
  if new.state = 'confirmed'
     and (tg_op = 'INSERT' or old.state is distinct from 'confirmed')
     and current_user in ('authenticated', 'anon') then
    raise exception 'confirm-needs-letter' using errcode = 'P0001',
      hint = 'A service is confirmed when its signed letter is verified.';
  end if;
  return new;
end $$;
revoke all on function public.client_services_confirm_guard() from public, anon, authenticated;

create or replace trigger client_services_confirm_guard
  before insert or update of state on public.client_services
  for each row execute function public.client_services_confirm_guard();

-- END OF SERVICE CONFIRM GUARD -------------------------------------------------

-- ===========================================================================
-- NOTICE DELETE — a withdrawn notice can be deleted for good (the user,
-- 2026-10-10: "why notices cannot be deleted?").
-- 2026-10-10. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/smsql.js compares the
-- two. It holds the word the connector stops on: run it in the SQL Editor.
--
-- WHAT CHANGED
--   `team_notice_delete(p_id)` (Team: Notices, as Withdraw) removes a
--   withdrawn notice and every colleague's copy of it from the bells, refused
--   `live` until it is withdrawn (Withdraw first, so nothing leaves a bell
--   without the team seeing it go), `not-found` once gone. A push already on
--   a phone stays there. Filed `team.changed` under subject Notices. There is
--   no restore.
--
-- ROLLBACK
--   Pages first (the ⋯ is drawn only on a withdrawn notice and names a
--   missing function "This needs a database update."), then remove the
--   function in the SQL Editor. A notice already deleted is gone.
-- ===========================================================================

create or replace function public.team_notice_delete(p_id uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  v public.team_notices;
  n int;
begin
  if me.id is null or not public.ops_granted('team.notice', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into v from public.team_notices tn where tn.id = p_id for update;
  if v.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if v.withdrawn_at is null then return jsonb_build_object('error', 'live'); end if;
  delete from public.ops_notifications o where o.notice_id = v.id;
  get diagnostics n = row_count;
  delete from public.team_notices tn where tn.id = v.id;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'team.changed', 'Notices', 'Deleted: ' || v.title);
  return jsonb_build_object('ok', true, 'copies', n);
end $$;
revoke all on function public.team_notice_delete(uuid) from public, anon;
grant execute on function public.team_notice_delete(uuid) to authenticated;

-- END OF NOTICE DELETE ---------------------------------------------------------

-- ===========================================================================
-- CONFIRM ONCE — a client's creator selection, the team's Confirm creators
-- and a portal request are each one act that happens once (audit F1, S3, C1,
-- 2026-10-10). 2026-10-10. Safe to run twice. Rollback at the foot. Mirrored
-- byte for byte in supabase/schema.sql under the same banner; tests/sql.js
-- compares the two.
--
-- WHAT CHANGED
--   1. `confirm_selection_with(p_token, p_person, p_passcode, p_selected,
--      p_backup, p_seen, p_idem)`: the selection page's Confirm sends the
--      creators on the client's screen, the price shown for each and a key
--      made once for the press. Under the campaign's row lock it refuses
--      `empty`, `closed`, `over-slots`, `stale` (a creator no longer open to
--      choose) and `prices` (a price changed since the page read it; the
--      answer carries the prices now), then saves the selection and files
--      the confirmation with what was confirmed (`snapshot`) in the same
--      transaction. The same key again answers `ok` with `again` and files
--      nothing. Joins `open_to_anon`: run 2026-10-07-function-hygiene.sql
--      again BEFORE this file.
--   2. `confirm_selection` (a page loaded before this one) refuses `empty`
--      when nothing is shortlisted (a backup, once selection has closed),
--      so a selection that never saved is never confirmed.
--   3. `campaign_confirm_creators(p_campaign, p_options, p_person, p_source,
--      p_idem)`: the console's Confirm creators, Creator Campaigns at Work on
--      a client in scope. Every named booking must still be shortlisted on
--      that campaign (`stale` with the count), then the confirmation, the
--      bookings and the campaign's state move together, filed
--      `campaign.locked`; the same key again files nothing.
--   4. `portal_request_once(p_client, p_kind, p_service, p_note, p_idem)`:
--      the portal's Request change keeps one key from the sheet's opening
--      until it is sent, so a reply lost on the way and a second press file
--      one request. `portal_request` (an older page) is the same with no key.
--   5. `campaign_confirmations.idem`, `.snapshot`, `client_requests.idem`,
--      each key unique within its campaign or client.
--
-- ROLLBACK
--   Pages first (they fall back to the older functions where these are
--   missing), then remove the three new functions, put `confirm_selection`
--   and `portal_request` back from their earlier bands, and leave the
--   columns (they hold nothing a page reads).
-- ===========================================================================

alter table public.campaign_confirmations add column if not exists idem text;
alter table public.campaign_confirmations add column if not exists snapshot jsonb;
create unique index if not exists campaign_conf_idem
  on public.campaign_confirmations(campaign_id, idem) where idem is not null;
alter table public.client_requests add column if not exists idem text;
create unique index if not exists client_requests_idem
  on public.client_requests(client_id, idem) where idem is not null;

create or replace function public.confirm_selection_with(
  p_token text, p_person text, p_passcode text, p_selected uuid[], p_backup uuid[],
  p_seen jsonb, p_idem text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  c      campaigns%rowtype;
  v_sel  uuid[];
  v_bak  uuid[];
  v_all  uuid[];
  v_idem text := left(nullif(btrim(coalesce(p_idem, '')), ''), 64);
  v_now  jsonb;
  v_snap jsonb;
  n      integer;
begin
  select * into c from campaigns where access_token = p_token for update;
  if not found then return jsonb_build_object('error', 'not-found'); end if;
  if c.passcode is not null and c.passcode <> ''
     and (p_passcode is null or p_passcode <> c.passcode) then
    return jsonb_build_object('error', 'passcode');
  end if;
  if coalesce(trim(p_person), '') = '' then
    return jsonb_build_object('error', 'name-required');
  end if;
  -- The same press again: the first answer stands and nothing is filed twice.
  if v_idem is not null and exists (select 1 from campaign_confirmations k
                                     where k.campaign_id = c.id and k.idem = v_idem) then
    return jsonb_build_object('ok', true, 'again', true);
  end if;

  v_sel := array(select distinct x from unnest(coalesce(p_selected, '{}'::uuid[])) x where x is not null);
  v_bak := case when coalesce(c.backups_open, false)
                then array(select distinct x from unnest(coalesce(p_backup, '{}'::uuid[])) x
                            where x is not null and not (x = any (v_sel)))
                else '{}'::uuid[] end;
  v_all := v_sel || v_bak;
  n := cardinality(v_sel);

  if c.selection_closed_at is not null and not (coalesce(c.backups_open, false) and n = 0) then
    return jsonb_build_object('error', 'closed');
  end if;
  if cardinality(v_all) = 0 then return jsonb_build_object('error', 'empty'); end if;
  if n > c.slots then return jsonb_build_object('error', 'over-slots', 'slots', c.slots); end if;
  -- Every creator named is still on the campaign and open to choose.
  if (select count(*) from campaign_options o
       where o.id = any (v_all) and o.campaign_id = c.id
         and o.state in ('option', 'shortlisted', 'backup')) <> cardinality(v_all) then
    return jsonb_build_object('error', 'stale');
  end if;
  -- The prices the client read are the prices now.
  select jsonb_object_agg(o.id::text, o.rate) into v_now
    from campaign_options o where o.id = any (v_all);
  if exists (select 1 from campaign_options o
              where o.id = any (v_all)
                and coalesce(p_seen -> (o.id::text), 'null'::jsonb)
                    is distinct from coalesce(to_jsonb(o.rate), 'null'::jsonb)) then
    return jsonb_build_object('error', 'prices', 'rates', v_now);
  end if;

  update campaign_options set state = 'option'
   where campaign_id = c.id and state in ('shortlisted', 'backup');
  if n > 0 then
    update campaign_options set state = 'shortlisted'
     where campaign_id = c.id and id = any (v_sel) and state = 'option';
  end if;
  if cardinality(v_bak) > 0 then
    update campaign_options set state = 'backup'
     where campaign_id = c.id and id = any (v_bak) and state = 'option';
  end if;

  select jsonb_agg(jsonb_build_object('id', o.id, 'creator', cr.name, 'rate', o.rate, 'as', o.state)
                   order by o.position, o.added_at)
    into v_snap
    from campaign_options o join creators cr on cr.id = o.creator_id
   where o.id = any (v_all);
  insert into campaign_confirmations (campaign_id, kind, person, source, idem, snapshot)
  values (c.id, 'client', trim(p_person), 'portal', v_idem, coalesce(v_snap, '[]'::jsonb));

  insert into public.activity_log (actor, action, subject, detail)
  values (trim(p_person), 'campaign.confirmed', c.title,
          case when n > 0 then n::text || ' creator' || case when n = 1 then '' else 's' end || ' confirmed'
               else cardinality(v_bak)::text || ' backup' || case when cardinality(v_bak) = 1 then '' else 's' end || ' confirmed' end);

  return jsonb_build_object('ok', true, 'selected', n);
end $$;

revoke all on function public.confirm_selection_with(text, text, text, uuid[], uuid[], jsonb, text) from public;
grant execute on function public.confirm_selection_with(text, text, text, uuid[], uuid[], jsonb, text) to anon, authenticated;

create or replace function public.confirm_selection(
  p_token text, p_person text, p_passcode text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  c campaigns%rowtype;
begin
  select * into c from campaigns where access_token = p_token;
  if not found then return jsonb_build_object('error', 'not-found'); end if;
  if c.passcode is not null and c.passcode <> ''
     and (p_passcode is null or p_passcode <> c.passcode) then
    return jsonb_build_object('error', 'passcode');
  end if;
  if coalesce(trim(p_person), '') = '' then
    return jsonb_build_object('error', 'name-required');
  end if;
  if c.selection_closed_at is not null and not coalesce(c.backups_open, false) then
    return jsonb_build_object('error', 'closed');
  end if;
  -- Nothing saved is nothing to confirm (a save refused under the page).
  if not exists (select 1 from campaign_options o
                  where o.campaign_id = c.id
                    and o.state = case when c.selection_closed_at is not null
                                       then 'backup' else 'shortlisted' end) then
    return jsonb_build_object('error', 'empty');
  end if;

  insert into campaign_confirmations (campaign_id, kind, person, source)
  values (c.id, 'client', trim(p_person), 'portal');

  insert into public.activity_log (actor, action, subject, detail)
  values (trim(p_person), 'campaign.confirmed', c.title,
          (select count(*)::text || ' creator' || case when count(*) = 1 then '' else 's' end
             from campaign_options
            where campaign_id = c.id and state = 'shortlisted') || ' confirmed');

  return jsonb_build_object('ok', true);
end $$;

revoke all on function public.confirm_selection(text, text, text) from public;
grant execute on function public.confirm_selection(text, text, text) to anon, authenticated;

create or replace function public.campaign_confirm_creators(
  p_campaign uuid, p_options uuid[], p_person text, p_source text, p_idem text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me       public.team_members;
  c        public.campaigns%rowtype;
  v_ids    uuid[] := array(select distinct x from unnest(coalesce(p_options, '{}'::uuid[])) x where x is not null);
  v_idem   text := left(nullif(btrim(coalesce(p_idem, '')), ''), 64);
  v_person text;
  v_source text := case when p_source in ('portal', 'whatsapp', 'email', 'call') then p_source else 'whatsapp' end;
  v_ok     integer;
  v_snap   jsonb;
begin
  if not public.allowed('campaigns.campaigns', 'work') then
    return jsonb_build_object('error', 'denied');
  end if;
  select * into me from public.ops_me();
  if me.id is null then return jsonb_build_object('error', 'denied'); end if;
  select * into c from public.campaigns where id = p_campaign for update;
  if not found then return jsonb_build_object('error', 'not-found'); end if;
  if not public.client_scope_ok('campaign', c.id, 'work') then
    return jsonb_build_object('error', 'client-scope');
  end if;
  if v_idem is not null and exists (select 1 from public.campaign_confirmations k
                                     where k.campaign_id = c.id and k.idem = v_idem) then
    return jsonb_build_object('ok', true, 'again', true);
  end if;
  if cardinality(v_ids) = 0 then return jsonb_build_object('error', 'empty'); end if;
  select count(*) into v_ok from public.campaign_options o
   where o.id = any (v_ids) and o.campaign_id = c.id and o.state = 'shortlisted';
  if v_ok <> cardinality(v_ids) then
    return jsonb_build_object('error', 'stale', 'count', cardinality(v_ids) - v_ok);
  end if;
  v_person := coalesce(nullif(btrim(coalesce(p_person, '')), ''), me.name);

  select jsonb_agg(jsonb_build_object('id', o.id, 'creator', cr.name, 'rate', o.rate, 'as', o.state)
                   order by o.position, o.added_at)
    into v_snap
    from public.campaign_options o join public.creators cr on cr.id = o.creator_id
   where o.id = any (v_ids);
  insert into public.campaign_confirmations (campaign_id, kind, person, source, idem, snapshot)
  values (c.id, case when v_source = 'portal' then 'client' else 'keyed_in' end,
          v_person, v_source, v_idem, coalesce(v_snap, '[]'::jsonb));
  update public.campaign_options
     set state = 'confirmed', confirmed_at = now(), confirmed_by = v_person
   where id = any (v_ids);
  update public.campaigns set state = 'production' where id = c.id;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'campaign.locked', c.title,
          cardinality(v_ids)::text || ' creators · ' || v_person);

  return jsonb_build_object('ok', true, 'confirmed', cardinality(v_ids));
end $$;
revoke all on function public.campaign_confirm_creators(uuid, uuid[], text, text, text) from public, anon;
grant execute on function public.campaign_confirm_creators(uuid, uuid[], text, text, text) to authenticated;

create or replace function public.portal_request_once(
  p_client uuid, p_kind text, p_service uuid, p_note text, p_idem text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  who    text := lower(auth.jwt() ->> 'email');
  cl     public.clients%rowtype;
  me     public.client_contacts%rowtype;
  sv     public.client_services%rowtype;
  rid    uuid;
  v_idem text := left(nullif(btrim(coalesce(p_idem, '')), ''), 64);
begin
  if who is null then return jsonb_build_object('error', 'not-signed-in'); end if;
  if p_client is null or p_client not in (select public.portal_clients()) then
    return jsonb_build_object('error', 'no-access');
  end if;
  -- The same request again (a reply lost on the way): the one already filed.
  if v_idem is not null then
    select r.id into rid from public.client_requests r
     where r.client_id = p_client and r.idem = v_idem;
    if rid is not null then return jsonb_build_object('ok', true, 'id', rid, 'again', true); end if;
  end if;
  if p_kind not in ('upgrade', 'downgrade', 'cancel', 'details') then
    return jsonb_build_object('error', 'bad-kind');
  end if;
  select * into cl from public.clients where id = p_client;
  select * into me from public.client_contacts
    where client_id = p_client and portal_access and archived_at is null and lower(email) = who
    order by is_primary desc limit 1;
  if p_kind <> 'details' then
    select * into sv from public.client_services
      where id = p_service and client_id = p_client and archived_at is null and state = 'confirmed';
    if sv.id is null then return jsonb_build_object('error', 'not-found'); end if;
  end if;
  if p_kind <> 'cancel' and coalesce(btrim(p_note), '') = '' then
    return jsonb_build_object('error', 'note-required');
  end if;
  insert into public.client_requests (client_id, contact_id, contact_name, kind, service_id, service_label, note, idem)
  values (p_client, me.id, me.name, p_kind, sv.id, sv.label, nullif(btrim(p_note), ''), v_idem)
  on conflict (client_id, idem) where idem is not null do nothing
  returning id into rid;
  if rid is null then
    select r.id into rid from public.client_requests r
     where r.client_id = p_client and r.idem = v_idem;
    return jsonb_build_object('ok', true, 'id', rid, 'again', true);
  end if;
  insert into public.activity_log (actor, action, subject, detail)
  values (who, 'request.raised', cl.name, p_kind || coalesce(' · ' || sv.label, ''));
  return jsonb_build_object('ok', true, 'id', rid);
end $$;

create or replace function public.portal_request(
  p_client uuid, p_kind text, p_service uuid default null, p_note text default null)
returns jsonb
language sql
security definer
set search_path = public
as $$
  select public.portal_request_once(p_client, p_kind, p_service, p_note, null)
$$;

revoke all on function public.portal_request_once(uuid, text, uuid, text, text) from public, anon;
grant execute on function public.portal_request_once(uuid, text, uuid, text, text) to authenticated;
revoke all on function public.portal_request(uuid, text, uuid, text) from public, anon;
grant execute on function public.portal_request(uuid, text, uuid, text) to authenticated;

-- END OF CONFIRM ONCE ----------------------------------------------------------

-- ===========================================================================
-- APPROVAL AS SEEN — a client's decision is on the version of the post the
-- page showed, and keeps what that was (audit F2, 2026-10-10).
-- 2026-10-10. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/approvalseen.js
-- compares the two. Holds no word the connector stops on.
--
-- WHAT CHANGED
--   1. `posts.content_version` counts every change to a post's file, copy or
--      title, a correction before any decision included (which stays a
--      correction of the same round: the round is the posts_revision
--      trigger's alone). Stamped by trigger `posts_content_version`; a page
--      cannot set it.
--   2. `get_review_feed` sends each post's `version`.
--   3. `submit_review_seen(… p_version)`: the client's link checked first,
--      then the post locked and its version compared; a post changed since
--      the page read it is refused `changed` (with the version now), and the
--      decision is filed through `submit_review` with what was decided on
--      kept as `reviews.seen` (version, round, title, caption, caption_zh,
--      media). Joins `open_to_anon`: run 2026-10-07-function-hygiene.sql
--      again BEFORE this file. `submit_review` stays for a page loaded
--      before this one.
--
-- ROLLBACK
--   Pages first (they fall back to `submit_review` where the new function
--   is missing), then re-run the REEL COVER PAIRS section's get_review_feed
--   and remove the trigger, the function and the two columns in the SQL
--   Editor.
-- ===========================================================================

alter table public.posts add column if not exists content_version integer not null default 1;
alter table public.reviews add column if not exists seen jsonb;

create or replace function public.posts_content_version() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if (new.media, new.caption, new.caption_zh, new.title)
     is distinct from (old.media, old.caption, old.caption_zh, old.title) then
    new.content_version := coalesce(old.content_version, 1) + 1;
  else
    new.content_version := old.content_version;
  end if;
  return new;
end $$;
revoke all on function public.posts_content_version() from public, anon, authenticated;
create or replace trigger posts_content_version before update on public.posts
  for each row execute function public.posts_content_version();

create or replace function public.get_review_feed(p_token text, p_passcode text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_client public.clients%rowtype;
begin
  select * into v_client
  from public.clients
  where access_token = p_token and active and not review_hidden;

  if not found then
    return jsonb_build_object('error', 'not_found');
  end if;

  if v_client.passcode is not null
     and (p_passcode is null or p_passcode <> v_client.passcode) then
    return jsonb_build_object('error', 'passcode_required', 'client', v_client.name);
  end if;

  return jsonb_build_object(
    'client', jsonb_build_object(
      'name', v_client.name,
      'logo_url', v_client.logo_url,
      'handles', jsonb_build_object(
        'instagram', v_client.handle_ig,
        'facebook',  v_client.handle_fb,
        'tiktok',    v_client.handle_tiktok,
        'xhs',       v_client.handle_xhs)),
    'batches', coalesce((
      select jsonb_agg(batch order by batch->>'created_at' desc)
      from (
        select jsonb_build_object(
          'id',         b.id,
          'title',      b.title,
          'note',       b.note,
          'created_at', b.created_at,
          'posts', coalesce((
            select jsonb_agg(post order by (post->>'position')::int)
            from (
              select jsonb_build_object(
                'id',         p.id,
                'platform',   p.platform,
                'format',     p.format,
                'handle',     p.handle,
                'caption',    p.caption,
                'caption_zh', p.caption_zh,
                'title',      p.title,
                'media',      p.media,
                'cover_for',  p.cover_for,
                'position',   p.position,
                'round',      p.round,
                'version',    p.content_version,
                'reset_note', case
                  when p.review_reset_at is not null then p.review_reset_note end,
                /* The decision standing on the round on show: never one about
                   a round the client no longer sees, never one taken back. */
                'review',     (
                  select jsonb_build_object(
                    'decision',   r.decision,
                    'note',       r.note,
                    'reviewer',   case when r.source = 'team' then null else r.reviewer end,
                    'created_at', r.created_at,
                    'by_team',    (r.source = 'team'),
                    'suggested',  (r.suggested_caption is not null or r.suggested_caption_zh is not null),
                    /* The client's own edit, so Edit request reopens it. */
                    'suggested_caption',    r.suggested_caption,
                    'suggested_caption_zh', r.suggested_caption_zh)
                  from public.reviews r
                  where r.post_id = p.id and r.round = p.round and r.undone_at is null
                    and (p.review_reset_at is null or r.created_at > p.review_reset_at)
                  order by r.created_at desc
                  limit 1),
                /* What the client asked of the round before, so a revision
                   says what it answers. Words only: the earlier file and copy
                   stay with the team. */
                'asked',      case when p.round > 1 then (
                  select jsonb_build_object(
                    'note',       r.note,
                    'reviewer',   r.reviewer,
                    'created_at', r.created_at,
                    'suggested',  (r.suggested_caption is not null or r.suggested_caption_zh is not null))
                  from public.reviews r
                  where r.post_id = p.id and r.round = p.round - 1 and r.decision = 'changes'
                    and r.undone_at is null
                  order by r.created_at desc
                  limit 1) end
              ) as post
              from public.posts p
              where p.batch_id = b.id
            ) posts
          ), '[]'::jsonb)
        ) as batch
        from public.batches b
        where b.client_id = v_client.id and b.published
      ) batches
    ), '[]'::jsonb)
  );
end $$;
revoke all on function public.get_review_feed(text, text) from public;
grant execute on function public.get_review_feed(text, text) to anon, authenticated;

create or replace function public.submit_review_seen(
  p_token      text,
  p_post_id    uuid,
  p_decision   text,
  p_version    integer,
  p_note       text default null,
  p_reviewer   text default null,
  p_passcode   text default null,
  p_caption    text default null,
  p_caption_zh text default null
) returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_post public.posts%rowtype;
  v_res  jsonb;
begin
  -- The link first, as submit_review asks it, so a post id alone says nothing.
  if not exists (select 1
                   from public.posts p
                   join public.batches b on b.id = p.batch_id
                   join public.clients c on c.id = b.client_id
                  where p.id = p_post_id and b.published
                    and c.access_token = p_token and c.active and not c.review_hidden
                    and (c.passcode is null or c.passcode = p_passcode)) then
    return jsonb_build_object('error', 'not_found');
  end if;
  select * into v_post from public.posts where id = p_post_id for update;
  if p_version is null or p_version is distinct from v_post.content_version then
    return jsonb_build_object('error', 'changed', 'version', v_post.content_version);
  end if;
  v_res := public.submit_review(p_token, p_post_id, p_decision, p_note, p_reviewer,
                                p_passcode, p_caption, p_caption_zh);
  if coalesce((v_res ->> 'ok')::boolean, false) then
    update public.reviews r
       set seen = jsonb_build_object('version', v_post.content_version, 'round', v_post.round,
                                     'title', v_post.title, 'caption', v_post.caption,
                                     'caption_zh', v_post.caption_zh, 'media', v_post.media)
     where r.post_id = p_post_id and r.created_at = now() and r.seen is null;
  end if;
  return v_res;
end $$;

revoke all on function public.submit_review_seen(text, uuid, text, integer, text, text, text, text, text) from public;
grant execute on function public.submit_review_seen(text, uuid, text, integer, text, text, text, text, text) to anon, authenticated;

-- END OF APPROVAL AS SEEN -----------------------------------------------------

-- ===========================================================================
-- RELEASED FILES — the client sees the round the team released and nothing
-- newer, a file changed after the quality check is checked again, and a file
-- the client approved is hidden rather than removed (audit S5, S6,
-- 2026-10-10). 2026-10-10. Safe to run twice. Rollback at the foot. Mirrored
-- byte for byte in supabase/schema.sql under the same banner;
-- tests/releasedfiles.js compares the two. It replaces a policy, so it runs
-- in the SQL Editor.
--
-- WHAT CHANGED
--   1. `campaign_options.released_round`, stamped by `campaign_qc_pass` at
--      release with the newest round handed in; `get_campaign` sends that
--      round's files alone, never a hidden one. Rows released before are
--      stamped once from their files.
--   2. `option_qc.voided_at`: a file added or removed while the booking is
--      Submitted voids that round's checks (trigger
--      `campaign_deliverables_qc_void`); `option_qc_count` reads only checks
--      standing, and the same colleague's check is taken again.
--   3. `campaign_deliverables.hidden_at` / `hidden_by`: from the client's
--      approval on (Scheduled, Posted, Completed) a file is hidden, never
--      removed: `campaign_file_hide(p_file, p_hide)`, Creator Campaigns at
--      Work, client scope, filed `campaign.file_hidden` /
--      `campaign.file_shown`. Trigger `campaign_deliverables_guard` refuses a
--      page removing such a file (`approved-hide`). Once hidden it is
--      deleted only by `campaign_file_delete(p_file)` at the granted part
--      `campaigns.files_delete`, filed `campaign.file_deleted`; the record's
--      section map files the three tags under Creator Campaigns.
--   4. The one `for all` policy is four: read at Creator Campaigns:
--      Campaigns View, add and change at Work, and a permanent delete at the
--      granted part `campaigns.files_delete` (an admin's alone until given).
--
-- ROLLBACK
--   Pages first (they read the new columns where present), then put back
--   `campaign_deliverables_team` (for all, is_team()), re-run the earlier
--   get_campaign, campaign_qc_pass and option_qc_count, and remove the
--   triggers, the function and the columns, in the SQL Editor.
-- ===========================================================================

alter table public.campaign_options add column if not exists released_round integer;
alter table public.option_qc add column if not exists voided_at timestamptz;
alter table public.campaign_deliverables add column if not exists hidden_at timestamptz;
alter table public.campaign_deliverables add column if not exists hidden_by text;

-- Rows released before: the round on show today.
update public.campaign_options o
   set released_round = (select max(d.round) from public.campaign_deliverables d
                          where d.option_id = o.id and d.removed_at is null)
 where o.released_round is null
   and o.state in ('reviewing', 'scheduled', 'posted', 'completed');
update public.campaign_options o
   set released_round = (select max(d.round) from public.campaign_deliverables d
                          where d.option_id = o.id and d.removed_at is null
                            and d.round < coalesce(o.revision_round, 0))
 where o.released_round is null and o.state = 'changes'
   and coalesce(o.changes_by, 'client') = 'client';

create or replace function public.option_qc_count(p_option uuid)
returns integer
language sql security definer stable set search_path = public as $$
  select count(distinct q.team_member_id)::int
    from public.option_qc q
    join public.campaign_options o on o.id = q.option_id
   where q.option_id = p_option
     and q.round = coalesce(o.revision_round, 0)
     and q.voided_at is null
$$;
grant execute on function public.option_qc_count(uuid) to authenticated;

create or replace function public.campaign_qc_pass(
  p_option uuid, p_want_second boolean default false)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me   public.team_members;
  o    public.campaign_options;
  n    integer;
begin
  if not public.allowed('campaigns.campaigns', 'work') then
    return jsonb_build_object('error', 'denied');
  end if;
  select * into me from public.ops_me();
  if me.id is null then return jsonb_build_object('error', 'denied'); end if;

  select * into o from public.campaign_options where id = p_option for update;
  if o.id is null then return jsonb_build_object('error', 'no-booking'); end if;
  if o.state <> 'submitted' then
    return jsonb_build_object('error', 'not-submitted');
  end if;

  /* A check voided by a file added since (audit S5) is taken again. */
  insert into public.option_qc (option_id, team_member_id, round)
  values (p_option, me.id, coalesce(o.revision_round, 0))
  on conflict (option_id, team_member_id, round)
  do update set voided_at = null, checked_at = now()
   where public.option_qc.voided_at is not null;

  if p_want_second and not coalesce(o.qc_second_wanted, false) then
    update public.campaign_options set qc_second_wanted = true where id = p_option;
    o.qc_second_wanted := true;
  end if;

  n := public.option_qc_count(p_option);
  if coalesce(o.qc_second_wanted, false) and n < 2 then
    return jsonb_build_object('state', 'waiting', 'checks', n, 'second', true);
  end if;

  update public.campaign_options
     set state = 'reviewing', changes_by = null,
         released_round = coalesce((select max(d.round) from public.campaign_deliverables d
                                     where d.option_id = p_option and d.removed_at is null
                                       and d.hidden_at is null), released_round)
   where id = p_option;
  return jsonb_build_object('state', 'reviewing', 'checks', n,
                            'second', coalesce(o.qc_second_wanted, false));
end $$;
grant execute on function public.campaign_qc_pass(uuid, boolean) to authenticated;

create or replace function public.campaign_deliverables_qc_void() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'UPDATE' and new.removed_at is not distinct from old.removed_at then
    return new;
  end if;
  update public.option_qc q set voided_at = now()
    from public.campaign_options o
   where o.id = new.option_id and o.state = 'submitted'
     and q.option_id = o.id and q.round = coalesce(o.revision_round, 0)
     and q.voided_at is null;
  return new;
end $$;
revoke all on function public.campaign_deliverables_qc_void() from public, anon, authenticated;
create or replace trigger campaign_deliverables_qc_void
  after insert or update on public.campaign_deliverables
  for each row execute function public.campaign_deliverables_qc_void();

/* A file the client approved is the client's record of what they approved:
   a page hides it, and never removes it. Run as the caller, so
   `current_user` tells a page's write from a function's. */
create or replace function public.campaign_deliverables_guard() returns trigger
language plpgsql set search_path = public as $$
begin
  if current_user in ('authenticated', 'anon')
     and new.removed_at is not null and old.removed_at is null
     and exists (select 1 from public.campaign_options o
                  where o.id = new.option_id and o.state in ('scheduled', 'posted', 'completed')) then
    raise exception 'approved-hide' using hint = 'An approved file is hidden, not removed.';
  end if;
  if current_user in ('authenticated', 'anon')
     and (new.hidden_at, new.hidden_by) is distinct from (old.hidden_at, old.hidden_by) then
    raise exception 'hide-function' using hint = 'Hide and Restore go through campaign_file_hide.';
  end if;
  return new;
end $$;
revoke all on function public.campaign_deliverables_guard() from public, anon, authenticated;
create or replace trigger campaign_deliverables_guard
  before update on public.campaign_deliverables
  for each row execute function public.campaign_deliverables_guard();

create or replace function public.campaign_file_hide(p_file uuid, p_hide boolean default true)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me   public.team_members;
  d    public.campaign_deliverables%rowtype;
  o    public.campaign_options%rowtype;
  c    public.campaigns%rowtype;
  cr   text;
begin
  if not public.allowed('campaigns.campaigns', 'work') then
    return jsonb_build_object('error', 'denied');
  end if;
  select * into me from public.ops_me();
  if me.id is null then return jsonb_build_object('error', 'denied'); end if;
  select * into d from public.campaign_deliverables where id = p_file for update;
  if d.id is null or d.removed_at is not null then return jsonb_build_object('error', 'not-found'); end if;
  select * into o from public.campaign_options where id = d.option_id;
  select * into c from public.campaigns where id = o.campaign_id;
  if not public.client_scope_ok('campaign', c.id, 'work') then
    return jsonb_build_object('error', 'client-scope');
  end if;
  if o.state not in ('scheduled', 'posted', 'completed') then
    return jsonb_build_object('error', 'not-approved');
  end if;
  if coalesce(p_hide, true) = (d.hidden_at is not null) then
    return jsonb_build_object('ok', true, 'again', true);
  end if;
  update public.campaign_deliverables
     set hidden_at = case when coalesce(p_hide, true) then now() end,
         hidden_by = case when coalesce(p_hide, true) then me.name end
   where id = d.id;
  select cx.name into cr from public.creators cx where cx.id = o.creator_id;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, case when coalesce(p_hide, true) then 'campaign.file_hidden' else 'campaign.file_shown' end,
          c.title, coalesce(cr, 'Creator') || ' · ' || coalesce(d.name, 'file'));
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.campaign_file_hide(uuid, boolean) from public, anon;
grant execute on function public.campaign_file_hide(uuid, boolean) to authenticated;

drop policy if exists campaign_deliverables_team on public.campaign_deliverables;
drop policy if exists campaign_deliverables_read on public.campaign_deliverables;
drop policy if exists campaign_deliverables_write on public.campaign_deliverables;
drop policy if exists campaign_deliverables_edit on public.campaign_deliverables;
drop policy if exists campaign_deliverables_del on public.campaign_deliverables;
create policy campaign_deliverables_read on public.campaign_deliverables
  for select to authenticated using (public.allowed('campaigns.campaigns', 'view'));
create policy campaign_deliverables_write on public.campaign_deliverables
  for insert to authenticated with check (public.allowed('campaigns.campaigns', 'work'));
create policy campaign_deliverables_edit on public.campaign_deliverables
  for update to authenticated using (public.allowed('campaigns.campaigns', 'work'))
  with check (public.allowed('campaigns.campaigns', 'work'));
create policy campaign_deliverables_del on public.campaign_deliverables
  for delete to authenticated using (public.ops_granted('campaigns.files_delete', 'work'));

/* A file the client approved leaves for good only by a colleague holding
   the granted part `campaigns.files_delete` (an admin's until given), and
   only once hidden: the stored file itself is kept, as every upload is. */
create or replace function public.campaign_file_delete(p_file uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me   public.team_members;
  d    public.campaign_deliverables%rowtype;
  o    public.campaign_options%rowtype;
  c    public.campaigns%rowtype;
  cr   text;
begin
  if not public.ops_granted('campaigns.files_delete', 'work') then
    return jsonb_build_object('error', 'denied');
  end if;
  select * into me from public.ops_me();
  if me.id is null then return jsonb_build_object('error', 'denied'); end if;
  select * into d from public.campaign_deliverables where id = p_file for update;
  if d.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if d.hidden_at is null then return jsonb_build_object('error', 'not-hidden'); end if;
  select * into o from public.campaign_options where id = d.option_id;
  select * into c from public.campaigns where id = o.campaign_id;
  if not public.client_scope_ok('campaign', c.id, 'manage') then
    return jsonb_build_object('error', 'client-scope');
  end if;
  select cx.name into cr from public.creators cx where cx.id = o.creator_id;
  delete from public.campaign_deliverables where id = d.id;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'campaign.file_deleted', c.title,
          coalesce(cr, 'Creator') || ' · ' || coalesce(d.name, 'file'));
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.campaign_file_delete(uuid) from public, anon;
grant execute on function public.campaign_file_delete(uuid) to authenticated;

create or replace function public.activity_section(p_action text)
returns text
language sql immutable parallel safe as $$
  select case
    when action in ('campaign.bulk', 'campaign.closed', 'campaign.confirmed',
                    'campaign.created', 'campaign.dates', 'campaign.deleted', 'campaign.edited',
                    'campaign.file_added', 'campaign.file_deleted', 'campaign.file_hidden',
                    'campaign.file_shown', 'campaign.qc',
                    'campaign.invoice', 'campaign.invoice_file',
                    'campaign.invoice_removed', 'campaign.keyed', 'campaign.locked',
                    'campaign.opened', 'campaign.rate', 'campaign.rated',
                    'campaign.reinstated', 'campaign.replaced', 'campaign.results', 'campaign.review',
                    'campaign.stage', 'campaign.submitted', 'campaign.task_linked',
                    'campaign.task_unlinked', 'campaign.unbooked',
                    'campaign.unkeyed', 'campaign.whatsapp', 'campaign.withdrawn', 'creator.added',
                    'creator.code', 'creator.links', 'creator.links_restored',
                    'creator.links_self', 'creator.off', 'creator.on', 'creator.removed',
                    'creator.updated') then 'campaigns'
    when action in ('client.action_done', 'client.action_reopened', 'client.added',
                    'client.billing', 'client.brand', 'client.deleted', 'client.edited',
                    'client.review_on', 'client.service', 'client.service_changed',
                    'client.service_removed', 'client.service_restored', 'client.stage', 'client.touch',
                    'client.touch_deleted', 'client.touch_edited', 'client.touch_removed',
                    'client.touch_restored', 'contact.added', 'contact.deleted',
                    'contact.edited', 'contact.portal_invite', 'contact.portal_off',
                    'contact.portal_on', 'contact.primary', 'contact.removed',
                    'contact.restored',
                    'request.changed', 'request.raised',
                    'request.reinstated', 'request.replied', 'request.withdrawn',
                    'service.override') then 'clients'
    when action in ('wa.sent', 'wa.template') then 'whatsapp'
    when action in ('report.ai_drafted', 'report.ai_failed', 'report.audited', 'report.confirmed',
                    'report.created', 'report.deleted', 'report.published',
                    'report.reassigned', 'report.returned', 'report.revised', 'report.saved',
                    'report.submitted', 'report.unpublished') then 'reports'
    when action in ('qr.created', 'qr.restored', 'qr.revoked', 'shortlink.created',
                    'shortlink.deleted', 'shortlink.imported', 'shortlink.updated') then 'links'
    when action in ('ops.deleted', 'ops.month_deleted', 'ops.numbering') then 'ops'
    when action in ('document.deleted', 'document.issued', 'document.reissued',
                    'document.restored', 'document.signed', 'document.superseded',
                    'document.unsigned', 'document.verified', 'document.voided',
                    'register.added', 'register.edited') then 'register'
    when action in ('client.drive', 'client.handles', 'client.profile',
                    'client.removed', 'drive.imported', 'link.reset', 'post.added',
                    'post.deleted', 'post.edited', 'reapproval.requested',
                    'review.approved', 'review.changes', 'review.removed',
                    'review.unconfirmed',
                    'set.created', 'set.deleted', 'set.month', 'set.published', 'set.renamed',
                    'set.task_linked', 'set.task_unlinked',
                    'set.withdrawn') then 'review'
    when action in ('script.approved', 'script.changes', 'script.created', 'script.deleted',
                    'script.link', 'script.saved', 'script.shared', 'script.shot',
                    'script.unshared') then 'scripts'
    when action in ('handbook.added', 'handbook.archived', 'handbook.deleted',
                    'handbook.edited', 'handbook.restored', 'handbook.version') then 'handbook'
    when action in ('service.added', 'service.changed', 'service.deleted',
                    'service.off', 'service.on') then 'services'
    when action in ('team.added', 'team.changed', 'team.edited', 'team.group_added',
                    'team.group_changed', 'team.group_removed', 'team.invited') then 'team'
    else 'other'
  end
  from (select p_action as action) t
$$;
grant execute on function public.activity_section(text) to authenticated;

create or replace function public.get_campaign(p_token text, p_passcode text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  c campaigns%rowtype;
  cl clients%rowtype;
  billable boolean;
begin
  select * into c from campaigns where access_token = p_token;
  if not found then return jsonb_build_object('error', 'not-found'); end if;
  select * into cl from clients where id = c.client_id;

  -- An invoice belongs to an accepted booking. Until the client has chosen and
  -- the team has confirmed at least one creator, the number and the PDF stay
  -- off the client's page, and reverting the last confirmation takes them off
  -- it again. The gate is here rather than on the page so nothing the client
  -- can open carries what it should not show.
  select exists (
    select 1 from campaign_options o
     where o.campaign_id = c.id
       and o.state in ('confirmed', 'pending_visit', 'pending_draft', 'submitted',
                       'reviewing', 'changes', 'scheduled', 'posted', 'completed')
  ) into billable;

  if c.passcode is not null and c.passcode <> '' then
    if p_passcode is null or p_passcode <> c.passcode then
      return jsonb_build_object('error', 'passcode', 'client', cl.name);
    end if;
  end if;

  return jsonb_build_object(
    'campaign', jsonb_build_object(
      'title', c.title, 'title_zh', c.title_zh,
      'purpose', c.purpose, 'purpose_zh', c.purpose_zh, 'slots', c.slots,
      'backups_open', coalesce(c.backups_open, false),
      'selection_closed', c.selection_closed_at is not null,
      'deadline', c.deadline, 'state', c.state, 'deliverable', c.deliverable,
      'push_format', c.push_format, 'brief', c.brief, 'brief_zh', c.brief_zh,
      'invoice_no', case when billable then c.invoice_no end,
      'invoice_url', case when billable then c.invoice_url end),
    -- Currency and tax travel with the campaign, because the client's page
    -- prints both and must not assume Malaysia.
    'client', jsonb_build_object('name', cl.name, 'logo_url', cl.logo_url,
      'market', coalesce(cl.market, 'MY'), 'sst_applies', coalesce(cl.sst_applies, true)),
    /* A draft reaches the client when the team releases it, and not a moment
       before. `submitted` is the team's own step, so it is reported as
       `pending_draft`: the client is not asked to approve something they
       cannot open, and does not learn that a round exists. A `changes` the
       team raised is the same round going back to the creator, so it is
       withheld the same way; a `changes` the client raised is their own and
       is reported as it is. The mapping is here and not on the page, because
       what a client may not see is withheld by this function. */
    'options', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', o.id, 'name', cr.name,
        'rate', o.rate, 'platforms', o.platforms, 'state', s.shown,
        'is_replacement', o.is_replacement, 'added_at', o.added_at,
        -- Production. Present once a creator is locked; null before that, so
        -- the page can tell "not started" from "nothing to say".
        'visit_date', o.visit_date, 'visit_time', o.visit_time,
        'visit_location', o.visit_location, 'visit_pic', o.visit_pic,
        'visit_pic_phone', o.visit_pic_phone, 'tracking_no', o.tracking_no,
        'draft_url', case when s.released then o.draft_url end,
        /* The client's own rounds: a round the team sent back, or a request
           taken back, is not one the client made (2026-09-27). */
        'revision_round', (select count(*) from public.option_reviews r
                            where r.option_id = o.id and r.source = 'client'
                              and r.decision = 'changes' and r.undone_at is null)::int + 1,
        'planned_publish', o.planned_publish,
        /* What the creator uploaded, once it has been released: the round
           the team last released (`released_round`, stamped at release), so
           a creator's next round, uploaded after the client asked for
           changes, stays with the team until it is released in its turn
           (audit S5, 2026-10-10). A file hidden after the client's approval
           is never sent (audit S6). */
        'files', case when s.released then coalesce((
            select jsonb_agg(jsonb_build_object(
              'id', d.id, 'url', d.url, 'name', d.name, 'kind', d.kind,
              'bytes', d.bytes) order by d.uploaded_at)
            from campaign_deliverables d
            where d.option_id = o.id and d.removed_at is null and d.hidden_at is null
              and d.round = coalesce(o.released_round,
                            (select max(d2.round) from campaign_deliverables d2
                              where d2.option_id = o.id and d2.removed_at is null))
          ), '[]'::jsonb) else '[]'::jsonb end,
        -- The caption is part of what is being approved, so it travels with
        -- the files and is withheld with them.
        'caption', case when s.released then o.draft_caption end,
        'profiles', coalesce((
          select jsonb_agg(jsonb_build_object('platform', p.platform, 'url', p.url))
          from creator_profiles p where p.creator_id = cr.id), '[]'::jsonb),
        -- One row per platform posted on, so two placements stay two numbers.
        'posts', coalesce((
          select jsonb_agg(jsonb_build_object(
            'platform', pp.platform, 'post_url', pp.post_url,
            'published_at', pp.published_at, 'window_days', pp.window_days,
            'impressions', pp.impressions, 'engagements', pp.engagements,
            'views', pp.views, 'measured_at', pp.measured_at) order by pp.platform)
          from option_posts pp where pp.option_id = o.id), '[]'::jsonb),
        /* What was last decided, so the card can say who approved it and
           when rather than jumping to the next step with nothing to show for
           the decision. The client's own decisions, and an approval the team
           gave on the client's behalf (`by_team`, read "Proceeded by"); a
           team send-back stays withheld. Withheld with the draft it is about. */
        'review', case when s.released then (
            select jsonb_build_object('decision', r.decision, 'reviewer', r.reviewer,
                                      'note', case when r.source = 'client' then r.note end,
                                      'at', r.created_at, 'by_team', r.source = 'team')
            from option_reviews r where r.option_id = o.id
              and (r.source = 'client' or r.decision = 'approved') and r.undone_at is null
            order by r.created_at desc limit 1) end)
        order by o.position, o.added_at)
      from campaign_options o
      join creators cr on cr.id = o.creator_id
      cross join lateral (
        select sh.shown,
               sh.shown in ('reviewing', 'changes', 'scheduled', 'posted', 'completed')
                 as released
        from (select case
                       when o.state = 'submitted' then 'pending_draft'
                       when o.state = 'changes'
                            and coalesce(o.changes_by, 'client') = 'team' then 'pending_draft'
                       else o.state
                     end as shown) sh
      ) s
      where o.campaign_id = c.id and o.state <> 'replaced'), '[]'::jsonb)
  );
end $$;

revoke all on function public.get_campaign(text, text) from public;
grant execute on function public.get_campaign(text, text) to anon, authenticated;

-- END OF RELEASED FILES -------------------------------------------------------

-- ===========================================================================
-- LETTERS HELD TO THEIR LINES — a letter is priced by the database and
-- verified only over the lines it printed; a client's deletion files itself;
-- the documents table takes no direct write; a group seeing only its own
-- clients holds no Activity record (audit S2, S4, R1, 2026-10-10).
-- 2026-10-10. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/lettersql.js compares
-- the two. It drops policies, so it runs in the SQL Editor.
--
-- WHAT CHANGED
--   1. `issue_letter` works the price itself (the letter's own rule:
--      js/documents.js priceOf, js/money.js rateFor, SST at the rate in
--      force today) and refuses page figures that differ by more than a sen
--      (`stale`, with the figures now). Same signature.
--   2. `verify_letter` refuses a letter one of whose lines was removed since
--      (`archived-line`) or whose quantity, rate, term or adjustment moved
--      since it was issued (`changed-terms`).
--   3. `delete_client` files `client.deleted` itself, in the transaction that
--      deletes; the page no longer files it.
--   4. `client_documents` keeps its read policy; insert, update and delete
--      go only through the letter functions (no page writes the table).
--   5. Trigger `team_roles_scope_guard`: a group is not given Own clients
--      only together with any Activity record access (`scope-activity`),
--      since the record is not scoped. An admin group is left alone.
--
-- ROLLBACK
--   Re-run the CLIENT LETTERS section's issue_letter and verify_letter, the
--   ONE SET OF HANDLES section's delete_client (the page filing again), and
--   the DELETE AT ITS LEVEL section's three client_documents policies, and
--   remove the trigger and its function.
-- ===========================================================================

create or replace function public.issue_letter(
  p_client    uuid,
  p_services  uuid[],
  p_idem      text,
  p_subtotal  numeric,
  p_tax       numeric,
  p_total     numeric,
  p_deal      jsonb   default '{}'::jsonb,
  p_replaces  uuid    default null,
  p_renewal   boolean default false,
  /* A reference somebody typed. Blank is the ordinary case and the counter
     below makes the number; where one is typed it is checked against every
     document that stands and the counter is not advanced, so filling a gap
     by hand never costs the next letter its place in the sequence. */
  p_serial    text    default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  who    text := lower(auth.jwt() ->> 'email');
  cl     public.clients%rowtype;
  ct     public.client_contacts%rowtype;
  me     public.team_members%rowtype;
  v_ym   text;
  v_seq  int;
  v_try  int;
  v_no   text;
  v_id   uuid;
  v_lines jsonb;
  v_n    int;
  v_bad  int;
  v_old  public.client_documents%rowtype;
  v_term int;
  v_each numeric;
  v_etax numeric;
  v_sub  numeric;
  v_tax  numeric;
  v_tot  numeric;
  v_pct  numeric;
begin
  if not public.allowed('clients.documents') then
    return jsonb_build_object('error', 'not-allowed');
  end if;
  if p_client is null or p_services is null or array_length(p_services, 1) is null then
    return jsonb_build_object('error', 'no-lines');
  end if;

  select * into cl from public.clients where id = p_client;
  if cl.id is null then return jsonb_build_object('error', 'no-client'); end if;

  -- The Client ID is what the serial is built from, so there is no letter
  -- without one. Staff enter it on the record; nothing invents it. A typed
  -- reference needs no code, because nothing is being built.
  v_no := nullif(btrim(coalesce(p_serial, '')), '');
  if v_no is null and coalesce(btrim(cl.client_code), '') = '' then
    return jsonb_build_object('error', 'no-client-code');
  end if;

  -- The same submission, pressed twice, is one letter. Answered before any
  -- number is reserved, so a double click cannot spend a serial either.
  if coalesce(btrim(p_idem), '') <> '' then
    select * into v_old from public.client_documents
      where client_id = p_client and idem_key = btrim(p_idem) limit 1;
    if v_old.id is not null then
      return jsonb_build_object('ok', true, 'repeat', true, 'id', v_old.id, 'number', v_old.number);
    end if;
  end if;

  -- A typed reference is checked before anything is written: the same shape
  -- the Register accepts, and refused where a document still holds it.
  if v_no is not null then
    if v_no !~ '^[A-Za-z0-9/._-]{3,40}$' then
      return jsonb_build_object('error', 'serial-shape');
    end if;
    if public.serial_taken(v_no) then
      return jsonb_build_object('error', 'serial-taken');
    end if;
  end if;

  -- Every id must be this client's own live line, and in a state this letter
  -- may carry: To quote always, Confirmed only on a deliberate renewal.
  select count(*) into v_bad from unnest(p_services) s(id)
    left join public.client_services cs
      on cs.id = s.id and cs.client_id = p_client and cs.archived_at is null
    where cs.id is null
       or (cs.state = 'confirmed' and not p_renewal)
       or cs.state not in ('quoted', 'confirmed');
  if v_bad > 0 then return jsonb_build_object('error', 'bad-lines'); end if;

  -- A line already on a live letter is not offered again by accident. The way
  -- through is to void that letter, or to name it as the one being replaced.
  select count(*) into v_bad
    from public.client_document_services m
    join public.client_documents d on d.id = m.document_id
   where m.service_id = any(p_services)
     and d.voided_at is null
     and d.superseded_by is null
     and d.verified_at is null
     and (p_replaces is null or d.id <> p_replaces);
  if v_bad > 0 then return jsonb_build_object('error', 'already-quoted'); end if;

  if p_replaces is not null then
    select * into v_old from public.client_documents
      where id = p_replaces and client_id = p_client;
    if v_old.id is null then return jsonb_build_object('error', 'no-replaces'); end if;
    if v_old.verified_at is not null then return jsonb_build_object('error', 'replaces-verified'); end if;
  end if;

  select * into ct from public.client_contacts
    where client_id = p_client and archived_at is null
    order by (id = cl.bill_contact_id) desc, is_primary desc, name limit 1;
  select * into me from public.team_members where lower(email) = who and active limit 1;

  -- A letter is signed by a person. issued_by is this row's name, so a team
  -- row named "Superadmin" printed that word under ADSPACE PLT on a client's
  -- letterhead. Refuse rather than draw a permission as a signatory.
  if not public.issuer_name_ok(me.name) then
    return jsonb_build_object('error', 'issuer-name', 'name', coalesce(me.name, ''));
  end if;

  -- The snapshot is built from the stored rows, never from what the browser
  -- sent: the words on a letter are the words the record held at that moment.
  select jsonb_agg(jsonb_build_object(
           'label', cs.label, 'unit', coalesce(cs.unit, ''), 'note', coalesce(cs.note, ''),
           'detail', coalesce(cs.detail, ''), 'state', cs.state,
           'qty', cs.qty, 'rate', cs.rate,
           'tenure', greatest(1, coalesce(cs.tenure, 1)),
           'start_on', coalesce(cs.start_on, ''),
           -- The line's own answer to whether its term prices it. Written into
           -- the snapshot because the letter is redrawn from it, and a letter
           -- must print the same figure every time it is drawn. A snapshot
           -- taken before this key existed carries none, which money.js reads
           -- as on, so those letters redraw as they were issued.
           'term_adjust', coalesce(cs.term_adjust, false),
           -- And the percentage that tick applies, so a later rate card can
           -- never move a figure this letter printed. Null on a line quoted
           -- before the column existed, which money.js reads as that card.
           'term_pct', cs.term_pct,
           'tax', cl.sst_applies is not false,
           'service_id', cs.id)
           order by cs.created_at)
    into v_lines
    from public.client_services cs
   where cs.id = any(p_services);
  if v_lines is null then return jsonb_build_object('error', 'no-lines'); end if;

  /* The price is the database's (audit S4, 2026-10-10), worked as the
     letter draws it (js/documents.js priceOf, js/money.js rateFor): each
     line's rate with its term on it, rounded to the cent; a letter whose
     lines share a term of more than a month priced by the month and times
     the term; SST at the rate in force today unless the client is exempt.
     The page's figures are kept only where they agree to the sen, so a line
     changed since the sheet opened, or a figure typed in a browser, is
     refused (`stale`) and the sheet reads the lines again. */
  select case when count(distinct greatest(1, coalesce(cs.tenure, 1))) = 1
               and min(greatest(1, coalesce(cs.tenure, 1))) > 1
              then min(greatest(1, coalesce(cs.tenure, 1))) else 0 end
    into v_term
    from public.client_services cs where cs.id = any(p_services);
  select coalesce(sum(coalesce(cs.qty, 0) *
           round(coalesce(cs.rate, 0) *
             case when cs.term_adjust is false then 1
                  when cs.term_pct is not null then 1 + cs.term_pct / 100
                  else case greatest(1, coalesce(cs.tenure, 1))
                         when 3 then 1 / 0.9 when 12 then 0.95 when 24 then 0.9 else 1 end
             end, 2) *
           case when v_term > 0 then 1 else greatest(1, coalesce(cs.tenure, 1)) end), 0)
    into v_each
    from public.client_services cs where cs.id = any(p_services);
  v_pct := case when cl.sst_applies is false then 0
                else coalesce(public.app_setting('sst_pct', (timezone('Asia/Kuala_Lumpur', now()))::date), 0) end;
  v_etax := round(v_each * v_pct) / 100;
  v_sub := round(v_each * greatest(v_term, 1), 2);
  v_tax := round(v_etax * greatest(v_term, 1), 2);
  v_tot := round(round(v_each + v_etax, 2) * greatest(v_term, 1), 2);
  if abs(coalesce(p_subtotal, -1) - v_sub) > 0.01 or abs(coalesce(p_tax, -1) - v_tax) > 0.01
     or abs(coalesce(p_total, -1) - v_tot) > 0.01 then
    return jsonb_build_object('error', 'stale', 'subtotal', v_sub, 'tax', v_tax, 'total', v_tot);
  end if;

  -- A typed reference spends no sequence number: the counter is the office's
  -- record of how many letters it has issued this month, and a person filling
  -- a gap by hand has not issued one more.
  if v_no is null then
    -- The month is Malaysian, because the office that numbers the letter is.
    v_ym := to_char(timezone('Asia/Kuala_Lumpur', now()), 'YYMM');

    -- The counter still advances on every automatic issue, and the upsert's
    -- row lock is what makes the scan below safe: a second issuer blocks here
    -- until the first has committed its letter, so the two never read the same
    -- gap as free. What the counter gives is a bound to scan within, not the
    -- number itself.
    insert into public.client_document_seq (client_id, ym, next_val)
         values (p_client, v_ym, 2)
    on conflict (client_id, ym)
      do update set next_val = public.client_document_seq.next_val + 1
      returning next_val - 1 into v_seq;

    -- The lowest free slot, not the counter's own value. A deleted letter
    -- releases its reference (serial_taken stopped counting deletions on
    -- 2026-09-20), and without this the automatic path still counted upward
    -- past the gap: a client whose first two letters were issued in testing
    -- and deleted started at 03 for ever. The counter is at least the number
    -- of letters issued this month, so a free slot exists at or below it
    -- unless somebody has typed references over the same range by hand; the
    -- cap covers that and refuses rather than looping.
    --
    -- Two digits is the floor, not the ceiling: the hundredth letter of a month
    -- widens to three rather than wrapping. Not lpad(): Postgres pads AND
    -- truncates to the width it is given, so lpad('100', 2, '0') is '10' and the
    -- hundredth letter would collide with the tenth.
    v_try := 1;
    loop
      v_no := 'AQL/' || cl.client_code || '/' || v_ym ||
              case when v_try < 100 then lpad(v_try::text, 2, '0') else v_try::text end;
      exit when not public.serial_taken(v_no);
      v_try := v_try + 1;
      if v_try > greatest(v_seq, 1) + 200 then
        return jsonb_build_object('error', 'no-serial');
      end if;
    end loop;
  end if;

  insert into public.client_documents
    (client_id, kind, number, issued_at, market, subtotal, tax, total,
     bill_to, lines, issued_by, client_code, idem_key)
  values
    (p_client, 'offer', v_no, (timezone('Asia/Kuala_Lumpur', now()))::date,
     coalesce(cl.market, 'MY'),
     round(coalesce(p_subtotal, 0), 2), round(coalesce(p_tax, 0), 2), round(coalesce(p_total, 0), 2),
     jsonb_build_object(
       'name', coalesce(cl.name, ''), 'legal_name', coalesce(cl.legal_name, ''),
       'address', coalesce(cl.billing_address, ''), 'regno', coalesce(cl.company_no, ''),
       'regno_old', coalesce(cl.company_no_old, ''), 'tin', coalesce(cl.tin, ''),
       'sst_no', coalesce(cl.sst_no, ''), 'sst_applies', cl.sst_applies is not false,
       'contact', coalesce(ct.name, ''), 'contact_role', coalesce(ct.role, ''),
       'phone', coalesce(ct.phone, ''), 'email', coalesce(ct.email, ''),
       'finance_email', coalesce(cl.finance_email, ''),
       'client_code', cl.client_code,
       'owner', coalesce(p_deal ->> 'owner', ''), 'source', coalesce(p_deal ->> 'source', ''),
       'industry', coalesce(p_deal ->> 'industry', ''), 'stage', coalesce(p_deal ->> 'stage', ''),
       'enquiry', coalesce(p_deal ->> 'enquiry', '')),
     v_lines, coalesce(me.name, who), cl.client_code, nullif(btrim(p_idem), ''))
  returning id into v_id;

  insert into public.client_document_services (document_id, service_id)
    select v_id, s.id from unnest(p_services) s(id)
    on conflict do nothing;

  if p_replaces is not null then
    update public.client_documents set superseded_by = v_id where id = p_replaces;
    insert into public.activity_log (actor, action, subject, detail)
    values (who, 'document.superseded', cl.name, v_old.number || ' replaced by ' || v_no);
  end if;

  select count(*) into v_n from public.client_document_services where document_id = v_id;
  insert into public.activity_log (actor, action, subject, detail)
  values (who, 'document.issued', cl.name, v_no || ' · ' || v_n || ' line' || case when v_n = 1 then '' else 's' end);

  return jsonb_build_object('ok', true, 'id', v_id, 'number', v_no);
exception
  when unique_violation then
    -- Two presses that raced past the idempotency read: the loser reads the
    -- winner's letter back rather than making a second one.
    if coalesce(btrim(p_idem), '') <> '' then
      select * into v_old from public.client_documents
        where client_id = p_client and idem_key = btrim(p_idem) limit 1;
      if v_old.id is not null then
        return jsonb_build_object('ok', true, 'repeat', true, 'id', v_old.id, 'number', v_old.number);
      end if;
    end if;
    -- A typed reference two people sent at once: the loser is told the
    -- reference is spent rather than that "two letters were issued at once",
    -- which names a cause they cannot act on.
    if nullif(btrim(coalesce(p_serial, '')), '') is not null then
      return jsonb_build_object('error', 'serial-taken');
    end if;
    return jsonb_build_object('error', 'clash');
end $$;

grant execute on function public.issue_letter(uuid, uuid[], text, numeric, numeric, numeric, jsonb, uuid, boolean, text) to authenticated;

create or replace function public.verify_letter(p_doc uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  who   text := lower(auth.jwt() ->> 'email');
  d     public.client_documents%rowtype;
  cl    public.clients%rowtype;
  me    public.team_members%rowtype;
  v_map int;
  v_n   int;
begin
  if not public.allowed('clients.documents') then return jsonb_build_object('error', 'not-allowed'); end if;
  select * into d from public.client_documents where id = p_doc;
  if d.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if d.voided_at is not null then return jsonb_build_object('error', 'voided'); end if;
  if d.superseded_by is not null then return jsonb_build_object('error', 'superseded'); end if;
  if d.signed_at is null then return jsonb_build_object('error', 'not-signed'); end if;

  -- Verifying twice is verifying once.
  if d.verified_at is not null then
    return jsonb_build_object('ok', true, 'repeat', true, 'confirmed', 0);
  end if;

  -- A letter issued before this change has no mappings, so there is nothing
  -- to confirm and no guess is made. It stays history.
  select count(*) into v_map from public.client_document_services where document_id = p_doc;
  if v_map = 0 or v_map <> coalesce(jsonb_array_length(d.lines), -1) then
    return jsonb_build_object('error', 'no-mapping');
  end if;

  /* What the client signed is the letter's snapshot. A line removed since,
     or one whose quantity, rate, term or adjustment moved since, is not
     what was signed, so nothing is confirmed (audit S4, 2026-10-10): the
     letter is reissued, or the line put back as it was. */
  if exists (select 1 from public.client_document_services m
               join public.client_services cs on cs.id = m.service_id
              where m.document_id = p_doc and cs.archived_at is not null) then
    return jsonb_build_object('error', 'archived-line');
  end if;
  if exists (select 1 from jsonb_array_elements(d.lines) l
               join public.client_services cs on cs.id = (l ->> 'service_id')::uuid
              where l ? 'service_id'
                and ((l ->> 'qty')::numeric is distinct from cs.qty
                  or (l ->> 'rate')::numeric is distinct from cs.rate
                  or (l ->> 'tenure')::int is distinct from greatest(1, coalesce(cs.tenure, 1))
                  or (l ? 'term_adjust' and (l ->> 'term_adjust')::boolean is distinct from coalesce(cs.term_adjust, false))
                  or (l ? 'term_pct' and (l ->> 'term_pct')::numeric is distinct from cs.term_pct))) then
    return jsonb_build_object('error', 'changed-terms');
  end if;

  update public.client_services cs
     set state = 'confirmed'
    from public.client_document_services m
   where m.document_id = p_doc and cs.id = m.service_id
     and cs.archived_at is null and cs.state <> 'confirmed';
  get diagnostics v_n = row_count;

  select * into me from public.team_members where lower(email) = who and active limit 1;
  update public.client_documents
     set verified_at = now(), verified_by = coalesce(me.name, who)
   where id = p_doc;

  select * into cl from public.clients where id = d.client_id;
  insert into public.activity_log (actor, action, subject, detail)
  values (who, 'document.verified', cl.name,
          d.number || ' · ' || v_n || ' line' || case when v_n = 1 then '' else 's' end || ' confirmed');
  return jsonb_build_object('ok', true, 'confirmed', v_n);
end $$;

grant execute on function public.verify_letter(uuid) to authenticated;

create or replace function public.delete_client(p_client uuid, p_code text)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  want text;
  who  text := auth.jwt() ->> 'email';
  cl   public.clients%rowtype;
  me   public.team_members%rowtype;
begin
  if who is null then
    raise exception 'Not signed in';
  end if;

  select value into want from public.app_secrets where key = 'delete_code';

  -- No code set: the interface asks for the client's name instead, and has
  -- already checked it. Nothing more to enforce here.
  if want is not null and want <> '' then
    if p_code is null or p_code <> want then
      return 'wrong-code';
    end if;
  end if;

  select * into cl from public.clients where id = p_client;
  delete from public.clients where id = p_client;
  if not found then
    return 'not-found';
  end if;
  /* Filed here, in the same transaction, never by the page after the answer
     (audit R1, 2026-10-10): a reply lost on the way left no record. */
  select * into me from public.team_members where lower(email) = lower(who) and active limit 1;
  insert into public.activity_log (actor, action, subject, detail)
  values (coalesce(me.name, who), 'client.deleted', cl.name, coalesce(cl.client_code, ''));
  return 'deleted';
end $$;

revoke all on function public.delete_client(uuid, text) from anon;
grant execute on function public.delete_client(uuid, text) to authenticated;

drop policy if exists client_documents_write on public.client_documents;
drop policy if exists client_documents_edit on public.client_documents;
drop policy if exists client_documents_del on public.client_documents;

/* Own clients only narrows Clients and every table under a client, but the
   Activity record is not scoped: it names every client's events. A group
   holds one or the other until the record is scoped (the user, 2026-10-10). */
create or replace function public.team_roles_scope_guard() returns trigger
language plpgsql set search_path = public as $$
begin
  if coalesce(new.client_scope, 'all') = 'own' and not coalesce(new.is_admin, false)
     and (coalesce(new.access ->> 'activity', 'none') <> 'none'
          or exists (select 1 from jsonb_each_text(coalesce(new.access, '{}'::jsonb)) e
                      where e.key like 'activity.%' and e.value <> 'none')) then
    raise exception 'scope-activity'
      using hint = 'Own clients only cannot be given with the Activity record, which is not limited to a colleague''s clients.';
  end if;
  return new;
end $$;
revoke all on function public.team_roles_scope_guard() from public, anon, authenticated;
create or replace trigger team_roles_scope_guard
  before insert or update of access, client_scope, is_admin on public.team_roles
  for each row execute function public.team_roles_scope_guard();

-- END OF LETTERS HELD TO THEIR LINES -------------------------------------------

-- ===========================================================================
-- A SEEN REPORT DELETED — Reports Full Access deletes any report, a published
-- one included: the report, every version and its rows go, and the client's
-- portal no longer lists it (the user, 2026-10-11: "delete permanently =
-- totally gone"). The period is typed back as before.
-- ===========================================================================

/* A report goes with its period typed back, at Reports Full Access. One the
   client has read goes too, with every version (the user, 2026-10-11): it
   leaves the client portal, and the record says it had been published. The
   PDF kept in storage stays, as every stored file does. */
create or replace function public.sm_report_delete(p_id uuid, p_confirm text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.sm_reports;
  word text;
  cname text;
  seen integer;
begin
  if me.id is null or not public.allowed('reports', 'manage') then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_id for update;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  word := public.sm_period_word(r.period_start, r.period_end);
  if lower(btrim(coalesce(p_confirm, ''))) <> lower(word) then return jsonb_build_object('error', 'confirm-mismatch'); end if;
  select count(*) into seen from public.sm_report_versions where report_id = p_id;
  select name into cname from public.clients where id = r.client_id;
  perform set_config('adspace.sm_fn', 'on', true);
  delete from public.sm_reports where id = p_id;
  perform set_config('adspace.sm_fn', 'off', true);
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'report.deleted', cname, word || ' · v' || r.version_no ||
          case when seen > 0 then ' · had been published, ' || seen || case when seen = 1 then ' version' else ' versions' end ||
                                  ' removed from the client portal' else '' end);
  return jsonb_build_object('ok', true, 'versions', seen);
end $$;
revoke all on function public.sm_report_delete(uuid, text) from public, anon;
grant execute on function public.sm_report_delete(uuid, text) to authenticated;

-- END OF A SEEN REPORT DELETED ----------------------------------------------

-- MONTHLY REPORTS NEED PLANNED CONTENT — a client's own monthly Accounts
-- Report is made only for a month in My Work with content planned (the user,
-- 2026-10-11: "0 planned content only allows advertising report"); a
-- white-label client, its own reports and its brands', is held to neither.
--   1. `sm_reports_month_gate` refuses `no-content` for a client's own
--      Accounts Report, not asked for, from October 2026, whose month holds
--      no planned content; an admin or Reports Full Access is held to it too.
--   2. `ops_engagements_accounts_content` refuses ticking the Accounts
--      report on a month with no planned content (`accounts-needs-content`),
--      checked only where the ticks or the plan change; a new month made
--      with no plan leaves the tick it took from the month before.
--   3. `sm_report_months` adds each month's `planned` and the client's
--      `white_label`, so New report greys a month the rule refuses.
-- Rollback: run sm_reports_month_gate and sm_report_months as the REPORTS ON
-- REQUEST section defines them, then drop the trigger
-- ops_engagements_accounts_content and its function.
create or replace function public.sm_reports_month_gate()
returns trigger
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
begin
  if new.brand_id is not null or new.on_request or new.period_start < date '2026-10-01' or me.id is null then return new; end if;
  if new.kind = 'social'
     and not coalesce((select c.white_label from public.clients c where c.id = new.client_id), false)
     and exists (select 1 from public.ops_engagements e
                  cross join lateral public.ops_month_span(e.period, e.start_day) s
                  where e.client_id = new.client_id and e.status <> 'cancelled'
                    and new.period_end between s.starts and s.ends
                    and coalesce(e.planned_count, 0) = 0) then
    raise exception 'no-content' using errcode = 'P0001';
  end if;
  if coalesce(me.is_admin, false) or me.role = 'admin' or public.allowed('reports', 'manage') then return new; end if;
  if exists (select 1 from public.ops_engagements e
              cross join lateral public.ops_month_span(e.period, e.start_day) s
              where e.client_id = new.client_id and e.status <> 'cancelled'
                and new.period_end between s.starts and s.ends
                and new.kind = any (coalesce(e.reports, '{}'::text[]))) then
    return new;
  end if;
  raise exception 'month-gate' using errcode = 'P0001';
end $$;
revoke all on function public.sm_reports_month_gate() from public, anon, authenticated;

create or replace function public.ops_engagements_accounts_content()
returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if not ('social' = any (coalesce(new.reports, '{}'::text[]))) or coalesce(new.planned_count, 0) > 0 then return new; end if;
  if tg_op = 'UPDATE' and new.reports is not distinct from old.reports
     and new.planned_count is not distinct from old.planned_count then return new; end if;
  if coalesce((select c.white_label from public.clients c where c.id = new.client_id), false) then return new; end if;
  /* A new month takes its ticks from the month before: one with no plan
     yet leaves the Accounts Report out rather than failing to be made. */
  if tg_op = 'INSERT' then
    new.reports := array_remove(new.reports, 'social');
    return new;
  end if;
  raise exception using message = jsonb_build_object('error', 'accounts-needs-content')::text;
end $$;
revoke all on function public.ops_engagements_accounts_content() from public, anon, authenticated;

create or replace trigger ops_engagements_accounts_content
  before insert or update on public.ops_engagements
  for each row execute function public.ops_engagements_accounts_content();

create or replace function public.sm_report_months(p_client uuid, p_kind text default 'social')
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  c public.clients;
begin
  if me.id is null or not public.allowed('reports', 'view') then return jsonb_build_object('error', 'denied'); end if;
  if coalesce(p_kind, '') not in ('social', 'ads') then return jsonb_build_object('error', 'bad-kind'); end if;
  select * into c from public.clients where id = p_client;
  if c.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if not public.client_row_seen(c.stage, c.owner, 'view') then return jsonb_build_object('error', 'denied'); end if;
  return jsonb_build_object(
    'may_override', coalesce(me.is_admin, false) or me.role = 'admin' or public.allowed('reports', 'manage'),
    'white_label', coalesce(c.white_label, false),
    'months', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', e.id, 'period', e.period, 'start_day', e.start_day,
               'starts', s.starts, 'ends', s.ends, 'status', e.status,
               'asks', p_kind = any (coalesce(e.reports, '{}'::text[])),
               'planned', coalesce(e.planned_count, 0),
               'report', (select r.id from public.sm_reports r
                           where r.client_id = e.client_id and r.kind = p_kind and r.brand_id is null
                             and not r.on_request and r.period_end between s.starts and s.ends
                           order by r.period_start desc limit 1))
             order by e.period desc)
        from public.ops_engagements e
       cross join lateral public.ops_month_span(e.period, e.start_day) s
       where e.client_id = p_client and e.status <> 'cancelled'), '[]'::jsonb));
end $$;
-- END OF MONTHLY REPORTS NEED PLANNED CONTENT -------------------------------

-- ===========================================================================
-- PRIORITY DEADLINES — a priority is a deadline from the moment it is set:
-- Urgent within 24 hours, High within 48, Medium within 72; Normal has none
-- (the user, 2026-10-11).
-- 2026-10-11. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/smsql.js compares the
-- two. Runs after REACH ALLOWANCE, whose settings it keeps.
--
-- WHAT CHANGED
--   1. Low is retired: on the first run alone, every task at Low (4, or the
--      older 5) becomes Normal (3). Medium then takes 4, which the task
--      functions already accept (1 to 4); Urgent 1, High 2 and Normal 3 keep
--      their keys. The first run is known by the settings below not yet being
--      there, so a second run never turns a Medium task back to Normal.
--   2. `priority_urgent_hours` (24), `priority_high_hours` (48) and
--      `priority_medium_hours` (72) are Business settings, whole hours from 1
--      to 720, from a day on. `app_settings_set` takes them, filed
--      "High deadline: 48 hours → 36 hours · from …".
--   3. `ops_tasks.priority_at` is when the priority was last set, stamped by
--      trigger `ops_tasks_priority_at` (on creation, and on every change of
--      level; a task from before takes its creation). The deadline counts
--      from it (a task made Normal on the 1st, due the 29th, raised to High on
--      the 12th at 9am, is owed by the 14th at 9am) and is never written: the
--      due date is never changed, and the count stops once the task reaches
--      client review (an everyday task's Review). `ops_priority_by(set at,
--      level)` gives the moment it falls.
--   4. A task is late by whichever deadline comes first (the user,
--      2026-10-11): `ops_report` counts a task past its priority's deadline
--      and short of its review as late beside the due date's rule (the late
--      list with `over_minutes`, open work by person), and on time only
--      where it met both (on time delivery, by person); the performance
--      review's hint, `perf_ops_rate`, reads the same.
--
-- ROLLBACK
--   Run app_settings_set from REACH ALLOWANCE, and ops_report and
--   perf_ops_rate from their own latest sections, again; ops_priority_by, the column priority_at and its
--   trigger may stay (nothing else reads them); the three settings rows may
--   stay. A task made Medium reads as Low on a page from before; tasks
--   that were Low stay Normal (none were Low on 2026-10-11).
-- ===========================================================================

alter table public.ops_tasks add column if not exists priority_at timestamptz;
update public.ops_tasks set priority_at = created_at where priority_at is null;

do $$
begin
  if not exists (select 1 from public.app_settings s where s.key = 'priority_medium_hours') then
    update public.ops_tasks set priority_level = 3 where priority_level in (4, 5);
  end if;
end $$;

insert into public.app_settings (key, from_date, value)
select 'priority_urgent_hours', date '2023-08-14', 24
 where not exists (select 1 from public.app_settings s where s.key = 'priority_urgent_hours');
insert into public.app_settings (key, from_date, value)
select 'priority_high_hours', date '2023-08-14', 48
 where not exists (select 1 from public.app_settings s where s.key = 'priority_high_hours');
insert into public.app_settings (key, from_date, value)
select 'priority_medium_hours', date '2023-08-14', 72
 where not exists (select 1 from public.app_settings s where s.key = 'priority_medium_hours');

create or replace function public.app_settings_set(p_from date, p_values jsonb)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me public.team_members; v_k text; v_v numeric; v_was numeric; v_name text; v_unit text;
  v_today date := (now() at time zone 'Asia/Kuala_Lumpur')::date;
  v_keys constant text[] := array['lead_followup_hours', 'proposal_followup_days', 'sst_pct',
    'term_1_3', 'term_4_5', 'term_6_11', 'term_12_23', 'term_24', 'report_due_days', 'revision_due_days',
    'ai_price_in', 'ai_price_out', 'meta_checks', 'approval_reminder_days', 'ai_price_search',
    'reach_allowance_pct', 'priority_urgent_hours', 'priority_high_hours', 'priority_medium_hours'];
  v_moved text[] := '{}';
begin
  if not public.ops_granted('team.settings', 'work') then return jsonb_build_object('error', 'denied'); end if;
  v_me := public.ops_me();
  if p_from is null or p_from < v_today then return jsonb_build_object('error', 'past', 'today', v_today); end if;
  if jsonb_typeof(p_values) is distinct from 'object' then return jsonb_build_object('error', 'bad-value'); end if;
  for v_k in select jsonb_object_keys(p_values) loop
    if not (v_k = any(v_keys)) or jsonb_typeof(p_values -> v_k) <> 'number' then
      return jsonb_build_object('error', 'bad-value', 'key', v_k);
    end if;
    v_v := (p_values ->> v_k)::numeric;
    if round(v_v, 2) <> v_v
       or (v_k = 'lead_followup_hours' and (v_v < 1 or v_v > 720 or v_v <> trunc(v_v)))
       or (v_k = 'proposal_followup_days' and (v_v < 1 or v_v > 365 or v_v <> trunc(v_v)))
       or (v_k = 'report_due_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'revision_due_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'approval_reminder_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'sst_pct' and (v_v < 0 or v_v > 100))
       or (v_k like 'term_%' and (v_v < -100 or v_v > 100))
       or (v_k like 'ai_price_%' and (v_v < 0 or v_v > 1000))
       or (v_k = 'meta_checks' and v_v not in (0, 1))
       or (v_k = 'reach_allowance_pct' and (v_v < 0 or v_v > 5))
       or (v_k like 'priority_%_hours' and (v_v < 1 or v_v > 720 or v_v <> trunc(v_v))) then
      return jsonb_build_object('error', 'bad-value', 'key', v_k);
    end if;
  end loop;
  for v_k in select jsonb_object_keys(p_values) loop
    v_v := (p_values ->> v_k)::numeric;
    v_was := public.app_setting(v_k, p_from);
    if v_was is distinct from v_v then
      insert into public.app_settings (key, from_date, value, set_by, set_at)
      values (v_k, p_from, v_v, v_me.id, now())
      on conflict (key, from_date) do update set value = excluded.value, set_by = excluded.set_by, set_at = now();
      v_name := case v_k when 'lead_followup_hours' then 'A lead waits' when 'proposal_followup_days' then 'A proposal waits'
        when 'sst_pct' then 'SST' when 'term_1_3' then '1 to 3 months' when 'term_4_5' then '4 and 5 months'
        when 'term_6_11' then '6 to 11 months' when 'term_12_23' then '12 to 23 months' when 'term_24' then '24 months and more'
        when 'revision_due_days' then 'Revision due' when 'ai_price_in' then 'AI input, a million tokens'
        when 'ai_price_out' then 'AI output, a million tokens' when 'ai_price_search' then 'AI web searches, a thousand' when 'meta_checks' then 'Meta checks'
        when 'approval_reminder_days' then 'Approval reminder' when 'reach_allowance_pct' then 'Reach allowance'
        when 'priority_urgent_hours' then 'Urgent deadline' when 'priority_high_hours' then 'High deadline'
        when 'priority_medium_hours' then 'Medium deadline' else 'Report due' end;
      v_unit := case when v_k = 'lead_followup_hours' or v_k like 'priority_%_hours' then ' hours' when v_k in ('proposal_followup_days', 'report_due_days', 'revision_due_days', 'approval_reminder_days') then ' days'
        else '%' end;
      insert into public.activity_log (actor, action, subject, detail)
      values (coalesce(v_me.name, 'admin'), 'team.changed', 'Settings',
              v_name || ': ' || case when v_k = 'meta_checks' then
                case when v_was = 1 then 'On' else 'Off' end || ' → ' || case when v_v = 1 then 'On' else 'Off' end ||
                ' · from ' || public.register_day(p_from) else '' end ||
              case when v_k = 'meta_checks' then '' else case when v_k like 'ai_price_%' then 'US$' else '' end ||
              trim(to_char(v_was, 'FM999999990.99'), '.') || case when v_k like 'ai_price_%' then '' else v_unit end || ' → ' ||
              case when v_k like 'ai_price_%' then 'US$' else '' end ||
              trim(to_char(v_v, 'FM999999990.99'), '.') || case when v_k like 'ai_price_%' then '' else v_unit end ||
              ' · from ' || public.register_day(p_from) end);
      v_moved := v_moved || v_k;
    end if;
  end loop;
  return public.app_settings_read() || jsonb_build_object('changed', to_jsonb(v_moved));
end $$;
revoke all on function public.app_settings_set(date, jsonb) from public, anon;


/* When the priority was set: on creation, and again on every change of
   level, by the database's clock. */
create or replace function public.ops_tasks_priority_at()
returns trigger
language plpgsql set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    new.priority_at := coalesce(new.priority_at, new.created_at, now());
  elsif new.priority_level is distinct from old.priority_level then
    new.priority_at := now();
  end if;
  return new;
end $$;
revoke all on function public.ops_tasks_priority_at() from public, anon, authenticated;

create or replace trigger ops_tasks_priority_at
  before insert or update of priority_level on public.ops_tasks
  for each row execute function public.ops_tasks_priority_at();

/* The moment a priority's deadline falls: when it was set plus the hours
   its level held on that day (Malaysia time); null for Normal. The report's
   late and on time read it; the page works out the same (js/ops.js
   `deadlineOf`). */
create or replace function public.ops_priority_by(p_set timestamptz, p_level smallint)
returns timestamptz
language sql stable security definer set search_path = public as $$
  select p_set + make_interval(hours => coalesce(public.app_setting(
           'priority_' || case p_level when 1 then 'urgent' when 2 then 'high' else 'medium' end || '_hours',
           (p_set at time zone 'Asia/Kuala_Lumpur')::date),
           case p_level when 1 then 24 when 2 then 48 else 72 end)::integer)
   where p_level in (1, 2, 4) and p_set is not null
$$;
revoke all on function public.ops_priority_by(timestamptz, smallint) from public, anon, authenticated;

create or replace function public.ops_report(
  p_from timestamptz default (now() - interval '90 days'),
  p_to   timestamptz default now())
returns jsonb
language plpgsql security definer stable set search_path = public as $$
declare
  out jsonb;
begin
  if not public.ops_granted('ops.reports', 'view') then
    return jsonb_build_object('error', 'denied');
  end if;

  with
  /* Where client review begins in each workflow. The final due date is the
     day the work is owed AT that stage, so everything below that position is
     "has not reached the client yet". Read from `stage_group` and never from
     a stage key: the two seeded workflows name that stage differently. */
  floors as (
    select workflow_id, min(position) as at
      from public.ops_workflow_stages
     where stage_group = 'client_review'
     group by workflow_id
  ),
  /* Where a priority's deadline is met (2026-10-11): client review, else the
     workflow's first review (an everyday task's Review). */
  pfloors as (
    select workflow_id,
           coalesce(min(position) filter (where stage_group = 'client_review'),
                    min(position) filter (where stage_group = 'internal_review')) as at
      from public.ops_workflow_stages
     group by workflow_id
  ),
  live as (
    select t.*, s.label as stage_label, s.position as stage_position,
           s.stage_group, f.at as review_at,
           public.ops_priority_by(coalesce(t.priority_at, t.created_at), t.priority_level) as prio_by, pf.at as prio_at
      from public.ops_tasks t
      join public.ops_workflow_stages s
        on s.workflow_id = t.workflow_id and s.key = t.stage_key
      left join floors f on f.workflow_id = t.workflow_id
      left join pfloors pf on pf.workflow_id = t.workflow_id
     where t.completed_at is null and t.cancelled_at is null
       and t.archived_at is null
  ),

  /* 1. WHAT IS RUNNING, by the words on the screen. Grouped by the stage's
        own label rather than by its group, because "what is on shooting" is
        the question and Shooting is a label, not a group. */
  running as (
    select jsonb_agg(x order by x ->> 'position', x ->> 'label') as j from (
      select jsonb_build_object(
               'stage_key', stage_key, 'label', stage_label,
               'position', stage_position, 'stage_group', stage_group,
               'count', count(*)) as x
        from live
       group by stage_key, stage_label, stage_position, stage_group
    ) q
  ),

  /* 2. WHAT IS LATE. Past the commitment and still short of client review,
        or past a priority's deadline and short of its review (On hold and
        Blocked still count): whichever comes first (the user, 2026-10-11).
        The same rule the queue row draws, stated once more here because a
        report a page computes for itself is a second definition. */
  late_now as (
    select l.*,
           (l.current_final_due_at is not null and l.current_final_due_at::date < current_date
            and (l.review_at is null or l.stage_position < l.review_at)) as due_late,
           (l.prio_by is not null and l.prio_by < now()
            and (l.prio_at is null or l.stage_position < l.prio_at or l.stage_group in ('kiv', 'blocked'))) as prio_late
      from live l
  ),
  late as (
    select jsonb_agg(x order by x ->> 'due_at') as j from (
      select jsonb_build_object(
               'task_id', l.id, 'task_no', l.task_no, 'title', l.title,
               'client', c.name, 'stage', l.stage_label,
               'due_at', case when l.prio_late and (not l.due_late or l.prio_by < l.current_final_due_at)
                              then l.prio_by else l.current_final_due_at end,
               'days_over', greatest(case when l.due_late then current_date - l.current_final_due_at::date end,
                                     case when l.prio_late then floor(extract(epoch from (now() - l.prio_by)) / 86400)::int end),
               'over_minutes', case when l.prio_late then floor(extract(epoch from (now() - l.prio_by)) / 60)::int end,
               'owner', (select tm.name
                           from public.ops_task_assignees a
                           join public.team_members tm on tm.id = a.team_member_id
                          where a.task_id = l.id and a.responsibility = 'owner'
                            and a.ended_at is null
                          limit 1)) as x
        from late_now l
        left join public.clients c on c.id = l.client_id
       where l.due_late or l.prio_late
    ) q
  ),

  /* 3. HOW LONG EACH STAGE TAKES. A task enters a stage at the event that
        names it and leaves at the next event, or at its own ending, or now.
        Only spans that were ENTERED inside the period are counted, so the
        window means what it says and a task that sat in Editing since March
        does not land in every report for ever. */
  spans as (
    select e.task_id,
           e.to_value ->> 'stage_key' as stage_key,
           e.created_at as from_at,
           coalesce(
             lead(e.created_at) over (partition by e.task_id order by e.created_at),
             t.completed_at, t.cancelled_at, now()) as to_at
      from public.ops_task_events e
      join public.ops_tasks t on t.id = e.task_id
     where e.event_type in ('task_created', 'stage_changed')
       and e.to_value ->> 'stage_key' is not null
  ),
  /* One row per span and no grouping: an earlier draft grouped by the span's
     own timestamps, which silently collapsed two tasks that entered the same
     stage in the same instant into one measurement. The label is looked up
     once per stage below instead of aggregated here. */
  span_mins as (
    select s.stage_key,
           extract(epoch from (s.to_at - s.from_at)) / 60 as mins
      from spans s
     where s.from_at >= p_from and s.from_at < p_to
       and s.to_at > s.from_at
  ),
  stage_time as (
    select jsonb_agg(x order by x ->> 'label') as j from (
      select jsonb_build_object(
               'stage_key', stage_key,
               'label', coalesce((select w.label from public.ops_workflow_stages w
                                   where w.key = sm.stage_key limit 1), stage_key),
               'n', count(*),
               'median_minutes', round(percentile_cont(0.5) within group (order by mins))::int,
               'p90_minutes', round(percentile_cont(0.9) within group (order by mins))::int) as x
        from span_mins sm
       group by stage_key
    ) q
  ),

  /* 4. WAS IT THERE ON TIME. Of the tasks that reached client review inside
        the period, how many got there on or before the date they were owed.
        Replanning is counted beside it and never folded into it: an extension
        that moves the date would otherwise erase the miss it was granted for,
        and a rate that cannot be missed is not a measurement. */
  reached as (
    select distinct on (e.task_id)
           e.task_id, e.created_at as at, t.current_final_due_at as due,
           public.ops_priority_by(coalesce(t.priority_at, t.created_at), t.priority_level) as prio_by,
           (t.original_final_due_at is distinct from t.current_final_due_at) as replanned
      from public.ops_task_events e
      join public.ops_tasks t on t.id = e.task_id
      join public.ops_workflow_stages w
        on w.workflow_id = t.workflow_id and w.key = e.to_value ->> 'stage_key'
     where e.event_type = 'stage_changed'
       and w.stage_group = 'client_review'
       and e.created_at >= p_from and e.created_at < p_to
     order by e.task_id, e.created_at
  ),
  on_time as (
    select jsonb_build_object(
             'reached', count(*),
             'met', count(*) filter (where (due is null or at::date <= due::date) and (prio_by is null or at <= prio_by)),
             'missed', count(*) filter (where not ((due is null or at::date <= due::date) and (prio_by is null or at <= prio_by))),
             'replanned', count(*) filter (where replanned)) as j
      from reached
  ),

  /* 5. BY PERSON. The foundation of a KPI and not a KPI: what somebody
        finished in the window, how much of it was on time, and how long their
        work took end to end. No ranking and no score — a number a person can
        check is worth more than a league table nobody trusts. */
  done as (
    select t.id, t.created_at, coalesce(t.completed_at, t.delivered_at) as ended,
           t.current_final_due_at as due,
           public.ops_priority_by(coalesce(t.priority_at, t.created_at), t.priority_level) as prio_by,
           /* When a priority's deadline was met: the first move into its
              review or beyond (never On hold, Blocked or Cancelled). */
           (select min(e.created_at)
              from public.ops_task_events e
              join public.ops_workflow_stages w
                on w.workflow_id = t.workflow_id and w.key = e.to_value ->> 'stage_key'
              join pfloors pf on pf.workflow_id = t.workflow_id
             where e.task_id = t.id and e.event_type = 'stage_changed'
               and w.position >= pf.at and w.stage_group not in ('kiv', 'blocked', 'cancelled')) as met_at,
           (select a.team_member_id
              from public.ops_task_assignees a
             where a.task_id = t.id and a.responsibility = 'owner'
             order by a.ended_at nulls first, a.assigned_at desc
             limit 1) as owner_id
      from public.ops_tasks t
     where t.completed_at is not null
       and t.completed_at >= p_from and t.completed_at < p_to
  ),
  by_person as (
    select jsonb_agg(x order by x ->> 'name') as j from (
      select jsonb_build_object(
               'team_member_id', d.owner_id,
               'name', coalesce(tm.name, 'Nobody'),
               'completed', count(*),
               'on_time', count(*) filter (where (d.due is null or d.ended::date <= d.due::date)
                                         and (d.prio_by is null or coalesce(d.met_at, d.ended) <= d.prio_by)),
               'median_cycle_minutes',
                 round(percentile_cont(0.5) within group (
                   order by extract(epoch from (d.ended - d.created_at)) / 60))::int) as x
        from done d
        left join public.team_members tm on tm.id = d.owner_id
       group by d.owner_id, tm.name
    ) q
  ),

  /* 6. WHO IS CARRYING THE OPEN WORK (2026-09-28). One row a Task Owner:
        the open tasks they hold, and how many of those are late by the rule
        in 2 above. The team's whole queue is `ops.all`, so it is answered
        only where that part is granted. */
  open_by_person as (
    select jsonb_agg(x order by (x ->> 'open')::int desc, x ->> 'name') as j from (
      select jsonb_build_object(
               'team_member_id', o.owner_id,
               'name', coalesce(tm.name, 'No task owner'),
               'open', count(*),
               'late', count(*) filter (where o.is_late)) as x
        from (select l.id,
                     (select a.team_member_id
                        from public.ops_task_assignees a
                       where a.task_id = l.id and a.responsibility = 'owner' and a.ended_at is null
                       limit 1) as owner_id,
                     (l.due_late or l.prio_late) as is_late
                from late_now l) o
        left join public.team_members tm on tm.id = o.owner_id
       where public.ops_granted('ops.all', 'view')
       group by o.owner_id, tm.name
    ) q
  )

  select jsonb_build_object(
           'from', p_from, 'to', p_to,
           'running',    coalesce((select j from running), '[]'::jsonb),
           'late',       coalesce((select j from late), '[]'::jsonb),
           'stage_time', coalesce((select j from stage_time), '[]'::jsonb),
           'on_time',    coalesce((select j from on_time), '{}'::jsonb),
           'by_person',  coalesce((select j from by_person), '[]'::jsonb),
           'open_by_person', case when public.ops_granted('ops.all', 'view')
                                  then coalesce((select j from open_by_person), '[]'::jsonb) end)
    into out;

  return out;
end $$;
grant execute on function public.ops_report(timestamptz, timestamptz) to authenticated;

/* What My Work already knows, for the reviewer: the tasks this person owned
   that were finished in the month with a deadline, and how many were on time
   by the rule the report reads (the user, 2026-10-11): finished by the due
   date's day and, where a priority set a deadline, at its review by that. A
   hint for the reviewer, never a score. */
create or replace function public.perf_ops_rate(p_member uuid, p_period date)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare d integer; o integer;
begin
  if to_regclass('public.ops_tasks') is null then return null; end if;
  select count(*),
         count(*) filter (where (x.due is null or x.ended::date <= x.due::date)
                            and (x.prio_by is null or coalesce(x.met_at, x.ended) <= x.prio_by))
    into d, o
    from (select t.current_final_due_at as due, coalesce(t.completed_at, t.delivered_at) as ended,
                 public.ops_priority_by(coalesce(t.priority_at, t.created_at), t.priority_level) as prio_by,
                 (select min(e.created_at)
                    from public.ops_task_events e
                    join public.ops_workflow_stages w
                      on w.workflow_id = t.workflow_id and w.key = e.to_value ->> 'stage_key'
                   where e.task_id = t.id and e.event_type = 'stage_changed'
                     and w.stage_group not in ('kiv', 'blocked', 'cancelled')
                     and w.position >= coalesce(
                       (select min(s.position) from public.ops_workflow_stages s
                         where s.workflow_id = t.workflow_id and s.stage_group = 'client_review'),
                       (select min(s.position) from public.ops_workflow_stages s
                         where s.workflow_id = t.workflow_id and s.stage_group = 'internal_review'))) as met_at
            from public.ops_tasks t
           where t.completed_at >= p_period and t.completed_at < (p_period + interval '1 month')
             and (select a.team_member_id from public.ops_task_assignees a
                   where a.task_id = t.id and a.responsibility = 'owner'
                   order by a.ended_at nulls first, a.assigned_at desc limit 1) = p_member) x
   where x.due is not null or x.prio_by is not null;
  return jsonb_build_object('done', d, 'on_time', o);
end $$;
revoke all on function public.perf_ops_rate(uuid, date) from public, anon, authenticated;

-- END OF PRIORITY DEADLINES -------------------------------------------------

-- ===========================================================================
-- THE REVIEW'S MY WORK FIGURES — what My Work already knows, beside the two
-- delivery rates a reviewer types (the user, 2026-10-11: "add timeline
-- adherence next").
-- 2026-10-11. Safe to run twice. Rollback below. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/ops.js compares the
-- two. Runs after PRIORITY DEADLINES, whose `ops_priority_by` it reads.
--
-- WHAT CHANGED
--   `perf_ops_rate(member, month)` answers two figures, each a hint beside
--   its rate and never a score:
--   1. posting (On-time posting): the content tasks the colleague owns whose
--      post date fell in the month, MYT, and has passed (or that went live),
--      and how many went live by their post date's day; a cancelled task is
--      left out. Before, this rate's hint counted tasks finished by their due
--      date, which is the timeline's question.
--   2. timeline (Timeline adherence): the tasks the colleague owns that
--      reached their review in the month, MYT, and how many got there by
--      their deadline, whichever came first (the rule My Work's late reads):
--      the due date's day at client review (an everyday task's at its
--      finish) and a priority's deadline at its review.
--   It answers `{posting: {due, on_time}, timeline: {reached, met}}` in
--   place of `{done, on_time}`: a page from before finds no `done` and draws
--   no hint, and this page finds no `posting` on a database from before and
--   draws none.
--
-- ROLLBACK
--   Run perf_ops_rate from PRIORITY DEADLINES again.
-- ===========================================================================

/* The review's My Work figures (2026-10-11). Who owns a task is its owner of
   record (the open assignment, else the last), as the hint read before. */
create or replace function public.perf_ops_rate(p_member uuid, p_period date)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  m_from timestamptz := (date_trunc('month', p_period)::date)::timestamp at time zone 'Asia/Kuala_Lumpur';
  m_to   timestamptz := ((date_trunc('month', p_period) + interval '1 month')::date)::timestamp at time zone 'Asia/Kuala_Lumpur';
  today  date := (now() at time zone 'Asia/Kuala_Lumpur')::date;
  p_due integer; p_ok integer; t_reached integer; t_met integer;
begin
  if to_regclass('public.ops_tasks') is null then return null; end if;

  select count(*),
         count(*) filter (where t.live_at is not null
                            and (t.live_at at time zone 'Asia/Kuala_Lumpur')::date
                                <= (t.publish_at at time zone 'Asia/Kuala_Lumpur')::date)
    into p_due, p_ok
    from public.ops_tasks t
   where t.publish_at >= m_from and t.publish_at < m_to
     and t.cancelled_at is null
     and (t.live_at is not null or (t.publish_at at time zone 'Asia/Kuala_Lumpur')::date < today)
     and exists (select 1 from public.ops_workflow_stages s
                  where s.workflow_id = t.workflow_id and s.stage_group = 'live')
     and (select a.team_member_id from public.ops_task_assignees a
           where a.task_id = t.id and a.responsibility = 'owner'
           order by a.ended_at nulls first, a.assigned_at desc limit 1) = p_member;

  with owned as (
    select t.id, t.workflow_id, t.current_final_due_at as due,
           coalesce(t.completed_at, t.delivered_at) as ended,
           public.ops_priority_by(coalesce(t.priority_at, t.created_at), t.priority_level) as prio_by,
           (select min(s.position) from public.ops_workflow_stages s
             where s.workflow_id = t.workflow_id and s.stage_group = 'client_review') as review_at,
           (select min(s.position) from public.ops_workflow_stages s
             where s.workflow_id = t.workflow_id and s.stage_group = 'internal_review') as first_review_at
      from public.ops_tasks t
     where t.cancelled_at is null
       and (t.current_final_due_at is not null or t.priority_level in (1, 2, 4))
       and (select a.team_member_id from public.ops_task_assignees a
             where a.task_id = t.id and a.responsibility = 'owner'
             order by a.ended_at nulls first, a.assigned_at desc limit 1) = p_member
  ),
  /* When each deadline was met: the first move to its stage or beyond, never
     into On hold, Blocked or Cancelled. The due date's is client review, else
     the finish; a priority's is client review, else the first review. */
  marks as (
    select o.*,
           case when o.review_at is null then o.ended
                else coalesce((select min(e.created_at)
                                 from public.ops_task_events e
                                 join public.ops_workflow_stages w
                                   on w.workflow_id = o.workflow_id and w.key = e.to_value ->> 'stage_key'
                                where e.task_id = o.id and e.event_type = 'stage_changed'
                                  and w.position >= o.review_at
                                  and w.stage_group not in ('kiv', 'blocked', 'cancelled')), o.ended) end as due_met,
           coalesce((select min(e.created_at)
                       from public.ops_task_events e
                       join public.ops_workflow_stages w
                         on w.workflow_id = o.workflow_id and w.key = e.to_value ->> 'stage_key'
                      where e.task_id = o.id and e.event_type = 'stage_changed'
                        and w.position >= coalesce(o.review_at, o.first_review_at)
                        and w.stage_group not in ('kiv', 'blocked', 'cancelled')), o.ended) as prio_met
      from owned o
  ),
  /* A task is counted in the month it met the last of its deadlines. */
  settled as (
    select m.*,
           case when (m.due is null or m.due_met is not null)
                 and (m.prio_by is null or m.prio_met is not null)
                then greatest(case when m.due is not null then m.due_met end,
                              case when m.prio_by is not null then m.prio_met end) end as at
      from marks m
  )
  select count(*),
         count(*) filter (where (s.due is null
                                 or (s.due_met at time zone 'Asia/Kuala_Lumpur')::date
                                    <= (s.due at time zone 'Asia/Kuala_Lumpur')::date)
                            and (s.prio_by is null or s.prio_met <= s.prio_by))
    into t_reached, t_met
    from settled s
   where s.at >= m_from and s.at < m_to;

  return jsonb_build_object(
    'posting',  jsonb_build_object('due', p_due, 'on_time', p_ok),
    'timeline', jsonb_build_object('reached', t_reached, 'met', t_met));
end $$;
revoke all on function public.perf_ops_rate(uuid, date) from public, anon, authenticated;

-- END OF THE REVIEW'S MY WORK FIGURES ---------------------------------------

-- ===========================================================================
-- PIECES OF THEIR OWN — each new content piece may name who it is assigned
-- to, its priority and its type; the sheet's shared ones stand where it names
-- none.
-- 2026-10-12. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/ops.js (§50) compares
-- the two. Runs after PIECE DATES REQUIRED.
--
-- WHAT CHANGED (the user, 2026-10-12: "Imagine i have 7 posts (6 retainers 1
-- adhoc) each have different dues different handling person, different
-- urgency and of course i have to set each different right")
--   1. `ops_create_pieces` reads `owner_id`, `priority_level` and `task_type`
--      on each piece, each over the payload's shared value; a piece naming
--      none takes the shared one as before, so a page loaded before this
--      file works unchanged. Every other rule stands: the three dates, 1 to
--      60 pieces, all or none, the same press twice the same act, and each
--      piece through `ops_create_task`, which checks the type and the plan.
--
-- ORDER
--   Apply before the page that sends a type, an owner and a priority on each
--   piece: a database without it would give every piece the first one's.
--
-- ROLLBACK
--   Run ops_create_pieces from PIECE DATES REQUIRED again.
-- ===========================================================================

/* The New sheet's one act: the pieces, each through ops_create_task, and the
   repeat on every one of them, all or none; each piece with its three dates
   and, where it names them, its own type, owner and priority. */
create or replace function public.ops_create_pieces(p_payload jsonb, p_idem text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m      public.team_members;
  n      integer;
  pc     jsonb;
  i      integer := 0;
  w      integer;
  k      integer;
  inweek integer;
  per    text;
  first_day date;
  last_off integer;
  spread boolean;
  base   jsonb;
  one    jsonb;
  made   jsonb := '[]'::jsonb;
  rep    jsonb;
  rule   jsonb;
  ids    uuid[] := '{}';
  gen    jsonb := '[]'::jsonb;
  pp     text;
  said   text;
begin
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if not public.allowed('ops', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if jsonb_typeof(p_payload -> 'pieces') is distinct from 'array' then
    return jsonb_build_object('error', 'bad-count');
  end if;
  n := jsonb_array_length(p_payload -> 'pieces');
  if n < 1 or n > 60 then return jsonb_build_object('error', 'bad-count'); end if;
  rep := case when jsonb_typeof(p_payload -> 'repeat') = 'object' then p_payload -> 'repeat' end;
  if rep is not null then
    if coalesce(rep ->> 'frequency', '') not in ('weekly', 'monthly', 'custom') then
      return jsonb_build_object('error', 'bad-frequency');
    end if;
    if rep ->> 'frequency' = 'custom' and coalesce((rep ->> 'interval_days')::integer, 0) < 1 then
      return jsonb_build_object('error', 'interval-required');
    end if;
  end if;

  /* What every piece shares: whose it is and which month. A piece names its
     own description, format, week and dates, and may name its own type,
     owner and priority; the shared ones stand where it names none (a page
     from before sends them once). Only a sheet's one piece carries a brief. */
  base := jsonb_strip_nulls(jsonb_build_object(
    'scope', p_payload ->> 'scope', 'client_id', p_payload ->> 'client_id',
    'engagement_id', p_payload ->> 'engagement_id',
    'code_period', p_payload ->> 'code_period',
    'task_type', p_payload ->> 'task_type',
    'owner_id', p_payload ->> 'owner_id',
    'priority_level', p_payload -> 'priority_level',
    'complexity', p_payload ->> 'complexity',
    'description', case when n = 1 then p_payload ->> 'description' end));
  per := p_payload ->> 'code_period';
  if per ~ '^\d{4}-\d{2}$' and coalesce(p_payload ->> 'scope', 'client') <> 'internal' then
    first_day := (per || '-01')::date;
    last_off := ((first_day + interval '1 month')::date - first_day) - 1;
  end if;
  /* Only a repeat needs a day to count from; plain pieces take the dates
     typed on their rows and nothing else. */
  spread := first_day is not null and rep is not null;
  base := base || jsonb_build_object('dates_as_given', true);

  begin
    for pc in select x from jsonb_array_elements(p_payload -> 'pieces') x loop
      i := i + 1;
      w := least(5, greatest(1, coalesce((pc ->> 'code_week')::integer, 1)));
      one := base || jsonb_strip_nulls(jsonb_build_object(
        'content_desc', nullif(btrim(coalesce(pc ->> 'content_desc', '')), ''),
        'deliverable_type', nullif(pc ->> 'deliverable_type', ''),
        'code_week', case when first_day is not null then w end,
        'task_type', nullif(pc ->> 'task_type', ''),
        'owner_id', nullif(pc ->> 'owner_id', ''),
        'priority_level', case when jsonb_typeof(pc -> 'priority_level') = 'number'
                               then pc -> 'priority_level' end));
      /* Every piece carries the three dates typed on its row: the draft
         due (ready for AQC review), the due date (to the client) and the
         post date (2026-10-06). */
      one := one || jsonb_strip_nulls(jsonb_build_object(
        'first_draft_due_at', nullif(pc ->> 'first_draft_due_at', ''),
        'final_due_at', nullif(pc ->> 'final_due_at', ''),
        'publish_at', nullif(pc ->> 'publish_at', '')));
      /* None of the three may be left blank (2026-10-09): a piece without
         its dates is refused by its place, and nothing is made. */
      if not (one ? 'first_draft_due_at' and one ? 'final_due_at' and one ? 'publish_at') then
        raise exception using message = jsonb_build_object('error', 'dates-required', 'piece', i)::text;
      end if;
      /* A tentative day inside the piece's week, the week's pieces spread
         across its seven days, so the calendar has somewhere to put each one
         and a repeat a day to count from; the content meeting fixes the real
         date. Never past the month's last day, which only week 5 reaches. */
      if spread and not (one ? 'publish_at') then
        select count(*) filter (where least(5, greatest(1, coalesce((y ->> 'code_week')::integer, 1))) = w),
               count(*) filter (where least(5, greatest(1, coalesce((y ->> 'code_week')::integer, 1))) = w and o < i)
          into inweek, k
          from jsonb_array_elements(p_payload -> 'pieces') with ordinality as a(y, o);
        one := one || jsonb_build_object('publish_at',
          (first_day + least((w - 1) * 7 + (k * 7) / greatest(inweek, 1), last_off))::timestamptz);
      end if;
      one := public.ops_create_task(one, case when p_idem is null then null else p_idem || ':' || i end);
      if one ? 'error' then raise exception using message = one::text; end if;
      made := made || jsonb_build_object('id', one ->> 'id', 'code', one ->> 'code', 'title', one ->> 'title');
      ids := ids || (one ->> 'id')::uuid;
      if rep is not null then
        rule := public.ops_set_recurring((one ->> 'id')::uuid, jsonb_strip_nulls(jsonb_build_object(
          'frequency', rep ->> 'frequency',
          'interval_days', case when rep ->> 'frequency' = 'custom' then rep -> 'interval_days' end,
          'ends_on', nullif(rep ->> 'ends_on', ''),
          'max_count', rep -> 'max_count')));
        if rule ? 'error' then raise exception using message = rule::text; end if;
      end if;
    end loop;
  exception when raise_exception then
    /* A refusal part way leaves nothing behind: the block's writes are
       undone and the refusal is answered as it was given. */
    said := sqlerrm;
    begin
      return said::jsonb;
    exception when others then
      return jsonb_build_object('error', said);
    end;
  end;

  /* What the new rules already owe is made now rather than tomorrow morning. */
  if rep is not null then
    foreach pp in array public.ops_recurring_periods() loop
      gen := gen || public.ops_generate_recurring(pp,
        array(select r.id from public.ops_recurring_rules r where r.active and r.source_task_id = any (ids)));
    end loop;
  end if;
  return jsonb_build_object('count', n, 'tasks', made, 'repeats', gen);
end $$;
grant execute on function public.ops_create_pieces(jsonb, text) to authenticated;

-- END OF PIECES OF THEIR OWN -------------------------------------------------

-- ===========================================================================
-- REVIEW LINK PREVIEW — the words a chat app shows for a client's review
-- link sent as a short link: the content set and the brand.
-- 2026-10-12. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/links.js compares the
-- two.
--
-- WHAT CHANGED (the user, 2026-10-12: "is it possible to do dynamic title:
-- {Content Set} {client brand name} - Content Review Portal by ADspace")
--   1. `review_link_preview(p_key, p_set)` answers, for a live review key
--      (the client active, shown in Content Review, no passcode), the
--      client's name as `brand` and, where `p_set` is the first eight
--      characters of a published set's id, that set's title as `set`;
--      else nothing. The links Worker (hi.adspace.me/r/{key}/{set}) asks it
--      with the public key to fill the preview, and sends people on to the
--      review page. Nothing is stored: a short link is the key and the set,
--      so there is nothing to clean up. It says no more than the link
--      already opens. Joins `open_to_anon`: run
--      2026-10-07-function-hygiene.sql again BEFORE this file.
--
-- ORDER
--   This file, then the pages (Copy link builds the short link), then the
--   Worker. A Worker without the function answers every preview with the
--   plain title.
--
-- ROLLBACK
--   drop function if exists public.review_link_preview(text, text);
--   then 2026-10-07-function-hygiene.sql from before this date.
-- ===========================================================================

create or replace function public.review_link_preview(p_key text, p_set text default null)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select coalesce((
    select jsonb_strip_nulls(jsonb_build_object(
      'brand', c.name,
      'set', (select b.title
                from public.batches b
               where b.client_id = c.id and b.published
                 and p_set ~ '^[0-9a-f]{8}$'
                 and left(b.id::text, 8) = p_set
               order by b.created_at desc
               limit 1)))
      from public.clients c
     where p_key ~ '^[A-Za-z0-9_-]{6,64}$'
       and c.access_token = p_key and c.active
       and not c.review_hidden and c.passcode is null
     limit 1), '{}'::jsonb)
$$;
revoke all on function public.review_link_preview(text, text) from public;
grant execute on function public.review_link_preview(text, text) to anon, authenticated;

-- END OF REVIEW LINK PREVIEW -------------------------------------------------

-- AUDIT WHILE THE PERIOD RUNS — Meta's figures keep moving until a report's
-- period has ended (the user, 2026-10-12: the audit of a report whose period
-- ended that day read 101 differences, nearly all ads still spending since
-- the export), so nothing is counted against them until the day after its
-- last day (Malaysia time).
--   1. `sm_report_running(p_id)`: whether the report's period has not yet
--      ended, today in Malaysia time on or before its last day.
--   2. `sm_report_audit_blocks(p_id, p_after)`: while the period runs,
--      Submit is not held by Meta (p_after null); Publish of an Advertising
--      Report, read again since confirmation, is refused `period-running`
--      until the day after the period's last day.
--   3. `sm_report_audit_last(p_id)` adds `running` and `counts_from` (the
--      first day the audit counts), so the card says so.
-- Rollback: run sm_report_audit_blocks and sm_report_audit_last as the
-- REPORT AUDIT section defines them, then
--   drop function if exists public.sm_report_running(uuid);
create or replace function public.sm_report_running(p_id uuid)
returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce((select r.period_end >= (now() at time zone 'Asia/Kuala_Lumpur')::date
                     from public.sm_reports r where r.id = p_id), false)
$$;
revoke all on function public.sm_report_running(uuid) from public, anon, authenticated;

create or replace function public.sm_report_audit_blocks(p_id uuid, p_after timestamptz default null)
returns text
language plpgsql stable security definer set search_path = public as $$
declare
  r public.sm_reports;
  a public.sm_report_audits;
begin
  select * into r from public.sm_reports where id = p_id;
  if r.id is null or not public.sm_report_audit_needed(p_id) then return null; end if;
  if public.sm_report_running(p_id) then
    return case when p_after is null then null else 'period-running' end;
  end if;
  select * into a from public.sm_report_audits x
   where x.report_id = p_id and x.version_no = r.version_no
   order by x.read_at desc, x.id desc limit 1;
  if a.id is null or a.read_at < coalesce(p_after, '-infinity'::timestamptz) then return 'meta-audit'; end if;
  if a.outcome not in ('match', 'override') then return 'meta-audit'; end if;
  if a.print is distinct from public.sm_report_meta_print(p_id) then return 'meta-audit'; end if;
  return null;
end $$;
revoke all on function public.sm_report_audit_blocks(uuid, timestamptz) from public, anon, authenticated;

create or replace function public.sm_report_audit_last(p_id uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.sm_reports;
  c public.clients;
  a public.sm_report_audits;
  v_print text;
begin
  if me.id is null or not public.allowed('reports', 'view') then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_id;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  select * into c from public.clients where id = r.client_id;
  if not public.client_row_seen(c.stage, c.owner, 'view') then return jsonb_build_object('error', 'denied'); end if;
  v_print := public.sm_report_meta_print(p_id);
  select * into a from public.sm_report_audits x
   where x.report_id = p_id and x.version_no = r.version_no
   order by x.read_at desc, x.id desc limit 1;
  return jsonb_build_object(
    'needed', public.sm_report_audit_needed(p_id),
    'may_override', coalesce(me.is_admin, false) or me.role = 'admin',
    'blocks', public.sm_report_audit_blocks(p_id, null),
    'running', public.sm_report_running(p_id),
    'counts_from', r.period_end + 1,
    'held', exists (select 1 from public.sm_report_audits x where x.report_id = p_id and x.version_no = r.version_no),
    'print_since', (select min(x.read_at) from public.sm_report_audits x
                     where x.report_id = p_id and x.version_no = r.version_no and x.print = v_print),
    'print_moved', exists (select 1 from public.sm_report_audits x
                            where x.report_id = p_id and x.version_no = r.version_no and x.print is distinct from v_print),
    'last', case when a.id is null then null else jsonb_build_object(
      'at', a.read_at, 'by', a.by_name, 'outcome', a.outcome, 'rows', a.diffs, 'note', a.note,
      'current', a.print is not distinct from v_print) end);
end $$;
revoke all on function public.sm_report_audit_last(uuid) from public, anon, authenticated;
grant execute on function public.sm_report_audit_last(uuid) to authenticated;
-- END OF AUDIT WHILE THE PERIOD RUNS ----------------------------------------

-- AI NEEDS THE BRAND — Write with AI on a caption or a script, and a Brand
-- analysis, are asked only once the client's brand is written down (the user,
-- 2026-10-12: "when the brand analysis or brand details are empty; do not
-- allow the content copywriting and those needed the AI to write or analysis
-- to write anything"). Reports are left as they are: their words come from
-- the report's own figures.
--   1. `ai_brand_ready(p_client)`: for a colleague who sees the client, what
--      it still lacks: `missing`, the Content brief's parts left empty of
--      Audience, Content pillars and Tone of voice (`audience`, `pillars`,
--      `tone`), and `analysis`, whether a Brand analysis is confirmed.
--      `caption-draft` and `script-draft` refuse `no-brief` while a part is
--      missing and `no-analysis` while none is confirmed; `brand-analysis`
--      refuses `no-brief`. Each asks before it claims a use, so a refusal
--      counts nothing.
-- Rollback: deploy the three functions as they stood, then
--   drop function if exists public.ai_brand_ready(uuid);
create or replace function public.ai_brand_ready(p_client uuid)
returns jsonb
language sql stable security definer set search_path = public as $$
  select case when not public.is_team() or not public.client_seen(p_client, 'view')
    then jsonb_build_object('error', 'denied')
    else (select jsonb_build_object(
      'missing', coalesce((select jsonb_agg(x.k order by x.o)
                             from unnest(array['audience', 'pillars', 'tone']) with ordinality as x(k, o)
                            where coalesce(btrim(case when jsonb_typeof(c.brief) = 'object' then c.brief ->> x.k end), '') = ''),
                          '[]'::jsonb),
      'analysis', exists (select 1 from public.brand_analyses a
                           where a.client_id = c.id and a.confirmed_at is not null))
      from public.clients c where c.id = p_client) end
$$;
revoke all on function public.ai_brand_ready(uuid) from public, anon, authenticated;
grant execute on function public.ai_brand_ready(uuid) to authenticated;
-- END OF AI NEEDS THE BRAND -------------------------------------------------

-- ===========================================================================
-- SHARE LINK PREVIEW — the words a chat app shows for a client's Video
-- Scripts link, a campaign's creator selection link and a creator's own
-- link, each sent as a short link on the links host.
-- 2026-10-13. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/smsql.js compares the
-- two.
--
-- WHAT CHANGED (the user, 2026-10-12: "video script and creator campaigns and
-- creator portal are not changed to hi.adspace.me … so we can show client
-- brand name instead"; the client portal left as it is)
--   1. `share_link_preview(p_kind, p_key)` answers, for a key a page would
--      open, what its preview may name and nothing more:
--        `script`   a client's Video Scripts key (`clients.script_key`, the
--                   client active, a script published): `brand`;
--        `campaign` a campaign's selection key (no passcode, not a draft):
--                   `brand` and `title`;
--        `creator`  a creator's code (the creator active) with one open
--                   booking: that campaign's `brand` and `title`; with none
--                   or several, nothing.
--      Else nothing. The links Worker (hi.adspace.me/s/, /c/, /p/) asks it
--      with the public key to fill the preview, and sends people on to the
--      page itself. Nothing is stored: the short link is the key the link
--      already carried. Joins `open_to_anon`: run
--      2026-10-07-function-hygiene.sql again BEFORE this file.
--
-- ORDER
--   2026-10-07-function-hygiene.sql, this file, then the pages (Copy link
--   builds the short link), then the Worker. A short link sent before the
--   Worker is updated answers Link not recognised, so the Worker goes live
--   the same day.
--
-- ROLLBACK
--   drop function if exists public.share_link_preview(text, text);
--   then 2026-10-07-function-hygiene.sql from before this date.
-- ===========================================================================

create or replace function public.share_link_preview(p_kind text, p_key text)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(case p_kind
    when 'script' then (
      select jsonb_strip_nulls(jsonb_build_object('brand', c.name))
        from public.clients c
       where p_key ~ '^[A-Za-z0-9_-]{6,64}$'
         and c.script_key = p_key and c.active
         and exists (select 1 from public.video_scripts s where s.client_id = c.id and s.status = 'shared')
       limit 1)
    when 'campaign' then (
      select jsonb_strip_nulls(jsonb_build_object('brand', c.name, 'title', nullif(btrim(k.title), '')))
        from public.campaigns k
        join public.clients c on c.id = k.client_id
       where p_key ~ '^[A-Za-z0-9_-]{6,64}$'
         and k.access_token = p_key
         and coalesce(k.passcode, '') = '' and k.state <> 'draft'
       limit 1)
    when 'creator' then (
      select case when count(*) = 1 then jsonb_strip_nulls(jsonb_build_object('brand', min(c.name), 'title', nullif(btrim(min(k.title)), ''))) end
        from public.creators cr
        join public.campaign_options o on o.creator_id = cr.id
         and o.state in ('confirmed', 'pending_visit', 'pending_draft', 'submitted', 'reviewing', 'changes', 'scheduled', 'posted')
        join public.campaigns k on k.id = o.campaign_id
        join public.clients c on c.id = k.client_id
       where p_key ~ '^[A-Za-z0-9]{8}$'
         and cr.access_code = upper(p_key) and cr.active)
  end, '{}'::jsonb)
$$;
revoke all on function public.share_link_preview(text, text) from public;
grant execute on function public.share_link_preview(text, text) to anon, authenticated;

-- END OF SHARE LINK PREVIEW --------------------------------------------------

-- ===========================================================================
-- PERIOD WORDS AS THE PAGE WRITES THEM — a report's period named the same
-- way by the database and the page.
-- 2026-10-13. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/smsql.js compares the
-- two.
--
-- WHAT CHANGED (the user, 2026-10-13: Delete on a report of 16 September to
-- 10 October 2026 asked for "16 September to 10 October 2026" and refused
-- it typed back: "That does not match the period.")
--   `sm_period_word` named a period that is not a whole month as
--   "16 Sep 2026 to 10 Oct 2026", while the page (js/smreport.js
--   `periodWord`) shows and asks for "16 September to 10 October 2026", so
--   `sm_report_delete` refused every such report. It now writes the
--   page's words: a whole month "September 2026"; one month "1 to 15
--   September 2026"; one year "16 September to 10 October 2026"; across a
--   year "16 December 2025 to 10 January 2026". The Activity record's
--   report lines name the period the same way from now on.
--
-- ORDER
--   This file alone; no page change.
--
-- ROLLBACK
--   The definition in supabase/schema.sql's SOCIAL MEDIA REPORTS section
--   ("FMDD Mon YYYY" both sides), run on its own.
-- ===========================================================================

create or replace function public.sm_period_word(p_start date, p_end date)
returns text
language sql immutable set search_path = public as $$
  select case
    when p_start = date_trunc('month', p_start)::date
     and p_end = (date_trunc('month', p_start) + interval '1 month - 1 day')::date
      then trim(to_char(p_start, 'FMMonth YYYY'))
    when date_trunc('month', p_start) = date_trunc('month', p_end)
      then to_char(p_start, 'FMDD') || ' to ' || to_char(p_end, 'FMDD FMMonth YYYY')
    when extract(year from p_start) = extract(year from p_end)
      then to_char(p_start, 'FMDD FMMonth') || ' to ' || to_char(p_end, 'FMDD FMMonth YYYY')
    else to_char(p_start, 'FMDD FMMonth YYYY') || ' to ' || to_char(p_end, 'FMDD FMMonth YYYY')
  end
$$;

-- END OF PERIOD WORDS AS THE PAGE WRITES THEM ---------------------------------

-- ===========================================================================
-- TASK REMINDERS — on a weekday from 10:00 to 18:00 MYT each colleague is
-- told what of their own needs them: one notice every few hours, never one
-- a task.
-- 2026-10-13. Superseded in part: 2026-10-14-public-holidays.sql adds the
-- holiday check to the schedules, so run that file after this one.
-- Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/ops.js compares the
-- two.
--
-- WHAT CHANGED (the user, 2026-10-13: "nudge or notification for different
-- assigned person … if its urgent, overdue etc., send periodical
-- notifications"; "for new tasks also not moved to in progress"; "not every
-- single task needs to have a noti but it should have something")
--   1. `ops_tasks_nudge(p_at)` (no caller but pg_cron; revoked from every
--      login) reads each open task's owner (an active colleague, never a
--      system account) and sorts the task into the first of:
--        Overdue: My Work's late rule (the due date passed short of client
--          review, or a priority's deadline passed short of its review);
--        Urgent: Urgent priority, its deadline still running;
--        Due today: the due date, or a priority's deadline, falls today;
--        Not started: still at a starting stage (`intake`, `ready`) with its
--          draft due (else its due date) within `task_start_days`, or with
--          no date, assigned that many days ago.
--      A colleague holding any is sent one notice (kind `tasks.nudge`):
--      one task names it and opens it; several are counted ("5 tasks need
--      attention: 2 overdue, 1 Urgent, 2 not started.") with the first
--      three named, opening My Work. Never more often than every
--      `task_remind_hours`; on a weekday from 10:00 to 18:00 MYT alone.
--      Answers how many were told.
--   2. Business settings (My Work: Task reminders), from a day on:
--      `task_remind_hours` (3; 0 to 24, 0 sends none) and `task_start_days`
--      (2; 0 to 30, 0 leaves out Not started). `app_settings_set` takes them,
--      filed "Task reminders: 3 hours → 4 hours · from …".
--   3. pg_cron `tasks-nudge` runs it at minute 0 of every hour from 02:00 to
--      09:00 UTC (10:00 to 17:00 MYT), Monday to Friday.
--   4. `ops_notifications_push` opens My Work for `tasks.nudge` and tags it
--      `tasks-nudge`, so the next count replaces the last on a phone. It is
--      not sent on WhatsApp (`ops_notifications_wa` names its own kinds).
--
-- ORDER
--   Pages first (the bell opens My Work for the new kind; Settings draws the
--   row), then this file.
--
-- ROLLBACK
--   select cron.unschedule('tasks-nudge');
--   The function and the two settings rows may stay (nothing else reads
--   them); app_settings_set from PRIORITY DEADLINES and
--   ops_notifications_push from VIDEO SCRIPTS run again.
-- ===========================================================================

insert into public.app_settings (key, from_date, value)
select 'task_remind_hours', date '2023-08-14', 3
 where not exists (select 1 from public.app_settings s where s.key = 'task_remind_hours');
insert into public.app_settings (key, from_date, value)
select 'task_start_days', date '2023-08-14', 2
 where not exists (select 1 from public.app_settings s where s.key = 'task_start_days');

create or replace function public.app_settings_set(p_from date, p_values jsonb)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me public.team_members; v_k text; v_v numeric; v_was numeric; v_name text; v_unit text;
  v_today date := (now() at time zone 'Asia/Kuala_Lumpur')::date;
  v_keys constant text[] := array['lead_followup_hours', 'proposal_followup_days', 'sst_pct',
    'term_1_3', 'term_4_5', 'term_6_11', 'term_12_23', 'term_24', 'report_due_days', 'revision_due_days',
    'ai_price_in', 'ai_price_out', 'meta_checks', 'approval_reminder_days', 'ai_price_search',
    'reach_allowance_pct', 'priority_urgent_hours', 'priority_high_hours', 'priority_medium_hours',
    'task_remind_hours', 'task_start_days'];
  v_moved text[] := '{}';
begin
  if not public.ops_granted('team.settings', 'work') then return jsonb_build_object('error', 'denied'); end if;
  v_me := public.ops_me();
  if p_from is null or p_from < v_today then return jsonb_build_object('error', 'past', 'today', v_today); end if;
  if jsonb_typeof(p_values) is distinct from 'object' then return jsonb_build_object('error', 'bad-value'); end if;
  for v_k in select jsonb_object_keys(p_values) loop
    if not (v_k = any(v_keys)) or jsonb_typeof(p_values -> v_k) <> 'number' then
      return jsonb_build_object('error', 'bad-value', 'key', v_k);
    end if;
    v_v := (p_values ->> v_k)::numeric;
    if round(v_v, 2) <> v_v
       or (v_k = 'lead_followup_hours' and (v_v < 1 or v_v > 720 or v_v <> trunc(v_v)))
       or (v_k = 'proposal_followup_days' and (v_v < 1 or v_v > 365 or v_v <> trunc(v_v)))
       or (v_k = 'report_due_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'revision_due_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'approval_reminder_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'sst_pct' and (v_v < 0 or v_v > 100))
       or (v_k like 'term_%' and (v_v < -100 or v_v > 100))
       or (v_k like 'ai_price_%' and (v_v < 0 or v_v > 1000))
       or (v_k = 'meta_checks' and v_v not in (0, 1))
       or (v_k = 'reach_allowance_pct' and (v_v < 0 or v_v > 5))
       or (v_k like 'priority_%_hours' and (v_v < 1 or v_v > 720 or v_v <> trunc(v_v)))
       or (v_k = 'task_remind_hours' and (v_v < 0 or v_v > 24 or v_v <> trunc(v_v)))
       or (v_k = 'task_start_days' and (v_v < 0 or v_v > 30 or v_v <> trunc(v_v))) then
      return jsonb_build_object('error', 'bad-value', 'key', v_k);
    end if;
  end loop;
  for v_k in select jsonb_object_keys(p_values) loop
    v_v := (p_values ->> v_k)::numeric;
    v_was := public.app_setting(v_k, p_from);
    if v_was is distinct from v_v then
      insert into public.app_settings (key, from_date, value, set_by, set_at)
      values (v_k, p_from, v_v, v_me.id, now())
      on conflict (key, from_date) do update set value = excluded.value, set_by = excluded.set_by, set_at = now();
      v_name := case v_k when 'lead_followup_hours' then 'A lead waits' when 'proposal_followup_days' then 'A proposal waits'
        when 'sst_pct' then 'SST' when 'term_1_3' then '1 to 3 months' when 'term_4_5' then '4 and 5 months'
        when 'term_6_11' then '6 to 11 months' when 'term_12_23' then '12 to 23 months' when 'term_24' then '24 months and more'
        when 'revision_due_days' then 'Revision due' when 'ai_price_in' then 'AI input, a million tokens'
        when 'ai_price_out' then 'AI output, a million tokens' when 'ai_price_search' then 'AI web searches, a thousand' when 'meta_checks' then 'Meta checks'
        when 'approval_reminder_days' then 'Approval reminder' when 'reach_allowance_pct' then 'Reach allowance'
        when 'priority_urgent_hours' then 'Urgent deadline' when 'priority_high_hours' then 'High deadline'
        when 'priority_medium_hours' then 'Medium deadline' when 'task_remind_hours' then 'Task reminders'
        when 'task_start_days' then 'Not started reminder' else 'Report due' end;
      v_unit := case when v_k in ('lead_followup_hours', 'task_remind_hours') or v_k like 'priority_%_hours' then ' hours'
        when v_k in ('proposal_followup_days', 'report_due_days', 'revision_due_days', 'approval_reminder_days', 'task_start_days') then ' days'
        else '%' end;
      insert into public.activity_log (actor, action, subject, detail)
      values (coalesce(v_me.name, 'admin'), 'team.changed', 'Settings',
              v_name || ': ' || case when v_k = 'meta_checks' then
                case when v_was = 1 then 'On' else 'Off' end || ' → ' || case when v_v = 1 then 'On' else 'Off' end ||
                ' · from ' || public.register_day(p_from) else '' end ||
              case when v_k = 'meta_checks' then '' else case when v_k like 'ai_price_%' then 'US$' else '' end ||
              trim(to_char(v_was, 'FM999999990.99'), '.') || case when v_k like 'ai_price_%' then '' else v_unit end || ' → ' ||
              case when v_k like 'ai_price_%' then 'US$' else '' end ||
              trim(to_char(v_v, 'FM999999990.99'), '.') || case when v_k like 'ai_price_%' then '' else v_unit end ||
              ' · from ' || public.register_day(p_from) end);
      v_moved := v_moved || v_k;
    end if;
  end loop;
  return public.app_settings_read() || jsonb_build_object('changed', to_jsonb(v_moved));
end $$;
revoke all on function public.app_settings_set(date, jsonb) from public, anon;

/* What of a colleague's own needs them, as one notice (see the head). */
create or replace function public.ops_tasks_nudge(p_at timestamptz default null)
returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_at    timestamptz := coalesce(p_at, now());
  v_local timestamp := coalesce(p_at, now()) at time zone 'Asia/Kuala_Lumpur';
  v_today date := (coalesce(p_at, now()) at time zone 'Asia/Kuala_Lumpur')::date;
  v_every integer;
  v_start integer;
  m record;
  v_title text;
  v_body text;
  v_parts text[];
  n integer := 0;
begin
  v_every := coalesce(public.app_setting('task_remind_hours', v_today), 3)::integer;
  v_start := coalesce(public.app_setting('task_start_days', v_today), 2)::integer;
  if v_every <= 0 or extract(isodow from v_today) > 5
     or extract(hour from v_local) < 10 or extract(hour from v_local) >= 18 then
    return 0;
  end if;
  for m in
    with floors as (
      select workflow_id, min(position) as at
        from public.ops_workflow_stages
       where stage_group = 'client_review'
       group by workflow_id
    ),
    pfloors as (
      select workflow_id,
             coalesce(min(position) filter (where stage_group = 'client_review'),
                      min(position) filter (where stage_group = 'internal_review')) as at
        from public.ops_workflow_stages
       group by workflow_id
    ),
    mine as (
      select a.team_member_id as member, k.id, a.assigned_at, k.priority_level,
             public.ops_serial(k.task_no) || ' · ' || public.ops_title(k) as label,
             coalesce(c.name, 'Internal') as client,
             s.stage_group, s.position, f.at as review_at, pf.at as prio_at,
             public.ops_priority_by(coalesce(k.priority_at, k.created_at), k.priority_level) as prio_by,
             (k.current_final_due_at at time zone 'Asia/Kuala_Lumpur')::date as due_day,
             (coalesce(k.current_first_draft_due_at, k.current_final_due_at) at time zone 'Asia/Kuala_Lumpur')::date as first_day
        from public.ops_task_assignees a
        join public.ops_tasks k on k.id = a.task_id
        join public.team_members tm on tm.id = a.team_member_id
        join public.ops_workflow_stages s on s.workflow_id = k.workflow_id and s.key = k.stage_key
        left join public.clients c on c.id = k.client_id
        left join floors f on f.workflow_id = k.workflow_id
        left join pfloors pf on pf.workflow_id = k.workflow_id
       where a.responsibility = 'owner' and a.ended_at is null
         and tm.active and not coalesce(tm.system, false)
         and k.completed_at is null and k.cancelled_at is null and k.archived_at is null
         and coalesce(s.stage_group, '') <> 'cancelled'
    ),
    sorted as (
      select x.*,
             (x.prio_by is not null and (x.prio_at is null or x.position < x.prio_at
                                         or x.stage_group in ('kiv', 'blocked'))) as prio_runs,
             (x.review_at is null or x.position < x.review_at) as short_of_review
        from mine x
    ),
    sized as (
      select y.*, case
        when (y.due_day < v_today and y.short_of_review) or (y.prio_runs and y.prio_by < v_at) then 1
        when y.prio_runs and y.priority_level = 1 then 2
        when (y.due_day = v_today and y.short_of_review)
          or (y.prio_runs and (y.prio_by at time zone 'Asia/Kuala_Lumpur')::date = v_today) then 3
        when v_start > 0 and y.stage_group in ('intake', 'ready')
          and ((y.first_day is not null and y.first_day <= v_today + v_start)
            or (y.first_day is null and y.assigned_at <= v_at - make_interval(days => v_start))) then 4
      end as bucket
        from sorted y
    )
    select z.member,
           count(*) as total,
           count(*) filter (where z.bucket = 1) as late,
           count(*) filter (where z.bucket = 2) as urgent,
           count(*) filter (where z.bucket = 3) as today,
           count(*) filter (where z.bucket = 4) as idle,
           (array_agg(z.id order by z.bucket, coalesce(z.due_day, z.first_day), z.label))[1] as first_id,
           (array_agg(z.bucket order by z.bucket, coalesce(z.due_day, z.first_day), z.label))[1] as first_bucket,
           (array_agg(z.client order by z.bucket, coalesce(z.due_day, z.first_day), z.label))[1] as first_client,
           (array_agg(z.prio_by order by z.bucket, coalesce(z.due_day, z.first_day), z.label))[1] as first_by,
           (array_agg(z.label order by z.bucket, coalesce(z.due_day, z.first_day), z.label))[1:3] as labels
      from sized z
     where z.bucket is not null
     group by z.member
     order by z.member
  loop
    if exists (select 1 from public.ops_notifications o
                where o.team_member_id = m.member and o.kind = 'tasks.nudge'
                  and o.created_at > v_at - make_interval(mins => v_every * 60 - 10)) then
      continue;
    end if;
    if m.total = 1 then
      v_title := m.labels[1] || case m.first_bucket when 1 then ' is overdue.' when 2 then ' is Urgent.'
                                                  when 3 then ' is due today.' else ' has not started.' end;
      v_body := m.first_client || case when m.first_bucket = 2 and m.first_by is not null then
        ' · deliver by ' || to_char(m.first_by at time zone 'Asia/Kuala_Lumpur', 'FMHH12:MIam') || ', ' ||
        public.register_day((m.first_by at time zone 'Asia/Kuala_Lumpur')::date) || '.' else '' end;
    else
      v_parts := array_remove(array[
        case when m.late > 0 then m.late || ' overdue' end,
        case when m.urgent > 0 then m.urgent || ' Urgent' end,
        case when m.today > 0 then m.today || ' due today' end,
        case when m.idle > 0 then m.idle || ' not started' end], null);
      v_title := m.total || ' tasks need attention: ' || array_to_string(v_parts, ', ') || '.';
      v_body := array_to_string(m.labels, '; ') ||
                case when m.total > 3 then '; and ' || (m.total - 3) || ' more.' else '.' end;
    end if;
    insert into public.ops_notifications (team_member_id, task_id, kind, title, body, created_at, dedupe_key)
    values (m.member, case when m.total = 1 then m.first_id end, 'tasks.nudge', v_title, v_body, v_at,
            'tasks.nudge.' || m.member || '.' || to_char(v_local, 'YYYY-MM-DD-HH24'))
    on conflict (dedupe_key) do nothing;
    n := n + 1;
  end loop;
  return n;
end $$;
revoke all on function public.ops_tasks_nudge(timestamptz) from public, anon, authenticated;

-- A count of what needs a colleague opens My Work.
create or replace function public.ops_notifications_push()
returns trigger
language plpgsql security definer set search_path = public as $$
declare
  v_title text := coalesce(nullif(btrim(new.title), ''), 'My Work');
  v_body  text := coalesce(new.body, '');
begin
  perform public.push_queue('team', new.team_member_id,
    jsonb_build_object('en', jsonb_build_object('title', v_title, 'body', v_body),
                       'zh', jsonb_build_object('title', v_title, 'body', v_body)),
    case when new.link is not null then new.link
         when new.task_id is not null then '/admin/?s=work&open=' || new.task_id::text
         when new.report_id is not null then '/admin/?s=reports&report=' || new.report_id::text
         when new.script_id is not null then '/admin/?s=scripts&script=' || new.script_id::text
         when new.kind in ('client_left', 'tasks.empty', 'tasks.nudge') then '/admin/?s=work'
         when new.kind = 'hr.letter' then '/admin/?s=mine&view=letters'
         when new.kind = 'perf.disputed' then '/admin/?s=team&tab=performance'
         when new.kind = 'perf.reflect' then '/admin/?s=mine&view=reflection'
         when new.kind = 'perf.initiative' then '/admin/?s=mine&view=initiatives'
         when new.kind like 'health.%' then '/admin/?s=mine&view=health'
         when new.kind like 'perf.%' then '/admin/?s=mine'
         else '/admin/' end,
    case when new.task_id is not null then 'task-' || new.task_id::text
         when new.report_id is not null then 'report-' || new.report_id::text
         when new.script_id is not null then 'script-' || new.script_id::text
         when new.kind = 'hr.letter' then 'hr-letter'
         when new.kind in ('perf.remind', 'perf.reflect', 'health.remind') then 'my-hr'
         when new.kind = 'tasks.empty' then 'tasks-empty'
         when new.kind = 'tasks.nudge' then 'tasks-nudge'
         when new.kind = 'outstation' then 'outstation'
         else null end);
  return new;
exception when others then
  return new;
end $$;

do $$
begin
  if not exists (select 1 from pg_extension where extname = 'pg_cron') then
    raise notice 'pg_cron is not enabled: no task reminders go out until it is.';
    return;
  end if;
  perform cron.unschedule(j.jobid) from cron.job j where j.jobname = 'tasks-nudge';
  perform cron.schedule('tasks-nudge', '0 2-9 * * 1-5', 'select public.ops_tasks_nudge()');
end $$;

-- END OF TASK REMINDERS ------------------------------------------------------

-- ===========================================================================
-- BILLING CONTACT AND REMOVED SERVICES — the billing contact follows the main
-- contact unless somebody else is chosen, and a removed service line no
-- letter quoted can be deleted.
-- 2026-10-13. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/sql.js compares the
-- two.
--
-- WHAT CHANGED (the user, 2026-10-13: a client's main contact changed and
-- the next letter still named the old one, "by default billing contact
-- fills main contact"; and that a removed service line should go for good)
--   1. An empty `clients.bill_contact_id` is the main contact: the Billing
--      sheet saves it empty while the main contact is chosen, and
--      `issue_letter` already answers Attn that way. Trigger
--      `client_contacts_bill_follows`: a contact that stops being the main
--      contact, or is removed, lets go of the billing contact it held, so
--      the next letter names the main contact. A billing contact chosen
--      apart from the main contact is left alone. Nothing issued changes:
--      a letter keeps the contact it was issued to.
--   2. A removed service line is deleted at Clients: Services Full Access
--      (the table's own policy, unchanged), filed `client.service_deleted`;
--      a line a Letter of Offer quoted stays (the letter's foreign key
--      restricts it). `activity_section()` names the new tag under Clients.
--
-- ORDER
--   Pages first, then this file. A page from before files nothing new.
--
-- ROLLBACK
--   Take the trigger client_contacts_bill_follows off public.client_contacts
--   in the SQL Editor; the function may stay. activity_section from the band
--   before this one runs again.
-- ===========================================================================

create or replace function public.client_contacts_bill_follows()
returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if (old.is_primary and not new.is_primary)
     or (old.archived_at is null and new.archived_at is not null) then
    update public.clients c set bill_contact_id = null
     where c.id = new.client_id and c.bill_contact_id = new.id;
  end if;
  return new;
exception when others then
  return new;
end $$;
revoke all on function public.client_contacts_bill_follows() from public, anon, authenticated;

create or replace trigger client_contacts_bill_follows
  after update of is_primary, archived_at on public.client_contacts
  for each row execute function public.client_contacts_bill_follows();

create or replace function public.activity_section(p_action text)
returns text
language sql immutable parallel safe as $$
  select case
    when action in ('campaign.bulk', 'campaign.closed', 'campaign.confirmed',
                    'campaign.created', 'campaign.dates', 'campaign.deleted', 'campaign.edited',
                    'campaign.file_added', 'campaign.file_deleted', 'campaign.file_hidden',
                    'campaign.file_shown', 'campaign.qc',
                    'campaign.invoice', 'campaign.invoice_file',
                    'campaign.invoice_removed', 'campaign.keyed', 'campaign.locked',
                    'campaign.opened', 'campaign.rate', 'campaign.rated',
                    'campaign.reinstated', 'campaign.replaced', 'campaign.results', 'campaign.review',
                    'campaign.stage', 'campaign.submitted', 'campaign.task_linked',
                    'campaign.task_unlinked', 'campaign.unbooked',
                    'campaign.unkeyed', 'campaign.whatsapp', 'campaign.withdrawn', 'creator.added',
                    'creator.code', 'creator.links', 'creator.links_restored',
                    'creator.links_self', 'creator.off', 'creator.on', 'creator.removed',
                    'creator.updated') then 'campaigns'
    when action in ('client.action_done', 'client.action_reopened', 'client.added',
                    'client.billing', 'client.brand', 'client.deleted', 'client.edited',
                    'client.review_on', 'client.service', 'client.service_changed',
                    'client.service_deleted', 'client.service_removed', 'client.service_restored', 'client.stage', 'client.touch',
                    'client.touch_deleted', 'client.touch_edited', 'client.touch_removed',
                    'client.touch_restored', 'contact.added', 'contact.deleted',
                    'contact.edited', 'contact.portal_invite', 'contact.portal_off',
                    'contact.portal_on', 'contact.primary', 'contact.removed',
                    'contact.restored',
                    'request.changed', 'request.raised',
                    'request.reinstated', 'request.replied', 'request.withdrawn',
                    'service.override') then 'clients'
    when action in ('wa.sent', 'wa.template') then 'whatsapp'
    when action in ('report.ai_drafted', 'report.ai_failed', 'report.audited', 'report.confirmed',
                    'report.created', 'report.deleted', 'report.published',
                    'report.reassigned', 'report.returned', 'report.revised', 'report.saved',
                    'report.submitted', 'report.unpublished') then 'reports'
    when action in ('qr.created', 'qr.restored', 'qr.revoked', 'shortlink.created',
                    'shortlink.deleted', 'shortlink.imported', 'shortlink.updated') then 'links'
    when action in ('ops.deleted', 'ops.month_deleted', 'ops.numbering') then 'ops'
    when action in ('document.deleted', 'document.issued', 'document.reissued',
                    'document.restored', 'document.signed', 'document.superseded',
                    'document.unsigned', 'document.verified', 'document.voided',
                    'register.added', 'register.edited') then 'register'
    when action in ('client.drive', 'client.handles', 'client.profile',
                    'client.removed', 'drive.imported', 'link.reset', 'post.added',
                    'post.deleted', 'post.edited', 'reapproval.requested',
                    'review.approved', 'review.changes', 'review.removed',
                    'review.unconfirmed',
                    'set.created', 'set.deleted', 'set.month', 'set.published', 'set.renamed',
                    'set.task_linked', 'set.task_unlinked',
                    'set.withdrawn') then 'review'
    when action in ('script.approved', 'script.changes', 'script.created', 'script.deleted',
                    'script.link', 'script.saved', 'script.shared', 'script.shot',
                    'script.unshared') then 'scripts'
    when action in ('handbook.added', 'handbook.archived', 'handbook.deleted',
                    'handbook.edited', 'handbook.restored', 'handbook.version') then 'handbook'
    when action in ('service.added', 'service.changed', 'service.deleted',
                    'service.off', 'service.on') then 'services'
    when action in ('team.added', 'team.changed', 'team.edited', 'team.group_added',
                    'team.group_changed', 'team.group_removed', 'team.invited') then 'team'
    else 'other'
  end
  from (select p_action as action) t
$$;
grant execute on function public.activity_section(text) to authenticated;

-- END OF BILLING CONTACT AND REMOVED SERVICES -------------------------------

-- ===========================================================================
-- RATE CARD VERSIONS — the rate card is edited as a draft and goes live as
-- a numbered version; each line carries what a quote needs to know of it.
-- 2026-10-13. Safe to run twice. Rollback at the foot. Mirrored byte for byte
-- in supabase/schema.sql under the same banner; tests/sql.js compares the
-- two.
--
-- WHAT CHANGED (the user, 2026-10-13: the rate card "should run based on
-- versioning, so every version changed would proceed proper updates to the
-- site and export")
--   1. `services.spec`: what a quote reads of a line. A plan (its letter,
--      with or without ads, platforms and contents a month, the content
--      mixes it offers, the ad budget it covers, who it is for); a platform's
--      management fee; Meta advertising and an ad booster (the budget each
--      covers); translation (an added language); a content format; the KOL
--      management fee's tiers; a verification's own fee; an add-on's group
--      on the card. Checked by `service_spec_ok`. Seeded only where a line
--      holds none.
--   2. `rate_card_text`: the card's own words (What's Included, notes, the
--      KOC and KOL pages, the Terms of Service), one block a key, seeded
--      once from Rate Card v.2.0.6 and changed only by
--      `rate_card_text_save` (Services Full Access, filed
--      `service.changed` under Rate card wording).
--   3. `rate_card_versions`: each version published, whole
--      (`rate_card_publish(p_version, p_valid_until, p_note)`, Services
--      Full Access: the lines, the words, SST and the term percentages as
--      at that day; `bad-version`, `version-taken`, `bad-date`,
--      `no-change`; filed `service.published`). `rate_card_current()`
--      answers the latest. The live card is seeded once as v.2.0.6, valid
--      until 31 December 2026. A client's service lines are priced from the
--      version, never from the draft.
--
-- ORDER
--   This file, then the pages. A page from before reads the draft as it
--   always did.
--
-- ROLLBACK
--   The pages from before. The tables and the column may stay: nothing
--   from before reads them.
-- ===========================================================================

alter table public.services add column if not exists spec jsonb;

create or replace function public.service_spec_ok(p jsonb)
returns boolean
language sql immutable set search_path = public as $$
  select p is null or (
    jsonb_typeof(p) = 'object'
    and coalesce(p->>'role', '') in ('', 'plan', 'platform', 'ads', 'booster', 'language', 'content', 'kol', 'koc', 'verify', 'addon')
    and (p->>'role' is distinct from 'plan' or (
      coalesce(p->>'plan', '') ~ '^[A-Z]$'
      and coalesce(p->>'platforms', '') ~ '^[1-9][0-9]?$'
      and coalesce(p->>'contents', '') ~ '^[1-9][0-9]?$'
      and jsonb_typeof(coalesce(p->'mix', 'null'::jsonb)) = 'array'
      and jsonb_array_length(p->'mix') between 1 and 3
      and (p->>'ad_budget' is null or coalesce(p->>'ad_budget', '') ~ '^[0-9]+(\.[0-9]+)?$')))
    and (p->>'role' not in ('ads', 'booster') or coalesce(p->>'budget', '') ~ '^[1-9][0-9]*$')
    and (p->>'role' is distinct from 'platform' or p->>'platform' in ('meta', 'tiktok', 'rednote', 'linkedin')))
$$;

do $c$
begin
  if not exists (select 1 from pg_constraint where conname = 'services_spec_ok') then
    alter table public.services add constraint services_spec_ok check (public.service_spec_ok(spec));
  end if;
end $c$;

