-- UNUSED TASK SHORTCUTS CLOSED — the first operations model's Finish and
-- Reopen are closed to every browser. 2026-10-18. Safe to run twice.
-- Rollback at the foot. Mirrored byte for byte in supabase/schema.sql under
-- the same banner; tests/sql.js compares the two.
--
-- WHAT CHANGED (second audit, item 3)
--   ops_complete_task and ops_reopen_task (THE OPERATIONS SYSTEM, 2026-09-19)
--   were still executable by every signed-in account, a client contact
--   included. They write stage keys no workflow holds ('done', 'revision'),
--   pass by the owner, AQC review, client review and draft gates every move
--   takes through ops_transition_task, and ops_reopen_task asks no client
--   scope. No page, policy, view, function, cron job or edge function calls
--   either (checked in the repo and live on 2026-10-18): a task finishes and
--   reopens through ops_transition_task. Both are revoked from public, anon
--   and authenticated; the functions stay, so nothing that names them breaks
--   at create time.
--
-- ROLLBACK
--   grant execute on function public.ops_complete_task(uuid, text, integer) to authenticated;
--   grant execute on function public.ops_reopen_task(uuid, text, integer) to authenticated;
-- ===========================================================================

revoke all on function public.ops_complete_task(uuid, text, integer) from public, anon, authenticated;
revoke all on function public.ops_reopen_task(uuid, text, integer) from public, anon, authenticated;

-- END OF UNUSED TASK SHORTCUTS CLOSED ---------------------------------------

-- ===========================================================================
-- CONFIRMED PERIODS HOLD THEIR MONTHS — a month inside a confirmed quarter or
-- bonus and trip period is neither reopened nor deleted until that period is
-- reopened. 2026-10-18. Safe to run twice. Rollback at the foot. Mirrored
-- byte for byte in supabase/schema.sql under the same banner; tests/perf.js
-- compares the two.
--
-- WHAT CHANGED (second audit, item 8)
--   Confirm keeps a quarter's or a half's rewards as a snapshot in
--   perf_rewards, and pays on it. perf_reopen and perf_delete read nothing
--   of it, so a final month in a paid quarter could be reopened, rescored
--   and finalised again (or deleted) while the snapshot, and the payout,
--   stayed as confirmed. Both now refuse `period-confirmed`, naming the
--   quarter or the period (`kind`, `word`), while either is confirmed;
--   Reopen under Quarters or Bonus and trip (Manage) is the way through, as
--   it is for the department scores and the company figures.
--
-- ROLLBACK
--   Run the perf_reopen definition of the PERFORMANCE REVIEWS section and
--   the perf_delete definition of A PERFORMANCE RECORD CAN BE DELETED in
--   supabase/schema.sql again.
-- ===========================================================================

create or replace function public.perf_reopen(p_token text, p_review uuid, p_reason text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare err text; m public.team_members; r public.perf_reviews; w public.perf_rewards;
begin
  err := public.perf_check(p_token, 'manage');
  if err is not null then return jsonb_build_object('error', err); end if;
  m := public.ops_me();
  if coalesce(btrim(p_reason), '') = '' then return jsonb_build_object('error', 'reason-needed'); end if;
  select * into r from public.perf_reviews where id = p_review for update;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if r.team_member_id = m.id then return jsonb_build_object('error', 'own-review'); end if;
  if r.status <> 'final' then return jsonb_build_object('error', 'not-final'); end if;
  /* A month inside a confirmed quarter or half is paid on that snapshot:
     the period is reopened first. */
  select * into w from public.perf_rewards x
   where (x.kind = 'quarter' and x.period = date_trunc('quarter', r.period)::date)
      or (x.kind = 'period' and x.period = public.perf_half(r.period))
   order by x.kind limit 1;
  if w.kind is not null then
    return jsonb_build_object('error', 'period-confirmed', 'kind', w.kind,
      'word', case w.kind when 'quarter' then public.perf_quarter_word(w.period) else public.perf_period_word(w.period) end);
  end if;
  perform public.perf_log(r.id, r.team_member_id, 'reopened',
    jsonb_build_object('reason', btrim(p_reason), 'was', public.perf_json(r, false)));
  update public.perf_reviews set status = 'draft', result = null, released_at = null,
         dispute_until = null, acknowledged_at = null, finalised_at = null, finalised_by = null,
         version = version + 1, rev = rev + 1, updated_at = now()
   where id = r.id returning * into r;
  return public.perf_json(r, true);
end $$;

create or replace function public.perf_delete(p_token text, p_review uuid, p_confirm text, p_reason text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_err     text;
  v_me      public.team_members;
  v_rev     public.perf_reviews;
  v_name    text;
  v_month   text;
  v_printed boolean;
  v_rw      public.perf_rewards;
begin
  v_err := public.perf_check(p_token, 'manage');
  if v_err is not null then return jsonb_build_object('error', v_err); end if;
  if not public.perf_is_admin() then return jsonb_build_object('error', 'admin-only'); end if;
  v_me := public.ops_me();
  select * into v_rev from public.perf_reviews pr where pr.id = p_review for update;
  if v_rev.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if v_rev.team_member_id = v_me.id then return jsonb_build_object('error', 'own-review'); end if;
  /* A month inside a confirmed quarter or half is paid on that snapshot:
     the period is reopened first. */
  select * into v_rw from public.perf_rewards x
   where (x.kind = 'quarter' and x.period = date_trunc('quarter', v_rev.period)::date)
      or (x.kind = 'period' and x.period = public.perf_half(v_rev.period))
   order by x.kind limit 1;
  if v_rw.kind is not null then
    return jsonb_build_object('error', 'period-confirmed', 'kind', v_rw.kind,
      'word', case v_rw.kind when 'quarter' then public.perf_quarter_word(v_rw.period) else public.perf_period_word(v_rw.period) end);
  end if;
  if coalesce(btrim(p_reason), '') = '' then return jsonb_build_object('error', 'reason-needed'); end if;
  select tm.name into v_name from public.team_members tm where tm.id = v_rev.team_member_id;
  v_month := public.perf_month_word(v_rev.period);
  if lower(regexp_replace(btrim(coalesce(p_confirm, '')), '\s+', ' ', 'g'))
     <> lower(regexp_replace(btrim(coalesce(v_name, '') || ' ' || v_month), '\s+', ' ', 'g')) then
    return jsonb_build_object('error', 'confirm-mismatch');
  end if;
  v_printed := exists (select 1 from public.perf_events pe where pe.review_id = v_rev.id and pe.kind = 'printed');

  insert into public.perf_deleted (team_member_id, period, serial, status, printed, released_at, deleted_by, reason)
  values (v_rev.team_member_id, v_rev.period, v_rev.serial, v_rev.status, v_printed, v_rev.released_at,
          v_me.id, btrim(p_reason));
  perform public.perf_log(null, v_rev.team_member_id, 'deleted',
    jsonb_build_object('period', v_rev.period, 'month', v_month, 'serial', v_rev.serial,
                       'status', v_rev.status, 'printed', v_printed, 'reason', btrim(p_reason)));
  delete from public.perf_reviews pr where pr.id = v_rev.id;
  return jsonb_build_object('ok', true, 'month', v_month, 'status', v_rev.status, 'printed', v_printed);
end $$;

revoke all on function public.perf_reopen(text, uuid, text) from public, anon, authenticated;
revoke all on function public.perf_delete(text, uuid, text, text) from public, anon, authenticated;
grant execute on function public.perf_reopen(text, uuid, text) to authenticated;
grant execute on function public.perf_delete(text, uuid, text, text) to authenticated;

-- END OF CONFIRMED PERIODS HOLD THEIR MONTHS --------------------------------

-- ===========================================================================
-- NOBODY SCORES THEIR OWN DEPARTMENT — the quarter's department scores are
-- entered by somebody outside the department. 2026-10-18. Safe to run twice.
-- Rollback at the foot. Mirrored byte for byte in supabase/schema.sql under
-- the same banner; tests/perf.js compares the two.
--
-- WHAT CHANGED (second audit, item 9)
--   The department prize goes whole to the winning department, shared by
--   its active members (perf_quarter_calc). perf_dept_save asked the
--   performance part and the master code, and nothing of who was scoring,
--   so a member of Creative holding team.performance could score Creative
--   100 and win the prize for their own department, against the rule that
--   nobody acts on their own review. It now refuses `own-department` where
--   the caller's department (team_members.department) is the one scored.
--   An admin, who holds no department, scores both, as today.
--
-- ROLLBACK
--   Run the perf_dept_save definition of the PERFORMANCE REWARDS section of
--   supabase/schema.sql again.
-- ===========================================================================

create or replace function public.perf_dept_save(p_token text, p_quarter date, p_department text, p_payload jsonb)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_err text; v_me public.team_members; v_q date; v_c jsonb; v_i integer; v_v jsonb; v_n numeric[] := '{}';
  v_max constant numeric[] := array[25, 25, 20, 15, 15]; v_was public.perf_dept_scores; v_crit boolean;
  v_changed jsonb := '[]'::jsonb; v_old numeric[];
begin
  v_err := public.perf_check(p_token, 'work');
  if v_err is not null then return jsonb_build_object('error', v_err); end if;
  v_me := public.ops_me();
  v_q := date_trunc('quarter', p_quarter)::date;
  if v_q is null or v_q < date '2026-07-01' then return jsonb_build_object('error', 'before-first'); end if;
  if p_department is null or p_department not in ('creative', 'marketing') then
    return jsonb_build_object('error', 'bad-department');
  end if;
  /* Nobody scores their own department: its members share its prize. */
  if v_me.department is not distinct from p_department then
    return jsonb_build_object('error', 'own-department');
  end if;
  if exists (select 1 from public.perf_rewards where kind = 'quarter' and period = v_q) then
    return jsonb_build_object('error', 'confirmed');
  end if;
  v_c := p_payload -> 'criteria';
  if v_c is null or jsonb_typeof(v_c) <> 'array' then return jsonb_build_object('error', 'bad-payload'); end if;
  if jsonb_array_length(v_c) <> 5 then return jsonb_build_object('error', 'bad-payload'); end if;
  for v_i in 1..5 loop
    v_v := v_c -> (v_i - 1);
    if jsonb_typeof(v_v) <> 'number' then
      return jsonb_build_object('error', 'bad-score', 'index', v_i, 'max', v_max[v_i]);
    end if;
    if (v_v #>> '{}')::numeric not between 0 and v_max[v_i]
       or round((v_v #>> '{}')::numeric, 1) <> (v_v #>> '{}')::numeric then
      return jsonb_build_object('error', 'bad-score', 'index', v_i, 'max', v_max[v_i]);
    end if;
    v_n := v_n || (v_v #>> '{}')::numeric;
  end loop;
  v_crit := coalesce((p_payload ->> 'critical')::boolean, false);
  select * into v_was from public.perf_dept_scores where quarter = v_q and department = p_department for update;
  insert into public.perf_dept_scores (quarter, department, c1, c2, c3, c4, c5, critical, entered_by, updated_at)
  values (v_q, p_department, v_n[1], v_n[2], v_n[3], v_n[4], v_n[5], v_crit, v_me.id, now())
  on conflict (quarter, department) do update set
    c1 = excluded.c1, c2 = excluded.c2, c3 = excluded.c3, c4 = excluded.c4, c5 = excluded.c5,
    critical = excluded.critical, entered_by = excluded.entered_by, updated_at = now();
  v_old := array[v_was.c1, v_was.c2, v_was.c3, v_was.c4, v_was.c5];
  for v_i in 1..5 loop
    if v_old[v_i] is distinct from v_n[v_i] then
      v_changed := v_changed || jsonb_build_array(jsonb_build_object('key', 'c' || v_i, 'from', v_old[v_i], 'to', v_n[v_i]));
    end if;
  end loop;
  if v_was.critical is distinct from v_crit then
    v_changed := v_changed || jsonb_build_array(jsonb_build_object('key', 'critical', 'from', v_was.critical, 'to', v_crit));
  end if;
  if jsonb_array_length(v_changed) > 0 then
    perform public.perf_log(null, null, 'dept_scored',
      jsonb_build_object('key', v_q::text, 'department', p_department, 'changed', v_changed));
  end if;
  return public.perf_quarter(p_token, v_q);
end $$;

revoke all on function public.perf_dept_save(text, date, text, jsonb) from public, anon, authenticated;
grant execute on function public.perf_dept_save(text, date, text, jsonb) to authenticated;

-- END OF NOBODY SCORES THEIR OWN DEPARTMENT ---------------------------------

-- ===========================================================================
-- AN ISSUE PRICED BY ITS MONTH — each issue's points are read with the
-- settings of the month it belongs to, as the month's total is. 2026-10-18.
-- Safe to run twice. Rollback at the foot. Mirrored byte for byte in
-- supabase/schema.sql under the same banner; tests/perf.js compares the two.
--
-- WHAT CHANGED (second audit, item 12)
--   perf_calc adds up a month's issues with that month's breach points
--   (perf_setting at r.period), but perf_breaches_json, the list of issues
--   the review sheet, the member's page and the printed record show, priced
--   each line, and named the VIC multiplier, with today's settings; so did
--   the figure perf_breach_log answers and files. Once the points changed
--   from a later quarter, an earlier month's lines no longer added up to
--   its total. All three now read the issue's own month (`p_period`, the
--   month the issue is logged into).
--
-- ROLLBACK
--   Run the perf_breaches_json definition of the VIC PERFORMANCE section and
--   the perf_breach_log definition of the MALAYSIA TIME IN THE DATABASE
--   section of supabase/schema.sql again.
-- ===========================================================================

create or replace function public.perf_breaches_json(p_member uuid, p_period date, p_with_void boolean)
returns jsonb
language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', b.id, 'occurred_on', b.occurred_on, 'category', b.category,
           'severity', b.severity, 'repeated', b.repeated, 'late', b.late,
           'what', b.what, 'evidence', b.evidence,
           'deduction', public.perf_deduction_vic_at(b.severity, b.repeated, b.late, b.vic, p_period),
           'client_id', b.client_id, 'client_name', (select c.name from public.clients c where c.id = b.client_id),
           'vic', b.vic, 'vic_x', case when b.vic then public.perf_setting('ded_vic', p_period) end,
           'logged_by', (select name from public.team_members where id = b.logged_by),
           'logged_at', b.logged_at, 'voided_at', b.voided_at, 'void_reason', b.void_reason)
         order by b.occurred_on, b.logged_at), '[]'::jsonb)
    from public.perf_breaches b
   where b.team_member_id = p_member and b.period = p_period
     and (p_with_void or b.voided_at is null)
$$;

create or replace function public.perf_breach_log(p_token text, p_member uuid, p_payload jsonb)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  err text; m public.team_members; on_ date; p date; cat text; sev integer; rep boolean;
  st text; nb public.perf_breaches; cl uuid;
begin
  err := public.perf_check(p_token, 'work');
  if err is not null then return jsonb_build_object('error', err); end if;
  m := public.ops_me();
  if p_member = m.id then return jsonb_build_object('error', 'own-review'); end if;
  if not exists (select 1 from public.team_members where id = p_member and active) then
    return jsonb_build_object('error', 'not-found');
  end if;
  begin on_ := (p_payload ->> 'occurred_on')::date; exception when others then on_ := null; end;
  if on_ is null or on_ > (now() at time zone 'Asia/Kuala_Lumpur')::date then return jsonb_build_object('error', 'bad-date'); end if;
  cat := p_payload ->> 'category';
  if cat is null or cat not in ('client', 'delivery', 'compliance', 'asset') then
    return jsonb_build_object('error', 'bad-category');
  end if;
  sev := case when (p_payload ->> 'severity') ~ '^[1-4]$' then (p_payload ->> 'severity')::integer end;
  if sev is null then return jsonb_build_object('error', 'bad-severity'); end if;
  if coalesce(btrim(p_payload ->> 'what'), '') = '' then return jsonb_build_object('error', 'what-needed'); end if;
  /* The client it concerns, optional (2026-10-15): a VIC client's issue
     counts double, stamped at logging. */
  if nullif(p_payload ->> 'client_id', '') is not null then
    begin cl := (p_payload ->> 'client_id')::uuid; exception when others then cl := null; end;
    if cl is null or not exists (select 1 from public.clients c where c.id = cl) then
      return jsonb_build_object('error', 'bad-client');
    end if;
  end if;
  p := date_trunc('month', on_)::date;
  select status into st from public.perf_reviews where team_member_id = p_member and period = p;
  if st is not null and st <> 'draft' then
    return jsonb_build_object('error', 'month-released', 'month', public.perf_month_word(p));
  end if;
  /* The same kind of breach earlier in the same quarter is a repeat, unless
     the reviewer says otherwise. */
  rep := case when p_payload ? 'repeated' and jsonb_typeof(p_payload -> 'repeated') = 'boolean'
              then (p_payload ->> 'repeated')::boolean
              else exists (select 1 from public.perf_breaches b
                            where b.team_member_id = p_member and b.category = cat
                              and b.voided_at is null
                              and date_trunc('quarter', b.occurred_on) = date_trunc('quarter', on_)
                              and b.occurred_on <= on_) end;
  insert into public.perf_breaches (team_member_id, occurred_on, period, category, severity,
                                    repeated, late, what, evidence, logged_by, client_id)
  values (p_member, on_, p, cat, sev, rep, coalesce((p_payload ->> 'late')::boolean, false),
          btrim(p_payload ->> 'what'), nullif(btrim(p_payload ->> 'evidence'), ''), m.id, cl)
  returning * into nb;
  perform public.perf_log((select id from public.perf_reviews where team_member_id = p_member and period = p),
    p_member, 'breach_logged', jsonb_build_object('breach', nb.id, 'category', cat, 'severity', sev,
      'repeated', rep, 'late', nb.late, 'vic', nb.vic,
      'deduction', public.perf_deduction_vic_at(sev, rep, nb.late, nb.vic, p)));
  return jsonb_build_object('ok', true, 'id', nb.id, 'repeated', rep, 'vic', nb.vic,
    'deduction', public.perf_deduction_vic_at(sev, rep, nb.late, nb.vic, p), 'period', p);
end $$;

revoke all on function public.perf_breaches_json(uuid, date, boolean) from public, anon, authenticated;
revoke all on function public.perf_breach_log(text, uuid, jsonb) from public, anon, authenticated;
grant execute on function public.perf_breach_log(text, uuid, jsonb) to authenticated;

-- END OF AN ISSUE PRICED BY ITS MONTH ---------------------------------------

-- ===========================================================================
-- REVIEW SET COUNTS — where each content set's posts stand, counted by the
-- database in one request. 2026-10-18. Safe to run twice. Rollback at the
-- foot. Mirrored byte for byte in supabase/schema.sql under the same banner;
-- tests/sql.js compares the two.
--
-- WHAT CHANGED
--   The Dashboard's Sets waiting on clients and My Work's Waiting for you
--   (Client changes, Awaiting approval) read every post of the sets they
--   showed, then every decision on those posts, passing up to a thousand
--   ids in the address. PostgREST answers at most a thousand rows a read,
--   so past that the counts stopped short without a word (second audit,
--   item 14). review_set_counts(p_sets) answers, for each set named, its
--   posts, how many the client approved, how many have changes requested,
--   how many are undecided, and when the oldest standing change request was
--   made. A post's decision is the newest that stands on its round on show
--   (not undone, its round, after any re-approval request), as the set's
--   own page reads it.
--   Security invoker: it reads posts and reviews under their own policies
--   (Content Review: Sets at View, client scope), so it answers nothing a
--   colleague could not read row by row.
--
-- ROLLBACK
--   drop function if exists public.review_set_counts(uuid[]);
--   (the pages then read the posts as before; deploy the earlier pages first)
-- ===========================================================================

create or replace function public.review_set_counts(p_sets uuid[])
returns table (set_id uuid, n_posts integer, n_approved integer, n_changes integer,
               n_undecided integer, changes_since timestamptz)
language sql stable security invoker set search_path = public as $$
  with p as (
    select po.id, po.batch_id, coalesce(po.round, 1) as rnd, po.review_reset_at
      from public.posts po
     where po.batch_id = any(p_sets[1:500])
  ), d as (
    select distinct on (p.id) p.id, p.batch_id, r.decision, r.created_at
      from p
      left join public.reviews r
        on r.post_id = p.id and r.undone_at is null and coalesce(r.round, 1) = p.rnd
       and (p.review_reset_at is null or r.created_at > p.review_reset_at)
     order by p.id, r.created_at desc nulls last
  )
  select d.batch_id,
         count(*)::integer,
         (count(*) filter (where d.decision = 'approved'))::integer,
         (count(*) filter (where d.decision = 'changes'))::integer,
         (count(*) filter (where d.decision is null))::integer,
         min(d.created_at) filter (where d.decision = 'changes')
    from d
   group by d.batch_id
$$;

revoke all on function public.review_set_counts(uuid[]) from public, anon;
grant execute on function public.review_set_counts(uuid[]) to authenticated;

-- END OF REVIEW SET COUNTS --------------------------------------------------

-- ===========================================================================
-- BREACH POINTS ADDED AS NUMBERS — an issue's points are kept to the decimal
-- the settings give, and the month's total is rounded once. 2026-10-18.
-- Safe to run twice. Rollback at the foot. Mirrored byte for byte in
-- supabase/schema.sql under the same banner; tests/perf.js compares the two.
--
-- WHAT CHANGED (second audit, item 11)
--   Breach points are settings to two decimals (perf_settings_set), but
--   perf_deduction_at returned an integer and perf_deduction_vic_at rounded
--   again after the VIC multiplier, so each issue was rounded on its own:
--   Level 1 at 2.5 taken twice cost 6, not 5, and a 75 month fell to 69,
--   below C at 70. perf_calc also cast the cap to a whole number.
--   * `perf_points_at(severity, repeated, late, vic, at)` (new, no page's to
--     call): an issue's points as a number, the multiplier on the exact sum.
--   * perf_calc adds them exactly, rounds the month's total once to the 0.1
--     step the scores take (so the final score is always one the page
--     shows), then applies the cap as a number. `deduction` and
--     `deduction_raw` may now carry one decimal; the page, the printed
--     record and the stand-in already read them as numbers. A final month
--     keeps the result it was finalised with.
--   * perf_breaches_json and perf_breach_log answer each issue's points to
--     the cent of a point (two decimals).
--   No live setting holds a decimal (checked 2026-10-18), so no month open
--   today reads differently.
--   perf_deduction_at and perf_deduction_vic_at stay as they were; nothing
--   in the last definitions calls them now.
--
-- ROLLBACK
--   Run the perf_calc and perf_breaches_json definitions of the VIC
--   PERFORMANCE section and the perf_breach_log definition of AN ISSUE
--   PRICED BY ITS MONTH in supabase/schema.sql again; perf_points_at may
--   stay (nothing else calls it).
-- ===========================================================================

/* An issue's points as a number, never rounded: the settings take two
   decimals and the VIC multiplier is applied to the exact sum. */
create or replace function public.perf_points_at(p_severity integer, p_repeated boolean, p_late boolean,
                                                 p_vic boolean, p_at date)
returns numeric
language sql stable security definer set search_path = public as $$
  select (- coalesce(case p_severity when 1 then public.perf_setting('ded_l1', p_at) when 2 then public.perf_setting('ded_l2', p_at)
                                    when 3 then public.perf_setting('ded_l3', p_at) when 4 then public.perf_setting('ded_l4', p_at) end, 0)
          - case when p_repeated then public.perf_setting('ded_repeat', p_at) else 0 end
          - case when p_late then public.perf_setting('ded_late', p_at) else 0 end)
         * case when p_vic then coalesce(public.perf_setting('ded_vic', p_at), 1) else 1 end
$$;
revoke all on function public.perf_points_at(integer, boolean, boolean, boolean, date) from public, anon, authenticated;

create or replace function public.perf_breaches_json(p_member uuid, p_period date, p_with_void boolean)
returns jsonb
language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', b.id, 'occurred_on', b.occurred_on, 'category', b.category,
           'severity', b.severity, 'repeated', b.repeated, 'late', b.late,
           'what', b.what, 'evidence', b.evidence,
           'deduction', round(public.perf_points_at(b.severity, b.repeated, b.late, b.vic, p_period), 2),
           'client_id', b.client_id, 'client_name', (select c.name from public.clients c where c.id = b.client_id),
           'vic', b.vic, 'vic_x', case when b.vic then public.perf_setting('ded_vic', p_period) end,
           'logged_by', (select name from public.team_members where id = b.logged_by),
           'logged_at', b.logged_at, 'voided_at', b.voided_at, 'void_reason', b.void_reason)
         order by b.occurred_on, b.logged_at), '[]'::jsonb)
    from public.perf_breaches b
   where b.team_member_id = p_member and b.period = p_period
     and (p_with_void or b.voided_at is null)
$$;

create or replace function public.perf_calc(r public.perf_reviews)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  base numeric; raw_ded numeric; ded numeric; fin numeric; l3 boolean; l4 boolean;
  g text; cap integer; rk integer; prev public.perf_reviews; prev_g text; ok boolean;
  complete boolean; path text; ads boolean; bd text; bc text; bm text;
  rank_of constant text := 'ABCDE';
  v_cap numeric;
begin
  if r.status = 'final' and r.result is not null then return r.result; end if;
  complete := r.s_output is not null and r.s_accuracy is not null and r.s_delivery is not null
          and r.s_client is not null and r.s_comms is not null and r.s_initiative is not null;
  base := coalesce(r.s_output, 0) + coalesce(r.s_accuracy, 0) + coalesce(r.s_delivery, 0)
        + coalesce(r.s_client, 0) + coalesce(r.s_comms, 0) + coalesce(r.s_initiative, 0);
  /* Each issue's points exactly as the settings give them (two decimals,
     times the VIC multiplier), the month's total rounded once, to the 0.1
     step the scores take, before the cap. */
  select round(coalesce(sum(public.perf_points_at(severity, repeated, late, vic, r.period)), 0), 1),
         coalesce(bool_or(severity = 3), false), coalesce(bool_or(severity = 4), false)
    into raw_ded, l3, l4
    from public.perf_breaches
   where team_member_id = r.team_member_id and period = r.period and voided_at is null;
  v_cap := public.perf_setting('ded_cap', r.period);
  ded := greatest(raw_ded, -v_cap);
  fin := greatest(0, least(100, base + ded));
  g := public.perf_grade_at(fin, r.period);
  cap := case when l4 then 4 when l3 then 2 else 0 end;
  rk := greatest(position(g in rank_of), cap);
  g := substr(rank_of, rk, 1);

  select * into prev from public.perf_reviews
   where team_member_id = r.team_member_id and period = (r.period - interval '1 month')::date
     and status <> 'draft';
  if prev.id is not null then
    prev_g := (public.perf_calc(prev)) ->> 'grade';
  end if;
  ok := (g in ('A', 'B') or (g = 'C' and prev_g is distinct from 'C')) and not l3 and not l4;
  path := case when g = 'E' or l3 or l4 then 'accountability' when g = 'D' then 'development' end;

  ads := coalesce((select runs_ads from public.perf_people where team_member_id = r.team_member_id), false);
  bd := (select b from unnest(array[public.perf_band(r.r_posting, 95), public.perf_band(r.r_timeline, 90)]) b
          where b is not null order by position(b in 'green amber red') desc limit 1);
  bc := (select b from unnest(array[public.perf_band(r.r_satisfaction, 90),
                                    case when ads then public.perf_pacing_band(r.r_pacing) end]) b
          where b is not null order by position(b in 'green amber red') desc limit 1);
  bm := public.perf_band(r.r_sla, 90);

  return jsonb_build_object(
    'complete', complete, 'base', base, 'deduction', ded, 'deduction_raw', raw_ded,
    'final', fin, 'cap', v_cap,
    'points', jsonb_build_object('1', public.perf_setting('ded_l1', r.period), '2', public.perf_setting('ded_l2', r.period),
                                 '3', public.perf_setting('ded_l3', r.period), '4', public.perf_setting('ded_l4', r.period),
                                 'repeat', public.perf_setting('ded_repeat', r.period), 'late', public.perf_setting('ded_late', r.period),
                                 'vic', public.perf_setting('ded_vic', r.period)),
    'raw_grade', public.perf_grade_at(fin, r.period), 'grade', g,
    'grade_word', public.perf_grade_word(g),
    'capped', case when rk > position(public.perf_grade_at(fin, r.period) in rank_of) then (case when l4 then 'D' else 'B' end) end,
    'l3', l3, 'l4', l4, 'review', l4,
    'eligible', ok, 'previous_grade', prev_g,
    'path', path,
    'suggested', jsonb_build_object(
      'delivery', case bd when 'green' then 15 when 'amber' then 12 when 'red' then 7.5 end,
      'delivery_band', bd,
      'client', case bc when 'green' then 20 when 'amber' then 16 when 'red' then 10 end,
      'client_band', bc,
      'comms', case bm when 'green' then 15 when 'amber' then 12 when 'red' then 7.5 end,
      'comms_band', bm));
end $$;

create or replace function public.perf_breach_log(p_token text, p_member uuid, p_payload jsonb)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  err text; m public.team_members; on_ date; p date; cat text; sev integer; rep boolean;
  st text; nb public.perf_breaches; cl uuid;
begin
  err := public.perf_check(p_token, 'work');
  if err is not null then return jsonb_build_object('error', err); end if;
  m := public.ops_me();
  if p_member = m.id then return jsonb_build_object('error', 'own-review'); end if;
  if not exists (select 1 from public.team_members where id = p_member and active) then
    return jsonb_build_object('error', 'not-found');
  end if;
  begin on_ := (p_payload ->> 'occurred_on')::date; exception when others then on_ := null; end;
  if on_ is null or on_ > (now() at time zone 'Asia/Kuala_Lumpur')::date then return jsonb_build_object('error', 'bad-date'); end if;
  cat := p_payload ->> 'category';
  if cat is null or cat not in ('client', 'delivery', 'compliance', 'asset') then
    return jsonb_build_object('error', 'bad-category');
  end if;
  sev := case when (p_payload ->> 'severity') ~ '^[1-4]$' then (p_payload ->> 'severity')::integer end;
  if sev is null then return jsonb_build_object('error', 'bad-severity'); end if;
  if coalesce(btrim(p_payload ->> 'what'), '') = '' then return jsonb_build_object('error', 'what-needed'); end if;
  /* The client it concerns, optional (2026-10-15): a VIC client's issue
     counts double, stamped at logging. */
  if nullif(p_payload ->> 'client_id', '') is not null then
    begin cl := (p_payload ->> 'client_id')::uuid; exception when others then cl := null; end;
    if cl is null or not exists (select 1 from public.clients c where c.id = cl) then
      return jsonb_build_object('error', 'bad-client');
    end if;
  end if;
  p := date_trunc('month', on_)::date;
  select status into st from public.perf_reviews where team_member_id = p_member and period = p;
  if st is not null and st <> 'draft' then
    return jsonb_build_object('error', 'month-released', 'month', public.perf_month_word(p));
  end if;
  /* The same kind of breach earlier in the same quarter is a repeat, unless
     the reviewer says otherwise. */
  rep := case when p_payload ? 'repeated' and jsonb_typeof(p_payload -> 'repeated') = 'boolean'
              then (p_payload ->> 'repeated')::boolean
              else exists (select 1 from public.perf_breaches b
                            where b.team_member_id = p_member and b.category = cat
                              and b.voided_at is null
                              and date_trunc('quarter', b.occurred_on) = date_trunc('quarter', on_)
                              and b.occurred_on <= on_) end;
  insert into public.perf_breaches (team_member_id, occurred_on, period, category, severity,
                                    repeated, late, what, evidence, logged_by, client_id)
  values (p_member, on_, p, cat, sev, rep, coalesce((p_payload ->> 'late')::boolean, false),
          btrim(p_payload ->> 'what'), nullif(btrim(p_payload ->> 'evidence'), ''), m.id, cl)
  returning * into nb;
  perform public.perf_log((select id from public.perf_reviews where team_member_id = p_member and period = p),
    p_member, 'breach_logged', jsonb_build_object('breach', nb.id, 'category', cat, 'severity', sev,
      'repeated', rep, 'late', nb.late, 'vic', nb.vic,
      'deduction', round(public.perf_points_at(sev, rep, nb.late, nb.vic, p), 2)));
  return jsonb_build_object('ok', true, 'id', nb.id, 'repeated', rep, 'vic', nb.vic,
    'deduction', round(public.perf_points_at(sev, rep, nb.late, nb.vic, p), 2), 'period', p);
end $$;

revoke all on function public.perf_breaches_json(uuid, date, boolean) from public, anon, authenticated;
revoke all on function public.perf_calc(public.perf_reviews) from public, anon, authenticated;
revoke all on function public.perf_breach_log(text, uuid, jsonb) from public, anon, authenticated;
