-- END OF BREACH POINTS ADDED AS NUMBERS -------------------------------------

-- ===========================================================================
-- SLOTS HOLD THEIR BOOKINGS — a campaign never books more creators than its
-- slots, and its slots never drop below the creators booked. 2026-10-18.
-- Safe to run twice. Rollback at the foot. Mirrored byte for byte in
-- supabase/schema.sql under the same banner; tests/sql.js compares the two.
--
-- WHAT CHANGED (second audit, item 10)
--   confirm_selection_with compared the client's picks with the whole of
--   the slots, and campaign_confirm_creators checked no slots at all: ten
--   slots with six booked took ten more picks and booked sixteen. Both now
--   refuse `over-slots` (with the slots and the creators booked) where the
--   creators booked (campaign_booked) and those confirmed now would pass
--   the slots. Each is restated whole from CONFIRM ONCE with that one
--   check added; every other refusal stands.
--   Lowering a campaign's slots below its bookings was refused on the page
--   alone; trigger campaigns_slots_floor now refuses it (`slots-booked`,
--   a check violation naming the count), whoever writes it.
--
-- ROLLBACK
--   Run the CONFIRM ONCE section of supabase/migrations/2026-10-10-confirm-once.sql
--   again (confirm_selection_with and campaign_confirm_creators as before),
--   then: drop trigger if exists campaigns_slots_floor on public.campaigns;
--         drop function if exists public.campaigns_slots_floor();
-- ===========================================================================

create or replace function public.confirm_selection_with(
  p_token text, p_person text, p_passcode text, p_selected uuid[], p_backup uuid[],
  p_seen jsonb, p_idem text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  c      campaigns%rowtype;
  v_sel  uuid[];
  v_bak  uuid[];
  v_all  uuid[];
  v_idem text := left(nullif(btrim(coalesce(p_idem, '')), ''), 64);
  v_now  jsonb;
  v_snap jsonb;
  n      integer;
  v_booked integer;
begin
  select * into c from campaigns where access_token = p_token for update;
  if not found then return jsonb_build_object('error', 'not-found'); end if;
  if c.passcode is not null and c.passcode <> ''
     and (p_passcode is null or p_passcode <> c.passcode) then
    return jsonb_build_object('error', 'passcode');
  end if;
  if coalesce(trim(p_person), '') = '' then
    return jsonb_build_object('error', 'name-required');
  end if;
  -- The same press again: the first answer stands and nothing is filed twice.
  if v_idem is not null and exists (select 1 from campaign_confirmations k
                                     where k.campaign_id = c.id and k.idem = v_idem) then
    return jsonb_build_object('ok', true, 'again', true);
  end if;

  v_sel := array(select distinct x from unnest(coalesce(p_selected, '{}'::uuid[])) x where x is not null);
  v_bak := case when coalesce(c.backups_open, false)
                then array(select distinct x from unnest(coalesce(p_backup, '{}'::uuid[])) x
                            where x is not null and not (x = any (v_sel)))
                else '{}'::uuid[] end;
  v_all := v_sel || v_bak;
  n := cardinality(v_sel);

  if c.selection_closed_at is not null and not (coalesce(c.backups_open, false) and n = 0) then
    return jsonb_build_object('error', 'closed');
  end if;
  if cardinality(v_all) = 0 then return jsonb_build_object('error', 'empty'); end if;
  -- The slots left are the slots less the creators already booked: a
  -- selection reopened for four of ten never books sixteen.
  v_booked := public.campaign_booked(c.id);
  if n > 0 and n > c.slots - v_booked then
    return jsonb_build_object('error', 'over-slots', 'slots', c.slots, 'booked', v_booked);
  end if;
  -- Every creator named is still on the campaign and open to choose.
  if (select count(*) from campaign_options o
       where o.id = any (v_all) and o.campaign_id = c.id
         and o.state in ('option', 'shortlisted', 'backup')) <> cardinality(v_all) then
    return jsonb_build_object('error', 'stale');
  end if;
  -- The prices the client read are the prices now.
  select jsonb_object_agg(o.id::text, o.rate) into v_now
    from campaign_options o where o.id = any (v_all);
  if exists (select 1 from campaign_options o
              where o.id = any (v_all)
                and coalesce(p_seen -> (o.id::text), 'null'::jsonb)
                    is distinct from coalesce(to_jsonb(o.rate), 'null'::jsonb)) then
    return jsonb_build_object('error', 'prices', 'rates', v_now);
  end if;

  update campaign_options set state = 'option'
   where campaign_id = c.id and state in ('shortlisted', 'backup');
  if n > 0 then
    update campaign_options set state = 'shortlisted'
     where campaign_id = c.id and id = any (v_sel) and state = 'option';
  end if;
  if cardinality(v_bak) > 0 then
    update campaign_options set state = 'backup'
     where campaign_id = c.id and id = any (v_bak) and state = 'option';
  end if;

  select jsonb_agg(jsonb_build_object('id', o.id, 'creator', cr.name, 'rate', o.rate, 'as', o.state)
                   order by o.position, o.added_at)
    into v_snap
    from campaign_options o join creators cr on cr.id = o.creator_id
   where o.id = any (v_all);
  insert into campaign_confirmations (campaign_id, kind, person, source, idem, snapshot)
  values (c.id, 'client', trim(p_person), 'portal', v_idem, coalesce(v_snap, '[]'::jsonb));

  insert into public.activity_log (actor, action, subject, detail)
  values (trim(p_person), 'campaign.confirmed', c.title,
          case when n > 0 then n::text || ' creator' || case when n = 1 then '' else 's' end || ' confirmed'
               else cardinality(v_bak)::text || ' backup' || case when cardinality(v_bak) = 1 then '' else 's' end || ' confirmed' end);

  return jsonb_build_object('ok', true, 'selected', n);
end $$;

revoke all on function public.confirm_selection_with(text, text, text, uuid[], uuid[], jsonb, text) from public;
grant execute on function public.confirm_selection_with(text, text, text, uuid[], uuid[], jsonb, text) to anon, authenticated;

create or replace function public.campaign_confirm_creators(
  p_campaign uuid, p_options uuid[], p_person text, p_source text, p_idem text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me       public.team_members;
  c        public.campaigns%rowtype;
  v_ids    uuid[] := array(select distinct x from unnest(coalesce(p_options, '{}'::uuid[])) x where x is not null);
  v_idem   text := left(nullif(btrim(coalesce(p_idem, '')), ''), 64);
  v_person text;
  v_source text := case when p_source in ('portal', 'whatsapp', 'email', 'call') then p_source else 'whatsapp' end;
  v_ok     integer;
  v_snap   jsonb;
  v_booked integer;
begin
  if not public.allowed('campaigns.campaigns', 'work') then
    return jsonb_build_object('error', 'denied');
  end if;
  select * into me from public.ops_me();
  if me.id is null then return jsonb_build_object('error', 'denied'); end if;
  select * into c from public.campaigns where id = p_campaign for update;
  if not found then return jsonb_build_object('error', 'not-found'); end if;
  if not public.client_scope_ok('campaign', c.id, 'work') then
    return jsonb_build_object('error', 'client-scope');
  end if;
  if v_idem is not null and exists (select 1 from public.campaign_confirmations k
                                     where k.campaign_id = c.id and k.idem = v_idem) then
    return jsonb_build_object('ok', true, 'again', true);
  end if;
  if cardinality(v_ids) = 0 then return jsonb_build_object('error', 'empty'); end if;
  select count(*) into v_ok from public.campaign_options o
   where o.id = any (v_ids) and o.campaign_id = c.id and o.state = 'shortlisted';
  if v_ok <> cardinality(v_ids) then
    return jsonb_build_object('error', 'stale', 'count', cardinality(v_ids) - v_ok);
  end if;
  -- Never more booked than the campaign's slots (second audit, item 10).
  v_booked := public.campaign_booked(c.id);
  if v_booked + cardinality(v_ids) > coalesce(c.slots, 0) then
    return jsonb_build_object('error', 'over-slots', 'slots', c.slots, 'booked', v_booked);
  end if;
  v_person := coalesce(nullif(btrim(coalesce(p_person, '')), ''), me.name);

  select jsonb_agg(jsonb_build_object('id', o.id, 'creator', cr.name, 'rate', o.rate, 'as', o.state)
                   order by o.position, o.added_at)
    into v_snap
    from public.campaign_options o join public.creators cr on cr.id = o.creator_id
   where o.id = any (v_ids);
  insert into public.campaign_confirmations (campaign_id, kind, person, source, idem, snapshot)
  values (c.id, case when v_source = 'portal' then 'client' else 'keyed_in' end,
          v_person, v_source, v_idem, coalesce(v_snap, '[]'::jsonb));
  update public.campaign_options
     set state = 'confirmed', confirmed_at = now(), confirmed_by = v_person
   where id = any (v_ids);
  update public.campaigns set state = 'production' where id = c.id;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'campaign.locked', c.title,
          cardinality(v_ids)::text || ' creators · ' || v_person);

  return jsonb_build_object('ok', true, 'confirmed', cardinality(v_ids));
end $$;
revoke all on function public.campaign_confirm_creators(uuid, uuid[], text, text, text) from public, anon;
grant execute on function public.campaign_confirm_creators(uuid, uuid[], text, text, text) to authenticated;

/* A slot holding a booked creator is never taken away by editing a number:
   free the booking first, then lower the count. */
create or replace function public.campaigns_slots_floor()
returns trigger
language plpgsql security definer set search_path = public as $$
declare
  v_booked integer;
begin
  if new.slots is distinct from old.slots then
    v_booked := public.campaign_booked(new.id);
    if coalesce(new.slots, 0) < v_booked then
      raise exception 'slots-booked: % creators are booked', v_booked
        using errcode = '23514', hint = 'slots-booked';
    end if;
  end if;
  return new;
end $$;
revoke all on function public.campaigns_slots_floor() from public, anon, authenticated;
create or replace trigger campaigns_slots_floor
  before update of slots on public.campaigns
  for each row execute function public.campaigns_slots_floor();

-- END OF SLOTS HOLD THEIR BOOKINGS ------------------------------------------

-- ===========================================================================
-- SCHEDULED JOBS WATCHED — a scheduled job that fails is told to the admins
-- the next morning, and the job history and old read notices are pruned.
-- 2026-10-18. Safe to run twice. Rollback at the foot. Mirrored byte for
-- byte in supabase/schema.sql under the same banner; tests/sql.js compares
-- the two.
--
-- WHAT CHANGED (second audit, item 4)
--   Nothing read cron.job_run_details, and the kicks and notification
--   fan-outs swallow their own errors by design (a notice never fails the
--   write that caused it), so a reminder, a repeat or the S3 report that
--   stopped working stopped silently.
--   * jobs_watch(p_now) (pg_cron `jobs-watch`, 08:20 MYT daily) counts the
--     scheduled runs that failed in the 24 hours before p_now, by job, and
--     the S3 reports filed as failed (s3_sweeps mode `failed`), and names an
--     S3 report that did not arrive at all in 26 hours while its job is on
--     (the job posts to the edge function, so its run succeeds whether or
--     not the function answers). Where anything failed, each active admin
--     is told once that day (kind `jobs.failed`, the bell and a push; never
--     WhatsApp), the jobs and their counts in the words.
--   * jobs_prune(p_now) (pg_cron `jobs-prune`, 03:40 MYT daily) removes job
--     history older than 14 days and notices read more than 90 days ago,
--     never a colleague's notice (Notices count its copies as Read by).
--   Neither is any page's to call. On a database without pg_cron both
--   functions leave the job history alone and no job is scheduled.
--
-- ROLLBACK
--   select cron.unschedule(jobid) from cron.job where jobname in ('jobs-watch', 'jobs-prune');
--   drop function if exists public.jobs_watch(timestamptz);
--   drop function if exists public.jobs_prune(timestamptz);
-- ===========================================================================

create or replace function public.jobs_watch(p_now timestamptz default now())
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_jobs jsonb := '[]'::jsonb;
  v_runs integer := 0;
  v_sweeps integer := 0;
  v_quiet boolean := false;
  v_words text;
  v_day text := to_char(p_now at time zone 'Asia/Kuala_Lumpur', 'YYYY-MM-DD');
  v_told integer := 0;
begin
  if to_regclass('cron.job_run_details') is not null then
    select coalesce(jsonb_agg(jsonb_build_object('job', x.name, 'failed', x.n) order by x.n desc, x.name), '[]'::jsonb),
           coalesce(sum(x.n), 0)::int
      into v_jobs, v_runs
      from (select coalesce(j.jobname, 'job ' || d.jobid) as name, count(*)::int as n
              from cron.job_run_details d
              left join cron.job j on j.jobid = d.jobid
             where d.status = 'failed' and d.start_time >= p_now - interval '24 hours' and d.start_time < p_now
             group by 1) x;
    /* The S3 report's job posts to its edge function and succeeds either
       way: a report that never arrived is a failure too. */
    v_quiet := exists (select 1 from cron.job j where j.jobname = 's3-sweep-daily' and j.active)
           and not exists (select 1 from public.s3_sweeps s where s.ran_at >= p_now - interval '26 hours' and s.ran_at < p_now);
  end if;
  select count(*)::int into v_sweeps from public.s3_sweeps s
   where s.mode = 'failed' and s.ran_at >= p_now - interval '24 hours' and s.ran_at < p_now;

  if v_runs = 0 and v_sweeps = 0 and not v_quiet then
    return jsonb_build_object('failed', 0, 'told', 0);
  end if;
  v_words := concat_ws('; ',
    nullif((select string_agg((e ->> 'job') || ' failed ' || (e ->> 'failed') ||
                              case when (e ->> 'failed')::int = 1 then ' time' else ' times' end, '; ')
              from jsonb_array_elements(v_jobs) e), ''),
    case when v_sweeps > 0 then 'the S3 report was filed as failed' end,
    case when v_quiet then 'the S3 report did not arrive' end) || '.';
  insert into public.ops_notifications (team_member_id, kind, title, body, dedupe_key)
  select t.id, 'jobs.failed', 'Scheduled jobs failed in the last 24 hours',
         v_words, 'jobs.failed.' || v_day || '.' || t.id
    from public.team_members t
   where t.active and t.is_admin
  on conflict (dedupe_key) do nothing;
  get diagnostics v_told = row_count;
  return jsonb_build_object('failed', v_runs + v_sweeps + case when v_quiet then 1 else 0 end,
    'jobs', v_jobs, 'sweeps', v_sweeps, 'sweep_missing', v_quiet, 'told', v_told);
end $$;
revoke all on function public.jobs_watch(timestamptz) from public, anon, authenticated;

create or replace function public.jobs_prune(p_now timestamptz default now())
returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_runs integer := 0; v_notes integer := 0;
begin
  if to_regclass('cron.job_run_details') is not null then
    delete from cron.job_run_details d where d.end_time < p_now - interval '14 days';
    get diagnostics v_runs = row_count;
  end if;
  /* A colleague's notice (notice_id) stays: Notices read its copies. */
  delete from public.ops_notifications n
   where n.read_at is not null and n.created_at < p_now - interval '90 days' and n.notice_id is null;
  get diagnostics v_notes = row_count;
  return jsonb_build_object('job_runs', v_runs, 'notices', v_notes);
end $$;
revoke all on function public.jobs_prune(timestamptz) from public, anon, authenticated;

do $$
begin
  if not exists (select 1 from pg_extension where extname = 'pg_cron') then
    raise notice 'pg_cron is not enabled: scheduled jobs are not watched until it is.';
    return;
  end if;
  perform cron.unschedule(j.jobid) from cron.job j where j.jobname in ('jobs-watch', 'jobs-prune');
  perform cron.schedule('jobs-watch', '20 0 * * *', 'select public.jobs_watch()');
  perform cron.schedule('jobs-prune', '40 19 * * *', 'select public.jobs_prune()');
end $$;

-- END OF SCHEDULED JOBS WATCHED ---------------------------------------------

-- ===========================================================================
-- CONFIRMATIONS KEPT — a client's acceptance of its creators is written once,
-- by its function, and outlives the campaign it confirmed; a campaign's
-- delete is filed by the database. 2026-10-18. Safe to run twice. Rollback
-- at the foot. Mirrored byte for byte in supabase/schema.sql under the same
-- banner; tests/confirmonce.js compares the two.
--
-- WHAT CHANGED (second audit, item 13)
--   1. `campaign_confirmations` is the record of who accepted which creators
--      at which rates. Its insert, update and delete policies let any
--      colleague at Creator Campaigns Work rewrite it and one at Manage
--      remove it. They now admit nothing: every row is written by
--      confirm_selection_with, confirm_selection or campaign_confirm_creators
--      (security definer), and none is changed or removed afterwards.
--   2. Each row keeps the campaign's title and client (`campaign_title`,
--      `client_id`, stamped on insert by campaign_confirmations_stamp and
--      filled in once for the rows before), and the campaign's foreign key,
--      which deleted the rows with the campaign, is taken off: a deleted
--      campaign leaves its confirmations, still naming it.
--   3. A campaign's delete is filed by trigger campaigns_deleted_log in the
--      transaction that deletes (`campaign.deleted`, the title, the invoice
--      number), as delete_client files its own; the page files nothing.
--
-- ROLLBACK
--   alter policy campaign_confirmations_write on public.campaign_confirmations
--     with check (public.allowed('campaigns.campaigns', 'work'));
--   alter policy campaign_confirmations_edit on public.campaign_confirmations
--     using (public.allowed('campaigns.campaigns', 'work')) with check (public.allowed('campaigns.campaigns', 'work'));
--   alter policy campaign_confirmations_del on public.campaign_confirmations
--     using (public.allowed('campaigns.campaigns', 'manage'));
--   drop trigger if exists campaigns_deleted_log on public.campaigns;
--   drop trigger if exists campaign_confirmations_stamp on public.campaign_confirmations;
--   (deploy the earlier pages first, which file the delete themselves; the
--   foreign key is put back only once no row names a deleted campaign:
--   alter table public.campaign_confirmations add constraint
--     campaign_confirmations_campaign_id_fkey foreign key (campaign_id)
--     references public.campaigns(id) on delete cascade;)
-- ===========================================================================

alter table public.campaign_confirmations add column if not exists campaign_title text;
alter table public.campaign_confirmations add column if not exists client_id uuid;

update public.campaign_confirmations k
   set campaign_title = c.title, client_id = c.client_id
  from public.campaigns c
 where c.id = k.campaign_id and k.campaign_title is null;

create or replace function public.campaign_confirmations_stamp()
returns trigger
language plpgsql security definer set search_path = public as $$
begin
  select c.title, c.client_id into new.campaign_title, new.client_id
    from public.campaigns c where c.id = new.campaign_id;
  return new;
end $$;
revoke all on function public.campaign_confirmations_stamp() from public, anon, authenticated;
create or replace trigger campaign_confirmations_stamp
  before insert on public.campaign_confirmations
  for each row execute function public.campaign_confirmations_stamp();

alter table public.campaign_confirmations
  drop constraint if exists campaign_confirmations_campaign_id_fkey;

alter policy campaign_confirmations_write on public.campaign_confirmations with check (false);
alter policy campaign_confirmations_edit on public.campaign_confirmations using (false) with check (false);
alter policy campaign_confirmations_del on public.campaign_confirmations using (false);

create or replace function public.campaigns_deleted_log()
returns trigger
language plpgsql security definer set search_path = public as $$
declare
  who text := auth.jwt() ->> 'email';
  me  public.team_members;
begin
  if who is not null then
    select * into me from public.team_members where lower(email) = lower(who) and active limit 1;
  end if;
  insert into public.activity_log (actor, action, subject, detail)
  values (coalesce(me.name, who, 'system'), 'campaign.deleted', old.title, coalesce(old.invoice_no, ''));
  return old;
end $$;
revoke all on function public.campaigns_deleted_log() from public, anon, authenticated;
create or replace trigger campaigns_deleted_log
  after delete on public.campaigns
  for each row execute function public.campaigns_deleted_log();

-- END OF CONFIRMATIONS KEPT -------------------------------------------------

-- ===========================================================================
-- ONE REPEAT NEVER STOPS THE OTHERS — a repeating task that cannot be made
-- is kept as an error on its rule, and every other rule is made as usual.
-- 2026-10-18. Safe to run twice. Rollback at the foot. Mirrored byte for
-- byte in supabase/schema.sql under the same banner; tests/ops.js compares
-- the two.
--
-- WHAT CHANGED (second audit, item 15)
--   ops_generate_recurring returned at the first refusal, and a raised
--   error ended the whole call, so one rule that could no longer make its
--   task (a month gone, an owner who left) stopped every rule after it for
--   that colleague every night, and nobody was told.
--   * Each make runs in its own block: a refusal or an error undoes that
--     attempt alone, is kept on the rule (ops_recurring_rules.last_error,
--     last_error_at; cleared by the next task the rule makes), leaves that
--     rule's other dates for the next run, and the run goes on to the next
--     rule. The answer adds `failed` and `errors` (rule, date, words).
--   * jobs_watch counts the active rules that failed in the last 24 hours
--     in the admins' morning notice ("2 repeating tasks could not be made").
--
-- ROLLBACK
--   Run the ops_generate_recurring definition of the DAYS ON MALAYSIA'S
--   CALENDAR section and the jobs_watch definition of SCHEDULED JOBS
--   WATCHED in supabase/schema.sql again; the two columns may stay.
-- ===========================================================================

alter table public.ops_recurring_rules add column if not exists last_error text;
alter table public.ops_recurring_rules add column if not exists last_error_at timestamptz;

create or replace function public.ops_generate_recurring(
  p_period text, p_rules uuid[] default null, p_idem text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m     public.team_members;
  r     public.ops_recurring_rules;
  src   public.ops_tasks;
  made  integer := 0;
  skip  integer := 0;
  key   text;
  first_day date;
  last_day date;
  anchor date;
  d     date;
  stepd integer;
  one   jsonb;
  wk    integer;
  held  integer := 0;
  ccl   uuid;
  mon   public.ops_engagements;
  errs  jsonb := '[]'::jsonb;
begin
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if not public.allowed('ops', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if p_period !~ '^\d{4}-\d{2}$' then return jsonb_build_object('error', 'bad-period'); end if;
  first_day := (p_period || '-01')::date;
  last_day := (first_day + interval '1 month' - interval '1 day')::date;

  for r in select * from public.ops_recurring_rules
            where active and (p_rules is null or id = any (p_rules))
              and (source_task_id is null or public.ops_may_see_task(source_task_id)) loop
    if r.source_task_id is not null then
      select * into src from public.ops_tasks where id = r.source_task_id;
    else
      src := null;
    end if;

    /* A client's repeats wait for the client's month: one that exists, is
       open and has its content meeting set or marked not applicable. Until
       then the rule is held and counted, and a later run makes them. */
    ccl := case when src.id is not null then case when src.scope = 'client' then src.client_id end
                else r.client_id end;
    mon := null;
    if ccl is not null then
      select * into mon from public.ops_engagements x where x.client_id = ccl and x.period = p_period;
      if mon.id is null or mon.status in ('completed', 'cancelled')
         or (mon.meeting_at is null and not mon.meeting_na) then
        held := held + 1;
        continue;
      end if;
    end if;

    /* The dates this rule falls on inside the month. */
    if r.frequency = 'monthly' then
      d := first_day + (least(coalesce(r.day_of_month,
              case when src.publish_at is not null then extract(day from src.publish_at)::integer else 1 end),
              extract(day from last_day)::integer) - 1);
      stepd := null;
    else
      stepd := case when r.frequency = 'weekly' then 7 else greatest(1, coalesce(r.interval_days, 7)) end;
      anchor := coalesce(src.publish_at::date, (r.created_at at time zone 'Asia/Kuala_Lumpur')::date, first_day);
      if anchor > first_day then d := anchor;
      else d := anchor + ((((first_day - anchor) + stepd - 1) / stepd) * stepd); end if;
    end if;

    while d is not null and d <= last_day loop
      if d >= first_day
         /* The task a rule copies is its first occurrence: nothing on or
            before its day is made again. */
         and (src.id is null or d > coalesce(src.publish_at::date, (r.created_at at time zone 'Asia/Kuala_Lumpur')::date))
         and (r.ends_on is null or d <= r.ends_on)
         and (r.max_count is null or r.generated_count < r.max_count) then
        key := 'recur:' || r.id::text || ':' || to_char(d, 'YYYY-MM-DD');
        /* Made once is made: a copy since deleted stays deleted, and a rule
           set again on the same task makes none of its dates twice. */
        if exists (select 1 from public.ops_tasks where idem_key = key)
           or exists (select 1 from public.ops_recurring_made x
                       where x.on_date = d
                         and (x.rule_id = r.id
                              or (r.source_task_id is not null and x.source_task_id = r.source_task_id))) then
          skip := skip + 1;
        else
          wk := coalesce(r.code_week, least(5, ((extract(day from d)::integer - 1) / 7) + 1));
          /* One rule that cannot make its task never stops the others: the
             attempt is undone, its error kept on the rule and answered, and
             the run goes on to the next rule. */
          one := null;
          begin
            if src.id is not null then
              one := public.ops_duplicate_task(src.id, jsonb_build_object(
                'keep_desc', true, 'copy_dates', false, 'copy_assignees', true,
                'publish_at', d::timestamptz, 'code_period', p_period, 'code_week', wk,
                'engagement_id', mon.id), key);
            else
              one := public.ops_create_task(jsonb_build_object(
                'scope', case when r.client_id is null then 'internal' else 'client' end,
                'client_id', r.client_id, 'template_id', r.template_id,
                'title', r.name || ' — ' || p_period, 'content_desc', r.name,
                'owner_id', r.owner_id, 'publish_at', d::timestamptz,
                'code_period', p_period, 'code_week', wk, 'engagement_id', mon.id), key);
            end if;
            if one ? 'error' then raise exception using message = 'repeat-refused'; end if;
          exception when others then
            if one is null or not (one ? 'error') then one := jsonb_build_object('error', sqlerrm); end if;
          end;
          if one ? 'error' then
            errs := errs || jsonb_build_array(jsonb_build_object('rule', r.id, 'on', d, 'error', one ->> 'error'));
            update public.ops_recurring_rules
               set last_error = left(one ->> 'error', 500), last_error_at = now()
             where id = r.id;
            exit;
          end if;
          made := made + 1;
          insert into public.ops_recurring_made (rule_id, source_task_id, on_date)
          values (r.id, r.source_task_id, d) on conflict do nothing;
          update public.ops_recurring_rules
             set generated_count = generated_count + 1, last_generated_period = p_period, updated_at = now(),
                 last_error = null, last_error_at = null
           where id = r.id;
          r.generated_count := r.generated_count + 1;
        end if;
      end if;
      exit when stepd is null;
      d := d + stepd;
    end loop;
  end loop;
  return jsonb_build_object('created', made, 'skipped', skip, 'held', held, 'period', p_period,
    'failed', jsonb_array_length(errs), 'errors', errs);
end $$;

create or replace function public.jobs_watch(p_now timestamptz default now())
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_jobs jsonb := '[]'::jsonb;
  v_runs integer := 0;
  v_sweeps integer := 0;
  v_quiet boolean := false;
  v_words text;
  v_day text := to_char(p_now at time zone 'Asia/Kuala_Lumpur', 'YYYY-MM-DD');
  v_told integer := 0;
  v_rules integer := 0;
begin
  if to_regclass('cron.job_run_details') is not null then
    select coalesce(jsonb_agg(jsonb_build_object('job', x.name, 'failed', x.n) order by x.n desc, x.name), '[]'::jsonb),
           coalesce(sum(x.n), 0)::int
      into v_jobs, v_runs
      from (select coalesce(j.jobname, 'job ' || d.jobid) as name, count(*)::int as n
              from cron.job_run_details d
              left join cron.job j on j.jobid = d.jobid
             where d.status = 'failed' and d.start_time >= p_now - interval '24 hours' and d.start_time < p_now
             group by 1) x;
    /* The S3 report's job posts to its edge function and succeeds either
       way: a report that never arrived is a failure too. */
    v_quiet := exists (select 1 from cron.job j where j.jobname = 's3-sweep-daily' and j.active)
           and not exists (select 1 from public.s3_sweeps s where s.ran_at >= p_now - interval '26 hours' and s.ran_at < p_now);
  end if;
  select count(*)::int into v_sweeps from public.s3_sweeps s
   where s.mode = 'failed' and s.ran_at >= p_now - interval '24 hours' and s.ran_at < p_now;

  /* A repeat rule that could not make its task (ops_generate_recurring
     keeps the error on the rule and goes on to the next). */
  select count(*)::int into v_rules from public.ops_recurring_rules x
   where x.active and x.last_error_at >= p_now - interval '24 hours' and x.last_error_at < p_now;

  if v_runs = 0 and v_sweeps = 0 and not v_quiet and v_rules = 0 then
    return jsonb_build_object('failed', 0, 'told', 0);
  end if;
  v_words := concat_ws('; ',
    nullif((select string_agg((e ->> 'job') || ' failed ' || (e ->> 'failed') ||
                              case when (e ->> 'failed')::int = 1 then ' time' else ' times' end, '; ')
              from jsonb_array_elements(v_jobs) e), ''),
    case when v_sweeps > 0 then 'the S3 report was filed as failed' end,
    case when v_quiet then 'the S3 report did not arrive' end,
    case when v_rules > 0 then v_rules || case when v_rules = 1 then ' repeating task could' else ' repeating tasks could' end
                               || ' not be made' end) || '.';
  insert into public.ops_notifications (team_member_id, kind, title, body, dedupe_key)
  select t.id, 'jobs.failed', 'Scheduled jobs failed in the last 24 hours',
         v_words, 'jobs.failed.' || v_day || '.' || t.id
    from public.team_members t
   where t.active and t.is_admin
  on conflict (dedupe_key) do nothing;
  get diagnostics v_told = row_count;
  return jsonb_build_object('failed', v_runs + v_sweeps + case when v_quiet then 1 else 0 end + v_rules,
    'jobs', v_jobs, 'sweeps', v_sweeps, 'sweep_missing', v_quiet, 'repeats', v_rules, 'told', v_told);
end $$;

grant execute on function public.ops_generate_recurring(text, uuid[], text) to authenticated;
revoke all on function public.jobs_watch(timestamptz) from public, anon, authenticated;

-- END OF ONE REPEAT NEVER STOPS THE OTHERS ----------------------------------

-- ===========================================================================
-- S3 KEYS READ ONCE — the S3 report's in-use check reads each column once
-- a run, whatever the number of files asked about. 2026-10-18. Safe to run
-- twice. Rollback at the foot. Mirrored byte for byte in supabase/schema.sql
-- under the same banner; tests/s3sql.js compares the two.
--
-- WHAT CHANGED (second audit, item 16)
--   s3_keys_in_use scanned every text, json and array column of every table
--   once for each key still unresolved: with thousands of files listed and
--   586 such columns live (about 20 MB of text), the nightly report read
--   the database thousands of times over. The rule is unchanged (a file is
--   in use while a handed-in draft holds it, standing or removed within the
--   Undo's 30 days, or while any other column's text contains its key);
--   only the reading is:
--   * every key asked shares a prefix (the listing's `content/`), so any
--     value holding a key holds that prefix: each column is read once, for
--     its values holding it, joined by a character no key holds (chr(1)),
--     so a key is never found across two values;
--   * each key is then sought in that text alone, by the same strpos.
--   A key holding chr(1) itself (none is uploaded) is still sought column by
--   column, as before. The answer is the same set of keys; their order is
--   the order asked.
--
-- ROLLBACK
--   Run the s3_keys_in_use definition of the S3 SWEEP section of
--   supabase/schema.sql again.
-- ===========================================================================

create or replace function public.s3_keys_in_use(p_keys text[])
returns text[]
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_ask  text[];
  v_used text[];
  v_rest text[];
  v_hit  text[];
  v_pre  text;
  v_blob text := '';
  v_part text;
  k      text;
  col    record;
begin
  /* An empty key would match every value, so it is never asked. */
  select coalesce(array_agg(distinct x), '{}') into v_ask
    from unnest(coalesce(p_keys, '{}')) x
   where x is not null and btrim(x) <> '';
  if cardinality(v_ask) = 0 then return '{}'; end if;

  /* A handed-in draft: standing, or soft removed within the Undo's 30 days. */
  select coalesce(array_agg(x), '{}') into v_used
    from unnest(v_ask) x
   where exists (select 1 from public.campaign_deliverables d
                  where strpos(d.url, x) > 0
                    and (d.removed_at is null or d.removed_at > now() - interval '30 days'));
  v_rest := array(select x from unnest(v_ask) x where not (x = any(v_used)));
  if cardinality(v_rest) = 0 then return v_used; end if;

  /* What every key left begins with: a value holding a key holds it. */
  v_pre := v_rest[1];
  foreach k in array v_rest loop
    while v_pre <> '' and left(k, length(v_pre)) <> v_pre loop
      v_pre := left(v_pre, length(v_pre) - 1);
    end loop;
  end loop;

  /* Every other text-like column of every table, read once, its values
     holding the prefix joined by a character no key holds. */
  for col in
    select c.relname as tbl, a.attname as att
      from pg_class c
      join pg_namespace n on n.oid = c.relnamespace
      join pg_attribute a on a.attrelid = c.oid
     where n.nspname = 'public' and c.relkind in ('r', 'p')
       and a.attnum > 0 and not a.attisdropped
       and a.atttypid in ('text'::regtype, 'character varying'::regtype, 'json'::regtype,
                          'jsonb'::regtype, 'text[]'::regtype, 'character varying[]'::regtype)
       and not (c.relname = 'campaign_deliverables' and a.attname = 'url')
       and c.relname <> 's3_sweeps'
     order by c.relname, a.attnum
  loop
    execute format('select string_agg(x.%I::text, chr(1)) from public.%I x where strpos(x.%I::text, $1) > 0',
                   col.att, col.tbl, col.att)
      into v_part using v_pre;
    if v_part is not null then v_blob := v_blob || chr(1) || v_part; end if;
  end loop;
  v_hit := array(select x from unnest(v_rest) x where strpos(x, chr(1)) = 0 and strpos(v_blob, x) > 0);
  v_used := v_used || v_hit;

  /* A key holding the joining character itself is sought column by column. */
  if exists (select 1 from unnest(v_rest) x where strpos(x, chr(1)) > 0) then
    for col in
      select c.relname as tbl, a.attname as att
        from pg_class c
        join pg_namespace n on n.oid = c.relnamespace
        join pg_attribute a on a.attrelid = c.oid
       where n.nspname = 'public' and c.relkind in ('r', 'p')
         and a.attnum > 0 and not a.attisdropped
         and a.atttypid in ('text'::regtype, 'character varying'::regtype, 'json'::regtype,
                            'jsonb'::regtype, 'text[]'::regtype, 'character varying[]'::regtype)
         and not (c.relname = 'campaign_deliverables' and a.attname = 'url')
         and c.relname <> 's3_sweeps'
       order by c.relname, a.attnum
    loop
      execute format(
        'select coalesce(array_agg(distinct k), ''{}'') from unnest($1) k
          where exists (select 1 from public.%I x where strpos(x.%I::text, k) > 0)',
        col.tbl, col.att)
        into v_hit
        using array(select x from unnest(v_rest) x where strpos(x, chr(1)) > 0 and not (x = any(v_used)));
      v_used := v_used || v_hit;
    end loop;
  end if;

  return v_used;
end $$;
revoke all on function public.s3_keys_in_use(text[]) from public, anon, authenticated;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    grant execute on function public.s3_keys_in_use(text[]) to service_role;
  end if;
end $$;

-- END OF S3 KEYS READ ONCE --------------------------------------------------

-- ===========================================================================
-- SELECTION LINK CLOSES — a creator selection link closes with its client,
-- and the team can reset it. 2026-10-18. Safe to run twice. Rollback at the
-- foot. Mirrored byte for byte in supabase/schema.sql under the same banner;
-- tests/confirmonce.js compares the two.
--
-- WHAT CHANGED (second audit, item 5)
--   1. `get_campaign` read a campaign by its key whatever became of the
--      client, and the key was written once, as the campaign was made. It
--      now answers `not-found` once the campaign's client is Past, as for a
--      key nobody knows; `sign-download` and `media-pass` ask it first, so a
--      past client's invoice and files close with it. A completed campaign
--      of a current client stays readable: its link carries the results.
--      Restated whole from SELECTION SAYS CONFIRMED with that one check.
--   2. `campaign_reset_link(p_campaign)`: Creator Campaigns: Campaigns at
--      Work, the client in reach at Work (`denied`, `not-found`,
--      `client-scope`), gives the campaign a new key from new_link_key();
--      link_key_changed retires any moved key, so every earlier link stops
--      at once. Filed `campaign.edited` (Selection link reset).
--
-- ROLLBACK
--   Run get_campaign from SELECTION SAYS CONFIRMED again, then:
--   drop function if exists public.campaign_reset_link(uuid);
-- ===========================================================================

create or replace function public.get_campaign(p_token text, p_passcode text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  c campaigns%rowtype;
  cl clients%rowtype;
  billable boolean;
begin
  select * into c from campaigns where access_token = p_token;
  if not found then return jsonb_build_object('error', 'not-found'); end if;
  select * into cl from clients where id = c.client_id;
  -- A past client's links close (second audit, item 5): answered as a key
  -- nobody knows, so the page says the link is not recognised.
  if cl.stage = 'past' then return jsonb_build_object('error', 'not-found'); end if;

  -- An invoice belongs to an accepted booking. Until the client has chosen and
  -- the team has confirmed at least one creator, the number and the PDF stay
  -- off the client's page, and reverting the last confirmation takes them off
  -- it again. The gate is here rather than on the page so nothing the client
  -- can open carries what it should not show.
  select exists (
    select 1 from campaign_options o
     where o.campaign_id = c.id
       and o.state in ('confirmed', 'pending_visit', 'pending_draft', 'submitted',
                       'reviewing', 'changes', 'scheduled', 'posted', 'completed')
  ) into billable;

  if c.passcode is not null and c.passcode <> '' then
    if p_passcode is null or p_passcode <> c.passcode then
      return jsonb_build_object('error', 'passcode', 'client', cl.name);
    end if;
  end if;

  return jsonb_build_object(
    'campaign', jsonb_build_object(
      'title', c.title, 'title_zh', c.title_zh,
      'purpose', c.purpose, 'purpose_zh', c.purpose_zh, 'slots', c.slots,
      'backups_open', coalesce(c.backups_open, false),
      'selection_closed', c.selection_closed_at is not null,
      'deadline', c.deadline, 'state', c.state, 'deliverable', c.deliverable,
      'push_format', c.push_format, 'brief', c.brief, 'brief_zh', c.brief_zh,
      'invoice_no', case when billable then c.invoice_no end,
      'invoice_url', case when billable then c.invoice_url end,
      /* The client's last confirmation: who, when, and the creators it
         named, so a page opened again says the selection was confirmed and
         asks again only once the picks differ (2026-10-14). */
      'confirmed', (
        select jsonb_build_object('person', k.person, 'at', k.created_at,
                 'selected', coalesce((select jsonb_agg(x->>'id') from jsonb_array_elements(coalesce(k.snapshot, '[]'::jsonb)) x
                                        where x->>'as' = 'shortlisted'), '[]'::jsonb))
          from campaign_confirmations k
         where k.campaign_id = c.id and k.kind = 'client'
         order by k.created_at desc limit 1)),
    -- Currency and tax travel with the campaign, because the client's page
    -- prints both and must not assume Malaysia.
    'client', jsonb_build_object('name', cl.name, 'logo_url', cl.logo_url,
      'market', coalesce(cl.market, 'MY'), 'sst_applies', coalesce(cl.sst_applies, true)),
    /* A draft reaches the client when the team releases it, and not a moment
       before. `submitted` is the team's own step, so it is reported as
       `pending_draft`: the client is not asked to approve something they
       cannot open, and does not learn that a round exists. A `changes` the
       team raised is the same round going back to the creator, so it is
       withheld the same way; a `changes` the client raised is their own and
       is reported as it is. The mapping is here and not on the page, because
       what a client may not see is withheld by this function. */
    'options', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', o.id, 'name', cr.name,
        'rate', o.rate, 'platforms', o.platforms, 'state', s.shown,
        'is_replacement', o.is_replacement, 'added_at', o.added_at,
        -- Production. Present once a creator is locked; null before that, so
        -- the page can tell "not started" from "nothing to say".
        'visit_date', o.visit_date, 'visit_time', o.visit_time,
        'visit_location', o.visit_location, 'visit_pic', o.visit_pic,
        'visit_pic_phone', o.visit_pic_phone, 'tracking_no', o.tracking_no,
        'draft_url', case when s.released then o.draft_url end,
        /* The client's own rounds: a round the team sent back, or a request
           taken back, is not one the client made (2026-09-27). */
        'revision_round', (select count(*) from public.option_reviews r
                            where r.option_id = o.id and r.source = 'client'
                              and r.decision = 'changes' and r.undone_at is null)::int + 1,
        'planned_publish', o.planned_publish,
        /* What the creator uploaded, once it has been released: the round
           the team last released (`released_round`, stamped at release), so
           a creator's next round, uploaded after the client asked for
           changes, stays with the team until it is released in its turn
           (audit S5, 2026-10-10). A file hidden after the client's approval
           is never sent (audit S6). */
        'files', case when s.released then coalesce((
            select jsonb_agg(jsonb_build_object(
              'id', d.id, 'url', d.url, 'name', d.name, 'kind', d.kind,
              'bytes', d.bytes) order by d.uploaded_at)
            from campaign_deliverables d
            where d.option_id = o.id and d.removed_at is null and d.hidden_at is null
              and d.round = coalesce(o.released_round,
                            (select max(d2.round) from campaign_deliverables d2
                              where d2.option_id = o.id and d2.removed_at is null))
          ), '[]'::jsonb) else '[]'::jsonb end,
        -- The caption is part of what is being approved, so it travels with
        -- the files and is withheld with them.
        'caption', case when s.released then o.draft_caption end,
        'profiles', coalesce((
          select jsonb_agg(jsonb_build_object('platform', p.platform, 'url', p.url))
          from creator_profiles p where p.creator_id = cr.id), '[]'::jsonb),
        -- One row per platform posted on, so two placements stay two numbers.
        'posts', coalesce((
          select jsonb_agg(jsonb_build_object(
            'platform', pp.platform, 'post_url', pp.post_url,
            'published_at', pp.published_at, 'window_days', pp.window_days,
            'impressions', pp.impressions, 'engagements', pp.engagements,
            'views', pp.views, 'measured_at', pp.measured_at) order by pp.platform)
          from option_posts pp where pp.option_id = o.id), '[]'::jsonb),
        /* What was last decided, so the card can say who approved it and
           when rather than jumping to the next step with nothing to show for
           the decision. The client's own decisions, and an approval the team
           gave on the client's behalf (`by_team`, read "Proceeded by"); a
           team send-back stays withheld. Withheld with the draft it is about. */
        'review', case when s.released then (
            select jsonb_build_object('decision', r.decision, 'reviewer', r.reviewer,
                                      'note', case when r.source = 'client' then r.note end,
                                      'at', r.created_at, 'by_team', r.source = 'team')
            from option_reviews r where r.option_id = o.id
              and (r.source = 'client' or r.decision = 'approved') and r.undone_at is null
            order by r.created_at desc limit 1) end)
        order by o.position, o.added_at)
      from campaign_options o
      join creators cr on cr.id = o.creator_id
      cross join lateral (
        select sh.shown,
               sh.shown in ('reviewing', 'changes', 'scheduled', 'posted', 'completed')
                 as released
        from (select case
                       when o.state = 'submitted' then 'pending_draft'
                       when o.state = 'changes'
                            and coalesce(o.changes_by, 'client') = 'team' then 'pending_draft'
                       else o.state
                     end as shown) sh
      ) s
      where o.campaign_id = c.id and o.state <> 'replaced'), '[]'::jsonb)
  );
end $$;

revoke all on function public.get_campaign(text, text) from public;
grant execute on function public.get_campaign(text, text) to anon, authenticated;

create or replace function public.campaign_reset_link(p_campaign uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me    public.team_members;
  c     public.campaigns%rowtype;
  v_key text;
begin
  if not public.allowed('campaigns.campaigns', 'work') then
    return jsonb_build_object('error', 'denied');
  end if;
  select * into me from public.ops_me();
  if me.id is null then return jsonb_build_object('error', 'denied'); end if;
  select * into c from public.campaigns where id = p_campaign for update;
  if not found then return jsonb_build_object('error', 'not-found'); end if;
  if not public.client_scope_ok('campaign', c.id, 'work') then
    return jsonb_build_object('error', 'client-scope');
  end if;
  v_key := public.new_link_key();
  update public.campaigns set access_token = v_key where id = c.id;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'campaign.edited', c.title, 'Selection link reset · the previous link no longer opens');
  return jsonb_build_object('ok', true, 'key', v_key);
end $$;
revoke all on function public.campaign_reset_link(uuid) from public, anon;
grant execute on function public.campaign_reset_link(uuid) to authenticated;

-- END OF SELECTION LINK CLOSES ----------------------------------------------

-- ===========================================================================
-- PERSONAL DATA KEPT FOR A TIME — a WhatsApp message's number, name and
-- words are cleared after twelve months, and the Activity record keeps three
-- years. 2026-10-18. Safe to run twice. Rollback at the foot. Mirrored byte
-- for byte in supabase/schema.sql under the same banner; tests/sql.js
-- compares the two.
--
-- WHAT CHANGED (second audit, item 17; PDPA 2010 and 2012: keep personal
-- data no longer than its purpose needs)
--   Nothing ever left wa_outbox or activity_log. privacy_retention(p_now)
--   (pg_cron `privacy-retention`, 02:45 MYT on the 2nd of each month):
--   * clears a WhatsApp message's number (to_number, left empty, as the
--     column refuses none), name, variables and link code (to_name, params,
--     button) twelve months after it was queued, never one still queued or
--     sending; what was sent, when, to which record and how it went stay,
--     so the counts and the record of the send do not change (the WhatsApp
--     section lists the last twelve months alone);
--   * removes Activity record rows older than three years.
--   Not a page's to call. Performance's own trail (perf_events), HR letters
--   and the documents keep their own rules. The nightly database dump keeps
--   what it held on its day: its expiry is a lifecycle rule on
--   private/backups/db/ in S3, the user's to set (STANDARD.md).
--
-- ROLLBACK
--   select cron.unschedule(jobid) from cron.job where jobname = 'privacy-retention';
--   drop function if exists public.privacy_retention(timestamptz);
--   (what was cleared or removed is not brought back: it is in the dumps).
-- ===========================================================================

create or replace function public.privacy_retention(p_now timestamptz default now())
returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_wa integer := 0; v_act integer := 0;
begin
  update public.wa_outbox o
     set to_number = '', to_name = null, params = '[]'::jsonb, button = null
   where o.created_at < p_now - interval '12 months'
     and o.state not in ('queued', 'sending')
     and (o.to_number <> '' or o.to_name is not null or o.params <> '[]'::jsonb or o.button is not null);
  get diagnostics v_wa = row_count;
  delete from public.activity_log a where a.created_at < p_now - interval '3 years';
  get diagnostics v_act = row_count;
  return jsonb_build_object('whatsapp_cleared', v_wa, 'activity_removed', v_act);
end $$;
revoke all on function public.privacy_retention(timestamptz) from public, anon, authenticated;

do $$
begin
  if not exists (select 1 from pg_extension where extname = 'pg_cron') then
    raise notice 'pg_cron is not enabled: personal data is not cleared until it is.';
    return;
  end if;
  perform cron.unschedule(j.jobid) from cron.job j where j.jobname = 'privacy-retention';
  perform cron.schedule('privacy-retention', '45 18 1 * *', 'select public.privacy_retention()');
end $$;

-- END OF PERSONAL DATA KEPT FOR A TIME --------------------------------------

-- ===========================================================================
-- MY WORK REPORT READS ITS PERIOD — the Dashboard's figures read the stage
-- events of the period alone, and the bell has an index of its own.
-- 2026-10-18. Safe to run twice. Rollback at the foot. Mirrored byte for
-- byte in supabase/schema.sql under the same banner; tests/ops.js compares
-- the two.
--
-- WHAT CHANGED (second audit, item 18)
--   * ops_report's spans worked out a span for every stage event ever
--     written and only then kept those entered in the period, and the
--     Dashboard asks it eight times a visit (js/overview.js). A span entered
--     in the period ends at its task's next event, which is later still, so
--     the events before the period never changed an answer: spans now reads
--     from p_from on. Every figure is the same.
--   * ops_notifications_member_created_idx (team_member_id, created_at
--     desc): the bell in page_pulse reads a colleague's unread notices and
--     the read ones of the last seven days; the index held so far covered
--     unread alone.
--
-- ROLLBACK
--   Run the ops_report definition of the MALAYSIA TIME IN THE DATABASE
--   section of supabase/schema.sql again;
--   drop index if exists public.ops_notifications_member_created_idx;
-- ===========================================================================

create or replace function public.ops_report(
  p_from timestamptz default (now() - interval '90 days'),
  p_to   timestamptz default now())
returns jsonb
language plpgsql security definer stable set search_path = public as $$
declare
  out jsonb;
begin
  if not public.ops_granted('ops.reports', 'view') then
    return jsonb_build_object('error', 'denied');
  end if;

  with
  /* Where client review begins in each workflow. The final due date is the
     day the work is owed AT that stage, so everything below that position is
     "has not reached the client yet". Read from `stage_group` and never from
     a stage key: the two seeded workflows name that stage differently. */
  floors as (
    select workflow_id, min(position) as at
      from public.ops_workflow_stages
     where stage_group = 'client_review'
     group by workflow_id
  ),
  /* Where a priority's deadline is met (2026-10-11): client review, else the
     workflow's first review (an everyday task's Review). */
  pfloors as (
    select workflow_id,
           coalesce(min(position) filter (where stage_group = 'client_review'),
                    min(position) filter (where stage_group = 'internal_review')) as at
      from public.ops_workflow_stages
     group by workflow_id
  ),
  live as (
    select t.*, s.label as stage_label, s.position as stage_position,
           s.stage_group, f.at as review_at,
           public.ops_priority_by(coalesce(t.priority_at, t.created_at), t.priority_level) as prio_by, pf.at as prio_at
      from public.ops_tasks t
      join public.ops_workflow_stages s
        on s.workflow_id = t.workflow_id and s.key = t.stage_key
      left join floors f on f.workflow_id = t.workflow_id
      left join pfloors pf on pf.workflow_id = t.workflow_id
     where t.completed_at is null and t.cancelled_at is null
       and t.archived_at is null
  ),

  /* 1. WHAT IS RUNNING, by the words on the screen. Grouped by the stage's
        own label rather than by its group, because "what is on shooting" is
        the question and Shooting is a label, not a group. */
  running as (
    select jsonb_agg(x order by x ->> 'position', x ->> 'label') as j from (
      select jsonb_build_object(
               'stage_key', stage_key, 'label', stage_label,
               'position', stage_position, 'stage_group', stage_group,
               'count', count(*)) as x
        from live
       group by stage_key, stage_label, stage_position, stage_group
    ) q
  ),

  /* 2. WHAT IS LATE. Past the commitment and still short of client review,
        or past a priority's deadline and short of its review (On hold and
        Blocked still count): whichever comes first (the user, 2026-10-11).
        The same rule the queue row draws, stated once more here because a
        report a page computes for itself is a second definition. */
  late_now as (
    select l.*,
           (l.current_final_due_at is not null and (l.current_final_due_at at time zone 'Asia/Kuala_Lumpur')::date < (now() at time zone 'Asia/Kuala_Lumpur')::date
            and (l.review_at is null or l.stage_position < l.review_at)) as due_late,
           (l.prio_by is not null and l.prio_by < now()
            and (l.prio_at is null or l.stage_position < l.prio_at or l.stage_group in ('kiv', 'blocked'))) as prio_late
      from live l
  ),
  late as (
    select jsonb_agg(x order by x ->> 'due_at') as j from (
      select jsonb_build_object(
               'task_id', l.id, 'task_no', l.task_no, 'title', l.title,
               'client', c.name, 'stage', l.stage_label,
               'due_at', case when l.prio_late and (not l.due_late or l.prio_by < l.current_final_due_at)
                              then l.prio_by else l.current_final_due_at end,
               'days_over', greatest(case when l.due_late then (now() at time zone 'Asia/Kuala_Lumpur')::date - (l.current_final_due_at at time zone 'Asia/Kuala_Lumpur')::date end,
                                     case when l.prio_late then floor(extract(epoch from (now() - l.prio_by)) / 86400)::int end),
               'over_minutes', case when l.prio_late then floor(extract(epoch from (now() - l.prio_by)) / 60)::int end,
               'owner', (select tm.name
                           from public.ops_task_assignees a
                           join public.team_members tm on tm.id = a.team_member_id
                          where a.task_id = l.id and a.responsibility = 'owner'
                            and a.ended_at is null
                          limit 1)) as x
        from late_now l
        left join public.clients c on c.id = l.client_id
       where l.due_late or l.prio_late
    ) q
  ),

  /* 3. HOW LONG EACH STAGE TAKES. A task enters a stage at the event that
        names it and leaves at the next event, or at its own ending, or now.
        Only spans that were ENTERED inside the period are counted, so the
        window means what it says and a task that sat in Editing since March
        does not land in every report for ever. */
  spans as (
    select e.task_id,
           e.to_value ->> 'stage_key' as stage_key,
           e.created_at as from_at,
           coalesce(
             lead(e.created_at) over (partition by e.task_id order by e.created_at),
             t.completed_at, t.cancelled_at, now()) as to_at
      from public.ops_task_events e
      join public.ops_tasks t on t.id = e.task_id
     where e.event_type in ('task_created', 'stage_changed')
       and e.to_value ->> 'stage_key' is not null
       /* Only a span entered in the period is counted, and its end is the
          task's next event, never an earlier one: what came before the
          period is not read (2026-10-18). */
       and e.created_at >= p_from
  ),
  /* One row per span and no grouping: an earlier draft grouped by the span's
     own timestamps, which silently collapsed two tasks that entered the same
     stage in the same instant into one measurement. The label is looked up
     once per stage below instead of aggregated here. */
  span_mins as (
    select s.stage_key,
           extract(epoch from (s.to_at - s.from_at)) / 60 as mins
      from spans s
     where s.from_at >= p_from and s.from_at < p_to
       and s.to_at > s.from_at
  ),
  stage_time as (
    select jsonb_agg(x order by x ->> 'label') as j from (
      select jsonb_build_object(
               'stage_key', stage_key,
               'label', coalesce((select w.label from public.ops_workflow_stages w
                                   where w.key = sm.stage_key limit 1), stage_key),
               'n', count(*),
               'median_minutes', round(percentile_cont(0.5) within group (order by mins))::int,
               'p90_minutes', round(percentile_cont(0.9) within group (order by mins))::int) as x
        from span_mins sm
       group by stage_key
    ) q
  ),

  /* 4. WAS IT THERE ON TIME. Of the tasks that reached client review inside
        the period, how many got there on or before the date they were owed.
        Replanning is counted beside it and never folded into it: an extension
        that moves the date would otherwise erase the miss it was granted for,
        and a rate that cannot be missed is not a measurement. */
  reached as (
    select distinct on (e.task_id)
           e.task_id, e.created_at as at, t.current_final_due_at as due,
           public.ops_priority_by(coalesce(t.priority_at, t.created_at), t.priority_level) as prio_by,
           (t.original_final_due_at is distinct from t.current_final_due_at) as replanned
      from public.ops_task_events e
      join public.ops_tasks t on t.id = e.task_id
      join public.ops_workflow_stages w
        on w.workflow_id = t.workflow_id and w.key = e.to_value ->> 'stage_key'
     where e.event_type = 'stage_changed'
       and w.stage_group = 'client_review'
       and e.created_at >= p_from and e.created_at < p_to
     order by e.task_id, e.created_at
  ),
  on_time as (
    select jsonb_build_object(
             'reached', count(*),
             'met', count(*) filter (where (due is null or at::date <= due::date) and (prio_by is null or at <= prio_by)),
             'missed', count(*) filter (where not ((due is null or at::date <= due::date) and (prio_by is null or at <= prio_by))),
             'replanned', count(*) filter (where replanned)) as j
      from reached
  ),

  /* 5. BY PERSON. The foundation of a KPI and not a KPI: what somebody
        finished in the window, how much of it was on time, and how long their
        work took end to end. No ranking and no score — a number a person can
        check is worth more than a league table nobody trusts. */
  done as (
    select t.id, t.created_at, coalesce(t.completed_at, t.delivered_at) as ended,
           t.current_final_due_at as due,
           public.ops_priority_by(coalesce(t.priority_at, t.created_at), t.priority_level) as prio_by,
           /* When a priority's deadline was met: the first move into its
              review or beyond (never On hold, Blocked or Cancelled). */
           (select min(e.created_at)
              from public.ops_task_events e
              join public.ops_workflow_stages w
                on w.workflow_id = t.workflow_id and w.key = e.to_value ->> 'stage_key'
              join pfloors pf on pf.workflow_id = t.workflow_id
             where e.task_id = t.id and e.event_type = 'stage_changed'
               and w.position >= pf.at and w.stage_group not in ('kiv', 'blocked', 'cancelled')) as met_at,
           (select a.team_member_id
              from public.ops_task_assignees a
             where a.task_id = t.id and a.responsibility = 'owner'
             order by a.ended_at nulls first, a.assigned_at desc
             limit 1) as owner_id
      from public.ops_tasks t
     where t.completed_at is not null
       and t.completed_at >= p_from and t.completed_at < p_to
  ),
  by_person as (
    select jsonb_agg(x order by x ->> 'name') as j from (
      select jsonb_build_object(
               'team_member_id', d.owner_id,
               'name', coalesce(tm.name, 'Nobody'),
               'completed', count(*),
               'on_time', count(*) filter (where (d.due is null or d.ended::date <= d.due::date)
                                         and (d.prio_by is null or coalesce(d.met_at, d.ended) <= d.prio_by)),
               'median_cycle_minutes',
                 round(percentile_cont(0.5) within group (
                   order by extract(epoch from (d.ended - d.created_at)) / 60))::int) as x
        from done d
        left join public.team_members tm on tm.id = d.owner_id
       group by d.owner_id, tm.name
    ) q
  ),

  /* 6. WHO IS CARRYING THE OPEN WORK (2026-09-28). One row a Task Owner:
        the open tasks they hold, and how many of those are late by the rule
        in 2 above. The team's whole queue is `ops.all`, so it is answered
        only where that part is granted. */
  open_by_person as (
    select jsonb_agg(x order by (x ->> 'open')::int desc, x ->> 'name') as j from (
      select jsonb_build_object(
               'team_member_id', o.owner_id,
               'name', coalesce(tm.name, 'No task owner'),
               'open', count(*),
               'late', count(*) filter (where o.is_late)) as x
        from (select l.id,
                     (select a.team_member_id
                        from public.ops_task_assignees a
                       where a.task_id = l.id and a.responsibility = 'owner' and a.ended_at is null
                       limit 1) as owner_id,
                     (l.due_late or l.prio_late) as is_late
                from late_now l) o
        left join public.team_members tm on tm.id = o.owner_id
       where public.ops_granted('ops.all', 'view')
       group by o.owner_id, tm.name
    ) q
  )

  select jsonb_build_object(
           'from', p_from, 'to', p_to,
           'running',    coalesce((select j from running), '[]'::jsonb),
           'late',       coalesce((select j from late), '[]'::jsonb),
           'stage_time', coalesce((select j from stage_time), '[]'::jsonb),
           'on_time',    coalesce((select j from on_time), '{}'::jsonb),
           'by_person',  coalesce((select j from by_person), '[]'::jsonb),
           'open_by_person', case when public.ops_granted('ops.all', 'view')
                                  then coalesce((select j from open_by_person), '[]'::jsonb) end)
    into out;

  return out;
end $$;

grant execute on function public.ops_report(timestamptz, timestamptz) to authenticated;

create index if not exists ops_notifications_member_created_idx
  on public.ops_notifications (team_member_id, created_at desc);

-- END OF MY WORK REPORT READS ITS PERIOD ------------------------------------

-- ===========================================================================
-- PASSCODE ATTEMPTS — a review or selection link's passcode is not guessed:
-- five wrong tries lock the link for 15 minutes, and a passcode asked for
-- names nobody. 2026-10-18. Safe to run twice. Rollback at the foot.
-- Mirrored byte for byte in supabase/schema.sql under the same banner;
-- tests/confirmonce.js compares the two.
--
-- WHAT CHANGED (second audit, item 6)
--   1. `link_attempts` (kind `review` or `selection`, the link's key, wrong
--      tries, the last try, locked until; RLS on, no policy, no grant) and
--      `link_passcode(p_kind, p_token, p_stored, p_given)`, closed to every
--      role: `ok` with no passcode set or the right one given (the count
--      cleared); `wrong` when none is given (the page asking whether one is
--      needed, never counted) or a wrong one is (counted; a try more than
--      15 minutes after the last starts again); `locked` from the fifth
--      wrong try for 15 minutes, the right passcode included.
--   2. Every function a link's passcode opens asks it: get_review_feed
--      (`passcode_required`, `not_found` while locked) and get_campaign,
--      save_selection, confirm_selection, confirm_selection_with and
--      review_draft (`passcode`, `not-found` while locked), each restated
--      whole from its last definition with only that check changed. A
--      missing or wrong passcode no longer answers the client's name.
--      submit_review and submit_review_seen need a post id only the feed
--      gives, so they keep their own check; media-pass and sign-download
--      ask get_review_feed or get_campaign first.
--
-- ROLLBACK
--   Run each function's definition before this band again (get_review_feed
--   from APPROVAL AS SEEN, get_campaign from SELECTION LINK CLOSES,
--   confirm_selection_with from SLOTS HOLD THEIR BOOKINGS, confirm_selection
--   from CONFIRM ONCE, save_selection and review_draft from their last
--   bands), then:
--   drop function if exists public.link_passcode(text, text, text, text);
--   drop table if exists public.link_attempts;
-- ===========================================================================

create table if not exists public.link_attempts (
  kind         text not null,
  token        text not null,
  fails        integer not null default 0,
  last_at      timestamptz not null default now(),
  locked_until timestamptz,
  primary key (kind, token)
);
alter table public.link_attempts enable row level security;
revoke all on public.link_attempts from public, anon, authenticated;

create or replace function public.link_passcode(p_kind text, p_token text, p_stored text, p_given text)
returns text
language plpgsql security definer set search_path = public as $$
declare
  a public.link_attempts%rowtype;
begin
  if coalesce(p_stored, '') = '' then return 'ok'; end if;
  select * into a from public.link_attempts
   where kind = p_kind and token = p_token for update;
  if a.locked_until is not null and a.locked_until > now() then return 'locked'; end if;
  -- Asked without one: the page learning that a passcode is needed.
  if coalesce(p_given, '') = '' then return 'wrong'; end if;
  if p_given = p_stored then
    if a.kind is not null and (a.fails > 0 or a.locked_until is not null) then
      update public.link_attempts set fails = 0, locked_until = null, last_at = now()
       where kind = p_kind and token = p_token;
    end if;
    return 'ok';
  end if;
  insert into public.link_attempts as t (kind, token, fails, last_at)
  values (p_kind, p_token, 1, now())
  on conflict (kind, token) do update
     set fails = case when t.locked_until is not null or t.last_at < now() - interval '15 minutes'
                      then 1 else t.fails + 1 end,
         last_at = now(),
         locked_until = null
  returning * into a;
  if a.fails >= 5 then
    update public.link_attempts set locked_until = now() + interval '15 minutes'
     where kind = p_kind and token = p_token;
    return 'locked';
  end if;
  return 'wrong';
end $$;
revoke all on function public.link_passcode(text, text, text, text) from public, anon, authenticated;

create or replace function public.get_review_feed(p_token text, p_passcode text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_client public.clients%rowtype;
begin
  select * into v_client
  from public.clients
  where access_token = p_token and active and not review_hidden;

  if not found then
    return jsonb_build_object('error', 'not_found');
  end if;

  -- Five wrong passcodes lock the link for 15 minutes, answered as a key
  -- nobody knows; a passcode asked for names nobody (second audit, item 6).
  case public.link_passcode('review', v_client.access_token, v_client.passcode, p_passcode)
    when 'locked' then return jsonb_build_object('error', 'not_found');
    when 'wrong' then return jsonb_build_object('error', 'passcode_required');
    else null;
  end case;

  return jsonb_build_object(
    'client', jsonb_build_object(
      'name', v_client.name,
      'logo_url', v_client.logo_url,
      'handles', jsonb_build_object(
        'instagram', v_client.handle_ig,
        'facebook',  v_client.handle_fb,
        'tiktok',    v_client.handle_tiktok,
        'xhs',       v_client.handle_xhs)),
    'batches', coalesce((
      select jsonb_agg(batch order by batch->>'created_at' desc)
      from (
        select jsonb_build_object(
          'id',         b.id,
          'title',      b.title,
          'note',       b.note,
          'created_at', b.created_at,
          'posts', coalesce((
            select jsonb_agg(post order by (post->>'position')::int)
            from (
              select jsonb_build_object(
                'id',         p.id,
                'platform',   p.platform,
                'format',     p.format,
                'handle',     p.handle,
                'caption',    p.caption,
                'caption_zh', p.caption_zh,
                'title',      p.title,
                'media',      p.media,
                'cover_for',  p.cover_for,
                'position',   p.position,
                'round',      p.round,
                'version',    p.content_version,
                'reset_note', case
                  when p.review_reset_at is not null then p.review_reset_note end,
                /* The decision standing on the round on show: never one about
                   a round the client no longer sees, never one taken back. */
                'review',     (
                  select jsonb_build_object(
                    'decision',   r.decision,
                    'note',       r.note,
                    'reviewer',   case when r.source = 'team' then null else r.reviewer end,
                    'created_at', r.created_at,
                    'by_team',    (r.source = 'team'),
                    'suggested',  (r.suggested_caption is not null or r.suggested_caption_zh is not null),
                    /* The client's own edit, so Edit request reopens it. */
                    'suggested_caption',    r.suggested_caption,
                    'suggested_caption_zh', r.suggested_caption_zh)
                  from public.reviews r
                  where r.post_id = p.id and r.round = p.round and r.undone_at is null
                    and (p.review_reset_at is null or r.created_at > p.review_reset_at)
                  order by r.created_at desc
                  limit 1),
                /* What the client asked of the round before, so a revision
                   says what it answers. Words only: the earlier file and copy
                   stay with the team. */
                'asked',      case when p.round > 1 then (
                  select jsonb_build_object(
                    'note',       r.note,
                    'reviewer',   r.reviewer,
                    'created_at', r.created_at,
                    'suggested',  (r.suggested_caption is not null or r.suggested_caption_zh is not null))
                  from public.reviews r
                  where r.post_id = p.id and r.round = p.round - 1 and r.decision = 'changes'
                    and r.undone_at is null
                  order by r.created_at desc
                  limit 1) end
              ) as post
              from public.posts p
              where p.batch_id = b.id
            ) posts
          ), '[]'::jsonb)
        ) as batch
        from public.batches b
        where b.client_id = v_client.id and b.published
      ) batches
    ), '[]'::jsonb)
  );
end $$;

revoke all on function public.get_review_feed(text, text) from public;
grant execute on function public.get_review_feed(text, text) to anon, authenticated;

create or replace function public.get_campaign(p_token text, p_passcode text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  c campaigns%rowtype;
  cl clients%rowtype;
  billable boolean;
begin
  select * into c from campaigns where access_token = p_token;
  if not found then return jsonb_build_object('error', 'not-found'); end if;
  select * into cl from clients where id = c.client_id;
  -- A past client's links close (second audit, item 5): answered as a key
  -- nobody knows, so the page says the link is not recognised.
  if cl.stage = 'past' then return jsonb_build_object('error', 'not-found'); end if;

  -- An invoice belongs to an accepted booking. Until the client has chosen and
  -- the team has confirmed at least one creator, the number and the PDF stay
  -- off the client's page, and reverting the last confirmation takes them off
  -- it again. The gate is here rather than on the page so nothing the client
  -- can open carries what it should not show.
  select exists (
    select 1 from campaign_options o
     where o.campaign_id = c.id
       and o.state in ('confirmed', 'pending_visit', 'pending_draft', 'submitted',
                       'reviewing', 'changes', 'scheduled', 'posted', 'completed')
  ) into billable;

  -- Five wrong passcodes lock the link for 15 minutes, answered as a key
  -- nobody knows; a passcode asked for names nobody (second audit, item 6).
  case public.link_passcode('selection', c.access_token, c.passcode, p_passcode)
    when 'locked' then return jsonb_build_object('error', 'not-found');
    when 'wrong' then return jsonb_build_object('error', 'passcode');
    else null;
  end case;

  return jsonb_build_object(
    'campaign', jsonb_build_object(
      'title', c.title, 'title_zh', c.title_zh,
      'purpose', c.purpose, 'purpose_zh', c.purpose_zh, 'slots', c.slots,
      'backups_open', coalesce(c.backups_open, false),
      'selection_closed', c.selection_closed_at is not null,
      'deadline', c.deadline, 'state', c.state, 'deliverable', c.deliverable,
      'push_format', c.push_format, 'brief', c.brief, 'brief_zh', c.brief_zh,
      'invoice_no', case when billable then c.invoice_no end,
      'invoice_url', case when billable then c.invoice_url end,
      /* The client's last confirmation: who, when, and the creators it
         named, so a page opened again says the selection was confirmed and
         asks again only once the picks differ (2026-10-14). */
      'confirmed', (
        select jsonb_build_object('person', k.person, 'at', k.created_at,
                 'selected', coalesce((select jsonb_agg(x->>'id') from jsonb_array_elements(coalesce(k.snapshot, '[]'::jsonb)) x
                                        where x->>'as' = 'shortlisted'), '[]'::jsonb))
          from campaign_confirmations k
         where k.campaign_id = c.id and k.kind = 'client'
         order by k.created_at desc limit 1)),
    -- Currency and tax travel with the campaign, because the client's page
    -- prints both and must not assume Malaysia.
    'client', jsonb_build_object('name', cl.name, 'logo_url', cl.logo_url,
      'market', coalesce(cl.market, 'MY'), 'sst_applies', coalesce(cl.sst_applies, true)),
    /* A draft reaches the client when the team releases it, and not a moment
       before. `submitted` is the team's own step, so it is reported as
       `pending_draft`: the client is not asked to approve something they
       cannot open, and does not learn that a round exists. A `changes` the
       team raised is the same round going back to the creator, so it is
       withheld the same way; a `changes` the client raised is their own and
       is reported as it is. The mapping is here and not on the page, because
       what a client may not see is withheld by this function. */
    'options', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', o.id, 'name', cr.name,
        'rate', o.rate, 'platforms', o.platforms, 'state', s.shown,
        'is_replacement', o.is_replacement, 'added_at', o.added_at,
        -- Production. Present once a creator is locked; null before that, so
        -- the page can tell "not started" from "nothing to say".
        'visit_date', o.visit_date, 'visit_time', o.visit_time,
        'visit_location', o.visit_location, 'visit_pic', o.visit_pic,
        'visit_pic_phone', o.visit_pic_phone, 'tracking_no', o.tracking_no,
        'draft_url', case when s.released then o.draft_url end,
        /* The client's own rounds: a round the team sent back, or a request
           taken back, is not one the client made (2026-09-27). */
        'revision_round', (select count(*) from public.option_reviews r
                            where r.option_id = o.id and r.source = 'client'
                              and r.decision = 'changes' and r.undone_at is null)::int + 1,
        'planned_publish', o.planned_publish,
        /* What the creator uploaded, once it has been released: the round
           the team last released (`released_round`, stamped at release), so
           a creator's next round, uploaded after the client asked for
           changes, stays with the team until it is released in its turn
           (audit S5, 2026-10-10). A file hidden after the client's approval
           is never sent (audit S6). */
        'files', case when s.released then coalesce((
            select jsonb_agg(jsonb_build_object(
              'id', d.id, 'url', d.url, 'name', d.name, 'kind', d.kind,
              'bytes', d.bytes) order by d.uploaded_at)
            from campaign_deliverables d
            where d.option_id = o.id and d.removed_at is null and d.hidden_at is null
              and d.round = coalesce(o.released_round,
                            (select max(d2.round) from campaign_deliverables d2
                              where d2.option_id = o.id and d2.removed_at is null))
          ), '[]'::jsonb) else '[]'::jsonb end,
        -- The caption is part of what is being approved, so it travels with
        -- the files and is withheld with them.
        'caption', case when s.released then o.draft_caption end,
        'profiles', coalesce((
          select jsonb_agg(jsonb_build_object('platform', p.platform, 'url', p.url))
          from creator_profiles p where p.creator_id = cr.id), '[]'::jsonb),
        -- One row per platform posted on, so two placements stay two numbers.
        'posts', coalesce((
          select jsonb_agg(jsonb_build_object(
            'platform', pp.platform, 'post_url', pp.post_url,
            'published_at', pp.published_at, 'window_days', pp.window_days,
            'impressions', pp.impressions, 'engagements', pp.engagements,
            'views', pp.views, 'measured_at', pp.measured_at) order by pp.platform)
          from option_posts pp where pp.option_id = o.id), '[]'::jsonb),
        /* What was last decided, so the card can say who approved it and
           when rather than jumping to the next step with nothing to show for
           the decision. The client's own decisions, and an approval the team
           gave on the client's behalf (`by_team`, read "Proceeded by"); a
           team send-back stays withheld. Withheld with the draft it is about. */
        'review', case when s.released then (
            select jsonb_build_object('decision', r.decision, 'reviewer', r.reviewer,
                                      'note', case when r.source = 'client' then r.note end,
                                      'at', r.created_at, 'by_team', r.source = 'team')
            from option_reviews r where r.option_id = o.id
              and (r.source = 'client' or r.decision = 'approved') and r.undone_at is null
            order by r.created_at desc limit 1) end)
        order by o.position, o.added_at)
      from campaign_options o
      join creators cr on cr.id = o.creator_id
      cross join lateral (
        select sh.shown,
               sh.shown in ('reviewing', 'changes', 'scheduled', 'posted', 'completed')
                 as released
        from (select case
                       when o.state = 'submitted' then 'pending_draft'
                       when o.state = 'changes'
                            and coalesce(o.changes_by, 'client') = 'team' then 'pending_draft'
                       else o.state
                     end as shown) sh
      ) s
      where o.campaign_id = c.id and o.state <> 'replaced'), '[]'::jsonb)
  );
end $$;

revoke all on function public.get_campaign(text, text) from public;
grant execute on function public.get_campaign(text, text) to anon, authenticated;

create or replace function public.save_selection(
  p_token text, p_selected uuid[], p_backup uuid[], p_passcode text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  c campaigns%rowtype;
  n integer;
begin
  select * into c from campaigns where access_token = p_token;
  if not found then return jsonb_build_object('error', 'not-found'); end if;
  -- Five wrong passcodes lock the link for 15 minutes, answered as a key
  -- nobody knows (second audit, item 6).
  case public.link_passcode('selection', c.access_token, c.passcode, p_passcode)
    when 'locked' then return jsonb_build_object('error', 'not-found');
    when 'wrong' then return jsonb_build_object('error', 'passcode');
    else null;
  end case;

  n := coalesce(array_length(p_selected, 1), 0);
  /* Closed once the slots were full, until the team reopens it; backups
     alone may still be named where the team opened them. */
  if c.selection_closed_at is not null and not (coalesce(c.backups_open, false) and n = 0) then
    return jsonb_build_object('error', 'closed');
  end if;
  if n > c.slots then
    return jsonb_build_object('error', 'over-slots', 'slots', c.slots);
  end if;

  -- Anything already confirmed or further along is the team's to change.
  update campaign_options set state = 'option'
   where campaign_id = c.id and state in ('shortlisted', 'backup');

  if n > 0 then
    update campaign_options set state = 'shortlisted'
     where campaign_id = c.id and id = any(p_selected) and state = 'option';
  end if;
  -- Only where the team opened them: the page hides the control, and this is
  -- what makes that a fact rather than a courtesy.
  if coalesce(c.backups_open, false) and coalesce(array_length(p_backup, 1), 0) > 0 then
    update campaign_options set state = 'backup'
     where campaign_id = c.id and id = any(p_backup) and state = 'option';
  end if;

  return jsonb_build_object('ok', true, 'selected', n);
end $$;

revoke all on function public.save_selection(text, uuid[], uuid[], text) from public;
grant execute on function public.save_selection(text, uuid[], uuid[], text) to anon, authenticated;

create or replace function public.confirm_selection(
  p_token text, p_person text, p_passcode text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  c campaigns%rowtype;
begin
  select * into c from campaigns where access_token = p_token;
  if not found then return jsonb_build_object('error', 'not-found'); end if;
  -- Five wrong passcodes lock the link for 15 minutes, answered as a key
  -- nobody knows (second audit, item 6).
  case public.link_passcode('selection', c.access_token, c.passcode, p_passcode)
    when 'locked' then return jsonb_build_object('error', 'not-found');
    when 'wrong' then return jsonb_build_object('error', 'passcode');
    else null;
  end case;
  if coalesce(trim(p_person), '') = '' then
    return jsonb_build_object('error', 'name-required');
  end if;
  if c.selection_closed_at is not null and not coalesce(c.backups_open, false) then
    return jsonb_build_object('error', 'closed');
  end if;
  -- Nothing saved is nothing to confirm (a save refused under the page).
  if not exists (select 1 from campaign_options o
                  where o.campaign_id = c.id
                    and o.state = case when c.selection_closed_at is not null
                                       then 'backup' else 'shortlisted' end) then
    return jsonb_build_object('error', 'empty');
  end if;

  insert into campaign_confirmations (campaign_id, kind, person, source)
  values (c.id, 'client', trim(p_person), 'portal');

  insert into public.activity_log (actor, action, subject, detail)
  values (trim(p_person), 'campaign.confirmed', c.title,
          (select count(*)::text || ' creator' || case when count(*) = 1 then '' else 's' end
             from campaign_options
            where campaign_id = c.id and state = 'shortlisted') || ' confirmed');

  return jsonb_build_object('ok', true);
end $$;

revoke all on function public.confirm_selection(text, text, text) from public;
grant execute on function public.confirm_selection(text, text, text) to anon, authenticated;

create or replace function public.confirm_selection_with(
  p_token text, p_person text, p_passcode text, p_selected uuid[], p_backup uuid[],
  p_seen jsonb, p_idem text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  c      campaigns%rowtype;
  v_sel  uuid[];
  v_bak  uuid[];
  v_all  uuid[];
  v_idem text := left(nullif(btrim(coalesce(p_idem, '')), ''), 64);
  v_now  jsonb;
  v_snap jsonb;
  n      integer;
  v_booked integer;
begin
  select * into c from campaigns where access_token = p_token for update;
  if not found then return jsonb_build_object('error', 'not-found'); end if;
  -- Five wrong passcodes lock the link for 15 minutes, answered as a key
  -- nobody knows (second audit, item 6).
  case public.link_passcode('selection', c.access_token, c.passcode, p_passcode)
    when 'locked' then return jsonb_build_object('error', 'not-found');
    when 'wrong' then return jsonb_build_object('error', 'passcode');
    else null;
  end case;
  if coalesce(trim(p_person), '') = '' then
    return jsonb_build_object('error', 'name-required');
  end if;
  -- The same press again: the first answer stands and nothing is filed twice.
  if v_idem is not null and exists (select 1 from campaign_confirmations k
                                     where k.campaign_id = c.id and k.idem = v_idem) then
    return jsonb_build_object('ok', true, 'again', true);
  end if;

  v_sel := array(select distinct x from unnest(coalesce(p_selected, '{}'::uuid[])) x where x is not null);
  v_bak := case when coalesce(c.backups_open, false)
                then array(select distinct x from unnest(coalesce(p_backup, '{}'::uuid[])) x
                            where x is not null and not (x = any (v_sel)))
                else '{}'::uuid[] end;
  v_all := v_sel || v_bak;
  n := cardinality(v_sel);

  if c.selection_closed_at is not null and not (coalesce(c.backups_open, false) and n = 0) then
    return jsonb_build_object('error', 'closed');
  end if;
  if cardinality(v_all) = 0 then return jsonb_build_object('error', 'empty'); end if;
  -- The slots left are the slots less the creators already booked: a
  -- selection reopened for four of ten never books sixteen.
  v_booked := public.campaign_booked(c.id);
  if n > 0 and n > c.slots - v_booked then
    return jsonb_build_object('error', 'over-slots', 'slots', c.slots, 'booked', v_booked);
  end if;
  -- Every creator named is still on the campaign and open to choose.
  if (select count(*) from campaign_options o
       where o.id = any (v_all) and o.campaign_id = c.id
         and o.state in ('option', 'shortlisted', 'backup')) <> cardinality(v_all) then
    return jsonb_build_object('error', 'stale');
  end if;
  -- The prices the client read are the prices now.
  select jsonb_object_agg(o.id::text, o.rate) into v_now
    from campaign_options o where o.id = any (v_all);
  if exists (select 1 from campaign_options o
              where o.id = any (v_all)
                and coalesce(p_seen -> (o.id::text), 'null'::jsonb)
                    is distinct from coalesce(to_jsonb(o.rate), 'null'::jsonb)) then
    return jsonb_build_object('error', 'prices', 'rates', v_now);
  end if;

  update campaign_options set state = 'option'
   where campaign_id = c.id and state in ('shortlisted', 'backup');
  if n > 0 then
    update campaign_options set state = 'shortlisted'
     where campaign_id = c.id and id = any (v_sel) and state = 'option';
  end if;
  if cardinality(v_bak) > 0 then
    update campaign_options set state = 'backup'
     where campaign_id = c.id and id = any (v_bak) and state = 'option';
  end if;

  select jsonb_agg(jsonb_build_object('id', o.id, 'creator', cr.name, 'rate', o.rate, 'as', o.state)
                   order by o.position, o.added_at)
    into v_snap
    from campaign_options o join creators cr on cr.id = o.creator_id
   where o.id = any (v_all);
  insert into campaign_confirmations (campaign_id, kind, person, source, idem, snapshot)
  values (c.id, 'client', trim(p_person), 'portal', v_idem, coalesce(v_snap, '[]'::jsonb));

  insert into public.activity_log (actor, action, subject, detail)
  values (trim(p_person), 'campaign.confirmed', c.title,
          case when n > 0 then n::text || ' creator' || case when n = 1 then '' else 's' end || ' confirmed'
               else cardinality(v_bak)::text || ' backup' || case when cardinality(v_bak) = 1 then '' else 's' end || ' confirmed' end);

  return jsonb_build_object('ok', true, 'selected', n);
end $$;

revoke all on function public.confirm_selection_with(text, text, text, uuid[], uuid[], jsonb, text) from public;
grant execute on function public.confirm_selection_with(text, text, text, uuid[], uuid[], jsonb, text) to anon, authenticated;

create or replace function public.review_draft(
  p_token text, p_option uuid, p_decision text, p_note text default null,
  p_reviewer text default null, p_passcode text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  c campaigns%rowtype;
  o campaign_options%rowtype;
  n integer;
begin
  select * into c from campaigns where access_token = p_token;
  if not found then return jsonb_build_object('error', 'not-found'); end if;
  -- Five wrong passcodes lock the link for 15 minutes, answered as a key
  -- nobody knows (second audit, item 6).
  case public.link_passcode('selection', c.access_token, c.passcode, p_passcode)
    when 'locked' then return jsonb_build_object('error', 'not-found');
    when 'wrong' then return jsonb_build_object('error', 'passcode');
    else null;
  end case;
  if p_decision not in ('approved', 'changes') then
    return jsonb_build_object('error', 'bad-decision');
  end if;

  select * into o from campaign_options
   where id = p_option and campaign_id = c.id;
  if not found then return jsonb_build_object('error', 'not-found'); end if;

  -- Only a draft that is actually with the client can be ruled on.
  if o.state not in ('reviewing', 'changes') then
    return jsonb_build_object('error', 'not-reviewing');
  end if;
  /* A draft the team sent back to the creator is not with the client: the
     selection page shows it as Pending draft, so only a hand-made call
     could rule on it (audit B, 2026-10-17). */
  if o.state = 'changes' and coalesce(o.changes_by, 'client') = 'team' then
    return jsonb_build_object('error', 'not-reviewing');
  end if;

  n := coalesce(o.revision_round, 0);

  insert into option_reviews (option_id, round, decision, note, reviewer)
  values (p_option, greatest(n, 1), p_decision, nullif(trim(coalesce(p_note, '')), ''), p_reviewer);

  if p_decision = 'approved' then
    update campaign_options set state = 'scheduled' where id = p_option;
  else
    update campaign_options
       set state = 'changes', revision_round = greatest(n, 1) + 1,
           changes_by = 'client'
     where id = p_option;
  end if;

  /* The client's decision is the one event on a campaign that nobody on the
     team witnesses, and it was the only one the activity record never held:
     a draft went to Reviewing and appeared as Scheduled with nothing in
     between saying who had said yes. The reviewer's own name is the actor,
     because a person decided it. */
  insert into activity_log (actor, action, subject, detail)
  select coalesce(nullif(trim(coalesce(p_reviewer, '')), ''), 'Client'),
         'campaign.review', c.title,
         cr.name || ' · ' ||
         case when p_decision = 'approved' then 'Approved' else 'Changes requested' end ||
         coalesce(': ' || nullif(trim(coalesce(p_note, '')), ''), '')
    from creators cr where cr.id = o.creator_id;

  return jsonb_build_object('ok', true, 'decision', p_decision);
end $$;

revoke all on function public.review_draft(text, uuid, text, text, text, text) from public;
grant execute on function public.review_draft(text, uuid, text, text, text, text) to anon, authenticated;

-- END OF PASSCODE ATTEMPTS --------------------------------------------------

-- ===========================================================================
-- SERVICE LINES NEVER BELOW ZERO — a client's service line holds no
-- negative rate or quantity. 2026-10-18. Safe to run twice. Rollback at the
-- foot. Mirrored byte for byte in supabase/schema.sql under the same banner;
-- tests/sql.js compares the two.
--
-- WHAT CHANGED
--   client_services.rate and qty took any number, and the Services sheet
--   sent what was typed. Since QUOTE TOTALS IN ONE PLACE (#563) a letter's
--   one-off part that adds up to zero or less is left out by quote_totals
--   while the page keeps it, so a letter holding a negative line was
--   refused `stale` on every press of Issue. Both columns now refuse a
--   figure below zero (client_services_rate_check, client_services_qty_check;
--   none of the 17 live lines held one, 2026-10-18), and the sheet refuses
--   it in words before it is sent. A quotation's own edits already refuse
--   one (`bad-edit`).
--
-- ROLLBACK
--   alter table public.client_services drop constraint if exists client_services_rate_check;
--   alter table public.client_services drop constraint if exists client_services_qty_check;
-- ===========================================================================

do $$
begin
  if exists (select 1 from public.client_services where rate < 0 or qty < 0) then
    raise exception 'client_services holds a negative rate or quantity: correct those lines first'
      using hint = 'select id, client_id, label, qty, rate from public.client_services where rate < 0 or qty < 0;';
  end if;
  if not exists (select 1 from pg_constraint where conname = 'client_services_rate_check'
                    and conrelid = 'public.client_services'::regclass) then
    alter table public.client_services add constraint client_services_rate_check check (rate >= 0);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'client_services_qty_check'
                    and conrelid = 'public.client_services'::regclass) then
    alter table public.client_services add constraint client_services_qty_check check (qty >= 0);
  end if;
end $$;

-- END OF SERVICE LINES NEVER BELOW ZERO -------------------------------------

-- ===========================================================================
-- WHATSAPP OUTAGE SPENDS NO TRY — a queued message that could not leave, or
-- that Meta held back for its throughput limit, keeps its three tries.
-- 2026-10-18. Safe to run twice. Rollback at the foot. Mirrored byte for
-- byte in supabase/schema.sql under the same banner; tests/sql.js compares
-- the two.
--
-- WHAT CHANGED
--   wa-send's drain stops at a request that never left (`not sent:`), so a
--   wake spends one try, but wa_done still counted it: an outage longer
--   than three wakes (about ten minutes) failed the oldest waiting message,
--   then the next. Meta's throughput limit (130429, read as wa-busy) counted
--   a try too, though it sent nothing.
--   * wa_done files a `not sent:` answer back to the queue and gives its
--     try back (tries less one, never below zero), so only Meta's own
--     refusal of the message spends one; an outage of any length fails
--     nothing, and the message goes once the way is clear.
--   * wa-send's drain files Meta's 130429 as `not sent:` and stops, as it
--     does a request that never left (supabase/functions/wa-send).
--
-- ROLLBACK
--   Run the wa_done definition of the WHATSAPP SENDS NEVER REPEATED section
--   of supabase/schema.sql again.
-- ===========================================================================

create or replace function public.wa_done(p_id uuid, p_ok boolean, p_wa_id text, p_error text)
returns void
language sql security definer set search_path = public as $$
  update public.wa_outbox o
     set state = case when p_ok then 'sent'
                      when coalesce(p_error, '') like 'unknown:%' then 'unknown'
                      when coalesce(p_error, '') like 'not sent:%' then 'queued'
                      when o.tries >= 3 then 'failed' else 'queued' end,
         tries = case when not p_ok and coalesce(p_error, '') like 'not sent:%' then greatest(0, o.tries - 1) else o.tries end,
         wa_id = left(p_wa_id, 200), error = left(p_error, 500), sent_at = case when p_ok then now() end
   where o.id = p_id
$$;
revoke all on function public.wa_done(uuid, boolean, text, text) from public, anon, authenticated;

-- END OF WHATSAPP OUTAGE SPENDS NO TRY --------------------------------------

-- ===========================================================================
-- A LEFT COLLEAGUE'S DRAFT NEVER HOLDS THE HALF — a bonus and trip period
-- no longer waits on a draft review of a colleague who has left, and names
-- the reviews it does wait on. 2026-10-18. Safe to run twice. Rollback at
-- the foot. Mirrored byte for byte in supabase/schema.sql under the same
-- banner; tests/perf.js compares the two.
--
-- WHAT CHANGED (follow-up to HALF YEAR WAITS ON FINAL MONTHS, #567)
--   A draft review that was started and never scored, of a colleague who
--   has since left, can never become final: perf_release refuses an
--   incomplete month and perf_close_windows skips a draft. Counted as open,
--   it held the whole half from being confirmed for good. Such a draft is
--   no longer counted (an inactive colleague earns no share); a released,
--   queried or acknowledged month of theirs still is, since it closes by
--   itself. perf_period answers `open_reviews` (name, month, state) beside
--   the count, and Bonus and trip names them.
--
-- ROLLBACK
--   Run the perf_period and perf_period_confirm definitions of the HALF
--   YEAR WAITS ON FINAL MONTHS section of supabase/schema.sql again.
-- ===========================================================================

create or replace function public.perf_period(p_token text, p_from date)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_err text; v_me public.team_members; v_f date; v_rw public.perf_rewards; v_c public.perf_company; v_out jsonb;
begin
  v_err := public.perf_check(p_token, 'view');
  if v_err is not null then return jsonb_build_object('error', v_err); end if;
  v_me := public.ops_me();
  v_f := public.perf_half(coalesce(p_from, public.perf_today()));
  if v_f < date '2026-07-01' then return jsonb_build_object('error', 'before-first'); end if;
  select * into v_rw from public.perf_rewards where kind = 'period' and period = v_f;
  v_out := coalesce(v_rw.snapshot, public.perf_period_calc(v_f));
  v_out := v_out || jsonb_build_object(
    'people', public.perf_hide_own(v_out -> 'people', v_me.id),
    'admin', public.perf_is_admin(),
    'confirmed', v_rw.period is not null, 'confirmed_at', v_rw.confirmed_at,
    'confirmed_by', (select t.name from public.team_members t where t.id = v_rw.confirmed_by),
    'ended', public.perf_today() >= (v_f + interval '6 months')::date,
    /* What still waits: every review of the six months not final, but a
       draft of a colleague who has left, which can never be released and
       earns no share. */
    'open_months', (select count(*)::int from public.perf_reviews r
                      join public.team_members t on t.id = r.team_member_id
                     where r.status <> 'final' and r.period >= v_f and r.period < (v_f + interval '6 months')::date
                       and not (r.status = 'draft' and not t.active)),
    'open_reviews', (select coalesce(jsonb_agg(jsonb_build_object('name', t.name, 'period', r.period, 'status', r.status)
                                               order by r.period, t.name), '[]'::jsonb)
                       from public.perf_reviews r
                       join public.team_members t on t.id = r.team_member_id
                      where r.status <> 'final' and r.period >= v_f and r.period < (v_f + interval '6 months')::date
                        and not (r.status = 'draft' and not t.active)),
    'events', public.perf_reward_events(array['company_set', 'period_confirmed', 'period_reopened'], v_f::text));
  /* Revenue and profit, and the ceiling they set, for an admin alone. */
  if public.perf_is_admin() then
    select * into v_c from public.perf_company where period = v_f;
    if v_c.period is not null then
      v_out := v_out || jsonb_build_object('company', jsonb_build_object('revenue', v_c.revenue, 'profit', v_c.profit,
        'pool', v_c.pool, 'trip_budget', v_c.trip_budget, 'max_pool', greatest(0, floor(v_c.profit * public.perf_setting('bonus_pool_profit_pct', v_f)) / 100)));
    end if;
  end if;
  return v_out;
end $$;

create or replace function public.perf_period_confirm(p_token text, p_from date)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_err text; v_me public.team_members; v_f date; v_snap jsonb; v_x jsonb; v_open integer;
begin
  v_err := public.perf_check(p_token, 'work');
  if v_err is not null then return jsonb_build_object('error', v_err); end if;
  v_me := public.ops_me();
  v_f := public.perf_half(p_from);
  if v_f is null or v_f < date '2026-07-01' then return jsonb_build_object('error', 'before-first'); end if;
  if exists (select 1 from public.perf_rewards where kind = 'period' and period = v_f) then
    return public.perf_period(p_token, v_f);
  end if;
  if public.perf_today() < (v_f + interval '6 months')::date then
    return jsonb_build_object('error', 'period-open');
  end if;
  /* Every review in the six months final first, as a quarter's: the
     calculation reads final months alone, and a snapshot is kept. A draft
     of a colleague who has left never can be, and earns no share. */
  select count(*)::int into v_open
    from public.perf_reviews r
    join public.team_members t on t.id = r.team_member_id
   where r.status <> 'final' and r.period >= v_f and r.period < (v_f + interval '6 months')::date
     and not (r.status = 'draft' and not t.active);
  if v_open > 0 then
    return jsonb_build_object('error', 'months-open', 'count', v_open, 'scope', 'period');
  end if;
  if not exists (select 1 from public.perf_company where period = v_f) then
    return jsonb_build_object('error', 'figures-needed');
  end if;
  v_snap := public.perf_period_calc(v_f);
  insert into public.perf_rewards (kind, period, snapshot, confirmed_by) values ('period', v_f, v_snap, v_me.id)
  on conflict (kind, period) do nothing;
  perform public.perf_log(null, null, 'period_confirmed', jsonb_build_object('key', v_f::text));
  for v_x in select * from jsonb_array_elements(v_snap -> 'people') loop
    if (v_x ->> 'active')::boolean then
      perform public.perf_notify((v_x ->> 'team_member_id')::uuid, 'perf.period',
        'Your ' || public.perf_period_word(v_f) || ' bonus and trip outcome is ready.',
        'perf.period.' || v_f || '.' || (v_x ->> 'team_member_id') || '.' || extract(epoch from now())::bigint);
    end if;
  end loop;
  return public.perf_period(p_token, v_f);
end $$;

revoke all on function public.perf_period(text, date) from public, anon, authenticated;
revoke all on function public.perf_period_confirm(text, date) from public, anon, authenticated;
grant execute on function public.perf_period(text, date) to authenticated;
grant execute on function public.perf_period_confirm(text, date) to authenticated;

-- END OF A LEFT COLLEAGUE'S DRAFT NEVER HOLDS THE HALF ----------------------

-- ===========================================================================
-- SUPPLIERS — the team's suppliers, each invited by a link to fill in their
-- own details, and letters issued to them from Documents (2026-10-18)
-- ===========================================================================
-- WHY (the user, 2026-10-18: "documents also need to issue to supplier";
-- the supplier sign-up form on Jotform "could jump into the fill in via
-- portal and data sync into it similar as client billing section"; "invite
-- only, with create link and set the supplier id before sending"; "nric only
-- for individuals"; "and 2 also can together")
--
-- WHAT IT ADDS
--   * `suppliers`: one row a supplier (its code, ASxxx, typed by the team;
--     what the form asks; Pending, Active or Inactive). RLS on, no policy,
--     no grant: read and written through the functions below.
--   * Two parts of Documents: `register.suppliers` (follows Documents: the
--     list, the links, the letters) and `register.supplier_pay` (granted, an
--     admin's by itself: the NRIC and the bank details, read at View and
--     written at Work). Without it, those fields are never sent.
--   * `supplier_forms`: one row a link (the supplier, its key, when it ends,
--     the answers once sent, taken in by whom). RLS on, no policy, no grant.
--     A link is open `details_form_days` (14), as a client's details form.
--   * `suppliers_list()`, `supplier_get(p_id)`, `supplier_create(p_code,
--     p_name)`, `supplier_link(p_id, p_reset)`, `supplier_save(p_id,
--     p_values, p_form)`, `supplier_set_status(p_id, p_status)`,
--     `supplier_delete(p_id, p_name)`: the team's, at the levels above.
--   * `supplier_form_read(p_key)` and `supplier_form_submit(p_key,
--     p_answers)` (anon): the supplier's page. The answers are checked as
--     the Jotform form checked them and wait for the team; they never write
--     the record by themselves. The team at Documents: Suppliers Work is
--     told (kind `supplier.details`).
--   * Documents: a family `supplier` (`doc_types`, `documents`), a
--     `documents.supplier_id`, a type Letter to Supplier (code GL),
--     `register_may('supplier', …)` answering `register.suppliers`, and
--     `issue_document` taking `p_supplier` (the reference
--     `ASL/{supplier code}/{YYMMDD}{NN}`); `document_reissue` keeps the
--     supplier.
--   * `activity_section()` files `supplier.*` under Documents.
--
-- ORDER: 2026-10-07-function-hygiene.sql again (its `open_to_anon` now names
-- the two form functions), this file, then the pages. A page served before
-- this file meets no Suppliers tab data ("This needs a database update").
-- Safe to run twice. Rollback: drop the functions below, the two tables,
-- `documents.supplier_id`; put back the family checks without `supplier`
-- (after deleting that family's documents and type), `register_may`,
-- `issue_document` (13 arguments), `document_reissue` and
-- `activity_section` from schema.sql's earlier sections.
-- ===========================================================================

create table if not exists public.suppliers (
  id             uuid primary key default gen_random_uuid(),
  code           text not null,
  name           text not null,
  kind           text check (kind in ('company', 'individual')),
  brn            text,
  nric           text,
  tin            text,
  sst_no         text,
  phone          text,
  address        text,
  contact_name   text,
  designation    text,
  email          text,
  mobile         text,
  payment_term   text check (payment_term in ('NET 7', 'NET 30', 'NET 45', 'NET 60')),
  currency       text not null default 'MYR' check (currency in ('MYR', 'SGD')),
  payee_name     text,
  bank_name      text,
  bank_account   text,
  finance_email  text,
  swift          text,
  bank_address   text,
  status         text not null default 'pending' check (status in ('pending', 'active', 'inactive')),
  created_at     timestamptz not null default now(),
  created_by     uuid references public.team_members(id) on delete set null,
  updated_at     timestamptz not null default now(),
  approved_at    timestamptz,
  approved_by    uuid references public.team_members(id) on delete set null
);
create unique index if not exists suppliers_code_idx on public.suppliers (upper(code));
alter table public.suppliers enable row level security;
revoke all on table public.suppliers from public, anon, authenticated;

create table if not exists public.supplier_forms (
  id           uuid primary key default gen_random_uuid(),
  supplier_id  uuid not null references public.suppliers(id) on delete cascade,
  access_key   text not null unique,
  created_at   timestamptz not null default now(),
  created_by   uuid references public.team_members(id) on delete set null,
  expires_at   timestamptz not null,
  voided_at    timestamptz,
  submitted_at timestamptz,
  answers      jsonb,
  used_at      timestamptz,
  used_by      uuid references public.team_members(id) on delete set null
);
create index if not exists supplier_forms_supplier_idx on public.supplier_forms (supplier_id, created_at desc);
alter table public.supplier_forms enable row level security;
revoke all on table public.supplier_forms from public, anon, authenticated;

/* Documents: a supplier's letters. */
alter table public.documents add column if not exists supplier_id uuid references public.suppliers(id) on delete set null;
create index if not exists documents_supplier_idx on public.documents (supplier_id);
alter table public.documents drop constraint if exists documents_family_check;
alter table public.documents add constraint documents_family_check
  check (family in ('quote_cover', 'client', 'hr', 'other', 'supplier'));
alter table public.doc_types drop constraint if exists doc_types_family_check;
alter table public.doc_types add constraint doc_types_family_check
  check (family in ('quote_cover', 'client', 'hr', 'supplier'));
insert into public.doc_types (id, family, code, name, title, salutation, closing, body_en, signed, position)
select 'supplier_letter', 'supplier', 'GL', 'Letter to Supplier', '', 'Dear Sir/Madam,', 'Yours sincerely,', '', true, 60
 where not exists (select 1 from public.doc_types t where t.id = 'supplier_letter');

/* A notice about a supplier opens it. */
alter table public.ops_notifications add column if not exists supplier_id uuid references public.suppliers(id) on delete cascade;

create or replace function public.register_may(p_family text, p_level text)
returns boolean
language sql security definer stable set search_path = public as $$
  select case
    when p_family = 'hr'       then public.allowed('register.hr', p_level)
    when p_family = 'other'    then public.allowed('register.documents', p_level)
    when p_family = 'supplier' then public.allowed('register.suppliers', p_level)
    else public.allowed('register.documents', p_level) or public.allowed('clients.documents', p_level)
  end
$$;
grant execute on function public.register_may(text, text) to authenticated;

/* One check of a supplier's answers, the form's and the team's alike: the
   value cleaned, else an error naming the field. NRIC is asked of an
   individual alone, BRN of a company (an individual's checked where given). */
create or replace function public.supplier_values_check(p jsonb, p_pay boolean)
returns jsonb
language plpgsql immutable set search_path = public as $$
declare
  o jsonb := '{}'::jsonb;
  v text;
  k text;
  kind text := nullif(btrim(coalesce(p->>'kind', '')), '');
  banks constant text[] := array['Maybank', 'CIMB', 'Hong Leong Bank', 'RHB', 'BSN', 'UOB', 'OCBC', 'AmBank',
    'Bank Islam', 'Public Bank', 'Alliance Bank', 'Standard Chartered Bank', 'Touch N Go Digital',
    '[SG] DBS/POSB', '[SG] OCBC', '[SG] UOB', '[SG] CIMB', '[SG] Maybank', '[SG] Bank of China'];
  mail constant text := '^[^@\s]+@[^@\s]+\.[^@\s]+$';
begin
  if kind is null or kind not in ('company', 'individual') then return jsonb_build_object('error', 'bad-kind'); end if;
  o := o || jsonb_build_object('kind', kind);
  v := btrim(regexp_replace(coalesce(p->>'name', ''), '\s+', ' ', 'g'));
  if length(v) < 2 or length(v) > 160 then return jsonb_build_object('error', 'bad-name'); end if;
  o := o || jsonb_build_object('name', v);
  v := regexp_replace(coalesce(p->>'brn', ''), '[^0-9]', '', 'g');
  if (kind = 'company' or v <> '') and v !~ '^[0-9]{12}$' then return jsonb_build_object('error', 'bad-brn'); end if;
  o := o || jsonb_build_object('brn', nullif(v, ''));
  v := upper(regexp_replace(coalesce(p->>'tin', ''), '\s+', '', 'g'));
  if v !~ '^[A-Z0-9]{5,20}$' then return jsonb_build_object('error', 'bad-tin'); end if;
  o := o || jsonb_build_object('tin', v);
  v := upper(regexp_replace(coalesce(p->>'sst_no', ''), '\s+', '', 'g'));
  if v <> '' and v !~ '^[A-Z][0-9]{2}-[0-9]{4}-[0-9]{8}$' then return jsonb_build_object('error', 'bad-sst_no'); end if;
  o := o || jsonb_build_object('sst_no', nullif(v, ''));
  foreach k in array array['phone', 'mobile'] loop
    v := regexp_replace(coalesce(p->>k, ''), '[^0-9+]', '', 'g');
    if length(regexp_replace(v, '[^0-9]', '', 'g')) < 8 or length(regexp_replace(v, '[^0-9]', '', 'g')) > 15 then
      return jsonb_build_object('error', 'bad-' || k);
    end if;
    o := o || jsonb_build_object(k, btrim(p->>k));
  end loop;
  v := btrim(coalesce(p->>'address', ''));
  if length(v) < 10 or length(v) > 400 then return jsonb_build_object('error', 'bad-address'); end if;
  o := o || jsonb_build_object('address', v);
  foreach k in array array['contact_name', 'designation'] loop
    v := btrim(regexp_replace(coalesce(p->>k, ''), '\s+', ' ', 'g'));
    if length(v) < 2 or length(v) > 80 then return jsonb_build_object('error', 'bad-' || k); end if;
    o := o || jsonb_build_object(k, v);
  end loop;
  foreach k in array array['email', 'finance_email'] loop
    v := lower(btrim(coalesce(p->>k, '')));
    if v !~ mail or length(v) > 160 then return jsonb_build_object('error', 'bad-' || k); end if;
    o := o || jsonb_build_object(k, v);
  end loop;
  v := coalesce(p->>'payment_term', '');
  if v not in ('NET 7', 'NET 30', 'NET 45', 'NET 60') then return jsonb_build_object('error', 'bad-payment_term'); end if;
  o := o || jsonb_build_object('payment_term', v);
  v := coalesce(nullif(p->>'currency', ''), 'MYR');
  if v not in ('MYR', 'SGD') then return jsonb_build_object('error', 'bad-currency'); end if;
  o := o || jsonb_build_object('currency', v);
  if not p_pay then return o; end if;
  v := regexp_replace(coalesce(p->>'nric', ''), '[^0-9]', '', 'g');
  if kind = 'individual' then
    if v !~ '^[0-9]{12}$' then return jsonb_build_object('error', 'bad-nric'); end if;
    o := o || jsonb_build_object('nric', substr(v, 1, 6) || '-' || substr(v, 7, 2) || '-' || substr(v, 9, 4));
  else
    o := o || jsonb_build_object('nric', null);
  end if;
  v := btrim(regexp_replace(coalesce(p->>'payee_name', ''), '\s+', ' ', 'g'));
  if length(v) < 2 or length(v) > 120 then return jsonb_build_object('error', 'bad-payee_name'); end if;
  o := o || jsonb_build_object('payee_name', v);
  v := coalesce(p->>'bank_name', '');
  if not (v = any (banks)) then return jsonb_build_object('error', 'bad-bank_name'); end if;
  o := o || jsonb_build_object('bank_name', v);
  v := regexp_replace(coalesce(p->>'bank_account', ''), '[\s-]', '', 'g');
  if v !~ '^[0-9]{6,20}$' then return jsonb_build_object('error', 'bad-bank_account'); end if;
  o := o || jsonb_build_object('bank_account', v);
  v := upper(regexp_replace(coalesce(p->>'swift', ''), '\s+', '', 'g'));
  if v <> '' and v !~ '^[A-Z]{6}[A-Z0-9]{2}([A-Z0-9]{3})?$' then return jsonb_build_object('error', 'bad-swift'); end if;
  o := o || jsonb_build_object('swift', nullif(v, ''));
  v := btrim(coalesce(p->>'bank_address', ''));
  if length(v) > 300 then return jsonb_build_object('error', 'bad-bank_address'); end if;
  o := o || jsonb_build_object('bank_address', nullif(v, ''));
  return o;
end $$;
revoke all on function public.supplier_values_check(jsonb, boolean) from public, anon, authenticated;

/* A supplier as the team reads it: the bank details only for Documents:
   Supplier payment at View. */
create or replace function public.supplier_json(s public.suppliers, p_pay boolean)
returns jsonb
language sql stable set search_path = public as $$
  select jsonb_strip_nulls(jsonb_build_object(
    'id', s.id, 'code', s.code, 'name', s.name, 'kind', s.kind, 'brn', s.brn, 'tin', s.tin, 'sst_no', s.sst_no,
    'phone', s.phone, 'address', s.address, 'contact_name', s.contact_name, 'designation', s.designation,
    'email', s.email, 'mobile', s.mobile, 'payment_term', s.payment_term, 'currency', s.currency,
    'finance_email', s.finance_email, 'status', s.status, 'created_at', s.created_at, 'updated_at', s.updated_at,
    'approved_at', s.approved_at,
    'approved_by', (select m.name from public.team_members m where m.id = s.approved_by))
    || case when p_pay then jsonb_strip_nulls(jsonb_build_object(
      'nric', s.nric, 'payee_name', s.payee_name, 'bank_name', s.bank_name, 'bank_account', s.bank_account,
      'swift', s.swift, 'bank_address', s.bank_address)) else '{}'::jsonb end)
$$;
revoke all on function public.supplier_json(public.suppliers, boolean) from public, anon, authenticated;

/* The list: every supplier, and whether its answers wait. */
create or replace function public.suppliers_list()
returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if (public.ops_me()).id is null or not public.allowed('register.suppliers', 'view') then
    return jsonb_build_object('error', 'denied');
  end if;
  return jsonb_build_object('ok', true, 'rows', coalesce((
    select jsonb_agg(public.supplier_json(s, false) || jsonb_build_object('waiting', exists (
             select 1 from public.supplier_forms f
              where f.supplier_id = s.id and f.voided_at is null and f.submitted_at is not null and f.used_at is null))
           order by upper(s.code))
      from public.suppliers s), '[]'::jsonb));
end $$;
revoke all on function public.suppliers_list() from public, anon;
grant execute on function public.suppliers_list() to authenticated;

/* One supplier, its latest link and the answers sent on it. */
create or replace function public.supplier_get(p_id uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  s   public.suppliers;
  f   public.supplier_forms;
  pay boolean := public.ops_granted('register.supplier_pay', 'view');
  work boolean := public.allowed('register.suppliers', 'work');
  a   jsonb;
begin
  if (public.ops_me()).id is null or not public.allowed('register.suppliers', 'view') then
    return jsonb_build_object('error', 'denied');
  end if;
  select * into s from public.suppliers x where x.id = p_id;
  if s.id is null then return jsonb_build_object('error', 'not-found'); end if;
  select * into f from public.supplier_forms x where x.supplier_id = p_id and x.voided_at is null
   order by x.created_at desc limit 1;
  a := f.answers;
  if a is not null and not pay then
    a := a - array['nric', 'payee_name', 'bank_name', 'bank_account', 'swift', 'bank_address'];
  end if;
  return jsonb_build_object('ok', true, 'pay', pay, 'supplier', public.supplier_json(s, pay),
    'form', case when f.id is null then null else jsonb_strip_nulls(jsonb_build_object(
      'id', f.id,
      'key', case when work and f.submitted_at is null and f.expires_at > now() then f.access_key end,
      'state', case when f.used_at is not null then 'used' when f.submitted_at is not null then 'submitted'
                    when f.expires_at <= now() then 'expired' else 'open' end,
      'created_at', f.created_at, 'expires_at', f.expires_at, 'submitted_at', f.submitted_at, 'used_at', f.used_at,
      'answers', case when f.submitted_at is not null then a end)) end);
end $$;
revoke all on function public.supplier_get(uuid) from public, anon;
grant execute on function public.supplier_get(uuid) to authenticated;

/* A new link for a supplier, or the one still open. */
create or replace function public.supplier_link(p_id uuid, p_reset boolean default false)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me    public.team_members := public.ops_me();
  s     public.suppliers;
  f     public.supplier_forms;
  v_key text;
  v_days int;
begin
  if me.id is null or not public.allowed('register.suppliers', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into s from public.suppliers x where x.id = p_id;
  if s.id is null then return jsonb_build_object('error', 'not-found'); end if;
  select * into f from public.supplier_forms x
   where x.supplier_id = p_id and x.voided_at is null and x.submitted_at is null and x.expires_at > now()
   order by x.created_at desc limit 1;
  if f.id is not null and not coalesce(p_reset, false) then
    return jsonb_build_object('ok', true, 'id', f.id, 'key', f.access_key, 'expires_at', f.expires_at);
  end if;
  update public.supplier_forms x set voided_at = now()
   where x.supplier_id = p_id and x.voided_at is null and x.submitted_at is null;
  loop
    v_key := public.new_link_key();
    exit when not exists (select 1 from public.supplier_forms x where x.access_key = v_key);
  end loop;
  v_days := coalesce(public.app_setting('details_form_days', (now() at time zone 'Asia/Kuala_Lumpur')::date), 14)::int;
  insert into public.supplier_forms (supplier_id, access_key, created_by, expires_at)
  values (p_id, v_key, me.id, now() + make_interval(days => v_days))
  returning * into f;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'supplier.edited', s.name,
          s.code || ' · ' || case when coalesce(p_reset, false) then 'Details form link reset' else 'Details form link created' end);
  return jsonb_build_object('ok', true, 'id', f.id, 'key', f.access_key, 'expires_at', f.expires_at);
end $$;
revoke all on function public.supplier_link(uuid, boolean) from public, anon;
grant execute on function public.supplier_link(uuid, boolean) to authenticated;

/* A supplier named and numbered by the team, Pending, with its link. */
create or replace function public.supplier_create(p_code text, p_name text)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me     public.team_members := public.ops_me();
  v_code text := upper(regexp_replace(coalesce(p_code, ''), '\s+', '', 'g'));
  v_name text := btrim(regexp_replace(coalesce(p_name, ''), '\s+', ' ', 'g'));
  v_id   uuid;
  r      jsonb;
begin
  if me.id is null or not public.allowed('register.suppliers', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if v_code !~ '^[A-Z0-9]{2,12}$' then return jsonb_build_object('error', 'bad-code'); end if;
  if length(v_name) < 2 or length(v_name) > 160 then return jsonb_build_object('error', 'bad-name'); end if;
  if exists (select 1 from public.suppliers s where upper(s.code) = v_code) then
    return jsonb_build_object('error', 'code-taken', 'name', (select s.name from public.suppliers s where upper(s.code) = v_code));
  end if;
  insert into public.suppliers (code, name, created_by) values (v_code, v_name, me.id) returning id into v_id;
  insert into public.activity_log (actor, action, subject, detail) values (me.name, 'supplier.added', v_name, v_code);
  r := public.supplier_link(v_id, false);
  return jsonb_build_object('ok', true, 'id', v_id, 'key', r->>'key', 'expires_at', r->'expires_at');
end $$;
revoke all on function public.supplier_create(text, text) from public, anon;
grant execute on function public.supplier_create(text, text) to authenticated;

/* The team's own Save: the details, the code and name, the bank details at
   Documents: Supplier payment Work alone; a form's answers taken in with it. */
create or replace function public.supplier_save(p_id uuid, p_values jsonb, p_form uuid default null)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me    public.team_members := public.ops_me();
  s     public.suppliers;
  pay   boolean := public.ops_granted('register.supplier_pay', 'work');
  v     jsonb;
  v_code text := upper(regexp_replace(coalesce(p_values->>'code', ''), '\s+', '', 'g'));
  moved text[] := '{}';
  k     text;
  word  constant jsonb := '{"code":"Supplier ID","name":"Name","kind":"Type","brn":"BRN","tin":"TIN","sst_no":"SST no.",
    "phone":"Office / mobile","address":"Billing address","contact_name":"Legal name","designation":"Designation",
    "email":"Email","mobile":"Mobile / WhatsApp","payment_term":"Payment term","currency":"Currency",
    "finance_email":"Finance email","nric":"NRIC","payee_name":"Payee name","bank_name":"Bank",
    "bank_account":"Account number","swift":"SWIFT code","bank_address":"Bank address"}';
  secret constant text[] := array['nric', 'payee_name', 'bank_name', 'bank_account', 'swift', 'bank_address'];
  was   jsonb;
begin
  if me.id is null or not public.allowed('register.suppliers', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into s from public.suppliers x where x.id = p_id for update;
  if s.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if v_code !~ '^[A-Z0-9]{2,12}$' then return jsonb_build_object('error', 'bad-code'); end if;
  if exists (select 1 from public.suppliers x where upper(x.code) = v_code and x.id <> p_id) then
    return jsonb_build_object('error', 'code-taken', 'name', (select x.name from public.suppliers x where upper(x.code) = v_code));
  end if;
  v := public.supplier_values_check(coalesce(p_values, '{}'::jsonb), pay);
  if v ? 'error' then return v; end if;
  v := v || jsonb_build_object('code', v_code);
  was := to_jsonb(s);
  for k in select jsonb_object_keys(v) loop
    if (was->>k) is distinct from (v->>k) then
      moved := moved || case when k = any (secret) then (word->>k)
        else (word->>k) || ': ' || coalesce(was->>k, 'not set') || ' → ' || coalesce(v->>k, 'not set') end;
    end if;
  end loop;
  update public.suppliers x set
    code = v_code, name = v->>'name', kind = v->>'kind', brn = v->>'brn', tin = v->>'tin', sst_no = v->>'sst_no',
    phone = v->>'phone', address = v->>'address', contact_name = v->>'contact_name', designation = v->>'designation',
    email = v->>'email', mobile = v->>'mobile', payment_term = v->>'payment_term', currency = v->>'currency',
    finance_email = v->>'finance_email',
    nric = case when pay then v->>'nric' else x.nric end,
    payee_name = case when pay then v->>'payee_name' else x.payee_name end,
    bank_name = case when pay then v->>'bank_name' else x.bank_name end,
    bank_account = case when pay then v->>'bank_account' else x.bank_account end,
    swift = case when pay then v->>'swift' else x.swift end,
    bank_address = case when pay then v->>'bank_address' else x.bank_address end,
    updated_at = now()
   where x.id = p_id;
  if p_form is not null then
    update public.supplier_forms f set used_at = coalesce(f.used_at, now()), used_by = coalesce(f.used_by, me.id)
     where f.id = p_form and f.supplier_id = p_id and f.submitted_at is not null;
  end if;
  if array_length(moved, 1) is not null then
    insert into public.activity_log (actor, action, subject, detail)
    values (me.name, 'supplier.edited', v->>'name', v_code || ' · ' || array_to_string(moved, ' · ') ||
            case when p_form is not null then ' · from the details form' else '' end);
  end if;
  return jsonb_build_object('ok', true, 'supplier',
    public.supplier_json((select x from public.suppliers x where x.id = p_id), public.ops_granted('register.supplier_pay', 'view')));
end $$;
revoke all on function public.supplier_save(uuid, jsonb, uuid) from public, anon;
grant execute on function public.supplier_save(uuid, jsonb, uuid) to authenticated;

/* Approve (Pending to Active, the details complete), Set inactive and
   Set active. */
create or replace function public.supplier_set_status(p_id uuid, p_status text)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  s  public.suppliers;
begin
  if me.id is null or not public.allowed('register.suppliers', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if p_status not in ('active', 'inactive') then return jsonb_build_object('error', 'bad-status'); end if;
  select * into s from public.suppliers x where x.id = p_id for update;
  if s.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if s.status = p_status then return jsonb_build_object('ok', true, 'status', s.status); end if;
  if p_status = 'active' and (s.kind is null or s.tin is null or s.address is null or s.email is null
      or s.payment_term is null or s.bank_account is null) then
    return jsonb_build_object('error', 'incomplete');
  end if;
  update public.suppliers x set status = p_status, updated_at = now(),
    approved_at = case when p_status = 'active' and x.approved_at is null then now() else x.approved_at end,
    approved_by = case when p_status = 'active' and x.approved_at is null then me.id else x.approved_by end
   where x.id = p_id;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, case when s.status = 'pending' then 'supplier.approved' else 'supplier.edited' end, s.name,
          s.code || ' · ' || initcap(s.status) || ' → ' || initcap(p_status));
  return jsonb_build_object('ok', true, 'status', p_status);
end $$;
revoke all on function public.supplier_set_status(uuid, text) from public, anon;
grant execute on function public.supplier_set_status(uuid, text) to authenticated;

/* Delete, at Manage, the name typed back. Letters issued keep their words. */
create or replace function public.supplier_delete(p_id uuid, p_name text)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  s  public.suppliers;
begin
  if me.id is null or not public.allowed('register.suppliers', 'manage') then return jsonb_build_object('error', 'denied'); end if;
  select * into s from public.suppliers x where x.id = p_id for update;
  if s.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if lower(btrim(coalesce(p_name, ''))) <> lower(btrim(s.name)) then return jsonb_build_object('error', 'bad-name'); end if;
  delete from public.suppliers x where x.id = p_id;
  insert into public.activity_log (actor, action, subject, detail) values (me.name, 'supplier.deleted', s.name, s.code);
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.supplier_delete(uuid, text) from public, anon;
grant execute on function public.supplier_delete(uuid, text) to authenticated;

/* What the supplier's page may know before it is filled in. */
create or replace function public.supplier_form_read(p_key text)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  f public.supplier_forms;
  s public.suppliers;
begin
  if coalesce(p_key, '') !~ '^[a-z0-9]{8}$' then return jsonb_build_object('error', 'not_found'); end if;
  select * into f from public.supplier_forms x where x.access_key = p_key and x.voided_at is null;
  if f.id is null then return jsonb_build_object('error', 'not_found'); end if;
  if f.submitted_at is not null then return jsonb_build_object('error', 'submitted'); end if;
  if f.expires_at <= now() then return jsonb_build_object('error', 'expired'); end if;
  select * into s from public.suppliers x where x.id = f.supplier_id;
  return jsonb_build_object('ok', true, 'name', s.name, 'code', s.code, 'expires_at', f.expires_at);
end $$;
revoke all on function public.supplier_form_read(text) from public;
grant execute on function public.supplier_form_read(text) to anon, authenticated;

/* The supplier's answers, once, checked as the form checks them. */
create or replace function public.supplier_form_submit(p_key text, p_answers jsonb)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  f public.supplier_forms;
  s public.suppliers;
  v jsonb;
begin
  if coalesce(p_key, '') !~ '^[a-z0-9]{8}$' then return jsonb_build_object('error', 'not_found'); end if;
  select * into f from public.supplier_forms x where x.access_key = p_key and x.voided_at is null for update;
  if f.id is null then return jsonb_build_object('error', 'not_found'); end if;
  if f.submitted_at is not null then return jsonb_build_object('error', 'submitted'); end if;
  if f.expires_at <= now() then return jsonb_build_object('error', 'expired'); end if;
  if coalesce(p_answers->>'authorise', '') <> 'true' then return jsonb_build_object('error', 'bad-authorise'); end if;
  v := public.supplier_values_check(coalesce(p_answers, '{}'::jsonb), true);
  if v ? 'error' then return v; end if;
  update public.supplier_forms x set submitted_at = now(), answers = jsonb_strip_nulls(v) where x.id = f.id;
  select * into s from public.suppliers x where x.id = f.supplier_id;
  insert into public.activity_log (actor, action, subject, detail)
  values (v->>'contact_name', 'supplier.edited', s.name, s.code || ' · Details received on the details form');
  insert into public.ops_notifications (team_member_id, kind, title, body, supplier_id, dedupe_key)
  select m.id, 'supplier.details', 'Supplier details received · ' || s.name,
         'From ' || (v->>'contact_name') || '. Review them on the supplier.',
         s.id, 'supplier.details:' || f.id || ':' || m.id
    from public.team_members m
   where m.active and not coalesce(m.system, false)
     and (m.is_admin or m.role = 'admin'
          or public.level_rank(coalesce(m.access ->> 'register.suppliers', m.access ->> 'register')) >= 2)
  on conflict (dedupe_key) do nothing;
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.supplier_form_submit(text, jsonb) from public;
grant execute on function public.supplier_form_submit(text, jsonb) to anon, authenticated;

/* Issue: a supplier's letter names its supplier and is numbered
   ASL/{supplier code}/{YYMMDD}{NN}. The signature grows by p_supplier, so
   the old one goes first. */
drop function if exists public.issue_document(text, uuid, uuid, text, date, text, jsonb, jsonb, jsonb, text[], text, text, boolean);
create or replace function public.issue_document(
  p_type      text,
  p_client    uuid,
  p_member    uuid,
  p_serial    text,
  p_issued_at date,
  p_title     text,
  p_recipient jsonb,
  p_body      jsonb,
  p_signatory jsonb,
  p_languages text[],
  p_idem      text,
  p_salutation text default null,
  p_signed    boolean default null,
  p_supplier  uuid default null
)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  who     text := lower(auth.jwt() ->> 'email');
  t       public.doc_types%rowtype;
  cl      public.clients%rowtype;
  mb      public.team_members%rowtype;
  sp      public.suppliers%rowtype;
  me      public.team_members%rowtype;
  v_old   public.documents%rowtype;
  v_serial text;
  v_base  text;
  v_n     int;
  v_id    uuid;
  v_langs text[];
  v_signed boolean;
begin
  select * into t from public.doc_types where id = p_type and active;
  if t.id is null then return jsonb_build_object('error', 'no-type'); end if;
  if not public.register_may(t.family, 'work') then return jsonb_build_object('error', 'not-allowed'); end if;

  if coalesce(btrim(p_idem), '') <> '' then
    select * into v_old from public.documents where idem_key = btrim(p_idem) limit 1;
    if v_old.id is not null then
      return jsonb_build_object('ok', true, 'repeat', true, 'id', v_old.id, 'serial', v_old.serial);
    end if;
  end if;

  if t.family in ('quote_cover', 'client') then
    if p_client is null then return jsonb_build_object('error', 'no-client'); end if;
    select * into cl from public.clients where id = p_client;
    if cl.id is null then return jsonb_build_object('error', 'no-client'); end if;
  end if;
  if t.family = 'hr' then
    if p_member is null then return jsonb_build_object('error', 'no-member'); end if;
    select * into mb from public.team_members where id = p_member;
    if mb.id is null then return jsonb_build_object('error', 'no-member'); end if;
    if coalesce(btrim(mb.staff_code), '') = '' then return jsonb_build_object('error', 'no-staff-code'); end if;
  end if;
  if t.family = 'supplier' then
    if p_supplier is null then return jsonb_build_object('error', 'no-supplier'); end if;
    select * into sp from public.suppliers where id = p_supplier;
    if sp.id is null then return jsonb_build_object('error', 'no-supplier'); end if;
  end if;

  -- Whether the letter leaves space to be signed is the sheet's tick
  -- (2026-10-01), else the type's own setting. A signed letter is signed by
  -- a person, never by a permission; an unsigned one may still name who
  -- issued it, held to the same test.
  v_signed := coalesce(p_signed, t.signed);
  if coalesce(btrim(p_signatory ->> 'name'), '') <> '' and not public.issuer_name_ok(p_signatory ->> 'name') then
    return jsonb_build_object('error', 'issuer-name', 'name', p_signatory ->> 'name');
  end if;
  if v_signed then
    if coalesce(btrim(p_signatory ->> 'name'), '') = '' then return jsonb_build_object('error', 'no-signatory'); end if;
    if not public.issuer_name_ok(p_signatory ->> 'name') then
      return jsonb_build_object('error', 'issuer-name', 'name', p_signatory ->> 'name');
    end if;
  end if;

  v_serial := nullif(btrim(coalesce(p_serial, '')), '');
  if v_serial is null then
    if t.family = 'quote_cover' then return jsonb_build_object('error', 'serial-required'); end if;
    if t.family in ('client', 'supplier') then
      if t.family = 'client' then
        if coalesce(btrim(cl.client_code), '') = '' then return jsonb_build_object('error', 'no-client-code'); end if;
        v_base := 'ACL/' || upper(btrim(cl.client_code));
      else
        v_base := 'ASL/' || upper(btrim(sp.code));
      end if;
      v_base := v_base || '/' || to_char(coalesce(p_issued_at, (timezone('Asia/Kuala_Lumpur', now()))::date), 'YYMMDD');
      -- Two issuers on one client (or supplier) and day wait for each other
      -- here, so the second never reads the first one's number as free.
      perform pg_advisory_xact_lock(hashtext('acl:' || v_base));
      v_n := 1;
      loop
        v_serial := v_base || case when v_n < 10 then '0' else '' end || v_n;
        exit when not public.serial_taken(v_serial);
        v_n := v_n + 1;
        if v_n > 999 then return jsonb_build_object('error', 'no-serial'); end if;
      end loop;
    else
      v_base := 'ADHR/' || upper(mb.staff_code) || '/' || coalesce(t.code, 'GL') ||
                to_char(timezone('Asia/Kuala_Lumpur', now()), 'YYMM');
      v_serial := v_base; v_n := 1;
      while public.serial_taken(v_serial) loop
        v_n := v_n + 1; v_serial := v_base || '-' || v_n;
      end loop;
    end if;
  else
    if v_serial !~ '^[A-Za-z0-9/._-]{3,40}$' then return jsonb_build_object('error', 'serial-shape'); end if;
    if public.serial_taken(v_serial) then return jsonb_build_object('error', 'serial-taken'); end if;
  end if;

  v_langs := coalesce(p_languages, '{en}');
  if array_length(v_langs, 1) is null then v_langs := '{en}'; end if;

  select * into me from public.team_members where lower(email) = who and active limit 1;

  insert into public.documents
    (type_id, family, kind, serial, client_id, member_id, supplier_id, issued_at, title, salutation, closing,
     recipient, body, languages, signatory, signed, source, issued_by, idem_key)
  values
    (t.id, t.family, t.name, v_serial,
     case when t.family in ('hr', 'supplier') then null else p_client end,
     case when t.family = 'hr' then p_member else null end,
     case when t.family = 'supplier' then p_supplier else null end,
     coalesce(p_issued_at, (timezone('Asia/Kuala_Lumpur', now()))::date),
     coalesce(nullif(btrim(p_title), ''), t.title),
     coalesce(nullif(btrim(p_salutation), ''), t.salutation), t.closing,
     coalesce(p_recipient, '{}'::jsonb), coalesce(p_body, '{}'::jsonb), v_langs,
     case when coalesce(btrim(p_signatory ->> 'name'), '') <> '' then p_signatory else null end, v_signed, 'portal',
     coalesce(me.name, who), nullif(btrim(p_idem), ''))
  returning id into v_id;

  -- The record is told an HR letter was issued and nothing about whom: the
  -- Activity record is read by more people than HR is.
  if t.family = 'hr' then
    insert into public.activity_log (actor, action, subject, detail)
    values (who, 'document.issued', 'HR', t.name);
  else
    insert into public.activity_log (actor, action, subject, detail)
    values (who, 'document.issued', case when t.family = 'supplier' then sp.name else cl.name end, v_serial || ' · ' || t.name);
  end if;
  return jsonb_build_object('ok', true, 'id', v_id, 'serial', v_serial);
exception
  when unique_violation then
    if coalesce(btrim(p_idem), '') <> '' then
      select * into v_old from public.documents where idem_key = btrim(p_idem) limit 1;
      if v_old.id is not null then
        return jsonb_build_object('ok', true, 'repeat', true, 'id', v_old.id, 'serial', v_old.serial);
      end if;
    end if;
    return jsonb_build_object('error', 'serial-taken');
end $$;
grant execute on function public.issue_document(text, uuid, uuid, text, date, text, jsonb, jsonb, jsonb, text[], text, text, boolean, uuid) to authenticated;

/* A reissue keeps the supplier its letter was addressed to. */
create or replace function public.document_reissue(
  p_doc       uuid,
  p_issued_at date,
  p_title     text,
  p_recipient jsonb,
  p_body      jsonb,
  p_signatory jsonb,
  p_languages text[],
  p_salutation text,
  p_idem      text
)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  who    text := lower(auth.jwt() ->> 'email');
  d      public.documents%rowtype;
  v_old  public.documents%rowtype;
  me     public.team_members%rowtype;
  cl     public.clients%rowtype;
  v_id   uuid;
  v_langs text[];
begin
  select * into d from public.documents where id = p_doc;
  if d.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if d.source <> 'portal' then return jsonb_build_object('error', 'not-portal'); end if;
  if not public.register_may(d.family, 'work') then return jsonb_build_object('error', 'not-allowed'); end if;
  if coalesce(btrim(p_idem), '') <> '' then
    select * into v_old from public.documents where idem_key = btrim(p_idem) limit 1;
    if v_old.id is not null then
      return jsonb_build_object('ok', true, 'repeat', true, 'id', v_old.id, 'serial', v_old.serial);
    end if;
  end if;
  if exists (select 1 from public.documents
              where upper(serial) = upper(d.serial) and voided_at is null and id <> d.id) then
    return jsonb_build_object('error', 'not-current');
  end if;
  if d.signed then
    if coalesce(btrim(p_signatory ->> 'name'), '') = '' then return jsonb_build_object('error', 'no-signatory'); end if;
    if not public.issuer_name_ok(p_signatory ->> 'name') then
      return jsonb_build_object('error', 'issuer-name', 'name', p_signatory ->> 'name');
    end if;
  end if;
  v_langs := coalesce(p_languages, d.languages, '{en}');
  if array_length(v_langs, 1) is null then v_langs := '{en}'; end if;
  select * into me from public.team_members where lower(email) = who and active limit 1;

  if d.voided_at is null then
    update public.documents set voided_at = now(), voided_by = who, void_reason = 'Reissued' where id = d.id;
  end if;
  insert into public.documents
    (type_id, family, kind, serial, client_id, member_id, supplier_id, issued_at, title, salutation, closing,
     recipient, body, languages, signatory, signed, source, issued_by, idem_key, replaces)
  values
    (d.type_id, d.family, d.kind, d.serial, d.client_id, d.member_id, d.supplier_id,
     coalesce(p_issued_at, d.issued_at, (timezone('Asia/Kuala_Lumpur', now()))::date),
     coalesce(nullif(btrim(p_title), ''), d.title),
     coalesce(nullif(btrim(p_salutation), ''), d.salutation), d.closing,
     coalesce(p_recipient, d.recipient), coalesce(p_body, d.body), v_langs,
     case when d.signed then p_signatory else null end, d.signed, 'portal',
     coalesce(me.name, who), nullif(btrim(p_idem), ''), d.id)
  returning id into v_id;

  if d.client_id is not null then select * into cl from public.clients where id = d.client_id; end if;
  insert into public.activity_log (actor, action, subject, detail)
  values (who, 'document.reissued',
          case when d.family = 'hr' then 'HR' else coalesce(cl.name, (select s.name from public.suppliers s where s.id = d.supplier_id), d.recipient ->> 'name', '') end,
          case when d.family = 'hr' then d.kind else d.serial || ' · ' || d.kind end);
  return jsonb_build_object('ok', true, 'id', v_id, 'serial', d.serial);
exception
  when unique_violation then
    return jsonb_build_object('error', 'serial-taken');
end $$;
grant execute on function public.document_reissue(uuid, date, text, jsonb, jsonb, jsonb, text[], text, text) to authenticated;

/* A supplier's steps are filed under Documents. */
create or replace function public.activity_section(p_action text)
returns text
language sql immutable parallel safe as $$
  select case
    when action in ('campaign.bulk', 'campaign.closed', 'campaign.confirmed',
                    'campaign.created', 'campaign.dates', 'campaign.deleted', 'campaign.edited',
                    'campaign.file_added', 'campaign.file_deleted', 'campaign.file_hidden',
                    'campaign.file_shown', 'campaign.qc',
                    'campaign.invoice', 'campaign.invoice_file',
                    'campaign.invoice_removed', 'campaign.keyed', 'campaign.locked',
                    'campaign.opened', 'campaign.rate', 'campaign.rated',
                    'campaign.reinstated', 'campaign.replaced', 'campaign.results', 'campaign.review',
                    'campaign.stage', 'campaign.submitted', 'campaign.task_linked',
                    'campaign.task_unlinked', 'campaign.unbooked',
                    'campaign.unkeyed', 'campaign.whatsapp', 'campaign.withdrawn', 'creator.added',
                    'creator.code', 'creator.links', 'creator.links_restored',
                    'creator.links_self', 'creator.off', 'creator.on', 'creator.removed',
                    'creator.updated') then 'campaigns'
    when action in ('client.action_done', 'client.action_reopened', 'client.added',
                    'client.billing', 'client.brand', 'client.deleted', 'client.edited',
                    'client.quotation', 'client.review_on', 'client.service', 'client.service_changed',
                    'client.service_deleted', 'client.service_removed', 'client.service_restored', 'client.stage', 'client.touch',
                    'client.touch_deleted', 'client.touch_edited', 'client.touch_removed',
                    'client.touch_restored', 'contact.added', 'contact.deleted',
                    'contact.edited', 'contact.portal_invite', 'contact.portal_off',
                    'contact.portal_on', 'contact.primary', 'contact.removed',
                    'contact.restored',
                    'request.changed', 'request.raised',
                    'request.reinstated', 'request.replied', 'request.withdrawn',
                    'service.override') then 'clients'
    when action in ('wa.sent', 'wa.template') then 'whatsapp'
    when action in ('report.ai_drafted', 'report.ai_failed', 'report.audited', 'report.confirmed',
                    'report.created', 'report.deleted', 'report.published',
                    'report.reassigned', 'report.returned', 'report.revised', 'report.saved',
                    'report.submitted', 'report.unpublished') then 'reports'
    when action in ('qr.created', 'qr.restored', 'qr.revoked', 'shortlink.created',
                    'shortlink.deleted', 'shortlink.imported', 'shortlink.updated') then 'links'
    when action in ('ops.deleted', 'ops.month_deleted', 'ops.numbering') then 'ops'
    when action in ('document.deleted', 'document.issued', 'document.reissued',
                    'document.restored', 'document.signed', 'document.superseded',
                    'document.unsigned', 'document.verified', 'document.voided',
                    'register.added', 'register.edited', 'supplier.added', 'supplier.approved',
                    'supplier.deleted', 'supplier.edited') then 'register'
    when action in ('client.drive', 'client.handles', 'client.profile',
                    'client.removed', 'drive.imported', 'link.reset', 'post.added',
                    'post.deleted', 'post.edited', 'reapproval.requested',
                    'review.approved', 'review.changes', 'review.removed',
                    'review.unconfirmed',
                    'set.created', 'set.deleted', 'set.month', 'set.published', 'set.renamed',
                    'set.task_linked', 'set.task_unlinked',
                    'set.withdrawn') then 'review'
    when action in ('script.approved', 'script.changes', 'script.created', 'script.deleted',
                    'script.link', 'script.saved', 'script.shared', 'script.shot',
                    'script.unshared') then 'scripts'
    when action in ('handbook.added', 'handbook.archived', 'handbook.deleted',
                    'handbook.edited', 'handbook.restored', 'handbook.version') then 'handbook'
    when action in ('service.added', 'service.changed', 'service.deleted',
                    'service.off', 'service.on', 'service.published') then 'services'
    when action in ('team.added', 'team.changed', 'team.edited', 'team.group_added',
                    'team.group_changed', 'team.group_removed', 'team.invited') then 'team'
    else 'other'
  end
  from (select p_action as action) t
$$;
grant execute on function public.activity_section(text) to authenticated;

-- END OF SUPPLIERS -----------------------------------------------------------

-- ===========================================================================
-- HELD TASKS RESUME WHERE THEY LEFT — a task on hold, blocked or cancelled
-- goes back to the stage it left. 2026-10-18. Safe to run twice. Rollback at
-- the foot. Mirrored byte for byte in supabase/schema.sql under the same
-- banner; tests/sql.js compares the two.
--
-- WHAT CHANGED (review of 2026-10-18, item 1)
--   On hold, Blocked and Cancelled offered every open stage on the line, so
--   a task put on hold at In progress could be resumed at Approved or
--   Scheduled, past AQC and client review. ops_tasks.held_from now records
--   the stage a task left for one of the three (trigger ops_tasks_held_from;
--   moving between the three keeps it, leaving them clears it), backfilled
--   from each held task's history. ops_transition_task takes a task out of
--   On hold or Blocked only back to that stage, and out of Cancelled to that
--   stage or the start of the line (refused 'held-resume' with 'allowed').
--   Moving between the three, and a task held before its history named the
--   stage, keep the workflow's own steps. No AQC rule is added (the user,
--   2026-10-18: AQC happens on WhatsApp; keep My Work's gates light).
--
-- ROLLBACK
--   Run ops_transition_task as MONTH STAGES FOLLOW THE WORK stated it (the
--   previous last definition in schema.sql), then:
--   drop trigger if exists ops_tasks_held_from on public.ops_tasks;
--   drop function if exists public.ops_tasks_held_from();
--   alter table public.ops_tasks drop column if exists held_from;
-- ===========================================================================

alter table public.ops_tasks add column if not exists held_from text;

create or replace function public.ops_tasks_held_from()
returns trigger
language plpgsql set search_path = public as $$
begin
  if new.stage_key in ('on_hold', 'blocked', 'cancelled') then
    if tg_op = 'UPDATE' and old.stage_key in ('on_hold', 'blocked', 'cancelled') then
      new.held_from := old.held_from;
    elsif tg_op = 'UPDATE' then
      new.held_from := old.stage_key;
    else
      new.held_from := null;
    end if;
  else
    new.held_from := null;
  end if;
  return new;
end $$;
revoke all on function public.ops_tasks_held_from() from public, anon, authenticated;
drop trigger if exists ops_tasks_held_from on public.ops_tasks;
create trigger ops_tasks_held_from before insert or update of stage_key on public.ops_tasks
  for each row execute function public.ops_tasks_held_from();

/* Each task standing on one of the three now: the stage its last move into
   them came from. Blocking files its own event ('blocked'). */
update public.ops_tasks t set held_from = x.from_key
  from (select distinct on (e.task_id) e.task_id, e.from_value ->> 'stage_key' as from_key
          from public.ops_task_events e
         where e.event_type in ('stage_changed', 'blocked')
           and e.to_value ->> 'stage_key' in ('on_hold', 'blocked', 'cancelled')
           and coalesce(e.from_value ->> 'stage_key', '') not in ('on_hold', 'blocked', 'cancelled', '')
         order by e.task_id, e.created_at desc) x
 where x.task_id = t.id and t.stage_key in ('on_hold', 'blocked', 'cancelled') and t.held_from is null;

create or replace function public.ops_transition_task(
  p_task uuid, p_next text, p_version integer default null, p_note text default null,
  p_assignee uuid default null, p_skip_reason text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m   public.team_members;
  t   public.ops_tasks;
  cur public.ops_workflow_stages;
  nxt public.ops_workflow_stages;
  sk  public.ops_workflow_stages;
  eng public.ops_engagements;
  has_owner boolean;
  has_draft boolean;
  has_final boolean;
  was_owner uuid;
  side text[] := array['blocked', 'waiting', 'kiv', 'cancelled'];
  skipping boolean := false;
  going_back boolean := false;
  ws  public.ops_work_sessions;
  wmins integer;
  v_round integer;
  held text[] := array['on_hold', 'blocked', 'cancelled'];
  resume_to text[];
  first_key text;
  resuming boolean := false;
begin
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if not public.ops_may_see_task(p_task) then return jsonb_build_object('error', 'denied'); end if;
  if not public.allowed('ops', 'work') then return jsonb_build_object('error', 'denied'); end if;

  select * into t from public.ops_tasks where id = p_task for update;
  if t.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if p_version is not null and p_version <> t.version then
    return jsonb_build_object('error', 'stale', 'task', public.ops_task_json(p_task));
  end if;
  if t.stage_key = p_next then return public.ops_task_json(p_task); end if;
  /* The stage is the owner's to move. Once a task is handed to somebody,
     whoever created it or held it before reads it and no longer moves it; an
     admin still may. */
  if not public.ops_owner_may_move(p_task) then return jsonb_build_object('error', 'not-owner'); end if;

  cur := public.ops_stage(t.workflow_id, t.stage_key);
  nxt := public.ops_stage(t.workflow_id, p_next);
  if nxt.id is null then return jsonb_build_object('error', 'no-such-stage'); end if;
  /* A retired stage keeps the tasks already standing on it and takes no new
     ones: Planning and the content meeting are the month's, not a task's. */
  if nxt.retired then return jsonb_build_object('error', 'retired-stage'); end if;
  /* A task on hold, blocked or cancelled goes back to the stage it left
     (held_from, stamped by ops_tasks_held_from), and a cancelled one also
     to the start of the line; never on past stages it had not reached
     (the user, 2026-10-18: keep it light, AQC review happens on WhatsApp).
     Moving between the three is a step as before. A task held before the
     column knew where from keeps the steps of its workflow. */
  if cur.key = any (held) and not (p_next = any (held)) and t.held_from is not null then
    select s.key into first_key from public.ops_workflow_stages s
     where s.workflow_id = t.workflow_id and not s.retired
       and not (s.stage_group = any (side)) and s.stage_group <> 'revision'
       and not (s.key = any (held))
     order by s.position limit 1;
    resume_to := array[t.held_from];
    if cur.key = 'cancelled' or coalesce((public.ops_stage(t.workflow_id, t.held_from)).retired, true) then
      resume_to := resume_to || first_key;
    end if;
    if not (p_next = any (resume_to)) then
      return jsonb_build_object('error', 'held-resume', 'allowed', to_jsonb(resume_to));
    end if;
    resuming := true;
  end if;
  if not resuming and not (p_next = any (cur.next_stage_keys)) then
    /* A step the deliverable does not need is skipped, forward along the
       line, with a reason on the record: who skipped it and why is written
       against every stage that was passed over. Nothing beside the line can
       be skipped into or out of, and nothing is skipped backwards. */
    /* A revision is where work is sent back from a review, so it is never
       a step somebody skips forward into. */
    if not (cur.stage_group = any (side)) and not (nxt.stage_group = any (side))
       and nxt.stage_group <> 'revision'
       and nxt.position > cur.position then
      if nullif(btrim(coalesce(p_skip_reason, '')), '') is null then
        return jsonb_build_object('error', 'skip-reason-required');
      end if;
      skipping := true;
    /* Going back is picking an earlier stage on the line, and says why; the
       reason goes on the record with the move. A revision is entered only
       from the review that sends work to it. */
    elsif not (cur.stage_group = any (side)) and not (nxt.stage_group = any (side))
       and nxt.stage_group <> 'revision'
       and nxt.position < cur.position then
      if nullif(btrim(coalesce(p_note, '')), '') is null then
        return jsonb_build_object('error', 'back-reason-required');
      end if;
      going_back := true;
    else
      return jsonb_build_object('error', 'bad-transition',
        'allowed', to_jsonb(cur.next_stage_keys));
    end if;
  end if;

  /* A performance review goes back to whoever created the task unless the
     move names somebody else. */
  if p_next = 'performance_review' and p_assignee is null and exists (
       select 1 from public.team_members where id = t.created_by and active) then
    p_assignee := t.created_by;
  end if;

  -- What each gate needs before it opens.
  has_owner := exists (select 1 from public.ops_task_assignees
                        where task_id = p_task and responsibility = 'owner' and ended_at is null)
               or p_assignee is not null;
  has_draft := exists (select 1 from public.ops_task_links
                        where task_id = p_task and archived_at is null
                          and kind in ('draft', 'review'));
  has_final := exists (select 1 from public.ops_task_links
                        where task_id = p_task and archived_at is null and kind = 'final');

  if p_next = 'ready' and (not has_owner or t.current_final_due_at is null) then
    return jsonb_build_object('error', 'ready-needs-owner-and-due');
  end if;
  if p_next = 'editing' and exists (
       select 1 from public.ops_video_details v
        where v.task_id = p_task and v.footage_ready is false) then
    return jsonb_build_object('error', 'footage-not-ready');
  end if;
  /* Production waits on the month's own facts: its readiness ticks
     answered, and its content meeting held or marked not applicable. The
     month's stage is worked out from those facts on the page and is never
     stored, so the stored status is not read here (2026-09-27). A task with
     no month (ad hoc, internal) has nothing to wait on. */
  if p_next = 'in_production' and t.engagement_id is not null then
    select * into eng from public.ops_engagements where id = t.engagement_id;
    if exists (select 1 from public.ops_engagement_checks c
                where c.engagement_id = eng.id
                  and c.state in ('not_started', 'waiting_client', 'in_progress')) then
      return jsonb_build_object('error', 'planning-incomplete');
    end if;
    if not (eng.meeting_na or (eng.meeting_at is not null and eng.meeting_at <= now())) then
      return jsonb_build_object('error', 'meeting-required');
    end if;
  end if;
  /* AQC review comes first: the client sees the work only once it has been
     through AQC review at least once. */
  if p_next = 'client_review'
     and exists (select 1 from public.ops_workflow_stages s
                  where s.workflow_id = t.workflow_id and s.key = 'internal_review')
     and not exists (select 1 from public.ops_task_events e
                      where e.task_id = p_task and e.event_type = 'stage_changed'
                        and e.to_value ->> 'stage_key' = 'internal_review') then
    return jsonb_build_object('error', 'needs-aqc');
  end if;
  /* The draft reaches the client as a link on the task or through the
     team's WhatsApp group with the client. Either way the record says how:
     the link, or a note naming where it went. */
  if p_next = 'client_review' and not has_draft
     and nullif(btrim(coalesce(p_note, '')), '') is null then
    return jsonb_build_object('error', 'needs-draft');
  end if;
  /* A revision says what has to change, and so does taking a post down. */
  if ((nxt.stage_group = 'revision' and p_next <> 'changes_requested') or p_next = 'taken_down')
     and nullif(btrim(coalesce(p_note, '')), '') is null then
    return jsonb_build_object('error', 'note-required');
  end if;
  /* After approval: a schedule needs its date, going live is confirmed with
     its own date through ops_mark_live and needs the post's link or a note,
     and a task is completed only once its performance checklist is done. */
  if p_next = 'scheduled' and t.publish_at is null then
    return jsonb_build_object('error', 'needs-schedule');
  end if;
  if p_next = 'live' and t.live_at is null then
    return jsonb_build_object('error', 'needs-live-date');
  end if;
  if p_next = 'live' and not has_final and coalesce(p_note, '') = '' then
    return jsonb_build_object('error', 'needs-final-or-reason');
  end if;
  if p_next = 'completed' and exists (
       select 1 from public.ops_task_checklist_items c
        where c.task_id = p_task and c.required and c.completed_at is null) then
    return jsonb_build_object('error', 'checklist-incomplete');
  end if;
  if p_next = 'delivered' and not has_final then
    return jsonb_build_object('error', 'needs-final-link');
  end if;
  if p_next = 'done' and t.delivered_at is null
     and coalesce(p_note, '') = '' then
    return jsonb_build_object('error', 'needs-delivery-or-reason');
  end if;
  if p_next = 'published' and not has_final and coalesce(p_note, '') = '' then
    return jsonb_build_object('error', 'needs-final-or-reason');
  end if;

  /* The hand to the next person, recorded on the move: the previous owner
     ends, the new one begins, and the event names both with the stage it
     happened at. Work level, because handing the work on is part of doing
     it; reassigning a task without moving it stays Manage. */
  if p_assignee is not null then
    select team_member_id into was_owner from public.ops_task_assignees
     where task_id = p_task and responsibility = 'owner' and ended_at is null;
    if p_assignee is distinct from was_owner then
      if not exists (select 1 from public.team_members where id = p_assignee and active) then
        return jsonb_build_object('error', 'no-such-person');
      end if;
      update public.ops_task_assignees set ended_at = now()
       where task_id = p_task and responsibility = 'owner' and ended_at is null;
      insert into public.ops_task_assignees (task_id, team_member_id, responsibility, assigned_by)
      values (p_task, p_assignee, 'owner', m.id);
      perform public.ops_log(p_task, 'assignment_changed',
        jsonb_build_object('owner_id', was_owner),
        jsonb_build_object('owner_id', p_assignee),
        jsonb_build_object('handover', true, 'stage_key', p_next, 'from_stage_key', t.stage_key));
    end if;
  end if;

  if skipping then
    for sk in select * from public.ops_workflow_stages
               where workflow_id = t.workflow_id
                 and position > cur.position and position < nxt.position
                 and not (stage_group = any (side))
                 and stage_group <> 'revision' and not retired
               order by position loop
      perform public.ops_log(p_task, 'stage_skipped',
        jsonb_build_object('stage_key', sk.key), jsonb_build_object('stage_key', p_next),
        jsonb_build_object('reason', btrim(p_skip_reason)));
    end loop;
  end if;

  /* The round: how many times this task has now entered this review or
     this revision, counted off its own history, so nothing is stored that
     a reverted move could leave wrong. */
  if nxt.is_review or nxt.stage_group = 'revision' then
    select count(*) + 1 into v_round from public.ops_task_events e
     where e.task_id = p_task and e.event_type = 'stage_changed'
       and e.to_value ->> 'stage_key' = p_next;
  end if;

  update public.ops_tasks set
    stage_key = p_next,
    version = version + 1,
    updated_at = now(),
    first_draft_submitted_at = case
      when first_draft_submitted_at is null and nxt.is_review then now()
      else first_draft_submitted_at end,
    delivered_at = case when p_next = 'delivered' then coalesce(delivered_at, now())
                        else delivered_at end,
    completed_at = case when nxt.is_terminal and p_next <> 'cancelled' then coalesce(completed_at, now())
                        when not nxt.is_terminal then null
                        else completed_at end,
    /* Leaving Cancelled for a live stage is a reopening, and the stamp
       leaves with it, as completed_at does; left behind, the task went on
       reading cancelled at the stage it had been reopened to. */
    cancelled_at = case when p_next = 'cancelled' then coalesce(cancelled_at, now())
                        when not nxt.is_terminal then null
                        else cancelled_at end,
    blocked_at = case when p_next = 'blocked' then blocked_at else null end,
    blocked_category = case when p_next = 'blocked' then blocked_category else null end
  where id = p_task;

  /* The performance review brings its own checklist, the same five checks
     for a brand post and a KOC post, added once however often the task
     comes back to the stage. */
  if p_next = 'performance_review' then
    insert into public.ops_task_checklist_items (task_id, label, position, required)
    select p_task, x.label,
           coalesce((select max(c.position) from public.ops_task_checklist_items c
                      where c.task_id = p_task), 0) + x.n,
           true
      from (values (1, 'Reach and views checked'),
                   (2, 'Engagement checked (likes, comments, shares, saves)'),
                   (3, 'Comments checked for brand safety'),
                   (4, 'Leads or sales checked, where tracked'),
                   (5, 'Keep live or take down decided')) as x(n, label)
     where not exists (select 1 from public.ops_task_checklist_items c
                        where c.task_id = p_task and c.label = x.label);
  end if;

  /* A finished task is not being worked on, so every timer running on it
     stops with it, each filed as the stop it is. */
  if nxt.is_terminal then
    for ws in select * from public.ops_work_sessions
               where task_id = p_task and ended_at is null loop
      wmins := greatest(0, (extract(epoch from (now() - ws.started_at)) / 60)::integer);
      update public.ops_work_sessions set ended_at = now(), minutes = wmins where id = ws.id;
      perform public.ops_log(p_task, 'work_stopped', null,
        jsonb_build_object('session_id', ws.id, 'minutes', wmins),
        jsonb_build_object('note', 'Stopped when the task finished'));
    end loop;
  end if;

  perform public.ops_log(p_task, 'stage_changed',
    jsonb_build_object('stage_key', t.stage_key),
    jsonb_build_object('stage_key', p_next),
    (case when p_note is null then '{}'::jsonb else jsonb_build_object('note', p_note) end)
    || (case when skipping then jsonb_build_object('skip_reason', btrim(p_skip_reason)) else '{}'::jsonb end)
    || (case when going_back then jsonb_build_object('back', true) else '{}'::jsonb end)
    || (case when v_round is not null then jsonb_build_object('round', v_round) else '{}'::jsonb end));
  if p_next = 'delivered' then
    perform public.ops_log(p_task, 'delivered', null, null, '{}'::jsonb);
  end if;
  if nxt.is_terminal and p_next <> 'cancelled' then
    perform public.ops_log(p_task, 'completed', null, null, '{}'::jsonb);
  end if;
  if p_next = 'cancelled' then
    perform public.ops_log(p_task, 'cancelled', null, null,
      jsonb_build_object('reason', p_note));
  end if;
  return public.ops_task_json(p_task);
end $$;
grant execute on function public.ops_transition_task(uuid, text, integer, text, uuid, text) to authenticated;

-- END OF HELD TASKS RESUME WHERE THEY LEFT ---------------------------------

-- ===========================================================================
-- DUE DATE MOVES THROUGH ITS ASK — ops_change_due_date is closed to every
-- browser. 2026-10-18. Safe to run twice. Rollback at the foot. Mirrored
-- byte for byte in supabase/schema.sql under the same banner; tests/sql.js
-- compares the two.
--
-- WHAT CHANGED (review of 2026-10-18, item 2)
--   ops_change_due_date moves a date the moment it is called. It was still
--   executable by every signed-in account, so a task's assignee could move
--   its final due date straight through it and skip the creator's approval
--   that ops_request_due_change asks for. No page, edge function or cron job
--   calls it (checked in the repo on 2026-10-18); its callers are
--   ops_request_due_change (the creator's or an admin's own move, and the
--   team's first draft date) and ops_decide_due_change (an approved ask),
--   both security definer, which keep reaching it as its owner. It is
--   revoked from public, anon and authenticated.
--
-- ROLLBACK
--   grant execute on function public.ops_change_due_date(uuid, text, timestamptz, text, text, integer) to authenticated;
-- ===========================================================================

revoke all on function public.ops_change_due_date(uuid, text, timestamptz, text, text, integer) from public, anon, authenticated;

-- END OF DUE DATE MOVES THROUGH ITS ASK --------------------------------------

-- ===========================================================================
-- MY WORK REPORT KEEPS CLIENT SCOPE — ops_report reads only the tasks the
-- caller may see. 2026-10-18. Safe to run twice. Rollback at the foot.
-- Mirrored byte for byte in supabase/schema.sql under the same banner;
-- tests/ops.js compares the two.
--
-- WHAT CHANGED (review of 2026-10-18, item 3)
--   CLIENT SCOPE (2026-10-03) put ops_task_in_scope on ops_report's open
--   work. A later restatement dropped it, so a colleague on Own clients
--   only who holds My Work: Report (ops.reports) read every client's late
--   and open work on the Dashboard. Every task read in it now asks
--   ops_task_in_scope: the open work, the finished work, the stage spans
--   and the reviews reached (the clients a colleague holds, their own tasks
--   always; a group seeing all clients reads what it read before). The
--   definition is otherwise the one MY WORK REPORT READS ITS PERIOD stated.
--
-- ROLLBACK
--   Run ops_report as MY WORK REPORT READS ITS PERIOD stated it.
-- ===========================================================================

create or replace function public.ops_report(
  p_from timestamptz default (now() - interval '90 days'),
  p_to   timestamptz default now())
returns jsonb
language plpgsql security definer stable set search_path = public as $$
declare
  out jsonb;
begin
  if not public.ops_granted('ops.reports', 'view') then
    return jsonb_build_object('error', 'denied');
  end if;

  with
  /* Where client review begins in each workflow. The final due date is the
     day the work is owed AT that stage, so everything below that position is
     "has not reached the client yet". Read from `stage_group` and never from
     a stage key: the two seeded workflows name that stage differently. */
  floors as (
    select workflow_id, min(position) as at
      from public.ops_workflow_stages
     where stage_group = 'client_review'
     group by workflow_id
  ),
  /* Where a priority's deadline is met (2026-10-11): client review, else the
     workflow's first review (an everyday task's Review). */
  pfloors as (
    select workflow_id,
           coalesce(min(position) filter (where stage_group = 'client_review'),
                    min(position) filter (where stage_group = 'internal_review')) as at
      from public.ops_workflow_stages
     group by workflow_id
  ),
  live as (
    select t.*, s.label as stage_label, s.position as stage_position,
           s.stage_group, f.at as review_at,
           public.ops_priority_by(coalesce(t.priority_at, t.created_at), t.priority_level) as prio_by, pf.at as prio_at
      from public.ops_tasks t
      join public.ops_workflow_stages s
        on s.workflow_id = t.workflow_id and s.key = t.stage_key
      left join floors f on f.workflow_id = t.workflow_id
      left join pfloors pf on pf.workflow_id = t.workflow_id
     where t.completed_at is null and t.cancelled_at is null
       and t.archived_at is null
       /* Client scope: a colleague on Own clients only reads the work of
          the clients they hold, and their own tasks always (2026-10-18). */
       and public.ops_task_in_scope(t.id)
  ),

  /* 1. WHAT IS RUNNING, by the words on the screen. Grouped by the stage's
        own label rather than by its group, because "what is on shooting" is
        the question and Shooting is a label, not a group. */
  running as (
    select jsonb_agg(x order by x ->> 'position', x ->> 'label') as j from (
      select jsonb_build_object(
               'stage_key', stage_key, 'label', stage_label,
               'position', stage_position, 'stage_group', stage_group,
               'count', count(*)) as x
        from live
       group by stage_key, stage_label, stage_position, stage_group
    ) q
  ),

  /* 2. WHAT IS LATE. Past the commitment and still short of client review,
        or past a priority's deadline and short of its review (On hold and
        Blocked still count): whichever comes first (the user, 2026-10-11).
        The same rule the queue row draws, stated once more here because a
        report a page computes for itself is a second definition. */
  late_now as (
    select l.*,
           (l.current_final_due_at is not null and (l.current_final_due_at at time zone 'Asia/Kuala_Lumpur')::date < (now() at time zone 'Asia/Kuala_Lumpur')::date
            and (l.review_at is null or l.stage_position < l.review_at)) as due_late,
           (l.prio_by is not null and l.prio_by < now()
            and (l.prio_at is null or l.stage_position < l.prio_at or l.stage_group in ('kiv', 'blocked'))) as prio_late
      from live l
  ),
  late as (
    select jsonb_agg(x order by x ->> 'due_at') as j from (
      select jsonb_build_object(
               'task_id', l.id, 'task_no', l.task_no, 'title', l.title,
               'client', c.name, 'stage', l.stage_label,
               'due_at', case when l.prio_late and (not l.due_late or l.prio_by < l.current_final_due_at)
                              then l.prio_by else l.current_final_due_at end,
               'days_over', greatest(case when l.due_late then (now() at time zone 'Asia/Kuala_Lumpur')::date - (l.current_final_due_at at time zone 'Asia/Kuala_Lumpur')::date end,
                                     case when l.prio_late then floor(extract(epoch from (now() - l.prio_by)) / 86400)::int end),
               'over_minutes', case when l.prio_late then floor(extract(epoch from (now() - l.prio_by)) / 60)::int end,
               'owner', (select tm.name
                           from public.ops_task_assignees a
                           join public.team_members tm on tm.id = a.team_member_id
                          where a.task_id = l.id and a.responsibility = 'owner'
                            and a.ended_at is null
                          limit 1)) as x
        from late_now l
        left join public.clients c on c.id = l.client_id
       where l.due_late or l.prio_late
    ) q
  ),

  /* 3. HOW LONG EACH STAGE TAKES. A task enters a stage at the event that
        names it and leaves at the next event, or at its own ending, or now.
        Only spans that were ENTERED inside the period are counted, so the
        window means what it says and a task that sat in Editing since March
        does not land in every report for ever. */
  spans as (
    select e.task_id,
           e.to_value ->> 'stage_key' as stage_key,
           e.created_at as from_at,
           coalesce(
             lead(e.created_at) over (partition by e.task_id order by e.created_at),
             t.completed_at, t.cancelled_at, now()) as to_at
      from public.ops_task_events e
      join public.ops_tasks t on t.id = e.task_id
     where e.event_type in ('task_created', 'stage_changed')
       and e.to_value ->> 'stage_key' is not null
       and public.ops_task_in_scope(t.id)
       /* Only a span entered in the period is counted, and its end is the
          task's next event, never an earlier one: what came before the
          period is not read (2026-10-18). */
       and e.created_at >= p_from
  ),
  /* One row per span and no grouping: an earlier draft grouped by the span's
     own timestamps, which silently collapsed two tasks that entered the same
     stage in the same instant into one measurement. The label is looked up
     once per stage below instead of aggregated here. */
  span_mins as (
    select s.stage_key,
           extract(epoch from (s.to_at - s.from_at)) / 60 as mins
      from spans s
     where s.from_at >= p_from and s.from_at < p_to
       and s.to_at > s.from_at
  ),
  stage_time as (
    select jsonb_agg(x order by x ->> 'label') as j from (
      select jsonb_build_object(
               'stage_key', stage_key,
               'label', coalesce((select w.label from public.ops_workflow_stages w
                                   where w.key = sm.stage_key limit 1), stage_key),
               'n', count(*),
               'median_minutes', round(percentile_cont(0.5) within group (order by mins))::int,
               'p90_minutes', round(percentile_cont(0.9) within group (order by mins))::int) as x
        from span_mins sm
       group by stage_key
    ) q
  ),

  /* 4. WAS IT THERE ON TIME. Of the tasks that reached client review inside
        the period, how many got there on or before the date they were owed.
        Replanning is counted beside it and never folded into it: an extension
        that moves the date would otherwise erase the miss it was granted for,
        and a rate that cannot be missed is not a measurement. */
  reached as (
    select distinct on (e.task_id)
           e.task_id, e.created_at as at, t.current_final_due_at as due,
           public.ops_priority_by(coalesce(t.priority_at, t.created_at), t.priority_level) as prio_by,
           (t.original_final_due_at is distinct from t.current_final_due_at) as replanned
      from public.ops_task_events e
      join public.ops_tasks t on t.id = e.task_id
      join public.ops_workflow_stages w
        on w.workflow_id = t.workflow_id and w.key = e.to_value ->> 'stage_key'
     where e.event_type = 'stage_changed'
       and w.stage_group = 'client_review'
       and public.ops_task_in_scope(t.id)
       and e.created_at >= p_from and e.created_at < p_to
     order by e.task_id, e.created_at
  ),
  on_time as (
    select jsonb_build_object(
             'reached', count(*),
             'met', count(*) filter (where (due is null or at::date <= due::date) and (prio_by is null or at <= prio_by)),
             'missed', count(*) filter (where not ((due is null or at::date <= due::date) and (prio_by is null or at <= prio_by))),
             'replanned', count(*) filter (where replanned)) as j
      from reached
  ),

  /* 5. BY PERSON. The foundation of a KPI and not a KPI: what somebody
        finished in the window, how much of it was on time, and how long their
        work took end to end. No ranking and no score — a number a person can
        check is worth more than a league table nobody trusts. */
  done as (
    select t.id, t.created_at, coalesce(t.completed_at, t.delivered_at) as ended,
           t.current_final_due_at as due,
           public.ops_priority_by(coalesce(t.priority_at, t.created_at), t.priority_level) as prio_by,
           /* When a priority's deadline was met: the first move into its
              review or beyond (never On hold, Blocked or Cancelled). */
           (select min(e.created_at)
              from public.ops_task_events e
              join public.ops_workflow_stages w
                on w.workflow_id = t.workflow_id and w.key = e.to_value ->> 'stage_key'
              join pfloors pf on pf.workflow_id = t.workflow_id
             where e.task_id = t.id and e.event_type = 'stage_changed'
               and w.position >= pf.at and w.stage_group not in ('kiv', 'blocked', 'cancelled')) as met_at,
           (select a.team_member_id
              from public.ops_task_assignees a
             where a.task_id = t.id and a.responsibility = 'owner'
             order by a.ended_at nulls first, a.assigned_at desc
             limit 1) as owner_id
      from public.ops_tasks t
     where t.completed_at is not null
       and t.completed_at >= p_from and t.completed_at < p_to
       and public.ops_task_in_scope(t.id)
  ),
  by_person as (
    select jsonb_agg(x order by x ->> 'name') as j from (
      select jsonb_build_object(
               'team_member_id', d.owner_id,
               'name', coalesce(tm.name, 'Nobody'),
               'completed', count(*),
               'on_time', count(*) filter (where (d.due is null or d.ended::date <= d.due::date)
                                         and (d.prio_by is null or coalesce(d.met_at, d.ended) <= d.prio_by)),
               'median_cycle_minutes',
                 round(percentile_cont(0.5) within group (
                   order by extract(epoch from (d.ended - d.created_at)) / 60))::int) as x
        from done d
        left join public.team_members tm on tm.id = d.owner_id
       group by d.owner_id, tm.name
    ) q
  ),

  /* 6. WHO IS CARRYING THE OPEN WORK (2026-09-28). One row a Task Owner:
        the open tasks they hold, and how many of those are late by the rule
        in 2 above. The team's whole queue is `ops.all`, so it is answered
        only where that part is granted. */
  open_by_person as (
    select jsonb_agg(x order by (x ->> 'open')::int desc, x ->> 'name') as j from (
      select jsonb_build_object(
               'team_member_id', o.owner_id,
               'name', coalesce(tm.name, 'No task owner'),
               'open', count(*),
               'late', count(*) filter (where o.is_late)) as x
        from (select l.id,
                     (select a.team_member_id
                        from public.ops_task_assignees a
                       where a.task_id = l.id and a.responsibility = 'owner' and a.ended_at is null
                       limit 1) as owner_id,
                     (l.due_late or l.prio_late) as is_late
                from late_now l) o
        left join public.team_members tm on tm.id = o.owner_id
       where public.ops_granted('ops.all', 'view')
       group by o.owner_id, tm.name
    ) q
  )

  select jsonb_build_object(
           'from', p_from, 'to', p_to,
           'running',    coalesce((select j from running), '[]'::jsonb),
           'late',       coalesce((select j from late), '[]'::jsonb),
           'stage_time', coalesce((select j from stage_time), '[]'::jsonb),
           'on_time',    coalesce((select j from on_time), '{}'::jsonb),
           'by_person',  coalesce((select j from by_person), '[]'::jsonb),
           'open_by_person', case when public.ops_granted('ops.all', 'view')
                                  then coalesce((select j from open_by_person), '[]'::jsonb) end)
    into out;

  return out;
end $$;

grant execute on function public.ops_report(timestamptz, timestamptz) to authenticated;

-- END OF MY WORK REPORT KEEPS CLIENT SCOPE ----------------------------------

-- ===========================================================================
-- PRIORITY SET BY WHOEVER SET THE TASK — a task's priority is changed by
-- its creator, a group at My Work Manage or an admin. 2026-10-18. Safe to
-- run twice. Rollback at the foot. Mirrored byte for byte in
-- supabase/schema.sql under the same banner; tests/ops.js compares the two.
--
-- WHAT CHANGED (review of 2026-10-18, item 11)
--   A priority is a deadline from when it was set (trigger
--   ops_tasks_priority_at restamps priority_at on every change of level),
--   and ops_update_task let anybody at My Work Work change it, so the
--   person a deadline binds could reset it (Urgent, High, Urgent again
--   restarts its 24 hours) or drop it to Normal. Of the two ways offered
--   (remember the stamp a level held in the last 24 hours, or limit who
--   changes it), the second is chosen: it needs no history of levels, and
--   it also closes the drop to Normal. ops_update_task now refuses a change
--   of priority ('priority-not-yours') unless the caller created the task,
--   holds My Work at Manage, or is an admin. Its other details are
--   unchanged; the stamp is unchanged.
--
-- ROLLBACK
--   Run ops_update_task as TASK DETAILS EDITABLE stated it (the
--   previous last definition in schema.sql).
-- ===========================================================================

create or replace function public.ops_update_task(
  p_task uuid, p_payload jsonb, p_version integer default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m     public.team_members;
  t     public.ops_tasks;
  d     text;
  pr    integer;
  fm    text;
  ty    text;
  cx    text;
  es    integer;
  was   jsonb := '{}'::jsonb;
  now_  jsonb := '{}'::jsonb;
begin
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if not public.ops_may_see_task(p_task) then return jsonb_build_object('error', 'denied'); end if;
  if not public.allowed('ops', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into t from public.ops_tasks where id = p_task for update;
  if t.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if p_version is not null and p_version <> t.version then
    return jsonb_build_object('error', 'stale', 'task', public.ops_task_json(p_task));
  end if;
  d := t.description; pr := t.priority_level; fm := t.deliverable_type;
  ty := t.task_type; cx := t.complexity; es := t.estimate_minutes;
  if p_payload ? 'description' then
    d := nullif(btrim(coalesce(p_payload ->> 'description', '')), '');
    if length(coalesce(d, '')) > 4000 then return jsonb_build_object('error', 'too-long'); end if;
  end if;
  if p_payload ? 'priority_level' then
    pr := (p_payload ->> 'priority_level')::integer;
    if pr is null or pr < 1 or pr > 4 then return jsonb_build_object('error', 'bad-priority'); end if;
    /* A priority is a deadline from when it is set, so it is changed by
       whoever created the task, a group at My Work Manage or an admin,
       never by the person it binds (2026-10-18: Urgent, High, Urgent again
       had restarted its 24 hours). */
    if pr is distinct from t.priority_level and t.created_by is distinct from m.id
       and not public.allowed('ops', 'manage') then
      return jsonb_build_object('error', 'priority-not-yours');
    end if;
  end if;
  if p_payload ? 'deliverable_type' then
    fm := nullif(btrim(coalesce(p_payload ->> 'deliverable_type', '')), '');
    if fm is not null and fm !~ '^[a-z0-9_]{1,40}$' then return jsonb_build_object('error', 'bad-format'); end if;
  end if;
  if p_payload ? 'task_type' then
    ty := p_payload ->> 'task_type';
    if ty is null or ty not in ('engagement', 'adhoc', 'goodwill', 'special') then
      return jsonb_build_object('error', 'bad-type');
    end if;
  end if;
  if p_payload ? 'complexity' then
    cx := p_payload ->> 'complexity';
    if cx is null or cx not in ('simple', 'standard', 'complex') then
      return jsonb_build_object('error', 'bad-complexity');
    end if;
  end if;
  if p_payload ? 'estimate_minutes' then
    if jsonb_typeof(p_payload -> 'estimate_minutes') = 'null' then es := null;
    else
      es := (p_payload ->> 'estimate_minutes')::integer;
      if es < 0 or es > 10000 then return jsonb_build_object('error', 'bad-estimate'); end if;
    end if;
  end if;
  if d is distinct from t.description then
    was := was || jsonb_build_object('description', t.description); now_ := now_ || jsonb_build_object('description', d);
  end if;
  if pr is distinct from t.priority_level then
    was := was || jsonb_build_object('priority_level', t.priority_level); now_ := now_ || jsonb_build_object('priority_level', pr);
  end if;
  if fm is distinct from t.deliverable_type then
    was := was || jsonb_build_object('deliverable_type', t.deliverable_type); now_ := now_ || jsonb_build_object('deliverable_type', fm);
  end if;
  if ty is distinct from t.task_type then
    was := was || jsonb_build_object('task_type', t.task_type); now_ := now_ || jsonb_build_object('task_type', ty);
  end if;
  if cx is distinct from t.complexity then
    was := was || jsonb_build_object('complexity', t.complexity); now_ := now_ || jsonb_build_object('complexity', cx);
  end if;
  if es is distinct from t.estimate_minutes then
    was := was || jsonb_build_object('estimate_minutes', t.estimate_minutes); now_ := now_ || jsonb_build_object('estimate_minutes', es);
  end if;
  if now_ = '{}'::jsonb then return public.ops_task_json(p_task); end if;
  update public.ops_tasks set description = d, priority_level = pr, deliverable_type = fm,
         task_type = ty, complexity = cx, estimate_minutes = es,
         version = version + 1, updated_at = now()
   where id = p_task;
  perform public.ops_log(p_task, 'details_changed', was, now_, '{}'::jsonb);
  return public.ops_task_json(p_task);
end $$;
grant execute on function public.ops_update_task(uuid, jsonb, integer) to authenticated;

-- END OF PRIORITY SET BY WHOEVER SET THE TASK -------------------------------

-- ===========================================================================
-- SUPPLIERS, A SECTION OF THEIR OWN — Suppliers leave Documents for the rail,
-- and a supplier is named by its own form (2026-10-18)
-- ===========================================================================
-- WHY (the user, 2026-10-18: "own section"; on New supplier asking the
-- name: "i wont know the company name first lol, needs them to fill in")
--
-- WHAT IT CHANGES
--   * The section `suppliers` (View, Work, Manage) in place of the part
--     `register.suppliers`, and the granted part `suppliers.pay` in place of
--     `register.supplier_pay`. Every group keeps what it held: `suppliers`
--     takes the old part's level, else Documents' (which the part followed),
--     and `suppliers.pay` the old granted part's; the old keys are taken off.
--     `team_role_sync` copies each group's map onto its colleagues.
--   * Every supplier function asks the new keys; `register_may('supplier',
--     …)` answers `suppliers`, so a supplier's letters follow the section.
--   * `suppliers.name` may be empty until the supplier's own form names it:
--     New supplier asks the Supplier ID alone; Approve waits for a name; a
--     supplier with no name is named by its Supplier ID where one is filed,
--     and Delete takes the Supplier ID typed back.
--   * Payment terms take NET 14, and `supplier_number_ok` holds Office /
--     mobile to a Malaysian or Singapore number and Mobile / WhatsApp to a
--     mobile (the user, 2026-10-18); the BRN (12 digits), NRIC
--     (XXXXXX-XX-XXXX) and SST no. (AXX-XXXX-XXXXXXXX) rules stand.
--   * `rail_order_set()` knows `suppliers`, so Arrange sections can place it.
--   * `activity_section()` files `supplier.*` under Suppliers
--     (`activity.suppliers`, which follows the Activity record's level as
--     every tab does).
--
-- ORDER: this file, then the pages. A page served before it asks the old
-- keys, which then fall back to Documents' level: it keeps working for the
-- groups that hold Documents. `supplier_delete` holds a delete the Supabase
-- connector stops on: it is run in the SQL Editor.
-- Safe to run twice. Rollback: 2026-10-18-suppliers.sql's functions, and
-- each group's `suppliers` / `suppliers.pay` written back as
-- `register.suppliers` / `register.supplier_pay`.
-- ===========================================================================

alter table public.suppliers alter column name drop not null;

/* Each group's access to suppliers, carried across. An admin group holds
   everything already and is left as it is. */
update public.team_roles r
   set access = (r.access - 'register.suppliers' - 'register.supplier_pay')
     || jsonb_build_object('suppliers', coalesce(r.access ->> 'register.suppliers', r.access ->> 'register', 'none'))
     || case when r.access ? 'register.supplier_pay' then jsonb_build_object('suppliers.pay', r.access ->> 'register.supplier_pay') else '{}'::jsonb end
 where not r.is_admin and not (r.access ? 'suppliers');

create or replace function public.register_may(p_family text, p_level text)
returns boolean
language sql security definer stable set search_path = public as $$
  select case
    when p_family = 'hr'       then public.allowed('register.hr', p_level)
    when p_family = 'other'    then public.allowed('register.documents', p_level)
    when p_family = 'supplier' then public.allowed('suppliers', p_level)
    else public.allowed('register.documents', p_level) or public.allowed('clients.documents', p_level)
  end
$$;
grant execute on function public.register_may(text, text) to authenticated;

create or replace function public.suppliers_list()
returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if (public.ops_me()).id is null or not public.allowed('suppliers', 'view') then
    return jsonb_build_object('error', 'denied');
  end if;
  return jsonb_build_object('ok', true, 'rows', coalesce((
    select jsonb_agg(public.supplier_json(s, false) || jsonb_build_object('waiting', exists (
             select 1 from public.supplier_forms f
              where f.supplier_id = s.id and f.voided_at is null and f.submitted_at is not null and f.used_at is null))
           order by upper(s.code))
      from public.suppliers s), '[]'::jsonb));
end $$;
revoke all on function public.suppliers_list() from public, anon;
grant execute on function public.suppliers_list() to authenticated;

create or replace function public.supplier_get(p_id uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  s   public.suppliers;
  f   public.supplier_forms;
  pay boolean := public.ops_granted('suppliers.pay', 'view');
  work boolean := public.allowed('suppliers', 'work');
  a   jsonb;
begin
  if (public.ops_me()).id is null or not public.allowed('suppliers', 'view') then
    return jsonb_build_object('error', 'denied');
  end if;
  select * into s from public.suppliers x where x.id = p_id;
  if s.id is null then return jsonb_build_object('error', 'not-found'); end if;
  select * into f from public.supplier_forms x where x.supplier_id = p_id and x.voided_at is null
   order by x.created_at desc limit 1;
  a := f.answers;
  if a is not null and not pay then
    a := a - array['nric', 'payee_name', 'bank_name', 'bank_account', 'swift', 'bank_address'];
  end if;
  return jsonb_build_object('ok', true, 'pay', pay, 'supplier', public.supplier_json(s, pay),
    'form', case when f.id is null then null else jsonb_strip_nulls(jsonb_build_object(
      'id', f.id,
      'key', case when work and f.submitted_at is null and f.expires_at > now() then f.access_key end,
      'state', case when f.used_at is not null then 'used' when f.submitted_at is not null then 'submitted'
                    when f.expires_at <= now() then 'expired' else 'open' end,
      'created_at', f.created_at, 'expires_at', f.expires_at, 'submitted_at', f.submitted_at, 'used_at', f.used_at,
      'answers', case when f.submitted_at is not null then a end)) end);
end $$;
revoke all on function public.supplier_get(uuid) from public, anon;
grant execute on function public.supplier_get(uuid) to authenticated;

create or replace function public.supplier_link(p_id uuid, p_reset boolean default false)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me    public.team_members := public.ops_me();
  s     public.suppliers;
  f     public.supplier_forms;
  v_key text;
  v_days int;
begin
  if me.id is null or not public.allowed('suppliers', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into s from public.suppliers x where x.id = p_id;
  if s.id is null then return jsonb_build_object('error', 'not-found'); end if;
  select * into f from public.supplier_forms x
   where x.supplier_id = p_id and x.voided_at is null and x.submitted_at is null and x.expires_at > now()
   order by x.created_at desc limit 1;
  if f.id is not null and not coalesce(p_reset, false) then
    return jsonb_build_object('ok', true, 'id', f.id, 'key', f.access_key, 'expires_at', f.expires_at);
  end if;
  update public.supplier_forms x set voided_at = now()
   where x.supplier_id = p_id and x.voided_at is null and x.submitted_at is null;
  loop
    v_key := public.new_link_key();
    exit when not exists (select 1 from public.supplier_forms x where x.access_key = v_key);
  end loop;
  v_days := coalesce(public.app_setting('details_form_days', (now() at time zone 'Asia/Kuala_Lumpur')::date), 14)::int;
  insert into public.supplier_forms (supplier_id, access_key, created_by, expires_at)
  values (p_id, v_key, me.id, now() + make_interval(days => v_days))
  returning * into f;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'supplier.edited', coalesce(s.name, s.code),
          s.code || ' · ' || case when coalesce(p_reset, false) then 'Details form link reset' else 'Details form link created' end);
  return jsonb_build_object('ok', true, 'id', f.id, 'key', f.access_key, 'expires_at', f.expires_at);
end $$;
revoke all on function public.supplier_link(uuid, boolean) from public, anon;
grant execute on function public.supplier_link(uuid, boolean) to authenticated;

create or replace function public.supplier_create(p_code text, p_name text)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me     public.team_members := public.ops_me();
  v_code text := upper(regexp_replace(coalesce(p_code, ''), '\s+', '', 'g'));
  v_name text := nullif(btrim(regexp_replace(coalesce(p_name, ''), '\s+', ' ', 'g')), '');
  v_id   uuid;
  r      jsonb;
begin
  if me.id is null or not public.allowed('suppliers', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if v_code !~ '^[A-Z0-9]{2,12}$' then return jsonb_build_object('error', 'bad-code'); end if;
  if v_name is not null and (length(v_name) < 2 or length(v_name) > 160) then return jsonb_build_object('error', 'bad-name'); end if;
  if exists (select 1 from public.suppliers s where upper(s.code) = v_code) then
    return jsonb_build_object('error', 'code-taken', 'name', (select s.name from public.suppliers s where upper(s.code) = v_code));
  end if;
  insert into public.suppliers (code, name, created_by) values (v_code, v_name, me.id) returning id into v_id;
  insert into public.activity_log (actor, action, subject, detail) values (me.name, 'supplier.added', coalesce(v_name, v_code), v_code);
  r := public.supplier_link(v_id, false);
  return jsonb_build_object('ok', true, 'id', v_id, 'key', r->>'key', 'expires_at', r->'expires_at');
end $$;
revoke all on function public.supplier_create(text, text) from public, anon;
grant execute on function public.supplier_create(text, text) to authenticated;

create or replace function public.supplier_save(p_id uuid, p_values jsonb, p_form uuid default null)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me    public.team_members := public.ops_me();
  s     public.suppliers;
  pay   boolean := public.ops_granted('suppliers.pay', 'work');
  v     jsonb;
  v_code text := upper(regexp_replace(coalesce(p_values->>'code', ''), '\s+', '', 'g'));
  moved text[] := '{}';
  k     text;
  word  constant jsonb := '{"code":"Supplier ID","name":"Name","kind":"Type","brn":"BRN","tin":"TIN","sst_no":"SST no.",
    "phone":"Office / mobile","address":"Billing address","contact_name":"Legal name","designation":"Designation",
    "email":"Email","mobile":"Mobile / WhatsApp","payment_term":"Payment term","currency":"Currency",
    "finance_email":"Finance email","nric":"NRIC","payee_name":"Payee name","bank_name":"Bank",
    "bank_account":"Account number","swift":"SWIFT code","bank_address":"Bank address"}';
  secret constant text[] := array['nric', 'payee_name', 'bank_name', 'bank_account', 'swift', 'bank_address'];
  was   jsonb;
begin
  if me.id is null or not public.allowed('suppliers', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into s from public.suppliers x where x.id = p_id for update;
  if s.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if v_code !~ '^[A-Z0-9]{2,12}$' then return jsonb_build_object('error', 'bad-code'); end if;
  if exists (select 1 from public.suppliers x where upper(x.code) = v_code and x.id <> p_id) then
    return jsonb_build_object('error', 'code-taken', 'name', (select x.name from public.suppliers x where upper(x.code) = v_code));
  end if;
  v := public.supplier_values_check(coalesce(p_values, '{}'::jsonb), pay);
  if v ? 'error' then return v; end if;
  v := v || jsonb_build_object('code', v_code);
  was := to_jsonb(s);
  for k in select jsonb_object_keys(v) loop
    if (was->>k) is distinct from (v->>k) then
      moved := moved || case when k = any (secret) then (word->>k)
        else (word->>k) || ': ' || coalesce(was->>k, 'not set') || ' → ' || coalesce(v->>k, 'not set') end;
    end if;
  end loop;
  update public.suppliers x set
    code = v_code, name = v->>'name', kind = v->>'kind', brn = v->>'brn', tin = v->>'tin', sst_no = v->>'sst_no',
    phone = v->>'phone', address = v->>'address', contact_name = v->>'contact_name', designation = v->>'designation',
    email = v->>'email', mobile = v->>'mobile', payment_term = v->>'payment_term', currency = v->>'currency',
    finance_email = v->>'finance_email',
    nric = case when pay then v->>'nric' else x.nric end,
    payee_name = case when pay then v->>'payee_name' else x.payee_name end,
    bank_name = case when pay then v->>'bank_name' else x.bank_name end,
    bank_account = case when pay then v->>'bank_account' else x.bank_account end,
    swift = case when pay then v->>'swift' else x.swift end,
    bank_address = case when pay then v->>'bank_address' else x.bank_address end,
    updated_at = now()
   where x.id = p_id;
  if p_form is not null then
    update public.supplier_forms f set used_at = coalesce(f.used_at, now()), used_by = coalesce(f.used_by, me.id)
     where f.id = p_form and f.supplier_id = p_id and f.submitted_at is not null;
  end if;
  if array_length(moved, 1) is not null then
    insert into public.activity_log (actor, action, subject, detail)
    values (me.name, 'supplier.edited', v->>'name', v_code || ' · ' || array_to_string(moved, ' · ') ||
            case when p_form is not null then ' · from the details form' else '' end);
  end if;
  return jsonb_build_object('ok', true, 'supplier',
    public.supplier_json((select x from public.suppliers x where x.id = p_id), public.ops_granted('suppliers.pay', 'view')));
end $$;
revoke all on function public.supplier_save(uuid, jsonb, uuid) from public, anon;
grant execute on function public.supplier_save(uuid, jsonb, uuid) to authenticated;

create or replace function public.supplier_set_status(p_id uuid, p_status text)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  s  public.suppliers;
begin
  if me.id is null or not public.allowed('suppliers', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if p_status not in ('active', 'inactive') then return jsonb_build_object('error', 'bad-status'); end if;
  select * into s from public.suppliers x where x.id = p_id for update;
  if s.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if s.status = p_status then return jsonb_build_object('ok', true, 'status', s.status); end if;
  if p_status = 'active' and (s.name is null or s.kind is null or s.tin is null or s.address is null or s.email is null
      or s.payment_term is null or s.bank_account is null) then
    return jsonb_build_object('error', 'incomplete');
  end if;
  update public.suppliers x set status = p_status, updated_at = now(),
    approved_at = case when p_status = 'active' and x.approved_at is null then now() else x.approved_at end,
    approved_by = case when p_status = 'active' and x.approved_at is null then me.id else x.approved_by end
   where x.id = p_id;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, case when s.status = 'pending' then 'supplier.approved' else 'supplier.edited' end, coalesce(s.name, s.code),
          s.code || ' · ' || initcap(s.status) || ' → ' || initcap(p_status));
  return jsonb_build_object('ok', true, 'status', p_status);
end $$;
revoke all on function public.supplier_set_status(uuid, text) from public, anon;
grant execute on function public.supplier_set_status(uuid, text) to authenticated;

create or replace function public.supplier_form_read(p_key text)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  f public.supplier_forms;
  s public.suppliers;
begin
  if coalesce(p_key, '') !~ '^[a-z0-9]{8}$' then return jsonb_build_object('error', 'not_found'); end if;
  select * into f from public.supplier_forms x where x.access_key = p_key and x.voided_at is null;
  if f.id is null then return jsonb_build_object('error', 'not_found'); end if;
  if f.submitted_at is not null then return jsonb_build_object('error', 'submitted'); end if;
  if f.expires_at <= now() then return jsonb_build_object('error', 'expired'); end if;
  select * into s from public.suppliers x where x.id = f.supplier_id;
  return jsonb_build_object('ok', true, 'name', s.name, 'code', s.code, 'expires_at', f.expires_at);
end $$;
revoke all on function public.supplier_form_read(text) from public;
grant execute on function public.supplier_form_read(text) to anon, authenticated;

create or replace function public.supplier_form_submit(p_key text, p_answers jsonb)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  f public.supplier_forms;
  s public.suppliers;
  v jsonb;
begin
  if coalesce(p_key, '') !~ '^[a-z0-9]{8}$' then return jsonb_build_object('error', 'not_found'); end if;
  select * into f from public.supplier_forms x where x.access_key = p_key and x.voided_at is null for update;
  if f.id is null then return jsonb_build_object('error', 'not_found'); end if;
  if f.submitted_at is not null then return jsonb_build_object('error', 'submitted'); end if;
  if f.expires_at <= now() then return jsonb_build_object('error', 'expired'); end if;
  if coalesce(p_answers->>'authorise', '') <> 'true' then return jsonb_build_object('error', 'bad-authorise'); end if;
  v := public.supplier_values_check(coalesce(p_answers, '{}'::jsonb), true);
  if v ? 'error' then return v; end if;
  update public.supplier_forms x set submitted_at = now(), answers = jsonb_strip_nulls(v) where x.id = f.id;
  select * into s from public.suppliers x where x.id = f.supplier_id;
  insert into public.activity_log (actor, action, subject, detail)
  values (v->>'contact_name', 'supplier.edited', coalesce(s.name, v->>'name'), s.code || ' · Details received on the details form');
  insert into public.ops_notifications (team_member_id, kind, title, body, supplier_id, dedupe_key)
  select m.id, 'supplier.details', 'Supplier details received · ' || coalesce(s.name, v->>'name'),
         'From ' || (v->>'contact_name') || '. Review them on the supplier.',
         s.id, 'supplier.details:' || f.id || ':' || m.id
    from public.team_members m
   where m.active and not coalesce(m.system, false)
     and (m.is_admin or m.role = 'admin'
          or public.level_rank(m.access ->> 'suppliers') >= 2)
  on conflict (dedupe_key) do nothing;
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.supplier_form_submit(text, jsonb) from public;
grant execute on function public.supplier_form_submit(text, jsonb) to anon, authenticated;

create or replace function public.supplier_delete(p_id uuid, p_name text)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  s  public.suppliers;
begin
  if me.id is null or not public.allowed('suppliers', 'manage') then return jsonb_build_object('error', 'denied'); end if;
  select * into s from public.suppliers x where x.id = p_id for update;
  if s.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if lower(btrim(coalesce(p_name, ''))) <> lower(btrim(coalesce(s.name, s.code))) then return jsonb_build_object('error', 'bad-name'); end if;
  delete from public.suppliers x where x.id = p_id;
  insert into public.activity_log (actor, action, subject, detail) values (me.name, 'supplier.deleted', coalesce(s.name, s.code), s.code);
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.supplier_delete(uuid, text) from public, anon;
grant execute on function public.supplier_delete(uuid, text) to authenticated;

/* Suppliers may be placed in a colleague's own order of the rail. */
create or replace function public.rail_order_set(p_sections text[])
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members;
  v_list text[] := coalesce(p_sections, '{}');
  v_known constant text[] := array['work', 'clients', 'review', 'scripts', 'campaigns', 'reports', 'whatsapp',
    'register', 'suppliers', 'links', 'services', 'team', 'handbook'];
begin
  me := public.ops_me();
  if me.id is null then return jsonb_build_object('error', 'denied'); end if;
  if exists (select 1 from unnest(v_list) k where k is null or not (k = any(v_known)))
     or (select count(distinct k) from unnest(v_list) k) <> cardinality(v_list) then
    return jsonb_build_object('error', 'bad-order');
  end if;
  insert into public.rail_orders (member_id, sections, updated_at) values (me.id, v_list, now())
  on conflict (member_id) do update set sections = excluded.sections, updated_at = now();
  return jsonb_build_object('sections', to_jsonb(v_list));
end $$;
grant execute on function public.rail_order_set(text[]) to authenticated;

create or replace function public.activity_section(p_action text)
returns text
language sql immutable parallel safe as $$
  select case
    when action in ('campaign.bulk', 'campaign.closed', 'campaign.confirmed',
                    'campaign.created', 'campaign.dates', 'campaign.deleted', 'campaign.edited',
                    'campaign.file_added', 'campaign.file_deleted', 'campaign.file_hidden',
                    'campaign.file_shown', 'campaign.qc',
                    'campaign.invoice', 'campaign.invoice_file',
                    'campaign.invoice_removed', 'campaign.keyed', 'campaign.locked',
                    'campaign.opened', 'campaign.rate', 'campaign.rated',
                    'campaign.reinstated', 'campaign.replaced', 'campaign.results', 'campaign.review',
                    'campaign.stage', 'campaign.submitted', 'campaign.task_linked',
                    'campaign.task_unlinked', 'campaign.unbooked',
                    'campaign.unkeyed', 'campaign.whatsapp', 'campaign.withdrawn', 'creator.added',
                    'creator.code', 'creator.links', 'creator.links_restored',
                    'creator.links_self', 'creator.off', 'creator.on', 'creator.removed',
                    'creator.updated') then 'campaigns'
    when action in ('client.action_done', 'client.action_reopened', 'client.added',
                    'client.billing', 'client.brand', 'client.deleted', 'client.edited',
                    'client.quotation', 'client.review_on', 'client.service', 'client.service_changed',
                    'client.service_deleted', 'client.service_removed', 'client.service_restored', 'client.stage', 'client.touch',
                    'client.touch_deleted', 'client.touch_edited', 'client.touch_removed',
                    'client.touch_restored', 'contact.added', 'contact.deleted',
                    'contact.edited', 'contact.portal_invite', 'contact.portal_off',
                    'contact.portal_on', 'contact.primary', 'contact.removed',
                    'contact.restored',
                    'request.changed', 'request.raised',
                    'request.reinstated', 'request.replied', 'request.withdrawn',
                    'service.override') then 'clients'
    when action in ('wa.sent', 'wa.template') then 'whatsapp'
    when action in ('report.ai_drafted', 'report.ai_failed', 'report.audited', 'report.confirmed',
                    'report.created', 'report.deleted', 'report.published',
                    'report.reassigned', 'report.returned', 'report.revised', 'report.saved',
                    'report.submitted', 'report.unpublished') then 'reports'
    when action in ('qr.created', 'qr.restored', 'qr.revoked', 'shortlink.created',
                    'shortlink.deleted', 'shortlink.imported', 'shortlink.updated') then 'links'
    when action in ('ops.deleted', 'ops.month_deleted', 'ops.numbering') then 'ops'
    when action in ('document.deleted', 'document.issued', 'document.reissued',
                    'document.restored', 'document.signed', 'document.superseded',
                    'document.unsigned', 'document.verified', 'document.voided',
                    'register.added', 'register.edited') then 'register'
    when action in ('supplier.added', 'supplier.approved', 'supplier.deleted', 'supplier.edited') then 'suppliers'
    when action in ('client.drive', 'client.handles', 'client.profile',
                    'client.removed', 'drive.imported', 'link.reset', 'post.added',
                    'post.deleted', 'post.edited', 'reapproval.requested',
                    'review.approved', 'review.changes', 'review.removed',
                    'review.unconfirmed',
                    'set.created', 'set.deleted', 'set.month', 'set.published', 'set.renamed',
                    'set.task_linked', 'set.task_unlinked',
                    'set.withdrawn') then 'review'
    when action in ('script.approved', 'script.changes', 'script.created', 'script.deleted',
                    'script.link', 'script.saved', 'script.shared', 'script.shot',
                    'script.unshared') then 'scripts'
    when action in ('handbook.added', 'handbook.archived', 'handbook.deleted',
                    'handbook.edited', 'handbook.restored', 'handbook.version') then 'handbook'
    when action in ('service.added', 'service.changed', 'service.deleted',
                    'service.off', 'service.on', 'service.published') then 'services'
    when action in ('team.added', 'team.changed', 'team.edited', 'team.group_added',
                    'team.group_changed', 'team.group_removed', 'team.invited') then 'team'
    else 'other'
  end
  from (select p_action as action) t
$$;
grant execute on function public.activity_section(text) to authenticated;


-- Payment terms take NET 14 (the user, 2026-10-18), and a number is a
-- Malaysian or Singapore one: an office line or a mobile for Office /
-- mobile, a mobile alone for Mobile / WhatsApp, with or without its
-- country code.
alter table public.suppliers drop constraint if exists suppliers_payment_term_check;
alter table public.suppliers add constraint suppliers_payment_term_check
  check (payment_term in ('NET 7', 'NET 14', 'NET 30', 'NET 45', 'NET 60'));

create or replace function public.supplier_number_ok(p text, p_mobile boolean)
returns boolean
language plpgsql immutable set search_path = public as $$
declare
  d text := regexp_replace(coalesce(p, ''), '[^0-9]', '', 'g');
  sg text;
  my text;
begin
  if length(d) = 8 then sg := d;
  elsif length(d) = 10 and d ~ '^65' then sg := substr(d, 3);
  elsif d ~ '^0' then my := d;
  elsif d ~ '^60' then my := '0' || substr(d, 3);
  end if;
  if sg is not null then return sg ~ (case when p_mobile then '^[89][0-9]{7}$' else '^[689][0-9]{7}$' end); end if;
  if my is null then return false; end if;
  return my ~ '^01[0-9]{8,9}$' or (not p_mobile and my ~ '^0[3-9][0-9]{7,8}$');
end $$;
revoke all on function public.supplier_number_ok(text, boolean) from public, anon, authenticated;

create or replace function public.supplier_values_check(p jsonb, p_pay boolean)
returns jsonb
language plpgsql immutable set search_path = public as $$
declare
  o jsonb := '{}'::jsonb;
  v text;
  k text;
  kind text := nullif(btrim(coalesce(p->>'kind', '')), '');
  banks constant text[] := array['Maybank', 'CIMB', 'Hong Leong Bank', 'RHB', 'BSN', 'UOB', 'OCBC', 'AmBank',
    'Bank Islam', 'Public Bank', 'Alliance Bank', 'Standard Chartered Bank', 'Touch N Go Digital',
    '[SG] DBS/POSB', '[SG] OCBC', '[SG] UOB', '[SG] CIMB', '[SG] Maybank', '[SG] Bank of China'];
  mail constant text := '^[^@\s]+@[^@\s]+\.[^@\s]+$';
begin
  if kind is null or kind not in ('company', 'individual') then return jsonb_build_object('error', 'bad-kind'); end if;
  o := o || jsonb_build_object('kind', kind);
  v := btrim(regexp_replace(coalesce(p->>'name', ''), '\s+', ' ', 'g'));
  if length(v) < 2 or length(v) > 160 then return jsonb_build_object('error', 'bad-name'); end if;
  o := o || jsonb_build_object('name', v);
  v := regexp_replace(coalesce(p->>'brn', ''), '[^0-9]', '', 'g');
  if (kind = 'company' or v <> '') and v !~ '^[0-9]{12}$' then return jsonb_build_object('error', 'bad-brn'); end if;
  o := o || jsonb_build_object('brn', nullif(v, ''));
  v := upper(regexp_replace(coalesce(p->>'tin', ''), '\s+', '', 'g'));
  if v !~ '^[A-Z0-9]{5,20}$' then return jsonb_build_object('error', 'bad-tin'); end if;
  o := o || jsonb_build_object('tin', v);
  v := upper(regexp_replace(coalesce(p->>'sst_no', ''), '\s+', '', 'g'));
  if v <> '' and v !~ '^[A-Z][0-9]{2}-[0-9]{4}-[0-9]{8}$' then return jsonb_build_object('error', 'bad-sst_no'); end if;
  o := o || jsonb_build_object('sst_no', nullif(v, ''));
  foreach k in array array['phone', 'mobile'] loop
    if not public.supplier_number_ok(p->>k, k = 'mobile') then return jsonb_build_object('error', 'bad-' || k); end if;
    o := o || jsonb_build_object(k, btrim(p->>k));
  end loop;
  v := btrim(coalesce(p->>'address', ''));
  if length(v) < 10 or length(v) > 400 then return jsonb_build_object('error', 'bad-address'); end if;
  o := o || jsonb_build_object('address', v);
  foreach k in array array['contact_name', 'designation'] loop
    v := btrim(regexp_replace(coalesce(p->>k, ''), '\s+', ' ', 'g'));
    if length(v) < 2 or length(v) > 80 then return jsonb_build_object('error', 'bad-' || k); end if;
    o := o || jsonb_build_object(k, v);
  end loop;
  foreach k in array array['email', 'finance_email'] loop
    v := lower(btrim(coalesce(p->>k, '')));
    if v !~ mail or length(v) > 160 then return jsonb_build_object('error', 'bad-' || k); end if;
    o := o || jsonb_build_object(k, v);
  end loop;
  v := coalesce(p->>'payment_term', '');
  if v not in ('NET 7', 'NET 14', 'NET 30', 'NET 45', 'NET 60') then return jsonb_build_object('error', 'bad-payment_term'); end if;
  o := o || jsonb_build_object('payment_term', v);
  v := coalesce(nullif(p->>'currency', ''), 'MYR');
  if v not in ('MYR', 'SGD') then return jsonb_build_object('error', 'bad-currency'); end if;
  o := o || jsonb_build_object('currency', v);
  if not p_pay then return o; end if;
  v := regexp_replace(coalesce(p->>'nric', ''), '[^0-9]', '', 'g');
  if kind = 'individual' then
    if v !~ '^[0-9]{12}$' then return jsonb_build_object('error', 'bad-nric'); end if;
    o := o || jsonb_build_object('nric', substr(v, 1, 6) || '-' || substr(v, 7, 2) || '-' || substr(v, 9, 4));
  else
    o := o || jsonb_build_object('nric', null);
  end if;
  v := btrim(regexp_replace(coalesce(p->>'payee_name', ''), '\s+', ' ', 'g'));
  if length(v) < 2 or length(v) > 120 then return jsonb_build_object('error', 'bad-payee_name'); end if;
  o := o || jsonb_build_object('payee_name', v);
  v := coalesce(p->>'bank_name', '');
  if not (v = any (banks)) then return jsonb_build_object('error', 'bad-bank_name'); end if;
  o := o || jsonb_build_object('bank_name', v);
  v := regexp_replace(coalesce(p->>'bank_account', ''), '[\s-]', '', 'g');
  if v !~ '^[0-9]{6,20}$' then return jsonb_build_object('error', 'bad-bank_account'); end if;
  o := o || jsonb_build_object('bank_account', v);
  v := upper(regexp_replace(coalesce(p->>'swift', ''), '\s+', '', 'g'));
  if v <> '' and v !~ '^[A-Z]{6}[A-Z0-9]{2}([A-Z0-9]{3})?$' then return jsonb_build_object('error', 'bad-swift'); end if;
  o := o || jsonb_build_object('swift', nullif(v, ''));
  v := btrim(coalesce(p->>'bank_address', ''));
  if length(v) > 300 then return jsonb_build_object('error', 'bad-bank_address'); end if;
  o := o || jsonb_build_object('bank_address', nullif(v, ''));
  return o;
end $$;
revoke all on function public.supplier_values_check(jsonb, boolean) from public, anon, authenticated;

-- END OF SUPPLIERS, A SECTION OF THEIR OWN ---------------------------------

-- ===========================================================================
-- TASKS NEED MY WORK AT WORK — a task, a month or a reminder to add tasks
-- goes only to a colleague whose group holds My Work at Work or above.
-- 2026-10-18. Safe to run twice. Rollback at the foot. Mirrored byte for
-- byte in supabase/schema.sql under the same banner; tests/sql.js compares
-- the two.
--
-- WHAT CHANGED (review of 2026-10-18, item 12)
--   ops_takes_tasks let in any level above No Access, so a colleague at My
--   Work View could be given a task they cannot move, take or hand on (every
--   task write asks My Work at Work). It now asks Work or above (an admin
--   always). The triggers that call it (ops_task_assignees_takes_tasks,
--   ops_engagements_takes_tasks) and the noon reminder follow. Work already
--   held is left as it is: nobody at View held a live task on 2026-10-18.
--
-- ROLLBACK
--   Run ops_takes_tasks as A COLLEAGUE WITHOUT MY WORK TAKES NO TASKS stated
--   it (level_rank(...) > 0).
-- ===========================================================================

create or replace function public.ops_takes_tasks(p_member uuid)
returns boolean
language sql security definer stable set search_path = public as $$
  select exists (
    select 1 from public.team_members t
     where t.id = p_member and t.active
       and (coalesce(t.is_admin, false) or coalesce(t.role, '') = 'admin'
            or public.level_rank(t.access ->> 'ops') >= 2));
$$;
revoke all on function public.ops_takes_tasks(uuid) from public, anon, authenticated;

-- END OF TASKS NEED MY WORK AT WORK ------------------------------------------

-- ===========================================================================
-- ONE PRESS, ONE NOTICE — a step that hands a task on tells its new owner
-- once. 2026-10-18. Safe to run twice. Rollback at the foot. Mirrored byte
-- for byte in supabase/schema.sql under the same banner; tests/ops.js
-- compares the two.
--
-- WHAT CHANGED (review of 2026-10-18, item 13)
--   ops_transition_task with p_assignee files assignment_changed (the new
--   owner told "Handed to you by … at …") and then stage_changed, which told
--   the same person "Moved to … by …": two notices and two pushes for one
--   press. ops_log now leaves out the stage notice when, in the same
--   transaction, the task was handed to that owner (an assignment_changed
--   event marked handover, stamped with the same now()). A move with no
--   hand-off, and a hand-off with no move, are told as before.
--
-- ROLLBACK
--   Run ops_log as THE CONTENT MEETING ON GOOGLE MEET stated it (the
--   previous last definition in schema.sql).
-- ===========================================================================

create or replace function public.ops_log(
  p_task uuid, p_type text, p_from jsonb, p_to jsonb, p_detail jsonb default '{}'::jsonb)
returns void
language plpgsql security definer set search_path = public as $$
declare
  m      public.team_members;
  t      public.ops_tasks;
  owner  uuid;
  who    text;
  body   text;
  st     public.ops_workflow_stages;
begin
  m := public.ops_me();
  insert into public.ops_task_events (task_id, event_type, actor_id, actor_email,
                                      from_value, to_value, detail)
  values (p_task, p_type, m.id, m.email, p_from, p_to, coalesce(p_detail, '{}'::jsonb));

  select * into t from public.ops_tasks where id = p_task;
  if t.id is null then return; end if;
  who := coalesce(nullif(m.name, ''), m.email, 'Somebody');

  if p_type = 'assignment_changed' then
    owner := (p_to ->> 'owner_id')::uuid;
    if owner is not null and owner is distinct from m.id then
      perform public.ops_notify(owner, p_task, 'assigned',
        public.ops_serial(t.task_no) || ' · ' || public.ops_title(t),
        case when coalesce((p_detail ->> 'handover')::boolean, false)
             then 'Handed to you by ' || who || ' at ' ||
                  coalesce((public.ops_stage(t.workflow_id, p_detail ->> 'stage_key')).label, p_detail ->> 'stage_key') || '.'
             else 'Assigned to you by ' || who || '.' end,
        'assigned:' || p_task::text || ':' || owner::text || ':' || to_char(now(), 'YYYYMMDDHH24MI'));
    end if;
    return;
  end if;

  select team_member_id into owner from public.ops_task_assignees
   where task_id = p_task and responsibility = 'owner' and ended_at is null
   limit 1;
  if owner is null or owner = m.id then return; end if;

  if p_type = 'stage_changed' then
    /* One press, one notice (2026-10-18): a move that also handed the task
       on has already told its new owner, in the same transaction, with the
       stage it was handed at. */
    if exists (select 1 from public.ops_task_events e
                where e.task_id = p_task and e.event_type = 'assignment_changed'
                  and e.created_at = now()
                  and coalesce((e.detail ->> 'handover')::boolean, false)
                  and e.to_value ->> 'owner_id' = owner::text) then
      return;
    end if;
    st := public.ops_stage(t.workflow_id, p_to ->> 'stage_key');
    body := 'Moved to ' || coalesce(st.label, p_to ->> 'stage_key')
      || coalesce(', round ' || (p_detail ->> 'round'), '') || ' by ' || who || '.';
  elsif p_type = 'due_changed' then
    body := 'The ' || case when p_to ->> 'kind' = 'final' then 'final' else 'first draft' end
      || ' date moved to ' || to_char((p_to ->> 'value')::timestamptz, 'DD Mon YYYY')
      || ' by ' || who || '.';
  elsif p_type = 'blocked' then
    body := 'Marked blocked by ' || who || ': '
      || coalesce(p_detail ->> 'category', 'reason not given') || '.';
  elsif p_type = 'unblocked' then
    body := 'Unblocked by ' || who || '.';
  elsif p_type = 'revision_requested' then
    body := 'A revision was requested by ' || who || '.';
  elsif p_type = 'approval_recorded' then
    body := 'A review decision was recorded by ' || who || '.';
  elsif p_type = 'reopened' then
    body := 'Reopened by ' || who || '.';
  elsif p_type = 'cancelled' then
    body := 'Cancelled by ' || who || '.';
  elsif p_type = 'commented' then
    body := who || ' commented: ' ||
      case when length(coalesce(p_detail ->> 'note', '')) > 140
           then left(p_detail ->> 'note', 139) || '…' else coalesce(p_detail ->> 'note', '') end;
  else
    return;
  end if;

  perform public.ops_notify(owner, p_task, p_type,
    public.ops_serial(t.task_no) || ' · ' || public.ops_title(t), body,
    p_type || ':' || p_task::text || ':' || owner::text || ':' ||
      /* Two comments in one minute are two things said; the same change
         twice in a minute is one. */
      case when p_type = 'commented' then md5(body) else to_char(now(), 'YYYYMMDDHH24MI') end);
end $$;

-- END OF ONE PRESS, ONE NOTICE ----------------------------------------------


-- ===========================================================================
-- SUPPLIER EMAILS — a supplier is emailed from its record, by hand
-- (2026-10-18)
-- ===========================================================================
-- WHY (the user, 2026-10-18: "for the email yes use resend"; "dont automate
-- first, propose me the build and mockups"; then, on the mockups: "ok build
-- it", replies to ap@adspacestudios.com, delivery status now, and after
-- Approve "prompt to either send or not, also keep the manual send option")
--
-- WHAT IT ADDS
--   * `supplier_email_templates`: one subject and body a purpose (`approved`,
--     Supplier approved; `document`, a supplier's document with its PDF),
--     the team's words with {fields} the saved supplier fills; seeded once.
--     Read at Suppliers View (`supplier_email_templates_list`), written at
--     Suppliers Manage (`supplier_email_template_save`), filed
--     `supplier.edited` under Supplier emails.
--   * `supplier_emails`: every email sent, who to, by whom, its words as
--     sent and what Resend said of it (sending, sent, failed, unknown, then
--     delivered, opened, bounced, complained). Kept when the supplier is
--     deleted (the link set null).
--   * `supplier_email_prepare(p_supplier, p_purpose, p_document)` (Suppliers
--     Work): the supplier's email and finance email, each {field} from the
--     record as saved, the template filled, and an email of the same
--     purpose and document sent within `wa_repeat_hours` (Settings, Sent
--     again). `supplier_email_begin` files the send before it goes,
--     refusing `recent` unless asked again, and `supplier_email_done` closes
--     it; `supplier-mail` calls both as the colleague. Resend's word on a
--     sent email reaches `supplier_email_status`, the service role's alone.
--   * `supplier_emails_of(p_supplier)` (Suppliers View): the record's
--     Emails.
--
-- ORDER: this file, then `supplier-mail`, then the pages. A page served
-- before draws no Emails and no Send email. Safe to run twice. Rollback:
-- drop the eight functions and the two tables.
-- ===========================================================================

create table if not exists public.supplier_email_templates (
  purpose     text primary key check (purpose in ('approved', 'document')),
  subject     text not null,
  body        text not null,
  updated_at  timestamptz not null default now(),
  updated_by  uuid references public.team_members(id) on delete set null
);
alter table public.supplier_email_templates enable row level security;
revoke all on table public.supplier_email_templates from public, anon, authenticated;

insert into public.supplier_email_templates (purpose, subject, body)
select x.purpose, x.subject, x.body from (values
  ('approved', 'Supplier registration approved · ADspace',
   E'Dear {contact name},\n\nThank you for completing your supplier registration. {supplier name} is now an approved supplier of ADSPACE PLT under Supplier ID {supplier id}.\n\nPayment is made on {payment term} terms in {currency}.\n\nYours sincerely,\n{sender name}\nADSPACE PLT'),
  ('document', '{document title} {document reference} · ADspace',
   E'Dear {contact name},\n\nPlease find attached our {document title} {document reference} for {supplier name} (Supplier ID {supplier id}), dated {document date}.\n\nYours sincerely,\n{sender name}\nADSPACE PLT')
) as x (purpose, subject, body)
where not exists (select 1 from public.supplier_email_templates);

create table if not exists public.supplier_emails (
  id            uuid primary key default gen_random_uuid(),
  supplier_id   uuid references public.suppliers(id) on delete set null,
  document_id   uuid,
  purpose       text not null check (purpose in ('approved', 'document')),
  to_email      text not null,
  cc_email      text,
  subject       text not null,
  body          text not null,
  sent_by       uuid references public.team_members(id) on delete set null,
  created_at    timestamptz not null default now(),
  status        text not null default 'sending'
                check (status in ('sending', 'sent', 'failed', 'unknown', 'delivered', 'opened', 'bounced', 'complained')),
  provider_id   text,
  error         text,
  sent_at       timestamptz,
  delivered_at  timestamptz,
  opened_at     timestamptz,
  bounced_at    timestamptz
);
create index if not exists supplier_emails_supplier_idx on public.supplier_emails (supplier_id, created_at desc);
create unique index if not exists supplier_emails_provider_idx on public.supplier_emails (provider_id) where provider_id is not null;
alter table public.supplier_emails enable row level security;
revoke all on table public.supplier_emails from public, anon, authenticated;

/* Each {field} in a text, named in any case and spacing, takes its value; a
   field nothing answers stays as typed, where the person sees it. */
create or replace function public.supplier_email_fill(p_text text, p_values jsonb)
returns text
language plpgsql immutable set search_path = public as $$
declare
  t text := coalesce(p_text, '');
  k text;
begin
  for k in select jsonb_object_keys(coalesce(p_values, '{}'::jsonb)) loop
    if coalesce(p_values->>k, '') <> '' then
      t := regexp_replace(t, '\{\s*' || replace(k, ' ', '\s+') || '\s*\}',
                          replace(p_values->>k, E'\\', E'\\\\'), 'gi');
    end if;
  end loop;
  return t;
end $$;
revoke all on function public.supplier_email_fill(text, jsonb) from public, anon, authenticated;

create or replace function public.supplier_email_templates_list()
returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if (public.ops_me()).id is null or not public.allowed('suppliers', 'view') then
    return jsonb_build_object('error', 'denied');
  end if;
  return jsonb_build_object('ok', true, 'rows', coalesce((
    select jsonb_agg(jsonb_build_object('purpose', t.purpose, 'subject', t.subject, 'body', t.body,
             'updated_at', t.updated_at, 'updated_by', m.name) order by t.purpose)
      from public.supplier_email_templates t left join public.team_members m on m.id = t.updated_by), '[]'::jsonb));
end $$;
revoke all on function public.supplier_email_templates_list() from public, anon;
grant execute on function public.supplier_email_templates_list() to authenticated;

create or replace function public.supplier_email_template_save(p_purpose text, p_subject text, p_body text)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me  public.team_members := public.ops_me();
  t   public.supplier_email_templates;
  v_s text := btrim(regexp_replace(coalesce(p_subject, ''), '\s+', ' ', 'g'));
  v_b text := btrim(replace(coalesce(p_body, ''), E'\r', ''));
  moved text[] := '{}';
begin
  if me.id is null or not public.allowed('suppliers', 'manage') then return jsonb_build_object('error', 'denied'); end if;
  select * into t from public.supplier_email_templates x where x.purpose = p_purpose for update;
  if t.purpose is null then return jsonb_build_object('error', 'bad-purpose'); end if;
  if length(v_s) < 2 or length(v_s) > 200 then return jsonb_build_object('error', 'bad-subject'); end if;
  if length(v_b) < 2 or length(v_b) > 5000 then return jsonb_build_object('error', 'bad-body'); end if;
  if t.subject is distinct from v_s then moved := moved || ('Subject: ' || t.subject || ' → ' || v_s); end if;
  if t.body is distinct from v_b then moved := moved || 'Body'::text; end if;
  if array_length(moved, 1) is null then return jsonb_build_object('ok', true); end if;
  update public.supplier_email_templates x set subject = v_s, body = v_b, updated_at = now(), updated_by = me.id
   where x.purpose = p_purpose;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'supplier.edited', 'Supplier emails',
          case p_purpose when 'approved' then 'Supplier approved' else 'Document' end || ' · ' || array_to_string(moved, ' · '));
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.supplier_email_template_save(text, text, text) from public, anon;
grant execute on function public.supplier_email_template_save(text, text, text) to authenticated;

/* What one email is: the supplier, its document, each {field} from the
   record as saved, and the template filled. Asked by the page to draw the
   sheet and by supplier-mail again at the send, as the colleague. */
create or replace function public.supplier_email_prepare(p_supplier uuid, p_purpose text, p_document uuid default null)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  me    public.team_members := public.ops_me();
  s     public.suppliers;
  d     public.documents;
  t     public.supplier_email_templates;
  v     jsonb;
  hours numeric;
  r     public.supplier_emails;
begin
  if me.id is null or not public.allowed('suppliers', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into s from public.suppliers x where x.id = p_supplier;
  if s.id is null then return jsonb_build_object('error', 'not-found'); end if;
  select * into t from public.supplier_email_templates x where x.purpose = p_purpose;
  if t.purpose is null then return jsonb_build_object('error', 'bad-purpose'); end if;
  if coalesce(s.email, '') = '' then return jsonb_build_object('error', 'no-email'); end if;
  if p_purpose = 'approved' and s.status <> 'active' then return jsonb_build_object('error', 'not-active'); end if;
  if p_purpose = 'document' then
    select * into d from public.documents x where x.id = p_document and x.supplier_id = s.id;
    if d.id is null or d.voided_at is not null then return jsonb_build_object('error', 'bad-document'); end if;
  end if;
  v := jsonb_build_object(
    'supplier name', coalesce(s.name, s.code), 'supplier id', s.code,
    'contact name', coalesce(s.contact_name, ''), 'designation', coalesce(s.designation, ''),
    'payment term', coalesce(s.payment_term, ''),
    'currency', case s.currency when 'SGD' then 'SGD' else 'MYR' end,
    'document title', coalesce(d.kind, ''), 'document reference', coalesce(d.serial, ''),
    'document date', case when d.issued_at is null then ''
      else to_char(d.issued_at at time zone 'Asia/Kuala_Lumpur', 'FMDD FMMonth YYYY') end,
    'sender name', coalesce(me.name, ''));
  hours := coalesce(public.app_setting('wa_repeat_hours', (now() at time zone 'Asia/Kuala_Lumpur')::date), 24);
  if hours > 0 then
    select * into r from public.supplier_emails x
     where x.supplier_id = s.id and x.purpose = p_purpose and x.document_id is not distinct from d.id
       and x.status not in ('failed') and x.created_at > now() - make_interval(secs => hours * 3600)
     order by x.created_at desc limit 1;
  end if;
  return jsonb_build_object('ok', true,
    'to', jsonb_build_object('name', coalesce(s.contact_name, coalesce(s.name, s.code)), 'email', s.email),
    'cc', nullif(coalesce(s.finance_email, ''), s.email),
    'values', v,
    'subject', public.supplier_email_fill(t.subject, v),
    'body', public.supplier_email_fill(t.body, v),
    'document', case when d.id is null then null else jsonb_build_object('id', d.id, 'serial', d.serial, 'kind', d.kind) end,
    'recent', case when r.id is null then null else jsonb_build_object('at', r.created_at, 'to', r.to_email,
      'by', (select m.name from public.team_members m where m.id = r.sent_by)) end);
end $$;
revoke all on function public.supplier_email_prepare(uuid, text, uuid) from public, anon;
grant execute on function public.supplier_email_prepare(uuid, text, uuid) to authenticated;

/* An email is filed before it goes, so a send whose answer is lost is still
   on the record (Not confirmed); the same email sent within the window is
   refused `recent` unless asked again. The words are the page's, every
   {field} filled from the record as saved. */
create or replace function public.supplier_email_begin(p_supplier uuid, p_purpose text, p_document uuid,
  p_cc boolean, p_subject text, p_body text, p_again boolean default false)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me  public.team_members := public.ops_me();
  p   jsonb := public.supplier_email_prepare(p_supplier, p_purpose, p_document);
  v_s text;
  v_b text;
  v_id uuid;
begin
  if p ? 'error' then return p; end if;
  if (p->'recent') is not null and jsonb_typeof(p->'recent') = 'object' and not coalesce(p_again, false) then
    return jsonb_build_object('error', 'recent', 'recent', p->'recent');
  end if;
  v_s := btrim(regexp_replace(public.supplier_email_fill(p_subject, p->'values'), '\s+', ' ', 'g'));
  v_b := btrim(replace(public.supplier_email_fill(p_body, p->'values'), E'\r', ''));
  if length(v_s) < 2 or length(v_s) > 200 then return jsonb_build_object('error', 'bad-subject'); end if;
  if length(v_b) < 2 or length(v_b) > 5000 then return jsonb_build_object('error', 'bad-body'); end if;
  insert into public.supplier_emails (supplier_id, document_id, purpose, to_email, cc_email, subject, body, sent_by)
  values (p_supplier, case when p_purpose = 'document' then p_document end, p_purpose, p->'to'->>'email',
          case when coalesce(p_cc, false) then p->>'cc' end, v_s, v_b, me.id)
  returning id into v_id;
  return jsonb_build_object('ok', true, 'id', v_id, 'to', p->'to', 'cc', case when coalesce(p_cc, false) then p->'cc' end,
    'subject', v_s, 'body', v_b, 'values', p->'values', 'document', p->'document');
end $$;
revoke all on function public.supplier_email_begin(uuid, text, uuid, boolean, text, text, boolean) from public, anon;
grant execute on function public.supplier_email_begin(uuid, text, uuid, boolean, text, text, boolean) to authenticated;

create or replace function public.supplier_email_done(p_id uuid, p_status text, p_provider text, p_error text)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  e  public.supplier_emails;
  s  public.suppliers;
begin
  if me.id is null then return jsonb_build_object('error', 'denied'); end if;
  if p_status not in ('sent', 'failed', 'unknown') then return jsonb_build_object('error', 'bad-status'); end if;
  select * into e from public.supplier_emails x where x.id = p_id and x.sent_by = me.id and x.status = 'sending' for update;
  if e.id is null then return jsonb_build_object('error', 'not-found'); end if;
  update public.supplier_emails x set status = p_status, provider_id = nullif(p_provider, ''),
    error = left(nullif(p_error, ''), 480), sent_at = case when p_status = 'sent' then now() end
   where x.id = p_id;
  select * into s from public.suppliers x where x.id = e.supplier_id;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'supplier.edited', coalesce(s.name, s.code, 'Supplier'),
          coalesce(s.code, '') || ' · ' ||
          case e.purpose when 'approved' then 'Supplier approved'
            else coalesce((select d.kind || ' ' || d.serial from public.documents d where d.id = e.document_id), 'Document') end ||
          case p_status when 'sent' then ' emailed to ' when 'unknown' then ' emailed, not confirmed, to ' else ' not emailed to ' end ||
          e.to_email || coalesce(', cc ' || e.cc_email, ''));
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.supplier_email_done(uuid, text, text, text) from public, anon;
grant execute on function public.supplier_email_done(uuid, text, text, text) to authenticated;

/* Resend's word on a sent email (supplier-mail, its webhook, the service
   role): delivered, opened, bounced or complained. A later word never
   steps back: an opened email is never delivered again, a bounce stays. */
create or replace function public.supplier_email_status(p_provider text, p_event text, p_at timestamptz)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  e    public.supplier_emails;
  rank constant jsonb := '{"sending":0,"unknown":1,"sent":1,"failed":1,"delivered":2,"opened":3,"complained":4,"bounced":4}';
  st   text := case p_event when 'email.delivered' then 'delivered' when 'email.opened' then 'opened'
                when 'email.clicked' then 'opened' when 'email.bounced' then 'bounced'
                when 'email.complained' then 'complained' when 'email.sent' then 'sent' end;
begin
  if st is null then return jsonb_build_object('ok', true, 'ignored', true); end if;
  select * into e from public.supplier_emails x where x.provider_id = p_provider for update;
  if e.id is null then return jsonb_build_object('error', 'not-found'); end if;
  update public.supplier_emails x set
    status = case when (rank->>st)::int > (rank->>x.status)::int then st else x.status end,
    sent_at = coalesce(x.sent_at, case when st <> 'bounced' then p_at end),
    delivered_at = case when st in ('delivered', 'opened') then coalesce(x.delivered_at, p_at) else x.delivered_at end,
    opened_at = case when st = 'opened' then coalesce(x.opened_at, p_at) else x.opened_at end,
    bounced_at = case when st = 'bounced' then coalesce(x.bounced_at, p_at) else x.bounced_at end
   where x.id = e.id;
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.supplier_email_status(text, text, timestamptz) from public, anon, authenticated;
grant execute on function public.supplier_email_status(text, text, timestamptz) to service_role;

create or replace function public.supplier_emails_of(p_supplier uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if (public.ops_me()).id is null or not public.allowed('suppliers', 'view') then
    return jsonb_build_object('error', 'denied');
  end if;
  return jsonb_build_object('ok', true, 'rows', coalesce((
    select jsonb_agg(jsonb_build_object('id', e.id, 'purpose', e.purpose, 'to', e.to_email, 'cc', e.cc_email,
             'subject', e.subject, 'status', e.status, 'error', e.error, 'created_at', e.created_at,
             'delivered_at', e.delivered_at, 'opened_at', e.opened_at, 'bounced_at', e.bounced_at,
             'by', m.name, 'document', d.serial) order by e.created_at desc)
      from public.supplier_emails e
      left join public.team_members m on m.id = e.sent_by
      left join public.documents d on d.id = e.document_id
     where e.supplier_id = p_supplier), '[]'::jsonb));
end $$;
revoke all on function public.supplier_emails_of(uuid) from public, anon;
grant execute on function public.supplier_emails_of(uuid) to authenticated;

-- END OF SUPPLIER EMAILS ----------------------------------------------------


-- ===========================================================================
-- PAST CLIENT LINKS ACT ON NOTHING — a past client's selection link saves,
-- confirms and decides nothing, as it already reads nothing, and its link
-- preview names nobody. 2026-10-18. Safe to run twice. Rollback at the foot.
-- Mirrored byte for byte in supabase/schema.sql under the same banner;
-- tests/confirmonce.js compares the two.
--
-- WHAT CHANGED (second audit, item 7)
--   1. save_selection, confirm_selection, confirm_selection_with and
--      review_draft answer `not-found` for a campaign whose client is Past,
--      before the passcode is asked, as get_campaign has since SELECTION
--      LINK CLOSES. Each is restated whole from PASSCODE ATTEMPTS with only
--      that check added.
--   2. share_link_preview('campaign') answers nothing for a Past client's
--      campaign, so a chat app's preview of /s/{key} names no client.
--
-- ROLLBACK
--   Run the four functions from PASSCODE ATTEMPTS again
--   (2026-10-18-passcode-attempts.sql), and share_link_preview from SHORT
--   LINKS RE-LETTERED (2026-10-15-short-links-relettered.sql).
-- ===========================================================================

create or replace function public.save_selection(
  p_token text, p_selected uuid[], p_backup uuid[], p_passcode text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  c campaigns%rowtype;
  n integer;
begin
  select * into c from campaigns where access_token = p_token;
  if not found then return jsonb_build_object('error', 'not-found'); end if;
  -- A past client's link acts on nothing, as it reads nothing (second
  -- audit, item 7): answered as a key nobody knows, before the passcode.
  if exists (select 1 from public.clients cl where cl.id = c.client_id and cl.stage = 'past') then
    return jsonb_build_object('error', 'not-found');
  end if;
  -- Five wrong passcodes lock the link for 15 minutes, answered as a key
  -- nobody knows (second audit, item 6).
  case public.link_passcode('selection', c.access_token, c.passcode, p_passcode)
    when 'locked' then return jsonb_build_object('error', 'not-found');
    when 'wrong' then return jsonb_build_object('error', 'passcode');
    else null;
  end case;

  n := coalesce(array_length(p_selected, 1), 0);
  /* Closed once the slots were full, until the team reopens it; backups
     alone may still be named where the team opened them. */
  if c.selection_closed_at is not null and not (coalesce(c.backups_open, false) and n = 0) then
    return jsonb_build_object('error', 'closed');
  end if;
  if n > c.slots then
    return jsonb_build_object('error', 'over-slots', 'slots', c.slots);
  end if;

  -- Anything already confirmed or further along is the team's to change.
  update campaign_options set state = 'option'
   where campaign_id = c.id and state in ('shortlisted', 'backup');

  if n > 0 then
    update campaign_options set state = 'shortlisted'
     where campaign_id = c.id and id = any(p_selected) and state = 'option';
  end if;
  -- Only where the team opened them: the page hides the control, and this is
  -- what makes that a fact rather than a courtesy.
  if coalesce(c.backups_open, false) and coalesce(array_length(p_backup, 1), 0) > 0 then
    update campaign_options set state = 'backup'
     where campaign_id = c.id and id = any(p_backup) and state = 'option';
  end if;

  return jsonb_build_object('ok', true, 'selected', n);
end $$;

revoke all on function public.save_selection(text, uuid[], uuid[], text) from public;
grant execute on function public.save_selection(text, uuid[], uuid[], text) to anon, authenticated;

create or replace function public.confirm_selection(
  p_token text, p_person text, p_passcode text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  c campaigns%rowtype;
begin
  select * into c from campaigns where access_token = p_token;
  if not found then return jsonb_build_object('error', 'not-found'); end if;
  -- A past client's link acts on nothing, as it reads nothing (second
  -- audit, item 7): answered as a key nobody knows, before the passcode.
  if exists (select 1 from public.clients cl where cl.id = c.client_id and cl.stage = 'past') then
    return jsonb_build_object('error', 'not-found');
  end if;
  -- Five wrong passcodes lock the link for 15 minutes, answered as a key
  -- nobody knows (second audit, item 6).
  case public.link_passcode('selection', c.access_token, c.passcode, p_passcode)
    when 'locked' then return jsonb_build_object('error', 'not-found');
    when 'wrong' then return jsonb_build_object('error', 'passcode');
    else null;
  end case;
  if coalesce(trim(p_person), '') = '' then
    return jsonb_build_object('error', 'name-required');
  end if;
  if c.selection_closed_at is not null and not coalesce(c.backups_open, false) then
    return jsonb_build_object('error', 'closed');
  end if;
  -- Nothing saved is nothing to confirm (a save refused under the page).
  if not exists (select 1 from campaign_options o
                  where o.campaign_id = c.id
                    and o.state = case when c.selection_closed_at is not null
                                       then 'backup' else 'shortlisted' end) then
    return jsonb_build_object('error', 'empty');
  end if;

  insert into campaign_confirmations (campaign_id, kind, person, source)
  values (c.id, 'client', trim(p_person), 'portal');

  insert into public.activity_log (actor, action, subject, detail)
  values (trim(p_person), 'campaign.confirmed', c.title,
          (select count(*)::text || ' creator' || case when count(*) = 1 then '' else 's' end
             from campaign_options
            where campaign_id = c.id and state = 'shortlisted') || ' confirmed');

  return jsonb_build_object('ok', true);
end $$;

revoke all on function public.confirm_selection(text, text, text) from public;
grant execute on function public.confirm_selection(text, text, text) to anon, authenticated;

create or replace function public.confirm_selection_with(
  p_token text, p_person text, p_passcode text, p_selected uuid[], p_backup uuid[],
  p_seen jsonb, p_idem text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  c      campaigns%rowtype;
  v_sel  uuid[];
  v_bak  uuid[];
  v_all  uuid[];
  v_idem text := left(nullif(btrim(coalesce(p_idem, '')), ''), 64);
  v_now  jsonb;
  v_snap jsonb;
  n      integer;
  v_booked integer;
begin
  select * into c from campaigns where access_token = p_token for update;
  if not found then return jsonb_build_object('error', 'not-found'); end if;
  -- A past client's link acts on nothing, as it reads nothing (second
  -- audit, item 7): answered as a key nobody knows, before the passcode.
  if exists (select 1 from public.clients cl where cl.id = c.client_id and cl.stage = 'past') then
    return jsonb_build_object('error', 'not-found');
  end if;
  -- Five wrong passcodes lock the link for 15 minutes, answered as a key
  -- nobody knows (second audit, item 6).
  case public.link_passcode('selection', c.access_token, c.passcode, p_passcode)
    when 'locked' then return jsonb_build_object('error', 'not-found');
    when 'wrong' then return jsonb_build_object('error', 'passcode');
    else null;
  end case;
  if coalesce(trim(p_person), '') = '' then
    return jsonb_build_object('error', 'name-required');
  end if;
  -- The same press again: the first answer stands and nothing is filed twice.
  if v_idem is not null and exists (select 1 from campaign_confirmations k
                                     where k.campaign_id = c.id and k.idem = v_idem) then
    return jsonb_build_object('ok', true, 'again', true);
  end if;

  v_sel := array(select distinct x from unnest(coalesce(p_selected, '{}'::uuid[])) x where x is not null);
  v_bak := case when coalesce(c.backups_open, false)
                then array(select distinct x from unnest(coalesce(p_backup, '{}'::uuid[])) x
                            where x is not null and not (x = any (v_sel)))
                else '{}'::uuid[] end;
  v_all := v_sel || v_bak;
  n := cardinality(v_sel);

  if c.selection_closed_at is not null and not (coalesce(c.backups_open, false) and n = 0) then
    return jsonb_build_object('error', 'closed');
  end if;
  if cardinality(v_all) = 0 then return jsonb_build_object('error', 'empty'); end if;
  -- The slots left are the slots less the creators already booked: a
  -- selection reopened for four of ten never books sixteen.
  v_booked := public.campaign_booked(c.id);
  if n > 0 and n > c.slots - v_booked then
    return jsonb_build_object('error', 'over-slots', 'slots', c.slots, 'booked', v_booked);
  end if;
  -- Every creator named is still on the campaign and open to choose.
  if (select count(*) from campaign_options o
       where o.id = any (v_all) and o.campaign_id = c.id
         and o.state in ('option', 'shortlisted', 'backup')) <> cardinality(v_all) then
    return jsonb_build_object('error', 'stale');
  end if;
  -- The prices the client read are the prices now.
  select jsonb_object_agg(o.id::text, o.rate) into v_now
    from campaign_options o where o.id = any (v_all);
  if exists (select 1 from campaign_options o
              where o.id = any (v_all)
                and coalesce(p_seen -> (o.id::text), 'null'::jsonb)
                    is distinct from coalesce(to_jsonb(o.rate), 'null'::jsonb)) then
    return jsonb_build_object('error', 'prices', 'rates', v_now);
  end if;

  update campaign_options set state = 'option'
   where campaign_id = c.id and state in ('shortlisted', 'backup');
  if n > 0 then
    update campaign_options set state = 'shortlisted'
     where campaign_id = c.id and id = any (v_sel) and state = 'option';
  end if;
  if cardinality(v_bak) > 0 then
    update campaign_options set state = 'backup'
     where campaign_id = c.id and id = any (v_bak) and state = 'option';
  end if;

  select jsonb_agg(jsonb_build_object('id', o.id, 'creator', cr.name, 'rate', o.rate, 'as', o.state)
                   order by o.position, o.added_at)
    into v_snap
    from campaign_options o join creators cr on cr.id = o.creator_id
   where o.id = any (v_all);
  insert into campaign_confirmations (campaign_id, kind, person, source, idem, snapshot)
  values (c.id, 'client', trim(p_person), 'portal', v_idem, coalesce(v_snap, '[]'::jsonb));

  insert into public.activity_log (actor, action, subject, detail)
  values (trim(p_person), 'campaign.confirmed', c.title,
          case when n > 0 then n::text || ' creator' || case when n = 1 then '' else 's' end || ' confirmed'
               else cardinality(v_bak)::text || ' backup' || case when cardinality(v_bak) = 1 then '' else 's' end || ' confirmed' end);

  return jsonb_build_object('ok', true, 'selected', n);
end $$;

revoke all on function public.confirm_selection_with(text, text, text, uuid[], uuid[], jsonb, text) from public;
grant execute on function public.confirm_selection_with(text, text, text, uuid[], uuid[], jsonb, text) to anon, authenticated;

create or replace function public.review_draft(
  p_token text, p_option uuid, p_decision text, p_note text default null,
  p_reviewer text default null, p_passcode text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  c campaigns%rowtype;
  o campaign_options%rowtype;
  n integer;
begin
  select * into c from campaigns where access_token = p_token;
  if not found then return jsonb_build_object('error', 'not-found'); end if;
  -- A past client's link acts on nothing, as it reads nothing (second
  -- audit, item 7): answered as a key nobody knows, before the passcode.
  if exists (select 1 from public.clients cl where cl.id = c.client_id and cl.stage = 'past') then
    return jsonb_build_object('error', 'not-found');
  end if;
  -- Five wrong passcodes lock the link for 15 minutes, answered as a key
  -- nobody knows (second audit, item 6).
  case public.link_passcode('selection', c.access_token, c.passcode, p_passcode)
    when 'locked' then return jsonb_build_object('error', 'not-found');
    when 'wrong' then return jsonb_build_object('error', 'passcode');
    else null;
  end case;
  if p_decision not in ('approved', 'changes') then
    return jsonb_build_object('error', 'bad-decision');
  end if;

  select * into o from campaign_options
   where id = p_option and campaign_id = c.id;
  if not found then return jsonb_build_object('error', 'not-found'); end if;

  -- Only a draft that is actually with the client can be ruled on.
  if o.state not in ('reviewing', 'changes') then
    return jsonb_build_object('error', 'not-reviewing');
  end if;
  /* A draft the team sent back to the creator is not with the client: the
     selection page shows it as Pending draft, so only a hand-made call
     could rule on it (audit B, 2026-10-17). */
  if o.state = 'changes' and coalesce(o.changes_by, 'client') = 'team' then
    return jsonb_build_object('error', 'not-reviewing');
  end if;

  n := coalesce(o.revision_round, 0);

  insert into option_reviews (option_id, round, decision, note, reviewer)
  values (p_option, greatest(n, 1), p_decision, nullif(trim(coalesce(p_note, '')), ''), p_reviewer);

  if p_decision = 'approved' then
    update campaign_options set state = 'scheduled' where id = p_option;
  else
    update campaign_options
       set state = 'changes', revision_round = greatest(n, 1) + 1,
           changes_by = 'client'
     where id = p_option;
  end if;

  /* The client's decision is the one event on a campaign that nobody on the
     team witnesses, and it was the only one the activity record never held:
     a draft went to Reviewing and appeared as Scheduled with nothing in
     between saying who had said yes. The reviewer's own name is the actor,
     because a person decided it. */
  insert into activity_log (actor, action, subject, detail)
  select coalesce(nullif(trim(coalesce(p_reviewer, '')), ''), 'Client'),
         'campaign.review', c.title,
         cr.name || ' · ' ||
         case when p_decision = 'approved' then 'Approved' else 'Changes requested' end ||
         coalesce(': ' || nullif(trim(coalesce(p_note, '')), ''), '')
    from creators cr where cr.id = o.creator_id;

  return jsonb_build_object('ok', true, 'decision', p_decision);
end $$;

revoke all on function public.review_draft(text, uuid, text, text, text, text) from public;
grant execute on function public.review_draft(text, uuid, text, text, text, text) to anon, authenticated;

create or replace function public.share_link_preview(p_kind text, p_key text)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(case p_kind
    when 'which' then (
      select case
        when exists (select 1 from public.campaigns k where k.access_token = p_key) then jsonb_build_object('kind', 'campaign')
        when exists (select 1 from public.clients c where c.script_key = p_key) then jsonb_build_object('kind', 'script')
      end
       where p_key ~ '^[A-Za-z0-9_-]{6,64}$')
    when 'script' then (
      select jsonb_strip_nulls(jsonb_build_object('brand', c.name))
        from public.clients c
       where p_key ~ '^[A-Za-z0-9_-]{6,64}$'
         and c.script_key = p_key and c.active
         and exists (select 1 from public.video_scripts s where s.client_id = c.id and s.status = 'shared')
       limit 1)
    when 'campaign' then (
      select jsonb_strip_nulls(jsonb_build_object('brand', c.name, 'title', nullif(btrim(k.title), '')))
        from public.campaigns k
        join public.clients c on c.id = k.client_id
       where p_key ~ '^[A-Za-z0-9_-]{6,64}$'
         and k.access_token = p_key
         and coalesce(k.passcode, '') = '' and k.state <> 'draft'
         and coalesce(c.stage, '') <> 'past'
       limit 1)
    when 'creator' then (
      select case when count(*) = 1 then jsonb_strip_nulls(jsonb_build_object('brand', min(c.name), 'title', nullif(btrim(min(k.title)), ''))) end
        from public.creators cr
        join public.campaign_options o on o.creator_id = cr.id
         and o.state in ('confirmed', 'pending_visit', 'pending_draft', 'submitted', 'reviewing', 'changes', 'scheduled', 'posted')
        join public.campaigns k on k.id = o.campaign_id
        join public.clients c on c.id = k.client_id
       where p_key ~ '^[A-Za-z0-9]{8}$'
         and cr.access_code = upper(p_key) and cr.active)
  end, '{}'::jsonb)
$$;
revoke all on function public.share_link_preview(text, text) from public;
grant execute on function public.share_link_preview(text, text) to anon, authenticated;

-- END OF PAST CLIENT LINKS ACT ON NOTHING -----------------------------------

-- ===========================================================================
-- EXPIRED ACCESS HANDS TASKS BACK — when a colleague's access expires, each
-- open task they hold goes back to whoever created it, else is left open to
-- take. 2026-10-18. Safe to run twice. Rollback at the foot. Mirrored byte
-- for byte in supabase/schema.sql under the same banner; tests/ops.js
-- compares the two.
--
-- WHAT CHANGED (review of 2026-10-18, item 19)
--   team_expire_access stood a colleague down and left their open tasks
--   with them: hidden from most of the team and movable only by an admin.
--   It now calls team_expiry_hand_back for each colleague it stands down.
--   Each open task (not finished, cancelled or archived) they hold as owner:
--     * goes back to its creator where the creator is another active
--       colleague who takes tasks (ops_takes_tasks), who is told (kind
--       assigned, "Handed back to you: … access ended.");
--     * else is left with no owner and open to take (open_at; the Take
--       flow of OPEN TO TAKE), and each active colleague at My Work Manage
--       or admin who takes tasks is told (kind tasks.unassigned).
--   Each move is filed on the task (assignment_changed, detail expired and
--   a note), so its history says why. Helpers and reviewers are left as
--   they are (trigger team_members_leaving ends them on a removal).
--
-- ROLLBACK
--   Run team_expire_access as TEAM ACCESS TIME stated it (the
--   previous last definition in schema.sql); team_expiry_hand_back may stay.
-- ===========================================================================

create or replace function public.team_expiry_hand_back(p_member uuid)
returns int language plpgsql security definer set search_path = public as $$
declare
  v_who public.team_members;
  t public.ops_tasks;
  v_to uuid;
  v_title text;
  n int := 0;
begin
  select * into v_who from public.team_members where id = p_member;
  if v_who.id is null then return 0; end if;
  for t in select k.* from public.ops_tasks k
             join public.ops_task_assignees a on a.task_id = k.id
            where a.team_member_id = p_member and a.responsibility = 'owner' and a.ended_at is null
              and k.completed_at is null and k.cancelled_at is null and k.archived_at is null
            order by k.task_no loop
    v_to := case when t.created_by is not null and t.created_by <> p_member
                       and public.ops_takes_tasks(t.created_by) then t.created_by end;
    v_title := public.ops_serial(t.task_no) || ' · ' || public.ops_title(t);
    update public.ops_task_assignees set ended_at = now()
     where task_id = t.id and responsibility = 'owner' and ended_at is null;
    if v_to is not null then
      insert into public.ops_task_assignees (task_id, team_member_id, responsibility, assigned_by)
      values (t.id, v_to, 'owner', null);
      update public.ops_tasks set version = version + 1, updated_at = now() where id = t.id;
      perform public.ops_notify(v_to, t.id, 'assigned', v_title,
        'Handed back to you: ' || v_who.name || '''s access ended.',
        'returned:' || t.id::text || ':' || v_to::text || ':' || to_char(now() at time zone 'Asia/Kuala_Lumpur', 'YYYYMMDDHH24MI'));
    else
      update public.ops_tasks set open_at = now(), open_by = null, version = version + 1, updated_at = now()
       where id = t.id;
      perform public.ops_notify(x.id, t.id, 'tasks.unassigned', v_title,
        v_who.name || '''s access ended. The task is open to take.',
        'unassigned:' || t.id::text || ':' || x.id::text || ':' || to_char(now() at time zone 'Asia/Kuala_Lumpur', 'YYYYMMDDHH24MI'))
        from public.team_members x
       where x.active and x.id <> p_member and not coalesce(x.system, false)
         and (coalesce(x.is_admin, false) or coalesce(x.role, '') = 'admin' or public.level_rank(x.access ->> 'ops') >= 3)
         and public.ops_takes_tasks(x.id);
    end if;
    insert into public.ops_task_events (task_id, event_type, actor_id, actor_email, from_value, to_value, detail)
    values (t.id, 'assignment_changed', null, null,
            jsonb_build_object('owner_id', p_member), jsonb_build_object('owner_id', v_to),
            jsonb_build_object('expired', true, 'note',
              case when v_to is not null then 'Access ended; handed back to whoever created it.'
                   else 'Access ended; open to take.' end));
    n := n + 1;
  end loop;
  return n;
end $$;
revoke all on function public.team_expiry_hand_back(uuid) from public, anon, authenticated;

create or replace function public.team_expire_access()
returns int language plpgsql security definer set search_path = public as $$
declare
  m public.team_members;
  n int := 0;
begin
  for m in select * from public.team_members t
            where t.active and t.access_until is not null
              and public.team_access_ends(t.access_until, t.access_until_time) <= now()
            order by t.access_until, t.access_until_time nulls last, t.name loop
    if (m.is_admin or m.role = 'admin') and not exists (
         select 1 from public.team_members o
          where o.id <> m.id and o.active and (o.is_admin or o.role = 'admin')
            and (o.access_until is null
                 or public.team_access_ends(o.access_until, o.access_until_time) > now())) then
      continue;
    end if;
    update public.team_members set active = false, expired_at = now() where id = m.id;
    perform public.team_expiry_hand_back(m.id);
    insert into public.activity_log (actor, action, subject, detail)
    values ('system', 'team.changed', m.name,
            case when m.access_until_time is null
                 then 'Access expired after ' || public.team_access_word(m.access_until, null)
                 else 'Access expired at ' || public.team_access_word(m.access_until, m.access_until_time) end);
    n := n + 1;
  end loop;
  return n;
end $$;
revoke all on function public.team_expire_access() from public, anon, authenticated;

-- END OF EXPIRED ACCESS HANDS TASKS BACK ------------------------------------

-- ===========================================================================
-- WORKING DAYS SKIP HOLIDAYS — a count of working days passes over weekends
-- and public holidays, and a client's request for changes falls due in
-- working days. 2026-10-18. Safe to run twice. Rollback at the foot.
-- Mirrored byte for byte in supabase/schema.sql under the same banner;
-- tests/ops.js compares the two.
--
-- WHAT CHANGED (review of 2026-10-18, item 20)
--   * ops_add_business_days skipped Saturday and Sunday (Malaysia time) but
--     counted a public holiday as a working day. It now passes over a day
--     on the Public holidays list too (public_holidays, Settings), so a
--     template's offsets land on working days. It reads a table, so it is
--     stable (no longer immutable) and security definer; it stays closed to
--     every browser.
--   * ops_tasks_revision_due put a task back to Revision (Client) due
--     today plus revision_due_days calendar days, so a Friday request fell
--     due on Saturday. It now counts revision_due_days working days from
--     today (Malaysia), through ops_add_business_days. The setting keeps its
--     key and its value; its words on the page read working days.
--
-- ROLLBACK
--   Run ops_add_business_days as THE OPERATIONS SYSTEM stated it, and
--   ops_tasks_revision_due as THREE DATES A POST stated it.
-- ===========================================================================

create or replace function public.ops_add_business_days(p_from timestamptz, p_days integer)
returns timestamptz
language plpgsql stable security definer set search_path = public as $$
declare
  d   timestamptz := p_from;
  n   integer := abs(coalesce(p_days, 0));
  dir integer := case when coalesce(p_days, 0) < 0 then -1 else 1 end;
begin
  if p_from is null then return null; end if;
  while n > 0 loop
    d := d + (dir || ' day')::interval;
    -- 0 is Sunday, 6 is Saturday in Postgres `dow`; a public holiday is no working day.
    if extract(dow from d at time zone 'Asia/Kuala_Lumpur') not in (0, 6)
       and not exists (select 1 from public.public_holidays h
                        where h.day = (d at time zone 'Asia/Kuala_Lumpur')::date) then
      n := n - 1;
    end if;
  end loop;
  return d;
end $$;
revoke all on function public.ops_add_business_days(timestamptz, integer) from public, anon, authenticated;

/* A client's request for changes sends the work back with a new due date:
   revision_due_days working days after today in Malaysia (weekends and
   public holidays passed over), stored as a typed date is (that day at
   00:00 UTC), and only where it is later than the due date the task holds. */
create or replace function public.ops_tasks_revision_due()
returns trigger
language plpgsql security definer set search_path = public as $$
declare v_day date; v_due timestamptz;
begin
  if new.stage_key <> 'revision_client' or old.stage_key is not distinct from new.stage_key then return null; end if;
  v_day := (now() at time zone 'Asia/Kuala_Lumpur')::date;
  v_due := ((public.ops_add_business_days(v_day::timestamp at time zone 'Asia/Kuala_Lumpur',
              coalesce(public.app_setting('revision_due_days', v_day), 1)::integer)
             at time zone 'Asia/Kuala_Lumpur')::date::timestamp) at time zone 'UTC';
  if new.current_final_due_at is not null and new.current_final_due_at >= v_due then return null; end if;
  update public.ops_tasks set current_final_due_at = v_due, updated_at = now() where id = new.id;
  perform public.ops_log(new.id, 'due_changed',
    jsonb_build_object('kind', 'final', 'value', new.current_final_due_at),
    jsonb_build_object('kind', 'final', 'value', v_due),
    jsonb_build_object('reason', 'client_request', 'note', 'The client asked for changes.', 'auto', true));
  return null;
end $$;
revoke all on function public.ops_tasks_revision_due() from public, anon, authenticated;

-- END OF WORKING DAYS SKIP HOLIDAYS ------------------------------------------

-- ===========================================================================
-- REVIEW SET COUNTS EVERY SET — review_set_counts answers every set it is
-- named, with no cap. 2026-10-18. Safe to run twice. Rollback at the foot.
-- Mirrored byte for byte in supabase/schema.sql under the same banner;
-- tests/sql.js compares the two.
--
-- WHAT CHANGED (review of 2026-10-18, item 9)
--   review_set_counts kept only the first 500 sets named (p_sets[1:500]),
--   and My Work's Waiting for you names every published set of the clients
--   a colleague holds, so past 500 sets the rest went uncounted without a
--   word. The cap is removed (the user, 2026-10-18). The work stays bounded
--   by what is named: the ids are read once each, each set's posts through
--   posts_batch_idx, and each post's standing decision is one index-ordered
--   read (reviews_post_round_idx, newest first, limit 1) in place of every
--   decision sorted. The answer is the one REVIEW SET COUNTS gave: a post's
--   decision is the newest that stands on its round on show (not undone, its
--   round, after any re-approval request). Still security invoker.
--
-- ROLLBACK
--   Run review_set_counts as REVIEW SET COUNTS stated it.
-- ===========================================================================

create or replace function public.review_set_counts(p_sets uuid[])
returns table (set_id uuid, n_posts integer, n_approved integer, n_changes integer,
               n_undecided integer, changes_since timestamptz)
language sql stable security invoker set search_path = public as $$
  with s as (
    select distinct x as id from unnest(p_sets) x where x is not null
  ), p as (
    select po.id, po.batch_id, coalesce(po.round, 1) as rnd, po.review_reset_at
      from s join public.posts po on po.batch_id = s.id
  ), d as (
    select p.id, p.batch_id, r.decision, r.created_at
      from p
      left join lateral (
        select r.decision, r.created_at
          from public.reviews r
         where r.post_id = p.id and r.undone_at is null and coalesce(r.round, 1) = p.rnd
           and (p.review_reset_at is null or r.created_at > p.review_reset_at)
         order by r.created_at desc
         limit 1) r on true
  )
  select d.batch_id,
         count(*)::integer,
         (count(*) filter (where d.decision = 'approved'))::integer,
         (count(*) filter (where d.decision = 'changes'))::integer,
         (count(*) filter (where d.decision is null))::integer,
         min(d.created_at) filter (where d.decision = 'changes')
    from d
   group by d.batch_id
$$;

revoke all on function public.review_set_counts(uuid[]) from public, anon;
grant execute on function public.review_set_counts(uuid[]) to authenticated;

-- END OF REVIEW SET COUNTS EVERY SET -----------------------------------------

-- ===========================================================================
-- FAILED JOBS NAMED — the admins' morning notice names each repeating task
-- that could not be made, counts the rules nobody can make, and reports a
-- failed morning check of its own. 2026-10-18. Safe to run twice. Rollback
-- at the foot. Mirrored byte for byte in supabase/schema.sql under the same
-- banner; tests/ops.js compares the two.
--
-- WHAT CHANGED (review of 2026-10-18, item 15)
--   * ops_recurring_daily passed in only the rules an active colleague
--     could make, so a rule whose creator and task owner had both left was
--     never made and never counted; and ops_generate_recurring skips a rule
--     whose task its colleague can no longer see. Both are now kept as the
--     rule's error (last_error, last_error_at) on the morning run, so the
--     notice counts them. An error from an earlier run that did not recur
--     is cleared once the run has passed it.
--   * jobs_watch names the failing rules (client, else Internal; the rule or
--     task's name; its task number), five at most then a count, and the
--     notice opens the first one's task. It reads back to its own last
--     successful run (at least 24 hours, at most seven days), so a morning
--     whose check failed is reported by the next, which says so. With no
--     active admin, the active colleagues at Team Full Access are told.
--   * The task card's Repeats line shows the rule's error (js/ops.js).
--
-- ROLLBACK
--   Run ops_recurring_daily as PIECES AND REPEATS stated it, and jobs_watch
--   as ONE REPEAT NEVER STOPS THE OTHERS stated it.
-- ===========================================================================

/* The morning run. Each rule is made as the colleague who set it, else its
   task's owner, with that colleague's own access. A rule neither of them can
   make, or whose task its colleague can no longer see, is kept as an error
   on the rule for the morning notice. Nobody calls this but the schedule. */
create or replace function public.ops_recurring_daily()
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  a   record;
  pp  text;
  out jsonb := '[]'::jsonb;
  was text := current_setting('request.jwt.claims', true);
begin
  update public.ops_recurring_rules r
     set last_error = 'No active colleague can make it: whoever set it and the owner of its task have left.',
         last_error_at = now()
   where r.active
     and not exists (
       select 1 from public.team_members tm
        where tm.active and tm.email is not null
          and tm.id in (r.created_by,
                        (select x.team_member_id from public.ops_task_assignees x
                          where x.task_id = r.source_task_id and x.responsibility = 'owner' and x.ended_at is null
                          limit 1)));
  for a in
    select actor.email, array_agg(r.id order by r.id) as rules
      from public.ops_recurring_rules r
      left join public.ops_tasks s on s.id = r.source_task_id
      cross join lateral (
        select tm.email from public.team_members tm
         where tm.active and tm.email is not null
           and tm.id in (r.created_by,
                         (select x.team_member_id from public.ops_task_assignees x
                           where x.task_id = s.id and x.responsibility = 'owner' and x.ended_at is null
                           limit 1))
         order by (tm.id = r.created_by) desc nulls last
         limit 1) actor
     where r.active
     group by actor.email
  loop
    perform set_config('request.jwt.claims',
      jsonb_build_object('email', a.email, 'role', 'authenticated')::text, true);
    update public.ops_recurring_rules r
       set last_error = 'Its colleague can no longer see the task it copies.', last_error_at = now()
     where r.id = any (a.rules) and r.source_task_id is not null
       and not public.ops_may_see_task(r.source_task_id);
    foreach pp in array public.ops_recurring_periods() loop
      out := out || jsonb_build_object('period', pp, 'rules', to_jsonb(a.rules),
                                       'result', public.ops_generate_recurring(pp, a.rules));
    end loop;
    update public.ops_recurring_rules r
       set last_error = null, last_error_at = null
     where r.id = any (a.rules) and r.last_error_at < now();
  end loop;
  perform set_config('request.jwt.claims', coalesce(was, ''), true);
  return out;
end $$;
revoke all on function public.ops_recurring_daily() from public, anon, authenticated;

create or replace function public.jobs_watch(p_now timestamptz default now())
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_jobs jsonb := '[]'::jsonb;
  v_runs integer := 0;
  v_self integer := 0;
  v_sweeps integer := 0;
  v_quiet boolean := false;
  v_words text;
  v_day text := to_char(p_now at time zone 'Asia/Kuala_Lumpur', 'YYYY-MM-DD');
  v_told integer := 0;
  v_rules integer := 0;
  v_names text;
  v_task uuid;
  v_since timestamptz := p_now - interval '24 hours';
  v_last timestamptz;
begin
  if to_regclass('cron.job_run_details') is not null then
    /* Back to this check's own last successful run, so a morning whose
       check failed is reported by the next: at least 24 hours, at most
       seven days. */
    select max(d.start_time) into v_last
      from cron.job_run_details d join cron.job j on j.jobid = d.jobid
     where j.jobname = 'jobs-watch' and d.status = 'succeeded' and d.start_time < p_now - interval '1 minute';
    v_since := greatest(p_now - interval '7 days', least(p_now - interval '24 hours', coalesce(v_last, p_now - interval '24 hours')));
    select coalesce(jsonb_agg(jsonb_build_object('job', x.name, 'failed', x.n) order by x.n desc, x.name), '[]'::jsonb),
           coalesce(sum(x.n), 0)::int
      into v_jobs, v_runs
      from (select coalesce(j.jobname, 'job ' || d.jobid) as name, count(*)::int as n
              from cron.job_run_details d
              left join cron.job j on j.jobid = d.jobid
             where d.status = 'failed' and d.start_time >= v_since and d.start_time < p_now
             group by 1) x;
    select coalesce(sum((e ->> 'failed')::int), 0)::int into v_self
      from jsonb_array_elements(v_jobs) e where e ->> 'job' = 'jobs-watch';
    /* The S3 report's job posts to its edge function and succeeds either
       way: a report that never arrived is a failure too. */
    v_quiet := exists (select 1 from cron.job j where j.jobname = 's3-sweep-daily' and j.active)
           and not exists (select 1 from public.s3_sweeps s where s.ran_at >= p_now - interval '26 hours' and s.ran_at < p_now);
  end if;
  select count(*)::int into v_sweeps from public.s3_sweeps s
   where s.mode = 'failed' and s.ran_at >= v_since and s.ran_at < p_now;

  /* Each repeat rule that could not make its task, named: its client (else
     Internal), the rule or its task, and the task number. */
  select count(*)::int,
         string_agg(w.label, '; ' order by w.at) filter (where w.n <= 5),
         (array_agg(w.task order by w.at) filter (where w.task is not null))[1]
    into v_rules, v_names, v_task
    from (select coalesce(c.name, 'Internal') || ': ' || coalesce(nullif(btrim(x.name), ''), public.ops_title(t), 'Repeating task')
                 || coalesce(' (' || public.ops_serial(t.task_no) || ')', '') as label,
                 x.last_error_at as at, t.id as task,
                 row_number() over (order by x.last_error_at) as n
            from public.ops_recurring_rules x
            left join public.ops_tasks t on t.id = x.source_task_id
            left join public.clients c on c.id = coalesce(case when t.id is not null then case when t.scope = 'client' then t.client_id end
                                                              else x.client_id end, x.client_id)
           where x.active and x.last_error_at >= v_since and x.last_error_at < p_now) w;

  if v_runs = 0 and v_sweeps = 0 and not v_quiet and v_rules = 0 then
    return jsonb_build_object('failed', 0, 'told', 0);
  end if;
  v_words := concat_ws('; ',
    case when v_self > 0 then 'the morning check of scheduled jobs failed ' || v_self ||
                              case when v_self = 1 then ' time' else ' times' end end,
    nullif((select string_agg((e ->> 'job') || ' failed ' || (e ->> 'failed') ||
                              case when (e ->> 'failed')::int = 1 then ' time' else ' times' end, '; ')
              from jsonb_array_elements(v_jobs) e where e ->> 'job' <> 'jobs-watch'), ''),
    case when v_sweeps > 0 then 'the S3 report was filed as failed' end,
    case when v_quiet then 'the S3 report did not arrive' end,
    case when v_rules > 0 then v_rules || case when v_rules = 1 then ' repeating task could' else ' repeating tasks could' end
                               || ' not be made: ' || v_names
                               || case when v_rules > 5 then ' and ' || (v_rules - 5) || ' more' else '' end end) || '.';
  insert into public.ops_notifications (team_member_id, task_id, kind, title, body, dedupe_key)
  select t.id, v_task, 'jobs.failed',
         case when v_since < p_now - interval '25 hours' then 'Scheduled jobs failed since the last check'
              else 'Scheduled jobs failed in the last 24 hours' end,
         v_words, 'jobs.failed.' || v_day || '.' || t.id
    from public.team_members t
   where t.active
     and (t.is_admin
          or (not exists (select 1 from public.team_members o where o.active and o.is_admin)
              and public.level_rank(t.access ->> 'team') >= 3))
  on conflict (dedupe_key) do nothing;
  get diagnostics v_told = row_count;
  return jsonb_build_object('failed', v_runs + v_sweeps + case when v_quiet then 1 else 0 end + v_rules,
    'jobs', v_jobs, 'self', v_self, 'since', v_since, 'sweeps', v_sweeps, 'sweep_missing', v_quiet,
    'repeats', v_rules, 'told', v_told);
end $$;
revoke all on function public.jobs_watch(timestamptz) from public, anon, authenticated;

-- END OF FAILED JOBS NAMED ---------------------------------------------------


-- ===========================================================================
-- SUPPLIERS LINKED TO CLIENTS — a supplier that is also one of our clients
-- names that client (2026-10-18)
-- ===========================================================================
-- WHY (the user, 2026-10-18: some suppliers are clients too; "u can leave
-- the supplier and client id separate"): the two records keep their own
-- IDs and are linked, each opening the other.
--
-- WHAT IT ADDS
--   * `suppliers.client_id` (the client it is, set null if the client goes).
--   * `supplier_client_set(p_id, p_client)` (Suppliers Work; a client needs
--     Clients View and the client in the caller's scope; null unlinks):
--     filed `supplier.edited` from and to.
--   * `supplier_get` answers `client` (its id, code and name where the
--     caller reads Clients and the client is in scope; `hidden` otherwise)
--     and, while none is linked and the caller may link one, `match`: the
--     clients whose BRN, digits alone, is the supplier's. The BRN itself is
--     never sent.
--   * `client_suppliers(p_client)` (Suppliers View, the client in scope):
--     the suppliers linked to a client, for its record.
--
-- ORDER: this file, then the pages. A page served before draws no link.
-- Safe to run twice. Rollback: drop `supplier_client_set`,
-- `client_suppliers`, put back `supplier_get` from SUPPLIERS, A SECTION OF
-- THEIR OWN, then drop `suppliers.client_id`.
-- ===========================================================================

alter table public.suppliers add column if not exists client_id uuid references public.clients(id) on delete set null;
create index if not exists suppliers_client_idx on public.suppliers (client_id) where client_id is not null;

create or replace function public.supplier_get(p_id uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  s   public.suppliers;
  f   public.supplier_forms;
  pay boolean := public.ops_granted('suppliers.pay', 'view');
  work boolean := public.allowed('suppliers', 'work');
  cv  boolean := public.allowed('clients', 'view');
  a   jsonb;
  cl  jsonb;
  mt  jsonb;
begin
  if (public.ops_me()).id is null or not public.allowed('suppliers', 'view') then
    return jsonb_build_object('error', 'denied');
  end if;
  select * into s from public.suppliers x where x.id = p_id;
  if s.id is null then return jsonb_build_object('error', 'not-found'); end if;
  select * into f from public.supplier_forms x where x.supplier_id = p_id and x.voided_at is null
   order by x.created_at desc limit 1;
  a := f.answers;
  if a is not null and not pay then
    a := a - array['nric', 'payee_name', 'bank_name', 'bank_account', 'swift', 'bank_address'];
  end if;
  if s.client_id is not null then
    select case when cv and public.client_seen(c.id, 'view')
                then jsonb_build_object('id', c.id, 'slug', c.slug, 'code', c.client_code, 'name', c.name)
                else jsonb_build_object('hidden', true) end
      into cl from public.clients c where c.id = s.client_id;
  elsif work and cv and s.brn is not null then
    select jsonb_agg(jsonb_build_object('id', c.id, 'code', c.client_code, 'name', c.name) order by c.client_code, c.name)
      into mt from public.clients c
     where regexp_replace(coalesce(c.company_no, ''), '[^0-9]', '', 'g') = s.brn
       and public.client_seen(c.id, 'view');
  end if;
  return jsonb_build_object('ok', true, 'pay', pay, 'supplier', public.supplier_json(s, pay),
    'client', cl, 'match', mt,
    'form', case when f.id is null then null else jsonb_strip_nulls(jsonb_build_object(
      'id', f.id,
      'key', case when work and f.submitted_at is null and f.expires_at > now() then f.access_key end,
      'state', case when f.used_at is not null then 'used' when f.submitted_at is not null then 'submitted'
                    when f.expires_at <= now() then 'expired' else 'open' end,
      'created_at', f.created_at, 'expires_at', f.expires_at, 'submitted_at', f.submitted_at, 'used_at', f.used_at,
      'answers', case when f.submitted_at is not null then a end)) end);
end $$;
revoke all on function public.supplier_get(uuid) from public, anon;
grant execute on function public.supplier_get(uuid) to authenticated;

create or replace function public.supplier_client_set(p_id uuid, p_client uuid)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me     public.team_members := public.ops_me();
  s      public.suppliers;
  was_w  text;
  now_w  text;
begin
  if me.id is null or not public.allowed('suppliers', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into s from public.suppliers x where x.id = p_id for update;
  if s.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if p_client is not null then
    if not public.allowed('clients', 'view') then return jsonb_build_object('error', 'denied'); end if;
    if not exists (select 1 from public.clients c where c.id = p_client) or not public.client_seen(p_client, 'view') then
      return jsonb_build_object('error', 'no-client');
    end if;
  end if;
  if s.client_id is not distinct from p_client then return jsonb_build_object('ok', true); end if;
  select coalesce(c.client_code || ' · ', '') || c.name into was_w from public.clients c where c.id = s.client_id;
  select coalesce(c.client_code || ' · ', '') || c.name into now_w from public.clients c where c.id = p_client;
  update public.suppliers x set client_id = p_client, updated_at = now() where x.id = p_id;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'supplier.edited', coalesce(s.name, s.code),
          s.code || ' · Client: ' || coalesce(was_w, 'not set') || ' → ' || coalesce(now_w, 'not set'));
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.supplier_client_set(uuid, uuid) from public, anon;
grant execute on function public.supplier_client_set(uuid, uuid) to authenticated;

create or replace function public.client_suppliers(p_client uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if (public.ops_me()).id is null or not public.allowed('suppliers', 'view')
     or not public.client_seen(p_client, 'view') then
    return jsonb_build_object('error', 'denied');
  end if;
  return jsonb_build_object('ok', true, 'rows', coalesce((
    select jsonb_agg(jsonb_build_object('id', s.id, 'code', s.code, 'name', s.name, 'status', s.status) order by upper(s.code))
      from public.suppliers s where s.client_id = p_client), '[]'::jsonb));
end $$;
revoke all on function public.client_suppliers(uuid) from public, anon;
grant execute on function public.client_suppliers(uuid) to authenticated;

-- END OF SUPPLIERS LINKED TO CLIENTS ----------------------------------------

-- ===========================================================================
-- DEPARTMENT SCORES ARE AN ADMIN'S — the quarter's department scores are
-- entered by an admin alone. 2026-10-18. Safe to run twice. Rollback at the
-- foot. Mirrored byte for byte in supabase/schema.sql under the same banner;
-- tests/perf.js compares the two.
--
-- WHAT CHANGED (review item 6)
--   NOBODY SCORES THEIR OWN DEPARTMENT kept a member from scoring their own
--   department, but the prize goes whole to the higher of two: a member of
--   Creative holding team.performance could still mark Marketing down and
--   win it. perf_dept_save now refuses `admin-only` unless the caller holds
--   Team: Performance admin (perf_is_admin(), team.perfadmin, an admin's
--   by itself). The own-department refusal stays for an admin who holds a
--   department. The page offers Department scores to that part alone.
--
-- ROLLBACK
--   Run the perf_dept_save definition of the NOBODY SCORES THEIR OWN
--   DEPARTMENT section of supabase/schema.sql again.
-- ===========================================================================

create or replace function public.perf_dept_save(p_token text, p_quarter date, p_department text, p_payload jsonb)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_err text; v_me public.team_members; v_q date; v_c jsonb; v_i integer; v_v jsonb; v_n numeric[] := '{}';
  v_max constant numeric[] := array[25, 25, 20, 15, 15]; v_was public.perf_dept_scores; v_crit boolean;
  v_changed jsonb := '[]'::jsonb; v_old numeric[];
begin
  v_err := public.perf_check(p_token, 'work');
  if v_err is not null then return jsonb_build_object('error', v_err); end if;
  /* The department prize is decided by an admin alone: with two
     departments, a member scoring the other one could swing it. */
  if not public.perf_is_admin() then return jsonb_build_object('error', 'admin-only'); end if;
  v_me := public.ops_me();
  v_q := date_trunc('quarter', p_quarter)::date;
  if v_q is null or v_q < date '2026-07-01' then return jsonb_build_object('error', 'before-first'); end if;
  if p_department is null or p_department not in ('creative', 'marketing') then
    return jsonb_build_object('error', 'bad-department');
  end if;
  /* Nobody scores their own department: its members share its prize. */
  if v_me.department is not distinct from p_department then
    return jsonb_build_object('error', 'own-department');
  end if;
  if exists (select 1 from public.perf_rewards where kind = 'quarter' and period = v_q) then
    return jsonb_build_object('error', 'confirmed');
  end if;
  v_c := p_payload -> 'criteria';
  if v_c is null or jsonb_typeof(v_c) <> 'array' then return jsonb_build_object('error', 'bad-payload'); end if;
  if jsonb_array_length(v_c) <> 5 then return jsonb_build_object('error', 'bad-payload'); end if;
  for v_i in 1..5 loop
    v_v := v_c -> (v_i - 1);
    if jsonb_typeof(v_v) <> 'number' then
      return jsonb_build_object('error', 'bad-score', 'index', v_i, 'max', v_max[v_i]);
    end if;
    if (v_v #>> '{}')::numeric not between 0 and v_max[v_i]
       or round((v_v #>> '{}')::numeric, 1) <> (v_v #>> '{}')::numeric then
      return jsonb_build_object('error', 'bad-score', 'index', v_i, 'max', v_max[v_i]);
    end if;
    v_n := v_n || (v_v #>> '{}')::numeric;
  end loop;
  v_crit := coalesce((p_payload ->> 'critical')::boolean, false);
  select * into v_was from public.perf_dept_scores where quarter = v_q and department = p_department for update;
  insert into public.perf_dept_scores (quarter, department, c1, c2, c3, c4, c5, critical, entered_by, updated_at)
  values (v_q, p_department, v_n[1], v_n[2], v_n[3], v_n[4], v_n[5], v_crit, v_me.id, now())
  on conflict (quarter, department) do update set
    c1 = excluded.c1, c2 = excluded.c2, c3 = excluded.c3, c4 = excluded.c4, c5 = excluded.c5,
    critical = excluded.critical, entered_by = excluded.entered_by, updated_at = now();
  v_old := array[v_was.c1, v_was.c2, v_was.c3, v_was.c4, v_was.c5];
  for v_i in 1..5 loop
    if v_old[v_i] is distinct from v_n[v_i] then
      v_changed := v_changed || jsonb_build_array(jsonb_build_object('key', 'c' || v_i, 'from', v_old[v_i], 'to', v_n[v_i]));
    end if;
  end loop;
  if v_was.critical is distinct from v_crit then
    v_changed := v_changed || jsonb_build_array(jsonb_build_object('key', 'critical', 'from', v_was.critical, 'to', v_crit));
  end if;
  if jsonb_array_length(v_changed) > 0 then
    perform public.perf_log(null, null, 'dept_scored',
      jsonb_build_object('key', v_q::text, 'department', p_department, 'changed', v_changed));
  end if;
  return public.perf_quarter(p_token, v_q);
end $$;

revoke all on function public.perf_dept_save(text, date, text, jsonb) from public, anon, authenticated;
grant execute on function public.perf_dept_save(text, date, text, jsonb) to authenticated;

-- END OF DEPARTMENT SCORES ARE AN ADMIN'S ----------------------------------

-- ===========================================================================
-- WHATSAPP QUEUE GIVES UP AFTER 48 HOURS — a queued message that has not
-- left in 48 hours is marked Failed, saying why, so the team can send it
-- again. 2026-10-18. Safe to run twice. Rollback at the foot. Mirrored byte
-- for byte in supabase/schema.sql under the same banner; tests/sql.js
-- compares the two.
--
-- WHAT CHANGED (review item 8)
--   WHATSAPP OUTAGE SPENDS NO TRY gives a request that never left its try
--   back, so a message caught by a long outage stayed Queued for ever: the
--   drain woke for it every five minutes, Sent recently counted it as sent
--   (so nobody was asked before sending it again), and privacy_retention,
--   which never clears a queued row, kept its number and words.
--   * wa_expire(p_now) marks every row still Queued 48 hours after it was
--     queued as Failed, with the error `expired: not sent within 48 hours`
--     (the WhatsApp section reads it in the team's words). A message Meta
--     accepted, or one at Sending or Not confirmed, is never touched.
--   * wa_claim runs it before it claims, and pg_cron `wa-expire` every
--     hour, so it holds whether or not the drain wakes. A failed row is
--     cleared by privacy_retention on the same twelve months as any other.
--     Not a page's to call.
--
-- ROLLBACK
--   select cron.unschedule(jobid) from cron.job where jobname = 'wa-expire';
--   then run wa_claim again from WHATSAPP QUEUE A FEW AT A TIME. wa_expire
--   is left in place, unused (a failed row is sent again by hand).
-- ===========================================================================

create or replace function public.wa_expire(p_now timestamptz default now())
returns integer
language plpgsql security definer set search_path = public as $$
declare v_n integer := 0;
begin
  update public.wa_outbox o
     set state = 'failed', error = 'expired: not sent within 48 hours'
   where o.state = 'queued' and o.created_at < p_now - interval '48 hours';
  get diagnostics v_n = row_count;
  return v_n;
end $$;
revoke all on function public.wa_expire(timestamptz) from public, anon, authenticated;

create or replace function public.wa_claim(p_limit integer default 1)
returns setof public.wa_outbox
language plpgsql security definer set search_path = public as $$
begin
  /* A message that has not left in 48 hours is failed, so it can be sent again. */
  perform public.wa_expire();
  /* A send cut off mid-way may have reached Meta: it is never sent again. */
  update public.wa_outbox o
     set state = 'unknown', error = 'unknown: the send was cut off before WhatsApp answered'
   where o.state = 'sending' and o.claimed_at < now() - interval '5 minutes';
  return query
  update public.wa_outbox o set state = 'sending', claimed_at = now(), tries = o.tries + 1
   where o.id in (select x.id from public.wa_outbox x
                   where x.state = 'queued' and x.tries < 3
                   order by x.created_at limit greatest(1, least(coalesce(p_limit, 1), 5))
                   for update skip locked)
  returning o.*;
end $$;
revoke all on function public.wa_claim(integer) from public, anon, authenticated;

/* Every hour, whether or not the drain wakes: the queue's own clock. */
do $$
begin
  if not exists (select 1 from pg_extension where extname = 'pg_cron') then
    raise notice 'pg_cron is not enabled: a queued message waits for the next drain to be failed.';
    return;
  end if;
  perform cron.unschedule(j.jobid) from cron.job j where j.jobname = 'wa-expire';
  perform cron.schedule('wa-expire', '23 * * * *', 'select public.wa_expire()');
end $$;

-- END OF WHATSAPP QUEUE GIVES UP AFTER 48 HOURS -----------------------------

-- ===========================================================================
-- PASSCODE LOCKS PER CALLER — wrong passcodes lock out the caller who typed
-- them, not the client: counted per link and caller address, with a much
-- higher count for the link as a whole that never shuts out a caller who
-- has already opened it. A lock is said as a lock, and the team sees and
-- clears it. 2026-10-18. Safe to run twice. Rollback at the foot. Mirrored
-- byte for byte in supabase/schema.sql under the same banner;
-- tests/confirmonce.js compares the two.
--
-- WHY (second audit, item 4)
--   PASSCODE ATTEMPTS counted wrong tries per link alone and looked at the
--   lock before the passcode, so anyone holding a link kept its client out
--   with five wrong guesses every 15 minutes, and the page called the lock
--   Link not recognised.
--
-- WHAT CHANGED
--   1. `request_ip()`: the caller's address as PostgREST passes it, the
--      first entry of X-Forwarded-For (Supabase's documented reading), else
--      CF-Connecting-IP, else X-Real-IP, else empty. media-pass and
--      sign-download forward their own caller's address the same way.
--   2. `link_tries` (kind, the link's key, the caller's address; wrong
--      tries, the last, locked until, the last right passcode; RLS on, no
--      policy, no grant): five wrong tries from one address within 15
--      minutes lock that address out of that link for 15 minutes.
--   3. `link_attempts` is the link's backstop: 100 wrong tries from every
--      address within an hour lock the link for an hour, for every caller
--      but one whose address gave the right passcode in the last 30 days.
--   4. `link_passcode(p_kind, p_token, p_stored, p_given)` keeps its answers
--      (`ok`, `wrong`, `locked`); asking without a passcode is still never
--      counted. A wrong try takes its rows with insert … on conflict do
--      nothing, then select … for update, so two at once count twice.
--   5. `link_locked(p_kind, p_token)` answers `{error: 'locked', minutes}`,
--      which get_review_feed, get_campaign, save_selection,
--      confirm_selection, confirm_selection_with and review_draft now return
--      in place of `not_found` / `not-found`; each is restated whole from
--      its last definition with only that answer changed. The pages say it
--      in words.
--   6. `link_lock_state(p_kind, p_id)` (Content Review settings or Creator
--      Campaigns: Campaigns at View, client scope) answers whether a
--      client's review link or a campaign's selection link is locked now,
--      until when and for how many addresses; `link_lock_clear(p_kind,
--      p_id)` (the same at Work) clears every lock and count on it, filed
--      `client.profile` / `campaign.edited` as the colleague.
--
-- ROLLBACK
--   Run PASSCODE ATTEMPTS (2026-10-18-passcode-attempts.sql) again for
--   link_passcode, get_review_feed and get_campaign, and PAST CLIENT LINKS
--   ACT ON NOTHING (2026-10-18-past-client-links-act-on-nothing.sql) for
--   the other four, then in the SQL Editor:
--   drop function if exists public.link_lock_clear(text, uuid);
--   drop function if exists public.link_lock_state(text, uuid);
--   drop function if exists public.link_locked(text, text);
--   drop function if exists public.request_ip();
--   drop table if exists public.link_tries;
-- ===========================================================================

create table if not exists public.link_tries (
  kind         text not null,
  token        text not null,
  ip           text not null,
  fails        integer not null default 0,
  last_at      timestamptz not null default now(),
  locked_until timestamptz,
  ok_at        timestamptz,
  primary key (kind, token, ip)
);
alter table public.link_tries enable row level security;
revoke all on public.link_tries from public, anon, authenticated;

create or replace function public.request_ip()
returns text
language sql stable set search_path = public as $$
  select left(coalesce(
    nullif(btrim(split_part(h ->> 'x-forwarded-for', ',', 1)), ''),
    nullif(btrim(h ->> 'cf-connecting-ip'), ''),
    nullif(btrim(h ->> 'x-real-ip'), ''),
    ''), 64)
  from (select coalesce(nullif(current_setting('request.headers', true), ''), '{}')::json as h) r
$$;
revoke all on function public.request_ip() from public, anon, authenticated;

create or replace function public.link_passcode(p_kind text, p_token text, p_stored text, p_given text)
returns text
language plpgsql security definer set search_path = public as $$
declare
  v_ip text := public.request_ip();
  a public.link_tries%rowtype;
  b public.link_attempts%rowtype;
  v_known boolean;
begin
  if coalesce(p_stored, '') = '' then return 'ok'; end if;
  select * into a from public.link_tries where kind = p_kind and token = p_token and ip = v_ip;
  select * into b from public.link_attempts where kind = p_kind and token = p_token;
  -- An address that opened the link in the last 30 days is never held by
  -- the link's backstop, only by its own count.
  v_known := a.ok_at is not null and a.ok_at > now() - interval '30 days';
  if a.locked_until > now() then return 'locked'; end if;
  if b.locked_until > now() and not v_known then return 'locked'; end if;
  -- Asked without one: the page learning that a passcode is needed.
  if coalesce(p_given, '') = '' then return 'wrong'; end if;
  if p_given = p_stored then
    if a.kind is null or a.fails > 0 or a.locked_until is not null or coalesce(a.ok_at < now() - interval '1 day', true) then
      insert into public.link_tries as t (kind, token, ip, fails, last_at, ok_at)
      values (p_kind, p_token, v_ip, 0, now(), now())
      on conflict (kind, token, ip) do update
         set fails = 0, locked_until = null, ok_at = now();
    end if;
    return 'ok';
  end if;

  insert into public.link_tries (kind, token, ip) values (p_kind, p_token, v_ip)
  on conflict (kind, token, ip) do nothing;
  select * into a from public.link_tries
   where kind = p_kind and token = p_token and ip = v_ip for update;
  if a.locked_until > now() then return 'locked'; end if;
  a.fails := case when a.locked_until is not null or a.last_at < now() - interval '15 minutes'
                  then 1 else a.fails + 1 end;
  a.locked_until := case when a.fails >= 5 then now() + interval '15 minutes' end;
  update public.link_tries set fails = a.fails, last_at = now(), locked_until = a.locked_until
   where kind = p_kind and token = p_token and ip = v_ip;

  insert into public.link_attempts (kind, token) values (p_kind, p_token)
  on conflict (kind, token) do nothing;
  select * into b from public.link_attempts
   where kind = p_kind and token = p_token for update;
  if b.locked_until is null or b.locked_until <= now() then
    b.fails := case when b.locked_until is not null or b.last_at < now() - interval '1 hour'
                    then 1 else b.fails + 1 end;
    b.locked_until := case when b.fails >= 100 then now() + interval '1 hour' end;
    update public.link_attempts set fails = b.fails, last_at = now(), locked_until = b.locked_until
     where kind = p_kind and token = p_token;
  end if;

  if a.locked_until is not null then return 'locked'; end if;
  if b.locked_until > now() and not v_known then return 'locked'; end if;
  return 'wrong';
end $$;
revoke all on function public.link_passcode(text, text, text, text) from public, anon, authenticated;

-- What a locked caller is told: a lock, and how long it has to run.
create or replace function public.link_locked(p_kind text, p_token text)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  a public.link_tries%rowtype;
  v_until timestamptz;
begin
  select * into a from public.link_tries
   where kind = p_kind and token = p_token and ip = public.request_ip();
  v_until := case when a.locked_until > now() then a.locked_until end;
  if not coalesce(a.ok_at > now() - interval '30 days', false) then
    v_until := greatest(v_until, (select l.locked_until from public.link_attempts l
                                   where l.kind = p_kind and l.token = p_token and l.locked_until > now()));
  end if;
  return jsonb_build_object('error', 'locked', 'minutes',
    greatest(1, ceil(extract(epoch from (coalesce(v_until, now() + interval '15 minutes') - now())) / 60))::int);
end $$;
revoke all on function public.link_locked(text, text) from public, anon, authenticated;

-- The link's key behind a client's review or a campaign's selection, asked
-- as the colleague: the section's level and the client's scope.
create or replace function public.link_lock_state(p_kind text, p_id uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_token text;
  v_until timestamptz;
  v_n     integer;
begin
  if p_kind = 'review' then
    if not public.allowed('review.settings', 'view') then return jsonb_build_object('error', 'denied'); end if;
    if not public.client_scope_ok('client', p_id, 'view') then return jsonb_build_object('error', 'client-scope'); end if;
    select c.access_token into v_token from public.clients c where c.id = p_id;
  elsif p_kind = 'selection' then
    if not public.allowed('campaigns.campaigns', 'view') then return jsonb_build_object('error', 'denied'); end if;
    if not public.client_scope_ok('campaign', p_id, 'view') then return jsonb_build_object('error', 'client-scope'); end if;
    select k.access_token into v_token from public.campaigns k where k.id = p_id;
  else
    return jsonb_build_object('error', 'bad-kind');
  end if;
  if v_token is null then return jsonb_build_object('error', 'not-found'); end if;
  select max(t.locked_until), count(*) into v_until, v_n
    from public.link_tries t
   where t.kind = p_kind and t.token = v_token and t.locked_until > now();
  return jsonb_build_object(
    'locked', v_n > 0 or exists (select 1 from public.link_attempts a
                                  where a.kind = p_kind and a.token = v_token and a.locked_until > now()),
    'all', exists (select 1 from public.link_attempts a
                    where a.kind = p_kind and a.token = v_token and a.locked_until > now()),
    'addresses', v_n,
    'until', greatest(v_until, (select a.locked_until from public.link_attempts a
                                 where a.kind = p_kind and a.token = v_token and a.locked_until > now())));
end $$;
revoke all on function public.link_lock_state(text, uuid) from public, anon;
grant execute on function public.link_lock_state(text, uuid) to authenticated;

create or replace function public.link_lock_clear(p_kind text, p_id uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me      public.team_members;
  v_token text;
  v_name  text;
  v_n     integer;
begin
  select * into me from public.ops_me();
  if me.id is null then return jsonb_build_object('error', 'denied'); end if;
  if p_kind = 'review' then
    if not public.allowed('review.settings', 'work') then return jsonb_build_object('error', 'denied'); end if;
    if not public.client_scope_ok('client', p_id, 'work') then return jsonb_build_object('error', 'client-scope'); end if;
    select c.access_token, c.name into v_token, v_name from public.clients c where c.id = p_id;
  elsif p_kind = 'selection' then
    if not public.allowed('campaigns.campaigns', 'work') then return jsonb_build_object('error', 'denied'); end if;
    if not public.client_scope_ok('campaign', p_id, 'work') then return jsonb_build_object('error', 'client-scope'); end if;
    select k.access_token, k.title into v_token, v_name from public.campaigns k where k.id = p_id;
  else
    return jsonb_build_object('error', 'bad-kind');
  end if;
  if v_token is null then return jsonb_build_object('error', 'not-found'); end if;
  update public.link_tries set fails = 0, locked_until = null
   where kind = p_kind and token = v_token and (fails > 0 or locked_until is not null);
  get diagnostics v_n = row_count;
  update public.link_attempts set fails = 0, locked_until = null
   where kind = p_kind and token = v_token;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, case when p_kind = 'review' then 'client.profile' else 'campaign.edited' end, v_name,
          case when p_kind = 'review' then 'Review link' else 'Selection link' end
          || ' unlocked · incorrect access codes cleared');
  return jsonb_build_object('ok', true, 'cleared', v_n);
end $$;
revoke all on function public.link_lock_clear(text, uuid) from public, anon;
grant execute on function public.link_lock_clear(text, uuid) to authenticated;

create or replace function public.get_review_feed(p_token text, p_passcode text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_client public.clients%rowtype;
begin
  select * into v_client
  from public.clients
  where access_token = p_token and active and not review_hidden;

  if not found then
    return jsonb_build_object('error', 'not_found');
  end if;

  -- Wrong passcodes lock out the caller who typed them, said as a lock
  -- (second audit, item 4); a passcode asked for names nobody (item 6).
  case public.link_passcode('review', v_client.access_token, v_client.passcode, p_passcode)
    when 'locked' then return public.link_locked('review', v_client.access_token);
    when 'wrong' then return jsonb_build_object('error', 'passcode_required');
    else null;
  end case;

  return jsonb_build_object(
    'client', jsonb_build_object(
      'name', v_client.name,
      'logo_url', v_client.logo_url,
      'handles', jsonb_build_object(
        'instagram', v_client.handle_ig,
        'facebook',  v_client.handle_fb,
        'tiktok',    v_client.handle_tiktok,
        'xhs',       v_client.handle_xhs)),
    'batches', coalesce((
      select jsonb_agg(batch order by batch->>'created_at' desc)
      from (
        select jsonb_build_object(
          'id',         b.id,
          'title',      b.title,
          'note',       b.note,
          'created_at', b.created_at,
          'posts', coalesce((
            select jsonb_agg(post order by (post->>'position')::int)
            from (
              select jsonb_build_object(
                'id',         p.id,
                'platform',   p.platform,
                'format',     p.format,
                'handle',     p.handle,
                'caption',    p.caption,
                'caption_zh', p.caption_zh,
                'title',      p.title,
                'media',      p.media,
                'cover_for',  p.cover_for,
                'position',   p.position,
                'round',      p.round,
                'version',    p.content_version,
                'reset_note', case
                  when p.review_reset_at is not null then p.review_reset_note end,
                /* The decision standing on the round on show: never one about
                   a round the client no longer sees, never one taken back. */
                'review',     (
                  select jsonb_build_object(
                    'decision',   r.decision,
                    'note',       r.note,
                    'reviewer',   case when r.source = 'team' then null else r.reviewer end,
                    'created_at', r.created_at,
                    'by_team',    (r.source = 'team'),
                    'suggested',  (r.suggested_caption is not null or r.suggested_caption_zh is not null),
                    /* The client's own edit, so Edit request reopens it. */
                    'suggested_caption',    r.suggested_caption,
                    'suggested_caption_zh', r.suggested_caption_zh)
                  from public.reviews r
                  where r.post_id = p.id and r.round = p.round and r.undone_at is null
                    and (p.review_reset_at is null or r.created_at > p.review_reset_at)
                  order by r.created_at desc
                  limit 1),
                /* What the client asked of the round before, so a revision
                   says what it answers. Words only: the earlier file and copy
                   stay with the team. */
                'asked',      case when p.round > 1 then (
                  select jsonb_build_object(
                    'note',       r.note,
                    'reviewer',   r.reviewer,
                    'created_at', r.created_at,
                    'suggested',  (r.suggested_caption is not null or r.suggested_caption_zh is not null))
                  from public.reviews r
                  where r.post_id = p.id and r.round = p.round - 1 and r.decision = 'changes'
                    and r.undone_at is null
                  order by r.created_at desc
                  limit 1) end
              ) as post
              from public.posts p
              where p.batch_id = b.id
            ) posts
          ), '[]'::jsonb)
        ) as batch
        from public.batches b
        where b.client_id = v_client.id and b.published
      ) batches
    ), '[]'::jsonb)
  );
end $$;

revoke all on function public.get_review_feed(text, text) from public;
grant execute on function public.get_review_feed(text, text) to anon, authenticated;

create or replace function public.get_campaign(p_token text, p_passcode text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  c campaigns%rowtype;
  cl clients%rowtype;
  billable boolean;
begin
  select * into c from campaigns where access_token = p_token;
  if not found then return jsonb_build_object('error', 'not-found'); end if;
  select * into cl from clients where id = c.client_id;
  -- A past client's links close (second audit, item 5): answered as a key
  -- nobody knows, so the page says the link is not recognised.
  if cl.stage = 'past' then return jsonb_build_object('error', 'not-found'); end if;

  -- An invoice belongs to an accepted booking. Until the client has chosen and
  -- the team has confirmed at least one creator, the number and the PDF stay
  -- off the client's page, and reverting the last confirmation takes them off
  -- it again. The gate is here rather than on the page so nothing the client
  -- can open carries what it should not show.
  select exists (
    select 1 from campaign_options o
     where o.campaign_id = c.id
       and o.state in ('confirmed', 'pending_visit', 'pending_draft', 'submitted',
                       'reviewing', 'changes', 'scheduled', 'posted', 'completed')
  ) into billable;

  -- Wrong passcodes lock out the caller who typed them, said as a lock
  -- (second audit, item 4); a passcode asked for names nobody (item 6).
  case public.link_passcode('selection', c.access_token, c.passcode, p_passcode)
    when 'locked' then return public.link_locked('selection', c.access_token);
    when 'wrong' then return jsonb_build_object('error', 'passcode');
    else null;
  end case;

  return jsonb_build_object(
    'campaign', jsonb_build_object(
      'title', c.title, 'title_zh', c.title_zh,
      'purpose', c.purpose, 'purpose_zh', c.purpose_zh, 'slots', c.slots,
      'backups_open', coalesce(c.backups_open, false),
      'selection_closed', c.selection_closed_at is not null,
      'deadline', c.deadline, 'state', c.state, 'deliverable', c.deliverable,
      'push_format', c.push_format, 'brief', c.brief, 'brief_zh', c.brief_zh,
      'invoice_no', case when billable then c.invoice_no end,
      'invoice_url', case when billable then c.invoice_url end,
      /* The client's last confirmation: who, when, and the creators it
         named, so a page opened again says the selection was confirmed and
         asks again only once the picks differ (2026-10-14). */
      'confirmed', (
        select jsonb_build_object('person', k.person, 'at', k.created_at,
                 'selected', coalesce((select jsonb_agg(x->>'id') from jsonb_array_elements(coalesce(k.snapshot, '[]'::jsonb)) x
                                        where x->>'as' = 'shortlisted'), '[]'::jsonb))
          from campaign_confirmations k
         where k.campaign_id = c.id and k.kind = 'client'
         order by k.created_at desc limit 1)),
    -- Currency and tax travel with the campaign, because the client's page
    -- prints both and must not assume Malaysia.
    'client', jsonb_build_object('name', cl.name, 'logo_url', cl.logo_url,
      'market', coalesce(cl.market, 'MY'), 'sst_applies', coalesce(cl.sst_applies, true)),
    /* A draft reaches the client when the team releases it, and not a moment
       before. `submitted` is the team's own step, so it is reported as
       `pending_draft`: the client is not asked to approve something they
       cannot open, and does not learn that a round exists. A `changes` the
       team raised is the same round going back to the creator, so it is
       withheld the same way; a `changes` the client raised is their own and
       is reported as it is. The mapping is here and not on the page, because
       what a client may not see is withheld by this function. */
    'options', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', o.id, 'name', cr.name,
        'rate', o.rate, 'platforms', o.platforms, 'state', s.shown,
        'is_replacement', o.is_replacement, 'added_at', o.added_at,
        -- Production. Present once a creator is locked; null before that, so
        -- the page can tell "not started" from "nothing to say".
        'visit_date', o.visit_date, 'visit_time', o.visit_time,
        'visit_location', o.visit_location, 'visit_pic', o.visit_pic,
        'visit_pic_phone', o.visit_pic_phone, 'tracking_no', o.tracking_no,
        'draft_url', case when s.released then o.draft_url end,
        /* The client's own rounds: a round the team sent back, or a request
           taken back, is not one the client made (2026-09-27). */
        'revision_round', (select count(*) from public.option_reviews r
                            where r.option_id = o.id and r.source = 'client'
                              and r.decision = 'changes' and r.undone_at is null)::int + 1,
        'planned_publish', o.planned_publish,
        /* What the creator uploaded, once it has been released: the round
           the team last released (`released_round`, stamped at release), so
           a creator's next round, uploaded after the client asked for
           changes, stays with the team until it is released in its turn
           (audit S5, 2026-10-10). A file hidden after the client's approval
           is never sent (audit S6). */
        'files', case when s.released then coalesce((
            select jsonb_agg(jsonb_build_object(
              'id', d.id, 'url', d.url, 'name', d.name, 'kind', d.kind,
              'bytes', d.bytes) order by d.uploaded_at)
            from campaign_deliverables d
            where d.option_id = o.id and d.removed_at is null and d.hidden_at is null
              and d.round = coalesce(o.released_round,
                            (select max(d2.round) from campaign_deliverables d2
                              where d2.option_id = o.id and d2.removed_at is null))
          ), '[]'::jsonb) else '[]'::jsonb end,
        -- The caption is part of what is being approved, so it travels with
        -- the files and is withheld with them.
        'caption', case when s.released then o.draft_caption end,
        'profiles', coalesce((
          select jsonb_agg(jsonb_build_object('platform', p.platform, 'url', p.url))
          from creator_profiles p where p.creator_id = cr.id), '[]'::jsonb),
        -- One row per platform posted on, so two placements stay two numbers.
        'posts', coalesce((
          select jsonb_agg(jsonb_build_object(
            'platform', pp.platform, 'post_url', pp.post_url,
            'published_at', pp.published_at, 'window_days', pp.window_days,
            'impressions', pp.impressions, 'engagements', pp.engagements,
            'views', pp.views, 'measured_at', pp.measured_at) order by pp.platform)
          from option_posts pp where pp.option_id = o.id), '[]'::jsonb),
        /* What was last decided, so the card can say who approved it and
           when rather than jumping to the next step with nothing to show for
           the decision. The client's own decisions, and an approval the team
           gave on the client's behalf (`by_team`, read "Proceeded by"); a
           team send-back stays withheld. Withheld with the draft it is about. */
        'review', case when s.released then (
            select jsonb_build_object('decision', r.decision, 'reviewer', r.reviewer,
                                      'note', case when r.source = 'client' then r.note end,
                                      'at', r.created_at, 'by_team', r.source = 'team')
            from option_reviews r where r.option_id = o.id
              and (r.source = 'client' or r.decision = 'approved') and r.undone_at is null
            order by r.created_at desc limit 1) end)
        order by o.position, o.added_at)
      from campaign_options o
      join creators cr on cr.id = o.creator_id
      cross join lateral (
        select sh.shown,
               sh.shown in ('reviewing', 'changes', 'scheduled', 'posted', 'completed')
                 as released
        from (select case
                       when o.state = 'submitted' then 'pending_draft'
                       when o.state = 'changes'
                            and coalesce(o.changes_by, 'client') = 'team' then 'pending_draft'
                       else o.state
                     end as shown) sh
      ) s
      where o.campaign_id = c.id and o.state <> 'replaced'), '[]'::jsonb)
  );
end $$;

revoke all on function public.get_campaign(text, text) from public;
grant execute on function public.get_campaign(text, text) to anon, authenticated;

create or replace function public.save_selection(
  p_token text, p_selected uuid[], p_backup uuid[], p_passcode text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  c campaigns%rowtype;
  n integer;
begin
  select * into c from campaigns where access_token = p_token;
  if not found then return jsonb_build_object('error', 'not-found'); end if;
  -- A past client's link acts on nothing, as it reads nothing (second
  -- audit, item 7): answered as a key nobody knows, before the passcode.
  if exists (select 1 from public.clients cl where cl.id = c.client_id and cl.stage = 'past') then
    return jsonb_build_object('error', 'not-found');
  end if;
  -- Wrong passcodes lock out the caller who typed them, said as a lock
  -- (second audit, item 4).
  case public.link_passcode('selection', c.access_token, c.passcode, p_passcode)
    when 'locked' then return public.link_locked('selection', c.access_token);
    when 'wrong' then return jsonb_build_object('error', 'passcode');
    else null;
  end case;

  n := coalesce(array_length(p_selected, 1), 0);
  /* Closed once the slots were full, until the team reopens it; backups
     alone may still be named where the team opened them. */
  if c.selection_closed_at is not null and not (coalesce(c.backups_open, false) and n = 0) then
    return jsonb_build_object('error', 'closed');
  end if;
  if n > c.slots then
    return jsonb_build_object('error', 'over-slots', 'slots', c.slots);
  end if;

  -- Anything already confirmed or further along is the team's to change.
  update campaign_options set state = 'option'
   where campaign_id = c.id and state in ('shortlisted', 'backup');

  if n > 0 then
    update campaign_options set state = 'shortlisted'
     where campaign_id = c.id and id = any(p_selected) and state = 'option';
  end if;
  -- Only where the team opened them: the page hides the control, and this is
  -- what makes that a fact rather than a courtesy.
  if coalesce(c.backups_open, false) and coalesce(array_length(p_backup, 1), 0) > 0 then
    update campaign_options set state = 'backup'
     where campaign_id = c.id and id = any(p_backup) and state = 'option';
  end if;

  return jsonb_build_object('ok', true, 'selected', n);
end $$;

revoke all on function public.save_selection(text, uuid[], uuid[], text) from public;
grant execute on function public.save_selection(text, uuid[], uuid[], text) to anon, authenticated;

create or replace function public.confirm_selection(
  p_token text, p_person text, p_passcode text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  c campaigns%rowtype;
begin
  select * into c from campaigns where access_token = p_token;
  if not found then return jsonb_build_object('error', 'not-found'); end if;
  -- A past client's link acts on nothing, as it reads nothing (second
  -- audit, item 7): answered as a key nobody knows, before the passcode.
  if exists (select 1 from public.clients cl where cl.id = c.client_id and cl.stage = 'past') then
    return jsonb_build_object('error', 'not-found');
  end if;
  -- Wrong passcodes lock out the caller who typed them, said as a lock
  -- (second audit, item 4).
  case public.link_passcode('selection', c.access_token, c.passcode, p_passcode)
    when 'locked' then return public.link_locked('selection', c.access_token);
    when 'wrong' then return jsonb_build_object('error', 'passcode');
    else null;
  end case;
  if coalesce(trim(p_person), '') = '' then
    return jsonb_build_object('error', 'name-required');
  end if;
  if c.selection_closed_at is not null and not coalesce(c.backups_open, false) then
    return jsonb_build_object('error', 'closed');
  end if;
  -- Nothing saved is nothing to confirm (a save refused under the page).
  if not exists (select 1 from campaign_options o
                  where o.campaign_id = c.id
                    and o.state = case when c.selection_closed_at is not null
                                       then 'backup' else 'shortlisted' end) then
    return jsonb_build_object('error', 'empty');
  end if;

  insert into campaign_confirmations (campaign_id, kind, person, source)
  values (c.id, 'client', trim(p_person), 'portal');

  insert into public.activity_log (actor, action, subject, detail)
  values (trim(p_person), 'campaign.confirmed', c.title,
          (select count(*)::text || ' creator' || case when count(*) = 1 then '' else 's' end
             from campaign_options
            where campaign_id = c.id and state = 'shortlisted') || ' confirmed');

  return jsonb_build_object('ok', true);
end $$;

revoke all on function public.confirm_selection(text, text, text) from public;
grant execute on function public.confirm_selection(text, text, text) to anon, authenticated;

create or replace function public.confirm_selection_with(
  p_token text, p_person text, p_passcode text, p_selected uuid[], p_backup uuid[],
  p_seen jsonb, p_idem text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  c      campaigns%rowtype;
  v_sel  uuid[];
  v_bak  uuid[];
  v_all  uuid[];
  v_idem text := left(nullif(btrim(coalesce(p_idem, '')), ''), 64);
  v_now  jsonb;
  v_snap jsonb;
  n      integer;
  v_booked integer;
begin
  select * into c from campaigns where access_token = p_token for update;
  if not found then return jsonb_build_object('error', 'not-found'); end if;
  -- A past client's link acts on nothing, as it reads nothing (second
  -- audit, item 7): answered as a key nobody knows, before the passcode.
  if exists (select 1 from public.clients cl where cl.id = c.client_id and cl.stage = 'past') then
    return jsonb_build_object('error', 'not-found');
  end if;
  -- Wrong passcodes lock out the caller who typed them, said as a lock
  -- (second audit, item 4).
  case public.link_passcode('selection', c.access_token, c.passcode, p_passcode)
    when 'locked' then return public.link_locked('selection', c.access_token);
    when 'wrong' then return jsonb_build_object('error', 'passcode');
    else null;
  end case;
  if coalesce(trim(p_person), '') = '' then
    return jsonb_build_object('error', 'name-required');
  end if;
  -- The same press again: the first answer stands and nothing is filed twice.
  if v_idem is not null and exists (select 1 from campaign_confirmations k
                                     where k.campaign_id = c.id and k.idem = v_idem) then
    return jsonb_build_object('ok', true, 'again', true);
  end if;

  v_sel := array(select distinct x from unnest(coalesce(p_selected, '{}'::uuid[])) x where x is not null);
  v_bak := case when coalesce(c.backups_open, false)
                then array(select distinct x from unnest(coalesce(p_backup, '{}'::uuid[])) x
                            where x is not null and not (x = any (v_sel)))
                else '{}'::uuid[] end;
  v_all := v_sel || v_bak;
  n := cardinality(v_sel);

  if c.selection_closed_at is not null and not (coalesce(c.backups_open, false) and n = 0) then
    return jsonb_build_object('error', 'closed');
  end if;
  if cardinality(v_all) = 0 then return jsonb_build_object('error', 'empty'); end if;
  -- The slots left are the slots less the creators already booked: a
  -- selection reopened for four of ten never books sixteen.
  v_booked := public.campaign_booked(c.id);
  if n > 0 and n > c.slots - v_booked then
    return jsonb_build_object('error', 'over-slots', 'slots', c.slots, 'booked', v_booked);
  end if;
  -- Every creator named is still on the campaign and open to choose.
  if (select count(*) from campaign_options o
       where o.id = any (v_all) and o.campaign_id = c.id
         and o.state in ('option', 'shortlisted', 'backup')) <> cardinality(v_all) then
    return jsonb_build_object('error', 'stale');
  end if;
  -- The prices the client read are the prices now.
  select jsonb_object_agg(o.id::text, o.rate) into v_now
    from campaign_options o where o.id = any (v_all);
  if exists (select 1 from campaign_options o
              where o.id = any (v_all)
                and coalesce(p_seen -> (o.id::text), 'null'::jsonb)
                    is distinct from coalesce(to_jsonb(o.rate), 'null'::jsonb)) then
    return jsonb_build_object('error', 'prices', 'rates', v_now);
  end if;

  update campaign_options set state = 'option'
   where campaign_id = c.id and state in ('shortlisted', 'backup');
  if n > 0 then
    update campaign_options set state = 'shortlisted'
     where campaign_id = c.id and id = any (v_sel) and state = 'option';
  end if;
  if cardinality(v_bak) > 0 then
    update campaign_options set state = 'backup'
     where campaign_id = c.id and id = any (v_bak) and state = 'option';
  end if;

  select jsonb_agg(jsonb_build_object('id', o.id, 'creator', cr.name, 'rate', o.rate, 'as', o.state)
                   order by o.position, o.added_at)
    into v_snap
    from campaign_options o join creators cr on cr.id = o.creator_id
   where o.id = any (v_all);
  insert into campaign_confirmations (campaign_id, kind, person, source, idem, snapshot)
  values (c.id, 'client', trim(p_person), 'portal', v_idem, coalesce(v_snap, '[]'::jsonb));

  insert into public.activity_log (actor, action, subject, detail)
  values (trim(p_person), 'campaign.confirmed', c.title,
          case when n > 0 then n::text || ' creator' || case when n = 1 then '' else 's' end || ' confirmed'
               else cardinality(v_bak)::text || ' backup' || case when cardinality(v_bak) = 1 then '' else 's' end || ' confirmed' end);

  return jsonb_build_object('ok', true, 'selected', n);
end $$;

revoke all on function public.confirm_selection_with(text, text, text, uuid[], uuid[], jsonb, text) from public;
grant execute on function public.confirm_selection_with(text, text, text, uuid[], uuid[], jsonb, text) to anon, authenticated;

create or replace function public.review_draft(
  p_token text, p_option uuid, p_decision text, p_note text default null,
  p_reviewer text default null, p_passcode text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  c campaigns%rowtype;
  o campaign_options%rowtype;
  n integer;
begin
  select * into c from campaigns where access_token = p_token;
  if not found then return jsonb_build_object('error', 'not-found'); end if;
  -- A past client's link acts on nothing, as it reads nothing (second
  -- audit, item 7): answered as a key nobody knows, before the passcode.
  if exists (select 1 from public.clients cl where cl.id = c.client_id and cl.stage = 'past') then
    return jsonb_build_object('error', 'not-found');
  end if;
  -- Wrong passcodes lock out the caller who typed them, said as a lock
  -- (second audit, item 4).
  case public.link_passcode('selection', c.access_token, c.passcode, p_passcode)
    when 'locked' then return public.link_locked('selection', c.access_token);
    when 'wrong' then return jsonb_build_object('error', 'passcode');
    else null;
  end case;
  if p_decision not in ('approved', 'changes') then
    return jsonb_build_object('error', 'bad-decision');
  end if;

  select * into o from campaign_options
   where id = p_option and campaign_id = c.id;
  if not found then return jsonb_build_object('error', 'not-found'); end if;

  -- Only a draft that is actually with the client can be ruled on.
  if o.state not in ('reviewing', 'changes') then
    return jsonb_build_object('error', 'not-reviewing');
  end if;
  /* A draft the team sent back to the creator is not with the client: the
     selection page shows it as Pending draft, so only a hand-made call
     could rule on it (audit B, 2026-10-17). */
  if o.state = 'changes' and coalesce(o.changes_by, 'client') = 'team' then
    return jsonb_build_object('error', 'not-reviewing');
  end if;

  n := coalesce(o.revision_round, 0);

  insert into option_reviews (option_id, round, decision, note, reviewer)
  values (p_option, greatest(n, 1), p_decision, nullif(trim(coalesce(p_note, '')), ''), p_reviewer);

  if p_decision = 'approved' then
    update campaign_options set state = 'scheduled' where id = p_option;
  else
    update campaign_options
       set state = 'changes', revision_round = greatest(n, 1) + 1,
           changes_by = 'client'
     where id = p_option;
  end if;

  /* The client's decision is the one event on a campaign that nobody on the
     team witnesses, and it was the only one the activity record never held:
     a draft went to Reviewing and appeared as Scheduled with nothing in
     between saying who had said yes. The reviewer's own name is the actor,
     because a person decided it. */
  insert into activity_log (actor, action, subject, detail)
  select coalesce(nullif(trim(coalesce(p_reviewer, '')), ''), 'Client'),
         'campaign.review', c.title,
         cr.name || ' · ' ||
         case when p_decision = 'approved' then 'Approved' else 'Changes requested' end ||
         coalesce(': ' || nullif(trim(coalesce(p_note, '')), ''), '')
    from creators cr where cr.id = o.creator_id;

  return jsonb_build_object('ok', true, 'decision', p_decision);
end $$;

revoke all on function public.review_draft(text, uuid, text, text, text, text) from public;
grant execute on function public.review_draft(text, uuid, text, text, text, text) to anon, authenticated;

-- END OF PASSCODE LOCKS PER CALLER ------------------------------------------

-- ===========================================================================
-- PASSCODE LOCKS LENGTHEN — a caller locked out again soon after is locked
-- out longer (15 minutes, then an hour, then a day), and a new access code
-- is six characters at least. 2026-10-18. Safe to run twice. Rollback at
-- the foot. Mirrored byte for byte in supabase/schema.sql under the same
-- banner; tests/confirmonce.js compares the two.
--
-- WHAT CHANGED (second audit, item 16)
--   1. `link_tries` keeps `strikes` and `struck_until` (the last lock's
--      end). A lock that begins within 24 hours of the last one ending is
--      the next step: 15 minutes, 1 hour, then 24 hours. The right access
--      code, and the team's Clear, start the steps again.
--      `link_passcode` and `link_lock_clear` are restated whole from
--      PASSCODE LOCKS PER CALLER with only that changed; `link_locked`
--      already says the minutes left.
--   2. Trigger `passcode_long_enough` on clients and campaigns refuses a
--      new or changed access code under six characters (`passcode-short`);
--      a shorter one already set keeps working until it is changed, and
--      clearing one is never refused. The console's Client settings says
--      so before it saves.
--
-- ROLLBACK
--   Run link_passcode and link_lock_clear from PASSCODE LOCKS PER CALLER
--   (2026-10-18-passcode-locks-per-caller.sql) again, then in the SQL
--   Editor:
--   drop trigger if exists clients_passcode_length on public.clients;
--   drop trigger if exists campaigns_passcode_length on public.campaigns;
--   drop function if exists public.passcode_long_enough();
--   alter table public.link_tries drop column if exists strikes,
--     drop column if exists struck_until;
-- ===========================================================================

alter table public.link_tries
  add column if not exists strikes integer not null default 0,
  add column if not exists struck_until timestamptz;

create or replace function public.link_passcode(p_kind text, p_token text, p_stored text, p_given text)
returns text
language plpgsql security definer set search_path = public as $$
declare
  v_ip text := public.request_ip();
  a public.link_tries%rowtype;
  b public.link_attempts%rowtype;
  v_known boolean;
begin
  if coalesce(p_stored, '') = '' then return 'ok'; end if;
  select * into a from public.link_tries where kind = p_kind and token = p_token and ip = v_ip;
  select * into b from public.link_attempts where kind = p_kind and token = p_token;
  -- An address that opened the link in the last 30 days is never held by
  -- the link's backstop, only by its own count.
  v_known := a.ok_at is not null and a.ok_at > now() - interval '30 days';
  if a.locked_until > now() then return 'locked'; end if;
  if b.locked_until > now() and not v_known then return 'locked'; end if;
  -- Asked without one: the page learning that a passcode is needed.
  if coalesce(p_given, '') = '' then return 'wrong'; end if;
  if p_given = p_stored then
    if a.kind is null or a.fails > 0 or a.locked_until is not null or a.strikes > 0
       or coalesce(a.ok_at < now() - interval '1 day', true) then
      insert into public.link_tries as t (kind, token, ip, fails, last_at, ok_at)
      values (p_kind, p_token, v_ip, 0, now(), now())
      on conflict (kind, token, ip) do update
         set fails = 0, locked_until = null, ok_at = now(), strikes = 0, struck_until = null;
    end if;
    return 'ok';
  end if;

  insert into public.link_tries (kind, token, ip) values (p_kind, p_token, v_ip)
  on conflict (kind, token, ip) do nothing;
  select * into a from public.link_tries
   where kind = p_kind and token = p_token and ip = v_ip for update;
  if a.locked_until > now() then return 'locked'; end if;
  a.fails := case when a.locked_until is not null or a.last_at < now() - interval '15 minutes'
                  then 1 else a.fails + 1 end;
  if a.fails >= 5 then
    -- A lock again within a day of the last one ending is longer: 15
    -- minutes, then an hour, then a day (second audit, item 16).
    a.strikes := case when a.struck_until > now() - interval '24 hours' then a.strikes + 1 else 1 end;
    a.locked_until := now() + case a.strikes when 1 then interval '15 minutes'
                                             when 2 then interval '1 hour'
                                             else interval '24 hours' end;
    a.struck_until := a.locked_until;
  else
    a.locked_until := null;
  end if;
  update public.link_tries
     set fails = a.fails, last_at = now(), locked_until = a.locked_until,
         strikes = a.strikes, struck_until = a.struck_until
   where kind = p_kind and token = p_token and ip = v_ip;

  insert into public.link_attempts (kind, token) values (p_kind, p_token)
  on conflict (kind, token) do nothing;
  select * into b from public.link_attempts
   where kind = p_kind and token = p_token for update;
  if b.locked_until is null or b.locked_until <= now() then
    b.fails := case when b.locked_until is not null or b.last_at < now() - interval '1 hour'
                    then 1 else b.fails + 1 end;
    b.locked_until := case when b.fails >= 100 then now() + interval '1 hour' end;
    update public.link_attempts set fails = b.fails, last_at = now(), locked_until = b.locked_until
     where kind = p_kind and token = p_token;
  end if;

  if a.locked_until is not null then return 'locked'; end if;
  if b.locked_until > now() and not v_known then return 'locked'; end if;
  return 'wrong';
end $$;
revoke all on function public.link_passcode(text, text, text, text) from public, anon, authenticated;

create or replace function public.link_lock_clear(p_kind text, p_id uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me      public.team_members;
  v_token text;
  v_name  text;
  v_n     integer;
begin
  select * into me from public.ops_me();
  if me.id is null then return jsonb_build_object('error', 'denied'); end if;
  if p_kind = 'review' then
    if not public.allowed('review.settings', 'work') then return jsonb_build_object('error', 'denied'); end if;
    if not public.client_scope_ok('client', p_id, 'work') then return jsonb_build_object('error', 'client-scope'); end if;
    select c.access_token, c.name into v_token, v_name from public.clients c where c.id = p_id;
  elsif p_kind = 'selection' then
    if not public.allowed('campaigns.campaigns', 'work') then return jsonb_build_object('error', 'denied'); end if;
    if not public.client_scope_ok('campaign', p_id, 'work') then return jsonb_build_object('error', 'client-scope'); end if;
    select k.access_token, k.title into v_token, v_name from public.campaigns k where k.id = p_id;
  else
    return jsonb_build_object('error', 'bad-kind');
  end if;
  if v_token is null then return jsonb_build_object('error', 'not-found'); end if;
  update public.link_tries set fails = 0, locked_until = null, strikes = 0, struck_until = null
   where kind = p_kind and token = v_token and (fails > 0 or locked_until is not null or strikes > 0);
  get diagnostics v_n = row_count;
  update public.link_attempts set fails = 0, locked_until = null
   where kind = p_kind and token = v_token;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, case when p_kind = 'review' then 'client.profile' else 'campaign.edited' end, v_name,
          case when p_kind = 'review' then 'Review link' else 'Selection link' end
          || ' unlocked · incorrect access codes cleared');
  return jsonb_build_object('ok', true, 'cleared', v_n);
end $$;
revoke all on function public.link_lock_clear(text, uuid) from public, anon;
grant execute on function public.link_lock_clear(text, uuid) to authenticated;

-- A new access code is six characters at least; one already set keeps
-- working until it is changed (second audit, item 16).
create or replace function public.passcode_long_enough()
returns trigger language plpgsql set search_path = public as $$
begin
  if new.passcode is not null and btrim(new.passcode) <> ''
     and (tg_op = 'INSERT' or new.passcode is distinct from old.passcode)
     and char_length(new.passcode) < 6 then
    raise exception 'passcode-short' using errcode = 'check_violation',
      hint = 'An access code needs at least 6 characters.';
  end if;
  return new;
end $$;
revoke all on function public.passcode_long_enough() from public, anon, authenticated;
create or replace trigger clients_passcode_length before insert or update of passcode on public.clients
  for each row execute function public.passcode_long_enough();
create or replace trigger campaigns_passcode_length before insert or update of passcode on public.campaigns
  for each row execute function public.passcode_long_enough();

-- END OF PASSCODE LOCKS LENGTHEN ---------------------------------------------

-- ===========================================================================
-- COMPLETED CAMPAIGNS STAY READABLE — a completed campaign's selection link
-- keeps showing its results after the client moves to Past. 2026-10-18.
-- Safe to run twice. Rollback at the foot. Mirrored byte for byte in
-- supabase/schema.sql under the same banner; tests/confirmonce.js compares
-- the two.
--
-- WHAT CHANGED (the user, 2026-10-18: "creator selection, once completed
-- the results not even viewed then the link no longer works"; 988)
--   get_campaign answers a Past client's campaign once it is Completed, read
--   only: `selection_closed` true and `backups_open` false, so the page
--   offers nothing to choose. Any other campaign of a Past client still
--   answers `not-found`, and save_selection, confirm_selection,
--   confirm_selection_with and review_draft still refuse every Past client
--   (PAST CLIENT LINKS ACT ON NOTHING), so nothing on the link writes.
--   media-pass and sign-download ask get_campaign, so the files and the
--   invoice open with it. Restated whole from PASSCODE LOCKS PER CALLER with
--   only that changed.
--
-- ROLLBACK
--   Run get_campaign from PASSCODE LOCKS PER CALLER again
--   (2026-10-18-passcode-locks-per-caller.sql).
-- ===========================================================================

create or replace function public.get_campaign(p_token text, p_passcode text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  c campaigns%rowtype;
  cl clients%rowtype;
  billable boolean;
begin
  select * into c from campaigns where access_token = p_token;
  if not found then return jsonb_build_object('error', 'not-found'); end if;
  select * into cl from clients where id = c.client_id;
  -- A past client's links close (second audit, item 5): answered as a key
  -- nobody knows, so the page says the link is not recognised. A completed
  -- campaign stays readable for its results, read only (the user,
  -- 2026-10-18: a client moved to Past before reading them lost the link);
  -- every write on the link still refuses a Past client.
  if cl.stage = 'past' and c.state <> 'completed' then
    return jsonb_build_object('error', 'not-found');
  end if;

  -- An invoice belongs to an accepted booking. Until the client has chosen and
  -- the team has confirmed at least one creator, the number and the PDF stay
  -- off the client's page, and reverting the last confirmation takes them off
  -- it again. The gate is here rather than on the page so nothing the client
  -- can open carries what it should not show.
  select exists (
    select 1 from campaign_options o
     where o.campaign_id = c.id
       and o.state in ('confirmed', 'pending_visit', 'pending_draft', 'submitted',
                       'reviewing', 'changes', 'scheduled', 'posted', 'completed')
  ) into billable;

  -- Wrong passcodes lock out the caller who typed them, said as a lock
  -- (second audit, item 4); a passcode asked for names nobody (item 6).
  case public.link_passcode('selection', c.access_token, c.passcode, p_passcode)
    when 'locked' then return public.link_locked('selection', c.access_token);
    when 'wrong' then return jsonb_build_object('error', 'passcode');
    else null;
  end case;

  return jsonb_build_object(
    'campaign', jsonb_build_object(
      'title', c.title, 'title_zh', c.title_zh,
      'purpose', c.purpose, 'purpose_zh', c.purpose_zh, 'slots', c.slots,
      -- A Past client's completed campaign offers nothing to choose.
      'backups_open', coalesce(c.backups_open, false) and cl.stage <> 'past',
      'selection_closed', c.selection_closed_at is not null or cl.stage = 'past',
      'deadline', c.deadline, 'state', c.state, 'deliverable', c.deliverable,
      'push_format', c.push_format, 'brief', c.brief, 'brief_zh', c.brief_zh,
      'invoice_no', case when billable then c.invoice_no end,
      'invoice_url', case when billable then c.invoice_url end,
      /* The client's last confirmation: who, when, and the creators it
         named, so a page opened again says the selection was confirmed and
         asks again only once the picks differ (2026-10-14). */
      'confirmed', (
        select jsonb_build_object('person', k.person, 'at', k.created_at,
                 'selected', coalesce((select jsonb_agg(x->>'id') from jsonb_array_elements(coalesce(k.snapshot, '[]'::jsonb)) x
                                        where x->>'as' = 'shortlisted'), '[]'::jsonb))
          from campaign_confirmations k
         where k.campaign_id = c.id and k.kind = 'client'
         order by k.created_at desc limit 1)),
    -- Currency and tax travel with the campaign, because the client's page
    -- prints both and must not assume Malaysia.
    'client', jsonb_build_object('name', cl.name, 'logo_url', cl.logo_url,
      'market', coalesce(cl.market, 'MY'), 'sst_applies', coalesce(cl.sst_applies, true)),
    /* A draft reaches the client when the team releases it, and not a moment
       before. `submitted` is the team's own step, so it is reported as
       `pending_draft`: the client is not asked to approve something they
       cannot open, and does not learn that a round exists. A `changes` the
       team raised is the same round going back to the creator, so it is
       withheld the same way; a `changes` the client raised is their own and
       is reported as it is. The mapping is here and not on the page, because
       what a client may not see is withheld by this function. */
    'options', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', o.id, 'name', cr.name,
        'rate', o.rate, 'platforms', o.platforms, 'state', s.shown,
        'is_replacement', o.is_replacement, 'added_at', o.added_at,
        -- Production. Present once a creator is locked; null before that, so
        -- the page can tell "not started" from "nothing to say".
        'visit_date', o.visit_date, 'visit_time', o.visit_time,
        'visit_location', o.visit_location, 'visit_pic', o.visit_pic,
        'visit_pic_phone', o.visit_pic_phone, 'tracking_no', o.tracking_no,
        'draft_url', case when s.released then o.draft_url end,
        /* The client's own rounds: a round the team sent back, or a request
           taken back, is not one the client made (2026-09-27). */
        'revision_round', (select count(*) from public.option_reviews r
                            where r.option_id = o.id and r.source = 'client'
                              and r.decision = 'changes' and r.undone_at is null)::int + 1,
        'planned_publish', o.planned_publish,
        /* What the creator uploaded, once it has been released: the round
           the team last released (`released_round`, stamped at release), so
           a creator's next round, uploaded after the client asked for
           changes, stays with the team until it is released in its turn
           (audit S5, 2026-10-10). A file hidden after the client's approval
           is never sent (audit S6). */
        'files', case when s.released then coalesce((
            select jsonb_agg(jsonb_build_object(
              'id', d.id, 'url', d.url, 'name', d.name, 'kind', d.kind,
              'bytes', d.bytes) order by d.uploaded_at)
            from campaign_deliverables d
            where d.option_id = o.id and d.removed_at is null and d.hidden_at is null
              and d.round = coalesce(o.released_round,
                            (select max(d2.round) from campaign_deliverables d2
                              where d2.option_id = o.id and d2.removed_at is null))
          ), '[]'::jsonb) else '[]'::jsonb end,
        -- The caption is part of what is being approved, so it travels with
        -- the files and is withheld with them.
        'caption', case when s.released then o.draft_caption end,
        'profiles', coalesce((
          select jsonb_agg(jsonb_build_object('platform', p.platform, 'url', p.url))
          from creator_profiles p where p.creator_id = cr.id), '[]'::jsonb),
        -- One row per platform posted on, so two placements stay two numbers.
        'posts', coalesce((
          select jsonb_agg(jsonb_build_object(
            'platform', pp.platform, 'post_url', pp.post_url,
            'published_at', pp.published_at, 'window_days', pp.window_days,
            'impressions', pp.impressions, 'engagements', pp.engagements,
            'views', pp.views, 'measured_at', pp.measured_at) order by pp.platform)
          from option_posts pp where pp.option_id = o.id), '[]'::jsonb),
        /* What was last decided, so the card can say who approved it and
           when rather than jumping to the next step with nothing to show for
           the decision. The client's own decisions, and an approval the team
           gave on the client's behalf (`by_team`, read "Proceeded by"); a
           team send-back stays withheld. Withheld with the draft it is about. */
        'review', case when s.released then (
            select jsonb_build_object('decision', r.decision, 'reviewer', r.reviewer,
                                      'note', case when r.source = 'client' then r.note end,
                                      'at', r.created_at, 'by_team', r.source = 'team')
            from option_reviews r where r.option_id = o.id
              and (r.source = 'client' or r.decision = 'approved') and r.undone_at is null
            order by r.created_at desc limit 1) end)
        order by o.position, o.added_at)
      from campaign_options o
      join creators cr on cr.id = o.creator_id
      cross join lateral (
        select sh.shown,
               sh.shown in ('reviewing', 'changes', 'scheduled', 'posted', 'completed')
                 as released
        from (select case
                       when o.state = 'submitted' then 'pending_draft'
                       when o.state = 'changes'
                            and coalesce(o.changes_by, 'client') = 'team' then 'pending_draft'
                       else o.state
                     end as shown) sh
      ) s
      where o.campaign_id = c.id and o.state <> 'replaced'), '[]'::jsonb)
  );
end $$;

revoke all on function public.get_campaign(text, text) from public;
grant execute on function public.get_campaign(text, text) to anon, authenticated;

-- END OF COMPLETED CAMPAIGNS STAY READABLE ----------------------------------

-- ===========================================================================
-- SUPPLIER ENTRIES — a supplier's document added by hand is filed under the
-- supplier (2026-10-18)
-- ===========================================================================
-- WHY (the user, 2026-10-18: "AS125 supplier documents not linked"): Add
-- entry offered no Supplier Letter, so a supplier's agreement, NDA or
-- incident report kept outside the portal was filed as Other (or under a
-- client made to hold it) and never reached the supplier's record.
--
-- WHAT IT CHANGES
--   * `register_add` and `register_update` take `p_supplier` and the family
--     `supplier` (Suppliers at Work, as `register_may` answers): a supplier
--     entry names its supplier (`no-supplier`) and no client or colleague;
--     an edit files the supplier from and to.
--   * Entries added by hand before, whose reference names a supplier's ID
--     (`…/AS125/…`), are filed under that supplier once: family `supplier`,
--     `supplier_id` set, the client they hung from let go.
--
-- ORDER: this file, then the pages. A page served before calls the eight or
-- nine argument form, which this replaces: it reloads (the functions are
-- dropped and made again with one more argument, defaulted).
-- Safe to run twice. Rollback: the two functions from DOCUMENT EDITS NAME
-- THEIR CHANGES and its add; the moved rows keep their supplier.
-- ===========================================================================

drop function if exists public.register_add(text, text, text, date, text, uuid, text, text, uuid);
create or replace function public.register_add(
  p_serial    text,
  p_family    text,
  p_kind      text,
  p_issued_at date,
  p_recipient text,
  p_client    uuid,
  p_note      text,
  p_file_url  text,
  p_member    uuid default null,
  p_supplier  uuid default null
)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  who   text := lower(auth.jwt() ->> 'email');
  me    public.team_members%rowtype;
  v_serial text := nullif(btrim(coalesce(p_serial, '')), '');
  v_fam text := coalesce(nullif(btrim(p_family), ''), 'other');
  v_id  uuid;
  cl    public.clients%rowtype;
  tm    public.team_members%rowtype;
  sp    public.suppliers%rowtype;
begin
  if v_fam not in ('quote_cover', 'client', 'hr', 'other', 'supplier') then return jsonb_build_object('error', 'bad-family'); end if;
  if not public.register_may(v_fam, 'work') then return jsonb_build_object('error', 'not-allowed'); end if;
  if v_serial is null then return jsonb_build_object('error', 'serial-required'); end if;
  if v_serial !~ '^[A-Za-z0-9/._-]{3,40}$' then return jsonb_build_object('error', 'serial-shape'); end if;
  if public.serial_taken(v_serial) then return jsonb_build_object('error', 'serial-taken'); end if;
  if coalesce(btrim(p_kind), '') = '' then return jsonb_build_object('error', 'kind-required'); end if;
  if v_fam = 'hr' then
    if p_member is not null then select * into tm from public.team_members where id = p_member; end if;
  elsif v_fam = 'supplier' then
    if p_supplier is not null then select * into sp from public.suppliers where id = p_supplier; end if;
    if sp.id is null then return jsonb_build_object('error', 'no-supplier'); end if;
  elsif p_client is not null then
    select * into cl from public.clients where id = p_client;
  end if;
  select * into me from public.team_members where lower(email) = who and active limit 1;

  insert into public.documents
    (family, kind, serial, client_id, member_id, supplier_id, issued_at, recipient, signed, source, file_url, note, issued_by)
  values
    (v_fam, btrim(p_kind), v_serial, cl.id, tm.id, sp.id, coalesce(p_issued_at, (now() at time zone 'Asia/Kuala_Lumpur')::date),
     jsonb_build_object('name', coalesce(btrim(p_recipient), '')), false, 'manual',
     nullif(btrim(p_file_url), ''), nullif(btrim(p_note), ''), coalesce(me.name, who))
  returning id into v_id;

  insert into public.activity_log (actor, action, subject, detail)
  values (who, 'register.added',
          case when v_fam = 'hr' then 'HR' else coalesce(cl.name, sp.name, sp.code, btrim(p_recipient), '') end,
          case when v_fam = 'hr' then btrim(p_kind) else v_serial || ' · ' || btrim(p_kind) end);
  return jsonb_build_object('ok', true, 'id', v_id, 'serial', v_serial);
exception
  when unique_violation then return jsonb_build_object('error', 'serial-taken');
end $$;
grant execute on function public.register_add(text, text, text, date, text, uuid, text, text, uuid, uuid) to authenticated;

drop function if exists public.register_update(uuid, text, text, date, text, uuid, text, text, uuid);
create or replace function public.register_update(
  p_doc       uuid,
  p_kind      text,
  p_family    text,
  p_issued_at date,
  p_recipient text,
  p_client    uuid,
  p_note      text,
  p_file_url  text,
  p_member    uuid default null,
  p_supplier  uuid default null
)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  who   text := lower(auth.jwt() ->> 'email');
  d     public.documents%rowtype;
  v_fam text := coalesce(nullif(btrim(p_family), ''), 'other');
  cl    public.clients%rowtype;
  was_cl public.clients%rowtype;
  tm    public.team_members%rowtype;
  sp    public.suppliers%rowtype;
  was_sp public.suppliers%rowtype;
  moves text[] := array[]::text[];
  fam_word jsonb := '{"quote_cover":"Quotation Covers","client":"Client Letters","hr":"HR Letters","supplier":"Supplier Letters","other":"Other"}'::jsonb;
  v_rec text := coalesce(btrim(p_recipient), '');
  v_note text := nullif(btrim(p_note), '');
  v_file text := nullif(btrim(p_file_url), '');
begin
  select * into d from public.documents where id = p_doc;
  if d.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if d.source <> 'manual' then return jsonb_build_object('error', 'not-manual'); end if;
  if v_fam not in ('quote_cover', 'client', 'hr', 'other', 'supplier') then return jsonb_build_object('error', 'bad-family'); end if;
  if not public.register_may(d.family, 'work') or not public.register_may(v_fam, 'work') then
    return jsonb_build_object('error', 'not-allowed');
  end if;
  if coalesce(btrim(p_kind), '') = '' then return jsonb_build_object('error', 'kind-required'); end if;
  if v_fam = 'hr' then
    if p_member is not null then select * into tm from public.team_members where id = p_member; end if;
  elsif v_fam = 'supplier' then
    if p_supplier is not null then select * into sp from public.suppliers where id = p_supplier; end if;
    if sp.id is null then return jsonb_build_object('error', 'no-supplier'); end if;
  elsif p_client is not null then
    select * into cl from public.clients where id = p_client;
  end if;
  if d.client_id is not null then select * into was_cl from public.clients where id = d.client_id; end if;
  if d.supplier_id is not null then select * into was_sp from public.suppliers where id = d.supplier_id; end if;

  /* What moved, in the order a reader looks: the type, the date, where it is
     filed, who it went to, then whether the note or the file changed. An HR
     row names only its type, date, note and file. */
  if d.kind is distinct from btrim(p_kind) then
    moves := moves || ('type ' || coalesce(d.kind, 'not set') || ' → ' || btrim(p_kind));
  end if;
  if d.issued_at is distinct from p_issued_at then
    moves := moves || ('date ' || public.register_day(d.issued_at) || ' → ' || public.register_day(p_issued_at));
  end if;
  if v_fam <> 'hr' and d.family <> 'hr' then
    if d.family is distinct from v_fam then
      moves := moves || ('filed ' || coalesce(fam_word ->> d.family, d.family) || ' → ' || coalesce(fam_word ->> v_fam, v_fam));
    end if;
    if coalesce(d.recipient ->> 'name', '') is distinct from v_rec then
      moves := moves || ('recipient ' || coalesce(nullif(d.recipient ->> 'name', ''), 'not set') || ' → ' || coalesce(nullif(v_rec, ''), 'not set'));
    end if;
    if d.client_id is distinct from cl.id then
      moves := moves || ('client ' || coalesce(was_cl.name, 'not set') || ' → ' || coalesce(cl.name, 'not set'));
    end if;
    if d.supplier_id is distinct from sp.id then
      moves := moves || ('supplier ' || coalesce(was_sp.code, 'not set') || ' → ' || coalesce(sp.code, 'not set'));
    end if;
  end if;
  if d.note is distinct from v_note then moves := moves || 'note changed'::text; end if;
  if d.file_url is distinct from v_file then moves := moves || 'file link changed'::text; end if;

  update public.documents set
    kind = btrim(p_kind), family = v_fam, issued_at = p_issued_at,
    recipient = jsonb_build_object('name', v_rec),
    client_id = cl.id, member_id = tm.id, supplier_id = sp.id,
    note = v_note, file_url = v_file
  where id = p_doc;
  if array_length(moves, 1) > 0 then
    insert into public.activity_log (actor, action, subject, detail)
    values (who, 'register.edited',
            case when v_fam = 'hr' or d.family = 'hr' then 'HR' else coalesce(cl.name, sp.name, sp.code, nullif(v_rec, ''), d.serial) end,
            case when v_fam = 'hr' or d.family = 'hr' then array_to_string(moves, '; ')
                 else d.serial || ': ' || array_to_string(moves, '; ') end);
  end if;
  return jsonb_build_object('ok', true, 'serial', d.serial);
end $$;
grant execute on function public.register_update(uuid, text, text, date, text, uuid, text, text, uuid, uuid) to authenticated;

/* Entries added by hand whose reference names a supplier's ID, filed under
   that supplier once. */
update public.documents d
   set family = 'supplier', supplier_id = s.id, client_id = null
  from public.suppliers s
 where d.supplier_id is null and d.source = 'manual' and d.family in ('other', 'client')
   and d.serial ~ ('/' || s.code || '/');

-- END OF SUPPLIER ENTRIES ----------------------------------------------------

-- ===========================================================================
-- SUPPLIER SERVICE AGREEMENT — a supplier's one document, issued from the
-- portal with its schedules (2026-10-18)
-- ===========================================================================
-- WHY (the user, 2026-10-18): the Supplier Service Agreement (Ads Campaign
-- Management) is the document a supplier signs; Letter to Supplier is no
-- longer offered. Schedule A names the supplier, the services and the fee;
-- Schedule B lists the client accounts it runs, picked from Clients, and is
-- updated by issuing a new copy (Reissue: the same reference, "Latest update
-- as at" the new day).
--
-- WHAT IT CHANGES
--   * `doc_types.schedule`: a type's prefilled schedule wording (the
--     agreement's Part 2 and Schedule B's notes), copied into each document.
--   * A type `supplier_sca`, Supplier Service Agreement, signed, its clauses
--     as its wording (`# Heading`, `1.` a numbered clause, `a.` a lettered
--     item, the team's to edit in Document types). Made once; the first run
--     also stops offering Letter to Supplier (issued letters keep their type).
--   * `issue_document` numbers it AD/SCA/{Supplier ID}/{YYMM}{NN}, the
--     lowest free from 01, and refuses one without its schedules
--     (`agreement-incomplete`, `sca_complete`).
--
-- ORDER: this file, then the pages. A page served before offers no
-- agreement. Safe to run twice. Rollback: ISSUE from SUPPLIERS; the type set
-- inactive (`doc_type_set_active`), Letter to Supplier active again.
-- ===========================================================================

alter table public.doc_types add column if not exists schedule jsonb;

/* Made once: an agreement row the team edited is never written over, and
   Letter to Supplier is stood down only on the run that makes it. */
with made as (
  insert into public.doc_types (id, family, code, name, title, salutation, closing, body_en, signed, position, schedule)
  select 'supplier_sca', 'supplier', 'SCA', 'Supplier Service Agreement', 'Service Agreement', '', '',
         $sca$# Parties

This Advertising Management Services Agreement (the "Agreement") is made on the Agreement Date stated in Schedule A between ADSPACE PLT (Business Registration Number: 202304002162), with its registered address at 61-02, Jalan Mutiara Emas 2A, Taman Mount Austin, 81100 Johor Bahru, Johor, Malaysia (the "Company"); and the person or entity named as the Supplier in Part 1 of Schedule A (the "Supplier").

The Company provides marketing services to its clients. The Company wishes to engage the Supplier, as an independent contractor, to plan, run and optimise paid advertising campaigns for those clients on the terms below.

# Definitions

1. "Client" means any person or business for whom the Company provides services and to whose work the Supplier is assigned or exposed during the Term, including any prospective client introduced to the Supplier by the Company.

1. "Confidential Information" means all non-public information disclosed to or obtained by the Supplier in connection with this Agreement, including Client identities and contacts, pricing, budgets, ad spend, campaign strategies, audiences, creatives, performance data, login credentials, business plans, processes, templates and know-how of the Company or any Client.

1. "Ad Accounts" means any advertising, analytics, tracking or business manager accounts (for example Meta, Google, TikTok, LinkedIn) used for Company or Client work.

1. "Work Product" means all campaigns, ad copy, creatives, audiences, reports, structures, playbooks, data and other materials created by the Supplier under this Agreement.

1. "Term" means the period described in Clause 4.

# Services

1. The Supplier will provide the ads management services set out in Schedule A (the "Services") for the Clients the Company assigns from time to time.

1. The Supplier will perform the Services with reasonable skill and care, follow each platform's advertising policies, and comply with the Company's reasonable instructions, brand guidelines and approval process.

1. The Supplier must not launch, pause, or change budgets on any campaign beyond the spend approval limit in Schedule A without the Company's prior written approval.

1. The Supplier will deal with Clients only through the Company, unless the Company asks the Supplier to join a call or channel. In any such contact the Supplier acts on the Company's behalf and under the Company's name.

1. The Company will set a monthly ad spend budget for each Ad Account, as listed in Schedule B or later confirmed by the Company in writing (the "Approved Budget"). The Supplier will pace spend so that each account's actual monthly spend stays within the budget tolerance in Schedule A.

1. If an account's spend exceeds its Approved Budget by more than the budget tolerance because the Supplier set up, changed or monitored a campaign incorrectly, or did not follow the Company's instructions, the Supplier will reimburse the Company for the excess spend. The Company may deduct this amount from any fees due.

1. Underspending. If an account is likely to spend less than its Approved Budget by more than the budget tolerance, the Supplier will notify the Company in writing within 1 working day, with the reason and a recovery plan. If the underspend results from the Supplier's failure to launch, monitor or optimise campaigns, the Company may reduce that month's fee for the account in proportion to the shortfall.

1. Exclusions. The Supplier is not responsible for over- or underspending caused by platform errors, billing or payment issues, account suspensions not caused by the Supplier, or written instructions from the Company or Client, provided the Supplier reports the issue to the Company promptly.

# Term

This Agreement starts on the Start Date stated in Schedule A and continues until terminated under Clause 10. If Schedule A states a trial period, either party may end this Agreement during that period on 30 days' written notice.

# Fees and Payment

1. The Company will pay the Supplier the fees set out in Schedule A.

1. The Supplier will invoice the Company monthly. The Company will pay valid invoices within 14 working days of receipt.

1. Ad spend is paid by the Company or the Client directly to the platform. The Supplier must not use any payment method for ad spend unless the Company approves it in writing.

1. The Supplier is responsible for their own taxes, statutory contributions and business expenses. No other expenses are reimbursed unless approved in writing beforehand.

1. If the Supplier becomes SST-registered, it will notify the Company in writing before charging SST, and the parties will agree any change to the fees in writing.

# Confidentiality and Data Protection

1. The Supplier will keep all Confidential Information strictly confidential and use it only to perform the Services.

1. The Supplier will not disclose it to anyone without the Company's prior written consent.

1. The Supplier will not copy, download, screenshot, export or store Confidential Information or Client data except as needed for the Services, and only on secure, password-protected devices and accounts.

1. The Supplier will not share login credentials, add other users to Ad Accounts, or allow any third party (including assistants or subcontractors) to access Company or Client work without the Company's written approval.

1. The Supplier will not publicly disclose that they work for the Company's Clients, or use any Client's name, logo, results or creatives in a portfolio, case study, social media post or pitch, unless the Company gives written permission.

1. The Supplier will handle any personal data (such as customer lists, leads and pixel data) in line with the Personal Data Protection Act 2010 and the Company's instructions, and will tell the Company within 24 hours of any suspected data breach or unauthorised access.

1. These obligations do not apply to information that is or becomes public through no fault of the Supplier, or that the law or a court requires to be disclosed (after first notifying the Company where lawful).

1. On request, and in any case when this Agreement ends, the Supplier will return or permanently delete all Confidential Information and confirm this in writing.

1. This Clause 6 continues to apply indefinitely after this Agreement ends.

# Intellectual Property and Account Ownership

1. All Work Product belongs to the Company (or the relevant Client, as the Company directs) from the moment it is created. The Supplier assigns to the Company all rights, including copyright, in the Work Product and waives any moral rights to the extent the law allows.

1. All Ad Accounts, pixels, audiences, data and business manager assets belong to the Company or the Client. The Supplier gains no ownership of them and must not transfer, duplicate or claim them.

1. The Supplier will work only through access granted by the Company. The Supplier must not move Client assets into accounts the Supplier controls.

1. Tools, skills and general know-how the Supplier had before this Agreement remain the Supplier's, provided they contain no Confidential Information.

# No Use for Own Benefit

1. The Supplier must not use anything learned or created through this engagement to compete with the Company or to profit outside it. In particular, during the Term and for 12 months after it ends, the Supplier will not:

a. use Confidential Information, Client data, audiences, campaign structures, creatives or performance insights for the Supplier's own business or for any other client;

a. use the Company's proprietary templates, playbooks, reporting formats, pricing models or processes to set up or run a competing service;

a. copy or reuse any Client's audiences, lookalikes, pixel data or customer lists in any other account;

a. accept commissions, rebates, kickbacks or referral fees from platforms, vendors or Clients in connection with the Services without disclosing them to the Company in writing; or

a. run ads for a direct competitor of an assigned Client during the Term without the Company's prior written consent.

1. Nothing in this Clause stops the Supplier from using general advertising skills and experience that are publicly known or not specific to the Company or its Clients.

# Non-Solicitation and Non-Circumvention

1. During the Term and for 12 months after it ends, the Supplier will not, directly or through anyone else:

a. solicit, approach or accept work from any Client the Supplier worked on or learned about through the Company, for services the same as or similar to the Company's;

a. encourage any Client to reduce or end its business with the Company; or

a. solicit or hire any Company employee or contractor the Supplier worked with.

1. If a Client contacts the Supplier directly about work, the Supplier will refer the Client back to the Company and inform the Company promptly.

1. If the Supplier breaches Clause 9.1, the Supplier will pay the Company, as a genuine pre-estimate of its loss, a sum equal to 6 months of the fees that Client paid the Company, without limiting the Company's other remedies.

1. The parties agree these restrictions are reasonable to protect the Company's client relationships and Confidential Information.

# Termination

1. Either party may end this Agreement by giving 30 days' written notice.

1. The Company may end this Agreement immediately by written notice if the Supplier breaches Clauses 6, 7, 8 or 9, acts dishonestly, or causes an Ad Account to be suspended through negligence or a policy breach.

1. On termination the Supplier will, within 3 working days: hand over all Work Product, reports and campaign notes; remove their own access from all Ad Accounts; and return or delete Confidential Information under Clause 6.7.

1. The Company will pay fees properly earned up to the termination date. Clause 3.6 survives until any amount due under it has been paid in full. Clauses 6, 7, 8, 9, 11 and 13 also survive termination.

# Independent Contractor, Liability and Indemnity

1. The Supplier is an independent contractor, not an employee, partner or agent of the Company, and is not entitled to employee benefits. The Supplier decides its own working hours, methods and tools, and may take on other work, subject to Clauses 8 and 9.

1. The Supplier will indemnify the Company against losses, claims and costs caused by the Supplier's breach of this Agreement, breach of platform policies, negligence or misuse of Confidential Information.

1. The Company is not liable for any indirect or consequential loss. The Company's total liability under this Agreement is limited to the fees paid to the Supplier in the 3 months before the claim.

# General

1. The Supplier may not assign or subcontract this Agreement without the Company's written consent.

1. This Agreement is the entire agreement between the parties on its subject. Changes are valid only in writing signed by both parties.

1. If any clause is found unenforceable, it will be read down to the extent needed and the rest of the Agreement continues in force.

1. Notices must be in writing and sent to the addresses or emails stated in Clause 1 (for the Company) and Schedule A (for the Supplier).

1. This Agreement may be signed electronically and in counterparts, in line with the Electronic Commerce Act 2006. An electronic signature has the same effect as a handwritten one, and the counterparts together form one agreement.

# Governing Law

This Agreement is governed by the laws of Malaysia.
$sca$, true, 59, $sch${
  "platforms": "Meta",
  "tasks": "Campaign setup, audience building, ad copy, A/B testing, budget pacing, daily monitoring, optimisation",
  "reporting": "Weekly snapshots to the Company and monthly reporting to the Company's clients",
  "response": "Within 4 working hours on working days",
  "spend_limit": "Changes above 40% per day need written approval",
  "tolerance": "Actual monthly spend within ±10% of the approved budget",
  "notes": "The Company may add, remove or change an account or its Approved Budget by sharing a new copy of this Schedule B, stating the account and the date the change takes effect.\n\nA blank End date means the account is ongoing.\n\nAd spend per month is the amount spent shown in the ad account. It excludes all relevant taxes."
}$sch$::jsonb
   where not exists (select 1 from public.doc_types t where t.id = 'supplier_sca')
  returning id
)
update public.doc_types set active = false
 where id = 'supplier_letter' and exists (select 1 from made);

/* What an agreement must hold before it is issued. */
create or replace function public.sca_complete(p_body jsonb)
returns boolean
language sql immutable set search_path = public as $$
  select coalesce(btrim(p_body #>> '{agreement,part1,legal_name}'), '') <> ''
     and coalesce(p_body #>> '{agreement,part1,start}', '') ~ '^\d{4}-\d{2}-\d{2}$'
     and coalesce(btrim(p_body #>> '{agreement,part2,fee}'), '') <> ''
     and case when jsonb_typeof(p_body #> '{agreement,accounts}') = 'array'
              then jsonb_array_length(p_body #> '{agreement,accounts}') between 1 and 60 else false end
$$;
revoke all on function public.sca_complete(jsonb) from public, anon, authenticated;

create or replace function public.issue_document(
  p_type      text,
  p_client    uuid,
  p_member    uuid,
  p_serial    text,
  p_issued_at date,
  p_title     text,
  p_recipient jsonb,
  p_body      jsonb,
  p_signatory jsonb,
  p_languages text[],
  p_idem      text,
  p_salutation text default null,
  p_signed    boolean default null,
  p_supplier  uuid default null
)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  who     text := lower(auth.jwt() ->> 'email');
  t       public.doc_types%rowtype;
  cl      public.clients%rowtype;
  mb      public.team_members%rowtype;
  sp      public.suppliers%rowtype;
  me      public.team_members%rowtype;
  v_old   public.documents%rowtype;
  v_serial text;
  v_base  text;
  v_n     int;
  v_id    uuid;
  v_langs text[];
  v_signed boolean;
begin
  select * into t from public.doc_types where id = p_type and active;
  if t.id is null then return jsonb_build_object('error', 'no-type'); end if;
  if not public.register_may(t.family, 'work') then return jsonb_build_object('error', 'not-allowed'); end if;

  if coalesce(btrim(p_idem), '') <> '' then
    select * into v_old from public.documents where idem_key = btrim(p_idem) limit 1;
    if v_old.id is not null then
      return jsonb_build_object('ok', true, 'repeat', true, 'id', v_old.id, 'serial', v_old.serial);
    end if;
  end if;

  if t.family in ('quote_cover', 'client') then
    if p_client is null then return jsonb_build_object('error', 'no-client'); end if;
    select * into cl from public.clients where id = p_client;
    if cl.id is null then return jsonb_build_object('error', 'no-client'); end if;
  end if;
  if t.family = 'hr' then
    if p_member is null then return jsonb_build_object('error', 'no-member'); end if;
    select * into mb from public.team_members where id = p_member;
    if mb.id is null then return jsonb_build_object('error', 'no-member'); end if;
    if coalesce(btrim(mb.staff_code), '') = '' then return jsonb_build_object('error', 'no-staff-code'); end if;
  end if;
  if t.family = 'supplier' then
    if p_supplier is null then return jsonb_build_object('error', 'no-supplier'); end if;
    select * into sp from public.suppliers where id = p_supplier;
    if sp.id is null then return jsonb_build_object('error', 'no-supplier'); end if;
    /* The agreement carries its schedules (2026-10-18): who the supplier is,
       when it starts, the fee and at least one account. */
    if t.id = 'supplier_sca' and not public.sca_complete(p_body) then
      return jsonb_build_object('error', 'agreement-incomplete');
    end if;
  end if;

  -- Whether the letter leaves space to be signed is the sheet's tick
  -- (2026-10-01), else the type's own setting. A signed letter is signed by
  -- a person, never by a permission; an unsigned one may still name who
  -- issued it, held to the same test.
  v_signed := coalesce(p_signed, t.signed);
  if coalesce(btrim(p_signatory ->> 'name'), '') <> '' and not public.issuer_name_ok(p_signatory ->> 'name') then
    return jsonb_build_object('error', 'issuer-name', 'name', p_signatory ->> 'name');
  end if;
  if v_signed then
    if coalesce(btrim(p_signatory ->> 'name'), '') = '' then return jsonb_build_object('error', 'no-signatory'); end if;
    if not public.issuer_name_ok(p_signatory ->> 'name') then
      return jsonb_build_object('error', 'issuer-name', 'name', p_signatory ->> 'name');
    end if;
  end if;

  v_serial := nullif(btrim(coalesce(p_serial, '')), '');
  if v_serial is null then
    if t.family = 'quote_cover' then return jsonb_build_object('error', 'serial-required'); end if;
    if t.family in ('client', 'supplier') then
      if t.family = 'client' then
        if coalesce(btrim(cl.client_code), '') = '' then return jsonb_build_object('error', 'no-client-code'); end if;
        v_base := 'ACL/' || upper(btrim(cl.client_code));
      elsif t.id = 'supplier_sca' then
        v_base := 'AD/SCA/' || upper(btrim(sp.code));
      else
        v_base := 'ASL/' || upper(btrim(sp.code));
      end if;
      /* A Supplier Service Agreement is numbered by its month
         (AD/SCA/{Supplier ID}/{YYMM}{NN}, 2026-10-18); every other letter by
         its day. */
      v_base := v_base || '/' || to_char(coalesce(p_issued_at, (timezone('Asia/Kuala_Lumpur', now()))::date),
                                         case when t.id = 'supplier_sca' then 'YYMM' else 'YYMMDD' end);
      -- Two issuers on one client (or supplier) and day wait for each other
      -- here, so the second never reads the first one's number as free.
      perform pg_advisory_xact_lock(hashtext('acl:' || v_base));
      v_n := 1;
      loop
        v_serial := v_base || case when v_n < 10 then '0' else '' end || v_n;
        exit when not public.serial_taken(v_serial);
        v_n := v_n + 1;
        if v_n > 999 then return jsonb_build_object('error', 'no-serial'); end if;
      end loop;
    else
      v_base := 'ADHR/' || upper(mb.staff_code) || '/' || coalesce(t.code, 'GL') ||
                to_char(timezone('Asia/Kuala_Lumpur', now()), 'YYMM');
      v_serial := v_base; v_n := 1;
      while public.serial_taken(v_serial) loop
        v_n := v_n + 1; v_serial := v_base || '-' || v_n;
      end loop;
    end if;
  else
    if v_serial !~ '^[A-Za-z0-9/._-]{3,40}$' then return jsonb_build_object('error', 'serial-shape'); end if;
    if public.serial_taken(v_serial) then return jsonb_build_object('error', 'serial-taken'); end if;
  end if;

  v_langs := coalesce(p_languages, '{en}');
  if array_length(v_langs, 1) is null then v_langs := '{en}'; end if;

  select * into me from public.team_members where lower(email) = who and active limit 1;

  insert into public.documents
    (type_id, family, kind, serial, client_id, member_id, supplier_id, issued_at, title, salutation, closing,
     recipient, body, languages, signatory, signed, source, issued_by, idem_key)
  values
    (t.id, t.family, t.name, v_serial,
     case when t.family in ('hr', 'supplier') then null else p_client end,
     case when t.family = 'hr' then p_member else null end,
     case when t.family = 'supplier' then p_supplier else null end,
     coalesce(p_issued_at, (timezone('Asia/Kuala_Lumpur', now()))::date),
     coalesce(nullif(btrim(p_title), ''), t.title),
     coalesce(nullif(btrim(p_salutation), ''), t.salutation), t.closing,
     coalesce(p_recipient, '{}'::jsonb), coalesce(p_body, '{}'::jsonb), v_langs,
     case when coalesce(btrim(p_signatory ->> 'name'), '') <> '' then p_signatory else null end, v_signed, 'portal',
     coalesce(me.name, who), nullif(btrim(p_idem), ''))
  returning id into v_id;

  -- The record is told an HR letter was issued and nothing about whom: the
  -- Activity record is read by more people than HR is.
  if t.family = 'hr' then
    insert into public.activity_log (actor, action, subject, detail)
    values (who, 'document.issued', 'HR', t.name);
  else
    insert into public.activity_log (actor, action, subject, detail)
    values (who, 'document.issued', case when t.family = 'supplier' then sp.name else cl.name end, v_serial || ' · ' || t.name);
  end if;
  return jsonb_build_object('ok', true, 'id', v_id, 'serial', v_serial);
exception
  when unique_violation then
    if coalesce(btrim(p_idem), '') <> '' then
      select * into v_old from public.documents where idem_key = btrim(p_idem) limit 1;
      if v_old.id is not null then
        return jsonb_build_object('ok', true, 'repeat', true, 'id', v_old.id, 'serial', v_old.serial);
      end if;
    end if;
    return jsonb_build_object('error', 'serial-taken');
end $$;
grant execute on function public.issue_document(text, uuid, uuid, text, date, text, jsonb, jsonb, jsonb, text[], text, text, boolean, uuid) to authenticated;

-- END OF SUPPLIER SERVICE AGREEMENT ------------------------------------------

-- ===========================================================================
-- HR LETTERS FIND THEIR COLLEAGUE — an HR letter whose reference carries a
-- colleague's Employee ID is filed under them (2026-10-18)
-- ===========================================================================
-- WHY (the user, 2026-10-18: "when its linked to a team member, shouldnt all
-- letters or documents go into their respective accounts"): the HR letters
-- added by hand from the old list carry the colleague's Employee ID in their
-- reference (ADHR/AD013/E2501, AD013-P2405001) but name nobody, so the
-- register's Team column found them and the colleague's record did not.
--
-- WHAT IT CHANGES
--   * `hr_member_of(serial)`: the one colleague whose Employee ID is a part
--     of the reference (split on / and -), else null (none, or two).
--   * Trigger `documents_hr_member` (before insert or update of serial,
--     family, member_id): an HR letter naming nobody takes that colleague.
--   * The HR letters already filed naming nobody are filed so once.
--
-- ORDER: this file, then the pages (the colleague's record also matches by
-- the reference, so either order reads the same). Safe to run twice.
-- Rollback: drop the trigger and the function; the rows keep their colleague.
-- ===========================================================================

create or replace function public.hr_member_of(p_serial text)
returns uuid
language sql stable security definer set search_path = public as $$
  select case when count(*) = 1 then (array_agg(m.id))[1] end
    from public.team_members m
   where coalesce(btrim(m.staff_code), '') <> ''
     and string_to_array(regexp_replace(upper(coalesce(p_serial, '')), '-', '/', 'g'), '/') @> array[upper(btrim(m.staff_code))]
$$;
revoke all on function public.hr_member_of(text) from public, anon, authenticated;

create or replace function public.documents_hr_member()
returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.family = 'hr' and new.member_id is null then
    new.member_id := public.hr_member_of(new.serial);
  end if;
  return new;
end $$;
revoke all on function public.documents_hr_member() from public, anon, authenticated;

create or replace trigger documents_hr_member
  before insert or update of serial, family, member_id on public.documents
  for each row execute function public.documents_hr_member();

update public.documents d
   set member_id = public.hr_member_of(d.serial)
 where d.family = 'hr' and d.member_id is null and public.hr_member_of(d.serial) is not null;

-- END OF HR LETTERS FIND THEIR COLLEAGUE ------------------------------------
select public.functions_tidy();

-- ===========================================================================
-- HEALTH TALK NOTES STAY BETWEEN THE TWO — a talk's note is read by the
-- colleague who asked and the colleague asked, never by Team: Health
-- (2026-10-18)
-- ===========================================================================
-- WHY (Team audit, item 1; the user, 2026-10-18: management never reads a
-- talk's note): `health_team()` sent each talk's note, with both names, to
-- whoever reads Team: Health. Health is sensitive personal data (PDPA 2010);
-- the note is written for the colleague asked alone, who reads it in My
-- records (`health_mine()`, `asked_me`), as the asker does (`asked`).
--
-- WHAT IT CHANGES
--   * `health_team()` sends a talk's names, state and dates, never its note.
--     Everything else it answers is unchanged.
--
-- ORDER: this file, then the pages (an older page draws a note only where
-- one is sent, so it simply draws none). Safe to run twice.
-- Rollback: run the HEALTH CHECK-INS section's `health_team()` again.
-- ===========================================================================

create or replace function public.health_team()
returns jsonb
language plpgsql security definer set search_path = public as $$
declare m public.team_members; h date;
begin
  m := public.ops_me();
  if m.id is null or not public.ops_granted('team.health', 'work') then
    return jsonb_build_object('error', 'denied');
  end if;
  h := public.health_half(public.health_today());
  return jsonb_build_object('half', h, 'half_end', public.health_half_end(h),
    'people', coalesce((select jsonb_agg(jsonb_build_object(
        'id', t.id, 'name', t.name, 'staff_code', t.staff_code, 'designation', t.designation,
        'department', t.department, 'role', t.role,
        'consent', case when c.team_member_id is null then null else jsonb_build_object(
          'agreed_at', c.agreed_at, 'withdrawn_at', c.withdrawn_at) end,
        'checkins', case when c.team_member_id is not null and c.withdrawn_at is null then coalesce((
            select jsonb_agg(public.health_checkin_json(x) order by x.half desc)
              from (select * from public.health_checkins k where k.team_member_id = t.id
                     order by k.half desc limit 12) x), '[]'::jsonb) else '[]'::jsonb end)
        order by t.staff_code nulls last, t.name)
        from public.team_members t
        left join public.health_consents c on c.team_member_id = t.id
       where t.active), '[]'::jsonb),
    'talks', coalesce((select jsonb_agg(jsonb_build_object(
        'id', k.id, 'from', f.name, 'from_id', k.team_member_id, 'with', w.name, 'with_id', k.with_id,
        'status', k.status, 'at', k.created_at, 'closed_at', k.closed_at)
        order by (k.status = 'open') desc, k.created_at desc)
        from public.health_talks k
        join public.team_members f on f.id = k.team_member_id
        join public.team_members w on w.id = k.with_id
       where k.status <> 'withdrawn' and k.created_at > now() - interval '90 days'), '[]'::jsonb));
end $$;
revoke all on function public.health_team() from public, anon, authenticated;
grant execute on function public.health_team() to authenticated;

-- END OF HEALTH TALK NOTES STAY BETWEEN THE TWO -----------------------------
select public.functions_tidy();

-- ===========================================================================
-- HEALTH ANSWERS FOLLOW THE AGREEMENT — Team: Health reads only the check-ins
-- given since the colleague's agreement now standing (2026-10-18)
-- ===========================================================================
-- WHY (Team audit, item 2): withdrawing takes a colleague's answers out of
-- Team: Health, but Agree again showed the last twelve half months once
-- more, answers given before the withdrawal included. Those were given under
-- an agreement the colleague ended; a new agreement covers what is answered
-- under it.
--
-- WHAT IT CHANGES
--   * `health_team()` sends a colleague's check-ins only where the check-in
--     was last saved on or after the current `agreed_at` (a half month's
--     check-in answered again after agreeing is the new answer). The
--     colleague still reads all of their own in My records.
--
-- ORDER: this file, then the pages (nothing on the page changes). Safe to
-- run twice. Rollback: run HEALTH TALK NOTES STAY BETWEEN THE TWO's
-- `health_team()` again.
-- ===========================================================================

create or replace function public.health_team()
returns jsonb
language plpgsql security definer set search_path = public as $$
declare m public.team_members; h date;
begin
  m := public.ops_me();
  if m.id is null or not public.ops_granted('team.health', 'work') then
    return jsonb_build_object('error', 'denied');
  end if;
  h := public.health_half(public.health_today());
  return jsonb_build_object('half', h, 'half_end', public.health_half_end(h),
    'people', coalesce((select jsonb_agg(jsonb_build_object(
        'id', t.id, 'name', t.name, 'staff_code', t.staff_code, 'designation', t.designation,
        'department', t.department, 'role', t.role,
        'consent', case when c.team_member_id is null then null else jsonb_build_object(
          'agreed_at', c.agreed_at, 'withdrawn_at', c.withdrawn_at) end,
        'checkins', case when c.team_member_id is not null and c.withdrawn_at is null then coalesce((
            select jsonb_agg(public.health_checkin_json(x) order by x.half desc)
              from (select * from public.health_checkins k
                     where k.team_member_id = t.id and k.updated_at >= c.agreed_at
                     order by k.half desc limit 12) x), '[]'::jsonb) else '[]'::jsonb end)
        order by t.staff_code nulls last, t.name)
        from public.team_members t
        left join public.health_consents c on c.team_member_id = t.id
       where t.active), '[]'::jsonb),
    'talks', coalesce((select jsonb_agg(jsonb_build_object(
        'id', k.id, 'from', f.name, 'from_id', k.team_member_id, 'with', w.name, 'with_id', k.with_id,
        'status', k.status, 'at', k.created_at, 'closed_at', k.closed_at)
        order by (k.status = 'open') desc, k.created_at desc)
        from public.health_talks k
        join public.team_members f on f.id = k.team_member_id
        join public.team_members w on w.id = k.with_id
       where k.status <> 'withdrawn' and k.created_at > now() - interval '90 days'), '[]'::jsonb));
end $$;
revoke all on function public.health_team() from public, anon, authenticated;
grant execute on function public.health_team() to authenticated;

-- END OF HEALTH ANSWERS FOLLOW THE AGREEMENT ---------------------------------
select public.functions_tidy();

-- ===========================================================================
-- TEAM HEALTH IS AN ADMIN'S — Team: Health opens for an admin alone, behind
-- the Performance master code (2026-10-18)
-- ===========================================================================
-- WHY (Team audit, item 11; the user: "only admin can view everyone else
-- health data"): `health_team()` asked only the granted part `team.health`,
-- which the group panel could give any group, and asked no code, while the
-- Performance reviews, less sensitive, are behind the master code.
--
-- WHAT IT CHANGES
--   * `health_check(p_token)`: null for an active admin holding a live
--     Performance unlock (`perf_unlock`, the master code, 15 minutes from
--     its last use, the same unlock Performance extends), else `denied`
--     (not an admin), `no-code` (no master code set) or `code-needed`.
--   * `health_team(p_token)` asks it first; everything it answers is as
--     before. The old `health_team()` stays for a page loaded before this
--     one and answers `code-needed` alone (no drop: the connector holds a
--     drop), so it reads nothing.
--   * `team.health` is no longer offered to a group; a group or colleague
--     holding it has it taken off their access map (it opened nothing for
--     anybody but an admin from now on).
--
-- ORDER: this file, then the pages (an old page meets `code-needed` and
-- reads Unable to load until it is reloaded). Safe to run twice.
-- Rollback: run HEALTH ANSWERS FOLLOW THE AGREEMENT's `health_team()`
-- again; `revoke` and `drop function public.health_team(text)` and
-- `public.health_check(text)` in the SQL Editor. The access maps are not
-- given the part back.
-- ===========================================================================

create or replace function public.health_check(p_token text)
returns text
language plpgsql security definer set search_path = public as $$
declare m public.team_members; n integer;
begin
  m := public.ops_me();
  if m.id is null then return 'not-team'; end if;
  if not (m.is_admin or m.role = 'admin') then return 'denied'; end if;
  if not public.perf_code_set() then return 'no-code'; end if;
  update public.perf_unlocks set expires_at = now() + interval '15 minutes'
   where token_hash = encode(sha256(convert_to(coalesce(p_token, ''), 'UTF8')), 'hex')
     and team_member_id = m.id and expires_at > now();
  get diagnostics n = row_count;
  if n = 0 then return 'code-needed'; end if;
  return null;
end $$;
revoke all on function public.health_check(text) from public, anon, authenticated;

create or replace function public.health_team(p_token text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare m public.team_members; h date; e text;
begin
  m := public.ops_me();
  e := public.health_check(p_token);
  if e is not null then return jsonb_build_object('error', e); end if;
  h := public.health_half(public.health_today());
  return jsonb_build_object('half', h, 'half_end', public.health_half_end(h),
    'people', coalesce((select jsonb_agg(jsonb_build_object(
        'id', t.id, 'name', t.name, 'staff_code', t.staff_code, 'designation', t.designation,
        'department', t.department, 'role', t.role,
        'consent', case when c.team_member_id is null then null else jsonb_build_object(
          'agreed_at', c.agreed_at, 'withdrawn_at', c.withdrawn_at) end,
        'checkins', case when c.team_member_id is not null and c.withdrawn_at is null then coalesce((
            select jsonb_agg(public.health_checkin_json(x) order by x.half desc)
              from (select * from public.health_checkins k
                     where k.team_member_id = t.id and k.updated_at >= c.agreed_at
                     order by k.half desc limit 12) x), '[]'::jsonb) else '[]'::jsonb end)
        order by t.staff_code nulls last, t.name)
        from public.team_members t
        left join public.health_consents c on c.team_member_id = t.id
       where t.active), '[]'::jsonb),
    'talks', coalesce((select jsonb_agg(jsonb_build_object(
        'id', k.id, 'from', f.name, 'from_id', k.team_member_id, 'with', w.name, 'with_id', k.with_id,
        'status', k.status, 'at', k.created_at, 'closed_at', k.closed_at)
        order by (k.status = 'open') desc, k.created_at desc)
        from public.health_talks k
        join public.team_members f on f.id = k.team_member_id
        join public.team_members w on w.id = k.with_id
       where k.status <> 'withdrawn' and k.created_at > now() - interval '90 days'), '[]'::jsonb));
end $$;
revoke all on function public.health_team(text) from public, anon, authenticated;
grant execute on function public.health_team(text) to authenticated;

create or replace function public.health_team()
returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object('error', 'code-needed')
$$;
revoke all on function public.health_team() from public, anon, authenticated;
grant execute on function public.health_team() to authenticated;

update public.team_roles set access = access - 'team.health' where access ? 'team.health';
update public.team_members set access = access - 'team.health' where access ? 'team.health';

-- END OF TEAM HEALTH IS AN ADMIN'S ------------------------------------------
select public.functions_tidy();

-- ===========================================================================
-- HEALTH DATA KEPT FOR A TIME — health check-ins leave after two years, and
-- a colleague's health data six months after they left, each a Business
-- setting (2026-10-18)
-- ===========================================================================
-- WHY (Team audit, item 12; PDPA 2010: keep personal data no longer than its
-- purpose needs): health check-ins, agreements, their log and talks were kept
-- for ever; only an admin's Delete their data on a removal erased them.
--
-- WHAT IT CHANGES
--   * Two Business settings from a day on (`app_settings`, Settings: Portal,
--     Health data kept; `team.settings`): `health_keep_months` (24, 6 to
--     120) and `health_leaver_months` (6, 1 to 60), seeded once.
--   * `app_settings_set` takes them (restated whole, nothing else changed).
--   * `privacy_retention(p_now)` (pg_cron `privacy-retention`, the 2nd of
--     each month), besides what it did: removes every check-in for a half
--     month that began more than `health_keep_months` before today (MYT);
--     and for a colleague no longer active who was removed or whose access
--     expired more than `health_leaver_months` ago, their check-ins,
--     agreement, its log and every talk they asked or were asked.
--
-- ORDER: this file, then the pages (the Settings row reads the two figures;
-- an older page shows no row). Safe to run twice. The connector holds a
-- statement holding `delete`: `privacy_retention` is run in the SQL Editor.
-- Rollback: run PERSONAL DATA KEPT FOR A TIME's `privacy_retention` and
-- SINGAPORE DOLLAR's `app_settings_set` again; the two settings stay unread.
-- What was removed is not brought back (the nightly dumps hold it 90 days).
-- ===========================================================================

insert into public.app_settings (key, from_date, value)
select 'health_keep_months', date '2023-08-14', 24
 where not exists (select 1 from public.app_settings s where s.key = 'health_keep_months');
insert into public.app_settings (key, from_date, value)
select 'health_leaver_months', date '2023-08-14', 6
 where not exists (select 1 from public.app_settings s where s.key = 'health_leaver_months');

create or replace function public.app_settings_set(p_from date, p_values jsonb)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me public.team_members; v_k text; v_v numeric; v_was numeric; v_name text; v_unit text; v_pre text;
  v_today date := (now() at time zone 'Asia/Kuala_Lumpur')::date;
  v_keys constant text[] := array['lead_followup_hours', 'proposal_followup_days', 'sst_pct',
    'term_1_3', 'term_4_5', 'term_6_11', 'term_12_23', 'term_18_23', 'term_24', 'report_due_days', 'revision_due_days',
    'ai_price_in', 'ai_price_out', 'meta_checks', 'approval_reminder_days', 'ai_price_search',
    'reach_allowance_pct', 'priority_urgent_hours', 'priority_high_hours', 'priority_medium_hours',
    'task_remind_hours', 'task_start_days', 'quote_valid_days', 'details_form_days', 'wa_repeat_hours',
    'bench_cpr_low', 'bench_cpr_mid', 'bench_cpr_high', 'bench_cpr_top', 'bench_msg_min', 'bench_msg_target', 'bench_msg_max',
    'bench_form_min', 'bench_form_target', 'bench_form_max', 'bench_cpm_min', 'bench_cpm_max', 'bench_cpl_rise',
    'bench_reels_share', 'bench_ad_spend_pct', 'bench_adset_daily', 'vic_lead_followup_hours', 'vic_proposal_followup_days', 'fx_sgd',
    'health_keep_months', 'health_leaver_months'];
  v_moved text[] := '{}';
begin
  if not public.ops_granted('team.settings', 'work') then return jsonb_build_object('error', 'denied'); end if;
  v_me := public.ops_me();
  if p_from is null or p_from < v_today then return jsonb_build_object('error', 'past', 'today', v_today); end if;
  if jsonb_typeof(p_values) is distinct from 'object' then return jsonb_build_object('error', 'bad-value'); end if;
  for v_k in select jsonb_object_keys(p_values) loop
    if not (v_k = any(v_keys)) or jsonb_typeof(p_values -> v_k) <> 'number' then
      return jsonb_build_object('error', 'bad-value', 'key', v_k);
    end if;
    v_v := (p_values ->> v_k)::numeric;
    if round(v_v, case when v_k = 'fx_sgd' then 4 else 2 end) <> v_v
       or (v_k = 'fx_sgd' and (v_v < 0.5 or v_v > 10))
       or (v_k in ('lead_followup_hours', 'vic_lead_followup_hours') and (v_v < 1 or v_v > 720 or v_v <> trunc(v_v)))
       or (v_k in ('proposal_followup_days', 'vic_proposal_followup_days') and (v_v < 1 or v_v > 365 or v_v <> trunc(v_v)))
       or (v_k = 'report_due_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'revision_due_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'approval_reminder_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'sst_pct' and (v_v < 0 or v_v > 100))
       or (v_k like 'term_%' and (v_v < -100 or v_v > 100))
       or (v_k like 'ai_price_%' and (v_v < 0 or v_v > 1000))
       or (v_k = 'meta_checks' and v_v not in (0, 1))
       or (v_k = 'reach_allowance_pct' and (v_v < 0 or v_v > 5))
       or (v_k like 'priority_%_hours' and (v_v < 1 or v_v > 720 or v_v <> trunc(v_v)))
       or (v_k = 'task_remind_hours' and (v_v < 0 or v_v > 24 or v_v <> trunc(v_v)))
       or (v_k = 'task_start_days' and (v_v < 0 or v_v > 30 or v_v <> trunc(v_v)))
       or (v_k in ('quote_valid_days', 'details_form_days') and (v_v < 1 or v_v > 90 or v_v <> trunc(v_v)))
       or (v_k = 'wa_repeat_hours' and (v_v < 0 or v_v > 168 or v_v <> trunc(v_v)))
       or (v_k = 'health_keep_months' and (v_v < 6 or v_v > 120 or v_v <> trunc(v_v)))
       or (v_k = 'health_leaver_months' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k in ('bench_reels_share') and (v_v < 0 or v_v > 100))
       or (v_k = 'bench_ad_spend_pct' and (v_v < 1 or v_v > 100))
       or (v_k = 'bench_cpl_rise' and (v_v < -100 or v_v > 100))
       or (v_k like 'bench_%' and v_k not in ('bench_reels_share', 'bench_ad_spend_pct', 'bench_cpl_rise') and (v_v < 0 or v_v > 10000)) then
      return jsonb_build_object('error', 'bad-value', 'key', v_k);
    end if;
  end loop;
  for v_k in select jsonb_object_keys(p_values) loop
    v_v := (p_values ->> v_k)::numeric;
    v_was := public.app_setting(v_k, p_from);
    if v_was is distinct from v_v then
      insert into public.app_settings (key, from_date, value, set_by, set_at)
      values (v_k, p_from, v_v, v_me.id, now())
      on conflict (key, from_date) do update set value = excluded.value, set_by = excluded.set_by, set_at = now();
      v_name := case v_k when 'lead_followup_hours' then 'A lead waits' when 'proposal_followup_days' then 'A proposal waits'
        when 'vic_lead_followup_hours' then 'A VIC lead waits' when 'vic_proposal_followup_days' then 'A VIC proposal waits'
        when 'sst_pct' then 'SST' when 'term_1_3' then '1 to 3 months' when 'term_4_5' then '4 and 5 months'
        when 'term_6_11' then '6 to 11 months' when 'term_12_23' then '12 to 17 months' when 'term_18_23' then '18 to 23 months' when 'term_24' then '24 months and more'
        when 'revision_due_days' then 'Revision due' when 'ai_price_in' then 'AI input, a million tokens'
        when 'ai_price_out' then 'AI output, a million tokens' when 'ai_price_search' then 'AI web searches, a thousand' when 'meta_checks' then 'Meta checks'
        when 'approval_reminder_days' then 'Approval reminder' when 'reach_allowance_pct' then 'Reach allowance'
        when 'priority_urgent_hours' then 'Urgent deadline' when 'priority_high_hours' then 'High deadline'
        when 'priority_medium_hours' then 'Medium deadline' when 'task_remind_hours' then 'Task reminders'
        when 'task_start_days' then 'Not started reminder' when 'quote_valid_days' then 'Quotation validity' when 'details_form_days' then 'Details form open'
        when 'wa_repeat_hours' then 'WhatsApp sent again'
        when 'bench_cpr_low' then 'Property cost per result, tier 1 from' when 'bench_cpr_mid' then 'Property cost per result, tier 2 from'
        when 'bench_cpr_high' then 'Property cost per result, tier 3 from' when 'bench_cpr_top' then 'Property cost per result, tier 3 up to'
        when 'bench_msg_min' then 'Messaging cost per result, low' when 'bench_msg_target' then 'Messaging cost per result, target'
        when 'bench_msg_max' then 'Messaging cost per result, high' when 'bench_form_min' then 'Lead form cost per result, low'
        when 'bench_form_target' then 'Lead form cost per result, target' when 'bench_form_max' then 'Lead form cost per result, high'
        when 'bench_cpm_min' then 'Cost per 1,000 impressions, low' when 'bench_cpm_max' then 'Cost per 1,000 impressions, high'
        when 'bench_cpl_rise' then 'Cost per lead rise a year' when 'bench_reels_share' then 'Reels share of impressions'
        when 'bench_ad_spend_pct' then 'Ad spend of the budget' when 'bench_adset_daily' then 'Daily budget an ad set, at least'
        when 'fx_sgd' then 'Singapore dollar rate'
        when 'health_keep_months' then 'Health check-ins kept' when 'health_leaver_months' then 'A leaver''s health data kept'
        else 'Report due' end;
      v_pre := case when v_k = 'fx_sgd' then 'RM ' when v_k like 'ai_price_%' then 'US$' when v_k like 'bench_%' and v_k not in ('bench_cpl_rise', 'bench_reels_share', 'bench_ad_spend_pct') then 'RM ' else '' end;
      v_unit := case when v_k = 'fx_sgd' then ' to S$1' when v_k in ('lead_followup_hours', 'vic_lead_followup_hours', 'task_remind_hours', 'wa_repeat_hours') or v_k like 'priority_%_hours' then ' hours'
        when v_k in ('proposal_followup_days', 'vic_proposal_followup_days', 'report_due_days', 'revision_due_days', 'approval_reminder_days', 'task_start_days', 'quote_valid_days', 'details_form_days') then ' days'
        when v_k in ('health_keep_months', 'health_leaver_months') then ' months'
        when v_pre <> '' then '' else '%' end;
      insert into public.activity_log (actor, action, subject, detail)
      values (coalesce(v_me.name, 'admin'), 'team.changed', 'Settings',
              v_name || ': ' || case when v_k = 'meta_checks' then
                case when v_was = 1 then 'On' else 'Off' end || ' → ' || case when v_v = 1 then 'On' else 'Off' end ||
                ' · from ' || public.register_day(p_from) else '' end ||
              case when v_k = 'meta_checks' then '' else coalesce(v_pre ||
              trim(to_char(v_was, case when v_k = 'fx_sgd' then 'FM999999990.9999' else 'FM999999990.99' end), '.') || v_unit, 'not set') || ' → ' || v_pre ||
              trim(to_char(v_v, case when v_k = 'fx_sgd' then 'FM999999990.9999' else 'FM999999990.99' end), '.') || v_unit ||
              ' · from ' || public.register_day(p_from) end);
      v_moved := v_moved || v_k;
    end if;
  end loop;
  return public.app_settings_read() || jsonb_build_object('changed', to_jsonb(v_moved));
end $$;
revoke all on function public.app_settings_set(date, jsonb) from public, anon;
grant execute on function public.app_settings_set(date, jsonb) to authenticated;

create or replace function public.privacy_retention(p_now timestamptz default now())
returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_wa integer := 0; v_act integer := 0; v_hc integer := 0; v_hl integer := 0;
  v_today date := (p_now at time zone 'Asia/Kuala_Lumpur')::date;
  v_keep integer := coalesce(public.app_setting('health_keep_months', (p_now at time zone 'Asia/Kuala_Lumpur')::date), 24)::integer;
  v_left integer := coalesce(public.app_setting('health_leaver_months', (p_now at time zone 'Asia/Kuala_Lumpur')::date), 6)::integer;
  v_gone uuid[];
begin
  update public.wa_outbox o
     set to_number = '', to_name = null, params = '[]'::jsonb, button = null
   where o.created_at < p_now - interval '12 months'
     and o.state not in ('queued', 'sending')
     and (o.to_number <> '' or o.to_name is not null or o.params <> '[]'::jsonb or o.button is not null);
  get diagnostics v_wa = row_count;
  delete from public.activity_log a where a.created_at < p_now - interval '3 years';
  get diagnostics v_act = row_count;
  delete from public.health_checkins k where k.half < v_today - make_interval(months => v_keep);
  get diagnostics v_hc = row_count;
  select coalesce(array_agg(m.id), '{}') into v_gone from public.team_members m
   where not m.active and coalesce(m.removed_at, m.expired_at) < p_now - make_interval(months => v_left);
  if array_length(v_gone, 1) > 0 then
    delete from public.health_checkins k where k.team_member_id = any(v_gone);
    get diagnostics v_hl = row_count;
    delete from public.health_talks t where t.team_member_id = any(v_gone) or t.with_id = any(v_gone);
    delete from public.health_log l where l.team_member_id = any(v_gone);
    delete from public.health_consents c where c.team_member_id = any(v_gone);
  end if;
  return jsonb_build_object('whatsapp_cleared', v_wa, 'activity_removed', v_act,
    'health_checkins_removed', v_hc + v_hl, 'health_leavers', coalesce(array_length(v_gone, 1), 0));
end $$;
revoke all on function public.privacy_retention(timestamptz) from public, anon, authenticated;

-- END OF HEALTH DATA KEPT FOR A TIME ----------------------------------------
select public.functions_tidy();

-- ===========================================================================
-- HEALTH TERMS ARE VERSIONED — the words a colleague agrees to are kept in
-- one place, each version whole, and a new version asks everyone again
-- (2026-10-18)
-- ===========================================================================
-- WHY (Team audit, item 17): the agreement card's words lived in
-- js/health.js and every agreement was stored as wording 1, so a change to
-- the words would have stood on agreements given to other words (PDPA 2010:
-- consent is to what was shown).
--
-- WHAT IT CHANGES
--   * `health_wordings` (version, care, terms, made_at; RLS on, no policy, no
--     grant): every version of the card's words, the company's lines
--     (`care`) and What you agree to (`terms`). Version 1, the words the
--     page has shown since 2026-10-07, is seeded once into an empty table.
--     A change of words is a migration adding the next version, never an
--     edit of one given.
--   * `health_wording_now()`: the latest version (an internal helper).
--   * `health_agreed(p_member)` stands only on an agreement to the latest
--     version: a new version pauses the check-ins, the talks and the
--     reminders, and takes the answers out of Team: Health, until the
--     colleague agrees to it.
--   * `health_mine()` also sends the latest version's words (`wording`), so
--     the page draws the card from the database alone.
--   * `health_consent(p_on, p_wording)`: agreeing names the version the page
--     showed, refused `stale-wording` where it is no longer the latest; the
--     version is kept on the agreement and its log line. The old
--     `health_consent(p_on)` stays for a page loaded before this one and
--     agrees to version 1 alone (no drop: the connector holds a drop).
--   * `health_team(p_token)` marks each agreement `current` and sends answers
--     only while `health_agreed()` stands.
--
-- ORDER: this file, then the pages (the page draws the words from
-- `health_mine()`). Safe to run twice.
-- Rollback: run HEALTH CHECK-INS' `health_agreed`, `health_mine` and
-- `health_consent`, and TEAM HEALTH IS AN ADMIN'S `health_team(p_token)`,
-- again; the table and `health_consent(boolean, integer)` may then be
-- dropped in the SQL Editor.
-- ===========================================================================

create table if not exists public.health_wordings (
  version   integer primary key check (version > 0),
  care      jsonb not null check (jsonb_typeof(care) = 'array'),
  terms     jsonb not null check (jsonb_typeof(terms) = 'array'),
  made_at   timestamptz not null default now()
);
alter table public.health_wordings enable row level security;
revoke all on table public.health_wordings from public, anon, authenticated;

insert into public.health_wordings (version, care, terms, made_at)
select 1, jsonb_build_array(
    'Life at work and life at home both shape how you feel, in body and in mind, and we care about all of it. Every two weeks, take a quiet moment to tell us how you really are.',
    'Please answer honestly. There are no right or wrong answers, only a true picture that helps us look after you. If something feels heavy, ask for a talk: reaching out early is a strength, and we would always rather hear from you and help.'),
  jsonb_build_array(
    'Every two weeks: five questions on your body, mind, sleep, energy and workload, each from 1 to 5, with a note if you wish.',
    'ADspace management reads your answers with your name, only to understand how you are and to support you.',
    'Your answers are never part of your performance review.',
    'You can withdraw at any time here, and your answers leave management''s view.'),
  timestamptz '2026-10-07 00:00:00+08'
 where not exists (select 1 from public.health_wordings);

create or replace function public.health_wording_now()
returns integer language sql stable security definer set search_path = public as $$
  select coalesce(max(w.version), 1) from public.health_wordings w
$$;
revoke all on function public.health_wording_now() from public, anon, authenticated;

create or replace function public.health_agreed(p_member uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.health_consents c
                  where c.team_member_id = p_member and c.withdrawn_at is null
                    and c.wording >= public.health_wording_now())
$$;
revoke all on function public.health_agreed(uuid) from public, anon, authenticated;

create or replace function public.health_mine()
returns jsonb
language plpgsql security definer set search_path = public as $$
declare m public.team_members; g jsonb; c public.health_consents; h date;
begin
  g := public.perf_mine_gate();
  if g is not null then return g; end if;
  m := public.ops_me();
  select * into c from public.health_consents where team_member_id = m.id;
  h := public.health_half(public.health_today());
  return jsonb_build_object(
    'consent', case when c.team_member_id is null then null else jsonb_build_object(
      'agreed_at', c.agreed_at, 'withdrawn_at', c.withdrawn_at, 'wording', c.wording) end,
    'wording', (select jsonb_build_object('version', w.version, 'care', w.care, 'terms', w.terms, 'made_at', w.made_at)
                  from public.health_wordings w where w.version = public.health_wording_now()),
    'half', h, 'half_end', public.health_half_end(h),
    'history', coalesce((select jsonb_agg(public.health_checkin_json(x) order by x.half desc)
                           from (select * from public.health_checkins k
                                  where k.team_member_id = m.id order by k.half desc limit 12) x), '[]'::jsonb),
    'asked', coalesce((select jsonb_agg(jsonb_build_object('id', t.id, 'with', w.name, 'with_id', t.with_id,
                         'note', t.note, 'status', t.status, 'at', t.created_at, 'closed_at', t.closed_at)
                         order by (t.status = 'open') desc, t.created_at desc)
                         from (select * from public.health_talks x where x.team_member_id = m.id
                                order by (x.status = 'open') desc, x.created_at desc limit 20) t
                         join public.team_members w on w.id = t.with_id), '[]'::jsonb),
    'asked_me', coalesce((select jsonb_agg(jsonb_build_object('id', t.id, 'from', f.name, 'from_id', t.team_member_id,
                            'note', t.note, 'status', t.status, 'at', t.created_at, 'closed_at', t.closed_at)
                            order by (t.status = 'open') desc, t.created_at desc)
                            from (select * from public.health_talks x where x.with_id = m.id and x.status <> 'withdrawn'
                                   order by (x.status = 'open') desc, x.created_at desc limit 20) t
                            join public.team_members f on f.id = t.team_member_id), '[]'::jsonb),
    'colleagues', coalesce((select jsonb_agg(jsonb_build_object('id', t.id, 'name', t.name, 'staff_code', t.staff_code)
                              order by t.staff_code nulls last, t.name)
                              from public.team_members t where t.active and t.id <> m.id), '[]'::jsonb));
end $$;
revoke all on function public.health_mine() from public, anon, authenticated;
grant execute on function public.health_mine() to authenticated;

create or replace function public.health_consent(p_on boolean, p_wording integer)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare m public.team_members; g jsonb; n integer; v integer;
begin
  g := public.perf_mine_gate();
  if g is not null then return g; end if;
  m := public.ops_me();
  if coalesce(p_on, false) then
    v := public.health_wording_now();
    if p_wording is distinct from v then return jsonb_build_object('error', 'stale-wording', 'version', v); end if;
    insert into public.health_consents (team_member_id, agreed_at, wording, withdrawn_at, updated_at)
    values (m.id, now(), v, null, now())
    on conflict (team_member_id) do update
       set agreed_at = now(), wording = v, withdrawn_at = null, updated_at = now();
    insert into public.health_log (team_member_id, kind, wording) values (m.id, 'agreed', v);
  else
    update public.health_consents set withdrawn_at = now(), updated_at = now()
     where team_member_id = m.id and withdrawn_at is null;
    get diagnostics n = row_count;
    if n = 0 then return jsonb_build_object('error', 'not-agreed'); end if;
    insert into public.health_log (team_member_id, kind) values (m.id, 'withdrawn');
  end if;
  return public.health_mine();
end $$;
revoke all on function public.health_consent(boolean, integer) from public, anon, authenticated;
grant execute on function public.health_consent(boolean, integer) to authenticated;

create or replace function public.health_consent(p_on boolean)
returns jsonb
language sql security definer set search_path = public as $$
  select public.health_consent(p_on, 1)
$$;
revoke all on function public.health_consent(boolean) from public, anon, authenticated;
grant execute on function public.health_consent(boolean) to authenticated;

create or replace function public.health_team(p_token text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare m public.team_members; h date; e text;
begin
  m := public.ops_me();
  e := public.health_check(p_token);
  if e is not null then return jsonb_build_object('error', e); end if;
  h := public.health_half(public.health_today());
  return jsonb_build_object('half', h, 'half_end', public.health_half_end(h),
    'people', coalesce((select jsonb_agg(jsonb_build_object(
        'id', t.id, 'name', t.name, 'staff_code', t.staff_code, 'designation', t.designation,
        'department', t.department, 'role', t.role,
        'consent', case when c.team_member_id is null then null else jsonb_build_object(
          'agreed_at', c.agreed_at, 'withdrawn_at', c.withdrawn_at,
          'current', c.wording >= public.health_wording_now()) end,
        'checkins', case when public.health_agreed(t.id) then coalesce((
            select jsonb_agg(public.health_checkin_json(x) order by x.half desc)
              from (select * from public.health_checkins k
                     where k.team_member_id = t.id and k.updated_at >= c.agreed_at
                     order by k.half desc limit 12) x), '[]'::jsonb) else '[]'::jsonb end)
        order by t.staff_code nulls last, t.name)
        from public.team_members t
        left join public.health_consents c on c.team_member_id = t.id
       where t.active), '[]'::jsonb),
    'talks', coalesce((select jsonb_agg(jsonb_build_object(
        'id', k.id, 'from', f.name, 'from_id', k.team_member_id, 'with', w.name, 'with_id', k.with_id,
        'status', k.status, 'at', k.created_at, 'closed_at', k.closed_at)
        order by (k.status = 'open') desc, k.created_at desc)
        from public.health_talks k
        join public.team_members f on f.id = k.team_member_id
        join public.team_members w on w.id = k.with_id
       where k.status <> 'withdrawn' and k.created_at > now() - interval '90 days'), '[]'::jsonb));
end $$;
revoke all on function public.health_team(text) from public, anon, authenticated;
grant execute on function public.health_team(text) to authenticated;

-- END OF HEALTH TERMS ARE VERSIONED -----------------------------------------
select public.functions_tidy();

-- ===========================================================================
-- A CHECK-IN KEEPS ITS HALF MONTH — a health check-in is saved into the half
-- month its sheet showed, or refused in words (2026-10-18)
-- ===========================================================================
-- WHY (Team audit, item 18): `health_checkin_save` filed the answers under
-- the half month of the moment they reached the database, so a sheet opened
-- for 1 to 15 October and saved after midnight on the 16th filed them, unseen,
-- under 16 to 31 October.
--
-- WHAT IT CHANGES
--   * `health_checkin_save(p_scores, p_note, p_half)`: the page names the
--     half month its sheet showed; one that is no longer the current half is
--     refused `stale-half` with the current one, and nothing is kept. Every
--     other refusal is as before.
--   * The old `health_checkin_save(p_scores, p_note)` stays for a page loaded
--     before this one and saves into the current half, as before (no drop:
--     the connector holds a drop).
--
-- ORDER: this file, then the pages. Safe to run twice.
-- Rollback: `revoke` and `drop function public.health_checkin_save(jsonb,
-- text, date)` in the SQL Editor; the page then reads "This needs a database
-- update" on Save until it is rolled back too.
-- ===========================================================================

create or replace function public.health_checkin_save(p_scores jsonb, p_note text, p_half date)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare m public.team_members; g jsonb; k text; v numeric; h date;
begin
  g := public.perf_mine_gate();
  if g is not null then return g; end if;
  m := public.ops_me();
  if not public.health_agreed(m.id) then return jsonb_build_object('error', 'no-consent'); end if;
  h := public.health_half(public.health_today());
  if p_half is distinct from h then
    return jsonb_build_object('error', 'stale-half', 'half', h, 'half_end', public.health_half_end(h));
  end if;
  if jsonb_typeof(p_scores) is distinct from 'object' then return jsonb_build_object('error', 'incomplete'); end if;
  foreach k in array array['body', 'mind', 'sleep', 'energy', 'workload'] loop
    if jsonb_typeof(p_scores -> k) is distinct from 'number' then
      return jsonb_build_object('error', 'incomplete', 'item', k);
    end if;
    v := (p_scores ->> k)::numeric;
    if v < 1 or v > 5 or v <> trunc(v) then return jsonb_build_object('error', 'bad-score', 'item', k); end if;
  end loop;
  if char_length(coalesce(p_note, '')) > 1000 then return jsonb_build_object('error', 'too-long'); end if;
  insert into public.health_checkins (team_member_id, half, body, mind, sleep, energy, workload, note)
  values (m.id, h, (p_scores ->> 'body')::smallint, (p_scores ->> 'mind')::smallint,
          (p_scores ->> 'sleep')::smallint, (p_scores ->> 'energy')::smallint,
          (p_scores ->> 'workload')::smallint, nullif(btrim(coalesce(p_note, '')), ''))
  on conflict (team_member_id, half) do update
     set body = excluded.body, mind = excluded.mind, sleep = excluded.sleep, energy = excluded.energy,
         workload = excluded.workload, note = excluded.note, updated_at = now();
  return public.health_mine();
end $$;
revoke all on function public.health_checkin_save(jsonb, text, date) from public, anon, authenticated;
grant execute on function public.health_checkin_save(jsonb, text, date) to authenticated;

-- END OF A CHECK-IN KEEPS ITS HALF MONTH ------------------------------------
select public.functions_tidy();

-- ===========================================================================
-- A HALF MONTH'S REMINDER ALWAYS COMES — the health reminder's days before a
-- half month ends are held to the days the half has (2026-10-18)
-- ===========================================================================
-- WHY (Team audit, item 19): `remind_before_days` may be up to 14, and the
-- health reminder went out that many days before the half month's end. The
-- second half of February runs 13 days (16 to 28 February; 14 in a leap
-- year), so at 13 or 14 its day fell in the first half and nobody was
-- reminded to check in for it.
--
-- WHAT IT CHANGES
--   * `my_hr_remind`: the days before a half month's end are the lesser of
--     the setting and the days from the half's first day to its last, so the
--     reminder comes on the half's first day at the latest. The month's
--     reflection reminder and everything else are as before.
--
-- ORDER: this file alone (no page reads it). Safe to run twice.
-- Rollback: run MY HR REMINDERS' `my_hr_remind` again.
-- ===========================================================================

create or replace function public.my_hr_remind(p_today date default null)
returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_today    date := coalesce(p_today, public.health_today());
  v_before   integer := coalesce(public.perf_setting('remind_before_days', coalesce(p_today, public.health_today())), 3)::integer;
  v_again    integer := coalesce(public.perf_setting('remind_again_days', coalesce(p_today, public.health_today())), 3)::integer;
  v_month    date := date_trunc('month', coalesce(p_today, public.health_today()))::date;
  v_last     date;
  v_half     date;
  v_hbefore  integer;
  v_after    boolean;
  v_end_day  boolean;
  v_half_day boolean;
  v_self     boolean;
  v_rlast    boolean;
  v_refl     boolean;
  v_health   boolean;
  v_parts    text[];
  v_said     text;
  v_title    text;
  m          record;
  n          integer := 0;
begin
  v_last := (v_month - interval '1 month')::date;
  v_half := public.health_half(v_today);
  v_after := extract(day from v_today) = 1 or (v_again > 0 and extract(day from v_today) = 1 + v_again);
  v_end_day := v_before > 0 and v_today = (v_month + interval '1 month' - interval '1 day')::date - v_before;
  /* A half month is 13 to 16 days long: the days before its end are never
     more than the days it has, so a February's second half is reminded on
     its first day at the latest, never not at all. */
  v_hbefore := least(v_before, public.health_half_end(v_half) - v_half);
  v_half_day := v_before > 0 and v_today = public.health_half_end(v_half) - v_hbefore;
  if not (v_after or v_end_day or v_half_day) then return 0; end if;
  for m in select t.id from public.team_members t where t.active order by t.id loop
    v_self := false; v_rlast := false; v_refl := false; v_health := false;
    if public.perf_reviewed(m.id) then
      if v_after then
        v_self := public.perf_self_open(m.id, v_last) is null
                  and not exists (select 1 from public.perf_self_ratings s
                                   where s.team_member_id = m.id and s.period = v_last);
        v_rlast := public.perf_reflection_open(m.id, v_last) is null
                   and not exists (select 1 from public.perf_reflections f
                                    where f.team_member_id = m.id and f.period = v_last
                                      and coalesce(f.proud, f.hard, f.learn) is not null);
      end if;
      if v_end_day then
        v_refl := public.perf_reflection_open(m.id, v_month) is null
                  and not exists (select 1 from public.perf_reflections f
                                   where f.team_member_id = m.id and f.period = v_month
                                     and coalesce(f.proud, f.hard, f.learn) is not null);
      end if;
    end if;
    if v_half_day then
      v_health := public.health_agreed(m.id)
                  and not exists (select 1 from public.health_checkins k
                                   where k.team_member_id = m.id and k.half = v_half);
    end if;
    v_parts := array[]::text[];
    if v_self and v_rlast then
      v_parts := v_parts || ('rate yourself and write your reflection for ' || public.perf_month_word(v_last));
    elsif v_self then
      v_parts := v_parts || ('rate yourself for ' || public.perf_month_word(v_last));
    elsif v_rlast then
      v_parts := v_parts || ('write your reflection for ' || public.perf_month_word(v_last));
    end if;
    if v_refl then v_parts := v_parts || ('write your ' || public.perf_month_word(v_month) || ' reflection'); end if;
    if v_health then v_parts := v_parts || 'check in on your health'::text; end if;
    if cardinality(v_parts) = 0 then continue; end if;
    if cardinality(v_parts) = 1 and v_refl then
      v_title := 'Write your reflection for ' || public.perf_month_word(v_month) || ' before the month ends.';
    elsif cardinality(v_parts) = 1 and v_health then
      v_title := 'Check in on your health by ' || to_char(public.health_half_end(v_half), 'FMDD FMMonth') || '.';
    else
      v_said := case cardinality(v_parts)
                  when 1 then v_parts[1]
                  when 2 then v_parts[1] || ' and ' || v_parts[2]
                  else v_parts[1] || ', ' || v_parts[2] || ' and ' || v_parts[3] end;
      v_title := upper(left(v_said, 1)) || substr(v_said, 2) || '.';
    end if;
    insert into public.ops_notifications (team_member_id, task_id, kind, title, body, dedupe_key)
    values (m.id, null,
            case when v_self then 'perf.remind' when v_rlast or v_refl then 'perf.reflect' else 'health.remind' end,
            v_title, null, 'myhr.remind.' || m.id || '.' || v_today)
    on conflict (dedupe_key) do nothing;
    n := n + 1;
  end loop;
  return n;
end $$;
revoke all on function public.my_hr_remind(date) from public, anon, authenticated;

-- END OF A HALF MONTH'S REMINDER ALWAYS COMES -------------------------------
select public.functions_tidy();

-- ===========================================================================
-- A LEAVER'S TALKS ARE CLOSED — a colleague set inactive, or whose access
-- expires, leaves no health talk open (2026-10-18)
-- ===========================================================================
-- WHY (Team audit, item 20): `team_members_leaving` withdrew the open talks
-- asked of a colleague only when they were removed. Set inactive, or stood
-- down by `team_expire_access`, they kept talks open that nobody could hold:
-- a colleague's request waited on someone who had left, and the leaver's own
-- request still read "would like to talk" to the colleague asked.
--
-- WHAT IT CHANGES
--   * Trigger `team_members_talks_closed` (after an update of `active`): when
--     a colleague stops being active, for any reason, every open talk they
--     asked or were asked is withdrawn (`closed_at` now). The asker can ask
--     again once both are active. A trigger of its own, so the leaving
--     trigger, which removes devices, is not restated.
--
-- ORDER: this file alone (no page changes). Safe to run twice.
-- Rollback: `drop trigger team_members_talks_closed on public.team_members`
-- and its function in the SQL Editor. Talks it withdrew stay withdrawn.
-- ===========================================================================

create or replace function public.team_members_talks_closed()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if old.active and not new.active then
    update public.health_talks h set status = 'withdrawn', closed_at = now()
     where (h.with_id = new.id or h.team_member_id = new.id) and h.status = 'open';
  end if;
  return null;
exception when others then
  return null;
end $$;
revoke all on function public.team_members_talks_closed() from public, anon, authenticated;
create or replace trigger team_members_talks_closed after update of active on public.team_members
  for each row execute function public.team_members_talks_closed();

-- END OF A LEAVER'S TALKS ARE CLOSED ----------------------------------------
select public.functions_tidy();

-- ===========================================================================
-- A NEW COLLEAGUE IS ADDED PLAIN — a signed-in insert never marks a system
-- account, a removal or an erasure (2026-10-18)
-- ===========================================================================
-- WHY (Team audit, item 3): `team_members_system_guard` fires on update
-- alone, so a page inserting a colleague at Team Full Access could send
-- `system = true` and make a row that no page could then change or remove;
-- `removed_at` and `erased_at` could be sent the same way, a row born
-- removed or erased.
--
-- WHAT IT CHANGES
--   * Trigger `team_members_insert_guard` (before insert): with a sign-in,
--     `system` true is refused `system-account`, and a `removed_at` or an
--     `erased_at` is refused `removed`. With no sign-in (the connector, the
--     SQL Editor) nothing is held, as the system account is set.
--
-- ORDER: this file alone (Add member never sends these). Safe to run twice.
-- Rollback: `drop trigger team_members_insert_guard on public.team_members`
-- and its function in the SQL Editor.
-- ===========================================================================

create or replace function public.team_members_insert_guard()
returns trigger
language plpgsql set search_path = public as $$
begin
  if coalesce(auth.jwt() ->> 'email', '') = '' then return new; end if;
  if coalesce(new.system, false) then
    raise exception 'system-account' using hint = 'A system account is set from the database.';
  end if;
  if new.removed_at is not null or new.erased_at is not null then
    raise exception 'removed' using hint = 'A colleague is added as working; removal is its own step.';
  end if;
  return new;
end $$;
revoke all on function public.team_members_insert_guard() from public, anon, authenticated;
create or replace trigger team_members_insert_guard before insert on public.team_members
  for each row execute function public.team_members_insert_guard();

-- END OF A NEW COLLEAGUE IS ADDED PLAIN -------------------------------------
select public.functions_tidy();

-- ===========================================================================
-- A REMOVAL STANDS — a removed colleague is never made active again through
-- a write of the row, nor by moving their access date (2026-10-18)
-- ===========================================================================
-- WHY (Team audit, item 4): `team_access_guard` refused a removed colleague
-- made active only by the new row's `removed_at`, so one write sending
-- `active = true` and `removed_at = null` passed it; and a colleague whose
-- access expired and who was then removed kept `expired_at`, so moving the
-- access date brought them back by the expiry's own way back.
--
-- WHAT IT CHANGES
--   * `team_access_guard`: with a sign-in, a `removed_at` or an `erased_at`
--     once set is never changed or cleared (`removed`); a colleague removed
--     before the write is never made active; the expiry's way back (moving
--     the date ahead) passes over a removed colleague. Without a sign-in (the
--     SQL Editor) a removal may still be put right by hand.
--
-- ORDER: this file alone (no page sends these). Safe to run twice.
-- Rollback: run COLLEAGUE LEAVING's `team_access_guard` again.
-- ===========================================================================

create or replace function public.team_access_guard()
returns trigger language plpgsql as $$
declare
  who text := lower(coalesce(auth.jwt() ->> 'email', ''));
  ends timestamptz := public.team_access_ends(new.access_until, new.access_until_time);
  moved boolean := new.access_until is distinct from old.access_until
                   or new.access_until_time is distinct from old.access_until_time;
begin
  /* A removal and an erasure are kept once made (2026-10-18): with a
     sign-in neither is taken back or moved; the removal function only ever
     sets them from empty. */
  if who <> '' and ((old.removed_at is not null and new.removed_at is distinct from old.removed_at)
                 or (old.erased_at is not null and new.erased_at is distinct from old.erased_at)) then
    raise exception 'removed' using hint = 'A removed colleague does not come back; add them again.';
  end if;
  if moved and who <> '' and lower(old.email) = who then
    raise exception 'own-expiry' using hint = 'Another admin sets your access date.';
  end if;
  if new.active and not old.active and new.removed_at is not null then
    raise exception 'removed' using hint = 'A removed colleague does not come back; add them again.';
  end if;
  if new.active and not old.active then
    if ends is not null and ends <= now() then
      raise exception 'expired-date' using hint = 'Move the access date first.';
    end if;
    new.expired_at := null;
  elsif old.expired_at is not null and moved and new.removed_at is null and (ends is null or ends > now()) then
    new.active := true;
    new.expired_at := null;
  end if;
  return new;
end $$;
create or replace trigger team_access_guard before update on public.team_members
  for each row execute function public.team_access_guard();

-- END OF A REMOVAL STANDS ---------------------------------------------------
select public.functions_tidy();

-- ===========================================================================
-- A COLLEAGUE'S ROW IS NEVER DELETED — the team table takes inserts and
-- updates at Team Full Access, and no delete from anybody (2026-10-18)
-- ===========================================================================
-- WHY (Team audit, item 5): policy `team_admin` was `for all`, so Team Full
-- Access or an admin could DELETE a colleague's row over REST, cascading into
-- their performance reviews, commissions, health and notifications with no
-- activity entry, where a colleague is only ever stood down or removed.
--
-- WHAT IT CHANGES
--   * `team_insert` (insert) and `team_update` (update), each at
--     `allowed('team', 'manage')` as before; `team_read` is unchanged.
--   * `team_admin` is dropped, so no policy admits a delete: a page's delete
--     is answered with no row, for an admin too. Removal stays the function's
--     (`team_member_remove`), which deletes nothing of the row.
--
-- ORDER: this file alone (no page deletes a colleague). The drop is held by
-- the connector: the two policies are applied first, then the drop in the
-- SQL Editor; until then the old policy stands beside them. Safe to run
-- twice.
-- Rollback: `create policy team_admin on public.team_members for all to
-- authenticated using (public.allowed('team', 'manage')) with check
-- (public.allowed('team', 'manage'));` then drop the two policies.
-- ===========================================================================

do $$
begin
  if not exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'team_members' and policyname = 'team_insert') then
    create policy team_insert on public.team_members for insert to authenticated
      with check (public.allowed('team', 'manage'));
  end if;
  if not exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'team_members' and policyname = 'team_update') then
    create policy team_update on public.team_members for update to authenticated
      using (public.allowed('team', 'manage'))
      with check (public.allowed('team', 'manage'));
  end if;
end $$;
drop policy if exists team_admin on public.team_members;

-- END OF A COLLEAGUE'S ROW IS NEVER DELETED ---------------------------------
select public.functions_tidy();

-- ===========================================================================
-- THE TEAM LIST HOLDS WHAT EVERY COLLEAGUE NEEDS — a colleague's mobile,
-- access dates and access are read through Team, never from the table
-- (2026-10-18)
-- ===========================================================================
-- WHY (Team audit, item 6): policy `team_read` let every active colleague
-- read every column of every colleague over REST: the mobile (hidden from
-- the namecard too), the access date and time, the removal and erasure, and
-- the access map.
--
-- WHAT IT CHANGES
--   1. `team_rows()`: every colleague's whole row, for Team at View alone
--      (nothing for anyone else), newest standing first, as the Team section
--      and a colleague's record read it.
--   2. `team_task_takers()`: the ids of the active colleagues who take tasks
--      (`ops_takes_tasks`), for any colleague, so My Work's pickers need no
--      access map.
--   3. The table answers a browser only the columns every page reads: the
--      name, sign-in email, group, standing, Employee ID, position,
--      department, role standard, capacity, the namecard's key, switch and
--      short link, client scope and the system mark. `access`, `mobile`,
--      `access_until`, `access_until_time`, `expired_at`, `removed_at`,
--      `erased_at` and `card_email` are withheld from `authenticated`; anon
--      reads nothing. Writes are as before (the policies decide them). A new
--      column is granted by running part 3 again with it named.
--
-- ORDER: parts 1 and 2, then the pages (they read the functions and name
-- their columns), then part 3 once the Pages build is live. An open tab
-- from before reads Could not load the team until it is reloaded. Safe to
-- run twice.
-- Rollback: `grant select on public.team_members to authenticated;` then
-- the pages from before; the functions may stay.
-- ===========================================================================

create or replace function public.team_rows()
returns setof public.team_members
language sql stable security definer set search_path = public as $$
  select t.* from public.team_members t
   where public.allowed('team', 'view')
   order by t.active desc, t.role, t.name
$$;
revoke all on function public.team_rows() from public, anon, authenticated;
grant execute on function public.team_rows() to authenticated;

create or replace function public.team_task_takers()
returns jsonb
language sql stable security definer set search_path = public as $$
  select case when public.is_team() then coalesce((
    select jsonb_agg(t.id order by t.id) from public.team_members t
     where t.active and public.ops_takes_tasks(t.id)), '[]'::jsonb) else '[]'::jsonb end
$$;
revoke all on function public.team_task_takers() from public, anon, authenticated;
grant execute on function public.team_task_takers() to authenticated;

revoke select on table public.team_members from anon, authenticated;
grant select (id, name, email, role, active, created_at, updated_at, is_admin,
  can_clients, can_review, can_campaigns, can_links, can_activity, can_billing, can_remove, can_doc_void,
  staff_code, designation, capacity_minutes_week, wip_guidance, department, role_family,
  card_key, card_on, card_slug, card_mobile, client_scope, system)
  on public.team_members to authenticated;

-- END OF THE TEAM LIST HOLDS WHAT EVERY COLLEAGUE NEEDS ----------------------
select public.functions_tidy();

-- ===========================================================================
-- A SIGN-IN EMAIL MOVES ONLY THROUGH AN ADMIN — a colleague's sign-in email
-- is changed by an admin alone (2026-10-18)
-- ===========================================================================
-- WHY (Team audit, item 7; the user: a colleague's email changes only
-- through an admin): `team_admin_guard` held the email on an admin's row
-- alone, so Team Full Access could re-point a colleague's sign-in email to
-- an address of their own and sign in as them.
--
-- WHAT IT CHANGES
--   * Trigger `team_email_guard` (before an update of `email`): with a
--     sign-in, anybody but an admin changing a colleague's email is refused
--     `admin-only`. Deleting a colleague's details (`team_member_remove`,
--     which empties the email as it stamps the erasure) and a run with no
--     sign-in are not held. A system account changing its own address stays
--     as `team_members_system_guard` allows (it is an admin).
--   * The Team page offers the email to an admin alone.
--
-- ORDER: this file, then the pages (an open page from before meets the
-- refusal in words). Safe to run twice.
-- Rollback: `drop trigger team_email_guard on public.team_members` and its
-- function in the SQL Editor.
-- ===========================================================================

create or replace function public.team_email_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if coalesce(auth.jwt() ->> 'email', '') = '' or public.allowed('admin') then return new; end if;
  if lower(new.email) is not distinct from lower(old.email) then return new; end if;
  if new.erased_at is not null and old.erased_at is null and new.email is null then return new; end if;
  raise exception 'admin-only' using errcode = '42501', hint = 'Only an admin changes a sign-in email.';
end $$;
revoke all on function public.team_email_guard() from public, anon, authenticated;
create or replace trigger team_email_guard before update of email on public.team_members
  for each row execute function public.team_email_guard();

-- END OF A SIGN-IN EMAIL MOVES ONLY THROUGH AN ADMIN ------------------------
select public.functions_tidy();

-- ===========================================================================
-- AN INVITATION GOES TO A COLLEAGUE — a team login is made only for an
-- active colleague's address, twenty invitations a day each (2026-10-18)
-- ===========================================================================
-- WHY (Team audit, item 8): `invite-member` made a login for any address
-- with only Team: Send invitation, and no limit, so a login could be made
-- for an address that is nobody on the team, as often as asked.
--
-- WHAT IT CHANGES
--   * `team_invites` (caller, address, kind, when; RLS on, no policy, no
--     grant): every invitation the function makes.
--   * `team_invite_claim(p_caller, p_email, p_kind)`: the service role's
--     alone; refuses `too-many` once the caller has made 20 in the last 24
--     hours, else files the invitation. `invite-member` asks it before it
--     makes a login, and makes a team login only for an address an active
--     colleague holds (`not_team_member`).
--
-- ORDER: this file, then `invite-member` (deployed and read back). Safe to
-- run twice.
-- Rollback: deploy the earlier `invite-member`; the table and function may
-- stay.
-- ===========================================================================

create table if not exists public.team_invites (
  id         uuid primary key default gen_random_uuid(),
  caller_id  uuid not null,
  email      text not null,
  kind       text not null check (kind in ('team', 'client')),
  created_at timestamptz not null default now()
);
create index if not exists team_invites_caller_idx on public.team_invites (caller_id, created_at);
alter table public.team_invites enable row level security;
revoke all on table public.team_invites from public, anon, authenticated;

create or replace function public.team_invite_claim(p_caller uuid, p_email text, p_kind text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare n integer;
begin
  if p_caller is null or coalesce(btrim(p_email), '') = '' or p_kind not in ('team', 'client') then
    return jsonb_build_object('error', 'bad-request');
  end if;
  perform pg_advisory_xact_lock(hashtext('team_invite_claim:' || p_caller::text));
  select count(*) into n from public.team_invites i
   where i.caller_id = p_caller and i.created_at > now() - interval '24 hours';
  if n >= 20 then return jsonb_build_object('error', 'too-many', 'limit', 20); end if;
  insert into public.team_invites (caller_id, email, kind) values (p_caller, lower(btrim(p_email)), p_kind);
  return null;
end $$;
revoke all on function public.team_invite_claim(uuid, text, text) from public, anon, authenticated;
grant execute on function public.team_invite_claim(uuid, text, text) to service_role;

-- END OF AN INVITATION GOES TO A COLLEAGUE ----------------------------------
select public.functions_tidy();

-- ===========================================================================
-- A STALE TEAM SAVE IS REFUSED — a colleague's or a group's save is written
-- only over the row as it was read (2026-10-18)
-- ===========================================================================
-- WHY (Team audit, item 9): the member sheet writes every field each time
-- and a group sends its whole access map, so two people editing the same
-- colleague or group overwrote each other without knowing.
--
-- WHAT IT CHANGES
--   * `team_roles.updated_at`, stamped on every change by trigger
--     `team_roles_touch` (`team_members.updated_at` is already stamped by
--     `team_role_defaults`). The pages write a colleague and a group with
--     `.eq('updated_at', …)` as read, so a row changed meanwhile answers no
--     row; the page tells that apart from a refusal, says so and reads the
--     row again (as a client's request is written, audit C2).
--
-- ORDER: this file, then the pages. Safe to run twice.
-- Rollback: the pages from before; the column and trigger may stay.
-- ===========================================================================

alter table public.team_roles add column if not exists updated_at timestamptz not null default now();

create or replace function public.team_roles_touch()
returns trigger language plpgsql set search_path = public as $$
begin
  new.updated_at := clock_timestamp();
  return new;
end $$;
revoke all on function public.team_roles_touch() from public, anon, authenticated;
create or replace trigger team_roles_touch before update on public.team_roles
  for each row execute function public.team_roles_touch();

-- END OF A STALE TEAM SAVE IS REFUSED ---------------------------------------
select public.functions_tidy();

-- ===========================================================================
-- REMOVED COLLEAGUES FREE THEIR DETAILS — a removed colleague's name, sign-in
-- email and Employee ID may be given to a colleague added again (2026-10-18)
-- ===========================================================================
-- WHY (Team audit, item 10): a removed colleague is never made active again
-- (`team_access_guard`, `removed`), so one who returns is added again. The
-- name, email and Employee ID indexes counted the removed row, so the new
-- row was refused, and the page read every refusal as "That email is
-- already on the list.".
--
-- WHAT IT CHANGES
--   * Three unique indexes that leave out a removed colleague
--     (`removed_at is null`): `team_members_name_live_idx`,
--     `team_members_email_live_idx`, `team_members_staff_code_live_idx`.
--     Every function that finds a colleague by email already asks an active
--     one (`ops_me`, `allowed`, `is_team`), and an HR reference naming an
--     Employee ID two rows hold names nobody (`hr_member_of`).
--   * The three indexes they replace are dropped. Each `drop` is held by
--     the connector: run the last three lines in the SQL Editor. Until then
--     the old indexes still refuse, and nothing else changes.
--
-- ORDER: the pages (they name the field that clashes) and the edge
-- functions (each asks an active colleague by email), then this file, then
-- the three drops. Safe to run twice.
-- Rollback: create the three old indexes again (it fails while two rows
-- share a value), then drop these three.
-- ===========================================================================

create unique index if not exists team_members_name_live_idx
  on public.team_members (lower(name)) where removed_at is null;
create unique index if not exists team_members_email_live_idx
  on public.team_members (lower(email)) where email is not null and removed_at is null;
create unique index if not exists team_members_staff_code_live_idx
  on public.team_members (upper(staff_code))
  where staff_code is not null and staff_code <> '' and removed_at is null;

drop index if exists public.team_members_name_idx;
drop index if exists public.team_members_email_idx;
drop index if exists public.team_members_staff_code_idx;
-- END OF REMOVED COLLEAGUES FREE THEIR DETAILS ------------------------------
select public.functions_tidy();

-- ===========================================================================
-- THE LAST ADMIN IS KEPT — two colleagues standing admins down at the same
-- moment never leave the team with none (2026-10-18)
-- ===========================================================================
-- WHY (Team audit, item 14): `team_member_remove` and the page's Set
-- inactive each asked whether another admin is active, then wrote, with
-- nothing holding the answer. Two admins removing or standing down each
-- other at once both found the other still active, and both went.
--
-- WHAT IT CHANGES
--   * Trigger `team_members_last_admin` (before update of active, role,
--     is_admin): a signed-in write that takes away an active admin first
--     takes the team's admin lock (an advisory lock held to the end of its
--     transaction), then refuses `last-admin` where no other active admin
--     stands. The second of two such writes waits for the first and reads
--     what it committed. It takes an advisory lock rather than the admin
--     rows' own, since each write already holds its own row and two row
--     locks taken in turn by two writes would deadlock.
--   * `team_member_remove` and `team_keep_one_admin` are not restated: each
--     body holds a word the connector stops on, and the trigger covers
--     every write they make. With no sign-in (the access expiry's run, the
--     SQL Editor) nothing is held, as before.
--
-- ORDER: this file; the pages read `last-admin` already. Safe to run twice.
-- Rollback: drop the trigger and the function (SQL Editor).
-- ===========================================================================

create or replace function public.team_members_last_admin()
returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if coalesce(auth.jwt() ->> 'email', '') = '' then return new; end if;
  if not (old.active and (coalesce(old.is_admin, false) or old.role = 'admin')) then return new; end if;
  if new.active and (new.role = 'admin'
                     or coalesce((select r.is_admin from public.team_roles r where r.slug = new.role), false)) then
    return new;
  end if;
  perform pg_advisory_xact_lock(hashtext('team-last-admin'));
  if not exists (select 1 from public.team_members x
                  where x.id <> old.id and x.active
                    and (coalesce(x.is_admin, false) or x.role = 'admin')) then
    raise exception 'last-admin' using errcode = 'P0001',
      hint = 'This is the last admin with access. Make another colleague admin first.';
  end if;
  return new;
end $$;
revoke all on function public.team_members_last_admin() from public, anon, authenticated;
create or replace trigger team_members_last_admin
  before update of active, role, is_admin on public.team_members
  for each row execute function public.team_members_last_admin();
-- END OF THE LAST ADMIN IS KEPT ---------------------------------------------
select public.functions_tidy();

-- ===========================================================================
-- A CLIENT ID AT ACTIVE — a client becomes Active only holding its Client ID,
-- the next number offered (2026-10-18)
-- ===========================================================================
-- WHY (the user, 2026-10-18): a lead, contacted or proposal may come to no
-- deal, so a Client ID is given when a client turns Active; the move asks
-- for it, the next number offered, as a new supplier's Supplier ID is.
--
-- WHAT IT CHANGES
--   * `client_code_next()`: the next free AC number, one past the highest
--     `AC` + digits held by any client, written as wide as that one (AC188
--     → AC189), at Clients Work. Read across every client, whatever the
--     caller's client scope, and the number alone leaves it.
--   * Trigger `clients_active_code`: a client written into Active, or kept
--     Active, with no Client ID is refused (`active-needs-code`).
--
-- ORDER: this file, then the pages. Safe to run twice.
-- Rollback: drop the trigger and the function; the pages from before.
-- ===========================================================================

create or replace function public.client_code_next()
returns text language plpgsql stable security definer set search_path = public as $$
declare
  v_n bigint := 0;
  v_w int := 3;
  r record;
begin
  if not public.allowed('clients', 'work') then
    raise exception 'denied';
  end if;
  for r in
    select substring(c.client_code from '^AC(\d+)$') as d
      from public.clients c
     where c.client_code ~ '^AC\d+$'
  loop
    if r.d::bigint >= v_n then
      v_n := r.d::bigint;
      v_w := greatest(3, length(r.d));
    end if;
  end loop;
  return 'AC' || lpad((v_n + 1)::text, v_w, '0');
end $$;
revoke all on function public.client_code_next() from public, anon;
grant execute on function public.client_code_next() to authenticated;

create or replace function public.clients_active_code()
returns trigger language plpgsql set search_path = public as $$
begin
  if new.stage = 'active' and coalesce(btrim(new.client_code), '') = '' then
    raise exception 'active-needs-code';
  end if;
  return new;
end $$;
revoke all on function public.clients_active_code() from public, anon, authenticated;
create or replace trigger clients_active_code before insert or update of stage, client_code on public.clients
  for each row execute function public.clients_active_code();

-- END OF A CLIENT ID AT ACTIVE ----------------------------------------------

select public.functions_tidy();

-- ===========================================================================
-- A SUPPLIER'S LINK IS CLOSED — the details form's link stops opening at a
-- press, with no new one made (2026-10-18)
-- ===========================================================================
-- WHY (the user, 2026-10-18: "how to delete the link?"): Reset link made a
-- new link in place of the old; a supplier approved by hand still held a
-- link open for two weeks.
--
-- WHAT IT CHANGES
--   * `supplier_link_close(p_id)`: at Suppliers Work, every open form of the
--     supplier ends now (`expires_at`), so it reads Link expired and Create
--     link makes a new one; filed `supplier.edited` · Details form link
--     closed (`no-link` with none open).
--
-- ORDER: this file, then the pages. Safe to run twice.
-- Rollback: drop the function; the pages from before.
-- ===========================================================================

create or replace function public.supplier_link_close(p_id uuid)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me  public.team_members := public.ops_me();
  s   public.suppliers;
  n   int;
begin
  if me.id is null or not public.allowed('suppliers', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into s from public.suppliers x where x.id = p_id;
  if s.id is null then return jsonb_build_object('error', 'not-found'); end if;
  update public.supplier_forms x set expires_at = now()
   where x.supplier_id = p_id and x.voided_at is null and x.submitted_at is null and x.expires_at > now();
  get diagnostics n = row_count;
  if n = 0 then return jsonb_build_object('error', 'no-link'); end if;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'supplier.edited', coalesce(s.name, s.code), s.code || ' · Details form link closed');
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.supplier_link_close(uuid) from public, anon;
grant execute on function public.supplier_link_close(uuid) to authenticated;

-- END OF A SUPPLIER'S LINK IS CLOSED ----------------------------------------

-- ACCESS ENDS ON THE MINUTE — a colleague whose access date has passed is
-- off the team at once, not at the next expiry run (2026-10-18)
-- ===========================================================================
-- WHY (Team audit, item 15): `team_expire_access()` stands a colleague down
-- every five minutes, and until it ran `is_team()`, `allowed()` and
-- `ops_me()` still answered for them, so a colleague whose access ended at
-- 17:00 could read and write until 17:05.
--
-- WHAT IT CHANGES
--   * `is_team()`, `allowed(p_section, p_level)`, `ops_me()` and `me()` (the
--     console's own read of who is signed in) count a colleague only while their access date has not
--     passed (`team_access_ends`, Malaysia's day and time; no date is no
--     end). The check sits in each query, with no function of its own, so
--     every policy pays for it once, in the row it already reads.
--     `allowed('admin')` asks only whether an active colleague is an admin,
--     and so needs no change.
--   * An admin is not held by it: the expiry run never stands down the
--     last admin with access, and an admin's own date is the run's to apply.
--   * `my_access_expired()` also answers for a colleague whose date has
--     passed and whom the run has not reached, so sign-in reads Access
--     expired, not Access denied.
--
-- ORDER: this file; the pages need nothing. Safe to run twice.
-- Rollback: the five functions as TEAM ACCESS EXPIRY and ACCESS left them.
-- ===========================================================================

create or replace function public.is_team()
returns boolean
language sql security definer stable set search_path = public as $$
  select exists (
    select 1 from public.team_members t
    where t.active and lower(t.email) = lower(auth.jwt() ->> 'email')
      and (t.access_until is null or t.is_admin or t.role = 'admin'
           or public.team_access_ends(t.access_until, t.access_until_time) > now()))
$$;
grant execute on function public.is_team() to authenticated;

create or replace function public.allowed(p_section text, p_level text)
returns boolean
language plpgsql security definer stable set search_path = public as $$
declare
  t public.team_members;
  k text := lower(coalesce(p_section, ''));
  lv text;
begin
  select * into t from public.team_members x
    where lower(x.email) = lower(auth.jwt() ->> 'email') and x.active
      and (x.access_until is null or x.is_admin or x.role = 'admin'
           or public.team_access_ends(x.access_until, x.access_until_time) > now())
    limit 1;
  if t.id is null then return false; end if;
  if t.is_admin or t.role = 'admin' then return true; end if;
  lv := t.access ->> k;
  if lv is null and position('.' in k) > 0 then
    lv := t.access ->> split_part(k, '.', 1);
  end if;
  return public.level_rank(lv) >= public.level_rank(p_level);
end $$;
grant execute on function public.allowed(text, text) to authenticated;

create or replace function public.ops_me()
returns public.team_members
language sql security definer stable set search_path = public as $$
  select * from public.team_members t
   where t.active and lower(t.email) = lower(auth.jwt() ->> 'email')
     and (t.access_until is null or t.is_admin or t.role = 'admin'
          or public.team_access_ends(t.access_until, t.access_until_time) > now())
   limit 1
$$;
grant execute on function public.ops_me() to authenticated;

create or replace function public.me()
returns public.team_members
language sql security definer stable set search_path = public as $$
  select * from public.team_members t
  where lower(t.email) = lower(auth.jwt() ->> 'email') and t.active
    and (t.access_until is null or t.is_admin or t.role = 'admin'
         or public.team_access_ends(t.access_until, t.access_until_time) > now())
  limit 1
$$;
grant execute on function public.me() to authenticated;

create or replace function public.my_access_expired()
returns boolean language sql security definer stable set search_path = public as $$
  select exists (select 1 from public.team_members t
                  where lower(t.email) = lower(auth.jwt() ->> 'email')
                    and ((not t.active and t.expired_at is not null)
                         or (t.active and t.access_until is not null and not (t.is_admin or t.role = 'admin')
                             and public.team_access_ends(t.access_until, t.access_until_time) <= now())))
$$;
grant execute on function public.my_access_expired() to authenticated;
-- END OF ACCESS ENDS ON THE MINUTE ------------------------------------------
select public.functions_tidy();

-- ===========================================================================
-- TEN NOTICES AN HOUR — a colleague sends at most ten notices in any hour
-- (2026-10-18)
-- ===========================================================================
-- WHY (Team audit, item 16): `team_notice_send` wrote a bell row and a
-- push for every colleague on each press with no limit, so a stuck key, a
-- page sending twice or a misused part could fill every colleague's bell
-- and phone.
--
-- WHAT IT CHANGES
--   * `team_notice_send` refuses `too-many` (with `limit` 10 and `next`, the
--     moment the next may go) once the sender has sent ten notices in the
--     hour before, counted from `team_notices` under a lock held for the
--     sender to the end of the transaction, so two presses at once are
--     counted one after the other. Ten is a safety limit, not a business
--     figure, so it is held in the function as an invitation's count is.
--     Every refusal before it stands as it was.
--
-- ORDER: the page (it words `too-many`), then this file. Safe to run twice.
-- Rollback: TEAM NOTICES' `team_notice_send`.
-- ===========================================================================

create or replace function public.team_notice_send(p_title text, p_body text, p_to uuid[])
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  v_title text := btrim(coalesce(p_title, ''));
  v_body  text := nullif(btrim(coalesce(p_body, '')), '');
  v_to    uuid[];
  v_id    uuid;
  n       int;
  v_sent  int;
  v_first timestamptz;
begin
  if me.id is null or not public.ops_granted('team.notice', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if v_title = '' or length(v_title) > 120 then return jsonb_build_object('error', 'bad-title'); end if;
  if v_body is not null and length(v_body) > 1000 then return jsonb_build_object('error', 'bad-body'); end if;
  perform pg_advisory_xact_lock(hashtext('team-notice-send:' || me.id::text));
  select count(*), min(tn.created_at) into v_sent, v_first
    from (select x.created_at from public.team_notices x
           where x.sent_by = me.id and x.created_at > now() - interval '1 hour'
           order by x.created_at desc limit 10) tn;
  if v_sent >= 10 then
    return jsonb_build_object('error', 'too-many', 'limit', 10, 'next', v_first + interval '1 hour');
  end if;
  select coalesce(array_agg(m.id order by m.name), '{}') into v_to
    from public.team_members m
   where m.active and not coalesce(m.system, false) and m.id <> me.id
     and (p_to is null or m.id = any(p_to));
  n := coalesce(array_length(v_to, 1), 0);
  if n = 0 then return jsonb_build_object('error', 'no-one'); end if;
  insert into public.team_notices (title, body, to_all, recipients, sent_by, sent_by_name)
  values (v_title, v_body, p_to is null, v_to, me.id, me.name)
  returning id into v_id;
  insert into public.ops_notifications (team_member_id, kind, title, body, notice_id, from_name)
  select x, 'notice', v_title, v_body, v_id, me.name from unnest(v_to) as x;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'team.changed', 'Notices',
    'Sent to ' || case when p_to is null then 'all colleagues (' || n || ')'
                       when n = 1 then '1 colleague' else n || ' colleagues' end || ': ' || v_title);
  return jsonb_build_object('ok', true, 'id', v_id, 'count', n);
end $$;
revoke all on function public.team_notice_send(text, text, uuid[]) from public, anon;
grant execute on function public.team_notice_send(text, text, uuid[]) to authenticated;
-- END OF TEN NOTICES AN HOUR ------------------------------------------------
select public.functions_tidy();

-- ===========================================================================
-- A CALLER'S ADDRESS IS CLOUDFLARE'S — the passcode locks count the address
-- Cloudflare saw, never one the caller wrote (2026-10-18)
-- ===========================================================================
-- WHY (audit 2026-10-18, item 1): `request_ip()` took the first entry of
-- X-Forwarded-For, which the caller writes. Read live (one request sent
-- with `X-Forwarded-For: 203.0.113.77, 198.51.100.9`): PostgREST passed
-- `203.0.113.77, 198.51.100.9,<the caller>` and `cf-connecting-ip:
-- <the caller>`; a request sending its own CF-Connecting-IP is refused by
-- Cloudflare (error 1000) and X-Real-IP never arrives. So a guesser wrote a
-- new address on every try and the five-try lock never held them.
--
-- WHAT IT CHANGES
--   * `request_ip()` reads `cf-connecting-ip`, else the last
--     X-Forwarded-For entry (the one the gateway appended), never the first.
--   * `media-pass` and `sign-download` ask for a link as the page did, and
--     Cloudflare stamps their own address on that call. They now pass the
--     caller's address in `x-adspace-ip` with `x-adspace-relay`, a secret
--     kept in `app_secrets` (`ip_relay_secret`, made here, read only with
--     the service role); `request_ip()` takes `x-adspace-ip` only beside the
--     right secret. It is security definer so it may read the secret, and
--     stays closed to every browser.
--   * The probe used to read the headers live (`zz_header_probe`, emptied
--     and closed the same hour) is dropped.
--
-- ORDER: this file, then `media-pass` and `sign-download`. Between the two
-- a function's passcode tries count against its own address, as before
-- 2026-10-18. Safe to run twice. The connector holds the last line (a drop):
-- run it in the SQL Editor.
-- Rollback: PASSCODE LOCKS PER CALLER's `request_ip()`, and the functions as
-- they were; the secret may stay.
-- ===========================================================================

insert into public.app_secrets (key, value)
select 'ip_relay_secret', replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '')
 where not exists (select 1 from public.app_secrets s where s.key = 'ip_relay_secret');

create or replace function public.request_ip()
returns text
language sql stable security definer set search_path = public as $$
  select left(coalesce(
    case when nullif(h ->> 'x-adspace-relay', '') is not null
          and h ->> 'x-adspace-relay' = (select s.value from public.app_secrets s where s.key = 'ip_relay_secret')
         then nullif(btrim(h ->> 'x-adspace-ip'), '') end,
    nullif(btrim(h ->> 'cf-connecting-ip'), ''),
    nullif(btrim(reverse(split_part(reverse(coalesce(h ->> 'x-forwarded-for', '')), ',', 1))), ''),
    ''), 64)
  from (select coalesce(nullif(current_setting('request.headers', true), ''), '{}')::json as h) r
$$;
revoke all on function public.request_ip() from public, anon, authenticated;

drop function if exists public.zz_header_probe();
-- END OF A CALLER'S ADDRESS IS CLOUDFLARE'S ---------------------------------
select public.functions_tidy();

-- ===========================================================================
-- WHATSAPP LINK FROM THE RECORD — a template's link button opens the page of
-- the record being messaged, never a value the composer sent.
-- 2026-10-19. Safe to run twice. Rollback at the foot. Mirrored byte for
-- byte in supabase/schema.sql under the same banner; tests/sql.js compares
-- the two.
--
-- WHAT CHANGED
--   wa-send filled a template's link button with the value the composer
--   sent, so a stale prefill could send one creator a button to another
--   creator's page, or a client a link to another client's review page
--   (the third audit, item 2).
--   * wa_compose_prepare answers `link` for an approval reminder: the
--     page that waits on the client, past the site's root (`review/?k=` and
--     the client's key, `creators/?k=` and the campaign's key). It already
--     answers a creator's `code`.
--   * wa-send fills the link button from that answer alone (the creator's
--     code; the approval link past the button's fixed base) and refuses a
--     template whose link button the record does not fill (`wa-no-link`)
--     (supabase/functions/wa-send). The composer shows the link button as a
--     value only read (js/whatsapp.js).
--
-- ROLLBACK
--   Run the wa_compose_prepare definition of the DATA HELD TO ITS LEVEL
--   section of supabase/schema.sql again (it answers no `link`; wa-send
--   then refuses every template with a link button sent to a contact).
-- ===========================================================================

create or replace function public.wa_compose_prepare(p_to_kind text, p_to uuid, p_purpose text, p_ref uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  me   public.team_members := public.ops_me();
  k    public.client_contacts;
  cr   public.creators;
  c    public.clients;
  r    public.sm_reports;
  o    public.campaign_options;
  cp   public.campaigns;
  b    public.batches;
  q    public.quotations;
  d    public.client_documents;
  v_n  text;
begin
  if me.id is null then return jsonb_build_object('error', 'denied'); end if;
  if p_purpose not in ('message', 'report', 'feedback', 'creator', 'approval', 'quotation', 'offer')
     or p_to_kind not in ('contact', 'creator')
     or (p_purpose in ('report', 'feedback', 'approval', 'quotation', 'offer') and p_to_kind <> 'contact')
     or (p_purpose = 'creator' and p_to_kind <> 'creator') then
    return jsonb_build_object('error', 'bad-request');
  end if;
  if not public.wa_may_send(p_purpose, p_to_kind) then return jsonb_build_object('error', 'denied'); end if;
  if p_to_kind = 'contact' then
    select * into k from public.client_contacts x where x.id = p_to and x.archived_at is null;
    if k.id is null then return jsonb_build_object('error', 'not-found'); end if;
    select * into c from public.clients x where x.id = k.client_id;
    if c.id is null or not public.client_seen(c.id, 'view') then return jsonb_build_object('error', 'not-found'); end if;
    if p_purpose = 'report' then
      select * into r from public.sm_reports x where x.id = p_ref;
      if r.id is null or r.client_id <> c.id then return jsonb_build_object('error', 'not-found'); end if;
      if r.status <> 'published' then return jsonb_build_object('error', 'not-published'); end if;
    end if;
    /* A quotation or a Letter of Offer is the contact's own client's: a
       quotation not removed, a letter not voided. */
    if p_purpose = 'quotation' then
      select * into q from public.quotations x where x.id = p_ref;
      if q.id is null or q.client_id <> c.id or q.removed_at is not null then return jsonb_build_object('error', 'not-found'); end if;
      if q.status = 'not_proceeding' then return jsonb_build_object('error', 'void'); end if;
    end if;
    if p_purpose = 'offer' then
      select * into d from public.client_documents x where x.id = p_ref;
      if d.id is null or d.client_id <> c.id or d.kind not in ('offer', 'intent', 'cover') then
        return jsonb_build_object('error', 'not-found');
      end if;
      if (d.voided_at is not null or d.superseded_by is not null) then return jsonb_build_object('error', 'void'); end if;
    end if;
    /* An approval reminder names what waits on the client: a published
       content set of theirs, or a creator's draft at Reviewing on a
       campaign of theirs, each read at its own section. */
    if p_purpose = 'approval' then
      select * into b from public.batches x where x.id = p_ref;
      if b.id is not null then
        if b.client_id <> c.id or not public.allowed('review.sets', 'view') then return jsonb_build_object('error', 'not-found'); end if;
        if not coalesce(b.published, false) then return jsonb_build_object('error', 'not-waiting'); end if;
      else
        select * into o from public.campaign_options x where x.id = p_ref;
        if o.id is not null then select * into cp from public.campaigns x where x.id = o.campaign_id; end if;
        if o.id is null or cp.id is null or cp.client_id is distinct from c.id or not public.allowed('campaigns.campaigns', 'view') then
          return jsonb_build_object('error', 'not-found');
        end if;
        if o.state <> 'reviewing' then return jsonb_build_object('error', 'not-waiting'); end if;
      end if;
    end if;
    v_n := public.wa_number(coalesce(case when k.whatsapp !~ '^@' then k.whatsapp end, k.phone), c.market);
    if v_n is null then
      return jsonb_build_object('error', case when k.whatsapp ~ '^@' then 'username' else 'no-number' end);
    end if;
    return jsonb_build_object('ok', true, 'number', v_n, 'name', k.name, 'greeting', public.contact_greeting(k.salutation, k.name),
      'client_id', c.id, 'client', case when r.id is not null then coalesce(nullif(r.brand_name, ''), c.name) else c.name end,
      'subject', c.name, 'ref_kind', case when b.id is not null then 'set' when o.id is not null then 'option'
                       when q.id is not null then 'quotation' when d.id is not null then 'offer' end,
      -- an approval reminder's link button: the page that waits, past the
      -- site's root (the client's review page, the campaign's selection page)
      'link', case when b.id is not null then 'review/?k=' || c.access_token
                   when o.id is not null then 'creators/?k=' || cp.access_token end);
  end if;
  select * into cr from public.creators x where x.id = p_to;
  if cr.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if p_purpose = 'creator' then
    select * into o from public.campaign_options x where x.id = p_ref;
    if o.id is null or o.creator_id <> cr.id then return jsonb_build_object('error', 'not-found'); end if;
    select * into cp from public.campaigns x where x.id = o.campaign_id;
    if cp.id is null or (cp.client_id is not null and not public.client_seen(cp.client_id, 'view')) then
      return jsonb_build_object('error', 'not-found');
    end if;
    if o.state in ('option', 'shortlisted', 'backup', 'withdrawn', 'replaced') then
      return jsonb_build_object('error', 'not-booked');
    end if;
  elsif not cr.active then
    return jsonb_build_object('error', 'not-found');
  end if;
  v_n := public.wa_number(cr.whatsapp, 'MY');
  if v_n is null then return jsonb_build_object('error', 'no-creator-number'); end if;
  return jsonb_build_object('ok', true, 'number', v_n, 'name', cr.name, 'greeting', split_part(btrim(cr.name), ' ', 1),
    'client_id', cp.client_id,
    'campaign', case when cp.id is not null then coalesce(nullif(btrim(cp.title), ''), 'Your campaign') end,
    'code', cr.access_code, 'subject', coalesce(nullif(btrim(cp.title), ''), cr.name));
end $$;
revoke all on function public.wa_compose_prepare(text, uuid, text, uuid) from public, anon;
grant execute on function public.wa_compose_prepare(text, uuid, text, uuid) to authenticated;

-- END OF WHATSAPP LINK FROM THE RECORD --------------------------------------

select public.functions_tidy();

-- ===========================================================================
-- REVIEW DECISIONS ASK THE PASSCODE AS THE PAGE DOES — submit_review and
-- submit_review_seen count a wrong passcode and keep a locked caller out
-- (2026-10-18)
-- ===========================================================================
-- WHY (audit 2026-10-18, item 13): both compared `c.passcode = p_passcode`
-- themselves, so a guesser locked out of `get_review_feed` (five wrong
-- tries, #618) could go on guessing through Approve, uncounted.
--
-- WHAT IT CHANGES
--   * Both ask `link_passcode('review', …)`, as `get_review_feed` does: a
--     wrong passcode is counted against its caller and answers `not_found`
--     as before; a locked caller is answered `locked` with its minutes
--     (`link_locked`), which the page reads as Not sent.
--   * Nothing else in either function moves.
--
-- ORDER: this file; the page needs nothing. Safe to run twice.
-- Rollback: HIDDEN FROM CONTENT REVIEW's `submit_review` and APPROVAL AS
-- SEEN's `submit_review_seen`.
-- ===========================================================================

create or replace function public.submit_review(
  p_token      text,
  p_post_id    uuid,
  p_decision   text,
  p_note       text default null,
  p_reviewer   text default null,
  p_passcode   text default null,
  p_caption    text default null,
  p_caption_zh text default null
) returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_client_id uuid;
  v_stored    text;
  v_post      public.posts%rowtype;
  v_cap       text;
  v_cap_zh    text;
begin
  if p_decision not in ('approved', 'changes') then
    return jsonb_build_object('error', 'bad_decision');
  end if;

  select c.id, c.passcode into v_client_id, v_stored
  from public.clients c
  where c.access_token = p_token
    and c.active
    and not c.review_hidden;

  if v_client_id is null then
    return jsonb_build_object('error', 'not_found');
  end if;
  -- The passcode as the link's own page asks it: counted per caller, and a
  -- caller locked out stays out here too (audit 2026-10-18, item 13).
  case public.link_passcode('review', p_token, v_stored, p_passcode)
    when 'locked' then return public.link_locked('review', p_token);
    when 'wrong' then return jsonb_build_object('error', 'not_found');
    else null;
  end case;

  -- the post must belong to a published batch of this client
  select p.* into v_post
  from public.posts p
  join public.batches b on b.id = p.batch_id
  where p.id = p_post_id and b.client_id = v_client_id and b.published;

  if v_post.id is null then
    return jsonb_build_object('error', 'not_found');
  end if;

  /* A suggested copy is kept only where it differs from the copy on show,
     and only on a request for changes. */
  if p_decision = 'changes' then
    v_cap    := case when p_caption is not null
                      and p_caption is distinct from coalesce(v_post.caption, '') then p_caption end;
    v_cap_zh := case when p_caption_zh is not null
                      and p_caption_zh is distinct from coalesce(v_post.caption_zh, '') then p_caption_zh end;
  end if;

  if p_decision = 'changes' and coalesce(btrim(p_note), '') = ''
     and v_cap is null and v_cap_zh is null then
    return jsonb_build_object('error', 'note_required');
  end if;

  insert into public.reviews (post_id, decision, note, reviewer, suggested_caption, suggested_caption_zh)
  values (p_post_id, p_decision, nullif(btrim(p_note), ''), nullif(btrim(p_reviewer), ''), v_cap, v_cap_zh);

  /* The activity record is the portal's account of what was decided and by
     whom, and it held only what the team did. A client approving a post is
     the decision the whole section exists to collect, and it left nothing
     anybody could produce later: the verdict sat in `reviews` alone, which
     no screen reads as a history. The reviewer's own typed name is the
     actor, because a person decided it. */
  insert into public.activity_log (actor, action, subject, detail)
  select coalesce(nullif(btrim(coalesce(p_reviewer, '')), ''), 'Client'),
         case when p_decision = 'approved' then 'review.approved' else 'review.changes' end,
         c.name,
         b.title || ' · ' || coalesce(nullif(p.platform, ''), 'post') ||
         case when p.round > 1 then ' · revision ' || p.round else '' end ||
         coalesce(' · ' || nullif(btrim(coalesce(p_note, '')), ''), '') ||
         case when v_cap is not null or v_cap_zh is not null then ' · caption edited' else '' end
    from public.posts p
    join public.batches b on b.id = p.batch_id
    join public.clients c on c.id = b.client_id
   where p.id = p_post_id;

  return jsonb_build_object('ok', true);
end $$;

revoke all on function public.submit_review(text, uuid, text, text, text, text, text, text) from public;
grant execute on function public.submit_review(text, uuid, text, text, text, text, text, text) to anon, authenticated;

create or replace function public.submit_review_seen(
  p_token      text,
  p_post_id    uuid,
  p_decision   text,
  p_version    integer,
  p_note       text default null,
  p_reviewer   text default null,
  p_passcode   text default null,
  p_caption    text default null,
  p_caption_zh text default null
) returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_post   public.posts%rowtype;
  v_res    jsonb;
  v_stored text;
begin
  -- The link first, as submit_review asks it, so a post id alone says nothing;
  -- the passcode through link_passcode, counted per caller (audit
  -- 2026-10-18, item 13).
  select c.passcode into v_stored
    from public.posts p
    join public.batches b on b.id = p.batch_id
    join public.clients c on c.id = b.client_id
   where p.id = p_post_id and b.published
     and c.access_token = p_token and c.active and not c.review_hidden;
  if not found then
    return jsonb_build_object('error', 'not_found');
  end if;
  case public.link_passcode('review', p_token, v_stored, p_passcode)
    when 'locked' then return public.link_locked('review', p_token);
    when 'wrong' then return jsonb_build_object('error', 'not_found');
    else null;
  end case;
  select * into v_post from public.posts where id = p_post_id for update;
  if p_version is null or p_version is distinct from v_post.content_version then
    return jsonb_build_object('error', 'changed', 'version', v_post.content_version);
  end if;
  v_res := public.submit_review(p_token, p_post_id, p_decision, p_note, p_reviewer,
                                p_passcode, p_caption, p_caption_zh);
  if coalesce((v_res ->> 'ok')::boolean, false) then
    update public.reviews r
       set seen = jsonb_build_object('version', v_post.content_version, 'round', v_post.round,
                                     'title', v_post.title, 'caption', v_post.caption,
                                     'caption_zh', v_post.caption_zh, 'media', v_post.media)
     where r.post_id = p_post_id and r.created_at = now() and r.seen is null;
  end if;
  return v_res;
end $$;

revoke all on function public.submit_review_seen(text, uuid, text, integer, text, text, text, text, text) from public;
grant execute on function public.submit_review_seen(text, uuid, text, integer, text, text, text, text, text) to anon, authenticated;
-- END OF REVIEW DECISIONS ASK THE PASSCODE AS THE PAGE DOES -----------------

-- ===========================================================================
-- BUKKU CONTACTS — a client's billing and a supplier's details sent to Bukku
-- by hand, one contact each, linked once (2026-10-18)
-- ===========================================================================
-- WHY (the user, 2026-10-18, Phase 1 approved): Bukku issues the quotations,
-- invoices and purchase orders, and its contacts were typed again by hand.
--
-- WHAT IT CHANGES
--   * `bukku_settings`: one row, which Bukku custom contact field holds the
--     Client ID and which the Supplier ID (`field_client`,
--     `field_supplier`, Bukku's own ids). Read by `bukku_config()` (Clients
--     Billing or Suppliers at Work, or Business settings); set by
--     `bukku_config_set(p_client, p_supplier)` (`team.settings`), filed
--     `team.changed` under Bukku. RLS on, no policy, no grant.
--   * `bukku_links`: a client or a supplier and the Bukku contact it is
--     linked to (`contact_id`), with who sent it last and when, and the
--     print of the details as sent (`sent_hash`, `bukku_print`), so the
--     record says Changed since. RLS on, no policy, no grant.
--   * `bukku_prepare(p_kind, p_id)`: what a send needs, read as the caller:
--     a client at Clients: Billing Work in scope (its registered name, BRN,
--     old BRN, TIN, SST no., billing address, finance email, market and
--     Client ID, the billing contact, else the main contact); a supplier at
--     Suppliers Work (its details, the NRIC only at `suppliers.pay` View).
--     A company's name is in capitals, a person's each word's first letter
--     (the user, 2026-10-18). A supplier linked to a client answers that
--     client's contact (one contact, both types). Refuses `incomplete` with
--     what is missing.
--   * `bukku_link_get(p_kind, p_id)`: the link and its last send, at View,
--     and whether the details changed since (`changed`).
--   * `bukku_linked(p_kind, p_id, p_contact, p_code)`: files a
--     send made by `bukku-sync` as the caller (the same checks as prepare),
--     linking a supplier's client to the same contact; filed
--     `client.edited` / `supplier.edited` · Sent to Bukku.
--
-- ORDER: this file, then `bukku-sync`, then the pages. Safe to run twice.
-- Rollback: drop the functions and the two tables; the pages from before.
-- ===========================================================================

create table if not exists public.bukku_settings (
  id             int primary key default 1 check (id = 1),
  field_client   bigint,
  field_supplier bigint,
  set_by         uuid references public.team_members(id) on delete set null,
  set_at         timestamptz not null default now()
);
alter table public.bukku_settings enable row level security;
revoke all on table public.bukku_settings from public, anon, authenticated;

create table if not exists public.bukku_links (
  kind       text not null check (kind in ('client', 'supplier')),
  record_id  uuid not null,
  contact_id bigint not null,
  code       text,
  sent_at    timestamptz not null default now(),
  sent_by    uuid references public.team_members(id) on delete set null,
  sent_hash  text,
  primary key (kind, record_id)
);
alter table public.bukku_links enable row level security;
revoke all on table public.bukku_links from public, anon, authenticated;

/* A company's name in capitals; a person's with each word's first letter
   capital (Lee Kim Kee), the rest as typed in lower case. */
create or replace function public.bukku_name_case(p_name text, p_company boolean)
returns text language sql immutable set search_path = public as $$
  select case when p_name is null or btrim(p_name) = '' then null
              when p_company then upper(regexp_replace(btrim(p_name), '\s+', ' ', 'g'))
              else initcap(lower(regexp_replace(btrim(p_name), '\s+', ' ', 'g'))) end
$$;
revoke all on function public.bukku_name_case(text, boolean) from public, anon, authenticated;

create or replace function public.bukku_may(p_kind text, p_id uuid, p_level text)
returns boolean language plpgsql stable security definer set search_path = public as $$
begin
  if (public.ops_me()).id is null then return false; end if;
  if p_kind = 'client' then
    return public.allowed('clients.billing', p_level) and public.client_seen(p_id, 'view');
  elsif p_kind = 'supplier' then
    return public.allowed('suppliers', p_level);
  end if;
  return false;
end $$;
revoke all on function public.bukku_may(text, uuid, text) from public, anon, authenticated;

create or replace function public.bukku_config()
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare b public.bukku_settings;
begin
  if (public.ops_me()).id is null or not (public.allowed('clients.billing', 'work') or public.allowed('suppliers', 'work')
      or public.ops_granted('team.settings', 'work')) then
    return jsonb_build_object('error', 'denied');
  end if;
  select * into b from public.bukku_settings where id = 1;
  return jsonb_build_object('ok', true, 'field_client', b.field_client, 'field_supplier', b.field_supplier, 'set_at', b.set_at);
end $$;
revoke all on function public.bukku_config() from public, anon;
grant execute on function public.bukku_config() to authenticated;

create or replace function public.bukku_config_set(p_client bigint, p_supplier bigint)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare me public.team_members := public.ops_me(); b public.bukku_settings;
begin
  if me.id is null or not public.ops_granted('team.settings', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if (p_client is not null and p_client <= 0) or (p_supplier is not null and p_supplier <= 0) then
    return jsonb_build_object('error', 'bad-value');
  end if;
  select * into b from public.bukku_settings where id = 1;
  if b.id is not null and b.field_client is not distinct from p_client and b.field_supplier is not distinct from p_supplier then
    return jsonb_build_object('ok', true);
  end if;
  insert into public.bukku_settings (id, field_client, field_supplier, set_by, set_at)
  values (1, p_client, p_supplier, me.id, now())
  on conflict (id) do update set field_client = excluded.field_client, field_supplier = excluded.field_supplier,
    set_by = excluded.set_by, set_at = now();
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'team.changed', 'Bukku', 'Client ID field: ' || coalesce(b.field_client::text, 'not set') || ' → ' || coalesce(p_client::text, 'not set')
    || '; Supplier ID field: ' || coalesce(b.field_supplier::text, 'not set') || ' → ' || coalesce(p_supplier::text, 'not set'));
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.bukku_config_set(bigint, bigint) from public, anon;
grant execute on function public.bukku_config_set(bigint, bigint) to authenticated;

/* The print of what a send carries, so a change since is seen without
   asking Bukku. */
create or replace function public.bukku_print(p_kind text, p_id uuid)
returns text language plpgsql stable security definer set search_path = public as $$
declare v text;
begin
  if p_kind = 'client' then
    select concat_ws('|', c.legal_name, c.company_no, c.company_no_old, c.tin, c.sst_no, c.billing_address,
             c.finance_email, c.client_code, c.market, ct.name, ct.email, ct.phone)
      into v
      from public.clients c
      left join public.client_contacts ct on ct.id = coalesce(c.bill_contact_id,
        (select y.id from public.client_contacts y where y.client_id = c.id and y.is_primary and y.archived_at is null limit 1))
     where c.id = p_id;
  else
    select concat_ws('|', s.name, s.kind, s.brn, s.tin, s.sst_no, s.address, s.email, s.finance_email,
             s.contact_name, s.mobile, s.phone, s.currency, s.code, s.payment_term)
      into v from public.suppliers s where s.id = p_id;
  end if;
  return case when v is null then null else md5(v) end;
end $$;
revoke all on function public.bukku_print(text, uuid) from public, anon, authenticated;

create or replace function public.bukku_link_get(p_kind text, p_id uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare l public.bukku_links; v_by text;
begin
  if not public.bukku_may(p_kind, p_id, 'view') then return jsonb_build_object('error', 'denied'); end if;
  select * into l from public.bukku_links x where x.kind = p_kind and x.record_id = p_id;
  if l.contact_id is null then return jsonb_build_object('ok', true); end if;
  select t.name into v_by from public.team_members t where t.id = l.sent_by;
  return jsonb_build_object('ok', true, 'contact_id', l.contact_id, 'code', l.code, 'sent_at', l.sent_at,
    'sent_by', v_by, 'changed', l.sent_hash is distinct from public.bukku_print(p_kind, p_id));
end $$;
revoke all on function public.bukku_link_get(text, uuid) from public, anon;
grant execute on function public.bukku_link_get(text, uuid) to authenticated;

create or replace function public.bukku_prepare(p_kind text, p_id uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  c public.clients; s public.suppliers; ct public.client_contacts;
  l public.bukku_links; b public.bukku_settings;
  v_missing text[] := '{}'; v_company boolean; v_id text; v_field bigint; v_pay boolean;
  v_person text; v_out jsonb;
begin
  if not public.bukku_may(p_kind, p_id, 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into b from public.bukku_settings where id = 1;
  if p_kind = 'client' then
    select * into c from public.clients x where x.id = p_id;
    if c.id is null then return jsonb_build_object('error', 'not-found'); end if;
    select * into ct from public.client_contacts x
     where x.id = c.bill_contact_id and x.archived_at is null;
    if ct.id is null then
      select * into ct from public.client_contacts x where x.client_id = c.id and x.is_primary and x.archived_at is null;
    end if;
    if coalesce(btrim(c.legal_name), '') = '' then v_missing := v_missing || 'Registered name'::text; end if;
    if coalesce(btrim(c.client_code), '') = '' then v_missing := v_missing || 'Client ID'::text; end if;
    if array_length(v_missing, 1) > 0 then return jsonb_build_object('error', 'incomplete', 'missing', to_jsonb(v_missing)); end if;
    select * into l from public.bukku_links x where x.kind = 'client' and x.record_id = c.id;
    v_person := btrim(coalesce(ct.name, ''));
    return jsonb_build_object('ok', true, 'kind', 'client', 'id', c.id,
      'legal_name', public.bukku_name_case(c.legal_name, true), 'other_name', c.name,
      'entity_type', case when c.market = 'SG' then 'FOREIGN_COMPANY' else 'MALAYSIAN_COMPANY' end,
      'reg_no_type', case when nullif(regexp_replace(coalesce(c.company_no, ''), '[^0-9A-Za-z]', '', 'g'), '') is null then null else 'BRN' end,
      'reg_no', nullif(regexp_replace(coalesce(c.company_no, ''), '[^0-9A-Za-z]', '', 'g'), ''),
      'old_reg_no', nullif(btrim(coalesce(c.company_no_old, '')), ''),
      'tax_id_no', nullif(btrim(coalesce(c.tin, '')), ''), 'sst_reg_no', nullif(btrim(coalesce(c.sst_no, '')), ''),
      'email', nullif(btrim(coalesce(c.finance_email, ct.email, '')), ''),
      'phone_no', public.wa_number(coalesce(ct.phone, ct.whatsapp), coalesce(c.market, 'MY')),
      'address', nullif(btrim(coalesce(c.billing_address, '')), ''),
      'country', case when c.market = 'SG' then 'SG' else 'MY' end,
      'currency', case when c.market = 'SG' then 'SGD' else 'MYR' end,
      'person', nullif(public.bukku_name_case(v_person, false), ''),
      'our_id', c.client_code, 'field_id', b.field_client, 'type', 'customer',
      'contact_id', l.contact_id);
  elsif p_kind = 'supplier' then
    select * into s from public.suppliers x where x.id = p_id;
    if s.id is null then return jsonb_build_object('error', 'not-found'); end if;
    if s.status <> 'active' then return jsonb_build_object('error', 'not-active'); end if;
    v_company := coalesce(s.kind, 'company') = 'company';
    v_pay := public.ops_granted('suppliers.pay', 'view');
    select * into l from public.bukku_links x where x.kind = 'supplier' and x.record_id = s.id;
    if l.contact_id is null and s.client_id is not null then
      select * into l from public.bukku_links x where x.kind = 'client' and x.record_id = s.client_id;
    end if;
    return jsonb_build_object('ok', true, 'kind', 'supplier', 'id', s.id,
      'legal_name', public.bukku_name_case(s.name, v_company),
      'entity_type', case when s.currency = 'SGD' then (case when v_company then 'FOREIGN_COMPANY' else 'FOREIGN_INDIVIDUAL' end)
                          else (case when v_company then 'MALAYSIAN_COMPANY' else 'MALAYSIAN_INDIVIDUAL' end) end,
      'reg_no_type', case when v_company and s.brn is not null then 'BRN' when not v_company and v_pay and s.nric is not null then 'NRIC' end,
      'reg_no', case when v_company then s.brn when v_pay then regexp_replace(coalesce(s.nric, ''), '[^0-9]', '', 'g') end,
      'tax_id_no', s.tin, 'sst_reg_no', s.sst_no,
      'email', coalesce(s.finance_email, s.email),
      'phone_no', public.wa_number(coalesce(s.mobile, s.phone), case when s.currency = 'SGD' then 'SG' else 'MY' end),
      'address', s.address, 'country', case when s.currency = 'SGD' then 'SG' else 'MY' end,
      'currency', s.currency,
      'person', public.bukku_name_case(coalesce(s.contact_name, case when not v_company then s.name end), false),
      'payment_term', s.payment_term,
      'our_id', s.code, 'field_id', b.field_supplier, 'type', 'supplier',
      'client_id', s.client_id, 'contact_id', l.contact_id);
  end if;
  return jsonb_build_object('error', 'bad-kind');
end $$;
revoke all on function public.bukku_prepare(text, uuid) from public, anon;
grant execute on function public.bukku_prepare(text, uuid) to authenticated;

create or replace function public.bukku_linked(p_kind text, p_id uuid, p_contact bigint, p_code text)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare me public.team_members := public.ops_me(); v_name text; v_code text; v_client uuid;
begin
  if not public.bukku_may(p_kind, p_id, 'work') then return jsonb_build_object('error', 'denied'); end if;
  if p_contact is null or p_contact <= 0 then return jsonb_build_object('error', 'bad-contact'); end if;
  if p_kind = 'client' then
    select x.name, x.client_code into v_name, v_code from public.clients x where x.id = p_id;
  else
    select coalesce(x.name, x.code), x.code, x.client_id into v_name, v_code, v_client from public.suppliers x where x.id = p_id;
  end if;
  if v_name is null then return jsonb_build_object('error', 'not-found'); end if;
  insert into public.bukku_links (kind, record_id, contact_id, code, sent_at, sent_by, sent_hash)
  values (p_kind, p_id, p_contact, left(p_code, 40), now(), me.id, public.bukku_print(p_kind, p_id))
  on conflict (kind, record_id) do update set contact_id = excluded.contact_id, code = excluded.code,
    sent_at = now(), sent_by = excluded.sent_by, sent_hash = excluded.sent_hash;
  /* One contact for a supplier that is also a client. */
  if v_client is not null then
    insert into public.bukku_links (kind, record_id, contact_id, code, sent_at, sent_by, sent_hash)
    values ('client', v_client, p_contact, left(p_code, 40), now(), me.id, null)
    on conflict (kind, record_id) do update set contact_id = excluded.contact_id, code = excluded.code;
  end if;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, case when p_kind = 'client' then 'client.edited' else 'supplier.edited' end, v_name,
          coalesce(v_code || ' · ', '') || 'Sent to Bukku · ' || coalesce(p_code, p_contact::text));
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.bukku_linked(text, uuid, bigint, text) from public, anon;
grant execute on function public.bukku_linked(text, uuid, bigint, text) to authenticated;

-- END OF BUKKU CONTACTS -----------------------------------------------------

select public.functions_tidy();

-- ===========================================================================
-- A CLIENT'S DEVICE FOLLOWS ONLY A LINK THAT OPENS — push_target refuses a
-- campaign behind a passcode and a Past client's (2026-10-18)
-- ===========================================================================
-- WHY (audit 2026-10-18, item 5): the client branch matched the link key
-- alone, so anyone holding a campaign's key could have a device told of its
-- drafts and posts without the passcode `get_campaign` asks for, and after
-- the client went Past, when `get_campaign` answers `not-found`.
--
-- WHAT IT CHANGES
--   * The client branch finds the campaign only where it has no passcode
--     and its client is not Past; anything else answers no campaign, which
--     `push_subscribe` reads as `not-found`, as the selection page itself
--     does. A campaign with a passcode offers no notifications (none held
--     one on 2026-10-18).
--   * The team and creator branches do not move.
--
-- ORDER: this file; the page needs nothing. Safe to run twice.
-- Rollback: PUSH NOTIFICATIONS' `push_target`.
-- ===========================================================================

create or replace function public.push_target(p_audience text, p_ref text)
returns uuid
language plpgsql stable security definer set search_path = public as $$
declare
  v_code text := upper(regexp_replace(coalesce(p_ref, ''), '[^A-Za-z0-9]', '', 'g'));
  v_id   uuid;
begin
  if p_audience = 'team' then
    return (public.ops_me()).id;
  elsif p_audience = 'client' and coalesce(p_ref, '') <> '' then
    -- The key alone opens only a link with no passcode, of a client not
    -- Past (audit 2026-10-18, item 5).
    select c.id into v_id from public.campaigns c
     where c.access_token = p_ref and coalesce(c.passcode, '') = ''
       and not exists (select 1 from public.clients cl where cl.id = c.client_id and cl.stage = 'past');
  elsif p_audience = 'creator' and length(v_code) >= 8 then
    select k.id into v_id from public.creators k where k.access_code = v_code and k.active;
  end if;
  return v_id;
end $$;
revoke all on function public.push_target(text, text) from public, anon, authenticated;
-- END OF A CLIENT'S DEVICE FOLLOWS ONLY A LINK THAT OPENS -------------------
select public.functions_tidy();

-- ===========================================================================
-- PASSCODE TRIES ARE KEPT FOR A TIME — privacy_retention removes a caller's
-- address against a link once it has been quiet 30 days (2026-10-18)
-- ===========================================================================
-- WHY (audit 2026-10-18, item 14): `link_tries` keeps each caller's address
-- for every link they typed a passcode on, and nothing ever removed a row,
-- so the addresses were kept for good (PDPA 2010: kept no longer than
-- needed).
--
-- WHAT IT CHANGES
--   * `privacy_retention` (the 2nd of each month) also removes each row
--     whose last try and last opening are over 30 days old and whose lock
--     has ended, answering `link_tries_removed`. An address that opened the
--     link within 30 days is kept: the link's own lock spares it.
--   * Everything else it does is HEALTH DATA KEPT FOR A TIME's, unchanged.
--
-- ORDER: this file, in the SQL Editor as one run (the connector holds a
-- statement holding `delete`); it stands in for HEALTH DATA KEPT FOR A
-- TIME's `privacy_retention` where that has not been run. Safe to run twice.
-- Rollback: run HEALTH DATA KEPT FOR A TIME's `privacy_retention` again.
-- ===========================================================================

create or replace function public.privacy_retention(p_now timestamptz default now())
returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_wa integer := 0; v_act integer := 0; v_hc integer := 0; v_hl integer := 0; v_lt integer := 0;
  v_today date := (p_now at time zone 'Asia/Kuala_Lumpur')::date;
  v_keep integer := coalesce(public.app_setting('health_keep_months', (p_now at time zone 'Asia/Kuala_Lumpur')::date), 24)::integer;
  v_left integer := coalesce(public.app_setting('health_leaver_months', (p_now at time zone 'Asia/Kuala_Lumpur')::date), 6)::integer;
  v_gone uuid[];
begin
  update public.wa_outbox o
     set to_number = '', to_name = null, params = '[]'::jsonb, button = null
   where o.created_at < p_now - interval '12 months'
     and o.state not in ('queued', 'sending')
     and (o.to_number <> '' or o.to_name is not null or o.params <> '[]'::jsonb or o.button is not null);
  get diagnostics v_wa = row_count;
  delete from public.activity_log a where a.created_at < p_now - interval '3 years';
  get diagnostics v_act = row_count;
  delete from public.health_checkins k where k.half < v_today - make_interval(months => v_keep);
  get diagnostics v_hc = row_count;
  select coalesce(array_agg(m.id), '{}') into v_gone from public.team_members m
   where not m.active and coalesce(m.removed_at, m.expired_at) < p_now - make_interval(months => v_left);
  if array_length(v_gone, 1) > 0 then
    delete from public.health_checkins k where k.team_member_id = any(v_gone);
    get diagnostics v_hl = row_count;
    delete from public.health_talks t where t.team_member_id = any(v_gone) or t.with_id = any(v_gone);
    delete from public.health_log l where l.team_member_id = any(v_gone);
    delete from public.health_consents c where c.team_member_id = any(v_gone);
  end if;
  -- A caller's address against a link's passcode, once it has had nothing
  -- to say for 30 days and holds no lock (audit 2026-10-18, item 14).
  delete from public.link_tries t
   where greatest(t.last_at, coalesce(t.ok_at, t.last_at)) < p_now - interval '30 days'
     and coalesce(t.locked_until, t.last_at) < p_now;
  get diagnostics v_lt = row_count;
  return jsonb_build_object('whatsapp_cleared', v_wa, 'activity_removed', v_act,
    'health_checkins_removed', v_hc + v_hl, 'health_leavers', coalesce(array_length(v_gone, 1), 0),
    'link_tries_removed', v_lt);
end $$;
revoke all on function public.privacy_retention(timestamptz) from public, anon, authenticated;
-- END OF PASSCODE TRIES ARE KEPT FOR A TIME ---------------------------------

-- ===========================================================================
-- CLIENT LAST ACTIVITY — the Clients list's Last activity in one read.
-- 2026-10-19. Safe to run twice. Rollback at the foot. Mirrored byte for
-- byte in supabase/schema.sql under the same banner; tests/sql.js compares
-- the two.
--
-- WHAT CHANGED (the third audit, item 7)
--   The Clients list worked out each client's Last activity from three
--   reads of every row (calls and visits, Letters of Offer, Documents),
--   none paged, so past PostgREST's thousand rows a table the newest facts
--   were cut off and a client read as quiet that was not. One function now
--   answers, for each client, the newest fact of each kind: the newest call
--   or visit not removed (its kind), the newest Letter of Offer and the
--   newest document (its kind), none dated ahead of now. It runs as the
--   caller (security invoker), so each table's own read policies and the
--   client scope decide what a colleague is answered, as the three reads
--   did; the page takes the newest of the three and names it as before.
--   A call's day is a date; it is answered as that day's midnight in UTC,
--   the moment the page read it as.
--
-- ROLLBACK
--   drop function if exists public.client_last_activity();
--   (pages served before this read the three tables themselves)
-- ===========================================================================

create or replace function public.client_last_activity()
returns table (client_id uuid, source text, kind text, at timestamptz)
language sql stable security invoker set search_path = public as $$
  select t.client_id, 'touch'::text, t.kind::text, t.at
    from (select distinct on (x.client_id) x.client_id, x.kind, (x.happened_at::timestamp at time zone 'UTC') as at
            from public.client_touches x
           where x.archived_at is null and x.client_id is not null
             and (x.happened_at::timestamp at time zone 'UTC') <= now() + interval '1 minute'
           order by x.client_id, x.happened_at desc) t
  union all
  select d.client_id, 'letter'::text, null::text, max(d.created_at)
    from public.client_documents d
   where d.client_id is not null and d.created_at <= now() + interval '1 minute'
   group by d.client_id
  union all
  select g.client_id, 'document'::text, g.kind::text, g.created_at
    from (select distinct on (y.client_id) y.client_id, y.kind, y.created_at
            from public.documents y
           where y.client_id is not null and y.created_at <= now() + interval '1 minute'
           order by y.client_id, y.created_at desc) g
$$;

revoke all on function public.client_last_activity() from public, anon;
grant execute on function public.client_last_activity() to authenticated;

-- END OF CLIENT LAST ACTIVITY ------------------------------------------------
select public.functions_tidy();

-- ===========================================================================
-- WHATSAPP SEND FILED FIRST — a message sent by hand is filed as Sending
-- before it goes, under a lock, so two quick presses send it once.
-- 2026-10-19. Safe to run twice. Rollback at the foot. Mirrored byte for
-- byte in supabase/schema.sql under the same banner; tests/sql.js compares
-- the two.
--
-- WHAT CHANGED
--   wa-send asked Sent recently, then sent, and filed the message only once
--   Meta answered (`wa_sent`), so two presses close together both passed
--   the check and both sent; a send WhatsApp never confirmed was filed
--   Failed, so it did not count as sent; and the sends from before the
--   composer (`report`, `feedback`, `wa_creator_send`) asked nothing at all
--   (the third audit, item 9).
--   * wa_send_begin(p_to_kind, p_to, p_purpose, p_ref, p_template, p_lang,
--     p_category, p_params, p_again) asks wa_compose_prepare as the caller,
--     takes a lock on the recipient, the purpose and the record, refuses
--     `sending` while the same message is on its way, refuses `recent`
--     (as wa_sent_recently answers) unless `p_again`, and files the message
--     as Sending before anything is sent.
--   * wa_send_done(p_id, p_ok, p_wa_id, p_error) closes it, the caller's
--     own row alone: Sent, Not confirmed (an `unknown:` answer, which counts
--     as Sent recently and is never sent again by itself) or Failed, and
--     files `wa.sent` as wa_sent did.
--   * The sends from before the composer are closed to every browser:
--     wa_report_prepare, wa_feedback_prepare, wa_record and wa_creator_send
--     (no page has called them since the composer, 2026-10-10); wa-send no
--     longer answers `report` or `feedback`.
--   wa_sent stays for wa-send as deployed before this file.
--
-- ROLLBACK
--   Redeploy the earlier wa-send first. Then
--     revoke all on function public.wa_send_begin(text, uuid, text, uuid, text, text, text, jsonb, boolean) from public, anon, authenticated;
--     revoke all on function public.wa_send_done(uuid, boolean, text, text) from public, anon, authenticated;
--   and, for a page still calling them, grant execute on the four retired
--   functions to authenticated again.
-- ===========================================================================

create or replace function public.wa_send_begin(p_to_kind text, p_to uuid, p_purpose text, p_ref uuid, p_template text,
                                                p_lang text, p_category text, p_params jsonb, p_again boolean default false)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me     public.team_members := public.ops_me();
  p      jsonb;
  v_rc   jsonb;
  v_ref  uuid;
  v_tpl  text := coalesce(nullif(btrim(p_template), ''), '');
  v_id   uuid;
begin
  if me.id is null then return jsonb_build_object('error', 'denied'); end if;
  p := public.wa_compose_prepare(p_to_kind, p_to, p_purpose, p_ref);
  if p ? 'error' then return p; end if;
  if v_tpl = '' then return jsonb_build_object('error', 'bad-request'); end if;
  -- the same message as wa_sent_recently reads it: a feedback request by
  -- its client, a plain message by its template, anything else its record
  v_ref := case when p_purpose = 'feedback' then (p ->> 'client_id')::uuid
                when p_purpose = 'message' then null else p_ref end;
  -- one send at a time of one message to one person: a second press waits
  -- here until the first is filed, then reads it
  perform pg_advisory_xact_lock(hashtextextended('wa_send:' || p_to_kind || ':' || p_to::text || ':' || p_purpose || ':' ||
    coalesce(v_ref::text, '') || ':' || case when p_purpose = 'message' then v_tpl else '' end, 0));
  if exists (select 1 from public.wa_outbox x
              where x.to_kind = p_to_kind and x.to_id = p_to and x.purpose = p_purpose and x.state = 'sending'
                and x.ref_id is not distinct from v_ref and (p_purpose <> 'message' or x.template = v_tpl)
                and x.claimed_at > now() - interval '5 minutes') then
    return jsonb_build_object('error', 'sending');
  end if;
  if not coalesce(p_again, false) then
    v_rc := public.wa_sent_recently(p_to_kind, p_to, p_purpose, p_ref, v_tpl);
    if coalesce((v_rc ->> 'recent')::boolean, false) then return jsonb_build_object('error', 'recent', 'recent', v_rc); end if;
  end if;
  insert into public.wa_outbox (purpose, to_number, to_name, template, lang, params, ref_kind, ref_id, client_id, state,
                                created_by, claimed_at, tries, to_kind, to_id, category)
  values (p_purpose, p ->> 'number', p ->> 'name', v_tpl, coalesce(nullif(btrim(p_lang), ''), 'en'),
          case when jsonb_typeof(p_params) = 'array' then p_params else '[]'::jsonb end,
          case p_purpose when 'report' then 'report' when 'creator' then 'option' when 'feedback' then 'client'
                         when 'approval' then p ->> 'ref_kind' when 'quotation' then 'quotation' when 'offer' then 'offer' end,
          case when p_purpose in ('report', 'creator', 'approval', 'quotation', 'offer') then p_ref when p_purpose = 'feedback' then (p ->> 'client_id')::uuid end,
          (p ->> 'client_id')::uuid, 'sending', me.name, now(), 1, p_to_kind, p_to,
          nullif(lower(btrim(coalesce(p_category, ''))), ''))
  returning id into v_id;
  return jsonb_build_object('ok', true, 'id', v_id);
end $$;
revoke all on function public.wa_send_begin(text, uuid, text, uuid, text, text, text, jsonb, boolean) from public, anon;
grant execute on function public.wa_send_begin(text, uuid, text, uuid, text, text, text, jsonb, boolean) to authenticated;

create or replace function public.wa_send_done(p_id uuid, p_ok boolean, p_wa_id text, p_error text)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me     public.team_members := public.ops_me();
  w      public.wa_outbox;
  p      jsonb;
  v_word text;
begin
  if me.id is null then return jsonb_build_object('error', 'denied'); end if;
  select * into w from public.wa_outbox x
   where x.id = p_id and x.state = 'sending' and x.created_by = me.name and x.to_kind is not null for update;
  if w.id is null then return jsonb_build_object('error', 'not-found'); end if;
  update public.wa_outbox x
     set state = case when coalesce(p_ok, false) then 'sent'
                      when coalesce(p_error, '') like 'unknown:%' then 'unknown' else 'failed' end,
         wa_id = left(p_wa_id, 200), error = left(p_error, 500),
         sent_at = case when coalesce(p_ok, false) then now() end
   where x.id = w.id;
  if coalesce(p_ok, false) then
    p := public.wa_compose_prepare(w.to_kind, w.to_id, w.purpose,
           case when w.purpose in ('feedback', 'message') then null else w.ref_id end);
    v_word := case w.purpose when 'report' then 'Report' when 'feedback' then 'Feedback request'
                             when 'creator' then 'Booking' when 'approval' then 'Approval reminder'
                             when 'quotation' then 'Quotation' when 'offer' then 'Letter of Offer' else 'Message' end;
    insert into public.activity_log (actor, action, subject, detail)
    values (me.name, 'wa.sent', coalesce(p ->> 'subject', w.to_name),
            case when w.purpose = 'creator' then w.to_name || ' · Booking sent on WhatsApp'
                 else v_word || ' sent on WhatsApp to ' || coalesce(nullif(btrim(w.to_name), ''), 'the contact') end);
  end if;
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.wa_send_done(uuid, boolean, text, text) from public, anon;
grant execute on function public.wa_send_done(uuid, boolean, text, text) to authenticated;

-- The sends from before the composer, closed to every browser (a function
-- already removed is passed over).
do $$
declare f text;
begin
  foreach f in array array['public.wa_report_prepare(uuid)', 'public.wa_feedback_prepare(uuid)',
    'public.wa_record(text, uuid, uuid, text, text, text, jsonb, boolean, text, text)', 'public.wa_creator_send(uuid)'] loop
    if to_regprocedure(f) is not null then
      execute 'revoke all on function ' || f || ' from public, anon, authenticated';
    end if;
  end loop;
end $$;

-- END OF WHATSAPP SEND FILED FIRST ------------------------------------------

select public.functions_tidy();

-- ===========================================================================
-- WHAT A CLIENT TYPES IS HELD TO A LENGTH — names 80, notes 2,000, captions
-- 5,000 in the functions a client page or a creator writes through
-- (2026-10-18)
-- ===========================================================================
-- WHY (audit 2026-10-18, item 12): `submit_review`, `review_draft`,
-- `confirm_selection`, `confirm_selection_with`, `creator_submit` and
-- `portal_request_once` (which `portal_request` calls) took a name, a note
-- or a caption of any length from a page with no sign-in, so one call could
-- write megabytes into the reviews, the requests and the Activity record.
--
-- WHAT IT CHANGES
--   * Each refuses `too-long` (`too_long` in `submit_review`, as its other
--     refusals are written) past 80 characters for a name, 2,000 for a note
--     and 5,000 for a caption, after the link and passcode are proved and
--     before anything is written. `submit_review_seen` and `portal_request`
--     call them and so refuse alike. Nothing else in any of them moves.
--   * The pages are unchanged: no real name, note or caption comes near the
--     limits (Instagram's own caption limit is 2,200), and a refusal reads
--     as Not sent.
--
-- ORDER: this file; the pages need nothing. Safe to run twice.
-- Rollback: run REVIEW DECISIONS ASK THE PASSCODE AS THE PAGE DOES's
-- `submit_review`, PASSCODE LOCKS PER CALLER's `review_draft`,
-- `confirm_selection` and `confirm_selection_with`, the schema's earlier
-- `creator_submit` and CONFIRM ONCE's `portal_request_once` again (each the
-- definition just before this file).
-- ===========================================================================

create or replace function public.submit_review(
  p_token      text,
  p_post_id    uuid,
  p_decision   text,
  p_note       text default null,
  p_reviewer   text default null,
  p_passcode   text default null,
  p_caption    text default null,
  p_caption_zh text default null
) returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_client_id uuid;
  v_stored    text;
  v_post      public.posts%rowtype;
  v_cap       text;
  v_cap_zh    text;
begin
  if p_decision not in ('approved', 'changes') then
    return jsonb_build_object('error', 'bad_decision');
  end if;

  select c.id, c.passcode into v_client_id, v_stored
  from public.clients c
  where c.access_token = p_token
    and c.active
    and not c.review_hidden;

  if v_client_id is null then
    return jsonb_build_object('error', 'not_found');
  end if;
  -- The passcode as the link's own page asks it: counted per caller, and a
  -- caller locked out stays out here too (audit 2026-10-18, item 13).
  case public.link_passcode('review', p_token, v_stored, p_passcode)
    when 'locked' then return public.link_locked('review', p_token);
    when 'wrong' then return jsonb_build_object('error', 'not_found');
    else null;
  end case;
  -- What a client types is held to a length (audit 2026-10-18, item 12).
  if length(coalesce(p_reviewer, '')) > 80 or length(coalesce(p_note, '')) > 2000
     or length(coalesce(p_caption, '')) > 5000 or length(coalesce(p_caption_zh, '')) > 5000 then
    return jsonb_build_object('error', 'too_long');
  end if;

  -- the post must belong to a published batch of this client
  select p.* into v_post
  from public.posts p
  join public.batches b on b.id = p.batch_id
  where p.id = p_post_id and b.client_id = v_client_id and b.published;

  if v_post.id is null then
    return jsonb_build_object('error', 'not_found');
  end if;

  /* A suggested copy is kept only where it differs from the copy on show,
     and only on a request for changes. */
  if p_decision = 'changes' then
    v_cap    := case when p_caption is not null
                      and p_caption is distinct from coalesce(v_post.caption, '') then p_caption end;
    v_cap_zh := case when p_caption_zh is not null
                      and p_caption_zh is distinct from coalesce(v_post.caption_zh, '') then p_caption_zh end;
  end if;

  if p_decision = 'changes' and coalesce(btrim(p_note), '') = ''
     and v_cap is null and v_cap_zh is null then
    return jsonb_build_object('error', 'note_required');
  end if;

  insert into public.reviews (post_id, decision, note, reviewer, suggested_caption, suggested_caption_zh)
  values (p_post_id, p_decision, nullif(btrim(p_note), ''), nullif(btrim(p_reviewer), ''), v_cap, v_cap_zh);

  /* The activity record is the portal's account of what was decided and by
     whom, and it held only what the team did. A client approving a post is
     the decision the whole section exists to collect, and it left nothing
     anybody could produce later: the verdict sat in `reviews` alone, which
     no screen reads as a history. The reviewer's own typed name is the
     actor, because a person decided it. */
  insert into public.activity_log (actor, action, subject, detail)
  select coalesce(nullif(btrim(coalesce(p_reviewer, '')), ''), 'Client'),
         case when p_decision = 'approved' then 'review.approved' else 'review.changes' end,
         c.name,
         b.title || ' · ' || coalesce(nullif(p.platform, ''), 'post') ||
         case when p.round > 1 then ' · revision ' || p.round else '' end ||
         coalesce(' · ' || nullif(btrim(coalesce(p_note, '')), ''), '') ||
         case when v_cap is not null or v_cap_zh is not null then ' · caption edited' else '' end
    from public.posts p
    join public.batches b on b.id = p.batch_id
    join public.clients c on c.id = b.client_id
   where p.id = p_post_id;

  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.submit_review(text, uuid, text, text, text, text, text, text) from public;
grant execute on function public.submit_review(text, uuid, text, text, text, text, text, text) to anon, authenticated;


create or replace function public.review_draft(
  p_token text, p_option uuid, p_decision text, p_note text default null,
  p_reviewer text default null, p_passcode text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  c campaigns%rowtype;
  o campaign_options%rowtype;
  n integer;
begin
  select * into c from campaigns where access_token = p_token;
  if not found then return jsonb_build_object('error', 'not-found'); end if;
  -- A past client's link acts on nothing, as it reads nothing (second
  -- audit, item 7): answered as a key nobody knows, before the passcode.
  if exists (select 1 from public.clients cl where cl.id = c.client_id and cl.stage = 'past') then
    return jsonb_build_object('error', 'not-found');
  end if;
  -- Wrong passcodes lock out the caller who typed them, said as a lock
  -- (second audit, item 4).
  case public.link_passcode('selection', c.access_token, c.passcode, p_passcode)
    when 'locked' then return public.link_locked('selection', c.access_token);
    when 'wrong' then return jsonb_build_object('error', 'passcode');
    else null;
  end case;
  if p_decision not in ('approved', 'changes') then
    return jsonb_build_object('error', 'bad-decision');
  end if;
  -- What a client types is held to a length (audit 2026-10-18, item 12).
  if length(coalesce(p_reviewer, '')) > 80 or length(coalesce(p_note, '')) > 2000 then
    return jsonb_build_object('error', 'too-long');
  end if;

  select * into o from campaign_options
   where id = p_option and campaign_id = c.id;
  if not found then return jsonb_build_object('error', 'not-found'); end if;

  -- Only a draft that is actually with the client can be ruled on.
  if o.state not in ('reviewing', 'changes') then
    return jsonb_build_object('error', 'not-reviewing');
  end if;
  /* A draft the team sent back to the creator is not with the client: the
     selection page shows it as Pending draft, so only a hand-made call
     could rule on it (audit B, 2026-10-17). */
  if o.state = 'changes' and coalesce(o.changes_by, 'client') = 'team' then
    return jsonb_build_object('error', 'not-reviewing');
  end if;

  n := coalesce(o.revision_round, 0);

  insert into option_reviews (option_id, round, decision, note, reviewer)
  values (p_option, greatest(n, 1), p_decision, nullif(trim(coalesce(p_note, '')), ''), p_reviewer);

  if p_decision = 'approved' then
    update campaign_options set state = 'scheduled' where id = p_option;
  else
    update campaign_options
       set state = 'changes', revision_round = greatest(n, 1) + 1,
           changes_by = 'client'
     where id = p_option;
  end if;

  /* The client's decision is the one event on a campaign that nobody on the
     team witnesses, and it was the only one the activity record never held:
     a draft went to Reviewing and appeared as Scheduled with nothing in
     between saying who had said yes. The reviewer's own name is the actor,
     because a person decided it. */
  insert into activity_log (actor, action, subject, detail)
  select coalesce(nullif(trim(coalesce(p_reviewer, '')), ''), 'Client'),
         'campaign.review', c.title,
         cr.name || ' · ' ||
         case when p_decision = 'approved' then 'Approved' else 'Changes requested' end ||
         coalesce(': ' || nullif(trim(coalesce(p_note, '')), ''), '')
    from creators cr where cr.id = o.creator_id;

  return jsonb_build_object('ok', true, 'decision', p_decision);
end $$;


create or replace function public.confirm_selection(
  p_token text, p_person text, p_passcode text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  c campaigns%rowtype;
begin
  select * into c from campaigns where access_token = p_token;
  if not found then return jsonb_build_object('error', 'not-found'); end if;
  -- A past client's link acts on nothing, as it reads nothing (second
  -- audit, item 7): answered as a key nobody knows, before the passcode.
  if exists (select 1 from public.clients cl where cl.id = c.client_id and cl.stage = 'past') then
    return jsonb_build_object('error', 'not-found');
  end if;
  -- Wrong passcodes lock out the caller who typed them, said as a lock
  -- (second audit, item 4).
  case public.link_passcode('selection', c.access_token, c.passcode, p_passcode)
    when 'locked' then return public.link_locked('selection', c.access_token);
    when 'wrong' then return jsonb_build_object('error', 'passcode');
    else null;
  end case;
  if coalesce(trim(p_person), '') = '' then
    return jsonb_build_object('error', 'name-required');
  end if;
  -- What a client types is held to a length (audit 2026-10-18, item 12).
  if length(btrim(p_person)) > 80 then return jsonb_build_object('error', 'too-long'); end if;
  if c.selection_closed_at is not null and not coalesce(c.backups_open, false) then
    return jsonb_build_object('error', 'closed');
  end if;
  -- Nothing saved is nothing to confirm (a save refused under the page).
  if not exists (select 1 from campaign_options o
                  where o.campaign_id = c.id
                    and o.state = case when c.selection_closed_at is not null
                                       then 'backup' else 'shortlisted' end) then
    return jsonb_build_object('error', 'empty');
  end if;

  insert into campaign_confirmations (campaign_id, kind, person, source)
  values (c.id, 'client', trim(p_person), 'portal');

  insert into public.activity_log (actor, action, subject, detail)
  values (trim(p_person), 'campaign.confirmed', c.title,
          (select count(*)::text || ' creator' || case when count(*) = 1 then '' else 's' end
             from campaign_options
            where campaign_id = c.id and state = 'shortlisted') || ' confirmed');

  return jsonb_build_object('ok', true);
end $$;


create or replace function public.confirm_selection_with(
  p_token text, p_person text, p_passcode text, p_selected uuid[], p_backup uuid[],
  p_seen jsonb, p_idem text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  c      campaigns%rowtype;
  v_sel  uuid[];
  v_bak  uuid[];
  v_all  uuid[];
  v_idem text := left(nullif(btrim(coalesce(p_idem, '')), ''), 64);
  v_now  jsonb;
  v_snap jsonb;
  n      integer;
  v_booked integer;
begin
  select * into c from campaigns where access_token = p_token for update;
  if not found then return jsonb_build_object('error', 'not-found'); end if;
  -- A past client's link acts on nothing, as it reads nothing (second
  -- audit, item 7): answered as a key nobody knows, before the passcode.
  if exists (select 1 from public.clients cl where cl.id = c.client_id and cl.stage = 'past') then
    return jsonb_build_object('error', 'not-found');
  end if;
  -- Wrong passcodes lock out the caller who typed them, said as a lock
  -- (second audit, item 4).
  case public.link_passcode('selection', c.access_token, c.passcode, p_passcode)
    when 'locked' then return public.link_locked('selection', c.access_token);
    when 'wrong' then return jsonb_build_object('error', 'passcode');
    else null;
  end case;
  if coalesce(trim(p_person), '') = '' then
    return jsonb_build_object('error', 'name-required');
  end if;
  -- What a client types is held to a length (audit 2026-10-18, item 12).
  if length(btrim(p_person)) > 80 then return jsonb_build_object('error', 'too-long'); end if;
  -- The same press again: the first answer stands and nothing is filed twice.
  if v_idem is not null and exists (select 1 from campaign_confirmations k
                                     where k.campaign_id = c.id and k.idem = v_idem) then
    return jsonb_build_object('ok', true, 'again', true);
  end if;

  v_sel := array(select distinct x from unnest(coalesce(p_selected, '{}'::uuid[])) x where x is not null);
  v_bak := case when coalesce(c.backups_open, false)
                then array(select distinct x from unnest(coalesce(p_backup, '{}'::uuid[])) x
                            where x is not null and not (x = any (v_sel)))
                else '{}'::uuid[] end;
  v_all := v_sel || v_bak;
  n := cardinality(v_sel);

  if c.selection_closed_at is not null and not (coalesce(c.backups_open, false) and n = 0) then
    return jsonb_build_object('error', 'closed');
  end if;
  if cardinality(v_all) = 0 then return jsonb_build_object('error', 'empty'); end if;
  -- The slots left are the slots less the creators already booked: a
  -- selection reopened for four of ten never books sixteen.
  v_booked := public.campaign_booked(c.id);
  if n > 0 and n > c.slots - v_booked then
    return jsonb_build_object('error', 'over-slots', 'slots', c.slots, 'booked', v_booked);
  end if;
  -- Every creator named is still on the campaign and open to choose.
  if (select count(*) from campaign_options o
       where o.id = any (v_all) and o.campaign_id = c.id
         and o.state in ('option', 'shortlisted', 'backup')) <> cardinality(v_all) then
    return jsonb_build_object('error', 'stale');
  end if;
  -- The prices the client read are the prices now.
  select jsonb_object_agg(o.id::text, o.rate) into v_now
    from campaign_options o where o.id = any (v_all);
  if exists (select 1 from campaign_options o
              where o.id = any (v_all)
                and coalesce(p_seen -> (o.id::text), 'null'::jsonb)
                    is distinct from coalesce(to_jsonb(o.rate), 'null'::jsonb)) then
    return jsonb_build_object('error', 'prices', 'rates', v_now);
  end if;

  update campaign_options set state = 'option'
   where campaign_id = c.id and state in ('shortlisted', 'backup');
  if n > 0 then
    update campaign_options set state = 'shortlisted'
     where campaign_id = c.id and id = any (v_sel) and state = 'option';
  end if;
  if cardinality(v_bak) > 0 then
    update campaign_options set state = 'backup'
     where campaign_id = c.id and id = any (v_bak) and state = 'option';
  end if;

  select jsonb_agg(jsonb_build_object('id', o.id, 'creator', cr.name, 'rate', o.rate, 'as', o.state)
                   order by o.position, o.added_at)
    into v_snap
    from campaign_options o join creators cr on cr.id = o.creator_id
   where o.id = any (v_all);
  insert into campaign_confirmations (campaign_id, kind, person, source, idem, snapshot)
  values (c.id, 'client', trim(p_person), 'portal', v_idem, coalesce(v_snap, '[]'::jsonb));

  insert into public.activity_log (actor, action, subject, detail)
  values (trim(p_person), 'campaign.confirmed', c.title,
          case when n > 0 then n::text || ' creator' || case when n = 1 then '' else 's' end || ' confirmed'
               else cardinality(v_bak)::text || ' backup' || case when cardinality(v_bak) = 1 then '' else 's' end || ' confirmed' end);

  return jsonb_build_object('ok', true, 'selected', n);
end $$;


create or replace function public.creator_submit(p_code text, p_option uuid, p_caption text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  cr creators%rowtype;
  o  campaign_options%rowtype;
  n  integer;
begin
  select * into cr from creators where access_code = upper(p_code) and active;
  if not found then return jsonb_build_object('error', 'not-found'); end if;
  select * into o from campaign_options where id = p_option and creator_id = cr.id;
  if not found then return jsonb_build_object('error', 'not-found'); end if;
  if not public.creator_can_deliver(o.state) then
    return jsonb_build_object('error', 'closed');
  end if;
  -- What a creator types is held to a length (audit 2026-10-18, item 12).
  if length(coalesce(p_caption, '')) > 5000 then return jsonb_build_object('error', 'too-long'); end if;
  select count(*) into n from campaign_deliverables
   where option_id = p_option and removed_at is null;
  if n = 0 then return jsonb_build_object('error', 'empty'); end if;

  /* `submitted` is ours, not the client's. It used to move straight to
     `reviewing`, which on the client's page reads "Your approval": the chip
     asked them to act the moment a creator uploaded, while the files are
     team-only, so there was nothing there for them to open. The team reviews
     it and releases it. */
  update campaign_options
     set state = 'submitted', draft_caption = p_caption, submitted_at = now(),
         changes_by = null          -- that round is over, whoever raised it
   where id = p_option;

  -- A creator is a party to this too, and when they handed in is exactly the
  -- fact a late delivery turns on.
  insert into public.activity_log (actor, action, subject, detail)
  select cr.name, 'campaign.submitted', c.title,
         n::text || ' file' || case when n = 1 then '' else 's' end || ' handed in'
         || case when o.state = 'submitted' then ' · updated' else '' end
    from campaigns c where c.id = o.campaign_id;

  return jsonb_build_object('ok', true, 'files', n);
end $$;


create or replace function public.portal_request_once(
  p_client uuid, p_kind text, p_service uuid, p_note text, p_idem text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  who    text := lower(auth.jwt() ->> 'email');
  cl     public.clients%rowtype;
  me     public.client_contacts%rowtype;
  sv     public.client_services%rowtype;
  rid    uuid;
  v_idem text := left(nullif(btrim(coalesce(p_idem, '')), ''), 64);
begin
  if who is null then return jsonb_build_object('error', 'not-signed-in'); end if;
  if p_client is null or p_client not in (select public.portal_clients()) then
    return jsonb_build_object('error', 'no-access');
  end if;
  -- The same request again (a reply lost on the way): the one already filed.
  if v_idem is not null then
    select r.id into rid from public.client_requests r
     where r.client_id = p_client and r.idem = v_idem;
    if rid is not null then return jsonb_build_object('ok', true, 'id', rid, 'again', true); end if;
  end if;
  if p_kind not in ('upgrade', 'downgrade', 'cancel', 'details') then
    return jsonb_build_object('error', 'bad-kind');
  end if;
  -- What a client types is held to a length (audit 2026-10-18, item 12).
  if length(coalesce(p_note, '')) > 2000 then return jsonb_build_object('error', 'too-long'); end if;
  select * into cl from public.clients where id = p_client;
  select * into me from public.client_contacts
    where client_id = p_client and portal_access and archived_at is null and lower(email) = who
    order by is_primary desc limit 1;
  if p_kind <> 'details' then
    select * into sv from public.client_services
      where id = p_service and client_id = p_client and archived_at is null and state = 'confirmed';
    if sv.id is null then return jsonb_build_object('error', 'not-found'); end if;
  end if;
  if p_kind <> 'cancel' and coalesce(btrim(p_note), '') = '' then
    return jsonb_build_object('error', 'note-required');
  end if;
  insert into public.client_requests (client_id, contact_id, contact_name, kind, service_id, service_label, note, idem)
  values (p_client, me.id, me.name, p_kind, sv.id, sv.label, nullif(btrim(p_note), ''), v_idem)
  on conflict (client_id, idem) where idem is not null do nothing
  returning id into rid;
  if rid is null then
    select r.id into rid from public.client_requests r
     where r.client_id = p_client and r.idem = v_idem;
    return jsonb_build_object('ok', true, 'id', rid, 'again', true);
  end if;
  insert into public.activity_log (actor, action, subject, detail)
  values (who, 'request.raised', cl.name, p_kind || coalesce(' · ' || sv.label, ''));
  return jsonb_build_object('ok', true, 'id', rid);
end $$;
-- END OF WHAT A CLIENT TYPES IS HELD TO A LENGTH ----------------------------

-- ===========================================================================
-- OPS REPORTS AT ONCE — the Dashboard's work figures in one request.
-- 2026-10-19. Safe to run twice. Rollback at the foot. Mirrored byte for
-- byte in supabase/schema.sql under the same banner; tests/ops.js compares
-- the two.
--
-- WHAT CHANGED (the third audit, item 19)
--   The Dashboard asked ops_report eight times a visit: the period, the
--   period before it, and each of the last six months for the on-time line
--   and the deliveries. ops_reports(p_ranges) takes the spans as a list
--   (`[{ "from": …, "to": … }, …]`, twelve at most) and answers ops_report's
--   own answer for each, in order, so every figure is the one ops_report
--   gives and the page makes one request. It runs as the caller, so
--   ops_report's own check (My Work: Reports, `denied`) answers as before.
--
-- ROLLBACK
--   drop function if exists public.ops_reports(jsonb);
--   (pages served before this ask ops_report a span at a time)
-- ===========================================================================

create or replace function public.ops_reports(p_ranges jsonb)
returns jsonb
language sql stable security invoker set search_path = public as $$
  select coalesce(jsonb_agg(public.ops_report((x.r ->> 'from')::timestamptz, (x.r ->> 'to')::timestamptz) order by x.n), '[]'::jsonb)
    from jsonb_array_elements(case when jsonb_typeof(p_ranges) = 'array' then p_ranges else '[]'::jsonb end)
         with ordinality x(r, n)
   where x.n <= 12
$$;

revoke all on function public.ops_reports(jsonb) from public, anon;
grant execute on function public.ops_reports(jsonb) to authenticated;

-- END OF OPS REPORTS AT ONCE -------------------------------------------------
select public.functions_tidy();

-- ===========================================================================
-- WAKE CALLS CARRY A SECRET — wa-send's drain and push-send answer only the
-- database's own wake, and a write wakes each of them once.
-- 2026-10-19. Safe to run twice. Rollback at the foot. Mirrored byte for
-- byte in supabase/schema.sql under the same banner; tests/sql.js compares
-- the two.
--
-- WHAT CHANGED
--   wa-send's `drain` and push-send ran for any caller with no sign-in, so
--   anybody could make them work through the queues on demand; and each
--   queued row woke its sender again, so a notice to forty colleagues
--   started forty runs of push-send (the third audit, item 17).
--   * A wake secret is made once in `app_secrets` (`wake_secret`, 244
--     random bits from gen_random_uuid), never shown to a page or a person.
--   * wa_kick and push_kick send it as the `x-adspace-wake` header, and wake
--     once a transaction (a statement queueing forty messages wakes once;
--     pg_net sends after the commit, so the one wake finds them all).
--   * wake_secret_ok(p_given) answers whether a header is the secret, to
--     the service role alone; wa-send's `drain` and push-send ask it and
--     refuse anything else (401) before touching a queue
--     (supabase/functions/wa-send, supabase/functions/push-send).
--   The pg_cron job `outbox-drain` wakes them through the same two
--   functions, so it carries the secret too.
--
-- ROLLBACK
--   Redeploy the earlier wa-send and push-send first. Then run push_kick
--   of the PUSH NOTIFICATIONS section and wa_kick of the WHATSAPP section
--   of supabase/schema.sql again (they send no header).
-- ===========================================================================

insert into public.app_secrets (key, value)
values ('wake_secret', replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', ''))
on conflict (key) do nothing;

create or replace function public.wake_secret_ok(p_given text)
returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce(length(p_given) >= 32, false) and exists (
    select 1 from public.app_secrets s where s.key = 'wake_secret' and s.value = p_given)
$$;
revoke all on function public.wake_secret_ok(text) from public, anon, authenticated;
grant execute on function public.wake_secret_ok(text) to service_role;

create or replace function public.wa_kick()
returns void
language plpgsql security definer set search_path = public as $$
begin
  -- once a transaction: the one wake, sent after the commit, finds every row
  if current_setting('adspace.wa_kicked', true) = '1' then return; end if;
  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
                  where n.nspname = 'net' and p.proname = 'http_post') then
    return;
  end if;
  execute 'select net.http_post(url := $1, body := $2, headers := $3)'
    using 'https://hwwuigvdfubuymchsvyx.supabase.co/functions/v1/wa-send', '{"action":"drain"}'::jsonb,
          jsonb_build_object('Content-Type', 'application/json', 'x-adspace-wake',
            coalesce((select s.value from public.app_secrets s where s.key = 'wake_secret'), ''));
  perform set_config('adspace.wa_kicked', '1', true);
exception when others then
  return;
end $$;
revoke all on function public.wa_kick() from public, anon, authenticated;

create or replace function public.push_kick()
returns void
language plpgsql security definer set search_path = public as $$
begin
  -- once a transaction: the one wake, sent after the commit, finds every row
  if current_setting('adspace.push_kicked', true) = '1' then return; end if;
  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
                  where n.nspname = 'net' and p.proname = 'http_post') then
    return;
  end if;
  execute 'select net.http_post(url := $1, body := $2, headers := $3)'
    using 'https://hwwuigvdfubuymchsvyx.supabase.co/functions/v1/push-send', '{}'::jsonb,
          jsonb_build_object('Content-Type', 'application/json', 'x-adspace-wake',
            coalesce((select s.value from public.app_secrets s where s.key = 'wake_secret'), ''));
  perform set_config('adspace.push_kicked', '1', true);
exception when others then
  return;
end $$;
revoke all on function public.push_kick() from public, anon, authenticated;

-- END OF WAKE CALLS CARRY A SECRET ------------------------------------------

