-- ===========================================================================
-- A MOVED DATE READS AS THE HOUSE WRITES IT — the notice of a task's moved
-- date names its Malaysian day as `12 Sept 2026`. 2026-10-19. Safe to run
-- twice. Rollback at the foot. Mirrored byte for byte in
-- supabase/schema.sql under the same banner; tests/ops.js compares the two.
--
-- WHAT CHANGED (the third audit, item 20)
--   ops_log wrote a moved first draft or final date as
--   to_char(…, 'DD Mon YYYY'): "05 Sep 2026", where the house writes
--   "5 Sept 2026" (register_day), and read on the database's UTC clock, so
--   a date at midnight in Malaysia read as the day before. It now names the
--   Malaysian day through register_day. Every other line is ONE PRESS, ONE
--   NOTICE's, unchanged.
--
-- ROLLBACK
--   Run ops_log as ONE PRESS, ONE NOTICE stated it
--   (2026-10-18-one-press-one-notice.sql).
-- ===========================================================================

create or replace function public.ops_log(
  p_task uuid, p_type text, p_from jsonb, p_to jsonb, p_detail jsonb default '{}'::jsonb)
returns void
language plpgsql security definer set search_path = public as $$
declare
  m      public.team_members;
  t      public.ops_tasks;
  owner  uuid;
  who    text;
  body   text;
  st     public.ops_workflow_stages;
begin
  m := public.ops_me();
  insert into public.ops_task_events (task_id, event_type, actor_id, actor_email,
                                      from_value, to_value, detail)
  values (p_task, p_type, m.id, m.email, p_from, p_to, coalesce(p_detail, '{}'::jsonb));

  select * into t from public.ops_tasks where id = p_task;
  if t.id is null then return; end if;
  who := coalesce(nullif(m.name, ''), m.email, 'Somebody');

  if p_type = 'assignment_changed' then
    owner := (p_to ->> 'owner_id')::uuid;
    if owner is not null and owner is distinct from m.id then
      perform public.ops_notify(owner, p_task, 'assigned',
        public.ops_serial(t.task_no) || ' · ' || public.ops_title(t),
        case when coalesce((p_detail ->> 'handover')::boolean, false)
             then 'Handed to you by ' || who || ' at ' ||
                  coalesce((public.ops_stage(t.workflow_id, p_detail ->> 'stage_key')).label, p_detail ->> 'stage_key') || '.'
             else 'Assigned to you by ' || who || '.' end,
        'assigned:' || p_task::text || ':' || owner::text || ':' || to_char(now(), 'YYYYMMDDHH24MI'));
    end if;
    return;
  end if;

  select team_member_id into owner from public.ops_task_assignees
   where task_id = p_task and responsibility = 'owner' and ended_at is null
   limit 1;
  if owner is null or owner = m.id then return; end if;

  if p_type = 'stage_changed' then
    /* One press, one notice (2026-10-18): a move that also handed the task
       on has already told its new owner, in the same transaction, with the
       stage it was handed at. */
    if exists (select 1 from public.ops_task_events e
                where e.task_id = p_task and e.event_type = 'assignment_changed'
                  and e.created_at = now()
                  and coalesce((e.detail ->> 'handover')::boolean, false)
                  and e.to_value ->> 'owner_id' = owner::text) then
      return;
    end if;
    st := public.ops_stage(t.workflow_id, p_to ->> 'stage_key');
    body := 'Moved to ' || coalesce(st.label, p_to ->> 'stage_key')
      || coalesce(', round ' || (p_detail ->> 'round'), '') || ' by ' || who || '.';
  elsif p_type = 'due_changed' then
    body := 'The ' || case when p_to ->> 'kind' = 'final' then 'final' else 'first draft' end
      || ' date moved to ' || public.register_day(((p_to ->> 'value')::timestamptz at time zone 'Asia/Kuala_Lumpur')::date)
      || ' by ' || who || '.';
  elsif p_type = 'blocked' then
    body := 'Marked blocked by ' || who || ': '
      || coalesce(p_detail ->> 'category', 'reason not given') || '.';
  elsif p_type = 'unblocked' then
    body := 'Unblocked by ' || who || '.';
  elsif p_type = 'revision_requested' then
    body := 'A revision was requested by ' || who || '.';
  elsif p_type = 'approval_recorded' then
    body := 'A review decision was recorded by ' || who || '.';
  elsif p_type = 'reopened' then
    body := 'Reopened by ' || who || '.';
  elsif p_type = 'cancelled' then
    body := 'Cancelled by ' || who || '.';
  elsif p_type = 'commented' then
    body := who || ' commented: ' ||
      case when length(coalesce(p_detail ->> 'note', '')) > 140
           then left(p_detail ->> 'note', 139) || '…' else coalesce(p_detail ->> 'note', '') end;
  else
    return;
  end if;

  perform public.ops_notify(owner, p_task, p_type,
    public.ops_serial(t.task_no) || ' · ' || public.ops_title(t), body,
    p_type || ':' || p_task::text || ':' || owner::text || ':' ||
      /* Two comments in one minute are two things said; the same change
         twice in a minute is one. */
      case when p_type = 'commented' then md5(body) else to_char(now(), 'YYYYMMDDHH24MI') end);
end $$;

-- END OF A MOVED DATE READS AS THE HOUSE WRITES IT -------------------------

-- ===========================================================================
-- ON TIME COUNTS LATE OPEN WORK — the Dashboard's on-time figure counts the
-- work still late as missed. 2026-10-19. Safe to run twice. Rollback at the
-- foot. Mirrored byte for byte in supabase/schema.sql under the same banner;
-- tests/ops.js compares the two.
--
-- WHAT CHANGED (the user, 2026-10-19: "there are late tasks yet showing 100%
-- on time delivery")
--   ops_report's on_time counted only the tasks that reached client review
--   in the period, so a task past its deadline and still short of its
--   review was in neither figure: the ring read 100% beside three late
--   tasks. on_time now also answers `late_open`: the open tasks late by the
--   rule of WHAT IS LATE, counted in the period their first missed deadline
--   fell in and in any period that runs to now. The Dashboard reads on time
--   as met over reached plus late_open. Every other figure is unchanged.
--
-- ROLLBACK
--   Run ops_report as MY WORK REPORT KEEPS CLIENT SCOPE stated it (pages
--   read a missing late_open as none).
-- ===========================================================================

create or replace function public.ops_report(
  p_from timestamptz default (now() - interval '90 days'),
  p_to   timestamptz default now())
returns jsonb
language plpgsql security definer stable set search_path = public as $$
declare
  out jsonb;
begin
  if not public.ops_granted('ops.reports', 'view') then
    return jsonb_build_object('error', 'denied');
  end if;

  with
  /* Where client review begins in each workflow. The final due date is the
     day the work is owed AT that stage, so everything below that position is
     "has not reached the client yet". Read from `stage_group` and never from
     a stage key: the two seeded workflows name that stage differently. */
  floors as (
    select workflow_id, min(position) as at
      from public.ops_workflow_stages
     where stage_group = 'client_review'
     group by workflow_id
  ),
  /* Where a priority's deadline is met (2026-10-11): client review, else the
     workflow's first review (an everyday task's Review). */
  pfloors as (
    select workflow_id,
           coalesce(min(position) filter (where stage_group = 'client_review'),
                    min(position) filter (where stage_group = 'internal_review')) as at
      from public.ops_workflow_stages
     group by workflow_id
  ),
  live as (
    select t.*, s.label as stage_label, s.position as stage_position,
           s.stage_group, f.at as review_at,
           public.ops_priority_by(coalesce(t.priority_at, t.created_at), t.priority_level) as prio_by, pf.at as prio_at
      from public.ops_tasks t
      join public.ops_workflow_stages s
        on s.workflow_id = t.workflow_id and s.key = t.stage_key
      left join floors f on f.workflow_id = t.workflow_id
      left join pfloors pf on pf.workflow_id = t.workflow_id
     where t.completed_at is null and t.cancelled_at is null
       and t.archived_at is null
       /* Client scope: a colleague on Own clients only reads the work of
          the clients they hold, and their own tasks always (2026-10-18). */
       and public.ops_task_in_scope(t.id)
  ),

  /* 1. WHAT IS RUNNING, by the words on the screen. Grouped by the stage's
        own label rather than by its group, because "what is on shooting" is
        the question and Shooting is a label, not a group. */
  running as (
    select jsonb_agg(x order by x ->> 'position', x ->> 'label') as j from (
      select jsonb_build_object(
               'stage_key', stage_key, 'label', stage_label,
               'position', stage_position, 'stage_group', stage_group,
               'count', count(*)) as x
        from live
       group by stage_key, stage_label, stage_position, stage_group
    ) q
  ),

  /* 2. WHAT IS LATE. Past the commitment and still short of client review,
        or past a priority's deadline and short of its review (On hold and
        Blocked still count): whichever comes first (the user, 2026-10-11).
        The same rule the queue row draws, stated once more here because a
        report a page computes for itself is a second definition. */
  late_now as (
    select l.*,
           (l.current_final_due_at is not null and (l.current_final_due_at at time zone 'Asia/Kuala_Lumpur')::date < (now() at time zone 'Asia/Kuala_Lumpur')::date
            and (l.review_at is null or l.stage_position < l.review_at)) as due_late,
           (l.prio_by is not null and l.prio_by < now()
            and (l.prio_at is null or l.stage_position < l.prio_at or l.stage_group in ('kiv', 'blocked'))) as prio_late
      from live l
  ),
  late as (
    select jsonb_agg(x order by x ->> 'due_at') as j from (
      select jsonb_build_object(
               'task_id', l.id, 'task_no', l.task_no, 'title', l.title,
               'client', c.name, 'stage', l.stage_label,
               'due_at', case when l.prio_late and (not l.due_late or l.prio_by < l.current_final_due_at)
                              then l.prio_by else l.current_final_due_at end,
               'days_over', greatest(case when l.due_late then (now() at time zone 'Asia/Kuala_Lumpur')::date - (l.current_final_due_at at time zone 'Asia/Kuala_Lumpur')::date end,
                                     case when l.prio_late then floor(extract(epoch from (now() - l.prio_by)) / 86400)::int end),
               'over_minutes', case when l.prio_late then floor(extract(epoch from (now() - l.prio_by)) / 60)::int end,
               'owner', (select tm.name
                           from public.ops_task_assignees a
                           join public.team_members tm on tm.id = a.team_member_id
                          where a.task_id = l.id and a.responsibility = 'owner'
                            and a.ended_at is null
                          limit 1)) as x
        from late_now l
        left join public.clients c on c.id = l.client_id
       where l.due_late or l.prio_late
    ) q
  ),

  /* 3. HOW LONG EACH STAGE TAKES. A task enters a stage at the event that
        names it and leaves at the next event, or at its own ending, or now.
        Only spans that were ENTERED inside the period are counted, so the
        window means what it says and a task that sat in Editing since March
        does not land in every report for ever. */
  spans as (
    select e.task_id,
           e.to_value ->> 'stage_key' as stage_key,
           e.created_at as from_at,
           coalesce(
             lead(e.created_at) over (partition by e.task_id order by e.created_at),
             t.completed_at, t.cancelled_at, now()) as to_at
      from public.ops_task_events e
      join public.ops_tasks t on t.id = e.task_id
     where e.event_type in ('task_created', 'stage_changed')
       and e.to_value ->> 'stage_key' is not null
       and public.ops_task_in_scope(t.id)
       /* Only a span entered in the period is counted, and its end is the
          task's next event, never an earlier one: what came before the
          period is not read (2026-10-18). */
       and e.created_at >= p_from
  ),
  /* One row per span and no grouping: an earlier draft grouped by the span's
     own timestamps, which silently collapsed two tasks that entered the same
     stage in the same instant into one measurement. The label is looked up
     once per stage below instead of aggregated here. */
  span_mins as (
    select s.stage_key,
           extract(epoch from (s.to_at - s.from_at)) / 60 as mins
      from spans s
     where s.from_at >= p_from and s.from_at < p_to
       and s.to_at > s.from_at
  ),
  stage_time as (
    select jsonb_agg(x order by x ->> 'label') as j from (
      select jsonb_build_object(
               'stage_key', stage_key,
               'label', coalesce((select w.label from public.ops_workflow_stages w
                                   where w.key = sm.stage_key limit 1), stage_key),
               'n', count(*),
               'median_minutes', round(percentile_cont(0.5) within group (order by mins))::int,
               'p90_minutes', round(percentile_cont(0.9) within group (order by mins))::int) as x
        from span_mins sm
       group by stage_key
    ) q
  ),

  /* 4. WAS IT THERE ON TIME. Of the tasks that reached client review inside
        the period, how many got there on or before the date they were owed;
        the work still late is counted beside them (`late_open`).
        Replanning is counted beside it and never folded into it: an extension
        that moves the date would otherwise erase the miss it was granted for,
        and a rate that cannot be missed is not a measurement. */
  reached as (
    select distinct on (e.task_id)
           e.task_id, e.created_at as at, t.current_final_due_at as due,
           public.ops_priority_by(coalesce(t.priority_at, t.created_at), t.priority_level) as prio_by,
           (t.original_final_due_at is distinct from t.current_final_due_at) as replanned
      from public.ops_task_events e
      join public.ops_tasks t on t.id = e.task_id
      join public.ops_workflow_stages w
        on w.workflow_id = t.workflow_id and w.key = e.to_value ->> 'stage_key'
     where e.event_type = 'stage_changed'
       and w.stage_group = 'client_review'
       and public.ops_task_in_scope(t.id)
       and e.created_at >= p_from and e.created_at < p_to
     order by e.task_id, e.created_at
  ),
  /* Work still short of its review and past its deadline is a miss too
     (2026-10-19, the user: "there are late tasks yet showing 100% on time
     delivery"): counted in the period its first missed deadline fell in,
     and in any period that runs to now (its end within ten minutes of now:
     the page names the moment it asks), where it is still late. A task
     counted as reached in the period is not counted again. */
  late_open as (
    select l.id
      from late_now l
     where (l.due_late or l.prio_late)
       and not exists (select 1 from reached r where r.task_id = l.id)
       and (case when l.prio_late and (not l.due_late or l.prio_by < l.current_final_due_at)
                 then l.prio_by else l.current_final_due_at end) < p_to
       and ((case when l.prio_late and (not l.due_late or l.prio_by < l.current_final_due_at)
                  then l.prio_by else l.current_final_due_at end) >= p_from
            or p_to >= now() - interval '10 minutes')
  ),
  on_time as (
    select jsonb_build_object(
             'reached', count(*),
             'met', count(*) filter (where (due is null or at::date <= due::date) and (prio_by is null or at <= prio_by)),
             'missed', count(*) filter (where not ((due is null or at::date <= due::date) and (prio_by is null or at <= prio_by))),
             'late_open', (select count(*) from late_open),
             'replanned', count(*) filter (where replanned)) as j
      from reached
  ),

  /* 5. BY PERSON. The foundation of a KPI and not a KPI: what somebody
        finished in the window, how much of it was on time, and how long their
        work took end to end. No ranking and no score — a number a person can
        check is worth more than a league table nobody trusts. */
  done as (
    select t.id, t.created_at, coalesce(t.completed_at, t.delivered_at) as ended,
           t.current_final_due_at as due,
           public.ops_priority_by(coalesce(t.priority_at, t.created_at), t.priority_level) as prio_by,
           /* When a priority's deadline was met: the first move into its
              review or beyond (never On hold, Blocked or Cancelled). */
           (select min(e.created_at)
              from public.ops_task_events e
              join public.ops_workflow_stages w
                on w.workflow_id = t.workflow_id and w.key = e.to_value ->> 'stage_key'
              join pfloors pf on pf.workflow_id = t.workflow_id
             where e.task_id = t.id and e.event_type = 'stage_changed'
               and w.position >= pf.at and w.stage_group not in ('kiv', 'blocked', 'cancelled')) as met_at,
           (select a.team_member_id
              from public.ops_task_assignees a
             where a.task_id = t.id and a.responsibility = 'owner'
             order by a.ended_at nulls first, a.assigned_at desc
             limit 1) as owner_id
      from public.ops_tasks t
     where t.completed_at is not null
       and t.completed_at >= p_from and t.completed_at < p_to
       and public.ops_task_in_scope(t.id)
  ),
  by_person as (
    select jsonb_agg(x order by x ->> 'name') as j from (
      select jsonb_build_object(
               'team_member_id', d.owner_id,
               'name', coalesce(tm.name, 'Nobody'),
               'completed', count(*),
               'on_time', count(*) filter (where (d.due is null or d.ended::date <= d.due::date)
                                         and (d.prio_by is null or coalesce(d.met_at, d.ended) <= d.prio_by)),
               'median_cycle_minutes',
                 round(percentile_cont(0.5) within group (
                   order by extract(epoch from (d.ended - d.created_at)) / 60))::int) as x
        from done d
        left join public.team_members tm on tm.id = d.owner_id
       group by d.owner_id, tm.name
    ) q
  ),

  /* 6. WHO IS CARRYING THE OPEN WORK (2026-09-28). One row a Task Owner:
        the open tasks they hold, and how many of those are late by the rule
        in 2 above. The team's whole queue is `ops.all`, so it is answered
        only where that part is granted. */
  open_by_person as (
    select jsonb_agg(x order by (x ->> 'open')::int desc, x ->> 'name') as j from (
      select jsonb_build_object(
               'team_member_id', o.owner_id,
               'name', coalesce(tm.name, 'No task owner'),
               'open', count(*),
               'late', count(*) filter (where o.is_late)) as x
        from (select l.id,
                     (select a.team_member_id
                        from public.ops_task_assignees a
                       where a.task_id = l.id and a.responsibility = 'owner' and a.ended_at is null
                       limit 1) as owner_id,
                     (l.due_late or l.prio_late) as is_late
                from late_now l) o
        left join public.team_members tm on tm.id = o.owner_id
       where public.ops_granted('ops.all', 'view')
       group by o.owner_id, tm.name
    ) q
  )

  select jsonb_build_object(
           'from', p_from, 'to', p_to,
           'running',    coalesce((select j from running), '[]'::jsonb),
           'late',       coalesce((select j from late), '[]'::jsonb),
           'stage_time', coalesce((select j from stage_time), '[]'::jsonb),
           'on_time',    coalesce((select j from on_time), '{}'::jsonb),
           'by_person',  coalesce((select j from by_person), '[]'::jsonb),
           'open_by_person', case when public.ops_granted('ops.all', 'view')
                                  then coalesce((select j from open_by_person), '[]'::jsonb) end)
    into out;

  return out;
end $$;

grant execute on function public.ops_report(timestamptz, timestamptz) to authenticated;

-- END OF ON TIME COUNTS LATE OPEN WORK --------------------------------------

-- ===========================================================================
-- POSTED ON TIME — the Dashboard reads whether content went live by its post
-- date beside on-time delivery. 2026-10-19. Safe to run twice. Rollback at
-- the foot. Mirrored byte for byte in supabase/schema.sql under the same
-- banner; tests/ops.js compares the two.
--
-- WHAT CHANGED (the user, 2026-10-19: "Build posted on time on the
-- dashboard. Keep ontime this way")
--   ops_report also answers `posted`: of the content tasks whose post date
--   (Malaysia's day) fell in the period and has passed, or which went live,
--   how many went live by their post date, as the performance review's
--   On-time posting reads a colleague's (`perf_ops_rate`). A task posts
--   where its workflow has a live stage; a cancelled one is left out; the
--   reader's client scope holds as for every other figure. A post due today
--   and not yet live waits for tomorrow. On-time delivery is unchanged.
--
-- ROLLBACK
--   Run ops_report from ON TIME COUNTS LATE OPEN WORK again (pages read a
--   missing posted as none).
-- ===========================================================================

create or replace function public.ops_report(
  p_from timestamptz default (now() - interval '90 days'),
  p_to   timestamptz default now())
returns jsonb
language plpgsql security definer stable set search_path = public as $$
declare
  out jsonb;
begin
  if not public.ops_granted('ops.reports', 'view') then
    return jsonb_build_object('error', 'denied');
  end if;

  with
  /* Where client review begins in each workflow. The final due date is the
     day the work is owed AT that stage, so everything below that position is
     "has not reached the client yet". Read from `stage_group` and never from
     a stage key: the two seeded workflows name that stage differently. */
  floors as (
    select workflow_id, min(position) as at
      from public.ops_workflow_stages
     where stage_group = 'client_review'
     group by workflow_id
  ),
  /* Where a priority's deadline is met (2026-10-11): client review, else the
     workflow's first review (an everyday task's Review). */
  pfloors as (
    select workflow_id,
           coalesce(min(position) filter (where stage_group = 'client_review'),
                    min(position) filter (where stage_group = 'internal_review')) as at
      from public.ops_workflow_stages
     group by workflow_id
  ),
  live as (
    select t.*, s.label as stage_label, s.position as stage_position,
           s.stage_group, f.at as review_at,
           public.ops_priority_by(coalesce(t.priority_at, t.created_at), t.priority_level) as prio_by, pf.at as prio_at
      from public.ops_tasks t
      join public.ops_workflow_stages s
        on s.workflow_id = t.workflow_id and s.key = t.stage_key
      left join floors f on f.workflow_id = t.workflow_id
      left join pfloors pf on pf.workflow_id = t.workflow_id
     where t.completed_at is null and t.cancelled_at is null
       and t.archived_at is null
       /* Client scope: a colleague on Own clients only reads the work of
          the clients they hold, and their own tasks always (2026-10-18). */
       and public.ops_task_in_scope(t.id)
  ),

  /* 1. WHAT IS RUNNING, by the words on the screen. Grouped by the stage's
        own label rather than by its group, because "what is on shooting" is
        the question and Shooting is a label, not a group. */
  running as (
    select jsonb_agg(x order by x ->> 'position', x ->> 'label') as j from (
      select jsonb_build_object(
               'stage_key', stage_key, 'label', stage_label,
               'position', stage_position, 'stage_group', stage_group,
               'count', count(*)) as x
        from live
       group by stage_key, stage_label, stage_position, stage_group
    ) q
  ),

  /* 2. WHAT IS LATE. Past the commitment and still short of client review,
        or past a priority's deadline and short of its review (On hold and
        Blocked still count): whichever comes first (the user, 2026-10-11).
        The same rule the queue row draws, stated once more here because a
        report a page computes for itself is a second definition. */
  late_now as (
    select l.*,
           (l.current_final_due_at is not null and (l.current_final_due_at at time zone 'Asia/Kuala_Lumpur')::date < (now() at time zone 'Asia/Kuala_Lumpur')::date
            and (l.review_at is null or l.stage_position < l.review_at)) as due_late,
           (l.prio_by is not null and l.prio_by < now()
            and (l.prio_at is null or l.stage_position < l.prio_at or l.stage_group in ('kiv', 'blocked'))) as prio_late
      from live l
  ),
  late as (
    select jsonb_agg(x order by x ->> 'due_at') as j from (
      select jsonb_build_object(
               'task_id', l.id, 'task_no', l.task_no, 'title', l.title,
               'client', c.name, 'stage', l.stage_label,
               'due_at', case when l.prio_late and (not l.due_late or l.prio_by < l.current_final_due_at)
                              then l.prio_by else l.current_final_due_at end,
               'days_over', greatest(case when l.due_late then (now() at time zone 'Asia/Kuala_Lumpur')::date - (l.current_final_due_at at time zone 'Asia/Kuala_Lumpur')::date end,
                                     case when l.prio_late then floor(extract(epoch from (now() - l.prio_by)) / 86400)::int end),
               'over_minutes', case when l.prio_late then floor(extract(epoch from (now() - l.prio_by)) / 60)::int end,
               'owner', (select tm.name
                           from public.ops_task_assignees a
                           join public.team_members tm on tm.id = a.team_member_id
                          where a.task_id = l.id and a.responsibility = 'owner'
                            and a.ended_at is null
                          limit 1)) as x
        from late_now l
        left join public.clients c on c.id = l.client_id
       where l.due_late or l.prio_late
    ) q
  ),

  /* 3. HOW LONG EACH STAGE TAKES. A task enters a stage at the event that
        names it and leaves at the next event, or at its own ending, or now.
        Only spans that were ENTERED inside the period are counted, so the
        window means what it says and a task that sat in Editing since March
        does not land in every report for ever. */
  spans as (
    select e.task_id,
           e.to_value ->> 'stage_key' as stage_key,
           e.created_at as from_at,
           coalesce(
             lead(e.created_at) over (partition by e.task_id order by e.created_at),
             t.completed_at, t.cancelled_at, now()) as to_at
      from public.ops_task_events e
      join public.ops_tasks t on t.id = e.task_id
     where e.event_type in ('task_created', 'stage_changed')
       and e.to_value ->> 'stage_key' is not null
       and public.ops_task_in_scope(t.id)
       /* Only a span entered in the period is counted, and its end is the
          task's next event, never an earlier one: what came before the
          period is not read (2026-10-18). */
       and e.created_at >= p_from
  ),
  /* One row per span and no grouping: an earlier draft grouped by the span's
     own timestamps, which silently collapsed two tasks that entered the same
     stage in the same instant into one measurement. The label is looked up
     once per stage below instead of aggregated here. */
  span_mins as (
    select s.stage_key,
           extract(epoch from (s.to_at - s.from_at)) / 60 as mins
      from spans s
     where s.from_at >= p_from and s.from_at < p_to
       and s.to_at > s.from_at
  ),
  stage_time as (
    select jsonb_agg(x order by x ->> 'label') as j from (
      select jsonb_build_object(
               'stage_key', stage_key,
               'label', coalesce((select w.label from public.ops_workflow_stages w
                                   where w.key = sm.stage_key limit 1), stage_key),
               'n', count(*),
               'median_minutes', round(percentile_cont(0.5) within group (order by mins))::int,
               'p90_minutes', round(percentile_cont(0.9) within group (order by mins))::int) as x
        from span_mins sm
       group by stage_key
    ) q
  ),

  /* 4. WAS IT THERE ON TIME. Of the tasks that reached client review inside
        the period, how many got there on or before the date they were owed;
        the work still late is counted beside them (`late_open`).
        Replanning is counted beside it and never folded into it: an extension
        that moves the date would otherwise erase the miss it was granted for,
        and a rate that cannot be missed is not a measurement. */
  reached as (
    select distinct on (e.task_id)
           e.task_id, e.created_at as at, t.current_final_due_at as due,
           public.ops_priority_by(coalesce(t.priority_at, t.created_at), t.priority_level) as prio_by,
           (t.original_final_due_at is distinct from t.current_final_due_at) as replanned
      from public.ops_task_events e
      join public.ops_tasks t on t.id = e.task_id
      join public.ops_workflow_stages w
        on w.workflow_id = t.workflow_id and w.key = e.to_value ->> 'stage_key'
     where e.event_type = 'stage_changed'
       and w.stage_group = 'client_review'
       and public.ops_task_in_scope(t.id)
       and e.created_at >= p_from and e.created_at < p_to
     order by e.task_id, e.created_at
  ),
  /* Work still short of its review and past its deadline is a miss too
     (2026-10-19, the user: "there are late tasks yet showing 100% on time
     delivery"): counted in the period its first missed deadline fell in,
     and in any period that runs to now (its end within ten minutes of now:
     the page names the moment it asks), where it is still late. A task
     counted as reached in the period is not counted again. */
  late_open as (
    select l.id
      from late_now l
     where (l.due_late or l.prio_late)
       and not exists (select 1 from reached r where r.task_id = l.id)
       and (case when l.prio_late and (not l.due_late or l.prio_by < l.current_final_due_at)
                 then l.prio_by else l.current_final_due_at end) < p_to
       and ((case when l.prio_late and (not l.due_late or l.prio_by < l.current_final_due_at)
                  then l.prio_by else l.current_final_due_at end) >= p_from
            or p_to >= now() - interval '10 minutes')
  ),
  on_time as (
    select jsonb_build_object(
             'reached', count(*),
             'met', count(*) filter (where (due is null or at::date <= due::date) and (prio_by is null or at <= prio_by)),
             'missed', count(*) filter (where not ((due is null or at::date <= due::date) and (prio_by is null or at <= prio_by))),
             'late_open', (select count(*) from late_open),
             'replanned', count(*) filter (where replanned)) as j
      from reached
  ),
  /* 4b. POSTED ON TIME (2026-10-19). Of the content whose post date fell in
         the period and has passed (Malaysia's day), or which went live, how
         much went live by its post date. Client approval counts here, as it
         does for the client; on-time delivery above is the team's own. */
  posted as (
    select jsonb_build_object(
             'due', count(*),
             'met', count(*) filter (where t.live_at is not null
                                       and (t.live_at at time zone 'Asia/Kuala_Lumpur')::date
                                           <= (t.publish_at at time zone 'Asia/Kuala_Lumpur')::date)) as j
      from public.ops_tasks t
     where t.publish_at >= p_from and t.publish_at < p_to
       and t.cancelled_at is null and t.archived_at is null
       and (t.live_at is not null
            or (t.publish_at at time zone 'Asia/Kuala_Lumpur')::date < (now() at time zone 'Asia/Kuala_Lumpur')::date)
       and exists (select 1 from public.ops_workflow_stages s
                    where s.workflow_id = t.workflow_id and s.stage_group = 'live')
       and public.ops_task_in_scope(t.id)
  ),

  /* 5. BY PERSON. The foundation of a KPI and not a KPI: what somebody
        finished in the window, how much of it was on time, and how long their
        work took end to end. No ranking and no score — a number a person can
        check is worth more than a league table nobody trusts. */
  done as (
    select t.id, t.created_at, coalesce(t.completed_at, t.delivered_at) as ended,
           t.current_final_due_at as due,
           public.ops_priority_by(coalesce(t.priority_at, t.created_at), t.priority_level) as prio_by,
           /* When a priority's deadline was met: the first move into its
              review or beyond (never On hold, Blocked or Cancelled). */
           (select min(e.created_at)
              from public.ops_task_events e
              join public.ops_workflow_stages w
                on w.workflow_id = t.workflow_id and w.key = e.to_value ->> 'stage_key'
              join pfloors pf on pf.workflow_id = t.workflow_id
             where e.task_id = t.id and e.event_type = 'stage_changed'
               and w.position >= pf.at and w.stage_group not in ('kiv', 'blocked', 'cancelled')) as met_at,
           (select a.team_member_id
              from public.ops_task_assignees a
             where a.task_id = t.id and a.responsibility = 'owner'
             order by a.ended_at nulls first, a.assigned_at desc
             limit 1) as owner_id
      from public.ops_tasks t
     where t.completed_at is not null
       and t.completed_at >= p_from and t.completed_at < p_to
       and public.ops_task_in_scope(t.id)
  ),
  by_person as (
    select jsonb_agg(x order by x ->> 'name') as j from (
      select jsonb_build_object(
               'team_member_id', d.owner_id,
               'name', coalesce(tm.name, 'Nobody'),
               'completed', count(*),
               'on_time', count(*) filter (where (d.due is null or d.ended::date <= d.due::date)
                                         and (d.prio_by is null or coalesce(d.met_at, d.ended) <= d.prio_by)),
               'median_cycle_minutes',
                 round(percentile_cont(0.5) within group (
                   order by extract(epoch from (d.ended - d.created_at)) / 60))::int) as x
        from done d
        left join public.team_members tm on tm.id = d.owner_id
       group by d.owner_id, tm.name
    ) q
  ),

  /* 6. WHO IS CARRYING THE OPEN WORK (2026-09-28). One row a Task Owner:
        the open tasks they hold, and how many of those are late by the rule
        in 2 above. The team's whole queue is `ops.all`, so it is answered
        only where that part is granted. */
  open_by_person as (
    select jsonb_agg(x order by (x ->> 'open')::int desc, x ->> 'name') as j from (
      select jsonb_build_object(
               'team_member_id', o.owner_id,
               'name', coalesce(tm.name, 'No task owner'),
               'open', count(*),
               'late', count(*) filter (where o.is_late)) as x
        from (select l.id,
                     (select a.team_member_id
                        from public.ops_task_assignees a
                       where a.task_id = l.id and a.responsibility = 'owner' and a.ended_at is null
                       limit 1) as owner_id,
                     (l.due_late or l.prio_late) as is_late
                from late_now l) o
        left join public.team_members tm on tm.id = o.owner_id
       where public.ops_granted('ops.all', 'view')
       group by o.owner_id, tm.name
    ) q
  )

  select jsonb_build_object(
           'from', p_from, 'to', p_to,
           'running',    coalesce((select j from running), '[]'::jsonb),
           'late',       coalesce((select j from late), '[]'::jsonb),
           'stage_time', coalesce((select j from stage_time), '[]'::jsonb),
           'on_time',    coalesce((select j from on_time), '{}'::jsonb),
           'posted',     coalesce((select j from posted), '{}'::jsonb),
           'by_person',  coalesce((select j from by_person), '[]'::jsonb),
           'open_by_person', case when public.ops_granted('ops.all', 'view')
                                  then coalesce((select j from open_by_person), '[]'::jsonb) end)
    into out;

  return out;
end $$;

grant execute on function public.ops_report(timestamptz, timestamptz) to authenticated;

-- END OF POSTED ON TIME -----------------------------------------------------

-- ===========================================================================
-- BUKKU AS BUKKU HOLDS IT — the billing person's salutation goes to Bukku,
-- and a contact may be linked without anything sent. 2026-10-19. Safe to
-- run twice. Rollback at the foot. Mirrored byte for byte in
-- supabase/schema.sql under the same banner; tests/bukkusql.js compares the
-- two.
--
-- WHAT CHANGED (the user, 2026-10-19: "the bukku address follow Address
-- line 1, address line 2, postal code, city, state, country … also can
-- allow link or sync without changing info"; "your salutation didnt follow
-- over")
--   1. bukku_prepare answers the client's billing contact's salutation
--      (`salutation`) beside the name; bukku-sync puts it before the name.
--   2. bukku_link_only(p_kind, p_id, p_contact, p_code) files the link as
--      bukku_linked does, the record's details as they stand marked sent,
--      and files "Linked to Bukku, nothing sent" (Link only: Bukku's
--      contact is not changed).
--   The address is read into Bukku's parts by bukku-sync itself.
--
-- ORDER
--   This file, then bukku-sync, then the pages (the sheet's Link only asks
--   the function's `link`).
--
-- ROLLBACK
--   Run bukku_prepare from BUKKU CONTACTS again; bukku_link_only, unused
--   by then, stays harmless.
-- ===========================================================================

create or replace function public.bukku_prepare(p_kind text, p_id uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  c public.clients; s public.suppliers; ct public.client_contacts;
  l public.bukku_links; b public.bukku_settings;
  v_missing text[] := '{}'; v_company boolean; v_id text; v_field bigint; v_pay boolean;
  v_person text; v_out jsonb;
begin
  if not public.bukku_may(p_kind, p_id, 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into b from public.bukku_settings where id = 1;
  if p_kind = 'client' then
    select * into c from public.clients x where x.id = p_id;
    if c.id is null then return jsonb_build_object('error', 'not-found'); end if;
    select * into ct from public.client_contacts x
     where x.id = c.bill_contact_id and x.archived_at is null;
    if ct.id is null then
      select * into ct from public.client_contacts x where x.client_id = c.id and x.is_primary and x.archived_at is null;
    end if;
    if coalesce(btrim(c.legal_name), '') = '' then v_missing := v_missing || 'Registered name'::text; end if;
    if coalesce(btrim(c.client_code), '') = '' then v_missing := v_missing || 'Client ID'::text; end if;
    if array_length(v_missing, 1) > 0 then return jsonb_build_object('error', 'incomplete', 'missing', to_jsonb(v_missing)); end if;
    select * into l from public.bukku_links x where x.kind = 'client' and x.record_id = c.id;
    v_person := btrim(coalesce(ct.name, ''));
    return jsonb_build_object('ok', true, 'kind', 'client', 'id', c.id,
      'legal_name', public.bukku_name_case(c.legal_name, true), 'other_name', c.name,
      'entity_type', case when c.market = 'SG' then 'FOREIGN_COMPANY' else 'MALAYSIAN_COMPANY' end,
      'reg_no_type', case when nullif(regexp_replace(coalesce(c.company_no, ''), '[^0-9A-Za-z]', '', 'g'), '') is null then null else 'BRN' end,
      'reg_no', nullif(regexp_replace(coalesce(c.company_no, ''), '[^0-9A-Za-z]', '', 'g'), ''),
      'old_reg_no', nullif(btrim(coalesce(c.company_no_old, '')), ''),
      'tax_id_no', nullif(btrim(coalesce(c.tin, '')), ''), 'sst_reg_no', nullif(btrim(coalesce(c.sst_no, '')), ''),
      'email', nullif(btrim(coalesce(c.finance_email, ct.email, '')), ''),
      'phone_no', public.wa_number(coalesce(ct.phone, ct.whatsapp), coalesce(c.market, 'MY')),
      'address', nullif(btrim(coalesce(c.billing_address, '')), ''),
      'country', case when c.market = 'SG' then 'SG' else 'MY' end,
      'currency', case when c.market = 'SG' then 'SGD' else 'MYR' end,
      'person', nullif(public.bukku_name_case(v_person, false), ''),
      'salutation', nullif(btrim(coalesce(ct.salutation, '')), ''),
      'our_id', c.client_code, 'field_id', b.field_client, 'type', 'customer',
      'contact_id', l.contact_id);
  elsif p_kind = 'supplier' then
    select * into s from public.suppliers x where x.id = p_id;
    if s.id is null then return jsonb_build_object('error', 'not-found'); end if;
    if s.status <> 'active' then return jsonb_build_object('error', 'not-active'); end if;
    v_company := coalesce(s.kind, 'company') = 'company';
    v_pay := public.ops_granted('suppliers.pay', 'view');
    select * into l from public.bukku_links x where x.kind = 'supplier' and x.record_id = s.id;
    if l.contact_id is null and s.client_id is not null then
      select * into l from public.bukku_links x where x.kind = 'client' and x.record_id = s.client_id;
    end if;
    return jsonb_build_object('ok', true, 'kind', 'supplier', 'id', s.id,
      'legal_name', public.bukku_name_case(s.name, v_company),
      'entity_type', case when s.currency = 'SGD' then (case when v_company then 'FOREIGN_COMPANY' else 'FOREIGN_INDIVIDUAL' end)
                          else (case when v_company then 'MALAYSIAN_COMPANY' else 'MALAYSIAN_INDIVIDUAL' end) end,
      'reg_no_type', case when v_company and s.brn is not null then 'BRN' when not v_company and v_pay and s.nric is not null then 'NRIC' end,
      'reg_no', case when v_company then s.brn when v_pay then regexp_replace(coalesce(s.nric, ''), '[^0-9]', '', 'g') end,
      'tax_id_no', s.tin, 'sst_reg_no', s.sst_no,
      'email', coalesce(s.finance_email, s.email),
      'phone_no', public.wa_number(coalesce(s.mobile, s.phone), case when s.currency = 'SGD' then 'SG' else 'MY' end),
      'address', s.address, 'country', case when s.currency = 'SGD' then 'SG' else 'MY' end,
      'currency', s.currency,
      'person', public.bukku_name_case(coalesce(s.contact_name, case when not v_company then s.name end), false),
      'payment_term', s.payment_term,
      'our_id', s.code, 'field_id', b.field_supplier, 'type', 'supplier',
      'client_id', s.client_id, 'contact_id', l.contact_id);
  end if;
  return jsonb_build_object('error', 'bad-kind');
end $$;
revoke all on function public.bukku_prepare(text, uuid) from public, anon;
grant execute on function public.bukku_prepare(text, uuid) to authenticated;

create or replace function public.bukku_link_only(p_kind text, p_id uuid, p_contact bigint, p_code text)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare me public.team_members := public.ops_me(); v_name text; v_code text; v_client uuid;
begin
  if not public.bukku_may(p_kind, p_id, 'work') then return jsonb_build_object('error', 'denied'); end if;
  if p_contact is null or p_contact <= 0 then return jsonb_build_object('error', 'bad-contact'); end if;
  if p_kind = 'client' then
    select x.name, x.client_code into v_name, v_code from public.clients x where x.id = p_id;
  else
    select coalesce(x.name, x.code), x.code, x.client_id into v_name, v_code, v_client from public.suppliers x where x.id = p_id;
  end if;
  if v_name is null then return jsonb_build_object('error', 'not-found'); end if;
  insert into public.bukku_links (kind, record_id, contact_id, code, sent_at, sent_by, sent_hash)
  values (p_kind, p_id, p_contact, left(p_code, 40), now(), me.id, public.bukku_print(p_kind, p_id))
  on conflict (kind, record_id) do update set contact_id = excluded.contact_id, code = excluded.code,
    sent_at = now(), sent_by = excluded.sent_by, sent_hash = excluded.sent_hash;
  /* One contact for a supplier that is also a client. */
  if v_client is not null then
    insert into public.bukku_links (kind, record_id, contact_id, code, sent_at, sent_by, sent_hash)
    values ('client', v_client, p_contact, left(p_code, 40), now(), me.id, null)
    on conflict (kind, record_id) do update set contact_id = excluded.contact_id, code = excluded.code;
  end if;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, case when p_kind = 'client' then 'client.edited' else 'supplier.edited' end, v_name,
          coalesce(v_code || ' · ', '') || 'Linked to Bukku, nothing sent · ' || coalesce(p_code, p_contact::text));
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.bukku_link_only(text, uuid, bigint, text) from public, anon;
grant execute on function public.bukku_link_only(text, uuid, bigint, text) to authenticated;

-- END OF BUKKU AS BUKKU HOLDS IT ---------------------------------------------

-- ===========================================================================
-- CONTENT REVIEW BY HAND — a new client starts outside Content Review.
-- 2026-10-19. Safe to run twice. Rollback at the foot. Mirrored byte for
-- byte in supabase/schema.sql under the same banner; tests/sql.js compares
-- the two.
--
-- WHAT CHANGED (the user, 2026-10-19: "not all new leads or clients auto
-- open the content review make it manually")
--   `clients.review_hidden` defaults to true, so a lead or client added from
--   now (by hand, by the quotation website, by any insert) is out of
--   Content Review until a colleague enables it (Enable client in Content
--   Review, or Enable Content Review on the record). Every client standing
--   today keeps its place.
--
-- ROLLBACK
--   alter table public.clients alter column review_hidden set default false;
-- ===========================================================================

alter table public.clients alter column review_hidden set default true;

-- END OF CONTENT REVIEW BY HAND ---------------------------------------------

-- ===========================================================================
-- CLIENT FORMS HOLD — five findings of the 2026-10-19 audit of the Clients
-- section's forms. 2026-10-19. Safe to run twice. Rollback at the foot.
-- Mirrored byte for byte in supabase/schema.sql under the same banner;
-- tests/sql.js compares the two.
--
-- WHAT CHANGED
--   3. A checklist never stores the registered company name or the
--      quotation reference it prefills (`details.entity`,
--      `details.quotation`): `client_checklist` works them out for each
--      reader on every read, as it did before the row existed, and
--      `client_checklist_set` seeds a new row without them. Rows already
--      holding them as prefilled lose them; a value the team typed over is
--      kept.
--   13. Sign-off (`client_checklist_step` review) is refused `own` to a
--      colleague who ticked or answered any item, not only to who prepared
--      it: a tick keeps its colleague's id (`by_id`) beside the name, an
--      answer or a note who set it (`set_by`); a tick from before reads by
--      its name (`checklist_filled_by`). `client_checklist` answers
--      `filled_by_me`, so the page draws no Sign off it would refuse.
--   10. The details form files its Activity record row as `Details form`,
--      the typed name in the detail, never as the actor.
--   15. `quotation_make`: a second press with the same key arriving while
--      the first is being written answers `again` with the first's row,
--      never a unique violation.
--   20. `meta_links_save`: two first saves at once write through
--      `insert ... on conflict ... do update`, never a unique violation.
--
-- ROLLBACK
--   Run again the earlier definitions: CLIENT CHECKLISTS'
--   client_checklist_step, CHECKLIST WRITER's client_checklist_set, DATA
--   HELD TO ITS LEVEL's client_checklist and client_details_submit,
--   QUOTATION IN SINGAPORE DOLLARS' quotation_make
--   and META LINKS' meta_links_save. The helper checklist_filled_by may
--   stay; the keys `by_id` and `set_by` are read by nothing else. Answers
--   cleared of a prefilled value are worked out again on every read.
-- ===========================================================================

-- Whether a colleague ticked or answered any item of a checklist (audit 13):
-- they never sign it off. A tick from before the colleague's id was kept is
-- read by its name.
create or replace function public.checklist_filled_by(p_answers jsonb, p_id uuid, p_name text)
returns boolean
language sql immutable set search_path = public as $$
  select coalesce(bool_or(e.value->>'by_id' = p_id::text or e.value->>'set_by' = p_id::text
                          or (e.value->>'by_id' is null and e.value ? 'state' and e.value->>'by' = p_name)), false)
    from jsonb_each(coalesce(p_answers, '{}'::jsonb)) e
$$;
revoke all on function public.checklist_filled_by(jsonb, uuid, text) from public, anon, authenticated;

create or replace function public.client_checklist(p_client uuid, p_kind text)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.client_checklists;
  t jsonb;
  pre jsonb;
  hints jsonb := '{}'::jsonb;
  q record;
  m timestamptz;
begin
  if me.id is null or not public.allowed('clients', 'view') then return jsonb_build_object('error', 'denied'); end if;
  if not public.client_scope_ok('client', p_client, 'view') then return jsonb_build_object('error', 'client-scope'); end if;
  if p_kind not in ('onboarding', 'pre_ads') then return jsonb_build_object('error', 'bad-kind'); end if;
  select * into r from public.client_checklists where client_id = p_client and kind = p_kind;
  t := coalesce(r.template, public.checklist_template(p_kind));
  pre := public.checklist_prefill(p_client, p_kind);
  -- Once started, only what each reader's own access gives (the registered
  -- name, the quotation) is worked out on the read; it is never stored.
  if r.id is not null then
    pre := jsonb_strip_nulls(jsonb_build_object('details.entity', pre->'details.entity',
                                                'details.quotation', pre->'details.quotation'));
  end if;
  if p_kind = 'onboarding' and public.allowed('clients.services', 'view') then
    select x.ref, x.issued_at into q from public.quotations x
     where x.client_id = p_client and x.removed_at is null order by x.issued_at desc limit 1;
    if q.ref is not null then
      hints := hints || jsonb_build_object('pre.quotation', 'Quotation ' || q.ref || ' issued ' ||
        to_char(q.issued_at at time zone 'Asia/Kuala_Lumpur', 'FMDD Mon YYYY'));
    end if;
  end if;
  if p_kind = 'onboarding' then
    select min(e.meeting_at) into m from public.ops_engagements e where e.client_id = p_client and e.meeting_at is not null;
    if m is not null then
      hints := hints || jsonb_build_object('pre.first_meeting', 'Meeting set for ' ||
        to_char(m at time zone 'Asia/Kuala_Lumpur', 'FMDD Mon YYYY, FMHH12:MIam'));
    end if;
  end if;
  return jsonb_build_object(
    'kind', p_kind, 'title', t->>'title', 'version', t->>'version', 'lead', t->>'lead', 'sections', t->'sections',
    'started', r.id is not null, 'answers', coalesce(r.answers, '{}'::jsonb), 'prefill', coalesce(pre, '{}'::jsonb),
    'sections_na', to_jsonb(coalesce(r.sections_na, '{}'::text[])), 'status', coalesce(r.status, 'open'),
    'prepared', case when r.prepared_at is not null then jsonb_build_object('id', r.prepared_by, 'name', r.prepared_name, 'at', r.prepared_at) end,
    'reviewed', case when r.reviewed_at is not null then jsonb_build_object('id', r.reviewed_by, 'name', r.reviewed_name, 'at', r.reviewed_at) end,
    'history', jsonb_array_length(coalesce(r.history, '[]'::jsonb)),
    'hints', hints, 'me', me.id, 'filled_by_me', public.checklist_filled_by(r.answers, me.id, me.name),
    'can_work', public.allowed('clients', 'work') and public.client_scope_ok('client', p_client, 'work'),
    'can_manage', public.allowed('clients', 'manage') and public.client_scope_ok('client', p_client, 'manage'),
    'updated_at', r.updated_at);
end $$;
revoke all on function public.client_checklist(uuid, text) from public, anon;
grant execute on function public.client_checklist(uuid, text) to authenticated;

create or replace function public.client_checklist_set(p_client uuid, p_kind text, p_item text, p_state text,
                                                       p_note text, p_value jsonb)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.client_checklists;
  c public.clients;
  t jsonb;
  sec jsonb;
  it jsonb;
  a jsonb;
  was jsonb;
  v_sec text := split_part(coalesce(p_item, ''), '.', 1);
  v_key text := split_part(coalesce(p_item, ''), '.', 2);
  what text;
begin
  if me.id is null or not public.allowed('clients', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if not public.client_scope_ok('client', p_client, 'work') then return jsonb_build_object('error', 'client-scope'); end if;
  if p_kind not in ('onboarding', 'pre_ads') then return jsonb_build_object('error', 'bad-kind'); end if;
  select * into c from public.clients where id = p_client;
  if c.id is null then return jsonb_build_object('error', 'not-found'); end if;
  insert into public.client_checklists (client_id, kind, version, template, answers)
  select p_client, p_kind, t0->>'version', t0,
         (select coalesce(jsonb_object_agg(k, jsonb_build_object('value', v)), '{}'::jsonb)
            from jsonb_each(public.checklist_prefill(p_client, p_kind) - 'details.entity' - 'details.quotation') e(k, v))
    from (select public.checklist_template(p_kind) t0) z
  on conflict (client_id, kind) do nothing;
  select * into r from public.client_checklists where client_id = p_client and kind = p_kind for update;
  if r.status <> 'open' then return jsonb_build_object('error', 'locked', 'status', r.status); end if;
  t := r.template;
  select s into sec from jsonb_array_elements(t->'sections') s where s->>'key' = v_sec;
  if sec is null then return jsonb_build_object('error', 'bad-item'); end if;

  if v_key = '' then
    if p_state = 'na' then
      update public.client_checklists set sections_na = array(select distinct unnest(sections_na || v_sec)),
             updated_at = now() where id = r.id;
      what := (sec->>'title') || ': not applicable';
    elsif coalesce(p_state, '') = '' then
      update public.client_checklists set sections_na = array_remove(sections_na, v_sec), updated_at = now() where id = r.id;
      what := (sec->>'title') || ': applicable';
    else return jsonb_build_object('error', 'bad-state'); end if;
  else
    select i into it from jsonb_array_elements(sec->'items') i where i->>'key' = v_key;
    if it is null then return jsonb_build_object('error', 'bad-item'); end if;
    was := coalesce(r.answers->p_item, '{}'::jsonb);
    a := was;
    if p_state is not null then
      if it->>'kind' <> 'tick' or p_state not in ('', 'done', 'na') then return jsonb_build_object('error', 'bad-state'); end if;
      a := (a - 'state' - 'by' - 'by_id' - 'at') || case when p_state = '' then '{}'::jsonb
             else jsonb_build_object('state', p_state, 'by', me.name, 'by_id', me.id, 'at', now()) end;
      what := (it->>'label') || ': ' || case p_state when 'done' then 'done' when 'na' then 'not applicable' else 'not done' end;
    end if;
    if p_note is not null then
      if char_length(p_note) > 1000 then return jsonb_build_object('error', 'too-long'); end if;
      a := (a - 'note') || case when btrim(p_note) = '' then '{}'::jsonb else jsonb_build_object('note', btrim(p_note)) end;
      a := a || jsonb_build_object('set_by', me.id);
      what := coalesce(what, (it->>'label') || ': note changed');
    end if;
    if p_value is not null then
      if it->>'kind' = 'tick' then return jsonb_build_object('error', 'bad-value'); end if;
      if it->>'kind' = 'text' and (jsonb_typeof(p_value) <> 'string' or char_length(p_value #>> '{}') > 4000) then
        return jsonb_build_object('error', 'bad-value');
      end if;
      if it->>'kind' = 'choice' and (jsonb_typeof(p_value) <> 'string' or
         (p_value #>> '{}' <> '' and not (it->'choices') ? (p_value #>> '{}'))) then
        return jsonb_build_object('error', 'bad-value');
      end if;
      if it->>'kind' = 'multi' and (jsonb_typeof(p_value) <> 'array' or
         exists (select 1 from jsonb_array_elements(p_value) v where jsonb_typeof(v) <> 'string' or not (it->'choices') ? (v #>> '{}'))) then
        return jsonb_build_object('error', 'bad-value');
      end if;
      /* A table (r1.2's Meta Campaign Setup): twelve rows at most, each
         row only the item's own columns, each cell words of 400 at most. */
      if it->>'kind' = 'table' and (jsonb_typeof(p_value) <> 'array' or jsonb_array_length(p_value) > 12 or
         exists (select 1 from jsonb_array_elements(p_value) rw where jsonb_typeof(rw) <> 'object' or
           exists (select 1 from jsonb_each(rw) e where jsonb_typeof(e.value) <> 'string' or char_length(e.value #>> '{}') > 400 or
             not exists (select 1 from jsonb_array_elements(it->'columns') col where col->>0 = e.key)))) then
        return jsonb_build_object('error', 'bad-value');
      end if;
      a := (a - 'value') || case when p_value in ('""'::jsonb, '[]'::jsonb) then '{}'::jsonb
             else jsonb_build_object('value', p_value) end;
      a := a || jsonb_build_object('set_by', me.id);
      what := coalesce(what, (it->>'label') || ': ' || case when p_value in ('""'::jsonb, '[]'::jsonb) then 'cleared' else 'changed' end);
    end if;
    if a - 'set_by' = was - 'set_by' then return public.client_checklist(p_client, p_kind); end if;
    update public.client_checklists set answers = case when a = '{}'::jsonb then answers - p_item else jsonb_set(answers, array[p_item], a) end,
           updated_at = now() where id = r.id;
  end if;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'client.edited', c.name, (t->>'title') || ' · ' || what);
  return public.client_checklist(p_client, p_kind);
end $$;
revoke all on function public.client_checklist_set(uuid, text, text, text, text, jsonb) from public, anon;
grant execute on function public.client_checklist_set(uuid, text, text, text, text, jsonb) to authenticated;

create or replace function public.client_checklist_step(p_client uuid, p_kind text, p_step text)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.client_checklists;
  c public.clients;
  n int;
  word text;
begin
  if me.id is null or not public.allowed('clients', case when p_step = 'reopen' then 'manage' else 'work' end) then
    return jsonb_build_object('error', 'denied');
  end if;
  if not public.client_scope_ok('client', p_client, case when p_step = 'reopen' then 'manage' else 'work' end) then
    return jsonb_build_object('error', 'client-scope');
  end if;
  select * into c from public.clients where id = p_client;
  select * into r from public.client_checklists where client_id = p_client and kind = p_kind for update;
  if c.id is null or r.id is null then return jsonb_build_object('error', 'not-started'); end if;
  if p_step = 'prepare' then
    if r.status <> 'open' then return jsonb_build_object('error', 'locked', 'status', r.status); end if;
    select count(*) into n
      from jsonb_array_elements(r.template->'sections') s, jsonb_array_elements(s->'items') i
     where i->>'kind' = 'tick' and not ((s->>'key') = any(r.sections_na))
       and coalesce(r.answers->((s->>'key') || '.' || (i->>'key'))->>'state', '') not in ('done', 'na');
    if n > 0 then return jsonb_build_object('error', 'incomplete', 'left', n); end if;
    update public.client_checklists set status = 'prepared', prepared_by = me.id, prepared_name = me.name,
           prepared_at = now(), updated_at = now() where id = r.id;
    word := 'prepared for review';
  elsif p_step = 'return' then
    if r.status <> 'prepared' then return jsonb_build_object('error', 'locked', 'status', r.status); end if;
    update public.client_checklists set status = 'open', prepared_by = null, prepared_name = null, prepared_at = null,
           updated_at = now() where id = r.id;
    word := 'sent back';
  elsif p_step = 'review' then
    if r.status <> 'prepared' then return jsonb_build_object('error', 'locked', 'status', r.status); end if;
    if r.prepared_by = me.id then return jsonb_build_object('error', 'own'); end if;
    if public.checklist_filled_by(r.answers, me.id, me.name) then return jsonb_build_object('error', 'own'); end if;
    update public.client_checklists set status = 'signed', reviewed_by = me.id, reviewed_name = me.name,
           reviewed_at = now(), updated_at = now() where id = r.id;
    update public.ops_engagement_checks k set state = 'ready', owner_id = me.id, updated_by = me.id, updated_at = now()
      from public.ops_engagements e
     where e.id = k.engagement_id and e.client_id = p_client and k.key = p_kind and k.state <> 'na';
    word := 'reviewed and signed off';
  elsif p_step = 'reopen' then
    if r.status <> 'signed' then return jsonb_build_object('error', 'locked', 'status', r.status); end if;
    update public.client_checklists set status = 'open',
           history = history || jsonb_build_array(jsonb_build_object('answers', r.answers, 'sections_na', to_jsonb(r.sections_na),
             'version', r.version, 'prepared', r.prepared_name, 'prepared_at', r.prepared_at,
             'reviewed', r.reviewed_name, 'reviewed_at', r.reviewed_at, 'reopened_by', me.name, 'reopened_at', now())),
           prepared_by = null, prepared_name = null, prepared_at = null,
           reviewed_by = null, reviewed_name = null, reviewed_at = null, updated_at = now() where id = r.id;
    update public.ops_engagement_checks k set state = 'not_started', owner_id = null, updated_by = me.id, updated_at = now()
      from public.ops_engagements e
     where e.id = k.engagement_id and e.client_id = p_client and k.key = p_kind and k.state = 'ready';
    word := 'reopened';
  else
    return jsonb_build_object('error', 'bad-step');
  end if;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'client.edited', c.name, (r.template->>'title') || ' · ' || word);
  return public.client_checklist(p_client, p_kind);
end $$;
revoke all on function public.client_checklist_step(uuid, text, text) from public, anon;
grant execute on function public.client_checklist_step(uuid, text, text) to authenticated;

-- What was stored as prefilled is let go; a value typed over is kept.
update public.client_checklists k
   set answers = case when (k.answers->'details.entity') - 'value' = '{}'::jsonb then k.answers - 'details.entity'
                      else jsonb_set(k.answers, array['details.entity'], (k.answers->'details.entity') - 'value') end
  from public.clients c
 where c.id = k.client_id and k.kind = 'pre_ads'
   and k.answers->'details.entity'->>'value' in (nullif(btrim(c.legal_name), ''), c.name);
update public.client_checklists k
   set answers = case when (k.answers->'details.quotation') - 'value' = '{}'::jsonb then k.answers - 'details.quotation'
                      else jsonb_set(k.answers, array['details.quotation'], (k.answers->'details.quotation') - 'value') end
 where k.kind = 'pre_ads'
   and k.answers->'details.quotation'->>'value' in (select x.ref from public.quotations x where x.client_id = k.client_id);

create or replace function public.client_details_submit(p_key text, p_answers jsonb)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  v_f    public.client_detail_forms;
  v_cl   public.clients;
  a      jsonb := coalesce(p_answers, '{}'::jsonb);
  t      text;
  v_name text := upper(btrim(regexp_replace(coalesce(a->>'legal_name', ''), '\s+', ' ', 'g')));
  v_brn  text := upper(regexp_replace(coalesce(a->>'company_no', ''), '\s+', '', 'g'));
  v_old  text := nullif(upper(regexp_replace(coalesce(a->>'company_no_old', ''), '\s+', '', 'g')), '');
  v_tin  text := nullif(upper(regexp_replace(coalesce(a->>'tin', ''), '\s+', '', 'g')), '');
  v_sst  text := nullif(upper(regexp_replace(coalesce(a->>'sst_no', ''), '\s+', '', 'g')), '');
  v_addr text := btrim(coalesce(a->>'billing_address', ''));
  v_fin  text := nullif(lower(btrim(coalesce(a->>'finance_email', ''))), '');
  v_sal  text := nullif(btrim(coalesce(a->>'contact_salutation', '')), '');
  v_cn   text := btrim(regexp_replace(coalesce(a->>'contact_name', ''), '\s+', ' ', 'g'));
  v_cp   text := btrim(coalesce(a->>'contact_phone', ''));
  v_ce   text := lower(btrim(coalesce(a->>'contact_email', '')));
begin
  if coalesce(p_key, '') !~ '^[a-z0-9]{8}$' then return jsonb_build_object('error', 'not_found'); end if;
  select * into v_f from public.client_detail_forms f where f.access_key = p_key and f.voided_at is null for update;
  if v_f.id is null then return jsonb_build_object('error', 'not_found'); end if;
  if v_f.submitted_at is not null then return jsonb_build_object('error', 'submitted'); end if;
  if v_f.expires_at <= now() then return jsonb_build_object('error', 'expired'); end if;
  if length(v_name) < 2 or length(v_name) > 160 then return jsonb_build_object('error', 'bad-legal_name'); end if;
  if v_brn !~ '^[A-Z0-9-]{6,20}$' then return jsonb_build_object('error', 'bad-company_no'); end if;
  if v_old is not null and v_old !~ '^[A-Z0-9-]{4,20}$' then return jsonb_build_object('error', 'bad-company_no_old'); end if;
  if v_tin is not null and v_tin !~ '^[A-Z0-9-]{6,20}$' then return jsonb_build_object('error', 'bad-tin'); end if;
  if v_sst is not null and v_sst !~ '^[A-Z0-9-]{6,25}$' then return jsonb_build_object('error', 'bad-sst_no'); end if;
  if length(v_addr) < 10 or length(v_addr) > 400 then return jsonb_build_object('error', 'bad-billing_address'); end if;
  if v_fin is not null and (v_fin !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' or length(v_fin) > 160) then
    return jsonb_build_object('error', 'bad-finance_email');
  end if;
  if v_sal is not null and v_sal not in ('Mr', 'Ms', 'Mrs', 'Mdm', 'Dr', 'Prof', 'Dato''', 'Datin', 'Datuk',
      'Dato'' Sri', 'Datin Sri', 'Tan Sri', 'Puan Sri', 'Tun', 'Tuan', 'Puan', 'Encik', 'Cik') then
    return jsonb_build_object('error', 'bad-contact_salutation');
  end if;
  if length(v_cn) < 2 or length(v_cn) > 80 then return jsonb_build_object('error', 'bad-contact_name'); end if;
  t := regexp_replace(v_cp, '[^0-9]', '', 'g');
  if length(t) < 8 or length(t) > 15 or length(v_cp) > 30 then return jsonb_build_object('error', 'bad-contact_phone'); end if;
  if v_ce !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' or length(v_ce) > 160 then return jsonb_build_object('error', 'bad-contact_email'); end if;

  update public.client_detail_forms f
     set submitted_at = now(),
         answers = jsonb_strip_nulls(jsonb_build_object(
           'legal_name', v_name, 'company_no', v_brn, 'company_no_old', v_old, 'tin', v_tin, 'sst_no', v_sst,
           'billing_address', v_addr, 'finance_email', v_fin, 'contact_salutation', v_sal,
           'contact_name', v_cn, 'contact_phone', v_cp, 'contact_email', v_ce))
   where f.id = v_f.id;
  select * into v_cl from public.clients c where c.id = v_f.client_id;
  insert into public.activity_log (actor, action, subject, detail)
  values ('Details form', 'client.edited', v_cl.name,
          'Billing details received on the details form from ' || coalesce(v_sal || ' ', '') || v_cn);
  insert into public.ops_notifications (team_member_id, kind, title, body, client_id, dedupe_key)
  select m.id, 'client.details', 'Billing details received · ' || v_cl.name,
         'From ' || coalesce(v_sal || ' ', '') || v_cn || '. Review them on the client''s Billing.',
         v_cl.id, 'client.details:' || v_f.id || ':' || m.id
    from public.team_members m
   where m.active and not coalesce(m.system, false)
     and (m.is_admin or m.role = 'admin'
          or (public.level_rank(coalesce(m.access ->> 'clients.billing', m.access ->> 'clients')) >= 2
              -- held to the colleague's own client scope, as client_row_seen holds a reader (audit S7)
              and (v_cl.stage not in ('lead', 'contacted', 'proposal', 'past')
                   or public.level_rank(coalesce(m.access ->> case when v_cl.stage = 'past' then 'clients.past' else 'clients.leads' end,
                                                 m.access ->> 'clients')) >= 1)
              and (coalesce(m.client_scope, 'all') <> 'own'
                   or (nullif(btrim(coalesce(v_cl.owner, '')), '') is null and v_cl.stage in ('lead', 'contacted', 'proposal'))
                   or lower(btrim(coalesce(v_cl.owner, ''))) = lower(btrim(coalesce(m.name, ''))))))
  on conflict (dedupe_key) do nothing;
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.client_details_submit(text, jsonb) from public;
grant execute on function public.client_details_submit(text, jsonb) to anon, authenticated;

create or replace function public.quotation_make(p_client uuid, p_sel jsonb, p_idem text, p_source text,
                                                 p_by text, p_contact jsonb)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  v_c public.clients;
  v_card jsonb := public.quote_card();
  v_p jsonb;
  v_q public.quotations;
  v_now timestamptz := now();
  v_days int;
  v_fx numeric;
  v_sel jsonb := case when jsonb_typeof(p_sel) is distinct from 'object' then p_sel
                      when p_source = 'console' then p_sel - 'client'
                      else p_sel - 'edits' - 'client' end;
begin
  if p_idem is not null then
    select * into v_q from public.quotations q where q.idem = p_idem;
    if v_q.id is not null then return jsonb_build_object('ok', true, 'id', v_q.id, 'ref', v_q.ref, 'again', true); end if;
  end if;
  select * into v_c from public.clients where id = p_client;
  if v_c.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if v_card is null then return jsonb_build_object('error', 'no-card'); end if;
  v_fx := public.quote_fx(v_c.id);
  if v_fx = 0 then return jsonb_build_object('error', 'no-fx'); end if;
  v_p := public.quote_fx_out(public.quote_adjust(public.quote_price(public.quote_fx_snap(public.quote_tax_snap(v_card->'snapshot', v_c.id), v_fx),
           v_sel), v_sel->'edits'), v_fx);
  if v_p ? 'error' then return v_p; end if;
  v_days := coalesce(public.app_setting('quote_valid_days', (v_now at time zone 'Asia/Kuala_Lumpur')::date), 30)::int;
  begin
  insert into public.quotations (ref, client_id, brand, version, version_id, selection, lines, totals, source,
                                 issued_at, valid_until, made_by, contact, idem, access_key)
  values (public.quote_ref(v_c.name, v_now), v_c.id, v_c.name, v_card->>'version', (v_card->>'id')::uuid, v_sel,
          v_p->'lines', v_p->'totals' || jsonb_build_object('on_request', v_p->'on_request'), p_source,
          v_now, (v_now at time zone 'Asia/Kuala_Lumpur')::date + v_days, p_by, p_contact, p_idem,
          case when p_source = 'website' then public.new_link_key() end)
  returning * into v_q;
  -- Two presses at once with one key: the second answers the first's.
  exception when unique_violation then
    select * into v_q from public.quotations q where q.idem = p_idem;
    if p_idem is null or v_q.id is null then raise; end if;
    return jsonb_build_object('ok', true, 'id', v_q.id, 'ref', v_q.ref, 'again', true);
  end;
  insert into public.activity_log (actor, action, subject, detail)
  values (coalesce(p_by, 'Website'), 'client.quotation', v_c.name,
          v_q.ref || ' sent · ' || coalesce('Monthly incl. SST ' || case when v_fx is null then 'RM ' else 'S$ ' end ||
            to_char((v_q.totals->'month'->>'incl')::numeric, 'FM999,999,990.00'), 'one-off') ||
          ' · rate card v.' || v_q.version ||
          case coalesce((v_p->>'adjusted')::int, 0) when 0 then '' when 1 then ' · 1 line changed'
               else ' · ' || (v_p->>'adjusted') || ' lines changed' end);
  return jsonb_build_object('ok', true, 'id', v_q.id, 'ref', v_q.ref, 'key', v_q.access_key);
end $$;
revoke all on function public.quotation_make(uuid, jsonb, text, text, text, jsonb) from public, anon, authenticated;

create or replace function public.meta_links_save(p_client uuid, p_brand uuid, p_ad_accounts jsonb, p_page jsonb, p_instagram jsonb)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  v_client text;
  v_brand text;
  v_accs jsonb := '[]'::jsonb;
  v_page jsonb := public.meta_asset_of(p_page);
  v_ig jsonb := public.meta_asset_of(p_instagram);
  e jsonb;
  a jsonb;
  v_old public.meta_links;
  v_detail text;
begin
  if me.id is null or not public.allowed('clients', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if not public.client_seen(p_client, 'work') then return jsonb_build_object('error', 'denied'); end if;
  select c.name into v_client from public.clients c where c.id = p_client;
  if v_client is null then return jsonb_build_object('error', 'not-found'); end if;
  if p_brand is not null then
    select b.name into v_brand from public.client_brands b where b.id = p_brand and b.client_id = p_client;
    if v_brand is null then return jsonb_build_object('error', 'bad-brand'); end if;
  end if;
  if p_ad_accounts is not null and jsonb_typeof(p_ad_accounts) <> 'array' then return jsonb_build_object('error', 'bad-asset'); end if;
  for e in select x from jsonb_array_elements(coalesce(p_ad_accounts, '[]'::jsonb)) as t(x) loop
    a := public.meta_asset_of(e);
    if a is null or a ? 'bad' then return jsonb_build_object('error', 'bad-asset'); end if;
    if not exists (select 1 from jsonb_array_elements(v_accs) as y(z) where y.z ->> 'id' = a ->> 'id') then
      v_accs := v_accs || jsonb_build_array(a);
    end if;
  end loop;
  if jsonb_array_length(v_accs) > 20 or coalesce(v_page ? 'bad', false) or coalesce(v_ig ? 'bad', false) then
    return jsonb_build_object('error', 'bad-asset');
  end if;
  select * into v_old from public.meta_links l
   where l.client_id = p_client and l.brand_id is not distinct from p_brand for update;
  if v_old.id is not null and v_old.ad_accounts = v_accs and v_old.page is not distinct from v_page and v_old.instagram is not distinct from v_ig then
    return jsonb_build_object('ok', true);
  end if;
  if v_old.id is null and jsonb_array_length(v_accs) = 0 and v_page is null and v_ig is null then
    return jsonb_build_object('ok', true);
  end if;
  v_detail := concat_ws(' · ',
    case when coalesce(v_old.ad_accounts, '[]'::jsonb) <> v_accs
         then 'Meta ad accounts: ' || public.meta_names(v_old.ad_accounts) || ' → ' || public.meta_names(v_accs) end,
    case when v_old.page is distinct from v_page
         then 'Facebook Page: ' || public.meta_names(v_old.page) || ' → ' || public.meta_names(v_page) end,
    case when v_old.instagram is distinct from v_ig
         then 'Instagram: ' || public.meta_names(v_old.instagram) || ' → ' || public.meta_names(v_ig) end);
  -- Two first saves at once: the second writes over the first, never fails (audit 20).
  insert into public.meta_links (client_id, brand_id, ad_accounts, page, instagram, updated_by)
  values (p_client, p_brand, v_accs, v_page, v_ig, me.name)
  on conflict (client_id, coalesce(brand_id, '00000000-0000-0000-0000-000000000000'::uuid)) do update
     set ad_accounts = excluded.ad_accounts, page = excluded.page, instagram = excluded.instagram,
         updated_at = now(), updated_by = excluded.updated_by;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'client.brand', v_client, case when v_brand is not null then v_brand || ': ' else '' end || v_detail);
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.meta_links_save(uuid, uuid, jsonb, jsonb, jsonb) from public, anon;
grant execute on function public.meta_links_save(uuid, uuid, jsonb, jsonb, jsonb) to authenticated;

-- END OF CLIENT FORMS HOLD -------------------------------------------------
select public.functions_tidy();

-- ===========================================================================
-- CLIENTS AUDIT FIXES — a client's timeline written over the row as read,
-- billing complete at Active, a details form used on its own client, the
-- main contact swapped in one transaction. 2026-10-19. Safe to run twice.
-- Rollback at the foot. Mirrored byte for byte in supabase/schema.sql under
-- the same banner; tests/sql.js compares the two.
--
-- WHAT CHANGED (the audit of the Clients section, 2026-10-19)
--   * Trigger `clients_touch`: every update of a client stamps `updated_at`,
--     so the page writes the timeline (`stage_log`, `stage_since`,
--     `created_at`, a move's reason) only over the row as it read it, and a
--     move made meanwhile is never overwritten (item 4).
--   * Trigger `clients_active_billing`: a move into Active is refused while
--     the registered name, BRN or billing address is empty, or the client
--     holds no billing contact (the one chosen, else a live main contact)
--     (`active-needs-billing`, item 7). Only the move is held: a client
--     already Active keeps its place. `clients_active_code` is unchanged.
--   * `client_details_used(p_id, p_client)`: the form must be that client's
--     (`not-found`), so a Billing save on one client never marks another's
--     form used (item 8). The one-argument version is dropped.
--   * `client_contact_make_primary(p_contact)`: the main contact swapped in
--     one transaction, at Clients: Contacts Work on a client in scope at
--     Work (`denied`, `not-found`), so a failed swap never leaves a client
--     with no main contact (item 12). The page files it as before.
--
-- ORDER: the pages, then this file. A page from before calls
--   `client_details_used(p_id)`, which is gone: its Save is kept and the
--   form stays unmarked (the call's refusal is not shown). Its main-contact
--   change writes the table as before.
--
-- ROLLBACK
--   drop trigger clients_touch on public.clients;
--   drop trigger clients_active_billing on public.clients;
--   drop function public.client_contact_make_primary(uuid);
--   the CLIENT DETAILS FORM section's client_details_used(uuid) again, and
--   drop function public.client_details_used(uuid, uuid).
-- ===========================================================================

create or replace trigger clients_touch before update on public.clients
  for each row execute function public.touch_updated_at();

create or replace function public.clients_active_billing()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.stage = 'active' and old.stage is distinct from 'active' and (
       coalesce(btrim(new.legal_name), '') = ''
       or coalesce(btrim(new.company_no), '') = ''
       or coalesce(btrim(new.billing_address), '') = ''
       or not exists (select 1 from public.client_contacts k
                       where k.client_id = new.id and k.archived_at is null
                         and (k.id = new.bill_contact_id or k.is_primary))) then
    raise exception 'active-needs-billing';
  end if;
  return new;
end $$;
revoke all on function public.clients_active_billing() from public, anon, authenticated;
create or replace trigger clients_active_billing before update of stage on public.clients
  for each row execute function public.clients_active_billing();

drop function if exists public.client_details_used(uuid);
create or replace function public.client_details_used(p_id uuid, p_client uuid)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me  public.team_members := public.ops_me();
  v_f public.client_detail_forms;
begin
  if me.id is null or not public.allowed('clients.billing', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into v_f from public.client_detail_forms f where f.id = p_id;
  if v_f.id is null or v_f.client_id is distinct from p_client or not public.client_seen(v_f.client_id, 'work') then
    return jsonb_build_object('error', 'not-found');
  end if;
  if v_f.submitted_at is null then return jsonb_build_object('error', 'not-submitted'); end if;
  update public.client_detail_forms f set used_at = coalesce(f.used_at, now()), used_by = coalesce(f.used_by, (select t.id from public.team_members t where t.id = me.id)) where f.id = p_id;
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.client_details_used(uuid, uuid) from public, anon;
grant execute on function public.client_details_used(uuid, uuid) to authenticated;

create or replace function public.client_contact_make_primary(p_contact uuid)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me   public.team_members := public.ops_me();
  v_ct public.client_contacts;
begin
  if me.id is null or not public.allowed('clients.contacts', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into v_ct from public.client_contacts k where k.id = p_contact;
  if v_ct.id is null or v_ct.archived_at is not null or not public.client_seen(v_ct.client_id, 'work') then
    return jsonb_build_object('error', 'not-found');
  end if;
  if not v_ct.is_primary then
    update public.client_contacts k set is_primary = false where k.client_id = v_ct.client_id and k.is_primary;
    update public.client_contacts k set is_primary = true where k.id = v_ct.id;
  end if;
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.client_contact_make_primary(uuid) from public, anon;
grant execute on function public.client_contact_make_primary(uuid) to authenticated;

-- END OF CLIENTS AUDIT FIXES -------------------------------------------------

-- ===========================================================================
-- CHECKLISTS FROM PORTAL ONBOARDING — the Dashboard asks for the checklists
-- of clients onboarded in the portal alone.
-- 2026-10-19. Safe to run twice. Rollback at the foot. Mirrored byte for
-- byte in supabase/schema.sql under the same banner; tests/sql.js compares
-- the two.
--
-- WHAT CHANGED (the user, 2026-10-19, of Needs attention listing Brew
-- Garten's and Star Living's checklists at 1,092 days: "These shouldnt be
-- inside … since we previously did manually")
--   `client_checklists_due()` lists an Active client's checklist not signed
--   only where the checklist was started in the portal, or the client first
--   became Active on or after 15 Oct 2026 (Malaysia), the day the checklists
--   came to the portal. A client onboarded before then was checked on paper
--   and is not asked again. Everything else it answers is unchanged.
--
-- ROLLBACK
--   Run client_checklists_due from the CLIENT CHECKLISTS section of the
--   schema again (the function before this file).
-- ===========================================================================

create or replace function public.client_checklists_due()
returns jsonb
language sql stable security definer set search_path = public as $$
  select case when (public.ops_me()).id is null or not public.allowed('clients', 'view') then '[]'::jsonb else
    coalesce((select jsonb_agg(jsonb_build_object('client_id', c.id, 'name', c.name, 'slug', c.slug, 'owner', c.owner,
              'kind', k.kind, 'status', coalesce(r.status, 'open'), 'started', r.id is not null,
              'since', coalesce(c.stage_since, c.created_at)) order by coalesce(c.stage_since, c.created_at))
       from public.clients c
       cross join (values ('onboarding'), ('pre_ads')) k(kind)
       left join public.client_checklists r on r.client_id = c.id and r.kind = k.kind
      where c.stage = 'active'
        and coalesce(r.status, 'open') <> 'signed'
        and (r.id is not null
             or (select min((e->>'at')::timestamptz) from jsonb_array_elements(coalesce(c.stage_log, '[]'::jsonb)) e
                  where e->>'stage' = 'active' and e->>'at' is not null)
                >= ('2026-10-15'::date)::timestamp at time zone 'Asia/Kuala_Lumpur')
        and public.client_scope_ok('client', c.id, 'view')
        and not exists (select 1 from public.ops_engagement_checks x join public.ops_engagements e on e.id = x.engagement_id
                         where e.client_id = c.id and x.key = k.kind and x.state = 'na')), '[]'::jsonb) end
$$;
revoke all on function public.client_checklists_due() from public, anon;
grant execute on function public.client_checklists_due() to authenticated;

-- END OF CHECKLISTS FROM PORTAL ONBOARDING ----------------------------------

-- ===========================================================================
-- A PLANNED SETTING WITHDRAWN — a Business setting planned from a later day is
-- withdrawn by saving the value in force the day before (2026-10-19)
-- ===========================================================================
-- WHY (business settings audit, 2026-10-19, item 19): to cancel "SST 6% from
-- 1 Dec" an admin had to save today's 8% from 1 Dec, which left a second row
-- restating the value in force and filed "SST: 6% → 8%".
--
-- WHAT IT CHANGES
--   * `app_settings_set` (restated whole; every refusal kept): a value saved
--     for a later day that equals the value in force the day before, where
--     that day holds a planned row and an earlier row exists, deletes the
--     planned row instead of writing one, and files `team.changed` under
--     Settings as "SST: planned change withdrawn · 6% from 1 Dec 2026, stays
--     8%". The figure is answered in `changed` as before, so the sheet's
--     "From …:" note leaves with the row.
--
-- ORDER: this file, then nothing (the pages already send it). Safe to run
-- twice. The connector holds a statement holding `delete`: this function is
-- run in the SQL Editor.
-- ROLLBACK: run HEALTH DATA KEPT FOR A TIME's `app_settings_set` again.
-- ===========================================================================

create or replace function public.app_settings_set(p_from date, p_values jsonb)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me public.team_members; v_k text; v_v numeric; v_was numeric; v_name text; v_unit text; v_pre text;
  v_today date := (now() at time zone 'Asia/Kuala_Lumpur')::date;
  v_keys constant text[] := array['lead_followup_hours', 'proposal_followup_days', 'sst_pct',
    'term_1_3', 'term_4_5', 'term_6_11', 'term_12_23', 'term_18_23', 'term_24', 'report_due_days', 'revision_due_days',
    'ai_price_in', 'ai_price_out', 'meta_checks', 'approval_reminder_days', 'ai_price_search',
    'reach_allowance_pct', 'priority_urgent_hours', 'priority_high_hours', 'priority_medium_hours',
    'task_remind_hours', 'task_start_days', 'quote_valid_days', 'details_form_days', 'wa_repeat_hours',
    'bench_cpr_low', 'bench_cpr_mid', 'bench_cpr_high', 'bench_cpr_top', 'bench_msg_min', 'bench_msg_target', 'bench_msg_max',
    'bench_form_min', 'bench_form_target', 'bench_form_max', 'bench_cpm_min', 'bench_cpm_max', 'bench_cpl_rise',
    'bench_reels_share', 'bench_ad_spend_pct', 'bench_adset_daily', 'vic_lead_followup_hours', 'vic_proposal_followup_days', 'fx_sgd',
    'health_keep_months', 'health_leaver_months'];
  v_moved text[] := '{}';
  v_drop boolean; v_fw text; v_fv text;
begin
  if not public.ops_granted('team.settings', 'work') then return jsonb_build_object('error', 'denied'); end if;
  v_me := public.ops_me();
  if p_from is null or p_from < v_today then return jsonb_build_object('error', 'past', 'today', v_today); end if;
  if jsonb_typeof(p_values) is distinct from 'object' then return jsonb_build_object('error', 'bad-value'); end if;
  for v_k in select jsonb_object_keys(p_values) loop
    if not (v_k = any(v_keys)) or jsonb_typeof(p_values -> v_k) <> 'number' then
      return jsonb_build_object('error', 'bad-value', 'key', v_k);
    end if;
    v_v := (p_values ->> v_k)::numeric;
    if round(v_v, case when v_k = 'fx_sgd' then 4 else 2 end) <> v_v
       or (v_k = 'fx_sgd' and (v_v < 0.5 or v_v > 10))
       or (v_k in ('lead_followup_hours', 'vic_lead_followup_hours') and (v_v < 1 or v_v > 720 or v_v <> trunc(v_v)))
       or (v_k in ('proposal_followup_days', 'vic_proposal_followup_days') and (v_v < 1 or v_v > 365 or v_v <> trunc(v_v)))
       or (v_k = 'report_due_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'revision_due_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'approval_reminder_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'sst_pct' and (v_v < 0 or v_v > 100))
       or (v_k like 'term_%' and (v_v < -100 or v_v > 100))
       or (v_k like 'ai_price_%' and (v_v < 0 or v_v > 1000))
       or (v_k = 'meta_checks' and v_v not in (0, 1))
       or (v_k = 'reach_allowance_pct' and (v_v < 0 or v_v > 5))
       or (v_k like 'priority_%_hours' and (v_v < 1 or v_v > 720 or v_v <> trunc(v_v)))
       or (v_k = 'task_remind_hours' and (v_v < 0 or v_v > 24 or v_v <> trunc(v_v)))
       or (v_k = 'task_start_days' and (v_v < 0 or v_v > 30 or v_v <> trunc(v_v)))
       or (v_k in ('quote_valid_days', 'details_form_days') and (v_v < 1 or v_v > 90 or v_v <> trunc(v_v)))
       or (v_k = 'wa_repeat_hours' and (v_v < 0 or v_v > 168 or v_v <> trunc(v_v)))
       or (v_k = 'health_keep_months' and (v_v < 6 or v_v > 120 or v_v <> trunc(v_v)))
       or (v_k = 'health_leaver_months' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k in ('bench_reels_share') and (v_v < 0 or v_v > 100))
       or (v_k = 'bench_ad_spend_pct' and (v_v < 1 or v_v > 100))
       or (v_k = 'bench_cpl_rise' and (v_v < -100 or v_v > 100))
       or (v_k like 'bench_%' and v_k not in ('bench_reels_share', 'bench_ad_spend_pct', 'bench_cpl_rise') and (v_v < 0 or v_v > 10000)) then
      return jsonb_build_object('error', 'bad-value', 'key', v_k);
    end if;
  end loop;
  for v_k in select jsonb_object_keys(p_values) loop
    v_v := (p_values ->> v_k)::numeric;
    v_was := public.app_setting(v_k, p_from);
    if v_was is distinct from v_v then
      /* A planned change saved back to the value in force the day before is
         withdrawn: its row goes, rather than a second row restating it. */
      v_drop := p_from > v_today
        and exists (select 1 from public.app_settings s where s.key = v_k and s.from_date = p_from)
        and exists (select 1 from public.app_settings s where s.key = v_k and s.from_date < p_from)
        and public.app_setting(v_k, p_from - 1) = v_v;
      if v_drop then
        delete from public.app_settings s where s.key = v_k and s.from_date = p_from;
      else
        insert into public.app_settings (key, from_date, value, set_by, set_at)
        values (v_k, p_from, v_v, v_me.id, now())
        on conflict (key, from_date) do update set value = excluded.value, set_by = excluded.set_by, set_at = now();
      end if;
      v_name := case v_k when 'lead_followup_hours' then 'A lead waits' when 'proposal_followup_days' then 'A proposal waits'
        when 'vic_lead_followup_hours' then 'A VIC lead waits' when 'vic_proposal_followup_days' then 'A VIC proposal waits'
        when 'sst_pct' then 'SST' when 'term_1_3' then '1 to 3 months' when 'term_4_5' then '4 and 5 months'
        when 'term_6_11' then '6 to 11 months' when 'term_12_23' then '12 to 17 months' when 'term_18_23' then '18 to 23 months' when 'term_24' then '24 months and more'
        when 'revision_due_days' then 'Revision due' when 'ai_price_in' then 'AI input, a million tokens'
        when 'ai_price_out' then 'AI output, a million tokens' when 'ai_price_search' then 'AI web searches, a thousand' when 'meta_checks' then 'Meta checks'
        when 'approval_reminder_days' then 'Approval reminder' when 'reach_allowance_pct' then 'Reach allowance'
        when 'priority_urgent_hours' then 'Urgent deadline' when 'priority_high_hours' then 'High deadline'
        when 'priority_medium_hours' then 'Medium deadline' when 'task_remind_hours' then 'Task reminders'
        when 'task_start_days' then 'Not started reminder' when 'quote_valid_days' then 'Quotation validity' when 'details_form_days' then 'Details form open'
        when 'wa_repeat_hours' then 'WhatsApp sent again'
        when 'bench_cpr_low' then 'Property cost per result, tier 1 from' when 'bench_cpr_mid' then 'Property cost per result, tier 2 from'
        when 'bench_cpr_high' then 'Property cost per result, tier 3 from' when 'bench_cpr_top' then 'Property cost per result, tier 3 up to'
        when 'bench_msg_min' then 'Messaging cost per result, low' when 'bench_msg_target' then 'Messaging cost per result, target'
        when 'bench_msg_max' then 'Messaging cost per result, high' when 'bench_form_min' then 'Lead form cost per result, low'
        when 'bench_form_target' then 'Lead form cost per result, target' when 'bench_form_max' then 'Lead form cost per result, high'
        when 'bench_cpm_min' then 'Cost per 1,000 impressions, low' when 'bench_cpm_max' then 'Cost per 1,000 impressions, high'
        when 'bench_cpl_rise' then 'Cost per lead rise a year' when 'bench_reels_share' then 'Reels share of impressions'
        when 'bench_ad_spend_pct' then 'Ad spend of the budget' when 'bench_adset_daily' then 'Daily budget an ad set, at least'
        when 'fx_sgd' then 'Singapore dollar rate'
        when 'health_keep_months' then 'Health check-ins kept' when 'health_leaver_months' then 'A leaver''s health data kept'
        else 'Report due' end;
      v_pre := case when v_k = 'fx_sgd' then 'RM ' when v_k like 'ai_price_%' then 'US$' when v_k like 'bench_%' and v_k not in ('bench_cpl_rise', 'bench_reels_share', 'bench_ad_spend_pct') then 'RM ' else '' end;
      v_unit := case when v_k = 'fx_sgd' then ' to S$1' when v_k in ('lead_followup_hours', 'vic_lead_followup_hours', 'task_remind_hours', 'wa_repeat_hours') or v_k like 'priority_%_hours' then ' hours'
        when v_k in ('proposal_followup_days', 'vic_proposal_followup_days', 'report_due_days', 'revision_due_days', 'approval_reminder_days', 'task_start_days', 'quote_valid_days', 'details_form_days') then ' days'
        when v_k in ('health_keep_months', 'health_leaver_months') then ' months'
        when v_pre <> '' then '' else '%' end;
      v_fw := case when v_k = 'meta_checks' then case when v_was = 1 then 'On' else 'Off' end else coalesce(v_pre ||
              trim(to_char(v_was, case when v_k = 'fx_sgd' then 'FM999999990.9999' else 'FM999999990.99' end), '.') || v_unit, 'not set') end;
      v_fv := case when v_k = 'meta_checks' then case when v_v = 1 then 'On' else 'Off' end else v_pre ||
              trim(to_char(v_v, case when v_k = 'fx_sgd' then 'FM999999990.9999' else 'FM999999990.99' end), '.') || v_unit end;
      insert into public.activity_log (actor, action, subject, detail)
      values (coalesce(v_me.name, 'admin'), 'team.changed', 'Settings',
              case when v_drop then v_name || ': planned change withdrawn · ' || v_fw || ' from ' || public.register_day(p_from) ||
                ', stays ' || v_fv else
              v_name || ': ' || case when v_k = 'meta_checks' then
                case when v_was = 1 then 'On' else 'Off' end || ' → ' || case when v_v = 1 then 'On' else 'Off' end ||
                ' · from ' || public.register_day(p_from) else '' end ||
              case when v_k = 'meta_checks' then '' else coalesce(v_pre ||
              trim(to_char(v_was, case when v_k = 'fx_sgd' then 'FM999999990.9999' else 'FM999999990.99' end), '.') || v_unit, 'not set') || ' → ' || v_pre ||
              trim(to_char(v_v, case when v_k = 'fx_sgd' then 'FM999999990.9999' else 'FM999999990.99' end), '.') || v_unit ||
              ' · from ' || public.register_day(p_from) end end);
      v_moved := v_moved || v_k;
    end if;
  end loop;
  return public.app_settings_read() || jsonb_build_object('changed', to_jsonb(v_moved));
end $$;
revoke all on function public.app_settings_set(date, jsonb) from public, anon;
grant execute on function public.app_settings_set(date, jsonb) to authenticated;

-- END OF A PLANNED SETTING WITHDRAWN -----------------------------------------
select public.functions_tidy();

-- ===========================================================================
-- SETTINGS A CLIENT PAGE READS — app_settings_read answers anyone outside the
-- team only the figures a client page prices with (2026-10-19)
-- ===========================================================================
-- WHY (audit 2026-10-18/19, item 1): `app_settings_read()` is granted to
-- anon, since the client portal, the selection page and the quotation
-- website price with SST and the term percentages, and it answered every
-- Business setting: AI prices, the ad benchmarks, the ringgit to S$ rate,
-- the follow-up limits, the retention months. Only who set each figure and
-- when were hidden.
--
-- WHAT IT CHANGES
--   * Anyone the team does not hold (`is_team()` false: a visitor, a
--     client's contact signed in) is answered `sst_pct` and the six term
--     percentages alone, the keys js/money.js reads on a client page
--     (`taxOf`, `termPct`). The team is answered every key, as before.
--   * Nothing else changes: `today`, `admin` and the shape of the answer.
--
-- ORDER: this file alone, after the pages (no page changes). Safe to run
-- twice. Rollback: run app_settings_read from BUSINESS SETTINGS again.
-- ===========================================================================

create or replace function public.app_settings_read()
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_team boolean := public.is_team();
begin
  return jsonb_build_object(
    'today', (now() at time zone 'Asia/Kuala_Lumpur')::date,
    'admin', v_team and public.allowed('admin'),
    'settings', coalesce((select jsonb_agg(jsonb_build_object('key', s.key, 'from', s.from_date, 'value', s.value,
                   'by', case when v_team then (select t.name from public.team_members t where t.id = s.set_by) end,
                   'at', case when v_team then s.set_at end)
                 order by s.key, s.from_date) from public.app_settings s
                where v_team or s.key in ('sst_pct', 'term_1_3', 'term_4_5', 'term_6_11', 'term_12_23', 'term_18_23', 'term_24')),
                '[]'::jsonb));
end $$;
grant execute on function public.app_settings_read() to anon, authenticated;
-- END OF SETTINGS A CLIENT PAGE READS ---------------------------------------
select public.functions_tidy();

-- ===========================================================================
-- VERIFY LOOKUPS COUNTED — /verify/ answers a connection outside the team
-- thirty references an hour (2026-10-19)
-- ===========================================================================
-- WHY (audit 2026-10-18/19, item 2): `verify_serial` (anon) answers any
-- reference with its kind, date and Valid or Void, and an HR reference is
-- guessable (`ADHR/{Employee ID}/{type code}{YYMM}`, `.../PR{YYMM}`), so a
-- stranger could sweep the months and codes and learn which letters a
-- colleague was given.
--
-- WHAT IT CHANGES
--   * Each lookup by anyone the team does not hold is counted against the
--     caller's address (`request_ip()`: the address Cloudflare saw) in
--     `verify_tries` (RLS on, no policy, no grant). Past 30 in an hour the
--     answer is `locked` with the minutes left, before any reference is
--     read; the page says so in its words. A colleague is never counted,
--     nor a session with no request (the SQL Editor, a suite).
--   * What a found reference shows is unchanged.
--   * `privacy_retention` (the 2nd of each month) removes an address's row
--     once its hour began over 30 days ago (`verify_tries_removed`);
--     everything else it does is PASSCODE TRIES ARE KEPT FOR A TIME's.
--
-- ORDER: the pages first (verify.js reads `locked`), then this file in the
-- SQL Editor as one run (the connector holds a statement holding `delete`).
-- Safe to run twice. An old open tab reads a lock as Unable to check.
-- Rollback: run verify_serial from A PERFORMANCE RECORD CAN BE DELETED and
-- privacy_retention from PASSCODE TRIES ARE KEPT FOR A TIME again, then
-- drop table if exists public.verify_tries;
-- ===========================================================================

create table if not exists public.verify_tries (
  ip    text primary key,
  n     integer not null default 0,
  since timestamptz not null default now()
);
alter table public.verify_tries enable row level security;
revoke all on public.verify_tries from public, anon, authenticated;

create or replace function public.verify_serial(p_serial text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  s text := upper(btrim(coalesce(p_serial, '')));
  sd text;
  d public.documents%rowtype;
  l public.client_documents%rowtype;
  rv public.perf_reviews%rowtype;
  dl public.perf_deleted%rowtype;
  v_ip text := public.request_ip();
  v_n integer;
  v_since timestamptz;
begin
  if v_ip <> '' then
    if not public.is_team() then
      insert into public.verify_tries as v (ip, n, since) values (v_ip, 1, now())
      on conflict (ip) do update
        set n = case when v.since < now() - interval '1 hour' then 1 else v.n + 1 end,
            since = case when v.since < now() - interval '1 hour' then now() else v.since end
      returning v.n, v.since into v_n, v_since;
      if v_n > 30 then
        return jsonb_build_object('found', false, 'locked', true,
          'minutes', greatest(1, ceil(extract(epoch from (v_since + interval '1 hour' - now())) / 60)::integer));
      end if;
    end if;
  end if;
  if length(s) < 3 or length(s) > 40 then return jsonb_build_object('found', false); end if;
  sd := replace(s, '/', '-');
  select * into d from public.documents
   where upper(serial) = s or replace(upper(serial), '/', '-') = sd
   order by (upper(serial) = s) desc, (voided_at is null) desc, created_at desc limit 1;
  if d.id is not null then
    return jsonb_build_object('found', true, 'serial', d.serial,
      'kind', case when d.family = 'hr' then 'HR Letter' else d.kind end,
      'issued_at', d.issued_at,
      'state', case when d.voided_at is null then 'valid' else 'voided' end);
  end if;
  select * into l from public.client_documents
   where upper(number) = s or replace(upper(number), '/', '-') = sd
   order by (upper(number) = s) desc limit 1;
  if l.id is not null then
    return jsonb_build_object('found', true, 'serial', l.number, 'kind', 'Letter of Offer',
      'issued_at', l.issued_at,
      'state', case when l.voided_at is not null then 'voided'
                    when l.superseded_by is not null then 'replaced'
                    else 'valid' end);
  end if;
  select * into rv from public.perf_reviews pr
   where (upper(pr.serial) = s or replace(upper(pr.serial), '/', '-') = sd)
     and exists (select 1 from public.perf_events pe where pe.review_id = pr.id and pe.kind = 'printed')
   limit 1;
  if rv.id is not null then
    return jsonb_build_object('found', true, 'serial', rv.serial, 'kind', 'HR Letter',
      'issued_at', rv.released_at,
      'state', case when rv.status = 'draft' then 'replaced' else 'valid' end);
  end if;
  select * into dl from public.perf_deleted pd
   where pd.printed and (upper(pd.serial) = s or replace(upper(pd.serial), '/', '-') = sd)
   order by pd.deleted_at desc limit 1;
  if dl.id is not null then
    return jsonb_build_object('found', true, 'serial', dl.serial, 'kind', 'HR Letter',
      'issued_at', dl.released_at, 'state', 'voided');
  end if;
  return jsonb_build_object('found', false);
end $$;
revoke all on function public.verify_serial(text) from public;
grant execute on function public.verify_serial(text) to anon, authenticated;

create or replace function public.privacy_retention(p_now timestamptz default now())
returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_wa integer := 0; v_act integer := 0; v_hc integer := 0; v_hl integer := 0; v_lt integer := 0; v_vt integer := 0;
  v_today date := (p_now at time zone 'Asia/Kuala_Lumpur')::date;
  v_keep integer := coalesce(public.app_setting('health_keep_months', (p_now at time zone 'Asia/Kuala_Lumpur')::date), 24)::integer;
  v_left integer := coalesce(public.app_setting('health_leaver_months', (p_now at time zone 'Asia/Kuala_Lumpur')::date), 6)::integer;
  v_gone uuid[];
begin
  update public.wa_outbox o
     set to_number = '', to_name = null, params = '[]'::jsonb, button = null
   where o.created_at < p_now - interval '12 months'
     and o.state not in ('queued', 'sending')
     and (o.to_number <> '' or o.to_name is not null or o.params <> '[]'::jsonb or o.button is not null);
  get diagnostics v_wa = row_count;
  delete from public.activity_log a where a.created_at < p_now - interval '3 years';
  get diagnostics v_act = row_count;
  delete from public.health_checkins k where k.half < v_today - make_interval(months => v_keep);
  get diagnostics v_hc = row_count;
  select coalesce(array_agg(m.id), '{}') into v_gone from public.team_members m
   where not m.active and coalesce(m.removed_at, m.expired_at) < p_now - make_interval(months => v_left);
  if array_length(v_gone, 1) > 0 then
    delete from public.health_checkins k where k.team_member_id = any(v_gone);
    get diagnostics v_hl = row_count;
    delete from public.health_talks t where t.team_member_id = any(v_gone) or t.with_id = any(v_gone);
    delete from public.health_log l where l.team_member_id = any(v_gone);
    delete from public.health_consents c where c.team_member_id = any(v_gone);
  end if;
  -- A caller's address against a link's passcode, once it has had nothing
  -- to say for 30 days and holds no lock (audit 2026-10-18, item 14).
  delete from public.link_tries t
   where greatest(t.last_at, coalesce(t.ok_at, t.last_at)) < p_now - interval '30 days'
     and coalesce(t.locked_until, t.last_at) < p_now;
  get diagnostics v_lt = row_count;
  -- A caller's address against /verify/, once its hour began 30 days ago.
  delete from public.verify_tries v where v.since < p_now - interval '30 days';
  get diagnostics v_vt = row_count;
  return jsonb_build_object('whatsapp_cleared', v_wa, 'activity_removed', v_act,
    'health_checkins_removed', v_hc + v_hl, 'health_leavers', coalesce(array_length(v_gone, 1), 0),
    'link_tries_removed', v_lt, 'verify_tries_removed', v_vt);
end $$;
revoke all on function public.privacy_retention(timestamptz) from public, anon, authenticated;
-- END OF VERIFY LOOKUPS COUNTED ---------------------------------------------
select public.functions_tidy();

-- ===========================================================================
-- UNREAD NOTICES PRUNED — jobs_prune also removes a notice left unread for
-- 180 days (2026-10-19)
-- ===========================================================================
-- WHY (audit 2026-10-18/19, item 4): `jobs_prune` removed only notices read
-- over 90 days ago, so one never opened was kept for good.
--
-- WHAT IT CHANGES
--   * It also removes a notice unread for over 180 days. A colleague's
--     notice (`notice_id`) still stays, read or not: Notices reads its
--     copies. Job history is pruned as before.
--
-- ORDER: this file in the SQL Editor as one run (the connector holds a
-- statement holding `delete`). Safe to run twice. Rollback: run jobs_prune
-- from SCHEDULED JOBS WATCHED again.
-- ===========================================================================

create or replace function public.jobs_prune(p_now timestamptz default now())
returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_runs integer := 0; v_notes integer := 0;
begin
  if to_regclass('cron.job_run_details') is not null then
    delete from cron.job_run_details d where d.end_time < p_now - interval '14 days';
    get diagnostics v_runs = row_count;
  end if;
  /* A colleague's notice (notice_id) stays: Notices read its copies. */
  delete from public.ops_notifications n
   where n.notice_id is null
     and ((n.read_at is not null and n.created_at < p_now - interval '90 days')
       or (n.read_at is null and n.created_at < p_now - interval '180 days'));
  get diagnostics v_notes = row_count;
  return jsonb_build_object('job_runs', v_runs, 'notices', v_notes);
end $$;
revoke all on function public.jobs_prune(timestamptz) from public, anon, authenticated;
-- END OF UNREAD NOTICES PRUNED ----------------------------------------------

-- A SUPPLIER'S DETAILS UPDATED BY LINK — approval ends the details form, an
-- approved supplier is sent an update link, a bank change is approved again
-- (2026-10-20)
-- ===========================================================================
-- WHY (the user, 2026-10-20, on BRIQ PACKAGING's record: an Active supplier
-- whose details form stood open until 2 Nov, and "if one supplier that has
-- been registered and approved by our company would like to change record,
-- how could this be done from supplier side?"): a form link outlived the
-- step it was made for, and a supplier asked to change its details had to
-- type every field again, its bank account included.
--
-- WHAT IT CHANGES
--   * `supplier_forms.purpose`: `details` (the first form, a Pending
--     supplier's) or `update` (a supplier already approved).
--   * `supplier_link`: a supplier that is not Pending is sent an update link
--     (Request update), filed Update link created / reset.
--   * `supplier_set_status`: a move of status ends every open link of the
--     supplier, filed with the move (… · details form link closed);
--     approving from Pending stamps who approved and when, every time.
--   * `supplier_form_read`: an update link answers the details held but the
--     NRIC and the bank details (`current`), and whether they are held
--     (`bank_held`, `nric_held`); never their values.
--   * `supplier_form_submit`: on an update link the NRIC and the bank details
--     left blank keep what is held (the bank account blank keeps the payee,
--     bank, account, SWIFT and bank address together); the team is told
--     "Supplier details update received".
--   * `supplier_get`: the form's `purpose` and `bank_changed` (its answers'
--     payee, bank or account differ from what is held), so a colleague
--     without Supplier bank details still reads that they changed.
--   * `supplier_save`: an Active supplier whose payee, bank or account
--     changes goes back to Pending until approved again (`repending`), filed.
--   * `supplier_json`: `approved_by` names a colleague, never a system
--     account.
--
-- ORDER: this file, then the pages. An old page reads `purpose` as absent
-- and shows the update link as a details form, which still works. Safe to
-- run twice. Rollback: SUPPLIERS, A SECTION OF THEIR OWN's and SUPPLIERS
-- LINKED TO CLIENTS's definitions of these functions, and SUPPLIERS's
-- `supplier_json`; the column may stay.
-- ===========================================================================

alter table public.supplier_forms add column if not exists purpose text not null default 'details';
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'supplier_forms_purpose_check') then
    alter table public.supplier_forms add constraint supplier_forms_purpose_check check (purpose in ('details', 'update'));
  end if;
end $$;
/* A link open on a supplier already approved is an update link. */
update public.supplier_forms f set purpose = 'update'
  from public.suppliers s
 where s.id = f.supplier_id and s.status <> 'pending' and f.purpose = 'details'
   and f.submitted_at is null and f.voided_at is null and f.expires_at > now();

create or replace function public.supplier_json(s public.suppliers, p_pay boolean)
returns jsonb
language sql stable set search_path = public as $$
  select jsonb_strip_nulls(jsonb_build_object(
    'id', s.id, 'code', s.code, 'name', s.name, 'kind', s.kind, 'brn', s.brn, 'tin', s.tin, 'sst_no', s.sst_no,
    'phone', s.phone, 'address', s.address, 'contact_name', s.contact_name, 'designation', s.designation,
    'email', s.email, 'mobile', s.mobile, 'payment_term', s.payment_term, 'currency', s.currency,
    'finance_email', s.finance_email, 'status', s.status, 'created_at', s.created_at, 'updated_at', s.updated_at,
    'approved_at', s.approved_at,
    'approved_by', (select m.name from public.team_members m where m.id = s.approved_by and not coalesce(m.system, false)))
    || case when p_pay then jsonb_strip_nulls(jsonb_build_object(
      'nric', s.nric, 'payee_name', s.payee_name, 'bank_name', s.bank_name, 'bank_account', s.bank_account,
      'swift', s.swift, 'bank_address', s.bank_address)) else '{}'::jsonb end)
$$;
revoke all on function public.supplier_json(public.suppliers, boolean) from public, anon, authenticated;

create or replace function public.supplier_link(p_id uuid, p_reset boolean default false)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me    public.team_members := public.ops_me();
  s     public.suppliers;
  f     public.supplier_forms;
  v_key text;
  v_days int;
  v_purpose text;
begin
  if me.id is null or not public.allowed('suppliers', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into s from public.suppliers x where x.id = p_id;
  if s.id is null then return jsonb_build_object('error', 'not-found'); end if;
  v_purpose := case when s.status = 'pending' then 'details' else 'update' end;
  select * into f from public.supplier_forms x
   where x.supplier_id = p_id and x.voided_at is null and x.submitted_at is null and x.expires_at > now()
   order by x.created_at desc limit 1;
  if f.id is not null and not coalesce(p_reset, false) then
    return jsonb_build_object('ok', true, 'id', f.id, 'key', f.access_key, 'expires_at', f.expires_at, 'purpose', f.purpose);
  end if;
  update public.supplier_forms x set voided_at = now()
   where x.supplier_id = p_id and x.voided_at is null and x.submitted_at is null;
  loop
    v_key := public.new_link_key();
    exit when not exists (select 1 from public.supplier_forms x where x.access_key = v_key);
  end loop;
  v_days := coalesce(public.app_setting('details_form_days', (now() at time zone 'Asia/Kuala_Lumpur')::date), 14)::int;
  insert into public.supplier_forms (supplier_id, access_key, created_by, expires_at, purpose)
  values (p_id, v_key, me.id, now() + make_interval(days => v_days), v_purpose)
  returning * into f;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'supplier.edited', coalesce(s.name, s.code),
          s.code || ' · ' || case when v_purpose = 'update' then 'Update link' else 'Details form link' end ||
          case when coalesce(p_reset, false) then ' reset' else ' created' end);
  return jsonb_build_object('ok', true, 'id', f.id, 'key', f.access_key, 'expires_at', f.expires_at, 'purpose', f.purpose);
end $$;
revoke all on function public.supplier_link(uuid, boolean) from public, anon;
grant execute on function public.supplier_link(uuid, boolean) to authenticated;

create or replace function public.supplier_set_status(p_id uuid, p_status text)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  s  public.suppliers;
  n  int;
begin
  if me.id is null or not public.allowed('suppliers', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if p_status not in ('active', 'inactive') then return jsonb_build_object('error', 'bad-status'); end if;
  select * into s from public.suppliers x where x.id = p_id for update;
  if s.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if s.status = p_status then return jsonb_build_object('ok', true, 'status', s.status); end if;
  if p_status = 'active' and (s.name is null or s.kind is null or s.tin is null or s.address is null or s.email is null
      or s.payment_term is null or s.bank_account is null) then
    return jsonb_build_object('error', 'incomplete');
  end if;
  update public.suppliers x set status = p_status, updated_at = now(),
    approved_at = case when p_status = 'active' and x.status = 'pending' then now() else x.approved_at end,
    approved_by = case when p_status = 'active' and x.status = 'pending' then me.id else x.approved_by end
   where x.id = p_id;
  /* A link is made for one step: a move of status ends every one open. */
  update public.supplier_forms x set expires_at = now()
   where x.supplier_id = p_id and x.voided_at is null and x.submitted_at is null and x.expires_at > now();
  get diagnostics n = row_count;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, case when s.status = 'pending' then 'supplier.approved' else 'supplier.edited' end, coalesce(s.name, s.code),
          s.code || ' · ' || initcap(s.status) || ' → ' || initcap(p_status) ||
          case when n > 0 then ' · details form link closed' else '' end);
  return jsonb_build_object('ok', true, 'status', p_status, 'closed', n);
end $$;
revoke all on function public.supplier_set_status(uuid, text) from public, anon;
grant execute on function public.supplier_set_status(uuid, text) to authenticated;

create or replace function public.supplier_form_read(p_key text)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  f public.supplier_forms;
  s public.suppliers;
begin
  if coalesce(p_key, '') !~ '^[a-z0-9]{8}$' then return jsonb_build_object('error', 'not_found'); end if;
  select * into f from public.supplier_forms x where x.access_key = p_key and x.voided_at is null;
  if f.id is null then return jsonb_build_object('error', 'not_found'); end if;
  if f.submitted_at is not null then return jsonb_build_object('error', 'submitted'); end if;
  if f.expires_at <= now() then return jsonb_build_object('error', 'expired'); end if;
  select * into s from public.suppliers x where x.id = f.supplier_id;
  if f.purpose = 'update' then
    return jsonb_build_object('ok', true, 'name', s.name, 'code', s.code, 'expires_at', f.expires_at, 'purpose', 'update',
      'current', jsonb_strip_nulls(jsonb_build_object(
        'kind', s.kind, 'name', s.name, 'brn', s.brn, 'tin', s.tin, 'sst_no', s.sst_no, 'phone', s.phone,
        'address', s.address, 'contact_name', s.contact_name, 'designation', s.designation, 'email', s.email,
        'mobile', s.mobile, 'payment_term', s.payment_term, 'currency', s.currency, 'finance_email', s.finance_email)),
      'bank_held', s.bank_account is not null, 'nric_held', s.nric is not null);
  end if;
  return jsonb_build_object('ok', true, 'name', s.name, 'code', s.code, 'expires_at', f.expires_at, 'purpose', 'details');
end $$;
revoke all on function public.supplier_form_read(text) from public;
grant execute on function public.supplier_form_read(text) to anon, authenticated;

create or replace function public.supplier_form_submit(p_key text, p_answers jsonb)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  f public.supplier_forms;
  s public.suppliers;
  v jsonb;
  a jsonb := coalesce(p_answers, '{}'::jsonb);
begin
  if coalesce(p_key, '') !~ '^[a-z0-9]{8}$' then return jsonb_build_object('error', 'not_found'); end if;
  select * into f from public.supplier_forms x where x.access_key = p_key and x.voided_at is null for update;
  if f.id is null then return jsonb_build_object('error', 'not_found'); end if;
  if f.submitted_at is not null then return jsonb_build_object('error', 'submitted'); end if;
  if f.expires_at <= now() then return jsonb_build_object('error', 'expired'); end if;
  if coalesce(a->>'authorise', '') <> 'true' then return jsonb_build_object('error', 'bad-authorise'); end if;
  select * into s from public.suppliers x where x.id = f.supplier_id;
  /* An update keeps the NRIC and the bank details held where left blank. */
  if f.purpose = 'update' then
    if btrim(coalesce(a->>'bank_account', '')) = '' and s.bank_account is not null then
      a := a || jsonb_build_object('payee_name', s.payee_name, 'bank_name', s.bank_name, 'bank_account', s.bank_account,
                                   'swift', s.swift, 'bank_address', s.bank_address);
    end if;
    if btrim(coalesce(a->>'nric', '')) = '' and s.nric is not null then
      a := a || jsonb_build_object('nric', s.nric);
    end if;
  end if;
  v := public.supplier_values_check(a, true);
  if v ? 'error' then return v; end if;
  update public.supplier_forms x set submitted_at = now(), answers = jsonb_strip_nulls(v) where x.id = f.id;
  insert into public.activity_log (actor, action, subject, detail)
  values (v->>'contact_name', 'supplier.edited', coalesce(s.name, v->>'name'), s.code || ' · ' ||
          case when f.purpose = 'update' then 'Details update received on the update link' else 'Details received on the details form' end);
  insert into public.ops_notifications (team_member_id, kind, title, body, supplier_id, dedupe_key)
  select m.id, 'supplier.details',
         case when f.purpose = 'update' then 'Supplier details update received · ' else 'Supplier details received · ' end || coalesce(s.name, v->>'name'),
         'From ' || (v->>'contact_name') || '. Review them on the supplier.',
         s.id, 'supplier.details:' || f.id || ':' || m.id
    from public.team_members m
   where m.active and not coalesce(m.system, false)
     and (m.is_admin or m.role = 'admin'
          or public.level_rank(m.access ->> 'suppliers') >= 2)
  on conflict (dedupe_key) do nothing;
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.supplier_form_submit(text, jsonb) from public;
grant execute on function public.supplier_form_submit(text, jsonb) to anon, authenticated;

create or replace function public.supplier_get(p_id uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  s   public.suppliers;
  f   public.supplier_forms;
  pay boolean := public.ops_granted('suppliers.pay', 'view');
  work boolean := public.allowed('suppliers', 'work');
  cv  boolean := public.allowed('clients', 'view');
  a   jsonb;
  cl  jsonb;
  mt  jsonb;
begin
  if (public.ops_me()).id is null or not public.allowed('suppliers', 'view') then
    return jsonb_build_object('error', 'denied');
  end if;
  select * into s from public.suppliers x where x.id = p_id;
  if s.id is null then return jsonb_build_object('error', 'not-found'); end if;
  select * into f from public.supplier_forms x where x.supplier_id = p_id and x.voided_at is null
   order by x.created_at desc limit 1;
  a := f.answers;
  if a is not null and not pay then
    a := a - array['nric', 'payee_name', 'bank_name', 'bank_account', 'swift', 'bank_address'];
  end if;
  if s.client_id is not null then
    select case when cv and public.client_seen(c.id, 'view')
                then jsonb_build_object('id', c.id, 'slug', c.slug, 'code', c.client_code, 'name', c.name)
                else jsonb_build_object('hidden', true) end
      into cl from public.clients c where c.id = s.client_id;
  elsif work and cv and s.brn is not null then
    select jsonb_agg(jsonb_build_object('id', c.id, 'code', c.client_code, 'name', c.name) order by c.client_code, c.name)
      into mt from public.clients c
     where regexp_replace(coalesce(c.company_no, ''), '[^0-9]', '', 'g') = s.brn
       and public.client_seen(c.id, 'view');
  end if;
  return jsonb_build_object('ok', true, 'pay', pay, 'supplier', public.supplier_json(s, pay),
    'client', cl, 'match', mt,
    'form', case when f.id is null then null else jsonb_strip_nulls(jsonb_build_object(
      'id', f.id, 'purpose', f.purpose,
      'key', case when work and f.submitted_at is null and f.expires_at > now() then f.access_key end,
      'state', case when f.used_at is not null then 'used' when f.submitted_at is not null then 'submitted'
                    when f.expires_at <= now() then 'expired' else 'open' end,
      'created_at', f.created_at, 'expires_at', f.expires_at, 'submitted_at', f.submitted_at, 'used_at', f.used_at,
      'answers', case when f.submitted_at is not null then a end,
      'bank_changed', case when f.submitted_at is not null and f.used_at is null and s.bank_account is not null then
        (f.answers->>'payee_name') is distinct from s.payee_name or (f.answers->>'bank_name') is distinct from s.bank_name
        or (f.answers->>'bank_account') is distinct from s.bank_account end)) end);
end $$;
revoke all on function public.supplier_get(uuid) from public, anon;
grant execute on function public.supplier_get(uuid) to authenticated;

create or replace function public.supplier_save(p_id uuid, p_values jsonb, p_form uuid default null)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me    public.team_members := public.ops_me();
  s     public.suppliers;
  pay   boolean := public.ops_granted('suppliers.pay', 'work');
  v     jsonb;
  v_code text := upper(regexp_replace(coalesce(p_values->>'code', ''), '\s+', '', 'g'));
  moved text[] := '{}';
  k     text;
  word  constant jsonb := '{"code":"Supplier ID","name":"Name","kind":"Type","brn":"BRN","tin":"TIN","sst_no":"SST no.",
    "phone":"Office / mobile","address":"Billing address","contact_name":"Legal name","designation":"Designation",
    "email":"Email","mobile":"Mobile / WhatsApp","payment_term":"Payment term","currency":"Currency",
    "finance_email":"Finance email","nric":"NRIC","payee_name":"Payee name","bank_name":"Bank",
    "bank_account":"Account number","swift":"SWIFT code","bank_address":"Bank address"}';
  secret constant text[] := array['nric', 'payee_name', 'bank_name', 'bank_account', 'swift', 'bank_address'];
  was   jsonb;
  repend boolean := false;
begin
  if me.id is null or not public.allowed('suppliers', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into s from public.suppliers x where x.id = p_id for update;
  if s.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if v_code !~ '^[A-Z0-9]{2,12}$' then return jsonb_build_object('error', 'bad-code'); end if;
  if exists (select 1 from public.suppliers x where upper(x.code) = v_code and x.id <> p_id) then
    return jsonb_build_object('error', 'code-taken', 'name', (select x.name from public.suppliers x where upper(x.code) = v_code));
  end if;
  v := public.supplier_values_check(coalesce(p_values, '{}'::jsonb), pay);
  if v ? 'error' then return v; end if;
  v := v || jsonb_build_object('code', v_code);
  was := to_jsonb(s);
  for k in select jsonb_object_keys(v) loop
    if (was->>k) is distinct from (v->>k) then
      moved := moved || case when k = any (secret) then (word->>k)
        else (word->>k) || ': ' || coalesce(was->>k, 'not set') || ' → ' || coalesce(v->>k, 'not set') end;
    end if;
  end loop;
  /* A bank account changed on an approved supplier is approved again. */
  repend := pay and s.status = 'active' and s.bank_account is not null and (
    (v->>'payee_name') is distinct from s.payee_name or (v->>'bank_name') is distinct from s.bank_name
    or (v->>'bank_account') is distinct from s.bank_account);
  update public.suppliers x set
    code = v_code, name = v->>'name', kind = v->>'kind', brn = v->>'brn', tin = v->>'tin', sst_no = v->>'sst_no',
    phone = v->>'phone', address = v->>'address', contact_name = v->>'contact_name', designation = v->>'designation',
    email = v->>'email', mobile = v->>'mobile', payment_term = v->>'payment_term', currency = v->>'currency',
    finance_email = v->>'finance_email',
    nric = case when pay then v->>'nric' else x.nric end,
    payee_name = case when pay then v->>'payee_name' else x.payee_name end,
    bank_name = case when pay then v->>'bank_name' else x.bank_name end,
    bank_account = case when pay then v->>'bank_account' else x.bank_account end,
    swift = case when pay then v->>'swift' else x.swift end,
    bank_address = case when pay then v->>'bank_address' else x.bank_address end,
    status = case when repend then 'pending' else x.status end,
    updated_at = now()
   where x.id = p_id;
  if p_form is not null then
    update public.supplier_forms f set used_at = coalesce(f.used_at, now()), used_by = coalesce(f.used_by, me.id)
     where f.id = p_form and f.supplier_id = p_id and f.submitted_at is not null;
  end if;
  if array_length(moved, 1) is not null then
    insert into public.activity_log (actor, action, subject, detail)
    values (me.name, 'supplier.edited', v->>'name', v_code || ' · ' || array_to_string(moved, ' · ') ||
            case when p_form is not null then ' · from the details form' else '' end ||
            case when repend then ' · Active → Pending until approved again' else '' end);
  end if;
  return jsonb_build_object('ok', true, 'repending', repend, 'supplier',
    public.supplier_json((select x from public.suppliers x where x.id = p_id), public.ops_granted('suppliers.pay', 'view')));
end $$;
revoke all on function public.supplier_save(uuid, jsonb, uuid) from public, anon;
grant execute on function public.supplier_save(uuid, jsonb, uuid) to authenticated;

-- END OF A SUPPLIER'S DETAILS UPDATED BY LINK ------------------------------

-- ===========================================================================
-- WHATSAPP FEEDBACK SENT ONCE — a feedback request sent from New message is
-- Sent recently for the client's record too, and the other way round
-- (2026-10-20)
-- ===========================================================================
-- WHY (the wave 2 UX review, WA-1): a feedback request sent from the
-- WhatsApp section's New message is filed with purpose `message`, and one
-- sent from the client's ⋯ with purpose `feedback`. `wa_sent_recently`
-- matched the purpose first, so the same template to the same person went
-- twice within the hour without the question.
--
-- WHAT IT CHANGES
--   * `wa_sent_recently`: for a feedback request or a plain message, a
--     message of the same template to the same recipient within the hours
--     set is Sent recently whatever purpose it was filed under. Every other
--     match and every refusal is as before. `wa_send_begin` asks it, so the
--     send itself refuses `recent` the same way.
--
-- ORDER: the pages, then this file. An old page asks the same function with
-- the same arguments. Safe to run twice. Rollback: WHATSAPP SENDS NEVER
-- REPEATED's definition of `wa_sent_recently`.
-- ===========================================================================

create or replace function public.wa_sent_recently(p_to_kind text, p_to uuid, p_purpose text, p_ref uuid, p_template text default null)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  me      public.team_members := public.ops_me();
  v_prep  jsonb;
  v_hours numeric := coalesce(public.app_setting('wa_repeat_hours', (now() at time zone 'Asia/Kuala_Lumpur')::date), 24);
  v_ref   uuid;
  v_tpl   text := coalesce(nullif(btrim(p_template), ''), '');
  w       public.wa_outbox;
begin
  if me.id is null then return jsonb_build_object('error', 'denied'); end if;
  v_prep := public.wa_compose_prepare(p_to_kind, p_to, p_purpose, p_ref);
  if v_prep ? 'error' then return v_prep; end if;
  if v_hours <= 0 then return jsonb_build_object('ok', true, 'recent', false, 'hours', 0); end if;
  v_ref := case when p_purpose = 'feedback' then (v_prep ->> 'client_id')::uuid
                when p_purpose = 'message' then null else p_ref end;
  select * into w from public.wa_outbox x
   where x.to_kind = p_to_kind and x.to_id = p_to
     and x.state in ('queued', 'sending', 'sent', 'unknown')
     and x.created_at > now() - make_interval(hours => v_hours::int)
     and ((x.purpose = p_purpose
           and x.ref_id is not distinct from v_ref
           and (p_purpose <> 'message' or x.template = v_tpl))
       -- a feedback request or a plain message: the same template to the
       -- same person, whatever purpose it was filed under
       or (p_purpose in ('feedback', 'message') and v_tpl <> '' and x.template = v_tpl))
   order by x.created_at desc limit 1;
  if w.id is null then return jsonb_build_object('ok', true, 'recent', false, 'hours', v_hours); end if;
  return jsonb_build_object('ok', true, 'recent', true, 'hours', v_hours, 'at', w.created_at,
    'by', case when w.created_by = 'system' then null else w.created_by end, 'to', w.to_name, 'state', w.state);
end $$;
revoke all on function public.wa_sent_recently(text, uuid, text, uuid, text) from public, anon;
grant execute on function public.wa_sent_recently(text, uuid, text, uuid, text) to authenticated;

-- END OF WHATSAPP FEEDBACK SENT ONCE ----------------------------------------

-- ===========================================================================
-- TAX CODES PER LINE — each service line and quotation line carries its own
-- tax code, Bukku's, so an outstation fee or a reimbursement can go without
-- SST beside lines that carry it (2026-10-22)
-- ===========================================================================
-- WHY (the user, 2026-10-22: "make the 8% SST inside settings ... and then
-- choose to apply each under per item basis", after Bukku's own Items
-- table): a letter and a quotation took one SST rate for every line, or
-- none for an exempt client. A fee billed at cost, or a line the client
-- owes no SST on, could not sit on the same letter as the rest.
--
-- WHAT IT CHANGES
--   * `tax_codes` (RLS on, no policy, no grant): the codes the team bills
--     with, read from Bukku (`bukku-sync` `taxes`) or added by hand: code,
--     name, rate, active. `tax_codes_list()` (the team) reads them;
--     `tax_codes_save(p_rows, p_replace)` (Business settings) writes them,
--     a read from Bukku standing down a code Bukku no longer holds; filed
--     `team.changed` under Tax codes. A code is never deleted: a letter
--     issued on it keeps its name and rate in its snapshot.
--   * `client_services.tax_code`: none is the client's SST as before.
--   * `quote_totals`: a line may carry its own rate (`sst`); the SST is
--     worked a rate at a time, each rounded once, so a quotation on one
--     rate is priced exactly as before.
--   * `quote_adjust`: an edit may set a line's tax code (`tax`), its rate
--     read from `tax_codes` by `quote_tax_edits` (never the page's);
--     `quote_preview` and `quotation_make` ask it. `quotation_offer`
--     carries each line's code onto the client's service line.
--   * `issue_letter`: each line priced at its code's rate, else the
--     client's (refused `bad-tax` for a code not offered), the code and
--     rate kept on the snapshot; a letter on one rate is priced as before.
--   * `verify_letter`: a line whose tax code moved since the letter is
--     `changed-terms`, as a moved rate is.
--
-- ORDER: this file, then the pages. An old page sends no tax code and
-- every figure it works stays the database's. Safe to run twice. Rollback:
-- QUOTE TOTALS IN ONE PLACE's quote_totals, quote_adjust and issue_letter,
-- QUOTATION TAX DAY's quotation_offer and quote_preview, the last
-- quotation_make before this and SERVICE CONFIRM GUARD's verify_letter; the
-- table and the column may stay.
-- ===========================================================================

create table if not exists public.tax_codes (
  code       text primary key check (code ~ '^[A-Za-z0-9._ -]{1,30}$'),
  name       text not null default '' check (length(name) <= 80),
  rate       numeric(5,2) not null check (rate >= 0 and rate <= 100),
  active     boolean not null default true,
  bukku_id   text,
  updated_at timestamptz not null default now()
);
alter table public.tax_codes enable row level security;
revoke all on public.tax_codes from public, anon, authenticated;

alter table public.client_services add column if not exists tax_code text;
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'client_services_tax_code_check') then
    alter table public.client_services add constraint client_services_tax_code_check
      check (tax_code is null or tax_code ~ '^[A-Za-z0-9._ -]{1,30}$');
  end if;
end $$;

create or replace function public.tax_codes_list()
returns jsonb
language sql stable security definer set search_path = public as $$
  select case when not public.is_team() then jsonb_build_object('error', 'denied')
    else jsonb_build_object('ok', true, 'codes', coalesce((
      select jsonb_agg(jsonb_build_object('code', t.code, 'name', t.name, 'rate', t.rate, 'active', t.active,
                                          'bukku', t.bukku_id is not null)
                       order by t.active desc, t.rate desc, t.code)
        from public.tax_codes t), '[]'::jsonb)) end
$$;
revoke all on function public.tax_codes_list() from public, anon;
grant execute on function public.tax_codes_list() to authenticated;

create or replace function public.tax_codes_save(p_rows jsonb, p_replace boolean default false)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me public.team_members := public.ops_me();
  v_r jsonb; v_code text; v_name text; v_rate numeric; v_on boolean;
  v_was public.tax_codes;
  v_codes text[] := '{}';
  v_add int := 0; v_moved text[] := '{}'; v_off int := 0; v_i int := 0;
begin
  if v_me.id is null or not public.ops_granted('team.settings', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if jsonb_typeof(p_rows) is distinct from 'array' or jsonb_array_length(p_rows) > 100 then
    return jsonb_build_object('error', 'bad-row');
  end if;
  -- Every row checked before any is written.
  for v_r in select * from jsonb_array_elements(p_rows) loop
    v_i := v_i + 1;
    v_code := btrim(coalesce(v_r->>'code', ''));
    if v_code !~ '^[A-Za-z0-9._ -]{1,30}$' or length(btrim(coalesce(v_r->>'name', ''))) > 80
       or coalesce(v_r->>'rate', '') !~ '^[0-9]{1,3}(\.[0-9]{1,2})?$' or (v_r->>'rate')::numeric > 100
       or v_code = any(v_codes) then
      return jsonb_build_object('error', 'bad-row', 'row', v_i, 'code', v_code);
    end if;
    v_codes := v_codes || v_code;
  end loop;
  for v_r in select * from jsonb_array_elements(p_rows) loop
    v_code := btrim(v_r->>'code');
    v_name := btrim(coalesce(v_r->>'name', ''));
    v_rate := (v_r->>'rate')::numeric;
    v_on := coalesce((v_r->>'active')::boolean, true);
    select * into v_was from public.tax_codes t where t.code = v_code;
    if v_was.code is null then
      insert into public.tax_codes (code, name, rate, active, bukku_id)
      values (v_code, v_name, v_rate, v_on, nullif(btrim(coalesce(v_r->>'bukku_id', '')), ''));
      v_add := v_add + 1;
    elsif v_was.name is distinct from v_name or v_was.rate <> v_rate or v_was.active <> v_on then
      update public.tax_codes t
         set name = v_name, rate = v_rate, active = v_on,
             bukku_id = coalesce(nullif(btrim(coalesce(v_r->>'bukku_id', '')), ''), t.bukku_id), updated_at = now()
       where t.code = v_code;
      v_moved := v_moved || (v_code || case when v_was.rate <> v_rate then ': ' || trim(to_char(v_was.rate, 'FM990.99'), '.') ||
        '% → ' || trim(to_char(v_rate, 'FM990.99'), '.') || '%' else '' end ||
        case when v_was.active <> v_on then case when v_on then ': on' else ': off' end else '' end);
    end if;
  end loop;
  -- A read from Bukku: a code Bukku no longer holds is stood down, never removed.
  if coalesce(p_replace, false) then
    with d as (
      update public.tax_codes t set active = false, updated_at = now()
       where t.active and not (t.code = any(v_codes)) returning 1)
    select count(*) into v_off from d;
  end if;
  if v_add + coalesce(array_length(v_moved, 1), 0) + v_off > 0 then
    insert into public.activity_log (actor, action, subject, detail)
    values (v_me.name, 'team.changed', 'Tax codes',
            concat_ws(' · ', case when p_replace then 'Read from Bukku' end,
              case when v_add > 0 then v_add || ' added' end,
              case when array_length(v_moved, 1) > 0 then array_to_string(v_moved, ', ') end,
              case when v_off > 0 then v_off || ' no longer offered' end));
  end if;
  return public.tax_codes_list();
end $$;
revoke all on function public.tax_codes_save(jsonb, boolean) from public, anon;
grant execute on function public.tax_codes_save(jsonb, boolean) to authenticated;

create or replace function public.quote_totals(p_lines jsonb, p_term int, p_pct numeric, p_sst numeric)
returns jsonb
language sql immutable set search_path = public as $$
  with l as (
    select e->>'basis' = 'month' as m,
           coalesce((e->>'qty')::numeric, 0) * coalesce((e->>'rate')::numeric, 0) as v,
           greatest(1, coalesce((e->>'months')::int, p_term, 1)) as mo,
           coalesce((e->>'sst')::numeric, p_sst) as r
      from jsonb_array_elements(coalesce(p_lines, '[]'::jsonb)) e
  ), g as (
    -- A rate's own subtotals: one rate is the whole, as before tax codes.
    select r,
           coalesce(sum(v) filter (where m), 0) as gsub,
           coalesce(sum(round(v, 2) * mo) filter (where m), 0) as gspan,
           coalesce(sum(v) filter (where not m), 0) as gonce
      from l group by r
  ), gt as (
    select coalesce(sum(round((gsub + round(gsub * p_pct / 100, 2)) * r / 100, 2)), 0) as sst,
           coalesce(sum(round(gonce * r / 100, 2)), 0) as osst,
           coalesce(sum(round(gspan * (1 + p_pct / 100) * (1 + r / 100), 2)), 0) as span_incl
      from g
  ), s as (
    select coalesce(sum(v) filter (where m), 0) as sub,
           coalesce(sum(round(v, 2) * mo) filter (where m), 0) as span,
           coalesce(bool_and(mo = p_term) filter (where m), true) as even,
           coalesce(bool_or(m), false) as month,
           coalesce(sum(v) filter (where not m), 0) as once
      from l
  ), u as (
    select s.*, gt.sst, gt.osst, gt.span_incl, round(sub * p_pct / 100, 2) as off,
           round(span * (1 + p_pct / 100), 2) as span_excl
      from s, gt
  )
  select jsonb_build_object(
    'month', case when month then jsonb_build_object('subtotal', sub, 'term', off, 'excl', sub + off, 'sst', sst, 'incl', sub + off + sst) end,
    'once', case when once > 0 then jsonb_build_object('subtotal', once, 'sst', osst, 'incl', once + osst) end,
    'even', even, 'span_excl', case when month then span_excl else 0 end, 'span_incl', case when month then span_incl else 0 end,
    'commitment', case when not month then 0 when even then (sub + off + sst) * p_term else span_incl end + once + osst)
  from u
$$;
revoke all on function public.quote_totals(jsonb, integer, numeric, numeric) from public, anon, authenticated;

/* Each edit's tax code given its rate from tax_codes, a rate the page sent
   dropped first: the price is the database's. An unknown code gets none,
   and quote_adjust refuses it. */
create or replace function public.quote_tax_edits(p_edits jsonb)
returns jsonb
language plpgsql stable set search_path = public as $$
declare
  v_out jsonb := '{}'::jsonb; v_k text; v_e jsonb; v_r numeric;
begin
  if jsonb_typeof(p_edits) is distinct from 'object' then return p_edits; end if;
  for v_k, v_e in select key, value from jsonb_each(p_edits) loop
    if jsonb_typeof(v_e) = 'object' then
      v_e := v_e - 'tax_pct';
      if coalesce(v_e->>'tax', '') <> '' then
        v_r := null;
        select t.rate into v_r from public.tax_codes t where t.code = v_e->>'tax' and t.active;
        if v_r is not null then v_e := v_e || jsonb_build_object('tax_pct', v_r); end if;
      end if;
    end if;
    v_out := v_out || jsonb_build_object(v_k, v_e);
  end loop;
  return v_out;
end $$;
revoke all on function public.quote_tax_edits(jsonb) from public, anon, authenticated;

create or replace function public.quote_adjust(p_price jsonb, p_edits jsonb)
returns jsonb
language plpgsql immutable set search_path = public as $$
declare
  v_t jsonb := coalesce(p_price->'totals', '{}'::jsonb);
  v_term int := coalesce((v_t->>'term')::int, 1);
  v_lines jsonb := '[]'::jsonb;
  v_l jsonb; v_e jsonb; v_k text; v_n int := 0; v_hit boolean;
  v_qty numeric; v_rate numeric; v_mo int;
  v_pct numeric := coalesce((v_t->>'term_pct')::numeric, 0);
  v_sst_pct numeric := coalesce((v_t->>'sst_pct')::numeric, 0);
  v_tot jsonb;
begin
  if p_price ? 'error' or jsonb_typeof(p_price->'lines') is distinct from 'array' then return p_price; end if;
  if p_edits is not null and jsonb_typeof(p_edits) not in ('object', 'null') then
    return jsonb_build_object('error', 'bad-edit');
  end if;
  for v_l in select * from jsonb_array_elements(p_price->'lines') loop
    v_k := (v_l->>'kind') || '|' || coalesce(v_l->>'slug', '') || '|' || (v_l->>'label');
    v_qty := (v_l->>'qty')::numeric; v_rate := (v_l->>'rate')::numeric;
    v_mo := case when v_l->>'basis' = 'month' then v_term else 1 end;
    v_hit := false;
    if jsonb_typeof(p_edits) = 'object' and jsonb_typeof(p_edits->v_k) = 'object' then
      v_e := p_edits->v_k;
      if (v_e ? 'qty' and coalesce(v_e->>'qty', '') !~ '^[0-9]{1,4}$')
         or (v_e ? 'rate' and coalesce(v_e->>'rate', '') !~ '^[0-9]{1,7}(\.[0-9]{1,2})?$')
         or (v_e ? 'months' and (v_l->>'basis' <> 'month' or coalesce(v_e->>'months', '') !~ '^[0-9]{1,2}$'))
         or (v_e ? 'tax' and coalesce(v_e->>'tax', '') !~ '^([A-Za-z0-9._ -]{1,30})?$') then
        return jsonb_build_object('error', 'bad-edit', 'line', v_l->>'label');
      end if;
      if (v_e ? 'qty' and (v_e->>'qty')::int < 1) or (v_e ? 'months' and (v_e->>'months')::int not between 1 and 36) then
        return jsonb_build_object('error', 'bad-edit', 'line', v_l->>'label');
      end if;
      if v_e ? 'qty' and (v_e->>'qty')::numeric <> v_qty then v_qty := (v_e->>'qty')::numeric; v_hit := true; end if;
      if v_e ? 'rate' and (v_e->>'rate')::numeric <> v_rate then
        v_l := v_l || jsonb_build_object('list_rate', v_rate);
        v_rate := (v_e->>'rate')::numeric; v_hit := true;
      end if;
      if v_e ? 'months' and (v_e->>'months')::int <> v_mo then v_mo := (v_e->>'months')::int; v_hit := true; end if;
      /* A line's own tax code (2026-10-22), its rate read from tax_codes by
         quote_tax_edits; an empty one keeps the quotation's SST. */
      if coalesce(v_e->>'tax', '') <> '' then
        if jsonb_typeof(v_e->'tax_pct') is distinct from 'number' then
          return jsonb_build_object('error', 'bad-tax', 'line', v_l->>'label');
        end if;
        v_l := v_l || jsonb_build_object('tax_code', v_e->>'tax', 'sst', (v_e->>'tax_pct')::numeric);
        v_hit := true;
      end if;
    end if;
    if v_hit then v_n := v_n + 1; end if;
    v_l := v_l || jsonb_build_object('key', v_k, 'qty', v_qty, 'rate', v_rate, 'months', v_mo,
                                     'amount', round(v_qty * v_rate, 2));
    v_lines := v_lines || jsonb_build_array(v_l);
  end loop;
  if v_n = 0 then
    return p_price || jsonb_build_object('lines', v_lines, 'adjusted', 0);
  end if;
  -- The figures, from the one calculation every quotation and letter shares.
  v_tot := public.quote_totals(v_lines, v_term, v_pct, v_sst_pct);
  return p_price || jsonb_build_object('lines', v_lines, 'adjusted', v_n,
    'totals', v_t || jsonb_build_object('month', v_tot->'month', 'once', v_tot->'once', 'commitment', v_tot->'commitment'));
end $$;
revoke all on function public.quote_adjust(jsonb, jsonb) from public, anon, authenticated;

create or replace function public.quote_preview(p_sel jsonb)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_card jsonb := public.quote_card();
  v_cl uuid;
  v_fx numeric;
begin
  if not public.is_team() or not public.allowed('clients.services', 'view') then
    return jsonb_build_object('error', 'denied');
  end if;
  if v_card is null then return jsonb_build_object('error', 'no-card'); end if;
  if coalesce(p_sel->>'client', '') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     and public.client_scope_ok('client', (p_sel->>'client')::uuid, 'view') then
    v_cl := (p_sel->>'client')::uuid;
  end if;
  v_fx := public.quote_fx(v_cl);
  if v_fx = 0 then return jsonb_build_object('error', 'no-fx'); end if;
  return public.quote_fx_out(public.quote_adjust(public.quote_price(public.quote_fx_snap(public.quote_tax_snap(v_card->'snapshot', v_cl), v_fx),
           p_sel - 'client'), public.quote_tax_edits(p_sel->'edits')), v_fx) || jsonb_build_object('version', v_card->>'version');
end $$;
revoke all on function public.quote_preview(jsonb) from public, anon;
grant execute on function public.quote_preview(jsonb) to authenticated;

create or replace function public.quotation_make(p_client uuid, p_sel jsonb, p_idem text, p_source text,
                                                 p_by text, p_contact jsonb)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  v_c public.clients;
  v_card jsonb := public.quote_card();
  v_p jsonb;
  v_q public.quotations;
  v_now timestamptz := now();
  v_days int;
  v_fx numeric;
  v_sel jsonb := case when jsonb_typeof(p_sel) is distinct from 'object' then p_sel
                      when p_source = 'console' then p_sel - 'client'
                      else p_sel - 'edits' - 'client' end;
begin
  if p_idem is not null then
    select * into v_q from public.quotations q where q.idem = p_idem;
    if v_q.id is not null then return jsonb_build_object('ok', true, 'id', v_q.id, 'ref', v_q.ref, 'again', true); end if;
  end if;
  select * into v_c from public.clients where id = p_client;
  if v_c.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if v_card is null then return jsonb_build_object('error', 'no-card'); end if;
  v_fx := public.quote_fx(v_c.id);
  if v_fx = 0 then return jsonb_build_object('error', 'no-fx'); end if;
  v_p := public.quote_fx_out(public.quote_adjust(public.quote_price(public.quote_fx_snap(public.quote_tax_snap(v_card->'snapshot', v_c.id), v_fx),
           v_sel), public.quote_tax_edits(v_sel->'edits')), v_fx);
  if v_p ? 'error' then return v_p; end if;
  v_days := coalesce(public.app_setting('quote_valid_days', (v_now at time zone 'Asia/Kuala_Lumpur')::date), 30)::int;
  begin
  insert into public.quotations (ref, client_id, brand, version, version_id, selection, lines, totals, source,
                                 issued_at, valid_until, made_by, contact, idem, access_key)
  values (public.quote_ref(v_c.name, v_now), v_c.id, v_c.name, v_card->>'version', (v_card->>'id')::uuid, v_sel,
          v_p->'lines', v_p->'totals' || jsonb_build_object('on_request', v_p->'on_request'), p_source,
          v_now, (v_now at time zone 'Asia/Kuala_Lumpur')::date + v_days, p_by, p_contact, p_idem,
          case when p_source = 'website' then public.new_link_key() end)
  returning * into v_q;
  -- Two presses at once with one key: the second answers the first's.
  exception when unique_violation then
    select * into v_q from public.quotations q where q.idem = p_idem;
    if p_idem is null or v_q.id is null then raise; end if;
    return jsonb_build_object('ok', true, 'id', v_q.id, 'ref', v_q.ref, 'again', true);
  end;
  insert into public.activity_log (actor, action, subject, detail)
  values (coalesce(p_by, 'Website'), 'client.quotation', v_c.name,
          v_q.ref || ' sent · ' || coalesce('Monthly incl. SST ' || case when v_fx is null then 'RM ' else 'S$ ' end ||
            to_char((v_q.totals->'month'->>'incl')::numeric, 'FM999,999,990.00'), 'one-off') ||
          ' · rate card v.' || v_q.version ||
          case coalesce((v_p->>'adjusted')::int, 0) when 0 then '' when 1 then ' · 1 line changed'
               else ' · ' || (v_p->>'adjusted') || ' lines changed' end);
  return jsonb_build_object('ok', true, 'id', v_q.id, 'ref', v_q.ref, 'key', v_q.access_key);
end $$;
revoke all on function public.quotation_make(uuid, jsonb, text, text, text, jsonb) from public, anon, authenticated;

create or replace function public.quotation_offer(p_id uuid)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  v_q public.quotations;
  v_l jsonb;
  v_ids uuid[] := '{}';
  v_id uuid;
begin
  if me.id is null or not public.allowed('clients.services', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into v_q from public.quotations where id = p_id for update;
  if v_q.id is null or v_q.removed_at is not null or not public.client_scope_ok('client', v_q.client_id, 'work') then
    return jsonb_build_object('error', 'not-found');
  end if;
  if v_q.status = 'not_proceeding' then return jsonb_build_object('error', 'not-proceeding'); end if;
  select coalesce(array_agg(s.id order by s.created_at), '{}') into v_ids
    from public.client_services s where s.quotation_id = v_q.id and s.archived_at is null;
  if array_length(v_ids, 1) is not null then return jsonb_build_object('ok', true, 'ids', to_jsonb(v_ids), 'again', true); end if;
  if v_q.valid_until < (now() at time zone 'Asia/Kuala_Lumpur')::date then return jsonb_build_object('error', 'expired'); end if;
  for v_l in select * from jsonb_array_elements(v_q.lines) loop
    insert into public.client_services (client_id, service_slug, label, qty, rate, unit, state, note,
                                        tenure, term_adjust, term_pct, detail, quotation_id, tax_code)
    values (v_q.client_id,
            case when exists (select 1 from public.services s where s.slug = v_l->>'slug') then v_l->>'slug' end,
            v_l->>'label', (v_l->>'qty')::numeric, (v_l->>'rate')::numeric,
            case when v_l->>'basis' = 'month' then 'Per month' else 'One-off' end, 'quoted',
            'Quotation ' || v_q.ref,
            case when v_l->>'basis' = 'month' then coalesce((v_l->>'months')::int, (v_q.totals->>'term')::int) else 1 end,
            v_l->>'basis' = 'month', case when v_l->>'basis' = 'month' then (v_q.totals->>'term_pct')::numeric else 0 end,
            nullif(array_to_string(array(select jsonb_array_elements_text(coalesce(v_l->'detail', '[]'::jsonb))), E'\n'), ''),
            v_q.id, nullif(v_l->>'tax_code', ''))
    returning id into v_id;
    v_ids := v_ids || v_id;
  end loop;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'client.quotation', v_q.brand, v_q.ref || ' · ' || array_length(v_ids, 1) || ' lines To quote for the Letter of Offer');
  return jsonb_build_object('ok', true, 'ids', to_jsonb(v_ids));
end $$;
revoke all on function public.quotation_offer(uuid) from public, anon;
grant execute on function public.quotation_offer(uuid) to authenticated;

create or replace function public.issue_letter(
  p_client    uuid,
  p_services  uuid[],
  p_idem      text,
  p_subtotal  numeric,
  p_tax       numeric,
  p_total     numeric,
  p_deal      jsonb   default '{}'::jsonb,
  p_replaces  uuid    default null,
  p_renewal   boolean default false,
  /* A reference somebody typed. Blank is the ordinary case and the counter
     below makes the number; where one is typed it is checked against every
     document that stands and the counter is not advanced, so filling a gap
     by hand never costs the next letter its place in the sequence. */
  p_serial    text    default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  who    text := lower(auth.jwt() ->> 'email');
  cl     public.clients%rowtype;
  ct     public.client_contacts%rowtype;
  me     public.team_members%rowtype;
  v_ym   text;
  v_seq  int;
  v_try  int;
  v_no   text;
  v_id   uuid;
  v_lines jsonb;
  v_n    int;
  v_bad  int;
  v_old  public.client_documents%rowtype;
  v_term int;
  v_each numeric;
  v_etax numeric;
  v_once numeric;
  v_otax numeric;
  v_sub  numeric;
  v_tax  numeric;
  v_tot  numeric;
  v_pct  numeric;
  v_qid  uuid;
  v_q    public.quotations%rowtype;
  v_tp   numeric;
  v_tpn  int;
  v_tadj boolean;
  v_qterm int;
  v_msub numeric;
  v_span numeric;
  v_even boolean;
  v_qt   jsonb;
  v_month boolean;
begin
  if not public.allowed('clients.documents') then
    return jsonb_build_object('error', 'not-allowed');
  end if;
  if p_client is null or p_services is null or array_length(p_services, 1) is null then
    return jsonb_build_object('error', 'no-lines');
  end if;

  select * into cl from public.clients where id = p_client;
  if cl.id is null then return jsonb_build_object('error', 'no-client'); end if;

  -- The Client ID is what the serial is built from, so there is no letter
  -- without one. Staff enter it on the record; nothing invents it. A typed
  -- reference needs no code, because nothing is being built.
  v_no := nullif(btrim(coalesce(p_serial, '')), '');
  if v_no is null and coalesce(btrim(cl.client_code), '') = '' then
    return jsonb_build_object('error', 'no-client-code');
  end if;

  -- The same submission, pressed twice, is one letter. Answered before any
  -- number is reserved, so a double click cannot spend a serial either.
  if coalesce(btrim(p_idem), '') <> '' then
    select * into v_old from public.client_documents
      where client_id = p_client and idem_key = btrim(p_idem) limit 1;
    if v_old.id is not null then
      return jsonb_build_object('ok', true, 'repeat', true, 'id', v_old.id, 'number', v_old.number);
    end if;
  end if;

  -- A typed reference is checked before anything is written: the same shape
  -- the Register accepts, and refused where a document still holds it.
  if v_no is not null then
    if v_no !~ '^[A-Za-z0-9/._-]{3,40}$' then
      return jsonb_build_object('error', 'serial-shape');
    end if;
    if public.serial_taken(v_no) then
      return jsonb_build_object('error', 'serial-taken');
    end if;
  end if;

  -- Every id must be this client's own live line, and in a state this letter
  -- may carry: To quote always, Confirmed only on a deliberate renewal.
  select count(*) into v_bad from unnest(p_services) s(id)
    left join public.client_services cs
      on cs.id = s.id and cs.client_id = p_client and cs.archived_at is null
    where cs.id is null
       or (cs.state = 'confirmed' and not p_renewal)
       or cs.state not in ('quoted', 'confirmed');
  if v_bad > 0 then return jsonb_build_object('error', 'bad-lines'); end if;

  -- A line already on a live letter is not offered again by accident. The way
  -- through is to void that letter, or to name it as the one being replaced.
  select count(*) into v_bad
    from public.client_document_services m
    join public.client_documents d on d.id = m.document_id
   where m.service_id = any(p_services)
     and d.voided_at is null
     and d.superseded_by is null
     and d.verified_at is null
     and (p_replaces is null or d.id <> p_replaces);
  if v_bad > 0 then return jsonb_build_object('error', 'already-quoted'); end if;

  if p_replaces is not null then
    select * into v_old from public.client_documents
      where id = p_replaces and client_id = p_client;
    if v_old.id is null then return jsonb_build_object('error', 'no-replaces'); end if;
    if v_old.verified_at is not null then return jsonb_build_object('error', 'replaces-verified'); end if;
  end if;

  select * into ct from public.client_contacts
    where client_id = p_client and archived_at is null
    order by (id = cl.bill_contact_id) desc, is_primary desc, name limit 1;
  select * into me from public.team_members where lower(email) = who and active limit 1;

  -- A letter is signed by a person. issued_by is this row's name, so a team
  -- row named "Superadmin" printed that word under ADSPACE PLT on a client's
  -- letterhead. Refuse rather than draw a permission as a signatory.
  if not public.issuer_name_ok(me.name) then
    return jsonb_build_object('error', 'issuer-name', 'name', coalesce(me.name, ''));
  end if;

  -- The snapshot is built from the stored rows, never from what the browser
  -- sent: the words on a letter are the words the record held at that moment.
  select jsonb_agg(jsonb_build_object(
           'label', cs.label, 'unit', coalesce(cs.unit, ''), 'note', coalesce(cs.note, ''),
           'detail', coalesce(cs.detail, ''), 'state', cs.state,
           'qty', cs.qty, 'rate', cs.rate,
           'tenure', greatest(1, coalesce(cs.tenure, 1)),
           'start_on', coalesce(cs.start_on, ''),
           -- The line's own answer to whether its term prices it. Written into
           -- the snapshot because the letter is redrawn from it, and a letter
           -- must print the same figure every time it is drawn. A snapshot
           -- taken before this key existed carries none, which money.js reads
           -- as on, so those letters redraw as they were issued.
           'term_adjust', coalesce(cs.term_adjust, false),
           -- And the percentage that tick applies, so a later rate card can
           -- never move a figure this letter printed. Null on a line quoted
           -- before the column existed, which money.js reads as that card.
           'term_pct', cs.term_pct,
           'tax', cl.sst_applies is not false,
           -- The line's own tax code and its rate as issued (2026-10-22);
           -- none is the client's SST, as before.
           'tax_code', cs.tax_code,
           'tax_pct', (select t.rate from public.tax_codes t where t.code = cs.tax_code),
           'service_id', cs.id)
           order by cs.created_at)
    into v_lines
    from public.client_services cs
   where cs.id = any(p_services);
  if v_lines is null then return jsonb_build_object('error', 'no-lines'); end if;
  /* A line's tax code is one the team holds and offers (2026-10-22). */
  if exists (select 1 from public.client_services cs
              where cs.id = any(p_services) and cs.tax_code is not null
                and not exists (select 1 from public.tax_codes t where t.code = cs.tax_code and t.active)) then
    return jsonb_build_object('error', 'bad-tax');
  end if;

  /* The price is the database's (audit S4, 2026-10-10), worked as the
     letter draws it (js/documents.js priceOf, js/money.js rateFor): each
     line's rate with its term on it, rounded to the cent. Where every line
     of more than a month shares one term, those lines are priced by the
     month and times the term, and a line of one month is a one-off item
     with its own SST (2026-10-15: a one-off item beside them no longer
     turns the letter into one whole total); otherwise every line is its
     whole amount. SST at the rate in force today unless the client is
     exempt. The page's figures are kept only where they agree to the sen,
     so a line changed since the sheet opened, or a figure typed in a
     browser, is refused (`stale`) and the sheet reads the lines again. */
  select case when count(distinct greatest(1, coalesce(cs.tenure, 1)))
                     filter (where greatest(1, coalesce(cs.tenure, 1)) > 1) = 1
              then max(greatest(1, coalesce(cs.tenure, 1))) else 0 end
    into v_term
    from public.client_services cs where cs.id = any(p_services);
  /* A letter whose every line came from one quotation is priced as that
     quotation was (audit F, 2026-10-17), exactly as `quote_price` and
     `quote_adjust` total it (2026-10-17, the review's finding 7): a line
     the quotation bills by the month (`quotation_offer` ticks its term) is
     a monthly line whatever months Build quote gave it, its percentage
     taken once on their subtotal; a line with no term is one-off; SST at
     the quotation's rate. The page's figures are held to the same price
     (js/documents.js priceOf). */
  select case when count(*) filter (where cs.quotation_id is null) = 0
                   and count(distinct cs.quotation_id) = 1 then min(cs.quotation_id::text)::uuid end,
         count(distinct coalesce(cs.term_pct, 0)) filter (where coalesce(cs.term_adjust, false)),
         coalesce(bool_and(greatest(1, coalesce(cs.tenure, 1)) = 1) filter (where not coalesce(cs.term_adjust, false)), true),
         coalesce(max(cs.term_pct) filter (where coalesce(cs.term_adjust, false)), 0)
    into v_qid, v_tpn, v_tadj, v_tp
    from public.client_services cs where cs.id = any(p_services);
  /* Only while the quotation still stands (2026-10-17, the review's
     finding 2): unexpired by Malaysia's day and not removed. A renewal, or a
     letter replacing one after the quotation lapsed, is priced on today's
     rates, as any other letter. */
  if v_qid is not null and coalesce(v_tpn, 0) <= 1 and v_tadj and not coalesce(p_renewal, false) then
    select * into v_q from public.quotations q
     where q.id = v_qid and q.removed_at is null
       and q.valid_until >= (timezone('Asia/Kuala_Lumpur', now()))::date;
  end if;
  if v_q.id is not null then
    /* As quote_adjust totals it: the monthly lines' subtotal of quantity ×
       rate, the percentage once on it; where every one runs the quotation's
       term, a month's excl. SST, its SST rounded once, times the term; where
       Build quote gave a line months of its own, the whole span (each line's
       amount × its months) with the percentage and SST taken once on it.
       One-off lines and their SST apart. */
    v_qterm := greatest(1, coalesce((v_q.totals->>'term')::int, 1));
    v_pct := case when cl.sst_applies is false then 0
                  else coalesce((v_q.totals->>'sst_pct')::numeric, 0) end;
    /* The lines as the quotation reads them (a line with its term ticked is
       monthly, on its own months), totalled by the one calculation every
       quotation shares (2026-10-18). */
    v_qt := public.quote_totals(
      (select coalesce(jsonb_agg(jsonb_build_object(
                'basis', case when coalesce(cs.term_adjust, false) then 'month' else 'once' end,
                'qty', coalesce(cs.qty, 0), 'rate', coalesce(cs.rate, 0),
                'months', greatest(1, coalesce(cs.tenure, 1)),
                'sst', (select t.rate from public.tax_codes t where t.code = cs.tax_code))), '[]'::jsonb)
         from public.client_services cs where cs.id = any(p_services)),
      v_qterm, v_tp, v_pct);
    v_month := jsonb_typeof(v_qt->'month') = 'object';
    v_once := coalesce((v_qt->'once'->>'subtotal')::numeric, 0);
    v_otax := coalesce((v_qt->'once'->>'sst')::numeric, 0);
    if not v_month then
      v_sub := round(v_once, 2);
      v_tax := v_otax;
    elsif (v_qt->>'even')::boolean then
      v_each := (v_qt->'month'->>'excl')::numeric;
      v_etax := (v_qt->'month'->>'sst')::numeric;
      v_sub := round(v_each * v_qterm + v_once, 2);
      v_tax := v_etax * v_qterm + v_otax;
    else
      v_sub := (v_qt->>'span_excl')::numeric + round(v_once, 2);
      v_tax := (v_qt->>'span_incl')::numeric + round(v_once, 2) + v_otax - v_sub;
    end if;
    v_tot := v_sub + v_tax;
    /* The letter keeps what it was priced on, so a redraw prints the same:
       the quotation, its SST and its term (a snapshot with no `quote_term`
       was priced before this, and redraws as it was). */
    select jsonb_agg(l.e || jsonb_build_object('quotation_id', v_qid, 'quote_sst', v_pct, 'quote_term', v_qterm) order by l.n)
      into v_lines from jsonb_array_elements(v_lines) with ordinality l(e, n);
  else
    v_pct := case when cl.sst_applies is false then 0
                  else coalesce(public.app_setting('sst_pct', (timezone('Asia/Kuala_Lumpur', now()))::date), 0) end;
    /* Each line at its own SST rate (2026-10-22): its tax code's, else the
       client's. The SST is worked a rate at a time, rounded once each, so
       a letter on one rate prices as it always did. */
    with x as (
      select greatest(1, coalesce(cs.tenure, 1)) as n,
             coalesce(cs.qty, 0) *
             round(coalesce(cs.rate, 0) *
               case when cs.term_adjust is false then 1
                    when cs.term_pct is not null then 1 + cs.term_pct / 100
                    else case greatest(1, coalesce(cs.tenure, 1))
                           when 3 then 1 / 0.9 when 12 then 0.95 when 24 then 0.9 else 1 end
               end, 2) as v,
             coalesce((select t.rate from public.tax_codes t where t.code = cs.tax_code), v_pct) as r
        from public.client_services cs where cs.id = any(p_services)
    ), y as (
      select r,
             coalesce(sum(v) filter (where v_term > 0 and n = v_term), 0) as e,
             coalesce(sum(v * n) filter (where v_term = 0 or n <> v_term), 0) as o
        from x group by r
    )
    select coalesce(sum(e), 0), coalesce(sum(o), 0),
           coalesce(sum(round(e * r) / 100), 0), coalesce(sum(round(o * r) / 100), 0)
      into v_each, v_once, v_etax, v_otax
      from y;
    v_sub := round(v_each * greatest(v_term, 1), 2) + round(v_once, 2);
    v_tax := round(v_etax * greatest(v_term, 1), 2) + v_otax;
    v_tot := round(round(v_each + v_etax, 2) * greatest(v_term, 1), 2) + round(v_once + v_otax, 2);
  end if;
  if abs(coalesce(p_subtotal, -1) - v_sub) > 0.01 or abs(coalesce(p_tax, -1) - v_tax) > 0.01
     or abs(coalesce(p_total, -1) - v_tot) > 0.01 then
    return jsonb_build_object('error', 'stale', 'subtotal', v_sub, 'tax', v_tax, 'total', v_tot);
  end if;

  -- A typed reference spends no sequence number: the counter is the office's
  -- record of how many letters it has issued this month, and a person filling
  -- a gap by hand has not issued one more.
  if v_no is null then
    -- The month is Malaysian, because the office that numbers the letter is.
    v_ym := to_char(timezone('Asia/Kuala_Lumpur', now()), 'YYMM');

    -- The counter still advances on every automatic issue, and the upsert's
    -- row lock is what makes the scan below safe: a second issuer blocks here
    -- until the first has committed its letter, so the two never read the same
    -- gap as free. What the counter gives is a bound to scan within, not the
    -- number itself.
    insert into public.client_document_seq (client_id, ym, next_val)
         values (p_client, v_ym, 2)
    on conflict (client_id, ym)
      do update set next_val = public.client_document_seq.next_val + 1
      returning next_val - 1 into v_seq;

    -- The lowest free slot, not the counter's own value. A deleted letter
    -- releases its reference (serial_taken stopped counting deletions on
    -- 2026-09-20), and without this the automatic path still counted upward
    -- past the gap: a client whose first two letters were issued in testing
    -- and deleted started at 03 for ever. The counter is at least the number
    -- of letters issued this month, so a free slot exists at or below it
    -- unless somebody has typed references over the same range by hand; the
    -- cap covers that and refuses rather than looping.
    --
    -- Two digits is the floor, not the ceiling: the hundredth letter of a month
    -- widens to three rather than wrapping. Not lpad(): Postgres pads AND
    -- truncates to the width it is given, so lpad('100', 2, '0') is '10' and the
    -- hundredth letter would collide with the tenth.
    v_try := 1;
    loop
      v_no := 'AQL/' || cl.client_code || '/' || v_ym ||
              case when v_try < 100 then lpad(v_try::text, 2, '0') else v_try::text end;
      exit when not public.serial_taken(v_no);
      v_try := v_try + 1;
      if v_try > greatest(v_seq, 1) + 200 then
        return jsonb_build_object('error', 'no-serial');
      end if;
    end loop;
  end if;

  insert into public.client_documents
    (client_id, kind, number, issued_at, market, subtotal, tax, total,
     bill_to, lines, issued_by, client_code, idem_key)
  values
    (p_client, 'offer', v_no, (timezone('Asia/Kuala_Lumpur', now()))::date,
     coalesce(cl.market, 'MY'),
     round(coalesce(p_subtotal, 0), 2), round(coalesce(p_tax, 0), 2), round(coalesce(p_total, 0), 2),
     jsonb_build_object(
       'name', coalesce(cl.name, ''), 'legal_name', coalesce(cl.legal_name, ''),
       'address', coalesce(cl.billing_address, ''), 'regno', coalesce(cl.company_no, ''),
       'regno_old', coalesce(cl.company_no_old, ''), 'tin', coalesce(cl.tin, ''),
       'sst_no', coalesce(cl.sst_no, ''), 'sst_applies', cl.sst_applies is not false,
       'contact', coalesce(ct.name, ''), 'contact_role', coalesce(ct.role, ''),
       'contact_salutation', coalesce(ct.salutation, ''),
       'phone', coalesce(ct.phone, ''), 'email', coalesce(ct.email, ''),
       'finance_email', coalesce(cl.finance_email, ''),
       'client_code', cl.client_code,
       'owner', coalesce(p_deal ->> 'owner', ''), 'source', coalesce(p_deal ->> 'source', ''),
       'industry', coalesce(p_deal ->> 'industry', ''), 'stage', coalesce(p_deal ->> 'stage', ''),
       'enquiry', coalesce(p_deal ->> 'enquiry', '')),
     v_lines, coalesce(me.name, who), cl.client_code, nullif(btrim(p_idem), ''))
  returning id into v_id;

  insert into public.client_document_services (document_id, service_id)
    select v_id, s.id from unnest(p_services) s(id)
    on conflict do nothing;

  if p_replaces is not null then
    update public.client_documents set superseded_by = v_id where id = p_replaces;
    insert into public.activity_log (actor, action, subject, detail)
    values (who, 'document.superseded', cl.name, v_old.number || ' replaced by ' || v_no);
  end if;

  select count(*) into v_n from public.client_document_services where document_id = v_id;
  insert into public.activity_log (actor, action, subject, detail)
  values (who, 'document.issued', cl.name, v_no || ' · ' || v_n || ' line' || case when v_n = 1 then '' else 's' end);

  return jsonb_build_object('ok', true, 'id', v_id, 'number', v_no);
exception
  when unique_violation then
    -- Two presses that raced past the idempotency read: the loser reads the
    -- winner's letter back rather than making a second one.
    if coalesce(btrim(p_idem), '') <> '' then
      select * into v_old from public.client_documents
        where client_id = p_client and idem_key = btrim(p_idem) limit 1;
      if v_old.id is not null then
        return jsonb_build_object('ok', true, 'repeat', true, 'id', v_old.id, 'number', v_old.number);
      end if;
    end if;
    -- A typed reference two people sent at once: the loser is told the
    -- reference is spent rather than that "two letters were issued at once",
    -- which names a cause they cannot act on.
    if nullif(btrim(coalesce(p_serial, '')), '') is not null then
      return jsonb_build_object('error', 'serial-taken');
    end if;
    return jsonb_build_object('error', 'clash');
end $$;


grant execute on function public.issue_letter(uuid, uuid[], text, numeric, numeric, numeric, jsonb, uuid, boolean, text) to authenticated;

create or replace function public.verify_letter(p_doc uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  who   text := lower(auth.jwt() ->> 'email');
  d     public.client_documents%rowtype;
  cl    public.clients%rowtype;
  me    public.team_members%rowtype;
  v_map int;
  v_n   int;
begin
  if not public.allowed('clients.documents') then return jsonb_build_object('error', 'not-allowed'); end if;
  select * into d from public.client_documents where id = p_doc;
  if d.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if d.voided_at is not null then return jsonb_build_object('error', 'voided'); end if;
  if d.superseded_by is not null then return jsonb_build_object('error', 'superseded'); end if;
  if d.signed_at is null then return jsonb_build_object('error', 'not-signed'); end if;

  -- Verifying twice is verifying once.
  if d.verified_at is not null then
    return jsonb_build_object('ok', true, 'repeat', true, 'confirmed', 0);
  end if;

  -- A letter issued before this change has no mappings, so there is nothing
  -- to confirm and no guess is made. It stays history.
  select count(*) into v_map from public.client_document_services where document_id = p_doc;
  if v_map = 0 or v_map <> coalesce(jsonb_array_length(d.lines), -1) then
    return jsonb_build_object('error', 'no-mapping');
  end if;

  /* What the client signed is the letter's snapshot. A line removed since,
     or one whose quantity, rate, term, adjustment or tax code moved since, is not
     what was signed, so nothing is confirmed (audit S4, 2026-10-10): the
     letter is reissued, or the line put back as it was. */
  if exists (select 1 from public.client_document_services m
               join public.client_services cs on cs.id = m.service_id
              where m.document_id = p_doc and cs.archived_at is not null) then
    return jsonb_build_object('error', 'archived-line');
  end if;
  if exists (select 1 from jsonb_array_elements(d.lines) l
               join public.client_services cs on cs.id = (l ->> 'service_id')::uuid
              where l ? 'service_id'
                and ((l ->> 'qty')::numeric is distinct from cs.qty
                  or (l ->> 'rate')::numeric is distinct from cs.rate
                  or (l ->> 'tenure')::int is distinct from greatest(1, coalesce(cs.tenure, 1))
                  or (l ? 'term_adjust' and (l ->> 'term_adjust')::boolean is distinct from coalesce(cs.term_adjust, false))
                  or (l ? 'term_pct' and (l ->> 'term_pct')::numeric is distinct from cs.term_pct)
                  or (l ? 'tax_code' and nullif(l ->> 'tax_code', '') is distinct from cs.tax_code))) then
    return jsonb_build_object('error', 'changed-terms');
  end if;

  update public.client_services cs
     set state = 'confirmed'
    from public.client_document_services m
   where m.document_id = p_doc and cs.id = m.service_id
     and cs.archived_at is null and cs.state <> 'confirmed';
  get diagnostics v_n = row_count;

  select * into me from public.team_members where lower(email) = who and active limit 1;
  update public.client_documents
     set verified_at = now(), verified_by = coalesce(me.name, who)
   where id = p_doc;

  select * into cl from public.clients where id = d.client_id;
  insert into public.activity_log (actor, action, subject, detail)
  values (who, 'document.verified', cl.name,
          d.number || ' · ' || v_n || ' line' || case when v_n = 1 then '' else 's' end || ' confirmed');
  return jsonb_build_object('ok', true, 'confirmed', v_n);
end $$;


grant execute on function public.verify_letter(uuid) to authenticated;

-- END OF TAX CODES PER LINE ------------------------------------------------

-- ===========================================================================
-- CLIENT PARTS FOR EACH TAB — Quotations, Brand and Checklists are parts of
-- Clients of their own (2026-10-22)
-- ===========================================================================
-- WHY (the user, 2026-10-22: "it does not cover every parent section and
-- every child section … AMV quote, AMV Service Lines, AMV Issue documents"):
-- Clients: Services answered for quotations and service lines alike, and
-- the Brand pane and the checklists answered to the Clients level alone, so
-- no group could be given one without the other.
--
-- WHAT IT CHANGES
--   * `clients.quotes` (Quotations): Build quote, a quotation's state and
--     the quotations list (`quote_preview`, `quotation_create`,
--     `quotation_set`, policy `quotations_read`), the rate card it prices
--     from (`rate_card_current`), a quotation sent on WhatsApp
--     (`wa_may_send`) and a quotation named on a checklist
--     (`checklist_prefill`, `client_checklist`). Issue Letter of Offer from
--     a quotation (`quotation_offer`) asks it and Clients: Services at Work,
--     since it makes service lines. Every group holding a level on Services
--     is given the same on Quotations, so nobody gains or loses a thing.
--   * `clients.brand` (Brand): Meta accounts (`meta_links_save`), the
--     Brand analysis (`brand_analysis_save`, `brand_analyses_list`,
--     `brand_analysis_confirm`, `ai_analysis_claim`, `ai_analysis_left`),
--     and the content brief and brand notes written on the client (trigger
--     `clients_brand_guard`, `brand-columns`, held as `client_review_columns`
--     holds its own).
--   * `clients.checklists` (Checklists): `client_checklist`,
--     `client_checklist_set`, `client_checklist_step`, `ai_checklist_claim`,
--     `ai_checklist_left`, `client_checklists_due`.
--   Each new part follows Clients where a group sets none, as every part.
--
-- ORDER: this file, then the pages. An old page asks the same functions and
-- is answered as before for every group. Safe to run twice. Rollback: each
-- function's definition before this file, policy `quotations_read` on
-- `allowed('clients.services', 'view')`, and
--   drop trigger if exists clients_brand_guard on public.clients;
-- the parts copied into the access maps may stay.
-- ===========================================================================

update public.team_roles r
   set access = r.access || jsonb_build_object('clients.quotes', r.access -> 'clients.services')
 where r.access ? 'clients.services' and not r.access ? 'clients.quotes';

alter policy quotations_read on public.quotations using (public.allowed('clients.quotes', 'view'));

create or replace function public.clients_brand_guard()
returns trigger language plpgsql set search_path = public as $$
begin
  /* A function writing the row has asked its own permission, and a cascade
     is not a person: only a write made on the table through the API. */
  if pg_trigger_depth() > 1 or current_user <> 'authenticated' then
    return new;
  end if;
  if (new.brief, new.brand_notes) is distinct from (old.brief, old.brand_notes)
     and not public.allowed('clients.brand', 'work') then
    raise exception 'brand-columns: the content brief and brand notes need Clients: Brand at Work.'
      using errcode = '42501';
  end if;
  return new;
end $$;
revoke all on function public.clients_brand_guard() from public, anon, authenticated;

create or replace trigger clients_brand_guard before update on public.clients
  for each row execute function public.clients_brand_guard();

create or replace function public.quote_preview(p_sel jsonb)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_card jsonb := public.quote_card();
  v_cl uuid;
  v_fx numeric;
begin
  if not public.is_team() or not public.allowed('clients.quotes', 'view') then
    return jsonb_build_object('error', 'denied');
  end if;
  if v_card is null then return jsonb_build_object('error', 'no-card'); end if;
  if coalesce(p_sel->>'client', '') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     and public.client_scope_ok('client', (p_sel->>'client')::uuid, 'view') then
    v_cl := (p_sel->>'client')::uuid;
  end if;
  v_fx := public.quote_fx(v_cl);
  if v_fx = 0 then return jsonb_build_object('error', 'no-fx'); end if;
  return public.quote_fx_out(public.quote_adjust(public.quote_price(public.quote_fx_snap(public.quote_tax_snap(v_card->'snapshot', v_cl), v_fx),
           p_sel - 'client'), public.quote_tax_edits(p_sel->'edits')), v_fx) || jsonb_build_object('version', v_card->>'version');
end $$;

create or replace function public.quotation_create(p_client uuid, p_sel jsonb, p_idem text)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare me public.team_members := public.ops_me();
begin
  if me.id is null or not public.allowed('clients.quotes', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if not public.client_scope_ok('client', p_client, 'work') then return jsonb_build_object('error', 'client-scope'); end if;
  return public.quotation_make(p_client, p_sel, nullif(btrim(coalesce(p_idem, '')), ''), 'console', me.name, null);
end $$;

create or replace function public.quotation_set(p_id uuid, p_what text)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  v_q public.quotations;
  v_word text;
begin
  if me.id is null or not public.allowed('clients.quotes', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into v_q from public.quotations where id = p_id;
  if v_q.id is null or not public.client_scope_ok('client', v_q.client_id, 'work') then
    return jsonb_build_object('error', 'not-found');
  end if;
  if p_what = 'not_proceeding' then
    update public.quotations set status = 'not_proceeding' where id = p_id; v_word := ' marked Not proceeding';
  elsif p_what = 'proceeding' then
    update public.quotations set status = case when requested_at is not null then 'requested' else 'sent' end
     where id = p_id;
    v_word := ' restored';
  elsif p_what = 'remove' then
    update public.quotations set removed_at = now(), removed_by = me.name where id = p_id; v_word := ' removed';
  elsif p_what = 'restore' then
    update public.quotations set removed_at = null, removed_by = null where id = p_id; v_word := ' restored';
  else
    return jsonb_build_object('error', 'bad-what');
  end if;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'client.quotation', v_q.brand, v_q.ref || v_word);
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.quotation_offer(p_id uuid)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  v_q public.quotations;
  v_l jsonb;
  v_ids uuid[] := '{}';
  v_id uuid;
begin
  if me.id is null or not (public.allowed('clients.quotes', 'work') and public.allowed('clients.services', 'work')) then return jsonb_build_object('error', 'denied'); end if;
  select * into v_q from public.quotations where id = p_id for update;
  if v_q.id is null or v_q.removed_at is not null or not public.client_scope_ok('client', v_q.client_id, 'work') then
    return jsonb_build_object('error', 'not-found');
  end if;
  if v_q.status = 'not_proceeding' then return jsonb_build_object('error', 'not-proceeding'); end if;
  select coalesce(array_agg(s.id order by s.created_at), '{}') into v_ids
    from public.client_services s where s.quotation_id = v_q.id and s.archived_at is null;
  if array_length(v_ids, 1) is not null then return jsonb_build_object('ok', true, 'ids', to_jsonb(v_ids), 'again', true); end if;
  if v_q.valid_until < (now() at time zone 'Asia/Kuala_Lumpur')::date then return jsonb_build_object('error', 'expired'); end if;
  for v_l in select * from jsonb_array_elements(v_q.lines) loop
    insert into public.client_services (client_id, service_slug, label, qty, rate, unit, state, note,
                                        tenure, term_adjust, term_pct, detail, quotation_id, tax_code)
    values (v_q.client_id,
            case when exists (select 1 from public.services s where s.slug = v_l->>'slug') then v_l->>'slug' end,
            v_l->>'label', (v_l->>'qty')::numeric, (v_l->>'rate')::numeric,
            case when v_l->>'basis' = 'month' then 'Per month' else 'One-off' end, 'quoted',
            'Quotation ' || v_q.ref,
            case when v_l->>'basis' = 'month' then coalesce((v_l->>'months')::int, (v_q.totals->>'term')::int) else 1 end,
            v_l->>'basis' = 'month', case when v_l->>'basis' = 'month' then (v_q.totals->>'term_pct')::numeric else 0 end,
            nullif(array_to_string(array(select jsonb_array_elements_text(coalesce(v_l->'detail', '[]'::jsonb))), E'\n'), ''),
            v_q.id, nullif(v_l->>'tax_code', ''))
    returning id into v_id;
    v_ids := v_ids || v_id;
  end loop;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'client.quotation', v_q.brand, v_q.ref || ' · ' || array_length(v_ids, 1) || ' lines To quote for the Letter of Offer');
  return jsonb_build_object('ok', true, 'ids', to_jsonb(v_ids));
end $$;

create or replace function public.rate_card_current()
returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object('id', v.id, 'version', v.version, 'valid_until', v.valid_until,
           'published_at', v.published_at, 'published_by', v.published_by, 'snapshot', v.snapshot)
    from public.rate_card_versions v
   where public.is_team() and (public.allowed('services', 'view') or public.allowed('clients.services', 'view')
                                or public.allowed('clients.quotes', 'view'))
   order by v.published_at desc
   limit 1
$$;

create or replace function public.wa_may_send(p_purpose text, p_to_kind text)
returns boolean
language sql stable security definer set search_path = public as $$
  select public.allowed('whatsapp', 'work') and case p_purpose
    when 'report'   then public.allowed('whatsapp.report', 'work') and public.allowed('reports', 'view')
    when 'feedback' then public.allowed('whatsapp.feedback', 'work') and public.allowed('clients', 'view')
    when 'creator'  then public.allowed('whatsapp.booking', 'work') and public.allowed('campaigns', 'view')
    when 'approval' then p_to_kind = 'contact' and public.allowed('whatsapp.approval', 'work')
                         and (public.allowed('review.sets', 'view') or public.allowed('campaigns.campaigns', 'view'))
    when 'quotation' then p_to_kind = 'contact' and public.allowed('whatsapp.documents', 'work')
                          and public.allowed('clients.quotes', 'view')
    when 'offer'    then p_to_kind = 'contact' and public.allowed('whatsapp.documents', 'work')
                         and public.allowed('clients.documents', 'view')
    when 'message'  then case p_to_kind when 'contact' then public.allowed('clients.contacts', 'view')
                                        when 'creator' then public.allowed('campaigns.creators', 'view')
                                        else false end
    else false end
$$;

create or replace function public.checklist_prefill(p_client uuid, p_kind text)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  c public.clients;
  q text;
  sw jsonb;
  j text := E'\n';
begin
  select * into c from public.clients where id = p_client;
  if c.id is null or p_kind <> 'pre_ads' then return '{}'::jsonb; end if;
  select x.ref into q from public.quotations x
   where x.client_id = p_client and x.removed_at is null order by x.issued_at desc limit 1;
  select b.analysis->'swot' into sw from public.brand_analyses b
   where b.client_id = p_client and b.confirmed_at is not null order by b.version desc limit 1;
  return jsonb_strip_nulls(jsonb_build_object(
    -- The registered name is Billing's, and a quotation Quotations' (audit S4):
    -- each is prefilled only for a reader who may open it.
    'details.entity', nullif(coalesce(case when public.allowed('clients.billing', 'view') or public.register_may('client', 'work')
                                           then nullif(btrim(c.legal_name), '') end, c.name), ''),
    'details.quotation', case when public.allowed('clients.quotes', 'view') then q end,
    'competitors.direct', nullif(btrim(coalesce(c.brief->>'competitors', '')), ''),
    'competitors.strength', nullif(array_to_string(array(select jsonb_array_elements_text(coalesce(sw->'strengths', '[]'::jsonb))), j), ''),
    'competitors.weakness', nullif(array_to_string(array(select jsonb_array_elements_text(coalesce(sw->'weaknesses', '[]'::jsonb))), j), ''),
    'competitors.opportunities', nullif(array_to_string(array(select jsonb_array_elements_text(coalesce(sw->'opportunities', '[]'::jsonb))), j), ''),
    'competitors.threats', nullif(array_to_string(array(select jsonb_array_elements_text(coalesce(sw->'threats', '[]'::jsonb))), j), '')));
end $$;

create or replace function public.client_checklist(p_client uuid, p_kind text)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.client_checklists;
  t jsonb;
  pre jsonb;
  hints jsonb := '{}'::jsonb;
  q record;
  m timestamptz;
begin
  if me.id is null or not public.allowed('clients.checklists', 'view') then return jsonb_build_object('error', 'denied'); end if;
  if not public.client_scope_ok('client', p_client, 'view') then return jsonb_build_object('error', 'client-scope'); end if;
  if p_kind not in ('onboarding', 'pre_ads') then return jsonb_build_object('error', 'bad-kind'); end if;
  select * into r from public.client_checklists where client_id = p_client and kind = p_kind;
  t := coalesce(r.template, public.checklist_template(p_kind));
  pre := public.checklist_prefill(p_client, p_kind);
  -- Once started, only what each reader's own access gives (the registered
  -- name, the quotation) is worked out on the read; it is never stored.
  if r.id is not null then
    pre := jsonb_strip_nulls(jsonb_build_object('details.entity', pre->'details.entity',
                                                'details.quotation', pre->'details.quotation'));
  end if;
  if p_kind = 'onboarding' and public.allowed('clients.quotes', 'view') then
    select x.ref, x.issued_at into q from public.quotations x
     where x.client_id = p_client and x.removed_at is null order by x.issued_at desc limit 1;
    if q.ref is not null then
      hints := hints || jsonb_build_object('pre.quotation', 'Quotation ' || q.ref || ' issued ' ||
        to_char(q.issued_at at time zone 'Asia/Kuala_Lumpur', 'FMDD Mon YYYY'));
    end if;
  end if;
  if p_kind = 'onboarding' then
    select min(e.meeting_at) into m from public.ops_engagements e where e.client_id = p_client and e.meeting_at is not null;
    if m is not null then
      hints := hints || jsonb_build_object('pre.first_meeting', 'Meeting set for ' ||
        to_char(m at time zone 'Asia/Kuala_Lumpur', 'FMDD Mon YYYY, FMHH12:MIam'));
    end if;
  end if;
  return jsonb_build_object(
    'kind', p_kind, 'title', t->>'title', 'version', t->>'version', 'lead', t->>'lead', 'sections', t->'sections',
    'started', r.id is not null, 'answers', coalesce(r.answers, '{}'::jsonb), 'prefill', coalesce(pre, '{}'::jsonb),
    'sections_na', to_jsonb(coalesce(r.sections_na, '{}'::text[])), 'status', coalesce(r.status, 'open'),
    'prepared', case when r.prepared_at is not null then jsonb_build_object('id', r.prepared_by, 'name', r.prepared_name, 'at', r.prepared_at) end,
    'reviewed', case when r.reviewed_at is not null then jsonb_build_object('id', r.reviewed_by, 'name', r.reviewed_name, 'at', r.reviewed_at) end,
    'history', jsonb_array_length(coalesce(r.history, '[]'::jsonb)),
    'hints', hints, 'me', me.id, 'filled_by_me', public.checklist_filled_by(r.answers, me.id, me.name),
    'can_work', public.allowed('clients.checklists', 'work') and public.client_scope_ok('client', p_client, 'work'),
    'can_manage', public.allowed('clients.checklists', 'manage') and public.client_scope_ok('client', p_client, 'manage'),
    'updated_at', r.updated_at);
end $$;

create or replace function public.client_checklist_set(p_client uuid, p_kind text, p_item text, p_state text,
                                                       p_note text, p_value jsonb)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.client_checklists;
  c public.clients;
  t jsonb;
  sec jsonb;
  it jsonb;
  a jsonb;
  was jsonb;
  v_sec text := split_part(coalesce(p_item, ''), '.', 1);
  v_key text := split_part(coalesce(p_item, ''), '.', 2);
  what text;
begin
  if me.id is null or not public.allowed('clients.checklists', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if not public.client_scope_ok('client', p_client, 'work') then return jsonb_build_object('error', 'client-scope'); end if;
  if p_kind not in ('onboarding', 'pre_ads') then return jsonb_build_object('error', 'bad-kind'); end if;
  select * into c from public.clients where id = p_client;
  if c.id is null then return jsonb_build_object('error', 'not-found'); end if;
  insert into public.client_checklists (client_id, kind, version, template, answers)
  select p_client, p_kind, t0->>'version', t0,
         (select coalesce(jsonb_object_agg(k, jsonb_build_object('value', v)), '{}'::jsonb)
            from jsonb_each(public.checklist_prefill(p_client, p_kind) - 'details.entity' - 'details.quotation') e(k, v))
    from (select public.checklist_template(p_kind) t0) z
  on conflict (client_id, kind) do nothing;
  select * into r from public.client_checklists where client_id = p_client and kind = p_kind for update;
  if r.status <> 'open' then return jsonb_build_object('error', 'locked', 'status', r.status); end if;
  t := r.template;
  select s into sec from jsonb_array_elements(t->'sections') s where s->>'key' = v_sec;
  if sec is null then return jsonb_build_object('error', 'bad-item'); end if;

  if v_key = '' then
    if p_state = 'na' then
      update public.client_checklists set sections_na = array(select distinct unnest(sections_na || v_sec)),
             updated_at = now() where id = r.id;
      what := (sec->>'title') || ': not applicable';
    elsif coalesce(p_state, '') = '' then
      update public.client_checklists set sections_na = array_remove(sections_na, v_sec), updated_at = now() where id = r.id;
      what := (sec->>'title') || ': applicable';
    else return jsonb_build_object('error', 'bad-state'); end if;
  else
    select i into it from jsonb_array_elements(sec->'items') i where i->>'key' = v_key;
    if it is null then return jsonb_build_object('error', 'bad-item'); end if;
    was := coalesce(r.answers->p_item, '{}'::jsonb);
    a := was;
    if p_state is not null then
      if it->>'kind' <> 'tick' or p_state not in ('', 'done', 'na') then return jsonb_build_object('error', 'bad-state'); end if;
      a := (a - 'state' - 'by' - 'by_id' - 'at') || case when p_state = '' then '{}'::jsonb
             else jsonb_build_object('state', p_state, 'by', me.name, 'by_id', me.id, 'at', now()) end;
      what := (it->>'label') || ': ' || case p_state when 'done' then 'done' when 'na' then 'not applicable' else 'not done' end;
    end if;
    if p_note is not null then
      if char_length(p_note) > 1000 then return jsonb_build_object('error', 'too-long'); end if;
      a := (a - 'note') || case when btrim(p_note) = '' then '{}'::jsonb else jsonb_build_object('note', btrim(p_note)) end;
      a := a || jsonb_build_object('set_by', me.id);
      what := coalesce(what, (it->>'label') || ': note changed');
    end if;
    if p_value is not null then
      if it->>'kind' = 'tick' then return jsonb_build_object('error', 'bad-value'); end if;
      if it->>'kind' = 'text' and (jsonb_typeof(p_value) <> 'string' or char_length(p_value #>> '{}') > 4000) then
        return jsonb_build_object('error', 'bad-value');
      end if;
      if it->>'kind' = 'choice' and (jsonb_typeof(p_value) <> 'string' or
         (p_value #>> '{}' <> '' and not (it->'choices') ? (p_value #>> '{}'))) then
        return jsonb_build_object('error', 'bad-value');
      end if;
      if it->>'kind' = 'multi' and (jsonb_typeof(p_value) <> 'array' or
         exists (select 1 from jsonb_array_elements(p_value) v where jsonb_typeof(v) <> 'string' or not (it->'choices') ? (v #>> '{}'))) then
        return jsonb_build_object('error', 'bad-value');
      end if;
      /* A table (r1.2's Meta Campaign Setup): twelve rows at most, each
         row only the item's own columns, each cell words of 400 at most. */
      if it->>'kind' = 'table' and (jsonb_typeof(p_value) <> 'array' or jsonb_array_length(p_value) > 12 or
         exists (select 1 from jsonb_array_elements(p_value) rw where jsonb_typeof(rw) <> 'object' or
           exists (select 1 from jsonb_each(rw) e where jsonb_typeof(e.value) <> 'string' or char_length(e.value #>> '{}') > 400 or
             not exists (select 1 from jsonb_array_elements(it->'columns') col where col->>0 = e.key)))) then
        return jsonb_build_object('error', 'bad-value');
      end if;
      a := (a - 'value') || case when p_value in ('""'::jsonb, '[]'::jsonb) then '{}'::jsonb
             else jsonb_build_object('value', p_value) end;
      a := a || jsonb_build_object('set_by', me.id);
      what := coalesce(what, (it->>'label') || ': ' || case when p_value in ('""'::jsonb, '[]'::jsonb) then 'cleared' else 'changed' end);
    end if;
    if a - 'set_by' = was - 'set_by' then return public.client_checklist(p_client, p_kind); end if;
    update public.client_checklists set answers = case when a = '{}'::jsonb then answers - p_item else jsonb_set(answers, array[p_item], a) end,
           updated_at = now() where id = r.id;
  end if;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'client.edited', c.name, (t->>'title') || ' · ' || what);
  return public.client_checklist(p_client, p_kind);
end $$;

create or replace function public.ai_checklist_claim(p_client uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m public.team_members;
  since timestamptz := public.ai_draft_day();
  n_used integer;
  lim integer;
  new_id uuid;
begin
  if not public.allowed('clients.checklists', 'work') then return jsonb_build_object('error', 'denied'); end if;
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'denied'); end if;
  if not exists (select 1 from public.clients c where c.id = p_client) then return jsonb_build_object('error', 'not-found'); end if;
  if not public.client_scope_ok('client', p_client, 'work') then return jsonb_build_object('error', 'client-scope'); end if;
  perform pg_advisory_xact_lock(hashtext('ai_draft_claim'));
  lim := case when coalesce(m.is_admin, false) or m.role = 'admin'
              then public.ai_draft_limit('checklist_admin', 20) else public.ai_draft_limit('checklist', 10) end;
  if lim = 0 then return jsonb_build_object('error', 'ai-limit', 'scope', 'stopped', 'limit', 0); end if;
  select count(*) into n_used from public.ai_drafts d
   where d.team_member_id = m.id and d.purpose = 'checklist' and d.created_at >= since and d.outcome <> 'failed';
  if n_used >= lim then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'checklist', 'limit', lim, 'next', since + interval '1 day');
  end if;
  insert into public.ai_drafts (team_member_id, client_id, purpose)
  values (m.id, p_client, 'checklist') returning id into new_id;
  return jsonb_build_object('id', new_id, 'left', lim - n_used - 1, 'limit', lim);
end $$;

create or replace function public.ai_checklist_left()
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  m public.team_members;
  since timestamptz := public.ai_draft_day();
  lim integer;
begin
  if not public.allowed('clients.checklists', 'work') then return jsonb_build_object('error', 'denied'); end if;
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'denied'); end if;
  lim := case when coalesce(m.is_admin, false) or m.role = 'admin'
              then public.ai_draft_limit('checklist_admin', 20) else public.ai_draft_limit('checklist', 10) end;
  return jsonb_build_object('limit', lim, 'next', since + interval '1 day',
    'left', greatest(0, lim - (select count(*) from public.ai_drafts d
      where d.team_member_id = m.id and d.purpose = 'checklist' and d.created_at >= since and d.outcome <> 'failed')::integer));
end $$;

create or replace function public.client_checklists_due()
returns jsonb
language sql stable security definer set search_path = public as $$
  select case when (public.ops_me()).id is null or not public.allowed('clients.checklists', 'view') then '[]'::jsonb else
    coalesce((select jsonb_agg(jsonb_build_object('client_id', c.id, 'name', c.name, 'slug', c.slug, 'owner', c.owner,
              'kind', k.kind, 'status', coalesce(r.status, 'open'), 'started', r.id is not null,
              'since', coalesce(c.stage_since, c.created_at)) order by coalesce(c.stage_since, c.created_at))
       from public.clients c
       cross join (values ('onboarding'), ('pre_ads')) k(kind)
       left join public.client_checklists r on r.client_id = c.id and r.kind = k.kind
      where c.stage = 'active'
        and coalesce(r.status, 'open') <> 'signed'
        and (r.id is not null
             or (select min((e->>'at')::timestamptz) from jsonb_array_elements(coalesce(c.stage_log, '[]'::jsonb)) e
                  where e->>'stage' = 'active' and e->>'at' is not null)
                >= ('2026-10-15'::date)::timestamp at time zone 'Asia/Kuala_Lumpur')
        and public.client_scope_ok('client', c.id, 'view')
        and not exists (select 1 from public.ops_engagement_checks x join public.ops_engagements e on e.id = x.engagement_id
                         where e.client_id = c.id and x.key = k.kind and x.state = 'na')), '[]'::jsonb) end
$$;

create or replace function public.client_checklist_step(p_client uuid, p_kind text, p_step text)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.client_checklists;
  c public.clients;
  n int;
  word text;
begin
  if me.id is null or not public.allowed('clients.checklists', case when p_step = 'reopen' then 'manage' else 'work' end) then
    return jsonb_build_object('error', 'denied');
  end if;
  if not public.client_scope_ok('client', p_client, case when p_step = 'reopen' then 'manage' else 'work' end) then
    return jsonb_build_object('error', 'client-scope');
  end if;
  select * into c from public.clients where id = p_client;
  select * into r from public.client_checklists where client_id = p_client and kind = p_kind for update;
  if c.id is null or r.id is null then return jsonb_build_object('error', 'not-started'); end if;
  if p_step = 'prepare' then
    if r.status <> 'open' then return jsonb_build_object('error', 'locked', 'status', r.status); end if;
    select count(*) into n
      from jsonb_array_elements(r.template->'sections') s, jsonb_array_elements(s->'items') i
     where i->>'kind' = 'tick' and not ((s->>'key') = any(r.sections_na))
       and coalesce(r.answers->((s->>'key') || '.' || (i->>'key'))->>'state', '') not in ('done', 'na');
    if n > 0 then return jsonb_build_object('error', 'incomplete', 'left', n); end if;
    update public.client_checklists set status = 'prepared', prepared_by = me.id, prepared_name = me.name,
           prepared_at = now(), updated_at = now() where id = r.id;
    word := 'prepared for review';
  elsif p_step = 'return' then
    if r.status <> 'prepared' then return jsonb_build_object('error', 'locked', 'status', r.status); end if;
    update public.client_checklists set status = 'open', prepared_by = null, prepared_name = null, prepared_at = null,
           updated_at = now() where id = r.id;
    word := 'sent back';
  elsif p_step = 'review' then
    if r.status <> 'prepared' then return jsonb_build_object('error', 'locked', 'status', r.status); end if;
    if r.prepared_by = me.id then return jsonb_build_object('error', 'own'); end if;
    if public.checklist_filled_by(r.answers, me.id, me.name) then return jsonb_build_object('error', 'own'); end if;
    update public.client_checklists set status = 'signed', reviewed_by = me.id, reviewed_name = me.name,
           reviewed_at = now(), updated_at = now() where id = r.id;
    update public.ops_engagement_checks k set state = 'ready', owner_id = me.id, updated_by = me.id, updated_at = now()
      from public.ops_engagements e
     where e.id = k.engagement_id and e.client_id = p_client and k.key = p_kind and k.state <> 'na';
    word := 'reviewed and signed off';
  elsif p_step = 'reopen' then
    if r.status <> 'signed' then return jsonb_build_object('error', 'locked', 'status', r.status); end if;
    update public.client_checklists set status = 'open',
           history = history || jsonb_build_array(jsonb_build_object('answers', r.answers, 'sections_na', to_jsonb(r.sections_na),
             'version', r.version, 'prepared', r.prepared_name, 'prepared_at', r.prepared_at,
             'reviewed', r.reviewed_name, 'reviewed_at', r.reviewed_at, 'reopened_by', me.name, 'reopened_at', now())),
           prepared_by = null, prepared_name = null, prepared_at = null,
           reviewed_by = null, reviewed_name = null, reviewed_at = null, updated_at = now() where id = r.id;
    update public.ops_engagement_checks k set state = 'not_started', owner_id = null, updated_by = me.id, updated_at = now()
      from public.ops_engagements e
     where e.id = k.engagement_id and e.client_id = p_client and k.key = p_kind and k.state = 'ready';
    word := 'reopened';
  else
    return jsonb_build_object('error', 'bad-step');
  end if;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'client.edited', c.name, (r.template->>'title') || ' · ' || word);
  return public.client_checklist(p_client, p_kind);
end $$;

create or replace function public.meta_links_save(p_client uuid, p_brand uuid, p_ad_accounts jsonb, p_page jsonb, p_instagram jsonb)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  v_client text;
  v_brand text;
  v_accs jsonb := '[]'::jsonb;
  v_page jsonb := public.meta_asset_of(p_page);
  v_ig jsonb := public.meta_asset_of(p_instagram);
  e jsonb;
  a jsonb;
  v_old public.meta_links;
  v_detail text;
begin
  if me.id is null or not public.allowed('clients.brand', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if not public.client_seen(p_client, 'work') then return jsonb_build_object('error', 'denied'); end if;
  select c.name into v_client from public.clients c where c.id = p_client;
  if v_client is null then return jsonb_build_object('error', 'not-found'); end if;
  if p_brand is not null then
    select b.name into v_brand from public.client_brands b where b.id = p_brand and b.client_id = p_client;
    if v_brand is null then return jsonb_build_object('error', 'bad-brand'); end if;
  end if;
  if p_ad_accounts is not null and jsonb_typeof(p_ad_accounts) <> 'array' then return jsonb_build_object('error', 'bad-asset'); end if;
  for e in select x from jsonb_array_elements(coalesce(p_ad_accounts, '[]'::jsonb)) as t(x) loop
    a := public.meta_asset_of(e);
    if a is null or a ? 'bad' then return jsonb_build_object('error', 'bad-asset'); end if;
    if not exists (select 1 from jsonb_array_elements(v_accs) as y(z) where y.z ->> 'id' = a ->> 'id') then
      v_accs := v_accs || jsonb_build_array(a);
    end if;
  end loop;
  if jsonb_array_length(v_accs) > 20 or coalesce(v_page ? 'bad', false) or coalesce(v_ig ? 'bad', false) then
    return jsonb_build_object('error', 'bad-asset');
  end if;
  select * into v_old from public.meta_links l
   where l.client_id = p_client and l.brand_id is not distinct from p_brand for update;
  if v_old.id is not null and v_old.ad_accounts = v_accs and v_old.page is not distinct from v_page and v_old.instagram is not distinct from v_ig then
    return jsonb_build_object('ok', true);
  end if;
  if v_old.id is null and jsonb_array_length(v_accs) = 0 and v_page is null and v_ig is null then
    return jsonb_build_object('ok', true);
  end if;
  v_detail := concat_ws(' · ',
    case when coalesce(v_old.ad_accounts, '[]'::jsonb) <> v_accs
         then 'Meta ad accounts: ' || public.meta_names(v_old.ad_accounts) || ' → ' || public.meta_names(v_accs) end,
    case when v_old.page is distinct from v_page
         then 'Facebook Page: ' || public.meta_names(v_old.page) || ' → ' || public.meta_names(v_page) end,
    case when v_old.instagram is distinct from v_ig
         then 'Instagram: ' || public.meta_names(v_old.instagram) || ' → ' || public.meta_names(v_ig) end);
  -- Two first saves at once: the second writes over the first, never fails (audit 20).
  insert into public.meta_links (client_id, brand_id, ad_accounts, page, instagram, updated_by)
  values (p_client, p_brand, v_accs, v_page, v_ig, me.name)
  on conflict (client_id, coalesce(brand_id, '00000000-0000-0000-0000-000000000000'::uuid)) do update
     set ad_accounts = excluded.ad_accounts, page = excluded.page, instagram = excluded.instagram,
         updated_at = now(), updated_by = excluded.updated_by;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'client.brand', v_client, case when v_brand is not null then v_brand || ': ' else '' end || v_detail);
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.brand_analysis_save(p_press uuid, p_analysis jsonb, p_sources jsonb,
                                                      p_basis jsonb, p_hypothesis boolean, p_model text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m public.team_members;
  d public.ai_drafts;
  c public.clients;
  a public.brand_analyses;
  v_no integer;
begin
  if not public.allowed('clients.brand', 'view') then return jsonb_build_object('error', 'denied'); end if;
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'denied'); end if;
  select * into d from public.ai_drafts x where x.id = p_press for update;
  if d.id is null or d.team_member_id <> m.id or d.purpose <> 'analysis' or d.outcome <> 'pending'
     or exists (select 1 from public.brand_analyses x where x.press_id = d.id) then
    return jsonb_build_object('error', 'not-found');
  end if;
  select * into c from public.clients x where x.id = d.client_id;
  if c.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if not public.client_seen(c.id, 'view') then return jsonb_build_object('error', 'client-scope'); end if;
  if jsonb_typeof(p_analysis) is distinct from 'object' or char_length(p_analysis::text) > 60000 then
    return jsonb_build_object('error', 'bad-analysis');
  end if;
  perform pg_advisory_xact_lock(hashtext('brand_analysis:' || c.id::text));
  select coalesce(max(x.version), 0) + 1 into v_no from public.brand_analyses x where x.client_id = c.id;
  insert into public.brand_analyses (client_id, version, analysis, sources, basis, hypothesis, model, press_id, created_by)
  values (c.id, v_no, p_analysis,
          case when jsonb_typeof(p_sources) = 'array' and char_length(p_sources::text) <= 12000 then p_sources else '[]'::jsonb end,
          case when jsonb_typeof(p_basis) = 'object' then p_basis else '{}'::jsonb end,
          coalesce(p_hypothesis, false), left(nullif(btrim(coalesce(p_model, '')), ''), 80), d.id, m.id)
  returning * into a;
  insert into public.activity_log (actor, action, subject, detail)
  values (coalesce(m.name, m.email), 'client.brand', c.name,
          'Brand analysis: version ' || v_no || ' run with AI' ||
          case when coalesce(p_hypothesis, false) then ', a starting hypothesis to test' else '' end);
  return public.brand_analysis_row(a);
end $$;

create or replace function public.brand_analyses_list(p_client uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.allowed('clients.brand', 'view') then return jsonb_build_object('error', 'denied'); end if;
  if not public.client_seen(p_client, 'view') then return jsonb_build_object('error', 'client-scope'); end if;
  return jsonb_build_object('versions', coalesce((select jsonb_agg(public.brand_analysis_row(x) order by x.version desc)
    from (select * from public.brand_analyses a where a.client_id = p_client order by a.version desc limit 20) x), '[]'::jsonb));
end $$;

create or replace function public.ai_analysis_claim(p_client uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m public.team_members;
  since timestamptz := public.ai_draft_day();
  n_used integer;
  lim integer;
  new_id uuid;
begin
  if not public.allowed('clients.brand', 'view') then return jsonb_build_object('error', 'denied'); end if;
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'denied'); end if;
  if not exists (select 1 from public.clients c where c.id = p_client) then return jsonb_build_object('error', 'not-found'); end if;
  if not public.client_seen(p_client, 'view') then return jsonb_build_object('error', 'client-scope'); end if;
  -- One count at a time, with the drafts, so the last analysis is taken once.
  perform pg_advisory_xact_lock(hashtext('ai_draft_claim'));
  lim := case when coalesce(m.is_admin, false) or m.role = 'admin'
              then public.ai_draft_limit('analysis_admin', 10) else public.ai_draft_limit('analysis', 3) end;
  if lim = 0 then return jsonb_build_object('error', 'ai-limit', 'scope', 'stopped', 'limit', 0); end if;
  select count(*) into n_used from public.ai_drafts d
   where d.team_member_id = m.id and d.purpose = 'analysis' and d.created_at >= since and d.outcome <> 'failed';
  if n_used >= lim then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'analysis', 'limit', lim, 'next', since + interval '1 day');
  end if;
  insert into public.ai_drafts (team_member_id, client_id, purpose)
  values (m.id, p_client, 'analysis') returning id into new_id;
  return jsonb_build_object('id', new_id, 'left', lim - n_used - 1, 'limit', lim);
end $$;

create or replace function public.ai_analysis_left()
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  m public.team_members;
  since timestamptz := public.ai_draft_day();
  lim integer;
  l_left integer;
begin
  if not public.allowed('clients.brand', 'view') then return jsonb_build_object('error', 'denied'); end if;
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'denied'); end if;
  lim := case when coalesce(m.is_admin, false) or m.role = 'admin'
              then public.ai_draft_limit('analysis_admin', 10) else public.ai_draft_limit('analysis', 3) end;
  l_left := greatest(0, lim - (select count(*) from public.ai_drafts d
    where d.team_member_id = m.id and d.purpose = 'analysis' and d.created_at >= since and d.outcome <> 'failed')::integer);
  return jsonb_build_object('left', l_left, 'limit', lim, 'scope', case when lim = 0 then 'stopped' else 'analysis' end,
    'next', case when l_left > 0 or lim = 0 then null else since + interval '1 day' end);
end $$;

create or replace function public.brand_analysis_confirm(p_id uuid, p_on boolean default true)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m public.team_members;
  a public.brand_analyses;
  c public.clients;
  v_an jsonb;
  v_was jsonb;
  v_new jsonb;
  v_put text;
  v_k text;
  v_filled text[] := '{}';
  v_word text;
begin
  if not public.allowed('clients.brand', 'view') then return jsonb_build_object('error', 'denied'); end if;
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'denied'); end if;
  select * into a from public.brand_analyses x where x.id = p_id for update;
  if a.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if not public.client_seen(a.client_id, 'view') then return jsonb_build_object('error', 'client-scope'); end if;
  select * into c from public.clients x where x.id = a.client_id;
  if coalesce(p_on, true) = (a.confirmed_at is not null) then return public.brand_analysis_row(a); end if;
  update public.brand_analyses x
     set confirmed_at = case when coalesce(p_on, true) then now() end,
         confirmed_by = case when coalesce(p_on, true) then m.id end
   where x.id = p_id returning * into a;
  insert into public.activity_log (actor, action, subject, detail)
  values (coalesce(m.name, m.email), 'client.brand', c.name,
          'Brand analysis: version ' || a.version ||
          case when coalesce(p_on, true) then ' written with AI, read and confirmed' else ' confirmation withdrawn' end);

  /* The brief's empty parts, from what this analysis concluded. */
  if coalesce(p_on, true) and public.allowed('clients.brand', 'work') and public.client_scope_ok('client', c.id, 'work') then
    v_an := coalesce(a.analysis, '{}'::jsonb);
    v_was := case when jsonb_typeof(c.brief) = 'object' then c.brief else '{}'::jsonb end;
    v_new := v_was;
    foreach v_k in array array['audience', 'pains', 'pillars', 'tone', 'competitors'] loop
      if coalesce(btrim(v_was ->> v_k), '') <> '' then continue; end if;
      v_put := case v_k
        when 'audience' then coalesce(nullif(btrim(v_an #>> '{brief,audience}'), ''),
          (select string_agg(btrim(concat_ws(': ', s ->> 'name', s ->> 'who')), E'\n')
             from jsonb_array_elements(case when jsonb_typeof(v_an -> 'audiences') = 'array' then v_an -> 'audiences' else '[]'::jsonb end) s))
        when 'pains' then coalesce(nullif(btrim(v_an #>> '{brief,pains}'), ''),
          (select string_agg(btrim(s ->> 'pains'), E'\n')
             from jsonb_array_elements(case when jsonb_typeof(v_an -> 'audiences') = 'array' then v_an -> 'audiences' else '[]'::jsonb end) s
            where coalesce(btrim(s ->> 'pains'), '') <> ''))
        when 'pillars' then
          (select string_agg(btrim(p #>> '{}'), E'\n')
             from jsonb_array_elements(case when jsonb_typeof(v_an #> '{brief,pillars}') = 'array' and jsonb_array_length(v_an #> '{brief,pillars}') > 0
                                            then v_an #> '{brief,pillars}'
                                            when jsonb_typeof(v_an #> '{content,pillars}') = 'array' then v_an #> '{content,pillars}'
                                            else '[]'::jsonb end) p)
        when 'tone' then nullif(btrim(v_an #>> '{brief,tone}'), '')
        else (select string_agg(btrim(p #>> '{}'), ', ')
                from jsonb_array_elements(case when jsonb_typeof(v_an #> '{positioning,competitors}') = 'array'
                                               then v_an #> '{positioning,competitors}' else '[]'::jsonb end) p)
      end;
      v_put := left(btrim(coalesce(v_put, '')), 1000);
      if v_put = '' then continue; end if;
      v_new := v_new || jsonb_build_object(v_k, v_put);
      v_word := case v_k when 'audience' then 'Audience' when 'pains' then 'Pains' when 'pillars' then 'Content pillars'
                         when 'tone' then 'Tone of voice' else 'Competitors' end;
      v_filled := v_filled || v_word;
    end loop;
    if array_length(v_filled, 1) > 0 and char_length(v_new::text) <= 8000 then
      update public.clients x set brief = v_new where x.id = c.id;
      insert into public.activity_log (actor, action, subject, detail)
      values (coalesce(m.name, m.email), 'client.brand', c.name,
              'Content brief: ' || array_to_string(v_filled, ', ') || ' filled from Brand analysis version ' || a.version);
    else
      v_filled := '{}';
    end if;
  end if;
  return public.brand_analysis_row(a) || jsonb_build_object('filled', to_jsonb(v_filled));
end $$;

-- END OF CLIENT PARTS FOR EACH TAB --------------------------------------------

-- ===========================================================================
-- TAX CODES CHOSEN AND DELETED — Read from Bukku takes only the codes ticked,
-- and a code no line, quotation or letter names can be deleted (2026-10-22)
-- ===========================================================================
-- WHY (the user, 2026-10-22: "Read from bukku for sst codes pull in 32 items
-- for taxes which i only uses 0% no tax or 8% SST. And you didnt provide
-- option to delete this is a mistake or error"): Read from Bukku took every
-- code Bukku holds, and a code once held could only be stood down.
--
-- WHAT IT CHANGES
--   * `tax_codes_delete(p_codes)` (Business settings): deletes the codes
--     named, all or none; refused `in-use` with the codes a service line, a
--     quotation or a letter names (those are set not offered instead), and
--     `bad-row` for a list of none or past 100. Filed `team.changed` under
--     Tax codes, the codes named.
--   * The page: Read from Bukku opens a list of Bukku's codes to tick (the
--     codes already offered ticked), and only the ticked ones are kept as
--     offered; each code's ⋯ holds Delete, and Select codes deletes several.
--
-- ORDER: this file, then the pages. An old page never calls it. Safe to
-- run twice. Rollback: `revoke execute on function
-- public.tax_codes_delete(text[]) from authenticated` (the function may
-- stay).
-- ===========================================================================

create or replace function public.tax_code_uses(p_code text)
returns int
language sql stable security definer set search_path = public as $$
  select (select count(*) from public.client_services s where s.tax_code = p_code)::int
       + (select count(*) from public.quotations q
           where exists (select 1 from jsonb_array_elements(case when jsonb_typeof(q.lines) = 'array' then q.lines else '[]'::jsonb end) l
                          where l ->> 'tax_code' = p_code)
              or q.selection::text like '%"tax": ' || to_jsonb(p_code)::text || '%')::int
       + (select count(*) from public.client_documents d
           where to_jsonb(d)::text like '%"tax_code": ' || to_jsonb(p_code)::text || '%')::int
$$;
revoke all on function public.tax_code_uses(text) from public, anon, authenticated;

create or replace function public.tax_codes_delete(p_codes text[])
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me public.team_members := public.ops_me();
  v_codes text[];
  v_used text[];
  v_gone text[];
begin
  if v_me.id is null or not public.ops_granted('team.settings', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select array_agg(distinct btrim(c)) into v_codes from unnest(coalesce(p_codes, '{}')) c where btrim(coalesce(c, '')) <> '';
  if v_codes is null or array_length(v_codes, 1) > 100 then return jsonb_build_object('error', 'bad-row'); end if;
  perform 1 from public.tax_codes t where t.code = any(v_codes) for update;
  select array_agg(t.code order by t.code) into v_used
    from public.tax_codes t where t.code = any(v_codes) and public.tax_code_uses(t.code) > 0;
  if v_used is not null then return jsonb_build_object('error', 'in-use', 'codes', to_jsonb(v_used)); end if;
  with d as (delete from public.tax_codes t where t.code = any(v_codes) returning t.code)
  select array_agg(d.code order by d.code) into v_gone from d;
  if v_gone is not null then
    insert into public.activity_log (actor, action, subject, detail)
    values (v_me.name, 'team.changed', 'Tax codes',
            array_length(v_gone, 1) || ' deleted: ' || array_to_string(v_gone, ', '));
  end if;
  return public.tax_codes_list() || jsonb_build_object('deleted', coalesce(array_length(v_gone, 1), 0));
end $$;
revoke all on function public.tax_codes_delete(text[]) from public, anon;
grant execute on function public.tax_codes_delete(text[]) to authenticated;

-- END OF TAX CODES CHOSEN AND DELETED -----------------------------------------

-- ===========================================================================
-- BILL IN RM OR S$ — a Singapore client is billed in RM unless the team sets
-- it to S$ on its Billing (2026-10-22)
-- ===========================================================================
-- WHY (the user, 2026-10-22: "follow RM as usual unless and optionally
-- choose to have it in S$ with the conversion", "if its at the client site
-- chosen S$ Singapore market then show this option, as it will also affect
-- the report"): a Singapore client's every figure (its quotations, service
-- lines, letters, reports, campaigns and client portal) read S$ because its
-- market was Singapore. The market stays a fact about the client (its
-- numbers, its registration, Meta's taxes); the currency is now its own
-- choice, RM by default.
--
-- WHAT IT CHANGES
--   * `clients.bill_sgd` (false by default), read with the record and set
--     on Billing at Clients: Billing Work (`clients_billing_guard` holds it
--     with the billing columns), offered only for a Singapore client.
--     `client_bill_market(market, sgd)`: SG only where the market is
--     Singapore and it is set, else MY (a client moved to Malaysia bills in
--     RM whatever the flag holds).
--   * `get_portal`, `get_campaign` and `sm_report_snapshot` send
--     `bill_market` beside `market`; `issue_letter` keeps the bill market on
--     the letter (its `market`, which the letter's figures read), and in its
--     `bill_to` the client's market and, billed in RM, the S$ rate in force;
--     `quote_fx` prices in S$ only a client billed in S$; `bukku_prepare`
--     sends the contact's currency from it.
--   * Every Singapore client stands billed in RM but one holding a report,
--     a quotation or a letter in S$ already, which keeps S$.
--
-- ORDER: this file, then the pages. A page from before reads the market as
-- before, so a Singapore client billed in RM reads S$ there until it
-- reloads. Safe to run twice. Rollback: the earlier definitions of these
-- seven functions (QUOTATION IN SINGAPORE DOLLARS's quote_fx, the last
-- get_portal, get_campaign, sm_report_snapshot, issue_letter and
-- bukku_prepare and CLIENT BILLING's clients_billing_guard before this band);
-- the column may stay.
-- ===========================================================================

alter table public.clients add column if not exists bill_sgd boolean not null default false;
grant select (bill_sgd) on table public.clients to authenticated;
grant update (bill_sgd) on table public.clients to authenticated;

-- Once: a Singapore client already holding S$ figures keeps S$ (read by
-- name, so a database without one of the three tables seeds from the rest).
do $$
declare
  v_has text := '';
begin
  if exists (select 1 from public.app_flags f where f.key = 'bill_sgd_seeded') then return; end if;
  if to_regclass('public.sm_reports') is not null then
    v_has := v_has || ' or exists (select 1 from public.sm_reports r where r.client_id = c.id)';
  end if;
  if to_regclass('public.quotations') is not null then
    v_has := v_has || ' or exists (select 1 from public.quotations q where q.client_id = c.id and q.totals ->> ''currency'' = ''SGD'')';
  end if;
  if to_regclass('public.client_documents') is not null then
    v_has := v_has || ' or exists (select 1 from public.client_documents d where d.client_id = c.id and d.market = ''SG'')';
  end if;
  if v_has <> '' then
    execute 'update public.clients c set bill_sgd = true where c.market = ''SG'' and not c.bill_sgd and (false' || v_has || ')';
  end if;
  insert into public.app_flags (key, on_now, set_by, set_at) values ('bill_sgd_seeded', true, 'migration', now()) on conflict (key) do nothing;
end $$;

create or replace function public.clients_billing_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  -- A billing contact deleted from Contacts nulls bill_contact_id by the
  -- foreign key, which is a cascade and not a person editing Billing.
  if pg_trigger_depth() > 1 then return new; end if;
  if (new.legal_name, new.company_no, new.company_no_old, new.tin, new.sst_no, new.sst_applies,
      new.bill_contact_id, new.finance_email, new.billing_address, new.bill_sgd)
     is distinct from
     (old.legal_name, old.company_no, old.company_no_old, old.tin, old.sst_no, old.sst_applies,
      old.bill_contact_id, old.finance_email, old.billing_address, old.bill_sgd)
     and not public.allowed('clients.billing', 'work') then
    raise exception 'Billing details need Clients: Billing at Work.' using errcode = '42501';
  end if;
  return new;
end $$;

create or replace function public.client_bill_market(p_market text, p_sgd boolean)
returns text
language sql immutable set search_path = public as $$
  select case when upper(coalesce(p_market, 'MY')) = 'SG' and coalesce(p_sgd, false) then 'SG' else 'MY' end
$$;

create or replace function public.get_portal(p_client uuid default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  who text := lower(auth.jwt() ->> 'email');
  cid uuid;
  cl  public.clients%rowtype;
  me  public.client_contacts%rowtype;
begin
  if who is null then return jsonb_build_object('error', 'not-signed-in'); end if;
  select p into cid from public.portal_clients() p
    order by (p = p_client) desc nulls last limit 1;
  if cid is null then return jsonb_build_object('error', 'no-access'); end if;
  select * into cl from public.clients where id = cid;
  select * into me from public.client_contacts
    where client_id = cid and portal_access and archived_at is null and lower(email) = who
    order by is_primary desc limit 1;

  return jsonb_build_object(
    'clients', coalesce((
      select jsonb_agg(jsonb_build_object('id', c.id, 'name', c.name) order by c.name)
      from public.clients c where c.id in (select public.portal_clients())), '[]'::jsonb),
    'client', jsonb_build_object(
      'id', cl.id, 'name', cl.name, 'legal_name', cl.legal_name, 'company_no', cl.company_no,
      'billing_address', cl.billing_address, 'market', coalesce(cl.market, 'MY'),
      'bill_market', public.client_bill_market(cl.market, cl.bill_sgd),
      'sst_applies', coalesce(cl.sst_applies, true), 'stage', cl.stage, 'owner', cl.owner,
      'industry', cl.industry, 'website', cl.website, 'logo_url', cl.logo_url),
    'me', jsonb_build_object('id', me.id, 'name', me.name, 'email', me.email),
    'contacts', coalesce((
      select jsonb_agg(jsonb_build_object('id', k.id, 'name', k.name, 'role', k.role, 'phone', k.phone,
        'email', k.email, 'is_primary', k.is_primary, 'portal_access', k.portal_access)
        order by k.is_primary desc, k.name)
      from public.client_contacts k where k.client_id = cid and k.archived_at is null), '[]'::jsonb),
    'services', coalesce((
      -- `term_adjust` travels with the line, because the client's page works
      -- the figure out the same way the console and the letter do and must
      -- never print a different one.
      select jsonb_agg(jsonb_build_object('id', s.id, 'label', s.label, 'unit', s.unit, 'qty', s.qty,
        'rate', s.rate, 'tenure', s.tenure, 'start_on', s.start_on, 'state', s.state, 'note', s.note,
        'term_adjust', coalesce(s.term_adjust, false), 'term_pct', s.term_pct)
        order by s.created_at)
      from public.client_services s
      where s.client_id = cid and s.archived_at is null and s.state in ('quoted', 'confirmed')), '[]'::jsonb),
    'documents', coalesce((
      select jsonb_agg(jsonb_build_object('id', d.id, 'kind', d.kind, 'number', d.number,
        'issued_at', d.issued_at, 'market', d.market, 'subtotal', d.subtotal, 'tax', d.tax,
        'total', d.total, 'bill_to', d.bill_to, 'lines', d.lines, 'issued_by', d.issued_by)
        order by d.created_at desc)
      from public.client_documents d where d.client_id = cid and d.voided_at is null), '[]'::jsonb),
    'requests', coalesce((
      select jsonb_agg(jsonb_build_object('id', r.id, 'kind', r.kind, 'service_label', r.service_label,
        'note', r.note, 'state', r.state, 'fee', r.fee, 'reply', r.reply,
        'created_at', r.created_at, 'withdrawn_at', r.withdrawn_at)
        order by r.created_at desc)
      from public.client_requests r where r.client_id = cid), '[]'::jsonb),
    'review', case
      when cl.review_hidden is not true
       and exists (select 1 from public.batches b where b.client_id = cid and b.published)
      then jsonb_build_object('token', cl.access_token) end,
    'campaigns', coalesce((
      select jsonb_agg(jsonb_build_object('id', m.id, 'title', m.title, 'title_zh', m.title_zh,
        'state', m.state, 'deadline', m.deadline, 'token', m.access_token)
        order by m.created_at desc)
      from public.campaigns m where m.client_id = cid and m.state <> 'draft'), '[]'::jsonb),
    'access', coalesce((
      select jsonb_agg(jsonb_build_object('name', k.name, 'email', k.email) order by k.is_primary desc, k.name)
      from public.client_contacts k
      where k.client_id = cid and k.archived_at is null and k.portal_access), '[]'::jsonb)
  );
end $$;

create or replace function public.get_campaign(p_token text, p_passcode text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  c campaigns%rowtype;
  cl clients%rowtype;
  billable boolean;
begin
  select * into c from campaigns where access_token = p_token;
  if not found then return jsonb_build_object('error', 'not-found'); end if;
  select * into cl from clients where id = c.client_id;
  -- A past client's links close (second audit, item 5): answered as a key
  -- nobody knows, so the page says the link is not recognised. A completed
  -- campaign stays readable for its results, read only (the user,
  -- 2026-10-18: a client moved to Past before reading them lost the link);
  -- every write on the link still refuses a Past client.
  if cl.stage = 'past' and c.state <> 'completed' then
    return jsonb_build_object('error', 'not-found');
  end if;

  -- An invoice belongs to an accepted booking. Until the client has chosen and
  -- the team has confirmed at least one creator, the number and the PDF stay
  -- off the client's page, and reverting the last confirmation takes them off
  -- it again. The gate is here rather than on the page so nothing the client
  -- can open carries what it should not show.
  select exists (
    select 1 from campaign_options o
     where o.campaign_id = c.id
       and o.state in ('confirmed', 'pending_visit', 'pending_draft', 'submitted',
                       'reviewing', 'changes', 'scheduled', 'posted', 'completed')
  ) into billable;

  -- Wrong passcodes lock out the caller who typed them, said as a lock
  -- (second audit, item 4); a passcode asked for names nobody (item 6).
  case public.link_passcode('selection', c.access_token, c.passcode, p_passcode)
    when 'locked' then return public.link_locked('selection', c.access_token);
    when 'wrong' then return jsonb_build_object('error', 'passcode');
    else null;
  end case;

  return jsonb_build_object(
    'campaign', jsonb_build_object(
      'title', c.title, 'title_zh', c.title_zh,
      'purpose', c.purpose, 'purpose_zh', c.purpose_zh, 'slots', c.slots,
      -- A Past client's completed campaign offers nothing to choose.
      'backups_open', coalesce(c.backups_open, false) and cl.stage <> 'past',
      'selection_closed', c.selection_closed_at is not null or cl.stage = 'past',
      'deadline', c.deadline, 'state', c.state, 'deliverable', c.deliverable,
      'push_format', c.push_format, 'brief', c.brief, 'brief_zh', c.brief_zh,
      'invoice_no', case when billable then c.invoice_no end,
      'invoice_url', case when billable then c.invoice_url end,
      /* The client's last confirmation: who, when, and the creators it
         named, so a page opened again says the selection was confirmed and
         asks again only once the picks differ (2026-10-14). */
      'confirmed', (
        select jsonb_build_object('person', k.person, 'at', k.created_at,
                 'selected', coalesce((select jsonb_agg(x->>'id') from jsonb_array_elements(coalesce(k.snapshot, '[]'::jsonb)) x
                                        where x->>'as' = 'shortlisted'), '[]'::jsonb))
          from campaign_confirmations k
         where k.campaign_id = c.id and k.kind = 'client'
         order by k.created_at desc limit 1)),
    -- Currency and tax travel with the campaign, because the client's page
    -- prints both and must not assume Malaysia.
    'client', jsonb_build_object('name', cl.name, 'logo_url', cl.logo_url,
      'market', coalesce(cl.market, 'MY'), 'bill_market', public.client_bill_market(cl.market, cl.bill_sgd), 'sst_applies', coalesce(cl.sst_applies, true)),
    /* A draft reaches the client when the team releases it, and not a moment
       before. `submitted` is the team's own step, so it is reported as
       `pending_draft`: the client is not asked to approve something they
       cannot open, and does not learn that a round exists. A `changes` the
       team raised is the same round going back to the creator, so it is
       withheld the same way; a `changes` the client raised is their own and
       is reported as it is. The mapping is here and not on the page, because
       what a client may not see is withheld by this function. */
    'options', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', o.id, 'name', cr.name,
        'rate', o.rate, 'platforms', o.platforms, 'state', s.shown,
        'is_replacement', o.is_replacement, 'added_at', o.added_at,
        -- Production. Present once a creator is locked; null before that, so
        -- the page can tell "not started" from "nothing to say".
        'visit_date', o.visit_date, 'visit_time', o.visit_time,
        'visit_location', o.visit_location, 'visit_pic', o.visit_pic,
        'visit_pic_phone', o.visit_pic_phone, 'tracking_no', o.tracking_no,
        'draft_url', case when s.released then o.draft_url end,
        /* The client's own rounds: a round the team sent back, or a request
           taken back, is not one the client made (2026-09-27). */
        'revision_round', (select count(*) from public.option_reviews r
                            where r.option_id = o.id and r.source = 'client'
                              and r.decision = 'changes' and r.undone_at is null)::int + 1,
        'planned_publish', o.planned_publish,
        /* What the creator uploaded, once it has been released: the round
           the team last released (`released_round`, stamped at release), so
           a creator's next round, uploaded after the client asked for
           changes, stays with the team until it is released in its turn
           (audit S5, 2026-10-10). A file hidden after the client's approval
           is never sent (audit S6). */
        'files', case when s.released then coalesce((
            select jsonb_agg(jsonb_build_object(
              'id', d.id, 'url', d.url, 'name', d.name, 'kind', d.kind,
              'bytes', d.bytes) order by d.uploaded_at)
            from campaign_deliverables d
            where d.option_id = o.id and d.removed_at is null and d.hidden_at is null
              and d.round = coalesce(o.released_round,
                            (select max(d2.round) from campaign_deliverables d2
                              where d2.option_id = o.id and d2.removed_at is null))
          ), '[]'::jsonb) else '[]'::jsonb end,
        -- The caption is part of what is being approved, so it travels with
        -- the files and is withheld with them.
        'caption', case when s.released then o.draft_caption end,
        'profiles', coalesce((
          select jsonb_agg(jsonb_build_object('platform', p.platform, 'url', p.url))
          from creator_profiles p where p.creator_id = cr.id), '[]'::jsonb),
        -- One row per platform posted on, so two placements stay two numbers.
        'posts', coalesce((
          select jsonb_agg(jsonb_build_object(
            'platform', pp.platform, 'post_url', pp.post_url,
            'published_at', pp.published_at, 'window_days', pp.window_days,
            'impressions', pp.impressions, 'engagements', pp.engagements,
            'views', pp.views, 'measured_at', pp.measured_at) order by pp.platform)
          from option_posts pp where pp.option_id = o.id), '[]'::jsonb),
        /* What was last decided, so the card can say who approved it and
           when rather than jumping to the next step with nothing to show for
           the decision. The client's own decisions, and an approval the team
           gave on the client's behalf (`by_team`, read "Proceeded by"); a
           team send-back stays withheld. Withheld with the draft it is about. */
        'review', case when s.released then (
            select jsonb_build_object('decision', r.decision, 'reviewer', r.reviewer,
                                      'note', case when r.source = 'client' then r.note end,
                                      'at', r.created_at, 'by_team', r.source = 'team')
            from option_reviews r where r.option_id = o.id
              and (r.source = 'client' or r.decision = 'approved') and r.undone_at is null
            order by r.created_at desc limit 1) end)
        order by o.position, o.added_at)
      from campaign_options o
      join creators cr on cr.id = o.creator_id
      cross join lateral (
        select sh.shown,
               sh.shown in ('reviewing', 'changes', 'scheduled', 'posted', 'completed')
                 as released
        from (select case
                       when o.state = 'submitted' then 'pending_draft'
                       when o.state = 'changes'
                            and coalesce(o.changes_by, 'client') = 'team' then 'pending_draft'
                       else o.state
                     end as shown) sh
      ) s
      where o.campaign_id = c.id and o.state <> 'replaced'), '[]'::jsonb)
  );
end $$;

create or replace function public.sm_report_snapshot(p_id uuid, p_final boolean default false)
returns jsonb
language plpgsql security definer stable set search_path = public as $$
declare
  r public.sm_reports;
  c public.clients;
begin
  if not public.allowed('reports', 'view') and not public.allowed('clients', 'view') then
    return jsonb_build_object('error', 'denied');
  end if;
  select * into r from public.sm_reports where id = p_id;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if not public.client_seen(r.client_id, 'view') then return jsonb_build_object('error', 'denied'); end if;
  -- Somebody who reads Clients but not Reports reads the finished report
  -- only: once it is confirmed, never while it is being prepared.
  if not public.allowed('reports', 'view') and r.status not in ('confirmed', 'published') then
    return jsonb_build_object('error', 'denied');
  end if;
  select * into c from public.clients where id = r.client_id;
  return jsonb_build_object(
    'report', jsonb_build_object(
      -- A white-label report names the brand it covers, with no client logo.
      'id', r.id, 'kind', r.kind, 'title', r.title, 'client_name', coalesce(r.brand_name, c.name),
      'client_logo_url', case when r.brand_name is null then c.logo_url end,
      'market', to_jsonb(c) ->> 'market', 'bill_market', public.client_bill_market(to_jsonb(c) ->> 'market', (to_jsonb(c) ->> 'bill_sgd')::boolean), 'lang', r.lang,
      'period_start', r.period_start, 'period_end', r.period_end,
      'headline', r.headline, 'intro', r.intro, 'insights', r.insights, 'rank_metric', r.rank_metric,
      'first_month', r.first_month, 'ads_totals', r.ads_totals,
      'status', case when p_final then 'final' else r.status end,
      'version_no', r.version_no, 'generated_at', now(),
      'prepared_by_name', (select name from public.team_members where id = r.submitted_by),
      -- The white-label client's wide logo while it is still ticked and the
      -- report's brand takes it (2026-10-07); else ADspace's own mark.
      'partner', (select jsonb_build_object('name', l.name, 'logo', l.report_logo)
                    from public.clients l where l.id = r.label_client and l.white_label
                     and coalesce((select b.logo from public.client_brands b where b.id = r.brand_id), 'partner') = 'partner')),
    'platforms', coalesce((select jsonb_agg(to_jsonb(p) - 'created_at' order by p.position, p.created_at)
                  from public.sm_report_platforms p where p.report_id = r.id), '[]'::jsonb),
    'posts', coalesce((select jsonb_agg((to_jsonb(q) - 'created_at' - 'thumb_data') || jsonb_build_object('thumb_url', q.thumb_data)
                  order by q.posted_on nulls last, q.position, q.created_at)
                  from public.sm_report_posts q where q.report_id = r.id), '[]'::jsonb),
    'ads', coalesce((select jsonb_agg((to_jsonb(a) - 'created_at' - 'thumb_data') || jsonb_build_object('thumb_url', a.thumb_data)
                  order by a.position, a.created_at)
                  from public.sm_report_ads a where a.report_id = r.id), '[]'::jsonb));
end $$;
grant execute on function public.sm_report_snapshot(uuid, boolean) to authenticated;

create or replace function public.issue_letter(
  p_client    uuid,
  p_services  uuid[],
  p_idem      text,
  p_subtotal  numeric,
  p_tax       numeric,
  p_total     numeric,
  p_deal      jsonb   default '{}'::jsonb,
  p_replaces  uuid    default null,
  p_renewal   boolean default false,
  /* A reference somebody typed. Blank is the ordinary case and the counter
     below makes the number; where one is typed it is checked against every
     document that stands and the counter is not advanced, so filling a gap
     by hand never costs the next letter its place in the sequence. */
  p_serial    text    default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  who    text := lower(auth.jwt() ->> 'email');
  cl     public.clients%rowtype;
  ct     public.client_contacts%rowtype;
  me     public.team_members%rowtype;
  v_ym   text;
  v_seq  int;
  v_try  int;
  v_no   text;
  v_id   uuid;
  v_lines jsonb;
  v_n    int;
  v_bad  int;
  v_old  public.client_documents%rowtype;
  v_term int;
  v_each numeric;
  v_etax numeric;
  v_once numeric;
  v_otax numeric;
  v_sub  numeric;
  v_tax  numeric;
  v_tot  numeric;
  v_pct  numeric;
  v_qid  uuid;
  v_q    public.quotations%rowtype;
  v_tp   numeric;
  v_tpn  int;
  v_tadj boolean;
  v_qterm int;
  v_msub numeric;
  v_span numeric;
  v_even boolean;
  v_qt   jsonb;
  v_month boolean;
begin
  if not public.allowed('clients.documents') then
    return jsonb_build_object('error', 'not-allowed');
  end if;
  if p_client is null or p_services is null or array_length(p_services, 1) is null then
    return jsonb_build_object('error', 'no-lines');
  end if;

  select * into cl from public.clients where id = p_client;
  if cl.id is null then return jsonb_build_object('error', 'no-client'); end if;

  -- The Client ID is what the serial is built from, so there is no letter
  -- without one. Staff enter it on the record; nothing invents it. A typed
  -- reference needs no code, because nothing is being built.
  v_no := nullif(btrim(coalesce(p_serial, '')), '');
  if v_no is null and coalesce(btrim(cl.client_code), '') = '' then
    return jsonb_build_object('error', 'no-client-code');
  end if;

  -- The same submission, pressed twice, is one letter. Answered before any
  -- number is reserved, so a double click cannot spend a serial either.
  if coalesce(btrim(p_idem), '') <> '' then
    select * into v_old from public.client_documents
      where client_id = p_client and idem_key = btrim(p_idem) limit 1;
    if v_old.id is not null then
      return jsonb_build_object('ok', true, 'repeat', true, 'id', v_old.id, 'number', v_old.number);
    end if;
  end if;

  -- A typed reference is checked before anything is written: the same shape
  -- the Register accepts, and refused where a document still holds it.
  if v_no is not null then
    if v_no !~ '^[A-Za-z0-9/._-]{3,40}$' then
      return jsonb_build_object('error', 'serial-shape');
    end if;
    if public.serial_taken(v_no) then
      return jsonb_build_object('error', 'serial-taken');
    end if;
  end if;

  -- Every id must be this client's own live line, and in a state this letter
  -- may carry: To quote always, Confirmed only on a deliberate renewal.
  select count(*) into v_bad from unnest(p_services) s(id)
    left join public.client_services cs
      on cs.id = s.id and cs.client_id = p_client and cs.archived_at is null
    where cs.id is null
       or (cs.state = 'confirmed' and not p_renewal)
       or cs.state not in ('quoted', 'confirmed');
  if v_bad > 0 then return jsonb_build_object('error', 'bad-lines'); end if;

  -- A line already on a live letter is not offered again by accident. The way
  -- through is to void that letter, or to name it as the one being replaced.
  select count(*) into v_bad
    from public.client_document_services m
    join public.client_documents d on d.id = m.document_id
   where m.service_id = any(p_services)
     and d.voided_at is null
     and d.superseded_by is null
     and d.verified_at is null
     and (p_replaces is null or d.id <> p_replaces);
  if v_bad > 0 then return jsonb_build_object('error', 'already-quoted'); end if;

  if p_replaces is not null then
    select * into v_old from public.client_documents
      where id = p_replaces and client_id = p_client;
    if v_old.id is null then return jsonb_build_object('error', 'no-replaces'); end if;
    if v_old.verified_at is not null then return jsonb_build_object('error', 'replaces-verified'); end if;
  end if;

  select * into ct from public.client_contacts
    where client_id = p_client and archived_at is null
    order by (id = cl.bill_contact_id) desc, is_primary desc, name limit 1;
  select * into me from public.team_members where lower(email) = who and active limit 1;

  -- A letter is signed by a person. issued_by is this row's name, so a team
  -- row named "Superadmin" printed that word under ADSPACE PLT on a client's
  -- letterhead. Refuse rather than draw a permission as a signatory.
  if not public.issuer_name_ok(me.name) then
    return jsonb_build_object('error', 'issuer-name', 'name', coalesce(me.name, ''));
  end if;

  -- The snapshot is built from the stored rows, never from what the browser
  -- sent: the words on a letter are the words the record held at that moment.
  select jsonb_agg(jsonb_build_object(
           'label', cs.label, 'unit', coalesce(cs.unit, ''), 'note', coalesce(cs.note, ''),
           'detail', coalesce(cs.detail, ''), 'state', cs.state,
           'qty', cs.qty, 'rate', cs.rate,
           'tenure', greatest(1, coalesce(cs.tenure, 1)),
           'start_on', coalesce(cs.start_on, ''),
           -- The line's own answer to whether its term prices it. Written into
           -- the snapshot because the letter is redrawn from it, and a letter
           -- must print the same figure every time it is drawn. A snapshot
           -- taken before this key existed carries none, which money.js reads
           -- as on, so those letters redraw as they were issued.
           'term_adjust', coalesce(cs.term_adjust, false),
           -- And the percentage that tick applies, so a later rate card can
           -- never move a figure this letter printed. Null on a line quoted
           -- before the column existed, which money.js reads as that card.
           'term_pct', cs.term_pct,
           'tax', cl.sst_applies is not false,
           -- The line's own tax code and its rate as issued (2026-10-22);
           -- none is the client's SST, as before.
           'tax_code', cs.tax_code,
           'tax_pct', (select t.rate from public.tax_codes t where t.code = cs.tax_code),
           'service_id', cs.id)
           order by cs.created_at)
    into v_lines
    from public.client_services cs
   where cs.id = any(p_services);
  if v_lines is null then return jsonb_build_object('error', 'no-lines'); end if;
  /* A line's tax code is one the team holds and offers (2026-10-22). */
  if exists (select 1 from public.client_services cs
              where cs.id = any(p_services) and cs.tax_code is not null
                and not exists (select 1 from public.tax_codes t where t.code = cs.tax_code and t.active)) then
    return jsonb_build_object('error', 'bad-tax');
  end if;

  /* The price is the database's (audit S4, 2026-10-10), worked as the
     letter draws it (js/documents.js priceOf, js/money.js rateFor): each
     line's rate with its term on it, rounded to the cent. Where every line
     of more than a month shares one term, those lines are priced by the
     month and times the term, and a line of one month is a one-off item
     with its own SST (2026-10-15: a one-off item beside them no longer
     turns the letter into one whole total); otherwise every line is its
     whole amount. SST at the rate in force today unless the client is
     exempt. The page's figures are kept only where they agree to the sen,
     so a line changed since the sheet opened, or a figure typed in a
     browser, is refused (`stale`) and the sheet reads the lines again. */
  select case when count(distinct greatest(1, coalesce(cs.tenure, 1)))
                     filter (where greatest(1, coalesce(cs.tenure, 1)) > 1) = 1
              then max(greatest(1, coalesce(cs.tenure, 1))) else 0 end
    into v_term
    from public.client_services cs where cs.id = any(p_services);
  /* A letter whose every line came from one quotation is priced as that
     quotation was (audit F, 2026-10-17), exactly as `quote_price` and
     `quote_adjust` total it (2026-10-17, the review's finding 7): a line
     the quotation bills by the month (`quotation_offer` ticks its term) is
     a monthly line whatever months Build quote gave it, its percentage
     taken once on their subtotal; a line with no term is one-off; SST at
     the quotation's rate. The page's figures are held to the same price
     (js/documents.js priceOf). */
  select case when count(*) filter (where cs.quotation_id is null) = 0
                   and count(distinct cs.quotation_id) = 1 then min(cs.quotation_id::text)::uuid end,
         count(distinct coalesce(cs.term_pct, 0)) filter (where coalesce(cs.term_adjust, false)),
         coalesce(bool_and(greatest(1, coalesce(cs.tenure, 1)) = 1) filter (where not coalesce(cs.term_adjust, false)), true),
         coalesce(max(cs.term_pct) filter (where coalesce(cs.term_adjust, false)), 0)
    into v_qid, v_tpn, v_tadj, v_tp
    from public.client_services cs where cs.id = any(p_services);
  /* Only while the quotation still stands (2026-10-17, the review's
     finding 2): unexpired by Malaysia's day and not removed. A renewal, or a
     letter replacing one after the quotation lapsed, is priced on today's
     rates, as any other letter. */
  if v_qid is not null and coalesce(v_tpn, 0) <= 1 and v_tadj and not coalesce(p_renewal, false) then
    select * into v_q from public.quotations q
     where q.id = v_qid and q.removed_at is null
       and q.valid_until >= (timezone('Asia/Kuala_Lumpur', now()))::date;
  end if;
  if v_q.id is not null then
    /* As quote_adjust totals it: the monthly lines' subtotal of quantity ×
       rate, the percentage once on it; where every one runs the quotation's
       term, a month's excl. SST, its SST rounded once, times the term; where
       Build quote gave a line months of its own, the whole span (each line's
       amount × its months) with the percentage and SST taken once on it.
       One-off lines and their SST apart. */
    v_qterm := greatest(1, coalesce((v_q.totals->>'term')::int, 1));
    v_pct := case when cl.sst_applies is false then 0
                  else coalesce((v_q.totals->>'sst_pct')::numeric, 0) end;
    /* The lines as the quotation reads them (a line with its term ticked is
       monthly, on its own months), totalled by the one calculation every
       quotation shares (2026-10-18). */
    v_qt := public.quote_totals(
      (select coalesce(jsonb_agg(jsonb_build_object(
                'basis', case when coalesce(cs.term_adjust, false) then 'month' else 'once' end,
                'qty', coalesce(cs.qty, 0), 'rate', coalesce(cs.rate, 0),
                'months', greatest(1, coalesce(cs.tenure, 1)),
                'sst', (select t.rate from public.tax_codes t where t.code = cs.tax_code))), '[]'::jsonb)
         from public.client_services cs where cs.id = any(p_services)),
      v_qterm, v_tp, v_pct);
    v_month := jsonb_typeof(v_qt->'month') = 'object';
    v_once := coalesce((v_qt->'once'->>'subtotal')::numeric, 0);
    v_otax := coalesce((v_qt->'once'->>'sst')::numeric, 0);
    if not v_month then
      v_sub := round(v_once, 2);
      v_tax := v_otax;
    elsif (v_qt->>'even')::boolean then
      v_each := (v_qt->'month'->>'excl')::numeric;
      v_etax := (v_qt->'month'->>'sst')::numeric;
      v_sub := round(v_each * v_qterm + v_once, 2);
      v_tax := v_etax * v_qterm + v_otax;
    else
      v_sub := (v_qt->>'span_excl')::numeric + round(v_once, 2);
      v_tax := (v_qt->>'span_incl')::numeric + round(v_once, 2) + v_otax - v_sub;
    end if;
    v_tot := v_sub + v_tax;
    /* The letter keeps what it was priced on, so a redraw prints the same:
       the quotation, its SST and its term (a snapshot with no `quote_term`
       was priced before this, and redraws as it was). */
    select jsonb_agg(l.e || jsonb_build_object('quotation_id', v_qid, 'quote_sst', v_pct, 'quote_term', v_qterm) order by l.n)
      into v_lines from jsonb_array_elements(v_lines) with ordinality l(e, n);
  else
    v_pct := case when cl.sst_applies is false then 0
                  else coalesce(public.app_setting('sst_pct', (timezone('Asia/Kuala_Lumpur', now()))::date), 0) end;
    /* Each line at its own SST rate (2026-10-22): its tax code's, else the
       client's. The SST is worked a rate at a time, rounded once each, so
       a letter on one rate prices as it always did. */
    with x as (
      select greatest(1, coalesce(cs.tenure, 1)) as n,
             coalesce(cs.qty, 0) *
             round(coalesce(cs.rate, 0) *
               case when cs.term_adjust is false then 1
                    when cs.term_pct is not null then 1 + cs.term_pct / 100
                    else case greatest(1, coalesce(cs.tenure, 1))
                           when 3 then 1 / 0.9 when 12 then 0.95 when 24 then 0.9 else 1 end
               end, 2) as v,
             coalesce((select t.rate from public.tax_codes t where t.code = cs.tax_code), v_pct) as r
        from public.client_services cs where cs.id = any(p_services)
    ), y as (
      select r,
             coalesce(sum(v) filter (where v_term > 0 and n = v_term), 0) as e,
             coalesce(sum(v * n) filter (where v_term = 0 or n <> v_term), 0) as o
        from x group by r
    )
    select coalesce(sum(e), 0), coalesce(sum(o), 0),
           coalesce(sum(round(e * r) / 100), 0), coalesce(sum(round(o * r) / 100), 0)
      into v_each, v_once, v_etax, v_otax
      from y;
    v_sub := round(v_each * greatest(v_term, 1), 2) + round(v_once, 2);
    v_tax := round(v_etax * greatest(v_term, 1), 2) + v_otax;
    v_tot := round(round(v_each + v_etax, 2) * greatest(v_term, 1), 2) + round(v_once + v_otax, 2);
  end if;
  if abs(coalesce(p_subtotal, -1) - v_sub) > 0.01 or abs(coalesce(p_tax, -1) - v_tax) > 0.01
     or abs(coalesce(p_total, -1) - v_tot) > 0.01 then
    return jsonb_build_object('error', 'stale', 'subtotal', v_sub, 'tax', v_tax, 'total', v_tot);
  end if;

  -- A typed reference spends no sequence number: the counter is the office's
  -- record of how many letters it has issued this month, and a person filling
  -- a gap by hand has not issued one more.
  if v_no is null then
    -- The month is Malaysian, because the office that numbers the letter is.
    v_ym := to_char(timezone('Asia/Kuala_Lumpur', now()), 'YYMM');

    -- The counter still advances on every automatic issue, and the upsert's
    -- row lock is what makes the scan below safe: a second issuer blocks here
    -- until the first has committed its letter, so the two never read the same
    -- gap as free. What the counter gives is a bound to scan within, not the
    -- number itself.
    insert into public.client_document_seq (client_id, ym, next_val)
         values (p_client, v_ym, 2)
    on conflict (client_id, ym)
      do update set next_val = public.client_document_seq.next_val + 1
      returning next_val - 1 into v_seq;

    -- The lowest free slot, not the counter's own value. A deleted letter
    -- releases its reference (serial_taken stopped counting deletions on
    -- 2026-09-20), and without this the automatic path still counted upward
    -- past the gap: a client whose first two letters were issued in testing
    -- and deleted started at 03 for ever. The counter is at least the number
    -- of letters issued this month, so a free slot exists at or below it
    -- unless somebody has typed references over the same range by hand; the
    -- cap covers that and refuses rather than looping.
    --
    -- Two digits is the floor, not the ceiling: the hundredth letter of a month
    -- widens to three rather than wrapping. Not lpad(): Postgres pads AND
    -- truncates to the width it is given, so lpad('100', 2, '0') is '10' and the
    -- hundredth letter would collide with the tenth.
    v_try := 1;
    loop
      v_no := 'AQL/' || cl.client_code || '/' || v_ym ||
              case when v_try < 100 then lpad(v_try::text, 2, '0') else v_try::text end;
      exit when not public.serial_taken(v_no);
      v_try := v_try + 1;
      if v_try > greatest(v_seq, 1) + 200 then
        return jsonb_build_object('error', 'no-serial');
      end if;
    end loop;
  end if;

  insert into public.client_documents
    (client_id, kind, number, issued_at, market, subtotal, tax, total,
     bill_to, lines, issued_by, client_code, idem_key)
  values
    (p_client, 'offer', v_no, (timezone('Asia/Kuala_Lumpur', now()))::date,
     public.client_bill_market(cl.market, cl.bill_sgd),
     round(coalesce(p_subtotal, 0), 2), round(coalesce(p_tax, 0), 2), round(coalesce(p_total, 0), 2),
     jsonb_build_object(
       'name', coalesce(cl.name, ''), 'legal_name', coalesce(cl.legal_name, ''),
       'address', coalesce(cl.billing_address, ''), 'regno', coalesce(cl.company_no, ''),
       'regno_old', coalesce(cl.company_no_old, ''), 'tin', coalesce(cl.tin, ''),
       'sst_no', coalesce(cl.sst_no, ''), 'sst_applies', cl.sst_applies is not false,
       'contact', coalesce(ct.name, ''), 'contact_role', coalesce(ct.role, ''),
       'contact_salutation', coalesce(ct.salutation, ''),
       -- A Singapore client billed in RM: its market and the rate in force,
       -- so the letter reads its figure in S$ beside it, as issued.
       'market', coalesce(cl.market, 'MY'),
       'fx_sgd', case when cl.market = 'SG' and not cl.bill_sgd then public.app_setting('fx_sgd', (timezone('Asia/Kuala_Lumpur', now()))::date) end,
       'phone', coalesce(ct.phone, ''), 'email', coalesce(ct.email, ''),
       'finance_email', coalesce(cl.finance_email, ''),
       'client_code', cl.client_code,
       'owner', coalesce(p_deal ->> 'owner', ''), 'source', coalesce(p_deal ->> 'source', ''),
       'industry', coalesce(p_deal ->> 'industry', ''), 'stage', coalesce(p_deal ->> 'stage', ''),
       'enquiry', coalesce(p_deal ->> 'enquiry', '')),
     v_lines, coalesce(me.name, who), cl.client_code, nullif(btrim(p_idem), ''))
  returning id into v_id;

  insert into public.client_document_services (document_id, service_id)
    select v_id, s.id from unnest(p_services) s(id)
    on conflict do nothing;

  if p_replaces is not null then
    update public.client_documents set superseded_by = v_id where id = p_replaces;
    insert into public.activity_log (actor, action, subject, detail)
    values (who, 'document.superseded', cl.name, v_old.number || ' replaced by ' || v_no);
  end if;

  select count(*) into v_n from public.client_document_services where document_id = v_id;
  insert into public.activity_log (actor, action, subject, detail)
  values (who, 'document.issued', cl.name, v_no || ' · ' || v_n || ' line' || case when v_n = 1 then '' else 's' end);

  return jsonb_build_object('ok', true, 'id', v_id, 'number', v_no);
exception
  when unique_violation then
    -- Two presses that raced past the idempotency read: the loser reads the
    -- winner's letter back rather than making a second one.
    if coalesce(btrim(p_idem), '') <> '' then
      select * into v_old from public.client_documents
        where client_id = p_client and idem_key = btrim(p_idem) limit 1;
      if v_old.id is not null then
        return jsonb_build_object('ok', true, 'repeat', true, 'id', v_old.id, 'number', v_old.number);
      end if;
    end if;
    -- A typed reference two people sent at once: the loser is told the
    -- reference is spent rather than that "two letters were issued at once",
    -- which names a cause they cannot act on.
    if nullif(btrim(coalesce(p_serial, '')), '') is not null then
      return jsonb_build_object('error', 'serial-taken');
    end if;
    return jsonb_build_object('error', 'clash');
end $$;

create or replace function public.quote_fx(p_client uuid)
returns numeric
language sql stable security definer set search_path = public as $$
  select case when exists (select 1 from public.clients c where c.id = p_client and c.market = 'SG' and c.bill_sgd)
              then coalesce(nullif(public.app_setting('fx_sgd', (now() at time zone 'Asia/Kuala_Lumpur')::date), 0), 0) end
$$;
revoke all on function public.quote_fx(uuid) from public, anon, authenticated;

create or replace function public.bukku_prepare(p_kind text, p_id uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  c public.clients; s public.suppliers; ct public.client_contacts;
  l public.bukku_links; b public.bukku_settings;
  v_missing text[] := '{}'; v_company boolean; v_id text; v_field bigint; v_pay boolean;
  v_person text; v_out jsonb;
begin
  if not public.bukku_may(p_kind, p_id, 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into b from public.bukku_settings where id = 1;
  if p_kind = 'client' then
    select * into c from public.clients x where x.id = p_id;
    if c.id is null then return jsonb_build_object('error', 'not-found'); end if;
    select * into ct from public.client_contacts x
     where x.id = c.bill_contact_id and x.archived_at is null;
    if ct.id is null then
      select * into ct from public.client_contacts x where x.client_id = c.id and x.is_primary and x.archived_at is null;
    end if;
    if coalesce(btrim(c.legal_name), '') = '' then v_missing := v_missing || 'Registered name'::text; end if;
    if coalesce(btrim(c.client_code), '') = '' then v_missing := v_missing || 'Client ID'::text; end if;
    if array_length(v_missing, 1) > 0 then return jsonb_build_object('error', 'incomplete', 'missing', to_jsonb(v_missing)); end if;
    select * into l from public.bukku_links x where x.kind = 'client' and x.record_id = c.id;
    v_person := btrim(coalesce(ct.name, ''));
    return jsonb_build_object('ok', true, 'kind', 'client', 'id', c.id,
      'legal_name', public.bukku_name_case(c.legal_name, true), 'other_name', c.name,
      'entity_type', case when c.market = 'SG' then 'FOREIGN_COMPANY' else 'MALAYSIAN_COMPANY' end,
      'reg_no_type', case when nullif(regexp_replace(coalesce(c.company_no, ''), '[^0-9A-Za-z]', '', 'g'), '') is null then null else 'BRN' end,
      'reg_no', nullif(regexp_replace(coalesce(c.company_no, ''), '[^0-9A-Za-z]', '', 'g'), ''),
      'old_reg_no', nullif(btrim(coalesce(c.company_no_old, '')), ''),
      'tax_id_no', nullif(btrim(coalesce(c.tin, '')), ''), 'sst_reg_no', nullif(btrim(coalesce(c.sst_no, '')), ''),
      'email', nullif(btrim(coalesce(c.finance_email, ct.email, '')), ''),
      'phone_no', public.wa_number(coalesce(ct.phone, ct.whatsapp), coalesce(c.market, 'MY')),
      'address', nullif(btrim(coalesce(c.billing_address, '')), ''),
      'country', case when c.market = 'SG' then 'SG' else 'MY' end,
      'currency', case when public.client_bill_market(c.market, c.bill_sgd) = 'SG' then 'SGD' else 'MYR' end,
      'person', nullif(public.bukku_name_case(v_person, false), ''),
      'salutation', nullif(btrim(coalesce(ct.salutation, '')), ''),
      'our_id', c.client_code, 'field_id', b.field_client, 'type', 'customer',
      'contact_id', l.contact_id);
  elsif p_kind = 'supplier' then
    select * into s from public.suppliers x where x.id = p_id;
    if s.id is null then return jsonb_build_object('error', 'not-found'); end if;
    if s.status <> 'active' then return jsonb_build_object('error', 'not-active'); end if;
    v_company := coalesce(s.kind, 'company') = 'company';
    v_pay := public.ops_granted('suppliers.pay', 'view');
    select * into l from public.bukku_links x where x.kind = 'supplier' and x.record_id = s.id;
    if l.contact_id is null and s.client_id is not null then
      select * into l from public.bukku_links x where x.kind = 'client' and x.record_id = s.client_id;
    end if;
    return jsonb_build_object('ok', true, 'kind', 'supplier', 'id', s.id,
      'legal_name', public.bukku_name_case(s.name, v_company),
      'entity_type', case when s.currency = 'SGD' then (case when v_company then 'FOREIGN_COMPANY' else 'FOREIGN_INDIVIDUAL' end)
                          else (case when v_company then 'MALAYSIAN_COMPANY' else 'MALAYSIAN_INDIVIDUAL' end) end,
      'reg_no_type', case when v_company and s.brn is not null then 'BRN' when not v_company and v_pay and s.nric is not null then 'NRIC' end,
      'reg_no', case when v_company then s.brn when v_pay then regexp_replace(coalesce(s.nric, ''), '[^0-9]', '', 'g') end,
      'tax_id_no', s.tin, 'sst_reg_no', s.sst_no,
      'email', coalesce(s.finance_email, s.email),
      'phone_no', public.wa_number(coalesce(s.mobile, s.phone), case when s.currency = 'SGD' then 'SG' else 'MY' end),
      'address', s.address, 'country', case when s.currency = 'SGD' then 'SG' else 'MY' end,
      'currency', s.currency,
      'person', public.bukku_name_case(coalesce(s.contact_name, case when not v_company then s.name end), false),
      'payment_term', s.payment_term,
      'our_id', s.code, 'field_id', b.field_supplier, 'type', 'supplier',
      'client_id', s.client_id, 'contact_id', l.contact_id);
  end if;
  return jsonb_build_object('error', 'bad-kind');
end $$;
revoke all on function public.bukku_prepare(text, uuid) from public, anon;
grant execute on function public.bukku_prepare(text, uuid) to authenticated;

-- END OF BILL IN RM OR S$ -----------------------------------------------------

-- ===========================================================================
-- A MONTH'S LATE WORK READS AS MY WORK READS IT — the client record's
-- Engagements and its month line count overdue tasks by My Work's own rule
-- (2026-10-22)
-- ===========================================================================
-- WHY (audit 2026-10-22, CLI-2; the user: "Fix all"): the record counted a
-- task late once its final date had passed, whatever its stage, from its
-- own read of the reader's tasks; My Work calls it late only while it is
-- short of client review, or past a priority's deadline and short of its
-- review. A task at Client review past its date read "1 overdue" on the
-- client and on time in My Work.
--
-- WHAT IT CHANGES
--   * `ops_task_late(p_task)`: whether a task is late now, by the rule
--     `ops_report`'s WHAT IS LATE states (and `isLate()` in js/ops.js):
--     open, and past its final date (Malaysian days) while short of its
--     workflow's client review, or past its priority's deadline while short
--     of its review (On hold and Blocked still count). Internal: revoked
--     from every caller; functions alone ask it.
--   * `ops_engagement_counts` adds `late`: the month's open tasks late by
--     that rule, over the whole month whoever asks, as its other counts.
--     The page reads it and no longer reads the month's tasks itself.
--
-- ORDER: this file, then the pages. An old page ignores `late` and keeps
-- its own read. Safe to run twice. Mirrored byte for byte in schema.sql.
-- ROLLBACK: run the MONTH COUNTS LEAVE REPORTS OUT section's
-- ops_engagement_counts again, then
--   drop function if exists public.ops_task_late(uuid);
-- ===========================================================================

create or replace function public.ops_task_late(p_task uuid)
returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce((
    select
      (t.current_final_due_at is not null
        and (t.current_final_due_at at time zone 'Asia/Kuala_Lumpur')::date
            < (now() at time zone 'Asia/Kuala_Lumpur')::date
        and (f.at is null or s.position < f.at))
      or
      (p.by is not null and p.by < now()
        and (pf.at is null or s.position < pf.at or s.stage_group in ('kiv', 'blocked')))
      from public.ops_tasks t
      join public.ops_workflow_stages s
        on s.workflow_id = t.workflow_id and s.key = t.stage_key
      cross join lateral (
        select public.ops_priority_by(coalesce(t.priority_at, t.created_at), t.priority_level) as by) p
      cross join lateral (
        select min(w.position) as at from public.ops_workflow_stages w
         where w.workflow_id = t.workflow_id and w.stage_group = 'client_review') f
      cross join lateral (
        select coalesce(min(w.position) filter (where w.stage_group = 'client_review'),
                        min(w.position) filter (where w.stage_group = 'internal_review')) as at
          from public.ops_workflow_stages w where w.workflow_id = t.workflow_id) pf
     where t.id = p_task
       and t.completed_at is null and t.cancelled_at is null and t.archived_at is null
  ), false)
$$;
revoke all on function public.ops_task_late(uuid) from public, anon, authenticated;

/* A month's tasks, counted over the whole month whoever asks: live (not
   cancelled), open (not finished), done (completed), content (live, less
   the report tasks the month makes for itself), and late (open, and late by
   My Work's rule, `ops_task_late`). Only months the caller may see answer. */
create or replace function public.ops_engagement_counts(p_engagements uuid[])
returns jsonb
language sql security definer stable set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'engagement_id', e.id,
           'live', (select count(*) from public.ops_tasks t
                     where t.engagement_id = e.id and t.archived_at is null
                       and t.cancelled_at is null),
           'open', (select count(*) from public.ops_tasks t
                     where t.engagement_id = e.id and t.archived_at is null
                       and t.cancelled_at is null and t.completed_at is null),
           'done', (select count(*) from public.ops_tasks t
                     where t.engagement_id = e.id and t.archived_at is null
                       and t.cancelled_at is null and t.completed_at is not null),
           'content', (select count(*) from public.ops_tasks t
                        where t.engagement_id = e.id and t.archived_at is null
                          and t.cancelled_at is null
                          and coalesce(t.source_type, '') not in ('report_social', 'report_ads')),
           'late', (select count(*) from public.ops_tasks t
                     where t.engagement_id = e.id and t.archived_at is null
                       and t.cancelled_at is null and t.completed_at is null
                       and public.ops_task_late(t.id)))), '[]'::jsonb)
    from public.ops_engagements e
   where e.id = any (coalesce(p_engagements, '{}'::uuid[]))
     and public.ops_may_see_engagement(e.id)
$$;
revoke all on function public.ops_engagement_counts(uuid[]) from public, anon;
grant execute on function public.ops_engagement_counts(uuid[]) to authenticated;

-- END OF A MONTH'S LATE WORK READS AS MY WORK READS IT -----------------------

-- ===========================================================================
-- BACKEND REVIEW HOLDS — the security and data findings of the 2026-10-22
-- backend review (the user, 2026-10-22: "Fix all"). 2026-10-22. Safe to run
-- twice. Rollback at the foot. Mirrored byte for byte in supabase/schema.sql
-- under the same banner; tests/sql.js compares the two.
--
-- WHAT CHANGED
--   SEC-1. Every guard that held an update holds an insert too
--     (`clients_billing_guard`, `clients_active_billing`,
--     `clients_white_label_guard`, `clients_brand_guard`,
--     `campaigns_finance_guard`, `campaign_deliverables_guard`): a page
--     inserting a client with billing, an Active stage, white label or a
--     brief, a campaign with its invoice, or a file already hidden, is
--     refused as the same update would be.
--   BE-2. A Bukku contact is linked to one record (`bukku_contact_taken`;
--     `bukku_linked` and `bukku_link_only` refuse `taken`), a supplier and
--     its own client sharing one; `bukku_contact_check` lets `bukku-sync`
--     ask before it writes to Bukku.
--   BE-3, CP-2. A public form's typed name is never an actor:
--     `supplier_form_submit` files 'Supplier form' and
--     `quote_website_request` 'Quotation website', the typed name in the
--     detail.
--   BE-4. A quotation's key answers only its own client
--     (`quotation_make`) and its own website visitor (`quote_website_create`).
--   BE-5. `app_setting` reads the first row for an earlier day only where
--     the schema seeded it: a figure the team planned for a later day is not
--     read before it.
--   BE-6. A details link ends when its client moves into Active or Past
--     (trigger `clients_details_close`), and a Past client's link opens
--     nothing (`client_details_read`, `client_details_submit`).
--
-- ORDER: this file, then `bukku-sync` (it asks `bukku_contact_check`), then
--   the pages. A page from before reads as it did; a Bukku sheet open from
--   before meets `taken` from the link functions where it relinks.
--
-- ROLLBACK
--   Each function's definition before this band (CLIENT BILLING, the
--   guards' own bands, BUKKU CONTACTS, SUPPLIER UPDATE LINK, QUOTE WEBSITE
--   GUARDS, BUSINESS SETTINGS, CLIENT DETAILS FORM, CLIENTS AUDIT FIXES),
--   each trigger again as `before update` (clients_active_billing `before
--   update of stage`); trigger clients_details_close and functions
--   bukku_contact_taken and bukku_contact_check removed.
-- ===========================================================================

/* SEC-1: each guard holds an insert as it holds an update. An insert is
   read against a blank row (the column defaults), and only a page's own
   write (the API's `authenticated` role) is held on insert: the functions
   that make a client (the quotation website) set no guarded column. */
create or replace function public.clients_billing_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  -- A billing contact removed from Contacts nulls bill_contact_id by the
  -- foreign key, which is a cascade and not a person editing Billing.
  if pg_trigger_depth() > 1 then return new; end if;
  if tg_op = 'INSERT' then
    if coalesce(current_setting('role', true), '') = 'authenticated'
       and (nullif(btrim(coalesce(new.legal_name, '') || coalesce(new.company_no, '') || coalesce(new.company_no_old, '') ||
                         coalesce(new.tin, '') || coalesce(new.sst_no, '') || coalesce(new.finance_email, '') ||
                         coalesce(new.billing_address, '')), '') is not null
            or new.bill_contact_id is not null or new.sst_applies is false or new.bill_sgd is true)
       and not public.allowed('clients.billing', 'work') then
      raise exception 'Billing details need Clients: Billing at Work.' using errcode = '42501';
    end if;
    return new;
  end if;
  if (new.legal_name, new.company_no, new.company_no_old, new.tin, new.sst_no, new.sst_applies,
      new.bill_contact_id, new.finance_email, new.billing_address, new.bill_sgd)
     is distinct from
     (old.legal_name, old.company_no, old.company_no_old, old.tin, old.sst_no, old.sst_applies,
      old.bill_contact_id, old.finance_email, old.billing_address, old.bill_sgd)
     and not public.allowed('clients.billing', 'work') then
    raise exception 'Billing details need Clients: Billing at Work.' using errcode = '42501';
  end if;
  return new;
end $$;
revoke all on function public.clients_billing_guard() from public, anon, authenticated;
create or replace trigger clients_billing_guard before insert or update on public.clients
  for each row execute function public.clients_billing_guard();

/* A client keyed in Active holds no contact yet, so a page never makes one
   Active: it is added, then moved through the gate. */
create or replace function public.clients_active_billing()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    if new.stage = 'active' and coalesce(current_setting('role', true), '') = 'authenticated' then
      raise exception 'active-needs-billing';
    end if;
    return new;
  end if;
  if new.stage = 'active' and old.stage is distinct from 'active' and (
       coalesce(btrim(new.legal_name), '') = ''
       or coalesce(btrim(new.company_no), '') = ''
       or coalesce(btrim(new.billing_address), '') = ''
       or not exists (select 1 from public.client_contacts k
                       where k.client_id = new.id and k.archived_at is null
                         and (k.id = new.bill_contact_id or k.is_primary))) then
    raise exception 'active-needs-billing';
  end if;
  return new;
end $$;
revoke all on function public.clients_active_billing() from public, anon, authenticated;
create or replace trigger clients_active_billing before insert or update of stage on public.clients
  for each row execute function public.clients_active_billing();

create or replace function public.clients_white_label_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if pg_trigger_depth() > 1 or (auth.jwt() ->> 'email') is null then return new; end if;
  if tg_op = 'INSERT' then
    if (new.white_label is true or new.report_logo is not null)
       and not public.ops_granted('reports.whitelabel', 'work') then
      raise exception 'White label needs Reports: White label at Work.' using errcode = '42501', hint = 'white-label';
    end if;
    return new;
  end if;
  if (new.white_label, new.report_logo) is distinct from (old.white_label, old.report_logo)
     and not public.ops_granted('reports.whitelabel', 'work') then
    raise exception 'White label needs Reports: White label at Work.' using errcode = '42501', hint = 'white-label';
  end if;
  return new;
end $$;
revoke all on function public.clients_white_label_guard() from public, anon, authenticated;
create or replace trigger clients_white_label_guard before insert or update on public.clients
  for each row execute function public.clients_white_label_guard();

create or replace function public.clients_brand_guard()
returns trigger language plpgsql set search_path = public as $$
begin
  /* A function writing the row has asked its own permission, and a cascade
     is not a person: only a write made on the table through the API. */
  if pg_trigger_depth() > 1 or current_user <> 'authenticated' then
    return new;
  end if;
  if (case when tg_op = 'INSERT' then new.brief is not null or new.brand_notes is not null
           else (new.brief, new.brand_notes) is distinct from (old.brief, old.brand_notes) end)
     and not public.allowed('clients.brand', 'work') then
    raise exception 'brand-columns: the content brief and brand notes need Clients: Brand at Work.'
      using errcode = '42501';
  end if;
  return new;
end $$;
revoke all on function public.clients_brand_guard() from public, anon, authenticated;
create or replace trigger clients_brand_guard before insert or update on public.clients
  for each row execute function public.clients_brand_guard();

create or replace function public.campaigns_finance_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if (case when tg_op = 'INSERT'
           then coalesce(current_setting('role', true), '') = 'authenticated'
                and (new.invoice_no, new.invoice_url, new.invoice_uploaded_at) is distinct from (null::text, null::text, null::timestamptz)
           else (new.invoice_no, new.invoice_url, new.invoice_uploaded_at)
                is distinct from (old.invoice_no, old.invoice_url, old.invoice_uploaded_at) end)
     and not public.allowed('campaigns.finance', 'work') then
    raise exception 'The invoice needs Creator Campaigns: Finance at Work.' using errcode = '42501';
  end if;
  return new;
end $$;
revoke all on function public.campaigns_finance_guard() from public, anon, authenticated;
create or replace trigger campaigns_finance_guard before insert or update on public.campaigns
  for each row execute function public.campaigns_finance_guard();

/* A file the client approved is the client's record of what they approved:
   a page hides it, and never removes it. Run as the caller, so
   `current_user` tells a page's write from a function's. */
create or replace function public.campaign_deliverables_guard() returns trigger
language plpgsql set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    if current_user in ('authenticated', 'anon') and (new.hidden_at is not null or new.hidden_by is not null) then
      raise exception 'hide-function' using hint = 'Hide and Restore go through campaign_file_hide.';
    end if;
    return new;
  end if;
  if current_user in ('authenticated', 'anon')
     and new.removed_at is not null and old.removed_at is null
     and exists (select 1 from public.campaign_options o
                  where o.id = new.option_id and o.state in ('scheduled', 'posted', 'completed')) then
    raise exception 'approved-hide' using hint = 'An approved file is hidden, not removed.';
  end if;
  if current_user in ('authenticated', 'anon')
     and (new.hidden_at, new.hidden_by) is distinct from (old.hidden_at, old.hidden_by) then
    raise exception 'hide-function' using hint = 'Hide and Restore go through campaign_file_hide.';
  end if;
  return new;
end $$;
revoke all on function public.campaign_deliverables_guard() from public, anon, authenticated;
create or replace trigger campaign_deliverables_guard
  before insert or update on public.campaign_deliverables
  for each row execute function public.campaign_deliverables_guard();

/* BE-5: a figure is the one in force on the day. The first row stands in
   for an earlier day only where the schema seeded it (no `set_by`), so a
   figure the team plans for a later day (the S$ rate) is not read before
   that day. */
create or replace function public.app_setting(p_key text, p_at date)
returns numeric
language sql stable security definer set search_path = public as $$
  select coalesce(
    (select s.value from public.app_settings s where s.key = p_key and s.from_date <= coalesce(p_at, (now() at time zone 'Asia/Kuala_Lumpur')::date)
      order by s.from_date desc limit 1),
    (select s.value from public.app_settings s where s.key = p_key and s.set_by is null order by s.from_date limit 1))
$$;
revoke all on function public.app_setting(text, date) from public, anon, authenticated;

/* BE-6: a details link is for the Active gate. A move into Active or Past
   ends every link still open on the client; a Past client's link opens
   nothing. */
create or replace function public.clients_details_close()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.stage in ('active', 'past') and old.stage is distinct from new.stage then
    update public.client_detail_forms f set voided_at = now()
     where f.client_id = new.id and f.voided_at is null and f.submitted_at is null;
  end if;
  return null;
end $$;
revoke all on function public.clients_details_close() from public, anon, authenticated;
create or replace trigger clients_details_close after update of stage on public.clients
  for each row execute function public.clients_details_close();

/* BE-2: one Bukku contact is one record's (a supplier and the client it is
   one contact with). */
create or replace function public.bukku_contact_taken(p_kind text, p_id uuid, p_contact bigint)
returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.bukku_links l
     where l.contact_id = p_contact
       and not (l.kind = p_kind and l.record_id = p_id)
       and not (p_kind = 'supplier' and l.kind = 'client'
                and l.record_id = (select x.client_id from public.suppliers x where x.id = p_id))
       and not (p_kind = 'client' and l.kind = 'supplier'
                and exists (select 1 from public.suppliers x where x.id = l.record_id and x.client_id = p_id)))
$$;
revoke all on function public.bukku_contact_taken(text, uuid, bigint) from public, anon, authenticated;

create or replace function public.bukku_contact_check(p_kind text, p_id uuid, p_contact bigint)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.bukku_may(p_kind, p_id, 'work') then return jsonb_build_object('error', 'denied'); end if;
  if public.bukku_contact_taken(p_kind, p_id, p_contact) then return jsonb_build_object('error', 'taken'); end if;
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.bukku_contact_check(text, uuid, bigint) from public, anon;
grant execute on function public.bukku_contact_check(text, uuid, bigint) to authenticated;

create or replace function public.bukku_linked(p_kind text, p_id uuid, p_contact bigint, p_code text)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare me public.team_members := public.ops_me(); v_name text; v_code text; v_client uuid;
begin
  if not public.bukku_may(p_kind, p_id, 'work') then return jsonb_build_object('error', 'denied'); end if;
  if p_contact is null or p_contact <= 0 then return jsonb_build_object('error', 'bad-contact'); end if;
  if p_kind = 'client' then
    select x.name, x.client_code into v_name, v_code from public.clients x where x.id = p_id;
  else
    select coalesce(x.name, x.code), x.code, x.client_id into v_name, v_code, v_client from public.suppliers x where x.id = p_id;
  end if;
  if v_name is null then return jsonb_build_object('error', 'not-found'); end if;
  if public.bukku_contact_taken(p_kind, p_id, p_contact) then return jsonb_build_object('error', 'taken'); end if;
  insert into public.bukku_links (kind, record_id, contact_id, code, sent_at, sent_by, sent_hash)
  values (p_kind, p_id, p_contact, left(p_code, 40), now(), me.id, public.bukku_print(p_kind, p_id))
  on conflict (kind, record_id) do update set contact_id = excluded.contact_id, code = excluded.code,
    sent_at = now(), sent_by = excluded.sent_by, sent_hash = excluded.sent_hash;
  /* One contact for a supplier that is also a client. */
  if v_client is not null then
    insert into public.bukku_links (kind, record_id, contact_id, code, sent_at, sent_by, sent_hash)
    values ('client', v_client, p_contact, left(p_code, 40), now(), me.id, null)
    on conflict (kind, record_id) do update set contact_id = excluded.contact_id, code = excluded.code;
  end if;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, case when p_kind = 'client' then 'client.edited' else 'supplier.edited' end, v_name,
          coalesce(v_code || ' · ', '') || 'Sent to Bukku · ' || coalesce(p_code, p_contact::text));
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.bukku_linked(text, uuid, bigint, text) from public, anon;
grant execute on function public.bukku_linked(text, uuid, bigint, text) to authenticated;
create or replace function public.bukku_link_only(p_kind text, p_id uuid, p_contact bigint, p_code text)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare me public.team_members := public.ops_me(); v_name text; v_code text; v_client uuid;
begin
  if not public.bukku_may(p_kind, p_id, 'work') then return jsonb_build_object('error', 'denied'); end if;
  if p_contact is null or p_contact <= 0 then return jsonb_build_object('error', 'bad-contact'); end if;
  if p_kind = 'client' then
    select x.name, x.client_code into v_name, v_code from public.clients x where x.id = p_id;
  else
    select coalesce(x.name, x.code), x.code, x.client_id into v_name, v_code, v_client from public.suppliers x where x.id = p_id;
  end if;
  if v_name is null then return jsonb_build_object('error', 'not-found'); end if;
  if public.bukku_contact_taken(p_kind, p_id, p_contact) then return jsonb_build_object('error', 'taken'); end if;
  insert into public.bukku_links (kind, record_id, contact_id, code, sent_at, sent_by, sent_hash)
  values (p_kind, p_id, p_contact, left(p_code, 40), now(), me.id, public.bukku_print(p_kind, p_id))
  on conflict (kind, record_id) do update set contact_id = excluded.contact_id, code = excluded.code,
    sent_at = now(), sent_by = excluded.sent_by, sent_hash = excluded.sent_hash;
  /* One contact for a supplier that is also a client. */
  if v_client is not null then
    insert into public.bukku_links (kind, record_id, contact_id, code, sent_at, sent_by, sent_hash)
    values ('client', v_client, p_contact, left(p_code, 40), now(), me.id, null)
    on conflict (kind, record_id) do update set contact_id = excluded.contact_id, code = excluded.code;
  end if;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, case when p_kind = 'client' then 'client.edited' else 'supplier.edited' end, v_name,
          coalesce(v_code || ' · ', '') || 'Linked to Bukku, nothing sent · ' || coalesce(p_code, p_contact::text));
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.bukku_link_only(text, uuid, bigint, text) from public, anon;
grant execute on function public.bukku_link_only(text, uuid, bigint, text) to authenticated;
create or replace function public.supplier_form_submit(p_key text, p_answers jsonb)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  f public.supplier_forms;
  s public.suppliers;
  v jsonb;
  a jsonb := coalesce(p_answers, '{}'::jsonb);
begin
  if coalesce(p_key, '') !~ '^[a-z0-9]{8}$' then return jsonb_build_object('error', 'not_found'); end if;
  select * into f from public.supplier_forms x where x.access_key = p_key and x.voided_at is null for update;
  if f.id is null then return jsonb_build_object('error', 'not_found'); end if;
  if f.submitted_at is not null then return jsonb_build_object('error', 'submitted'); end if;
  if f.expires_at <= now() then return jsonb_build_object('error', 'expired'); end if;
  if coalesce(a->>'authorise', '') <> 'true' then return jsonb_build_object('error', 'bad-authorise'); end if;
  select * into s from public.suppliers x where x.id = f.supplier_id;
  /* An update keeps the NRIC and the bank details held where left blank. */
  if f.purpose = 'update' then
    if btrim(coalesce(a->>'bank_account', '')) = '' and s.bank_account is not null then
      a := a || jsonb_build_object('payee_name', s.payee_name, 'bank_name', s.bank_name, 'bank_account', s.bank_account,
                                   'swift', s.swift, 'bank_address', s.bank_address);
    end if;
    if btrim(coalesce(a->>'nric', '')) = '' and s.nric is not null then
      a := a || jsonb_build_object('nric', s.nric);
    end if;
  end if;
  v := public.supplier_values_check(a, true);
  if v ? 'error' then return v; end if;
  update public.supplier_forms x set submitted_at = now(), answers = jsonb_strip_nulls(v) where x.id = f.id;
  insert into public.activity_log (actor, action, subject, detail)
  values ('Supplier form', 'supplier.edited', coalesce(s.name, v->>'name'), s.code || ' · ' ||
          case when f.purpose = 'update' then 'Details update received on the update link' else 'Details received on the details form' end ||
          coalesce(' from ' || nullif(btrim(v->>'contact_name'), ''), ''));
  insert into public.ops_notifications (team_member_id, kind, title, body, supplier_id, dedupe_key)
  select m.id, 'supplier.details',
         case when f.purpose = 'update' then 'Supplier details update received · ' else 'Supplier details received · ' end || coalesce(s.name, v->>'name'),
         'From ' || (v->>'contact_name') || '. Review them on the supplier.',
         s.id, 'supplier.details:' || f.id || ':' || m.id
    from public.team_members m
   where m.active and not coalesce(m.system, false)
     and (m.is_admin or m.role = 'admin'
          or public.level_rank(m.access ->> 'suppliers') >= 2)
  on conflict (dedupe_key) do nothing;
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.supplier_form_submit(text, jsonb) from public;
grant execute on function public.supplier_form_submit(text, jsonb) to anon, authenticated;
create or replace function public.quote_website_request(p_key text, p_billing jsonb)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  v_q    public.quotations;
  v_sg   boolean;
  v_reg  text := upper(btrim(regexp_replace(coalesce(p_billing->>'registered_name', ''), '\s+', ' ', 'g')));
  v_brn  text := upper(regexp_replace(coalesce(p_billing->>'brn', ''), '[^0-9A-Za-z]', '', 'g'));
  v_addr text := btrim(coalesce(p_billing->>'address', ''));
begin
  if coalesce(p_key, '') !~ '^[a-z0-9]{8}$' then return jsonb_build_object('error', 'not-found'); end if;
  select * into v_q from public.quotations q
   where q.access_key = p_key and q.source = 'website' and q.removed_at is null for update;
  if v_q.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if v_q.requested_at is not null then return jsonb_build_object('ok', true, 'again', true); end if;
  if v_q.status = 'not_proceeding' then return jsonb_build_object('error', 'not-proceeding'); end if;
  if v_q.valid_until < (now() at time zone 'Asia/Kuala_Lumpur')::date then return jsonb_build_object('error', 'expired'); end if;
  select c.market = 'SG' into v_sg from public.clients c where c.id = v_q.client_id;
  if length(v_reg) < 3 or length(v_reg) > 160 or length(v_addr) < 10 or length(v_addr) > 400
     or (coalesce(v_sg, false) and v_brn !~ '^([0-9]{8,9}[A-Z]|[TSR][0-9]{2}[A-Z]{2}[0-9]{4}[A-Z])$')
     or (not coalesce(v_sg, false) and v_brn !~ '^[0-9]{12}$') then
    return jsonb_build_object('error', 'bad-billing');
  end if;
  update public.quotations
     set billing = jsonb_build_object('registered_name', v_reg, 'brn', v_brn, 'address', v_addr),
         requested_at = now(), status = 'requested'
   where id = v_q.id;
  insert into public.activity_log (actor, action, subject, detail)
  values ('Quotation website', 'client.quotation', v_q.brand,
          v_q.ref || ' · Letter of Offer requested on the website' ||
          coalesce(' by ' || nullif(btrim(v_q.contact->>'name'), ''), ''));
  perform public.quote_tell(v_q.client_id, 'quote.requested', 'Letter of Offer requested · ' || v_q.brand,
    v_q.ref || ' · ' || v_reg, v_q.id::text);
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.quote_website_request(text, jsonb) from public;
grant execute on function public.quote_website_request(text, jsonb) to anon, authenticated;
create or replace function public.quotation_make(p_client uuid, p_sel jsonb, p_idem text, p_source text,
                                                 p_by text, p_contact jsonb)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  v_c public.clients;
  v_card jsonb := public.quote_card();
  v_p jsonb;
  v_q public.quotations;
  v_now timestamptz := now();
  v_days int;
  v_fx numeric;
  v_sel jsonb := case when jsonb_typeof(p_sel) is distinct from 'object' then p_sel
                      when p_source = 'console' then p_sel - 'client'
                      else p_sel - 'edits' - 'client' end;
begin
  if p_idem is not null then
    select * into v_q from public.quotations q where q.idem = p_idem and q.client_id = p_client;
    if v_q.id is not null then return jsonb_build_object('ok', true, 'id', v_q.id, 'ref', v_q.ref, 'again', true); end if;
  end if;
  select * into v_c from public.clients where id = p_client;
  if v_c.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if v_card is null then return jsonb_build_object('error', 'no-card'); end if;
  v_fx := public.quote_fx(v_c.id);
  if v_fx = 0 then return jsonb_build_object('error', 'no-fx'); end if;
  v_p := public.quote_fx_out(public.quote_adjust(public.quote_price(public.quote_fx_snap(public.quote_tax_snap(v_card->'snapshot', v_c.id), v_fx),
           v_sel), public.quote_tax_edits(v_sel->'edits')), v_fx);
  if v_p ? 'error' then return v_p; end if;
  v_days := coalesce(public.app_setting('quote_valid_days', (v_now at time zone 'Asia/Kuala_Lumpur')::date), 30)::int;
  begin
  insert into public.quotations (ref, client_id, brand, version, version_id, selection, lines, totals, source,
                                 issued_at, valid_until, made_by, contact, idem, access_key)
  values (public.quote_ref(v_c.name, v_now), v_c.id, v_c.name, v_card->>'version', (v_card->>'id')::uuid, v_sel,
          v_p->'lines', v_p->'totals' || jsonb_build_object('on_request', v_p->'on_request'), p_source,
          v_now, (v_now at time zone 'Asia/Kuala_Lumpur')::date + v_days, p_by, p_contact, p_idem,
          case when p_source = 'website' then public.new_link_key() end)
  returning * into v_q;
  -- Two presses at once with one key: the second answers the first's.
  exception when unique_violation then
    select * into v_q from public.quotations q where q.idem = p_idem and q.client_id = p_client;
    if p_idem is null or v_q.id is null then raise; end if;
    return jsonb_build_object('ok', true, 'id', v_q.id, 'ref', v_q.ref, 'again', true);
  end;
  insert into public.activity_log (actor, action, subject, detail)
  values (coalesce(p_by, 'Website'), 'client.quotation', v_c.name,
          v_q.ref || ' sent · ' || coalesce('Monthly incl. SST ' || case when v_fx is null then 'RM ' else 'S$ ' end ||
            to_char((v_q.totals->'month'->>'incl')::numeric, 'FM999,999,990.00'), 'one-off') ||
          ' · rate card v.' || v_q.version ||
          case coalesce((v_p->>'adjusted')::int, 0) when 0 then '' when 1 then ' · 1 line changed'
               else ' · ' || (v_p->>'adjusted') || ' lines changed' end);
  return jsonb_build_object('ok', true, 'id', v_q.id, 'ref', v_q.ref, 'key', v_q.access_key);
end $$;
revoke all on function public.quotation_make(uuid, jsonb, text, text, text, jsonb) from public, anon, authenticated;
create or replace function public.quote_website_create(p_sel jsonb, p_contact jsonb, p_idem text)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  v_name  text := btrim(regexp_replace(coalesce(p_contact->>'name', ''), '\s+', ' ', 'g'));
  v_email text := lower(btrim(coalesce(p_contact->>'email', '')));
  v_wa    text := public.quote_website_number(p_contact->>'whatsapp');
  v_brand text := btrim(regexp_replace(coalesce(p_contact->>'brand', ''), '\s+', ' ', 'g'));
  v_ind   text := nullif(btrim(coalesce(p_contact->>'industry', '')), '');
  v_lang  text := case when p_contact->>'lang' = 'zh' then 'zh' else 'en' end;
  v_sal   text := nullif(btrim(coalesce(p_contact->>'salutation', '')), '');
  v_idem  text := nullif(btrim(coalesce(p_idem, '')), '');
  v_sel   jsonb;
  v_q     public.quotations;
  v_c     public.clients;
  v_base  text;
  v_slug  text;
  v_n     int := 1;
  v_r     jsonb;
  v_new   boolean := false;
begin
  if v_idem is null or length(v_idem) > 80 then return jsonb_build_object('error', 'bad-request'); end if;
  select * into v_q from public.quotations q
   where q.idem = v_idem and q.source = 'website' and lower(q.contact->>'email') = v_email;
  if v_q.id is not null then
    return jsonb_build_object('ok', true, 'ref', v_q.ref, 'key', v_q.access_key, 'again', true);
  end if;
  if length(v_name) < 2 or length(v_name) > 80 then return jsonb_build_object('error', 'bad-name'); end if;
  if v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' or length(v_email) > 160 then return jsonb_build_object('error', 'bad-email'); end if;
  if v_wa !~ '^(60(1[0-9]{8,9}|7[0-9]{7,8})|65[0-9]{8})$' then return jsonb_build_object('error', 'bad-whatsapp'); end if;
  if length(v_brand) < 2 or length(v_brand) > 120 then return jsonb_build_object('error', 'bad-brand'); end if;
  if v_ind is not null and v_ind not in ('Property', 'F&B', 'Retail', 'Wellness', 'Lifestyle',
                                         'Automotive', 'Tech', 'Education', 'Other') then
    return jsonb_build_object('error', 'bad-industry');
  end if;
  if v_sal is not null and v_sal not in ('Mr', 'Ms', 'Mrs', 'Mdm', 'Dr', 'Prof', 'Dato''', 'Datin', 'Datuk',
      'Dato'' Sri', 'Datin Sri', 'Tan Sri', 'Puan Sri', 'Tun', 'Tuan', 'Puan', 'Encik', 'Cik') then
    return jsonb_build_object('error', 'bad-salutation');
  end if;
  if coalesce((p_contact->>'consent')::boolean, false) is not true then return jsonb_build_object('error', 'consent'); end if;
  if jsonb_typeof(p_sel) is distinct from 'object' then return jsonb_build_object('error', 'bad-selection'); end if;
  if jsonb_typeof(p_sel->'once') = 'array' and jsonb_array_length(p_sel->'once') > 20
     or jsonb_typeof(p_sel->'extra') = 'object' and (select count(*) from jsonb_object_keys(p_sel->'extra')) > 10 then
    return jsonb_build_object('error', 'bad-selection');
  end if;

  -- What the price reads, and nothing else.
  v_sel := jsonb_strip_nulls(jsonb_build_object(
    'mix', case when jsonb_typeof(p_sel->'mix') = 'string' and length(p_sel->>'mix') <= 20 then p_sel->'mix' end,
    'plan', case when jsonb_typeof(p_sel->'plan') = 'string' and length(p_sel->>'plan') <= 80 then p_sel->'plan' end,
    'term', case when jsonb_typeof(p_sel->'term') in ('number', 'string') and length(p_sel->>'term') <= 4 then p_sel->'term' end,
    'budget', case when jsonb_typeof(p_sel->'budget') in ('number', 'string') and length(p_sel->>'budget') <= 12 then p_sel->'budget' end,
    'translate', case when jsonb_typeof(p_sel->'translate') = 'boolean' then p_sel->'translate' end,
    'platforms', (select jsonb_agg(distinct v) from jsonb_array_elements_text(
                    case when jsonb_typeof(p_sel->'platforms') = 'array' then p_sel->'platforms' else '[]'::jsonb end) v
                   where v in ('meta', 'tiktok', 'rednote', 'linkedin')),
    'langs', (select jsonb_agg(distinct l) from jsonb_array_elements_text(
                case when jsonb_typeof(p_sel->'langs') = 'array' then p_sel->'langs' else '[]'::jsonb end) l
               where l in ('en', 'zh', 'ms')),
    'extra', case when jsonb_typeof(p_sel->'extra') = 'object' then
               (select jsonb_object_agg(left(k, 80), p_sel->'extra'->k) from jsonb_object_keys(p_sel->'extra') k) end,
    'once', case when jsonb_typeof(p_sel->'once') = 'array' then
              (select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('slug', left(o->>'slug', 80), 'qty', o->'qty')))
                 from jsonb_array_elements(p_sel->'once') o where jsonb_typeof(o) = 'object') end));

  -- Two posts at once are counted one after the other.
  perform pg_advisory_xact_lock(hashtextextended('quote-web:' || least(v_email, v_wa), 0));
  perform pg_advisory_xact_lock(hashtextextended('quote-web:' || greatest(v_email, v_wa), 0));
  if (select count(*) from public.quotations q
       where q.source = 'website' and q.issued_at > now() - interval '1 day'
         and (lower(q.contact->>'email') = v_email or q.contact->>'whatsapp' = '+' || v_wa)) >= 5 then
    return jsonb_build_object('error', 'limit');
  end if;

  -- A lead this person already is (the same contact holds both the email
  -- and the number), else a new one.
  select c.* into v_c from public.clients c
    join public.client_contacts k on k.client_id = c.id
   where c.stage in ('lead', 'contacted', 'proposal')
     and k.archived_at is null
     and lower(k.email) = v_email
     and public.quote_website_number(k.whatsapp) = v_wa
   order by c.created_at desc limit 1;
  if v_c.id is null then
    v_base := btrim(regexp_replace(lower(v_brand), '[^a-z0-9]+', '-', 'g'), '-');
    if v_base = '' then v_base := 'client'; end if;
    v_slug := v_base;
    while exists (select 1 from public.clients c where lower(c.slug) = v_slug) loop
      v_n := v_n + 1; v_slug := v_base || '-' || v_n;
    end loop;
    insert into public.clients (name, access_token, stage, industry, source, market, slug, deal_note)
    values (v_brand, public.new_link_key(), 'lead', v_ind, 'website',
            case when v_wa like '65%' then 'SG' else 'MY' end, v_slug,
            'Quotation requested on the website.')
    returning * into v_c;
    insert into public.client_contacts (client_id, salutation, name, email, whatsapp, lang, is_primary)
    values (v_c.id, v_sal, v_name, v_email, '+' || v_wa, v_lang, true);
    insert into public.activity_log (actor, action, subject, detail)
    values ('Website', 'client.added', v_c.name, 'Website · ' || coalesce(v_sal || ' ', '') || v_name);
    v_new := true;
  end if;

  v_r := public.quotation_make(v_c.id, v_sel, v_idem, 'website', null,
    jsonb_strip_nulls(jsonb_build_object('salutation', v_sal, 'name', v_name, 'email', v_email,
      'whatsapp', '+' || v_wa, 'lang', v_lang, 'brand', v_brand)));
  if v_r ? 'error' then
    if v_new then raise exception using message = 'quote:' || (v_r->>'error'); end if;
    return v_r;
  end if;
  select * into v_q from public.quotations where id = (v_r->>'id')::uuid;
  perform public.quote_tell(v_c.id, 'quote.website', 'Quotation made on the website · ' || v_c.name,
    v_q.ref || ' · ' || coalesce('Monthly incl. SST RM ' ||
      to_char((v_q.totals->'month'->>'incl')::numeric, 'FM999,999,990.00'), 'one-off') || ' · ' || v_name,
    v_q.id::text);
  return jsonb_build_object('ok', true, 'ref', v_q.ref, 'key', v_q.access_key);
exception when raise_exception then
  if sqlerrm like 'quote:%' then return jsonb_build_object('error', substr(sqlerrm, 7)); end if;
  raise;
end $$;
revoke all on function public.quote_website_create(jsonb, jsonb, text) from public, anon, authenticated;
grant execute on function public.quote_website_create(jsonb, jsonb, text) to service_role;
create or replace function public.client_details_read(p_key text)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_f  public.client_detail_forms;
  v_cl public.clients;
begin
  if coalesce(p_key, '') !~ '^[a-z0-9]{8}$' then return jsonb_build_object('error', 'not_found'); end if;
  select * into v_f from public.client_detail_forms f where f.access_key = p_key and f.voided_at is null;
  if v_f.id is null then return jsonb_build_object('error', 'not_found'); end if;
  if v_f.submitted_at is not null then return jsonb_build_object('error', 'submitted'); end if;
  if v_f.expires_at <= now() then return jsonb_build_object('error', 'expired'); end if;
  select * into v_cl from public.clients c where c.id = v_f.client_id;
  if v_cl.stage = 'past' then return jsonb_build_object('error', 'not_found'); end if;
  return jsonb_build_object('ok', true, 'brand', v_cl.name, 'expires_at', v_f.expires_at);
end $$;
revoke all on function public.client_details_read(text) from public;
grant execute on function public.client_details_read(text) to anon, authenticated;
create or replace function public.client_details_submit(p_key text, p_answers jsonb)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  v_f    public.client_detail_forms;
  v_cl   public.clients;
  a      jsonb := coalesce(p_answers, '{}'::jsonb);
  t      text;
  v_name text := upper(btrim(regexp_replace(coalesce(a->>'legal_name', ''), '\s+', ' ', 'g')));
  v_brn  text := upper(regexp_replace(coalesce(a->>'company_no', ''), '\s+', '', 'g'));
  v_old  text := nullif(upper(regexp_replace(coalesce(a->>'company_no_old', ''), '\s+', '', 'g')), '');
  v_tin  text := nullif(upper(regexp_replace(coalesce(a->>'tin', ''), '\s+', '', 'g')), '');
  v_sst  text := nullif(upper(regexp_replace(coalesce(a->>'sst_no', ''), '\s+', '', 'g')), '');
  v_addr text := btrim(coalesce(a->>'billing_address', ''));
  v_fin  text := nullif(lower(btrim(coalesce(a->>'finance_email', ''))), '');
  v_sal  text := nullif(btrim(coalesce(a->>'contact_salutation', '')), '');
  v_cn   text := btrim(regexp_replace(coalesce(a->>'contact_name', ''), '\s+', ' ', 'g'));
  v_cp   text := btrim(coalesce(a->>'contact_phone', ''));
  v_ce   text := lower(btrim(coalesce(a->>'contact_email', '')));
begin
  if coalesce(p_key, '') !~ '^[a-z0-9]{8}$' then return jsonb_build_object('error', 'not_found'); end if;
  select * into v_f from public.client_detail_forms f where f.access_key = p_key and f.voided_at is null for update;
  if v_f.id is null then return jsonb_build_object('error', 'not_found'); end if;
  if v_f.submitted_at is not null then return jsonb_build_object('error', 'submitted'); end if;
  if v_f.expires_at <= now() then return jsonb_build_object('error', 'expired'); end if;
  if exists (select 1 from public.clients c where c.id = v_f.client_id and c.stage = 'past') then
    return jsonb_build_object('error', 'not_found');
  end if;
  if length(v_name) < 2 or length(v_name) > 160 then return jsonb_build_object('error', 'bad-legal_name'); end if;
  if v_brn !~ '^[A-Z0-9-]{6,20}$' then return jsonb_build_object('error', 'bad-company_no'); end if;
  if v_old is not null and v_old !~ '^[A-Z0-9-]{4,20}$' then return jsonb_build_object('error', 'bad-company_no_old'); end if;
  if v_tin is not null and v_tin !~ '^[A-Z0-9-]{6,20}$' then return jsonb_build_object('error', 'bad-tin'); end if;
  if v_sst is not null and v_sst !~ '^[A-Z0-9-]{6,25}$' then return jsonb_build_object('error', 'bad-sst_no'); end if;
  if length(v_addr) < 10 or length(v_addr) > 400 then return jsonb_build_object('error', 'bad-billing_address'); end if;
  if v_fin is not null and (v_fin !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' or length(v_fin) > 160) then
    return jsonb_build_object('error', 'bad-finance_email');
  end if;
  if v_sal is not null and v_sal not in ('Mr', 'Ms', 'Mrs', 'Mdm', 'Dr', 'Prof', 'Dato''', 'Datin', 'Datuk',
      'Dato'' Sri', 'Datin Sri', 'Tan Sri', 'Puan Sri', 'Tun', 'Tuan', 'Puan', 'Encik', 'Cik') then
    return jsonb_build_object('error', 'bad-contact_salutation');
  end if;
  if length(v_cn) < 2 or length(v_cn) > 80 then return jsonb_build_object('error', 'bad-contact_name'); end if;
  t := regexp_replace(v_cp, '[^0-9]', '', 'g');
  if length(t) < 8 or length(t) > 15 or length(v_cp) > 30 then return jsonb_build_object('error', 'bad-contact_phone'); end if;
  if v_ce !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' or length(v_ce) > 160 then return jsonb_build_object('error', 'bad-contact_email'); end if;

  update public.client_detail_forms f
     set submitted_at = now(),
         answers = jsonb_strip_nulls(jsonb_build_object(
           'legal_name', v_name, 'company_no', v_brn, 'company_no_old', v_old, 'tin', v_tin, 'sst_no', v_sst,
           'billing_address', v_addr, 'finance_email', v_fin, 'contact_salutation', v_sal,
           'contact_name', v_cn, 'contact_phone', v_cp, 'contact_email', v_ce))
   where f.id = v_f.id;
  select * into v_cl from public.clients c where c.id = v_f.client_id;
  insert into public.activity_log (actor, action, subject, detail)
  values ('Details form', 'client.edited', v_cl.name,
          'Billing details received on the details form from ' || coalesce(v_sal || ' ', '') || v_cn);
  insert into public.ops_notifications (team_member_id, kind, title, body, client_id, dedupe_key)
  select m.id, 'client.details', 'Billing details received · ' || v_cl.name,
         'From ' || coalesce(v_sal || ' ', '') || v_cn || '. Review them on the client''s Billing.',
         v_cl.id, 'client.details:' || v_f.id || ':' || m.id
    from public.team_members m
   where m.active and not coalesce(m.system, false)
     and (m.is_admin or m.role = 'admin'
          or (public.level_rank(coalesce(m.access ->> 'clients.billing', m.access ->> 'clients')) >= 2
              -- held to the colleague's own client scope, as client_row_seen holds a reader (audit S7)
              and (v_cl.stage not in ('lead', 'contacted', 'proposal', 'past')
                   or public.level_rank(coalesce(m.access ->> case when v_cl.stage = 'past' then 'clients.past' else 'clients.leads' end,
                                                 m.access ->> 'clients')) >= 1)
              and (coalesce(m.client_scope, 'all') <> 'own'
                   or (nullif(btrim(coalesce(v_cl.owner, '')), '') is null and v_cl.stage in ('lead', 'contacted', 'proposal'))
                   or lower(btrim(coalesce(v_cl.owner, ''))) = lower(btrim(coalesce(m.name, ''))))))
  on conflict (dedupe_key) do nothing;
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.client_details_submit(text, jsonb) from public;
grant execute on function public.client_details_submit(text, jsonb) to anon, authenticated;

-- END OF BACKEND REVIEW HOLDS ----------------------------------------------

-- ON TIME ON MALAYSIA'S DAY — the Dashboard's on-time figures read the day a
-- task reached client review in Malaysia, per person too, and the six
-- months' line reads only what it draws. 2026-10-22. Safe to run twice.
-- Rollback at the foot. Mirrored byte for byte in supabase/schema.sql under
-- the same banner; tests/ops.js compares the two.
--
-- WHAT CHANGED (the review of 2026-10-22, OVW-1, OVW-2, OVW-11)
--   * On time: a task reaching client review is on time where the Malaysian
--     day it got there is not after its due date's Malaysian day. The casts
--     read UTC's day: a task reaching review at 07:00 the morning after its
--     due date counted as on time while the queue called it late (OVW-1).
--   * On time by person: a finished task is on time where it reached client
--     review by its due date (else its review, else its finish), as the ring
--     above it reads the same work; it had compared the day the task was
--     finished, a week after it went live, so nearly every content task read
--     late (OVW-2). A priority's deadline reads as before.
--   * ops_report's body is ops_report_of(p_from, p_to, p_light); ops_report
--     answers it whole, and ops_reports answers the third span on (the six
--     months' line) light: on_time, posted and by_person, with what is
--     running, late, each stage's time and the open work left empty, so the
--     whole open queue is read for the two spans that show it (OVW-11).
--
-- ORDER: this file, then the pages (an old page reads the same answers).
--
-- ROLLBACK
--   Run ops_report from POSTED ON TIME and ops_reports from OPS REPORTS AT
--   ONCE again; ops_report_of is then unused and may stay.
-- ===========================================================================

create or replace function public.ops_report_of(
  p_from  timestamptz,
  p_to    timestamptz,
  p_light boolean)
returns jsonb
language plpgsql security definer stable set search_path = public as $$
declare
  out jsonb;
begin
  if not public.ops_granted('ops.reports', 'view') then
    return jsonb_build_object('error', 'denied');
  end if;

  with
  /* Where client review begins in each workflow. The final due date is the
     day the work is owed AT that stage, so everything below that position is
     "has not reached the client yet". Read from `stage_group` and never from
     a stage key: the two seeded workflows name that stage differently. */
  floors as (
    select workflow_id, min(position) as at
      from public.ops_workflow_stages
     where stage_group = 'client_review'
     group by workflow_id
  ),
  /* Where a priority's deadline is met (2026-10-11): client review, else the
     workflow's first review (an everyday task's Review). */
  pfloors as (
    select workflow_id,
           coalesce(min(position) filter (where stage_group = 'client_review'),
                    min(position) filter (where stage_group = 'internal_review')) as at
      from public.ops_workflow_stages
     group by workflow_id
  ),
  live as (
    select t.*, s.label as stage_label, s.position as stage_position,
           s.stage_group, f.at as review_at,
           public.ops_priority_by(coalesce(t.priority_at, t.created_at), t.priority_level) as prio_by, pf.at as prio_at
      from public.ops_tasks t
      join public.ops_workflow_stages s
        on s.workflow_id = t.workflow_id and s.key = t.stage_key
      left join floors f on f.workflow_id = t.workflow_id
      left join pfloors pf on pf.workflow_id = t.workflow_id
     where t.completed_at is null and t.cancelled_at is null
       and t.archived_at is null
       /* Client scope: a colleague on Own clients only reads the work of
          the clients they hold, and their own tasks always (2026-10-18). */
       and public.ops_task_in_scope(t.id)
  ),

  /* 1. WHAT IS RUNNING, by the words on the screen. Grouped by the stage's
        own label rather than by its group, because "what is on shooting" is
        the question and Shooting is a label, not a group. */
  running as (
    select jsonb_agg(x order by x ->> 'position', x ->> 'label') as j from (
      select jsonb_build_object(
               'stage_key', stage_key, 'label', stage_label,
               'position', stage_position, 'stage_group', stage_group,
               'count', count(*)) as x
        from live
       where not p_light
       group by stage_key, stage_label, stage_position, stage_group
    ) q
  ),

  /* 2. WHAT IS LATE. Past the commitment and still short of client review,
        or past a priority's deadline and short of its review (On hold and
        Blocked still count): whichever comes first (the user, 2026-10-11).
        The same rule the queue row draws, stated once more here because a
        report a page computes for itself is a second definition. */
  late_now as (
    select l.*,
           (l.current_final_due_at is not null and (l.current_final_due_at at time zone 'Asia/Kuala_Lumpur')::date < (now() at time zone 'Asia/Kuala_Lumpur')::date
            and (l.review_at is null or l.stage_position < l.review_at)) as due_late,
           (l.prio_by is not null and l.prio_by < now()
            and (l.prio_at is null or l.stage_position < l.prio_at or l.stage_group in ('kiv', 'blocked'))) as prio_late
      from live l
  ),
  late as (
    select jsonb_agg(x order by x ->> 'due_at') as j from (
      select jsonb_build_object(
               'task_id', l.id, 'task_no', l.task_no, 'title', l.title,
               'client', c.name, 'stage', l.stage_label,
               'due_at', case when l.prio_late and (not l.due_late or l.prio_by < l.current_final_due_at)
                              then l.prio_by else l.current_final_due_at end,
               'days_over', greatest(case when l.due_late then (now() at time zone 'Asia/Kuala_Lumpur')::date - (l.current_final_due_at at time zone 'Asia/Kuala_Lumpur')::date end,
                                     case when l.prio_late then floor(extract(epoch from (now() - l.prio_by)) / 86400)::int end),
               'over_minutes', case when l.prio_late then floor(extract(epoch from (now() - l.prio_by)) / 60)::int end,
               'owner', (select tm.name
                           from public.ops_task_assignees a
                           join public.team_members tm on tm.id = a.team_member_id
                          where a.task_id = l.id and a.responsibility = 'owner'
                            and a.ended_at is null
                          limit 1)) as x
        from late_now l
        left join public.clients c on c.id = l.client_id
       where (l.due_late or l.prio_late) and not p_light
    ) q
  ),

  /* 3. HOW LONG EACH STAGE TAKES. A task enters a stage at the event that
        names it and leaves at the next event, or at its own ending, or now.
        Only spans that were ENTERED inside the period are counted, so the
        window means what it says and a task that sat in Editing since March
        does not land in every report for ever. */
  spans as (
    select e.task_id,
           e.to_value ->> 'stage_key' as stage_key,
           e.created_at as from_at,
           coalesce(
             lead(e.created_at) over (partition by e.task_id order by e.created_at),
             t.completed_at, t.cancelled_at, now()) as to_at
      from public.ops_task_events e
      join public.ops_tasks t on t.id = e.task_id
     where e.event_type in ('task_created', 'stage_changed')
       and e.to_value ->> 'stage_key' is not null
       and public.ops_task_in_scope(t.id)
       /* Only a span entered in the period is counted, and its end is the
          task's next event, never an earlier one: what came before the
          period is not read (2026-10-18). */
       and e.created_at >= p_from
  ),
  /* One row per span and no grouping: an earlier draft grouped by the span's
     own timestamps, which silently collapsed two tasks that entered the same
     stage in the same instant into one measurement. The label is looked up
     once per stage below instead of aggregated here. */
  span_mins as (
    select s.stage_key,
           extract(epoch from (s.to_at - s.from_at)) / 60 as mins
      from spans s
     where s.from_at >= p_from and s.from_at < p_to
       and s.to_at > s.from_at
  ),
  stage_time as (
    select jsonb_agg(x order by x ->> 'label') as j from (
      select jsonb_build_object(
               'stage_key', stage_key,
               'label', coalesce((select w.label from public.ops_workflow_stages w
                                   where w.key = sm.stage_key limit 1), stage_key),
               'n', count(*),
               'median_minutes', round(percentile_cont(0.5) within group (order by mins))::int,
               'p90_minutes', round(percentile_cont(0.9) within group (order by mins))::int) as x
        from span_mins sm
       where not p_light
       group by stage_key
    ) q
  ),

  /* 4. WAS IT THERE ON TIME. Of the tasks that reached client review inside
        the period, how many got there on or before the date they were owed;
        the work still late is counted beside them (`late_open`).
        Replanning is counted beside it and never folded into it: an extension
        that moves the date would otherwise erase the miss it was granted for,
        and a rate that cannot be missed is not a measurement. */
  reached as (
    select distinct on (e.task_id)
           e.task_id, e.created_at as at, t.current_final_due_at as due,
           public.ops_priority_by(coalesce(t.priority_at, t.created_at), t.priority_level) as prio_by,
           (t.original_final_due_at is distinct from t.current_final_due_at) as replanned
      from public.ops_task_events e
      join public.ops_tasks t on t.id = e.task_id
      join public.ops_workflow_stages w
        on w.workflow_id = t.workflow_id and w.key = e.to_value ->> 'stage_key'
     where e.event_type = 'stage_changed'
       and w.stage_group = 'client_review'
       and public.ops_task_in_scope(t.id)
       and e.created_at >= p_from and e.created_at < p_to
     order by e.task_id, e.created_at
  ),
  /* Work still short of its review and past its deadline is a miss too
     (2026-10-19, the user: "there are late tasks yet showing 100% on time
     delivery"): counted in the period its first missed deadline fell in,
     and in any period that runs to now (its end within ten minutes of now:
     the page names the moment it asks), where it is still late. A task
     counted as reached in the period is not counted again. */
  late_open as (
    select l.id
      from late_now l
     where (l.due_late or l.prio_late)
       and not exists (select 1 from reached r where r.task_id = l.id)
       and (case when l.prio_late and (not l.due_late or l.prio_by < l.current_final_due_at)
                 then l.prio_by else l.current_final_due_at end) < p_to
       and ((case when l.prio_late and (not l.due_late or l.prio_by < l.current_final_due_at)
                  then l.prio_by else l.current_final_due_at end) >= p_from
            or p_to >= now() - interval '10 minutes')
  ),
  on_time as (
    select jsonb_build_object(
             'reached', count(*),
             'met', count(*) filter (where (due is null or (at at time zone 'Asia/Kuala_Lumpur')::date <= (due at time zone 'Asia/Kuala_Lumpur')::date)
                                       and (prio_by is null or at <= prio_by)),
             'missed', count(*) filter (where not ((due is null or (at at time zone 'Asia/Kuala_Lumpur')::date <= (due at time zone 'Asia/Kuala_Lumpur')::date)
                                                 and (prio_by is null or at <= prio_by))),
             'late_open', (select count(*) from late_open),
             'replanned', count(*) filter (where replanned)) as j
      from reached
  ),
  /* 4b. POSTED ON TIME (2026-10-19). Of the content whose post date fell in
         the period and has passed (Malaysia's day), or which went live, how
         much went live by its post date. Client approval counts here, as it
         does for the client; on-time delivery above is the team's own. */
  posted as (
    select jsonb_build_object(
             'due', count(*),
             'met', count(*) filter (where t.live_at is not null
                                       and (t.live_at at time zone 'Asia/Kuala_Lumpur')::date
                                           <= (t.publish_at at time zone 'Asia/Kuala_Lumpur')::date)) as j
      from public.ops_tasks t
     where t.publish_at >= p_from and t.publish_at < p_to
       and t.cancelled_at is null and t.archived_at is null
       and (t.live_at is not null
            or (t.publish_at at time zone 'Asia/Kuala_Lumpur')::date < (now() at time zone 'Asia/Kuala_Lumpur')::date)
       and exists (select 1 from public.ops_workflow_stages s
                    where s.workflow_id = t.workflow_id and s.stage_group = 'live')
       and public.ops_task_in_scope(t.id)
  ),

  /* 5. BY PERSON. The foundation of a KPI and not a KPI: what somebody
        finished in the window, how much of it was on time, and how long their
        work took end to end. No ranking and no score — a number a person can
        check is worth more than a league table nobody trusts. */
  done as (
    select t.id, t.created_at, t.completed_at as ended,
           t.current_final_due_at as due,
           public.ops_priority_by(coalesce(t.priority_at, t.created_at), t.priority_level) as prio_by,
           /* When a priority's deadline was met: the first move into its
              review or beyond (never On hold, Blocked or Cancelled). */
           (select min(e.created_at)
              from public.ops_task_events e
              join public.ops_workflow_stages w
                on w.workflow_id = t.workflow_id and w.key = e.to_value ->> 'stage_key'
              join pfloors pf on pf.workflow_id = t.workflow_id
             where e.task_id = t.id and e.event_type = 'stage_changed'
               and w.position >= pf.at and w.stage_group not in ('kiv', 'blocked', 'cancelled')) as met_at,
           /* When it reached client review (2026-10-22, OVW-2): the day the
              due date is owed at, as the on-time ring reads it. */
           (select min(e.created_at)
              from public.ops_task_events e
              join public.ops_workflow_stages w
                on w.workflow_id = t.workflow_id and w.key = e.to_value ->> 'stage_key'
             where e.task_id = t.id and e.event_type = 'stage_changed'
               and w.stage_group = 'client_review') as review_at,
           (select a.team_member_id
              from public.ops_task_assignees a
             where a.task_id = t.id and a.responsibility = 'owner'
             order by a.ended_at nulls first, a.assigned_at desc
             limit 1) as owner_id
      from public.ops_tasks t
     where t.completed_at is not null
       and t.completed_at >= p_from and t.completed_at < p_to
       and public.ops_task_in_scope(t.id)
  ),
  by_person as (
    select jsonb_agg(x order by x ->> 'name') as j from (
      select jsonb_build_object(
               'team_member_id', d.owner_id,
               'name', coalesce(tm.name, 'Nobody'),
               'completed', count(*),
               'on_time', count(*) filter (where (d.due is null
                                                 or (coalesce(d.review_at, d.met_at, d.ended) at time zone 'Asia/Kuala_Lumpur')::date
                                                    <= (d.due at time zone 'Asia/Kuala_Lumpur')::date)
                                         and (d.prio_by is null or coalesce(d.met_at, d.ended) <= d.prio_by)),
               'median_cycle_minutes',
                 round(percentile_cont(0.5) within group (
                   order by extract(epoch from (d.ended - d.created_at)) / 60))::int) as x
        from done d
        left join public.team_members tm on tm.id = d.owner_id
       group by d.owner_id, tm.name
    ) q
  ),

  /* 6. WHO IS CARRYING THE OPEN WORK (2026-09-28). One row a Task Owner:
        the open tasks they hold, and how many of those are late by the rule
        in 2 above. The team's whole queue is `ops.all`, so it is answered
        only where that part is granted. */
  open_by_person as (
    select jsonb_agg(x order by (x ->> 'open')::int desc, x ->> 'name') as j from (
      select jsonb_build_object(
               'team_member_id', o.owner_id,
               'name', coalesce(tm.name, 'No task owner'),
               'open', count(*),
               'late', count(*) filter (where o.is_late)) as x
        from (select l.id,
                     (select a.team_member_id
                        from public.ops_task_assignees a
                       where a.task_id = l.id and a.responsibility = 'owner' and a.ended_at is null
                       limit 1) as owner_id,
                     (l.due_late or l.prio_late) as is_late
                from late_now l) o
        left join public.team_members tm on tm.id = o.owner_id
       where public.ops_granted('ops.all', 'view') and not p_light
       group by o.owner_id, tm.name
    ) q
  )

  select jsonb_build_object(
           'from', p_from, 'to', p_to,
           'running',    coalesce((select j from running), '[]'::jsonb),
           'late',       coalesce((select j from late), '[]'::jsonb),
           'stage_time', coalesce((select j from stage_time), '[]'::jsonb),
           'on_time',    coalesce((select j from on_time), '{}'::jsonb),
           'posted',     coalesce((select j from posted), '{}'::jsonb),
           'by_person',  coalesce((select j from by_person), '[]'::jsonb),
           'open_by_person', case when public.ops_granted('ops.all', 'view')
                                  then coalesce((select j from open_by_person), '[]'::jsonb) end)
    into out;

  return out;
end $$;

revoke all on function public.ops_report_of(timestamptz, timestamptz, boolean) from public, anon;
grant execute on function public.ops_report_of(timestamptz, timestamptz, boolean) to authenticated;

create or replace function public.ops_report(
  p_from timestamptz default (now() - interval '90 days'),
  p_to   timestamptz default now())
returns jsonb
language sql stable security invoker set search_path = public as $$
  select public.ops_report_of(p_from, p_to, false)
$$;
grant execute on function public.ops_report(timestamptz, timestamptz) to authenticated;

/* The period and the one before it whole; each span after them (the six
   months' line) light. */
create or replace function public.ops_reports(p_ranges jsonb)
returns jsonb
language sql stable security invoker set search_path = public as $$
  select coalesce(jsonb_agg(public.ops_report_of((x.r ->> 'from')::timestamptz, (x.r ->> 'to')::timestamptz, x.n > 2) order by x.n), '[]'::jsonb)
    from jsonb_array_elements(case when jsonb_typeof(p_ranges) = 'array' then p_ranges else '[]'::jsonb end)
         with ordinality x(r, n)
   where x.n <= 12
$$;
revoke all on function public.ops_reports(jsonb) from public, anon;
grant execute on function public.ops_reports(jsonb) to authenticated;

-- END OF ON TIME ON MALAYSIA'S DAY -------------------------------------------

-- ===========================================================================
-- NEW MONTH NEVER REPLACES ONE — New month refuses a month the client already
-- holds rather than writing over it. 2026-10-22. Safe to run twice. Rollback
-- at the foot. Mirrored byte for byte in supabase/schema.sql under the same
-- banner; tests/ops.js compares the two.
--
-- WHY (the review of 2026-10-22, WRK-1, P1): New month opened on this month
-- with its fields empty; saved on a month the client held, the function
-- edited that month, so its posts planned became 0, its Reports ticks none
-- and its Drive link empty, and its open report task was cancelled.
--
-- WHAT IT CHANGES
--   * ops_engagement_upsert: a payload carrying `new: true` (New month) on a
--     client and month already held answers `exists` with the period and
--     writes nothing, also where another colleague made it a moment before.
--     A payload without it (Edit, a task joining its month) is as before.
--
-- ORDER: this file, then the pages (an old page sends no `new` and is
-- answered as before). ROLLBACK: MONTH REPORTS' ops_engagement_upsert.
-- ===========================================================================

create or replace function public.ops_engagement_upsert(p_payload jsonb)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m public.team_members;
  cid uuid;
  per text;
  eid uuid;
  k text;
  fresh boolean := false;
  prev public.ops_engagements;
  v_day integer;
  v_reports text[];
  v_was_day integer;
  v_new boolean := coalesce((p_payload ->> 'new')::boolean, false);
begin
  p_payload := p_payload - 'new';
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'not-team'); end if;
  if not public.allowed('ops', 'work') then return jsonb_build_object('error', 'denied'); end if;
  cid := (p_payload ->> 'client_id')::uuid;
  per := p_payload ->> 'period';
  if cid is null or not exists (select 1 from public.clients where id = cid) then
    return jsonb_build_object('error', 'client-required');
  end if;
  if per is null or per !~ '^\d{4}-\d{2}$' then return jsonb_build_object('error', 'bad-period'); end if;
  if p_payload ? 'start_day' and (nullif(p_payload ->> 'start_day', '') is null
     or (p_payload ->> 'start_day') !~ '^\d{1,2}$' or (p_payload ->> 'start_day')::integer not between 1 and 28) then
    return jsonb_build_object('error', 'bad-start-day');
  end if;
  if p_payload ? 'reports' then
    if jsonb_typeof(p_payload -> 'reports') <> 'array' then return jsonb_build_object('error', 'bad-reports'); end if;
    select coalesce(array_agg(distinct x), '{}') into v_reports from jsonb_array_elements_text(p_payload -> 'reports') x;
    if not (v_reports <@ array['social', 'ads']::text[]) then return jsonb_build_object('error', 'bad-reports'); end if;
  end if;

  select e.id into eid from public.ops_engagements e where e.client_id = cid and e.period = per;
  /* New month never edits a month the client holds (2026-10-22, WRK-1). */
  if eid is not null and v_new then return jsonb_build_object('error', 'exists', 'period', per); end if;
  if eid is null then
    select * into prev from public.ops_engagements o
     where o.client_id = cid and o.period < per order by o.period desc limit 1;
    v_day := coalesce((p_payload ->> 'start_day')::integer, prev.start_day, 1);
    v_reports := coalesce(v_reports, prev.reports, '{}');
    insert into public.ops_engagements (client_id, period, manager_id, planned_count, drive_url, created_by,
                                        reports, start_day)
    values (cid, per, coalesce((p_payload ->> 'manager_id')::uuid, m.id),
            coalesce((p_payload ->> 'planned_count')::integer, 0),
            nullif(p_payload ->> 'drive_url', ''), m.id, v_reports, v_day)
    on conflict (client_id, period) do nothing
    returning id into eid;
    /* Somebody else made it between the read and the write: theirs stands. */
    if eid is null then
      if v_new then return jsonb_build_object('error', 'exists', 'period', per); end if;
      select e.id into eid from public.ops_engagements e where e.client_id = cid and e.period = per;
    else
      fresh := true;
    end if;
  end if;
  if fresh then
    if not exists (select 1 from public.ops_engagements o where o.client_id = cid and o.id <> eid) then
    foreach k in array array['onboarding', 'pre_ads'] loop
      insert into public.ops_engagement_checks (engagement_id, key) values (eid, k)
      on conflict do nothing;
    end loop;
    end if;
    perform public.ops_engagement_log(eid, 'created', p_payload - 'client_id');
  else
    if not public.ops_may_see_engagement(eid) then return jsonb_build_object('error', 'denied'); end if;
    /* Asked for with nothing to change, the month is answered as it stands:
       a task made for a month joins it without editing it. */
    if (p_payload - 'client_id' - 'period') = '{}'::jsonb then
      return public.ops_engagement_json(eid) || jsonb_build_object('created', false);
    end if;
    select o.start_day into v_was_day from public.ops_engagements o where o.id = eid;
    update public.ops_engagements set
      manager_id = coalesce((p_payload ->> 'manager_id')::uuid, manager_id),
      planned_count = coalesce((p_payload ->> 'planned_count')::integer, planned_count),
      drive_url = case when p_payload ? 'drive_url' then nullif(p_payload ->> 'drive_url', '') else drive_url end,
      reports = coalesce(v_reports, reports),
      start_day = coalesce((p_payload ->> 'start_day')::integer, start_day),
      updated_at = now(), version = version + 1
    where id = eid;
    perform public.ops_engagement_log(eid, 'edited', p_payload - 'client_id' - 'period');
  end if;
  perform public.ops_engagement_sync_reports(eid,
    v_was_day is not null and v_was_day is distinct from (select o.start_day from public.ops_engagements o where o.id = eid));
  return public.ops_engagement_json(eid) || jsonb_build_object('created', fresh);
end $$;
grant execute on function public.ops_engagement_upsert(jsonb) to authenticated;

-- END OF NEW MONTH NEVER REPLACES ONE ----------------------------------------

-- ===========================================================================
-- CREATORS OFFERED ARE FILED — adding creators to a campaign, its Undo and a
-- creator's Remove are written to the Activity record (2026-10-22, CMP-3)
-- ===========================================================================
-- WHY: Add creators, its Undo and Remove of an offered creator wrote no
-- activity row; only an offer made again was filed, so a campaign's
-- Activity never showed who was put before the client or taken away.
--
-- WHAT IT CHANGES
--   * `activity_section()` files `campaign.offered` and
--     `campaign.unoffered` under Creator Campaigns, as the console's
--     ACTION_LABEL names them.
--
-- ORDER: this file, then the pages (a row filed before it reads under
-- Other until it runs). Safe to run twice. Mirrored byte for byte in
-- supabase/schema.sql under the same banner; tests/sql.js compares the
-- last restatement.
--
-- ROLLBACK: the activity_section() of the band before this one (SUPPLIERS
-- OWN SECTION's), run again.
-- ===========================================================================

create or replace function public.activity_section(p_action text)
returns text
language sql immutable parallel safe as $$
  select case
    when action in ('campaign.bulk', 'campaign.closed', 'campaign.confirmed',
                    'campaign.created', 'campaign.dates', 'campaign.deleted', 'campaign.edited',
                    'campaign.file_added', 'campaign.file_deleted', 'campaign.file_hidden',
                    'campaign.file_shown', 'campaign.qc',
                    'campaign.invoice', 'campaign.invoice_file',
                    'campaign.invoice_removed', 'campaign.keyed', 'campaign.locked',
                    'campaign.offered', 'campaign.opened', 'campaign.rate', 'campaign.rated',
                    'campaign.reinstated', 'campaign.replaced', 'campaign.results', 'campaign.review',
                    'campaign.stage', 'campaign.submitted', 'campaign.task_linked',
                    'campaign.task_unlinked', 'campaign.unbooked',
                    'campaign.unkeyed', 'campaign.unoffered', 'campaign.whatsapp', 'campaign.withdrawn', 'creator.added',
                    'creator.code', 'creator.links', 'creator.links_restored',
                    'creator.links_self', 'creator.off', 'creator.on', 'creator.removed',
                    'creator.updated') then 'campaigns'
    when action in ('client.action_done', 'client.action_reopened', 'client.added',
                    'client.billing', 'client.brand', 'client.deleted', 'client.edited',
                    'client.quotation', 'client.review_on', 'client.service', 'client.service_changed',
                    'client.service_deleted', 'client.service_removed', 'client.service_restored', 'client.stage', 'client.touch',
                    'client.touch_deleted', 'client.touch_edited', 'client.touch_removed',
                    'client.touch_restored', 'contact.added', 'contact.deleted',
                    'contact.edited', 'contact.portal_invite', 'contact.portal_off',
                    'contact.portal_on', 'contact.primary', 'contact.removed',
                    'contact.restored',
                    'request.changed', 'request.raised',
                    'request.reinstated', 'request.replied', 'request.withdrawn',
                    'service.override') then 'clients'
    when action in ('wa.sent', 'wa.template') then 'whatsapp'
    when action in ('report.ai_drafted', 'report.ai_failed', 'report.audited', 'report.confirmed',
                    'report.created', 'report.deleted', 'report.published',
                    'report.reassigned', 'report.returned', 'report.revised', 'report.saved',
                    'report.submitted', 'report.unpublished') then 'reports'
    when action in ('qr.created', 'qr.restored', 'qr.revoked', 'shortlink.created',
                    'shortlink.deleted', 'shortlink.imported', 'shortlink.updated') then 'links'
    when action in ('ops.deleted', 'ops.month_deleted', 'ops.numbering') then 'ops'
    when action in ('document.deleted', 'document.issued', 'document.reissued',
                    'document.restored', 'document.signed', 'document.superseded',
                    'document.unsigned', 'document.verified', 'document.voided',
                    'register.added', 'register.edited') then 'register'
    when action in ('supplier.added', 'supplier.approved', 'supplier.deleted', 'supplier.edited') then 'suppliers'
    when action in ('client.drive', 'client.handles', 'client.profile',
                    'client.removed', 'drive.imported', 'link.reset', 'post.added',
                    'post.deleted', 'post.edited', 'reapproval.requested',
                    'review.approved', 'review.changes', 'review.removed',
                    'review.unconfirmed',
                    'set.created', 'set.deleted', 'set.month', 'set.published', 'set.renamed',
                    'set.task_linked', 'set.task_unlinked',
                    'set.withdrawn') then 'review'
    when action in ('script.approved', 'script.changes', 'script.created', 'script.deleted',
                    'script.link', 'script.saved', 'script.shared', 'script.shot',
                    'script.unshared') then 'scripts'
    when action in ('handbook.added', 'handbook.archived', 'handbook.deleted',
                    'handbook.edited', 'handbook.restored', 'handbook.version') then 'handbook'
    when action in ('service.added', 'service.changed', 'service.deleted',
                    'service.off', 'service.on', 'service.published') then 'services'
    when action in ('team.added', 'team.changed', 'team.edited', 'team.group_added',
                    'team.group_changed', 'team.group_removed', 'team.invited') then 'team'
    else 'other'
  end
  from (select p_action as action) t
$$;
grant execute on function public.activity_section(text) to authenticated;

-- END OF CREATORS OFFERED ARE FILED -------------------------------------------

-- ===========================================================================
-- CAMPAIGN RESULTS NOT BELOW ZERO — a booking's post figures are counts
-- (2026-10-22, CMP-17)
-- ===========================================================================
-- WHY: the console's results fields took a negative impressions figure and
-- saved it; the creator's own page refuses one through creator_post_save,
-- the table did not.
--
-- WHAT IT CHANGES
--   * `option_posts_figures_check`: impressions, engagements and views are
--     null or zero and above. A row already below zero is set to null
--     first (a count below zero was never a figure).
--
-- ORDER: this file, then the pages (or either way: the page already reads
-- a refusal). Safe to run twice.
--
-- ROLLBACK
--   alter table public.option_posts drop constraint if exists option_posts_figures_check;
-- ===========================================================================

update public.option_posts set impressions = null where impressions < 0;
update public.option_posts set engagements = null where engagements < 0;
update public.option_posts set views = null where views < 0;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'option_posts_figures_check') then
    alter table public.option_posts add constraint option_posts_figures_check
      check (coalesce(impressions, 0) >= 0 and coalesce(engagements, 0) >= 0 and coalesce(views, 0) >= 0);
  end if;
end $$;

-- END OF CAMPAIGN RESULTS NOT BELOW ZERO --------------------------------------

-- ===========================================================================
-- BACKEND REVIEW REST — the remaining database findings of the 2026-10-22
-- backend review (the user, 2026-10-22: "Fix all"). 2026-10-22. Safe to run
-- twice. Rollback at the foot. Mirrored byte for byte in supabase/schema.sql
-- under the same banner; tests/sql.js compares the two.
--
-- WHAT CHANGED
--   BE-11. A device is never pushed out by another: `push_subscribe` takes
--     five new devices a target in any hour and twenty in all, refusing
--     `too-many` past either, where it used to drop the oldest, so a client's
--     link could no longer be used to push the client's own phones off.
--
-- ORDER: this file in the SQL Editor (`push_subscribe` holds a delete, which
--   the connector holds), then the pages. A page from before reads as it
--   did; a device refused `too-many` keeps its notifications off.
--
-- ROLLBACK
--   push_subscribe as PUSH NOTIFICATIONS defines it.
-- ===========================================================================

/* A device turns notifications on for what its page follows. A console
   follows one colleague and a creator's page one creator, so turning on
   there moves the device; a client's device adds each campaign it is turned
   on for. A device already following keeps its place; a new one is taken
   five a target in any hour and twenty in all, never by pushing another
   out (2026-10-22, BE-11). */
create or replace function public.push_subscribe(
  p_audience text, p_ref text, p_endpoint text, p_p256dh text, p_auth text, p_lang text default 'en')
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_target uuid;
  v_lang   text := case when p_lang = 'zh' then 'zh' else 'en' end;
begin
  if not public.push_endpoint_ok(p_endpoint)
     or coalesce(length(p_p256dh), 0) not between 80 and 100
     or coalesce(length(p_auth), 0) not between 16 and 32 then
    return jsonb_build_object('error', 'bad-subscription');
  end if;
  if p_audience not in ('team', 'client', 'creator') then
    return jsonb_build_object('error', 'bad-audience');
  end if;
  v_target := public.push_target(p_audience, p_ref);
  if v_target is null then
    return jsonb_build_object('error', case when p_audience = 'team' then 'not-team' else 'not-found' end);
  end if;

  if not exists (select 1 from public.push_subscriptions s where s.endpoint = p_endpoint and s.target = v_target) then
    perform pg_advisory_xact_lock(hashtext('push_subscribe:' || v_target::text));
    if (select count(*) from public.push_subscriptions s
         where s.target = v_target and s.created_at > now() - interval '1 hour') >= 5
       or (select count(*) from public.push_subscriptions s where s.target = v_target) >= 20 then
      return jsonb_build_object('error', 'too-many');
    end if;
  end if;

  if p_audience in ('team', 'creator') then
    delete from public.push_subscriptions s
     where s.endpoint = p_endpoint and s.audience = p_audience and s.target <> v_target;
  end if;
  insert into public.push_subscriptions
    (endpoint, p256dh, auth, audience, team_member_id, campaign_id, creator_id, lang)
  values (p_endpoint, p_p256dh, p_auth, p_audience,
          case when p_audience = 'team' then v_target end,
          case when p_audience = 'client' then v_target end,
          case when p_audience = 'creator' then v_target end, v_lang)
  on conflict (endpoint, target) do update
     set lang = excluded.lang, seen_at = now();
  update public.push_subscriptions s set p256dh = p_p256dh, auth = p_auth
   where s.endpoint = p_endpoint and (s.p256dh <> p_p256dh or s.auth <> p_auth);
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.push_subscribe(text, text, text, text, text, text) from public;
grant execute on function public.push_subscribe(text, text, text, text, text, text) to anon, authenticated;

-- END OF BACKEND REVIEW REST ------------------------------------------------

select public.functions_tidy();

-- ===========================================================================
-- FEEDBACK ASKED OF CLIENTS ALONE — a feedback request on WhatsApp goes to a
-- client's contact, never a lead's.
-- 2026-10-22. Safe to run twice. Rollback at the foot. Mirrored byte for
-- byte in supabase/schema.sql under the same banner; tests/sql.js compares
-- the two.
--
-- WHAT CHANGED (the menu review, MENU-1; the user, 2026-10-22: "Fix all")
--   The client record's ⋯ offered Request feedback on WhatsApp on a lead,
--   a contacted lead and a proposal, and wa_compose_prepare sent it.
--   * wa_compose_prepare refuses `feedback` to a contact whose client is at
--     Lead, Contacted or Proposal sent (`not-client`); every other purpose
--     and stage answers as before. The record's ⋯ no longer offers it there.
--
-- ROLLBACK
--   Run the wa_compose_prepare definition of the WHATSAPP LINK FROM THE
--   RECORD section of supabase/schema.sql again.
-- ===========================================================================

create or replace function public.wa_compose_prepare(p_to_kind text, p_to uuid, p_purpose text, p_ref uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  me   public.team_members := public.ops_me();
  k    public.client_contacts;
  cr   public.creators;
  c    public.clients;
  r    public.sm_reports;
  o    public.campaign_options;
  cp   public.campaigns;
  b    public.batches;
  q    public.quotations;
  d    public.client_documents;
  v_n  text;
begin
  if me.id is null then return jsonb_build_object('error', 'denied'); end if;
  if p_purpose not in ('message', 'report', 'feedback', 'creator', 'approval', 'quotation', 'offer')
     or p_to_kind not in ('contact', 'creator')
     or (p_purpose in ('report', 'feedback', 'approval', 'quotation', 'offer') and p_to_kind <> 'contact')
     or (p_purpose = 'creator' and p_to_kind <> 'creator') then
    return jsonb_build_object('error', 'bad-request');
  end if;
  if not public.wa_may_send(p_purpose, p_to_kind) then return jsonb_build_object('error', 'denied'); end if;
  if p_to_kind = 'contact' then
    select * into k from public.client_contacts x where x.id = p_to and x.archived_at is null;
    if k.id is null then return jsonb_build_object('error', 'not-found'); end if;
    select * into c from public.clients x where x.id = k.client_id;
    if c.id is null or not public.client_seen(c.id, 'view') then return jsonb_build_object('error', 'not-found'); end if;
    /* A feedback request asks a client about work done for them: a lead,
       contacted or proposed, has none (MENU-1, 2026-10-22). */
    if p_purpose = 'feedback' and coalesce(c.stage, 'lead') in ('lead', 'contacted', 'proposal') then
      return jsonb_build_object('error', 'not-client');
    end if;
    if p_purpose = 'report' then
      select * into r from public.sm_reports x where x.id = p_ref;
      if r.id is null or r.client_id <> c.id then return jsonb_build_object('error', 'not-found'); end if;
      if r.status <> 'published' then return jsonb_build_object('error', 'not-published'); end if;
    end if;
    /* A quotation or a Letter of Offer is the contact's own client's: a
       quotation not removed, a letter not voided. */
    if p_purpose = 'quotation' then
      select * into q from public.quotations x where x.id = p_ref;
      if q.id is null or q.client_id <> c.id or q.removed_at is not null then return jsonb_build_object('error', 'not-found'); end if;
      if q.status = 'not_proceeding' then return jsonb_build_object('error', 'void'); end if;
    end if;
    if p_purpose = 'offer' then
      select * into d from public.client_documents x where x.id = p_ref;
      if d.id is null or d.client_id <> c.id or d.kind not in ('offer', 'intent', 'cover') then
        return jsonb_build_object('error', 'not-found');
      end if;
      if (d.voided_at is not null or d.superseded_by is not null) then return jsonb_build_object('error', 'void'); end if;
    end if;
    /* An approval reminder names what waits on the client: a published
       content set of theirs, or a creator's draft at Reviewing on a
       campaign of theirs, each read at its own section. */
    if p_purpose = 'approval' then
      select * into b from public.batches x where x.id = p_ref;
      if b.id is not null then
        if b.client_id <> c.id or not public.allowed('review.sets', 'view') then return jsonb_build_object('error', 'not-found'); end if;
        if not coalesce(b.published, false) then return jsonb_build_object('error', 'not-waiting'); end if;
      else
        select * into o from public.campaign_options x where x.id = p_ref;
        if o.id is not null then select * into cp from public.campaigns x where x.id = o.campaign_id; end if;
        if o.id is null or cp.id is null or cp.client_id is distinct from c.id or not public.allowed('campaigns.campaigns', 'view') then
          return jsonb_build_object('error', 'not-found');
        end if;
        if o.state <> 'reviewing' then return jsonb_build_object('error', 'not-waiting'); end if;
      end if;
    end if;
    v_n := public.wa_number(coalesce(case when k.whatsapp !~ '^@' then k.whatsapp end, k.phone), c.market);
    if v_n is null then
      return jsonb_build_object('error', case when k.whatsapp ~ '^@' then 'username' else 'no-number' end);
    end if;
    return jsonb_build_object('ok', true, 'number', v_n, 'name', k.name, 'greeting', public.contact_greeting(k.salutation, k.name),
      'client_id', c.id, 'client', case when r.id is not null then coalesce(nullif(r.brand_name, ''), c.name) else c.name end,
      'subject', c.name, 'ref_kind', case when b.id is not null then 'set' when o.id is not null then 'option'
                       when q.id is not null then 'quotation' when d.id is not null then 'offer' end,
      -- an approval reminder's link button: the page that waits, past the
      -- site's root (the client's review page, the campaign's selection page)
      'link', case when b.id is not null then 'review/?k=' || c.access_token
                   when o.id is not null then 'creators/?k=' || cp.access_token end);
  end if;
  select * into cr from public.creators x where x.id = p_to;
  if cr.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if p_purpose = 'creator' then
    select * into o from public.campaign_options x where x.id = p_ref;
    if o.id is null or o.creator_id <> cr.id then return jsonb_build_object('error', 'not-found'); end if;
    select * into cp from public.campaigns x where x.id = o.campaign_id;
    if cp.id is null or (cp.client_id is not null and not public.client_seen(cp.client_id, 'view')) then
      return jsonb_build_object('error', 'not-found');
    end if;
    if o.state in ('option', 'shortlisted', 'backup', 'withdrawn', 'replaced') then
      return jsonb_build_object('error', 'not-booked');
    end if;
  elsif not cr.active then
    return jsonb_build_object('error', 'not-found');
  end if;
  v_n := public.wa_number(cr.whatsapp, 'MY');
  if v_n is null then return jsonb_build_object('error', 'no-creator-number'); end if;
  return jsonb_build_object('ok', true, 'number', v_n, 'name', cr.name, 'greeting', split_part(btrim(cr.name), ' ', 1),
    'client_id', cp.client_id,
    'campaign', case when cp.id is not null then coalesce(nullif(btrim(cp.title), ''), 'Your campaign') end,
    'code', cr.access_code, 'subject', coalesce(nullif(btrim(cp.title), ''), cr.name));
end $$;
revoke all on function public.wa_compose_prepare(text, uuid, text, uuid) from public, anon;
grant execute on function public.wa_compose_prepare(text, uuid, text, uuid) to authenticated;

-- END OF FEEDBACK ASKED OF CLIENTS ALONE -------------------------------------

-- ===========================================================================
-- DEPARTMENTS — the team's departments are a list kept in Settings, and the
-- department prize is worked out across the departments that take part
-- (2026-10-23)
-- ===========================================================================
-- WHY (the user, 2026-10-23: "can add more departments?", then "Editable
-- list in Settings"; on the department prize: "creative and marketing for
-- now. in the future could add more like sales etc. so do necessary changes
-- and prep for this"): a colleague's department was Creative or Marketing,
-- fixed by a check on three tables and by the department prize, which named
-- the two in its own code.
--
-- WHAT IT ADDS
--   * `departments` (key, name, active, in_prize, criteria, position): RLS
--     on, no policy, no grant. The key is made once from the name and never
--     moves; a rename changes the name alone. Seeded once, into an empty
--     table, with Creative and Marketing, both in the prize with the five
--     criteria the Performance page named for them.
--   * `team_members.department`, `perf_people.department` and
--     `perf_dept_scores.department` reference `departments(key)`, so a
--     department named anywhere is one on the list. The checks naming the
--     two are taken away by the SQL Editor part,
--     2026-10-23-departments-editor.sql; until it runs, a colleague can be
--     put only in Creative or Marketing.
--   * `departments_list()` (the team): every department, its colleagues
--     (active), whether it is in the prize and its criteria, in its order.
--   * `department_save(p_key, p_name, p_in_prize, p_criteria)` (Business
--     settings): adds a department (p_key null) or changes one. A name of 2
--     to 40 characters, unique in any case (`bad-name`, `taken`); a
--     department in the prize names its five criteria, each 2 to 60
--     characters (`criteria-needed`, `bad-criteria`); filed `team.changed`
--     under Departments, from and to.
--   * `department_set_active(p_key, p_on)` (Business settings): an
--     inactive department is offered to nobody and leaves the prize;
--     its colleagues keep it. Never asks; filed.
--   * The department prize (`perf_quarter_calc`, `perf_quarter_confirm`,
--     `perf_dept_save`) takes every active department in the prize, in the
--     list's order: Confirm waits for each one's scores
--     (`dept-scores-needed`), scores are entered only for one of them
--     (`bad-department`), and each department carries its criteria names
--     (`names`), kept in a confirmed snapshot. With none in the prize the
--     reason is `no-departments`.
--
-- ORDER: this file, then the pages, then the SQL Editor part. An old page
-- reads the two departments it knows from its own words and writes only
-- them, which the list holds. Safe to run twice. Rollback: run the
-- perf_quarter_calc, perf_quarter_confirm and perf_dept_save definitions
-- of DEPARTMENT SCORES ARE AN ADMIN'S and PERFORMANCE QUARTER LIVE in
-- supabase/schema.sql again, then revoke execute on the three department
-- functions from authenticated (the table and the references may stay).
-- ===========================================================================

create table if not exists public.departments (
  key text primary key check (key ~ '^[a-z][a-z0-9_]{1,23}$'),
  name text not null,
  active boolean not null default true,
  in_prize boolean not null default false,
  criteria jsonb,
  position int not null default 100,
  updated_at timestamptz not null default now(),
  updated_by uuid
);
alter table public.departments enable row level security;
revoke all on table public.departments from public, anon, authenticated;
create unique index if not exists departments_name_idx on public.departments (lower(name));

do $$
begin
  if exists (select 1 from public.departments) then return; end if;
  insert into public.departments (key, name, active, in_prize, criteria, position) values
    ('creative', 'Creative', true, true, jsonb_build_array('On-time creative delivery', 'Creative quality and revision',
       'Client performance support', 'Asset organisation', 'Cross-functional responsiveness'), 1),
    ('marketing', 'Marketing', true, true, jsonb_build_array('Client account health', 'Campaign planning and execution',
       'Posting and servicing accuracy', 'Reporting and proactive improvement', 'Brief and handover quality'), 2);
end $$;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'team_members_department_fkey') then
    alter table public.team_members add constraint team_members_department_fkey
      foreign key (department) references public.departments(key);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'perf_people_department_fkey') then
    alter table public.perf_people add constraint perf_people_department_fkey
      foreign key (department) references public.departments(key);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'perf_dept_scores_department_fkey') then
    alter table public.perf_dept_scores add constraint perf_dept_scores_department_fkey
      foreign key (department) references public.departments(key);
  end if;
end $$;

/* Every department, for the Team sheet, Performance and Settings. */
create or replace function public.departments_list()
returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.is_team() then return jsonb_build_object('error', 'denied'); end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
      'key', d.key, 'name', d.name, 'active', d.active, 'in_prize', d.in_prize,
      'criteria', coalesce(d.criteria, '[]'::jsonb),
      'members', (select count(*)::int from public.team_members t where t.department = d.key and t.active))
      order by d.position, lower(d.name))
    from public.departments d), '[]'::jsonb);
end $$;
revoke all on function public.departments_list() from public, anon;
grant execute on function public.departments_list() to authenticated;

/* The criteria a department's prize scores are entered under: five names,
   each 2 to 60 characters, else null. */
create or replace function public.department_criteria_ok(p_criteria jsonb)
returns jsonb
language plpgsql immutable set search_path = public as $$
declare v_out jsonb := '[]'::jsonb; v_i int; v_t text;
begin
  if p_criteria is null or jsonb_typeof(p_criteria) <> 'array' or jsonb_array_length(p_criteria) <> 5 then return null; end if;
  for v_i in 0..4 loop
    if jsonb_typeof(p_criteria -> v_i) <> 'string' then return null; end if;
    v_t := btrim(regexp_replace(p_criteria ->> v_i, '\s+', ' ', 'g'));
    if char_length(v_t) < 2 or char_length(v_t) > 60 then return null; end if;
    v_out := v_out || to_jsonb(v_t);
  end loop;
  return v_out;
end $$;
revoke all on function public.department_criteria_ok(jsonb) from public, anon, authenticated;

/* Add a department (p_key null) or change one. */
create or replace function public.department_save(p_key text, p_name text, p_in_prize boolean, p_criteria jsonb)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me public.team_members;
  v_name text := btrim(regexp_replace(coalesce(p_name, ''), '\s+', ' ', 'g'));
  v_old public.departments;
  v_crit jsonb;
  v_key text; v_base text; v_n int := 1;
  v_moves text[] := '{}';
begin
  if not public.ops_granted('team.settings', 'work') then return jsonb_build_object('error', 'denied'); end if;
  v_me := public.ops_me();
  if char_length(v_name) < 2 or char_length(v_name) > 40 then return jsonb_build_object('error', 'bad-name'); end if;
  if p_key is not null then
    select * into v_old from public.departments d where d.key = p_key for update;
    if v_old.key is null then return jsonb_build_object('error', 'not-found'); end if;
  end if;
  if exists (select 1 from public.departments d where lower(d.name) = lower(v_name) and d.key is distinct from p_key) then
    return jsonb_build_object('error', 'taken');
  end if;
  if p_criteria is not null and jsonb_typeof(p_criteria) = 'array' and jsonb_array_length(p_criteria) > 0 then
    v_crit := public.department_criteria_ok(p_criteria);
    if v_crit is null then return jsonb_build_object('error', 'bad-criteria'); end if;
  end if;
  if coalesce(p_in_prize, false) and v_crit is null then return jsonb_build_object('error', 'criteria-needed'); end if;
  if v_old.key is null then
    v_base := left(btrim(regexp_replace(lower(v_name), '[^a-z0-9]+', '_', 'g'), '_'), 20);
    if v_base !~ '^[a-z]' then v_base := 'dept_' || v_base; end if;
    v_base := left(v_base, 20);
    if char_length(v_base) < 2 then v_base := 'dept'; end if;
    v_key := v_base;
    while exists (select 1 from public.departments d where d.key = v_key) loop
      v_n := v_n + 1; v_key := v_base || v_n;
    end loop;
    insert into public.departments (key, name, active, in_prize, criteria, position, updated_at, updated_by)
    values (v_key, v_name, true, coalesce(p_in_prize, false), v_crit,
            coalesce((select max(d.position) from public.departments d), 0) + 1, now(),
            (select m.id from public.team_members m where m.id = v_me.id));
    insert into public.activity_log (actor, action, subject, detail)
    values (coalesce(v_me.name, 'admin'), 'team.changed', 'Departments',
      'Added: ' || v_name || case when coalesce(p_in_prize, false) then ' · in the department prize' else '' end);
    return jsonb_build_object('ok', true, 'key', v_key);
  end if;
  if v_old.name <> v_name then v_moves := v_moves || ('Name: ' || v_old.name || ' → ' || v_name); end if;
  if v_old.in_prize is distinct from coalesce(p_in_prize, false) then
    v_moves := v_moves || ('Department prize: ' || case when v_old.in_prize then 'In' else 'Out' end || ' → '
      || case when coalesce(p_in_prize, false) then 'In' else 'Out' end);
  end if;
  if v_old.criteria is distinct from v_crit then v_moves := v_moves || 'Criteria changed'::text; end if;
  if cardinality(v_moves) = 0 then return jsonb_build_object('ok', true, 'key', v_old.key); end if;
  update public.departments d set name = v_name, in_prize = coalesce(p_in_prize, false), criteria = v_crit,
         updated_at = now(), updated_by = (select m.id from public.team_members m where m.id = v_me.id)
   where d.key = v_old.key;
  insert into public.activity_log (actor, action, subject, detail)
  values (coalesce(v_me.name, 'admin'), 'team.changed', 'Departments', v_old.name || ' · ' || array_to_string(v_moves, ' · '));
  return jsonb_build_object('ok', true, 'key', v_old.key);
end $$;
revoke all on function public.department_save(text, text, boolean, jsonb) from public, anon;
grant execute on function public.department_save(text, text, boolean, jsonb) to authenticated;

/* Offer a department, or stop offering it. */
create or replace function public.department_set_active(p_key text, p_on boolean)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_me public.team_members; v_old public.departments;
begin
  if not public.ops_granted('team.settings', 'work') then return jsonb_build_object('error', 'denied'); end if;
  v_me := public.ops_me();
  select * into v_old from public.departments d where d.key = p_key for update;
  if v_old.key is null then return jsonb_build_object('error', 'not-found'); end if;
  if v_old.active = coalesce(p_on, false) then return jsonb_build_object('ok', true); end if;
  update public.departments d set active = coalesce(p_on, false), updated_at = now(),
         updated_by = (select m.id from public.team_members m where m.id = v_me.id)
   where d.key = p_key;
  insert into public.activity_log (actor, action, subject, detail)
  values (coalesce(v_me.name, 'admin'), 'team.changed', 'Departments',
    v_old.name || ' · ' || case when p_on then 'Inactive → Active' else 'Active → Inactive' end);
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.department_set_active(text, boolean) from public, anon;
grant execute on function public.department_set_active(text, boolean) to authenticated;

/* The quarter, its department prize across the departments in the prize. */
create or replace function public.perf_quarter_calc(p_quarter date)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_q date := date_trunc('quarter', p_quarter)::date;
  v_qe date := (date_trunc('quarter', p_quarter) + interval '3 months')::date;
  v_people jsonb; v_wins integer; v_each numeric; v_ind jsonb;
  v_depts jsonb; v_dwins integer; v_both boolean; v_why text; v_dp jsonb;
  v_open integer; v_missing integer; v_ended boolean := public.perf_today() >= (date_trunc('quarter', p_quarter) + interval '3 months')::date;
  v_ip numeric := public.perf_setting('prize_individual', date_trunc('quarter', p_quarter)::date);
  v_dpool numeric := public.perf_setting('prize_department', date_trunc('quarter', p_quarter)::date);
  v_dmin numeric := public.perf_setting('prize_department_min_total', date_trunc('quarter', p_quarter)::date);
begin
  with m as (
    select t.id as mid, t.name as mname, t.staff_code as mcode, t.department as mdept, t.active as mactive,
           public.perf_reviewed(t.id) as monlist, f.nmonths, f.nfinal, f.mean, f.emonth,
           (select count(*)::int from public.perf_reviews o
             where o.team_member_id = t.id and o.status <> 'final'
               and o.period >= v_q and o.period < v_qe) as nopen,
           exists (select 1 from public.perf_breaches b
                    where b.team_member_id = t.id and b.voided_at is null and b.severity = 4
                      and b.period >= v_q and b.period < v_qe) as ml4
      from public.team_members t
      cross join lateral (
        select count(*)::int as nmonths, (count(*) filter (where x.st = 'final'))::int as nfinal,
               round(avg((x.res ->> 'final')::numeric), 2) as mean,
               coalesce(bool_or(x.res ->> 'grade' = 'E'), false) as emonth
          from (select coalesce(r.result, public.perf_calc(r)) as res, r.status as st
                  from public.perf_reviews r
                 where r.team_member_id = t.id and r.status <> 'draft'
                   and r.period >= v_q and r.period < v_qe) x) f
     where f.nmonths > 0 or (t.active and public.perf_reviewed(t.id))
  ), e as (
    select m.*, array_remove(array[
             case when m.nmonths = 0 then 'no-month' end,
             case when m.emonth then 'e-month' end,
             case when m.ml4 then 'critical-breach' end,
             case when not m.mactive then 'inactive' end,
             case when not m.monlist then 'not-reviewed' end], null) as why
      from m
  ), w as (
    select e.*, cardinality(e.why) = 0 as ok,
           coalesce(cardinality(e.why) = 0
                    and e.mean = max(e.mean) filter (where cardinality(e.why) = 0) over (), false) as won
      from e
  ), p as (
    select w.*, count(*) filter (where w.won) over () as nwon,
           case when w.nmonths > 0 then rank() over (order by w.mean desc nulls last) end as mrank
      from w
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'team_member_id', p.mid, 'name', p.mname, 'staff_code', p.mcode, 'department', p.mdept,
           'active', p.mactive, 'reviewed', p.monlist, 'months', p.nmonths, 'finals', p.nfinal, 'open', p.nopen,
           'rank', p.mrank, 'average', p.mean,
           'grade', case when p.nmonths > 0 then public.perf_grade_at(p.mean, v_q) end,
           'e_month', p.emonth, 'l4', p.ml4, 'eligible', p.ok, 'reasons', to_jsonb(p.why),
           'prize', case when p.won then floor(v_ip * 100 / p.nwon) / 100 else 0 end)
         order by p.mean desc nulls last, p.mname), '[]'::jsonb),
         coalesce(max(p.nwon), 0)
    into v_people, v_wins
    from p;
  v_each := case when v_wins > 0 then floor(v_ip * 100 / v_wins) / 100 end;
  v_ind := jsonb_build_object('pool', v_ip, 'winners', v_wins, 'each', v_each,
    'paid', coalesce(v_each * v_wins, 0), 'remainder', v_ip - coalesce(v_each * v_wins, 0),
    'reason', case when v_wins = 0 then 'nobody-eligible' end);

  with d as (
    select k.key as dep, k.name as dname, k.criteria as dnames, s.c1, s.c2, s.c3, s.c4, s.c5, coalesce(s.critical, false) as crit,
           s.c1 + s.c2 + s.c3 + s.c4 + s.c5 as total, s.quarter is not null as entered,
           row_number() over (order by k.position, lower(k.name)) as ord
      from public.departments k
      left join public.perf_dept_scores s on s.quarter = v_q and s.department = k.key
     where k.active and k.in_prize
  ), x as (
    select d.*, bool_and(d.entered) over () as bothin,
           coalesce(d.total = max(d.total) over (), false) as istop
      from d
  ), y as (
    select x.*, (x.bothin and x.istop and x.total >= v_dmin and not x.crit) as won,
           coalesce((select array_agg(t.id order by t.name) from public.team_members t
                      where t.active and t.department = x.dep and public.perf_reviewed(t.id)), '{}'::uuid[]) as mems
      from x
  ), z as (
    select y.*, count(*) filter (where y.won) over () as nwon,
           case when y.won then floor((v_dpool * 100) / count(*) filter (where y.won) over ()) end as sharec
      from y
  )
  select jsonb_agg(jsonb_build_object(
           'department', z.dep, 'name', z.dname, 'names', coalesce(z.dnames, '[]'::jsonb), 'entered', z.entered,
           'criteria', case when z.entered then jsonb_build_array(z.c1, z.c2, z.c3, z.c4, z.c5) end,
           'total', z.total, 'grade', case when z.entered then public.perf_grade_at(z.total, v_q) end,
           'critical', z.crit, 'top', z.bothin and z.istop,
           'qualifies', z.entered and z.total >= v_dmin and not z.crit, 'won', z.won,
           'share', coalesce(z.sharec / 100, 0), 'members', to_jsonb(z.mems))
         order by z.ord),
         coalesce(max(z.nwon), 0), bool_and(z.bothin),
         case when bool_and(z.bothin) and max(z.nwon) = 0 then
           case when bool_or(z.istop and z.total >= v_dmin and z.crit) then 'critical-issue' else 'below-b' end end
    into v_depts, v_dwins, v_both, v_why
    from z;
  v_dp := jsonb_build_object('pool', v_dpool, 'winners', v_dwins,
    'paid', case when v_dwins > 0 then floor((v_dpool * 100) / v_dwins) * v_dwins / 100 else 0 end,
    'remainder', case when v_dwins > 0 then v_dpool - floor((v_dpool * 100) / v_dwins) * v_dwins / 100 else v_dpool end,
    'reason', case when v_depts is null then 'no-departments' when not v_both then 'scores-needed' else v_why end);

  select count(*)::int into v_open
    from public.perf_reviews r
   where r.status <> 'final' and r.period >= v_q and r.period < v_qe;
  select count(*)::int into v_missing
    from public.team_members t
    cross join generate_series(v_q, (v_qe - interval '1 month')::date, interval '1 month') g(mo)
   where t.active and public.perf_reviewed(t.id)
     and (g.mo + interval '1 month')::date <= public.perf_today()
     and not exists (select 1 from public.perf_reviews r where r.team_member_id = t.id and r.period = g.mo::date);

  return jsonb_build_object('quarter', v_q, 'word', public.perf_quarter_word(v_q),
    'ended', v_ended, 'provisional', not v_ended or v_open > 0 or v_missing > 0,
    'people', v_people, 'individual', v_ind,
    'departments', coalesce(v_depts, '[]'::jsonb), 'department_prize', v_dp,
    'open_months', v_open, 'missing_months', v_missing,
    'rules', jsonb_build_object('individual', v_ip, 'department', v_dpool, 'min_total', v_dmin,
      'grades', jsonb_build_object('A', public.perf_setting('grade_a', v_q), 'B', public.perf_setting('grade_b', v_q),
                                   'C', public.perf_setting('grade_c', v_q), 'D', public.perf_setting('grade_d', v_q))));
end $$;
revoke all on function public.perf_quarter_calc(date) from public, anon, authenticated;

/* A quarter is confirmed once every department in the prize is scored. */
create or replace function public.perf_quarter_confirm(p_token text, p_quarter date)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_err text; v_me public.team_members; v_q date; v_snap jsonb; v_x jsonb; v_open integer;
begin
  v_err := public.perf_check(p_token, 'work');
  if v_err is not null then return jsonb_build_object('error', v_err); end if;
  v_me := public.ops_me();
  v_q := date_trunc('quarter', p_quarter)::date;
  if v_q is null or v_q < date '2026-07-01' then return jsonb_build_object('error', 'before-first'); end if;
  if exists (select 1 from public.perf_rewards where kind = 'quarter' and period = v_q) then
    return public.perf_quarter(p_token, v_q);
  end if;
  if public.perf_today() < (v_q + interval '3 months')::date then
    return jsonb_build_object('error', 'quarter-open');
  end if;
  select count(*)::int into v_open
    from public.perf_reviews r
   where r.status <> 'final' and r.period >= v_q and r.period < (v_q + interval '3 months')::date;
  if v_open > 0 then
    return jsonb_build_object('error', 'months-open', 'count', v_open);
  end if;
  if exists (select 1 from public.departments k
              where k.active and k.in_prize
                and not exists (select 1 from public.perf_dept_scores s where s.quarter = v_q and s.department = k.key)) then
    return jsonb_build_object('error', 'dept-scores-needed');
  end if;
  v_snap := public.perf_quarter_calc(v_q);
  insert into public.perf_rewards (kind, period, snapshot, confirmed_by) values ('quarter', v_q, v_snap, v_me.id)
  on conflict (kind, period) do nothing;
  perform public.perf_log(null, null, 'quarter_confirmed', jsonb_build_object('key', v_q::text,
    'winners', v_snap -> 'individual' -> 'winners', 'departments', v_snap -> 'department_prize' -> 'winners'));
  for v_x in select * from jsonb_array_elements(v_snap -> 'people') loop
    if (v_x ->> 'active')::boolean then
      perform public.perf_notify((v_x ->> 'team_member_id')::uuid, 'perf.quarter',
        'Your ' || public.perf_quarter_word(v_q) || ' quarterly outcome is ready.',
        'perf.quarter.' || v_q || '.' || (v_x ->> 'team_member_id') || '.' || extract(epoch from now())::bigint);
    end if;
  end loop;
  return public.perf_quarter(p_token, v_q);
end $$;
revoke all on function public.perf_quarter_confirm(text, date) from public, anon;
grant execute on function public.perf_quarter_confirm(text, date) to authenticated;

/* A department's prize scores, for a department in the prize alone. */
create or replace function public.perf_dept_save(p_token text, p_quarter date, p_department text, p_payload jsonb)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_err text; v_me public.team_members; v_q date; v_c jsonb; v_i integer; v_v jsonb; v_n numeric[] := '{}';
  v_max constant numeric[] := array[25, 25, 20, 15, 15]; v_was public.perf_dept_scores; v_crit boolean;
  v_changed jsonb := '[]'::jsonb; v_old numeric[];
begin
  v_err := public.perf_check(p_token, 'work');
  if v_err is not null then return jsonb_build_object('error', v_err); end if;
  /* The department prize is decided by an admin alone: a member scoring
     another department could swing it. */
  if not public.perf_is_admin() then return jsonb_build_object('error', 'admin-only'); end if;
  v_me := public.ops_me();
  v_q := date_trunc('quarter', p_quarter)::date;
  if v_q is null or v_q < date '2026-07-01' then return jsonb_build_object('error', 'before-first'); end if;
  if p_department is null or not exists (select 1 from public.departments k
                                          where k.key = p_department and k.active and k.in_prize) then
    return jsonb_build_object('error', 'bad-department');
  end if;
  /* Nobody scores their own department: its members share its prize. */
  if v_me.department is not distinct from p_department then
    return jsonb_build_object('error', 'own-department');
  end if;
  if exists (select 1 from public.perf_rewards where kind = 'quarter' and period = v_q) then
    return jsonb_build_object('error', 'confirmed');
  end if;
  v_c := p_payload -> 'criteria';
  if v_c is null or jsonb_typeof(v_c) <> 'array' then return jsonb_build_object('error', 'bad-payload'); end if;
  if jsonb_array_length(v_c) <> 5 then return jsonb_build_object('error', 'bad-payload'); end if;
  for v_i in 1..5 loop
    v_v := v_c -> (v_i - 1);
    if jsonb_typeof(v_v) <> 'number' then
      return jsonb_build_object('error', 'bad-score', 'index', v_i, 'max', v_max[v_i]);
    end if;
    if (v_v #>> '{}')::numeric not between 0 and v_max[v_i]
       or round((v_v #>> '{}')::numeric, 1) <> (v_v #>> '{}')::numeric then
      return jsonb_build_object('error', 'bad-score', 'index', v_i, 'max', v_max[v_i]);
    end if;
    v_n := v_n || (v_v #>> '{}')::numeric;
  end loop;
  v_crit := coalesce((p_payload ->> 'critical')::boolean, false);
  select * into v_was from public.perf_dept_scores where quarter = v_q and department = p_department for update;
  insert into public.perf_dept_scores (quarter, department, c1, c2, c3, c4, c5, critical, entered_by, updated_at)
  values (v_q, p_department, v_n[1], v_n[2], v_n[3], v_n[4], v_n[5], v_crit, v_me.id, now())
  on conflict (quarter, department) do update set
    c1 = excluded.c1, c2 = excluded.c2, c3 = excluded.c3, c4 = excluded.c4, c5 = excluded.c5,
    critical = excluded.critical, entered_by = excluded.entered_by, updated_at = now();
  v_old := array[v_was.c1, v_was.c2, v_was.c3, v_was.c4, v_was.c5];
  for v_i in 1..5 loop
    if v_old[v_i] is distinct from v_n[v_i] then
      v_changed := v_changed || jsonb_build_array(jsonb_build_object('key', 'c' || v_i, 'from', v_old[v_i], 'to', v_n[v_i]));
    end if;
  end loop;
  if v_was.critical is distinct from v_crit then
    v_changed := v_changed || jsonb_build_array(jsonb_build_object('key', 'critical', 'from', v_was.critical, 'to', v_crit));
  end if;
  if jsonb_array_length(v_changed) > 0 then
    perform public.perf_log(null, null, 'dept_scored',
      jsonb_build_object('key', v_q::text, 'department', p_department, 'changed', v_changed));
  end if;
  return public.perf_quarter(p_token, v_q);
end $$;
revoke all on function public.perf_dept_save(text, date, text, jsonb) from public, anon, authenticated;
grant execute on function public.perf_dept_save(text, date, text, jsonb) to authenticated;

-- END OF DEPARTMENTS --------------------------------------------------------

-- ===========================================================================
-- DEPARTMENTS, THE SQL EDITOR PART — the checks that named Creative and
-- Marketing give way to the list, and a department nobody names can be
-- taken off it (2026-10-23)
-- ===========================================================================
-- WHY: 2026-10-23-departments.sql makes the department a reference to
-- `departments`. The three checks that named the two departments stand
-- until they are taken away, and the connector holds any statement naming
-- them, so this part runs in the SQL Editor, after that file.
--
-- WHAT IT CHANGES
--   * The checks `team_members_department_check`,
--     `perf_people_department_check` and
--     `perf_dept_scores_department_check` go; each column keeps its
--     reference to `departments(key)`.
--   * `department_delete(p_key)` (Business settings): takes a department
--     off the list where no colleague, review profile or prize score names
--     it (`in-use` with the colleagues counted), else `not-found`; filed
--     `team.changed` under Departments.
--
-- ORDER: after 2026-10-23-departments.sql. Safe to run twice. Rollback:
-- revoke execute on public.department_delete(text) from authenticated; the
-- checks are not put back (they would refuse every department added since).
-- ===========================================================================

alter table public.team_members drop constraint if exists team_members_department_check;
alter table public.perf_people drop constraint if exists perf_people_department_check;
alter table public.perf_dept_scores drop constraint if exists perf_dept_scores_department_check;

/* Take a department nobody names off the list. */
create or replace function public.department_delete(p_key text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_me public.team_members; v_old public.departments; v_n int;
begin
  if not public.ops_granted('team.settings', 'work') then return jsonb_build_object('error', 'denied'); end if;
  v_me := public.ops_me();
  select * into v_old from public.departments d where d.key = p_key for update;
  if v_old.key is null then return jsonb_build_object('error', 'not-found'); end if;
  select count(*)::int into v_n from public.team_members t where t.department = p_key;
  if v_n > 0 or exists (select 1 from public.perf_people p where p.department = p_key)
     or exists (select 1 from public.perf_dept_scores s where s.department = p_key) then
    return jsonb_build_object('error', 'in-use', 'members', v_n);
  end if;
  delete from public.departments d where d.key = p_key;
  insert into public.activity_log (actor, action, subject, detail)
  values (coalesce(v_me.name, 'admin'), 'team.changed', 'Departments', 'Removed: ' || v_old.name);
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.department_delete(text) from public, anon;
grant execute on function public.department_delete(text) to authenticated;

-- END OF DEPARTMENTS, THE SQL EDITOR PART ----------------------------------

-- ===========================================================================
-- SALES BY — a client records who brought it in, and a colleague who sees
-- their own clients only sees the clients they brought in too (2026-10-23)
-- ===========================================================================
-- WHY (the user, 2026-10-23: a sales executive in business development
-- whose group sees its own clients only "noticed that … the clients that
-- they handled have alr been handed over to other team members (for
-- operations and executions works) and hence unable to view it", then "Add
-- a Sales by field" and "Same as their group allows"): Own clients only
-- read the Person in charge alone, which moves to the colleague who runs
-- the work once a client is won.
--
-- WHAT IT CHANGES
--   * `clients.sales_by` (a colleague, `team_members(id)`): who brought the
--     client in, apart from Person in charge. Read with every client read
--     (granted with the record's columns), written with the client.
--     Trigger `clients_sales_by_guard`: a signed-in colleague puts
--     themselves, or nobody, on a client they add, and only Clients Full
--     Access names anyone else or changes it after (`sales-by`).
--   * `client_row_seen_by(stage, owner, sales_by, level)`: the scope rule,
--     where Own clients only now holds a client the colleague is Person in
--     charge of or brought in (Sales by), plus a lead nobody holds; the
--     band of the stage and the level asked are read as before, so the
--     group's own levels apply. `client_row_seen(stage, owner, level)`
--     stays, reading no Sales by.
--   * The rule's readers take it: `client_seen` (every client_scope
--     policy, through `client_scope_ok`), `client_scope_guard`,
--     `client_scope_removal`, `sm_report_gate`, `sm_reports_owed`,
--     `sm_report_months`, `sm_report_audit_save`, `sm_report_audit_last`
--     and `vic_clients`, each otherwise as its last definition.
--
-- ORDER: this file, then the pages. An old page never sends the column.
-- Safe to run twice. Rollback: run the earlier definitions of the nine
-- functions in supabase/schema.sql again (each before this band); the
-- column and the guard may stay.
-- ===========================================================================

alter table public.clients add column if not exists sales_by uuid references public.team_members(id);
grant select (sales_by) on table public.clients to authenticated;
grant insert (sales_by) on table public.clients to authenticated;
grant update (sales_by) on table public.clients to authenticated;
create index if not exists clients_sales_by_idx on public.clients (sales_by);

/* Who brought a client in is set by them on a client they add, else at
   Clients Full Access. A function's own write (a cascade, the quotation
   website's lead) and the connector pass. */
create or replace function public.clients_sales_by_guard()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_me public.team_members;
begin
  if pg_trigger_depth() > 1 or auth.jwt() is null then return new; end if;
  if tg_op = 'UPDATE' and new.sales_by is not distinct from old.sales_by then return new; end if;
  v_me := public.ops_me();
  if v_me.id is null or public.allowed('clients', 'manage') then return new; end if;
  if tg_op = 'INSERT' and (new.sales_by is null or new.sales_by = v_me.id) then return new; end if;
  raise exception 'Sales by is set at Clients Full Access.' using errcode = '42501', hint = 'sales-by';
end $$;
revoke all on function public.clients_sales_by_guard() from public, anon, authenticated;
create or replace trigger clients_sales_by_guard before insert or update of sales_by on public.clients
  for each row execute function public.clients_sales_by_guard();

/* The scope rule, with who brought the client in. */
create or replace function public.client_row_seen_by(p_stage text, p_owner text, p_sales_by uuid, p_level text)
returns boolean language plpgsql security definer stable set search_path = public as $$
declare
  t public.team_members;
  band text;
begin
  select * into t from public.team_members
   where lower(email) = lower(auth.jwt() ->> 'email') and active limit 1;
  if t.id is null or t.is_admin or t.role = 'admin' then return true; end if;
  band := case when p_stage in ('lead', 'contacted', 'proposal') then 'clients.leads'
               when p_stage = 'past' then 'clients.past' end;
  if band is not null and public.level_rank(coalesce(t.access ->> band, t.access ->> 'clients'))
                          < public.level_rank(p_level) then
    return false;
  end if;
  if coalesce(t.client_scope, 'all') = 'own' then
    if p_sales_by is not null and p_sales_by = t.id then return true; end if;
    if nullif(btrim(coalesce(p_owner, '')), '') is null then
      return coalesce(band = 'clients.leads', false);
    end if;
    return lower(btrim(p_owner)) = lower(btrim(coalesce(t.name, '')));
  end if;
  return true;
end $$;
revoke all on function public.client_row_seen_by(text, text, uuid, text) from public, anon, authenticated;

create or replace function public.client_seen(p_client uuid, p_level text default 'view')
returns boolean language plpgsql security definer stable set search_path = public as $$
declare
  st text;
  ow text;
  sb uuid;
begin
  if p_client is null then return true; end if;
  select c.stage, c.owner, c.sales_by into st, ow, sb from public.clients c where c.id = p_client;
  if not found then return true; end if;
  return public.client_row_seen_by(st, ow, sb, p_level);
end $$;
revoke all on function public.client_seen(uuid, text) from public, anon, authenticated;

create or replace function public.client_scope_guard()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  kind text := tg_argv[0];
  col  text := tg_argv[1];
  o jsonb;
  n jsonb := to_jsonb(new);
begin
  if pg_trigger_depth() > 1 or public.client_scope_free('work') then return new; end if;
  if tg_op = 'UPDATE' and tg_table_name = 'sm_report_versions'
     and coalesce(current_setting('adspace.keep_file', true), '') = 'on' then
    return new;
  end if;
  if tg_op = 'UPDATE' then
    o := to_jsonb(old);
    if (kind = 'self' and not public.client_row_seen_by(o ->> 'stage', o ->> 'owner', (o ->> 'sales_by')::uuid, 'work'))
       or (kind <> 'self' and not public.client_scope_ok(kind, (o ->> col)::uuid, 'work')) then
      raise exception 'This client is outside your access.' using errcode = '42501', hint = 'client-scope';
    end if;
  end if;
  if (kind = 'self' and not public.client_row_seen_by(n ->> 'stage', n ->> 'owner', (n ->> 'sales_by')::uuid, 'work'))
     or (kind <> 'self' and not public.client_scope_ok(kind, (n ->> col)::uuid, 'work')) then
    raise exception 'This client is outside your access.' using errcode = '42501', hint = 'client-scope';
  end if;
  return new;
end $$;
revoke all on function public.client_scope_guard() from public, anon, authenticated;

create or replace function public.client_scope_removal()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  kind text := tg_argv[0];
  col  text := tg_argv[1];
  o jsonb := to_jsonb(old);
begin
  if pg_trigger_depth() > 1 or public.client_scope_free('manage') then return old; end if;
  if (kind = 'self' and not public.client_row_seen_by(o ->> 'stage', o ->> 'owner', (o ->> 'sales_by')::uuid, 'manage'))
     or (kind <> 'self' and not public.client_scope_ok(kind, (o ->> col)::uuid, 'manage')) then
    raise exception 'This client is outside your access.' using errcode = '42501', hint = 'client-scope';
  end if;
  return old;
end $$;
revoke all on function public.client_scope_removal() from public, anon, authenticated;

create or replace function public.sm_report_gate(p_id uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.sm_reports;
  c public.clients;
  e public.ops_engagements;
  task public.ops_tasks;
  v_starts date;
  v_ends date;
  v_due timestamptz;
  v_made integer := 0;
  v_missing text[] := '{}';
begin
  if me.id is null or not public.allowed('reports', 'view') then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_id;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  select * into c from public.clients where id = r.client_id;
  if not public.client_row_seen_by(c.stage, c.owner, c.sales_by, 'view') then return jsonb_build_object('error', 'denied'); end if;
  if r.period_start < date '2026-10-01' or r.on_request then
    return jsonb_build_object('applies', false, 'ok', true, 'missing', '[]'::jsonb, 'on_request', r.on_request);
  end if;
  select x.* into e from public.ops_engagements x
   cross join lateral public.ops_month_span(x.period, x.start_day) s
   where x.client_id = r.client_id and x.status <> 'cancelled'
     and r.period_end between s.starts and s.ends
   order by x.period desc limit 1;
  if e.id is null then
    v_missing := v_missing || 'no-month'::text;
    v_due := ((r.period_end + public.app_setting('report_due_days', r.period_end)::integer)::timestamp + time '23:59') at time zone 'Asia/Kuala_Lumpur';
  else
    select s.starts, s.ends into v_starts, v_ends from public.ops_month_span(e.period, e.start_day) s;
    v_due := ((v_ends + public.app_setting('report_due_days', v_ends)::integer)::timestamp + time '23:59') at time zone 'Asia/Kuala_Lumpur';
    if not (r.kind = any (e.reports)) then
      v_missing := v_missing || 'not-ticked'::text;
    else
      select * into task from public.ops_tasks x
       where x.engagement_id = e.id and x.source_type = 'report_' || r.kind
         and x.cancelled_at is null and x.archived_at is null
       order by x.created_at desc limit 1;
      if task.id is null then
        v_missing := v_missing || 'no-task'::text;
      else
        v_due := coalesce(task.current_final_due_at, v_due);
      end if;
    end if;
    select count(*) into v_made from public.ops_tasks x
     where x.engagement_id = e.id and x.cancelled_at is null and x.archived_at is null
       and coalesce(x.source_type, '') not in ('report_social', 'report_ads');
    if v_made < e.planned_count then v_missing := v_missing || 'content'::text; end if;
  end if;
  return jsonb_build_object(
    'applies', true, 'ok', cardinality(v_missing) = 0, 'missing', to_jsonb(v_missing),
    'month', case when e.id is null then null else jsonb_build_object(
               'id', e.id, 'period', e.period, 'start_day', e.start_day, 'starts', v_starts, 'ends', v_ends,
               'reports', to_jsonb(e.reports)) end,
    'planned', coalesce(e.planned_count, 0), 'made', v_made,
    'task', case when task.id is null then null else jsonb_build_object(
              'id', task.id, 'task_no', task.task_no, 'stage_key', task.stage_key) end,
    'due', v_due, 'late', now() > v_due,
    'may_override', coalesce(me.is_admin, false) or me.role = 'admin' or public.allowed('reports', 'manage'));
end $$;

create or replace function public.sm_reports_owed(p_period text default null)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_period   text := coalesce(nullif(btrim(p_period), ''),
                       to_char(date_trunc('month', now() at time zone 'Asia/Kuala_Lumpur') - interval '1 month', 'YYYY-MM'));
  v_items    jsonb := '[]'::jsonb;
  v_seen     uuid[] := '{}';
  v_task     uuid;
  v_tdue     timestamptz;
  v_assignee text;
  v_due      timestamptz;
  v_found    boolean;
  e          record;
  k          text;
  r          record;
begin
  if not public.allowed('reports', 'manage') then return jsonb_build_object('error', 'denied'); end if;
  if v_period !~ '^[0-9]{4}-(0[1-9]|1[0-2])$' then return jsonb_build_object('error', 'bad-period'); end if;

  -- Every report a month of the period asks for, found or not started.
  for e in
    select x.id, x.client_id, x.reports, s.starts, s.ends, c.name as client_name, c.slug as client_slug
      from public.ops_engagements x
      join public.clients c on c.id = x.client_id
     cross join lateral public.ops_month_span(x.period, x.start_day) s
     where x.period = v_period and x.status <> 'cancelled' and cardinality(x.reports) > 0
       and public.client_row_seen_by(c.stage, c.owner, c.sales_by, 'view')
     order by c.name
  loop
    foreach k in array e.reports loop
      v_task := null; v_tdue := null; v_assignee := null;
      select x.id, x.current_final_due_at, m.name into v_task, v_tdue, v_assignee
        from public.ops_tasks x
        left join public.ops_task_assignees a
          on a.task_id = x.id and a.responsibility = 'owner' and a.ended_at is null
        left join public.team_members m on m.id = a.team_member_id
       where x.engagement_id = e.id and x.source_type = 'report_' || k
         and x.cancelled_at is null and x.archived_at is null
       order by x.created_at desc limit 1;
      v_due := coalesce(v_tdue,
        ((e.ends + public.app_setting('report_due_days', e.ends)::integer)::timestamp + time '23:59') at time zone 'Asia/Kuala_Lumpur');
      v_found := false;
      for r in
        select y.id, y.status, y.sent_on, b.name as brand_name
          from public.sm_reports y
          left join public.client_brands b on b.id = y.brand_id
         where y.client_id = e.client_id and y.kind = k and not y.on_request
           and y.period_end between e.starts and e.ends
         order by b.name nulls first, y.period_start
      loop
        v_found := true;
        v_seen := v_seen || r.id;
        v_items := v_items || jsonb_build_object(
          'client_id', e.client_id, 'client', e.client_name, 'slug', e.client_slug, 'kind', k,
          'brand', r.brand_name, 'report_id', r.id, 'status', r.status, 'sent_on', r.sent_on,
          'asked', true, 'task_id', v_task, 'assignee', v_assignee, 'due', v_due,
          'late', r.status <> 'published' and now() > v_due);
      end loop;
      if not v_found then
        v_items := v_items || jsonb_build_object(
          'client_id', e.client_id, 'client', e.client_name, 'slug', e.client_slug, 'kind', k,
          'brand', null, 'report_id', null, 'status', 'none', 'sent_on', null,
          'asked', true, 'task_id', v_task, 'assignee', v_assignee, 'due', v_due, 'late', now() > v_due);
      end if;
    end loop;
  end loop;

  -- Every report made for the period that no month's tick asked for: it
  -- belongs to the month whose span holds its last day, else to the
  -- calendar month of that day.
  for r in
    select y.id, y.client_id, y.kind, y.status, y.sent_on, y.period_end,
           c.name as client_name, c.slug as client_slug, b.name as brand_name
      from public.sm_reports y
      join public.clients c on c.id = y.client_id
      left join public.client_brands b on b.id = y.brand_id
     where not (y.id = any (v_seen)) and not y.on_request
       and coalesce((select x.period from public.ops_engagements x
                      cross join lateral public.ops_month_span(x.period, x.start_day) s
                      where x.client_id = y.client_id and x.status <> 'cancelled'
                        and y.period_end between s.starts and s.ends
                      order by x.period desc limit 1),
                    to_char(y.period_end, 'YYYY-MM')) = v_period
       and public.client_row_seen_by(c.stage, c.owner, c.sales_by, 'view')
     order by c.name, y.kind, b.name nulls first
  loop
    v_due := ((r.period_end + public.app_setting('report_due_days', r.period_end)::integer)::timestamp + time '23:59') at time zone 'Asia/Kuala_Lumpur';
    v_items := v_items || jsonb_build_object(
      'client_id', r.client_id, 'client', r.client_name, 'slug', r.client_slug, 'kind', r.kind,
      'brand', r.brand_name, 'report_id', r.id, 'status', r.status, 'sent_on', r.sent_on,
      'asked', false, 'task_id', null, 'assignee', null, 'due', v_due,
      'late', r.status <> 'published' and now() > v_due);
  end loop;

  return jsonb_build_object('period', v_period, 'items', v_items);
end $$;
revoke all on function public.sm_reports_owed(text) from public, anon, authenticated;
grant execute on function public.sm_reports_owed(text) to authenticated;

create or replace function public.sm_report_months(p_client uuid, p_kind text default 'social')
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  c public.clients;
begin
  if me.id is null or not public.allowed('reports', 'view') then return jsonb_build_object('error', 'denied'); end if;
  if coalesce(p_kind, '') not in ('social', 'ads') then return jsonb_build_object('error', 'bad-kind'); end if;
  select * into c from public.clients where id = p_client;
  if c.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if not public.client_row_seen_by(c.stage, c.owner, c.sales_by, 'view') then return jsonb_build_object('error', 'denied'); end if;
  return jsonb_build_object(
    'may_override', coalesce(me.is_admin, false) or me.role = 'admin' or public.allowed('reports', 'manage'),
    'white_label', coalesce(c.white_label, false),
    'months', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', e.id, 'period', e.period, 'start_day', e.start_day,
               'starts', s.starts, 'ends', s.ends, 'status', e.status,
               'asks', p_kind = any (coalesce(e.reports, '{}'::text[])),
               'planned', coalesce(e.planned_count, 0),
               'report', (select r.id from public.sm_reports r
                           where r.client_id = e.client_id and r.kind = p_kind and r.brand_id is null
                             and not r.on_request and r.period_end between s.starts and s.ends
                           order by r.period_start desc limit 1))
             order by e.period desc)
        from public.ops_engagements e
       cross join lateral public.ops_month_span(e.period, e.start_day) s
       where e.client_id = p_client and e.status <> 'cancelled'), '[]'::jsonb));
end $$;

create or replace function public.sm_report_audit_save(p_id uuid, p_outcome text, p_rows jsonb default '[]'::jsonb,
                                                       p_note text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.sm_reports;
  c public.clients;
  prev public.sm_report_audits;
  v_rows jsonb := coalesce(p_rows, '[]'::jsonb);
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
  v_print text;
  v_id uuid;
  v_at timestamptz;
  v_word text;
begin
  if me.id is null or not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if coalesce(p_outcome, '') not in ('match', 'mismatch', 'unavailable', 'override') then
    return jsonb_build_object('error', 'bad-outcome');
  end if;
  if jsonb_typeof(v_rows) is distinct from 'array' or jsonb_array_length(v_rows) > 500 or length(v_rows::text) > 200000 then
    return jsonb_build_object('error', 'bad-rows');
  end if;
  if p_outcome = 'match' then v_rows := '[]'::jsonb; end if;
  if p_outcome = 'mismatch' and jsonb_array_length(v_rows) = 0 then return jsonb_build_object('error', 'bad-rows'); end if;
  select * into r from public.sm_reports where id = p_id for update;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  select * into c from public.clients where id = r.client_id;
  if not public.client_row_seen_by(c.stage, c.owner, c.sales_by, 'view') then return jsonb_build_object('error', 'denied'); end if;
  if not (r.status = 'draft' or (r.kind = 'ads' and r.status in ('review', 'confirmed'))) then
    return jsonb_build_object('error', 'not-open', 'status', r.status);
  end if;
  if not public.sm_report_audit_needed(p_id) then return jsonb_build_object('error', 'not-linked'); end if;
  select * into prev from public.sm_report_audits x
   where x.report_id = p_id and x.version_no = r.version_no
   order by x.read_at desc, x.id desc limit 1;
  if p_outcome = 'override' then
    if not (coalesce(me.is_admin, false) or me.role = 'admin') then return jsonb_build_object('error', 'denied'); end if;
    if prev.id is null or prev.outcome <> 'unavailable' then return jsonb_build_object('error', 'not-unavailable'); end if;
    if v_note is null then return jsonb_build_object('error', 'reason-required'); end if;
    v_rows := '[]'::jsonb;
  end if;
  if p_outcome = 'match' then v_note := null; end if;
  v_note := left(v_note, 500);
  v_print := public.sm_report_meta_print(p_id);
  if prev.id is not null and p_outcome <> 'override' and prev.outcome = p_outcome
     and prev.print is not distinct from v_print and prev.diffs = v_rows and prev.note is not distinct from v_note then
    update public.sm_report_audits set read_at = now(), by_id = me.id, by_name = me.name where id = prev.id
    returning id, read_at into v_id, v_at;
    return jsonb_build_object('ok', true, 'id', v_id, 'at', v_at, 'outcome', p_outcome, 'again', true);
  end if;
  insert into public.sm_report_audits (report_id, version_no, by_id, by_name, outcome, print, diffs, note)
  values (p_id, r.version_no, me.id, me.name, p_outcome, v_print, v_rows, v_note)
  returning id, read_at into v_id, v_at;
  if prev.id is null or prev.outcome <> p_outcome or p_outcome = 'override' then
    v_word := case p_outcome
      when 'match' then 'Against Meta: matches'
      when 'mismatch' then 'Against Meta: ' || jsonb_array_length(v_rows) || ' to fix'
      when 'unavailable' then 'Against Meta: not checked, Meta unavailable'
      else 'Against Meta: not checked, Meta unavailable · Reason: ' || v_note end;
    perform public.sm_report_log(p_id, 'report.audited', 'Report audit · ' || v_word);
  end if;
  return jsonb_build_object('ok', true, 'id', v_id, 'at', v_at, 'outcome', p_outcome);
end $$;
revoke all on function public.sm_report_audit_save(uuid, text, jsonb, text) from public, anon, authenticated;
grant execute on function public.sm_report_audit_save(uuid, text, jsonb, text) to authenticated;

create or replace function public.sm_report_audit_last(p_id uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.sm_reports;
  c public.clients;
  a public.sm_report_audits;
  v_print text;
begin
  if me.id is null or not public.allowed('reports', 'view') then return jsonb_build_object('error', 'denied'); end if;
  select * into r from public.sm_reports where id = p_id;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  select * into c from public.clients where id = r.client_id;
  if not public.client_row_seen_by(c.stage, c.owner, c.sales_by, 'view') then return jsonb_build_object('error', 'denied'); end if;
  v_print := public.sm_report_meta_print(p_id);
  select * into a from public.sm_report_audits x
   where x.report_id = p_id and x.version_no = r.version_no
   order by x.read_at desc, x.id desc limit 1;
  return jsonb_build_object(
    'needed', public.sm_report_audit_needed(p_id),
    'may_override', coalesce(me.is_admin, false) or me.role = 'admin',
    'blocks', public.sm_report_audit_blocks(p_id, null),
    'running', public.sm_report_running(p_id),
    'counts_from', r.period_end + 1,
    'held', exists (select 1 from public.sm_report_audits x where x.report_id = p_id and x.version_no = r.version_no),
    'print_since', (select min(x.read_at) from public.sm_report_audits x
                     where x.report_id = p_id and x.version_no = r.version_no and x.print = v_print),
    'print_moved', exists (select 1 from public.sm_report_audits x
                            where x.report_id = p_id and x.version_no = r.version_no and x.print is distinct from v_print),
    'last', case when a.id is null then null else jsonb_build_object(
      'at', a.read_at, 'by', a.by_name, 'outcome', a.outcome, 'rows', a.diffs, 'note', a.note,
      'current', a.print is not distinct from v_print) end);
end $$;
revoke all on function public.sm_report_audit_last(uuid) from public, anon, authenticated;
grant execute on function public.sm_report_audit_last(uuid) to authenticated;

create or replace function public.vic_clients()
returns table (client_id uuid, name text, since timestamptz, by_name text, note text)
language sql stable security definer set search_path = public as $$
  select c.id, c.name, c.vic_at, t.name, c.vic_note
    from public.clients c
    left join public.team_members t on t.id = c.vic_by
   where c.vic_at is not null
     and (public.ops_me()).id is not null
     and (public.client_row_seen_by(c.stage, c.owner, c.sales_by, 'view')
          or exists (select 1 from public.ops_tasks k
                       join public.ops_task_assignees a on a.task_id = k.id and a.ended_at is null
                      where k.client_id = c.id and a.team_member_id = (public.ops_me()).id))
$$;
revoke all on function public.vic_clients() from public, anon;
grant execute on function public.vic_clients() to authenticated;

-- END OF SALES BY ---------------------------------------------------------

-- ===========================================================================
-- LETTER TERMS — a Letter of Offer carries terms of its own under TERMS
-- (2026-10-23)
-- ===========================================================================
-- WHY (the user, 2026-10-23: "i need to add sentences like the Inclusions
-- under Terms, allow this function too"): TERMS held only the term and the
-- validity the letter works out.
--
-- WHAT IT CHANGES
--   * `issue_letter` reads `p_deal -> 'terms'`: the points typed in the
--     Issue Letter of Offer sheet, one a line, blanks dropped, ten at most
--     and 400 characters each (`bad-terms`), kept in the letter's snapshot
--     as `bill_to -> 'terms'`, which every redraw (the console, the client
--     portal) prints under TERMS after the term and the validity. Otherwise
--     as its last definition. An older page sends none; a letter issued
--     before holds none.
--
-- ORDER: this file, then the pages. Safe to run twice. Rollback: run the
-- earlier definition of `issue_letter` in supabase/schema.sql again (the
-- one before this band); letters already issued keep their terms.
-- ===========================================================================

create or replace function public.issue_letter(
  p_client    uuid,
  p_services  uuid[],
  p_idem      text,
  p_subtotal  numeric,
  p_tax       numeric,
  p_total     numeric,
  p_deal      jsonb   default '{}'::jsonb,
  p_replaces  uuid    default null,
  p_renewal   boolean default false,
  /* A reference somebody typed. Blank is the ordinary case and the counter
     below makes the number; where one is typed it is checked against every
     document that stands and the counter is not advanced, so filling a gap
     by hand never costs the next letter its place in the sequence. */
  p_serial    text    default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  who    text := lower(auth.jwt() ->> 'email');
  cl     public.clients%rowtype;
  ct     public.client_contacts%rowtype;
  me     public.team_members%rowtype;
  v_ym   text;
  v_seq  int;
  v_try  int;
  v_no   text;
  v_id   uuid;
  v_lines jsonb;
  v_n    int;
  v_bad  int;
  v_old  public.client_documents%rowtype;
  v_term int;
  v_each numeric;
  v_etax numeric;
  v_once numeric;
  v_otax numeric;
  v_sub  numeric;
  v_tax  numeric;
  v_tot  numeric;
  v_pct  numeric;
  v_qid  uuid;
  v_q    public.quotations%rowtype;
  v_tp   numeric;
  v_tpn  int;
  v_tadj boolean;
  v_qterm int;
  v_msub numeric;
  v_span numeric;
  v_even boolean;
  v_qt   jsonb;
  v_month boolean;
  v_terms jsonb;
begin
  if not public.allowed('clients.documents') then
    return jsonb_build_object('error', 'not-allowed');
  end if;
  if p_client is null or p_services is null or array_length(p_services, 1) is null then
    return jsonb_build_object('error', 'no-lines');
  end if;

  select * into cl from public.clients where id = p_client;
  if cl.id is null then return jsonb_build_object('error', 'no-client'); end if;

  -- The letter's own terms, one point a line, kept with what it was issued
  -- with and printed under TERMS after the term and the validity
  -- (2026-10-23): ten at most, each 1 to 400 characters.
  v_terms := coalesce((select jsonb_agg(btrim(t)) from jsonb_array_elements_text(
               case when jsonb_typeof(p_deal -> 'terms') = 'array' then p_deal -> 'terms' else '[]'::jsonb end) t
             where btrim(t) <> ''), '[]'::jsonb);
  if jsonb_array_length(v_terms) > 10
     or exists (select 1 from jsonb_array_elements_text(v_terms) t where length(t) > 400) then
    return jsonb_build_object('error', 'bad-terms');
  end if;

  -- The Client ID is what the serial is built from, so there is no letter
  -- without one. Staff enter it on the record; nothing invents it. A typed
  -- reference needs no code, because nothing is being built.
  v_no := nullif(btrim(coalesce(p_serial, '')), '');
  if v_no is null and coalesce(btrim(cl.client_code), '') = '' then
    return jsonb_build_object('error', 'no-client-code');
  end if;

  -- The same submission, pressed twice, is one letter. Answered before any
  -- number is reserved, so a double click cannot spend a serial either.
  if coalesce(btrim(p_idem), '') <> '' then
    select * into v_old from public.client_documents
      where client_id = p_client and idem_key = btrim(p_idem) limit 1;
    if v_old.id is not null then
      return jsonb_build_object('ok', true, 'repeat', true, 'id', v_old.id, 'number', v_old.number);
    end if;
  end if;

  -- A typed reference is checked before anything is written: the same shape
  -- the Register accepts, and refused where a document still holds it.
  if v_no is not null then
    if v_no !~ '^[A-Za-z0-9/._-]{3,40}$' then
      return jsonb_build_object('error', 'serial-shape');
    end if;
    if public.serial_taken(v_no) then
      return jsonb_build_object('error', 'serial-taken');
    end if;
  end if;

  -- Every id must be this client's own live line, and in a state this letter
  -- may carry: To quote always, Confirmed only on a deliberate renewal.
  select count(*) into v_bad from unnest(p_services) s(id)
    left join public.client_services cs
      on cs.id = s.id and cs.client_id = p_client and cs.archived_at is null
    where cs.id is null
       or (cs.state = 'confirmed' and not p_renewal)
       or cs.state not in ('quoted', 'confirmed');
  if v_bad > 0 then return jsonb_build_object('error', 'bad-lines'); end if;

  -- A line already on a live letter is not offered again by accident. The way
  -- through is to void that letter, or to name it as the one being replaced.
  select count(*) into v_bad
    from public.client_document_services m
    join public.client_documents d on d.id = m.document_id
   where m.service_id = any(p_services)
     and d.voided_at is null
     and d.superseded_by is null
     and d.verified_at is null
     and (p_replaces is null or d.id <> p_replaces);
  if v_bad > 0 then return jsonb_build_object('error', 'already-quoted'); end if;

  if p_replaces is not null then
    select * into v_old from public.client_documents
      where id = p_replaces and client_id = p_client;
    if v_old.id is null then return jsonb_build_object('error', 'no-replaces'); end if;
    if v_old.verified_at is not null then return jsonb_build_object('error', 'replaces-verified'); end if;
  end if;

  select * into ct from public.client_contacts
    where client_id = p_client and archived_at is null
    order by (id = cl.bill_contact_id) desc, is_primary desc, name limit 1;
  select * into me from public.team_members where lower(email) = who and active limit 1;

  -- A letter is signed by a person. issued_by is this row's name, so a team
  -- row named "Superadmin" printed that word under ADSPACE PLT on a client's
  -- letterhead. Refuse rather than draw a permission as a signatory.
  if not public.issuer_name_ok(me.name) then
    return jsonb_build_object('error', 'issuer-name', 'name', coalesce(me.name, ''));
  end if;

  -- The snapshot is built from the stored rows, never from what the browser
  -- sent: the words on a letter are the words the record held at that moment.
  select jsonb_agg(jsonb_build_object(
           'label', cs.label, 'unit', coalesce(cs.unit, ''), 'note', coalesce(cs.note, ''),
           'detail', coalesce(cs.detail, ''), 'state', cs.state,
           'qty', cs.qty, 'rate', cs.rate,
           'tenure', greatest(1, coalesce(cs.tenure, 1)),
           'start_on', coalesce(cs.start_on, ''),
           -- The line's own answer to whether its term prices it. Written into
           -- the snapshot because the letter is redrawn from it, and a letter
           -- must print the same figure every time it is drawn. A snapshot
           -- taken before this key existed carries none, which money.js reads
           -- as on, so those letters redraw as they were issued.
           'term_adjust', coalesce(cs.term_adjust, false),
           -- And the percentage that tick applies, so a later rate card can
           -- never move a figure this letter printed. Null on a line quoted
           -- before the column existed, which money.js reads as that card.
           'term_pct', cs.term_pct,
           'tax', cl.sst_applies is not false,
           -- The line's own tax code and its rate as issued (2026-10-22);
           -- none is the client's SST, as before.
           'tax_code', cs.tax_code,
           'tax_pct', (select t.rate from public.tax_codes t where t.code = cs.tax_code),
           'service_id', cs.id)
           order by cs.created_at)
    into v_lines
    from public.client_services cs
   where cs.id = any(p_services);
  if v_lines is null then return jsonb_build_object('error', 'no-lines'); end if;
  /* A line's tax code is one the team holds and offers (2026-10-22). */
  if exists (select 1 from public.client_services cs
              where cs.id = any(p_services) and cs.tax_code is not null
                and not exists (select 1 from public.tax_codes t where t.code = cs.tax_code and t.active)) then
    return jsonb_build_object('error', 'bad-tax');
  end if;

  /* The price is the database's (audit S4, 2026-10-10), worked as the
     letter draws it (js/documents.js priceOf, js/money.js rateFor): each
     line's rate with its term on it, rounded to the cent. Where every line
     of more than a month shares one term, those lines are priced by the
     month and times the term, and a line of one month is a one-off item
     with its own SST (2026-10-15: a one-off item beside them no longer
     turns the letter into one whole total); otherwise every line is its
     whole amount. SST at the rate in force today unless the client is
     exempt. The page's figures are kept only where they agree to the sen,
     so a line changed since the sheet opened, or a figure typed in a
     browser, is refused (`stale`) and the sheet reads the lines again. */
  select case when count(distinct greatest(1, coalesce(cs.tenure, 1)))
                     filter (where greatest(1, coalesce(cs.tenure, 1)) > 1) = 1
              then max(greatest(1, coalesce(cs.tenure, 1))) else 0 end
    into v_term
    from public.client_services cs where cs.id = any(p_services);
  /* A letter whose every line came from one quotation is priced as that
     quotation was (audit F, 2026-10-17), exactly as `quote_price` and
     `quote_adjust` total it (2026-10-17, the review's finding 7): a line
     the quotation bills by the month (`quotation_offer` ticks its term) is
     a monthly line whatever months Build quote gave it, its percentage
     taken once on their subtotal; a line with no term is one-off; SST at
     the quotation's rate. The page's figures are held to the same price
     (js/documents.js priceOf). */
  select case when count(*) filter (where cs.quotation_id is null) = 0
                   and count(distinct cs.quotation_id) = 1 then min(cs.quotation_id::text)::uuid end,
         count(distinct coalesce(cs.term_pct, 0)) filter (where coalesce(cs.term_adjust, false)),
         coalesce(bool_and(greatest(1, coalesce(cs.tenure, 1)) = 1) filter (where not coalesce(cs.term_adjust, false)), true),
         coalesce(max(cs.term_pct) filter (where coalesce(cs.term_adjust, false)), 0)
    into v_qid, v_tpn, v_tadj, v_tp
    from public.client_services cs where cs.id = any(p_services);
  /* Only while the quotation still stands (2026-10-17, the review's
     finding 2): unexpired by Malaysia's day and not removed. A renewal, or a
     letter replacing one after the quotation lapsed, is priced on today's
     rates, as any other letter. */
  if v_qid is not null and coalesce(v_tpn, 0) <= 1 and v_tadj and not coalesce(p_renewal, false) then
    select * into v_q from public.quotations q
     where q.id = v_qid and q.removed_at is null
       and q.valid_until >= (timezone('Asia/Kuala_Lumpur', now()))::date;
  end if;
  if v_q.id is not null then
    /* As quote_adjust totals it: the monthly lines' subtotal of quantity ×
       rate, the percentage once on it; where every one runs the quotation's
       term, a month's excl. SST, its SST rounded once, times the term; where
       Build quote gave a line months of its own, the whole span (each line's
       amount × its months) with the percentage and SST taken once on it.
       One-off lines and their SST apart. */
    v_qterm := greatest(1, coalesce((v_q.totals->>'term')::int, 1));
    v_pct := case when cl.sst_applies is false then 0
                  else coalesce((v_q.totals->>'sst_pct')::numeric, 0) end;
    /* The lines as the quotation reads them (a line with its term ticked is
       monthly, on its own months), totalled by the one calculation every
       quotation shares (2026-10-18). */
    v_qt := public.quote_totals(
      (select coalesce(jsonb_agg(jsonb_build_object(
                'basis', case when coalesce(cs.term_adjust, false) then 'month' else 'once' end,
                'qty', coalesce(cs.qty, 0), 'rate', coalesce(cs.rate, 0),
                'months', greatest(1, coalesce(cs.tenure, 1)),
                'sst', (select t.rate from public.tax_codes t where t.code = cs.tax_code))), '[]'::jsonb)
         from public.client_services cs where cs.id = any(p_services)),
      v_qterm, v_tp, v_pct);
    v_month := jsonb_typeof(v_qt->'month') = 'object';
    v_once := coalesce((v_qt->'once'->>'subtotal')::numeric, 0);
    v_otax := coalesce((v_qt->'once'->>'sst')::numeric, 0);
    if not v_month then
      v_sub := round(v_once, 2);
      v_tax := v_otax;
    elsif (v_qt->>'even')::boolean then
      v_each := (v_qt->'month'->>'excl')::numeric;
      v_etax := (v_qt->'month'->>'sst')::numeric;
      v_sub := round(v_each * v_qterm + v_once, 2);
      v_tax := v_etax * v_qterm + v_otax;
    else
      v_sub := (v_qt->>'span_excl')::numeric + round(v_once, 2);
      v_tax := (v_qt->>'span_incl')::numeric + round(v_once, 2) + v_otax - v_sub;
    end if;
    v_tot := v_sub + v_tax;
    /* The letter keeps what it was priced on, so a redraw prints the same:
       the quotation, its SST and its term (a snapshot with no `quote_term`
       was priced before this, and redraws as it was). */
    select jsonb_agg(l.e || jsonb_build_object('quotation_id', v_qid, 'quote_sst', v_pct, 'quote_term', v_qterm) order by l.n)
      into v_lines from jsonb_array_elements(v_lines) with ordinality l(e, n);
  else
    v_pct := case when cl.sst_applies is false then 0
                  else coalesce(public.app_setting('sst_pct', (timezone('Asia/Kuala_Lumpur', now()))::date), 0) end;
    /* Each line at its own SST rate (2026-10-22): its tax code's, else the
       client's. The SST is worked a rate at a time, rounded once each, so
       a letter on one rate prices as it always did. */
    with x as (
      select greatest(1, coalesce(cs.tenure, 1)) as n,
             coalesce(cs.qty, 0) *
             round(coalesce(cs.rate, 0) *
               case when cs.term_adjust is false then 1
                    when cs.term_pct is not null then 1 + cs.term_pct / 100
                    else case greatest(1, coalesce(cs.tenure, 1))
                           when 3 then 1 / 0.9 when 12 then 0.95 when 24 then 0.9 else 1 end
               end, 2) as v,
             coalesce((select t.rate from public.tax_codes t where t.code = cs.tax_code), v_pct) as r
        from public.client_services cs where cs.id = any(p_services)
    ), y as (
      select r,
             coalesce(sum(v) filter (where v_term > 0 and n = v_term), 0) as e,
             coalesce(sum(v * n) filter (where v_term = 0 or n <> v_term), 0) as o
        from x group by r
    )
    select coalesce(sum(e), 0), coalesce(sum(o), 0),
           coalesce(sum(round(e * r) / 100), 0), coalesce(sum(round(o * r) / 100), 0)
      into v_each, v_once, v_etax, v_otax
      from y;
    v_sub := round(v_each * greatest(v_term, 1), 2) + round(v_once, 2);
    v_tax := round(v_etax * greatest(v_term, 1), 2) + v_otax;
    v_tot := round(round(v_each + v_etax, 2) * greatest(v_term, 1), 2) + round(v_once + v_otax, 2);
  end if;
  if abs(coalesce(p_subtotal, -1) - v_sub) > 0.01 or abs(coalesce(p_tax, -1) - v_tax) > 0.01
     or abs(coalesce(p_total, -1) - v_tot) > 0.01 then
    return jsonb_build_object('error', 'stale', 'subtotal', v_sub, 'tax', v_tax, 'total', v_tot);
  end if;

  -- A typed reference spends no sequence number: the counter is the office's
  -- record of how many letters it has issued this month, and a person filling
  -- a gap by hand has not issued one more.
  if v_no is null then
    -- The month is Malaysian, because the office that numbers the letter is.
    v_ym := to_char(timezone('Asia/Kuala_Lumpur', now()), 'YYMM');

    -- The counter still advances on every automatic issue, and the upsert's
    -- row lock is what makes the scan below safe: a second issuer blocks here
    -- until the first has committed its letter, so the two never read the same
    -- gap as free. What the counter gives is a bound to scan within, not the
    -- number itself.
    insert into public.client_document_seq (client_id, ym, next_val)
         values (p_client, v_ym, 2)
    on conflict (client_id, ym)
      do update set next_val = public.client_document_seq.next_val + 1
      returning next_val - 1 into v_seq;

    -- The lowest free slot, not the counter's own value. A letter removed
    -- releases its reference (serial_taken stopped counting deletions on
    -- 2026-09-20), and without this the automatic path still counted upward
    -- past the gap: a client whose first two letters were issued in testing
    -- and removed started at 03 for ever. The counter is at least the number
    -- of letters issued this month, so a free slot exists at or below it
    -- unless somebody has typed references over the same range by hand; the
    -- cap covers that and refuses rather than looping.
    --
    -- Two digits is the floor, not the ceiling: the hundredth letter of a month
    -- widens to three rather than wrapping. Not lpad(): Postgres pads AND
    -- truncates to the width it is given, so lpad('100', 2, '0') is '10' and the
    -- hundredth letter would collide with the tenth.
    v_try := 1;
    loop
      v_no := 'AQL/' || cl.client_code || '/' || v_ym ||
              case when v_try < 100 then lpad(v_try::text, 2, '0') else v_try::text end;
      exit when not public.serial_taken(v_no);
      v_try := v_try + 1;
      if v_try > greatest(v_seq, 1) + 200 then
        return jsonb_build_object('error', 'no-serial');
      end if;
    end loop;
  end if;

  insert into public.client_documents
    (client_id, kind, number, issued_at, market, subtotal, tax, total,
     bill_to, lines, issued_by, client_code, idem_key)
  values
    (p_client, 'offer', v_no, (timezone('Asia/Kuala_Lumpur', now()))::date,
     public.client_bill_market(cl.market, cl.bill_sgd),
     round(coalesce(p_subtotal, 0), 2), round(coalesce(p_tax, 0), 2), round(coalesce(p_total, 0), 2),
     jsonb_build_object(
       'name', coalesce(cl.name, ''), 'legal_name', coalesce(cl.legal_name, ''),
       'address', coalesce(cl.billing_address, ''), 'regno', coalesce(cl.company_no, ''),
       'regno_old', coalesce(cl.company_no_old, ''), 'tin', coalesce(cl.tin, ''),
       'sst_no', coalesce(cl.sst_no, ''), 'sst_applies', cl.sst_applies is not false,
       'contact', coalesce(ct.name, ''), 'contact_role', coalesce(ct.role, ''),
       'contact_salutation', coalesce(ct.salutation, ''),
       -- A Singapore client billed in RM: its market and the rate in force,
       -- so the letter reads its figure in S$ beside it, as issued.
       'market', coalesce(cl.market, 'MY'),
       'fx_sgd', case when cl.market = 'SG' and not cl.bill_sgd then public.app_setting('fx_sgd', (timezone('Asia/Kuala_Lumpur', now()))::date) end,
       'phone', coalesce(ct.phone, ''), 'email', coalesce(ct.email, ''),
       'finance_email', coalesce(cl.finance_email, ''),
       'client_code', cl.client_code,
       'owner', coalesce(p_deal ->> 'owner', ''), 'source', coalesce(p_deal ->> 'source', ''),
       'industry', coalesce(p_deal ->> 'industry', ''), 'stage', coalesce(p_deal ->> 'stage', ''),
       'enquiry', coalesce(p_deal ->> 'enquiry', ''),
       'terms', v_terms),
     v_lines, coalesce(me.name, who), cl.client_code, nullif(btrim(p_idem), ''))
  returning id into v_id;

  insert into public.client_document_services (document_id, service_id)
    select v_id, s.id from unnest(p_services) s(id)
    on conflict do nothing;

  if p_replaces is not null then
    update public.client_documents set superseded_by = v_id where id = p_replaces;
    insert into public.activity_log (actor, action, subject, detail)
    values (who, 'document.superseded', cl.name, v_old.number || ' replaced by ' || v_no);
  end if;

  select count(*) into v_n from public.client_document_services where document_id = v_id;
  insert into public.activity_log (actor, action, subject, detail)
  values (who, 'document.issued', cl.name, v_no || ' · ' || v_n || ' line' || case when v_n = 1 then '' else 's' end);

  return jsonb_build_object('ok', true, 'id', v_id, 'number', v_no);
exception
  when unique_violation then
    -- Two presses that raced past the idempotency read: the loser reads the
    -- winner's letter back rather than making a second one.
    if coalesce(btrim(p_idem), '') <> '' then
      select * into v_old from public.client_documents
        where client_id = p_client and idem_key = btrim(p_idem) limit 1;
      if v_old.id is not null then
        return jsonb_build_object('ok', true, 'repeat', true, 'id', v_old.id, 'number', v_old.number);
      end if;
    end if;
    -- A typed reference two people sent at once: the loser is told the
    -- reference is spent rather than that "two letters were issued at once",
    -- which names a cause they cannot act on.
    if nullif(btrim(coalesce(p_serial, '')), '') is not null then
      return jsonb_build_object('error', 'serial-taken');
    end if;
    return jsonb_build_object('error', 'clash');
end $$;
revoke all on function public.issue_letter(uuid, uuid[], text, numeric, numeric, numeric, jsonb, uuid, boolean, text) from public, anon;
grant execute on function public.issue_letter(uuid, uuid[], text, numeric, numeric, numeric, jsonb, uuid, boolean, text) to authenticated;

-- END OF LETTER TERMS -------------------------------------------------------

-- ===========================================================================
-- LETTER VALIDITY IN ITS TERMS — the offer's validity is the first point of
-- the letter's own terms, prefilled and editable (2026-10-23)
-- ===========================================================================
-- WHY (the user, 2026-10-23: "dont hard coded inside, you should auto fill
-- in the terms part as first sentence"): the letter printed a validity of
-- 30 days typed into the page, apart from the terms typed on it.
--
-- WHAT IT CHANGES
--   * `issue_letter` keeps `bill_to -> 'terms_own'` (true where the page
--     sends `p_deal -> 'terms_own'`): the Issue Letter of Offer sheet opens
--     its Terms on the validity, worked from `quote_valid_days` (Tax and
--     terms), and the letter prints its terms as typed. A letter without
--     the mark redraws as issued, its validity 30 days from its date.
--     Otherwise as its last definition (LETTER TERMS).
--
-- ORDER: this file, then the pages. Safe to run twice. Rollback: run
-- LETTER TERMS again; letters already issued keep their mark.
-- ===========================================================================

create or replace function public.issue_letter(
  p_client    uuid,
  p_services  uuid[],
  p_idem      text,
  p_subtotal  numeric,
  p_tax       numeric,
  p_total     numeric,
  p_deal      jsonb   default '{}'::jsonb,
  p_replaces  uuid    default null,
  p_renewal   boolean default false,
  /* A reference somebody typed. Blank is the ordinary case and the counter
     below makes the number; where one is typed it is checked against every
     document that stands and the counter is not advanced, so filling a gap
     by hand never costs the next letter its place in the sequence. */
  p_serial    text    default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  who    text := lower(auth.jwt() ->> 'email');
  cl     public.clients%rowtype;
  ct     public.client_contacts%rowtype;
  me     public.team_members%rowtype;
  v_ym   text;
  v_seq  int;
  v_try  int;
  v_no   text;
  v_id   uuid;
  v_lines jsonb;
  v_n    int;
  v_bad  int;
  v_old  public.client_documents%rowtype;
  v_term int;
  v_each numeric;
  v_etax numeric;
  v_once numeric;
  v_otax numeric;
  v_sub  numeric;
  v_tax  numeric;
  v_tot  numeric;
  v_pct  numeric;
  v_qid  uuid;
  v_q    public.quotations%rowtype;
  v_tp   numeric;
  v_tpn  int;
  v_tadj boolean;
  v_qterm int;
  v_msub numeric;
  v_span numeric;
  v_even boolean;
  v_qt   jsonb;
  v_month boolean;
  v_terms jsonb;
begin
  if not public.allowed('clients.documents') then
    return jsonb_build_object('error', 'not-allowed');
  end if;
  if p_client is null or p_services is null or array_length(p_services, 1) is null then
    return jsonb_build_object('error', 'no-lines');
  end if;

  select * into cl from public.clients where id = p_client;
  if cl.id is null then return jsonb_build_object('error', 'no-client'); end if;

  -- The letter's own terms, one point a line, kept with what it was issued
  -- with and printed under TERMS after the term and the validity
  -- (2026-10-23): ten at most, each 1 to 400 characters.
  v_terms := coalesce((select jsonb_agg(btrim(t)) from jsonb_array_elements_text(
               case when jsonb_typeof(p_deal -> 'terms') = 'array' then p_deal -> 'terms' else '[]'::jsonb end) t
             where btrim(t) <> ''), '[]'::jsonb);
  if jsonb_array_length(v_terms) > 10
     or exists (select 1 from jsonb_array_elements_text(v_terms) t where length(t) > 400) then
    return jsonb_build_object('error', 'bad-terms');
  end if;

  -- The Client ID is what the serial is built from, so there is no letter
  -- without one. Staff enter it on the record; nothing invents it. A typed
  -- reference needs no code, because nothing is being built.
  v_no := nullif(btrim(coalesce(p_serial, '')), '');
  if v_no is null and coalesce(btrim(cl.client_code), '') = '' then
    return jsonb_build_object('error', 'no-client-code');
  end if;

  -- The same submission, pressed twice, is one letter. Answered before any
  -- number is reserved, so a double click cannot spend a serial either.
  if coalesce(btrim(p_idem), '') <> '' then
    select * into v_old from public.client_documents
      where client_id = p_client and idem_key = btrim(p_idem) limit 1;
    if v_old.id is not null then
      return jsonb_build_object('ok', true, 'repeat', true, 'id', v_old.id, 'number', v_old.number);
    end if;
  end if;

  -- A typed reference is checked before anything is written: the same shape
  -- the Register accepts, and refused where a document still holds it.
  if v_no is not null then
    if v_no !~ '^[A-Za-z0-9/._-]{3,40}$' then
      return jsonb_build_object('error', 'serial-shape');
    end if;
    if public.serial_taken(v_no) then
      return jsonb_build_object('error', 'serial-taken');
    end if;
  end if;

  -- Every id must be this client's own live line, and in a state this letter
  -- may carry: To quote always, Confirmed only on a deliberate renewal.
  select count(*) into v_bad from unnest(p_services) s(id)
    left join public.client_services cs
      on cs.id = s.id and cs.client_id = p_client and cs.archived_at is null
    where cs.id is null
       or (cs.state = 'confirmed' and not p_renewal)
       or cs.state not in ('quoted', 'confirmed');
  if v_bad > 0 then return jsonb_build_object('error', 'bad-lines'); end if;

  -- A line already on a live letter is not offered again by accident. The way
  -- through is to void that letter, or to name it as the one being replaced.
  select count(*) into v_bad
    from public.client_document_services m
    join public.client_documents d on d.id = m.document_id
   where m.service_id = any(p_services)
     and d.voided_at is null
     and d.superseded_by is null
     and d.verified_at is null
     and (p_replaces is null or d.id <> p_replaces);
  if v_bad > 0 then return jsonb_build_object('error', 'already-quoted'); end if;

  if p_replaces is not null then
    select * into v_old from public.client_documents
      where id = p_replaces and client_id = p_client;
    if v_old.id is null then return jsonb_build_object('error', 'no-replaces'); end if;
    if v_old.verified_at is not null then return jsonb_build_object('error', 'replaces-verified'); end if;
  end if;

  select * into ct from public.client_contacts
    where client_id = p_client and archived_at is null
    order by (id = cl.bill_contact_id) desc, is_primary desc, name limit 1;
  select * into me from public.team_members where lower(email) = who and active limit 1;

  -- A letter is signed by a person. issued_by is this row's name, so a team
  -- row named "Superadmin" printed that word under ADSPACE PLT on a client's
  -- letterhead. Refuse rather than draw a permission as a signatory.
  if not public.issuer_name_ok(me.name) then
    return jsonb_build_object('error', 'issuer-name', 'name', coalesce(me.name, ''));
  end if;

  -- The snapshot is built from the stored rows, never from what the browser
  -- sent: the words on a letter are the words the record held at that moment.
  select jsonb_agg(jsonb_build_object(
           'label', cs.label, 'unit', coalesce(cs.unit, ''), 'note', coalesce(cs.note, ''),
           'detail', coalesce(cs.detail, ''), 'state', cs.state,
           'qty', cs.qty, 'rate', cs.rate,
           'tenure', greatest(1, coalesce(cs.tenure, 1)),
           'start_on', coalesce(cs.start_on, ''),
           -- The line's own answer to whether its term prices it. Written into
           -- the snapshot because the letter is redrawn from it, and a letter
           -- must print the same figure every time it is drawn. A snapshot
           -- taken before this key existed carries none, which money.js reads
           -- as on, so those letters redraw as they were issued.
           'term_adjust', coalesce(cs.term_adjust, false),
           -- And the percentage that tick applies, so a later rate card can
           -- never move a figure this letter printed. Null on a line quoted
           -- before the column existed, which money.js reads as that card.
           'term_pct', cs.term_pct,
           'tax', cl.sst_applies is not false,
           -- The line's own tax code and its rate as issued (2026-10-22);
           -- none is the client's SST, as before.
           'tax_code', cs.tax_code,
           'tax_pct', (select t.rate from public.tax_codes t where t.code = cs.tax_code),
           'service_id', cs.id)
           order by cs.created_at)
    into v_lines
    from public.client_services cs
   where cs.id = any(p_services);
  if v_lines is null then return jsonb_build_object('error', 'no-lines'); end if;
  /* A line's tax code is one the team holds and offers (2026-10-22). */
  if exists (select 1 from public.client_services cs
              where cs.id = any(p_services) and cs.tax_code is not null
                and not exists (select 1 from public.tax_codes t where t.code = cs.tax_code and t.active)) then
    return jsonb_build_object('error', 'bad-tax');
  end if;

  /* The price is the database's (audit S4, 2026-10-10), worked as the
     letter draws it (js/documents.js priceOf, js/money.js rateFor): each
     line's rate with its term on it, rounded to the cent. Where every line
     of more than a month shares one term, those lines are priced by the
     month and times the term, and a line of one month is a one-off item
     with its own SST (2026-10-15: a one-off item beside them no longer
     turns the letter into one whole total); otherwise every line is its
     whole amount. SST at the rate in force today unless the client is
     exempt. The page's figures are kept only where they agree to the sen,
     so a line changed since the sheet opened, or a figure typed in a
     browser, is refused (`stale`) and the sheet reads the lines again. */
  select case when count(distinct greatest(1, coalesce(cs.tenure, 1)))
                     filter (where greatest(1, coalesce(cs.tenure, 1)) > 1) = 1
              then max(greatest(1, coalesce(cs.tenure, 1))) else 0 end
    into v_term
    from public.client_services cs where cs.id = any(p_services);
  /* A letter whose every line came from one quotation is priced as that
     quotation was (audit F, 2026-10-17), exactly as `quote_price` and
     `quote_adjust` total it (2026-10-17, the review's finding 7): a line
     the quotation bills by the month (`quotation_offer` ticks its term) is
     a monthly line whatever months Build quote gave it, its percentage
     taken once on their subtotal; a line with no term is one-off; SST at
     the quotation's rate. The page's figures are held to the same price
     (js/documents.js priceOf). */
  select case when count(*) filter (where cs.quotation_id is null) = 0
                   and count(distinct cs.quotation_id) = 1 then min(cs.quotation_id::text)::uuid end,
         count(distinct coalesce(cs.term_pct, 0)) filter (where coalesce(cs.term_adjust, false)),
         coalesce(bool_and(greatest(1, coalesce(cs.tenure, 1)) = 1) filter (where not coalesce(cs.term_adjust, false)), true),
         coalesce(max(cs.term_pct) filter (where coalesce(cs.term_adjust, false)), 0)
    into v_qid, v_tpn, v_tadj, v_tp
    from public.client_services cs where cs.id = any(p_services);
  /* Only while the quotation still stands (2026-10-17, the review's
     finding 2): unexpired by Malaysia's day and not removed. A renewal, or a
     letter replacing one after the quotation lapsed, is priced on today's
     rates, as any other letter. */
  if v_qid is not null and coalesce(v_tpn, 0) <= 1 and v_tadj and not coalesce(p_renewal, false) then
    select * into v_q from public.quotations q
     where q.id = v_qid and q.removed_at is null
       and q.valid_until >= (timezone('Asia/Kuala_Lumpur', now()))::date;
  end if;
  if v_q.id is not null then
    /* As quote_adjust totals it: the monthly lines' subtotal of quantity ×
       rate, the percentage once on it; where every one runs the quotation's
       term, a month's excl. SST, its SST rounded once, times the term; where
       Build quote gave a line months of its own, the whole span (each line's
       amount × its months) with the percentage and SST taken once on it.
       One-off lines and their SST apart. */
    v_qterm := greatest(1, coalesce((v_q.totals->>'term')::int, 1));
    v_pct := case when cl.sst_applies is false then 0
                  else coalesce((v_q.totals->>'sst_pct')::numeric, 0) end;
    /* The lines as the quotation reads them (a line with its term ticked is
       monthly, on its own months), totalled by the one calculation every
       quotation shares (2026-10-18). */
    v_qt := public.quote_totals(
      (select coalesce(jsonb_agg(jsonb_build_object(
                'basis', case when coalesce(cs.term_adjust, false) then 'month' else 'once' end,
                'qty', coalesce(cs.qty, 0), 'rate', coalesce(cs.rate, 0),
                'months', greatest(1, coalesce(cs.tenure, 1)),
                'sst', (select t.rate from public.tax_codes t where t.code = cs.tax_code))), '[]'::jsonb)
         from public.client_services cs where cs.id = any(p_services)),
      v_qterm, v_tp, v_pct);
    v_month := jsonb_typeof(v_qt->'month') = 'object';
    v_once := coalesce((v_qt->'once'->>'subtotal')::numeric, 0);
    v_otax := coalesce((v_qt->'once'->>'sst')::numeric, 0);
    if not v_month then
      v_sub := round(v_once, 2);
      v_tax := v_otax;
    elsif (v_qt->>'even')::boolean then
      v_each := (v_qt->'month'->>'excl')::numeric;
      v_etax := (v_qt->'month'->>'sst')::numeric;
      v_sub := round(v_each * v_qterm + v_once, 2);
      v_tax := v_etax * v_qterm + v_otax;
    else
      v_sub := (v_qt->>'span_excl')::numeric + round(v_once, 2);
      v_tax := (v_qt->>'span_incl')::numeric + round(v_once, 2) + v_otax - v_sub;
    end if;
    v_tot := v_sub + v_tax;
    /* The letter keeps what it was priced on, so a redraw prints the same:
       the quotation, its SST and its term (a snapshot with no `quote_term`
       was priced before this, and redraws as it was). */
    select jsonb_agg(l.e || jsonb_build_object('quotation_id', v_qid, 'quote_sst', v_pct, 'quote_term', v_qterm) order by l.n)
      into v_lines from jsonb_array_elements(v_lines) with ordinality l(e, n);
  else
    v_pct := case when cl.sst_applies is false then 0
                  else coalesce(public.app_setting('sst_pct', (timezone('Asia/Kuala_Lumpur', now()))::date), 0) end;
    /* Each line at its own SST rate (2026-10-22): its tax code's, else the
       client's. The SST is worked a rate at a time, rounded once each, so
       a letter on one rate prices as it always did. */
    with x as (
      select greatest(1, coalesce(cs.tenure, 1)) as n,
             coalesce(cs.qty, 0) *
             round(coalesce(cs.rate, 0) *
               case when cs.term_adjust is false then 1
                    when cs.term_pct is not null then 1 + cs.term_pct / 100
                    else case greatest(1, coalesce(cs.tenure, 1))
                           when 3 then 1 / 0.9 when 12 then 0.95 when 24 then 0.9 else 1 end
               end, 2) as v,
             coalesce((select t.rate from public.tax_codes t where t.code = cs.tax_code), v_pct) as r
        from public.client_services cs where cs.id = any(p_services)
    ), y as (
      select r,
             coalesce(sum(v) filter (where v_term > 0 and n = v_term), 0) as e,
             coalesce(sum(v * n) filter (where v_term = 0 or n <> v_term), 0) as o
        from x group by r
    )
    select coalesce(sum(e), 0), coalesce(sum(o), 0),
           coalesce(sum(round(e * r) / 100), 0), coalesce(sum(round(o * r) / 100), 0)
      into v_each, v_once, v_etax, v_otax
      from y;
    v_sub := round(v_each * greatest(v_term, 1), 2) + round(v_once, 2);
    v_tax := round(v_etax * greatest(v_term, 1), 2) + v_otax;
    v_tot := round(round(v_each + v_etax, 2) * greatest(v_term, 1), 2) + round(v_once + v_otax, 2);
  end if;
  if abs(coalesce(p_subtotal, -1) - v_sub) > 0.01 or abs(coalesce(p_tax, -1) - v_tax) > 0.01
     or abs(coalesce(p_total, -1) - v_tot) > 0.01 then
    return jsonb_build_object('error', 'stale', 'subtotal', v_sub, 'tax', v_tax, 'total', v_tot);
  end if;

  -- A typed reference spends no sequence number: the counter is the office's
  -- record of how many letters it has issued this month, and a person filling
  -- a gap by hand has not issued one more.
  if v_no is null then
    -- The month is Malaysian, because the office that numbers the letter is.
    v_ym := to_char(timezone('Asia/Kuala_Lumpur', now()), 'YYMM');

    -- The counter still advances on every automatic issue, and the upsert's
    -- row lock is what makes the scan below safe: a second issuer blocks here
    -- until the first has committed its letter, so the two never read the same
    -- gap as free. What the counter gives is a bound to scan within, not the
    -- number itself.
    insert into public.client_document_seq (client_id, ym, next_val)
         values (p_client, v_ym, 2)
    on conflict (client_id, ym)
      do update set next_val = public.client_document_seq.next_val + 1
      returning next_val - 1 into v_seq;

    -- The lowest free slot, not the counter's own value. A letter removed
    -- releases its reference (serial_taken stopped counting deletions on
    -- 2026-09-20), and without this the automatic path still counted upward
    -- past the gap: a client whose first two letters were issued in testing
    -- and removed started at 03 for ever. The counter is at least the number
    -- of letters issued this month, so a free slot exists at or below it
    -- unless somebody has typed references over the same range by hand; the
    -- cap covers that and refuses rather than looping.
    --
    -- Two digits is the floor, not the ceiling: the hundredth letter of a month
    -- widens to three rather than wrapping. Not lpad(): Postgres pads AND
    -- truncates to the width it is given, so lpad('100', 2, '0') is '10' and the
    -- hundredth letter would collide with the tenth.
    v_try := 1;
    loop
      v_no := 'AQL/' || cl.client_code || '/' || v_ym ||
              case when v_try < 100 then lpad(v_try::text, 2, '0') else v_try::text end;
      exit when not public.serial_taken(v_no);
      v_try := v_try + 1;
      if v_try > greatest(v_seq, 1) + 200 then
        return jsonb_build_object('error', 'no-serial');
      end if;
    end loop;
  end if;

  insert into public.client_documents
    (client_id, kind, number, issued_at, market, subtotal, tax, total,
     bill_to, lines, issued_by, client_code, idem_key)
  values
    (p_client, 'offer', v_no, (timezone('Asia/Kuala_Lumpur', now()))::date,
     public.client_bill_market(cl.market, cl.bill_sgd),
     round(coalesce(p_subtotal, 0), 2), round(coalesce(p_tax, 0), 2), round(coalesce(p_total, 0), 2),
     jsonb_build_object(
       'name', coalesce(cl.name, ''), 'legal_name', coalesce(cl.legal_name, ''),
       'address', coalesce(cl.billing_address, ''), 'regno', coalesce(cl.company_no, ''),
       'regno_old', coalesce(cl.company_no_old, ''), 'tin', coalesce(cl.tin, ''),
       'sst_no', coalesce(cl.sst_no, ''), 'sst_applies', cl.sst_applies is not false,
       'contact', coalesce(ct.name, ''), 'contact_role', coalesce(ct.role, ''),
       'contact_salutation', coalesce(ct.salutation, ''),
       -- A Singapore client billed in RM: its market and the rate in force,
       -- so the letter reads its figure in S$ beside it, as issued.
       'market', coalesce(cl.market, 'MY'),
       'fx_sgd', case when cl.market = 'SG' and not cl.bill_sgd then public.app_setting('fx_sgd', (timezone('Asia/Kuala_Lumpur', now()))::date) end,
       'phone', coalesce(ct.phone, ''), 'email', coalesce(ct.email, ''),
       'finance_email', coalesce(cl.finance_email, ''),
       'client_code', cl.client_code,
       'owner', coalesce(p_deal ->> 'owner', ''), 'source', coalesce(p_deal ->> 'source', ''),
       'industry', coalesce(p_deal ->> 'industry', ''), 'stage', coalesce(p_deal ->> 'stage', ''),
       'enquiry', coalesce(p_deal ->> 'enquiry', ''),
       'terms', v_terms,
       -- The validity is one of the points typed (2026-10-23): a letter
       -- sent with it in its terms prints none of its own.
       'terms_own', coalesce(p_deal ->> 'terms_own', '') = 'true'),
     v_lines, coalesce(me.name, who), cl.client_code, nullif(btrim(p_idem), ''))
  returning id into v_id;

  insert into public.client_document_services (document_id, service_id)
    select v_id, s.id from unnest(p_services) s(id)
    on conflict do nothing;

  if p_replaces is not null then
    update public.client_documents set superseded_by = v_id where id = p_replaces;
    insert into public.activity_log (actor, action, subject, detail)
    values (who, 'document.superseded', cl.name, v_old.number || ' replaced by ' || v_no);
  end if;

  select count(*) into v_n from public.client_document_services where document_id = v_id;
  insert into public.activity_log (actor, action, subject, detail)
  values (who, 'document.issued', cl.name, v_no || ' · ' || v_n || ' line' || case when v_n = 1 then '' else 's' end);

  return jsonb_build_object('ok', true, 'id', v_id, 'number', v_no);
exception
  when unique_violation then
    -- Two presses that raced past the idempotency read: the loser reads the
    -- winner's letter back rather than making a second one.
    if coalesce(btrim(p_idem), '') <> '' then
      select * into v_old from public.client_documents
        where client_id = p_client and idem_key = btrim(p_idem) limit 1;
      if v_old.id is not null then
        return jsonb_build_object('ok', true, 'repeat', true, 'id', v_old.id, 'number', v_old.number);
      end if;
    end if;
    -- A typed reference two people sent at once: the loser is told the
    -- reference is spent rather than that "two letters were issued at once",
    -- which names a cause they cannot act on.
    if nullif(btrim(coalesce(p_serial, '')), '') is not null then
      return jsonb_build_object('error', 'serial-taken');
    end if;
    return jsonb_build_object('error', 'clash');
end $$;
revoke all on function public.issue_letter(uuid, uuid[], text, numeric, numeric, numeric, jsonb, uuid, boolean, text) from public, anon;
grant execute on function public.issue_letter(uuid, uuid[], text, numeric, numeric, numeric, jsonb, uuid, boolean, text) to authenticated;

-- END OF LETTER VALIDITY IN ITS TERMS -------------------------------------

-- ===========================================================================
-- A WITHDRAWN TALK CAN BE DELETED — the colleague who asked for a talk and
-- withdrew it deletes it from their Talks (2026-10-24)
-- ===========================================================================
-- WHY (the user, 2026-10-24: "Health > Talks > Withdrawn (but not possible
-- to delete?"): whatever a person adds, they can delete where nothing names
-- it (2026-10-22). A withdrawn talk is the asker's alone: the colleague
-- asked and Team: Health no longer read it.
--
-- WHAT IT ADDS
--   * `health_talk_delete(p_id)`: behind the fresh proof
--     (`perf_mine_gate`); the asker alone (`not-found` for anyone else),
--     a withdrawn talk alone (`bad-status`, so an open or done talk, which
--     the colleague asked still reads, stays); answers `health_mine()`.
--     Nothing is filed: a talk never reaches the Activity record.
--
-- ORDER: this file in the SQL Editor (it holds a delete the connector holds
-- back), then the pages. A page served before it reads "This needs a
-- database update" at Delete. Safe to run twice. Rollback:
--   drop function if exists public.health_talk_delete(uuid);
-- ===========================================================================

create or replace function public.health_talk_delete(p_id uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare m public.team_members; g jsonb; t public.health_talks;
begin
  g := public.perf_mine_gate();
  if g is not null then return g; end if;
  m := public.ops_me();
  select * into t from public.health_talks where id = p_id for update;
  if t.id is null or t.team_member_id is distinct from m.id then
    return jsonb_build_object('error', 'not-found');
  end if;
  if t.status <> 'withdrawn' then return jsonb_build_object('error', 'bad-status'); end if;
  delete from public.health_talks where id = t.id;
  return public.health_mine();
end $$;

revoke all on function public.health_talk_delete(uuid) from public, anon, authenticated;
grant execute on function public.health_talk_delete(uuid) to authenticated;

-- END OF A WITHDRAWN TALK CAN BE DELETED --------------------------------------

-- ===========================================================================
-- OVERSEAS ACCESS — the console answers a colleague outside Malaysia and
-- Singapore only once an admin has approved it, for 14 days at most
-- (2026-10-24)
-- ===========================================================================
-- WHY (the user, 2026-10-24: "due to safety purposes … once detected located
-- overseas then prompt a window to submit request access and the request
-- would go to admin for approval … admin excluded"; "Allowed in Malaysia
-- Singapore"; "14 days per cycle"; "Admins only"): a sign-in used from
-- abroad, a colleague's or a stolen one, should not read the team's data
-- without somebody deciding it may.
--
-- WHAT IT ADDS
--   * `request_country()`: the country Cloudflare saw the request come from
--     (`cf-ipcountry`, which Cloudflare sets and a caller cannot: checked on
--     the live API, 2026-10-24), empty where there is no request (pg_cron,
--     the SQL Editor). Internal.
--   * `team_place_ok(p_admin, p_member)`: true for an admin, a request from
--     Malaysia or Singapore or with no country, or a colleague holding an
--     approved request whose day (MYT) has not passed. Internal.
--   * `is_team()`, `allowed(p_section, p_level)`, `ops_granted`, `ops_me()`
--     and `me()` ask it, so every policy and every function that asks them
--     refuses a colleague abroad without approval. `allowed('admin')` is an
--     admin's alone and needs no change. Client pages never ask them.
--   * `team_abroad` (RLS on, no policy, no grant): a request a row, waiting,
--     approved (until a day), declined or ended.
--   * `abroad_state()`: the signed-in colleague's own country, whether they
--     are held, their latest request and the days an approval may run.
--   * `abroad_request(p_reason, p_until)`: a colleague who is not an admin
--     asks (`bad-reason` 3 to 300, `bad-until` today to today plus
--     `abroad_days`); a waiting request is replaced; every active admin but a
--     system account is told (kind `abroad.request`).
--   * `abroad_list()`, `abroad_decide(p_id, p_approve, p_until, p_note)`,
--     `abroad_end(p_id)`: an admin's; each decision filed `team.changed`
--     under Overseas access, and the colleague told (kind `abroad.decided`).
--   * `abroad_days` (14), a Business setting (Settings, Portal: Overseas
--     approval, 1 to 30), which `app_settings_set` takes from OVERSEAS
--     APPROVAL DAYS, the SQL Editor's part.
--
-- ORDER: this file (the connector), then
-- 2026-10-24-overseas-access-days.sql (the SQL Editor: it holds a delete),
-- then the pages. A page served before it asks nothing;
-- a colleague abroad then reads Access denied until the pages are live.
-- Safe to run twice. Rollback: the five functions as ACCESS ENDS ON THE
-- MINUTE and TEAM ACCESS left them (drop the new ones in the SQL Editor).
-- ===========================================================================

create table if not exists public.team_abroad (
  id             uuid primary key default gen_random_uuid(),
  team_member_id uuid not null references public.team_members(id) on delete cascade,
  country        text not null default '',
  reason         text not null,
  until          date not null,
  status         text not null default 'waiting',
  note           text,
  asked_at       timestamptz not null default now(),
  decided_by     uuid references public.team_members(id) on delete set null,
  decided_at     timestamptz,
  constraint team_abroad_status_check check (status in ('waiting', 'approved', 'declined', 'ended'))
);
create index if not exists team_abroad_member_idx on public.team_abroad (team_member_id, status, until);
alter table public.team_abroad enable row level security;
revoke all on public.team_abroad from public, anon, authenticated;

insert into public.app_settings (key, from_date, value)
select 'abroad_days', date '2023-08-14', 14
 where not exists (select 1 from public.app_settings s where s.key = 'abroad_days');

create or replace function public.request_country()
returns text
language sql stable set search_path = public as $$
  select upper(left(coalesce(nullif(btrim(h ->> 'cf-ipcountry'), ''), ''), 2))
  from (select coalesce(nullif(current_setting('request.headers', true), ''), '{}')::json as h) r
$$;
revoke all on function public.request_country() from public, anon, authenticated;

create or replace function public.team_home_country(p_country text)
returns boolean
language sql immutable set search_path = public as $$
  select coalesce(p_country, '') in ('', 'MY', 'SG')
$$;
revoke all on function public.team_home_country(text) from public, anon, authenticated;

create or replace function public.team_place_ok(p_admin boolean, p_member uuid)
returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce(p_admin, false)
      or public.team_home_country(public.request_country())
      or exists (select 1 from public.team_abroad a
                  where a.team_member_id = p_member and a.status = 'approved'
                    and a.until >= (now() at time zone 'Asia/Kuala_Lumpur')::date)
$$;
revoke all on function public.team_place_ok(boolean, uuid) from public, anon, authenticated;

create or replace function public.is_team()
returns boolean
language sql security definer stable set search_path = public as $$
  select exists (
    select 1 from public.team_members t
    where t.active and lower(t.email) = lower(auth.jwt() ->> 'email')
      and (t.access_until is null or t.is_admin or t.role = 'admin'
           or public.team_access_ends(t.access_until, t.access_until_time) > now())
      and public.team_place_ok(t.is_admin or t.role = 'admin', t.id))
$$;
grant execute on function public.is_team() to authenticated;

create or replace function public.allowed(p_section text, p_level text)
returns boolean
language plpgsql security definer stable set search_path = public as $$
declare
  t public.team_members;
  k text := lower(coalesce(p_section, ''));
  lv text;
begin
  select * into t from public.team_members x
    where lower(x.email) = lower(auth.jwt() ->> 'email') and x.active
      and (x.access_until is null or x.is_admin or x.role = 'admin'
           or public.team_access_ends(x.access_until, x.access_until_time) > now())
    limit 1;
  if t.id is null then return false; end if;
  if t.is_admin or t.role = 'admin' then return true; end if;
  if not public.team_place_ok(false, t.id) then return false; end if;
  lv := t.access ->> k;
  if lv is null and position('.' in k) > 0 then
    lv := t.access ->> split_part(k, '.', 1);
  end if;
  return public.level_rank(lv) >= public.level_rank(p_level);
end $$;
grant execute on function public.allowed(text, text) to authenticated;

create or replace function public.ops_granted(p_key text, p_level text)
returns boolean
language plpgsql security definer stable set search_path = public as $$
declare t public.team_members;
begin
  select * into t from public.team_members
   where active and lower(email) = lower(auth.jwt() ->> 'email') limit 1;
  if t.id is null then return false; end if;
  if t.is_admin or t.role = 'admin' then return true; end if;
  if not public.team_place_ok(false, t.id) then return false; end if;
  return public.level_rank(t.access ->> p_key) >= public.level_rank(p_level);
end $$;
grant execute on function public.ops_granted(text, text) to authenticated;

create or replace function public.ops_me()
returns public.team_members
language sql security definer stable set search_path = public as $$
  select * from public.team_members t
   where t.active and lower(t.email) = lower(auth.jwt() ->> 'email')
     and (t.access_until is null or t.is_admin or t.role = 'admin'
          or public.team_access_ends(t.access_until, t.access_until_time) > now())
     and public.team_place_ok(t.is_admin or t.role = 'admin', t.id)
   limit 1
$$;
grant execute on function public.ops_me() to authenticated;

create or replace function public.me()
returns public.team_members
language sql security definer stable set search_path = public as $$
  select * from public.team_members t
  where lower(t.email) = lower(auth.jwt() ->> 'email') and t.active
    and (t.access_until is null or t.is_admin or t.role = 'admin'
         or public.team_access_ends(t.access_until, t.access_until_time) > now())
    and public.team_place_ok(t.is_admin or t.role = 'admin', t.id)
  limit 1
$$;
grant execute on function public.me() to authenticated;

/* The colleague signed in, whatever the country: who the cover is for. */
create or replace function public.abroad_who()
returns public.team_members
language sql security definer stable set search_path = public as $$
  select * from public.team_members t
  where lower(t.email) = lower(auth.jwt() ->> 'email') and t.active
    and (t.access_until is null or t.is_admin or t.role = 'admin'
         or public.team_access_ends(t.access_until, t.access_until_time) > now())
  limit 1
$$;
revoke all on function public.abroad_who() from public, anon, authenticated;

create or replace function public.abroad_state()
returns jsonb
language plpgsql security definer stable set search_path = public as $$
declare
  t public.team_members := public.abroad_who();
  v_today date := (now() at time zone 'Asia/Kuala_Lumpur')::date;
  v_admin boolean;
  a public.team_abroad;
begin
  if t.id is null then return jsonb_build_object('team', false); end if;
  v_admin := t.is_admin or t.role = 'admin';
  select * into a from public.team_abroad x where x.team_member_id = t.id order by x.asked_at desc limit 1;
  return jsonb_build_object(
    'team', true, 'admin', v_admin, 'country', public.request_country(),
    'held', not public.team_place_ok(v_admin, t.id),
    'today', v_today,
    'days', coalesce(public.app_setting('abroad_days', v_today), 14)::int,
    'request', case when a.id is null then null else jsonb_build_object(
      'id', a.id, 'status', case when a.status = 'approved' and a.until < v_today then 'expired' else a.status end,
      'until', a.until, 'country', a.country, 'reason', a.reason, 'note', a.note,
      'asked_at', a.asked_at, 'decided_at', a.decided_at) end);
end $$;
revoke all on function public.abroad_state() from public, anon;
grant execute on function public.abroad_state() to authenticated;

create or replace function public.abroad_request(p_reason text, p_until date)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  t public.team_members := public.abroad_who();
  v_today date := (now() at time zone 'Asia/Kuala_Lumpur')::date;
  v_days int := coalesce(public.app_setting('abroad_days', (now() at time zone 'Asia/Kuala_Lumpur')::date), 14)::int;
  v_reason text := btrim(regexp_replace(coalesce(p_reason, ''), '\s+', ' ', 'g'));
  v_country text := public.request_country();
  v_id uuid;
begin
  if t.id is null then return jsonb_build_object('error', 'denied'); end if;
  if t.is_admin or t.role = 'admin' then return jsonb_build_object('error', 'admin'); end if;
  if char_length(v_reason) < 3 or char_length(v_reason) > 300 then return jsonb_build_object('error', 'bad-reason'); end if;
  if p_until is null or p_until < v_today or p_until > v_today + v_days then
    return jsonb_build_object('error', 'bad-until', 'max', v_today + v_days);
  end if;
  select x.id into v_id from public.team_abroad x
   where x.team_member_id = t.id and x.status = 'waiting' order by x.asked_at desc limit 1 for update;
  if v_id is null then
    insert into public.team_abroad (team_member_id, country, reason, until)
    values (t.id, v_country, v_reason, p_until) returning id into v_id;
  else
    update public.team_abroad set country = v_country, reason = v_reason, until = p_until, asked_at = now()
     where id = v_id;
  end if;
  insert into public.ops_notifications (team_member_id, kind, title, body, dedupe_key)
  select m.id, 'abroad.request', 'Overseas access requested · ' || t.name,
         case when v_country <> '' then 'From ' || v_country || ' · ' else '' end ||
         'until ' || public.register_day(p_until) || ' · ' || v_reason,
         'abroad:' || v_id || ':' || m.id || ':' || to_char(now() at time zone 'Asia/Kuala_Lumpur', 'YYYYMMDDHH24MI')
    from public.team_members m
   where m.active and (m.is_admin or m.role = 'admin') and not coalesce(m.system, false)
  on conflict (dedupe_key) do nothing;
  return public.abroad_state();
end $$;
revoke all on function public.abroad_request(text, date) from public, anon;
grant execute on function public.abroad_request(text, date) to authenticated;

create or replace function public.abroad_list()
returns jsonb
language plpgsql security definer stable set search_path = public as $$
declare v_today date := (now() at time zone 'Asia/Kuala_Lumpur')::date;
begin
  if not public.allowed('admin') then return jsonb_build_object('error', 'denied'); end if;
  return jsonb_build_object(
    'today', v_today,
    'days', coalesce(public.app_setting('abroad_days', v_today), 14)::int,
    'rows', coalesce((select jsonb_agg(jsonb_build_object(
        'id', a.id, 'member', a.team_member_id, 'name', m.name, 'code', m.staff_code,
        'country', a.country, 'reason', a.reason, 'until', a.until, 'note', a.note,
        'status', case when a.status = 'approved' and a.until < v_today then 'expired' else a.status end,
        'asked_at', a.asked_at, 'decided_at', a.decided_at,
        'decided_by', (select d.name from public.team_members d where d.id = a.decided_by))
        order by (a.status = 'waiting') desc, (a.status = 'approved' and a.until >= v_today) desc, a.asked_at desc)
      from public.team_abroad a join public.team_members m on m.id = a.team_member_id
     where a.status = 'waiting' or (a.status = 'approved' and a.until >= v_today)
        or a.asked_at > now() - interval '90 days'), '[]'::jsonb));
end $$;
revoke all on function public.abroad_list() from public, anon;
grant execute on function public.abroad_list() to authenticated;

create or replace function public.abroad_decide(p_id uuid, p_approve boolean, p_until date default null, p_note text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me public.team_members := public.ops_me();
  v_today date := (now() at time zone 'Asia/Kuala_Lumpur')::date;
  v_days int := coalesce(public.app_setting('abroad_days', (now() at time zone 'Asia/Kuala_Lumpur')::date), 14)::int;
  v_note text := nullif(btrim(regexp_replace(coalesce(p_note, ''), '\s+', ' ', 'g')), '');
  a public.team_abroad; v_name text;
begin
  if not public.allowed('admin') then return jsonb_build_object('error', 'denied'); end if;
  select * into a from public.team_abroad x where x.id = p_id for update;
  if a.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if a.status <> 'waiting' then return jsonb_build_object('error', 'not-waiting'); end if;
  if char_length(coalesce(v_note, '')) > 300 then return jsonb_build_object('error', 'too-long'); end if;
  if coalesce(p_approve, false) and (p_until is null or p_until < v_today or p_until > v_today + v_days) then
    return jsonb_build_object('error', 'bad-until', 'max', v_today + v_days);
  end if;
  update public.team_abroad
     set status = case when p_approve then 'approved' else 'declined' end,
         until = case when p_approve then p_until else until end,
         note = v_note, decided_by = v_me.id, decided_at = now()
   where id = a.id;
  select m.name into v_name from public.team_members m where m.id = a.team_member_id;
  insert into public.activity_log (actor, action, subject, detail)
  values (coalesce(v_me.name, 'admin'), 'team.changed', 'Overseas access',
    coalesce(v_name, 'A colleague') || ': ' ||
    case when p_approve then 'approved until ' || public.register_day(p_until) else 'declined' end ||
    case when a.country <> '' then ' · from ' || a.country else '' end ||
    case when v_note is not null then ' · ' || v_note else '' end);
  insert into public.ops_notifications (team_member_id, kind, title, body, dedupe_key)
  values (a.team_member_id, 'abroad.decided',
    case when p_approve then 'Overseas access approved until ' || public.register_day(p_until)
         else 'Overseas access declined' end,
    v_note, 'abroad.decided:' || a.id)
  on conflict (dedupe_key) do nothing;
  return public.abroad_list();
end $$;
revoke all on function public.abroad_decide(uuid, boolean, date, text) from public, anon;
grant execute on function public.abroad_decide(uuid, boolean, date, text) to authenticated;

create or replace function public.abroad_end(p_id uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me public.team_members := public.ops_me();
  v_today date := (now() at time zone 'Asia/Kuala_Lumpur')::date;
  a public.team_abroad; v_name text;
begin
  if not public.allowed('admin') then return jsonb_build_object('error', 'denied'); end if;
  select * into a from public.team_abroad x where x.id = p_id for update;
  if a.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if a.status <> 'approved' or a.until < v_today then return jsonb_build_object('error', 'not-approved'); end if;
  update public.team_abroad set status = 'ended', decided_by = v_me.id, decided_at = now() where id = a.id;
  select m.name into v_name from public.team_members m where m.id = a.team_member_id;
  insert into public.activity_log (actor, action, subject, detail)
  values (coalesce(v_me.name, 'admin'), 'team.changed', 'Overseas access',
    coalesce(v_name, 'A colleague') || ': ended · was approved until ' || public.register_day(a.until));
  insert into public.ops_notifications (team_member_id, kind, title, body, dedupe_key)
  values (a.team_member_id, 'abroad.decided', 'Overseas access ended', null, 'abroad.ended:' || a.id)
  on conflict (dedupe_key) do nothing;
  return public.abroad_list();
end $$;
revoke all on function public.abroad_end(uuid) from public, anon;
grant execute on function public.abroad_end(uuid) to authenticated;

-- END OF OVERSEAS ACCESS ----------------------------------------------------

-- ===========================================================================
-- OVERSEAS APPROVAL DAYS — the days an overseas approval may run are a
-- Business setting like any other (2026-10-24)
-- ===========================================================================
-- WHY (the user, 2026-10-24: "14 days per cycle"): the figure is the team's
-- to change, from a day on, through the one sheet every setting uses.
--
-- WHAT IT CHANGES
--   * `app_settings_set` takes `abroad_days` (1 to 30 whole days), filed
--     as Overseas approval, from and to. Nothing else moves.
--
-- ORDER: after OVERSEAS ACCESS, in the SQL Editor (the function holds a
-- delete, which the connector holds back). Safe to run twice. Rollback:
-- run app_settings_set from A PLANNED SETTING WITHDRAWN again.
-- ===========================================================================

create or replace function public.app_settings_set(p_from date, p_values jsonb)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me public.team_members; v_k text; v_v numeric; v_was numeric; v_name text; v_unit text; v_pre text;
  v_today date := (now() at time zone 'Asia/Kuala_Lumpur')::date;
  v_keys constant text[] := array['lead_followup_hours', 'proposal_followup_days', 'sst_pct',
    'term_1_3', 'term_4_5', 'term_6_11', 'term_12_23', 'term_18_23', 'term_24', 'report_due_days', 'revision_due_days',
    'ai_price_in', 'ai_price_out', 'meta_checks', 'approval_reminder_days', 'ai_price_search',
    'reach_allowance_pct', 'priority_urgent_hours', 'priority_high_hours', 'priority_medium_hours',
    'task_remind_hours', 'task_start_days', 'quote_valid_days', 'details_form_days', 'wa_repeat_hours',
    'bench_cpr_low', 'bench_cpr_mid', 'bench_cpr_high', 'bench_cpr_top', 'bench_msg_min', 'bench_msg_target', 'bench_msg_max',
    'bench_form_min', 'bench_form_target', 'bench_form_max', 'bench_cpm_min', 'bench_cpm_max', 'bench_cpl_rise',
    'bench_reels_share', 'bench_ad_spend_pct', 'bench_adset_daily', 'vic_lead_followup_hours', 'vic_proposal_followup_days', 'fx_sgd',
    'health_keep_months', 'health_leaver_months', 'abroad_days'];
  v_moved text[] := '{}';
  v_drop boolean; v_fw text; v_fv text;
begin
  if not public.ops_granted('team.settings', 'work') then return jsonb_build_object('error', 'denied'); end if;
  v_me := public.ops_me();
  if p_from is null or p_from < v_today then return jsonb_build_object('error', 'past', 'today', v_today); end if;
  if jsonb_typeof(p_values) is distinct from 'object' then return jsonb_build_object('error', 'bad-value'); end if;
  for v_k in select jsonb_object_keys(p_values) loop
    if not (v_k = any(v_keys)) or jsonb_typeof(p_values -> v_k) <> 'number' then
      return jsonb_build_object('error', 'bad-value', 'key', v_k);
    end if;
    v_v := (p_values ->> v_k)::numeric;
    if round(v_v, case when v_k = 'fx_sgd' then 4 else 2 end) <> v_v
       or (v_k = 'fx_sgd' and (v_v < 0.5 or v_v > 10))
       or (v_k in ('lead_followup_hours', 'vic_lead_followup_hours') and (v_v < 1 or v_v > 720 or v_v <> trunc(v_v)))
       or (v_k in ('proposal_followup_days', 'vic_proposal_followup_days') and (v_v < 1 or v_v > 365 or v_v <> trunc(v_v)))
       or (v_k = 'report_due_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'revision_due_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'approval_reminder_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'sst_pct' and (v_v < 0 or v_v > 100))
       or (v_k like 'term_%' and (v_v < -100 or v_v > 100))
       or (v_k like 'ai_price_%' and (v_v < 0 or v_v > 1000))
       or (v_k = 'meta_checks' and v_v not in (0, 1))
       or (v_k = 'reach_allowance_pct' and (v_v < 0 or v_v > 5))
       or (v_k like 'priority_%_hours' and (v_v < 1 or v_v > 720 or v_v <> trunc(v_v)))
       or (v_k = 'task_remind_hours' and (v_v < 0 or v_v > 24 or v_v <> trunc(v_v)))
       or (v_k = 'task_start_days' and (v_v < 0 or v_v > 30 or v_v <> trunc(v_v)))
       or (v_k in ('quote_valid_days', 'details_form_days') and (v_v < 1 or v_v > 90 or v_v <> trunc(v_v)))
       or (v_k = 'wa_repeat_hours' and (v_v < 0 or v_v > 168 or v_v <> trunc(v_v)))
       or (v_k = 'health_keep_months' and (v_v < 6 or v_v > 120 or v_v <> trunc(v_v)))
       or (v_k = 'health_leaver_months' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'abroad_days' and (v_v < 1 or v_v > 30 or v_v <> trunc(v_v)))
       or (v_k in ('bench_reels_share') and (v_v < 0 or v_v > 100))
       or (v_k = 'bench_ad_spend_pct' and (v_v < 1 or v_v > 100))
       or (v_k = 'bench_cpl_rise' and (v_v < -100 or v_v > 100))
       or (v_k like 'bench_%' and v_k not in ('bench_reels_share', 'bench_ad_spend_pct', 'bench_cpl_rise') and (v_v < 0 or v_v > 10000)) then
      return jsonb_build_object('error', 'bad-value', 'key', v_k);
    end if;
  end loop;
  for v_k in select jsonb_object_keys(p_values) loop
    v_v := (p_values ->> v_k)::numeric;
    v_was := public.app_setting(v_k, p_from);
    if v_was is distinct from v_v then
      /* A planned change saved back to the value in force the day before is
         withdrawn: its row goes, rather than a second row restating it. */
      v_drop := p_from > v_today
        and exists (select 1 from public.app_settings s where s.key = v_k and s.from_date = p_from)
        and exists (select 1 from public.app_settings s where s.key = v_k and s.from_date < p_from)
        and public.app_setting(v_k, p_from - 1) = v_v;
      if v_drop then
        delete from public.app_settings s where s.key = v_k and s.from_date = p_from;
      else
        insert into public.app_settings (key, from_date, value, set_by, set_at)
        values (v_k, p_from, v_v, v_me.id, now())
        on conflict (key, from_date) do update set value = excluded.value, set_by = excluded.set_by, set_at = now();
      end if;
      v_name := case v_k when 'lead_followup_hours' then 'A lead waits' when 'proposal_followup_days' then 'A proposal waits'
        when 'vic_lead_followup_hours' then 'A VIC lead waits' when 'vic_proposal_followup_days' then 'A VIC proposal waits'
        when 'sst_pct' then 'SST' when 'term_1_3' then '1 to 3 months' when 'term_4_5' then '4 and 5 months'
        when 'term_6_11' then '6 to 11 months' when 'term_12_23' then '12 to 17 months' when 'term_18_23' then '18 to 23 months' when 'term_24' then '24 months and more'
        when 'revision_due_days' then 'Revision due' when 'ai_price_in' then 'AI input, a million tokens'
        when 'ai_price_out' then 'AI output, a million tokens' when 'ai_price_search' then 'AI web searches, a thousand' when 'meta_checks' then 'Meta checks'
        when 'approval_reminder_days' then 'Approval reminder' when 'reach_allowance_pct' then 'Reach allowance'
        when 'priority_urgent_hours' then 'Urgent deadline' when 'priority_high_hours' then 'High deadline'
        when 'priority_medium_hours' then 'Medium deadline' when 'task_remind_hours' then 'Task reminders'
        when 'task_start_days' then 'Not started reminder' when 'quote_valid_days' then 'Quotation validity' when 'details_form_days' then 'Details form open'
        when 'wa_repeat_hours' then 'WhatsApp sent again'
        when 'bench_cpr_low' then 'Property cost per result, tier 1 from' when 'bench_cpr_mid' then 'Property cost per result, tier 2 from'
        when 'bench_cpr_high' then 'Property cost per result, tier 3 from' when 'bench_cpr_top' then 'Property cost per result, tier 3 up to'
        when 'bench_msg_min' then 'Messaging cost per result, low' when 'bench_msg_target' then 'Messaging cost per result, target'
        when 'bench_msg_max' then 'Messaging cost per result, high' when 'bench_form_min' then 'Lead form cost per result, low'
        when 'bench_form_target' then 'Lead form cost per result, target' when 'bench_form_max' then 'Lead form cost per result, high'
        when 'bench_cpm_min' then 'Cost per 1,000 impressions, low' when 'bench_cpm_max' then 'Cost per 1,000 impressions, high'
        when 'bench_cpl_rise' then 'Cost per lead rise a year' when 'bench_reels_share' then 'Reels share of impressions'
        when 'bench_ad_spend_pct' then 'Ad spend of the budget' when 'bench_adset_daily' then 'Daily budget an ad set, at least'
        when 'fx_sgd' then 'Singapore dollar rate'
        when 'health_keep_months' then 'Health check-ins kept' when 'health_leaver_months' then 'A leaver''s health data kept'
        when 'abroad_days' then 'Overseas approval'
        else 'Report due' end;
      v_pre := case when v_k = 'fx_sgd' then 'RM ' when v_k like 'ai_price_%' then 'US$' when v_k like 'bench_%' and v_k not in ('bench_cpl_rise', 'bench_reels_share', 'bench_ad_spend_pct') then 'RM ' else '' end;
      v_unit := case when v_k = 'fx_sgd' then ' to S$1' when v_k in ('lead_followup_hours', 'vic_lead_followup_hours', 'task_remind_hours', 'wa_repeat_hours') or v_k like 'priority_%_hours' then ' hours'
        when v_k in ('proposal_followup_days', 'vic_proposal_followup_days', 'report_due_days', 'revision_due_days', 'approval_reminder_days', 'task_start_days', 'quote_valid_days', 'details_form_days', 'abroad_days') then ' days'
        when v_k in ('health_keep_months', 'health_leaver_months') then ' months'
        when v_pre <> '' then '' else '%' end;
      v_fw := case when v_k = 'meta_checks' then case when v_was = 1 then 'On' else 'Off' end else coalesce(v_pre ||
              trim(to_char(v_was, case when v_k = 'fx_sgd' then 'FM999999990.9999' else 'FM999999990.99' end), '.') || v_unit, 'not set') end;
      v_fv := case when v_k = 'meta_checks' then case when v_v = 1 then 'On' else 'Off' end else v_pre ||
              trim(to_char(v_v, case when v_k = 'fx_sgd' then 'FM999999990.9999' else 'FM999999990.99' end), '.') || v_unit end;
      insert into public.activity_log (actor, action, subject, detail)
      values (coalesce(v_me.name, 'admin'), 'team.changed', 'Settings',
              case when v_drop then v_name || ': planned change withdrawn · ' || v_fw || ' from ' || public.register_day(p_from) ||
                ', stays ' || v_fv else
              v_name || ': ' || case when v_k = 'meta_checks' then
                case when v_was = 1 then 'On' else 'Off' end || ' → ' || case when v_v = 1 then 'On' else 'Off' end ||
                ' · from ' || public.register_day(p_from) else '' end ||
              case when v_k = 'meta_checks' then '' else coalesce(v_pre ||
              trim(to_char(v_was, case when v_k = 'fx_sgd' then 'FM999999990.9999' else 'FM999999990.99' end), '.') || v_unit, 'not set') || ' → ' || v_pre ||
              trim(to_char(v_v, case when v_k = 'fx_sgd' then 'FM999999990.9999' else 'FM999999990.99' end), '.') || v_unit ||
              ' · from ' || public.register_day(p_from) end end);
      v_moved := v_moved || v_k;
    end if;
  end loop;
  return public.app_settings_read() || jsonb_build_object('changed', to_jsonb(v_moved));
end $$;
revoke all on function public.app_settings_set(date, jsonb) from public, anon;
grant execute on function public.app_settings_set(date, jsonb) to authenticated;

-- END OF OVERSEAS APPROVAL DAYS ---------------------------------------------

-- ===========================================================================
-- ADMIN TOOLS END ON THE MINUTE — a granted part stops answering the moment
-- a colleague's access ends, and Issue Letter of Offer asks Letters too
-- (2026-10-24)
-- ===========================================================================
-- WHY (permissions audit 2026-10-24, S3 and N6c): `allowed()`, `is_team()`,
-- `ops_me()` and `me()` stop counting a colleague the minute their access
-- ends (ACCESS ENDS ON THE MINUTE), but `ops_granted` asked `active` alone,
-- so for up to five minutes, until `team_expire_access` ran, a leaver kept
-- every admin tool they held (Upgrade mode, the Handbook, AI limits, Bukku,
-- white label, the task number). `quotation_offer` made a quotation's lines
-- To quote without Clients: Letters, which the page and the rule ask
-- (Issue Letter of Offer asks Quotations, Service lines and Letters at Work).
--
-- WHAT IT CHANGES
--   * `ops_granted(p_key, p_level)`: refuses a colleague who is not an admin
--     once `team_access_ends(access_until, access_until_time)` has passed;
--     an admin stays the expiry run's, as in `allowed()`.
--   * `quotation_offer(p_id)`: `denied` without Clients: Letters at Work.
--
-- ORDER: this file (the connector; it holds no drop or delete), then
-- nothing: the pages already ask both. Safe to run twice. Rollback: the two
-- functions as OVERSEAS ACCESS and CLIENT PARTS FOR EACH TAB left them.
-- ===========================================================================

create or replace function public.ops_granted(p_key text, p_level text)
returns boolean
language plpgsql security definer stable set search_path = public as $$
declare t public.team_members;
begin
  select * into t from public.team_members
   where active and lower(email) = lower(auth.jwt() ->> 'email') limit 1;
  if t.id is null then return false; end if;
  if t.is_admin or t.role = 'admin' then return true; end if;
  if t.access_until is not null
     and public.team_access_ends(t.access_until, t.access_until_time) <= now() then return false; end if;
  if not public.team_place_ok(false, t.id) then return false; end if;
  return public.level_rank(t.access ->> p_key) >= public.level_rank(p_level);
end $$;
grant execute on function public.ops_granted(text, text) to authenticated;

create or replace function public.quotation_offer(p_id uuid)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  v_q public.quotations;
  v_l jsonb;
  v_ids uuid[] := '{}';
  v_id uuid;
begin
  if me.id is null or not (public.allowed('clients.quotes', 'work') and public.allowed('clients.services', 'work')
                           and public.allowed('clients.documents', 'work')) then return jsonb_build_object('error', 'denied'); end if;
  select * into v_q from public.quotations where id = p_id for update;
  if v_q.id is null or v_q.removed_at is not null or not public.client_scope_ok('client', v_q.client_id, 'work') then
    return jsonb_build_object('error', 'not-found');
  end if;
  if v_q.status = 'not_proceeding' then return jsonb_build_object('error', 'not-proceeding'); end if;
  select coalesce(array_agg(s.id order by s.created_at), '{}') into v_ids
    from public.client_services s where s.quotation_id = v_q.id and s.archived_at is null;
  if array_length(v_ids, 1) is not null then return jsonb_build_object('ok', true, 'ids', to_jsonb(v_ids), 'again', true); end if;
  if v_q.valid_until < (now() at time zone 'Asia/Kuala_Lumpur')::date then return jsonb_build_object('error', 'expired'); end if;
  for v_l in select * from jsonb_array_elements(v_q.lines) loop
    insert into public.client_services (client_id, service_slug, label, qty, rate, unit, state, note,
                                        tenure, term_adjust, term_pct, detail, quotation_id, tax_code)
    values (v_q.client_id,
            case when exists (select 1 from public.services s where s.slug = v_l->>'slug') then v_l->>'slug' end,
            v_l->>'label', (v_l->>'qty')::numeric, (v_l->>'rate')::numeric,
            case when v_l->>'basis' = 'month' then 'Per month' else 'One-off' end, 'quoted',
            'Quotation ' || v_q.ref,
            case when v_l->>'basis' = 'month' then coalesce((v_l->>'months')::int, (v_q.totals->>'term')::int) else 1 end,
            v_l->>'basis' = 'month', case when v_l->>'basis' = 'month' then (v_q.totals->>'term_pct')::numeric else 0 end,
            nullif(array_to_string(array(select jsonb_array_elements_text(coalesce(v_l->'detail', '[]'::jsonb))), E'\n'), ''),
            v_q.id, nullif(v_l->>'tax_code', ''))
    returning id into v_id;
    v_ids := v_ids || v_id;
  end loop;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'client.quotation', v_q.brand, v_q.ref || ' · ' || array_length(v_ids, 1) || ' lines To quote for the Letter of Offer');
  return jsonb_build_object('ok', true, 'ids', to_jsonb(v_ids));
end $$;
revoke all on function public.quotation_offer(uuid) from public, anon;
grant execute on function public.quotation_offer(uuid) to authenticated;

-- END OF ADMIN TOOLS END ON THE MINUTE -------------------------------------

-- ===========================================================================
-- HAND-OVER TAKES CLIENTS — a colleague's clients and open campaigns are
-- counted and handed over by the database, and a rename follows them
-- (2026-10-24)
-- ===========================================================================
-- WHY (the Team audit of 2026-10-24, TEAM2-3)
--   The page found a colleague's clients and open campaigns by reading every
--   client and campaign in the browser, under the caller's own policies: a
--   group seeing its own clients only missed the rest, a read stopped at a
--   thousand rows, and three heavy reads ran each time the Work pane, Set
--   inactive or Delete opened. The person in charge was then moved row by
--   row from the page, and a rename was carried the same way.
--
-- WHAT CHANGED
--   * `team_work_held(p_member)` also counts `clients` (every client whose
--     person in charge is the colleague, matched on the trimmed name in any
--     case, as the page matched it) and `campaigns` (their campaigns not
--     completed), and lists them (`client_list`: id, name, slug, Client ID,
--     stage; `campaign_list`: id, title, state) for the Work pane. Team Full
--     Access reads them whatever its client scope.
--   * `team_hand_over(p_member, p_to)` takes the kinds `clients` and
--     `campaigns`: the person in charge becomes the colleague chosen, each
--     record filed on its own Activity (`client.edited`, `campaign.edited`:
--     Person in charge: … to …) and in the one line under the colleague. A
--     completed campaign keeps who ran it. Every refusal it gave stands.
--   * `client_scope_guard` lets that write through (`adspace.team_owner`,
--     set by the function alone for its own statements), so a Team Full
--     Access colleague seeing their own clients only still hands over
--     clients they cannot see.
--   * Trigger `team_members_rename_owner` (after a change of name): every
--     client and every campaign naming the colleague as person in charge,
--     completed ones included (the same person, renamed), reads the new
--     name, each filed. It runs inside the colleague's write, so
--     `clients_owner_guard` and the scope guard, which leave a write made by
--     a trigger alone, do not stand in its way.
--
-- ORDER
--   This file, then the page (`js/team.js` stops reading clients and
--   campaigns itself). An open tab of the page before meets the old reads,
--   which still work; the new page on a database without this file finds no
--   `clients` in `team_work_held` and offers no client hand-over.
--
-- Safe to run twice. Rollback: run COLLEAGUE HAND-OVER's team_work_held,
-- COLLEAGUE LEAVING's team_hand_over and SALES BY's client_scope_guard again,
-- then in the SQL Editor:
--   drop trigger if exists team_members_rename_owner on public.team_members;
--   drop function if exists public.team_members_rename_owner();
-- ===========================================================================

create or replace function public.team_work_held(p_member uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  me     public.team_members := public.ops_me();
  v_name text;
begin
  if me.id is null or not public.allowed('team', 'manage') then return jsonb_build_object('error', 'denied'); end if;
  select lower(btrim(coalesce(x.name, ''))) into v_name from public.team_members x where x.id = p_member;
  if not found then
    return jsonb_build_object('error', 'not-found');
  end if;
  return jsonb_build_object('ok', true,
    'clients', (select count(*) from public.clients c where v_name <> '' and lower(btrim(coalesce(c.owner, ''))) = v_name),
    'campaigns', (select count(*) from public.campaigns g where v_name <> '' and lower(btrim(coalesce(g.owner, ''))) = v_name
                    and g.state is distinct from 'completed'),
    'client_list', coalesce((select jsonb_agg(jsonb_build_object('id', c.id, 'name', c.name, 'slug', c.slug,
                      'client_code', c.client_code, 'stage', c.stage) order by c.name, c.id)
                    from public.clients c where v_name <> '' and lower(btrim(coalesce(c.owner, ''))) = v_name), '[]'::jsonb),
    'campaign_list', coalesce((select jsonb_agg(jsonb_build_object('id', g.id, 'title', g.title, 'state', g.state)
                      order by g.title, g.id)
                    from public.campaigns g where v_name <> '' and lower(btrim(coalesce(g.owner, ''))) = v_name
                      and g.state is distinct from 'completed'), '[]'::jsonb),
    'tasks', (select count(*) from public.ops_task_assignees a join public.ops_tasks t on t.id = a.task_id
               where a.team_member_id = p_member and a.responsibility = 'owner' and a.ended_at is null
                 and t.archived_at is null and t.completed_at is null and t.cancelled_at is null),
    'months', (select count(*) from public.ops_engagements e
                where e.manager_id = p_member and e.status not in ('completed', 'cancelled')),
    'meetings', (select count(*) from public.ops_engagements e
                  where e.meeting_owner_id = p_member and e.status not in ('completed', 'cancelled')
                    and e.meeting_at > now()),
    'repeats', (select count(*) from public.ops_recurring_rules r where r.owner_id = p_member and r.active),
    'reviews', (select count(*) from public.sm_reports s where s.reviewer_id = p_member and s.status = 'review'),
    'extensions', (select count(*) from public.ops_due_requests d where d.decider_id = p_member and d.state = 'asked'),
    'templates', (select count(*) from public.ops_task_templates x where x.default_owner_id = p_member and x.active));
end $$;
revoke all on function public.team_work_held(uuid) from public, anon;
grant execute on function public.team_work_held(uuid) to authenticated;

create or replace function public.client_scope_guard()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  kind text := tg_argv[0];
  col  text := tg_argv[1];
  o jsonb;
  n jsonb := to_jsonb(new);
begin
  if pg_trigger_depth() > 1 or public.client_scope_free('work') then return new; end if;
  if tg_op = 'UPDATE' and tg_table_name = 'sm_report_versions'
     and coalesce(current_setting('adspace.keep_file', true), '') = 'on' then
    return new;
  end if;
  -- `team_hand_over` moving the person in charge (HAND-OVER TAKES CLIENTS).
  if tg_op = 'UPDATE' and tg_table_name in ('clients', 'campaigns')
     and coalesce(current_setting('adspace.team_owner', true), '') = 'on' then
    return new;
  end if;
  if tg_op = 'UPDATE' then
    o := to_jsonb(old);
    if (kind = 'self' and not public.client_row_seen_by(o ->> 'stage', o ->> 'owner', (o ->> 'sales_by')::uuid, 'work'))
       or (kind <> 'self' and not public.client_scope_ok(kind, (o ->> col)::uuid, 'work')) then
      raise exception 'This client is outside your access.' using errcode = '42501', hint = 'client-scope';
    end if;
  end if;
  if (kind = 'self' and not public.client_row_seen_by(n ->> 'stage', n ->> 'owner', (n ->> 'sales_by')::uuid, 'work'))
     or (kind <> 'self' and not public.client_scope_ok(kind, (n ->> col)::uuid, 'work')) then
    raise exception 'This client is outside your access.' using errcode = '42501', hint = 'client-scope';
  end if;
  return new;
end $$;
revoke all on function public.client_scope_guard() from public, anon, authenticated;

create or replace function public.team_hand_over(p_member uuid, p_to jsonb)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me      public.team_members := public.ops_me();
  v_from  public.team_members;
  v_who   public.team_members;
  v_kind  text;
  v_id    text;
  v_to    uuid;
  v_n     integer;
  v_skip  integer := 0;
  v_moved jsonb := '{}'::jsonb;
  v_lines text[] := '{}';
  v_cl    text;
  v_key   text;
  r       record;
  v_kinds constant text[] := array['clients', 'campaigns', 'tasks', 'months', 'meetings', 'repeats', 'reviews',
                                   'extensions', 'templates'];
  v_words constant text[] := array['clients', 'open campaigns', 'open tasks', 'months', 'meetings', 'repeating tasks',
                                   'reports to review', 'extension requests', 'templates'];
  v_one   constant text[] := array['client', 'open campaign', 'open task', 'month', 'meeting', 'repeating task',
                                   'report to review', 'extension request', 'template'];
begin
  if me.id is null or not public.allowed('team', 'manage') then return jsonb_build_object('error', 'denied'); end if;
  select * into v_from from public.team_members x where x.id = p_member;
  if v_from.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if v_from.id = me.id then return jsonb_build_object('error', 'own'); end if;
  if coalesce(v_from.system, false) then return jsonb_build_object('error', 'system-account'); end if;
  if jsonb_typeof(p_to) is distinct from 'object' then return jsonb_build_object('error', 'bad-request'); end if;
  for v_kind in select jsonb_object_keys(p_to) loop
    if not (v_kind = any(v_kinds)) then return jsonb_build_object('error', 'bad-kind', 'kind', v_kind); end if;
    v_id := nullif(btrim(coalesce(p_to ->> v_kind, '')), '');
    if v_id is null then continue; end if;
    if v_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      return jsonb_build_object('error', 'bad-person', 'kind', v_kind);
    end if;
    select * into v_who from public.team_members x
     where x.id = v_id::uuid and x.active and not coalesce(x.system, false) and x.id <> p_member;
    if v_who.id is null then return jsonb_build_object('error', 'bad-person', 'kind', v_kind); end if;
  end loop;

  v_key := lower(btrim(coalesce(v_from.name, '')));
  for v_kind in select unnest(v_kinds) loop
    v_id := nullif(btrim(coalesce(p_to ->> v_kind, '')), '');
    if v_id is null then continue; end if;
    v_to := v_id::uuid;
    select * into v_who from public.team_members x where x.id = v_to;
    v_n := 0;
    if v_kind = 'clients' then
      perform set_config('adspace.team_owner', 'on', true);
      for r in select c.id, c.name from public.clients c
                where v_key <> '' and lower(btrim(coalesce(c.owner, ''))) = v_key order by c.id for update loop
        update public.clients c set owner = v_who.name where c.id = r.id;
        insert into public.activity_log (actor, action, subject, detail)
        values (me.name, 'client.edited', r.name, 'Person in charge: ' || v_from.name || ' to ' || v_who.name);
        v_n := v_n + 1;
      end loop;
      perform set_config('adspace.team_owner', 'off', true);
    elsif v_kind = 'campaigns' then
      perform set_config('adspace.team_owner', 'on', true);
      for r in select g.id, g.title from public.campaigns g
                where v_key <> '' and lower(btrim(coalesce(g.owner, ''))) = v_key
                  and g.state is distinct from 'completed' order by g.id for update loop
        update public.campaigns g set owner = v_who.name where g.id = r.id;
        insert into public.activity_log (actor, action, subject, detail)
        values (me.name, 'campaign.edited', r.title, 'Person in charge: ' || v_from.name || ' to ' || v_who.name);
        v_n := v_n + 1;
      end loop;
      perform set_config('adspace.team_owner', 'off', true);
    elsif v_kind = 'tasks' then
      for r in select t.id, t.stage_key from public.ops_tasks t
                where t.archived_at is null and t.completed_at is null and t.cancelled_at is null
                  and exists (select 1 from public.ops_task_assignees a where a.task_id = t.id and a.responsibility = 'owner'
                                 and a.ended_at is null and a.team_member_id = p_member)
                order by t.id for update of t loop
        update public.ops_task_assignees a set ended_at = now()
         where a.task_id = r.id and a.responsibility = 'owner' and a.ended_at is null;
        insert into public.ops_task_assignees (task_id, team_member_id, responsibility, assigned_by)
        values (r.id, v_to, 'owner', me.id);
        update public.ops_tasks t set version = t.version + 1, updated_at = now() where t.id = r.id;
        perform public.ops_log(r.id, 'assignment_changed',
          jsonb_build_object('owner_id', p_member), jsonb_build_object('owner_id', v_to),
          jsonb_build_object('handover', true, 'stage_key', r.stage_key, 'note', 'Handed over from ' || v_from.name));
        v_n := v_n + 1;
      end loop;
    elsif v_kind = 'months' then
      for r in select e.id from public.ops_engagements e
                where e.manager_id = p_member and e.status not in ('completed', 'cancelled') order by e.id for update loop
        update public.ops_engagements e set manager_id = v_to, updated_at = now(), version = e.version + 1 where e.id = r.id;
        perform public.ops_engagement_log(r.id, 'edited', jsonb_build_object('handover', true,
          'manager_id', jsonb_build_object('from', p_member, 'to', v_to)));
        v_n := v_n + 1;
      end loop;
    elsif v_kind = 'meetings' then
      for r in select e.id from public.ops_engagements e
                where e.meeting_owner_id = p_member and e.status not in ('completed', 'cancelled')
                  and e.meeting_at > now() order by e.id for update loop
        update public.ops_engagements e set meeting_owner_id = v_to, updated_at = now(), version = e.version + 1 where e.id = r.id;
        perform public.ops_engagement_log(r.id, 'edited', jsonb_build_object('handover', true,
          'meeting_owner_id', jsonb_build_object('from', p_member, 'to', v_to)));
        v_n := v_n + 1;
      end loop;
    elsif v_kind = 'repeats' then
      update public.ops_recurring_rules x set owner_id = v_to, updated_at = now()
       where x.owner_id = p_member and x.active;
      get diagnostics v_n = row_count;
    elsif v_kind = 'reviews' then
      for r in select s.id, s.client_id, s.submitted_by, s.period_start, s.period_end from public.sm_reports s
                where s.reviewer_id = p_member and s.status = 'review' order by s.id for update loop
        if r.submitted_by is not distinct from v_to or not public.sm_report_may_review(v_to) then
          v_skip := v_skip + 1;
          continue;
        end if;
        perform set_config('adspace.sm_fn', 'on', true);
        update public.sm_reports s set reviewer_id = v_to where s.id = r.id;
        perform set_config('adspace.sm_fn', 'off', true);
        perform public.sm_report_log(r.id, 'report.reassigned', 'Reviewer: ' || v_from.name || ' → ' || v_who.name);
        select c.name into v_cl from public.clients c where c.id = r.client_id;
        perform public.sm_report_notify(v_to, r.id, 'report.review', 'Report to review',
          coalesce(v_cl, 'A client') || ' · ' || public.sm_period_word(r.period_start, r.period_end));
        v_n := v_n + 1;
      end loop;
    elsif v_kind = 'extensions' then
      update public.ops_due_requests x set decider_id = v_to where x.decider_id = p_member and x.state = 'asked';
      get diagnostics v_n = row_count;
    elsif v_kind = 'templates' then
      update public.ops_task_templates x set default_owner_id = v_to, updated_at = now()
       where x.default_owner_id = p_member and x.active;
      get diagnostics v_n = row_count;
    end if;
    if v_n > 0 then
      v_moved := v_moved || jsonb_build_object(v_kind, v_n);
      v_lines := v_lines || (v_n || ' ' || (case when v_n = 1 then v_one else v_words end)[array_position(v_kinds, v_kind)]
        || ' → ' || v_who.name);
    end if;
  end loop;

  if array_length(v_lines, 1) > 0 then
    insert into public.activity_log (actor, action, subject, detail)
    values (me.name, 'team.changed', v_from.name, 'Work handed over: ' || array_to_string(v_lines, '; '));
  end if;
  return jsonb_build_object('ok', true, 'moved', v_moved, 'skipped', jsonb_build_object('reviews', v_skip));
end $$;
revoke all on function public.team_hand_over(uuid, jsonb) from public, anon;
grant execute on function public.team_hand_over(uuid, jsonb) to authenticated;

create or replace function public.team_members_rename_owner()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_old text := lower(btrim(coalesce(old.name, '')));
  v_new text := btrim(coalesce(new.name, ''));
  v_by  text := coalesce((public.ops_me()).name, 'system');
  r     record;
begin
  if v_old = '' or v_new = '' or v_old = lower(v_new) and btrim(coalesce(old.name, '')) = v_new then
    return new;
  end if;
  for r in select c.id, c.name from public.clients c where lower(btrim(coalesce(c.owner, ''))) = v_old order by c.id loop
    update public.clients c set owner = v_new where c.id = r.id;
    insert into public.activity_log (actor, action, subject, detail)
    values (v_by, 'client.edited', r.name, 'Person in charge: ' || btrim(old.name) || ' to ' || v_new);
  end loop;
  for r in select g.id, g.title from public.campaigns g where lower(btrim(coalesce(g.owner, ''))) = v_old order by g.id loop
    update public.campaigns g set owner = v_new where g.id = r.id;
    insert into public.activity_log (actor, action, subject, detail)
    values (v_by, 'campaign.edited', r.title, 'Person in charge: ' || btrim(old.name) || ' to ' || v_new);
  end loop;
  return new;
end $$;
revoke all on function public.team_members_rename_owner() from public, anon, authenticated;

create or replace trigger team_members_rename_owner after update of name on public.team_members
  for each row when (old.name is distinct from new.name) execute function public.team_members_rename_owner();

-- END OF HAND-OVER TAKES CLIENTS ---------------------------------------------

-- ===========================================================================
-- DEPARTMENTS IN RECORDS — the list says which department records still
-- name, so Delete is offered only where it would go through (2026-10-24)
-- ===========================================================================
-- WHY (the Team audit of 2026-10-24, TEAM2-15)
--   Settings' Departments offered Delete wherever no active colleague was in
--   the department, and `department_delete` then refused it (`in-use`)
--   where a colleague no longer active, a review profile or a prize score
--   still named it: an act offered only to be refused.
--
-- WHAT CHANGED
--   * `departments_list()` also answers `in_records` for each department:
--     true while any colleague (active or not), a performance review
--     profile or a department prize score names it, exactly what
--     `department_delete` refuses. The page draws Delete only where neither
--     `members` nor `in_records` holds; the function still refuses.
--
-- ORDER
--   This file, then the page. An open page before reads the extra key and
--   ignores it; the new page on a database without it reads no
--   `in_records` and offers Delete as before.
--
-- Safe to run twice. Rollback: run DEPARTMENTS' departments_list again.
-- ===========================================================================

create or replace function public.departments_list()
returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.is_team() then return jsonb_build_object('error', 'denied'); end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
      'key', d.key, 'name', d.name, 'active', d.active, 'in_prize', d.in_prize,
      'criteria', coalesce(d.criteria, '[]'::jsonb),
      'members', (select count(*)::int from public.team_members t where t.department = d.key and t.active),
      'in_records', exists (select 1 from public.team_members t where t.department = d.key)
                    or exists (select 1 from public.perf_people p where p.department = d.key)
                    or exists (select 1 from public.perf_dept_scores s where s.department = d.key))
      order by d.position, lower(d.name))
    from public.departments d), '[]'::jsonb);
end $$;
revoke all on function public.departments_list() from public, anon;
grant execute on function public.departments_list() to authenticated;

-- END OF DEPARTMENTS IN RECORDS ----------------------------------------------

-- ===========================================================================
-- ADMIN TOOLS ARE AN ADMIN'S — only an admin turns on, changes or takes off a
-- granted part on any group (2026-10-24)
-- ===========================================================================
-- WHY (the permissions audit of 2026-10-24, S2; the user decided "admins
-- only", declining that Team Full Access delegate Performance or HR Letters)
--   A colleague at Team Full Access who is not an admin could open a group,
--   their own included, and switch on any admin tool (Business settings,
--   Upgrade mode, Performance reviews, Supplier bank details …): the tools
--   are granted parts in `access`, and `team_roles_admin_guard` held only a
--   group made admin.
--
-- WHAT CHANGED
--   * `team_roles_admin_guard` also refuses, for a signed-in caller who is
--     not an admin, a group written (made or changed) whose granted parts
--     differ from what it held (`admin-only`). The granted parts are those
--     `ops_granted` is asked for, the page's GRANTED: ops.all, ops.reports,
--     ops.workflows, ops.time, ops.numbering, ops.override,
--     team.performance, team.perfadmin, team.settings, team.upgrade,
--     team.invite, team.handbook, team.announce, team.notice,
--     reports.whitelabel, reports.transfer, reports.ai, reports.meta,
--     register.types, campaigns.files_delete, clients.vic, suppliers.pay.
--     Every other key, and a group's name and scope, stay Team Full
--     Access's. An admin, a write made by another trigger and a run with no
--     sign-in pass, as before.
--
-- ORDER
--   This file, then the page, which disables the switches and granted
--   selects for anyone not an admin. An open page before still offers them
--   and meets the refusal in the team's words.
--
-- Safe to run twice. Rollback: run ADMINS MADE BY ADMINS'
-- team_roles_admin_guard again.
-- ===========================================================================

create or replace function public.team_roles_admin_guard()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  who text := lower(coalesce(auth.jwt() ->> 'email', ''));
  v_granted constant text[] := array['ops.all', 'ops.reports', 'ops.workflows', 'ops.time', 'ops.numbering',
    'ops.override', 'team.performance', 'team.perfadmin', 'team.settings', 'team.upgrade', 'team.invite',
    'team.handbook', 'team.announce', 'team.notice', 'reports.whitelabel', 'reports.transfer', 'reports.ai',
    'reports.meta', 'register.types', 'campaigns.files_delete', 'clients.vic', 'suppliers.pay'];
  k text;
begin
  if who = '' or pg_trigger_depth() > 1 or public.allowed('admin') then
    if tg_op = 'DELETE' then return old; end if;
    return new;
  end if;
  if (tg_op <> 'INSERT' and (coalesce(old.is_admin, false) or old.slug = 'admin'))
     or (tg_op <> 'DELETE' and (coalesce(new.is_admin, false) or new.slug = 'admin')) then
    raise exception 'admin-only' using errcode = '42501', hint = 'Only an admin changes an admin group.';
  end if;
  if tg_op = 'DELETE' then return old; end if;
  foreach k in array v_granted loop
    if coalesce(new.access ->> k, '') is distinct from
       (case when tg_op = 'INSERT' then '' else coalesce(old.access ->> k, '') end) then
      raise exception 'admin-only' using errcode = '42501', hint = 'Only an admin changes an admin tool.';
    end if;
  end loop;
  return new;
end $$;
revoke all on function public.team_roles_admin_guard() from public, anon, authenticated;

-- END OF ADMIN TOOLS ARE AN ADMIN'S ------------------------------------------

-- ===========================================================================
-- HR HISTORY APART — an HR letter's history is read at HR Letters, its own
-- part of the Activity record (2026-10-24)
-- ===========================================================================
-- WHY (the permissions audit of 2026-10-24, S5; the user decided "file it
-- apart")
--   An HR document's history (issued, edited, voided, deleted; filed under
--   subject HR with its kind alone) is tagged as a Documents act, so the
--   Activity record's Documents part opened it: the View only and Manager
--   presets, which hold the Activity record at View and never HR Letters,
--   read when each colleague's letters were issued and voided.
--
-- WHAT CHANGED
--   * The read policy `activity_read` answers a Documents row filed under
--     subject HR only where the reader holds the Activity record's own part
--     for it, HR letters (`activity.hr`), and HR Letters themselves
--     (`register.hr`) at View. Every other row is read as before, by its
--     section's part. `activity_section()` and the tags are unchanged.
--   * The policy is altered in place (`alter policy`), so nothing is
--     dropped and a page reading the record keeps reading it meanwhile.
--
-- ORDER
--   This file, then the page (the Section select offers HR letters, and
--   Documents reads without them). An open page before reads Documents
--   without the HR rows a reader may no longer see.
--
-- Safe to run twice. Rollback:
--   alter policy activity_read on public.activity_log
--     using (public.allowed('activity.' || public.activity_section(action), 'view'));
-- ===========================================================================

alter policy activity_read on public.activity_log
  using (case when public.activity_section(action) = 'register' and subject = 'HR'
              then public.allowed('activity.hr', 'view') and public.allowed('register.hr', 'view')
              else public.allowed('activity.' || public.activity_section(action), 'view') end);

-- END OF HR HISTORY APART ----------------------------------------------------

-- ===========================================================================
-- UNUSED TABLES DROPPED — five tables nothing reads or writes any more
-- (2026-10-24)
-- ===========================================================================
-- WHY (the cleanup audit of 2026-10-24, R5; the user: "Ok yes")
--   Five tables stood in the database with no page, function, view or
--   policy of another table reading them: `activity_viewers` (the old
--   Activity switch, replaced by the access map; one row), `ops_kpi_targets`
--   (never filled), `report_partners` and `report_partner_clients` (white
--   label moved onto the client, 2026-10-07; their functions dropped
--   2026-10-19) and `video_script_reviews` (the client's link decides
--   nothing since 2026-10-09; `script_decide` answers `closed`).
--   `sm_reports.partner_id` (set on no report) goes with `report_partners`.
--   `ops_engagement_events` is kept: it is a month's change history.
--
-- WHAT CHANGED
--   * `sm_report_brand` no longer clears `partner_id`.
--   * `sm_reports.partner_id` is dropped, then the five tables.
--
-- ORDER
--   This file in the SQL Editor (it holds drops the connector holds back).
--   No page reads any of them, so an open page meets nothing.
--
-- Safe to run twice. Rollback: run REPORT PARTNERS, WHITE LABEL ON THE
-- REPORT, the ACTIVITY VIEWERS, OPS KPI TARGETS and VIDEO SCRIPTS table
-- sections of schema.sql again (empty tables; the one activity_viewers row
-- is not restored), and WHITE LABEL BRANDS' sm_report_brand.
-- ===========================================================================

create or replace function public.sm_report_brand(p_id uuid, p_brand uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.sm_reports;
  c public.clients;
  b public.client_brands;
begin
  if me.id is null or not public.ops_granted('reports.whitelabel', 'work') then
    return jsonb_build_object('error', 'denied');
  end if;
  select * into r from public.sm_reports where id = p_id for update;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if not public.client_seen(r.client_id, 'view') then return jsonb_build_object('error', 'denied'); end if;
  if r.status = 'published' then return jsonb_build_object('error', 'published'); end if;
  select * into c from public.clients where id = r.client_id;
  if p_brand is not null then
    select * into b from public.client_brands where id = p_brand;
    if b.id is null or b.client_id <> r.client_id or not b.active or not c.white_label or c.report_logo is null then
      return jsonb_build_object('error', 'bad-brand');
    end if;
  end if;
  if r.brand_id is not distinct from p_brand then return jsonb_build_object('ok', true); end if;
  if exists (select 1 from public.sm_reports x
              where x.client_id = r.client_id and x.kind = r.kind and x.id <> r.id
                and x.period_start = r.period_start and x.period_end = r.period_end
                and x.brand_id is not distinct from p_brand) then
    return jsonb_build_object('error', 'exists');
  end if;
  perform set_config('adspace.sm_fn', 'on', true);
  begin
    update public.sm_reports
       set brand_id = b.id, brand_name = b.name,
           label_client = case when b.id is not null then r.client_id end
     where id = p_id;
  exception when unique_violation then
    perform set_config('adspace.sm_fn', 'off', true);
    return jsonb_build_object('error', 'index-pending');
  end;
  perform set_config('adspace.sm_fn', 'off', true);
  perform public.sm_report_log(p_id, 'report.saved',
    'White label: ' || coalesce(r.brand_name, 'not set') || ' → ' || coalesce(b.name, 'not set'));
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.sm_report_brand(uuid, uuid) from public, anon;
grant execute on function public.sm_report_brand(uuid, uuid) to authenticated;

alter table public.sm_reports drop column if exists partner_id;
drop table if exists public.report_partner_clients;
drop table if exists public.report_partners;
drop table if exists public.video_script_reviews;
drop table if exists public.ops_kpi_targets;
drop table if exists public.activity_viewers;

