-- ===========================================================================
-- A COLLEAGUE'S LAST SIGN-IN AND LAST ACTIVE — read on their record's rail
-- at Team Full Access (2026-10-24)
-- ===========================================================================
-- WHY (Team audit TEAM2-9; the user decided the colleague record takes a
-- rail as a client's does, with when they last signed in and were last
-- active)
--   Team showed nothing of whether a colleague uses the console: an invited
--   colleague who never signed in, or one who stopped, read the same as
--   everybody else.
--
-- WHAT CHANGED
--   * `team_members.last_seen_at`: stamped by `page_pulse` for the team
--     audience (the console's minute) at most once every 15 minutes, for the
--     signed-in colleague alone (`ops_me()`); a client page asks for the
--     clients' audience and never stamps. Withheld from the table's column
--     grants (never named in them); `team_rows()` answers it at Team Full
--     Access alone and as null below it.
--   * `team_role_defaults` leaves `updated_at` alone when only
--     `last_seen_at` moved, so the stamp never makes a colleague's record
--     read as changed meanwhile (a save over the row as read).
--   * `page_pulse` is volatile (it writes the stamp); a stamp that fails is
--     swallowed and never fails the minute.
--   * `team_member_seen(p_id)` (Team Full Access, else null): the last
--     sign-in from `auth.users`, the last active, and when an invitation
--     was last sent (`team_invites`), for one colleague not erased.
--   * Trigger `team_members_erased_seen` clears `last_seen_at` the moment a
--     colleague's personal details are erased.
--
-- ORDER
--   This file, then the pages (the rail asks `team_member_seen`). An open
--   page before never asks it; one after this file and before the pages
--   reads nothing new.
--
-- Safe to run twice. Rollback: run THE TEAM LIST HOLDS WHAT EVERY COLLEAGUE
-- NEEDS' team_rows, ONE CHECK A MINUTE's page_pulse and the schema's
-- team_role_defaults again; the column, trigger and function may stay.
-- ===========================================================================

alter table public.team_members add column if not exists last_seen_at timestamptz;

create or replace function public.team_role_defaults()
returns trigger language plpgsql as $$
declare r public.team_roles;
begin
  /* The console's minute stamps when a colleague was last active; that
     alone is no change to their record (A COLLEAGUE'S LAST SIGN-IN). */
  if tg_op = 'UPDATE' and new.last_seen_at is distinct from old.last_seen_at
     and (to_jsonb(new) - 'last_seen_at') = (to_jsonb(old) - 'last_seen_at') then
    return new;
  end if;
  select * into r from public.team_roles where slug = new.role;
  if r.slug is null then
    select * into r from public.team_roles where slug = 'account';
    new.role := 'account';
  end if;
  new.is_admin      := r.is_admin;
  new.can_clients   := r.can_clients;   new.can_review   := r.can_review;
  new.can_campaigns := r.can_campaigns; new.can_links    := r.can_links;
  new.can_activity  := r.can_activity;  new.can_billing  := r.can_billing;
  new.can_remove    := r.can_remove;    new.can_doc_void := r.can_doc_void;
  new.access        := coalesce(r.access, '{}'::jsonb);
  new.client_scope  := coalesce(r.client_scope, 'all');
  new.updated_at    := now();
  return new;
end $$;

create or replace function public.team_members_erased_seen()
returns trigger language plpgsql set search_path = public as $$
begin
  if new.erased_at is not null then new.last_seen_at := null; end if;
  return new;
end $$;
revoke all on function public.team_members_erased_seen() from public, anon, authenticated;
create or replace trigger team_members_erased_seen before update of erased_at on public.team_members
  for each row execute function public.team_members_erased_seen();

create or replace function public.page_pulse(p_audience text default null, p_bell boolean default false)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me public.team_members;
  v  jsonb := jsonb_build_object('maintenance', public.maintenance_state());
begin
  if p_audience in ('team', 'clients') then
    v := v || jsonb_build_object('announcements', coalesce(public.announcement_now(p_audience), '[]'::jsonb));
  end if;
  /* The console's minute says the colleague is active, at most once every
     15 minutes; a client page asks for the clients and never stamps. */
  if p_audience = 'team' then
    begin
      update public.team_members t set last_seen_at = now()
       where t.id = (public.ops_me()).id
         and (t.last_seen_at is null or t.last_seen_at < now() - interval '15 minutes');
    exception when others then null;
    end;
  end if;
  if coalesce(p_bell, false) then
    me := public.ops_me();
    if me.id is not null then
      v := v || jsonb_build_object('bell', jsonb_build_object(
        'unread', coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at desc)
                              from (select * from public.ops_notifications o
                                     where o.team_member_id = me.id and o.read_at is null and o.hidden_at is null
                                     order by o.created_at desc limit 30) x), '[]'::jsonb),
        'earlier', coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at desc)
                               from (select * from public.ops_notifications o
                                      where o.team_member_id = me.id and o.read_at is not null and o.hidden_at is null
                                        and o.created_at >= now() - interval '7 days'
                                      order by o.created_at desc limit 10) x), '[]'::jsonb)));
    end if;
  end if;
  return v;
end $$;
revoke all on function public.page_pulse(text, boolean) from public;
grant execute on function public.page_pulse(text, boolean) to anon, authenticated;

create or replace function public.team_rows()
returns setof public.team_members
language sql stable security definer set search_path = public as $$
  select (jsonb_populate_record(t, case when public.allowed('team', 'manage') then '{}'::jsonb
                                        else '{"last_seen_at": null}'::jsonb end)).*
    from public.team_members t
   where public.allowed('team', 'view')
   order by t.active desc, t.role, t.name
$$;
revoke all on function public.team_rows() from public, anon, authenticated;
grant execute on function public.team_rows() to authenticated;

create or replace function public.team_member_seen(p_id uuid)
returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
           'last_sign_in_at', (select u.last_sign_in_at from auth.users u
                                where lower(u.email) = lower(t.email)
                                order by u.last_sign_in_at desc nulls last limit 1),
           'last_seen_at', t.last_seen_at,
           'invited_at', (select max(i.created_at) from public.team_invites i
                           where lower(i.email) = lower(t.email) and i.kind = 'team'))
    from public.team_members t
   where t.id = p_id and t.erased_at is null and public.allowed('team', 'manage')
$$;
revoke all on function public.team_member_seen(uuid) from public, anon, authenticated;
grant execute on function public.team_member_seen(uuid) to authenticated;

-- END OF A COLLEAGUE'S LAST SIGN-IN -------------------------------------------

-- ===========================================================================
-- ADMIN NOTICES REACH THE SYSTEM ACCOUNT — and a waiting overseas request
-- reminds the admins until it is decided (2026-10-24)
-- ===========================================================================
-- WHY (the user, 2026-10-24): a colleague's overseas request reached one
-- admin, whose phone takes no notifications, and nobody else: the system
-- account was left out. "System account acts same as other admins. The
-- only difference is that it could overwrite everything without reason."
-- A request then waited with nothing to bring it back.
--
-- WHAT CHANGED
--   * `team_notice_send`, `quote_tell`, `client_details_submit`,
--     `supplier_form_submit` and `abroad_request` tell a system account as
--     they tell every other colleague who qualifies. Nothing else in them
--     moves. Task work (the reminders, pickers) still leaves it out.
--   * `team_abroad.reminded_at`; a request asked again starts afresh.
--   * `abroad_remind()` (pg_cron `abroad-remind`, every fifteen minutes from
--     08:00 to 22:45 MYT): every request still waiting, its colleague
--     active and its day not passed, tells every active admin again once
--     `abroad_remind_hours` (2, a Business setting, 0 sends none) have
--     passed since it was asked or last reminded. The service role's alone.
--
-- ORDER
--   This file, then OVERSEAS REMINDER SETTING in the SQL Editor (Settings
--   edits the hours only once it has run), then the pages. The page before
--   reads no new key; a reminder reads as the request's own notice.
--
-- Safe to run twice. Rollback: run each function from its section before
-- (TEAM NOTICES' send as last restated, QUOTATION WEBSITE, CLIENT DETAILS
-- FORM, SUPPLIER UPDATE LINK, OVERSEAS ACCESS) and unschedule
-- `abroad-remind`.
-- ===========================================================================

alter table public.team_abroad add column if not exists reminded_at timestamptz;

insert into public.app_settings (key, from_date, value)
select 'abroad_remind_hours', date '2023-08-14', 2
 where not exists (select 1 from public.app_settings s where s.key = 'abroad_remind_hours');

create or replace function public.team_notice_send(p_title text, p_body text, p_to uuid[])
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  v_title text := btrim(coalesce(p_title, ''));
  v_body  text := nullif(btrim(coalesce(p_body, '')), '');
  v_to    uuid[];
  v_id    uuid;
  n       int;
  v_sent  int;
  v_first timestamptz;
begin
  if me.id is null or not public.ops_granted('team.notice', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if v_title = '' or length(v_title) > 120 then return jsonb_build_object('error', 'bad-title'); end if;
  if v_body is not null and length(v_body) > 1000 then return jsonb_build_object('error', 'bad-body'); end if;
  perform pg_advisory_xact_lock(hashtext('team-notice-send:' || me.id::text));
  select count(*), min(tn.created_at) into v_sent, v_first
    from (select x.created_at from public.team_notices x
           where x.sent_by = me.id and x.created_at > now() - interval '1 hour'
           order by x.created_at desc limit 10) tn;
  if v_sent >= 10 then
    return jsonb_build_object('error', 'too-many', 'limit', 10, 'next', v_first + interval '1 hour');
  end if;
  select coalesce(array_agg(m.id order by m.name), '{}') into v_to
    from public.team_members m
   where m.active and m.id <> me.id
     and (p_to is null or m.id = any(p_to));
  n := coalesce(array_length(v_to, 1), 0);
  if n = 0 then return jsonb_build_object('error', 'no-one'); end if;
  insert into public.team_notices (title, body, to_all, recipients, sent_by, sent_by_name)
  values (v_title, v_body, p_to is null, v_to, me.id, me.name)
  returning id into v_id;
  insert into public.ops_notifications (team_member_id, kind, title, body, notice_id, from_name)
  select x, 'notice', v_title, v_body, v_id, me.name from unnest(v_to) as x;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'team.changed', 'Notices',
    'Sent to ' || case when p_to is null then 'all colleagues (' || n || ')'
                       when n = 1 then '1 colleague' else n || ' colleagues' end || ': ' || v_title);
  return jsonb_build_object('ok', true, 'id', v_id, 'count', n);
end $$;
revoke all on function public.team_notice_send(text, text, uuid[]) from public, anon;
grant execute on function public.team_notice_send(text, text, uuid[]) to authenticated;

create or replace function public.quote_tell(p_client uuid, p_kind text, p_title text, p_body text, p_key text)
returns void
language plpgsql volatile security definer set search_path = public as $$
begin
  insert into public.ops_notifications (team_member_id, kind, title, body, client_id, dedupe_key)
  select m.id, p_kind, p_title, p_body, p_client, p_kind || ':' || p_key || ':' || m.id
    from public.team_members m
   where m.active
     and (m.is_admin or m.role = 'admin'
          or public.level_rank(coalesce(m.access ->> 'clients.leads', m.access ->> 'clients')) >= 2)
  on conflict (dedupe_key) do nothing;
end $$;
revoke all on function public.quote_tell(uuid, text, text, text, text) from public, anon, authenticated;

create or replace function public.client_details_submit(p_key text, p_answers jsonb)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  v_f    public.client_detail_forms;
  v_cl   public.clients;
  a      jsonb := coalesce(p_answers, '{}'::jsonb);
  t      text;
  v_name text := upper(btrim(regexp_replace(coalesce(a->>'legal_name', ''), '\s+', ' ', 'g')));
  v_brn  text := upper(regexp_replace(coalesce(a->>'company_no', ''), '\s+', '', 'g'));
  v_old  text := nullif(upper(regexp_replace(coalesce(a->>'company_no_old', ''), '\s+', '', 'g')), '');
  v_tin  text := nullif(upper(regexp_replace(coalesce(a->>'tin', ''), '\s+', '', 'g')), '');
  v_sst  text := nullif(upper(regexp_replace(coalesce(a->>'sst_no', ''), '\s+', '', 'g')), '');
  v_addr text := btrim(coalesce(a->>'billing_address', ''));
  v_fin  text := nullif(lower(btrim(coalesce(a->>'finance_email', ''))), '');
  v_sal  text := nullif(btrim(coalesce(a->>'contact_salutation', '')), '');
  v_cn   text := btrim(regexp_replace(coalesce(a->>'contact_name', ''), '\s+', ' ', 'g'));
  v_cp   text := btrim(coalesce(a->>'contact_phone', ''));
  v_ce   text := lower(btrim(coalesce(a->>'contact_email', '')));
begin
  if coalesce(p_key, '') !~ '^[a-z0-9]{8}$' then return jsonb_build_object('error', 'not_found'); end if;
  select * into v_f from public.client_detail_forms f where f.access_key = p_key and f.voided_at is null for update;
  if v_f.id is null then return jsonb_build_object('error', 'not_found'); end if;
  if v_f.submitted_at is not null then return jsonb_build_object('error', 'submitted'); end if;
  if v_f.expires_at <= now() then return jsonb_build_object('error', 'expired'); end if;
  if exists (select 1 from public.clients c where c.id = v_f.client_id and c.stage = 'past') then
    return jsonb_build_object('error', 'not_found');
  end if;
  if length(v_name) < 2 or length(v_name) > 160 then return jsonb_build_object('error', 'bad-legal_name'); end if;
  if v_brn !~ '^[A-Z0-9-]{6,20}$' then return jsonb_build_object('error', 'bad-company_no'); end if;
  if v_old is not null and v_old !~ '^[A-Z0-9-]{4,20}$' then return jsonb_build_object('error', 'bad-company_no_old'); end if;
  if v_tin is not null and v_tin !~ '^[A-Z0-9-]{6,20}$' then return jsonb_build_object('error', 'bad-tin'); end if;
  if v_sst is not null and v_sst !~ '^[A-Z0-9-]{6,25}$' then return jsonb_build_object('error', 'bad-sst_no'); end if;
  if length(v_addr) < 10 or length(v_addr) > 400 then return jsonb_build_object('error', 'bad-billing_address'); end if;
  if v_fin is not null and (v_fin !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' or length(v_fin) > 160) then
    return jsonb_build_object('error', 'bad-finance_email');
  end if;
  if v_sal is not null and v_sal not in ('Mr', 'Ms', 'Mrs', 'Mdm', 'Dr', 'Prof', 'Dato''', 'Datin', 'Datuk',
      'Dato'' Sri', 'Datin Sri', 'Tan Sri', 'Puan Sri', 'Tun', 'Tuan', 'Puan', 'Encik', 'Cik') then
    return jsonb_build_object('error', 'bad-contact_salutation');
  end if;
  if length(v_cn) < 2 or length(v_cn) > 80 then return jsonb_build_object('error', 'bad-contact_name'); end if;
  t := regexp_replace(v_cp, '[^0-9]', '', 'g');
  if length(t) < 8 or length(t) > 15 or length(v_cp) > 30 then return jsonb_build_object('error', 'bad-contact_phone'); end if;
  if v_ce !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' or length(v_ce) > 160 then return jsonb_build_object('error', 'bad-contact_email'); end if;

  update public.client_detail_forms f
     set submitted_at = now(),
         answers = jsonb_strip_nulls(jsonb_build_object(
           'legal_name', v_name, 'company_no', v_brn, 'company_no_old', v_old, 'tin', v_tin, 'sst_no', v_sst,
           'billing_address', v_addr, 'finance_email', v_fin, 'contact_salutation', v_sal,
           'contact_name', v_cn, 'contact_phone', v_cp, 'contact_email', v_ce))
   where f.id = v_f.id;
  select * into v_cl from public.clients c where c.id = v_f.client_id;
  insert into public.activity_log (actor, action, subject, detail)
  values ('Details form', 'client.edited', v_cl.name,
          'Billing details received on the details form from ' || coalesce(v_sal || ' ', '') || v_cn);
  insert into public.ops_notifications (team_member_id, kind, title, body, client_id, dedupe_key)
  select m.id, 'client.details', 'Billing details received · ' || v_cl.name,
         'From ' || coalesce(v_sal || ' ', '') || v_cn || '. Review them on the client''s Billing.',
         v_cl.id, 'client.details:' || v_f.id || ':' || m.id
    from public.team_members m
   where m.active
     and (m.is_admin or m.role = 'admin'
          or (public.level_rank(coalesce(m.access ->> 'clients.billing', m.access ->> 'clients')) >= 2
              -- held to the colleague's own client scope, as client_row_seen holds a reader (audit S7)
              and (v_cl.stage not in ('lead', 'contacted', 'proposal', 'past')
                   or public.level_rank(coalesce(m.access ->> case when v_cl.stage = 'past' then 'clients.past' else 'clients.leads' end,
                                                 m.access ->> 'clients')) >= 1)
              and (coalesce(m.client_scope, 'all') <> 'own'
                   or (nullif(btrim(coalesce(v_cl.owner, '')), '') is null and v_cl.stage in ('lead', 'contacted', 'proposal'))
                   or lower(btrim(coalesce(v_cl.owner, ''))) = lower(btrim(coalesce(m.name, ''))))))
  on conflict (dedupe_key) do nothing;
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.client_details_submit(text, jsonb) from public;
grant execute on function public.client_details_submit(text, jsonb) to anon, authenticated;

create or replace function public.supplier_form_submit(p_key text, p_answers jsonb)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  f public.supplier_forms;
  s public.suppliers;
  v jsonb;
  a jsonb := coalesce(p_answers, '{}'::jsonb);
begin
  if coalesce(p_key, '') !~ '^[a-z0-9]{8}$' then return jsonb_build_object('error', 'not_found'); end if;
  select * into f from public.supplier_forms x where x.access_key = p_key and x.voided_at is null for update;
  if f.id is null then return jsonb_build_object('error', 'not_found'); end if;
  if f.submitted_at is not null then return jsonb_build_object('error', 'submitted'); end if;
  if f.expires_at <= now() then return jsonb_build_object('error', 'expired'); end if;
  if coalesce(a->>'authorise', '') <> 'true' then return jsonb_build_object('error', 'bad-authorise'); end if;
  select * into s from public.suppliers x where x.id = f.supplier_id;
  /* An update keeps the NRIC and the bank details held where left blank. */
  if f.purpose = 'update' then
    if btrim(coalesce(a->>'bank_account', '')) = '' and s.bank_account is not null then
      a := a || jsonb_build_object('payee_name', s.payee_name, 'bank_name', s.bank_name, 'bank_account', s.bank_account,
                                   'swift', s.swift, 'bank_address', s.bank_address);
    end if;
    if btrim(coalesce(a->>'nric', '')) = '' and s.nric is not null then
      a := a || jsonb_build_object('nric', s.nric);
    end if;
  end if;
  v := public.supplier_values_check(a, true);
  if v ? 'error' then return v; end if;
  update public.supplier_forms x set submitted_at = now(), answers = jsonb_strip_nulls(v) where x.id = f.id;
  insert into public.activity_log (actor, action, subject, detail)
  values ('Supplier form', 'supplier.edited', coalesce(s.name, v->>'name'), s.code || ' · ' ||
          case when f.purpose = 'update' then 'Details update received on the update link' else 'Details received on the details form' end ||
          coalesce(' from ' || nullif(btrim(v->>'contact_name'), ''), ''));
  insert into public.ops_notifications (team_member_id, kind, title, body, supplier_id, dedupe_key)
  select m.id, 'supplier.details',
         case when f.purpose = 'update' then 'Supplier details update received · ' else 'Supplier details received · ' end || coalesce(s.name, v->>'name'),
         'From ' || (v->>'contact_name') || '. Review them on the supplier.',
         s.id, 'supplier.details:' || f.id || ':' || m.id
    from public.team_members m
   where m.active
     and (m.is_admin or m.role = 'admin'
          or public.level_rank(m.access ->> 'suppliers') >= 2)
  on conflict (dedupe_key) do nothing;
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.supplier_form_submit(text, jsonb) from public;
grant execute on function public.supplier_form_submit(text, jsonb) to anon, authenticated;

create or replace function public.abroad_request(p_reason text, p_until date)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  t public.team_members := public.abroad_who();
  v_today date := (now() at time zone 'Asia/Kuala_Lumpur')::date;
  v_days int := coalesce(public.app_setting('abroad_days', (now() at time zone 'Asia/Kuala_Lumpur')::date), 14)::int;
  v_reason text := btrim(regexp_replace(coalesce(p_reason, ''), '\s+', ' ', 'g'));
  v_country text := public.request_country();
  v_id uuid;
begin
  if t.id is null then return jsonb_build_object('error', 'denied'); end if;
  if t.is_admin or t.role = 'admin' then return jsonb_build_object('error', 'admin'); end if;
  if char_length(v_reason) < 3 or char_length(v_reason) > 300 then return jsonb_build_object('error', 'bad-reason'); end if;
  if p_until is null or p_until < v_today or p_until > v_today + v_days then
    return jsonb_build_object('error', 'bad-until', 'max', v_today + v_days);
  end if;
  select x.id into v_id from public.team_abroad x
   where x.team_member_id = t.id and x.status = 'waiting' order by x.asked_at desc limit 1 for update;
  if v_id is null then
    insert into public.team_abroad (team_member_id, country, reason, until)
    values (t.id, v_country, v_reason, p_until) returning id into v_id;
  else
    update public.team_abroad set country = v_country, reason = v_reason, until = p_until, asked_at = now(), reminded_at = null
     where id = v_id;
  end if;
  insert into public.ops_notifications (team_member_id, kind, title, body, dedupe_key)
  select m.id, 'abroad.request', 'Overseas access requested · ' || t.name,
         case when v_country <> '' then 'From ' || v_country || ' · ' else '' end ||
         'until ' || public.register_day(p_until) || ' · ' || v_reason,
         'abroad:' || v_id || ':' || m.id || ':' || to_char(now() at time zone 'Asia/Kuala_Lumpur', 'YYYYMMDDHH24MI')
    from public.team_members m
   where m.active and (m.is_admin or m.role = 'admin')
  on conflict (dedupe_key) do nothing;
  return public.abroad_state();
end $$;
revoke all on function public.abroad_request(text, date) from public, anon;
grant execute on function public.abroad_request(text, date) to authenticated;

create or replace function public.abroad_remind()
returns int
language plpgsql security definer set search_path = public as $$
declare
  v_hours numeric := coalesce(public.app_setting('abroad_remind_hours', (now() at time zone 'Asia/Kuala_Lumpur')::date), 2);
  v_today date := (now() at time zone 'Asia/Kuala_Lumpur')::date;
  v_n int := 0;
  r record;
begin
  if v_hours <= 0 then return 0; end if;
  for r in
    select x.id, x.country, x.reason, x.until, t.name
      from public.team_abroad x join public.team_members t on t.id = x.team_member_id
     where x.status = 'waiting' and t.active and x.until >= v_today
       and greatest(x.asked_at, coalesce(x.reminded_at, x.asked_at)) <= now() - make_interval(mins => (v_hours * 60)::int)
     order by x.asked_at
     for update of x skip locked
  loop
    update public.team_abroad set reminded_at = now() where id = r.id;
    insert into public.ops_notifications (team_member_id, kind, title, body, dedupe_key)
    select m.id, 'abroad.request', 'Overseas access waiting · ' || r.name,
           case when r.country <> '' then 'From ' || r.country || ' · ' else '' end ||
           'until ' || public.register_day(r.until) || ' · ' || r.reason,
           'abroad:' || r.id || ':remind:' || m.id || ':' || to_char(now() at time zone 'Asia/Kuala_Lumpur', 'YYYYMMDDHH24MI')
      from public.team_members m
     where m.active and (m.is_admin or m.role = 'admin')
    on conflict (dedupe_key) do nothing;
    v_n := v_n + 1;
  end loop;
  return v_n;
end $$;
revoke all on function public.abroad_remind() from public, anon, authenticated;

do $$
begin
  if not exists (select 1 from pg_extension where extname = 'pg_cron') then
    raise notice 'pg_cron is not enabled: no overseas reminders go out until it is.';
    return;
  end if;
  perform cron.unschedule(j.jobid) from cron.job j where j.jobname = 'abroad-remind';
  perform cron.schedule('abroad-remind', '*/15 0-14 * * *', 'select public.abroad_remind()');
end $$;

-- END OF ADMIN NOTICES REACH THE SYSTEM ACCOUNT ------------------------------

-- ===========================================================================
-- OVERSEAS REMINDER SETTING — how often a waiting overseas request reminds
-- the admins is a Business setting like any other (2026-10-24)
-- ===========================================================================
-- WHY (the user, 2026-10-24: a request waited with nothing to bring it
-- back): the hours between reminders are the team's to change, from a day
-- on, through the one sheet every setting uses.
--
-- WHAT IT CHANGES
--   * `app_settings_set` takes `abroad_remind_hours` (0 to 24 whole hours,
--     0 sends none), filed as Overseas reminder, from and to. Nothing else
--     moves.
--
-- ORDER: after ADMIN NOTICES REACH THE SYSTEM ACCOUNT, in the SQL Editor
-- (the function holds a delete, which the connector holds back). Safe to
-- run twice. Rollback: run app_settings_set from OVERSEAS APPROVAL DAYS
-- again.
-- ===========================================================================

create or replace function public.app_settings_set(p_from date, p_values jsonb)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me public.team_members; v_k text; v_v numeric; v_was numeric; v_name text; v_unit text; v_pre text;
  v_today date := (now() at time zone 'Asia/Kuala_Lumpur')::date;
  v_keys constant text[] := array['lead_followup_hours', 'proposal_followup_days', 'sst_pct',
    'term_1_3', 'term_4_5', 'term_6_11', 'term_12_23', 'term_18_23', 'term_24', 'report_due_days', 'revision_due_days',
    'ai_price_in', 'ai_price_out', 'meta_checks', 'approval_reminder_days', 'ai_price_search',
    'reach_allowance_pct', 'priority_urgent_hours', 'priority_high_hours', 'priority_medium_hours',
    'task_remind_hours', 'task_start_days', 'quote_valid_days', 'details_form_days', 'wa_repeat_hours',
    'bench_cpr_low', 'bench_cpr_mid', 'bench_cpr_high', 'bench_cpr_top', 'bench_msg_min', 'bench_msg_target', 'bench_msg_max',
    'bench_form_min', 'bench_form_target', 'bench_form_max', 'bench_cpm_min', 'bench_cpm_max', 'bench_cpl_rise',
    'bench_reels_share', 'bench_ad_spend_pct', 'bench_adset_daily', 'vic_lead_followup_hours', 'vic_proposal_followup_days', 'fx_sgd',
    'health_keep_months', 'health_leaver_months', 'abroad_days', 'abroad_remind_hours'];
  v_moved text[] := '{}';
  v_drop boolean; v_fw text; v_fv text;
begin
  if not public.ops_granted('team.settings', 'work') then return jsonb_build_object('error', 'denied'); end if;
  v_me := public.ops_me();
  if p_from is null or p_from < v_today then return jsonb_build_object('error', 'past', 'today', v_today); end if;
  if jsonb_typeof(p_values) is distinct from 'object' then return jsonb_build_object('error', 'bad-value'); end if;
  for v_k in select jsonb_object_keys(p_values) loop
    if not (v_k = any(v_keys)) or jsonb_typeof(p_values -> v_k) <> 'number' then
      return jsonb_build_object('error', 'bad-value', 'key', v_k);
    end if;
    v_v := (p_values ->> v_k)::numeric;
    if round(v_v, case when v_k = 'fx_sgd' then 4 else 2 end) <> v_v
       or (v_k = 'fx_sgd' and (v_v < 0.5 or v_v > 10))
       or (v_k in ('lead_followup_hours', 'vic_lead_followup_hours') and (v_v < 1 or v_v > 720 or v_v <> trunc(v_v)))
       or (v_k in ('proposal_followup_days', 'vic_proposal_followup_days') and (v_v < 1 or v_v > 365 or v_v <> trunc(v_v)))
       or (v_k = 'report_due_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'revision_due_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'approval_reminder_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'sst_pct' and (v_v < 0 or v_v > 100))
       or (v_k like 'term_%' and (v_v < -100 or v_v > 100))
       or (v_k like 'ai_price_%' and (v_v < 0 or v_v > 1000))
       or (v_k = 'meta_checks' and v_v not in (0, 1))
       or (v_k = 'reach_allowance_pct' and (v_v < 0 or v_v > 5))
       or (v_k like 'priority_%_hours' and (v_v < 1 or v_v > 720 or v_v <> trunc(v_v)))
       or (v_k = 'task_remind_hours' and (v_v < 0 or v_v > 24 or v_v <> trunc(v_v)))
       or (v_k = 'task_start_days' and (v_v < 0 or v_v > 30 or v_v <> trunc(v_v)))
       or (v_k in ('quote_valid_days', 'details_form_days') and (v_v < 1 or v_v > 90 or v_v <> trunc(v_v)))
       or (v_k = 'wa_repeat_hours' and (v_v < 0 or v_v > 168 or v_v <> trunc(v_v)))
       or (v_k = 'health_keep_months' and (v_v < 6 or v_v > 120 or v_v <> trunc(v_v)))
       or (v_k = 'health_leaver_months' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'abroad_days' and (v_v < 1 or v_v > 30 or v_v <> trunc(v_v)))
       or (v_k = 'abroad_remind_hours' and (v_v < 0 or v_v > 24 or v_v <> trunc(v_v)))
       or (v_k in ('bench_reels_share') and (v_v < 0 or v_v > 100))
       or (v_k = 'bench_ad_spend_pct' and (v_v < 1 or v_v > 100))
       or (v_k = 'bench_cpl_rise' and (v_v < -100 or v_v > 100))
       or (v_k like 'bench_%' and v_k not in ('bench_reels_share', 'bench_ad_spend_pct', 'bench_cpl_rise') and (v_v < 0 or v_v > 10000)) then
      return jsonb_build_object('error', 'bad-value', 'key', v_k);
    end if;
  end loop;
  for v_k in select jsonb_object_keys(p_values) loop
    v_v := (p_values ->> v_k)::numeric;
    v_was := public.app_setting(v_k, p_from);
    if v_was is distinct from v_v then
      /* A planned change saved back to the value in force the day before is
         withdrawn: its row goes, rather than a second row restating it. */
      v_drop := p_from > v_today
        and exists (select 1 from public.app_settings s where s.key = v_k and s.from_date = p_from)
        and exists (select 1 from public.app_settings s where s.key = v_k and s.from_date < p_from)
        and public.app_setting(v_k, p_from - 1) = v_v;
      if v_drop then
        delete from public.app_settings s where s.key = v_k and s.from_date = p_from;
      else
        insert into public.app_settings (key, from_date, value, set_by, set_at)
        values (v_k, p_from, v_v, v_me.id, now())
        on conflict (key, from_date) do update set value = excluded.value, set_by = excluded.set_by, set_at = now();
      end if;
      v_name := case v_k when 'lead_followup_hours' then 'A lead waits' when 'proposal_followup_days' then 'A proposal waits'
        when 'vic_lead_followup_hours' then 'A VIC lead waits' when 'vic_proposal_followup_days' then 'A VIC proposal waits'
        when 'sst_pct' then 'SST' when 'term_1_3' then '1 to 3 months' when 'term_4_5' then '4 and 5 months'
        when 'term_6_11' then '6 to 11 months' when 'term_12_23' then '12 to 17 months' when 'term_18_23' then '18 to 23 months' when 'term_24' then '24 months and more'
        when 'revision_due_days' then 'Revision due' when 'ai_price_in' then 'AI input, a million tokens'
        when 'ai_price_out' then 'AI output, a million tokens' when 'ai_price_search' then 'AI web searches, a thousand' when 'meta_checks' then 'Meta checks'
        when 'approval_reminder_days' then 'Approval reminder' when 'reach_allowance_pct' then 'Reach allowance'
        when 'priority_urgent_hours' then 'Urgent deadline' when 'priority_high_hours' then 'High deadline'
        when 'priority_medium_hours' then 'Medium deadline' when 'task_remind_hours' then 'Task reminders'
        when 'task_start_days' then 'Not started reminder' when 'quote_valid_days' then 'Quotation validity' when 'details_form_days' then 'Details form open'
        when 'wa_repeat_hours' then 'WhatsApp sent again'
        when 'bench_cpr_low' then 'Property cost per result, tier 1 from' when 'bench_cpr_mid' then 'Property cost per result, tier 2 from'
        when 'bench_cpr_high' then 'Property cost per result, tier 3 from' when 'bench_cpr_top' then 'Property cost per result, tier 3 up to'
        when 'bench_msg_min' then 'Messaging cost per result, low' when 'bench_msg_target' then 'Messaging cost per result, target'
        when 'bench_msg_max' then 'Messaging cost per result, high' when 'bench_form_min' then 'Lead form cost per result, low'
        when 'bench_form_target' then 'Lead form cost per result, target' when 'bench_form_max' then 'Lead form cost per result, high'
        when 'bench_cpm_min' then 'Cost per 1,000 impressions, low' when 'bench_cpm_max' then 'Cost per 1,000 impressions, high'
        when 'bench_cpl_rise' then 'Cost per lead rise a year' when 'bench_reels_share' then 'Reels share of impressions'
        when 'bench_ad_spend_pct' then 'Ad spend of the budget' when 'bench_adset_daily' then 'Daily budget an ad set, at least'
        when 'fx_sgd' then 'Singapore dollar rate'
        when 'health_keep_months' then 'Health check-ins kept' when 'health_leaver_months' then 'A leaver''s health data kept'
        when 'abroad_days' then 'Overseas approval' when 'abroad_remind_hours' then 'Overseas reminder'
        else 'Report due' end;
      v_pre := case when v_k = 'fx_sgd' then 'RM ' when v_k like 'ai_price_%' then 'US$' when v_k like 'bench_%' and v_k not in ('bench_cpl_rise', 'bench_reels_share', 'bench_ad_spend_pct') then 'RM ' else '' end;
      v_unit := case when v_k = 'fx_sgd' then ' to S$1' when v_k in ('lead_followup_hours', 'vic_lead_followup_hours', 'task_remind_hours', 'wa_repeat_hours', 'abroad_remind_hours') or v_k like 'priority_%_hours' then ' hours'
        when v_k in ('proposal_followup_days', 'vic_proposal_followup_days', 'report_due_days', 'revision_due_days', 'approval_reminder_days', 'task_start_days', 'quote_valid_days', 'details_form_days', 'abroad_days') then ' days'
        when v_k in ('health_keep_months', 'health_leaver_months') then ' months'
        when v_pre <> '' then '' else '%' end;
      v_fw := case when v_k = 'meta_checks' then case when v_was = 1 then 'On' else 'Off' end else coalesce(v_pre ||
              trim(to_char(v_was, case when v_k = 'fx_sgd' then 'FM999999990.9999' else 'FM999999990.99' end), '.') || v_unit, 'not set') end;
      v_fv := case when v_k = 'meta_checks' then case when v_v = 1 then 'On' else 'Off' end else v_pre ||
              trim(to_char(v_v, case when v_k = 'fx_sgd' then 'FM999999990.9999' else 'FM999999990.99' end), '.') || v_unit end;
      insert into public.activity_log (actor, action, subject, detail)
      values (coalesce(v_me.name, 'admin'), 'team.changed', 'Settings',
              case when v_drop then v_name || ': planned change withdrawn · ' || v_fw || ' from ' || public.register_day(p_from) ||
                ', stays ' || v_fv else
              v_name || ': ' || case when v_k = 'meta_checks' then
                case when v_was = 1 then 'On' else 'Off' end || ' → ' || case when v_v = 1 then 'On' else 'Off' end ||
                ' · from ' || public.register_day(p_from) else '' end ||
              case when v_k = 'meta_checks' then '' else coalesce(v_pre ||
              trim(to_char(v_was, case when v_k = 'fx_sgd' then 'FM999999990.9999' else 'FM999999990.99' end), '.') || v_unit, 'not set') || ' → ' || v_pre ||
              trim(to_char(v_v, case when v_k = 'fx_sgd' then 'FM999999990.9999' else 'FM999999990.99' end), '.') || v_unit ||
              ' · from ' || public.register_day(p_from) end end);
      v_moved := v_moved || v_k;
    end if;
  end loop;
  return public.app_settings_read() || jsonb_build_object('changed', to_jsonb(v_moved));
end $$;
revoke all on function public.app_settings_set(date, jsonb) from public, anon;
grant execute on function public.app_settings_set(date, jsonb) to authenticated;

-- END OF OVERSEAS REMINDER SETTING ------------------------------------------

-- ===========================================================================
-- PURCHASE VALUE AND ROAS — an ad's purchase value, as Meta reports it, so
-- an Advertising Report reads its Sales ads' return on ad spend. 2026-10-25.
-- Safe to run twice. Rollback at the foot. Mirrored byte for byte in
-- supabase/schema.sql under the same banner; tests/smsql.js compares the two.
--
-- WHY (the user, 2026-10-25, of Roro's September report: "does it show and
-- include the roas data and commentary?"): a Sales ad held its purchases and
-- its cost per purchase, never what the purchases were worth, so no return
-- could be read.
--
-- WHAT CHANGED
--   1. `sm_report_ads.purchase_value`: the value of the purchases Meta
--      attributes to the ad over the period, in the account's currency; 0 or
--      more, empty where not given. Written by the page on a draft, as every
--      other figure of the row (the draft guard and the policies hold it).
--      ROAS is worked out from it (purchase value over amount spent), never
--      stored. The snapshot carries it, so a published version prints as it
--      was published; one published before holds none and prints none.
--   2. `sm_report_meta_print` takes it into the figures' print where a row
--      holds one, so a value changed after a match holds the report again,
--      and a report holding none keeps the print it had (no match undone).
--
-- ROLLBACK
--   alter table public.sm_report_ads drop constraint if exists sm_report_ads_purchase_value_chk;
--   alter table public.sm_report_ads drop column if exists purchase_value;
--   then run sm_report_meta_print from REPORT AUDIT again.
-- ===========================================================================

alter table public.sm_report_ads add column if not exists purchase_value numeric(14,2);
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'sm_report_ads_purchase_value_chk') then
    alter table public.sm_report_ads add constraint sm_report_ads_purchase_value_chk
      check (purchase_value is null or purchase_value >= 0);
  end if;
end $$;

create or replace function public.sm_report_meta_print(p_id uuid)
returns text
language sql stable security definer set search_path = public as $$
  select md5(case when r.kind = 'ads' then
      coalesce((select string_agg((jsonb_build_array(a.id, a.result_label, a.results, a.reach, a.impressions, a.spend,
                  a.ctr, a.cpr, a.hook_rate, a.hold_rate, a.avg_play, a.retention, a.age, a.ad_ids)
                  || case when a.purchase_value is null then '[]'::jsonb else jsonb_build_array(a.purchase_value) end)::text,
                  ';' order by a.id)
                  from public.sm_report_ads a
                 where a.report_id = r.id and coalesce(a.platform, 'meta') = 'meta'), '')
      || '#' || jsonb_build_object('reach', r.ads_totals -> 'reach', 'impressions', r.ads_totals -> 'impressions',
                                   'spend', r.ads_totals -> 'spend')::text
    else
      coalesce((select string_agg(jsonb_build_array(p.id, p.url, p.views, p.reach, p.impressions, p.interactions,
                  p.engagements, p.likes, p.comments, p.shares, p.saves)::text, ';' order by p.id)
                  from public.sm_report_posts p
                  join public.sm_report_platforms f on f.id = p.platform_id
                 where p.report_id = r.id and f.platform in ('facebook', 'instagram')), '')
    end)
  from public.sm_reports r where r.id = p_id
$$;
revoke all on function public.sm_report_meta_print(uuid) from public, anon, authenticated;

-- END OF PURCHASE VALUE AND ROAS ---------------------------------------------

-- ===========================================================================
-- ANALYTICS IS AN ADMIN TOOL — the granted part team.analytics joins the
-- admin tools only an admin turns on (2026-10-25)
-- ===========================================================================
-- WHY (the user, 2026-10-25: an internal Analytics section of trends and
-- forecasts, "Admins only (Recommended)")
--   Analytics is a granted part, `team.analytics`, an admin's by itself and
--   any other group's only once an admin gives it. The page alone asks it
--   (every figure it draws is read under the sections' own policies), so the
--   database's part is that nobody but an admin gives it.
--
-- WHAT CHANGED
--   * `team_roles_admin_guard` holds `team.analytics` with the other granted
--     parts: a signed-in caller who is not an admin cannot turn it on,
--     change it or take it off on any group (`admin-only`).
--
-- ORDER
--   The page (which offers the switch to an admin alone), then this file.
--   Until it runs, a non-admin at Team Full Access could give a group
--   Analytics, which reads nothing the group's sections do not already open.
--
-- Safe to run twice. Rollback: run ADMIN TOOLS ARE AN ADMIN'S
-- (2026-10-24-admin-tools-admins-only.sql) again.
-- ===========================================================================

create or replace function public.team_roles_admin_guard()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  who text := lower(coalesce(auth.jwt() ->> 'email', ''));
  v_granted constant text[] := array['ops.all', 'ops.reports', 'ops.workflows', 'ops.time', 'ops.numbering',
    'ops.override', 'team.performance', 'team.perfadmin', 'team.settings', 'team.upgrade', 'team.invite',
    'team.handbook', 'team.announce', 'team.notice', 'reports.whitelabel', 'reports.transfer', 'reports.ai',
    'reports.meta', 'register.types', 'campaigns.files_delete', 'clients.vic', 'suppliers.pay',
    'team.analytics'];
  k text;
begin
  if who = '' or pg_trigger_depth() > 1 or public.allowed('admin') then
    if tg_op = 'DELETE' then return old; end if;
    return new;
  end if;
  if (tg_op <> 'INSERT' and (coalesce(old.is_admin, false) or old.slug = 'admin'))
     or (tg_op <> 'DELETE' and (coalesce(new.is_admin, false) or new.slug = 'admin')) then
    raise exception 'admin-only' using errcode = '42501', hint = 'Only an admin changes an admin group.';
  end if;
  if tg_op = 'DELETE' then return old; end if;
  foreach k in array v_granted loop
    if coalesce(new.access ->> k, '') is distinct from
       (case when tg_op = 'INSERT' then '' else coalesce(old.access ->> k, '') end) then
      raise exception 'admin-only' using errcode = '42501', hint = 'Only an admin changes an admin tool.';
    end if;
  end loop;
  return new;
end $$;
revoke all on function public.team_roles_admin_guard() from public, anon, authenticated;

-- END OF ANALYTICS IS AN ADMIN TOOL ----------------------------------------

-- ===========================================================================
-- ANALYTICS COUNTS FROM — the month Analytics counts leads and clients from
-- is a Business setting (2026-10-25)
-- ===========================================================================
-- WHY (the user, 2026-10-25, the Analytics review, finding 1): before the
-- portal the team typed in only the clients it won, each with its Client
-- since date, never the leads that came to nothing. Counted from the oldest
-- of those dates (Oct 2023), Analytics read 36 full months, drew a forecast
-- and named the busiest months from about one lead a calendar month.
--
-- WHAT IT CHANGES
--   * `analytics_from` (YYYYMM, Aug 2023 to Dec 2099, a real month), seeded
--     202609 from the start: the month leads were first kept in the portal.
--     The page counts full months, the forecast and the busiest months only
--     from it (js/analytics.js `countsFrom`).
--   * `app_settings_set` takes it, filed as Analytics counts from, the
--     months in words (Sept 2026 → Oct 2026), from a day. Nothing else
--     moves.
--
-- ORDER: the page first (it reads Sept 2026 where the setting is missing),
-- then this file in the SQL Editor (the function holds a delete, which the
-- connector holds back). Safe to run twice. Rollback: run app_settings_set
-- from OVERSEAS REMINDER SETTING again; the setting's row may stay.
-- ===========================================================================

insert into public.app_settings (key, from_date, value)
select 'analytics_from', date '2023-08-14', 202609
 where not exists (select 1 from public.app_settings s where s.key = 'analytics_from');

create or replace function public.app_settings_set(p_from date, p_values jsonb)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me public.team_members; v_k text; v_v numeric; v_was numeric; v_name text; v_unit text; v_pre text;
  v_today date := (now() at time zone 'Asia/Kuala_Lumpur')::date;
  v_keys constant text[] := array['lead_followup_hours', 'proposal_followup_days', 'sst_pct',
    'term_1_3', 'term_4_5', 'term_6_11', 'term_12_23', 'term_18_23', 'term_24', 'report_due_days', 'revision_due_days',
    'ai_price_in', 'ai_price_out', 'meta_checks', 'approval_reminder_days', 'ai_price_search',
    'reach_allowance_pct', 'priority_urgent_hours', 'priority_high_hours', 'priority_medium_hours',
    'task_remind_hours', 'task_start_days', 'quote_valid_days', 'details_form_days', 'wa_repeat_hours',
    'bench_cpr_low', 'bench_cpr_mid', 'bench_cpr_high', 'bench_cpr_top', 'bench_msg_min', 'bench_msg_target', 'bench_msg_max',
    'bench_form_min', 'bench_form_target', 'bench_form_max', 'bench_cpm_min', 'bench_cpm_max', 'bench_cpl_rise',
    'bench_reels_share', 'bench_ad_spend_pct', 'bench_adset_daily', 'vic_lead_followup_hours', 'vic_proposal_followup_days', 'fx_sgd',
    'health_keep_months', 'health_leaver_months', 'abroad_days', 'abroad_remind_hours', 'analytics_from'];
  v_moved text[] := '{}';
  v_drop boolean; v_fw text; v_fv text;
begin
  if not public.ops_granted('team.settings', 'work') then return jsonb_build_object('error', 'denied'); end if;
  v_me := public.ops_me();
  if p_from is null or p_from < v_today then return jsonb_build_object('error', 'past', 'today', v_today); end if;
  if jsonb_typeof(p_values) is distinct from 'object' then return jsonb_build_object('error', 'bad-value'); end if;
  for v_k in select jsonb_object_keys(p_values) loop
    if not (v_k = any(v_keys)) or jsonb_typeof(p_values -> v_k) <> 'number' then
      return jsonb_build_object('error', 'bad-value', 'key', v_k);
    end if;
    v_v := (p_values ->> v_k)::numeric;
    if round(v_v, case when v_k = 'fx_sgd' then 4 else 2 end) <> v_v
       or (v_k = 'fx_sgd' and (v_v < 0.5 or v_v > 10))
       or (v_k in ('lead_followup_hours', 'vic_lead_followup_hours') and (v_v < 1 or v_v > 720 or v_v <> trunc(v_v)))
       or (v_k in ('proposal_followup_days', 'vic_proposal_followup_days') and (v_v < 1 or v_v > 365 or v_v <> trunc(v_v)))
       or (v_k = 'report_due_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'revision_due_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'approval_reminder_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'sst_pct' and (v_v < 0 or v_v > 100))
       or (v_k like 'term_%' and (v_v < -100 or v_v > 100))
       or (v_k like 'ai_price_%' and (v_v < 0 or v_v > 1000))
       or (v_k = 'meta_checks' and v_v not in (0, 1))
       or (v_k = 'reach_allowance_pct' and (v_v < 0 or v_v > 5))
       or (v_k like 'priority_%_hours' and (v_v < 1 or v_v > 720 or v_v <> trunc(v_v)))
       or (v_k = 'task_remind_hours' and (v_v < 0 or v_v > 24 or v_v <> trunc(v_v)))
       or (v_k = 'task_start_days' and (v_v < 0 or v_v > 30 or v_v <> trunc(v_v)))
       or (v_k in ('quote_valid_days', 'details_form_days') and (v_v < 1 or v_v > 90 or v_v <> trunc(v_v)))
       or (v_k = 'wa_repeat_hours' and (v_v < 0 or v_v > 168 or v_v <> trunc(v_v)))
       or (v_k = 'health_keep_months' and (v_v < 6 or v_v > 120 or v_v <> trunc(v_v)))
       or (v_k = 'health_leaver_months' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'abroad_days' and (v_v < 1 or v_v > 30 or v_v <> trunc(v_v)))
       or (v_k = 'abroad_remind_hours' and (v_v < 0 or v_v > 24 or v_v <> trunc(v_v)))
       or (v_k = 'analytics_from' and (v_v < 202308 or v_v > 209912 or v_v <> trunc(v_v) or mod(v_v, 100) not between 1 and 12))
       or (v_k in ('bench_reels_share') and (v_v < 0 or v_v > 100))
       or (v_k = 'bench_ad_spend_pct' and (v_v < 1 or v_v > 100))
       or (v_k = 'bench_cpl_rise' and (v_v < -100 or v_v > 100))
       or (v_k like 'bench_%' and v_k not in ('bench_reels_share', 'bench_ad_spend_pct', 'bench_cpl_rise') and (v_v < 0 or v_v > 10000)) then
      return jsonb_build_object('error', 'bad-value', 'key', v_k);
    end if;
  end loop;
  for v_k in select jsonb_object_keys(p_values) loop
    v_v := (p_values ->> v_k)::numeric;
    v_was := public.app_setting(v_k, p_from);
    if v_was is distinct from v_v then
      /* A planned change saved back to the value in force the day before is
         withdrawn: its row goes, rather than a second row restating it. */
      v_drop := p_from > v_today
        and exists (select 1 from public.app_settings s where s.key = v_k and s.from_date = p_from)
        and exists (select 1 from public.app_settings s where s.key = v_k and s.from_date < p_from)
        and public.app_setting(v_k, p_from - 1) = v_v;
      if v_drop then
        delete from public.app_settings s where s.key = v_k and s.from_date = p_from;
      else
        insert into public.app_settings (key, from_date, value, set_by, set_at)
        values (v_k, p_from, v_v, v_me.id, now())
        on conflict (key, from_date) do update set value = excluded.value, set_by = excluded.set_by, set_at = now();
      end if;
      v_name := case v_k when 'lead_followup_hours' then 'A lead waits' when 'proposal_followup_days' then 'A proposal waits'
        when 'vic_lead_followup_hours' then 'A VIC lead waits' when 'vic_proposal_followup_days' then 'A VIC proposal waits'
        when 'sst_pct' then 'SST' when 'term_1_3' then '1 to 3 months' when 'term_4_5' then '4 and 5 months'
        when 'term_6_11' then '6 to 11 months' when 'term_12_23' then '12 to 17 months' when 'term_18_23' then '18 to 23 months' when 'term_24' then '24 months and more'
        when 'revision_due_days' then 'Revision due' when 'ai_price_in' then 'AI input, a million tokens'
        when 'ai_price_out' then 'AI output, a million tokens' when 'ai_price_search' then 'AI web searches, a thousand' when 'meta_checks' then 'Meta checks'
        when 'approval_reminder_days' then 'Approval reminder' when 'reach_allowance_pct' then 'Reach allowance'
        when 'priority_urgent_hours' then 'Urgent deadline' when 'priority_high_hours' then 'High deadline'
        when 'priority_medium_hours' then 'Medium deadline' when 'task_remind_hours' then 'Task reminders'
        when 'task_start_days' then 'Not started reminder' when 'quote_valid_days' then 'Quotation validity' when 'details_form_days' then 'Details form open'
        when 'wa_repeat_hours' then 'WhatsApp sent again'
        when 'bench_cpr_low' then 'Property cost per result, tier 1 from' when 'bench_cpr_mid' then 'Property cost per result, tier 2 from'
        when 'bench_cpr_high' then 'Property cost per result, tier 3 from' when 'bench_cpr_top' then 'Property cost per result, tier 3 up to'
        when 'bench_msg_min' then 'Messaging cost per result, low' when 'bench_msg_target' then 'Messaging cost per result, target'
        when 'bench_msg_max' then 'Messaging cost per result, high' when 'bench_form_min' then 'Lead form cost per result, low'
        when 'bench_form_target' then 'Lead form cost per result, target' when 'bench_form_max' then 'Lead form cost per result, high'
        when 'bench_cpm_min' then 'Cost per 1,000 impressions, low' when 'bench_cpm_max' then 'Cost per 1,000 impressions, high'
        when 'bench_cpl_rise' then 'Cost per lead rise a year' when 'bench_reels_share' then 'Reels share of impressions'
        when 'bench_ad_spend_pct' then 'Ad spend of the budget' when 'bench_adset_daily' then 'Daily budget an ad set, at least'
        when 'fx_sgd' then 'Singapore dollar rate'
        when 'health_keep_months' then 'Health check-ins kept' when 'health_leaver_months' then 'A leaver''s health data kept'
        when 'abroad_days' then 'Overseas approval' when 'abroad_remind_hours' then 'Overseas reminder'
        when 'analytics_from' then 'Analytics counts from'
        else 'Report due' end;
      v_pre := case when v_k = 'fx_sgd' then 'RM ' when v_k like 'ai_price_%' then 'US$' when v_k like 'bench_%' and v_k not in ('bench_cpl_rise', 'bench_reels_share', 'bench_ad_spend_pct') then 'RM ' else '' end;
      v_unit := case when v_k = 'fx_sgd' then ' to S$1' when v_k in ('lead_followup_hours', 'vic_lead_followup_hours', 'task_remind_hours', 'wa_repeat_hours', 'abroad_remind_hours') or v_k like 'priority_%_hours' then ' hours'
        when v_k in ('proposal_followup_days', 'vic_proposal_followup_days', 'report_due_days', 'revision_due_days', 'approval_reminder_days', 'task_start_days', 'quote_valid_days', 'details_form_days', 'abroad_days') then ' days'
        when v_k in ('health_keep_months', 'health_leaver_months') then ' months'
        when v_pre <> '' then '' else '%' end;
      v_fw := case when v_k = 'meta_checks' then case when v_was = 1 then 'On' else 'Off' end
              when v_k = 'analytics_from' then coalesce(substr(public.register_day(to_date(v_was::bigint::text, 'YYYYMM')), 3), 'not set') else coalesce(v_pre ||
              trim(to_char(v_was, case when v_k = 'fx_sgd' then 'FM999999990.9999' else 'FM999999990.99' end), '.') || v_unit, 'not set') end;
      v_fv := case when v_k = 'meta_checks' then case when v_v = 1 then 'On' else 'Off' end
              when v_k = 'analytics_from' then substr(public.register_day(to_date(v_v::bigint::text, 'YYYYMM')), 3) else v_pre ||
              trim(to_char(v_v, case when v_k = 'fx_sgd' then 'FM999999990.9999' else 'FM999999990.99' end), '.') || v_unit end;
      insert into public.activity_log (actor, action, subject, detail)
      values (coalesce(v_me.name, 'admin'), 'team.changed', 'Settings',
              case when v_drop then v_name || ': planned change withdrawn · ' || v_fw || ' from ' || public.register_day(p_from) ||
                ', stays ' || v_fv else
              case when v_k = 'analytics_from' then v_name || ': ' || v_fw || ' → ' || v_fv || ' · from ' || public.register_day(p_from) else
              v_name || ': ' || case when v_k = 'meta_checks' then
                case when v_was = 1 then 'On' else 'Off' end || ' → ' || case when v_v = 1 then 'On' else 'Off' end ||
                ' · from ' || public.register_day(p_from) else '' end ||
              case when v_k = 'meta_checks' then '' else coalesce(v_pre ||
              trim(to_char(v_was, case when v_k = 'fx_sgd' then 'FM999999990.9999' else 'FM999999990.99' end), '.') || v_unit, 'not set') || ' → ' || v_pre ||
              trim(to_char(v_v, case when v_k = 'fx_sgd' then 'FM999999990.9999' else 'FM999999990.99' end), '.') || v_unit ||
              ' · from ' || public.register_day(p_from) end end end);
      v_moved := v_moved || v_k;
    end if;
  end loop;
  return public.app_settings_read() || jsonb_build_object('changed', to_jsonb(v_moved));
end $$;
revoke all on function public.app_settings_set(date, jsonb) from public, anon;
grant execute on function public.app_settings_set(date, jsonb) to authenticated;

-- END OF ANALYTICS COUNTS FROM ---------------------------------------------

-- ===========================================================================
-- REPORT VERSIONS RESTORED AND DELETED — an earlier version of a report is
-- made the draft again, and a version no longer on the client portal is
-- deleted (2026-10-25)
-- ===========================================================================
-- WHY (the user, 2026-10-25: a client asked for the September report again
-- with new figures; "is it still possible to call back v1", then "yes please
-- and also delete for each version"): Revise works on the report's figures
-- in place, so an earlier version lived only in its kept copy, read as a
-- PDF and never brought back.
--
-- WHAT IT CHANGES
--   * `sm_report_version_restore(p_version)` (Reports at Work, the client
--     in scope): the report's figures, accounts, posts, ads and commentary
--     are put back as that version kept them (its snapshot), as a draft; a
--     published report becomes the next version's draft as Revise makes
--     it, a draft stays its own version; a report in review or confirmed
--     is refused (`in-review`). Filed `report.revised` · Restored from
--     version n. The client portal keeps what it shows until the draft is
--     published.
--   * `sm_report_version_delete(p_version)` (Reports Full Access, the
--     client in scope): removes a version and its kept copy's row; the
--     version on the client portal (the newest not withdrawn) is refused
--     (`on-portal`): publish a newer one or unpublish first. Filed
--     `report.version_deleted`. The PDF kept in S3 stays (nothing deletes
--     from S3).
--   * `activity_section()` files `report.version_deleted` under Reports.
--
-- ORDER: this file, then the pages. A page served before it reads no
-- Restore or Delete (the functions are missing; the sheet says the
-- database needs an update). Its bodies hold `delete`, so it is run in the
-- SQL Editor. Safe to run twice. Mirrored byte for byte in
-- supabase/schema.sql under the same banner.
--
-- ROLLBACK: drop function public.sm_report_version_restore(uuid);
-- drop function public.sm_report_version_delete(uuid); run the
-- activity_section() of CREATORS OFFERED ARE FILED again.
-- ===========================================================================

create or replace function public.activity_section(p_action text)
returns text
language sql immutable parallel safe as $$
  select case
    when action in ('campaign.bulk', 'campaign.closed', 'campaign.confirmed',
                    'campaign.created', 'campaign.dates', 'campaign.deleted', 'campaign.edited',
                    'campaign.file_added', 'campaign.file_deleted', 'campaign.file_hidden',
                    'campaign.file_shown', 'campaign.qc',
                    'campaign.invoice', 'campaign.invoice_file',
                    'campaign.invoice_removed', 'campaign.keyed', 'campaign.locked',
                    'campaign.offered', 'campaign.opened', 'campaign.rate', 'campaign.rated',
                    'campaign.reinstated', 'campaign.replaced', 'campaign.results', 'campaign.review',
                    'campaign.stage', 'campaign.submitted', 'campaign.task_linked',
                    'campaign.task_unlinked', 'campaign.unbooked',
                    'campaign.unkeyed', 'campaign.unoffered', 'campaign.whatsapp', 'campaign.withdrawn', 'creator.added',
                    'creator.code', 'creator.links', 'creator.links_restored',
                    'creator.links_self', 'creator.off', 'creator.on', 'creator.removed',
                    'creator.updated') then 'campaigns'
    when action in ('client.action_done', 'client.action_reopened', 'client.added',
                    'client.billing', 'client.brand', 'client.deleted', 'client.edited',
                    'client.quotation', 'client.review_on', 'client.service', 'client.service_changed',
                    'client.service_deleted', 'client.service_removed', 'client.service_restored', 'client.stage', 'client.touch',
                    'client.touch_deleted', 'client.touch_edited', 'client.touch_removed',
                    'client.touch_restored', 'contact.added', 'contact.deleted',
                    'contact.edited', 'contact.portal_invite', 'contact.portal_off',
                    'contact.portal_on', 'contact.primary', 'contact.removed',
                    'contact.restored',
                    'request.changed', 'request.raised',
                    'request.reinstated', 'request.replied', 'request.withdrawn',
                    'service.override') then 'clients'
    when action in ('wa.sent', 'wa.template') then 'whatsapp'
    when action in ('report.ai_drafted', 'report.ai_failed', 'report.audited', 'report.confirmed',
                    'report.created', 'report.deleted', 'report.published',
                    'report.reassigned', 'report.returned', 'report.revised', 'report.saved',
                    'report.submitted', 'report.unpublished', 'report.version_deleted') then 'reports'
    when action in ('qr.created', 'qr.restored', 'qr.revoked', 'shortlink.created',
                    'shortlink.deleted', 'shortlink.imported', 'shortlink.updated') then 'links'
    when action in ('ops.deleted', 'ops.month_deleted', 'ops.numbering') then 'ops'
    when action in ('document.deleted', 'document.issued', 'document.reissued',
                    'document.restored', 'document.signed', 'document.superseded',
                    'document.unsigned', 'document.verified', 'document.voided',
                    'register.added', 'register.edited') then 'register'
    when action in ('supplier.added', 'supplier.approved', 'supplier.deleted', 'supplier.edited') then 'suppliers'
    when action in ('client.drive', 'client.handles', 'client.profile',
                    'client.removed', 'drive.imported', 'link.reset', 'post.added',
                    'post.deleted', 'post.edited', 'reapproval.requested',
                    'review.approved', 'review.changes', 'review.removed',
                    'review.unconfirmed',
                    'set.created', 'set.deleted', 'set.month', 'set.published', 'set.renamed',
                    'set.task_linked', 'set.task_unlinked',
                    'set.withdrawn') then 'review'
    when action in ('script.approved', 'script.changes', 'script.created', 'script.deleted',
                    'script.link', 'script.saved', 'script.shared', 'script.shot',
                    'script.unshared') then 'scripts'
    when action in ('handbook.added', 'handbook.archived', 'handbook.deleted',
                    'handbook.edited', 'handbook.restored', 'handbook.version') then 'handbook'
    when action in ('service.added', 'service.changed', 'service.deleted',
                    'service.off', 'service.on', 'service.published') then 'services'
    when action in ('team.added', 'team.changed', 'team.edited', 'team.group_added',
                    'team.group_changed', 'team.group_removed', 'team.invited') then 'team'
    else 'other'
  end
  from (select p_action as action) t
$$;
grant execute on function public.activity_section(text) to authenticated;

/* An earlier version back as the draft: its snapshot's rows written over
   the report's own. A key a snapshot from before a column was added lacks
   takes the column's default. */
create or replace function public.sm_report_version_restore(p_version uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  v public.sm_report_versions;
  r public.sm_reports;
  s jsonb;
  head jsonb;
  nv integer;
begin
  if me.id is null or not public.allowed('reports', 'work') then return jsonb_build_object('error', 'denied'); end if;
  select * into v from public.sm_report_versions where id = p_version;
  if v.id is null then return jsonb_build_object('error', 'not-found'); end if;
  select * into r from public.sm_reports where id = v.report_id for update;
  if r.id is null then return jsonb_build_object('error', 'not-found'); end if;
  if not public.client_seen(r.client_id, 'work') then return jsonb_build_object('error', 'denied'); end if;
  if r.status not in ('draft', 'published') then return jsonb_build_object('error', 'in-review', 'status', r.status); end if;
  s := v.snapshot;
  head := coalesce(s -> 'report', '{}'::jsonb);
  nv := case when r.status = 'published' then r.version_no + 1 else r.version_no end;
  perform set_config('adspace.sm_fn', 'on', true);
  update public.sm_reports
     set status = 'draft', version_no = nv, return_note = null,
         submitted_by = null, submitted_at = null, confirmed_by = null, confirmed_at = null,
         headline = head ->> 'headline', intro = head ->> 'intro',
         insights = coalesce(head -> 'insights', '{}'::jsonb),
         rank_metric = coalesce(head ->> 'rank_metric', r.rank_metric),
         first_month = coalesce((head ->> 'first_month')::boolean, r.first_month),
         ads_totals = coalesce(nullif(head -> 'ads_totals', 'null'::jsonb), '{}'::jsonb)
   where id = r.id;
  delete from public.sm_report_posts where report_id = r.id;
  delete from public.sm_report_platforms where report_id = r.id;
  delete from public.sm_report_ads where report_id = r.id;
  insert into public.sm_report_platforms
  select (jsonb_populate_record(null::public.sm_report_platforms,
           jsonb_build_object('id', gen_random_uuid(), 'position', 0, 'metrics', jsonb_build_array('views', 'engagements'))
           || e.j || jsonb_build_object('report_id', r.id, 'created_at', now() + e.n * interval '1 microsecond'))).*
    from jsonb_array_elements(coalesce(s -> 'platforms', '[]'::jsonb)) with ordinality e(j, n);
  insert into public.sm_report_posts
  select (jsonb_populate_record(null::public.sm_report_posts,
           jsonb_build_object('id', gen_random_uuid(), 'position', 0)
           || (e.j - 'thumb_url')
           || jsonb_build_object('report_id', r.id, 'thumb_data', e.j -> 'thumb_url',
                                 'created_at', now() + e.n * interval '1 microsecond'))).*
    from jsonb_array_elements(coalesce(s -> 'posts', '[]'::jsonb)) with ordinality e(j, n);
  insert into public.sm_report_ads
  select (jsonb_populate_record(null::public.sm_report_ads,
           jsonb_build_object('id', gen_random_uuid(), 'position', 0, 'objective', 'awareness',
                              'age', '{}'::jsonb, 'retention', '{}'::jsonb, 'platform', 'meta')
           || (e.j - 'thumb_url')
           || jsonb_build_object('report_id', r.id, 'thumb_data', e.j -> 'thumb_url',
                                 'created_at', now() + e.n * interval '1 microsecond'))).*
    from jsonb_array_elements(coalesce(s -> 'ads', '[]'::jsonb)) with ordinality e(j, n);
  perform set_config('adspace.sm_fn', 'off', true);
  perform public.sm_report_log(r.id, 'report.revised', 'Restored from version ' || v.version_no);
  return jsonb_build_object('ok', true, 'status', 'draft', 'version_no', nv, 'from', v.version_no);
end $$;
revoke all on function public.sm_report_version_restore(uuid) from public, anon;
grant execute on function public.sm_report_version_restore(uuid) to authenticated;

/* A version no longer on the client portal, deleted. */
create or replace function public.sm_report_version_delete(p_version uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  v public.sm_report_versions;
  r public.sm_reports;
begin
  if me.id is null or not public.allowed('reports', 'manage') then return jsonb_build_object('error', 'denied'); end if;
  select * into v from public.sm_report_versions where id = p_version;
  if v.id is null then return jsonb_build_object('error', 'not-found'); end if;
  select * into r from public.sm_reports where id = v.report_id for update;
  if not public.client_seen(r.client_id, 'manage') then return jsonb_build_object('error', 'denied'); end if;
  if v.withdrawn_at is null and not exists (
       select 1 from public.sm_report_versions x
        where x.report_id = v.report_id and x.withdrawn_at is null and x.version_no > v.version_no) then
    return jsonb_build_object('error', 'on-portal');
  end if;
  delete from public.sm_report_versions where id = p_version;
  perform public.sm_report_log(r.id, 'report.version_deleted', 'Version ' || v.version_no);
  return jsonb_build_object('ok', true, 'version_no', v.version_no);
end $$;
revoke all on function public.sm_report_version_delete(uuid) from public, anon;
grant execute on function public.sm_report_version_delete(uuid) to authenticated;

-- END OF REPORT VERSIONS RESTORED AND DELETED --------------------------------

-- ===========================================================================
-- ANALYTICS ALERTS — when a figure on Analytics counts as better or worse,
-- and when churn is an alert, are Business settings (2026-10-25)
-- ===========================================================================
-- WHY (the user, 2026-10-25: "i dont see whether this analytics trend is good
-- or bad since all is monochrome … churned clients too much for example")
--
-- WHAT IT CHANGES
--   * `analytics_change_pct` (10, 1 to 50): a figure counts as better or
--     worse than the period before once it moved by this share, else it
--     reads Steady (js/analytics.js `judge`).
--   * `analytics_churn_pct` (10, 1 to 100): clients lost in a quarter, as a
--     share of those active at its start, above which churn reads Above
--     alert.
--   * `app_settings_set` takes them (whole percentages), filed from and to.
--     Both sit on Settings, Clients: Analytics.
--
-- ORDER: the page first (it reads 10 and 10 where a setting is missing),
-- then this file in the SQL Editor (the function holds a delete, which the
-- connector holds back). Safe to run twice. Rollback: run app_settings_set
-- from ANALYTICS COUNTS FROM again; the two settings' rows may stay.
-- ===========================================================================

insert into public.app_settings (key, from_date, value)
select 'analytics_change_pct', date '2023-08-14', 10
 where not exists (select 1 from public.app_settings s where s.key = 'analytics_change_pct');
insert into public.app_settings (key, from_date, value)
select 'analytics_churn_pct', date '2023-08-14', 10
 where not exists (select 1 from public.app_settings s where s.key = 'analytics_churn_pct');

create or replace function public.app_settings_set(p_from date, p_values jsonb)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me public.team_members; v_k text; v_v numeric; v_was numeric; v_name text; v_unit text; v_pre text;
  v_today date := (now() at time zone 'Asia/Kuala_Lumpur')::date;
  v_keys constant text[] := array['lead_followup_hours', 'proposal_followup_days', 'sst_pct',
    'term_1_3', 'term_4_5', 'term_6_11', 'term_12_23', 'term_18_23', 'term_24', 'report_due_days', 'revision_due_days',
    'ai_price_in', 'ai_price_out', 'meta_checks', 'approval_reminder_days', 'ai_price_search',
    'reach_allowance_pct', 'priority_urgent_hours', 'priority_high_hours', 'priority_medium_hours',
    'task_remind_hours', 'task_start_days', 'quote_valid_days', 'details_form_days', 'wa_repeat_hours',
    'bench_cpr_low', 'bench_cpr_mid', 'bench_cpr_high', 'bench_cpr_top', 'bench_msg_min', 'bench_msg_target', 'bench_msg_max',
    'bench_form_min', 'bench_form_target', 'bench_form_max', 'bench_cpm_min', 'bench_cpm_max', 'bench_cpl_rise',
    'bench_reels_share', 'bench_ad_spend_pct', 'bench_adset_daily', 'vic_lead_followup_hours', 'vic_proposal_followup_days', 'fx_sgd',
    'health_keep_months', 'health_leaver_months', 'abroad_days', 'abroad_remind_hours', 'analytics_from',
    'analytics_change_pct', 'analytics_churn_pct'];
  v_moved text[] := '{}';
  v_drop boolean; v_fw text; v_fv text;
begin
  if not public.ops_granted('team.settings', 'work') then return jsonb_build_object('error', 'denied'); end if;
  v_me := public.ops_me();
  if p_from is null or p_from < v_today then return jsonb_build_object('error', 'past', 'today', v_today); end if;
  if jsonb_typeof(p_values) is distinct from 'object' then return jsonb_build_object('error', 'bad-value'); end if;
  for v_k in select jsonb_object_keys(p_values) loop
    if not (v_k = any(v_keys)) or jsonb_typeof(p_values -> v_k) <> 'number' then
      return jsonb_build_object('error', 'bad-value', 'key', v_k);
    end if;
    v_v := (p_values ->> v_k)::numeric;
    if round(v_v, case when v_k = 'fx_sgd' then 4 else 2 end) <> v_v
       or (v_k = 'fx_sgd' and (v_v < 0.5 or v_v > 10))
       or (v_k in ('lead_followup_hours', 'vic_lead_followup_hours') and (v_v < 1 or v_v > 720 or v_v <> trunc(v_v)))
       or (v_k in ('proposal_followup_days', 'vic_proposal_followup_days') and (v_v < 1 or v_v > 365 or v_v <> trunc(v_v)))
       or (v_k = 'report_due_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'revision_due_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'approval_reminder_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'sst_pct' and (v_v < 0 or v_v > 100))
       or (v_k like 'term_%' and (v_v < -100 or v_v > 100))
       or (v_k like 'ai_price_%' and (v_v < 0 or v_v > 1000))
       or (v_k = 'meta_checks' and v_v not in (0, 1))
       or (v_k = 'reach_allowance_pct' and (v_v < 0 or v_v > 5))
       or (v_k like 'priority_%_hours' and (v_v < 1 or v_v > 720 or v_v <> trunc(v_v)))
       or (v_k = 'task_remind_hours' and (v_v < 0 or v_v > 24 or v_v <> trunc(v_v)))
       or (v_k = 'task_start_days' and (v_v < 0 or v_v > 30 or v_v <> trunc(v_v)))
       or (v_k in ('quote_valid_days', 'details_form_days') and (v_v < 1 or v_v > 90 or v_v <> trunc(v_v)))
       or (v_k = 'wa_repeat_hours' and (v_v < 0 or v_v > 168 or v_v <> trunc(v_v)))
       or (v_k = 'health_keep_months' and (v_v < 6 or v_v > 120 or v_v <> trunc(v_v)))
       or (v_k = 'health_leaver_months' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'abroad_days' and (v_v < 1 or v_v > 30 or v_v <> trunc(v_v)))
       or (v_k = 'abroad_remind_hours' and (v_v < 0 or v_v > 24 or v_v <> trunc(v_v)))
       or (v_k = 'analytics_from' and (v_v < 202308 or v_v > 209912 or v_v <> trunc(v_v) or mod(v_v, 100) not between 1 and 12))
       or (v_k = 'analytics_change_pct' and (v_v < 1 or v_v > 50 or v_v <> trunc(v_v)))
       or (v_k = 'analytics_churn_pct' and (v_v < 1 or v_v > 100 or v_v <> trunc(v_v)))
       or (v_k in ('bench_reels_share') and (v_v < 0 or v_v > 100))
       or (v_k = 'bench_ad_spend_pct' and (v_v < 1 or v_v > 100))
       or (v_k = 'bench_cpl_rise' and (v_v < -100 or v_v > 100))
       or (v_k like 'bench_%' and v_k not in ('bench_reels_share', 'bench_ad_spend_pct', 'bench_cpl_rise') and (v_v < 0 or v_v > 10000)) then
      return jsonb_build_object('error', 'bad-value', 'key', v_k);
    end if;
  end loop;
  for v_k in select jsonb_object_keys(p_values) loop
    v_v := (p_values ->> v_k)::numeric;
    v_was := public.app_setting(v_k, p_from);
    if v_was is distinct from v_v then
      /* A planned change saved back to the value in force the day before is
         withdrawn: its row goes, rather than a second row restating it. */
      v_drop := p_from > v_today
        and exists (select 1 from public.app_settings s where s.key = v_k and s.from_date = p_from)
        and exists (select 1 from public.app_settings s where s.key = v_k and s.from_date < p_from)
        and public.app_setting(v_k, p_from - 1) = v_v;
      if v_drop then
        delete from public.app_settings s where s.key = v_k and s.from_date = p_from;
      else
        insert into public.app_settings (key, from_date, value, set_by, set_at)
        values (v_k, p_from, v_v, v_me.id, now())
        on conflict (key, from_date) do update set value = excluded.value, set_by = excluded.set_by, set_at = now();
      end if;
      v_name := case v_k when 'lead_followup_hours' then 'A lead waits' when 'proposal_followup_days' then 'A proposal waits'
        when 'vic_lead_followup_hours' then 'A VIC lead waits' when 'vic_proposal_followup_days' then 'A VIC proposal waits'
        when 'sst_pct' then 'SST' when 'term_1_3' then '1 to 3 months' when 'term_4_5' then '4 and 5 months'
        when 'term_6_11' then '6 to 11 months' when 'term_12_23' then '12 to 17 months' when 'term_18_23' then '18 to 23 months' when 'term_24' then '24 months and more'
        when 'revision_due_days' then 'Revision due' when 'ai_price_in' then 'AI input, a million tokens'
        when 'ai_price_out' then 'AI output, a million tokens' when 'ai_price_search' then 'AI web searches, a thousand' when 'meta_checks' then 'Meta checks'
        when 'approval_reminder_days' then 'Approval reminder' when 'reach_allowance_pct' then 'Reach allowance'
        when 'priority_urgent_hours' then 'Urgent deadline' when 'priority_high_hours' then 'High deadline'
        when 'priority_medium_hours' then 'Medium deadline' when 'task_remind_hours' then 'Task reminders'
        when 'task_start_days' then 'Not started reminder' when 'quote_valid_days' then 'Quotation validity' when 'details_form_days' then 'Details form open'
        when 'wa_repeat_hours' then 'WhatsApp sent again'
        when 'bench_cpr_low' then 'Property cost per result, tier 1 from' when 'bench_cpr_mid' then 'Property cost per result, tier 2 from'
        when 'bench_cpr_high' then 'Property cost per result, tier 3 from' when 'bench_cpr_top' then 'Property cost per result, tier 3 up to'
        when 'bench_msg_min' then 'Messaging cost per result, low' when 'bench_msg_target' then 'Messaging cost per result, target'
        when 'bench_msg_max' then 'Messaging cost per result, high' when 'bench_form_min' then 'Lead form cost per result, low'
        when 'bench_form_target' then 'Lead form cost per result, target' when 'bench_form_max' then 'Lead form cost per result, high'
        when 'bench_cpm_min' then 'Cost per 1,000 impressions, low' when 'bench_cpm_max' then 'Cost per 1,000 impressions, high'
        when 'bench_cpl_rise' then 'Cost per lead rise a year' when 'bench_reels_share' then 'Reels share of impressions'
        when 'bench_ad_spend_pct' then 'Ad spend of the budget' when 'bench_adset_daily' then 'Daily budget an ad set, at least'
        when 'fx_sgd' then 'Singapore dollar rate'
        when 'health_keep_months' then 'Health check-ins kept' when 'health_leaver_months' then 'A leaver''s health data kept'
        when 'abroad_days' then 'Overseas approval' when 'abroad_remind_hours' then 'Overseas reminder'
        when 'analytics_from' then 'Analytics counts from'
        when 'analytics_change_pct' then 'Analytics change threshold' when 'analytics_churn_pct' then 'Analytics churn alert, a quarter'
        else 'Report due' end;
      v_pre := case when v_k = 'fx_sgd' then 'RM ' when v_k like 'ai_price_%' then 'US$' when v_k like 'bench_%' and v_k not in ('bench_cpl_rise', 'bench_reels_share', 'bench_ad_spend_pct') then 'RM ' else '' end;
      v_unit := case when v_k = 'fx_sgd' then ' to S$1' when v_k in ('lead_followup_hours', 'vic_lead_followup_hours', 'task_remind_hours', 'wa_repeat_hours', 'abroad_remind_hours') or v_k like 'priority_%_hours' then ' hours'
        when v_k in ('proposal_followup_days', 'vic_proposal_followup_days', 'report_due_days', 'revision_due_days', 'approval_reminder_days', 'task_start_days', 'quote_valid_days', 'details_form_days', 'abroad_days') then ' days'
        when v_k in ('health_keep_months', 'health_leaver_months') then ' months'
        when v_pre <> '' then '' else '%' end;
      v_fw := case when v_k = 'meta_checks' then case when v_was = 1 then 'On' else 'Off' end
              when v_k = 'analytics_from' then coalesce(substr(public.register_day(to_date(v_was::bigint::text, 'YYYYMM')), 3), 'not set') else coalesce(v_pre ||
              trim(to_char(v_was, case when v_k = 'fx_sgd' then 'FM999999990.9999' else 'FM999999990.99' end), '.') || v_unit, 'not set') end;
      v_fv := case when v_k = 'meta_checks' then case when v_v = 1 then 'On' else 'Off' end
              when v_k = 'analytics_from' then substr(public.register_day(to_date(v_v::bigint::text, 'YYYYMM')), 3) else v_pre ||
              trim(to_char(v_v, case when v_k = 'fx_sgd' then 'FM999999990.9999' else 'FM999999990.99' end), '.') || v_unit end;
      insert into public.activity_log (actor, action, subject, detail)
      values (coalesce(v_me.name, 'admin'), 'team.changed', 'Settings',
              case when v_drop then v_name || ': planned change withdrawn · ' || v_fw || ' from ' || public.register_day(p_from) ||
                ', stays ' || v_fv else
              case when v_k = 'analytics_from' then v_name || ': ' || v_fw || ' → ' || v_fv || ' · from ' || public.register_day(p_from) else
              v_name || ': ' || case when v_k = 'meta_checks' then
                case when v_was = 1 then 'On' else 'Off' end || ' → ' || case when v_v = 1 then 'On' else 'Off' end ||
                ' · from ' || public.register_day(p_from) else '' end ||
              case when v_k = 'meta_checks' then '' else coalesce(v_pre ||
              trim(to_char(v_was, case when v_k = 'fx_sgd' then 'FM999999990.9999' else 'FM999999990.99' end), '.') || v_unit, 'not set') || ' → ' || v_pre ||
              trim(to_char(v_v, case when v_k = 'fx_sgd' then 'FM999999990.9999' else 'FM999999990.99' end), '.') || v_unit ||
              ' · from ' || public.register_day(p_from) end end end);
      v_moved := v_moved || v_k;
    end if;
  end loop;
  return public.app_settings_read() || jsonb_build_object('changed', to_jsonb(v_moved));
end $$;
revoke all on function public.app_settings_set(date, jsonb) from public, anon;
grant execute on function public.app_settings_set(date, jsonb) to authenticated;

-- END OF ANALYTICS ALERTS ---------------------------------------------------

-- ===========================================================================
-- ANALYTICS READ WITH AI — an AI analysis of the Analytics figures, kept as
-- versions (2026-10-25)
-- ===========================================================================
-- WHY (the user, 2026-10-25: "i dont see whether this analytics trend is good
-- or bad since all is monochrome … churned clients too much for example";
-- "build part 1 and 2 together")
--
-- WHAT IT CHANGES
--   * `analytics_reads` (RLS on, no policy, no grant): each AI analysis of
--     the Analytics figures as the next version, with the figures it read
--     (`figures`), the period, the model and who ran it.
--   * Write with AI on Analytics is its own count (`ai_drafts.purpose`
--     `analytics`): `analytics` (3) a colleague's a day and
--     `analytics_admin` (10) an admin's, settings in `ai_draft_limits`,
--     claimed by `ai_analytics_claim()` (`team.analytics` at Work) and read
--     by `ai_analytics_left()`; `ai_draft_usage` and `ai_draft_set_limit`
--     know them.
--   * `analytics_read_save(p_press, p_period, p_figures, p_analysis,
--     p_model)` keeps a run as the next version (the press its own, once),
--     filed `team.changed` under Analytics; `analytics_reads_list()` the
--     last twenty, newest first; `analytics_read_delete(p_id)` removes one
--     (asked on the page, no restore), filed.
--
-- ORDER: the page first (it reads Write with AI as "This needs a database
-- update" until this runs), then this file in the SQL Editor (it holds a
-- delete and the purpose check's drop, which the connector holds back),
-- then the edge function `analytics-read`. Safe to run twice.
--
-- ROLLBACK
--   Run CHECKLIST WRITER's ai_draft_usage and ai_draft_set_limit again;
--   drop the six functions and `analytics_reads`; delete the `analytics`
--   rows from ai_drafts and put the purpose check back to its six
--   purposes.
-- ===========================================================================

create table if not exists public.analytics_reads (
  id uuid primary key default gen_random_uuid(),
  version integer not null unique,
  period text not null,
  figures jsonb not null default '{}'::jsonb,
  analysis jsonb not null,
  model text,
  press_id uuid unique references public.ai_drafts (id) on delete set null,
  created_by uuid references public.team_members (id) on delete set null,
  created_at timestamptz not null default now()
);
alter table public.analytics_reads enable row level security;
revoke all on public.analytics_reads from public, anon, authenticated;

do $$
begin
  if not exists (select 1 from pg_constraint
                  where conname = 'ai_drafts_purpose' and pg_get_constraintdef(oid) like '%analytics%') then
    alter table public.ai_drafts drop constraint if exists ai_drafts_purpose;
    alter table public.ai_drafts add constraint ai_drafts_purpose
      check (purpose in ('draft', 'check', 'caption', 'script', 'analysis', 'checklist', 'analytics'));
  end if;
end $$;

create or replace function public.ai_analytics_claim()
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m public.team_members;
  since timestamptz := public.ai_draft_day();
  n_used integer;
  lim integer;
  new_id uuid;
begin
  if not public.ops_granted('team.analytics', 'work') then return jsonb_build_object('error', 'denied'); end if;
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'denied'); end if;
  perform pg_advisory_xact_lock(hashtext('ai_draft_claim'));
  lim := case when coalesce(m.is_admin, false) or m.role = 'admin'
              then public.ai_draft_limit('analytics_admin', 10) else public.ai_draft_limit('analytics', 3) end;
  if lim = 0 then return jsonb_build_object('error', 'ai-limit', 'scope', 'stopped', 'limit', 0); end if;
  select count(*) into n_used from public.ai_drafts d
   where d.team_member_id = m.id and d.purpose = 'analytics' and d.created_at >= since and d.outcome <> 'failed';
  if n_used >= lim then
    return jsonb_build_object('error', 'ai-limit', 'scope', 'analytics', 'limit', lim, 'next', since + interval '1 day');
  end if;
  insert into public.ai_drafts (team_member_id, purpose)
  values (m.id, 'analytics') returning id into new_id;
  return jsonb_build_object('id', new_id, 'left', lim - n_used - 1, 'limit', lim);
end $$;

create or replace function public.ai_analytics_left()
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  m public.team_members;
  since timestamptz := public.ai_draft_day();
  lim integer;
begin
  if not public.ops_granted('team.analytics', 'work') then return jsonb_build_object('error', 'denied'); end if;
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'denied'); end if;
  lim := case when coalesce(m.is_admin, false) or m.role = 'admin'
              then public.ai_draft_limit('analytics_admin', 10) else public.ai_draft_limit('analytics', 3) end;
  return jsonb_build_object('limit', lim, 'next', since + interval '1 day',
    'left', greatest(0, lim - (select count(*) from public.ai_drafts d
      where d.team_member_id = m.id and d.purpose = 'analytics' and d.created_at >= since and d.outcome <> 'failed')::integer));
end $$;

create or replace function public.analytics_read_row(r public.analytics_reads)
returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object('id', r.id, 'version', r.version, 'period', r.period, 'figures', r.figures,
    'analysis', r.analysis, 'model', r.model, 'created_at', r.created_at,
    'by', (select t.name from public.team_members t where t.id = r.created_by))
$$;
revoke all on function public.analytics_read_row(public.analytics_reads) from public, anon, authenticated;

create or replace function public.analytics_read_save(p_press uuid, p_period text, p_figures jsonb,
                                                      p_analysis jsonb, p_model text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m public.team_members;
  d public.ai_drafts;
  a public.analytics_reads;
  v_no integer;
begin
  if not public.ops_granted('team.analytics', 'work') then return jsonb_build_object('error', 'denied'); end if;
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'denied'); end if;
  select * into d from public.ai_drafts x where x.id = p_press for update;
  if d.id is null or d.team_member_id <> m.id or d.purpose <> 'analytics' or d.outcome <> 'pending'
     or exists (select 1 from public.analytics_reads x where x.press_id = d.id) then
    return jsonb_build_object('error', 'not-found');
  end if;
  if jsonb_typeof(p_analysis) is distinct from 'object' or char_length(p_analysis::text) > 40000
     or jsonb_typeof(p_figures) is distinct from 'object' or char_length(p_figures::text) > 60000
     or char_length(btrim(coalesce(p_period, ''))) not between 1 and 80 then
    return jsonb_build_object('error', 'bad-analysis');
  end if;
  perform pg_advisory_xact_lock(hashtext('analytics_reads'));
  select coalesce(max(x.version), 0) + 1 into v_no from public.analytics_reads x;
  insert into public.analytics_reads (version, period, figures, analysis, model, press_id, created_by)
  values (v_no, btrim(p_period), p_figures, p_analysis, left(nullif(btrim(coalesce(p_model, '')), ''), 80), d.id, m.id)
  returning * into a;
  insert into public.activity_log (actor, action, subject, detail)
  values (coalesce(m.name, m.email), 'team.changed', 'Analytics',
          'Analysis version ' || v_no || ' written with AI · ' || btrim(p_period));
  return public.analytics_read_row(a);
end $$;

create or replace function public.analytics_reads_list()
returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.ops_granted('team.analytics', 'work') then return jsonb_build_object('error', 'denied'); end if;
  return jsonb_build_object('versions', coalesce((select jsonb_agg(public.analytics_read_row(x) order by x.version desc)
    from (select * from public.analytics_reads a order by a.version desc limit 20) x), '[]'::jsonb));
end $$;

create or replace function public.analytics_read_delete(p_id uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  m public.team_members;
  a public.analytics_reads;
begin
  if not public.ops_granted('team.analytics', 'work') then return jsonb_build_object('error', 'denied'); end if;
  m := public.ops_me();
  if m.id is null then return jsonb_build_object('error', 'denied'); end if;
  delete from public.analytics_reads x where x.id = p_id returning * into a;
  if a.id is null then return jsonb_build_object('error', 'not-found'); end if;
  insert into public.activity_log (actor, action, subject, detail)
  values (coalesce(m.name, m.email), 'team.changed', 'Analytics',
          'Analysis version ' || a.version || ' deleted · ' || a.period);
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.ai_draft_usage()
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_day timestamptz := public.ai_draft_day();
  v_month timestamptz := now() - interval '30 days';
  -- This calendar month in Malaysia, for what the calls cost.
  v_cal timestamptz := date_trunc('month', now() at time zone 'Asia/Kuala_Lumpur') at time zone 'Asia/Kuala_Lumpur';
  v_today date := (now() at time zone 'Asia/Kuala_Lumpur')::date;
begin
  if not public.ops_granted('reports.ai', 'work') then return jsonb_build_object('error', 'denied'); end if;
  return jsonb_build_object(
    'person', public.ai_draft_limit('person', 10),
    'admin', public.ai_draft_limit('admin', 20),
    'report', public.ai_draft_limit('report', 1),
    'report_admin', public.ai_draft_limit('report_admin', 5),
    'check', public.ai_draft_limit('check', 1),
    'check_admin', public.ai_draft_limit('check_admin', 5),
    'caption', public.ai_draft_limit('caption', 20),
    'caption_admin', public.ai_draft_limit('caption_admin', 40),
    'script', public.ai_draft_limit('script', 10),
    'script_admin', public.ai_draft_limit('script_admin', 20),
    'analysis', public.ai_draft_limit('analysis', 3),
    'analysis_admin', public.ai_draft_limit('analysis_admin', 10),
    'checklist', public.ai_draft_limit('checklist', 10),
    'checklist_admin', public.ai_draft_limit('checklist_admin', 20),
    'analytics', public.ai_draft_limit('analytics', 3),
    'analytics_admin', public.ai_draft_limit('analytics_admin', 10),
    'cost', (select jsonb_build_object(
        'since', v_cal,
        'price_in', public.app_setting('ai_price_in', v_today),
        'price_out', public.app_setting('ai_price_out', v_today),
        'price_search', coalesce(public.app_setting('ai_price_search', v_today), 10),
        'uses', count(*),
        'untracked', count(*) filter (where c.input_tokens is null),
        'input', coalesce(sum(c.input_tokens), 0),
        'output', coalesce(sum(c.output_tokens), 0),
        'searches', coalesce(sum(c.web_searches), 0),
        'usd', round(coalesce(sum(c.usd), 0), 2),
        'by', coalesce((select jsonb_object_agg(p.purpose, p.x) from (
            select c2.purpose, jsonb_build_object('uses', count(*), 'input', coalesce(sum(c2.input_tokens), 0),
                     'output', coalesce(sum(c2.output_tokens), 0), 'searches', coalesce(sum(c2.web_searches), 0),
                     'usd', round(coalesce(sum(c2.usd), 0), 2)) as x
              from (select d.purpose, d.input_tokens, d.output_tokens, d.web_searches,
                           (coalesce(d.input_tokens, 0) * public.app_setting('ai_price_in', (d.created_at at time zone 'Asia/Kuala_Lumpur')::date)
                          + coalesce(d.output_tokens, 0) * public.app_setting('ai_price_out', (d.created_at at time zone 'Asia/Kuala_Lumpur')::date)) / 1000000.0
                          + coalesce(d.web_searches, 0) * coalesce(public.app_setting('ai_price_search', (d.created_at at time zone 'Asia/Kuala_Lumpur')::date), 10) / 1000.0 as usd
                      from public.ai_drafts d where d.created_at >= v_cal and (d.outcome <> 'failed' or d.input_tokens is not null)) c2
             group by c2.purpose) p), '{}'::jsonb))
      from (select d.input_tokens, d.output_tokens, d.web_searches,
                   (coalesce(d.input_tokens, 0) * public.app_setting('ai_price_in', (d.created_at at time zone 'Asia/Kuala_Lumpur')::date)
                  + coalesce(d.output_tokens, 0) * public.app_setting('ai_price_out', (d.created_at at time zone 'Asia/Kuala_Lumpur')::date)) / 1000000.0
                  + coalesce(d.web_searches, 0) * coalesce(public.app_setting('ai_price_search', (d.created_at at time zone 'Asia/Kuala_Lumpur')::date), 10) / 1000.0 as usd
              from public.ai_drafts d where d.created_at >= v_cal and (d.outcome <> 'failed' or d.input_tokens is not null)) c),
    'resets_at', v_day + interval '1 day',
    'people', coalesce((select jsonb_agg(s.x order by s.x ->> 'name') from (
      select jsonb_build_object(
        'id', t.id, 'name', t.name, 'code', t.staff_code, 'group', g.name, 'group_slug', t.role,
        'admin', coalesce(t.is_admin, false) or t.role = 'admin',
        'day', (select count(*) from public.ai_drafts d where d.team_member_id = t.id and d.created_at >= v_day and d.outcome <> 'failed' and d.purpose in ('draft', 'check')),
        'captions', (select count(*) from public.ai_drafts d where d.team_member_id = t.id and d.created_at >= v_day and d.outcome <> 'failed' and d.purpose = 'caption'),
        'caption_cap', case when coalesce(t.is_admin, false) or t.role = 'admin'
                            then public.ai_draft_limit('caption_admin', 40) else public.ai_draft_limit('caption', 20) end,
        'scripts', (select count(*) from public.ai_drafts d where d.team_member_id = t.id and d.created_at >= v_day and d.outcome <> 'failed' and d.purpose = 'script'),
        'script_cap', case when coalesce(t.is_admin, false) or t.role = 'admin'
                           then public.ai_draft_limit('script_admin', 20) else public.ai_draft_limit('script', 10) end,
        'analyses', (select count(*) from public.ai_drafts d where d.team_member_id = t.id and d.created_at >= v_day and d.outcome <> 'failed' and d.purpose = 'analysis'),
        'analysis_cap', case when coalesce(t.is_admin, false) or t.role = 'admin'
                             then public.ai_draft_limit('analysis_admin', 10) else public.ai_draft_limit('analysis', 3) end,
        'checklists', (select count(*) from public.ai_drafts d where d.team_member_id = t.id and d.created_at >= v_day and d.outcome <> 'failed' and d.purpose = 'checklist'),
        'checklist_cap', case when coalesce(t.is_admin, false) or t.role = 'admin'
                              then public.ai_draft_limit('checklist_admin', 20) else public.ai_draft_limit('checklist', 10) end,
        'analytics', (select count(*) from public.ai_drafts d where d.team_member_id = t.id and d.created_at >= v_day and d.outcome <> 'failed' and d.purpose = 'analytics'),
        'analytics_cap', case when coalesce(t.is_admin, false) or t.role = 'admin'
                              then public.ai_draft_limit('analytics_admin', 10) else public.ai_draft_limit('analytics', 3) end,
        'month', (select count(*) from public.ai_drafts d where d.team_member_id = t.id and d.created_at > v_month and d.outcome <> 'failed'),
        'limit', (select l.daily from public.ai_draft_limits l where l.scope = t.id::text),
        'cap', public.ai_day_cap(t)) as x
        from public.team_members t
        left join public.team_roles g on g.slug = t.role
       where t.active
         and (coalesce(t.is_admin, false) or t.role = 'admin'
              or public.level_rank(coalesce(t.access ->> 'reports', 'none')) >= public.level_rank('work')
              or public.level_rank(coalesce(t.access ->> 'review', 'none')) >= public.level_rank('work')
              or public.level_rank(coalesce(t.access ->> 'scripts', 'none')) >= public.level_rank('work')
              or exists (select 1 from public.ai_drafts d where d.team_member_id = t.id and d.created_at > v_month))
    ) s), '[]'::jsonb));
end $$;
revoke all on function public.ai_draft_usage() from public, anon, authenticated;
grant execute on function public.ai_draft_usage() to authenticated;

create or replace function public.ai_draft_set_limit(p_scope text, p_daily integer)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_who text;
  v_name text;
  v_was integer;
  v_def integer;
  v_unit text := ' a day';
  v_scope text := btrim(coalesce(p_scope, ''));
  t public.team_members;
begin
  if not public.ops_granted('reports.ai', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if p_daily is not null and (p_daily < 0 or p_daily > 500) then
    return jsonb_build_object('error', 'bad-limit');
  end if;
  if v_scope = 'person' then
    v_name := 'Each colleague'; v_def := 10;
  elsif v_scope = 'admin' then
    v_name := 'Each admin'; v_def := 20;
  elsif v_scope = 'report' then
    v_name := 'Drafts per report, each colleague'; v_def := 1;
  elsif v_scope = 'report_admin' then
    v_name := 'Drafts per report, each admin'; v_def := 5;
  elsif v_scope = 'check' then
    v_name := 'Figures checks per report, each colleague'; v_def := 1;
  elsif v_scope = 'check_admin' then
    v_name := 'Figures checks per report, each admin'; v_def := 5;
  elsif v_scope = 'caption' then
    v_name := 'Captions, each colleague'; v_def := 20;
  elsif v_scope = 'caption_admin' then
    v_name := 'Captions, each admin'; v_def := 40;
  elsif v_scope = 'script' then
    v_name := 'Scripts, each colleague'; v_def := 10;
  elsif v_scope = 'script_admin' then
    v_name := 'Scripts, each admin'; v_def := 20;
  elsif v_scope = 'analysis' then
    v_name := 'Brand analyses, each colleague'; v_def := 3;
  elsif v_scope = 'analysis_admin' then
    v_name := 'Brand analyses, each admin'; v_def := 10;
  elsif v_scope = 'checklist' then
    v_name := 'Checklists, each colleague'; v_def := 10;
  elsif v_scope = 'checklist_admin' then
    v_name := 'Checklists, each admin'; v_def := 20;
  elsif v_scope = 'analytics' then
    v_name := 'Analytics analyses, each colleague'; v_def := 3;
  elsif v_scope = 'analytics_admin' then
    v_name := 'Analytics analyses, each admin'; v_def := 10;
  elsif v_scope = 'team' then
    return jsonb_build_object('error', 'bad-scope');
  else
    select * into t from public.team_members x where x.id::text = v_scope;
    if t.id is null then return jsonb_build_object('error', 'not-found'); end if;
    v_name := t.name;
    v_def := case when coalesce(t.is_admin, false) or t.role = 'admin'
                  then public.ai_draft_limit('admin', 20) else public.ai_draft_limit('person', 10) end;
  end if;
  select l.daily into v_was from public.ai_draft_limits l where l.scope = v_scope;
  if v_was is not distinct from p_daily then return jsonb_build_object('ok', true, 'same', true); end if;
  select coalesce(x.name, x.email) into v_who from public.team_members x
   where lower(x.email) = lower(auth.jwt() ->> 'email') and x.active limit 1;
  insert into public.ai_draft_limits (scope, daily, set_by, set_at)
  values (v_scope, p_daily, v_who, now())
  on conflict (scope) do update set daily = excluded.daily, set_by = excluded.set_by, set_at = excluded.set_at;
  insert into public.activity_log (actor, action, subject, detail)
  values (coalesce(v_who, 'admin'), 'team.changed', 'AI',
          v_name || ': ' ||
          case when v_was is null then 'standard, ' || v_def || v_unit when v_was = 0 then 'stopped' else v_was || v_unit end ||
          ' → ' ||
          case when p_daily is null then 'standard, ' || v_def || v_unit when p_daily = 0 then 'stopped' else p_daily || v_unit end);
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.ai_draft_set_limit(text, integer) from public, anon, authenticated;
grant execute on function public.ai_draft_set_limit(text, integer) to authenticated;

revoke all on function public.ai_analytics_claim() from public, anon, authenticated;
revoke all on function public.ai_analytics_left() from public, anon, authenticated;
