-- ===========================================================================
-- QUOTATION WORDS FOR A CLIENT — a quotation's lines name content pieces,
-- never "contents". 2026-10-27. Safe to run twice. Rollback at the foot.
-- Mirrored byte for byte in supabase/schema.sql under the same banner;
-- tests/sql.js compares the two.
--
-- WHAT CHANGED (the user, 2026-10-27: client-facing words are formal
-- English)
--   `content` is uncountable in formal English, so a plan's line read
--   "6 contents per month" and a translation line "Translation into
--   Chinese, per content" on every quotation, its PDF and the Letter of
--   Offer made from it. quote_price now writes "6 content pieces per
--   month: …" and "…, per content piece". No figure moves. A quotation
--   already issued keeps the words it was issued with; an edit kept under
--   an older translation line's label no longer finds the new label (the
--   card's rate stands on a copy of that line).
--
-- ROLLBACK
--   Run quote_price from QUOTE TOTALS IN ONE PLACE again.
-- ===========================================================================

create or replace function public.quote_price(p_snap jsonb, p_sel jsonb)
returns jsonb
language plpgsql immutable set search_path = public as $$
declare
  v_svc jsonb := coalesce(p_snap->'services', '[]'::jsonb);
  v_set jsonb := coalesce(p_snap->'settings', '{}'::jsonb);
  v_text jsonb := coalesce(p_snap->'text', '{}'::jsonb);
  v_lines jsonb := '[]'::jsonb;
  v_req text[] := '{}';
  v_plan jsonb; v_spec jsonb; v_mix jsonb; v_opt jsonb;
  v_term int; v_mixi int := 0; v_slots int := 0; v_contents int := 0;
  v_meta numeric; v_fee numeric; v_val numeric; v_best numeric := 0; v_factor numeric;
  v_cover numeric := 0; v_budget numeric := 0; v_cost numeric; v_from numeric;
  v_plats text[] := '{}'; v_in text[] := '{}'; v_p text; v_k text; v_n int; v_q int;
  v_s jsonb; v_rate numeric; v_langs text[] := '{}'; v_l text; v_base text;
  v_pct numeric := 0; v_qtot jsonb;
  v_sst_pct numeric := coalesce((v_set->>'sst_pct')::numeric, 0);
  v_detail text[]; v_words text[]; v_tot int := 0; v_x jsonb; v_month boolean := false;
  v_hint jsonb := '{}'::jsonb;
  v_names constant jsonb := '{"meta":"Meta","tiktok":"TikTok","rednote":"rednote","linkedin":"LinkedIn"}';
  v_lname constant jsonb := '{"en":"English","zh":"Chinese","ms":"Malay"}';
begin
  if jsonb_typeof(p_sel) is distinct from 'object' then return jsonb_build_object('error', 'bad-selection'); end if;
  if coalesce(p_sel->>'term', '') !~ '^[0-9]{1,2}$' then return jsonb_build_object('error', 'bad-term'); end if;
  v_term := (p_sel->>'term')::int;
  /* The terms a quotation is offered on (the user, 2026-10-14); 1 is
     one-off items alone, refused below where a monthly line is held. */
  if v_term not in (1, 3, 6, 12, 18, 24) then return jsonb_build_object('error', 'bad-term'); end if;
  select (s->>'rate')::numeric into v_meta from jsonb_array_elements(v_svc) s
   where s->'spec'->>'role' = 'platform' and s->'spec'->>'platform' = 'meta' limit 1;
  v_meta := coalesce(v_meta, 0);

  -- Platforms asked for, known and once each, cheapest first.
  select coalesce(array_agg(p order by f, o), '{}') into v_plats
    from (select x.p, x.o, (select (s->>'rate')::numeric from jsonb_array_elements(v_svc) s
                             where s->'spec'->>'role' = 'platform' and s->'spec'->>'platform' = x.p
                               and coalesce((s->>'active')::boolean, true) limit 1) f
            from (select distinct on (v) v as p, array_position(array['meta', 'tiktok', 'rednote', 'linkedin'], v) o
                    from jsonb_array_elements_text(coalesce(p_sel->'platforms', '[]'::jsonb)) v
                   where v in ('meta', 'tiktok', 'rednote', 'linkedin')) x) y
   where f is not null;

  if nullif(p_sel->>'plan', '') is not null then
    v_plan := public.quote_svc(p_snap, p_sel->>'plan');
    v_spec := v_plan->'spec';
    if v_plan is null or v_spec->>'role' is distinct from 'plan' or v_plan->>'rate' is null then
      return jsonb_build_object('error', 'bad-plan');
    end if;
    if coalesce(p_sel->>'mix', '0') ~ '^[0-9]$' then v_mixi := coalesce((p_sel->>'mix')::int, 0); end if;
    if v_mixi >= jsonb_array_length(v_spec->'mix') then v_mixi := 0; end if;
    v_mix := v_spec->'mix'->v_mixi;
    v_slots := (v_spec->>'platforms')::int;
    v_contents := (v_spec->>'contents')::int;
    v_cover := coalesce((v_spec->>'ad_budget')::numeric, 0);
    if array_length(v_plats, 1) is null then return jsonb_build_object('error', 'no-platform'); end if;
    v_in := v_plats[1:v_slots];

    -- The plan's whole saving: its fee against everything in it at Ala Carte,
    -- on the option worth more.
    for v_opt in select * from jsonb_array_elements(v_spec->'mix') loop
      v_val := v_slots * v_meta + coalesce(public.quote_ads_cost(p_snap, v_cover), 0);
      for v_k in select jsonb_object_keys(v_opt) loop
        select (s->>'rate')::numeric into v_rate from jsonb_array_elements(v_svc) s
         where s->'spec'->>'role' = 'content' and s->'spec'->>'kind' = v_k limit 1;
        v_val := v_val + coalesce(v_rate, 0) * (v_opt->>v_k)::int;
      end loop;
      v_best := greatest(v_best, v_val);
    end loop;
    v_factor := case when v_best > 0 then (v_plan->>'rate')::numeric / v_best else 1 end;
    -- What one more of each content costs on this plan, for the builder.
    select coalesce(jsonb_object_agg(s->>'slug', round((s->>'rate')::numeric * v_factor / 10) * 10), '{}'::jsonb) into v_hint
      from jsonb_array_elements(v_svc) s
     where s->'spec'->>'role' = 'content' and s->>'rate' is not null and coalesce((s->>'active')::boolean, true);

    v_words := '{}';
    for v_k in select k from jsonb_object_keys(v_mix) k
                order by array_position(array['graphic', 'reel'], k) nulls last, k loop
      v_n := (v_mix->>v_k)::int;
      v_words := v_words || (v_n || ' ' || case v_k when 'graphic' then case when v_n = 1 then 'graphic' else 'graphics' end
        when 'reel' then case when v_n = 1 then 'reel' else 'reels' end else v_k end);
    end loop;
    v_detail := array[v_contents || ' content pieces per month: ' || array_to_string(v_words, ' and ') ||
      case when v_mix ? 'reel' then ', up to 60 seconds each' else '' end];
    if v_cover > 0 then
      v_detail := v_detail || ('Advertising budget coverage up to ' || public.quote_rm(v_cover) || ' per month');
    end if;
    v_detail := v_detail || string_to_array(coalesce(v_text->>case when v_cover > 0 then 'plans_ads_included' else 'plans_included' end, ''), E'\n');
    v_lines := v_lines || jsonb_build_object('slug', v_plan->>'slug', 'kind', 'plan', 'basis', 'month',
      'label', 'Social Media Services · Plan ' || (v_spec->>'plan') || ' (' ||
        regexp_replace((select string_agg(v_names->>x, ', ' order by o) from unnest(v_in) with ordinality u(x, o)),
                       ', ([^,]*)$', ' and \1') || ')',
      'detail', (select jsonb_agg(d) from unnest(v_detail) d where btrim(d) <> ''),
      'qty', 1, 'rate', (v_plan->>'rate')::numeric);

    -- A dearer platform in a Meta-rate place adds the difference.
    foreach v_p in array v_in loop
      select (s->>'rate')::numeric, s->>'slug' into v_fee, v_k from jsonb_array_elements(v_svc) s
       where s->'spec'->>'role' = 'platform' and s->'spec'->>'platform' = v_p limit 1;
      if v_fee > v_meta then
        v_lines := v_lines || jsonb_build_object('slug', v_k, 'kind', 'platform_in', 'basis', 'month',
          'label', (v_names->>v_p) || ' within the plan', 'detail', '[]'::jsonb, 'qty', 1, 'rate', v_fee - v_meta);
      end if;
    end loop;
    foreach v_p in array coalesce(v_plats[v_slots + 1:], '{}') loop
      select (s->>'rate')::numeric, s->>'slug' into v_fee, v_k from jsonb_array_elements(v_svc) s
       where s->'spec'->>'role' = 'platform' and s->'spec'->>'platform' = v_p limit 1;
      v_lines := v_lines || jsonb_build_object('slug', v_k, 'kind', 'platform', 'basis', 'month',
        'label', 'Additional platform · ' || (v_names->>v_p), 'detail', '[]'::jsonb, 'qty', 1, 'rate', v_fee);
    end loop;

    -- Extra contents, at the plan's whole saving, to the nearest RM 10.
    if jsonb_typeof(p_sel->'extra') = 'object' then
      for v_k in select k from jsonb_object_keys(p_sel->'extra') k
                 order by array_position(array['static-graphic', 'gif', 'carousel', 'reels-30', 'reels-60', 'short-video-120'], k) nulls last, k loop
        if coalesce(p_sel->'extra'->>v_k, '') !~ '^[0-9]{1,2}$' then return jsonb_build_object('error', 'bad-extra'); end if;
        v_q := (p_sel->'extra'->>v_k)::int;
        continue when v_q = 0;
        v_s := public.quote_svc(p_snap, v_k);
        if v_s is null or v_s->'spec'->>'role' is distinct from 'content' or v_s->>'rate' is null then
          return jsonb_build_object('error', 'bad-extra');
        end if;
        v_lines := v_lines || jsonb_build_object('slug', v_k, 'kind', 'extra', 'basis', 'month',
          'label', 'Additional ' || lower(left(case v_s->'spec'->>'kind' when 'graphic' then 'Graphic (Static)' when 'carousel' then 'Graphic (Carousel)'
                        when 'gif' then 'Graphic (GIF)' else v_s->>'name' end, 1)) || substr(case v_s->'spec'->>'kind' when 'graphic' then 'Graphic (Static)' when 'carousel' then 'Graphic (Carousel)'
                        when 'gif' then 'Graphic (GIF)' else v_s->>'name' end, 2),
          'detail', '[]'::jsonb, 'qty', v_q,
          'rate', round((v_s->>'rate')::numeric * v_factor / 10) * 10);
        v_tot := v_tot + v_q;
      end loop;
    end if;
    v_tot := v_tot + v_contents;

    -- Translation, a content for each language after the first.
    select coalesce(array_agg(l order by array_position(array['en', 'zh', 'ms'], l)), '{}') into v_langs
      from (select distinct l from jsonb_array_elements_text(coalesce(p_sel->'langs', '[]'::jsonb)) l
             where l in ('en', 'zh', 'ms')) z;
    if coalesce((p_sel->>'translate')::boolean, false) and array_length(v_langs, 1) > 1 then
      v_s := (select s from jsonb_array_elements(v_svc) s where s->'spec'->>'role' = 'language'
               and coalesce((s->>'active')::boolean, true) limit 1);
      if v_s is null then return jsonb_build_object('error', 'no-translation'); end if;
      foreach v_l in array v_langs[2:] loop
        v_lines := v_lines || jsonb_build_object('slug', v_s->>'slug', 'kind', 'translation', 'basis', 'month',
          'label', 'Translation into ' || (v_lname->>v_l) || ', per content piece', 'detail', '[]'::jsonb,
          'qty', v_tot, 'rate', (v_s->>'rate')::numeric);
      end loop;
    end if;
  else
    -- No plan: each platform managed at its own fee.
    foreach v_p in array v_plats loop
      select (s->>'rate')::numeric, s->>'slug' into v_fee, v_k from jsonb_array_elements(v_svc) s
       where s->'spec'->>'role' = 'platform' and s->'spec'->>'platform' = v_p limit 1;
      v_lines := v_lines || jsonb_build_object('slug', v_k, 'kind', 'platform', 'basis', 'month',
        'label', 'Account management · ' || (v_names->>v_p), 'detail', '[]'::jsonb, 'qty', 1, 'rate', v_fee);
    end loop;
  end if;

  -- The advertising budget past what the plan covers.
  if coalesce(p_sel->>'budget', '0') !~ '^-?[0-9]{1,7}$' then return jsonb_build_object('error', 'bad-budget'); end if;
  v_budget := (coalesce(p_sel->>'budget', '0'))::numeric;
  if v_budget < 0 then
    v_req := v_req || 'budget'::text;
  elsif v_budget > v_cover then
    v_cost := public.quote_ads_cost(p_snap, v_budget);
    if v_cost is null then
      v_req := v_req || 'budget'::text;
    elsif v_cover > 0 then
      v_lines := v_lines || jsonb_build_object('slug', null, 'kind', 'ads', 'basis', 'month',
        'label', 'Advertising budget coverage, up to ' || public.quote_rm(v_budget), 'detail', '[]'::jsonb,
        'qty', 1, 'rate', v_cost - public.quote_ads_cost(p_snap, v_cover));
    else
      select s into v_s from jsonb_array_elements(v_svc) s
       where s->'spec'->>'role' = 'ads' and coalesce((s->>'active')::boolean, true)
       order by ((s->'spec'->>'budget')::numeric >= v_budget) desc,
                case when (s->'spec'->>'budget')::numeric >= v_budget then (s->'spec'->>'budget')::numeric
                     else -(s->'spec'->>'budget')::numeric end
       limit 1;
      v_from := least(v_budget, (v_s->'spec'->>'budget')::numeric);
      v_lines := v_lines || jsonb_build_object('slug', v_s->>'slug', 'kind', 'ads', 'basis', 'month',
        'label', 'Meta advertising · advertising budget up to ' || public.quote_rm((v_s->'spec'->>'budget')::numeric),
        'detail', coalesce((select jsonb_agg(d) from unnest(string_to_array(coalesce(v_text->>'ads_included', ''), E'\n')) d
                             where btrim(d) <> ''), '[]'::jsonb),
        'qty', 1, 'rate', (v_s->>'rate')::numeric);
      if v_budget > (v_s->'spec'->>'budget')::numeric then
        v_lines := v_lines || jsonb_build_object('slug', null, 'kind', 'ads', 'basis', 'month',
          'label', 'Advertising budget coverage, up to ' || public.quote_rm(v_budget), 'detail', '[]'::jsonb,
          'qty', 1, 'rate', v_cost - (v_s->>'rate')::numeric);
      end if;
    end if;
  end if;

  -- One-off items; a KOL campaign and a custom KOC list are quoted on request.
  if jsonb_typeof(p_sel->'once') = 'array' then
    for v_x in select * from jsonb_array_elements(p_sel->'once') loop
      if coalesce(v_x->>'qty', '') !~ '^[0-9]{1,3}$' or (v_x->>'qty')::int < 1 then
        return jsonb_build_object('error', 'bad-once');
      end if;
      v_s := public.quote_svc(p_snap, v_x->>'slug');
      if v_s is null or coalesce(v_s->'spec'->>'role', '') not in ('content', 'verify', 'koc', 'kol', 'addon') then
        return jsonb_build_object('error', 'bad-once');
      end if;
      if v_s->>'rate' is null then v_req := v_req || (v_s->>'name')::text; continue; end if;
      v_lines := v_lines || jsonb_build_object('slug', v_s->>'slug', 'kind', v_s->'spec'->>'role', 'basis', 'once',
        'label', case v_s->'spec'->>'kind' when 'graphic' then 'Graphic (Static)' when 'carousel' then 'Graphic (Carousel)'
                        when 'gif' then 'Graphic (GIF)' else v_s->>'name' end, 'detail', '[]'::jsonb, 'qty', (v_x->>'qty')::int, 'rate', (v_s->>'rate')::numeric);
    end loop;
  end if;

  if jsonb_array_length(v_lines) = 0 and array_length(v_req, 1) is null then
    return jsonb_build_object('error', 'empty');
  end if;

  select coalesce(bool_or(l->>'basis' = 'month'), false) into v_month from jsonb_array_elements(v_lines) l;
  if v_month and v_term = 1 then return jsonb_build_object('error', 'bad-term'); end if;
  v_pct := case when not v_month then 0
                when v_term <= 3 then coalesce((v_set->>'term_1_3')::numeric, 0)
                when v_term <= 5 then coalesce((v_set->>'term_4_5')::numeric, 0)
                when v_term <= 11 then coalesce((v_set->>'term_6_11')::numeric, 0)
                when v_term <= 17 then coalesce((v_set->>'term_12_23')::numeric, 0)
                when v_term <= 23 then coalesce((v_set->>'term_18_23')::numeric, (v_set->>'term_12_23')::numeric, 0)
                else coalesce((v_set->>'term_24')::numeric, 0) end;
  -- The figures, from the one calculation every quotation and letter shares.
  v_qtot := public.quote_totals(v_lines, v_term, v_pct, v_sst_pct);

  return jsonb_build_object(
    'lines', (select jsonb_agg(l || jsonb_build_object('amount', round((l->>'qty')::numeric * (l->>'rate')::numeric, 2)))
                from jsonb_array_elements(v_lines) l),
    'on_request', to_jsonb(v_req),
    'extra_rates', v_hint,
    'totals', jsonb_build_object(
      'term', v_term, 'term_pct', v_pct, 'sst_pct', v_sst_pct, 'budget', greatest(v_budget, 0),
      'month', v_qtot->'month', 'once', v_qtot->'once', 'commitment', v_qtot->'commitment'));
end $$;
revoke all on function public.quote_price(jsonb, jsonb) from public, anon, authenticated;

-- END OF QUOTATION WORDS FOR A CLIENT ---------------------------------------

-- ===========================================================================
-- BILLING CONTACT READ WITH THE RECORD — `client_billing` names a missing
-- billing contact too (2026-10-27)
-- ===========================================================================
-- WHY (the user, 2026-10-27): a client's record drew "Billing contact" in
-- its Billing details missing line for a second, then took it away. The
-- page worked the contact out from the client's contacts, which arrive
-- after the record is drawn, so every record opened read the contact as
-- missing until they did.
--
-- WHAT IT CHANGES
--   `client_billing` (restated whole from CLIENT SCOPE) adds
--   `bill_contact_id` to `billing_missing` where no billing contact stands:
--   neither the contact chosen nor a main contact, live, as
--   `clients_active_billing` holds the move into Active. The page reads it
--   until the contacts arrive, then reads the contacts as before. Nothing
--   else moves: the same columns, to the same people.
--
-- ORDER: this file (connector), then the page. An old page reads the list
-- as before and never asks for the contact by this name.
--
-- ROLLBACK: run client_billing from CLIENT SCOPE again.
-- ===========================================================================

create or replace function public.client_billing(p_ids uuid[] default null)
returns table (id uuid, legal_name text, company_no text, company_no_old text, tin text,
               sst_no text, bill_contact_id uuid, bill_contact text, bill_contact_email text,
               bill_contact_phone text, finance_email text, billing_address text,
               billing_missing text[])
language sql stable security definer set search_path = public as $$
  select c.id,
         case when p.bill or p.docs then c.legal_name end,
         case when p.bill then c.company_no end,
         case when p.bill then c.company_no_old end,
         case when p.bill then c.tin end,
         case when p.bill then c.sst_no end,
         case when p.bill then c.bill_contact_id end,
         case when p.bill then c.bill_contact end,
         case when p.bill then c.bill_contact_email end,
         case when p.bill then c.bill_contact_phone end,
         case when p.bill then c.finance_email end,
         case when p.bill or p.docs then c.billing_address end,
         array_remove(array[
           case when coalesce(btrim(c.legal_name), '') = '' then 'legal_name' end,
           case when coalesce(btrim(c.company_no), '') = '' then 'company_no' end,
           case when not exists (select 1 from public.client_contacts k
                                  where k.client_id = c.id and k.archived_at is null
                                    and (k.id = c.bill_contact_id or k.is_primary))
                then 'bill_contact_id' end,
           case when coalesce(btrim(c.billing_address), '') = '' then 'billing_address' end], null)
    from public.clients c,
         (select public.allowed('clients.billing', 'view') as bill,
                 public.register_may('client', 'work') as docs,
                 public.allowed('clients', 'view') as cv) p
   where (p.bill or p.docs or p.cv)
     and (p_ids is null or c.id = any(p_ids))
     and public.client_seen(c.id, 'view')
$$;
revoke all on function public.client_billing(uuid[]) from public, anon;
grant execute on function public.client_billing(uuid[]) to authenticated;

-- END OF BILLING CONTACT READ WITH THE RECORD -------------------------------

-- ===========================================================================
-- DEMO ACCESS — a PIN typed in the sign-in's email box opens the console on
-- sample data (2026-10-27)
-- ===========================================================================
-- WHY (the user, 2026-10-27): "enter this pin will allow me access however
-- it will only show all fake populated data unable to add anything … so i
-- can sell ppl this portal"; "Just enter in the email input"; "the demo act
-- as one setting to control the pin (input or change) and active /
-- inactive".
--
-- WHAT IT CHANGES
--   One flag (`app_flags` key `demo`, on or off) and one secret
--   (`app_secrets` key `demo_pin`, the PIN as a bcrypt hash, never the PIN).
--   `demo_state()` answers whether it is on and whether a PIN is set, for
--     Business settings (`team.settings`).
--   `demo_set(p_on, p_pin)` turns it on or off and sets a new PIN (4 to 8
--     digits; empty keeps the one held), `team.settings` at Work; refused
--     `denied`, `bad-pin`, `no-pin` (on with none held). Filed
--     `team.changed` under Demo access, from and to, never the PIN.
--   `demo_pin_ok(p_pin)` (anon) answers true only while it is on and the
--     PIN is right. Wrong ones are counted as a link's passcode is
--     (`link_passcode`, kind `demo`): five within 15 minutes lock that
--     address out, longer each time, and the answer is false either way.
--   Nothing here reads or writes a client, a colleague or any record: the
--   demo's data lives in the visitor's browser alone (demo/engine.js).
--
-- ORDER: 2026-10-07-function-hygiene.sql again (its `open_to_anon` now
-- names `demo_pin_ok`), then this file (connector), then the pages. An old
-- page never asks.
--
-- ROLLBACK (SQL Editor):
--   drop function if exists public.demo_pin_ok(text);
--   drop function if exists public.demo_set(boolean, text);
--   drop function if exists public.demo_state();
--   delete from public.app_flags where key = 'demo';
--   delete from public.app_secrets where key = 'demo_pin';
-- ===========================================================================

create or replace function public.demo_state()
returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.ops_granted('team.settings', 'work') then return jsonb_build_object('error', 'denied'); end if;
  return jsonb_build_object(
    'on', coalesce((select f.on_now from public.app_flags f where f.key = 'demo'), false),
    'pin_set', exists (select 1 from public.app_secrets s where s.key = 'demo_pin' and coalesce(s.value, '') <> ''),
    'set_by', (select f.set_by from public.app_flags f where f.key = 'demo'),
    'set_at', (select f.set_at from public.app_flags f where f.key = 'demo'));
end $$;
revoke all on function public.demo_state() from public, anon;
grant execute on function public.demo_state() to authenticated;

create or replace function public.demo_set(p_on boolean, p_pin text default null)
returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  v_me public.team_members;
  v_was boolean;
  v_pin text := btrim(coalesce(p_pin, ''));
  v_held boolean;
  v_bits text[] := '{}';
begin
  if not public.ops_granted('team.settings', 'work') then return jsonb_build_object('error', 'denied'); end if;
  v_me := public.ops_me();
  if v_pin <> '' and v_pin !~ '^[0-9]{4,8}$' then return jsonb_build_object('error', 'bad-pin'); end if;
  v_held := exists (select 1 from public.app_secrets s where s.key = 'demo_pin' and coalesce(s.value, '') <> '');
  if coalesce(p_on, false) and v_pin = '' and not v_held then return jsonb_build_object('error', 'no-pin'); end if;
  v_was := coalesce((select f.on_now from public.app_flags f where f.key = 'demo'), false);
  if v_pin <> '' then
    insert into public.app_secrets (key, value) values ('demo_pin', crypt(v_pin, gen_salt('bf', 8)))
    on conflict (key) do update set value = excluded.value, updated_at = now();
    v_bits := v_bits || 'PIN changed'::text;
  end if;
  if v_was is distinct from coalesce(p_on, false) then
    v_bits := array['Demo access: ' || case when v_was then 'On' else 'Off' end || ' → ' || case when p_on then 'On' else 'Off' end] || v_bits;
  end if;
  insert into public.app_flags as f (key, on_now, set_by, set_at)
  values ('demo', coalesce(p_on, false), coalesce(v_me.name, v_me.email), now())
  on conflict (key) do update set on_now = excluded.on_now,
    set_by = case when f.on_now is distinct from excluded.on_now or v_pin <> '' then excluded.set_by else f.set_by end,
    set_at = case when f.on_now is distinct from excluded.on_now or v_pin <> '' then excluded.set_at else f.set_at end;
  if array_length(v_bits, 1) > 0 then
    insert into public.activity_log (actor, action, subject, detail)
    values (coalesce(v_me.name, v_me.email, 'admin'), 'team.changed', 'Demo access', array_to_string(v_bits, ' · '));
  end if;
  return public.demo_state();
end $$;
revoke all on function public.demo_set(boolean, text) from public, anon;
grant execute on function public.demo_set(boolean, text) to authenticated;

create or replace function public.demo_pin_ok(p_pin text)
returns boolean
language plpgsql security definer set search_path = public, extensions as $$
declare
  v_hash text;
begin
  if not coalesce((select f.on_now from public.app_flags f where f.key = 'demo'), false) then return false; end if;
  select s.value into v_hash from public.app_secrets s where s.key = 'demo_pin';
  if coalesce(v_hash, '') = '' or coalesce(btrim(p_pin), '') !~ '^[0-9]{4,8}$' then return false; end if;
  return public.link_passcode('demo', 'demo', v_hash, crypt(btrim(p_pin), v_hash)) = 'ok';
end $$;
grant execute on function public.demo_pin_ok(text) to anon, authenticated;

-- END OF DEMO ACCESS ---------------------------------------------------------

select public.functions_tidy();

-- ===========================================================================
-- CREATOR CODES COUNTED — a wrong creator access code is counted against the
-- caller's address, five within 15 minutes locking it out (2026-10-27)
-- ===========================================================================
-- WHY (the user, 2026-10-27: "What if someone keeps trying on one
-- browser?"): every other code a page takes (a link's passcode, /verify/,
-- the demo PIN) was counted; a creator's eight-character code was not, so
-- `get_creator` answered any number of guesses. Once the creator's page
-- checks a code by itself at its eighth character, the server must count.
--
-- WHAT IT CHANGES
--   `creator_code_try(p_code)` (internal) reads an eight-character code and
--     answers its creator (active or not), or nothing, or the minutes a
--     locked caller has left. A wrong code is counted in `link_tries`
--     (kind `creator`, token `code`, the caller's address from
--     `request_ip()`): five within 15 minutes lock that address out for 15
--     minutes, then an hour, then a day where it is locked again within a
--     day of the last lock ending, as `link_passcode` does. While locked
--     nothing is looked up, the right code included. A right code changes
--     no count, so a creator holding one code cannot reset a guesser's.
--     No backstop across addresses: one held over every caller would let a
--     guesser lock every creator out. `privacy_retention` already clears
--     the rows after 30 days.
--   `get_creator` (now volatile) answers `locked` with `minutes`;
--   `creator_set_profiles` and the creator branch of `share_link_preview`
--     (now plpgsql, volatile) take the code through the same count, so
--     neither tells a right code from a wrong one beyond it.
--   `push_subscribe` is in the SQL Editor part
--     (2026-10-27-creator-codes-counted-editor.sql), since it holds a
--     delete the connector holds.
--
-- ORDER: this file (connector), then the editor part, then the pages. An
-- old page reads `locked` as a code not recognised.
--
-- ROLLBACK: get_creator, creator_set_profiles and share_link_preview as
-- schema.sql defined them before this banner, then in the SQL Editor:
--   drop function if exists public.creator_code_try(text);
--   delete from public.link_tries where kind = 'creator';
-- ===========================================================================

/* One eight-character code, counted. Answers the creator it opens (active
   or not), or nothing; `o_locked` is the minutes a locked caller has left. */
create or replace function public.creator_code_try(p_code text, out o_creator uuid, out o_locked integer)
language plpgsql security definer set search_path = public as $$
declare
  v_code text := upper(regexp_replace(coalesce(p_code, ''), '[^A-Za-z0-9]', '', 'g'));
  v_ip   text := public.request_ip();
  a      public.link_tries%rowtype;
begin
  if v_code !~ '^[A-Z0-9]{8}$' then return; end if;
  select * into a from public.link_tries t where t.kind = 'creator' and t.token = 'code' and t.ip = v_ip;
  if a.locked_until > now() then
    o_locked := greatest(1, ceil(extract(epoch from a.locked_until - now()) / 60))::integer;
    return;
  end if;
  select k.id into o_creator from public.creators k where k.access_code = v_code;
  if o_creator is not null then return; end if;

  insert into public.link_tries (kind, token, ip) values ('creator', 'code', v_ip)
  on conflict (kind, token, ip) do nothing;
  select * into a from public.link_tries t
   where t.kind = 'creator' and t.token = 'code' and t.ip = v_ip for update;
  if a.locked_until > now() then
    o_locked := greatest(1, ceil(extract(epoch from a.locked_until - now()) / 60))::integer;
    return;
  end if;
  a.fails := case when a.locked_until is not null or a.last_at < now() - interval '15 minutes'
                  then 1 else a.fails + 1 end;
  if a.fails >= 5 then
    a.strikes := case when a.struck_until > now() - interval '24 hours' then a.strikes + 1 else 1 end;
    a.locked_until := now() + case a.strikes when 1 then interval '15 minutes'
                                             when 2 then interval '1 hour'
                                             else interval '24 hours' end;
    a.struck_until := a.locked_until;
    o_locked := greatest(1, ceil(extract(epoch from a.locked_until - now()) / 60))::integer;
  else
    a.locked_until := null;
  end if;
  update public.link_tries t
     set fails = a.fails, last_at = now(), locked_until = a.locked_until,
         strikes = a.strikes, struck_until = a.struck_until
   where t.kind = 'creator' and t.token = 'code' and t.ip = v_ip;
end $$;
revoke all on function public.creator_code_try(text) from public, anon, authenticated;

/* The creator's page: a code opens its creator's bookings, a wrong one is
   counted against the caller (`creator_code_try`), and a caller locked out
   is answered `locked` with the minutes left, the right code included.
   Volatile now: it writes the count. */
create or replace function public.get_creator(p_code text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  cr     creators%rowtype;
  v_id   uuid;
  v_lock integer;
begin
  select t.o_creator, t.o_locked into v_id, v_lock from public.creator_code_try(p_code) t;
  if v_lock is not null then return jsonb_build_object('error', 'locked', 'minutes', v_lock); end if;
  select * into cr from creators where id = v_id;
  if not found then return jsonb_build_object('error', 'not-found'); end if;
  if not cr.active then return jsonb_build_object('error', 'inactive'); end if;

  return jsonb_build_object(
    /* Who they are to us: the name the team keyed, since when, and the
       profile links the client's selection page opens, which they may keep
       up to date themselves. Never `client_rate`: that is the client's
       price, not theirs to read. */
    'creator', jsonb_build_object('name', cr.name, 'code', cr.access_code,
      'since', cr.created_at,
      'profiles', coalesce((
        select jsonb_agg(jsonb_build_object('platform', p.platform, 'handle', p.handle, 'url', p.url)
                         order by p.platform, p.url)
          from creator_profiles p where p.creator_id = cr.id), '[]'::jsonb)),
    'bookings', coalesce((
      select jsonb_agg(b order by b->>'sort')
      from (
        select jsonb_build_object(
          'id', o.id,
          'sort', coalesce(o.visit_date::text, '9999') || c.title,
          'campaign', c.title,
          'campaign_zh', c.title_zh,
          'brand', cl.name,
          'brief', c.brief,
          'brief_zh', c.brief_zh,
          'deliverable', c.deliverable,
          'push_format', c.push_format,
          'platforms', o.platforms,
          /* NO RATE, AND NO CURRENCY. `campaign_options.rate` is what the
             client is quoted for this booking and carries our markup, so it
             is not the creator's to read and is certainly not "their fee";
             what a creator is paid is agreed with them and claimed on AP01,
             which the page links to once the work is approved. `currency`
             existed only to format that one figure and names the client's
             market, which is a fact about the client. */
          'state', o.state,
          'visit_date', o.visit_date,
          'visit_time', o.visit_time,
          'visit_location', o.visit_location,
          'visit_pic', o.visit_pic,
          'visit_pic_phone', o.visit_pic_phone,
          'tracking_no', o.tracking_no,
          'submission_due', o.submission_due,
          'planned_publish', o.planned_publish,
          'revision_round', o.revision_round,
          /* The open request's note, whoever made it: the client's through
             their page, the team's through the send-back (2026-09-27). A
             team round sent back before the record held it is in
             `drop_reason`. */
          'change_note', case when o.state = 'changes' then coalesce(
            (select r.note from public.option_reviews r
              where r.option_id = o.id and r.decision = 'changes' and r.undone_at is null
                and r.source = case when coalesce(o.changes_by, 'client') = 'team' then 'team' else 'client' end
              order by r.created_at desc limit 1),
            case when o.changes_by = 'team' then o.drop_reason end) end,
          /* Each placement's post and its numbers, and the period the team
             set to count them over: the creator fills in the link and the
             figures here (2026-09-27). */
          'posts', coalesce((
            select jsonb_agg(jsonb_build_object(
              'platform', pp.platform, 'post_url', pp.post_url,
              'published_at', pp.published_at,
              'measure_from', pp.measure_from, 'measure_to', pp.measure_to,
              'impressions', pp.impressions, 'engagements', pp.engagements,
              'views', pp.views, 'measured_at', pp.measured_at,
              'entered_by', pp.entered_by) order by pp.platform)
            from public.option_posts pp where pp.option_id = o.id), '[]'::jsonb),
          'caption', o.draft_caption,
          'submitted_at', o.submitted_at,
          'rating', o.creator_rating,
          'can_deliver', public.creator_can_deliver(o.state),
          'files', coalesce((
            select jsonb_agg(jsonb_build_object(
              'id', d.id, 'url', d.url, 'name', d.name, 'kind', d.kind,
              'bytes', d.bytes, 'round', d.round)
              order by d.uploaded_at)
            from campaign_deliverables d
             where d.option_id = o.id and d.removed_at is null), '[]'::jsonb)
        ) as b
        from campaign_options o
        join campaigns c on c.id = o.campaign_id
        join clients cl on cl.id = c.client_id
        where o.creator_id = cr.id
          and c.state <> 'draft'
          and o.state in ('confirmed', 'pending_visit', 'pending_delivery',
                          'pending_draft', 'submitted', 'reviewing', 'changes',
                          'scheduled', 'posted', 'completed', 'withdrawn', 'replaced')
      ) rows), '[]'::jsonb));
end $$;
grant execute on function public.get_creator(text) to anon, authenticated;

create or replace function public.creator_set_profiles(p_code text, p_profiles jsonb)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  cr     public.creators;
  v_id   uuid;
  v_lock integer;
begin
  select t.o_creator, t.o_locked into v_id, v_lock from public.creator_code_try(p_code) t;
  if v_lock is not null then return jsonb_build_object('error', 'locked', 'minutes', v_lock); end if;
  select * into cr from public.creators k where k.id = v_id and k.active;
  if cr.id is null then return jsonb_build_object('error', 'not-found'); end if;
  return public.profiles_replace(cr.id, p_profiles, cr.name, 'creator', 'creator.links_self');
end $$;
grant execute on function public.creator_set_profiles(text, jsonb) to anon, authenticated;

/* A link's preview. A creator's code is counted as the creator's page
   counts it (a locked caller is answered the plain title); the other kinds
   read as before. */
create or replace function public.share_link_preview(p_kind text, p_key text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_id   uuid;
  v_lock integer;
  v_out  jsonb;
begin
  if p_kind = 'creator' then
    if coalesce(p_key, '') !~ '^[A-Za-z0-9]{8}$' then return '{}'::jsonb; end if;
    select t.o_creator, t.o_locked into v_id, v_lock from public.creator_code_try(p_key) t;
    if v_id is null then return '{}'::jsonb; end if;
    select case when count(*) = 1 then jsonb_strip_nulls(jsonb_build_object('brand', min(c.name), 'title', nullif(btrim(min(k.title)), ''))) end
      into v_out
      from public.creators cr
      join public.campaign_options o on o.creator_id = cr.id
       and o.state in ('confirmed', 'pending_visit', 'pending_draft', 'submitted', 'reviewing', 'changes', 'scheduled', 'posted')
      join public.campaigns k on k.id = o.campaign_id
      join public.clients c on c.id = k.client_id
     where cr.id = v_id and cr.active;
    return coalesce(v_out, '{}'::jsonb);
  end if;
  select case p_kind
    when 'which' then (
      select case
        when exists (select 1 from public.campaigns k where k.access_token = p_key) then jsonb_build_object('kind', 'campaign')
        when exists (select 1 from public.clients c where c.script_key = p_key) then jsonb_build_object('kind', 'script')
      end
       where p_key ~ '^[A-Za-z0-9_-]{6,64}$')
    when 'script' then (
      select jsonb_strip_nulls(jsonb_build_object('brand', c.name))
        from public.clients c
       where p_key ~ '^[A-Za-z0-9_-]{6,64}$'
         and c.script_key = p_key and c.active
         and exists (select 1 from public.video_scripts s where s.client_id = c.id and s.status = 'shared')
       limit 1)
    when 'campaign' then (
      select jsonb_strip_nulls(jsonb_build_object('brand', c.name, 'title', nullif(btrim(k.title), '')))
        from public.campaigns k
        join public.clients c on c.id = k.client_id
       where p_key ~ '^[A-Za-z0-9_-]{6,64}$'
         and k.access_token = p_key
         and coalesce(k.passcode, '') = '' and k.state <> 'draft'
         and coalesce(c.stage, '') <> 'past'
       limit 1)
  end into v_out;
  return coalesce(v_out, '{}'::jsonb);
end $$;
revoke all on function public.share_link_preview(text, text) from public;
grant execute on function public.share_link_preview(text, text) to anon, authenticated;

-- END OF CREATOR CODES COUNTED -----------------------------------------------

select public.functions_tidy();

-- ===========================================================================
-- CREATOR CODES COUNTED, THE SQL EDITOR PART — turning notifications on with
-- a creator's code counts a wrong code as the creator's page does
-- (2026-10-27)
-- ===========================================================================
-- WHY: 2026-10-27-creator-codes-counted.sql counts wrong creator codes in
-- `get_creator`, `creator_set_profiles` and `share_link_preview`.
-- `push_subscribe` answered a creator's code too (`not-found` or not), and
-- it holds a delete the connector holds, so it runs here, after that file.
--
-- WHAT IT CHANGES
--   `push_subscribe` takes a creator's code through `creator_code_try`
--   before anything else: a caller locked out is answered `locked` with
--   `minutes`, and a wrong code is counted. Everything else is as BACKEND
--   REVIEW REST left it.
--
-- ORDER: after 2026-10-27-creator-codes-counted.sql. Safe to run twice.
-- Rollback: push_subscribe as BACKEND REVIEW REST defines it.
-- ===========================================================================

create or replace function public.push_subscribe(
  p_audience text, p_ref text, p_endpoint text, p_p256dh text, p_auth text, p_lang text default 'en')
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_target uuid;
  v_lang   text := case when p_lang = 'zh' then 'zh' else 'en' end;
  v_lock   integer;
begin
  if not public.push_endpoint_ok(p_endpoint)
     or coalesce(length(p_p256dh), 0) not between 80 and 100
     or coalesce(length(p_auth), 0) not between 16 and 32 then
    return jsonb_build_object('error', 'bad-subscription');
  end if;
  if p_audience not in ('team', 'client', 'creator') then
    return jsonb_build_object('error', 'bad-audience');
  end if;
  if p_audience = 'creator' then
    select t.o_creator, t.o_locked into v_target, v_lock from public.creator_code_try(p_ref) t;
    if v_lock is not null then return jsonb_build_object('error', 'locked', 'minutes', v_lock); end if;
  end if;
  v_target := public.push_target(p_audience, p_ref);
  if v_target is null then
    return jsonb_build_object('error', case when p_audience = 'team' then 'not-team' else 'not-found' end);
  end if;

  if not exists (select 1 from public.push_subscriptions s where s.endpoint = p_endpoint and s.target = v_target) then
    perform pg_advisory_xact_lock(hashtext('push_subscribe:' || v_target::text));
    if (select count(*) from public.push_subscriptions s
         where s.target = v_target and s.created_at > now() - interval '1 hour') >= 5
       or (select count(*) from public.push_subscriptions s where s.target = v_target) >= 20 then
      return jsonb_build_object('error', 'too-many');
    end if;
  end if;

  if p_audience in ('team', 'creator') then
    delete from public.push_subscriptions s
     where s.endpoint = p_endpoint and s.audience = p_audience and s.target <> v_target;
  end if;
  insert into public.push_subscriptions
    (endpoint, p256dh, auth, audience, team_member_id, campaign_id, creator_id, lang)
  values (p_endpoint, p_p256dh, p_auth, p_audience,
          case when p_audience = 'team' then v_target end,
          case when p_audience = 'client' then v_target end,
          case when p_audience = 'creator' then v_target end, v_lang)
  on conflict (endpoint, target) do update
     set lang = excluded.lang, seen_at = now();
  update public.push_subscriptions s set p256dh = p_p256dh, auth = p_auth
   where s.endpoint = p_endpoint and (s.p256dh <> p_p256dh or s.auth <> p_auth);
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.push_subscribe(text, text, text, text, text, text) from public;
grant execute on function public.push_subscribe(text, text, text, text, text, text) to anon, authenticated;

-- END OF CREATOR CODES COUNTED, THE SQL EDITOR PART ------------------------

select public.functions_tidy();

-- ===========================================================================
-- OVERDUE INVOICE REMINDERS — overdue invoices read from Bukku, and a
-- reminder emailed to a client by hand (2026-10-28)
-- ===========================================================================
-- WHY (the user, 2026-10-28: "pull those overdues data from bukku and inside
-- Portal and selectively send by users"; Bukku's own reminder is "fully
-- bukku labeled ... unprofessional"; replies go to einvoice@; the mockups
-- approved, WhatsApp held back): the team chased overdue invoices through a
-- Claude page, a Jotform letter and the Resend connector.
--
-- WHAT IT ADDS
--   * `invoice_emails`: every reminder sent, to whom, by whom, the invoices
--     it named (Bukku's ids, numbers and amounts as read at the send), its
--     words as sent and what Resend said of it. Kept when the client goes
--     (the link set null). Supplier emails keep their own table; Resend's
--     webhook (`supplier_email_status`, restated below) now finds an email
--     in either, so delivery is recorded in one function.
--   * `invoice_email_template`: the reminder's two subjects, its message
--     (holding `{invoices}`, where the table of invoices goes), the legal
--     note and the disclaimer; seeded once, edited at Business settings
--     (`invoice_email_template_save`, filed `team.changed` under Overdue
--     reminder), read at Clients: Billing View.
--   * `invoice_scope()` (Clients: Billing View): who is asking, whether they
--     see every client (`all`, so a Bukku contact linked to no client is
--     theirs too) and may send (Clients: Billing Work), and each Bukku
--     contact linked to a client they see, with that client's recipient:
--     the billing contact (else the main contact) with their salutation,
--     its email, the finance email to copy and the registered name.
--   * `invoice_reminders(p_contacts)` (Clients: Billing View): the reminders
--     sent to those Bukku contacts, newest first, held to the same scope.
--   * `invoice_email_begin` and `invoice_email_done`, the service role's
--     alone: bukku-sync calls them after checking the colleague through
--     `invoice_scope` and reading the invoices from Bukku itself, so a page
--     can never file a reminder or name its figures. Begin takes the
--     contact's lock first, so two colleagues pressing Send together send
--     once (`sending`), and refuses `recent` within `wa_repeat_hours`
--     unless asked again.
--
-- ORDER: this file (connector), then bukku-sync and supplier-mail (both
-- with _shared/mail.ts), then the pages. A page served before draws no
-- Overdue invoices. Safe to run twice.
--
-- ROLLBACK: supplier_email_status as schema.sql defined it before this
-- banner, then in the SQL Editor:
--   drop function if exists public.invoice_email_done(uuid, text, text, text);
--   drop function if exists public.invoice_email_begin(uuid, uuid, bigint, text, text, jsonb, boolean, text, text, boolean);
--   drop function if exists public.invoice_reminders(bigint[]);
--   drop function if exists public.invoice_scope();
--   drop function if exists public.invoice_recipient(uuid);
--   drop function if exists public.invoice_email_template_save(text, text, text, text, text);
--   drop function if exists public.invoice_email_template_get();
--   drop table if exists public.invoice_email_template;
--   drop table if exists public.invoice_emails;
-- ===========================================================================

create table if not exists public.invoice_emails (
  id            uuid primary key default gen_random_uuid(),
  client_id     uuid references public.clients(id) on delete set null,
  bukku_contact bigint not null,
  client_name   text not null,
  invoices      jsonb not null,
  to_email      text not null,
  cc_email      text,
  subject       text not null,
  body          text not null,
  sent_by       uuid references public.team_members(id) on delete set null,
  created_at    timestamptz not null default now(),
  status        text not null default 'sending'
                check (status in ('sending', 'sent', 'failed', 'unknown', 'delivered', 'opened', 'bounced', 'complained')),
  provider_id   text,
  error         text,
  sent_at       timestamptz,
  delivered_at  timestamptz,
  opened_at     timestamptz,
  bounced_at    timestamptz
);
create index if not exists invoice_emails_contact_idx on public.invoice_emails (bukku_contact, created_at desc);
create index if not exists invoice_emails_client_idx on public.invoice_emails (client_id, created_at desc);
create unique index if not exists invoice_emails_provider_idx on public.invoice_emails (provider_id) where provider_id is not null;
alter table public.invoice_emails enable row level security;
revoke all on table public.invoice_emails from public, anon, authenticated;

create table if not exists public.invoice_email_template (
  id            int primary key default 1 check (id = 1),
  subject_one   text not null,
  subject_many  text not null,
  body          text not null,
  legal         text not null default '',
  disclaimer    text not null default '',
  updated_at    timestamptz not null default now(),
  updated_by    uuid references public.team_members(id) on delete set null
);
alter table public.invoice_email_template enable row level security;
revoke all on table public.invoice_email_template from public, anon, authenticated;

insert into public.invoice_email_template (id, subject_one, subject_many, body, legal, disclaimer)
select 1, 'Payment reminder · Invoice {invoice no}', 'Payment reminder · {count} overdue invoices',
  E'Dear {contact name},\n\nThis is a reminder that payment of {total} for {client} is now overdue.\n\n{invoices}\n\nWe would be grateful if payment could be arranged at your earliest convenience. If payment has already been made, please disregard this email.\n\nShould you have any questions, please reply to this email.\n\nThank you for your continued support.\n\n{sign off},\nADspace Finance',
  'Legal note: All services rendered will be invoiced accordingly unless a written cancellation is provided and acknowledged in advance. All invoices must be settled promptly to avoid overdue interest charges.',
  'This email and any attachment are private and confidential and intended solely for the addressee. If you have received it in error, please notify einvoice@adspacestudios.com and delete it. Any use, copying or disclosure by anyone else is not permitted.'
where not exists (select 1 from public.invoice_email_template);

/* Who a client's reminder goes to: the billing contact, else the live main
   contact, with their salutation; the finance email to copy where it
   differs; the registered name, else the brand. Internal. */
create or replace function public.invoice_recipient(p_client uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  c public.clients;
  k public.client_contacts;
begin
  select * into c from public.clients x where x.id = p_client;
  if c.id is null then return null; end if;
  select * into k from public.client_contacts x
   where x.client_id = c.id and x.archived_at is null and (x.id = c.bill_contact_id or x.is_primary)
   order by (x.id = c.bill_contact_id) desc limit 1;
  return jsonb_build_object(
    'name', nullif(btrim(concat_ws(' ', nullif(btrim(coalesce(k.salutation, '')), ''), btrim(coalesce(k.name, '')))), ''),
    'email', nullif(btrim(coalesce(k.email, '')), ''),
    'cc', case when nullif(btrim(coalesce(c.finance_email, '')), '') is not null
                and lower(btrim(c.finance_email)) is distinct from lower(btrim(coalesce(k.email, '')))
               then btrim(c.finance_email) end,
    'company', coalesce(nullif(btrim(coalesce(c.legal_name, '')), ''), c.name));
end $$;
revoke all on function public.invoice_recipient(uuid) from public, anon, authenticated;

create or replace function public.invoice_scope()
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
begin
  if me.id is null or not public.allowed('clients.billing', 'view') then
    return jsonb_build_object('error', 'denied');
  end if;
  return jsonb_build_object('ok', true,
    'me', jsonb_build_object('id', me.id, 'name', me.name),
    'all', public.client_scope_free('view'),
    'send', public.allowed('clients.billing', 'work'),
    'links', coalesce((
      select jsonb_agg(jsonb_build_object('contact', l.contact_id, 'client', c.id, 'name', c.name, 'code', c.client_code,
               'slug', c.slug, 'stage', c.stage, 'to', public.invoice_recipient(c.id)) order by c.name)
        from (select distinct on (x.contact_id) x.contact_id, x.client_id
                from (select b.contact_id, b.record_id as client_id, 0 as pref
                        from public.bukku_links b where b.kind = 'client'
                      union all
                      select b.contact_id, s.client_id, 1
                        from public.bukku_links b join public.suppliers s on s.id = b.record_id
                       where b.kind = 'supplier' and s.client_id is not null) x
               order by x.contact_id, x.pref) l
        join public.clients c on c.id = l.client_id
       where public.client_seen(c.id, 'view')), '[]'::jsonb));
end $$;
revoke all on function public.invoice_scope() from public, anon;
grant execute on function public.invoice_scope() to authenticated;

create or replace function public.invoice_reminders(p_contacts bigint[])
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  v_all boolean;
begin
  if me.id is null or not public.allowed('clients.billing', 'view') then
    return jsonb_build_object('error', 'denied');
  end if;
  v_all := public.client_scope_free('view');
  return jsonb_build_object('ok', true, 'rows', coalesce((
    select jsonb_agg(r order by (r->>'at') desc) from (
      select jsonb_build_object('id', e.id, 'contact', e.bukku_contact, 'client', e.client_id,
               'invoices', e.invoices, 'to', e.to_email, 'cc', e.cc_email, 'subject', e.subject,
               'status', e.status, 'error', e.error, 'at', e.created_at, 'delivered_at', e.delivered_at,
               'opened_at', e.opened_at, 'bounced_at', e.bounced_at, 'by', m.name) as r
        from public.invoice_emails e
        left join public.team_members m on m.id = e.sent_by
       where e.bukku_contact = any(coalesce(p_contacts, '{}'::bigint[]))
         and (case when e.client_id is null then v_all else public.client_seen(e.client_id, 'view') end)
       order by e.created_at desc
       limit 500) q), '[]'::jsonb));
end $$;
revoke all on function public.invoice_reminders(bigint[]) from public, anon;
grant execute on function public.invoice_reminders(bigint[]) to authenticated;

create or replace function public.invoice_email_template_get()
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  t public.invoice_email_template;
begin
  if (public.ops_me()).id is null or not (public.allowed('clients.billing', 'view') or public.ops_granted('team.settings', 'view')) then
    return jsonb_build_object('error', 'denied');
  end if;
  select * into t from public.invoice_email_template x where x.id = 1;
  return jsonb_build_object('ok', true, 'subject_one', t.subject_one, 'subject_many', t.subject_many, 'body', t.body,
    'legal', t.legal, 'disclaimer', t.disclaimer, 'updated_at', t.updated_at,
    'updated_by', (select m.name from public.team_members m where m.id = t.updated_by));
end $$;
revoke all on function public.invoice_email_template_get() from public, anon;
grant execute on function public.invoice_email_template_get() to authenticated;

create or replace function public.invoice_email_template_save(p_subject_one text, p_subject_many text, p_body text,
  p_legal text, p_disclaimer text)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me  public.team_members := public.ops_me();
  t   public.invoice_email_template;
  v_1 text := btrim(regexp_replace(coalesce(p_subject_one, ''), '\s+', ' ', 'g'));
  v_n text := btrim(regexp_replace(coalesce(p_subject_many, ''), '\s+', ' ', 'g'));
  v_b text := btrim(replace(coalesce(p_body, ''), E'\r', ''));
  v_l text := btrim(regexp_replace(coalesce(p_legal, ''), '\s+', ' ', 'g'));
  v_d text := btrim(regexp_replace(coalesce(p_disclaimer, ''), '\s+', ' ', 'g'));
  moved text[] := '{}';
begin
  if me.id is null or not public.ops_granted('team.settings', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if length(v_1) < 2 or length(v_1) > 200 or length(v_n) < 2 or length(v_n) > 200 then return jsonb_build_object('error', 'bad-subject'); end if;
  if length(v_b) < 2 or length(v_b) > 5000 then return jsonb_build_object('error', 'bad-body'); end if;
  if v_b !~* '\{\s*invoices\s*\}' then return jsonb_build_object('error', 'no-invoices'); end if;
  if length(v_l) > 1000 or length(v_d) > 1000 then return jsonb_build_object('error', 'too-long'); end if;
  select * into t from public.invoice_email_template x where x.id = 1 for update;
  if t.subject_one is distinct from v_1 then moved := moved || ('Subject, one invoice: ' || t.subject_one || ' → ' || v_1); end if;
  if t.subject_many is distinct from v_n then moved := moved || ('Subject, several invoices: ' || t.subject_many || ' → ' || v_n); end if;
  if t.body is distinct from v_b then moved := moved || 'Message'::text; end if;
  if t.legal is distinct from v_l then moved := moved || 'Legal note'::text; end if;
  if t.disclaimer is distinct from v_d then moved := moved || 'Disclaimer'::text; end if;
  if array_length(moved, 1) is null then return jsonb_build_object('ok', true); end if;
  update public.invoice_email_template x set subject_one = v_1, subject_many = v_n, body = v_b, legal = v_l,
    disclaimer = v_d, updated_at = now(), updated_by = me.id where x.id = 1;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'team.changed', 'Overdue reminder', array_to_string(moved, ' · '));
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.invoice_email_template_save(text, text, text, text, text) from public, anon;
grant execute on function public.invoice_email_template_save(text, text, text, text, text) to authenticated;

/* An amount as the portal writes it: RM or S$, two decimals, the sign
   held to its figure (a no-break space), so a line never parts them. */
create or replace function public.invoice_money(p_amount numeric, p_currency text)
returns text
language sql immutable set search_path = public as $$
  select case upper(coalesce(p_currency, 'MYR')) when 'MYR' then 'RM' when 'SGD' then 'S$' else upper(p_currency) end
         || chr(160) || to_char(round(coalesce(p_amount, 0), 2), 'FM999,999,999,990.00')
$$;
revoke all on function public.invoice_money(numeric, text) from public, anon, authenticated;

/* A reminder filed before it goes (bukku-sync, the service role, after it
   checked the colleague through invoice_scope and read the invoices from
   Bukku itself). The contact's lock is taken first: a send already going
   to it answers `sending`, one made within the window `recent` unless
   asked again. The words are the colleague's, every {field} filled here. */
create or replace function public.invoice_email_begin(p_actor uuid, p_client uuid, p_contact bigint, p_name text,
  p_email text, p_invoices jsonb, p_cc boolean, p_subject text, p_body text, p_again boolean default false)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me     public.team_members;
  t      public.invoice_email_template;
  rcp    jsonb;
  inv    jsonb;
  hours  numeric;
  r      public.invoice_emails;
  v_n    int;
  v_to   text;
  v_cc   text;
  v_who  text;
  v_co   text;
  v_tot  text;
  v_nos  text;
  v_list text[];
  v_vals jsonb;
  v_s    text;
  v_b    text;
  v_id   uuid;
begin
  select * into me from public.team_members x where x.id = p_actor and x.active;
  if me.id is null then return jsonb_build_object('error', 'denied'); end if;
  if p_contact is null or p_contact <= 0 then return jsonb_build_object('error', 'bad-request'); end if;
  if jsonb_typeof(p_invoices) <> 'array' or jsonb_array_length(p_invoices) < 1 or jsonb_array_length(p_invoices) > 50 then
    return jsonb_build_object('error', 'bad-invoices');
  end if;
  for inv in select value from jsonb_array_elements(p_invoices) loop
    if coalesce(inv->>'number', '') !~ '^[A-Za-z0-9/._ -]{1,40}$' or coalesce(inv->>'currency', '') !~ '^[A-Z]{3}$'
       or (inv->>'amount') is null or (inv->>'amount')::numeric <= 0
       or (coalesce(inv->>'link', '') <> '' and inv->>'link' !~ '^https://[a-z0-9-]+\.bukku\.my/[A-Za-z0-9/_-]+$') then
      return jsonb_build_object('error', 'bad-invoices');
    end if;
  end loop;
  perform pg_advisory_xact_lock(hashtextextended('invoice-mail:' || p_contact::text, 0));
  select * into r from public.invoice_emails x
   where x.bukku_contact = p_contact and x.status = 'sending' and x.created_at > now() - interval '10 minutes'
   order by x.created_at desc limit 1;
  if r.id is not null then return jsonb_build_object('error', 'sending'); end if;
  hours := coalesce(public.app_setting('wa_repeat_hours', (now() at time zone 'Asia/Kuala_Lumpur')::date), 24);
  if hours > 0 and not coalesce(p_again, false) then
    select * into r from public.invoice_emails x
     where x.bukku_contact = p_contact and x.status <> 'failed' and x.created_at > now() - make_interval(secs => hours * 3600)
     order by x.created_at desc limit 1;
    if r.id is not null then
      return jsonb_build_object('error', 'recent', 'recent', jsonb_build_object('at', r.created_at, 'to', r.to_email,
        'by', (select m.name from public.team_members m where m.id = r.sent_by)));
    end if;
  end if;
  rcp := case when p_client is null then null else public.invoice_recipient(p_client) end;
  v_to := coalesce(rcp->>'email', nullif(btrim(coalesce(p_email, '')), ''));
  if v_to is null or v_to !~ '^[^@\s,;<>]+@[^@\s,;<>]+\.[^@\s,;<>]+$' then return jsonb_build_object('error', 'no-email'); end if;
  v_cc := case when coalesce(p_cc, false) and lower(coalesce(rcp->>'cc', '')) <> lower(v_to) then rcp->>'cc' end;
  v_co := coalesce(rcp->>'company', nullif(btrim(coalesce(p_name, '')), ''), 'Client');
  v_who := coalesce(rcp->>'name', v_co);
  v_n := jsonb_array_length(p_invoices);
  select string_agg(public.invoice_money(s.amt, s.cur), ' and ' order by s.cur) into v_tot
    from (select x->>'currency' as cur, sum((x->>'amount')::numeric) as amt
            from jsonb_array_elements(p_invoices) x group by x->>'currency') s;
  select array_agg(x->>'number' order by o) into v_list from jsonb_array_elements(p_invoices) with ordinality as a (x, o);
  v_nos := case when v_n = 1 then v_list[1]
                else array_to_string(v_list[1:v_n - 1], ', ') || ' and ' || v_list[v_n] end;
  v_vals := jsonb_build_object('contact name', v_who, 'client', v_co, 'invoice no', v_nos, 'count', v_n::text,
    'total', v_tot, 'sign off', case when rcp->>'name' is not null then 'Yours sincerely' else 'Yours faithfully' end);
  select * into t from public.invoice_email_template x where x.id = 1;
  v_s := btrim(regexp_replace(public.supplier_email_fill(coalesce(nullif(btrim(coalesce(p_subject, '')), ''),
           case when v_n = 1 then t.subject_one else t.subject_many end), v_vals), '\s+', ' ', 'g'));
  v_b := btrim(replace(public.supplier_email_fill(coalesce(nullif(btrim(coalesce(p_body, '')), ''), t.body), v_vals), E'\r', ''));
  if length(v_s) < 2 or length(v_s) > 200 then return jsonb_build_object('error', 'bad-subject'); end if;
  if length(v_b) < 2 or length(v_b) > 5000 then return jsonb_build_object('error', 'bad-body'); end if;
  if v_b !~* '\{\s*invoices\s*\}' then return jsonb_build_object('error', 'no-invoices'); end if;
  insert into public.invoice_emails (client_id, bukku_contact, client_name, invoices, to_email, cc_email, subject, body, sent_by)
  values (p_client, p_contact, v_co, p_invoices, v_to, v_cc, v_s, v_b, me.id)
  returning id into v_id;
  return jsonb_build_object('ok', true, 'id', v_id, 'to', v_to, 'cc', v_cc, 'subject', v_s, 'body', v_b,
    'legal', t.legal, 'disclaimer', t.disclaimer);
end $$;
revoke all on function public.invoice_email_begin(uuid, uuid, bigint, text, text, jsonb, boolean, text, text, boolean) from public, anon, authenticated;
grant execute on function public.invoice_email_begin(uuid, uuid, bigint, text, text, jsonb, boolean, text, text, boolean) to service_role;

create or replace function public.invoice_email_done(p_id uuid, p_status text, p_provider text, p_error text)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  e public.invoice_emails;
  m public.team_members;
begin
  if p_status not in ('sent', 'failed', 'unknown') then return jsonb_build_object('error', 'bad-status'); end if;
  select * into e from public.invoice_emails x where x.id = p_id and x.status = 'sending' for update;
  if e.id is null then return jsonb_build_object('error', 'not-found'); end if;
  update public.invoice_emails x set status = p_status, provider_id = nullif(p_provider, ''),
    error = left(nullif(p_error, ''), 480), sent_at = case when p_status = 'sent' then now() end
   where x.id = p_id;
  select * into m from public.team_members x where x.id = e.sent_by;
  insert into public.activity_log (actor, action, subject, detail)
  values (coalesce(m.name, 'system'), 'client.edited', e.client_name,
          'Overdue reminder ' ||
          case p_status when 'sent' then 'emailed to ' when 'unknown' then 'emailed, not confirmed, to ' else 'not emailed to ' end ||
          e.to_email || coalesce(', cc ' || e.cc_email, '') || ' · ' ||
          (select string_agg(x->>'number', ', ') from jsonb_array_elements(e.invoices) x));
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.invoice_email_done(uuid, text, text, text) from public, anon, authenticated;
grant execute on function public.invoice_email_done(uuid, text, text, text) to service_role;

/* Resend's word on a sent email (supplier-mail, its webhook, the service
   role): delivered, opened, bounced or complained, a supplier's email or
   an overdue reminder alike. A later word never steps back: an opened
   email is never delivered again, a bounce stays. */
create or replace function public.supplier_email_status(p_provider text, p_event text, p_at timestamptz)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  e    public.supplier_emails;
  i    public.invoice_emails;
  rank constant jsonb := '{"sending":0,"unknown":1,"sent":1,"failed":1,"delivered":2,"opened":3,"complained":4,"bounced":4}';
  st   text := case p_event when 'email.delivered' then 'delivered' when 'email.opened' then 'opened'
                when 'email.clicked' then 'opened' when 'email.bounced' then 'bounced'
                when 'email.complained' then 'complained' when 'email.sent' then 'sent' end;
begin
  if st is null then return jsonb_build_object('ok', true, 'ignored', true); end if;
  select * into e from public.supplier_emails x where x.provider_id = p_provider for update;
  if e.id is not null then
    update public.supplier_emails x set
      status = case when (rank->>st)::int > (rank->>x.status)::int then st else x.status end,
      sent_at = coalesce(x.sent_at, case when st <> 'bounced' then p_at end),
      delivered_at = case when st in ('delivered', 'opened') then coalesce(x.delivered_at, p_at) else x.delivered_at end,
      opened_at = case when st = 'opened' then coalesce(x.opened_at, p_at) else x.opened_at end,
      bounced_at = case when st = 'bounced' then coalesce(x.bounced_at, p_at) else x.bounced_at end
     where x.id = e.id;
    return jsonb_build_object('ok', true);
  end if;
  select * into i from public.invoice_emails x where x.provider_id = p_provider for update;
  if i.id is null then return jsonb_build_object('error', 'not-found'); end if;
  update public.invoice_emails x set
    status = case when (rank->>st)::int > (rank->>x.status)::int then st else x.status end,
    sent_at = coalesce(x.sent_at, case when st <> 'bounced' then p_at end),
    delivered_at = case when st in ('delivered', 'opened') then coalesce(x.delivered_at, p_at) else x.delivered_at end,
    opened_at = case when st = 'opened' then coalesce(x.opened_at, p_at) else x.opened_at end,
    bounced_at = case when st = 'bounced' then coalesce(x.bounced_at, p_at) else x.bounced_at end
   where x.id = i.id;
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.supplier_email_status(text, text, timestamptz) from public, anon, authenticated;
grant execute on function public.supplier_email_status(text, text, timestamptz) to service_role;

