-- ===========================================================================
-- AUDIT SMALL FIXES — a draft ruled on only while with the client, a
-- representative's WhatsApp only while their card is on, an email cut off
-- mid-send no longer Sending (2026-10-29)
-- ===========================================================================
-- WHY (the whole-repo audit of 2026-10-29):
--   2. `review_draft` took a decision on a draft at Changes requested too,
--      without holding the booking: a selection page left open from before
--      the client asked for changes could approve the unrevised draft, and
--      the creator was told it was cleared to post.
--   4. An email whose function stopped between its filing and its close
--      read Sending for ever (the supplier's and the overdue reminder's).
--   7. The quotation website named a colleague's WhatsApp while their
--      namecard was off.
--
-- WHAT IT CHANGES
--   * `review_draft` (restated whole from its last definition): Reviewing
--     alone, the booking read `for update`.
--   * `quote_website_read` (restated whole from QUOTATION WEBSITE GUARDS):
--     the representative's WhatsApp only with `card_on` and `card_mobile`.
--   * `mail_sweep()` (the owner's alone) marks an email still Sending ten
--     minutes after it was filed as Not confirmed (`unknown`), which a
--     colleague reads as check before sending again; pg_cron `mail-sweep`
--     every fifteen minutes.
--
-- ORDER: this file (connector). No page changes with it. Safe to run twice.
--
-- ROLLBACK: review_draft and quote_website_read from their last definitions
-- before this banner; then in the SQL Editor:
--   select cron.unschedule(jobid) from cron.job where jobname = 'mail-sweep';
--   drop function if exists public.mail_sweep();
-- ===========================================================================

create or replace function public.review_draft(
  p_token text, p_option uuid, p_decision text, p_note text default null,
  p_reviewer text default null, p_passcode text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  c campaigns%rowtype;
  o campaign_options%rowtype;
  n integer;
begin
  select * into c from campaigns where access_token = p_token;
  if not found then return jsonb_build_object('error', 'not-found'); end if;
  -- A past client's link acts on nothing, as it reads nothing (second
  -- audit, item 7): answered as a key nobody knows, before the passcode.
  if exists (select 1 from public.clients cl where cl.id = c.client_id and cl.stage = 'past') then
    return jsonb_build_object('error', 'not-found');
  end if;
  -- Wrong passcodes lock out the caller who typed them, said as a lock
  -- (second audit, item 4).
  case public.link_passcode('selection', c.access_token, c.passcode, p_passcode)
    when 'locked' then return public.link_locked('selection', c.access_token);
    when 'wrong' then return jsonb_build_object('error', 'passcode');
    else null;
  end case;
  if p_decision not in ('approved', 'changes') then
    return jsonb_build_object('error', 'bad-decision');
  end if;
  -- What a client types is held to a length (audit 2026-10-18, item 12).
  if length(coalesce(p_reviewer, '')) > 80 or length(coalesce(p_note, '')) > 2000 then
    return jsonb_build_object('error', 'too-long');
  end if;

  -- The booking is held while it is ruled on, so two decisions at once
  -- are taken one after the other (audit 2026-10-29, 2).
  select * into o from campaign_options
   where id = p_option and campaign_id = c.id
   for update;
  if not found then return jsonb_build_object('error', 'not-found'); end if;

  /* Only a draft that is with the client can be ruled on: Reviewing, as
     the selection page draws the decision. A draft already sent back for
     changes is with the creator, so a page left open from before can no
     longer approve it unrevised (audit 2026-10-29, 2; the team's send-back
     too, audit B, 2026-10-17). */
  if o.state <> 'reviewing' then
    return jsonb_build_object('error', 'not-reviewing');
  end if;

  n := coalesce(o.revision_round, 0);

  insert into option_reviews (option_id, round, decision, note, reviewer)
  values (p_option, greatest(n, 1), p_decision, nullif(trim(coalesce(p_note, '')), ''), p_reviewer);

  if p_decision = 'approved' then
    update campaign_options set state = 'scheduled' where id = p_option;
  else
    update campaign_options
       set state = 'changes', revision_round = greatest(n, 1) + 1,
           changes_by = 'client'
     where id = p_option;
  end if;

  /* The client's decision is the one event on a campaign that nobody on the
     team witnesses, and it was the only one the activity record never held:
     a draft went to Reviewing and appeared as Scheduled with nothing in
     between saying who had said yes. The reviewer's own name is the actor,
     because a person decided it. */
  insert into activity_log (actor, action, subject, detail)
  select coalesce(nullif(trim(coalesce(p_reviewer, '')), ''), 'Client'),
         'campaign.review', c.title,
         cr.name || ' · ' ||
         case when p_decision = 'approved' then 'Approved' else 'Changes requested' end ||
         coalesce(': ' || nullif(trim(coalesce(p_note, '')), ''), '')
    from creators cr where cr.id = o.creator_id;

  return jsonb_build_object('ok', true, 'decision', p_decision);
end $$;
revoke all on function public.review_draft(text, uuid, text, text, text, text) from public;
grant execute on function public.review_draft(text, uuid, text, text, text, text) to anon, authenticated;

create or replace function public.quote_website_read(p_key text)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  w  public.quotations;
  q  public.quotations;
  c  public.clients;
  m  public.team_members;
  d  public.client_documents;
  f  public.client_detail_forms;
  v_today date := (now() at time zone 'Asia/Kuala_Lumpur')::date;
  v_stage text;
  v_portal boolean := false;
  v_billed boolean;
  v_own boolean;
begin
  if coalesce(p_key, '') !~ '^[a-z0-9]{8}$' then return jsonb_build_object('error', 'not-found'); end if;
  select * into w from public.quotations x
   where x.access_key = p_key and x.source = 'website' and x.removed_at is null;
  if w.id is null then return jsonb_build_object('error', 'not-found'); end if;
  select * into q from public.quotations x where x.id = public.quote_shown(w.id);
  select * into c from public.clients x where x.id = w.client_id;
  if nullif(btrim(coalesce(c.owner, '')), '') is not null then
    select * into m from public.team_members x
     where x.active and not coalesce(x.system, false) and x.removed_at is null and x.name = c.owner
     limit 1;
  end if;
  -- The letter that stands on the quotation's lines, the latest first.
  select dd.* into d from public.client_documents dd
   where dd.kind = 'offer' and dd.voided_at is null and dd.superseded_by is null
     and exists (select 1 from public.client_document_services ds
                   join public.client_services s on s.id = ds.service_id
                  where ds.document_id = dd.id and s.quotation_id = q.id)
   order by dd.created_at desc limit 1;
  -- The client's details form is offered only on the quotation that made
  -- the lead: a later website quotation that matched an existing lead's
  -- email and number never opens that lead's form (2026-10-26, audit).
  v_own := c.created_at >= w.issued_at - interval '1 minute'
           and not exists (select 1 from public.quotations o
                            where o.client_id = c.id and o.issued_at < w.issued_at and o.id <> w.id);
  v_billed := coalesce(btrim(c.legal_name), '') <> '' and coalesce(btrim(c.company_no), '') <> ''
              and coalesce(btrim(c.billing_address), '') <> '';

  if d.id is not null then
    if d.verified_at is not null and c.stage = 'active' then
      v_stage := 'welcome';
      select exists (select 1 from public.client_contacts k
                      where k.client_id = c.id and k.archived_at is null and k.portal_access
                        and lower(btrim(k.email)) = lower(btrim(coalesce(w.contact->>'email', '')))) into v_portal;
    elsif d.signed_at is not null then v_stage := 'signed';
    else v_stage := 'letter';
    end if;
  elsif w.status = 'not_proceeding' or q.status = 'not_proceeding' then
    v_stage := 'closed';
  elsif q.valid_until < v_today then
    v_stage := 'expired';
  elsif not v_billed and v_own then
    select * into f from public.client_detail_forms x
     where x.client_id = c.id and x.voided_at is null
     order by x.created_at desc limit 1;
    if f.id is not null and f.submitted_at is not null and f.used_at is null then v_stage := 'billing_sent';
    elsif f.id is not null and f.submitted_at is null and f.expires_at > now() then v_stage := 'billing';
    end if;
  elsif v_billed and w.proceed_at is not null then
    v_stage := 'billing_sent';
  end if;
  if v_stage is null then
    v_stage := case when w.proceed_at is not null then 'ready' else 'quote' end;
  end if;

  return jsonb_build_object(
    'ref', q.ref, 'first_ref', w.ref, 'revised', q.id <> w.id,
    'brand', coalesce(w.contact->>'brand', w.brand), 'version', q.version,
    'issued_at', q.issued_at, 'valid_until', q.valid_until, 'lines', q.lines, 'totals', q.totals,
    'selection', w.selection, 'attention', w.contact->>'name',
    'stage', v_stage,
    'status', case when d.id is not null then 'offer' else q.status end,
    'details_key', case when v_stage = 'billing' then f.access_key end,
    'portal', v_portal,
    'proceed_at', w.proceed_at, 'proceed_due', w.proceed_due,
    'rep', case when m.id is null then null else jsonb_build_object('name', m.name, 'title', nullif(btrim(coalesce(m.designation, '')), ''),
             'whatsapp', case when coalesce(m.card_on, true) and coalesce(m.card_mobile, true) then nullif(public.wa_number(m.mobile), '') end) end,
    'market', case when c.market = 'SG' then 'SG' else 'MY' end,
    'today', v_today);
end $$;
revoke all on function public.quote_website_read(text) from public;
grant execute on function public.quote_website_read(text) to anon, authenticated;

create or replace function public.mail_sweep()
returns integer
language plpgsql volatile security definer set search_path = public as $$
declare
  n integer := 0;
  k integer;
begin
  update public.invoice_emails x set status = 'unknown', error = coalesce(x.error, 'unknown: not closed')
   where x.status = 'sending' and x.created_at < now() - interval '10 minutes';
  get diagnostics k = row_count; n := n + k;
  update public.supplier_emails x set status = 'unknown', error = coalesce(x.error, 'unknown: not closed')
   where x.status = 'sending' and x.created_at < now() - interval '10 minutes';
  get diagnostics k = row_count; n := n + k;
  return n;
end $$;
revoke all on function public.mail_sweep() from public, anon, authenticated;

do $$
begin
  if not exists (select 1 from pg_extension where extname = 'pg_cron') then
    raise notice 'pg_cron is not enabled: an email cut off mid-send reads Sending until swept by hand.';
    return;
  end if;
  perform cron.unschedule(j.jobid) from cron.job j where j.jobname = 'mail-sweep';
  perform cron.schedule('mail-sweep', '*/15 * * * *', 'select public.mail_sweep()');
end $$;

-- END OF AUDIT SMALL FIXES --------------------------------------------------

-- ===========================================================================
-- WEBSITE WHATSAPP CAP — the quotation website sends no more WhatsApp
-- messages a day than a Business setting allows (2026-10-29)
-- ===========================================================================
-- WHY (the whole-repo audit of 2026-10-29, finding 3): every quotation made
-- on /quote/ queues the `quote_ready` WhatsApp, paid for by ADspace, to the
-- number typed. Turnstile and five a contact a day were the only limits, so
-- a run of new emails and numbers could send without end.
--
-- WHAT IT CHANGES
--   * `quote_wa_day` (Business setting, 30 from the start; 0 to 500, 0 sends
--     none): the website quotations a day (MYT) whose prospect is told on
--     WhatsApp; changed in Settings once the SQL Editor part has run.
--   * `quote_wa_allowed(p_id)` (the owner's alone): whether the website
--     quotations made today before this one stand under it, counted under
--     one lock so two at once count each other.
--   * `quote_website_create` (restated whole from QUOTATION WEBSITE GUARDS)
--     queues the message only while allowed; past it the quotation is made
--     and the team told as before.
--
-- ORDER: this file (connector), its SQL Editor part
-- (2026-10-29-website-whatsapp-cap-editor.sql), then the pages (Settings,
-- WhatsApp: Website quotations). Safe to run twice.
--
-- ROLLBACK: quote_website_create from QUOTATION WEBSITE GUARDS; leave
-- quote_wa_allowed and the setting's row (nothing else reads them).
-- ===========================================================================

insert into public.app_settings (key, from_date, value)
select 'quote_wa_day', date '2023-08-14', 30
 where not exists (select 1 from public.app_settings s where s.key = 'quote_wa_day');

create or replace function public.quote_wa_allowed(p_id uuid)
returns boolean
language plpgsql volatile security definer set search_path = public as $$
declare
  v_today date := (now() at time zone 'Asia/Kuala_Lumpur')::date;
  v_cap numeric := coalesce(public.app_setting('quote_wa_day', v_today), 30);
  v_made integer;
begin
  if v_cap <= 0 then return false; end if;
  perform pg_advisory_xact_lock(hashtextextended('quote-web-wa-day', 0));
  select count(*) into v_made from public.quotations q
   where q.source = 'website' and q.id <> p_id
     and q.issued_at >= (v_today::timestamp at time zone 'Asia/Kuala_Lumpur');
  return v_made < v_cap;
end $$;
revoke all on function public.quote_wa_allowed(uuid) from public, anon, authenticated;


create or replace function public.quote_website_create(p_sel jsonb, p_contact jsonb, p_idem text)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  v_name  text := btrim(regexp_replace(coalesce(p_contact->>'name', ''), '\s+', ' ', 'g'));
  v_email text := lower(btrim(coalesce(p_contact->>'email', '')));
  v_wa    text := public.quote_website_number(p_contact->>'whatsapp');
  v_brand text := btrim(regexp_replace(coalesce(p_contact->>'brand', ''), '\s+', ' ', 'g'));
  v_ind   text := nullif(btrim(coalesce(p_contact->>'industry', '')), '');
  v_lang  text := case when p_contact->>'lang' = 'zh' then 'zh' else 'en' end;
  v_sal   text := nullif(btrim(coalesce(p_contact->>'salutation', '')), '');
  v_idem  text := nullif(btrim(coalesce(p_idem, '')), '');
  v_sel   jsonb;
  v_q     public.quotations;
  v_c     public.clients;
  v_base  text;
  v_slug  text;
  v_n     int := 1;
  v_r     jsonb;
  v_new   boolean := false;
begin
  if v_idem is null or length(v_idem) > 80 then return jsonb_build_object('error', 'bad-request'); end if;
  select * into v_q from public.quotations q
   where q.idem = v_idem and q.source = 'website' and lower(q.contact->>'email') = v_email;
  if v_q.id is not null then
    return jsonb_build_object('ok', true, 'ref', v_q.ref, 'key', v_q.access_key, 'again', true);
  end if;
  if length(v_name) < 2 or length(v_name) > 80 then return jsonb_build_object('error', 'bad-name'); end if;
  if v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' or length(v_email) > 160 then return jsonb_build_object('error', 'bad-email'); end if;
  if v_wa !~ '^(60(1[0-9]{8,9}|7[0-9]{7,8})|65[0-9]{8})$' then return jsonb_build_object('error', 'bad-whatsapp'); end if;
  if length(v_brand) < 2 or length(v_brand) > 120 then return jsonb_build_object('error', 'bad-brand'); end if;
  -- A name or brand is never a web address: both go into the WhatsApp the
  -- prospect is sent from ADspace's number (2026-10-26, audit).
  if v_name ~* public.quote_link_like() then return jsonb_build_object('error', 'bad-name'); end if;
  if v_brand ~* public.quote_link_like() then return jsonb_build_object('error', 'bad-brand'); end if;
  if v_ind is not null and v_ind not in ('Property', 'F&B', 'Retail', 'Wellness', 'Lifestyle',
                                         'Automotive', 'Tech', 'Education', 'Other') then
    return jsonb_build_object('error', 'bad-industry');
  end if;
  if v_sal is not null and v_sal not in ('Mr', 'Ms', 'Mrs', 'Mdm', 'Dr', 'Prof', 'Dato''', 'Datin', 'Datuk',
      'Dato'' Sri', 'Datin Sri', 'Tan Sri', 'Puan Sri', 'Tun', 'Tuan', 'Puan', 'Encik', 'Cik') then
    return jsonb_build_object('error', 'bad-salutation');
  end if;
  if coalesce((p_contact->>'consent')::boolean, false) is not true then return jsonb_build_object('error', 'consent'); end if;
  if jsonb_typeof(p_sel) is distinct from 'object' then return jsonb_build_object('error', 'bad-selection'); end if;
  if jsonb_typeof(p_sel->'once') = 'array' and jsonb_array_length(p_sel->'once') > 20
     or jsonb_typeof(p_sel->'extra') = 'object' and (select count(*) from jsonb_object_keys(p_sel->'extra')) > 10 then
    return jsonb_build_object('error', 'bad-selection');
  end if;

  -- What the price reads, and nothing else.
  v_sel := jsonb_strip_nulls(jsonb_build_object(
    'mix', case when jsonb_typeof(p_sel->'mix') = 'string' and length(p_sel->>'mix') <= 20 then p_sel->'mix' end,
    'plan', case when jsonb_typeof(p_sel->'plan') = 'string' and length(p_sel->>'plan') <= 80 then p_sel->'plan' end,
    'term', case when jsonb_typeof(p_sel->'term') in ('number', 'string') and length(p_sel->>'term') <= 4 then p_sel->'term' end,
    'budget', case when jsonb_typeof(p_sel->'budget') in ('number', 'string') and length(p_sel->>'budget') <= 12 then p_sel->'budget' end,
    'translate', case when jsonb_typeof(p_sel->'translate') = 'boolean' then p_sel->'translate' end,
    'platforms', (select jsonb_agg(distinct v) from jsonb_array_elements_text(
                    case when jsonb_typeof(p_sel->'platforms') = 'array' then p_sel->'platforms' else '[]'::jsonb end) v
                   where v in ('meta', 'tiktok', 'rednote', 'linkedin')),
    'langs', (select jsonb_agg(distinct l) from jsonb_array_elements_text(
                case when jsonb_typeof(p_sel->'langs') = 'array' then p_sel->'langs' else '[]'::jsonb end) l
               where l in ('en', 'zh', 'ms')),
    'extra', case when jsonb_typeof(p_sel->'extra') = 'object' then
               (select jsonb_object_agg(left(k, 80), p_sel->'extra'->k) from jsonb_object_keys(p_sel->'extra') k) end,
    'once', case when jsonb_typeof(p_sel->'once') = 'array' then
              (select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('slug', left(o->>'slug', 80), 'qty', o->'qty')))
                 from jsonb_array_elements(p_sel->'once') o where jsonb_typeof(o) = 'object') end));

  -- Two posts at once are counted one after the other.
  perform pg_advisory_xact_lock(hashtextextended('quote-web:' || least(v_email, v_wa), 0));
  perform pg_advisory_xact_lock(hashtextextended('quote-web:' || greatest(v_email, v_wa), 0));
  if (select count(*) from public.quotations q
       where q.source = 'website' and q.issued_at > now() - interval '1 day'
         and (lower(q.contact->>'email') = v_email or q.contact->>'whatsapp' = '+' || v_wa)) >= 5 then
    return jsonb_build_object('error', 'limit');
  end if;

  -- A lead this person already is (the same contact holds both the email
  -- and the number), else a new one.
  select c.* into v_c from public.clients c
    join public.client_contacts k on k.client_id = c.id
   where c.stage in ('lead', 'contacted', 'proposal')
     and k.archived_at is null
     and lower(k.email) = v_email
     and public.quote_website_number(k.whatsapp) = v_wa
   order by c.created_at desc limit 1;
  if v_c.id is null then
    v_base := btrim(regexp_replace(lower(v_brand), '[^a-z0-9]+', '-', 'g'), '-');
    if v_base = '' then v_base := 'client'; end if;
    v_slug := v_base;
    while exists (select 1 from public.clients c where lower(c.slug) = v_slug) loop
      v_n := v_n + 1; v_slug := v_base || '-' || v_n;
    end loop;
    insert into public.clients (name, access_token, stage, industry, source, market, slug, deal_note)
    values (v_brand, public.new_link_key(), 'lead', v_ind, 'website',
            case when v_wa like '65%' then 'SG' else 'MY' end, v_slug,
            'Quotation requested on the website.')
    returning * into v_c;
    insert into public.client_contacts (client_id, salutation, name, email, whatsapp, lang, is_primary)
    values (v_c.id, v_sal, v_name, v_email, '+' || v_wa, v_lang, true);
    insert into public.activity_log (actor, action, subject, detail)
    values ('Website', 'client.added', v_c.name, 'Website · ' || coalesce(v_sal || ' ', '') || v_name);
    v_new := true;
  end if;

  v_r := public.quotation_make(v_c.id, v_sel, v_idem, 'website', null,
    jsonb_strip_nulls(jsonb_build_object('salutation', v_sal, 'name', v_name, 'email', v_email,
      'whatsapp', '+' || v_wa, 'lang', v_lang, 'brand', v_brand)));
  if v_r ? 'error' then
    if v_new then raise exception using message = 'quote:' || (v_r->>'error'); end if;
    return v_r;
  end if;
  select * into v_q from public.quotations where id = (v_r->>'id')::uuid;
  perform public.quote_tell(v_c.id, 'quote.website', 'Quotation made on the website · ' || v_c.name,
    v_q.ref || ' · ' || coalesce('Monthly incl. SST RM ' ||
      to_char((v_q.totals->'month'->>'incl')::numeric, 'FM999,999,990.00'), 'one-off') || ' · ' || v_name,
    v_q.id::text);
  -- The prospect is told on WhatsApp that the quotation is ready, its link
  -- button the quotation's key; a queueing fault never fails the quotation.
  -- No more a day than the Business setting allows (audit 2026-10-29, 3):
  -- past it the quotation is made and the team told, the message not sent.
  begin
    if public.quote_wa_allowed(v_q.id) then
      perform public.wa_enqueue('quote_ready', v_wa, v_name,
        jsonb_build_array(public.contact_greeting(v_sal, v_name), v_brand, v_q.ref),
        'quotation', v_q.id, v_c.id, v_q.access_key);
    end if;
  exception when others then null;
  end;
  return jsonb_build_object('ok', true, 'ref', v_q.ref, 'key', v_q.access_key);
exception when raise_exception then
  if sqlerrm like 'quote:%' then return jsonb_build_object('error', substr(sqlerrm, 7)); end if;
  raise;
end $$;
revoke all on function public.quote_website_create(jsonb, jsonb, text) from public, anon, authenticated;
grant execute on function public.quote_website_create(jsonb, jsonb, text) to service_role;

-- END OF WEBSITE WHATSAPP CAP -----------------------------------------------


-- ===========================================================================
-- WEBSITE WHATSAPP CAP, THE SQL EDITOR PART — Settings may change how many
-- website quotations a day are sent on WhatsApp (2026-10-29)
-- ===========================================================================
-- WHY: 2026-10-29-website-whatsapp-cap.sql reads `quote_wa_day`. Settings
-- writes it through `app_settings_set`, which holds a delete the connector
-- holds, so it runs here, after that file.
--
-- WHAT IT CHANGES
--   `app_settings_set` (restated whole from its last definition) takes
--   `quote_wa_day`, 0 to 500 a day, filed as Website quotations on WhatsApp.
--
-- ORDER: after 2026-10-29-website-whatsapp-cap.sql. Safe to run twice.
-- Rollback: app_settings_set from its last definition before this banner.
-- ===========================================================================

create or replace function public.app_settings_set(p_from date, p_values jsonb)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me public.team_members; v_k text; v_v numeric; v_was numeric; v_name text; v_unit text; v_pre text;
  v_today date := (now() at time zone 'Asia/Kuala_Lumpur')::date;
  v_keys constant text[] := array['lead_followup_hours', 'proposal_followup_days', 'sst_pct',
    'term_1_3', 'term_4_5', 'term_6_11', 'term_12_23', 'term_18_23', 'term_24', 'report_due_days', 'revision_due_days',
    'ai_price_in', 'ai_price_out', 'meta_checks', 'approval_reminder_days', 'ai_price_search',
    'reach_allowance_pct', 'priority_urgent_hours', 'priority_high_hours', 'priority_medium_hours',
    'task_remind_hours', 'task_start_days', 'quote_valid_days', 'details_form_days', 'wa_repeat_hours',
    'bench_cpr_low', 'bench_cpr_mid', 'bench_cpr_high', 'bench_cpr_top', 'bench_msg_min', 'bench_msg_target', 'bench_msg_max',
    'bench_form_min', 'bench_form_target', 'bench_form_max', 'bench_cpm_min', 'bench_cpm_max', 'bench_cpl_rise',
    'bench_reels_share', 'bench_ad_spend_pct', 'bench_adset_daily', 'vic_lead_followup_hours', 'vic_proposal_followup_days', 'fx_sgd',
    'health_keep_months', 'health_leaver_months', 'abroad_days', 'abroad_remind_hours', 'analytics_from',
    'analytics_change_pct', 'analytics_churn_pct', 'quote_reply_days', 'quote_wa_day'];
  v_moved text[] := '{}';
  v_drop boolean; v_fw text; v_fv text;
begin
  if not public.ops_granted('team.settings', 'work') then return jsonb_build_object('error', 'denied'); end if;
  v_me := public.ops_me();
  if p_from is null or p_from < v_today then return jsonb_build_object('error', 'past', 'today', v_today); end if;
  if jsonb_typeof(p_values) is distinct from 'object' then return jsonb_build_object('error', 'bad-value'); end if;
  for v_k in select jsonb_object_keys(p_values) loop
    if not (v_k = any(v_keys)) or jsonb_typeof(p_values -> v_k) <> 'number' then
      return jsonb_build_object('error', 'bad-value', 'key', v_k);
    end if;
    v_v := (p_values ->> v_k)::numeric;
    if round(v_v, case when v_k = 'fx_sgd' then 4 else 2 end) <> v_v
       or (v_k = 'fx_sgd' and (v_v < 0.5 or v_v > 10))
       or (v_k in ('lead_followup_hours', 'vic_lead_followup_hours') and (v_v < 1 or v_v > 720 or v_v <> trunc(v_v)))
       or (v_k in ('proposal_followup_days', 'vic_proposal_followup_days') and (v_v < 1 or v_v > 365 or v_v <> trunc(v_v)))
       or (v_k = 'report_due_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'revision_due_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'approval_reminder_days' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'sst_pct' and (v_v < 0 or v_v > 100))
       or (v_k like 'term_%' and (v_v < -100 or v_v > 100))
       or (v_k like 'ai_price_%' and (v_v < 0 or v_v > 1000))
       or (v_k = 'meta_checks' and v_v not in (0, 1))
       or (v_k = 'reach_allowance_pct' and (v_v < 0 or v_v > 5))
       or (v_k like 'priority_%_hours' and (v_v < 1 or v_v > 720 or v_v <> trunc(v_v)))
       or (v_k = 'task_remind_hours' and (v_v < 0 or v_v > 24 or v_v <> trunc(v_v)))
       or (v_k = 'task_start_days' and (v_v < 0 or v_v > 30 or v_v <> trunc(v_v)))
       or (v_k in ('quote_valid_days', 'details_form_days') and (v_v < 1 or v_v > 90 or v_v <> trunc(v_v)))
       or (v_k = 'quote_reply_days' and (v_v < 1 or v_v > 10 or v_v <> trunc(v_v)))
       or (v_k = 'wa_repeat_hours' and (v_v < 0 or v_v > 168 or v_v <> trunc(v_v)))
       or (v_k = 'quote_wa_day' and (v_v < 0 or v_v > 500 or v_v <> trunc(v_v)))
       or (v_k = 'health_keep_months' and (v_v < 6 or v_v > 120 or v_v <> trunc(v_v)))
       or (v_k = 'health_leaver_months' and (v_v < 1 or v_v > 60 or v_v <> trunc(v_v)))
       or (v_k = 'abroad_days' and (v_v < 1 or v_v > 30 or v_v <> trunc(v_v)))
       or (v_k = 'abroad_remind_hours' and (v_v < 0 or v_v > 24 or v_v <> trunc(v_v)))
       or (v_k = 'analytics_from' and (v_v < 202308 or v_v > 209912 or v_v <> trunc(v_v) or mod(v_v, 100) not between 1 and 12))
       or (v_k = 'analytics_change_pct' and (v_v < 1 or v_v > 50 or v_v <> trunc(v_v)))
       or (v_k = 'analytics_churn_pct' and (v_v < 1 or v_v > 100 or v_v <> trunc(v_v)))
       or (v_k in ('bench_reels_share') and (v_v < 0 or v_v > 100))
       or (v_k = 'bench_ad_spend_pct' and (v_v < 1 or v_v > 100))
       or (v_k = 'bench_cpl_rise' and (v_v < -100 or v_v > 100))
       or (v_k like 'bench_%' and v_k not in ('bench_reels_share', 'bench_ad_spend_pct', 'bench_cpl_rise') and (v_v < 0 or v_v > 10000)) then
      return jsonb_build_object('error', 'bad-value', 'key', v_k);
    end if;
  end loop;
  for v_k in select jsonb_object_keys(p_values) loop
    v_v := (p_values ->> v_k)::numeric;
    v_was := public.app_setting(v_k, p_from);
    if v_was is distinct from v_v then
      /* A planned change saved back to the value in force the day before is
         withdrawn: its row goes, rather than a second row restating it. */
      v_drop := p_from > v_today
        and exists (select 1 from public.app_settings s where s.key = v_k and s.from_date = p_from)
        and exists (select 1 from public.app_settings s where s.key = v_k and s.from_date < p_from)
        and public.app_setting(v_k, p_from - 1) = v_v;
      if v_drop then
        delete from public.app_settings s where s.key = v_k and s.from_date = p_from;
      else
        insert into public.app_settings (key, from_date, value, set_by, set_at)
        values (v_k, p_from, v_v, v_me.id, now())
        on conflict (key, from_date) do update set value = excluded.value, set_by = excluded.set_by, set_at = now();
      end if;
      v_name := case v_k when 'lead_followup_hours' then 'A lead waits' when 'proposal_followup_days' then 'A proposal waits'
        when 'vic_lead_followup_hours' then 'A VIC lead waits' when 'vic_proposal_followup_days' then 'A VIC proposal waits'
        when 'sst_pct' then 'SST' when 'term_1_3' then '1 to 3 months' when 'term_4_5' then '4 and 5 months'
        when 'term_6_11' then '6 to 11 months' when 'term_12_23' then '12 to 17 months' when 'term_18_23' then '18 to 23 months' when 'term_24' then '24 months and more'
        when 'revision_due_days' then 'Revision due' when 'ai_price_in' then 'AI input, a million tokens'
        when 'ai_price_out' then 'AI output, a million tokens' when 'ai_price_search' then 'AI web searches, a thousand' when 'meta_checks' then 'Meta checks'
        when 'approval_reminder_days' then 'Approval reminder' when 'reach_allowance_pct' then 'Reach allowance'
        when 'priority_urgent_hours' then 'Urgent deadline' when 'priority_high_hours' then 'High deadline'
        when 'priority_medium_hours' then 'Medium deadline' when 'task_remind_hours' then 'Task reminders'
        when 'task_start_days' then 'Not started reminder' when 'quote_valid_days' then 'Quotation validity' when 'details_form_days' then 'Details form open'
        when 'quote_reply_days' then 'Contact within'
        when 'wa_repeat_hours' then 'WhatsApp sent again'
        when 'quote_wa_day' then 'Website quotations on WhatsApp'
        when 'bench_cpr_low' then 'Property cost per result, tier 1 from' when 'bench_cpr_mid' then 'Property cost per result, tier 2 from'
        when 'bench_cpr_high' then 'Property cost per result, tier 3 from' when 'bench_cpr_top' then 'Property cost per result, tier 3 up to'
        when 'bench_msg_min' then 'Messaging cost per result, low' when 'bench_msg_target' then 'Messaging cost per result, target'
        when 'bench_msg_max' then 'Messaging cost per result, high' when 'bench_form_min' then 'Lead form cost per result, low'
        when 'bench_form_target' then 'Lead form cost per result, target' when 'bench_form_max' then 'Lead form cost per result, high'
        when 'bench_cpm_min' then 'Cost per 1,000 impressions, low' when 'bench_cpm_max' then 'Cost per 1,000 impressions, high'
        when 'bench_cpl_rise' then 'Cost per lead rise a year' when 'bench_reels_share' then 'Reels share of impressions'
        when 'bench_ad_spend_pct' then 'Ad spend of the budget' when 'bench_adset_daily' then 'Daily budget an ad set, at least'
        when 'fx_sgd' then 'Singapore dollar rate'
        when 'health_keep_months' then 'Health check-ins kept' when 'health_leaver_months' then 'A leaver''s health data kept'
        when 'abroad_days' then 'Overseas approval' when 'abroad_remind_hours' then 'Overseas reminder'
        when 'analytics_from' then 'Analytics counts from'
        when 'analytics_change_pct' then 'Analytics change threshold' when 'analytics_churn_pct' then 'Analytics churn alert, a quarter'
        else 'Report due' end;
      v_pre := case when v_k = 'fx_sgd' then 'RM ' when v_k like 'ai_price_%' then 'US$' when v_k like 'bench_%' and v_k not in ('bench_cpl_rise', 'bench_reels_share', 'bench_ad_spend_pct') then 'RM ' else '' end;
      v_unit := case when v_k = 'fx_sgd' then ' to S$1' when v_k in ('lead_followup_hours', 'vic_lead_followup_hours', 'task_remind_hours', 'wa_repeat_hours', 'abroad_remind_hours') or v_k like 'priority_%_hours' then ' hours'
        when v_k in ('proposal_followup_days', 'vic_proposal_followup_days', 'report_due_days', 'revision_due_days', 'approval_reminder_days', 'task_start_days', 'quote_valid_days', 'details_form_days', 'abroad_days') then ' days'
        when v_k = 'quote_reply_days' then ' working days'
        when v_k = 'quote_wa_day' then ' a day'
        when v_k in ('health_keep_months', 'health_leaver_months') then ' months'
        when v_pre <> '' then '' else '%' end;
      v_fw := case when v_k = 'meta_checks' then case when v_was = 1 then 'On' else 'Off' end
              when v_k = 'analytics_from' then coalesce(substr(public.register_day(to_date(v_was::bigint::text, 'YYYYMM')), 3), 'not set') else coalesce(v_pre ||
              trim(to_char(v_was, case when v_k = 'fx_sgd' then 'FM999999990.9999' else 'FM999999990.99' end), '.') || v_unit, 'not set') end;
      v_fv := case when v_k = 'meta_checks' then case when v_v = 1 then 'On' else 'Off' end
              when v_k = 'analytics_from' then substr(public.register_day(to_date(v_v::bigint::text, 'YYYYMM')), 3) else v_pre ||
              trim(to_char(v_v, case when v_k = 'fx_sgd' then 'FM999999990.9999' else 'FM999999990.99' end), '.') || v_unit end;
      insert into public.activity_log (actor, action, subject, detail)
      values (coalesce(v_me.name, 'admin'), 'team.changed', 'Settings',
              case when v_drop then v_name || ': planned change withdrawn · ' || v_fw || ' from ' || public.register_day(p_from) ||
                ', stays ' || v_fv else
              case when v_k = 'analytics_from' then v_name || ': ' || v_fw || ' → ' || v_fv || ' · from ' || public.register_day(p_from) else
              v_name || ': ' || case when v_k = 'meta_checks' then
                case when v_was = 1 then 'On' else 'Off' end || ' → ' || case when v_v = 1 then 'On' else 'Off' end ||
                ' · from ' || public.register_day(p_from) else '' end ||
              case when v_k = 'meta_checks' then '' else coalesce(v_pre ||
              trim(to_char(v_was, case when v_k = 'fx_sgd' then 'FM999999990.9999' else 'FM999999990.99' end), '.') || v_unit, 'not set') || ' → ' || v_pre ||
              trim(to_char(v_v, case when v_k = 'fx_sgd' then 'FM999999990.9999' else 'FM999999990.99' end), '.') || v_unit ||
              ' · from ' || public.register_day(p_from) end end end);
      v_moved := v_moved || v_k;
    end if;
  end loop;
  return public.app_settings_read() || jsonb_build_object('changed', to_jsonb(v_moved));
end $$;
revoke all on function public.app_settings_set(date, jsonb) from public, anon;
grant execute on function public.app_settings_set(date, jsonb) to authenticated;

-- END OF WEBSITE WHATSAPP CAP, THE SQL EDITOR PART --------------------------

-- ===========================================================================
-- OVERDUE REMINDER WORDING — the reminder reads as a creditor writes it, and
-- its fine print is every email's (2026-10-29)
-- ===========================================================================
-- WHY (the review of the Overdue invoices section, 2026-10-28; the user,
-- 2026-10-29: "1-5"): "payment of {total} for {client}" read as if ADspace
-- owed the money; a company with no named contact was greeted by its
-- registered name above "Yours faithfully"; the legal note spoke of overdue
-- interest that no agreement states; the disclaimer differed from the
-- confidentiality line every other portal email carries.
--
-- WHAT IT CHANGES
--   * `invoice_email_template`: the message reads "payment of {total} due
--     from {client}", the legal note ends "settled in accordance with the
--     agreed payment terms", the disclaimer is the standing confidentiality
--     line (_shared/mail.ts). Each is changed only where it still holds the
--     seed's words: wording a colleague changed at Business settings is
--     left as it is (the preview file reports which).
--   * `invoice_email_begin` (restated whole from OVERDUE INVOICE REMINDERS,
--     every refusal kept): {contact name} with no named contact reads
--     "Sir or Madam", never the company.
--
-- ORDER: the pages (the preview fills the same greeting), then this file
-- (connector). An open tab before the pages greets the company in its
-- preview while the email greets Sir or Madam. Safe to run twice.
--
-- ROLLBACK: invoice_email_begin from OVERDUE INVOICE REMINDERS again, and the
-- three seeds written back where they hold this file's words.
-- ===========================================================================

update public.invoice_email_template x set body =
  E'Dear {contact name},\n\nThis is a reminder that payment of {total} due from {client} is now overdue.\n\n{invoices}\n\nWe would be grateful if payment could be arranged at your earliest convenience. If payment has already been made, please disregard this email.\n\nShould you have any questions, please reply to this email.\n\nThank you for your continued support.\n\n{sign off},\nADspace Finance',
  updated_at = now()
 where x.id = 1 and x.body =
  E'Dear {contact name},\n\nThis is a reminder that payment of {total} for {client} is now overdue.\n\n{invoices}\n\nWe would be grateful if payment could be arranged at your earliest convenience. If payment has already been made, please disregard this email.\n\nShould you have any questions, please reply to this email.\n\nThank you for your continued support.\n\n{sign off},\nADspace Finance';
update public.invoice_email_template x set legal =
  'Legal note: All services rendered will be invoiced accordingly unless a written cancellation is provided and acknowledged in advance. All invoices are to be settled in accordance with the agreed payment terms.',
  updated_at = now()
 where x.id = 1 and x.legal =
  'Legal note: All services rendered will be invoiced accordingly unless a written cancellation is provided and acknowledged in advance. All invoices must be settled promptly to avoid overdue interest charges.';
update public.invoice_email_template x set disclaimer =
  'This email and any attachments are confidential and may be privileged. If you are not the intended recipient, please do not disclose, copy or rely on it; notify the sender and delete it from your system.',
  updated_at = now()
 where x.id = 1 and x.disclaimer =
  'This email and any attachment are private and confidential and intended solely for the addressee. If you have received it in error, please notify einvoice@adspacestudios.com and delete it. Any use, copying or disclosure by anyone else is not permitted.';

create or replace function public.invoice_email_begin(p_actor uuid, p_client uuid, p_contact bigint, p_name text,
  p_email text, p_invoices jsonb, p_cc boolean, p_subject text, p_body text, p_again boolean default false)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me     public.team_members;
  t      public.invoice_email_template;
  rcp    jsonb;
  inv    jsonb;
  hours  numeric;
  r      public.invoice_emails;
  v_n    int;
  v_to   text;
  v_cc   text;
  v_who  text;
  v_co   text;
  v_tot  text;
  v_nos  text;
  v_list text[];
  v_vals jsonb;
  v_s    text;
  v_b    text;
  v_id   uuid;
begin
  select * into me from public.team_members x where x.id = p_actor and x.active;
  if me.id is null then return jsonb_build_object('error', 'denied'); end if;
  if p_contact is null or p_contact <= 0 then return jsonb_build_object('error', 'bad-request'); end if;
  if jsonb_typeof(p_invoices) <> 'array' or jsonb_array_length(p_invoices) < 1 or jsonb_array_length(p_invoices) > 50 then
    return jsonb_build_object('error', 'bad-invoices');
  end if;
  for inv in select value from jsonb_array_elements(p_invoices) loop
    if coalesce(inv->>'number', '') !~ '^[A-Za-z0-9/._ -]{1,40}$' or coalesce(inv->>'currency', '') !~ '^[A-Z]{3}$'
       or (inv->>'amount') is null or (inv->>'amount')::numeric <= 0
       or (coalesce(inv->>'link', '') <> '' and inv->>'link' !~ '^https://[a-z0-9-]+\.bukku\.my/[A-Za-z0-9/_-]+$') then
      return jsonb_build_object('error', 'bad-invoices');
    end if;
  end loop;
  perform pg_advisory_xact_lock(hashtextextended('invoice-mail:' || p_contact::text, 0));
  select * into r from public.invoice_emails x
   where x.bukku_contact = p_contact and x.status = 'sending' and x.created_at > now() - interval '10 minutes'
   order by x.created_at desc limit 1;
  if r.id is not null then return jsonb_build_object('error', 'sending'); end if;
  hours := coalesce(public.app_setting('wa_repeat_hours', (now() at time zone 'Asia/Kuala_Lumpur')::date), 24);
  if hours > 0 and not coalesce(p_again, false) then
    select * into r from public.invoice_emails x
     where x.bukku_contact = p_contact and x.status <> 'failed' and x.created_at > now() - make_interval(secs => hours * 3600)
     order by x.created_at desc limit 1;
    if r.id is not null then
      return jsonb_build_object('error', 'recent', 'recent', jsonb_build_object('at', r.created_at, 'to', r.to_email,
        'by', (select m.name from public.team_members m where m.id = r.sent_by)));
    end if;
  end if;
  rcp := case when p_client is null then null else public.invoice_recipient(p_client) end;
  v_to := coalesce(rcp->>'email', nullif(btrim(coalesce(p_email, '')), ''));
  if v_to is null or v_to !~ '^[^@\s,;<>]+@[^@\s,;<>]+\.[^@\s,;<>]+$' then return jsonb_build_object('error', 'no-email'); end if;
  v_cc := case when coalesce(p_cc, false) and lower(coalesce(rcp->>'cc', '')) <> lower(v_to) then rcp->>'cc' end;
  v_co := coalesce(rcp->>'company', nullif(btrim(coalesce(p_name, '')), ''), 'Client');
  v_who := coalesce(rcp->>'name', 'Sir or Madam');
  v_n := jsonb_array_length(p_invoices);
  select string_agg(public.invoice_money(s.amt, s.cur), ' and ' order by s.cur) into v_tot
    from (select x->>'currency' as cur, sum((x->>'amount')::numeric) as amt
            from jsonb_array_elements(p_invoices) x group by x->>'currency') s;
  select array_agg(x->>'number' order by o) into v_list from jsonb_array_elements(p_invoices) with ordinality as a (x, o);
  v_nos := case when v_n = 1 then v_list[1]
                else array_to_string(v_list[1:v_n - 1], ', ') || ' and ' || v_list[v_n] end;
  v_vals := jsonb_build_object('contact name', v_who, 'client', v_co, 'invoice no', v_nos, 'count', v_n::text,
    'total', v_tot, 'sign off', case when rcp->>'name' is not null then 'Yours sincerely' else 'Yours faithfully' end);
  select * into t from public.invoice_email_template x where x.id = 1;
  v_s := btrim(regexp_replace(public.supplier_email_fill(coalesce(nullif(btrim(coalesce(p_subject, '')), ''),
           case when v_n = 1 then t.subject_one else t.subject_many end), v_vals), '\s+', ' ', 'g'));
  v_b := btrim(replace(public.supplier_email_fill(coalesce(nullif(btrim(coalesce(p_body, '')), ''), t.body), v_vals), E'\r', ''));
  if length(v_s) < 2 or length(v_s) > 200 then return jsonb_build_object('error', 'bad-subject'); end if;
  if length(v_b) < 2 or length(v_b) > 5000 then return jsonb_build_object('error', 'bad-body'); end if;
  if v_b !~* '\{\s*invoices\s*\}' then return jsonb_build_object('error', 'no-invoices'); end if;
  insert into public.invoice_emails (client_id, bukku_contact, client_name, invoices, to_email, cc_email, subject, body, sent_by)
  values (p_client, p_contact, v_co, p_invoices, v_to, v_cc, v_s, v_b, me.id)
  returning id into v_id;
  return jsonb_build_object('ok', true, 'id', v_id, 'to', v_to, 'cc', v_cc, 'subject', v_s, 'body', v_b,
    'legal', t.legal, 'disclaimer', t.disclaimer);
end $$;
revoke all on function public.invoice_email_begin(uuid, uuid, bigint, text, text, jsonb, boolean, text, text, boolean) from public, anon, authenticated;
grant execute on function public.invoice_email_begin(uuid, uuid, bigint, text, text, jsonb, boolean, text, text, boolean) to service_role;

-- END OF OVERDUE REMINDER WORDING --------------------------------------------

-- ===========================================================================
-- MEETING MESSAGE — the content meeting's message to the client, as the
-- team words it (2026-10-29)
-- ===========================================================================
-- WHY (the user, 2026-10-29: "approve all, build item 5 too"): the message
-- a month's card copies for the client (date, time, agenda, channel, link)
-- was typed into js/ops.js; changing a word needed a release.
--
-- WHAT IT ADDS
--   * `meeting_message_template`: one row, the message with its words in
--     braces ({meeting}, {date}, {time}, {month}, {channel}, {link}); seeded
--     once with the wording the page used, edited at Settings, Templates,
--     Meeting message (`team.settings`).
--   * `meeting_message_get()`: any colleague (the month's card fills it).
--   * `meeting_message_save(p_body)`: `team.settings` at Work; 2 to 3,000
--     characters holding {date} (`no-date`); filed `team.changed` under
--     Meeting message; an unchanged save files nothing.
--
-- ORDER: this file (connector), then the pages. A page served before keeps
-- its own words; a page served after on a database without this file falls
-- back to the same words. Safe to run twice.
--
-- ROLLBACK
--   drop function if exists public.meeting_message_save(text);
--   drop function if exists public.meeting_message_get();
--   drop table if exists public.meeting_message_template;
-- ===========================================================================

create table if not exists public.meeting_message_template (
  id          int primary key default 1 check (id = 1),
  body        text not null,
  updated_at  timestamptz not null default now(),
  updated_by  uuid references public.team_members(id) on delete set null
);
alter table public.meeting_message_template enable row level security;
revoke all on table public.meeting_message_template from public, anon, authenticated;

insert into public.meeting_message_template (id, body)
select 1, E'Meeting Schedule {meeting}\n\nDate 日期: {date}\nTime 时间: {time}\n\nMeeting Agenda 摘要:\n•  {month} Content Discussion\n\nChannel 渠道:\n{channel}\nLink: {link}'
where not exists (select 1 from public.meeting_message_template);

create or replace function public.meeting_message_get()
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  t public.meeting_message_template;
begin
  if (public.ops_me()).id is null then return jsonb_build_object('error', 'denied'); end if;
  select * into t from public.meeting_message_template x where x.id = 1;
  return jsonb_build_object('ok', true, 'body', t.body, 'updated_at', t.updated_at,
    'updated_by', (select m.name from public.team_members m where m.id = t.updated_by));
end $$;
revoke all on function public.meeting_message_get() from public, anon;
grant execute on function public.meeting_message_get() to authenticated;

create or replace function public.meeting_message_save(p_body text)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me  public.team_members := public.ops_me();
  t   public.meeting_message_template;
  v_b text := btrim(replace(coalesce(p_body, ''), E'\r', ''));
begin
  if me.id is null or not public.ops_granted('team.settings', 'work') then return jsonb_build_object('error', 'denied'); end if;
  if length(v_b) < 2 or length(v_b) > 3000 then return jsonb_build_object('error', 'bad-body'); end if;
  if v_b !~* '\{\s*date\s*\}' then return jsonb_build_object('error', 'no-date'); end if;
  select * into t from public.meeting_message_template x where x.id = 1 for update;
  if t.body is not distinct from v_b then return jsonb_build_object('ok', true); end if;
  update public.meeting_message_template x set body = v_b, updated_at = now(), updated_by = me.id where x.id = 1;
  insert into public.activity_log (actor, action, subject, detail)
  values (me.name, 'team.changed', 'Meeting message', 'Message');
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.meeting_message_save(text) from public, anon;
grant execute on function public.meeting_message_save(text) to authenticated;

-- END OF MEETING MESSAGE ------------------------------------------------------


-- ===========================================================================
-- SALUTATION SAID ONCE — a name after its salutation never carries a second
-- one (2026-10-29)
-- ===========================================================================
-- WHY (the user, 2026-10-29: "salutation is Mrs but why would it show Mrs
-- Ms xxx", then "check for other salutation as well"): Send to Bukku put
-- the contact's salutation before the name Bukku held, Ms Agnes Ang, and
-- read Mrs Ms Agnes Ang. Every place a name follows its salutation is held
-- to one rule.
--
-- WHAT CHANGED
--   * `contact_named(p_salutation, p_name)` (internal): the salutation,
--     then the name with any salutation it opens on taken off (Mrs and
--     Ms Agnes Ang read Mrs Agnes Ang; two-word titles whole, never Tan);
--     no salutation, the name as it stands. `ADspaceWords.person` reads it
--     alike on the pages.
--   * `contact_greeting` greets through it where a salutation is set (it
--     said a same salutation once, never a different one).
--   * `invoice_recipient` names the reminder's contact through it.
--
-- ORDER: this file (connector), then the pages. Either order is safe: each
-- side only stops repeating a salutation. Safe to run twice.
--
-- ROLLBACK
--   Run DATA HELD TO ITS LEVEL's contact_greeting and OVERDUE INVOICE
--   REMINDERS' invoice_recipient again, then
--   drop function if exists public.contact_named(text, text);
-- ===========================================================================

-- SALUTATION SAID ONCE ------------------------------------------------------

create or replace function public.contact_named(p_salutation text, p_name text)
returns text
language sql immutable set search_path = public as $$
  select case when x.s = '' then x.n
              else btrim(x.s || ' ' || regexp_replace(x.n,
                '^(dato''? sri|datin sri|datuk sri|tan sri|puan sri|mrs|mr|ms|miss|mdm|madam|dr|prof|dato''?|datin|datuk|tun|tuan|puan|encik|cik)\.?\s+',
                '', 'i')) end
    from (select btrim(coalesce(p_salutation, '')) as s,
                 btrim(regexp_replace(coalesce(p_name, ''), '\s+', ' ', 'g')) as n) x
$$;
revoke all on function public.contact_named(text, text) from public, anon, authenticated;

create or replace function public.contact_greeting(p_salutation text, p_name text)
returns text
language sql immutable set search_path = public as $$
  -- A salutation is said once, however the name was keyed, and the two-word
  -- titles are whole (audit I12): never "Ms Ms Jane Doe", never "Mrs Ms
  -- Jane Doe", never "Tan".
  select case when x.s <> ''
              then public.contact_named(x.s, x.n)
              when lower(x.n) ~ '^(tan sri|puan sri|dato''? sri|datin sri|datuk sri) '
              then x.n
              when lower(split_part(x.n, ' ', 1)) ~ '^(mr|ms|mrs|mdm|dr|prof|dato''?|datin|datuk|puan|tun|tuan|encik|cik|madam|miss)\.?$'
               and position(' ' in x.n) > 0
              then x.n
              else split_part(x.n, ' ', 1) end
    from (select btrim(coalesce(p_salutation, '')) as s,
                 btrim(regexp_replace(coalesce(p_name, ''), '\s+', ' ', 'g')) as n) x
$$;
revoke all on function public.contact_greeting(text, text) from public, anon, authenticated;

/* Who a client's reminder goes to: the billing contact, else the live main
   contact, with their salutation said once; the finance email to copy where
   it differs; the registered name, else the brand. Internal. */
create or replace function public.invoice_recipient(p_client uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  c public.clients;
  k public.client_contacts;
begin
  select * into c from public.clients x where x.id = p_client;
  if c.id is null then return null; end if;
  select * into k from public.client_contacts x
   where x.client_id = c.id and x.archived_at is null and (x.id = c.bill_contact_id or x.is_primary)
   order by (x.id = c.bill_contact_id) desc limit 1;
  return jsonb_build_object(
    'name', nullif(public.contact_named(k.salutation, k.name), ''),
    'email', nullif(btrim(coalesce(k.email, '')), ''),
    'cc', case when nullif(btrim(coalesce(c.finance_email, '')), '') is not null
                and lower(btrim(c.finance_email)) is distinct from lower(btrim(coalesce(k.email, '')))
               then btrim(c.finance_email) end,
    'company', coalesce(nullif(btrim(coalesce(c.legal_name, '')), ''), c.name));
end $$;
revoke all on function public.invoice_recipient(uuid) from public, anon, authenticated;

-- END OF SALUTATION SAID ONCE -----------------------------------------------


-- ===========================================================================
-- BUKKU UNLINK — a record linked to the wrong Bukku contact is let go
-- (2026-10-29)
-- ===========================================================================
-- WHY (the user, 2026-10-29: "linking of the client in Bukku is a dead end
-- is it it doesnt allow to unlink"): once linked, Send to Bukku offered the
-- linked contact alone, and nothing took the link away.
--
-- WHAT IT ADDS
--   * `bukku_links_gone`: the links let go, kept for their way back (RLS
--     on, no policy, no grant).
--   * `bukku_unlink(p_kind, p_id)`: Clients: Billing (a client) or Suppliers
--     (a supplier) at Work, as Send to Bukku asks. It lets go of the
--     record's link and, since a supplier that is also a client is one
--     Bukku contact, of its pair's link to the same contact (each pair
--     record at its own Work; `denied` naming none). Nothing is sent to or
--     changed in Bukku. `not-linked` where there is none. Filed
--     `client.edited` / `supplier.edited` Unlinked from Bukku · code.
--     Answers `stamp` for the way back.
--   * `bukku_unlink_undo(p_kind, p_id, p_stamp)`: the same level puts back
--     what that unlink let go, as it stood (Last sent and its changes kept);
--     `moved` where the record has been linked since, `taken` where another
--     record holds that contact now. Filed Linked to Bukku again · code.
--
-- ORDER: this file (SQL Editor: it holds `delete`), then the pages. A page
-- served before draws no Unlink; a page served after on a database without
-- this file says This needs a database update. Safe to run twice.
--
-- ROLLBACK
--   drop function if exists public.bukku_unlink_undo(text, uuid, timestamptz);
--   drop function if exists public.bukku_unlink(text, uuid);
--   drop table if exists public.bukku_links_gone;
-- ===========================================================================

-- BUKKU UNLINK --------------------------------------------------------------

create table if not exists public.bukku_links_gone (
  kind       text not null,
  record_id  uuid not null,
  contact_id bigint not null,
  code       text,
  sent_at    timestamptz,
  sent_by    uuid,
  sent_hash  text,
  gone_at    timestamptz not null default now(),
  gone_by    uuid references public.team_members(id) on delete set null
);
alter table public.bukku_links_gone enable row level security;
revoke all on table public.bukku_links_gone from public, anon, authenticated;
create index if not exists bukku_links_gone_record_idx on public.bukku_links_gone (kind, record_id, gone_at);

/* The links one contact holds for a record and its pair: a client and every
   supplier that is that client, alike. Internal. */
create or replace function public.bukku_pair_links(p_kind text, p_id uuid)
returns setof public.bukku_links
language sql stable security definer set search_path = public as $$
  with me as (
    select case when p_kind = 'client' then p_id
                else (select s.client_id from public.suppliers s where s.id = p_id) end as cid,
           coalesce((select l.contact_id from public.bukku_links l where l.kind = p_kind and l.record_id = p_id),
                    case when p_kind = 'supplier' then
                      (select l.contact_id from public.bukku_links l
                        where l.kind = 'client' and l.record_id = (select s.client_id from public.suppliers s where s.id = p_id)) end) as contact
  )
  select l.* from public.bukku_links l, me
   where me.contact is not null and l.contact_id = me.contact
     and ((l.kind = p_kind and l.record_id = p_id)
       or (me.cid is not null and l.kind = 'client' and l.record_id = me.cid)
       or (me.cid is not null and l.kind = 'supplier'
           and l.record_id in (select s.id from public.suppliers s where s.client_id = me.cid)))
$$;
revoke all on function public.bukku_pair_links(text, uuid) from public, anon, authenticated;

/* A record's name and its ID, as the activity record files it. Internal. */
create or replace function public.bukku_record_name(p_kind text, p_id uuid)
returns text
language sql stable security definer set search_path = public as $$
  select case when p_kind = 'client'
              then (select x.name from public.clients x where x.id = p_id)
              else (select coalesce(x.name, x.code) from public.suppliers x where x.id = p_id) end
$$;
revoke all on function public.bukku_record_name(text, uuid) from public, anon, authenticated;

create or replace function public.bukku_unlink(p_kind text, p_id uuid)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  r public.bukku_links;
  v_at timestamptz := clock_timestamp();
  v_n int := 0;
begin
  if p_kind not in ('client', 'supplier') or not public.bukku_may(p_kind, p_id, 'work') then
    return jsonb_build_object('error', 'denied');
  end if;
  if public.bukku_record_name(p_kind, p_id) is null then return jsonb_build_object('error', 'not-found'); end if;
  for r in select * from public.bukku_pair_links(p_kind, p_id) loop
    if not public.bukku_may(r.kind, r.record_id, 'work') then return jsonb_build_object('error', 'denied'); end if;
  end loop;
  for r in select * from public.bukku_pair_links(p_kind, p_id) loop
    insert into public.bukku_links_gone (kind, record_id, contact_id, code, sent_at, sent_by, sent_hash, gone_at, gone_by)
    values (r.kind, r.record_id, r.contact_id, r.code, r.sent_at, r.sent_by, r.sent_hash, v_at, me.id);
    delete from public.bukku_links x where x.kind = r.kind and x.record_id = r.record_id;
    insert into public.activity_log (actor, action, subject, detail)
    values (me.name, case when r.kind = 'client' then 'client.edited' else 'supplier.edited' end,
            public.bukku_record_name(r.kind, r.record_id),
            'Unlinked from Bukku · ' || coalesce(r.code, r.contact_id::text));
    v_n := v_n + 1;
  end loop;
  if v_n = 0 then return jsonb_build_object('error', 'not-linked'); end if;
  return jsonb_build_object('ok', true, 'stamp', v_at, 'records', v_n);
end $$;
revoke all on function public.bukku_unlink(text, uuid) from public, anon;
grant execute on function public.bukku_unlink(text, uuid) to authenticated;

create or replace function public.bukku_unlink_undo(p_kind text, p_id uuid, p_stamp timestamptz)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me public.team_members := public.ops_me();
  g public.bukku_links_gone;
  v_n int := 0;
begin
  if p_kind not in ('client', 'supplier') or not public.bukku_may(p_kind, p_id, 'work') then
    return jsonb_build_object('error', 'denied');
  end if;
  if not exists (select 1 from public.bukku_links_gone x
                  where x.gone_at = p_stamp and x.kind = p_kind and x.record_id = p_id) then
    return jsonb_build_object('error', 'not-found');
  end if;
  for g in select * from public.bukku_links_gone x where x.gone_at = p_stamp loop
    if not public.bukku_may(g.kind, g.record_id, 'work') then return jsonb_build_object('error', 'denied'); end if;
    if exists (select 1 from public.bukku_links l where l.kind = g.kind and l.record_id = g.record_id) then
      return jsonb_build_object('error', 'moved');
    end if;
    if public.bukku_contact_taken(g.kind, g.record_id, g.contact_id) then return jsonb_build_object('error', 'taken'); end if;
  end loop;
  for g in select * from public.bukku_links_gone x where x.gone_at = p_stamp loop
    insert into public.bukku_links (kind, record_id, contact_id, code, sent_at, sent_by, sent_hash)
    values (g.kind, g.record_id, g.contact_id, g.code, coalesce(g.sent_at, now()), g.sent_by, g.sent_hash);
    insert into public.activity_log (actor, action, subject, detail)
    values (me.name, case when g.kind = 'client' then 'client.edited' else 'supplier.edited' end,
            public.bukku_record_name(g.kind, g.record_id),
            'Linked to Bukku again · ' || coalesce(g.code, g.contact_id::text));
    v_n := v_n + 1;
  end loop;
  delete from public.bukku_links_gone x where x.gone_at = p_stamp;
  return jsonb_build_object('ok', true, 'records', v_n);
end $$;
revoke all on function public.bukku_unlink_undo(text, uuid, timestamptz) from public, anon;
grant execute on function public.bukku_unlink_undo(text, uuid, timestamptz) to authenticated;

-- END OF BUKKU UNLINK -------------------------------------------------------


-- ===========================================================================
-- REVIEW FIXES OF 2026-10-29 — an IPv6 caller counted by its block, any
-- invoice number reminded, the demo's counts reset with its PIN, a website
-- quotation past the WhatsApp cap said to the team (2026-10-29)
-- ===========================================================================
-- WHY (the review of the releases after #796, 2026-10-29, the user: "ok fix
-- all"):
--    7. `request_ip()` answered an IPv6 caller's whole address, so a guesser
--       changing its address inside its own /64 (every IPv6 host holds one)
--       never met a lock, and filled `link_tries` with a row a guess.
--   11. `invoice_email_begin` took an invoice number of letters, digits and
--       / . _ - alone, so a Bukku number such as INV#2026-001 refused every
--       reminder to its client (the email escapes it anyway).
--   14. A demo PIN locked by wrong tries stayed locked when a new PIN was
--       set: only waiting freed it.
--   17. A website quotation past the day's WhatsApp cap told the team as
--       any other, so nobody knew the prospect had no message.
--
-- WHAT IT CHANGES
--   * `request_ip()` (internal): an IPv6 address reads as its /64; every
--     count keyed on it (a link's passcode, /verify/, the demo PIN, a
--     creator's code) takes it. Rows kept under a whole IPv6 address age
--     out as before.
--   * `invoice_email_begin` (restated whole from OVERDUE REMINDER WORDING):
--     an invoice number is 1 to 60 characters with no control character.
--   * `demo_set` (restated whole from DEMO ACCESS): a new PIN clears the
--     demo's wrong tries and locks.
--   * `quote_website_create` (restated whole from WEBSITE WHATSAPP CAP):
--     the cap is read before the team's notice, which ends Not sent on
--     WhatsApp (daily limit) past it; the message follows the same answer.
--
-- ORDER: this file (connector), then the pages. Either order is safe: no
-- answer changes its shape. Safe to run twice.
--
-- ROLLBACK: request_ip, invoice_email_begin, demo_set and
-- quote_website_create from their last definitions before this banner.
-- ===========================================================================

create or replace function public.request_ip()
returns text
language plpgsql stable security definer set search_path = public as $$
declare
  h json := coalesce(nullif(current_setting('request.headers', true), ''), '{}')::json;
  v text;
begin
  v := left(coalesce(
    case when nullif(h ->> 'x-adspace-relay', '') is not null
          and h ->> 'x-adspace-relay' = (select s.value from public.app_secrets s where s.key = 'ip_relay_secret')
         then nullif(btrim(h ->> 'x-adspace-ip'), '') end,
    nullif(btrim(h ->> 'cf-connecting-ip'), ''),
    nullif(btrim(reverse(split_part(reverse(coalesce(h ->> 'x-forwarded-for', '')), ',', 1))), ''),
    ''), 64);
  -- An IPv6 caller is counted by its /64, the block one machine or network
  -- holds: a guesser changing its address inside it is one caller (review
  -- 2026-10-29, 7). An IPv4 address, one written as IPv6 (::ffff:), and a
  -- value that is no address stay as they are.
  if position(':' in v) > 0 and v !~* '^::ffff:' then
    begin
      v := host(network(set_masklen(v::inet, 64))) || '/64';
    exception when others then null;
    end;
  end if;
  return v;
end $$;
revoke all on function public.request_ip() from public, anon, authenticated;

create or replace function public.invoice_email_begin(p_actor uuid, p_client uuid, p_contact bigint, p_name text,
  p_email text, p_invoices jsonb, p_cc boolean, p_subject text, p_body text, p_again boolean default false)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  me     public.team_members;
  t      public.invoice_email_template;
  rcp    jsonb;
  inv    jsonb;
  hours  numeric;
  r      public.invoice_emails;
  v_n    int;
  v_to   text;
  v_cc   text;
  v_who  text;
  v_co   text;
  v_tot  text;
  v_nos  text;
  v_list text[];
  v_vals jsonb;
  v_s    text;
  v_b    text;
  v_id   uuid;
begin
  select * into me from public.team_members x where x.id = p_actor and x.active;
  if me.id is null then return jsonb_build_object('error', 'denied'); end if;
  if p_contact is null or p_contact <= 0 then return jsonb_build_object('error', 'bad-request'); end if;
  if jsonb_typeof(p_invoices) <> 'array' or jsonb_array_length(p_invoices) < 1 or jsonb_array_length(p_invoices) > 50 then
    return jsonb_build_object('error', 'bad-invoices');
  end if;
  for inv in select value from jsonb_array_elements(p_invoices) loop
    if btrim(coalesce(inv->>'number', '')) = '' or coalesce(inv->>'number', '') !~ '^[^[:cntrl:]]{1,60}$' or coalesce(inv->>'currency', '') !~ '^[A-Z]{3}$'
       or (inv->>'amount') is null or (inv->>'amount')::numeric <= 0
       or (coalesce(inv->>'link', '') <> '' and inv->>'link' !~ '^https://[a-z0-9-]+\.bukku\.my/[A-Za-z0-9/_-]+$') then
      return jsonb_build_object('error', 'bad-invoices');
    end if;
  end loop;
  perform pg_advisory_xact_lock(hashtextextended('invoice-mail:' || p_contact::text, 0));
  select * into r from public.invoice_emails x
   where x.bukku_contact = p_contact and x.status = 'sending' and x.created_at > now() - interval '10 minutes'
   order by x.created_at desc limit 1;
  if r.id is not null then return jsonb_build_object('error', 'sending'); end if;
  hours := coalesce(public.app_setting('wa_repeat_hours', (now() at time zone 'Asia/Kuala_Lumpur')::date), 24);
  if hours > 0 and not coalesce(p_again, false) then
    select * into r from public.invoice_emails x
     where x.bukku_contact = p_contact and x.status <> 'failed' and x.created_at > now() - make_interval(secs => hours * 3600)
     order by x.created_at desc limit 1;
    if r.id is not null then
      return jsonb_build_object('error', 'recent', 'recent', jsonb_build_object('at', r.created_at, 'to', r.to_email,
        'by', (select m.name from public.team_members m where m.id = r.sent_by)));
    end if;
  end if;
  rcp := case when p_client is null then null else public.invoice_recipient(p_client) end;
  v_to := coalesce(rcp->>'email', nullif(btrim(coalesce(p_email, '')), ''));
  if v_to is null or v_to !~ '^[^@\s,;<>]+@[^@\s,;<>]+\.[^@\s,;<>]+$' then return jsonb_build_object('error', 'no-email'); end if;
  v_cc := case when coalesce(p_cc, false) and lower(coalesce(rcp->>'cc', '')) <> lower(v_to) then rcp->>'cc' end;
  v_co := coalesce(rcp->>'company', nullif(btrim(coalesce(p_name, '')), ''), 'Client');
  v_who := coalesce(rcp->>'name', 'Sir or Madam');
  v_n := jsonb_array_length(p_invoices);
  select string_agg(public.invoice_money(s.amt, s.cur), ' and ' order by s.cur) into v_tot
    from (select x->>'currency' as cur, sum((x->>'amount')::numeric) as amt
            from jsonb_array_elements(p_invoices) x group by x->>'currency') s;
  select array_agg(x->>'number' order by o) into v_list from jsonb_array_elements(p_invoices) with ordinality as a (x, o);
  v_nos := case when v_n = 1 then v_list[1]
                else array_to_string(v_list[1:v_n - 1], ', ') || ' and ' || v_list[v_n] end;
  v_vals := jsonb_build_object('contact name', v_who, 'client', v_co, 'invoice no', v_nos, 'count', v_n::text,
    'total', v_tot, 'sign off', case when rcp->>'name' is not null then 'Yours sincerely' else 'Yours faithfully' end);
  select * into t from public.invoice_email_template x where x.id = 1;
  v_s := btrim(regexp_replace(public.supplier_email_fill(coalesce(nullif(btrim(coalesce(p_subject, '')), ''),
           case when v_n = 1 then t.subject_one else t.subject_many end), v_vals), '\s+', ' ', 'g'));
  v_b := btrim(replace(public.supplier_email_fill(coalesce(nullif(btrim(coalesce(p_body, '')), ''), t.body), v_vals), E'\r', ''));
  if length(v_s) < 2 or length(v_s) > 200 then return jsonb_build_object('error', 'bad-subject'); end if;
  if length(v_b) < 2 or length(v_b) > 5000 then return jsonb_build_object('error', 'bad-body'); end if;
  if v_b !~* '\{\s*invoices\s*\}' then return jsonb_build_object('error', 'no-invoices'); end if;
  insert into public.invoice_emails (client_id, bukku_contact, client_name, invoices, to_email, cc_email, subject, body, sent_by)
  values (p_client, p_contact, v_co, p_invoices, v_to, v_cc, v_s, v_b, me.id)
  returning id into v_id;
  return jsonb_build_object('ok', true, 'id', v_id, 'to', v_to, 'cc', v_cc, 'subject', v_s, 'body', v_b,
    'legal', t.legal, 'disclaimer', t.disclaimer);
end $$;
revoke all on function public.invoice_email_begin(uuid, uuid, bigint, text, text, jsonb, boolean, text, text, boolean) from public, anon, authenticated;
grant execute on function public.invoice_email_begin(uuid, uuid, bigint, text, text, jsonb, boolean, text, text, boolean) to service_role;

create or replace function public.demo_set(p_on boolean, p_pin text default null)
returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  v_me public.team_members;
  v_was boolean;
  v_pin text := btrim(coalesce(p_pin, ''));
  v_held boolean;
  v_bits text[] := '{}';
begin
  if not public.ops_granted('team.settings', 'work') then return jsonb_build_object('error', 'denied'); end if;
  v_me := public.ops_me();
  if v_pin <> '' and v_pin !~ '^[0-9]{4,8}$' then return jsonb_build_object('error', 'bad-pin'); end if;
  v_held := exists (select 1 from public.app_secrets s where s.key = 'demo_pin' and coalesce(s.value, '') <> '');
  if coalesce(p_on, false) and v_pin = '' and not v_held then return jsonb_build_object('error', 'no-pin'); end if;
  v_was := coalesce((select f.on_now from public.app_flags f where f.key = 'demo'), false);
  if v_pin <> '' then
    insert into public.app_secrets (key, value) values ('demo_pin', crypt(v_pin, gen_salt('bf', 8)))
    on conflict (key) do update set value = excluded.value, updated_at = now();
    v_bits := v_bits || 'PIN changed'::text;
    -- A new PIN starts every count afresh: the wrong tries a guesser or a
    -- mistyping colleague left no longer lock it (review 2026-10-29, 14).
    update public.link_tries set fails = 0, locked_until = null, strikes = 0, struck_until = null
     where kind = 'demo' and (fails > 0 or locked_until is not null or strikes > 0);
    update public.link_attempts set fails = 0, locked_until = null
     where kind = 'demo' and (fails > 0 or locked_until is not null);
  end if;
  if v_was is distinct from coalesce(p_on, false) then
    v_bits := array['Demo access: ' || case when v_was then 'On' else 'Off' end || ' → ' || case when p_on then 'On' else 'Off' end] || v_bits;
  end if;
  insert into public.app_flags as f (key, on_now, set_by, set_at)
  values ('demo', coalesce(p_on, false), coalesce(v_me.name, v_me.email), now())
  on conflict (key) do update set on_now = excluded.on_now,
    set_by = case when f.on_now is distinct from excluded.on_now or v_pin <> '' then excluded.set_by else f.set_by end,
    set_at = case when f.on_now is distinct from excluded.on_now or v_pin <> '' then excluded.set_at else f.set_at end;
  if array_length(v_bits, 1) > 0 then
    insert into public.activity_log (actor, action, subject, detail)
    values (coalesce(v_me.name, v_me.email, 'admin'), 'team.changed', 'Demo access', array_to_string(v_bits, ' · '));
  end if;
  return public.demo_state();
end $$;
revoke all on function public.demo_set(boolean, text) from public, anon;
grant execute on function public.demo_set(boolean, text) to authenticated;

create or replace function public.quote_website_create(p_sel jsonb, p_contact jsonb, p_idem text)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  v_name  text := btrim(regexp_replace(coalesce(p_contact->>'name', ''), '\s+', ' ', 'g'));
  v_email text := lower(btrim(coalesce(p_contact->>'email', '')));
  v_wa    text := public.quote_website_number(p_contact->>'whatsapp');
  v_brand text := btrim(regexp_replace(coalesce(p_contact->>'brand', ''), '\s+', ' ', 'g'));
  v_ind   text := nullif(btrim(coalesce(p_contact->>'industry', '')), '');
  v_lang  text := case when p_contact->>'lang' = 'zh' then 'zh' else 'en' end;
  v_sal   text := nullif(btrim(coalesce(p_contact->>'salutation', '')), '');
  v_idem  text := nullif(btrim(coalesce(p_idem, '')), '');
  v_sel   jsonb;
  v_q     public.quotations;
  v_c     public.clients;
  v_base  text;
  v_slug  text;
  v_n     int := 1;
  v_r     jsonb;
  v_new   boolean := false;
  v_wa_ok boolean := false;
begin
  if v_idem is null or length(v_idem) > 80 then return jsonb_build_object('error', 'bad-request'); end if;
  select * into v_q from public.quotations q
   where q.idem = v_idem and q.source = 'website' and lower(q.contact->>'email') = v_email;
  if v_q.id is not null then
    return jsonb_build_object('ok', true, 'ref', v_q.ref, 'key', v_q.access_key, 'again', true);
  end if;
  if length(v_name) < 2 or length(v_name) > 80 then return jsonb_build_object('error', 'bad-name'); end if;
  if v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' or length(v_email) > 160 then return jsonb_build_object('error', 'bad-email'); end if;
  if v_wa !~ '^(60(1[0-9]{8,9}|7[0-9]{7,8})|65[0-9]{8})$' then return jsonb_build_object('error', 'bad-whatsapp'); end if;
  if length(v_brand) < 2 or length(v_brand) > 120 then return jsonb_build_object('error', 'bad-brand'); end if;
  -- A name or brand is never a web address: both go into the WhatsApp the
  -- prospect is sent from ADspace's number (2026-10-26, audit).
  if v_name ~* public.quote_link_like() then return jsonb_build_object('error', 'bad-name'); end if;
  if v_brand ~* public.quote_link_like() then return jsonb_build_object('error', 'bad-brand'); end if;
  if v_ind is not null and v_ind not in ('Property', 'F&B', 'Retail', 'Wellness', 'Lifestyle',
                                         'Automotive', 'Tech', 'Education', 'Other') then
    return jsonb_build_object('error', 'bad-industry');
  end if;
  if v_sal is not null and v_sal not in ('Mr', 'Ms', 'Mrs', 'Mdm', 'Dr', 'Prof', 'Dato''', 'Datin', 'Datuk',
      'Dato'' Sri', 'Datin Sri', 'Tan Sri', 'Puan Sri', 'Tun', 'Tuan', 'Puan', 'Encik', 'Cik') then
    return jsonb_build_object('error', 'bad-salutation');
  end if;
  if coalesce((p_contact->>'consent')::boolean, false) is not true then return jsonb_build_object('error', 'consent'); end if;
  if jsonb_typeof(p_sel) is distinct from 'object' then return jsonb_build_object('error', 'bad-selection'); end if;
  if jsonb_typeof(p_sel->'once') = 'array' and jsonb_array_length(p_sel->'once') > 20
     or jsonb_typeof(p_sel->'extra') = 'object' and (select count(*) from jsonb_object_keys(p_sel->'extra')) > 10 then
    return jsonb_build_object('error', 'bad-selection');
  end if;

  -- What the price reads, and nothing else.
  v_sel := jsonb_strip_nulls(jsonb_build_object(
    'mix', case when jsonb_typeof(p_sel->'mix') = 'string' and length(p_sel->>'mix') <= 20 then p_sel->'mix' end,
    'plan', case when jsonb_typeof(p_sel->'plan') = 'string' and length(p_sel->>'plan') <= 80 then p_sel->'plan' end,
    'term', case when jsonb_typeof(p_sel->'term') in ('number', 'string') and length(p_sel->>'term') <= 4 then p_sel->'term' end,
    'budget', case when jsonb_typeof(p_sel->'budget') in ('number', 'string') and length(p_sel->>'budget') <= 12 then p_sel->'budget' end,
    'translate', case when jsonb_typeof(p_sel->'translate') = 'boolean' then p_sel->'translate' end,
    'platforms', (select jsonb_agg(distinct v) from jsonb_array_elements_text(
                    case when jsonb_typeof(p_sel->'platforms') = 'array' then p_sel->'platforms' else '[]'::jsonb end) v
                   where v in ('meta', 'tiktok', 'rednote', 'linkedin')),
    'langs', (select jsonb_agg(distinct l) from jsonb_array_elements_text(
                case when jsonb_typeof(p_sel->'langs') = 'array' then p_sel->'langs' else '[]'::jsonb end) l
               where l in ('en', 'zh', 'ms')),
    'extra', case when jsonb_typeof(p_sel->'extra') = 'object' then
               (select jsonb_object_agg(left(k, 80), p_sel->'extra'->k) from jsonb_object_keys(p_sel->'extra') k) end,
    'once', case when jsonb_typeof(p_sel->'once') = 'array' then
              (select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('slug', left(o->>'slug', 80), 'qty', o->'qty')))
                 from jsonb_array_elements(p_sel->'once') o where jsonb_typeof(o) = 'object') end));

  -- Two posts at once are counted one after the other.
  perform pg_advisory_xact_lock(hashtextextended('quote-web:' || least(v_email, v_wa), 0));
  perform pg_advisory_xact_lock(hashtextextended('quote-web:' || greatest(v_email, v_wa), 0));
  if (select count(*) from public.quotations q
       where q.source = 'website' and q.issued_at > now() - interval '1 day'
         and (lower(q.contact->>'email') = v_email or q.contact->>'whatsapp' = '+' || v_wa)) >= 5 then
    return jsonb_build_object('error', 'limit');
  end if;

  -- A lead this person already is (the same contact holds both the email
  -- and the number), else a new one.
  select c.* into v_c from public.clients c
    join public.client_contacts k on k.client_id = c.id
   where c.stage in ('lead', 'contacted', 'proposal')
     and k.archived_at is null
     and lower(k.email) = v_email
     and public.quote_website_number(k.whatsapp) = v_wa
   order by c.created_at desc limit 1;
  if v_c.id is null then
    v_base := btrim(regexp_replace(lower(v_brand), '[^a-z0-9]+', '-', 'g'), '-');
    if v_base = '' then v_base := 'client'; end if;
    v_slug := v_base;
    while exists (select 1 from public.clients c where lower(c.slug) = v_slug) loop
      v_n := v_n + 1; v_slug := v_base || '-' || v_n;
    end loop;
    insert into public.clients (name, access_token, stage, industry, source, market, slug, deal_note)
    values (v_brand, public.new_link_key(), 'lead', v_ind, 'website',
            case when v_wa like '65%' then 'SG' else 'MY' end, v_slug,
            'Quotation requested on the website.')
    returning * into v_c;
    insert into public.client_contacts (client_id, salutation, name, email, whatsapp, lang, is_primary)
    values (v_c.id, v_sal, v_name, v_email, '+' || v_wa, v_lang, true);
    insert into public.activity_log (actor, action, subject, detail)
    values ('Website', 'client.added', v_c.name, 'Website · ' || coalesce(v_sal || ' ', '') || v_name);
    v_new := true;
  end if;

  v_r := public.quotation_make(v_c.id, v_sel, v_idem, 'website', null,
    jsonb_strip_nulls(jsonb_build_object('salutation', v_sal, 'name', v_name, 'email', v_email,
      'whatsapp', '+' || v_wa, 'lang', v_lang, 'brand', v_brand)));
  if v_r ? 'error' then
    if v_new then raise exception using message = 'quote:' || (v_r->>'error'); end if;
    return v_r;
  end if;
  select * into v_q from public.quotations where id = (v_r->>'id')::uuid;
  -- Whether the prospect is told on WhatsApp is known before the team is,
  -- so a quotation past the day's cap says so in the team's notice (review
  -- 2026-10-29, 17: the 31st of the day read as the 1st).
  begin
    v_wa_ok := public.quote_wa_allowed(v_q.id);
  exception when others then v_wa_ok := false;
  end;
  perform public.quote_tell(v_c.id, 'quote.website', 'Quotation made on the website · ' || v_c.name,
    v_q.ref || ' · ' || coalesce('Monthly incl. SST RM ' ||
      to_char((v_q.totals->'month'->>'incl')::numeric, 'FM999,999,990.00'), 'one-off') || ' · ' || v_name
      || case when v_wa_ok then '' else ' · Not sent on WhatsApp (daily limit)' end,
    v_q.id::text);
  -- The prospect is told on WhatsApp that the quotation is ready, its link
  -- button the quotation's key; a queueing fault never fails the quotation.
  -- No more a day than the Business setting allows (audit 2026-10-29, 3):
  -- past it the quotation is made and the team told, the message not sent.
  begin
    if v_wa_ok then
      perform public.wa_enqueue('quote_ready', v_wa, v_name,
        jsonb_build_array(public.contact_greeting(v_sal, v_name), v_brand, v_q.ref),
        'quotation', v_q.id, v_c.id, v_q.access_key);
    end if;
  exception when others then null;
  end;
  return jsonb_build_object('ok', true, 'ref', v_q.ref, 'key', v_q.access_key);
exception when raise_exception then
  if sqlerrm like 'quote:%' then return jsonb_build_object('error', substr(sqlerrm, 7)); end if;
  raise;
end $$;
revoke all on function public.quote_website_create(jsonb, jsonb, text) from public, anon, authenticated;
grant execute on function public.quote_website_create(jsonb, jsonb, text) to service_role;

-- END OF REVIEW FIXES OF 2026-10-29 ---------------------------------------


select public.functions_tidy();
